def attempt_load(weights, device=None, inplace=True, fuse=True):
    from models.yolo import Detect, Model

    model = Ensemble()
    for w in weights if isinstance(weights, list) else [weights]:
        ckpt = torch_load(attempt_download(w), map_location="cpu")  # load
        ckpt = (ckpt.get("ema") or ckpt["model"]).to(device).float()  # FP32 model

        # Model compatibility updates
        if not hasattr(ckpt, "stride"):
            ckpt.stride = torch.tensor([32.0])
        if hasattr(ckpt, "names") and isinstance(ckpt.names, (list, tuple)):
            ckpt.names = dict(enumerate(ckpt.names))  # convert to dict

        model.append(ckpt.fuse().eval() if fuse and hasattr(ckpt, "fuse") else ckpt.eval())  # model in eval mode

    # Module compatibility updates
    for m in model.modules():
        t = type(m)
        if t in (nn.Hardswish, nn.LeakyReLU, nn.ReLU, nn.ReLU6, nn.SiLU, Detect, Model):
            m.inplace = inplace  # torch 1.7.0 compatibility
            if t is Detect and not isinstance(m.anchor_grid, list):
                delattr(m, "anchor_grid")
                setattr(m, "anchor_grid", [torch.zeros(1)] * m.nl)
        elif t is nn.Upsample and not hasattr(m, "recompute_scale_factor"):
            m.recompute_scale_factor = None  # torch 1.11.0 compatibility

    # Return model
    if len(model) == 1:
        return model[-1]

    # Return detection ensemble
    print(f"Ensemble created with {weights}\n")
    for k in "names", "nc", "yaml":
        setattr(model, k, getattr(model[0], k))
    model.stride = model[torch.argmax(torch.tensor([m.stride.max() for m in model])).int()].stride  # max stride
    assert all(model[0].nc == m.nc for m in model), f"Models have different class counts: {[m.nc for m in model]}"
    return model

def forward(
        self, input, sampler=None
    ):  # pylint: disable=redefined-builtin, arguments-differ
        if sampler is None:
            for module in self:
                input = module(input)
        else:
            for module in self:
                if hasattr(module, "od") and module.od:
                    input = module(input, sampler=sampler)
                elif hasattr(module, "is_od") and module.is_od:
                    input = module(input, p=sampler())
                else:
                    input = module(input)
        return input

def get_final_steps_per_checkpoint(
    steps_per_epoch: int, steps_per_checkpoint: int = 0, checkpoints_per_epoch: float = 0, should_log: bool = False
):
    if steps_per_checkpoint != 0 and checkpoints_per_epoch != 0:
        raise ValueError(
            "It is invalid to specify both checkpoints_per_epoch AND steps_per_checkpoint. Please specify one or the "
            "other, or specify neither to checkpoint/eval the model every epoch."
        )

    # Set steps_per_checkpoint based on the checkpoints_per_epoch, if checkpoints_per_epoch was specified.
    if checkpoints_per_epoch != 0:
        steps_per_checkpoint = int(steps_per_epoch / checkpoints_per_epoch)

    # Cap steps_per_checkpoint at steps_per_epoch.
    if steps_per_checkpoint > steps_per_epoch:
        if should_log:
            logger.info(
                f"Note: steps_per_checkpoint (was {steps_per_checkpoint}) is now set to the number of "
                f"steps per epoch: {steps_per_epoch}.\n"
            )
        return steps_per_epoch

    # steps_per_checkpoint wasn't specified. Use steps_per_epoch.
    if steps_per_checkpoint == 0:
        return steps_per_epoch

    return steps_per_checkpoint

def handle_multi_feature_output(
        self, api_name, multi_feature_outputs, features_to_invoke, **kwargs
    ):
        if "enabled" in api_name:
            # *_enabled feature calls can return bool, or tuple (bool, Optional[int]).
            # If any of them returns bool, then we return bool - this means that we cannot state anything
            # about enablement in the next steps.
            # If all of them return a tuple (bool, Optional[int]), we return the minimum value,
            # representing the number of steps after the feature will be enabled next time.
            # If the second value is None, that means that the feature will never be enabled.
            all_ret_tuple = all(
                isinstance(feature_output, tuple) for feature_output in multi_feature_outputs
            )
            if all_ret_tuple:
                run_current = any(feature_output[0] for feature_output in multi_feature_outputs)
                next_iter = None
                for feature_output in multi_feature_outputs:
                    if next_iter is None:
                        next_iter = feature_output[1]
                    elif feature_output[1] is not None:
                        next_iter = min(next_iter, feature_output[1])
                return run_current, next_iter
            run_current = any(feature_output for feature_output in multi_feature_outputs)
            return run_current, None
        return super().handle_multi_feature_output(
            api_name, multi_feature_outputs, features_to_invoke, **kwargs
        )

def output_counts(self) -> None:
        if not self.enabled:
            return
        counts = []
        for key, count in self._counts.items():
            if not count:
                continue
            txt = key.title()
            if key in ("distance", "roll"):
                txt += f" ({getattr(self, f'_{key}')})"
            if key == "scale":
                txt += f" (min: {self._min_scale}, max: {self._max_scale})"
            counts.append(txt + f": {count}")
        if counts:
            logger.info("[Align filter] %s", ", ".join(counts))

def library_dispatch_passes(target: tvm.target.Target):
    if target.kind.name == "cuda":
        return backend.cuda.library_dispatch_passes(target)
    if target.kind.name == "rocm":
        return backend.rocm.library_dispatch_passes(target)
    if target.kind.name == "metal":
        return backend.gpu_generic.library_dispatch_passes(target)
    if target.kind.name == "llvm":
        return backend.cpu_generic.library_dispatch_passes(target)
    if target.kind.name == "opencl" and "adreno" in target.keys:
        return backend.adreno.library_dispatch_passes(target)
    if BackendDispatcher.is_gpu_target(target):
        return backend.gpu_generic.library_dispatch_passes(target)
    raise ValueError(f"Target {target} is not yet supported by library dispatch passes.")

def pairwise_kernels(
    X, Y=None, metric="linear", *, filter_params=False, n_jobs=None, **kwds
):
    # import GPKernel locally to prevent circular imports
    from sklearn.gaussian_process.kernels import Kernel as GPKernel

    if metric == "precomputed":
        X, _ = check_pairwise_arrays(X, Y, precomputed=True)
        return X
    elif isinstance(metric, GPKernel):
        func = metric.__call__
    elif metric in PAIRWISE_KERNEL_FUNCTIONS:
        if filter_params:
            kwds = {k: kwds[k] for k in kwds if k in KERNEL_PARAMS[metric]}
        func = PAIRWISE_KERNEL_FUNCTIONS[metric]
    elif callable(metric):
        func = partial(_pairwise_callable, metric=metric, **kwds)

    return _parallel_pairwise(X, Y, func, n_jobs, **kwds)

def apply_pass_and_basic_check(
    prog: Program,
    pass_name: Union[str, AbstractGraphPass],
    skip_output_name_check: Optional[bool] = False,
    skip_output_type_check: Optional[bool] = False,
    skip_output_shape_check: Optional[bool] = False,
    skip_input_name_check: Optional[bool] = False,
    skip_input_type_check: Optional[bool] = False,
    skip_function_name_check: Optional[bool] = False,
    func_name: Optional[str] = "main",
    skip_essential_scope_check: Optional[bool] = False,
) -> Tuple[Program, Block, Block]:
    prev_prog = copy.deepcopy(prog)

    graph_pass = pass_name if isinstance(pass_name, AbstractGraphPass) else PASS_REGISTRY[pass_name]

    _decorate_prog_with_scope_if_not_present(prog)
    graph_pass(prog)
    prog.validate(check_essential_scope=not skip_essential_scope_check)

    if not skip_function_name_check:
        if prev_prog.functions.keys() != prog.functions.keys():
            raise ValueError("function names changed during {pass_name}.")

    for name in prev_prog.functions:
        if not skip_output_name_check:
            assert_same_output_names(prev_prog, prog, name)
        if not skip_output_type_check:
            assert_same_output_types(prev_prog, prog, name)
        if not skip_output_shape_check:
            assert_same_output_shapes(prev_prog, prog, name)

        if not skip_input_name_check:
            assert_same_input_names(prev_prog, prog, name)
        if not skip_input_type_check:
            assert_same_input_types(prev_prog, prog, name)

    return prev_prog, prev_prog.functions[func_name], prog.functions[func_name]

def contains(self, mouseevent):
        if self._different_canvas(mouseevent):
            return False, {}

        # Make sure we have data to plot
        if self._invalidy or self._invalidx:
            self.recache()
        if len(self._xy) == 0:
            return False, {}

        # Convert points to pixels
        transformed_path = self._get_transformed_path()
        path, affine = transformed_path.get_transformed_path_and_affine()
        path = affine.transform_path(path)
        xy = path.vertices
        xt = xy[:, 0]
        yt = xy[:, 1]

        # Convert pick radius from points to pixels
        fig = self.get_figure(root=True)
        if fig is None:
            _log.warning('no figure set when check if mouse is on line')
            pixels = self._pickradius
        else:
            pixels = fig.dpi / 72. * self._pickradius

        # The math involved in checking for containment (here and inside of
        # segment_hits) assumes that it is OK to overflow, so temporarily set
        # the error flags accordingly.
        with np.errstate(all='ignore'):
            # Check for collision
            if self._linestyle in ['None', None]:
                # If no line, return the nearby point(s)
                ind, = np.nonzero(
                    (xt - mouseevent.x) ** 2 + (yt - mouseevent.y) ** 2
                    <= pixels ** 2)
            else:
                # If line, return the nearby segment(s)
                ind = segment_hits(mouseevent.x, mouseevent.y, xt, yt, pixels)
                if self._drawstyle.startswith("steps"):
                    ind //= 2

        ind += self.ind_offset

        # Return the point(s) within radius
        return len(ind) > 0, dict(ind=ind)

def loss_and_grads(self, grads, batch, *args, **kwargs):
        if batch is None:
            batch = (
                self._sample_from_joint(*args, **kwargs)
                for _ in range(self.training_batch_size)
            )
            batch_size = self.training_batch_size
        else:
            batch_size = len(batch)

        loss = 0
        for model_trace in batch:
            with poutine.trace(param_only=True) as particle_param_capture:
                guide_trace = self._get_matched_trace(model_trace, *args, **kwargs)
            particle_loss = self._differentiable_loss_particle(guide_trace)
            particle_loss /= batch_size

            if grads:
                guide_params = set(
                    site["value"].unconstrained()
                    for site in particle_param_capture.trace.nodes.values()
                )
                guide_grads = torch.autograd.grad(
                    particle_loss, guide_params, allow_unused=True
                )
                for guide_grad, guide_param in zip(guide_grads, guide_params):
                    if guide_grad is None:
                        continue
                    guide_param.grad = (
                        guide_grad
                        if guide_param.grad is None
                        else guide_param.grad + guide_grad
                    )

            loss += torch_item(particle_loss)

        warn_if_nan(loss, "loss")
        return loss

def get_merge_attributes(self) -> List[str]:
        if self.selected_radio.isChecked():
            return self.selected_attributes

        if isinstance(self.data, MArray):
            non_nan = self.data[~self.data.mask]
        elif isinstance(self.data, np.ndarray):
            non_nan = self.data[~np.isnan(self.data)]
        else:  # list
            non_nan = [x for x in self.data if x is not None]

        counts = Counter(non_nan)
        if self.n_values_radio.isChecked():
            keep_values = self.n_values_spin.value()
            values = counts.most_common()[keep_values:]
            indices = [i for i, _ in values]
        elif self.frequent_abs_radio.isChecked():
            indices = [v for v, c in counts.most_common()
                       if c < self.frequent_abs_spin.value()]
        else:  # self.frequent_rel_radio.isChecked():
            n_all = sum(counts.values())
            indices = [v for v, c in counts.most_common()
                       if c / n_all * 100 < self.frequent_rel_spin.value()]

        indices = np.array(indices, dtype=int)  # indices must be ints
        return np.array(self.variable.categories)[indices].tolist()

def ast_to_code(ast, indent=0):
    code = []

    def append(line):
        code.append(('    ' * indent) + line)

    if isinstance(ast, Node):
        append('ast.{}('.format(ast.__class__.__name__))
        indent += 1
        for i, k in enumerate(ast._fields, 1):
            v = getattr(ast, k)
            append('{}={},'.format(
                k,
                ast_to_code(v, indent),
            ))
        if ast.loc:
            append('loc={}'.format(ast_to_code(ast.loc, indent)))

        indent -= 1
        append(')')

    elif isinstance(ast, Loc):
        append('loc({}, {})'.format(ast.start, ast.end))

    elif isinstance(ast, list):
        if ast:
            append('[')
            indent += 1

            for i, it in enumerate(ast, 1):
                is_last = i == len(ast)
                append(ast_to_code(it, indent) + (',' if not is_last else ''))

            indent -= 1
            append(']')
        else:
            append('[]')

    else:
        append(repr(ast))

    return '\n'.join(code).strip()

def forward(
        self,
        y: np.ndarray,
        h: int,
        X: Optional[np.ndarray] = None,
        X_future: Optional[np.ndarray] = None,
        level: Optional[List[int]] = None,
        fitted: bool = False,
    ):
        if not hasattr(self, "model_"):
            raise Exception("You have to use the `fit` method first")
        y = _ensure_float(y)
        with np.errstate(invalid="ignore"):
            mod = forward_arima(self.model_, y=y, xreg=X, method=self.method)
        fcst = forecast_arima(mod, h, xreg=X_future, level=level)
        res = {"mean": fcst["mean"]}
        if fitted:
            res["fitted"] = fitted_arima(mod)
        if level is not None:
            level = sorted(level)
            if self.prediction_intervals is not None:
                res = self._add_conformal_intervals(fcst=res, y=y, X=X, level=level)
            else:
                res = {
                    **res,
                    **{f"lo-{l}": fcst["lower"][f"{l}%"] for l in reversed(level)},
                    **{f"hi-{l}": fcst["upper"][f"{l}%"] for l in level},
                }
            if fitted:
                # add prediction intervals for fitted values
                se = np.sqrt(mod["sigma2"])
                res = _add_fitted_pi(res=res, se=se, level=level)
        return res

def is_advanced_hyperparameter_format(hyperparameters: dict) -> bool:
    assert isinstance(hyperparameters, dict), f"`hyperparameters` must be a dict, but found: {type(hyperparameters)}"
    advanced_hyperparameter_format = None
    for key in hyperparameters:
        if isinstance(key, int) or (isinstance(key, str) and key == "default"):
            if advanced_hyperparameter_format is None:
                advanced_hyperparameter_format = True
            if not advanced_hyperparameter_format:
                raise ValueError(f"Invalid `hyperparameters` format:\n{hyperparameters}")
        else:
            if advanced_hyperparameter_format is None:
                advanced_hyperparameter_format = False
            if advanced_hyperparameter_format:
                raise ValueError(f"Invalid `hyperparameters` format:\n{hyperparameters}")

    if advanced_hyperparameter_format is None:
        advanced_hyperparameter_format = False
    return advanced_hyperparameter_format

def ParseFloat(text):
  try:
    # Assume Python compatible syntax.
    return float(text)
  except ValueError:
    # Check alternative spellings.
    if _FLOAT_INFINITY.match(text):
      if text[0] == '-':
        return float('-inf')
      else:
        return float('inf')
    elif _FLOAT_NAN.match(text):
      return float('nan')
    else:
      # assume '1.0f' format
      try:
        return float(text.rstrip('f'))
      except ValueError:
        raise ValueError('Couldn\'t parse float: %s' % text)

def pad(self, seqs, round_to=1):
        # TODO: This should be generalized to handle different ranks
        if not seqs:
            raise ValueError("Cannot pad empty sequence")
        if len(set(seq.ndim for seq in seqs)) != 1:
            raise ValueError("Cannot pad sequences with different ndims")
        if len(set(seq.dtype for seq in seqs)) != 1:
            raise ValueError("Cannot pad sequences with different dtypes")
        if len(set(seq.shape[1:] for seq in seqs)) != 1:
            raise ValueError("Cannot pad sequences that differ on other dimensions")

        # Our CUDA kernel can currently only handle C contiguous arrays.
        if not all(seq.flags["C_CONTIGUOUS"] for seq in seqs) or seqs[0].dtype not in (
            "float32",
            "float64",
            "int32",
            "int64",
        ):
            return super().pad(seqs, round_to)

        return _custom_kernels.pad(seqs, round_to)

def generate_from_arrow_type(pa_type: pa.DataType) -> FeatureType:
    if isinstance(pa_type, pa.StructType):
        return {field.name: generate_from_arrow_type(field.type) for field in pa_type}
    elif isinstance(pa_type, pa.FixedSizeListType):
        return List(generate_from_arrow_type(pa_type.value_type), length=pa_type.list_size)
    elif isinstance(pa_type, pa.ListType):
        return List(generate_from_arrow_type(pa_type.value_type))
    elif isinstance(pa_type, pa.LargeListType):
        return LargeList(generate_from_arrow_type(pa_type.value_type))
    elif isinstance(pa_type, _ArrayXDExtensionType):
        array_feature = [None, None, Array2D, Array3D, Array4D, Array5D][pa_type.ndims]
        return array_feature(shape=pa_type.shape, dtype=pa_type.value_type)
    elif isinstance(pa_type, pa.JsonType):
        return Json()
    elif isinstance(pa_type, pa.DataType):
        return Value(dtype=_arrow_to_datasets_dtype(pa_type))
    else:
        raise ValueError(f"Cannot convert {pa_type} to a Feature type.")

def parse_markdown_file(
        self, file_path: str
    ) -> MarkdownAgentConfig:
        if not os.path.exists(file_path):
            raise FileNotFoundError(
                f"Markdown file {file_path} not found."
            )

        try:
            with open(file_path, "r", encoding="utf-8") as file:
                content = file.read()

            # Parse YAML frontmatter (Claude Code sub-agent format)
            yaml_result = self.parse_yaml_frontmatter(content)
            frontmatter = yaml_result["frontmatter"]
            remaining_content = yaml_result["content"]

            if not frontmatter:
                raise ValueError(
                    f"No YAML frontmatter found in {file_path}. File must use Claude Code sub-agent format with YAML frontmatter."
                )

            # Use YAML frontmatter data
            config_data = {
                "name": frontmatter.get("name", Path(file_path).stem),
                "description": frontmatter.get(
                    "description", "Agent loaded from markdown"
                ),
                "model_name": frontmatter.get("model_name")
                or frontmatter.get("model", DEFAULT_MODEL),
                "temperature": frontmatter.get("temperature", 0.1),
                "max_loops": frontmatter.get("max_loops", 1),
                "mcp_url": frontmatter.get("mcp_url"),
                "system_prompt": remaining_content.strip(),
                "streaming_on": frontmatter.get(
                    "streaming_on", False
                ),
            }

            # Use default model if not specified
            if not config_data["model_name"]:
                config_data["model_name"] = DEFAULT_MODEL

            logger.info(
                f"Successfully parsed markdown file: {file_path}"
            )
            return MarkdownAgentConfig(**config_data)

        except Exception as e:
            logger.error(
                f"Error parsing markdown file {file_path}: {str(e)}"
            )
            raise ValueError(
                f"Error parsing markdown file {file_path}: {str(e)}"
            )

def ipynb(
    name: str,
    output: Path,
    watch: bool,
    sort: Literal["top-down", "topological"],
    include_outputs: bool,
    sandbox: bool | None,
    force: bool,
    args: tuple[str],
) -> None:
    import sys

    if include_outputs:
        # Set default, if not provided
        from marimo._cli.sandbox import maybe_prompt_run_in_sandbox

        if sandbox is None:
            sandbox = maybe_prompt_run_in_sandbox(name)

        if sandbox:
            from marimo._cli.sandbox import run_in_sandbox

            run_in_sandbox(
                sys.argv[1:],
                name=name,
                additional_deps=["nbformat"],
            )
            return

    try:
        DependencyManager.nbformat.require(
            why="to convert marimo notebooks to ipynb"
        )
    except ModuleNotFoundError as e:
        package = getattr(e, "name", None) or "nbformat"
        raise MarimoCLIMissingDependencyError(str(e), package) from None

    cli_args = parse_args(args) if include_outputs else {}

    def export_callback(file_path: MarimoPath) -> ExportResult:
        if include_outputs:
            return asyncio_run(
                run_app_then_export_as_ipynb(
                    file_path,
                    sort_mode=sort,
                    cli_args=cli_args,
                    argv=list(args),
                )
            )
        return export_as_ipynb(file_path, sort_mode=sort)

    return watch_and_export(
        MarimoPath(name), output, watch, export_callback, force
    )

def position_after_whitespace(body, start_position):
    body_length = len(body)
    position = start_position
    while position < body_length:
        code = char_code_at(body, position)
        if code in ignored_whitespace_characters:
            position += 1

        elif code == 35:  # #, skip comments
            position += 1
            while position < body_length:
                code = char_code_at(body, position)
                if not (code is not None and (code > 0x001F or code == 0x0009) and code not in (0x000A, 0x000D)):
                    break

                position += 1
        else:
            break
    return position

def detect_urls(files: list[str], verbose: bool = False) -> list[str]:
    external_urls: set[str] = set()
    for file in files:
        f_detect: Callable[[str, str], list[str]] | None = None
        if file.endswith(".html"):
            f_detect = detect_html_external_urls
        elif file.endswith(".css"):
            f_detect = detect_css_external_urls
        else:
            continue
        with open(file, encoding="utf-8") as f:
            content = f.read()
            urls = f_detect(content)
        if verbose:
            print(f"Processing {file}")
            exist_urls, new_urls = 0, 0
            for url in urls:
                if url in external_urls:
                    exist_urls += 1
                else:
                    new_urls += 1
                    if verbose:
                        print(f"Found new {url}")
            print(f"Found {exist_urls} existing resources and {new_urls} new resources")
        external_urls.update(urls)
    if verbose:
        print(f"Total {len(external_urls)} external resources")
        print("External resources:")
        print("\n".join(external_urls))

    return list(external_urls)

def aggregate_grads_colocate(all_grads, average=True):
    nr_tower = len(all_grads)
    if nr_tower == 1:
        return all_grads[0]

    def aggregate(grads):
        if average:
            return tf.multiply(tf.add_n(grads), 1.0 / nr_tower)
        else:
            return tf.add_n(grads)

    ret = []
    for idx, grad_and_vars in enumerate(zip(*all_grads)):
        # Ngpu * 2
        v = grad_and_vars[0][1]
        grads = [g for (g, _) in grad_and_vars]
        with tf.device(v.device):       # colocate summed grad with var
            grad = aggregate(grads)
        ret.append((grad, v))
    return ret

def run(self, *args, **kwargs):
        self._args, self._kwargs = args, kwargs
        num_samples = [0] * self.num_chains

        with optional(
            pyro.validation_enabled(not self.disable_validation),
            self.disable_validation is not None,
        ):
            args = [arg.detach() if torch.is_tensor(arg) else arg for arg in args]
            for x, chain_id in self.sampler.run(*args, **kwargs):
                if num_samples[chain_id] == 0:
                    # If transforms is not explicitly provided, infer automatically using
                    # model args, kwargs.
                    if self.transforms is None:
                        self._set_transforms(*args, **kwargs)
                    num_samples[chain_id] += 1
                    z_structure = x
                elif num_samples[chain_id] == self.num_samples + 1:
                    self._diagnostics[chain_id] = x
                else:
                    num_samples[chain_id] += 1
                    if self.num_chains > 1:
                        x_cloned = x.clone()
                        del x
                    else:
                        x_cloned = x

                    # unpack latent
                    pos = 0
                    z_acc = z_structure.copy()
                    for k in sorted(z_structure):
                        shape = z_structure[k]
                        next_pos = pos + shape.numel()
                        z_acc[k] = x_cloned[pos:next_pos].reshape(shape)
                        pos = next_pos

                    for name, z in z_acc.items():
                        if name in self.transforms:
                            z_acc[name] = self.transforms[name].inv(z)

                    self._statistics.update(
                        {
                            (chain_id, name): transformed_sample
                            for name, transformed_sample in z_acc.items()
                        }
                    )

        # terminate the sampler (shut down worker processes)
        self.sampler.terminate(True)

def gemma3_sdpa_pass(
        gm: torch.fx.GraphModule, settings: CompilationSettings
    ) -> torch.fx.GraphModule:
        config = get_lowering_pass_config(gemma3_sdpa_pass)
        sliding_window = None
        layer_types = None
        model_config = config.get("model_config", None)
        if not isinstance(model_config, Gemma3TextConfig):
            logger.warning(
                f"Expected Gemma3TextConfig, got {type(model_config)}, will use default SDPA replacement instead"
            )
        else:
            sliding_window = getattr(model_config, "sliding_window", None)
            layer_types = getattr(model_config, "layer_types", None)
            logger.debug(
                f"got Gemma3 config: sliding_window={sliding_window}, layer_types={layer_types}"
            )

        index = 0
        for node in gm.graph.nodes:
            if node.op == "call_function" and node.target in REPLACEABLE_ATEN_OPS:
                sliding_window_size = None
                if (
                    sliding_window is not None
                    and sliding_window > 0
                    and layer_types is not None
                    and index < len(layer_types)
                ):
                    if layer_types[index] == "sliding_attention":
                        sliding_window_size = sliding_window
                index += 1

                # Process the node
                logger.debug(
                    f"Applying Gemma3-specific SDPA replacement with {node.name=}, {node.target=}, {sliding_window_size=}"
                )
                gm = _process_sdpa_node(gm, node, settings, sliding_window_size)

        clean_up_graph_after_modifications(gm)
        logger.debug("Applied Gemma3-specific SDPA replacement")
        return gm

def find_agent_by_name(
    agents: List[Union[Agent, Callable]], agent_name: str
) -> Agent:
    if not agents:
        raise ValueError("Agents list cannot be empty")

    if not isinstance(agent_name, str):
        raise TypeError("Agent name must be a string")

    if not agent_name.strip():
        raise ValueError("Agent name cannot be empty or whitespace")

    try:
        for agent in agents:
            if hasattr(agent, "name") and agent.name == agent_name:
                return agent
        raise ValueError(f"Agent with name '{agent_name}' not found")
    except Exception as e:
        raise RuntimeError(f"Error finding agent: {str(e)}")

def explain_response(response, if_2xx, if_4xx, if_others, exit_if_4xx=False):
    if response.ok or response.is_redirect:
        if if_2xx:
            console.print(if_2xx)
        return
    else:
        if response.status_code >= 400 and response.status_code <= 499:
            errmsg = if_4xx
        else:
            errmsg = if_others
        try:
            # convert response text to json
            content = response.json()
            console.print(
                f"{response.status_code} {content['code']}:"
                f" {content['message']}\n{errmsg}"
            )
        except Exception:
            # fallback to display raw message
            console.print(f"{response.status_code}: {response.text}\n{errmsg}")

        if (
            response.status_code >= 400
            and response.status_code <= 499
            and not exit_if_4xx
        ):
            return
        else:
            sys.exit(1)

def add_condition_greater_than(self, threshold: float, metrics: Optional[List[str]] = None, class_mode: str = 'all'
                                   ):

        def condition(check_result, metrics_to_check=metrics):
            metrics_to_check = check_result['Metric'].unique() if metrics_to_check is None else metrics_to_check
            metrics_pass = []

            for metric in metrics_to_check:
                if metric not in check_result.Metric.unique():
                    raise DeepchecksValueError(f'The requested metric was not calculated, the metrics calculated in '
                                               f'this check are: {check_result.Metric.unique()}.')

                class_val = check_result[check_result.Metric == metric].groupby('Class').Value
                class_gt = class_val.apply(lambda x: x > threshold)
                if class_mode == 'all':
                    metrics_pass.append(all(class_gt))
                elif class_mode == 'any':
                    metrics_pass.append(any(class_gt))
                elif class_mode in class_val.groups:
                    metrics_pass.append(class_gt[class_val.indices[class_mode]].item())
                else:
                    raise DeepchecksValueError(f'class_mode expected be one of the classes in the check results or any '
                                               f'or all, received {class_mode}.')

            if all(metrics_pass):
                return ConditionResult(ConditionCategory.PASS, 'Passed for all of the metrics.')
            else:
                failed_metrics = ([a for a, b in zip(metrics_to_check, metrics_pass) if not b])
                return ConditionResult(ConditionCategory.FAIL, f'Failed for metrics: {failed_metrics}')

        return self.add_condition(f'Selected metrics scores are greater than {format_number(threshold)}', condition)

def load_pretrained_model(model, model_path, modules_to_load=None, exclude_modules=None):
    model_dict = torch.load(model_path, map_location=lambda storage, loc: storage)
    if exclude_modules:
        for e in exclude_modules.split(","):
            model_dict = {k: v for k, v in model_dict.items() if not k.startswith(e)}

    if not modules_to_load:
        src_dict = model_dict
    else:
        src_dict = {}
        for module in modules_to_load.split(","):
            src_dict.update({k: v for k, v in model_dict.items() if k.startswith(module)})

    dst_state = model.state_dict()
    dst_state.update(src_dict)
    model.load_state_dict(dst_state)

def get_redirects(redirects_filename):
    redirects = {}
    print("Parsing the NT redirect file")
    for l, line in enumerate(BZ2File(redirects_filename)):
        split = line.split()
        if len(split) != 4:
            print("ignoring malformed line: " + line)
            continue
        redirects[short_name(split[0])] = short_name(split[2])
        if l % 1000000 == 0:
            print("[%s] line: %08d" % (datetime.now().isoformat(), l))

    # compute the transitive closure
    print("Computing the transitive closure of the redirect relation")
    for l, source in enumerate(redirects.keys()):
        transitive_target = None
        target = redirects[source]
        seen = {source}
        while True:
            transitive_target = target
            target = redirects.get(target)
            if target is None or target in seen:
                break
            seen.add(target)
        redirects[source] = transitive_target
        if l % 1000000 == 0:
            print("[%s] line: %08d" % (datetime.now().isoformat(), l))

    return redirects

def update_user_template(self, old_name, new_name, new_content):
        prompts_config_path = get_prompts_config_path()
        if not os.path.exists(prompts_config_path):
            return

        try:
            with open(prompts_config_path, "r", encoding="utf-8") as f:
                user_templates = json.load(f)

            for template in user_templates:
                if template["name"] == old_name:
                    template["name"] = new_name
                    template["content"] = new_content
                    break

            with open(prompts_config_path, "w", encoding="utf-8") as f:
                json.dump(user_templates, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Error updating template: {e}")

def should_cast_parameter(self, op: Operation, param_name: str) -> Optional[str]:
        if not super()._check_target_dtype_for_param(op, param_name, self.target_dtype):
            return None

        if is_current_opset_version_compatible_with(AvailableTarget.iOS17):
            # In IOS17+ activation ops with alpha/beta support mixed precision, and we don't want to
            # cast alpha/beta to fp16 for better numerical accuracy.
            if op.op_type in self._ACTIVATION_ALPHA_OPS and param_name == "alpha":
                return None
            if op.op_type in self._ACTIVATION_ALPHA_BETA_OPS and param_name in {"alpha", "beta"}:
                return None

            # Element-wise unary ops with epsilon also support mixed precision.
            if op.op_type in self._ELEMENTWISE_UNARY_EPSILON_OPS and param_name == "epsilon":
                return None

        return self.target_dtype

def to_copy(self, column_names=None, selection=None, strings=True, virtual=True, selections=True):
        if column_names:
            column_names = _ensure_strings_from_expressions(column_names)
        df = vaex.from_items(*self.to_items(column_names=column_names, selection=selection, strings=strings, virtual=False))
        if virtual:
            for name, value in self.virtual_columns.items():
                df.add_virtual_column(name, value)
        if selections:
            # the filter selection does not need copying
            for key, value in self.selection_histories.items():
                if key != FILTER_SELECTION_NAME:
                    df.selection_histories[key] = list(value)
            for key, value in self.selection_history_indices.items():
                if key != FILTER_SELECTION_NAME:
                    df.selection_history_indices[key] = value
        df.functions.update(self.functions)
        df.copy_metadata(self)
        return df

def compress(self, num_kmeans_workers: int = 1, inplace: bool = False) -> _torch.nn.Module:
        self._model = super().compress(inplace=inplace)
        kmeans_config_dict = dict()
        for name, submodule in self._model.named_modules():
            submod_config = self._config.get_module_config(name, submodule)
            if submod_config is None:
                continue

            k_means_module_cls = _KMeansSupportedModulesRegistry.get_kmeans_module(submodule)
            if k_means_module_cls is None:
                continue

            for param_name in k_means_module_cls.parameter_names:
                # Validate configuration for parameter
                param = submodule.get_parameter(param_name)
                updated_config = _validate_param_config(
                    name + "." + param_name,
                    param,
                    submodule,
                    submod_config,
                    ["palettization_group_size", "palettization_cluster_dim"],
                )
                if not updated_config:
                    continue

                if name not in kmeans_config_dict:
                    kmeans_config_dict[name] = {}

                kmeans_config_dict[name][param_name] = _KMeansConfig(
                    n_bits=updated_config.n_bits,
                    axis=updated_config.channel_axis,
                    lut_dtype=updated_config.lut_dtype,
                    block_size=updated_config.group_size,
                    cluster_dim=updated_config.cluster_dim,
                    enable_per_channel_scale=updated_config.enable_per_channel_scale,
                    enable_fast_kmeans_mode=updated_config.enable_fast_kmeans_mode,
                    rounding_precision=updated_config.rounding_precision,
                )

        if num_kmeans_workers > 1:
            return _ParallelKMeans.cluster_weights(
                self._model, kmeans_config_dict, num_workers=num_kmeans_workers
            )
        else:
            return _SequentialKMeans.cluster_weights(self._model, kmeans_config_dict)

def linkcode_resolve(domain, info):
  if domain != 'py':
    return None

  try:
    mod = sys.modules[info['module']]
  except ImportError:
    return None

  obj = mod
  try:
    for attr in info['fullname'].split('.'):
      obj = getattr(obj, attr)
  except AttributeError:
    return None
  else:
    obj = inspect.unwrap(obj)

  try:
    filename = inspect.getsourcefile(obj)
  except TypeError:
    return None

  try:
    source, lineno = inspect.getsourcelines(obj)
  except OSError:
    return None

  # TODO(slebedev): support tags after we release an initial version.
  return 'https://github.com/deepmind/sonnet/blob/v2/sonnet/%s#L%d#L%d' % (
      os.path.relpath(filename, start=os.path.dirname(
          snt.__file__)), lineno, lineno + len(source) - 1)

def list_instances(
    status: Optional[str] = None,
    config: Optional[Dict[str, str]] = None,
) -> Dict[str, Dict[str, Any]]:
    if config is None:
        config = resolve_current_config()
    endpoint = '/v2/instances'
    base_params: Dict[str, Any] = ({
        'project': quote(config['project_id'])
    } if config['project_id'] else {})
    instances: Dict[str, Dict[str, Any]] = {}
    cursor: Optional[str] = None

    try:
        while True:
            params = base_params.copy()
            if cursor:
                params['next_cursor'] = cursor

            response = _make_request('GET',
                                     endpoint,
                                     params=params,
                                     config=config)
            logger.debug(f'Raw API response: {json.dumps(response, indent=2)}')

            instance_list = response.get('data', [])
            for instance in instance_list:
                instance_id = instance['fid']
                raw_status = instance['status']
                logger.debug(f'Instance {instance_id} status: {raw_status}')

                # Filter by status if provided (matches raw API status)
                if status and raw_status != status:
                    continue

                instances[instance_id] = {
                    'fid': instance_id,
                    'name': instance['name'],
                    'status': raw_status,
                    'ssh_destination': instance['ssh_destination'],
                    'instance_type': instance['instance_type'],
                    'created_at': instance['created_at'],
                    'bid': instance['bid'],
                    'private_ip': instance['private_ip'],
                    'region': instance['region'],
                }

            # Check for next page
            cursor = response.get('next_cursor')
            if not cursor:
                break

        return instances
    except Exception as e:
        raise MithrilError(f'Failed to list instances: {str(e)}') from e

def validate_token(self) -> Dict[str, Any]:
        try:
            # Try to get token from huggingface_hub
            token = hf_get_token()

            # If not found, try direct file read
            if not token:
                token_path = Path.home() / ".cache" / "huggingface" / "token"
                if token_path.exists():
                    with open(token_path, "r") as f:
                        token = f.read().strip()

            if not token:
                return {
                    "valid": False,
                    "message": "No HuggingFace token found. Please run 'huggingface-cli login'.",
                }

            # Validate token by trying to get user info
            try:
                user_info = self.api.whoami(token=token)
                return {
                    "valid": True,
                    "username": user_info.get("name"),
                    "message": "Token is valid",
                }
            except Exception as e:
                return {
                    "valid": False,
                    "message": f"Token is invalid or expired: {str(e)}",
                }

        except Exception as e:
            raise PublishingServiceError(
                f"Failed to validate token: {str(e)}",
                status.HTTP_500_INTERNAL_SERVER_ERROR,
            ) from e

def compute_pooling_output_shape(
    input_shape,
    pool_size,
    strides,
    padding="valid",
    data_format="channels_last",
):
    strides = pool_size if strides is None else strides
    input_shape_origin = list(input_shape)
    input_shape = np.array(input_shape)
    if data_format == "channels_last":
        spatial_shape = input_shape[1:-1]
    else:
        spatial_shape = input_shape[2:]
    none_dims = []
    for i in range(len(spatial_shape)):
        if spatial_shape[i] is None:
            # Set `None` shape to a manual value so that we can run numpy
            # computation on `spatial_shape`.
            spatial_shape[i] = -1
            none_dims.append(i)
    pool_size = np.array(pool_size)
    if padding == "valid":
        output_spatial_shape = (
            np.floor((spatial_shape - pool_size) / strides) + 1
        )
        for i in range(len(output_spatial_shape)):
            if i not in none_dims and output_spatial_shape[i] < 0:
                raise ValueError(
                    "Computed output size would be negative. Received: "
                    f"`inputs.shape={input_shape}` and `pool_size={pool_size}`."
                )
    elif padding == "same":
        output_spatial_shape = np.floor((spatial_shape - 1) / strides) + 1
    else:
        raise ValueError(
            "Argument `padding` must be either 'valid' or 'same'. Received: "
            f"padding={padding}"
        )
    output_spatial_shape = [int(i) for i in output_spatial_shape]
    for i in none_dims:
        output_spatial_shape[i] = None
    output_spatial_shape = tuple(output_spatial_shape)
    if data_format == "channels_last":
        output_shape = (
            (input_shape_origin[0],)
            + output_spatial_shape
            + (input_shape_origin[-1],)
        )
    else:
        output_shape = (
            input_shape_origin[0],
            input_shape_origin[1],
        ) + output_spatial_shape
    return output_shape

