def datetime_parsing(text: str, base_date: datetime = None) -> list[tuple[str, datetime, tuple[int, int]]]:
    if base_date is None:
        base_date = datetime.now()

    matches = []
    found_array = []

    # Find the position in the string
    for expression, function in regex:
        for match in expression.finditer(text):
            matches.append((match.group(), function(match, base_date), match.span()))

    # Wrap the matched text with TAG element to prevent nested selections
    for match, value, spans in matches:
        subn = re.subn(
            '(?!<TAG[^>]*?>)' + match + '(?![^<]*?</TAG>)', '<TAG>' + match + '</TAG>', text
        )
        text = subn[0]
        is_substituted = subn[1]
        if is_substituted != 0:
            found_array.append((match, value, spans))

    # To preserve order of the match, sort based on the start position
    return sorted(found_array, key=lambda match: match and match[2][0])

def restore(self, scope: dict[str, Any]) -> None:
        memo: dict[int, Any] = {}  # Track processed objects to handle cycles
        for var, lookup in self.contextual_defs():
            value = self.defs.get(var, None)
            scope[lookup] = self._restore_from_stub_if_needed(
                value, scope, memo
            )

        for key, value in self.meta.items():
            self.meta[key] = self._restore_from_stub_if_needed(
                value, scope, memo
            )

        defs = {**globals(), **scope}
        for ref in self.stateful_refs:
            if ref not in defs:
                raise CacheException(
                    "Failure while restoring cached values. "
                    "Cache expected a reference to a "
                    f"variable that is not present ({ref})."
                )
            value = defs[ref]
            if isinstance(value, SetFunctor):
                value(self.defs[ref])
            # UI Values cannot be easily programmatically set, so only update
            # state values.
            elif not isinstance(value, UIElement):
                raise CacheException(
                    "Failure while restoring cached values. "
                    "Unexpected stateful reference type "
                    f"({type(ref)}:{ref})."
                )

def submit(
        self,
        *args,
        api_name: str | None = None,
        fn_index: int | None = None,
        headers: dict[str, str] | None = None,
        result_callbacks: Callable | list[Callable] | None = None,
        **kwargs,
    ) -> Job:
        inferred_fn_index = self._infer_fn_index(api_name, fn_index)

        endpoint = self.endpoints[inferred_fn_index]

        if isinstance(endpoint, Endpoint):
            args = utils.construct_args(endpoint.parameters_info, args, kwargs)

        helper = None
        if endpoint.protocol in (
            "sse",
            "sse_v1",
            "sse_v2",
            "sse_v2.1",
            "sse_v3",
        ):
            headers = headers or {}
            headers["x-gradio-user"] = "api"
            helper = self.new_helper(inferred_fn_index, headers=headers)
            end_to_end_fn = endpoint.make_end_to_end_fn(helper)
        else:
            raise ValueError("Unknown protocol: " + endpoint.protocol)
        future = self.executor.submit(copy_context().run, end_to_end_fn, *args)

        cancel_fn = endpoint.make_cancel(helper)

        job = Job(
            future,
            communicator=helper,
            verbose=self.verbose,
            space_id=self.space_id,
            _cancel_fn=cancel_fn,
        )

        if result_callbacks:
            if isinstance(result_callbacks, Callable):
                result_callbacks = [result_callbacks]

            def create_fn(callback) -> Callable:
                def fn(future):
                    if isinstance(future.result(), tuple):
                        callback(*future.result())
                    else:
                        callback(future.result())

                return fn

            for callback in result_callbacks:
                job.add_done_callback(create_fn(callback))

        return job

def create(
        cls,
        *,
        role: Literal["user", "assistant", "system"],
        message_id: str,
        content: str | None,
        parts: list[ChatPart],
        part_validator_class: Any | None = None,
    ) -> ChatMessage:

        if part_validator_class:
            validated_parts = []
            for part in parts:
                if isinstance(part, part_validator_class):
                    validated_parts.append(part)
                elif isinstance(part, dict):
                    sanitized_part = remove_none_values(part)
                    # Try pydantic validation for dict -> class conversion
                    try:
                        from pydantic import TypeAdapter

                        adapter = TypeAdapter(part_validator_class)
                        validated_parts.append(
                            adapter.validate_python(sanitized_part)
                        )
                    except ImportError:
                        LOGGER.debug(
                            "Pydantic not installed, skipping dict validation"
                        )
                    except Exception:
                        LOGGER.debug("Part %r could not be validated", part)
                else:
                    LOGGER.debug(
                        "Part %r (type=%s) is not an instance of %s and not a dict, dropping",
                        part,
                        type(part).__name__,
                        part_validator_class.__name__,
                    )
            parts = validated_parts

        return cls(role=role, id=message_id, content=content, parts=parts)

def reshape_classifier_output(model, n=1000):
    from models.common import Classify

    name, m = list((model.model if hasattr(model, "model") else model).named_children())[-1]  # last module
    if isinstance(m, Classify):  # YOLOv5 Classify() head
        if m.linear.out_features != n:
            m.linear = nn.Linear(m.linear.in_features, n)
    elif isinstance(m, nn.Linear):  # ResNet, EfficientNet
        if m.out_features != n:
            setattr(model, name, nn.Linear(m.in_features, n))
    elif isinstance(m, nn.Sequential):
        types = [type(x) for x in m]
        if nn.Linear in types:
            i = len(types) - 1 - types[::-1].index(nn.Linear)  # last nn.Linear index
            if m[i].out_features != n:
                m[i] = nn.Linear(m[i].in_features, n)
        elif nn.Conv2d in types:
            i = len(types) - 1 - types[::-1].index(nn.Conv2d)  # last nn.Conv2d index
            if m[i].out_channels != n:
                m[i] = nn.Conv2d(m[i].in_channels, n, m[i].kernel_size, m[i].stride, bias=m[i].bias is not None)

def make_tensor_type_proto(
    elem_type: int,
    shape: Sequence[str | int | None] | None,
    shape_denotation: list[str] | None = None,
) -> TypeProto:
    type_proto = TypeProto()
    tensor_type_proto = type_proto.tensor_type
    tensor_type_proto.elem_type = elem_type
    tensor_shape_proto = tensor_type_proto.shape

    if shape is not None:
        # You might think this is a no-op (extending a normal Python
        # list by [] certainly is), but protobuf lists work a little
        # differently; if a field is never set, it is omitted from the
        # resulting protobuf; a list that is explicitly set to be
        # empty will get an (empty) entry in the protobuf. This
        # difference is visible to our consumers, so make sure we emit
        # an empty shape!
        tensor_shape_proto.dim.extend([])

        if shape_denotation and len(shape_denotation) != len(shape):
            raise ValueError(
                "Invalid shape_denotation. Must be of the same length as shape."
            )

        for i, d in enumerate(shape):
            dim = tensor_shape_proto.dim.add()
            if d is None:
                pass
            elif isinstance(d, int):
                dim.dim_value = d
            elif isinstance(d, str):
                dim.dim_param = d
            else:
                raise ValueError(
                    f"Invalid item in shape: {d}. Needs to be of int or str."
                )

            if shape_denotation:
                dim.denotation = shape_denotation[i]

    return type_proto

def meta_init(module: nn.Module, param_init_fn: Optional[Callable[[nn.Module], None]] = None) -> None:
    # TODO need a unit test for this
    cur_param_init_fn = getattr(module, 'param_init_fn', param_init_fn)
    for child in module.children():
        meta_init(child, cur_param_init_fn)
    has_meta = any(param.is_meta for param in module.parameters(recurse=False)
                  ) or any(buffer.is_meta for buffer in module.buffers(recurse=False))
    if not has_meta:
        return
    for param in module.parameters(recurse=False):
        # NOTE we assume buffers are not shared among modules
        assert isinstance(
            param,
            DTensor,
        ), 'Only DTensor can be meta initialized safely w/o breaking potential weight tying'
    module.to_empty(device='cuda', recurse=False)
    if isinstance(cur_param_init_fn, Callable):
        cur_param_init_fn(module)
    elif hasattr(module, 'reset_parameters') and isinstance(module.reset_parameters, Callable):
        module.reset_parameters()
    else:
        raise ValueError(
            f'Module `{module}` does not have (or have inherited) a ``param_init_fn`` or does not have a ``reset_parameters`` function. '
            'This leaves parameters without initialization. Please add a ``param_init_fn`` or ``reset_parameters`` '
            f'to module `{module}`.',
        )

def check_user_config(self):
        if self.config.aspect_bucket_alignment != 64:
            logger.warning(
                f"{self.NAME} requires an alignment value of 64px. Overriding the value of --aspect_bucket_alignment."
            )
            self.config.aspect_bucket_alignment = 64

        if self.config.prediction_type is not None:
            logger.warning(
                f"{self.NAME} uses flow matching and does not support prediction type {self.config.prediction_type}."
            )

        # Lumina2 supports up to 256 tokens by default
        if self.config.tokenizer_max_length is None:
            self.config.tokenizer_max_length = 256
        elif self.config.tokenizer_max_length > 512:
            logger.warning(f"{self.NAME} has a maximum token length of 512. Setting to 512.")
            self.config.tokenizer_max_length = 512

        # Lumina2 default inference steps
        if self.config.validation_num_inference_steps > 30:
            logger.warning(
                f"{self.NAME} typically uses around 30 inference steps. Consider reducing --validation_num_inference_steps."
            )

def on_classes_filter_clicked(self):
        if self.model_manager.loaded_model_config is None:
            return
        model = self.model_manager.loaded_model_config.get("model")
        classes_attr = getattr(model, "classes", [])
        if not classes_attr:
            return
        if isinstance(classes_attr, dict):
            class_names = [
                classes_attr[k] for k in sorted(classes_attr.keys())
            ]
        else:
            class_names = list(classes_attr)

        raw_filter = getattr(model, "filter_classes", None)
        filter_names = None
        if isinstance(raw_filter, list):
            if (
                raw_filter
                and isinstance(raw_filter[0], int)
                and not isinstance(classes_attr, dict)
            ):
                filter_names = [
                    class_names[i]
                    for i in raw_filter
                    if 0 <= int(i) < len(class_names)
                ]
            else:
                filter_names = raw_filter
        dialog = ClassesFilterDialog(class_names, filter_names, parent=self)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            self.model_manager.set_auto_labeling_filter_classes(
                dialog.get_selected_classes()
            )

async def update_resource_rule(
    rule_id: int,
    data: UpdateResourceRuleRequest,
    admin: User = Depends(require_permission("admin.users")),
) -> ResourceRuleResponse:
    store = _get_store()

    # Check rule exists
    existing = await store.get_resource_rule(rule_id)
    if not existing:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Resource rule {rule_id} not found",
        )

    # Build updates dict
    updates = {}
    if data.name is not None:
        updates["name"] = data.name
    if data.pattern is not None:
        updates["pattern"] = data.pattern
    if data.action is not None:
        if data.action not in ["allow", "deny"]:
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail="Invalid action. Must be 'allow' or 'deny'",
            )
        updates["action"] = data.action
    if data.priority is not None:
        updates["priority"] = data.priority
    if data.description is not None:
        updates["description"] = data.description

    if not updates:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="No fields to update",
        )

    success = await store.update_resource_rule(rule_id, updates)
    if not success:
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Failed to update rule",
        )

    # Fetch updated rule
    rule = await store.get_resource_rule(rule_id)

    logger.info("Resource rule %d updated by %s", rule_id, admin.username)

    return ResourceRuleResponse(
        id=rule.id,
        name=rule.name,
        resource_type=rule.resource_type.value,
        pattern=rule.pattern,
        action=rule.action.value,
        priority=rule.priority,
        description=rule.description,
    )

def wait_until_running(self) -> public.Run:
        if self._run is not None:
            return self._run

        while True:
            # sleep here to hide an ugly warning
            time.sleep(2)
            item = self._get_item()
            if item and item["associatedRunId"] is not None:
                try:
                    self._run = public.Run(
                        self.client,
                        self._entity,
                        self.project,
                        item["associatedRunId"],
                        None,
                    )
                    self._run_id = item["associatedRunId"]
                except ValueError as e:
                    wandb.termwarn(str(e))
                else:
                    return self._run
            elif item:
                wandb.termlog("Waiting for run to start")

            time.sleep(3)

def similarity_score(s1: str, s2: str) -> float:
    # Find common prefix length
    prefix_len = 0
    for c1, c2 in zip(s1, s2, strict=False):
        if c1 != c2:
            break
        prefix_len += 1

    # Find common suffix length if strings differ in middle
    if prefix_len < min(len(s1), len(s2)):
        s1_rev = s1[::-1]
        s2_rev = s2[::-1]
        suffix_len = 0
        for c1, c2 in zip(s1_rev, s2_rev, strict=False):
            if c1 != c2:
                break
            suffix_len += 1
    else:
        suffix_len = 0

    # Return inverse similarity - shorter common affix means higher score
    return len(s1) + len(s2) - 2.0 * (prefix_len + suffix_len)

def finalize(
        self, model: _Optional[_torch.nn.Module] = None, inplace: bool = False
    ) -> _torch.nn.Module:
        if model is None:
            model = self._model
        finalized_model = model if inplace else _copy.deepcopy(model)

        # If model has been prepared for quantization but not finalized yet
        if _is_quant_prepared(self):
            raise RuntimeError(
                "When running joint compression, first finalize quantizer / palettizer "
                "and then finalize pruner with that model. This is to ensure the compression "
                "metadata (required for export) is correctly registered in the model."
            )

        # Add compression metadata
        _register_metadata_version(finalized_model)
        for name, pruner_info in self._pruner_info.items():
            submodule = finalized_model.get_submodule(name)
            _utils.register_compression_metadata(submodule, pruner_info, self._supported_modules)

        # Remove pruning hooks
        for name, submodule in finalized_model.named_modules(remove_duplicate=True):
            if hasattr(submodule, "pruning_method"):
                submodule.pruning_method.remove(submodule)
            # If the module has been joint pruned + palettized, then palettizer finalize()
            # can remove pruning_method attribute but not the forward pre hook. So we explicitly remove it.
            elif name in self._pruner_info and _is_palettized_module(
                self._pruner_info[name].module
            ):
                for k, hook in submodule._forward_pre_hooks.items():
                    if isinstance(hook, BaseDynamicPruningMethod):
                        del submodule._forward_pre_hooks[k]

        if model is None:
            self._model = finalized_model
        return finalized_model

def concat_examples_func(batch, device=None, padding=None):
    assert device is None or isinstance(device, backend.Device)
    if not batch:
        raise ValueError('batch is empty')

    first_elem = batch[0]

    if isinstance(first_elem, tuple):
        result = []
        if not isinstance(padding, tuple):
            padding = [padding] * len(first_elem)

        for i in six.moves.range(len(first_elem)):
            result.append(to_device(device, _concat_arrays(
                [example[i] for example in batch], padding[i])))

        return tuple(result)

    elif isinstance(first_elem, dict):
        result = {}
        if not isinstance(padding, dict):
            padding = {key: padding for key in first_elem}

        for key in first_elem:
            result[key] = to_device(device, _concat_arrays(
                [example[key] for example in batch], padding[key]))

        return result

    else:
        return to_device(device, _concat_arrays(batch, padding))

def extract_tensor_patches(
    input: torch.Tensor,
    window_size: Union[int, Tuple[int, int]],
    stride: Union[int, Tuple[int, int]] = 1,
    padding: PadType = 0,
    allow_auto_padding: bool = False,
) -> torch.Tensor:
    if not torch.is_tensor(input):
        raise TypeError(f"Input input type is not a torch.Tensor. Got {type(input)}")

    if len(input.shape) != 4:
        raise ValueError(f"Invalid input shape, we expect BxCxHxW. Got: {input.shape}")

    # check if the window sliding over the image will fit into the image
    # torch's unfold drops the final patches that don't fit
    window_size = cast(Tuple[int, int], _pair(window_size))
    stride = cast(Tuple[int, int], _pair(stride))
    original_size = (input.shape[-2], input.shape[-1])

    if not padding:
        # if padding is specified, we leave it up to the user to ensure it fits
        # otherwise we check here if it will fit and offer to calculate padding
        if not _check_patch_fit(original_size, window_size, stride):
            if not allow_auto_padding:
                warn(
                    f"The window will not fit into the image. \nWindow size: {window_size}\nStride: {stride}\n"
                    f"Image size: {original_size}\n"
                    "This means that the final incomplete patches will be dropped. By enabling `allow_auto_padding`, "
                    "the input will be padded to fit the window and stride.",
                    stacklevel=1,
                )
            else:
                padding = compute_padding(original_size=original_size, window_size=window_size, stride=stride)

    if padding:
        padding = create_padding_tuple(padding)
        input = F.pad(input, padding)

    return _extract_tensor_patchesnd(input, window_size, stride)

def shutdown(self) -> None:
        # Check if already shutdown
        if getattr(self, "_is_shutdown", False):
            return
        self._is_shutdown = True

        # Signal all workers to stop
        instruction_queues = getattr(self, "_instruction_queues", None)
        if instruction_queues:
            for _, queue in instruction_queues.items():
                queue.put("stop")

        # Let base class handle background thread cleanup
        super().shutdown()

        # Close all multiprocessing queues created by the scheme.
        queues_to_close = []
        for name in ("_weight_init_queues", "_instruction_queues", "_ack_queues"):
            mapping = getattr(self, name, None)
            if not mapping:
                continue
            queues_to_close.extend(mapping.values())
            setattr(self, name, {})

        unique = {}
        for q in queues_to_close:
            unique[id(q)] = q
        for q in unique.values():
            _close_mp_queue(q)

def convert_batch_of_bboxes(
        batch: _BatchOfSamples,
        notation: str
) -> List[np.ndarray]:
    are_coordinates_normalized, notation_tokens = verify_bbox_format_notation(notation)
    output = []

    for image, bboxes in batch:
        if len(bboxes) == 0:
            # image does not have bboxes
            output.append(np.asarray([]))
            continue

        if are_coordinates_normalized is False:
            image_height = None
            image_width = None
        elif isinstance(image, Image):
            image_height, image_width = image.height, image.width
        elif is_torch_object(image) or isinstance(image, np.ndarray):
            image_height, image_width, *_ = image.shape
        else:
            raise TypeError(
                'Do not know how to take dimension sizes of '
                f'object of type - {type(image)}'
            )

        r = []
        for bbox in bboxes:
            if len(bbox) < 5:
                raise ValueError('incorrect bbox')  # TODO: better message
            else:
                r.append(_convert_bbox(
                    bbox,
                    notation_tokens,
                    image_width=image_width,
                    image_height=image_height,
                ))
        output.append(np.stack(r, axis=0))

    return output

def start_or_get_spark(
    app_name="Sample",
    url="local[*]",
    memory="10g",
    config=None,
    packages=None,
    jars=None,
    repositories=None,
):

    submit_args = ""
    if packages is not None:
        submit_args = "--packages {} ".format(",".join(packages))
    if jars is not None:
        submit_args += "--jars {} ".format(",".join(jars))
    if repositories is not None:
        submit_args += "--repositories {}".format(",".join(repositories))
    if submit_args:
        os.environ["PYSPARK_SUBMIT_ARGS"] = "{} pyspark-shell".format(submit_args)

    spark_opts = [
        'SparkSession.builder.appName("{}")'.format(app_name),
        'master("{}")'.format(url),
    ]

    if config is not None:
        for key, raw_value in config.items():
            value = (
                '"{}"'.format(raw_value) if isinstance(raw_value, str) else raw_value
            )
            spark_opts.append('config("{key}", {value})'.format(key=key, value=value))

    if config is None or "spark.driver.memory" not in config:
        spark_opts.append('config("spark.driver.memory", "{}")'.format(memory))

    # Set larger stack size
    spark_opts.append('config("spark.executor.extraJavaOptions", "-Xss4m")')
    spark_opts.append('config("spark.driver.extraJavaOptions", "-Xss4m")')

    spark_opts.append("getOrCreate()")
    return eval(".".join(spark_opts))

def from_dict(cls, obj: dict) -> TagData:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return TagData.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in TagData) in the input: " + str(obj))

        _obj = TagData.parse_obj({
            "id": obj.get("id"),
            "dataset_id": obj.get("datasetId"),
            "prev_tag_id": obj.get("prevTagId"),
            "query_tag_id": obj.get("queryTagId"),
            "preselected_tag_id": obj.get("preselectedTagId"),
            "name": obj.get("name"),
            "bit_mask_data": obj.get("bitMaskData"),
            "tot_size": obj.get("totSize"),
            "created_at": obj.get("createdAt"),
            "last_modified_at": obj.get("lastModifiedAt"),
            "changes": [TagChangeEntry.from_dict(_item) for _item in obj.get("changes")] if obj.get("changes") is not None else None,
            "run_id": obj.get("runId")
        })
        return _obj

def objects_to_list_of_image_dicts(
    objs: Union[list[str], list[dict], list[np.ndarray], list["PIL.Image.Image"]],
) -> list[dict]:
    if config.PIL_AVAILABLE:
        import PIL.Image
    else:
        raise ImportError("To support encoding images, please install 'Pillow'.")

    if objs:
        _, obj = first_non_null_value(objs)
        if isinstance(obj, str):
            return [{"path": obj, "bytes": None} if obj is not None else None for obj in objs]
        if isinstance(obj, np.ndarray):
            obj_to_image_dict_func = no_op_if_value_is_null(encode_np_array)
            return [obj_to_image_dict_func(obj) for obj in objs]
        elif isinstance(obj, PIL.Image.Image):
            obj_to_image_dict_func = no_op_if_value_is_null(encode_pil_image)
            return [obj_to_image_dict_func(obj) for obj in objs]
        else:
            return objs
    else:
        return objs

def protocol_df_chunk_to_pandas(df: DataFrameXchg) -> pd.DataFrame:
    columns: dict[str, Any] = {}
    buffers = []  # hold on to buffers, keeps memory alive
    for name in df.column_names():
        if not isinstance(name, str):
            raise ValueError(f"Column {name} is not a string")
        if name in columns:
            raise ValueError(f"Column {name} is not unique")
        col = df.get_column_by_name(name)
        dtype = col.dtype[0]
        if dtype in (
            DtypeKind.INT,
            DtypeKind.UINT,
            DtypeKind.FLOAT,
            DtypeKind.BOOL,
        ):
            columns[name], buf = primitive_column_to_ndarray(col)
        elif dtype == DtypeKind.CATEGORICAL:
            columns[name], buf = categorical_column_to_series(col)
        elif dtype == DtypeKind.STRING:
            columns[name], buf = string_column_to_ndarray(col)
        elif dtype == DtypeKind.DATETIME:
            columns[name], buf = datetime_column_to_ndarray(col)
        else:
            raise NotImplementedError(f"Data type {dtype} not handled yet")

        buffers.append(buf)

    pandas_df = pd.DataFrame(columns)
    pandas_df.attrs["_INTERCHANGE_PROTOCOL_BUFFERS"] = buffers
    return pandas_df

def validate_fwd_input_output(
    name: str, func: Callable[[Any, Any, bool], Any], X: Any, Y: Any
) -> None:
    schema = Schema.from_function(func)
    fields = list(schema.model_fields)
    if len(fields) != 3:
        bad_params = f"{len(fields)} ({', '.join(fields)})"
        err = f"Invalid forward function. Expected 3 arguments (model, X, is_train), got {bad_params}"
        raise DataValidationError(name, X, Y, [{"msg": err}])
    x_field = schema.model_fields[fields[1]]
    y_field = schema.model_fields[fields[2]]  # noqa: F841
    errors = []
    if X is not None and x_field.annotation is not Any:
        if isinstance(X, list) and len(X) > 5:
            X = X[:5]
        err = validate_type(X, x_field.annotation)
        if err:
            errors.append({"loc": ("X",), "msg": err})
    if Y is not None:
        ret = inspect.signature(func).return_annotation
        if ret is not inspect.Signature.empty:
            err = validate_type((Y, lambda x: x), ret)
            if err:
                errors.append({"loc": ("Y",), "msg": err})
    if errors:
        raise DataValidationError(name, X, Y, errors)

def find(
        self,
        path: str,
        maxdepth: int | None = None,
        withdirs: bool = False,
        detail: bool = False,
        refresh: bool = False,
        revision: str | None = None,
        **kwargs,
    ) -> list[str] | dict[str, dict[str, Any]]:
        if maxdepth is not None and maxdepth < 1:
            raise ValueError("maxdepth must be at least 1")
        resolved_path = self.resolve_path(path, revision=revision)
        path = resolved_path.unresolve()
        try:
            out = self._ls_tree(path, recursive=True, refresh=refresh, maxdepth=maxdepth, **kwargs)
        except EntryNotFoundError:
            # Path could be a file
            try:
                if self.info(path, revision=revision, **kwargs)["type"] == "file":
                    out = {path: {}}
                else:
                    out = {}
            except FileNotFoundError:
                out = {}
        else:
            if not withdirs:
                out = [o for o in out if o["type"] != "directory"]
            else:
                # If `withdirs=True`, include the directory itself to be consistent with the spec
                path_info = self.info(path, **kwargs)
                out = [path_info] + out if path_info["type"] == "directory" else out
            out = {o["name"]: o for o in out}
        names = sorted(out)
        if not detail:
            return names
        else:
            return {name: out[name] for name in names}

def format_array(array: np.ndarray) -> str:
    try:
        import numpy as np  # pylint:disable=import-outside-toplevel
    except ImportError:
        return repr(array)

    if array.dtype == "object":
        retval = "np.array("
        for sub in array:
            retval += f"{format_array(sub)}, "
        if array.size:
            retval = retval[:-2]
        return f"{retval}, dtype='{array.dtype}')"

    if np.prod(array.shape) <= 10:
        return f"np.array({str(array.tolist())}, dtype='{array.dtype}')"
    return f"<array(shape{array.shape}, '{array.dtype}')>"

def fail_stale_trials(study: "optuna.Study") -> None:
    storage = study._storage

    if not isinstance(storage, BaseHeartbeat):
        return

    if not is_heartbeat_enabled(storage):
        return

    failed_trial_ids = []
    for trial_id in storage._get_stale_trial_ids(study._study_id):
        try:
            if storage.set_trial_state_values(trial_id, state=TrialState.FAIL):
                failed_trial_ids.append(trial_id)
        except optuna.exceptions.UpdateFinishedTrialError:
            # If another process fails the trial, the storage raises
            # optuna.exceptions.UpdateFinishedTrialError.
            pass

    failed_trial_callback = storage.get_failed_trial_callback()
    if failed_trial_callback is not None:
        for trial_id in failed_trial_ids:
            failed_trial = copy.deepcopy(storage.get_trial(trial_id))
            failed_trial_callback(study, failed_trial)

