def from_keras(cls, model):
        graph = cls()
        # Shamelessly copied (then modified) from keras/keras/utils/layer_utils.py
        sequential_like = cls._is_sequential(model)

        relevant_nodes = None
        if not sequential_like:
            relevant_nodes = []
            for v in model._nodes_by_depth.values():
                relevant_nodes += v

        layers = model.layers
        for i in range(len(layers)):
            node = Node.from_keras(layers[i])
            if hasattr(layers[i], "_inbound_nodes"):
                for in_node in layers[i]._inbound_nodes:
                    if relevant_nodes and in_node not in relevant_nodes:
                        # node is not part of the current network
                        continue
                    for in_layer in _nest(in_node.inbound_layers):
                        inbound_keras_node = Node.from_keras(in_layer)

                        if inbound_keras_node.id not in graph.nodes_by_id:
                            graph.add_node(inbound_keras_node)
                        inbound_node = graph.nodes_by_id[inbound_keras_node.id]

                        graph.add_edge(inbound_node, node)
            graph.add_node(node)
        return graph

def process_split_ratio(ratio):
    if isinstance(ratio, float):
        if ratio <= 0 or ratio >= 1:
            raise ValueError("Split ratio has to be between 0 and 1")

        multi = False
    elif isinstance(ratio, list):
        if any([x <= 0 for x in ratio]):
            raise ValueError(
                "All split ratios in the ratio list should be larger than 0."
            )

        # normalize split ratios if they are not summed to 1
        if math.fsum(ratio) != 1.0:
            ratio = [x / math.fsum(ratio) for x in ratio]

        multi = True
    else:
        raise TypeError("Split ratio should be either float or a list of floats.")

    return multi, ratio

def fit(self, X, y=None):
        # Convert python objects to numpy arrays
        if isinstance(X, (list, tuple)):
            X = np.array(X)

        if y is not None and isinstance(y, (list, tuple)):
            y = np.array(y)

        # Case where no columns are specified
        if self.columns is None:
            if (y is None and (X.ndim != 2 or X.shape[1] != 2)) or (
                y is not None and (X.ndim != 1 or y.ndim != 1)
            ):
                raise YellowbrickValueError(
                    (
                        "when self.columns is None specify either X and y as 1D arrays "
                        "or X as a matrix with 2 columns"
                    )
                )

            if y is None:
                # Draw the first column as x and the second column as y
                self.draw(X[:, 0], X[:, 1], xlabel="0", ylabel="1")
                return self

            # Draw x against y
            self.draw(X, y, xlabel="x", ylabel="y")
            return self

        # Case where a single string or int index is specified
        if isinstance(self.columns, (int, str)):
            if y is None:
                raise YellowbrickValueError(
                    "when self.columns is a single index, y must be specified"
                )

            # fetch the index from X -- raising index error if not possible
            x = self._index_into(self.columns, X)
            self.draw(x, y, xlabel=str(self.columns), ylabel="target")
            return self

        # Case where there is a double index for both columns
        columns = tuple(self.columns)
        if len(columns) != 2:
            raise YellowbrickValueError(
                ("'{}' contains too many indices or is invalid for joint plot").format(
                    columns
                )
            )

        # TODO: color the points based on the target if it is given
        x = self._index_into(columns[0], X)
        y = self._index_into(columns[1], X)
        self.draw(x, y, xlabel=str(columns[0]), ylabel=str(columns[1]))
        return self

def maybe_convert_indices(indices, n: int, verify: bool = True) -> np.ndarray:
    if isinstance(indices, list):
        indices = np.array(indices)
        if len(indices) == 0:
            # If `indices` is empty, np.array will return a float,
            # and will cause indexing errors.
            return np.empty(0, dtype=np.intp)

    mask = indices < 0
    if mask.any():
        indices = indices.copy()
        indices[mask] += n

    if verify:
        mask = (indices >= n) | (indices < 0)
        if mask.any():
            raise IndexError("indices are out-of-bounds")
    return indices

def normalize(
    image: np.ndarray,
    mean: float | Collection[float],
    std: float | Collection[float],
    data_format: ChannelDimension | None = None,
    input_data_format: str | ChannelDimension | None = None,
) -> np.ndarray:
    if not isinstance(image, np.ndarray):
        raise TypeError("image must be a numpy array")

    if input_data_format is None:
        input_data_format = infer_channel_dimension_format(image)

    channel_axis = get_channel_dimension_axis(image, input_data_format=input_data_format)
    num_channels = image.shape[channel_axis]

    # We cast to float32 to avoid errors that can occur when subtracting uint8 values.
    # We preserve the original dtype if it is a float type to prevent upcasting float16.
    if not np.issubdtype(image.dtype, np.floating):
        image = image.astype(np.float32)

    if isinstance(mean, Collection):
        if len(mean) != num_channels:
            raise ValueError(f"mean must have {num_channels} elements if it is an iterable, got {len(mean)}")
    else:
        mean = [mean] * num_channels
    mean = np.array(mean, dtype=image.dtype)

    if isinstance(std, Collection):
        if len(std) != num_channels:
            raise ValueError(f"std must have {num_channels} elements if it is an iterable, got {len(std)}")
    else:
        std = [std] * num_channels
    std = np.array(std, dtype=image.dtype)

    if input_data_format == ChannelDimension.LAST:
        image = (image - mean) / std
    else:
        image = ((image.T - mean) / std).T

    image = to_channel_dimension_format(image, data_format, input_data_format) if data_format is not None else image
    return image

def update_version_in_examples(version: str, patch: bool = False):
    for folder, directories, fnames in os.walk(PATH_TO_EXAMPLES):
        # Removing some of the folders with non-actively maintained examples from the walk
        if "legacy" in directories:
            directories.remove("legacy")
        for fname in fnames:
            if fname.endswith(".py"):
                if UV_SCRIPT_MARKER in Path(folder, fname).read_text():
                    # Update the dependencies in UV scripts
                    uv_script_file_type = "uv_script_dev" if ".dev" in version else "uv_script_release"
                    update_version_in_file(os.path.join(folder, fname), version, file_type=uv_script_file_type)
                if not patch:
                    # We don't update the version in the examples for patch releases.
                    update_version_in_file(os.path.join(folder, fname), version, file_type="examples")

def forward(self, x):
        x2, x3, x4, x5 = None, None, None, None
        for stage in range(17): # https://github.com/PaddlePaddle/PaddleOCR/blob/release/2.1/ppocr/modeling/backbones/det_mobilenet_v3.py
            x = self.features[stage](x)
            if stage == 3:  # if s == 2 and start_idx > 3
                x2 = x
            elif stage == 6:
                x3 = x
            elif stage == 12:
                x4 = x
            elif stage == 16:
                x5 = x
        return x2, x3, x4, x5

def load_lora_weights(
        self,
        pretrained_model_name_or_path_or_dict: Union[str, Dict[str, torch.Tensor]],
        adapter_name=None,
        **kwargs,
    ):
        if not USE_PEFT_BACKEND:
            raise ValueError("PEFT backend is required for this method.")

        state_dict = self.lora_state_dict(pretrained_model_name_or_path_or_dict, **kwargs)

        # Separate transformer and controlnet weights
        transformer_state_dict = {}
        controlnet_state_dict = {}

        for key, value in state_dict.items():
            if key.startswith("controlnet."):
                # Remove the "controlnet." prefix for loading into controlnet
                new_key = key[len("controlnet.") :]
                controlnet_state_dict[new_key] = value
            elif key.startswith("transformer."):
                # Remove the "transformer." prefix
                new_key = key[len("transformer.") :]
                transformer_state_dict[new_key] = value
            else:
                # Handle unprefixed keys based on content
                if "controlnet" in key:
                    controlnet_state_dict[key] = value
                else:
                    transformer_state_dict[key] = value

        # Load into transformer if there are transformer weights
        _transformer = self.transformer if not hasattr(self.transformer, "transformer") else self.transformer.transformer
        if transformer_state_dict:
            self.load_lora_into_transformer(
                transformer_state_dict,
                transformer=_transformer,  # Access the base transformer
                adapter_name=adapter_name,
                _pipeline=self,
            )

        # Load into controlnet if there are controlnet weights
        if controlnet_state_dict:
            self.load_lora_into_controlnet(
                controlnet_state_dict,
                controlnet=self.transformer.controlnet,  # Access the controlnet through wrapper
                adapter_name=adapter_name,
                _pipeline=self,
            )

def nested_map(f, obj, level=0, ignore_nones=True):
  if _is_at_level(obj, level):
    if ignore_nones and _is_made_of_nones(obj):
      return None
    else:
      return f(obj)

  if _is_namedtuple_instance(obj):
    return type(obj)(*nested_map(f, list(obj), level=level))
  if isinstance(obj, list):
    return [nested_map(f, y, level=level) for y in obj]
  if isinstance(obj, tuple):
    return tuple([nested_map(f, y, level=level) for y in obj])
  if isinstance(obj, dict):
    return {k: nested_map(f, v, level=level) for (k, v) in obj.items()}

  raise ValueError('Non-exhaustive pattern match for {}.'.format(obj))

def validate_repo_id(repo_id: str | None) -> None:
    if repo_id is None:
        # Repo id is not always required
        return

    if not isinstance(repo_id, str):
        # Typically, a Path is not a repo_id
        raise HFValidationError(f"Repo id must be a string, not {type(repo_id)}: '{repo_id}'.")

    if repo_id.count("/") > 1:
        raise HFValidationError(
            "Repo id must be in the form 'repo_name' or 'namespace/repo_name':"
            f" '{repo_id}'. Use `repo_type` argument if needed."
        )

    if not REPO_ID_REGEX.match(repo_id):
        raise HFValidationError(
            "Repo id must use alphanumeric chars, '-', '_' or '.'."
            " The name cannot start or end with '-' or '.' and the maximum length is 96:"
            f" '{repo_id}'."
        )

    if "--" in repo_id or ".." in repo_id:
        raise HFValidationError(f"Cannot have -- or .. in repo_id: '{repo_id}'.")

    if repo_id.endswith(".git"):
        raise HFValidationError(f"Repo_id cannot end by '.git': '{repo_id}'.")

def init_shards(self, output_prefix, corpus, shardsize=4096, dtype=_default_dtype):
        is_corpus, corpus = gensim.utils.is_corpus(corpus)
        if not is_corpus:
            raise ValueError("Cannot initialize shards without a corpus to read from! Corpus type: %s" % type(corpus))

        proposed_dim = self._guess_n_features(corpus)
        if proposed_dim != self.dim:
            if self.dim is None:
                logger.info('Deriving dataset dimension from corpus: %d', proposed_dim)
            else:
                logger.warning(
                    "Dataset dimension derived from input corpus differs from initialization argument, "
                    "using corpus. (corpus %d, init arg %d)", proposed_dim, self.dim
                )

        self.dim = proposed_dim
        self.offsets = [0]

        start_time = time.perf_counter()

        logger.info('Running init from corpus.')

        for n, doc_chunk in enumerate(gensim.utils.grouper(corpus, chunksize=shardsize)):
            logger.info('Chunk no. %d at %f s', n, time.perf_counter() - start_time)

            current_shard = numpy.zeros((len(doc_chunk), self.dim), dtype=dtype)
            logger.debug('Current chunk dimension: %d x %d', len(doc_chunk), self.dim)

            for i, doc in enumerate(doc_chunk):
                doc = dict(doc)
                current_shard[i][list(doc)] = list(doc.values())

            # Handles the updating as well.
            if self.sparse_serialization:
                current_shard = sparse.csr_matrix(current_shard)

            self.save_shard(current_shard)

        end_time = time.perf_counter()
        logger.info('Built %d shards in %f s.', self.n_shards, end_time - start_time)

def save_images(save_dir, validation_images, validation_shortname, validation_resolutions, config):
    validation_img_idx = 0
    resolutions = [_res for res in validation_resolutions for _res in [res] * config.num_eval_images]

    for validation_image in validation_images.get(validation_shortname, []):
        if validation_img_idx >= len(resolutions):
            # Fallback if we have more images than resolutions
            if hasattr(validation_image, "size"):
                res_label = f"{validation_image.size[0]}x{validation_image.size[1]}"
            else:
                res_label = "unknown"
        else:
            res = resolutions[validation_img_idx]
            if isinstance(res, str) and "x" in res:
                res_label = str(res)
            elif isinstance(res, tuple):
                res_label = f"{res[0]}x{res[1]}"
            else:
                res_label = f"{res}x{res}"

        filename = f"step_{StateTracker.get_global_step()}_{validation_shortname}_{validation_img_idx}_{res_label}.png"
        save_path = os.path.join(save_dir, filename)

        try:
            validation_image.save(save_path)
        except Exception as e:
            logger.error(f"Failed to save validation image to {save_path}: {e}")

        validation_img_idx += 1

def Value(
    body=None,
    normalizer=None,
    inject_actions=False,
    inject_actions_n_layers=1,
    inject_actions_dim=64,
    batch_axes=None,
    mode='train',
    is_discrete=False,
    vocab_size=2,
    multiplicative_action_injection=False,
    head_init_range=None,
):
  if body is None:
    body = lambda mode: []
  if normalizer is None:
    normalizer = lambda mode: []

  def ActionInjector(mode):
    if inject_actions:
      if is_discrete:
        action_encoder = tl.Embedding(vocab_size, inject_actions_dim)
      else:
        action_encoder = tl.Dense(inject_actions_dim)
      encoders = tl.Parallel(
          tl.Dense(inject_actions_dim),
          action_encoder,
      )
      if multiplicative_action_injection:
        action_injector = tl.Serial(
            tl.Fn('TanhMulGate', lambda x, a: x * jnp.tanh(a)),
            tl.LayerNorm()  # compensate for reduced variance
        )
      else:
        action_injector = tl.Add()
      return tl.Serial(
          # Input: (body output, actions).
          encoders,
          action_injector,
          models.MLP(
              layer_widths=(inject_actions_dim,) * inject_actions_n_layers,
              out_activation=True,
              flatten=False,
              mode=mode,
          )
      )
    else:
      return []

  head_kwargs = {}
  if head_init_range is not None:
    head_kwargs['kernel_initializer'] = tl.RandomUniformInitializer(
        lim=head_init_range
    )

  return tl.Serial(
      _Batch(normalizer(mode=mode), batch_axes),
      _Batch(body(mode=mode), batch_axes),
      ActionInjector(mode=mode),
      tl.Dense(1, **head_kwargs),
  )

def validate_tag(tag):
    if isinstance(tag, bytes_type):
        if not is_utf8_decodable(tag):
            raise MetaflowTaggingError("Tags must be UTF-8 decodable")
    elif isinstance(tag, unicode_type):
        if not is_utf8_encodable(tag):
            raise MetaflowTaggingError("Tags must be UTF-8 encodable")
    else:
        raise MetaflowTaggingError(
            "Tags must be some kind of string (bytes or unicode), got %s",
            str(type(tag)),
        )
    if not len(tag):
        raise MetaflowTaggingError("Tags must not be empty string")
    if len(tag) > MAX_TAG_SIZE:
        raise MetaflowTaggingError("Tag is too long %d > %d" % (len(tag), MAX_TAG_SIZE))

def get_default_pipeline(target: tvm.target.Target):
    if target.kind.name == "cuda":
        return backend.cuda.get_default_pipeline(target)
    if target.kind.name == "rocm":
        return backend.rocm.get_default_pipeline(target)
    if target.kind.name == "metal":
        return backend.gpu_generic.get_default_pipeline(target)
    if target.kind.name == "llvm":
        return backend.cpu_generic.get_default_pipeline(target)
    if target.kind.name == "opencl" and "adreno" in target.keys:
        return backend.adreno.get_default_pipeline(target)
    if BackendDispatcher.is_gpu_target(target):
        return backend.gpu_generic.get_default_pipeline(target)
    raise ValueError(
        f"Target {target} is not yet supported by default pipeline. "
        "Please lower and build the IRModule manually."
    )

def clear_deepspeed_offload_cache(self, config_name: Optional[str] = None) -> Dict[str, Any]:
        store = get_config_store()
        active_config = config_name or store.get_active_config()
        if not active_config:
            raise MaintenanceServiceError("No active training configuration is selected.")

        try:
            config_data, _ = store.load_config(active_config)
        except (FileNotFoundError, ValueError) as exc:  # pragma: no cover - defensive
            raise MaintenanceServiceError(f"Unable to load configuration '{active_config}': {exc}") from exc

        offload_path = self._extract_offload_path(config_data)
        if not offload_path:
            raise MaintenanceServiceError("The active configuration does not define --offload_param_path. Nothing to clear.")

        resolved_root = Path(os.path.expanduser(str(offload_path))).resolve()
        if not resolved_root.exists() or not resolved_root.is_dir():
            raise MaintenanceServiceError(f"Offload path '{resolved_root}' does not exist or is not a directory.")

        removed: List[str] = []
        for entry in resolved_root.iterdir():
            if not entry.is_dir():
                continue
            if not entry.name.startswith("zero_stage_"):
                continue
            try:
                shutil.rmtree(entry, ignore_errors=True)
                removed.append(str(entry))
            except Exception as exc:  # pragma: no cover - defensive
                logger.debug("Unable to remove DeepSpeed offload directory %s: %s", entry, exc, exc_info=True)

        return {
            "cleared": True,
            "root": str(resolved_root),
            "removed": removed,
        }

def fuse_qkv_projections(self):
        if not self.config.fuse_qkv_projections or self._qkv_projections_fused:
            return

        try:
            # Try to use fused attention if available
            from diffusers.models.attention_processor import FusedAttnProcessor2_0

            attn_processor = FusedAttnProcessor2_0()
        except:
            logger.debug("Fused attention not available for Lumina2, using default")
            return

        if self.model is not None:
            logger.debug("Fusing QKV projections in the model..")
            for module in self.model.modules():
                if isinstance(module, Attention):
                    module.fuse_projections(fuse=True)
        else:
            logger.warning("Model does not support QKV projection fusing. Skipping.")

        self.unwrap_model(model=self.model).set_attn_processor(attn_processor)
        self._qkv_projections_fused = True

def set_concurrency(self, worker_index=None, num_workers=None):
            if self._started and getattr(self, "_fetch_thread", None) and self._fetch_thread.is_alive():
                raise ValueError("set_concurrency must be called before the iterator starts")

            resolved_workers = None
            if num_workers is not None:
                try:
                    resolved_workers = int(num_workers)
                except Exception as exc:
                    raise ValueError("num_workers must be an integer") from exc
            else:
                try:
                    detected = get_node_count()
                except Exception:
                    detected = None
                if isinstance(detected, int) and detected > 1:
                    resolved_workers = detected

            if resolved_workers is None or resolved_workers <= 1:
                self._num_workers = None
                self._worker_index = None
                self._adjust_limit_for_concurrency()
                return

            if worker_index is None:
                candidate = self._node_id
                if candidate is None:
                    try:
                        candidate = get_node_id()
                    except Exception:
                        candidate = 0
                worker_index = candidate

            try:
                resolved_index = int(worker_index)
            except Exception as exc:
                raise ValueError("worker_index must be an integer") from exc

            if resolved_index < 0:
                raise ValueError("worker_index must be non-negative")

            resolved_index = resolved_index % resolved_workers

            self._num_workers = resolved_workers
            self._worker_index = resolved_index
            self._adjust_limit_for_concurrency()

def encode_nested_example(schema, obj, level=0):
    # Nested structures: we allow dict, list/tuples, sequences
    if isinstance(schema, dict):
        if level == 0 and obj is None:
            raise ValueError("Got None but expected a dictionary instead")
        return (
            {k: encode_nested_example(schema[k], obj.get(k), level=level + 1) for k in schema}
            if obj is not None
            else None
        )
    elif isinstance(schema, (LargeList, List)):
        if obj is None:
            return None
        else:
            if len(obj) > 0:
                sub_schema = schema.feature
                for first_elmt in obj:
                    if _check_non_null_non_empty_recursive(first_elmt, sub_schema):
                        break
                try:
                    changed = bool(encode_nested_example(sub_schema, first_elmt, level=level + 1) != first_elmt)
                except ValueError:  # can happen when comparing arrays
                    changed = False
                if changed:
                    return [encode_nested_example(sub_schema, o, level=level + 1) for o in obj]
            return list(obj)
    # Object with special encoding:
    # ClassLabel will convert from string to int, TranslationVariableLanguages does some checks
    elif hasattr(schema, "encode_example"):
        return schema.encode_example(obj) if obj is not None else None
    # Other object should be directly convertible to a native Arrow type (like Translation and Translation)
    return obj

def autocast_if_enabled(engine):
    global _WARNED_NESTED_AUTOCAST

    if torch.is_autocast_enabled():
        if engine.torch_autocast_enabled():
            if not _WARNED_NESTED_AUTOCAST:
                if dist.get_rank() == 0:
                    logger.info(
                        "torch.autocast is already enabled outside DeepSpeed. "
                        "Switching to the configuration defined in `torch_autocast` section of DeepSpeed config.")
                _WARNED_NESTED_AUTOCAST = True
            with torch.autocast(device_type=get_accelerator().device_name(),
                                dtype=engine.torch_autocast_dtype(),
                                enabled=True):
                yield
        else:
            if not _WARNED_NESTED_AUTOCAST:
                if dist.get_rank() == 0:
                    logger.warning(
                        "torch.autocast is enabled outside DeepSpeed but disabled within the DeepSpeed engine. "
                        "If you are using DeepSpeed's built-in mixed precision, the engine will follow the settings in bf16/fp16 section. "
                        "To use torch's native autocast instead, configure the `torch_autocast` section in the DeepSpeed config."
                    )
                _WARNED_NESTED_AUTOCAST = True
            with torch.autocast(device_type=get_accelerator().device_name(), enabled=False):
                yield
    else:
        if engine.torch_autocast_enabled():
            with torch.autocast(device_type=get_accelerator().device_name(),
                                dtype=engine.torch_autocast_dtype(),
                                enabled=True):
                yield
        else:
            yield

def add(
        self,
        embeddings: List[List[float]],
        routes: List[str],
        utterances: List[str],
        function_schemas: Optional[List[Dict[str, Any]]] = None,
        metadata_list: List[Dict[str, Any]] = [],
        **kwargs,
    ) -> None:
        table_name = self._get_table_name()
        new_embeddings_length = len(embeddings[0])
        if new_embeddings_length != self.dimensions:
            raise ValueError(
                f"The vector embeddings being added are of length {new_embeddings_length}, which does not match the expected dimensions of {self.dimensions}."
            )
        records = [
            PostgresIndexRecord(vector=vector, route=route, utterance=utterance)
            for vector, route, utterance in zip(embeddings, routes, utterances)
        ]
        if not isinstance(self.conn, psycopg.Connection):
            raise TypeError("Index has not established a connection to Postgres")
        try:
            with self.conn.cursor() as cur:
                cur.executemany(
                    f"INSERT INTO {table_name} (id, route, utterance, vector) VALUES (%s, %s, %s, %s) ON CONFLICT (id) DO NOTHING",
                    [
                        (record.id, record.route, record.utterance, record.vector)
                        for record in records
                    ],
                )
                self.conn.commit()
        except Exception:
            if self.conn is not None:
                self.conn.rollback()
            raise

def ops_to_not_decompose(
        self, ep: ExportedProgram
    ) -> tuple[list[torch._ops.OpOverload], Callable[[torch.fx.Node], bool] | None]:
        from executorch.backends.mlx.builder.program_builder import MLXProgramBuilder

        # Check if the graph already contains lowered modules (post-partitioning pass)
        # In this case, we should return empty since partitioning is already done
        for node in ep.graph.nodes:
            if node.op == "get_attr" and "lowered_module" in node.name:
                logger.debug(
                    "MLX ops_to_not_decompose: Graph already partitioned, returning empty"
                )
                return ([], None)

        # Run the builder to determine which nodes are supported
        builder = MLXProgramBuilder(ep)
        builder.check_support_only()

        # Collect ops for nodes that are actually supported
        do_not_decompose: list[torch._ops.OpOverload] = []

        for node in ep.graph.nodes:
            if node.op == "call_function" and isinstance(
                node.target, torch._ops.OpOverload
            ):
                info = builder.node_info.get(node)
                if info is not None and info.supported:
                    if node.target not in do_not_decompose:
                        do_not_decompose.append(node.target)

        logger.debug(
            f"MLX ops_to_not_decompose: {[str(op) for op in do_not_decompose]}"
        )
        return (do_not_decompose, None)

def process(self, im0) -> SolutionResults:
        self.extract_tracks(im0)  # Extract tracks
        annotator = SolutionAnnotator(im0, line_width=self.line_width)  # Initialize annotator

        pixels_distance = 0
        # Iterate over bounding boxes, track ids and classes index
        for box, track_id, cls, conf in zip(self.boxes, self.track_ids, self.clss, self.confs):
            annotator.box_label(box, color=colors(int(cls), True), label=self.adjust_box_label(cls, conf, track_id))

            # Update selected boxes if they're being tracked
            if len(self.selected_boxes) == 2:
                for trk_id in self.selected_boxes.keys():
                    if trk_id == track_id:
                        self.selected_boxes[track_id] = box

        if len(self.selected_boxes) == 2:
            # Calculate centroids of selected boxes
            self.centroids.extend(
                [[int((box[0] + box[2]) // 2), int((box[1] + box[3]) // 2)] for box in self.selected_boxes.values()]
            )
            # Calculate Euclidean distance between centroids
            pixels_distance = math.sqrt(
                (self.centroids[0][0] - self.centroids[1][0]) ** 2 + (self.centroids[0][1] - self.centroids[1][1]) ** 2
            )
            annotator.plot_distance_and_line(pixels_distance, self.centroids)

        self.centroids = []  # Reset centroids for next frame
        plot_im = annotator.result()
        self.display_output(plot_im)  # Display output with base class function
        if self.CFG.get("show") and self.env_check:
            cv2.setMouseCallback("Ultralytics Solutions", self.mouse_event_for_distance)

        # Return SolutionResults with processed image and calculated metrics
        return SolutionResults(plot_im=plot_im, pixels_distance=pixels_distance, total_tracks=len(self.track_ids))

def thread_binding(
    start: PrimExpr,
    stop: PrimExpr = None,
    thread: str | None = None,
    *,
    annotations: dict[str, Any] | None = None,
) -> frame.ForFrame:
    if thread is None:
        if not isinstance(stop, str):
            raise ValueError("Thread cannot be None for thread_binding")
        thread = stop
        stop = start
        if hasattr(start, "dtype"):
            start = IntImm(start.dtype, 0)
        else:
            start = 0
    elif stop is None:
        stop = start
        if hasattr(start, "dtype"):
            start = IntImm(start.dtype, 0)
        else:
            start = 0
    return _ffi_api.ThreadBinding(  # type: ignore[attr-defined] # pylint: disable=no-member
        start, stop, thread, annotations
    )

def split_code_in_indented_blocks(
    code: str, indent_level: str = "", start_prompt: str | None = None, end_prompt: str | None = None
) -> list[str]:
    # Let's split the code into lines and move to start_index.
    index = 0
    lines = code.split("\n")
    if start_prompt is not None:
        while not lines[index].startswith(start_prompt):
            index += 1
        blocks = ["\n".join(lines[:index])]
    else:
        blocks = []

    # This variable contains the block treated at a given time.
    current_block = [lines[index]]
    index += 1
    # We split into blocks until we get to the `end_prompt` (or the end of the file).
    while index < len(lines) and (end_prompt is None or not lines[index].startswith(end_prompt)):
        # We have a non-empty line with the proper indent -> start of a new block
        if len(lines[index]) > 0 and get_indent(lines[index]) == indent_level:
            # Store the current block in the result and rest. There are two cases: the line is part of the block (like
            # a closing parenthesis) or not.
            if len(current_block) > 0 and get_indent(current_block[-1]).startswith(indent_level + " "):
                # Line is part of the current block
                current_block.append(lines[index])
                blocks.append("\n".join(current_block))
                if index < len(lines) - 1:
                    current_block = [lines[index + 1]]
                    index += 1
                else:
                    current_block = []
            else:
                # Line is not part of the current block
                blocks.append("\n".join(current_block))
                current_block = [lines[index]]
        else:
            # Just add the line to the current block
            current_block.append(lines[index])
        index += 1

    # Adds current block if it's nonempty.
    if len(current_block) > 0:
        blocks.append("\n".join(current_block))

    # Add final block after end_prompt if provided.
    if end_prompt is not None and index < len(lines):
        blocks.append("\n".join(lines[index:]))

    return blocks

def define_aliases(alias_d, cls=None):
    if cls is None:  # Return the actual class decorator.
        return functools.partial(define_aliases, alias_d)

    def make_alias(name):  # Enforce a closure over *name*.
        @functools.wraps(getattr(cls, name))
        def method(self, *args, **kwargs):
            return getattr(self, name)(*args, **kwargs)
        return method

    for prop, aliases in alias_d.items():
        exists = False
        for prefix in ["get_", "set_"]:
            if prefix + prop in vars(cls):
                exists = True
                for alias in aliases:
                    method = make_alias(prefix + prop)
                    method.__name__ = prefix + alias
                    method.__doc__ = f"Alias for `{prefix + prop}`."
                    setattr(cls, prefix + alias, method)
        if not exists:
            raise ValueError(
                f"Neither getter nor setter exists for {prop!r}")

    alias_to_prop = {
        alias: prop for prop, aliases in alias_d.items() for alias in aliases}

    def get_aliased_and_aliases(d):
        return {*d.keys(), *d.values()}

    preexisting_aliases = getattr(cls, "_alias_to_prop", {})
    conflicting = (get_aliased_and_aliases(preexisting_aliases)
                   & get_aliased_and_aliases(alias_to_prop))
    if conflicting:
        # Need to decide on conflict resolution policy.
        raise NotImplementedError(
            f"Parent class already defines conflicting aliases: {conflicting}")
    cls._alias_to_prop = {**preexisting_aliases, **alias_to_prop}
    return cls

def get_clique_tree(nodes: Iterable[int], edges: List[Tuple[int, int]]) -> nx.Graph:
    # Form the original graph G1
    G1 = nx.Graph()
    G1.add_nodes_from(nodes)
    G1.add_edges_from(edges)

    # Check if graph is chordal
    # TODO: Add step to triangulate graph if not
    if not nx.is_chordal(G1):
        raise NotImplementedError("Graph triangulation not implemented.")

    # Create maximal clique graph G2
    # Each node is a maximal clique C_i
    # Let w = |C_i \cap C_j|; C_i, C_j have an edge with weight w if w > 0
    G2 = nx.Graph()
    for i, c in enumerate(nx.chordal_graph_cliques(G1)):
        G2.add_node(i, members=c)
    for i in G2.nodes:
        for j in G2.nodes:
            S = G2.nodes[i]["members"].intersection(G2.nodes[j]["members"])
            w = len(S)
            if w > 0:
                G2.add_edge(i, j, weight=w, members=S)

    # Return a minimum spanning tree of G2
    return nx.minimum_spanning_tree(G2)

def train_step(self, model, inputs):
        model = model.module if self._dist or is_parallel(model) else model
        model.train()
        loss, sample_size, logging_output = self.criterion(model, inputs)
        train_outputs = {'loss': loss}
        # add model output info to log
        if 'log_vars' not in train_outputs:
            default_keys_pattern = ['loss']
            match_keys = set([])
            for key_p in default_keys_pattern:
                match_keys.update(
                    [key for key in train_outputs.keys() if key_p in key])
            log_vars = {}
            for key in match_keys:
                value = train_outputs.get(key, None)
                if value is not None:
                    if dist.is_available() and dist.is_initialized():
                        value = value.data.clone()
                        dist.all_reduce(value.div_(dist.get_world_size()))
                    log_vars.update({key: value.item()})
            self.log_buffer.update(log_vars)
        else:
            self.log_buffer.update(train_outputs['log_vars'])
        self.train_outputs = train_outputs

def get_resumption_state_dict(state: State) -> dict[str, Any]:
    resumption_state_dict = {}
    resumption_state_dict['dataset_state'] = get_dataset_state_dict(
        state.train_dataloader,
        state.timestamp,
    )
    resumption_state_dict['timestamp'] = state.timestamp.state_dict()

    scheduler_state_dict = _make_state_dict_for_list_of_objects(state.schedulers)
    if scheduler_state_dict != {}:
        resumption_state_dict['schedulers'] = scheduler_state_dict

    # Use list of tuples to account for duplicates
    callbacks_state_dict = _make_state_dict_for_list_of_objects(state.callbacks, use_list_of_tuples=True)
    if callbacks_state_dict != {}:
        resumption_state_dict['callbacks'] = callbacks_state_dict

    # Use list of tuples to preserve order.
    algorithms_state_dict = _make_state_dict_for_list_of_objects(state.algorithms, use_list_of_tuples=True)
    if algorithms_state_dict != {}:
        resumption_state_dict['algorithms'] = algorithms_state_dict

    if state.scaler is not None:
        scaler_sd = _make_state_dict_for_list_of_objects(state.scaler)
        if scaler_sd != {}:
            resumption_state_dict['scaler'] = scaler_sd

    resumption_state_dict['rank_zero_seed'] = state.rank_zero_seed
    resumption_state_dict['run_name'] = state.run_name
    resumption_state_dict['rng'] = reproducibility.get_rng_state()

    return resumption_state_dict

def only_nodes_with_namespaces(self, node_namespaces: list[str]) -> Pipeline:
        nodes = []
        unmatched_namespaces = []  # Track namespaces that don't match any nodes

        for node_namespace in node_namespaces:
            matching_nodes = []
            for n in self._nodes:
                if n.namespace and (
                    n.namespace == node_namespace
                    or n.namespace.startswith(f"{node_namespace}.")
                ):
                    matching_nodes.append(n)

            if not matching_nodes:
                unmatched_namespaces.append(node_namespace)
            nodes.extend(matching_nodes)

        if unmatched_namespaces:
            raise ValueError(
                f"Pipeline does not contain nodes with the following namespaces: {unmatched_namespaces}"
            )

        return Pipeline(nodes)

def serialize(serializer, fname, corpus, id2word=None, index_fname=None,
                  progress_cnt=None, labels=None, metadata=False):
        if getattr(corpus, 'fname', None) == fname:
            raise ValueError("identical input vs. output corpus filename, refusing to serialize: %s" % fname)

        if index_fname is None:
            index_fname = utils.smart_extension(fname, '.index')

        kwargs = {'metadata': metadata}
        if progress_cnt is not None:
            kwargs['progress_cnt'] = progress_cnt

        if labels is not None:
            kwargs['labels'] = labels

        offsets = serializer.save_corpus(fname, corpus, id2word, **kwargs)

        if offsets is None:
            raise NotImplementedError(
                "Called serialize on class %s which doesn't support indexing!" % serializer.__name__
            )

        # store offsets persistently, using pickle
        # we shouldn't have to worry about self.index being a numpy.ndarray as the serializer will return
        # the offsets that are actually stored on disk - we're not storing self.index in any case, the
        # load just needs to turn whatever is loaded from disk back into a ndarray - this should also ensure
        # backwards compatibility
        logger.info("saving %s index to %s", serializer.__name__, index_fname)
        utils.pickle(offsets, index_fname)

def from_tensor(cls, boxes: torch.Tensor, mode: str = "xyzxyz", validate_boxes: bool = True) -> Boxes3D:
        if not (2 <= boxes.ndim <= 3 and boxes.shape[-1] == 6):
            raise ValueError(f"BBox shape must be (N, 6) or (B, N, 6). Got {boxes.shape}.")

        batched = boxes.ndim == 3
        boxes = boxes if batched else boxes.unsqueeze(0)
        boxes = boxes if boxes.is_floating_point() else boxes.float()

        xmin, ymin, zmin = boxes[..., 0], boxes[..., 1], boxes[..., 2]
        mode = mode.lower()
        if mode == "xyzxyz":
            width = boxes[..., 3] - boxes[..., 0]
            height = boxes[..., 4] - boxes[..., 1]
            depth = boxes[..., 5] - boxes[..., 2]
        elif mode == "xyzxyz_plus":
            width = boxes[..., 3] - boxes[..., 0] + 1
            height = boxes[..., 4] - boxes[..., 1] + 1
            depth = boxes[..., 5] - boxes[..., 2] + 1
        elif mode == "xyzwhd":
            depth, height, width = boxes[..., 4], boxes[..., 3], boxes[..., 5]
        else:
            raise ValueError(f"Unknown mode {mode}")

        if validate_boxes:
            if (width <= 0).any():
                raise ValueError("Some boxes have negative widths or 0.")
            if (height <= 0).any():
                raise ValueError("Some boxes have negative heights or 0.")
            if (depth <= 0).any():
                raise ValueError("Some boxes have negative depths or 0.")

        hexahedrons = _boxes3d_to_polygons3d(xmin, ymin, zmin, width, height, depth)
        hexahedrons = hexahedrons if batched else hexahedrons.squeeze(0)
        return cls(hexahedrons, raise_if_not_floating_point=False, mode=mode)

def wait_for_workers(self, device: Device):
        # Verify enqueue thread has processed all tasks unless a worker threw an exception
        while self._exception_queue.empty():
            with self._object_lock:
                if len(self._logged_objects) == 0:
                    break
            time.sleep(0.2)  # Yield lock for enqueue thread

        # Verify all tasks have been completed unless a worker threw an exception
        all_ranks_upload_done_tensor = device.tensor_to_device(
            torch.tensor(
                [int(not self._file_upload_queue.empty() and self._exception_queue.empty())],
                dtype=torch.uint8,
            ),
        )
        dist.all_reduce(all_ranks_upload_done_tensor, reduce_operation='MAX')
        upload_not_done = all_ranks_upload_done_tensor.item() == 1
        while upload_not_done:
            time.sleep(2)
            all_ranks_upload_done_tensor = device.tensor_to_device(
                torch.tensor(
                    [int(not self._file_upload_queue.empty() and self._exception_queue.empty())],
                    dtype=torch.uint8,
                ),
            )
            dist.all_reduce(all_ranks_upload_done_tensor, reduce_operation='MAX')
            upload_not_done = all_ranks_upload_done_tensor.item() == 1

        if not self._exception_queue.empty():
            e = self._exception_queue.get_nowait()
            raise e

async def block_inspect(
    slug: Annotated[
        Optional[str],
        cyclopts.Parameter(help="A Block slug: <BLOCK_TYPE_SLUG>/<BLOCK_NAME>"),
    ] = None,
    *,
    block_id: Annotated[
        Optional[UUID],
        cyclopts.Parameter("--id", help="A Block id to search for if no slug is given"),
    ] = None,
    output: Annotated[
        Optional[str],
        cyclopts.Parameter(
            "--output",
            alias="-o",
            help="Specify an output format. Currently supports: json",
        ),
    ] = None,
):
    from prefect.client.orchestration import get_client
    from prefect.exceptions import ObjectNotFound

    if output and output.lower() != "json":
        exit_with_error("Only 'json' output format is supported.")

    async with get_client() as client:
        if slug is None and block_id is not None:
            try:
                block_document = await client.read_block_document(
                    block_id, include_secrets=False
                )
            except ObjectNotFound:
                exit_with_error(f"Block {block_id!r} not found!")
        elif slug is not None:
            if "/" not in slug:
                exit_with_error(
                    f"{slug!r} is not valid. Slug must contain a '/', e.g. 'json/my-json-block'"
                )
            block_type_slug, block_document_name = slug.split("/")
            try:
                block_document = await client.read_block_document_by_name(
                    block_document_name, block_type_slug, include_secrets=False
                )
            except ObjectNotFound:
                exit_with_error(f"Block {slug!r} not found!")
        else:
            exit_with_error("Must provide a block slug or id")

        if output and output.lower() == "json":
            block_json = block_document.model_dump(mode="json")
            json_output = orjson.dumps(block_json, option=orjson.OPT_INDENT_2).decode()
            _cli.console.print(json_output, soft_wrap=True)
        else:
            _cli.console.print(_display_block(block_document))

