                    )

def compute_indicators(
        self,
        df: pd.DataFrame,
        indicator_syms: Iterable[IndicatorSymbol],
        cache_date_fields: Optional[CacheDateFields],
        disable_parallel: bool,
    ) -> dict[IndicatorSymbol, pd.Series]:
        if not indicator_syms or df.empty:
            return {}
        scope = StaticScope.instance()
        indicator_data, uncached_ind_syms = self._get_cached_indicators(
            indicator_syms, cache_date_fields
        )
        if not uncached_ind_syms:
            scope.logger.loaded_indicator_data()
            scope.logger.info_loaded_indicator_data(indicator_syms)
            return indicator_data
        if indicator_data:
            scope.logger.info_loaded_indicator_data(indicator_data.keys())
        scope.logger.indicator_data_start(uncached_ind_syms)
        scope.logger.info_indicator_data_start(uncached_ind_syms)
        sym_data: dict[str, dict[str, Optional[NDArray]]] = defaultdict(dict)
        for _, sym in uncached_ind_syms:
            if sym in sym_data:
                continue
            data = df[df[DataCol.SYMBOL.value] == sym]
            for col in scope.all_data_cols:
                if col not in data.columns:
                    sym_data[sym][col] = None
                    continue
                sym_data[sym][col] = data[col].to_numpy(copy=True)
        for i, (ind_sym, series) in enumerate(
            self._run_indicators(sym_data, uncached_ind_syms, disable_parallel)
        ):
            indicator_data[ind_sym] = series
            self._set_cached_indicator(series, ind_sym, cache_date_fields)
            scope.logger.indicator_data_loading(i + 1)
        return indicator_data

def merge_from_list(coco_dict_list, desired_name2id=None, verbose=1):
    if verbose:
        if not desired_name2id:
            print(
                "'desired_name2id' is not specified, combining all categories."
            )

    # create desired_name2id by combinin all categories, if desired_name2id is not specified
    if desired_name2id is None:
        desired_name2id = {}
        ind = 0
        for coco_dict in coco_dict_list:
            temp_categories = copy.deepcopy(coco_dict["categories"])
            for temp_category in temp_categories:
                if temp_category["name"] not in desired_name2id:
                    desired_name2id[temp_category["name"]] = ind
                    ind += 1
                else:
                    continue

    for ind, coco_dict in enumerate(coco_dict_list):
        if ind == 0:
            merged_coco_dict = copy.deepcopy(coco_dict)
        else:
            merged_coco_dict = merge(
                merged_coco_dict, coco_dict, desired_name2id
            )

    # print categories
    if verbose:
        print(
            "Categories are formed as:\n",
            merged_coco_dict["categories"],
        )

    return merged_coco_dict

async def fetch_logs(authenticated: bool = Depends(user_authentication)):
    if not AUTOTRAIN_LOCAL:
        return {"logs": "Logs are only available in local mode."}
    log_file = "autotrain.log"
    with open(log_file, "r", encoding="utf-8") as f:
        logs = f.read()
    if len(str(logs).strip()) == 0:
        logs = "No logs available."

    logs = logs.split("\n")
    logs = logs[::-1]
    # remove lines containing /is_model_training & /accelerators
    logs = [log for log in logs if "/ui/" not in log and "/static/" not in log and "nvidia-ml-py" not in log]

    cuda_available = torch.cuda.is_available()
    if cuda_available:
        devices = Device.all()
        device_logs = []
        for device in devices:
            device_logs.append(
                f"Device {device.index}: {device.name()} - {device.memory_used_human()}/{device.memory_total_human()}"
            )
        device_logs.append("-----------------")
        logs = device_logs + logs
    return {"logs": logs}

def query(
        self,
        vector: np.ndarray,
        top_k: int = 5,
        route_filter: Optional[List[str]] = None,
        sparse_vector: dict[int, float] | SparseEmbedding | None = None,
    ) -> Tuple[np.ndarray, List[str]]:
        if self.index is None or self.routes is None:
            raise ValueError("Index or routes are not populated.")
        if route_filter is not None:
            filtered_index = []
            filtered_routes = []
            for route, vec in zip(self.routes, self.index):
                if route in route_filter:
                    filtered_index.append(vec)
                    filtered_routes.append(route)
            if not filtered_routes:
                raise ValueError("No routes found matching the filter criteria.")
            sim = similarity_matrix(vector, np.array(filtered_index))
            scores, idx = top_scores(sim, top_k)
            route_names = [filtered_routes[i] for i in idx]
        else:
            sim = similarity_matrix(vector, self.index)
            scores, idx = top_scores(sim, top_k)
            route_names = [self.routes[i] for i in idx]
        return scores, route_names

def check_constituents(train_constituents, trees, treebank_name, fail=True):
    constituents = Tree.get_unique_constituent_labels(trees)
    for con in constituents:
        if con not in train_constituents:
            first_error = None
            num_errors = 0
            for tree_idx, tree in enumerate(trees):
                constituents = Tree.get_unique_constituent_labels(tree)
                if con in constituents:
                    num_errors += 1
                    if first_error is None:
                        first_error = tree_idx
            error = "Found constituent label {} in the {} set which don't exist in the train set.  This constituent label occurred in {} trees, with the first tree index at {} counting from 1\nThe error tree (which may have POS tags changed from the retagger and may be missing functional tags or empty nodes) is:\n{:P}".format(con, treebank_name, num_errors, (first_error+1), trees[first_error])
            if fail:
                raise RuntimeError(error)
            else:
                warnings.warn(error)

def from_tuples(
        cls,
        tuples: Iterable[tuple[Hashable, ...]],
        sortorder: int | None = None,
        names: Sequence[Hashable] | Hashable | None = None,
    ) -> MultiIndex:
        if not is_list_like(tuples):
            raise TypeError("Input must be a list / sequence of tuple-likes.")
        if is_iterator(tuples):
            tuples = list(tuples)
        tuples = cast("Collection[tuple[Hashable, ...]]", tuples)

        # handling the empty tuple cases
        if len(tuples) and all(isinstance(e, tuple) and not e for e in tuples):
            codes = [np.zeros(len(tuples))]
            levels = [Index(com.asarray_tuplesafe(tuples, dtype=np.dtype("object")))]
            return cls(
                levels=levels,
                codes=codes,
                sortorder=sortorder,
                names=names,
                verify_integrity=False,
            )

        arrays: list[Sequence[Hashable]]
        if len(tuples) == 0:
            if names is None:
                raise TypeError("Cannot infer number of levels from empty list")
            # error: Argument 1 to "len" has incompatible type "Hashable";
            # expected "Sized"
            arrays = [[]] * len(names)  # type: ignore[arg-type]
        elif isinstance(tuples, (np.ndarray, Index)):
            if isinstance(tuples, Index):
                tuples = np.asarray(tuples._values)

            arrays = list(lib.tuples_to_object_array(tuples).T)
        elif isinstance(tuples, list):
            arrays = list(lib.to_object_array_tuples(tuples).T)
        else:
            arrs = zip_longest(*tuples, fillvalue=np.nan)
            arrays = cast("list[Sequence[Hashable]]", arrs)

        return cls.from_arrays(arrays, sortorder=sortorder, names=names)

def inverse_transpose_batch(self, turn_batch_list):
        dialogs = {}
        total_turn_num = len(turn_batch_list)
        # initialize
        for idx_in_batch, dial_id in enumerate(turn_batch_list[0]['dial_id']):
            dialogs[dial_id] = []
            for turn_n in range(total_turn_num):
                dial_turn = {}
                turn_batch = turn_batch_list[turn_n]
                for key, v_list in turn_batch.items():
                    if key == 'dial_id':
                        continue
                    value = v_list[idx_in_batch]
                    if key == 'pointer' and self.db is not None:
                        turn_domain = turn_batch['turn_domain'][idx_in_batch][
                            -1]
                        value = self.db.pointerBack(value, turn_domain)
                    dial_turn[key] = value
                dialogs[dial_id].append(dial_turn)
        return dialogs

def augment_telugu(sents):
    new_sents = []
    for sentence in sents:
        if not sentence[1].startswith("# text"):
            raise ValueError("Expected the second line of %s to start with # text" % sentence[0])
        if not sentence[2].startswith("# translit"):
            raise ValueError("Expected the second line of %s to start with # translit" % sentence[0])
        if sentence[1].endswith(". . .") or sentence[1][-1] not in ('.', '?', '!'):
            continue
        if sentence[1][-1] in ('.', '?', '!') and sentence[1][-2] != ' ' and sentence[1][-3:] != ' ..' and sentence[1][-4:] != ' ...':
            raise ValueError("Sentence %s does not end with space-punctuation, which is against our assumptions for the te_mtg treebank.  Please check the augment method to see if it is still needed" % sentence[0])
        if random.random() < 0.1:
            new_sentence = list(sentence)
            new_sentence[1] = new_sentence[1][:-2] + new_sentence[1][-1]
            new_sentence[2] = new_sentence[2][:-2] + new_sentence[2][-1]
            new_sentence[-2] = new_sentence[-2] + "|SpaceAfter=No"
            new_sents.append(new_sentence)
        if sentence[1].find(",") > 1 and random.random() < 0.1:
            new_sentence = list(sentence)
            index = sentence[1].find(",")
            new_sentence[1] = sentence[1][:index-1] + sentence[1][index:]
            index = sentence[1].find(",")
            new_sentence[2] = sentence[2][:index-1] + sentence[2][index:]
            for idx, word in enumerate(new_sentence):
                if idx < 4:
                    # skip sent_id, text, transliteration, and the first word
                    continue
                if word.split("\t")[1] == ',':
                    new_sentence[idx-1] = new_sentence[idx-1] + "|SpaceAfter=No"
                    break
            new_sents.append(new_sentence)
    return sents + new_sents

def post_process_object_detection(
        self, outputs, threshold: float = 0.5, target_sizes: TensorType | list[tuple] = None
    ):
        requires_backends(self, ["torch"])
        out_logits, out_bbox = outputs.logits, outputs.pred_boxes

        if target_sizes is not None:
            if len(out_logits) != len(target_sizes):
                raise ValueError(
                    "Make sure that you pass in as many target sizes as the batch dimension of the logits"
                )

        prob = nn.functional.softmax(out_logits, -1)
        scores, labels = prob[..., :-1].max(-1)

        # Convert to [x0, y0, x1, y1] format
        boxes = center_to_corners_format(out_bbox)

        # Convert from relative [0, 1] to absolute [0, height] coordinates
        if target_sizes is not None:
            if isinstance(target_sizes, list):
                img_h = torch.Tensor([i[0] for i in target_sizes])
                img_w = torch.Tensor([i[1] for i in target_sizes])
            else:
                img_h, img_w = target_sizes.unbind(1)

            scale_fct = torch.stack([img_w, img_h, img_w, img_h], dim=1).to(boxes.device)
            boxes = boxes * scale_fct[:, None, :]

        results = []
        for s, l, b in zip(scores, labels, boxes):
            score = s[s > threshold]
            label = l[s > threshold]
            box = b[s > threshold]
            results.append({"scores": score, "labels": label, "boxes": box})

        return results

async def check(self, ctx: RuleContext) -> None:
        for cell in ctx.notebook.cells:
            # Skip empty cells
            if not cell.code.strip():
                continue

            try:
                tree = ast_parse(cell.code)

                # Check if there are any statements
                if not tree.body:
                    continue

                # Get the last statement
                last_stmt = tree.body[-1]

                # Check if it's a branch statement
                if isinstance(last_stmt, ast.If):
                    await self._check_if_statement(last_stmt, cell, ctx)
                elif isinstance(last_stmt, ast.Match):
                    await self._check_match_statement(last_stmt, cell, ctx)
                elif isinstance(last_stmt, ast.Try):
                    await self._check_try_statement(last_stmt, cell, ctx)

            except SyntaxError:
                # Skip cells that don't parse
                continue

def check_model_supports_utilities(
        self, img: Optional[str] = None
    ) -> bool:

        # Only check vision support if an image is provided
        if img is not None:
            out = supports_vision(self.model_name)
            if out is False:
                logger.error(
                    f"[Agent: {self.agent_name}] Model '{self.model_name}' does not support vision capabilities. "
                    f"Image input was provided: {img[:100]}{'...' if len(img) > 100 else ''}. "
                    f"Please use a vision-enabled model."
                )

        if self.tools_list_dictionary is not None:
            out = supports_function_calling(self.model_name)
            if out is False:
                logger.error(
                    f"[Agent: {self.agent_name}] Model '{self.model_name}' does not support function calling capabilities. "
                    f"tools_list_dictionary is set: {self.tools_list_dictionary}. "
                    f"Please use a function calling-enabled model."
                )

        if self.tools is not None:
            if len(self.tools) > 2:
                out = supports_parallel_function_calling(
                    self.model_name
                )
                if out is False:
                    logger.error(
                        f"[Agent: {self.agent_name}] Model '{self.model_name}' does not support parallel function calling capabilities. "
                        f"Please use a parallel function calling-enabled model."
                    )

        return None

def normalize(self, image, mean, std, rescale=False):
        self._ensure_format_supported(image)

        if isinstance(image, PIL.Image.Image):
            image = self.to_numpy_array(image, rescale=True)
        # If the input image is a PIL image, it automatically gets rescaled. If it's another
        # type it may need rescaling.
        elif rescale:
            if isinstance(image, np.ndarray):
                image = self.rescale(image.astype(np.float32), 1 / 255.0)
            elif is_torch_tensor(image):
                image = self.rescale(image.float(), 1 / 255.0)

        if isinstance(image, np.ndarray):
            if not isinstance(mean, np.ndarray):
                mean = np.array(mean).astype(image.dtype)
            if not isinstance(std, np.ndarray):
                std = np.array(std).astype(image.dtype)
        elif is_torch_tensor(image):
            import torch

            if not isinstance(mean, torch.Tensor):
                if isinstance(mean, np.ndarray):
                    mean = torch.from_numpy(mean)
                else:
                    mean = torch.tensor(mean)
            if not isinstance(std, torch.Tensor):
                if isinstance(std, np.ndarray):
                    std = torch.from_numpy(std)
                else:
                    std = torch.tensor(std)

        if image.ndim == 3 and image.shape[0] in [1, 3]:
            return (image - mean[:, None, None]) / std[:, None, None]
        else:
            return (image - mean) / std

def distance(v1, v2, method=COSINE):
    if method == COSINE:
        return 1 - cosine_similarity(v1, v2)
    if method == EUCLIDEAN: # Squared Euclidean distance is used (1.5x faster).
        return sum((v1.get(w, 0) - v2.get(w, 0)) ** 2 for w in set(chain(v1, v2)))
    if method == MANHATTAN:
        return sum(abs(v1.get(w, 0) - v2.get(w, 0)) for w in set(chain(v1, v2)))
    if method == CHEBYSHEV:
        return max(abs(v1.get(w, 0) - v2.get(w, 0)) for w in set(chain(v1, v2)))
    if method == HAMMING:
        d = sum(not (w in v1 and w in v2 and v1[w] == v2[w]) for w in set(chain(v1, v2)))
        d = d / float(max(len(v1), len(v2)) or 1)
        return d
    if isinstance(method, type(distance)):
        # Given method is a function of the form: distance(v1, v2) => float.
        return method(v1, v2)

def to_properties(cls, config, compact=False, indent=2, key_stack=[]):
        def escape_value(value):
            return value.replace('=', '\\=').replace('!', '\\!').replace('#', '\\#').replace('\n', '\\\n')

        stripped_key_stack = [key.strip('"') for key in key_stack]
        lines = []
        if isinstance(config, ConfigTree):
            for key, item in config.items():
                if item is not None:
                    lines.append(cls.to_properties(item, compact, indent, stripped_key_stack + [key]))
        elif isinstance(config, list):
            for index, item in enumerate(config):
                if item is not None:
                    lines.append(cls.to_properties(item, compact, indent, stripped_key_stack + [str(index)]))
        elif isinstance(config, basestring):
            lines.append('.'.join(stripped_key_stack) + ' = ' + escape_value(config))
        elif config is True:
            lines.append('.'.join(stripped_key_stack) + ' = true')
        elif config is False:
            lines.append('.'.join(stripped_key_stack) + ' = false')
        elif config is None or isinstance(config, NoneValue):
            pass
        else:
            lines.append('.'.join(stripped_key_stack) + ' = ' + str(config))
        return '\n'.join([line for line in lines if len(line) > 0])

def scaled(size: QSizeF, constraint: QSizeF, mode=Qt.KeepAspectRatio) -> QSizeF:
    size, constraint = QSizeF(size), QSizeF(constraint)
    if size.isEmpty():
        return size
    if constraint.width() < 0 and constraint.height() < 0:
        return size
    if mode == Qt.IgnoreAspectRatio:
        if constraint.width() >= 0:
            size.setWidth(constraint.width())
        if constraint.height() >= 0:
            size.setHeight(constraint.height())
    elif mode == Qt.KeepAspectRatio:
        if constraint.width() < 0:
            constraint.setWidth(QWIDGETSIZE_MAX)
        if constraint.height() < 0:
            constraint.setHeight(QWIDGETSIZE_MAX)
        size.scale(constraint, mode)
    elif mode == Qt.KeepAspectRatioByExpanding:
        if constraint.width() < 0:
            constraint.setWidth(0)
        if constraint.height() < 0:
            constraint.setHeight(0)
        size.scale(constraint, mode)
    return size

def edit_tab(self, stdscr, tab_name: str) -> None:
        nav = MenuNavigator(stdscr)

        while True:
            fields, sections, _ = self._get_tab_structure(tab_name)
            section_fields = {
                section["id"]: [field for field in fields if field.get("section_id") == section["id"]]
                for section in sections
            }
            sections_with_fields = [section for section in sections if section_fields.get(section["id"])]

            if not sections_with_fields:
                self.show_message(stdscr, "No configurable fields in this tab with the current context.")
                return

            menu_items: List[tuple[str, Any]] = []
            current_values: Dict[str, str] = {}

            for section in sections_with_fields:
                title = section.get("title") or section["id"].replace("_", " ").title()
                count = len(section_fields[section["id"]])
                current_values[title] = f"{count} field{'s' if count != 1 else ''}"
                menu_items.append((title, partial(self.edit_section, tab_name=tab_name, section_id=section["id"])))

            last_selected = self._section_menu_indices.get(tab_name, 0)
            if menu_items:
                last_selected = max(0, min(last_selected, len(menu_items) - 1))
            else:
                last_selected = 0

            choice = nav.show_menu(self.tab_lookup[tab_name].title, menu_items, current_values, selected=last_selected)
            self._section_menu_indices[tab_name] = nav.last_selection

            if choice == -1:
                if self.confirm_quit(stdscr):
                    raise KeyboardInterrupt
            elif choice == -2:
                return
            else:
                menu_items[choice][1](stdscr)

async def send(
        self,
        content: BidiInputEvent | ToolResultEvent,
    ) -> None:
        if not self._connection_id:
            raise RuntimeError("model not started | call start before sending")

        # Note: TypedEvent inherits from dict, so isinstance checks for TypedEvent must come first
        if isinstance(content, BidiTextInputEvent):
            await self._send_text_content(content.text)
        elif isinstance(content, BidiAudioInputEvent):
            await self._send_audio_content(content)
        elif isinstance(content, ToolResultEvent):
            tool_result = content.get("tool_result")
            if tool_result:
                await self._send_tool_result(tool_result)
        else:
            raise ValueError(f"content_type={type(content)} | content not supported")

def hybrid_forward(
        self, F, data: Tensor, prev: Optional[Tensor] = None
    ) -> Tensor:
        if not self.sequence:
            return data

        if prev is None:
            assert (
                "r" not in self.sequence
            ), "Residual connection not allowed if no previous value given."

        for step in self.sequence:
            if step == "r":
                data = F.broadcast_add(data, prev)

            elif step == "n":
                assert self.layer_norm is not None
                data = self.layer_norm(data)

            elif step == "d":
                if self.dropout > 0.0:
                    data = F.Dropout(data, p=self.dropout)
            else:
                raise ValueError("Unknown step in sequence: %s" % step)

        return data

def kwargs_to_args(kwargs: dict, args: Optional[list[str]] = None) -> list[str]:
    if args is None:
        args = []

    kwargs_args = []
    for key, value in list(kwargs.items()):
        if value is None:
            continue

        flag = "--" + key.replace("_", "-")

        if isinstance(value, bool):
            kwargs_args.append(flag if value else f"--no-{key.replace('_', '-')}")

        elif isinstance(value, (list, tuple)):
            kwargs_args.append(flag)
            kwargs_args.extend(str(v) for v in value)
        else:
            kwargs_args.extend([flag, str(value)])

        kwargs.pop(key)

    existing_flags = _parse_args_to_flag_groups(args)
    kwargs_flags = _parse_args_to_flag_groups(kwargs_args)

    result_args = []

    # First add positional arguments (like the dbt command)
    if "__positional__" in existing_flags:
        result_args.extend(existing_flags["__positional__"])
        del existing_flags["__positional__"]

    # Then add flags from existing args
    for flag, values in existing_flags.items():
        result_args.extend([flag] + values)

    # Finally add flags from kwargs that aren't already in existing args
    for flag, values in kwargs_flags.items():
        if flag not in existing_flags:
            result_args.extend([flag] + values)

    return result_args

def resize(
        self,
        video: "torch.Tensor",
        size: SizeDict,
        resample: "PILImageResampling | tvF.InterpolationMode | int | None" = None,
        antialias: bool = True,
        **kwargs,
    ) -> "torch.Tensor":
        if resample is not None:
            if isinstance(resample, (PILImageResampling, int)):
                interpolation = pil_torch_interpolation_mapping[resample]
            else:
                interpolation = resample
        else:
            interpolation = tvF.InterpolationMode.BILINEAR
        if interpolation == tvF.InterpolationMode.LANCZOS:
            logger.warning_once(
                "You have used fast image processor with LANCZOS resample which not yet supported for torch.Tensor. "
                "BICUBIC resample will be used as an alternative. Please fall back to image processor if you "
                "want full consistency with the original model."
            )
            interpolation = tvF.InterpolationMode.BICUBIC

        if size.longest_edge:
            # Resize the image so that the shortest edge or the longest edge is of the given size
            # while maintaining the aspect ratio of the original image.
            new_size = get_resize_output_image_size(
                video,
                resolution_max_side=size.longest_edge,
            )
        elif size.height and size.width:
            new_size = (size.height, size.width)
        else:
            raise ValueError(f"Size must contain 'height' and 'width' keys, or 'longest_edge' key. Got {size}.")

        video = tvF.resize(video, new_size, interpolation=interpolation, antialias=antialias)

        # Resize again to match image processor when `do_image_splitting=False`. Frames have to be squared to `max_image_size`
        # NOTE: videos are always processoed without image splitting
        max_size = self.max_image_size["longest_edge"], self.max_image_size["longest_edge"]
        video = tvF.resize(video, max_size, interpolation=interpolation, antialias=antialias)
        return video

def generate_batched_itr(self,
                             data_itr,
                             beam_size=None,
                             cuda=False,
                             timer=None):
        for sample in data_itr:
            s = utils.move_to_cuda(sample) if cuda else sample
            if 'net_input' not in s:
                continue
            input = s['net_input']
            # model.forward normally channels prev_output_tokens into the decoder
            # separately, but SequenceGenerator directly calls model.encoder
            encoder_input = {
                k: v
                for k, v in input.items() if k != 'prev_output_tokens'
            }
            if timer is not None:
                timer.start()
            with torch.no_grad():
                hypos = self.generate(encoder_input)
            if timer is not None:
                timer.stop(sum(len(h[0]['tokens']) for h in hypos))
            for i, id in enumerate(s['id'].data):
                # remove padding
                src = utils.strip_pad(input['src_tokens'].data[i, :], self.pad)
                ref = (
                    utils.strip_pad(s['target'].data[i, :], self.pad)
                    if s['target'] is not None else None)
                yield id, src, ref, hypos[i]

def better_help(obj: Any) -> str:
    # Pick a reasonable title for any object kind (modules, functions, ...).
    title = getattr(obj, "__name__", None) or type(obj).__name__

    lines: list[str] = [f"# {title}"]

    # Prefer the original (pre-@helpable) docstring so we don't duplicate
    # the generated heading or drop the human-written description line.
    raw_doc = getattr(obj, "_original_doc__", None) or getattr(
        obj, "__doc__", None
    )
    desc = _first_doc_line(raw_doc)
    # Strip the generated `# Name` heading if _original_doc__ is unavailable.
    if desc.startswith("#"):
        desc = ""
    if desc:
        lines.append(desc)

    lines.append("")

    attrs: list[str] = []
    methods: list[str] = []

    for name in _public_attrs(obj):
        val = _safe_getattr_static(obj, name)
        if val is _MISSING:
            continue

        call_target = _unwrap_callable(val)

        if isinstance(val, property):
            attrs.append(f"  {name}: {_type_label(val)}")
            continue

        if callable(call_target) and not isinstance(val, Enum):
            try:
                sig = _format_signature(call_target)
            except (ValueError, TypeError):
                sig = "(...)"
            doc = _first_doc_line(getattr(call_target, "__doc__", None))
            entry = f"  {name}{sig}"
            if doc:
                entry += f"  -- {doc}"
            methods.append(entry)
        elif isinstance(val, Enum):
            attrs.append(f"  {name} = {val.value!r}")
        else:
            attrs.append(f"  {name}: {_type_label(val)}")

    if attrs:
        lines.append("Attributes:")
        lines.extend(attrs)
        lines.append("")

    if methods:
        lines.append("Methods:")
        lines.extend(methods)

    return "\n".join(lines)

def get_quantized_per_tensor(self, name, torch_dtype, scale, zero_point, quantized_name):
        if self._quant_dtype is None:
            self._quant_dtype = torch_dtype
        elif self._quant_dtype != torch_dtype:
            raise NotImplementedError(
                "Currently we only support a single activation dtype throughout the model"
            )

        if torch_dtype == torch.quint8:
            zero_point = np.uint8(zero_point)
            output_dtype = "uint8"
        elif torch_dtype == torch.qint8:
            zero_point = np.int8(zero_point)
            output_dtype = "int8"
        else:
            raise ValueError(f"Invalid torch dtype for quantization: {torch_dtype}")
        if np.isscalar(zero_point):
            # MIL allows skipping zero_point if its zero.
            if zero_point == 0:
                zero_point = None
            # TODO (rdar://107718371): skip 128 for uint8 by switching to int8

        result = mb.quantize(
            input=self._context[name], zero_point=zero_point, scale=scale, output_dtype=output_dtype
        )
        self._context.add(result, quantized_name)
        self._context.quant_context.add_quantization_info(
            quantized_name, torch_dtype, scale, zero_point
        )
        return result

def merge_tensors(tensor_objects, non_tensor_objects, tensor_flags):
    merged_objects = []
    tensor_idx = 0
    non_tensor_idx = 0

    real_tensor_flags = None

    # remove the flags that are assigned to the size of the flattened tensors
    if PARTITION_ACTIVATIONS:
        real_tensor_flags = []
        previous_flag = False
        for flag in tensor_flags:
            if previous_flag:
                previous_flag = False
                continue
            previous_flag = flag
            real_tensor_flags.append(flag)
    else:
        real_tensor_flags = tensor_flags

    for is_tensor in real_tensor_flags:
        if is_tensor:
            merged_objects.append(tensor_objects[tensor_idx])
            tensor_idx += 1
        else:
            merged_objects.append(non_tensor_objects[non_tensor_idx])
            non_tensor_idx += 1

    return tuple(merged_objects)

def postprocessing_fn(results):
        samples = results[0]
        if tape.shots.has_partitioned_shots:
            results_processed = []
            for s in samples:
                res = [m.process_samples(s, measured_wires) for m in tape.measurements]
                if len(tape.measurements) == 1:
                    res = res[0]
                results_processed.append(res)
        else:
            results_processed = [
                m.process_samples(samples, measured_wires) for m in tape.measurements
            ]
            if len(tape.measurements) == 1:
                results_processed = results_processed[0]

        return results_processed

def extract_pdf_metadata(
    document_path: Path,
    log: logging.Logger | None = None,
) -> list[MetadataEntry]:
    import pikepdf

    from paperless.parsers import MetadataEntry

    _log = log or logger
    result: list[MetadataEntry] = []
    namespace_pattern = re.compile(r"\{(.*)\}(.*)")

    try:
        pdf = pikepdf.open(document_path)
        meta = pdf.open_metadata()
    except Exception as e:
        _log.warning("Could not open PDF metadata for %s: %s", document_path, e)
        return []

    for key, value in meta.items():
        if isinstance(value, list):
            value = " ".join(str(e) for e in value)
        value = str(value)

        try:
            m = namespace_pattern.match(key)
            if m is None:
                continue

            namespace = m.group(1)
            key_value = m.group(2)

            try:
                namespace.encode("utf-8")
                key_value.encode("utf-8")
            except UnicodeEncodeError as enc_err:  # pragma: no cover
                _log.debug("Skipping metadata key %s: %s", key, enc_err)
                continue

            result.append(
                MetadataEntry(
                    namespace=namespace,
                    prefix=meta.REVERSE_NS[namespace],
                    key=key_value,
                    value=value,
                ),
            )
        except Exception as e:
            _log.warning(
                "Error reading metadata key %s value %s: %s",
                key,
                value,
                e,
            )

    return result

def save(self) -> None:
        from wandb.sdk.artifacts._validators import validate_artifact_type

        if (old_type := self._saved.type) != (new_type := self.type):
            try:
                validate_artifact_type(new_type, self.name)
            except ValueError as e:
                reason = str(e)
                raise ValueError(
                    f"Failed to save artifact collection {self.name!r}: {reason}"
                ) from e
            try:
                validate_artifact_type(old_type, self.name)
            except ValueError as e:
                reason = f"The current type {old_type!r} is an internal type and cannot be changed."
                raise ValueError(
                    f"Failed to save artifact collection {self.name!r}: {reason}"
                ) from e

        # FIXME: Consider consolidating the multiple GQL mutations into a single call.
        self._update_collection()

        if self.is_sequence() and (old_type != new_type):
            self._update_sequence_type()

        if (new_tags := set(self._current.tags)) != (old_tags := set(self._saved.tags)):
            if added_tags := (new_tags - old_tags):
                self._add_tags(added_tags)
            if deleted_tags := (old_tags - new_tags):
                self._delete_tags(deleted_tags)
            self._saved.tags = copy(new_tags)

def run_committee_hearing(
        self, committee: str, topic: str, witnesses: List[str] = None
    ) -> Dict:
        # Get senators on the committee (simplified - in reality would be more complex)
        committee_senators = [
            name
            for name in self.senators.keys()
            if committee in self._get_senator_committees(name)
        ]

        hearing_transcript = []

        # Opening statements
        for senator_name in committee_senators:
            senator = self.senators[senator_name]
            opening = senator.run(
                f"As a member of the {committee} Committee, provide an opening statement for a hearing on: {topic}"
            )

            hearing_transcript.append(
                {
                    "type": "opening_statement",
                    "senator": senator_name,
                    "content": opening,
                }
            )

        # Witness testimony (simulated)
        if witnesses:
            for witness in witnesses:
                hearing_transcript.append(
                    {
                        "type": "witness_testimony",
                        "witness": witness,
                        "content": f"Testimony on {topic} from {witness}",
                    }
                )

        # Question and answer session
        for senator_name in committee_senators:
            senator = self.senators[senator_name]
            questions = senator.run(
                f"As a member of the {committee} Committee, what questions would you ask witnesses about: {topic}"
            )

            hearing_transcript.append(
                {
                    "type": "questions",
                    "senator": senator_name,
                    "content": questions,
                }
            )

        return {
            "committee": committee,
            "topic": topic,
            "witnesses": witnesses or [],
            "transcript": hearing_transcript,
        }

def to_numpy(obj):
    if isinstance(obj, (dict, UserDict)):
        return {k: to_numpy(v) for k, v in obj.items()}
    elif isinstance(obj, (list, tuple)):
        return np.array(obj)
    elif is_tf_tensor(obj):
        return obj.numpy()
    elif is_torch_tensor(obj):
        return obj.detach().cpu().numpy()
    elif is_jax_tensor(obj):
        return np.asarray(obj)
    else:
        return obj

def to_string(counts: list[int]) -> str:
            result = []

            for i in range(len(counts)):
                x = int(counts[i])

                # Apply delta encoding for all counts after the second entry
                if i > 2:
                    x -= int(counts[i - 2])

                # Variable-length encode the value
                while True:
                    c = x & 0x1F  # Take 5 bits
                    x >>= 5

                    # If the sign bit (0x10) is set, continue if x != -1;
                    # otherwise, continue if x != 0
                    more = (x != -1) if (c & 0x10) else (x != 0)
                    if more:
                        c |= 0x20  # Set continuation bit
                    c += 48  # Shift to ASCII
                    result.append(chr(c))
                    if not more:
                        break

            return "".join(result)

def import_offline_session(
        cls,
        session_folder_zip: str,
        upload: bool = True,
        finalize: bool = False,
    ) -> str:
        id = Task.import_offline_session(session_folder_zip)
        dataset = Dataset.get(dataset_id=id)
        # note that there can only be one offline session in the dependency graph: our session
        # noinspection PyProtectedMember
        dataset._dependency_graph = {
            (id if k.startswith("offline-") else k): [(id if sub_v.startswith("offline-") else sub_v) for sub_v in v]
            for k, v in dataset._dependency_graph.items()  # noqa
        }
        # noinspection PyProtectedMember
        for entry in dataset._dataset_file_entries.values():
            if entry.parent_dataset_id.startswith("offline-"):
                entry.parent_dataset_id = id
        for entry in dataset._dataset_link_entries.values():
            if entry.parent_dataset_id.startswith("offline-"):
                entry.parent_dataset_id = id
        # noinspection PyProtectedMember
        dataset._update_dependency_graph()
        # noinspection PyProtectedMember
        dataset._log_dataset_page()

        started = False
        if upload or finalize:
            started = True
            # noinspection PyProtectedMember
            dataset._task.mark_started(force=True)

        if upload:
            dataset.upload()
        if finalize:
            dataset.finalize()

        if started:
            # noinspection PyProtectedMember
            dataset._task.mark_completed()

        return id

def multi_predict(stracks):
        if len(stracks) <= 0:
            return
        multi_mean = np.asarray([st.mean.copy() for st in stracks])
        multi_covariance = np.asarray([st.covariance for st in stracks])
        for i, st in enumerate(stracks):
            if st.state != TrackState.Tracked:
                multi_mean[i][6] = 0
                multi_mean[i][7] = 0
        multi_mean, multi_covariance = BOTrack.shared_kalman.multi_predict(
            multi_mean, multi_covariance
        )
        for i, (mean, cov) in enumerate(zip(multi_mean, multi_covariance)):
            stracks[i].mean = mean
            stracks[i].covariance = cov

def mark_activation_offload(*tensors, offload: bool = True):
    if TEDebugState.debug_enabled:
        raise RuntimeError("CPU offload is not supported in debug mode.")

    for tensor in tensors:
        if tensor is None:
            continue
        if type(tensor) in [torch.Tensor, torch.nn.Parameter]:
            if offload:
                tensor.activation_offloading = True
            else:
                # This is a hack to prevent the tensor from being offloaded.
                # And it won't break the original logic of the code.
                tensor._TE_do_not_offload = True
        else:
            data_tensors = tensor.get_data_tensors()
            for tensor in data_tensors:
                if tensor is not None:
                    if offload:
                        tensor.activation_offloading = True
                        # This is a hack to force clear the tensor after it is offloaded.
                        # It is needed, because .*TensorStorage classes are saved in the ctx,
                        # and they contain the reference to their data tensors.
                        tensor.needs_force_clear = offload
                    else:
                        tensor._TE_do_not_offload = True

def emit_stop_position(
    P: "MLXProgramBuilder",
    start: "Union[int, Slot]",
    length_tensor: "Slot",
    length_dim: int,
    length_meta: "Optional[torch.Tensor]" = None,
) -> "Union[int, Slot]":
    from executorch.backends.mlx.serialization.mlx_graph_schema import (
        AddIntNode,
        IntOrVid,
        SymSizeNode,
    )

    # Check if seq_len is symbolic (dynamic)
    seq_len_is_symbolic = False
    seq_len_concrete = None

    if length_meta is not None:
        seq_len_dim = length_meta.shape[length_dim]
        if hasattr(seq_len_dim, "node"):
            seq_len_is_symbolic = True
        else:
            seq_len_concrete = int(seq_len_dim)

    if seq_len_is_symbolic or length_meta is None:
        # Dynamic seq_len: emit SymSizeNode to get length at runtime
        _, seq_len_slot = P.slot_manager.make_tmp_value_slot()
        P.emit(
            SymSizeNode(
                a=P.slot_to_tid(length_tensor),
                dim=length_dim,
                out=P.slot_to_vid(seq_len_slot),
            )
        )
        _, stop_slot = P.slot_manager.make_tmp_value_slot()
        if isinstance(start, Slot):
            start_iov = P.to_int_or_vid(start)
        else:
            start_iov = IntOrVid.from_literal(int(start))
        P.emit(
            AddIntNode(
                a=start_iov,
                b=IntOrVid.from_vid(P.slot_to_vid(seq_len_slot)),
                out=P.slot_to_vid(stop_slot),
            )
        )
        return stop_slot
    else:
        # Static seq_len
        if isinstance(start, Slot):
            # Dynamic start + static length
            _, stop_slot = P.slot_manager.make_tmp_value_slot()
            P.emit(
                AddIntNode(
                    a=P.to_int_or_vid(start),
                    b=IntOrVid.from_literal(seq_len_concrete),
                    out=P.slot_to_vid(stop_slot),
                )
            )
            return stop_slot
        else:
            # Both static - just return the sum
            return start + seq_len_concrete

def findSystemFonts(fontpaths=None, fontext='ttf'):
    fontfiles = set()
    fontexts = get_fontext_synonyms(fontext)

    if fontpaths is None:
        if os.getenv('MPL_IGNORE_SYSTEM_FONTS'):
            installed_fonts = []
            fontpaths = []
        elif sys.platform == 'win32':
            installed_fonts = _get_win32_installed_fonts()
            fontpaths = []
        elif sys.platform == 'emscripten':
            installed_fonts = []
            fontpaths = []
        else:
            installed_fonts = _get_fontconfig_fonts()
            if sys.platform == 'darwin':
                installed_fonts += _get_macos_fonts()
                fontpaths = [*X11FontDirectories, *OSXFontDirectories]
            else:
                fontpaths = X11FontDirectories
        fontfiles.update(str(path) for path in installed_fonts
                         if path.suffix.lower()[1:] in fontexts)

    elif isinstance(fontpaths, str):
        fontpaths = [fontpaths]

    for path in fontpaths:
        fontfiles.update(map(os.path.abspath, list_fonts(path, fontexts)))

    return [fname for fname in fontfiles if os.path.exists(fname)]

def copy_tensor(dst_tensor, src_tensor):
    copied = True
    if (isinstance(dst_tensor, numpy.ndarray) and
            isinstance(src_tensor, numpy.ndarray)):
        numpy.copyto(dst_tensor, src_tensor)
    elif torch_available():
        if isinstance(dst_tensor, torch.Tensor) and isinstance(
                src_tensor, torch.Tensor):
            dst_tensor.copy_(src_tensor)
        elif isinstance(dst_tensor, torch.Tensor) and isinstance(
                src_tensor, numpy.ndarray):
            t = torch.Tensor(src_tensor)
            dst_tensor.copy_(t)
        elif isinstance(dst_tensor, numpy.ndarray) and isinstance(
                src_tensor, torch.Tensor):
            t = src_tensor.numpy()
            numpy.copyto(dst_tensor, t)
        else:
            copied = False
    else:
        copied = False
    if not copied:
        raise ValueError(
            f"Unsupported tensor type. Got: {type(dst_tensor)} and "
            f"{type(src_tensor)}. Supported CPU tensor types are: "
            f"torch.Tensor, numpy.ndarray.")

def write_dl(self, rows, col_max=30, col_spacing=2):
        rows = list(rows)
        widths = measure_table(rows)
        if len(widths) != 2:
            raise TypeError("Expected two columns for definition list")

        first_col = min(widths[0], col_max) + col_spacing

        for first, second in iter_rows(rows, len(widths)):
            self.write("{:>{w}}{}".format("", first, w=self.current_indent))
            if not second:
                self.write("\n")
                continue
            if term_len(first) <= first_col - col_spacing:
                self.write(" " * (first_col - term_len(first)))
            else:
                self.write("\n")
                self.write(" " * (first_col + self.current_indent))

            text_width = max(self.width - first_col - 2, 10)
            wrapped_text = wrap_text(second, text_width, preserve_paragraphs=True)
            lines = wrapped_text.splitlines()

            if lines:
                self.write("{}\n".format(lines[0]))

                for line in lines[1:]:
                    self.write(
                        "{:>{w}}{}\n".format(
                            "", line, w=first_col + self.current_indent
                        )
                    )

                if len(lines) > 1:
                    # separate long help from next option
                    self.write("\n")
            else:
                self.write("\n")

def set_names(
        self,
        names: Hashable | Sequence[Hashable] | dict[Hashable, Hashable],
        *,
        level: Hashable | Sequence[Hashable] | None = None,
        inplace: bool = False,
    ) -> Self | None:
        if level is not None and not isinstance(self, ABCMultiIndex):
            raise ValueError("Level must be None for non-MultiIndex")

        if level is not None and not is_list_like(level) and is_list_like(names):
            raise TypeError("Names must be a string when a single level is provided.")

        if not is_list_like(names) and level is None and self.nlevels > 1:
            raise TypeError("Must pass list-like as `names`.")

        if is_dict_like(names) and not isinstance(self, ABCMultiIndex):
            raise TypeError("Can only pass dict-like as `names` for MultiIndex.")

        if is_dict_like(names) and level is not None:
            raise TypeError("Can not pass level for dictlike `names`.")

        if isinstance(self, ABCMultiIndex) and is_dict_like(names) and level is None:
            # Transform dict to list of new names and corresponding levels
            level_list: list[int] = []
            names_adjusted: list[Hashable] = []
            for i, name in enumerate(self.names):
                if name in names.keys():  # type: ignore[union-attr]
                    level_list.append(i)
                    names_adjusted.append(names[name])  # type: ignore[index]
            level = level_list
            names = names_adjusted

        if not is_list_like(names):
            names = [names]  # type: ignore[assignment]
        if level is not None and not is_list_like(level):
            level = [level]

        if inplace:
            idx = self
        else:
            idx = self._view()

        idx._set_names(names, level=level)  # type: ignore[arg-type]
        if not inplace:
            return idx  # pyright: ignore[reportReturnType]
        return None

def parse_requirements() -> Tuple[PackagesType, PackagesType, Set[str]]:
    essential_packages: PackagesType = {}
    other_packages: PackagesType = {}
    duplicates: Set[str] = set()
    with open("requirements.txt", "r") as req_file:
        section: str = ""
        for line in req_file:
            line = line.strip()

            if line.startswith("####"):
                # Line is a section name.
                section = parse_section_name(line)
                continue

            if not line or line.startswith("#"):
                # Line is empty or just regular comment.
                continue

            module, version = parse_package(line)
            if module in essential_packages or module in other_packages:
                duplicates.add(module)

            if section.startswith("ESSENTIAL"):
                essential_packages[module] = version
            else:
                other_packages[module] = version

    return essential_packages, other_packages, duplicates

def load_app(filename: str | Path | None) -> App | None:
    if filename is None:
        return None

    path = Path(filename)
    handler = get_notebook_serializer(path)

    contents = _maybe_contents(filename)
    if not contents:
        return None

    try:
        notebook_ir = handler.deserialize(contents, filepath=str(path))
        if notebook_ir and is_non_marimo_python_script(notebook_ir):
            # Should fail instead of overriding contents
            raise NonMarimoPythonScriptError(
                f"Python script {path} is not a marimo notebook."
            )

        if not notebook_ir.valid:
            LOGGER.error(f"Notebook {path} is not a valid marimo notebook.")
            return None

        app = load_notebook_ir(notebook_ir)
        app._cell_manager.ensure_one_cell()
        return app
    except MarimoFileError as e:
        LOGGER.error(FAILED_LOAD_NOTEBOOK_MESSAGE)
        raise MarimoFileError(FAILED_LOAD_NOTEBOOK_MESSAGE) from e

def assert_allclose(x, y, rtol=1e-4, atol=1e-4):
    if isinstance(x, (dict, FrozenDictJax, FrozenDictFlax)):
        assert isinstance(y, (dict, FrozenDictJax, FrozenDictFlax))
        assert set(x.keys()) == set(y.keys())
        for k in x.keys():
            assert_allclose(x[k], y[k], rtol, atol)
    elif isinstance(x, Iterable) and not hasattr(x, "__array__"):
        assert isinstance(y, Iterable) and not hasattr(y, "__array__")
        assert len(x) == len(y)
        for x_elt, y_elt in zip(x, y):
            assert_allclose(x_elt, y_elt, rtol, atol)
    elif hasattr(x, "__array__") or np.isscalar(x):
        assert hasattr(y, "__array__") or np.isscalar(y), f"{y}"
        x = np.asarray(x)
        y = np.asarray(y)
        np.testing.assert_allclose(x, y, rtol, atol)
    elif isinstance(x, TrainState):
        assert isinstance(y, TrainState)
        assert_allclose(tree_leaves(x), tree_leaves(y), rtol, atol)
    elif x == y:
        return
    else:
        raise TypeError((type(x), type(y)))

def check_marl_grouping(group_map: dict[str, list[str]], agent_names: list[str]):
    n_agents = len(agent_names)
    if n_agents == 0:
        raise ValueError("No agents passed")
    if len(set(agent_names)) != n_agents:
        raise ValueError("There are agents with the same name")
    if len(group_map.keys()) > n_agents:
        raise ValueError(
            f"Number of groups {len(group_map.keys())} greater than number of agents {n_agents}"
        )
    found_agents = {agent_name: False for agent_name in agent_names}
    for group_name, group in group_map.items():
        if not len(group):
            raise ValueError(f"Group {group_name} is empty")
        for agent_name in group:
            if agent_name not in found_agents:
                raise ValueError(f"Agent {agent_name} wasn't present in environment")
            if not found_agents[agent_name]:
                found_agents[agent_name] = True
            else:
                raise ValueError(f"Agent {agent_name} present more than once")
    for agent_name, found in found_agents.items():
        if not found:
            raise ValueError(f"Agent {agent_name} wasn't found in any group")

def memoize(key, save_at_exit=False):
    def _register(f):
        """Registration function"""
        allow_types = (str, int, float, tuple)
        fkey = key + "." + f.__name__ + ".pkl"
        if fkey not in Cache.cache_by_key:
            Cache.cache_by_key[fkey] = Cache(fkey, save_at_exit)
        cache = Cache.cache_by_key[fkey]
        cargs = tuple(x.cell_contents for x in f.__closure__) if f.__closure__ else ()
        cargs = (len(cargs),) + cargs

        @functools.wraps(f)
        def _memoized_f(*args, **kwargs):
            assert not kwargs, "Only allow positional call"
            key = cargs + args
            for arg in key:
                if isinstance(arg, tuple):
                    for x in arg:
                        assert isinstance(x, allow_types)
                else:
                    assert isinstance(arg, allow_types)
            if key in cache.cache:
                return cache.cache[key]
            res = f(*args)
            cache.cache[key] = res
            cache.dirty = True
            return res

        return _memoized_f

    return _register

def external_constants_pass(
    gm: GraphModule,
    gen_tag_fn: Optional[Callable[[torch.fx.Node], Optional[str]]] = None,
) -> PassResult:
    mutated = False
    for module in gm.modules():
        if not isinstance(module, torch.fx.GraphModule):
            continue

        for node in module.graph.nodes:
            if (node.op == "placeholder") and ("_lifted_tensor" not in node.name):
                spec = node.meta.get("spec")
                if isinstance(spec, TensorSpec) and spec.const:
                    if gen_tag_fn is not None:
                        node.meta["constant_tag"] = gen_tag_fn(node)
                    else:
                        node.meta["constant_tag"] = "_default_external_constant"
                    mutated = True
    return PassResult(gm, mutated)

def bio_phylo_to_times(tree, *, get_time=None):
    if get_time is None:
        # Compute time as cumulative branch length.
        def get_branch_length(clade):
            branch_length = clade.branch_length
            return 1.0 if branch_length is None else branch_length

        times = {tree.root: get_branch_length(tree.root)}

    leaf_times = []
    coal_times = []
    for clade in tree.find_clades():
        if get_time is None:
            time = times[clade]
            for child in clade:
                times[child] = time + get_branch_length(child)
        else:
            time = get_time(clade)

        num_children = len(clade)
        if num_children == 0:
            leaf_times.append(time)
        else:
            # Pyro expects binary coalescent events, so we split n-ary events
            # into n-1 separate binary events.
            for _ in range(num_children - 1):
                coal_times.append(time)
    assert len(leaf_times) == 1 + len(coal_times)

    leaf_times = torch.tensor(leaf_times)
    coal_times = torch.tensor(coal_times)
    return leaf_times, coal_times

def compute_metric(
    y: np.ndarray,
    metric: "Scorer",
    *,
    y_pred: np.ndarray = None,
    y_pred_proba: np.ndarray = None,
    weights: np.ndarray = None,
    weight_evaluation: bool = None,
    as_error: bool = False,
    silent: bool = False,
    **kwargs,
) -> float:
    if not metric.needs_quantile:
        kwargs.pop("quantile_levels", None)
    if weight_evaluation is None:
        weight_evaluation = not (weights is None)
    if weight_evaluation and weights is None:
        raise ValueError("Sample weights cannot be None when weight_evaluation=True.")
    if as_error:
        func = metric.error
    else:
        func = metric
    if metric.needs_pred or metric.needs_quantile:
        if y_pred is None:
            raise ValueError(
                f"y_pred must be specified for metric {metric.name}... (needs_pred={metric.needs_pred}, need_quantile={metric.needs_quantile}"
            )
        predictions = y_pred
    elif metric.needs_proba or metric.needs_threshold:
        if y_pred_proba is None:
            raise ValueError(
                f"y_pred_proba must be specified for metric {metric.name}... "
                f"(needs_proba={metric.needs_proba}, needs_threshold={metric.needs_threshold}"
            )
        predictions = y_pred_proba
    else:
        raise AssertionError(
            f"Metric {metric.name} does not support predictions or prediction probabilities as input. "
            f"Ensure the metric is constructed properly."
        )
    if not weight_evaluation:
        return func(y, predictions, **kwargs)
    try:
        weighted_metric = func(y, predictions, sample_weight=weights, **kwargs)
    except (ValueError, TypeError, KeyError):
        if hasattr(metric, "name"):
            metric_name = metric.name
        else:
            metric_name = metric
        if not silent:
            logger.log(
                30,
                f"WARNING: eval_metric='{metric_name}' does not support sample weights so they will be ignored in reported metric.",
            )
        weighted_metric = func(y, predictions, **kwargs)
    return weighted_metric

def save_as_html(
    serializer: t.Union[HtmlSerializer[T], WidgetSerializer[T]],
    file: t.Union[str, io.TextIOWrapper, None] = None,
    requirejs: bool = True,
    connected: bool = False,
    **kwargs
) -> t.Optional[str]:
    if file is None:
        file = 'output.html'
    if isinstance(file, str):
        file = create_new_file_name(file)

    if isinstance(serializer, WidgetSerializer):
        widget_to_html(
            serializer.serialize(**kwargs),
            html_out=file,
            title=get_result_name(serializer.value),
            requirejs=requirejs,
            connected=connected,
        )
    elif isinstance(serializer, HtmlSerializer):
        html = serializer.serialize(  # pylint: disable=redefined-outer-name
            full_html=True,
            include_requirejs=requirejs,
            include_plotlyjs=True,
            connected=connected,
            **kwargs
        )
        if isinstance(file, str):
            with open(file, 'w', encoding='utf-8') as f:
                f.write(html)
        elif isinstance(file, io.TextIOWrapper):
            file.write(html)
        else:
            raise TypeError(f'Unsupported type of "file" parameter - {type(file)}')
    else:
        raise TypeError(f'Unsupported serializer type - {type(serializer)}')

    if isinstance(file, str):
        return file

def tagstr2tree(
    s, chunk_label="NP", root_label="S", sep="/", source_tagset=None, target_tagset=None
):

    WORD_OR_BRACKET = re.compile(r"\[|\]|[^\[\]\s]+")

    stack = [Tree(root_label, [])]
    for match in WORD_OR_BRACKET.finditer(s):
        text = match.group()
        if text[0] == "[":
            if len(stack) != 1:
                raise ValueError(f"Unexpected [ at char {match.start():d}")
            chunk = Tree(chunk_label, [])
            stack[-1].append(chunk)
            stack.append(chunk)
        elif text[0] == "]":
            if len(stack) != 2:
                raise ValueError(f"Unexpected ] at char {match.start():d}")
            stack.pop()
        else:
            if sep is None:
                stack[-1].append(text)
            else:
                word, tag = str2tuple(text, sep)
                if source_tagset and target_tagset:
                    tag = map_tag(source_tagset, target_tagset, tag)
                stack[-1].append((word, tag))

    if len(stack) != 1:
        raise ValueError(f"Expected ] at char {len(s):d}")
    return stack[0]

def invoke(self, ctx: click.Context) -> None:
        try:
            return super().invoke(ctx)
        except click.NoSuchOption as e:
            if e.ctx is not None and e.ctx.command is not None:
                cmd = e.ctx.command
                if isinstance(cmd, click.Group):
                    # Group has no user-facing options -> show subcommands instead
                    items = [
                        (name, sub.get_short_help_str(limit=80))
                        for name in cmd.list_commands(e.ctx)
                        if (sub := cmd.get_command(e.ctx, name)) is not None and not sub.hidden
                    ]
                    _enrich_usage_error(e, "commands", items)
                else:
                    # Leaf command -> show its options using Click's rich formatting
                    items = [
                        record
                        for p in cmd.get_params(e.ctx)
                        if isinstance(p, click.Option) and not p.hidden and (record := p.get_help_record(e.ctx))
                    ]
                    _enrich_usage_error(e, "options", items)
            raise

def online_read(
        self,
        config: RepoConfig,
        table: FeatureView,
        entity_keys: List[EntityKeyProto],
        requested_features: Optional[List[str]] = None,
    ) -> List[Tuple[Optional[datetime], Optional[Dict[str, ValueProto]]]]:
        project = config.project

        result: List[Tuple[Optional[datetime], Optional[Dict[str, ValueProto]]]] = []

        entity_key_bins = [
            serialize_entity_key(
                entity_key,
                entity_key_serialization_version=config.entity_key_serialization_version,
            ).hex()
            for entity_key in entity_keys
        ]

        feature_rows_sequence = self._read_rows_by_entity_keys(
            config,
            project,
            table,
            entity_key_bins,
            columns=["feature_name", "value", "event_ts"],
        )

        for entity_key_bin, feature_rows in zip(entity_key_bins, feature_rows_sequence):
            res = {}
            res_ts = None
            if feature_rows:
                for feature_row in feature_rows:
                    if (
                        requested_features is None
                        or feature_row.feature_name in requested_features
                    ):
                        val = ValueProto()
                        val.ParseFromString(feature_row.value)
                        res[feature_row.feature_name] = val
                        res_ts = feature_row.event_ts
            if not res:
                result.append((None, None))
            else:
                result.append((res_ts, res))
        return result

def check_users_workspaces_active_resources(
        user_ids: List[str],
        workspace_names: List[str]) -> Tuple[str, List[str], Dict[str, str]]:
    all_clusters, all_managed_jobs = _get_active_resources_for_workspaces(
        workspace_names)
    resource_errors = []
    missed_users = set()
    active_cluster_names = []
    active_job_names = []
    # Check clusters
    if all_clusters:
        for cluster in all_clusters:
            user_hash = cluster.get('user_hash')
            if user_hash and user_hash not in user_ids:
                missed_users.add(user_hash)
                active_cluster_names.append(cluster['name'])
        if active_cluster_names:
            cluster_list = ', '.join(active_cluster_names)
            resource_errors.append(
                f'{len(active_cluster_names)} active cluster(s):'
                f' {cluster_list}')

    # Check managed jobs
    if all_managed_jobs:
        for job in all_managed_jobs:
            user_hash = job.get('user_hash')
            if user_hash and user_hash not in user_ids:
                missed_users.add(user_hash)
                active_job_names.append(str(job['job_id']))
        if active_job_names:
            job_list = ', '.join(active_job_names)
            resource_errors.append(f'{len(active_job_names)} active'
                                   f' managed job(s): {job_list}')

    resource_error_summary = ''
    if resource_errors:
        resource_error_summary = ' and '.join(resource_errors)
    missed_users_names = []
    missed_user_dict = {}
    if missed_users:
        all_users = global_user_state.get_all_users()
        for user in all_users:
            if user.id in missed_users:
                missed_users_names.append(user.name if user.name else user.id)
                missed_user_dict[user.id] = user.name if user.name else user.id
    return resource_error_summary, missed_users_names, missed_user_dict

def doesnt_use_pandas_warnings(file_obj: IO[str]) -> Iterable[tuple[int, str]]:
    contents = file_obj.read()
    lines = contents.split("\n")
    tree = ast.parse(contents)
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue

        if isinstance(node.func, ast.Attribute) and isinstance(
            node.func.value, ast.Name
        ):
            # Check for `warnings.warn`.
            if node.func.value.id != "warnings" or node.func.attr != "warn":
                continue
        elif isinstance(node.func, ast.Name):
            # Check for just `warn` when using `from warnings import warn`.
            if node.func.id != "warn":
                continue
        if any(
            "# pdlint: ignore[warning_class]" in lines[k]
            for k in range(node.lineno - 1, node.end_lineno + 1)
        ):
            continue
        values = [arg.id for arg in node.args if isinstance(arg, ast.Name)] + [
            kw.value.id for kw in node.keywords if kw.arg == "category"
        ]
        for value in values:
            matches = re.match(DEPRECATION_WARNINGS_PATTERN, value)
            if matches is not None:
                yield (
                    node.lineno,
                    f"Don't use {matches[0]}, use a pandas-specific warning in "
                    f"pd.errors instead. You can add "
                    f"`# pdlint: ignore[warning_class]` to override.",
                )

def get_versions():
    # I am in _version.py, which lives at ROOT/VERSIONFILE_SOURCE. If we have
    # __file__, we can work backwards from there to the root. Some
    # py2exe/bbfreeze/non-CPython implementations don't do __file__, in which
    # case we can only use expanded keywords.

    cfg = get_config()
    verbose = cfg.verbose

    try:
        return git_versions_from_keywords(get_keywords(), cfg.tag_prefix, verbose)
    except NotThisMethod:
        pass

    try:
        root = os.path.realpath(__file__)
        # versionfile_source is the relative path from the top of the source
        # tree (where the .git directory might live) to this file. Invert
        # this to find the root from __file__.
        for _ in cfg.versionfile_source.split("/"):
            root = os.path.dirname(root)
    except NameError:
        return {
            "version": "0+unknown",
            "full-revisionid": None,
            "dirty": None,
            "error": "unable to find root of source tree",
            "date": None,
        }

    try:
        pieces = git_pieces_from_vcs(cfg.tag_prefix, root, verbose)
        return render(pieces, cfg.style)
    except NotThisMethod:
        pass

    try:
        if cfg.parentdir_prefix:
            return versions_from_parentdir(cfg.parentdir_prefix, root, verbose)
    except NotThisMethod:
        pass

    return {
        "version": "0+unknown",
        "full-revisionid": None,
        "dirty": None,
        "error": "unable to compute version",
        "date": None,
    }

def load_bytes_single(self, tmpdir, key):
        from azure.core.exceptions import ResourceNotFoundError

        try:
            blob = self.get_blob_client(key)
            try:
                blob_properties = blob.get_blob_properties()
            except ResourceNotFoundError:
                # load_bytes() needs to return None for keys that don't exist
                return key, None, None
            tmp_filename = os.path.join(tmpdir, str(uuid.uuid4()))
            try:
                with open(tmp_filename, "wb") as f:
                    blob.download_blob(
                        max_concurrency=AZURE_STORAGE_DOWNLOAD_MAX_CONCURRENCY
                    ).readinto(f)
                metaflow_user_attributes = None
                if (
                    blob_properties.metadata
                    and "metaflow_user_attributes" in blob_properties.metadata
                ):
                    metaflow_user_attributes = json.loads(
                        blob_properties.metadata["metaflow_user_attributes"]
                    )
            except Exception:
                # clean up the tmp file for the one specific failed load
                if os.path.exists(tmp_filename):
                    os.unlink(tmp_filename)
                raise
            return key, tmp_filename, metaflow_user_attributes
        except Exception as e:
            process_exception(e)

def load_objects(to_load: Mapping, checkpoint: str | Mapping | Path, **kwargs: Any) -> None:
        if not isinstance(checkpoint, (Mapping, str, Path)):
            raise TypeError(f"Argument checkpoint should be a string or a dictionary, but given {type(checkpoint)}")

        Checkpoint._check_objects(to_load, "load_state_dict")

        if isinstance(checkpoint, (str, Path)):
            checkpoint_obj = torch.load(checkpoint, weights_only=True)
        else:
            checkpoint_obj = checkpoint

        def _load_object(obj: Any, chkpt_obj: Any) -> None:
            if isinstance(obj, (nn.DataParallel, nn.parallel.DistributedDataParallel)):
                obj = obj.module

            if isinstance(obj, torch.nn.Module):
                obj.load_state_dict(chkpt_obj, **kwargs)
            else:
                obj.load_state_dict(chkpt_obj)

        if len(to_load) == 1:
            # single object and checkpoint is directly a state_dict
            key, obj = list(to_load.items())[0]
            if key not in checkpoint_obj:
                _load_object(obj, checkpoint_obj)
                return

        _tree_apply2(_load_object, to_load, checkpoint_obj)

def destroy_group(self):
        if len(self._dev_comm_map.keys()) > 0:

            # TODO(Hao): check this barrier call
            # self.barrier()

            # Destroy the communicators and streams.
            for comm_key, comms in self._dev_comm_map.items():
                for c in comms:
                    # FIXME(yonghao): comms created in XLA should be destroied
                    if hasattr(c, "destroy"):
                        c.destroy()
                self._dev_comm_map[comm_key] = None

        if self.rank == 0:
            for comm_key in self._dev_comm_map:
                assert not self._dev_comm_map[comm_key]
                group_key = self._generate_group_key(comm_key)
                self._destroy_store(group_key)
        self._barrier_tensor = None
        self._dev_comm_map = None
        self._dev_streams_map = None

def list_documents_in_collection(
        self, collection_name: str, base_document_id: str = None
    ) -> List[str]:
        logger.debug(
            f"[Mongo] Listing all documents with base document id {base_document_id} for collection {collection_name}"
        )
        stop = False
        offset = None
        document_ids_set = set()
        collection = self.db[collection_name]

        while stop is not True:
            batch_cursor = (
                collection.find(
                    {f"metadata.{DATA_POINT_FQN_METADATA_KEY}": base_document_id}
                    if base_document_id
                    else {},
                    {f"metadata.{DATA_POINT_FQN_METADATA_KEY}": 1},
                )
                .skip(offset if offset else 0)
                .limit(BATCH_SIZE)
            )

            # Convert cursor to list to check if we got any results
            batch_results = list(batch_cursor)
            if not batch_results:
                stop = True
                break

            for doc in batch_results:
                if doc.get("metadata") and doc.get("metadata").get(
                    DATA_POINT_FQN_METADATA_KEY
                ):
                    document_ids_set.add(
                        doc.get("metadata").get(DATA_POINT_FQN_METADATA_KEY)
                    )
                if len(document_ids_set) > MAX_SCROLL_LIMIT:
                    stop = True
                    break

            if len(batch_results) < BATCH_SIZE:
                stop = True
            else:
                offset = (offset if offset else 0) + BATCH_SIZE

        logger.debug(
            f"[Mongo] Found {len(document_ids_set)} documents with base document id {base_document_id} for collection {collection_name}"
        )
        return list(document_ids_set)

def fix_mask_conflict(masks, model, dummy_input, traced=None):
    if isinstance(masks, str):
        # if the input is the path of the mask_file
        assert os.path.exists(masks)
        masks = torch.load(masks)
    assert len(masks) > 0, 'Mask tensor cannot be empty'
    # if the user uses the model and dummy_input to trace the model, we
    # should get the traced model handly, so that, we only trace the
    # model once, GroupMaskConflict and ChannelMaskConflict will reuse
    # this traced model.
    if traced is None:
        assert model is not None and dummy_input is not None
        training = model.training
        # We need to trace the model in eval mode
        model.eval()
        kw_args = {}
        if torch.__version__ >= '1.6.0':
            # only pytorch with version greater than 1.6.0 has the strict option
            kw_args['strict'] = False
        try:
            import pytorch_lightning as pl
        except ImportError:
            is_lightning_module = False
        else:
            if isinstance(model, pl.LightningModule):
                is_lightning_module = True
            else:
                is_lightning_module = False
        if is_lightning_module:
            traced = model.to_torchscript(method="trace", example_inputs=dummy_input, **kw_args)
        else:
            traced = torch.jit.trace(model, dummy_input, **kw_args)
        model.train(training)

    fix_group_mask = GroupMaskConflict(masks, model, dummy_input, traced)
    masks = fix_group_mask.fix_mask()
    fix_channel_mask = ChannelMaskConflict(masks, model, dummy_input, traced)
    masks = fix_channel_mask.fix_mask()
    return masks

def convert_wire_order(tape, wire_order=None, show_all_wires=False):
    full_wire_map, used_wire_map = default_wire_map(tape)

    if wire_order is None:
        # If no external wire order is dictated, the tape ordering is all we need to consider
        return full_wire_map, used_wire_map

    # Create wire order complemented by all wires in the tape mapping that are not in the order yet
    full_wire_order = list(wire_order) + [wire for wire in full_wire_map if wire not in wire_order]
    used_wire_order = list(wire_order) + [wire for wire in used_wire_map if wire not in wire_order]

    if not show_all_wires:
        # Filter out wires that are in wire_order but not in full_wire_map/used_wire_map
        full_wire_order = [wire for wire in full_wire_order if wire in full_wire_map]
        used_wire_order = [wire for wire in used_wire_order if wire in used_wire_map]

    # Create consecutive integer mapping from ordered list
    full_wire_map = {wire: ind for ind, wire in enumerate(full_wire_order)}
    used_wire_map = {wire: ind for ind, wire in enumerate(used_wire_order)}

    return full_wire_map, used_wire_map

def convert_data_type(torch_type: torch.TensorType) -> TensorType:
    if torch_type == torch.float32:
        return TensorType.FLOAT32

    elif torch_type == torch.uint8:
        return TensorType.UINT8

    elif torch_type == torch.int8:
        return TensorType.INT8

    elif torch_type == torch.int32:
        return TensorType.INT32

    elif torch_type == torch.int64:
        return TensorType.INT64

    elif torch_type == torch.bool:
        return TensorType.BOOL

    else:
        logger.e(
            logger.Code.NOT_IMPLEMENTED,
            f"Conversion of Torch type '{torch_type}' not supported.",
        )

def preprocess_examples(
        self,
        texts: TextInput | list[TextInput],
        images: ImageInput | None = None,
        bboxes: BboxInput = None,
        num_image_tokens: int | None = 64,
    ) -> str | list[str]:
        # These are fake `<image>` tokens enclosed between (the actual) `<image>` token and `</image>`.
        img_tokens = [self.boi_token] * num_image_tokens
        img_info_tokens = " ".join([self.boi_token] + img_tokens + [self.eoi_token])

        # make batch to simplify processing logic
        batched = True
        if isinstance(texts, str):
            batched = False
            texts = [texts]

        if images is None:
            images = [None] * len(texts)
        elif not isinstance(images, list):
            images = [images]
        if len(texts) != len(images):
            raise ValueError(
                f"The number of examples in `texts` and `images` should be the same. Got {len(texts)} v.s. {len(images)} instead."
            )

        if not batched:
            self._check_bboxes_for_single_text(bboxes)
            bboxes = [bboxes]
        elif bboxes is not None:
            if not isinstance(bboxes, list):
                raise ValueError("`bboxes` should be `None` or a list (as a batch) when `texts` is passed as a batch.")
            for x in bboxes:
                self._check_bboxes_for_single_text(x)
        else:
            bboxes = [None] * len(texts)

        if len(bboxes) != len(texts):
            raise ValueError(
                f"The number of examples in `texts` and `bboxes` should be the same. Got {len(texts)} v.s. {len(bboxes)} instead."
            )

        result = [
            self._preprocess_single_example(text, image, bbox, img_info_tokens)
            for text, image, bbox in zip(texts, images, bboxes)
        ]
        # un-batch if necessary
        if not batched:
            result = result[0]

        return result

def update_preconditioner(
        self,
        grad,
        state,
        max_precond_dim=10000,
        merge_dims=False,
        precondition_1d=False,
    ):
        if grad.dim() == 1:
            if precondition_1d and grad.shape[0] <= max_precond_dim:
                state["GG"][0].lerp_(grad.unsqueeze(1) @ grad.unsqueeze(0), 1 - state["shampoo_beta"])
        else:
            if merge_dims:
                new_grad = self.merge_dims(grad, max_precond_dim)
                for idx, sh in enumerate(new_grad.shape):
                    if sh <= max_precond_dim:
                        outer_product = torch.tensordot(
                            new_grad,
                            new_grad,
                            dims=[[*chain(range(idx), range(idx + 1, len(new_grad.shape)))]] * 2,
                        )
                        state["GG"][idx].lerp_(outer_product, 1 - state["shampoo_beta"])
            else:
                for idx, sh in enumerate(grad.shape):
                    if sh <= max_precond_dim:
                        outer_product = torch.tensordot(
                            grad,
                            grad,
                            # Contracts across all dimensions except for k.
                            dims=[[*chain(range(idx), range(idx + 1, len(grad.shape)))]] * 2,
                        )
                        state["GG"][idx].lerp_(
                            outer_product.to(state["GG"][idx].dtype),
                            1 - state["shampoo_beta"],
                        )

        if state["Q"] is None:
            state["Q"] = self.get_orthogonal_matrix(state["GG"])
        if state["step"] > 0 and state["step"] % state["precondition_frequency"] == 0:
            state["Q"] = self.get_orthogonal_matrix_QR(state, max_precond_dim, merge_dims)

def save_swarm_metadata(
    swarm_instance: Any,
    swarm_workspace_dir: str,
    execution_result: Optional[Any] = None,
    execution_metadata: Optional[Dict[str, Any]] = None,
) -> Optional[str]:
    if not swarm_workspace_dir:
        return None

    try:
        metadata_dict = {
            "execution_timestamp": datetime.now().isoformat(),
            "swarm_name": getattr(swarm_instance, "name", "unnamed"),
            "swarm_id": getattr(swarm_instance, "id", None),
            "swarm_type": getattr(swarm_instance, "swarm_type", None),
            "max_loops": getattr(swarm_instance, "max_loops", None),
            "agents_count": (
                len(swarm_instance.agents)
                if hasattr(swarm_instance, "agents")
                else 0
            ),
        }

        # Add execution result summary
        if execution_result is not None:
            if isinstance(execution_result, (str, int, float, bool)):
                metadata_dict["execution_result_summary"] = str(
                    execution_result
                )
            elif isinstance(execution_result, (list, dict)):
                metadata_dict["execution_result_summary"] = {
                    "type": type(execution_result).__name__,
                    "length": len(execution_result),
                }
            else:
                metadata_dict["execution_result_summary"] = str(
                    type(execution_result).__name__
                )

        # Add additional execution metadata if provided
        if execution_metadata:
            metadata_dict.update(execution_metadata)

        # Convert to JSON string
        metadata_json = json.dumps(
            metadata_dict, indent=2, default=str
        )

        # Save to file
        metadata_path = create_file_in_folder(
            swarm_workspace_dir, "metadata.json", metadata_json
        )

        if metadata_path:
            logger.debug(f"Saved swarm metadata to {metadata_path}")
        return metadata_path

    except Exception as e:
        logger.warning(f"Failed to save swarm metadata: {e}")
        return None

def remove_callback(self, event, func=None):
        if event is None:
            events = list(self._callbacks.keys())
        elif event == "select":
            events = ["click1", "space", "return"]
        elif event == "move":
            events = ["up", "down", "next", "prior"]
        else:
            events = [event]

        for e in events:
            if func is None:
                del self._callbacks[e]
            else:
                try:
                    del self._callbacks[e][func]
                except KeyError:
                    pass

def update_metrics(
        self,
        targets: Tensor,
        predictions: dict[str, Tensor],
        tokenizer: PreTrainedTokenizer | None = None,
    ) -> None:
        if tokenizer is not None:
            # Decode the targets and predictions to compute response-based metrics using the initialized tokenizer.
            decoded_targets, decoded_predictions = get_decoded_targets_and_predictions(targets, predictions, tokenizer)

        for metric_name, metric_fn in self._metric_functions.items():
            prediction_key = get_metric_tensor_input(metric_name)
            try:
                if prediction_key == RESPONSE:
                    if tokenizer is not None:
                        # RESPONSE metrics cannot be computed if decoded texts are not provided.
                        # Decoded texts are only provided using the LLM model type.
                        if decoded_targets is not None and decoded_predictions is not None:
                            # Move metric function to the device of the predictions.
                            # For CUDA, it can be computed on any of the GPUs since it uses allgather to collect
                            # the results from all GPUs and compute the final metric.
                            # We use 'predictions' as the key since it is always present in the predictions dict.
                            device = "cuda" if predictions["predictions"].is_cuda else "cpu"
                            metric_fn = metric_fn.to(device)
                            if metric_name == "bleu":
                                # BLEU takes in targets as a list.
                                metric_fn.update(decoded_predictions, [decoded_targets])
                            else:
                                metric_fn.update(decoded_predictions, decoded_targets)
                else:
                    metric_fn = metric_fn.to(predictions[prediction_key].device)
                    metric_fn.update(predictions[prediction_key].detach(), targets)
            except Exception as e:
                logger.info(f"Ran into error when calculating metric {metric_name}. Skipping. The error is: {e}")

def init(repo, yes, skip_if_exists):
    repo_path = clean_repo_path(repo) or os.getcwd()
    re_init = False
    if Repo.exists(repo_path):
        if yes and skip_if_exists:
            raise click.BadParameter('Conflicting init options.Either specify -y/--yes or -s/--skip-if-exists')
        elif yes:
            re_init = True
        elif skip_if_exists:
            click.echo('Repo exists at {}. Skipped initialization.'.format(repo_path))
            return
        else:
            re_init = click.confirm(
                'Aim repository is already initialized. Do you want to re-initialize to empty Aim repository?'
            )
        if not re_init:
            return
        # Clear old repo
        Repo.rm(repo_path)

    repo = Repo.from_path(repo_path, init=True)
    if re_init:
        click.echo('Re-initialized empty Aim repository at {}'.format(repo.root_path))
    else:
        click.echo('Initialized a new Aim repository at {}'.format(repo.root_path))

def list_evaluators() -> list[dict]:
    results: list[dict] = []

    # User-registered evaluators
    for name, info in sorted(_load_user_evaluators().items()):
        results.append(
            {
                "name": name,
                "source": "registered",
                "type": info["import_path"],
            }
        )

    # Built-in evaluators from registry
    seen_names = {r["name"] for r in results}
    for name, cls in sorted(_EVALUATOR_REGISTRY.items()):
        if name not in seen_names:
            results.append(
                {
                    "name": name,
                    "source": "built-in",
                    "type": f"{cls.__module__}.{cls.__name__}",
                }
            )

    # Plugin evaluators from entry points
    seen_names = {r["name"] for r in results}
    eps = entry_points(group="rllm.evaluators")
    for ep in eps:
        if ep.name not in seen_names:
            pkg = ep.dist.name if ep.dist else "unknown"
            results.append(
                {
                    "name": ep.name,
                    "source": f"plugin ({pkg})",
                    "type": str(ep.value),
                }
            )

    return results

def observable(fermion_ops, init_term=0, mapping="jordan_wigner", wires=None):
    openfermion, _ = _import_of()

    mapping = mapping.strip().lower()

    if mapping not in ("jordan_wigner", "parity", "bravyi_kitaev"):
        raise TypeError(
            f"The '{mapping}' transformation is not available. \n "
            f"Please set 'mapping' to 'jordan_wigner', 'parity', or 'bravyi_kitaev'."
        )

    # Initialize the FermionOperator
    mb_obs = openfermion.ops.FermionOperator("") * init_term
    for ops in fermion_ops:
        if not isinstance(ops, openfermion.ops.FermionOperator):
            raise TypeError(
                f"Elements in the lists are expected to be of type 'FermionOperator'; got {type(ops)}"
            )
        mb_obs += ops

    # Map the fermionic operator to a qubit operator
    if mapping == "bravyi_kitaev":
        return qml.qchem.convert.import_operator(
            openfermion.transforms.bravyi_kitaev(mb_obs), wires=wires
        )

    if mapping == "parity":
        qubits = openfermion.count_qubits(mb_obs)
        if qubits == 0:
            return 0.0 * qml.I(0)
        binary_code = openfermion.parity_code(qubits)
        return qml.qchem.convert.import_operator(
            openfermion.transforms.binary_code_transform(mb_obs, binary_code), wires=wires
        )

    return qml.qchem.convert.import_operator(
        openfermion.transforms.jordan_wigner(mb_obs), wires=wires
    )

def retain_active_states(self, active_variables: set[str]) -> None:
        # Remove all non-active states by name
        active_state_ids = set()
        for state_key in list(self._states.keys()):
            if extract_name(state_key) not in active_variables:
                id_key = id(self._states[state_key])
                lookup = self._inv_states.get(id_key, None)
                if lookup is not None:
                    if state_key in lookup:
                        lookup.remove(state_key)
                    if not lookup:
                        del self._inv_states[id_key]
                del self._states[state_key]
            else:
                active_state_ids.add(id(self._states[state_key]))

        # Remove all non-active states by id
        for state_id in list(self._inv_states.keys()):
            if state_id not in active_state_ids:
                del self._inv_states[state_id]

def get_tokens(self, text, unfiltered=False):
        if not isinstance(text, text_type):
            if self.encoding == 'guess':
                text, _ = guess_decode(text)
            elif self.encoding == 'chardet':
                try:
                    import chardet
                except ImportError:
                    raise ImportError('To enable chardet encoding guessing, '
                                      'please install the chardet library '
                                      'from http://chardet.feedparser.org/')
                # check for BOM first
                decoded = None
                for bom, encoding in _encoding_map:
                    if text.startswith(bom):
                        decoded = text[len(bom):].decode(encoding, 'replace')
                        break
                # no BOM found, so use chardet
                if decoded is None:
                    enc = chardet.detect(text[:1024])  # Guess using first 1KB
                    decoded = text.decode(enc.get('encoding') or 'utf-8',
                                          'replace')
                text = decoded
            else:
                text = text.decode(self.encoding)
                if text.startswith(u'\ufeff'):
                    text = text[len(u'\ufeff'):]
        else:
            if text.startswith(u'\ufeff'):
                text = text[len(u'\ufeff'):]

        # text now *is* a unicode string
        text = text.replace('\r\n', '\n')
        text = text.replace('\r', '\n')
        if self.stripall:
            text = text.strip()
        elif self.stripnl:
            text = text.strip('\n')
        if self.tabsize > 0:
            text = text.expandtabs(self.tabsize)
        if self.ensurenl and not text.endswith('\n'):
            text += '\n'

        def streamer():
            for _, t, v in self.get_tokens_unprocessed(text):
                yield t, v
        stream = streamer()
        if not unfiltered:
            stream = apply_filters(stream, self.filters, self)
        return stream

def format_field_names(self):
        for resource_name, schema in self.full_schema["properties"].items():
            for field_name, data_type in schema["properties"].items():
                # Move ad_group_ad.ad.x fields up a level in the schema (ad_group_ad.ad.x -> ad_group_ad.x)
                if resource_name == "ad_group_ad" and field_name == "ad":
                    for ad_field_name, ad_field_schema in data_type["properties"].items():
                        self.stream_schema["properties"][ad_field_name] = ad_field_schema
                elif resource_name not in {"metrics", "segments"}:
                    self.stream_schema["properties"][f"{resource_name}_{field_name}"] = data_type
                else:
                    self.stream_schema["properties"][field_name] = data_type

def parse_directory_to_df(
    directory_path: str, extra_columns_parser: Optional[Callable[[str, str], dict]] = None
) -> pl.DataFrame:
    all_dataframes = []
    for root, _dirs, files in os.walk(directory_path):
        for file_name in files:
            if file_name.endswith('.log'):
                process_uuid = file_name.replace('.log', '')
                file_path = os.path.join(root, file_name)
                with open(file_path, 'r') as file:
                    log_contents = file.read()
                    df = parse_log_to_polars(log_contents, process_uuid)

                    extra_columns = pipeline_block_columns_parser(directory_path, file_path)

                    if extra_columns_parser:
                        extra_columns.update(extra_columns_parser(directory_path, file_path) or {})

                    if extra_columns:
                        for col, val in extra_columns.items():
                            df = df.with_columns((pl.lit(val)).alias(col))

                    all_dataframes.append(df)

    if all_dataframes:
        final_df = pl.concat(all_dataframes)
        return final_df
    else:
        return pl.DataFrame(
            [],
            schema=DEFAULT_SCHEMA,
        )

def remove_tasks(  # noqa: C901, PLR0912
    celery_queue: "LocalCeleryQueue",
    queue_entries: Iterable["QueueEntry"],
):
    from celery.result import AsyncResult

    stash_revs: dict[str, ExpStashEntry] = {}
    failed_stash_revs: list[ExpStashEntry] = []
    done_entry_set: set[QueueEntry] = set()
    stash_rev_all = celery_queue.stash.stash_revs
    failed_rev_all: dict[str, ExpStashEntry] = {}
    if celery_queue.failed_stash:
        failed_rev_all = celery_queue.failed_stash.stash_revs
    for entry in queue_entries:
        if entry.stash_rev in stash_rev_all:
            stash_revs[entry.stash_rev] = stash_rev_all[entry.stash_rev]
        else:
            done_entry_set.add(entry)
            if entry.stash_rev in failed_rev_all:
                failed_stash_revs.append(failed_rev_all[entry.stash_rev])

    try:
        for msg, queue_entry in celery_queue._iter_queued():
            if queue_entry.stash_rev in stash_revs and msg.delivery_tag:
                celery_queue.celery.reject(msg.delivery_tag)
    finally:
        celery_queue.stash.remove_revs(list(stash_revs.values()))

    try:
        for msg, queue_entry in celery_queue._iter_processed():
            if queue_entry not in done_entry_set:
                continue
            task_id = msg.headers["id"]
            result: AsyncResult = AsyncResult(task_id)
            if result is not None:
                result.forget()
            if msg.delivery_tag:
                celery_queue.celery.purge(msg.delivery_tag)
    finally:
        if celery_queue.failed_stash:
            celery_queue.failed_stash.remove_revs(failed_stash_revs)

def autoscale(self, enable=True, axis='both', tight=None):
        if enable is None:
            scalex = True
            scaley = True
            scalez = True
        else:
            if axis in ['x', 'both']:
                self.set_autoscalex_on(enable)
                scalex = self.get_autoscalex_on()
            else:
                scalex = False
            if axis in ['y', 'both']:
                self.set_autoscaley_on(enable)
                scaley = self.get_autoscaley_on()
            else:
                scaley = False
            if axis in ['z', 'both']:
                self.set_autoscalez_on(enable)
                scalez = self.get_autoscalez_on()
            else:
                scalez = False
        if scalex:
            self._request_autoscale_view("x", tight=tight)
        if scaley:
            self._request_autoscale_view("y", tight=tight)
        if scalez:
            self._request_autoscale_view("z", tight=tight)

def setup(entity: str | None, project: str | None) -> None:
    # We can't or shouldn't init weave; return
    if os.getenv(_DISABLE_WEAVE):
        return
    if not project:
        return

    # Use entity/project when available; otherwise fall back to project only
    if entity:
        project_path = f"{entity}/{project}"
    else:
        project_path = project

    # If weave is not yet imported, we can't init it from here.  Instead, we'll
    # rely on the weave library itself to detect a run and init itself.
    if _WEAVE_PACKAGE_NAME not in sys.modules:
        _maybe_suggest_weave_installation()
        return

    # If weave has already been imported, initialize immediately
    wandb.termlog("Initializing weave.")
    try:
        _weave_init(project_path)
    except Exception as e:
        wandb.termwarn(f"Failed to automatically initialize weave: {e}")

def get_upstream_assets_for_node(
    node: DbtNode,
    all_nodes: dict[str, DbtNode],
    adapter_type: str,
) -> list[Asset]:
    # Collect asset-eligible dep IDs by walking through ephemerals.
    # The resolved node's depends_on may have had sources stripped
    # during dependency resolution, so start from the original
    # (unresolved) node when available.
    original_node = all_nodes.get(node.unique_id)
    start_deps: set[str] = set(node.depends_on)
    if original_node is not None:
        start_deps |= set(original_node.depends_on)

    collected: list[str] = []
    visited: set[str] = set()

    def _walk(dep_id: str) -> None:
        if dep_id in visited:
            return
        visited.add(dep_id)

        dep_node = all_nodes.get(dep_id)
        if dep_node is None:
            return

        # Trace through ephemeral models to their dependencies.
        if dep_node.materialization == "ephemeral":
            for nested_dep in dep_node.depends_on:
                _walk(nested_dep)
            return

        if dep_node.resource_type in _UPSTREAM_ASSET_TYPES and dep_node.relation_name:
            collected.append(dep_id)

    for dep_id in start_deps:
        _walk(dep_id)

    assets: list[Asset] = []
    for dep_id in collected:
        dep_node = all_nodes[dep_id]
        asset_key = format_resource_id(adapter_type, dep_node.relation_name)
        assets.append(
            Asset(
                key=asset_key,
                properties=AssetProperties(name=dep_node.name),
            )
        )
    return assets

def fit(self, X, y):
        self._fit(X, y)

        classes_ = self.classes_
        _y = self._y
        if not self.outputs_2d_:
            _y = self._y.reshape((-1, 1))
            classes_ = [self.classes_]

        if self.outlier_label is None:
            outlier_label_ = None

        elif self.outlier_label == "most_frequent":
            outlier_label_ = []
            # iterate over multi-output, get the most frequent label for each
            # output.
            for k, classes_k in enumerate(classes_):
                label_count = np.bincount(_y[:, k])
                outlier_label_.append(classes_k[label_count.argmax()])

        else:
            if _is_arraylike(self.outlier_label) and not isinstance(
                self.outlier_label, str
            ):
                if len(self.outlier_label) != len(classes_):
                    raise ValueError(
                        "The length of outlier_label: {} is "
                        "inconsistent with the output "
                        "length: {}".format(self.outlier_label, len(classes_))
                    )
                outlier_label_ = self.outlier_label
            else:
                outlier_label_ = [self.outlier_label] * len(classes_)

            for classes, label in zip(classes_, outlier_label_):
                if _is_arraylike(label) and not isinstance(label, str):
                    # ensure the outlier label for each output is a scalar.
                    raise TypeError(
                        "The outlier_label of classes {} is "
                        "supposed to be a scalar, got "
                        "{}.".format(classes, label)
                    )
                if np.append(classes, label).dtype != classes.dtype:
                    # ensure the dtype of outlier label is consistent with y.
                    raise TypeError(
                        "The dtype of outlier_label {} is "
                        "inconsistent with classes {} in "
                        "y.".format(label, classes)
                    )

        self.outlier_label_ = outlier_label_

        return self

def decompose_mcx(
    control_wires,
    target_wire,
    work_wires,
    work_wire_type: Literal["zeroed", "borrowed"] = "borrowed",
):

    n_ctrl_wires, n_work_wires = len(control_wires), len(work_wires)
    if n_ctrl_wires == 1:
        return [qml.CNOT(wires=control_wires + Wires(target_wire))]
    if n_ctrl_wires == 2:
        return qml.Toffoli.compute_decomposition(wires=control_wires + Wires(target_wire))

    if n_work_wires >= n_ctrl_wires - 2:
        # Lemma 7.2 of `Barenco et al. (1995) <https://arxiv.org/abs/quant-ph/9503016>`_
        return _decompose_mcx_with_many_workers_old(
            control_wires, target_wire, work_wires, work_wire_type
        )
    if n_work_wires >= 2:
        return _decompose_mcx_with_two_workers_old(
            control_wires, target_wire, work_wires[0:2], work_wire_type
        )
    if n_work_wires == 1:
        return _decompose_mcx_with_one_worker_kg24(
            control_wires, target_wire, work_wires[0], work_wire_type
        )

    # Lemma 7.5
    with qml.QueuingManager.stop_recording():
        op = qml.X(target_wire)
    return _decompose_multicontrolled_unitary(op, control_wires)

def list_command(
    manifest_path: str,
    tag_filter: Optional[str],
    show_columns: bool,
):
    from feast.dbt.parser import DbtManifestParser

    click.echo(f"{Fore.CYAN}Parsing dbt manifest: {manifest_path}{Style.RESET_ALL}")

    try:
        parser = DbtManifestParser(manifest_path)
        parser.parse()
    except (FileNotFoundError, ValueError) as e:
        click.echo(f"{Fore.RED}Error: {e}{Style.RESET_ALL}", err=True)
        raise SystemExit(1)

    if parser.dbt_version:
        click.echo(f"  dbt version: {parser.dbt_version}")
    if parser.project_name:
        click.echo(f"  Project: {parser.project_name}")

    models = parser.get_models(tag_filter=tag_filter)

    if not models:
