                click.echo(f"    - {col.name}: {type_str}")

        click.echo()

def strided_set(a, v, begin, end, strides=None):
    n = len(a.shape)

    if len(begin.shape) != 1:
        raise ValueError("begin should be a vector")
    if not begin.dtype == "int32":
        raise TypeError("begin should be int32")
    if len(end.shape) != 1:
        raise ValueError("end should be a vector")
    if not end.dtype == "int32":
        raise TypeError("end should be int32")
    if strides is not None:
        if len(strides.shape) != 1:
            raise ValueError("strides should be a vector")
        if not strides.dtype == "int32":
            raise TypeError("strides should be int32")

    def _max(a, b):
        return tvm.tirx.Select(a > b, a, b)

    if strides is None:
        strides = [tvm.tirx.const(1, "int32")] * n
    else:
        strides = [
            tvm.tirx.if_then_else(strides.shape[0] > i, strides[i], tvm.tirx.const(1, "int32"))
            for i in range(n)
        ]

    begin = [
        tvm.tirx.if_then_else(
            begin.shape[0] > i,
            begin[i],
            tvm.tirx.Select(strides[i] > 0, tvm.tirx.const(0, "int32"), a.shape[i]),
        )
        for i in range(n)
    ]
    end = [
        tvm.tirx.if_then_else(
            end.shape[0] > i,
            end[i],
            tvm.tirx.Select(strides[i] > 0, a.shape[i] + 1, -(a.shape[i] + 1)),
        )
        for i in range(n)
    ]

    # Convert negative indexes
    for i in range(n):
        begin[i] = tvm.tirx.if_then_else(begin[i] < 0, begin[i] + a.shape[i], begin[i])
        end[i] = tvm.tirx.if_then_else(end[i] < 0, end[i] + a.shape[i], end[i])

    def _select(*indices):
        from_val = []
        index_tuple = []
        for i in range(n):
            from_val.append(within_index(begin[i], end[i], strides[i], indices[i]))
            index_tuple.append(make_idx(begin[i], end[i], strides[i], a.shape[i], indices[i]))
        return tvm.tirx.if_then_else(tvm.tirx.all(*from_val), v(*index_tuple), a(*indices))

    return te.compute(a.shape, _select, name="strided_set")

def check_series(
    Z,
    enforce_univariate=False,
    enforce_multivariate=False,
    allow_empty=False,
    allow_numpy=True,
    allow_None=True,
    enforce_index_type=None,
    allow_index_names=False,
    var_name="input",
):
    if Z is None:
        if allow_None:
            return Z
        else:
            raise ValueError(var_name + " cannot be None")

    # Check if pandas series or numpy array
    if not allow_numpy:
        valid_data_types = tuple(
            filter(lambda x: x is not np.ndarray, VALID_DATA_TYPES)
        )
    else:
        valid_data_types = VALID_DATA_TYPES

    if not isinstance(Z, valid_data_types):
        raise TypeError(
            f"{var_name} must be a one of {valid_data_types}, but found type: {type(Z)}"
        )

    if enforce_univariate and enforce_multivariate:
        raise ValueError(
            "`enforce_univariate` and `enforce_multivariate` cannot both be set to "
            "True."
        )

    if enforce_univariate:
        _check_is_univariate(Z, var_name=var_name)

    if enforce_multivariate:
        _check_is_multivariate(Z, var_name=var_name)

    # check time index if input data is not an NumPy ndarray
    if not isinstance(Z, np.ndarray):
        check_time_index(
            Z.index,
            allow_empty=allow_empty,
            enforce_index_type=enforce_index_type,
            var_name=var_name,
        )

    if not allow_index_names and not isinstance(Z, np.ndarray):
        Z.index.names = [None for name in Z.index.names]

    return Z

def compute_grpo_advantages(self, group_rewards: list[float]) -> list[float]:
        if not group_rewards:
            return []

        def calculate_mean_and_std(valid_group_rewards: list[float]) -> tuple[float, float]:
            if len(valid_group_rewards) == 1:
                return 0.0, 1.0

            mean_reward = sum(valid_group_rewards) / len(valid_group_rewards)
            std_reward = np.std(valid_group_rewards)
            return mean_reward, float(std_reward)

        valid_group_rewards = [r for r in group_rewards if r is not None]
        mean_reward, std_reward = calculate_mean_and_std(valid_group_rewards)

        advantages = [(r - mean_reward) / std_reward if r is not None else float("inf") for r in group_rewards]
        # we take any entry with "inf" as the lowest advantage possible in this group.
        lowest_advantage = min(advantages)
        advantages = [a if a != float("inf") else lowest_advantage for a in advantages]
        return advantages

def shutdown(self) -> None:
        # Shutdown sandbox orchestrator first
        if self.sandbox_orchestrator is not None:
            try:
                import asyncio

                loop = asyncio.get_event_loop()
                if loop.is_running():
                    loop.create_task(self.sandbox_orchestrator.shutdown())
                else:
                    loop.run_until_complete(self.sandbox_orchestrator.shutdown())
            except Exception:
                pass
            self.sandbox_orchestrator = None

        if self.proxy_manager is not None:
            self.proxy_manager.shutdown_proxy()
            self.proxy_manager = None
        # Best-effort close of the connection pool
        try:
            import asyncio

            loop = asyncio.get_event_loop()
            if loop.is_running():
                loop.create_task(self._close_store())
            else:
                loop.run_until_complete(self._close_store())
        except Exception:
            pass

def generate_possible_configs(config_options: dict[str, Any]):
    # The number of configs to generate is the max length of the lists of samples over all parameters.
    num_configs = 1
    for parameter_name in config_options:
        if isinstance(config_options[parameter_name], list):
            num_configs = max(num_configs, len(config_options[parameter_name]))
            config_options[parameter_name] = deque(config_options[parameter_name])

    for _ in range(num_configs):
        config = {}
        for parameter_name in config_options:
            # if parameter is regular parameter with explored values.
            if config_options[parameter_name] and not isinstance(config_options[parameter_name], str):
                config[parameter_name] = config_options[parameter_name].popleft()
            # case for parameters where we don't have choices such as `encoder.type: parallel_cnn` that
            # cause the downstream parameters to change.
            elif isinstance(config_options[parameter_name], str):
                config[parameter_name] = config_options[parameter_name]
        yield create_nested_dict(config)

def preprocess():
    text = open("./_sources/reference.rst", "r").read()
    os.remove("./_sources/reference.rst")

    if not os.path.exists("./_sources/reference"):
        os.makedirs("./_sources/reference")

    def pairwise(iterable):
        "s -> (s0, s1), (s2, s3), (s4, s5), ..."

        iteration = iter(iterable)
        return izip(iteration, iteration)

    sections = map(str.strip, re.split(r"<!--\s*(.+)\s*-->", text))
    for section, content in pairwise(sections[1:]):
        if section.endswith(".proto"):
            section_name = section[: -len(".proto")]
            file_name = "./_sources/reference/{0}.rst".format(section_name)
            with open(file_name, "w") as f:
                f.truncate()
                f.write(content)
                f.close()

def flatten(self, max_depth=16) -> "Features":
        for depth in range(1, max_depth):
            no_change = True
            flattened = self.copy()
            for column_name, subfeature in self.items():
                if isinstance(subfeature, dict):
                    no_change = False
                    flattened.update({f"{column_name}.{k}": v for k, v in subfeature.items()})
                    del flattened[column_name]
                elif hasattr(subfeature, "flatten") and subfeature.flatten() != subfeature:
                    no_change = False
                    flattened.update({f"{column_name}.{k}": v for k, v in subfeature.flatten().items()})
                    del flattened[column_name]
            self = flattened
            if no_change:
                break
        return self

def flat_content(self) -> str | None:
        if self.content is None:
            return None
        if isinstance(self.content, str):
            return self.content
        # Flatten [{"type": "text", "text": "..."}, ...] arrays
        parts: list[str] = []
        for block in self.content:
            if isinstance(block, dict):
                text = block.get("text")
                if text:
                    parts.append(text)
            elif isinstance(block, str):
                parts.append(block)
        return "\n".join(parts) if parts else None

def get_models(
        self,
        model_names: Optional[List[str]] = None,
        tag_filter: Optional[str] = None,
    ) -> List[DbtModel]:
        if self._parsed_manifest is None:
            self.parse()

        if self._parsed_manifest is None:
            return []

        models = []
        nodes = getattr(self._parsed_manifest, "nodes", {}) or {}

        for node_id, node in nodes.items():
            # Only process models (not tests, seeds, snapshots, etc.)
            if not node_id.startswith("model."):
                continue

            model = self._extract_model_from_node(node_id, node)
            if model is None:
                continue

            # Filter by model names if specified
            if model_names and model.name not in model_names:
                continue

            # Filter by tag if specified
            if tag_filter and tag_filter not in model.tags:
                continue

            models.append(model)

        return models

def loss(self, batch, preds=None):
        if not hasattr(self, "criterion"):
            self.criterion = self.init_criterion()

        img = batch["img"]
        # NOTE: preprocess gt_bbox and gt_labels to list.
        bs = img.shape[0]
        batch_idx = batch["batch_idx"]
        gt_groups = [(batch_idx == i).sum().item() for i in range(bs)]
        targets = {
            "cls": batch["cls"].to(img.device, dtype=torch.long).view(-1),
            "bboxes": batch["bboxes"].to(device=img.device),
            "batch_idx": batch_idx.to(img.device, dtype=torch.long).view(-1),
            "gt_groups": gt_groups,
        }

        if preds is None:
            preds = self.predict(img, batch=targets)
        dec_bboxes, dec_scores, enc_bboxes, enc_scores, dn_meta = preds if self.training else preds[1]
        if dn_meta is None:
            dn_bboxes, dn_scores = None, None
        else:
            dn_bboxes, dec_bboxes = torch.split(dec_bboxes, dn_meta["dn_num_split"], dim=2)
            dn_scores, dec_scores = torch.split(dec_scores, dn_meta["dn_num_split"], dim=2)

        dec_bboxes = torch.cat([enc_bboxes.unsqueeze(0), dec_bboxes])  # (7, bs, 300, 4)
        dec_scores = torch.cat([enc_scores.unsqueeze(0), dec_scores])

        loss = self.criterion(
            (dec_bboxes, dec_scores), targets, dn_bboxes=dn_bboxes, dn_scores=dn_scores, dn_meta=dn_meta
        )
        # NOTE: There are like 12 losses in RTDETR, backward with all losses but only show the main three losses.
        return sum(loss.values()), torch.as_tensor(
            [loss[k].detach() for k in ["loss_giou", "loss_class", "loss_bbox"]], device=img.device
        )

def get_track_state_for_display(self, track):
        if hasattr(track, "hits") and track.hits < self.min_hits:
            return None
        if hasattr(track, "is_activated") and not track.is_activated:
            return None

        if hasattr(track, "time_since_update"):
            if track.time_since_update == 0:
                return "confirmed"
            if track.time_since_update <= self.max_age:
                return "predicted"
            return "lost"

        if hasattr(track, "state"):
            try:
                from boxmot.trackers.bytetrack.basetrack import TrackState

                if track.state == TrackState.Tracked:
                    return "confirmed"
                if track.state == TrackState.Lost:
                    return "predicted"
                return "lost"
            except Exception:
                return "confirmed" if getattr(track, "is_activated", True) else "lost"

        return "confirmed"

def get_params_dependent_on_data(self, params: dict[str, Any], data: dict[str, Any]) -> dict[str, Any]:
        img_h, img_w = params["shape"][:2]

        if self.max_size is not None:
            if isinstance(self.max_size, (list, tuple)):
                max_size = self.py_random.choice(self.max_size)
            else:
                max_size = self.max_size
            scale = max_size / max(img_h, img_w)
        elif self.max_size_hw is not None:
            # We know max_size_hw is not None here due to model validator
            max_h, max_w = self.max_size_hw
            if max_h is not None and max_w is not None:
                # Scale based on longest side to maintain aspect ratio
                h_scale = max_h / img_h
                w_scale = max_w / img_w
                scale = min(h_scale, w_scale)
            elif max_h is not None:
                # Only height specified
                scale = max_h / img_h
            else:
                # Only width specified
                scale = max_w / img_w

        return {"scale": scale}

def validate_predictions_format(predictions, task_type: TaskType):
    single_image_pred = _validate_predictions_label_common_format('prediction', predictions, task_type)

    if task_type == TaskType.CLASSIFICATION and single_image_pred is not None:
        if not isinstance(single_image_pred, np.ndarray) or not isinstance(single_image_pred[0], Number) or \
                not 0.99 < np.sum(single_image_pred) < 1.01:
            raise ValidationError('Classification prediction per image must be a sequence of floats representing '
                                  'probabilities per class.')
    elif task_type == TaskType.OBJECT_DETECTION and single_image_pred is not None:
        error_msg = 'Object detection prediction per image must be a sequence of 2D arrays, where each row ' \
                    'has 6 columns: [x_min, y_min, w, h, confidence, class_id]'
        if single_image_pred.shape[1] != 6:
            raise ValidationError(error_msg)
        if np.min(single_image_pred) < 0:
            raise ValidationError(f'Found one of coordinates to be negative, {error_msg}')
        if np.max(single_image_pred[:, 5] % 1) > 0:
            raise ValidationError(f'Class_id must be a positive integer. {error_msg}')
    elif task_type == TaskType.SEMANTIC_SEGMENTATION and single_image_pred is not None:
        if len(single_image_pred.shape) != 3:
            raise ValidationError('Semantic segmentation prediction per image must be a 3D array of shape (C, H, W),'
                                  'where H and W are the height and width of the corresponding image, and C is the '
                                  'number of classes that can be detected.')
        if not 0.99 < np.sum(single_image_pred[:, 0][:, 0]) < 1.01:
            raise ValidationError('Semantic segmentation prediction per pixel per image should be probabilities per '
                                  'each possible class')

def should_use_benchmark_reid(args: Any, cfg: dict[str, Any]) -> bool:
    benchmark_model = resolve_required_reid_model(cfg)
    if benchmark_model is None:
        return False

    current_model = getattr(args, "reid", None)
    if current_model is None:
        return False

    if isinstance(current_model, (list, tuple)):
        if not current_model:
            return False
        current_model = current_model[0]

    resolved_current = resolve_model_path(current_model)
    resolved_benchmark = resolve_model_path(benchmark_model)
    if resolved_current == resolved_benchmark:
        return True
    if Path(current_model).name.lower() == Path(benchmark_model).name.lower():
        return True

    if getattr(args, "reid_explicit", None) is True:
        return False

    default_name = (WEIGHTS / "osnet_x0_25_msmt17.pt").name.lower()
    return Path(current_model).name.lower() == default_name

def recursive_freeze(module: nn.Module, sample: Dict[str, Any], include_root: bool = True) -> Tuple[nn.Module, bool]:
    if include_root and isinstance(module, Mutable):
        return module.freeze(sample), True

    # Examine all the children.
    replaced_dict = {}
    for name, child_module in module.named_children():
        if isinstance(child_module, Mutable):
            new_module, replaced = child_module.freeze(sample), True
        else:
            new_module, replaced = recursive_freeze(child_module, sample)
        if replaced:
            replaced_dict[name] = new_module

    # If some children is replaced.
    if replaced_dict:
        module = copy.deepcopy(module)
        for name, new_module in replaced_dict.items():
            setattr(module, name, new_module)
        return module, True
    return module, False

def validate_pretrain_weights(pretrain_weights: str, strict: bool = False) -> bool:
    if not os.path.exists(pretrain_weights):
        if strict:
            raise FileNotFoundError(f"Pretrained weights file not found: {pretrain_weights}")
        return False

    # Check if we have a hash for this model
    model_name = os.path.basename(pretrain_weights)
    asset = ModelWeights.from_filename(model_name)

    if asset is None or asset.md5_hash is None:
        # No hash available for validation
        logger.debug(f"No MD5 hash available for {model_name}, skipping validation")
        return True

    if not _validate_file_md5(pretrain_weights, asset.md5_hash):
        error_msg = (
            f"MD5 hash validation failed for {pretrain_weights}. "
            f"The file may be corrupted or tampered with. "
            f"Consider re-downloading with download_pretrain_weights('{model_name}', redownload=True)"
        )
        if strict:
            raise ValueError(error_msg)
        else:
            logger.warning(error_msg)
        return False

    logger.debug(f"MD5 validation passed for {pretrain_weights}")
    return True

def handler(messages: list[dict[str, str]]) -> str:
    # -------- Input Validation --------

    if not isinstance(messages, list):
        return "Invalid input format: messages must be a list."

    if not messages:
        return "No input message received."

    last_msg = messages[-1]

    if not isinstance(last_msg, dict):
        return "Invalid message structure."

    user_input = last_msg.get("content")

    if not user_input or not isinstance(user_input, str):
        return "Empty or invalid message content."

    # -------- Swarm Execution --------

    try:
        result = orchestrator.run(user_input)
        return result

    except Exception as e:
        return f"Internal agent error: {str(e)}"

def expand_fragment_tape(
    tape: QuantumScript,
) -> tuple[list[QuantumScript], list[PrepareNode], list[MeasureNode]]:
    prepare_nodes = [o for o in tape.operations if isinstance(o, PrepareNode)]
    measure_nodes = [o for o in tape.operations if isinstance(o, MeasureNode)]

    wire_map = {mn.wires[0]: i for i, mn in enumerate(measure_nodes)}

    n_meas = len(measure_nodes)
    if n_meas >= 1:
        measure_combinations = partition_pauli_group(len(measure_nodes))
    else:
        measure_combinations = [[""]]

    tapes = []

    for prepare_settings in product(range(len(PREPARE_SETTINGS)), repeat=len(prepare_nodes)):
        for measure_group in measure_combinations:
            if n_meas >= 1:
                group = [
                    string_to_pauli_word(paulis, wire_map=wire_map) for paulis in measure_group
                ]
            else:
                group = []

            prepare_mapping = {
                id(n): PREPARE_SETTINGS[s] for n, s in zip(prepare_nodes, prepare_settings)
            }

            ops_list = []

            with QueuingManager.stop_recording():
                for op in tape.operations:
                    if isinstance(op, PrepareNode):
                        w = op.wires[0]
                        ops_list.extend(prepare_mapping[id(op)](w))
                    elif not isinstance(op, MeasureNode):
                        ops_list.append(op)
                measurements = _get_measurements(group, tape.measurements)

            qs = QuantumScript(ops=ops_list, measurements=measurements)
            tapes.append(qs)

    return tapes, prepare_nodes, measure_nodes

def analyze_cpu_tensors(min_size_mb: float = 10.0):
    gc.collect()

    results = {
        "total_cpu_mb": 0,
        "total_gpu_mb": 0,
        "pinned_mb": 0,
        "by_dtype": defaultdict(float),
        "by_shape": defaultdict(float),
        "large_tensors": [],
    }

    seen_ids = set()

    for obj in gc.get_objects():
        try:
            if torch.is_tensor(obj) and id(obj) not in seen_ids:
                seen_ids.add(id(obj))
                size_mb = obj.numel() * obj.element_size() / (1024 * 1024)
                dtype_str = str(obj.dtype)

                if obj.device.type == "cpu":
                    results["total_cpu_mb"] += size_mb
                    results["by_dtype"][dtype_str] += size_mb

                    if obj.is_pinned():
                        results["pinned_mb"] += size_mb

                    if size_mb >= min_size_mb:
                        shape_str = str(tuple(obj.shape))
                        results["by_shape"][shape_str] += size_mb
                        results["large_tensors"].append(
                            {
                                "shape": tuple(obj.shape),
                                "dtype": dtype_str,
                                "size_mb": size_mb,
                                "pinned": obj.is_pinned(),
                                "requires_grad": obj.requires_grad,
                            }
                        )
                else:
                    results["total_gpu_mb"] += size_mb
        except:
            pass

    # Sort large tensors by size
    results["large_tensors"].sort(key=lambda x: x["size_mb"], reverse=True)

    return results

def initialize_model(name, cfg):
    model_functions = {
        "resnet18": lambda: torchvision.models.resnet18(weights="IMAGENET1K_V1"),
        "resnet34": lambda: torchvision.models.resnet34(weights="IMAGENET1K_V1"),
        "resnet50": lambda: torchvision.models.resnet50(weights="IMAGENET1K_V1"),
        "resnet101": lambda: torchvision.models.resnet101(weights="IMAGENET1K_V1"),
        "resnet152": lambda: torchvision.models.resnet152(weights="IMAGENET1K_V1"),
        "densenet121": lambda: torchvision.models.densenet121(weights="IMAGENET1K_V1"),
        "vgg16": lambda: torchvision.models.vgg16(weights="IMAGENET1K_V1"),
        "lenet": lambda: LeNet(
            {"channels": cfg.channels, "num_classes": cfg.num_classes}
        ),
    }
    model = model_functions[name]()
    # Modify model for grayscale input if necessary
    if cfg.channels == 1:
        if name.startswith("resnet"):
            model.conv1 = torch.nn.Conv2d(
                1, 64, kernel_size=7, stride=2, padding=3, bias=False
            )
        elif name == "densenet121":
            model.features[0] = torch.nn.Conv2d(
                1, 64, kernel_size=(7, 7), stride=(2, 2), padding=(3, 3), bias=False
            )
        elif name == "vgg16":
            model.features[0] = torch.nn.Conv2d(
                1, 64, kernel_size=(3, 3), stride=(1, 1), padding=(1, 1)
            )

    # Modify final layer to match the number of classes
    if name.startswith("resnet"):
        num_ftrs = model.fc.in_features
        model.fc = torch.nn.Linear(num_ftrs, cfg.num_classes)
    elif name == "densenet121":
        num_ftrs = model.classifier.in_features
        model.classifier = torch.nn.Linear(num_ftrs, cfg.num_classes)
    elif name == "vgg16":
        num_ftrs = model.classifier[-1].in_features
        model.classifier[-1] = torch.nn.Linear(num_ftrs, cfg.num_classes)

    return model.cpu()

def detect_console_encoding() -> str:
    global _initial_defencoding

    encoding = None
    try:
        encoding = sys.stdout.encoding or sys.stdin.encoding
    except (AttributeError, OSError):
        pass

    # try again for something better
    if not encoding or "ascii" in encoding.lower():
        try:
            encoding = locale.getpreferredencoding()
        except locale.Error:
            # can be raised by locale.setlocale(), which is
            #  called by getpreferredencoding
            #  (on some systems, see stdlib locale docs)
            pass

    # when all else fails. this will usually be "ascii"
    if not encoding or "ascii" in encoding.lower():
        encoding = sys.getdefaultencoding()

    # GH#3360, save the reported defencoding at import time
    # MPL backends may change it. Make available for debugging.
    if not _initial_defencoding:
        _initial_defencoding = sys.getdefaultencoding()

    return encoding

def arg_scope(list_ops_or_scope, **kwargs):
  if isinstance(list_ops_or_scope, dict):
    # Assumes that list_ops_or_scope is a scope that is being reused.
    if kwargs:
      raise ValueError('When attempting to re-use a scope by suppling a'
                       'dictionary, kwargs must be empty.')
    current_scope = list_ops_or_scope.copy()
    try:
      _get_arg_stack().append(current_scope)
      yield current_scope
    finally:
      _get_arg_stack().pop()
  else:
    # Assumes that list_ops_or_scope is a list/tuple of ops with kwargs.
    if not isinstance(list_ops_or_scope, (list, tuple)):
      raise TypeError('list_ops_or_scope must either be a list/tuple or reused '
                      'scope (i.e. dict)')
    try:
      current_scope = current_arg_scope().copy()
      for op in list_ops_or_scope:
        key = arg_scope_func_key(op)
        if not has_arg_scope(op):
          raise ValueError('%s is not decorated with @add_arg_scope',
                           _name_op(op))
        if key in current_scope:
          current_kwargs = current_scope[key].copy()
          current_kwargs.update(kwargs)
          current_scope[key] = current_kwargs
        else:
          current_scope[key] = kwargs.copy()
      _get_arg_stack().append(current_scope)
      yield current_scope
    finally:
      _get_arg_stack().pop()

def expand_mask(masks, bboxes, im_shape, scores=None, thresh=0.5, scale=1.0, sortby=None):
    from ...data.transforms.mask import fill
    if len(masks) != len(bboxes):
        raise ValueError('The length of bboxes and masks mismatch, {} vs {}'
                         .format(len(bboxes), len(masks)))
    if scores is not None and len(masks) != len(scores):
        raise ValueError('The length of scores and masks mismatch, {} vs {}'
                         .format(len(scores), len(masks)))

    if isinstance(masks, mx.nd.NDArray):
        masks = masks.asnumpy()
    if isinstance(bboxes, mx.nd.NDArray):
        bboxes = bboxes.asnumpy()
    if isinstance(scores, mx.nd.NDArray):
        scores = scores.asnumpy()

    if sortby is not None:
        if sortby == 'area':
            areas = (bboxes[:, 2] - bboxes[:, 0]) * (bboxes[:, 3] - bboxes[:, 1])
            sorted_inds = np.argsort(-areas)
        elif sortby == 'xmin':
            sorted_inds = np.argsort(-bboxes[:, 0])
        elif sortby == 'ymin':
            sorted_inds = np.argsort(-bboxes[:, 1])
        elif sortby == 'xmax':
            sorted_inds = np.argsort(-bboxes[:, 2])
        elif sortby == 'ymax':
            sorted_inds = np.argsort(-bboxes[:, 3])
        else:
            raise ValueError('argument sortby cannot take value {}'
                             .format(sortby))
    else:
        sorted_inds = np.argsort(range(len(masks)))

    bboxes *= scale
    valid = np.where(scores >= thresh)[0]
    sorted_inds = sorted_inds[valid]
    masks = masks[valid]
    bboxes = bboxes[valid]
    full_masks = fill(masks, bboxes, im_shape)
    return full_masks, sorted_inds

def calculate_object_size(obj: typing.Any, unit: str = "byte") -> int:
    seen = set()
    to_visit: collections.deque = collections.deque()
    byte_size = 0

    to_visit.append(obj)

    while True:
        try:
            obj = to_visit.popleft()
        except IndexError:
            break

        # If element was already covered, skip it
        if id(obj) in seen:
            continue

        # Update size accounting
        byte_size += sys.getsizeof(obj)

        # Mark element as seen
        seen.add(id(obj))

        # Add keys and values for size account
        if isinstance(obj, dict):
            for v in obj.values():
                to_visit.append(v)

            for k in obj.keys():
                to_visit.append(k)
        elif hasattr(obj, "__dict__"):
            to_visit.append(obj.__dict__)
        elif hasattr(obj, "__iter__") and not (
            isinstance(obj, str) or isinstance(obj, bytes) or isinstance(obj, bytearray)
        ):
            for i in obj:
                to_visit.append(i)

    if unit == "KiB":
        final_size = byte_size / 1024
    elif unit == "MiB":
        final_size = byte_size / (2**20)
    else:
        final_size = byte_size

    return int(final_size)

def get_hashable(obj: Any) -> Hashable:
    # If hashable already, just return
    if is_hashable(obj):
        return obj
    # Get dictionary from SimpleNamespace
    if isinstance(obj, SimpleNamespace):
        obj = vars(obj)
    # For dictionaries or pd.Series, construct a frozenset from items
    # Also recurse on values in case they aren't hashable
    if isinstance(obj, (dict, pd.Series)):
        return frozenset((k, get_hashable(v)) for k, v in obj.items())
    # For lists, recurse on values
    if isinstance(obj, (list, tuple)):
        return tuple(get_hashable(v) for v in obj)
    # For NumPy arrays, hash the byte representation of the data array
    if isinstance(obj, np.ndarray):
        return obj.data.tobytes()
    raise ValueError(f"Object {obj} has no hashing proxy.")

def create_split(dataset_builder, batch_size, train,
                 split_start, split_end,
                 dtype=tf.float32,
                 image_size=IMAGE_SIZE, cache=False):
  # Hide any GPUs from TensorFlow. Otherwise TF might reserve memory and make
  # it unavailable to JAX.
  tf.config.experimental.set_visible_devices([], 'GPU')
  if train:
    train_examples = dataset_builder.info.splits['train'].num_examples
    split = f'train[{split_start}:{split_end}]'
  else:
    validate_examples = dataset_builder.info.splits['validation'].num_examples
    split = f'validation[{split_start}:{split_end}]'

  def decode_example(example):
    if train:
      image = preprocess_for_train(example['image'], dtype, image_size)
    else:
      image = preprocess_for_eval(example['image'], dtype, image_size)
    return {'image': image, 'label': example['label']}

  ds = dataset_builder.as_dataset(split=split, decoders={
      'image': tfds.decode.SkipDecoding(),
  })
  options = tf.data.Options()
  options.experimental_threading.private_threadpool_size = 48
  ds = ds.with_options(options)

  if cache:
    ds = ds.cache()

  if train:
    ds = ds.repeat()
    ds = ds.shuffle(16 * batch_size, seed=0)

  ds = ds.map(decode_example, num_parallel_calls=tf.data.experimental.AUTOTUNE)
  ds = ds.batch(batch_size, drop_remainder=True)

  if not train:
    ds = ds.repeat()

  ds = ds.prefetch(10)

  return ds

def observables_to_binary_matrix(observables, n_qubits=None, wire_map=None):
    m_cols = len(observables)

    if wire_map is None:
        all_wires = Wires.all_wires([pauli_word.wires for pauli_word in observables])
        wire_map = {i: c for c, i in enumerate(all_wires)}

    n_qubits_min = max(wire_map.values()) + 1
    if n_qubits is None:
        n_qubits = n_qubits_min
    elif n_qubits < n_qubits_min:
        raise ValueError(
            f"n_qubits must support the highest mapped wire index {n_qubits_min},"
            f" instead got n_qubits={n_qubits}."
        )

    binary_mat = np.zeros((m_cols, 2 * n_qubits))

    for i in range(m_cols):
        binary_mat[i, :] = pauli_to_binary(observables[i], n_qubits=n_qubits, wire_map=wire_map)

    return binary_mat

async def allocate_devices_with_gpu_idx(
        self, model_uid: str, model_type: str, gpu_idx: List[int]
    ) -> List[int]:
        # must be subset of total devices visible to this worker
        if not set(gpu_idx) <= set(self._total_gpu_devices):
            raise ValueError(
                f"Worker {self.address} cannot use the GPUs with these indexes: {gpu_idx}. "
                f"Worker {self.address} can only see these GPUs: {self._total_gpu_devices}."
            )
        # currently just report a warning log when there are already models on these GPUs
        for idx in gpu_idx:
            existing_model_uids = []
            if idx in self._gpu_to_model_uids:
                for rep_uid in self._gpu_to_model_uids[idx]:
                    existing_model_uids.append(rep_uid)
            if not self._allow_multi_replica_per_gpu and (
                existing_model_uids
                or len(self._user_specified_gpu_to_model_uids.get(idx, set())) > 0
            ):
                raise RuntimeError(
                    f"GPU index {idx} has been occupied with models: {existing_model_uids}, "
                    f"and multi-replica-per-GPU is disabled."
                )

            if existing_model_uids:
                logger.warning(
                    f"WARNING!!! GPU index {idx} has been occupied "
                    f"with these models on it: {existing_model_uids}"
                )

        for idx in gpu_idx:
            self._user_specified_gpu_to_model_uids[idx].add((model_uid, model_type))
        return sorted(gpu_idx)

def heisenberg_expand(self, U, wire_order):
        U_dim = len(U)
        nw = len(self.wires)

        if U.ndim > 2:
            raise ValueError("Only order-1 and order-2 arrays supported.")

        if U_dim != 1 + 2 * nw:
            raise ValueError(f"{self.name}: Heisenberg matrix is the wrong size {U_dim}.")

        if len(wire_order) == 0 or len(self.wires) == len(wire_order):
            # no expansion necessary (U is a full-system matrix in the correct order)
            return U

        if not wire_order.contains_wires(self.wires):
            raise ValueError(
                f"{self.name}: Some observable wires {self.wires} do not exist on this device with wires {wire_order}"
            )

        # get the indices that the operation's wires have on the device
        wire_indices = wire_order.indices(self.wires)

        # expand U into the I, x_0, p_0, x_1, p_1, ... basis
        dim = 1 + len(wire_order) * 2

        def loc(w):
            "Returns the slice denoting the location of (x_w, p_w) in the basis."
            ind = 2 * w + 1
            return slice(ind, ind + 2)

        if U.ndim == 1:
            W = np.zeros(dim)
            W[0] = U[0]
            for k, w in enumerate(wire_indices):
                W[loc(w)] = U[loc(k)]
        elif U.ndim == 2:
            W = np.zeros((dim, dim)) if isinstance(self, CVObservable) else np.eye(dim)
            W[0, 0] = U[0, 0]

            for k1, w1 in enumerate(wire_indices):
                s1 = loc(k1)
                d1 = loc(w1)

                # first column
                W[d1, 0] = U[s1, 0]
                # first row (for gates, the first row is always (1, 0, 0, ...), but not for observables!)
                W[0, d1] = U[0, s1]

                for k2, w2 in enumerate(wire_indices):
                    W[d1, loc(w2)] = U[s1, loc(k2)]  # block k1, k2 in U goes to w1, w2 in W.
        return W

def get_jupyter_code(path, get_bash, which_cells: list[int] | None = None) -> str:
    output = f"```{'bash' if get_bash else 'python'}\n"
    with open(path, "r") as f:
        j = json.load(f)
        i = -1
        for cell in j["cells"]:
            is_code = cell["cell_type"] == "code"
            if len(cell["source"]) == 0:
                continue
            is_bash = "bash" in cell["source"][0]
            is_copyright = "Copyright" in cell["source"][0]
            if is_code and is_bash == get_bash and not is_copyright:
                i += 1
                if which_cells is not None:
                    if i not in which_cells:
                        continue
                for line in cell["source"]:
                    is_print = "print_readable" in line
                    is_bash_line = "bash" in line
                    is_setup_path = "setup_path.sh" in line
                    if not (is_print or is_bash_line or is_setup_path):
                        output += line
                output += "\n"
    output += "```\n"
    return output

def get_forward_reference(
    annotation: Any,
) -> Optional[aiplatform.base.VertexAiResourceNoun]:

  def get_aiplatform_class_by_name(_annotation):
    """Resolves str annotation to AiPlatfrom Class."""
    if isinstance(_annotation, str):
      return getattr(aiplatform, _annotation, None)

  ai_platform_class = get_aiplatform_class_by_name(annotation)
  if ai_platform_class:
    return ai_platform_class

  try:
    # Python 3.7+
    from typing import ForwardRef

    if isinstance(annotation, ForwardRef):
      annotation = annotation.__forward_arg__
      ai_platform_class = get_aiplatform_class_by_name(annotation)
      if ai_platform_class:
        return ai_platform_class

  except ImportError:
    pass

async def delete_deployments(
    db: PrefectDBInterface,
    session: AsyncSession,
    deployment_ids: list[UUID],
) -> list[UUID]:
    if not deployment_ids:
        return []

    # Build delete events before deletion while deployments are still in session
    result = await session.execute(
        select(db.Deployment).where(db.Deployment.id.in_(deployment_ids))
    )
    existing_deployments = list(result.scalars().unique().all())

    if not existing_deployments:
        return []

    existing_ids = [d.id for d in existing_deployments]

    delete_events = []
    for d in existing_deployments:
        delete_events.append(
            await deployment_deleted_event(
                session=session, deployment=d, occurred=now("UTC")
            )
        )

    # Delete scheduled runs for all deployments
    for deployment_id in existing_ids:
        await _delete_scheduled_runs(
            session=session, deployment_id=deployment_id, auto_scheduled_only=False
        )

    # Delete related concurrency limits
    await session.execute(
        delete(db.ConcurrencyLimitV2).where(
            db.ConcurrencyLimitV2.id.in_(
                select(db.Deployment.concurrency_limit_id).where(
                    db.Deployment.id.in_(existing_ids)
                )
            )
        )
    )

    # Delete all deployments
    await session.execute(
        delete(db.Deployment).where(db.Deployment.id.in_(existing_ids))
    )

    # Emit delete events
    async with PrefectServerEventsClient() as events_client:
        for event in delete_events:
            await events_client.emit(event)

    return existing_ids

def to_str_round(x: Any, decimal: int = 6):
    if isinstance(x, str):
        return x
    if isinstance(x, (list, tuple, np.ndarray)):
        tmp_str = ", ".join([to_str_round(y, decimal=decimal) for y in x])
        return "[" + tmp_str + "]"
    if isinstance(x, dict):
        return str({k: to_str_round(v, decimal=decimal) for k, v in x.items()})
    if isinstance(x, (int, np.int32, np.int64)):
        return str(x)
    if isinstance(x, (float, np.float32, np.float64)):
        format_str = f"%.{decimal}f"
        return format_str % x
    if x is None:
        return str(x)
    raise ValueError("Invalid value: " + str(x))

def bicall(
        self,
        input: str,  # open up to the external
        promt_kwargs: Optional[Dict] = {},
        model_kwargs: Optional[Dict] = {},
        id: Optional[str] = None,
    ) -> Union["Parameter", ReActOutput]:
        # initialize step_history in both training and eval mode

        # set up the prompts
        prompt_kwargs = {
            **promt_kwargs,
            "input_str": input,
        }

        step_history: List[Union[StepOutput, Parameter]] = []
        if self.debug:
            printc(f"input_query: {input}", color="red")
        for i in range(self.max_steps):
            step = i + 1
            try:
                step_output = self._run_one_step(
                    step, prompt_kwargs, model_kwargs, id, step_history
                )
                if isinstance(step_output, Parameter):
                    step_output.data_id = id
                step_history.append(step_output)
                if self._check_last_step(step_history):
                    break
            except Exception as e:
                log.error(f"Error running step {step}: {e}")
                printc(f"Error running step {step}: {e}", color="red")
                raise e  # the only place to raise the error for debugging. In normal cases, the agent should not raise an error.

        answer = self._get_answer(step_history)
        if self.training:
            return answer
        # wrap the output
        output = ReActOutput(step_history=step_history, id=id, answer=answer)
        if self.debug:
            printc(f"answer: {output}", color="yellow")

        return output

def get_document_info(
        self,
        docs: List[str],
        df: pd.DataFrame = None,
        metadata: Mapping[str, Any] | None = None,
    ) -> pd.DataFrame:
        check_documents_type(docs)
        if df is not None:
            document_info = df.copy()
            document_info["Document"] = docs
            document_info["Topic"] = self.topics_
        else:
            document_info = pd.DataFrame({"Document": docs, "Topic": self.topics_})

        # Add topic info through `.get_topic_info()`
        topic_info = self.get_topic_info().drop("Count", axis=1)
        document_info = document_info.merge(topic_info, on="Topic", how="left")

        # Add top n words
        top_n_words = {topic: " - ".join(next(zip(*self.get_topic(topic)))) for topic in set(self.topics_)}
        document_info["Top_n_words"] = document_info.Topic.map(top_n_words)

        # Add flat probabilities
        if self.probabilities_ is not None:
            if len(self.probabilities_.shape) == 1:
                document_info["Probability"] = self.probabilities_
            else:
                document_info["Probability"] = [
                    max(probs) if topic != -1 else 1 - sum(probs)
                    for topic, probs in zip(self.topics_, self.probabilities_)
                ]

        # Add representative document labels
        repr_docs = [repr_doc for repr_docs in self.representative_docs_.values() for repr_doc in repr_docs]
        document_info["Representative_document"] = False
        document_info.loc[document_info.Document.isin(repr_docs), "Representative_document"] = True

        # Add custom meta data provided by the user
        if metadata is not None:
            for column, values in metadata.items():
                document_info[column] = values
        return document_info

def wait(fs, timeout=None, return_when=ALL_COMPLETED):
    with _AcquireFutures(fs):
        done = set(f for f in fs
                   if f._state in [CANCELLED_AND_NOTIFIED, FINISHED])
        not_done = set(fs) - done

        if (return_when == FIRST_COMPLETED) and done:
            return DoneAndNotDoneFutures(done, not_done)
        elif (return_when == FIRST_EXCEPTION) and done:
            if any(f for f in done
                   if not f.cancelled() and f.exception() is not None):
                return DoneAndNotDoneFutures(done, not_done)

        if len(done) == len(fs):
            return DoneAndNotDoneFutures(done, not_done)

        waiter = _create_and_install_waiters(fs, return_when)

    waiter.event.wait(timeout)
    for f in fs:
        with f._condition:
            f._waiters.remove(waiter)

    done.update(waiter.finished_futures)
    return DoneAndNotDoneFutures(done, set(fs) - done)

def fit(self, X, y=None):
        X = validate_data(
            self, X, accept_sparse=["csr", "csc"], dtype=[np.float64, np.float32]
        )

        n_samples, n_features = X.shape

        if self.n_components == "auto":
            self.n_components_ = johnson_lindenstrauss_min_dim(
                n_samples=n_samples, eps=self.eps
            )

            if self.n_components_ <= 0:
                raise ValueError(
                    "eps=%f and n_samples=%d lead to a target dimension of "
                    "%d which is invalid" % (self.eps, n_samples, self.n_components_)
                )

            elif self.n_components_ > n_features:
                raise ValueError(
                    "eps=%f and n_samples=%d lead to a target dimension of "
                    "%d which is larger than the original space with "
                    "n_features=%d"
                    % (self.eps, n_samples, self.n_components_, n_features)
                )
        else:
            if self.n_components > n_features:
                warnings.warn(
                    "The number of components is higher than the number of"
                    " features: n_features < n_components (%s < %s)."
                    "The dimensionality of the problem will not be reduced."
                    % (n_features, self.n_components),
                    DataDimensionalityWarning,
                )

            self.n_components_ = self.n_components

        # Generate a projection matrix of size [n_components, n_features]
        self.components_ = self._make_random_matrix(
            self.n_components_, n_features
        ).astype(X.dtype, copy=False)

        if self.compute_inverse_components:
            self.inverse_components_ = self._compute_inverse_components()

        # Required by ClassNamePrefixFeaturesOutMixin.get_feature_names_out.
        self._n_features_out = self.n_components

        return self

def match_predictions(
        self, pred_classes: torch.Tensor, true_classes: torch.Tensor, iou: torch.Tensor, use_scipy: bool = False
    ) -> torch.Tensor:
        # Dx10 matrix, where D - detections, 10 - IoU thresholds
        correct = np.zeros((pred_classes.shape[0], self.iouv.shape[0])).astype(bool)
        # LxD matrix where L - labels (rows), D - detections (columns)
        correct_class = true_classes[:, None] == pred_classes
        iou = iou * correct_class  # zero out the wrong classes
        iou = iou.cpu().numpy()
        for i, threshold in enumerate(self.iouv.cpu().tolist()):
            if use_scipy:
                import scipy  # scope import to avoid importing for all commands

                cost_matrix = iou * (iou >= threshold)
                if cost_matrix.any():
                    labels_idx, detections_idx = scipy.optimize.linear_sum_assignment(cost_matrix, maximize=True)
                    valid = cost_matrix[labels_idx, detections_idx] > 0
                    if valid.any():
                        correct[detections_idx[valid], i] = True
            else:
                matches = np.nonzero(iou >= threshold)  # IoU > threshold and classes match
                matches = np.array(matches).T
                if matches.shape[0]:
                    if matches.shape[0] > 1:
                        matches = matches[iou[matches[:, 0], matches[:, 1]].argsort()[::-1]]
                        matches = matches[np.unique(matches[:, 1], return_index=True)[1]]
                        matches = matches[np.unique(matches[:, 0], return_index=True)[1]]
                    correct[matches[:, 1].astype(int), i] = True
        return torch.tensor(correct, dtype=torch.bool, device=pred_classes.device)

def build_lr_scheduler(cfg: ConfigDict, default_args: dict = None):
    if cfg['type'].lower().endswith('warmup'):
        # build warmup lr scheduler
        if not hasattr(cfg, 'base_scheduler'):
            if default_args is None or ('base_scheduler' not in default_args):
                raise ValueError(
                    'Must provide ``base_scheduler`` which is an instance of ``torch.optim.lr_scheduler._LRScheduler`` '
                    'for build warmup lr scheduler.')
    else:
        # build lr scheduler without warmup
        if not hasattr(cfg, 'optimizer'):
            if default_args is None or ('optimizer' not in default_args):
                raise ValueError(
                    'Must provide ``optimizer`` which is an instance of ``torch.optim.Optimizer`` '
                    'for build lr scheduler')

    return build_from_cfg(
        cfg, LR_SCHEDULER, group_key=default_group, default_args=default_args)

def KORNIA_CHECK_TYPE(x: Any, typ: T | tuple[T, ...], msg: Optional[str] = None, raises: bool = True) -> bool:
    if not torch.jit.is_scripting():
        if not _KORNIA_CHECKS_ENABLED:
            return True

    if not isinstance(x, typ):
        if raises:
            # JIT doesn't support try-except or type introspection, so use simple message
            if torch.jit.is_scripting():
                error_msg = "Type mismatch."
                if msg is not None:
                    error_msg += f"\n  {msg}"
                raise TypeCheckError(error_msg)
            else:
                # In Python mode, we can safely use type introspection
                expected_type_str = typ.__name__ if not isinstance(typ, tuple) else " | ".join(t.__name__ for t in typ)
                type_name = str(type(x))
                error_msg = f"Type mismatch: expected {expected_type_str}, got {type_name}."
                if msg is not None:
                    error_msg += f"\n  {msg}"
                raise TypeCheckError(
                    error_msg,
                    actual_type=type(x),
                    expected_type=typ,
                )
        return False
    return True

def set_params(self, summary_dict):
        layer, sd = self, summary_dict

        # collapse `parameters` and `hyperparameters` nested dicts into a single
        # merged dictionary
        flatten_keys = ["parameters", "hyperparameters"]
        for k in flatten_keys:
            if k in sd:
                entry = sd[k]
                sd.update(entry)
                del sd[k]

        for k, v in sd.items():
            if k in self.parameters:
                layer.parameters[k] = v
            if k in self.hyperparameters:
                if k == "act_fn":
                    layer.act_fn = ActivationInitializer(v)()
                elif k == "optimizer":
                    layer.optimizer = OptimizerInitializer(sd[k])()
                elif k == "wrappers":
                    layer = init_wrappers(layer, sd[k])
                elif k not in ["wrappers", "optimizer"]:
                    setattr(layer, k, v)
        return layer

def list_wizard_models(self) -> Dict[str, Any]:
        self._ensure_models_loaded()
        wizard_models = []
        category_order = {"image": 0, "video": 1, "audio": 2, "other": 3}

        for family_name, model_cls in ModelRegistry.model_families().items():
            # Skip entries that aren't actual classes
            if not isinstance(model_cls, type):
                continue

            # Check if model is enabled in wizard (default to True if not specified)
            enabled = getattr(model_cls, "ENABLED_IN_WIZARD", True)
            if not enabled:
                continue

            # Get model metadata
            display_name = getattr(model_cls, "NAME", family_name)
            description = getattr(model_cls, "MODEL_DESCRIPTION", "")
            try:
                if issubclass(model_cls, AudioModelFoundation):
                    category = "audio"
                elif issubclass(model_cls, VideoModelFoundation):
                    category = "video"
                else:
                    category = "image"
            except TypeError:
                category = "image"

            wizard_models.append(
                {
                    "family": family_name,
                    "name": display_name,
                    "description": description,
                    "category": category,
                }
            )

        # Sort by display name for consistent ordering
        wizard_models.sort(key=lambda x: (category_order.get(x.get("category"), 99), x["name"]))

        return {"models": wizard_models}

def route(
        self, name: str, path: str | None = None, show_in_navbar: bool = True
    ) -> Blocks:
        if get_blocks_context():
            raise ValueError(
                "You cannot create a route while inside a Blocks() context. Call route() outside the Blocks() context (unindent this line)."
            )

        if path:
            path = path.strip("/")
            valid_path_regex = re.compile(r"^[a-zA-Z0-9-._~!$&'()*+,;=:@\[\]]+$")
            if not valid_path_regex.match(path):
                raise ValueError(
                    f"Path '{path}' contains invalid characters. Paths can only contain alphanumeric characters and the following special characters: -._~!$&'()*+,;=:@[]"
                )
        if path in INTERNAL_ROUTES:
            raise ValueError(f"Route with path '{path}' already exists")
        if path is None:
            path = slugify(name)
            if not path:
                raise ValueError(f"Route with path '{name}' is not valid")
        while path in INTERNAL_ROUTES or path in [page[0] for page in self.pages]:
            path = "_" + path
        self.pages.append((path, name, show_in_navbar))
        self.current_page = path
        return self

def window_function(
    window_length: int,
    name: str = "hann",
    periodic: bool = True,
    frame_length: int | None = None,
    center: bool = True,
) -> np.ndarray:
    length = window_length + 1 if periodic else window_length

    if name == "boxcar":
        window = np.ones(length)
    elif name in ["hamming", "hamming_window"]:
        window = np.hamming(length)
    elif name in ["hann", "hann_window"]:
        window = np.hanning(length)
    elif name == "povey":
        window = np.power(np.hanning(length), 0.85)
    else:
        raise ValueError(f"Unknown window function '{name}'")

    if periodic:
        window = window[:-1]

    if frame_length is None:
        return window

    if window_length > frame_length:
        raise ValueError(
            f"Length of the window ({window_length}) may not be larger than frame_length ({frame_length})"
        )

    padded_window = np.zeros(frame_length)
    offset = (frame_length - window_length) // 2 if center else 0
    padded_window[offset : offset + window_length] = window
    return padded_window

def create_new_layer(layer, n_dim):
    input_shape = layer.output.shape
    dense_deeper_classes = [StubDense, get_dropout_class(n_dim), StubReLU]
    conv_deeper_classes = [
        get_conv_class(n_dim),
        get_batch_norm_class(n_dim),
        StubReLU]
    if is_layer(layer, "ReLU"):
        conv_deeper_classes = [
            get_conv_class(n_dim),
            get_batch_norm_class(n_dim)]
        dense_deeper_classes = [StubDense, get_dropout_class(n_dim)]
    elif is_layer(layer, "Dropout"):
        dense_deeper_classes = [StubDense, StubReLU]
    elif is_layer(layer, "BatchNormalization"):
        conv_deeper_classes = [get_conv_class(n_dim), StubReLU]

    layer_class = None
    if len(input_shape) == 1:
        # It is in the dense layer part.
        layer_class = sample(dense_deeper_classes, 1)[0]
    else:
        # It is in the conv layer part.
        layer_class = sample(conv_deeper_classes, 1)[0]

    if layer_class == StubDense:
        new_layer = StubDense(input_shape[0], input_shape[0])

    elif layer_class == get_dropout_class(n_dim):
        new_layer = layer_class(Constant.DENSE_DROPOUT_RATE)  # pylint: disable=not-callable

    elif layer_class == get_conv_class(n_dim):
        new_layer = layer_class(  # pylint: disable=not-callable
            input_shape[-1], input_shape[-1], sample((1, 3, 5), 1)[0], stride=1
        )

    elif layer_class == get_batch_norm_class(n_dim):
        new_layer = layer_class(input_shape[-1])  # pylint: disable=not-callable

    elif layer_class == get_pooling_class(n_dim):
        new_layer = layer_class(sample((1, 3, 5), 1)[0])  # pylint: disable=not-callable

    else:
        new_layer = layer_class()  # pylint: disable=not-callable

    return new_layer

def set_item(
        self,
        key: str,
        value: Any,
        info: AttributeInfo | None,
        require_type: type[DatasetAttribute] | None = None,
    ) -> None:
        try:
            if isinstance(value, DatasetAttribute):
                if require_type and not isinstance(value, require_type):
                    raise TypeError(
                        f"Expected '{key}' to be of type '{require_type.__name__}', but got '{type(value).__name__}'."
                    )

                value._set_parent(self.bind, key)  # pylint: disable=protected-access
                if info:
                    info.save(value.info)

            elif require_type is not None:
                require_type(value, info, parent_and_key=(self.bind, key))
            else:
                attr_type = match_obj_type(value)
                attr_type(value, info, parent_and_key=(self.bind, key))
        except ValueError as exc:
            if exc.args[0] == "Unable to create dataset (no write intent on file)":
                raise DatasetNotWriteableError(self.bind) from exc

            raise exc

        self._cache.pop(key, None)

def filter_inputs_and_outputs(self):
        filtered_inputs = []
        filtered_outputs = []
        for k in self.inputs:
            if k not in self.graph.keys():
                continue
            v = self.graph[k]
            if len(v.inputs) == 0 and v.op not in {"Const", "get_global", "NoOp"}:
                filtered_inputs.append(k)
                self.input_types.append(v.datatype)
            elif len(v.inputs) != 0 and v.op == "Placeholder":
                assert len(v.inputs) == 1, "This is not a PlaceholderWithDefault!"
                filtered_inputs.append(k)
                self.input_types.append(v.datatype)
        for k in self.outputs:
            if k not in self.graph.keys():
                continue
            v = self.graph[k]
            filtered_outputs.append(k)
            self.output_types.append(v.datatype)
        self.inputs, self.outputs = filtered_inputs, filtered_outputs

def set_image_batch(
        self,
        image_list: List[Union[np.ndarray, str, Image]],
    ) -> None:
        images = []
        for image in image_list:
            if isinstance(image, str):
                if image.startswith("http"):
                    image = common.download_file(image)

                if not os.path.exists(image):
                    raise ValueError(f"Input path {image} does not exist.")

                image = cv2.imread(image)
                image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
            elif isinstance(image, Image):
                image = np.array(image)
            elif isinstance(image, np.ndarray):
                pass
            else:
                raise ValueError("Input image must be either a path or a numpy array.")

            images.append(image)

        self.predictor.set_image_batch(images)

def format_commands(self, ctx, formatter):
        commands = []
        for subcommand in self.list_commands(ctx):
            cmd = self.get_command(ctx, subcommand)
            # What is this, the tool lied about a command.  Ignore it
            if cmd is None:
                continue
            if cmd.hidden:
                continue

            commands.append((subcommand, cmd))

        # allow for 3 times the default spacing
        if len(commands):
            limit = formatter.width - 6 - max(len(cmd[0]) for cmd in commands)

            rows = []
            for subcommand, cmd in commands:
                help = cmd.get_short_help_str(limit)
                rows.append((subcommand, help))

            if rows:
                with formatter.section("Commands"):
                    formatter.write_dl(rows)

def diagnostics_from_stats(statistics, num_samples, num_chains):
    diag = {}
    mean_var_dict = {}
    for (_, name), stat in statistics.items():
        if name in mean_var_dict:
            mean, var = mean_var_dict[name]
            mean.append(stat["mean"])
            var.append(stat["variance"])
        elif "mean" in stat and "variance" in stat:
            mean_var_dict[name] = ([stat["mean"]], [stat["variance"]])

    for name, (m, v) in mean_var_dict.items():
        mean_var_dict[name] = (torch.stack(m), torch.stack(v))

    for name, (m, v) in mean_var_dict.items():
        N = num_samples
        var_within = v.mean(dim=0)
        var_estimator = (N - 1) / N * var_within
        if num_chains > 1:
            var_between = m.var(dim=0)
            var_estimator = var_estimator + var_between
        else:
            var_within = var_estimator

        diag[name] = OrderedDict({"r_hat": (var_estimator / var_within).sqrt()})

    return diag

def get_column_type(column: pd.Series) -> Literal['float', 'int', 'string', 'time', 'other']:
    if is_float_dtype(column):
        return 'float'
    elif is_numeric_dtype(column):
        return 'int'
    elif is_datetime64_any_dtype(column):
        return 'time'

    try:
        column: pd.Series = pd.to_numeric(column)
        if is_float_dtype(column):
            return 'float'
        else:
            return 'int'
    except ValueError:
        return 'string'
    # Non-string objects like pd.Timestamp results in TypeError
    except TypeError:
        return 'other'

def get_mode() -> RunMode | None:
    try:
        from marimo._runtime.context.kernel_context import KernelRuntimeContext
        from marimo._runtime.context.script_context import ScriptRuntimeContext

        context = get_context()
        if isinstance(context, KernelRuntimeContext):
            if context.session_mode == SessionMode.RUN:
                return "run"
            elif context.session_mode == SessionMode.EDIT:
                return "edit"
            else:
                assert_never(context.session_mode)

        if isinstance(context, ScriptRuntimeContext):
            return "script"
    except ContextNotInitializedError:
        pass

    # This is a fallback, it's possible to be in pytest mode and have a context,
    # as in native marimo tests.
    if "PYTEST_CURRENT_TEST" in os.environ:
        return "test"

    return None

def view(self, port: int = 8080, non_blocking: bool = False) -> Experiment:
        # Backward compatibility
        if isinstance(self, str):
            _logger.warning('Experiment.view(id) is deprecated (and has already stopped working for non-HPO experiments). '
                            'Use Experiment(id).view() instead.')
            # Assumes the type is `Experiment`, self is experiment_id.
            self = Experiment(None, id=self)

        self._action = 'view'

        if not self.has_checkpoint():
            raise RuntimeError(f'Experiment {self.id} does not exist thus cannot be viewed.')

        self.load_checkpoint()

        self.start(port=port, debug=False, run_mode=RunMode.Detach)
        if not non_blocking:
            try:
                while True:
                    time.sleep(10)
            except KeyboardInterrupt:
                _logger.warning('KeyboardInterrupt detected')
            finally:
                self.stop()
        return self

def conv2d_backward_weight_nchw_python(
    dy_np, x_np, kernel_size, stride, padding, groups=1, channels=None
):
    N, C, H, W = x_np.shape
    _, K, P, Q = dy_np.shape
    R, S = kernel_size
    pad_h, pad_w = padding
    stride_h, stride_w = stride
    is_depth_wise = C == K and C == groups

    if is_depth_wise:
        assert channels == groups, "Only channel_mult == 1 supported for now."
        dw = np.zeros((K, 1, R, S)).astype(dy_np.dtype)
    else:
        assert groups == 1, "General grouped conv2d not supported for now."
        dw = np.zeros((K, C, R, S)).astype(dy_np.dtype)

    for k in range(K):
        for r in range(R):
            for s in range(S):
                for c in range(dw.shape[1]):
                    acc = 0
                    for n in range(N):
                        for p in range(P):
                            for q in range(Q):
                                if not is_depth_wise:
                                    in_c = c
                                else:
                                    in_c = k

                                coord = (
                                    n,
                                    in_c,
                                    p * stride_h - pad_h + r,
                                    q * stride_w - pad_w + s,
                                )

                                if (
                                    coord[2] < H
                                    and coord[2] >= 0
                                    and coord[3] < W
                                    and coord[3] >= 0
                                ):
                                    acc += dy_np[n, k, p, q] * x_np[coord]

                    dw[k, c, r, s] = acc

    return dw

def get_android_recipe(
    target_config: str = "android-arm64-snapdragon-fp16", **kwargs
) -> ExportRecipe:

    if not is_supported_platform_for_qnn_lowering():
        raise ValueError(
            "QNN is not supported or not properly configured on this platform"
        )

    try:
        # Qualcomm QNN backend runs QNN sdk download on first use
        # with a pip install, so wrap it in a try/except
        # pyre-ignore
        from executorch.backends.qualcomm.recipes import QNNRecipeType

        # (1) if this is called from a pip install, the QNN SDK will be available
        # (2) if this is called from a source build, check if qnn is available otherwise, had to run build.sh
        if os.getenv("QNN_SDK_ROOT", None) is None:
            raise ValueError(
                "QNN SDK not found, cannot use QNN recipes. First run `./backends/qualcomm/scripts/build.sh`, if building from source"
            )
    except Exception as e:
        raise ValueError(
            "QNN backend is not available. Please ensure the Qualcomm backend "
            "is properly installed and configured, "
        ) from e

    android_configs: Dict[str, List[RecipeType]] = {
        # pyre-ignore
        "android-arm64-snapdragon-fp16": [QNNRecipeType.FP16, XNNPackRecipeType.FP32],
    }

    if target_config not in android_configs:
        supported = list(android_configs.keys())
        raise ValueError(
            f"Unsupported Android configuration: '{target_config}'. "
            f"Supported: {supported}"
        )

    kwargs = kwargs or {}

    if target_config == "android-arm64-snapdragon-fp16":
        if "soc_model" not in kwargs:
            kwargs["soc_model"] = "SM8650"

    backend_recipes = android_configs[target_config]
    return _create_target_recipe(target_config, backend_recipes, **kwargs)

async def resolve_variables(template: T, client: Optional["PrefectClient"] = None) -> T:
    if TYPE_CHECKING:
        # The @inject_client decorator takes care of providing the client, but
        # the function signature must mark it as optional to callers.
        assert client is not None

    if isinstance(template, str):
        placeholders = find_placeholders(template)
        has_variable_placeholder = any(
            placeholder.type is PlaceholderType.VARIABLE for placeholder in placeholders
        )
        if not placeholders or not has_variable_placeholder:
            # If there are no values, we can just use the template
            return template
        elif (
            len(placeholders) == 1
            and list(placeholders)[0].full_match == template
            and list(placeholders)[0].type is PlaceholderType.VARIABLE
        ):
            variable_name = list(placeholders)[0].name.replace(
                VARIABLE_PLACEHOLDER_PREFIX, ""
            )
            variable = await client.read_variable_by_name(name=variable_name)
            if variable is None:
                return ""
            else:
                return cast(T, variable.value)
        else:
            for full_match, name, placeholder_type in placeholders:
                if placeholder_type is PlaceholderType.VARIABLE:
                    variable_name = name.replace(VARIABLE_PLACEHOLDER_PREFIX, "")
                    variable = await client.read_variable_by_name(name=variable_name)
                    if variable is None:
                        template = template.replace(full_match, "")
                    else:
                        template = template.replace(full_match, str(variable.value))
            return template
    elif isinstance(template, dict):
        return {
            key: await resolve_variables(value, client=client)
            for key, value in template.items()
        }
    elif isinstance(template, list):
        return [await resolve_variables(item, client=client) for item in template]
    else:
        return template

def validate_mcm_method(
    capabilities: DeviceCapabilities | None, mcm_method: str | None, shots_present: bool
):
    if mcm_method is None or mcm_method == "deferred":
        return  # no need to validate if requested deferred or if no method is requested.

    if mcm_method == "one-shot" and not shots_present:
        raise QuantumFunctionError('The "one-shot" MCM method is only supported with finite shots.')

    if capabilities is None:
        # If the device does not declare its supported mcm methods through capabilities,
        # simply check that the requested mcm method is something we recognize.
        if mcm_method not in ("deferred", "one-shot", "tree-traversal"):
            raise QuantumFunctionError(
                f'Requested MCM method "{mcm_method}" unsupported by the device. Supported methods '
                f'are: "deferred", "one-shot", and "tree-traversal".'
            )
        return

    if mcm_method not in capabilities.supported_mcm_methods:
        supported_methods = capabilities.supported_mcm_methods + ["deferred"]
        supported_method_strings = [f'"{m}"' for m in supported_methods]
        raise QuantumFunctionError(
            f'Requested MCM method "{mcm_method}" unsupported by the device. Supported methods '
            f"are: {', '.join(supported_method_strings)}."
        )

def auto_set_denpendency_group_ids(graph_module: torch.fx.GraphModule,
                                   config_list: List[Dict[str, Any]],
                                   prune_type: str = 'Filter',
                                   prune_axis: int = 0) -> List[Dict[str, Any]]:

    channel_dependency = build_channel_dependency(graph_module, prune_type, prune_axis)
    module2uid = {}
    for d_set in channel_dependency:
        uid = uuid4().hex
        module2uid.update({node.target: uid for node in d_set})

    group_dependency = build_group_dependency(graph_module)
    group_dependency = {node.target: group_max for node, (group_max, group_min) in group_dependency.items()}

    config_list = trans_legacy_config_list(config_list)
    new_config_list = []
    for config in config_list:
        modules, public_config, _ = select_modules_by_config(graph_module, config)
        for target in modules.keys():
            sub_config = deepcopy(public_config)
            if target in module2uid:
                sub_config['dependency_group_id'] = module2uid[target]
            if target in group_dependency:
                sub_config['internal_metric_block'] = int(group_dependency[target])
            new_config_list.append({
                'op_names': [target],
                **sub_config
            })

    return new_config_list

def cast_storage(self, storage: Union[pa.StringArray, pa.StructArray, pa.ListArray]) -> pa.StructArray:
        if pa.types.is_string(storage.type):
            bytes_array = pa.array([None] * len(storage), type=pa.binary())
            storage = pa.StructArray.from_arrays([bytes_array, storage], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_large_binary(storage.type):
            storage = array_cast(
                storage, pa.binary()
            )  # this can fail in case of big videos, paths should be used instead
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_binary(storage.type):
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_struct(storage.type):
            if storage.type.get_field_index("bytes") >= 0:
                bytes_array = storage.field("bytes")
            else:
                bytes_array = pa.array([None] * len(storage), type=pa.binary())
            if storage.type.get_field_index("path") >= 0:
                path_array = storage.field("path")
            else:
                path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([bytes_array, path_array], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_list(storage.type):
            bytes_array = pa.array(
                [encode_np_array(np.array(arr))["bytes"] if arr is not None else None for arr in storage.to_pylist()],
                type=pa.binary(),
            )
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays(
                [bytes_array, path_array], ["bytes", "path"], mask=bytes_array.is_null()
            )
        return array_cast(storage, self.pa_type)

def is_valid_name(name: str) -> tuple[bool, str]:
    if not name:
        return False, "Cannot be empty."

    # Check if the name exceeds the maximum length
    if len(name) > MAX_NAME_LENGTH:
        return False, f"Must be no longer than {MAX_NAME_LENGTH} characters."

    # Check if the first character is a letter
    if not name[0].isalpha():
        return False, "Must start with a letter."

    # Check if the rest of the characters are valid (letter, digit, or dash)
    for char in name[1:]:
        if not (char.isalnum() or char in "-"):
            return False, "Can only contain letters, digits, and hyphens."

    return True, ""

def run_hook_script(
    script_template: str,
    *,
    config,
    local_path: str | None = None,
    remote_path: str | None = None,
    global_step: int | None = None,
) -> None:
    if script_template in (None, "", "None"):
        return
    output_dir = getattr(config, "output_dir", None)

    def _resolver(name: str):
        if name == "local_checkpoint_path":
            if local_path:
                return local_path
            return resolve_latest_checkpoint_path(output_dir)
        if name == "remote_checkpoint_path":
            return remote_path or ""
        if name == "global_step":
            step_value = global_step if global_step is not None else StateTracker.get_global_step()
            return "" if step_value is None else str(step_value)
        if name == "tracker_run_name":
            return getattr(config, "tracker_run_name", "") or ""
        if name == "tracker_project_name":
            return getattr(config, "tracker_project_name", "") or ""
        if name == "model_family":
            model_family = getattr(config, "model_family", None) or StateTracker.get_model_family()
            return "" if model_family is None else str(model_family)
        if name == "huggingface_path":
            return getattr(config, "hub_model_id", "") or ""
        if name == "model_type":
            return getattr(config, "model_type", "") or ""
        if name == "lora_type":
            return getattr(config, "lora_type", "") or ""
        if name.startswith("validation_"):
            return getattr(config, name, "") or ""
        raise KeyError(name)

    try:
        command = build_script_command(script_template, _resolver)
    except ValueError as exc:
        logger.error("Failed to format external script command: %s", exc)
        return
    submit_script(command)

def render_summary_tabs(module: DocumentedModule) -> str:
    tab_entries: list[tuple[str, list[str]]] = []

    if module.classes:
        tab_entries.append(
            (
                "Classes",
                [f"- [`{cls.name}`](#{item_anchor(cls)})" for cls in module.classes],
            )
        )

    property_links = []
    method_links = []
    for cls in module.classes:
        for child in cls.children:
            if child.kind == "property":
                property_links.append(f"- [`{cls.name}.{child.name}`](#{item_anchor(child)})")
        for child in cls.children:
            if child.kind == "method":
                method_links.append(f"- [`{cls.name}.{child.name}`](#{item_anchor(child)})")
    if property_links:
        tab_entries.append(("Properties", property_links))
    if method_links:
        tab_entries.append(("Methods", method_links))

    if module.functions:
        tab_entries.append(
            (
                "Functions",
                [f"- [`{func.name}`](#{item_anchor(func)})" for func in module.functions],
            )
        )

    if not tab_entries:
        return ""

    lines = ['!!! abstract "Summary"\n']
    for label, bullets in tab_entries:
        badge_class = SUMMARY_BADGE_MAP.get(label, label.lower())
        label_badge = f'<span class="doc-kind doc-kind-{badge_class}">{label}</span>'
        lines.append(f'    === "{label_badge}"\n')
        lines.append("\n".join(f"        {line}" for line in bullets))
        lines.append("")  # Blank line after each tab block
    return "\n".join(lines).rstrip() + "\n\n"

def nsdiffs(x, m, max_D=1, test="seas"):
    D = 0
    if max_D <= 0:
        raise ValueError("max_D must be a positive integer")
    if np.max(x) == np.min(x) or m < 2:
        return D
    if test == "seas":
        dodiff = seas_seasonalstationaritytest(x, m)
        while dodiff and D < max_D:
            D += 1
            x = diff(x, lag=m)
            if np.max(x) == np.min(x):
                return D
            if len(x) >= 2 * m and D < max_D:
                dodiff = seas_seasonalstationaritytest(x, m)
            else:
                dodiff = False
    return D

def garbage_collect_exports(export_dir_base, exports_to_keep):
  if exports_to_keep is None:
    return
  version_paths = []  # List of tuples (version, path)
  for filename in tf.compat.v1.gfile.ListDirectory(export_dir_base):
    path = os.path.join(
        tf.compat.as_bytes(export_dir_base),
        tf.compat.as_bytes(filename))
    if len(filename) == 10 and filename.isdigit():
      version_paths.append((int(filename), path))

  oldest_version_path = sorted(version_paths)[:-exports_to_keep]
  for _, path in oldest_version_path:
    try:
      tf.compat.v1.gfile.DeleteRecursively(path)
    except tf.errors.NotFoundError as e:
      logging.warn("Can not delete %s recursively: %s", path, e)

def channel_dependency_breakpoint(node: torch.fx.Node):
    if len(node.all_input_nodes) == 0:
        return True

    def find_parent(node: torch.fx.Node):
        par_arg = node.all_input_nodes[0]

        while isinstance(par_arg, tuple):
            par_arg = par_arg[0]
        return par_arg

    def get_shape(node):
        meta = node.meta.get('tensor_meta', None)
        if isinstance(meta, TensorMetadata):
            return meta[0]
        elif isinstance(meta, tuple):
            return meta[0][0]
        return None

    in_shape = get_shape(find_parent(node))
    out_shape = get_shape(node)
    if not in_shape or not out_shape or len(in_shape) <= 1 or len(out_shape) <= 1:
        return True
    in_channel = in_shape[1]
    out_channel = out_shape[1]
    # TODO: add more rules here
    return in_channel != out_channel

def print_args(args: dict | None = None, show_file=True, show_func=False):
    def strip_auth(v):
        """Clean longer Ultralytics HUB URLs by stripping potential authentication information."""
        return clean_url(v) if (isinstance(v, str) and v.startswith("http") and len(v) > 100) else v

    x = inspect.currentframe().f_back  # previous frame
    file, _, func, _, _ = inspect.getframeinfo(x)
    if args is None:  # get args automatically
        args, _, _, frm = inspect.getargvalues(x)
        args = {k: v for k, v in frm.items() if k in args}
    try:
        file = Path(file).resolve().relative_to(ROOT).with_suffix("")
    except ValueError:
        file = Path(file).stem
    s = (f"{file}: " if show_file else "") + (f"{func}: " if show_func else "")
    LOGGER.info(colorstr(s) + ", ".join(f"{k}={strip_auth(v)}" for k, v in sorted(args.items())))

def load_files_to_dataframe(self, file_paths: list[str], root_dir=None) -> pd.DataFrame:
        if root_dir:
            file_paths = [os.path.join(root_dir, path) for path in file_paths]
        dataframes = [self.load_file_to_dataframe(path) for path in file_paths]
        try:
            if self.config.columns:
                column_names = [column["name"] for column in self.config.columns]

                set_cols_dfs = []
                for df in dataframes:
                    # Split column is not included in configs, add in if pre-set split is present
                    if SPLIT in df.columns:
                        column_names.append(SPLIT)

                    # If the number of columns in the dataframe does not match the number of columns in the config,
                    # then the dataframe likely has an extra column that we don't want - i.e. "Unnamed: 0".
                    if len(column_names) != len(df.columns):
                        df = df[column_names]
                    set_cols_dfs.append(df.set_axis(column_names, axis=1))
                return pd.concat(set_cols_dfs, ignore_index=True)
            else:
                return pd.concat(dataframes, ignore_index=True)
        except ValueError as e:
            logger.warning(f"Error setting column names: {e}")
            return pd.concat(dataframes, ignore_index=True)

def approxrand(a, b, **kwargs):
    shuffles = kwargs.get("shuffles", 999)
    # there's no point in trying to shuffle beyond all possible permutations
    shuffles = min(shuffles, reduce(operator.mul, range(1, len(a) + len(b) + 1)))
    stat = kwargs.get("statistic", lambda lst: sum(lst) / len(lst))
    verbose = kwargs.get("verbose", False)

    if verbose:
        print("shuffles: %d" % shuffles)

    actual_stat = fabs(stat(a) - stat(b))

    if verbose:
        print("actual statistic: %f" % actual_stat)
        print("-" * 60)

    c = 1e-100
    lst = LazyConcatenation([a, b])
    indices = list(range(len(a) + len(b)))

    for i in range(shuffles):
        if verbose and i % 10 == 0:
            print("shuffle: %d" % i)

        shuffle(indices)

        pseudo_stat_a = stat(LazyMap(lambda i: lst[i], indices[: len(a)]))
        pseudo_stat_b = stat(LazyMap(lambda i: lst[i], indices[len(a) :]))
        pseudo_stat = fabs(pseudo_stat_a - pseudo_stat_b)

        if pseudo_stat >= actual_stat:
            c += 1

        if verbose and i % 10 == 0:
            print("pseudo-statistic: %f" % pseudo_stat)
            print("significance: %f" % ((c + 1) / (i + 1)))
            print("-" * 60)

    significance = (c + 1) / (shuffles + 1)

    if verbose:
        print("significance: %f" % significance)
        if betai:
            for phi in [0.01, 0.05, 0.10, 0.15, 0.25, 0.50]:
                print(f"prob(phi<={phi:f}): {betai(c, shuffles, phi):f}")

    return (significance, c, shuffles)

def convert_state_dict_sharded(loaded_shards: list[dict], config: MistralConfig):
    new_dict = {}

    num_shards = len(loaded_shards)

    n_heads = config.num_attention_heads
    dim = config.hidden_size
    dims_per_head = dim // n_heads
    num_key_value_heads = config.num_key_value_heads
    n_heads_per_shard = n_heads // num_shards
    num_local_key_value_heads = num_key_value_heads // num_shards
    key_value_dim = dim if n_heads == num_key_value_heads else dims_per_head * num_local_key_value_heads

    original_keys = loaded_shards[0].keys()
    for old_key in original_keys:
        new_key = map_old_key_to_new(old_key)
        cat_dim = get_concat_dim(new_key)

        if "q_proj" in new_key:
            tensor = torch.cat(
                [shard.pop(old_key).view(n_heads_per_shard, dims_per_head, dim) for shard in loaded_shards],
                dim=cat_dim,
            ).reshape(dim, dim)
            tensor = permute_for_rope(tensor, n_heads, dim, dim)
        elif "k_proj" in new_key:
            tensor = torch.cat(
                [shard.pop(old_key).view(num_local_key_value_heads, dims_per_head, dim) for shard in loaded_shards],
                dim=cat_dim,
            ).reshape(key_value_dim, dim)
            tensor = permute_for_rope(tensor, num_key_value_heads, key_value_dim, dim)
        elif "v_proj" in new_key:
            tensor = torch.cat(
                [shard.pop(old_key).view(num_local_key_value_heads, dims_per_head, dim) for shard in loaded_shards],
                dim=cat_dim,
            ).reshape(key_value_dim, dim)
        elif "input_layernorm" in new_key or "post_attention_layernorm" in new_key:
            tensor = loaded_shards[0][old_key].clone()
        elif "model.norm.weight" in new_key:
            tensor = loaded_shards[0][old_key]
        else:
            tensor = torch.cat([shard.pop(old_key) for shard in loaded_shards], dim=cat_dim)

        new_dict[new_key] = tensor

    return new_dict

def step(
        self,
        task: str,
        img: str = None,
        streaming_callback: Optional[
            Callable[[str, str, bool], None]
        ] = None,
        *args,
        **kwargs,
    ):
        try:
            # Update dashboard for director execution
            if self.interactive and self.dashboard:
                self.dashboard.update_director_status("PLANNING")

            output = self.run_director(task=task, img=img)

            # Parse the orders
            plan, orders = self.parse_orders(output)

            formatter.print_director_task_distribution(
                director_name=self.director_name,
                orders=orders,
            )

            # Update dashboard with plan and orders information
            if self.interactive and self.dashboard:
                self.dashboard.update_director_plan(plan)
                # Convert orders to list of dicts for dashboard
                orders_list = [
                    {
                        "agent_name": order.agent_name,
                        "task": order.task,
                    }
                    for order in orders
                ]
                self.dashboard.update_director_orders(orders_list)
                self.dashboard.update_director_status("EXECUTING")

            # Execute the orders
            outputs = self.execute_orders(
                orders, streaming_callback=streaming_callback
            )

            if self.agent_as_judge:
                feedback = self.run_judge_agent(outputs)
            elif self.director_feedback_on is True:
                feedback = self.feedback_director(outputs)
            else:
                feedback = outputs

            return feedback

        except Exception as e:
            error_msg = f"[ERROR] Step execution failed: {str(e)}"
            logger.error(
                f"{error_msg}\n[TRACE] Traceback: {traceback.format_exc()}\n[BUG] If this issue persists, please report it at: https://github.com/kyegomez/swarms/issues"
            )

def lemmas(self, lemma, pos=None, lang="eng"):
        lemma = lemma.lower()
        if lang == "eng":
            return [
                lemma_obj
                for synset in self.synsets(lemma, pos)
                for lemma_obj in synset.lemmas()
                if lemma_obj.name().lower() == lemma
            ]

        else:
            self._load_lang_data(lang)
            lemmas = []
            syn = self.synsets(lemma, lang=lang)
            for s in syn:
                if pos is not None and s.pos() != pos:
                    continue
                for lemma_obj in s.lemmas(lang=lang):
                    if lemma_obj.name().lower() == lemma:
                        lemmas.append(lemma_obj)
            return lemmas

def get_shared_times(
    *series_or_times: TimeSeries | pd.Index | None, sort: bool = True
) -> pd.Index:

    # `sort = None` specifies to `pd.Index.intersection` that values should be sorted:
    sort = None if sort else False

    def intersection_func(series_or_times_1, series_or_times_2):
        times_1 = (
            series_or_times_1.time_index
            if isinstance(series_or_times_1, TimeSeries)
            else series_or_times_1
        )
        times_2 = (
            series_or_times_2.time_index
            if isinstance(series_or_times_2, TimeSeries)
            else series_or_times_2
        )
        return times_1.intersection(times_2, sort=sort)

    specified_inputs = [series for series in series_or_times if series is not None]

    if not specified_inputs:
        shared_times = None
    elif len(specified_inputs) == 1:
        shared_times = (
            specified_inputs[0].time_index
            if isinstance(specified_inputs[0], TimeSeries)
            else specified_inputs[0]
        )
        shared_times = None if len(shared_times) == 0 else shared_times
    else:
        shared_times = reduce(intersection_func, specified_inputs)
        # Empty intersection may result from intersecting time indices being of different types - throw error if so:
        if shared_times.empty:
            shared_times = None
            times_types = [
                type(ts.time_index if isinstance(ts, TimeSeries) else ts)
                for ts in specified_inputs
            ]
            if not len(set(times_types)) == 1:
                raise_log(
                    ValueError(
                        "Specified series and/or times must all have the same type of "
                        "`time_index` (i.e. all `pd.RangeIndex` or all `pd.DatetimeIndex`)."
                    ),
                    logger=logger,
                )
    return shared_times

def remove(self) -> None:
        handler = self.handler()
        engine = self.engine()

        if handler is None or engine is None:
            return

        if hasattr(handler, "_parent"):
            handler = handler._parent()
            if handler is None:
                raise RuntimeError(
                    "Internal error! Please fill an issue on https://github.com/pytorch/ignite/issues "
                    "if encounter this error. Thank you!"
                )

        if isinstance(self.event_name, EventsList):
            for e in self.event_name:
                if engine.has_event_handler(handler, e):
                    engine.remove_event_handler(handler, e)
        else:
            if engine.has_event_handler(handler, self.event_name):
                engine.remove_event_handler(handler, self.event_name)

def save_csvs(data, folder_name, suffix=None, to_csv_parameters=None):
    error_message_data = "'data' must be a dictionary that maps table names to pandas DataFrames."
    if not isinstance(data, dict):
        raise ValueError(error_message_data)

    for table_name, table in data.items():
        if not isinstance(table, pd.DataFrame):
            raise ValueError(error_message_data)

    if not os.path.exists(folder_name):
        os.makedirs(folder_name)

    table_name_to_filepath = {}
    errors = []
    for table_name in data:
        filename = f'{table_name}{suffix}.csv' if suffix else f'{table_name}.csv'
        filepath = os.path.join(folder_name, filename)
        if os.path.exists(filepath):
            errors.append(filename)

        table_name_to_filepath[table_name] = filepath

    if errors:
        end_message = 'Please remove them or specify a different suffix.'
        filename_to_print = '\n'.join(errors[:3])
        if len(errors) > 3:
            end_message = ''.join([f'+ {len(errors) - 3} more files.', end_message])

        raise FileExistsError(
            f"The following files already exist in '{folder_name}':\n{filename_to_print}"
            f'\n{end_message}'
        )

    to_csv_parameters = to_csv_parameters or {}
    for table_name, filepath in table_name_to_filepath.items():
        table = data[table_name]
        table.to_csv(filepath, **to_csv_parameters)

def load_notebook_ir(
    notebook: NotebookSerialization, filepath: str | None = None
) -> App:
    # Use filepath from notebook if not explicitly provided
    if filepath is None:
        filepath = notebook.filename

    # Markdown frontmatter may contain non-config metadata (e.g., author,
    # description). Filter to only pass recognized config keys to App().
    options = notebook.app.options
    if filepath and MarimoPath(filepath).is_markdown():
        options = _AppConfig.sanitize(options)

    app = App(**options, _filename=filepath)
    for cell in notebook.cells:
        if isinstance(cell, UnparsableCell):
            app._unparsable_cell(cell.code, **cell.options)
            continue
        app._cell_manager.register_ir_cell(cell, InternalApp(app))
    if notebook.header and notebook.header.value:
        app._header = notebook.header.value
    return app

def make_flat_list_of_images(
    images: list[ImageInput] | ImageInput,
    expected_ndims: int = 3,
) -> ImageInput:
    # If the input is a nested list of images, we flatten it
    if (
        isinstance(images, (list, tuple))
        and all(isinstance(images_i, (list, tuple)) for images_i in images)
        and all(is_valid_list_of_images(images_i) or not images_i for images_i in images)
    ):
        return [img for img_list in images for img in img_list]

    if isinstance(images, (list, tuple)) and is_valid_list_of_images(images):
        if is_pil_image(images[0]) or images[0].ndim == expected_ndims:
            return images
        if images[0].ndim == expected_ndims + 1:
            return [img for img_list in images for img in img_list]

    if is_valid_image(images):
        if is_pil_image(images) or images.ndim == expected_ndims:
            return [images]
        if images.ndim == expected_ndims + 1:
            return list(images)

    raise ValueError(f"Could not make a flat list of images from {images}")

def types_to_proto(self, valuetype: type) -> proto.MIL_pb2.ValueType:
        if types.is_tensor(valuetype):
            primitive = types_to_proto_primitive(valuetype.get_primitive())
            return create_valuetype_tensor(valuetype.get_shape(), primitive)
        elif types.is_tuple(valuetype):
            v_type = proto.MIL_pb2.ValueType()
            t_type = v_type.tupleType
            for t in valuetype.T:
                new_v_type = t_type.types.add()
                new_v_type.CopyFrom(self.types_to_proto(t))
            return v_type
        elif types.is_list(valuetype):
            elem = valuetype.T[0]
            length = valuetype.T[1]
            if types.is_tensor(elem):
                dtype = types_to_proto_primitive(elem.get_primitive())
                elem_shape = elem.get_shape()
            elif types.is_scalar(elem):
                dtype = types_to_proto_primitive(valuetype)
                elem_shape = ()
            elif types.is_str(elem):
                dtype = types_to_proto_primitive(elem)
                elem_shape = ()
            else:
                raise NotImplementedError(
                    "Only list of either tensors or scalars supported. "
                    "Got element of type {}".format(elem.__type_info__())
                )
            return create_valuetype_list(length=length, elem_shape=elem_shape, dtype=dtype)
        elif types.is_dict(valuetype):
            return self.create_valuetype_dict(valuetype.T[0], valuetype.T[1])
        elif types.is_state(valuetype):
            wrapped_type = valuetype.wrapped_type()
            v_type = proto.MIL_pb2.ValueType()
            v_type.stateType.wrappedType.CopyFrom(self.types_to_proto(wrapped_type))
            return v_type
        else:
            return create_valuetype_scalar(types_to_proto_primitive(valuetype))

def commute_clifford_op(clifford_op: Operator, xz: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if len(xz) != clifford_op.num_wires:
        raise ValueError(
            "Please ensure that the length of xz matches the number of wires of the clifford_op."
        )

    if not all(len(element) == 2 for element in xz):
        raise ValueError(
            "Please ensure there are 2 elements instead of in each tuple in the xz list."
        )

    xz_flatten = tuple(itertools.chain.from_iterable(xz))

    if not all(element in [0, 1] for element in xz_flatten):
        raise ValueError("Please ensure xz are either 0 or 1.")

    if isinstance(clifford_op, S):
        _x, _z = xz[0]
        return _commute_s(_x, _z)

    if isinstance(clifford_op, H):
        _x, _z = xz[0]
        return _commute_h(_x, _z)

    if isinstance(clifford_op, CNOT):
        _xc, _zc = xz[0]
        _xt, _zt = xz[1]
        return _commute_cnot(_xc, _zc, _xt, _zt)

    raise NotImplementedError("Only qml.H, qml.S and qml.CNOT are supported.")

def open(self, mode: str = "a", **kwargs) -> None:
        tables = _tables()

        if self._mode != mode:
            # if we are changing a write mode to read, ok
            if self._mode in ["a", "w"] and mode in ["r", "r+"]:
                pass
            elif mode in ["w"]:
                # this would truncate, raise here
                if self.is_open:
                    raise PossibleDataLossError(
                        f"Re-opening the file [{self._path}] with mode [{self._mode}] "
                        "will delete the current file!"
                    )

            self._mode = mode

        # close and reopen the handle
        if self.is_open:
            self.close()

        if self._complevel and self._complevel > 0:
            self._filters = _tables().Filters(
                self._complevel, self._complib, fletcher32=self._fletcher32
            )

        if _table_file_open_policy_is_strict and self.is_open:
            msg = (
                "Cannot open HDF5 file, which is already opened, "
                "even in read-only mode."
            )
            raise ValueError(msg)

        self._handle = tables.open_file(self._path, self._mode, **kwargs)

def filter(example, uniques, args):
    if not check_uniques(example, uniques):
        return False
    elif example["autogenerated"]:
        return False
    elif example["line_max"] > args.line_max:
        return False
    elif example["line_mean"] > args.line_mean:
        return False
    elif example["alpha_frac"] < args.alpha_frac:
        return False
    elif example["ratio"] < args.min_token_ratio:
        return False
    elif example["config_or_test"] and np.random.rand() <= args.filter_proba:
        return False
    elif example["has_no_keywords"] and np.random.rand() <= args.filter_proba:
        return False
    elif example["has_few_assignments"]:
        return False
    else:
        return True

def as_array(
        self,
        dtype: np.dtype | None = None,
        copy: bool = False,
        na_value: object = lib.no_default,
    ) -> np.ndarray:
        passed_nan = lib.is_float(na_value) and isna(na_value)

        if len(self.blocks) == 0:
            arr = np.empty(self.shape, dtype=float)
            return arr.transpose()

        if self.is_single_block:
            blk = self.blocks[0]

            if na_value is not lib.no_default:
                # We want to copy when na_value is provided to avoid
                # mutating the original object
                if lib.is_np_dtype(blk.dtype, "f") and passed_nan:
                    # We are already numpy-float and na_value=np.nan
                    pass
                else:
                    copy = True

            if blk.is_extension:
                # Avoid implicit conversion of extension blocks to object

                # error: Item "ndarray" of "Union[ndarray, ExtensionArray]" has no
                # attribute "to_numpy"
                arr = blk.values.to_numpy(  # type: ignore[union-attr]
                    dtype=dtype,
                    na_value=na_value,
                    copy=copy,
                ).reshape(blk.shape)
            elif not copy:
                arr = np.asarray(blk.values, dtype=dtype)
            else:
                arr = np.array(blk.values, dtype=dtype, copy=copy)
            if passed_nan and blk.dtype.kind in "mM":
                arr[isna(blk.values)] = na_value

            if not copy:
                arr = arr.view()
                arr.flags.writeable = False
        else:
            arr = self._interleave(dtype=dtype, na_value=na_value)
            # The underlying data was copied within _interleave, so no need
            # to further copy if copy=True or setting na_value

        if na_value is lib.no_default:
            pass
        elif arr.dtype.kind == "f" and passed_nan:
            pass
        else:
            arr[isna(arr)] = na_value

        return arr.transpose()

def transform(self, X):
        # Pack by dimension
        columns = []
        for dim in self.dimensions:
            columns.append([])

        for i in range(len(X)):
            for j in range(self.n_dims):
                columns[j].append(X[i][j])

        # Transform
        for j in range(self.n_dims):
            columns[j] = self.dimensions[j].transform(columns[j])

        # Repack as an array
        Xt = np.hstack([np.asarray(c).reshape((len(X), -1)) for c in columns])

        return Xt

def validate(self, types: Dict[str, Optional[torch.dtype]]) -> bool:
        # Every arg name in `types` should be one of the tensor ios in current function.
        for arg_name in types:
            if not self.__contains__(arg_name):
                return False

        # Any essential tensor input should exist in current `type` input.
        for io_name in self.essential_tensor_io_names:
            if io_name not in types:
                return False

        valid_type = False
        for constraint in self.type_constraint:
            if valid_type:
                break

            valid_type = True
            # Narrow down the type_alias based on contraint and actual input
            for arg_name, arg_type in types.items():
                if arg_type is None:
                    # None means the user didn't set dtype for this argment
                    # (i.e. empty tensorlist), skipping the validation.
                    continue
                elif arg_type in self.type_alias[constraint[arg_name]]:
                    self.type_alias[constraint[arg_name]].reduce_to(arg_type)
                else:
                    valid_type = False
                    break

            for alias in self.type_alias.values():
                alias.clear()

        return valid_type

def write_to_artifact(executor_input, text):
  output_artifacts = {}
  for name, artifacts in (
      executor_input.get('outputs', {}).get('artifacts', {}).items()
  ):
    artifacts_list = artifacts.get('artifacts')
    if artifacts_list:
      output_artifacts[name] = artifacts_list[0]

  executor_output = {}
  if output_artifacts:
    executor_output['artifacts'] = {}
    uri_with_prefix = ''

    # TODO - Support multiple outputs, current implementation.

    # sets all output uri's to text
    for name, artifact in output_artifacts.items():
      metadata = artifact.get('metadata', {})
      # Add URI Prefix
      # "https://[location]-aiplatform.googleapis.com/API_VERSION/": For AI Platform resource names, current version is defined in AIPLATFORM_API_VERSION.
      if RESOURCE_NAME_PATTERN.match(text):
        location = re.findall('locations/([\w\-]+)', text)[0]
        uri_with_prefix = f'https://{location}-aiplatform.googleapis.com/{AIPLATFORM_API_VERSION}/{text}'
        metadata.update({'resourceName': text})

      # "gcs://": For Google Cloud Storage resources.
      elif text.startswith(RESOURCE_PREFIX['google_cloud_storage_gcs_fuse']):
        uri_with_prefix = text.replace(
            RESOURCE_PREFIX['google_cloud_storage_gcs_fuse'],
            RESOURCE_PREFIX.get('google_cloud_storage'),
        )

      # "bq://": For BigQuery resources.
      elif text.startswith(RESOURCE_PREFIX.get('bigquery')):
        uri_with_prefix = text
      else:
        uri_with_prefix = text

      runtime_artifact = {
          'name': artifact.get('name'),
          'uri': uri_with_prefix,
          'metadata': metadata,
      }
      artifacts_list = {'artifacts': [runtime_artifact]}

      executor_output['artifacts'][name] = artifacts_list

  os.makedirs(
      os.path.dirname(executor_input['outputs']['outputFile']), exist_ok=True
  )
  with open(executor_input['outputs']['outputFile'], 'w') as f:
    f.write(json.dumps(executor_output))

def create_task(self, task_def_l, dry_run=False, print_nt=False) -> List[str]:
        new_tasks = []
        _id_list = []
        for t in task_def_l:
            try:
                r = self.task_pool.find_one({"filter": t})
            except InvalidDocument:
                r = self.task_pool.find_one({"filter": self._dict_to_str(t)})
            # When r is none, it indicates that r s a new task
            if r is None:
                new_tasks.append(t)
                if not dry_run:
                    insert_result = self.insert_task_def(t)
                    _id_list.append(insert_result.inserted_id)
                else:
                    _id_list.append(None)
            else:
                _id_list.append(self._decode_task(r)["_id"])

        self.logger.info(f"Total Tasks: {len(task_def_l)}, New Tasks: {len(new_tasks)}")

        if print_nt:  # print new task
            for t in new_tasks:
                print(t)

        if dry_run:
            return []

        return _id_list

def prepare_data(dataloader: Im2LatexDataset) -> Tuple[torch.tensor, torch.tensor]:
    _, ims = dataloader.pairs[dataloader.i-1].T
    images = []
    scale = None
    c = 0
    width, height = imagesize.get(ims[0])
    while True:
        c += 1
        s = np.array([width, height])
        scale = 5*(np.random.random()+.02)
        if all((s*scale) <= dataloader.max_dimensions[0]) and all((s*scale) >= 16):
            break
        if c > 25:
            return None, None
    x, y = 0, 0
    for path in list(ims):
        im = Image.open(path)
        modes = [Image.Resampling.BICUBIC,
                 Image.Resampling.BILINEAR]
        if scale < 1:
            modes.append(Image.Resampling.LANCZOS)
        m = modes[int(len(modes)*np.random.random())]
        im = im.resize((int(width*scale), int(height*scale)), m)
        try:
            im = pad(im)
        except:
            return None, None
        if im is None:
            print(path, 'not found!')
            continue
        im = np.array(im)
        im = cv2.cvtColor(im, cv2.COLOR_BGR2RGB)
        images.append(dataloader.transform(image=im)['image'][:1])
        if images[-1].shape[-1] > x:
            x = images[-1].shape[-1]
        if images[-1].shape[-2] > y:
            y = images[-1].shape[-2]
    if x > dataloader.max_dimensions[0] or y > dataloader.max_dimensions[1]:
        return None, None
    for i in range(len(images)):
        h, w = images[i].shape[1:]
        images[i] = F.pad(images[i], (0, x-w, 0, y-h), value=0)
    try:
        images = torch.cat(images).float().unsqueeze(1)
    except RuntimeError as e:
        #print(e, 'Images not working: %s' % (' '.join(list(ims))))
        return None, None
    dataloader.i += 1
    labels = torch.tensor(width//32-1).repeat(len(ims)).long()
    return images, labels

def filter(
        self,
        files: list[Path],
        explicit_patterns: list[str] | None = None,
    ) -> FilterResult:
        result = FilterResult()
        explicit_patterns = explicit_patterns or []

        for file in files:
            # Make path relative to flow_dir for pattern matching
            try:
                rel_path = str(file.relative_to(self.flow_dir))
            except ValueError:
                # File not under flow_dir - try with resolved paths
                try:
                    rel_path = str(file.resolve().relative_to(self.flow_dir))
                except ValueError:
                    # Can't make relative - just use name
                    rel_path = file.name

            # Auto-exclude .prefectignore files (hardcoded behavior)
            if rel_path.endswith(".prefectignore") or file.name == ".prefectignore":
                result.excluded_by_ignore.append(file)
                continue

            # Check against ignore spec
            excluded = False
            if self._spec is not None:
                if self._spec.match_file(rel_path):
                    excluded = True

            if excluded:
                result.excluded_by_ignore.append(file)

                # Check if this file was explicitly included by user
                for pattern in explicit_patterns:
                    # Check if the explicit pattern matches this file
                    if self._matches_explicit_pattern(rel_path, pattern):
                        result.explicitly_excluded.append(
                            f"File '{rel_path}' was explicitly included but is "
                            f"excluded by .prefectignore. Edit .prefectignore to include it."
                        )
                        break
            else:
                result.included_files.append(file)

        return result

def get_mwt(*dep_datasets):
    mwt_map = {}
    for dataset in dep_datasets:
        for sentence in dataset.sentences:
            for token in sentence.tokens:
                if len(token.words) == 1:
                    continue
                # words such as "accorgermene" we just skip over
                # those are already expanded in the constituency dataset
                # TODO: the clitics are actually expanded weirdly, maybe need to compensate for that
                if token.words[0].upos in ('VERB', 'AUX') and all(word.upos == 'PRON' for word in token.words[1:]):
                    continue
                if token.text.lower() in EXCEPTIONS:
                    continue
                if len(token.words) != 2 or token.words[0].upos != 'ADP' or token.words[1].upos != 'DET':
                    raise ValueError("Not sure how to handle this: {}".format(token))
                expansion = (token.words[0].text, token.words[1].text)
                if token.text in mwt_map:
                    if mwt_map[token.text] != expansion:
                        raise ValueError("Inconsistent MWT: {} -> {} or {}".format(token.text, expansion, mwt_map[token.text]))
                    continue
                #print("Expanding {} to {}".format(token.text, expansion))
                mwt_map[token.text] = expansion
    return mwt_map

def build_dataset_dag_ids(datasets: Dict[str, Any], target_dataset_id: str) -> List[str]:
    if not isinstance(datasets, dict) or not target_dataset_id:
        return []

    visited: set[str] = set()
    visiting: set[str] = set()
    order: list[str] = []

    def visit(did: str):
        if did in visited:
            return
        if did in visiting:
            # Cycle; bail out (shouldn't happen, but be defensive)
            return
        visiting.add(did)
        entry = datasets.get(did)
        if isinstance(entry, dict):
            for pid in _parent_ids(entry):
                if isinstance(pid, str) and pid and pid in datasets:
                    visit(pid)
        visiting.remove(did)
        visited.add(did)
        order.append(did)

    visit(target_dataset_id)
    return order

def get_transformers_submodules() -> list[str]:
    submodules = []
    for path, directories, files in os.walk(PATH_TO_TRANSFORMERS):
        for folder in directories:
            # Ignore private modules
            if folder.startswith("_"):
                directories.remove(folder)
                continue
            # Ignore leftovers from branches (empty folders apart from pycache)
            if len(list((Path(path) / folder).glob("*.py"))) == 0:
                continue
            short_path = str((Path(path) / folder).relative_to(PATH_TO_TRANSFORMERS))
            submodule = short_path.replace(os.path.sep, ".")
            submodules.append(submodule)
        for fname in files:
            if fname == "__init__.py":
                continue
            short_path = str((Path(path) / fname).relative_to(PATH_TO_TRANSFORMERS))
            submodule = short_path.replace(".py", "").replace(os.path.sep, ".")
            if len(submodule.split(".")) == 1:
                submodules.append(submodule)
    return submodules

def pr(left, right):
            if left is None:
                return right
            elif right is None:
                return left

            k = klass
            if isinstance(left, ConditionBinOp):
                if isinstance(right, ConditionBinOp):
                    k = JointConditionBinOp
                elif isinstance(left, k):
                    return left
                elif isinstance(right, k):
                    return right

            elif isinstance(left, FilterBinOp):
                if isinstance(right, FilterBinOp):
                    k = JointFilterBinOp
                elif isinstance(left, k):
                    return left
                elif isinstance(right, k):
                    return right

            return k(
                self.op, left, right, queryables=self.queryables, encoding=self.encoding
            ).evaluate()

