def quaternion_slerp(
    quat0: NDArray, quat1: NDArray, fraction: float, spin: int = 0, shortestpath: bool = True
) -> np.ndarray:
    q0 = unit_vector(quat0[:4])
    q1 = unit_vector(quat1[:4])
    if q0 is None or q1 is None:
        raise ValueError("Input quaternions invalid.")
    if fraction == 0.0:
        return q0
    if fraction == 1.0:
        return q1
    d = np.dot(q0, q1)
    if abs(abs(d) - 1.0) < _EPS:
        return q0
    if shortestpath and d < 0.0:
        # invert rotation
        d = -d
        np.negative(q1, q1)
    angle = math.acos(d) + spin * math.pi
    if abs(angle) < _EPS:
        return q0
    isin = 1.0 / math.sin(angle)
    q0 *= math.sin((1.0 - fraction) * angle) * isin
    q1 *= math.sin(fraction * angle) * isin
    q0 += q1
    return q0

def to_fd(x, dtype=None):
    if isinstance(x, OrderedDict):
        if dtype:
            if not is_dtype(x, dtype):
                return cast_fd(x, dtype)
        return x
    elif isinstance(x, np.ndarray):
        return np_to_fd(x, dtype=dtype)
    elif isinstance(x, pd.DataFrame):
        return df_to_fd(x, dtype=dtype)
    elif isinstance(x, dict):
        if dtype:
            if not is_dtype(x, dtype):
                return cast_fd(x, dtype)
        return OrderedDict((key, x[key]) for key in x)
    else:
        raise NotImplementedError('unknown type {}'.format(str(type(x))))

def convert_pandas_to_listDataset(pd_dataframe: pd.DataFrame):
    # use numpy to implement abstraction of gluonTS ListDataset
    import numpy as np

    # For non-multiindexed DataFrames
    if not isinstance(pd_dataframe.index, pd.MultiIndex):
        start_datetime = pd_dataframe.index[0]

        target_columns = pd_dataframe.columns.difference(["instances", "timepoints"])
        target_values = pd_dataframe[target_columns].to_numpy().astype(np.float32)

        if isinstance(pd_dataframe.index, pd.DatetimeIndex):
            freq = pd_dataframe.index.inferred_freq

        elif isinstance(pd_dataframe.index, pd.PeriodIndex):
            freq = pd_dataframe.index.freq

        else:
            start_datetime = pd.Timestamp(start_datetime)
            freq = "D"

        return [
            {
                "start": pd.Period(start_datetime, freq),
                "target": target_values,
            }
        ]

    list_dataset = []

    # Obtain the total amount of timesteps to assist with inferring frequency
    time_index = pd_dataframe.index.get_level_values(1)
    freq = None

    if isinstance(time_index, pd.DatetimeIndex):
        freq = time_index.inferred_freq

    elif isinstance(time_index, pd.PeriodIndex):
        freq = time_index.freq

    if freq is None:
        freq = "D"

    # By maintaining 2 levels in the DataFrame's indices
    # we can access each series and its timestep values with ease!
    for _, data in pd_dataframe.groupby(level=0):
        data = data.reset_index(level=0, drop=True)

        # Getting the starting time for each series
        start_datetime = data.index[0]

        if not isinstance(data.index, (pd.DatetimeIndex, pd.PeriodIndex)):
            start_datetime = pd.Timestamp(start_datetime)

        # Isolating multivariate values for each time series
        target_column = data.columns.difference(["instances"])

        target_values = data[target_column].to_numpy().astype(np.float32)

        list_dataset.append(
            {
                "start": pd.Period(start_datetime, freq),
                "target": target_values,
            }
        )

    return list_dataset

async def exception_to_failed_state(
    exc: Optional[BaseException] = None,
    result_store: Optional["ResultStore"] = None,
    write_result: bool = False,
    **kwargs: Any,
) -> State[BaseException]:
    try:
        local_logger = get_run_logger()
    except MissingContextError:
        local_logger = logger

    if not exc:
        _, exc, _ = sys.exc_info()
        if exc is None:
            raise ValueError(
                "Exception was not passed and no active exception could be found."
            )
    else:
        pass

    if result_store:
        key = uuid.uuid4().hex
        data = result_store.create_result_record(exc, key=key)
        if write_result:
            try:
                await result_store.apersist_result_record(data)
            except Exception as nested_exc:
                local_logger.warning(
                    "Failed to write result: %s Execution will continue, but the result has not been written",
                    nested_exc,
                )
    else:
        # Attach the exception for local usage, will not be available when retrieved
        # from the API
        data = exc

    existing_message = kwargs.pop("message", "")
    if existing_message and not existing_message.endswith(" "):
        existing_message += " "

    # TODO: Consider if we want to include traceback information, it is intentionally
    #       excluded from messages for now
    message = existing_message + format_exception(exc)

    state = Failed(data=data, message=message, **kwargs)
    state.state_details.retriable = False

    return state

def autotune_batch_size(self, requested_batch_size: int) -> int:
        dev_lower = str(self.device).lower()
        use_accel = dev_lower.startswith(
            ("cuda", "0", "1", "2", "3", "4", "5", "6", "7", "mps", "metal")
        )
        if not use_accel:
            return max(1, requested_batch_size)

        def _empty_cache():
            if dev_lower.startswith("cuda") and torch.cuda.is_available():
                torch.cuda.empty_cache()
            elif dev_lower.startswith(("mps", "metal")) and hasattr(torch, "mps"):
                try:
                    torch.mps.empty_cache()
                except Exception:
                    pass

        if isinstance(self.imgsz, (list, tuple)):
            h, w = int(self.imgsz[0]), int(self.imgsz[1])
        else:
            h = w = int(self.imgsz)
        dummy = np.zeros((h, w, 3), dtype=np.uint8)

        bs = max(1, int(requested_batch_size))
        while bs >= 1:
            try:
                self.detector([dummy] * bs, conf=0.25, iou=0.7, classes=None, agnostic_nms=False)
                if bs < requested_batch_size:
                    LOGGER.info(f"Auto-tuned batch size: {bs} (requested: {requested_batch_size})")
                return bs
            except RuntimeError as e:
                if "out of memory" not in str(e).lower():
                    raise
                _empty_cache()
                next_bs = max(1, bs - 1)
                LOGGER.warning(f"Batch size {bs} OOM; trying {next_bs}.")
                if next_bs == bs:
                    break
                bs = next_bs

        raise RuntimeError("Unable to run even batch size 1; reduce image size or move to CPU.")

def get_weight_decay_parameters(
    modules: Iterable[Module],
    decay_norm: bool = False,
    decay_bias: bool = False,
    norm_layers: Tuple[Type[Module], ...] = _NORM_LAYERS,
) -> Tuple[List[Parameter], List[Parameter]]:
    params = []
    params_no_weight_decay = []

    # Iterate through each module and categorize its parameters into ones that should be decayed and those that should not
    for module in modules:
        for mod in module.modules():
            if isinstance(mod, norm_layers):
                if not decay_norm:
                    params_no_weight_decay.extend(mod.parameters(recurse=False))
                else:
                    params.extend(mod.parameters(recurse=False))
            else:
                for name, param in mod.named_parameters(recurse=False):
                    if not decay_bias and name.endswith("bias"):
                        params_no_weight_decay.append(param)
                    else:
                        params.append(param)
    return params, params_no_weight_decay

def style_generator(kw):
    kw_iterators = {}
    remaining_kw = {}
    for key, value in kw.items():
        if key in ['facecolor', 'edgecolor']:
            if value is None or cbook._str_lower_equal(value, 'none'):
                kw_iterators[key] = itertools.repeat(value)
            else:
                check_non_empty(key, value)
                kw_iterators[key] = itertools.cycle(mcolors.to_rgba_array(value))

        elif key in ['hatch', 'linewidth']:
            check_non_empty(key, value)
            kw_iterators[key] = itertools.cycle(np.atleast_1d(value))

        elif key == 'linestyle':
            check_non_empty(key, value)
            kw_iterators[key] = itertools.cycle(mlines._get_dash_patterns(value))

        else:
            remaining_kw[key] = value

    def style_gen():
        while True:
            yield {key: next(val) for key, val in kw_iterators.items()}

    return remaining_kw, style_gen()

def get_embeddings(self, pipeline: ExtractRunner) -> None:
        embeds: dict[str, npt.NDArray[np.float32]] = {}
        non_aligned: dict[str, npt.NDArray[np.uint8]] = {}
        aligned: dict[str, tuple[PNGHeader, npt.NDArray[np.uint8]]] = {}

        for filepath in self._filter_files.union(self._nfilter_files):
            with open(filepath, "rb") as in_file:
                raw_image = in_file.read()

            meta = self._get_meta(filepath, raw_image)
            if meta is not None:
                idn = meta.alignments.identity
                embed = np.array(idn.get(self._runner.handler.storage_name, []),
                                 dtype="float32")
                if np.any(embed):
                    logger.debug("[IdentityFilter] Identity from header '%s'. Shape: %s",
                                 filepath, embed.shape)
                    embeds[filepath] = embed
                    continue

            image = T.cast("npt.NDArray[np.uint8]",
                           cv2.imdecode(np.frombuffer(raw_image, dtype="uint8"), cv2.IMREAD_COLOR))

            if meta is None:
                non_aligned[filepath] = image
                continue

            logger.debug("[IdentityFilter] No identity in header: '%s'", filepath)
            aligned[filepath] = (meta, image)

        if aligned or non_aligned:
            logger.info("Extracting faces for Identity Filter...")
        if non_aligned:
            embeds |= self._from_pipeline(pipeline, non_aligned)
        if aligned:
            embeds |= self._from_plugin(aligned)
        self._add_embeds_to_plugin(embeds)

def rank_classes_by_multilabel_quality(
    labels=None,
    pred_probs=None,
    *,
    class_names=None,
    joint=None,
    confident_joint=None,
) -> pd.DataFrame:

    issues_df = common_multilabel_issues(
        labels=labels, pred_probs=pred_probs, class_names=class_names, confident_joint=joint
    )
    issues_dict = defaultdict(defaultdict)  # type: Dict[str, Any]
    num_examples = _get_num_examples_multilabel(labels=labels, confident_joint=confident_joint)
    return_columns = [
        "Class Name",
        "Class Index",
        "Label Issues",
        "Inverse Label Issues",
        "Label Noise",
        "Inverse Label Noise",
        "Label Quality Score",
    ]
    if class_names is None:
        return_columns = return_columns[1:]
    for class_num, row in issues_df.iterrows():
        if row["In Given Label"]:
            if class_names is not None:
                issues_dict[row["Class Index"]]["Class Name"] = row["Class Name"]
            issues_dict[row["Class Index"]]["Label Issues"] = int(
                row["Issue Probability"] * num_examples
            )
            issues_dict[row["Class Index"]]["Label Noise"] = row["Issue Probability"]
            issues_dict[row["Class Index"]]["Label Quality Score"] = (
                1 - issues_dict[row["Class Index"]]["Label Noise"]
            )
        else:
            if class_names is not None:
                issues_dict[row["Class Index"]]["Class Name"] = row["Class Name"]
            issues_dict[row["Class Index"]]["Inverse Label Issues"] = int(
                row["Issue Probability"] * num_examples
            )
            issues_dict[row["Class Index"]]["Inverse Label Noise"] = row["Issue Probability"]

    issues_df_dict = defaultdict(list)
    for i in issues_dict:
        issues_df_dict["Class Index"].append(i)
        for j in issues_dict[i]:
            issues_df_dict[j].append(issues_dict[i][j])
    return (
        pd.DataFrame.from_dict(issues_df_dict)
        .sort_values(by="Label Quality Score", ascending=True)
        .reset_index(drop=True)
    )[return_columns]

def from_result(
        cls,
        res: requests.Response,
        request_cls: Optional[Type] = None,
        logger: Optional[logging.Logger] = None,
        service: Optional[str] = None,
        action: Optional[str] = None,
        session: Optional[Any] = None,
    ) -> "CallResult":
        response_cls = get_response_cls(request_cls)

        if res is None:
            return cls._make_raw_response(request_cls=request_cls, service=service, action=action)

        try:
            data = res.json()
        except ValueError:
            return cls._make_raw_response(
                request_cls=request_cls,
                service=service,
                action=action,
                status_code=res.status_code,
                text=res.text,
            )
        if "meta" not in data:
            raise ValueError("Missing meta section in response payload")
        try:
            meta = ResponseMeta(**data["meta"])
            # TODO: validate meta?
            # meta.validate()
        except Exception as ex:
            raise ValueError("Failed parsing meta section in response payload (data=%s, error=%s)" % (data, ex))

        response = None
        response_data = None
        try:
            response_data = data.get("data", {})
            if response_cls:
                response = response_cls(**response_data)
                # TODO: validate response?
                # response.validate()
        except Exception as e:
            if logger:
                logger.warning("Failed parsing response: %s" % str(e))
        return cls(
            meta=meta,
            response=response,
            response_data=response_data,
            request_cls=request_cls,
            session=session,
        )

def convert(
        self,
        input_dict: dict[str, torch.Tensor],
        source_patterns: list[str] | None = None,
        model: torch.nn.Module | None = None,
        full_layer_name: str | None = None,
        missing_keys=None,
        **kwargs,
    ) -> dict[str, torch.Tensor]:
        is_unsafe_serialization = list(input_dict.keys())[0] not in source_patterns

        param_data = {}
        layer_name = ".".join(full_layer_name.split(".")[:-1])
        if is_unsafe_serialization:
            if isinstance(input_dict["weight"], list):
                weight = input_dict["weight"][0]
            else:
                weight = input_dict["weight"]
        else:
            for suffix in input_dict.keys():
                if len(input_dict[suffix]) != 1:
                    raise ValueError(
                        f"Expected a single tensor for {suffix} but got {len(input_dict[suffix])} tensors instead"
                    )
                param_data[f"{layer_name}.{suffix}"] = input_dict[suffix][0]

        # If it's unsafe-serialized (i.e. not safetensors), no need for anything
        if is_unsafe_serialization:
            return {full_layer_name: weight}
        elif not is_metadata_torchao(self.hf_quantizer.metadata):
            raise ValueError("Invalid torchao safetensors metadata")

        unflattened_state_dict, leftover_state_dict = unflatten_tensor_state_dict(
            param_data, self.hf_quantizer.metadata
        )
        assert not leftover_state_dict  # there should be no unprocessed tensors
        new_param = unflattened_state_dict[full_layer_name]

        module, _ = get_module_from_name(model, full_layer_name)
        # Add repr to the module
        if isinstance(module, torch.nn.Linear):
            module.extra_repr = types.MethodType(_linear_extra_repr, module)

        return {full_layer_name: new_param}

def reliability_check(self):
        if self.agents is None or len(self.agents) == 0:
            raise ValueError("Agents list cannot be None or empty")

        if self.max_loops == 0:
            raise ValueError("max_loops cannot be 0")

        if self.multi_agent_collab_prompt is True:
            for agent in self.agents:
                if hasattr(agent, "system_prompt"):
                    if agent.system_prompt is None:
                        agent.system_prompt = ""
                    agent.system_prompt += MULTI_AGENT_COLLAB_PROMPT
                else:
                    logger.warning(
                        f"Agent {getattr(agent, 'name', str(agent))} does not have a 'system_prompt' attribute."
                    )

        logger.info(
            f"Sequential Workflow Name: {self.name} is ready to run."
        )

def spaces_in_path(path: str | Path):
    # If path has spaces, replace them with underscores
    if " " in str(path):
        string = isinstance(path, str)  # input type
        path = Path(path)

        # Create a temporary directory and construct the new path
        with tempfile.TemporaryDirectory() as tmp_dir:
            tmp_path = Path(tmp_dir) / path.name.replace(" ", "_")

            # Copy file/directory
            if path.is_dir():
                shutil.copytree(path, tmp_path)
            elif path.is_file():
                tmp_path.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(path, tmp_path)

            try:
                # Yield the temporary path
                yield str(tmp_path) if string else tmp_path

            finally:
                # Copy file/directory back
                if tmp_path.is_dir():
                    shutil.copytree(tmp_path, path, dirs_exist_ok=True)
                elif tmp_path.is_file():
                    shutil.copy2(tmp_path, path)  # Copy back the file

    else:
        # If there are no spaces, just yield the original path
        yield path

def state(self, state):
    if isinstance(state, dict) and state == GET_STATE_FROM_CACHE:
      return
    if not self._sublayers:
      self._state = state
    else:
      # When having sublayers, self._state just marks which are cached,
      # the actual weights are stored by sublayers.
      self._state = []
      for s in state:
        if isinstance(s, dict) and s == GET_STATE_FROM_CACHE:
          self._state.append(s)
        else:
          self._state.append(None)
      # Set sublayer states.
      n_layers = len(self.sublayers)
      if len(state) != n_layers:
        raise ValueError(
            f'Number of state elements ({len(state)}) does not equal the '
            f'number of sublayers ({n_layers}) in: {str(self)}.')
      for sublayer, sublayer_state in zip(self.sublayers, state):
        sublayer.state = sublayer_state

def combine_tfr(all_tfr, weights="nave"):
    if any("taper" in tfr._dims for tfr in all_tfr):
        raise NotImplementedError(
            "Aggregating multitaper tapers across TFR datasets is not supported."
        )

    tfr = all_tfr[0].copy()
    if isinstance(weights, str):
        if weights not in ("nave", "equal"):
            raise ValueError('Weights must be a list of float, or "nave" or "equal"')
        if weights == "nave":
            weights = np.array([e.nave for e in all_tfr], float)
            weights /= weights.sum()
        else:  # == 'equal'
            weights = [1.0 / len(all_tfr)] * len(all_tfr)
    weights = np.array(weights, float)
    if weights.ndim != 1 or weights.size != len(all_tfr):
        raise ValueError("Weights must be the same size as all_tfr")

    ch_names = tfr.ch_names
    for t_ in all_tfr[1:]:
        assert t_.ch_names == ch_names, (
            f"{tfr} and {t_} do not contain the same channels"
        )
        assert np.max(np.abs(t_.times - tfr.times)) < 1e-7, (
            f"{tfr} and {t_} do not contain the same time instants"
        )

    # use union of bad channels
    bads = list(set(tfr.info["bads"]).union(*(t_.info["bads"] for t_ in all_tfr[1:])))
    tfr.info["bads"] = bads

    # XXX : should be refactored with combined_evoked function
    tfr.data = sum(w * t_.data for w, t_ in zip(weights, all_tfr))
    tfr.nave = max(int(1.0 / sum(w**2 / e.nave for w, e in zip(weights, all_tfr))), 1)
    return tfr

def write_js_metadata(pkg_data, project_shortname, has_wildcards):
    function_string = generate_js_metadata(
        pkg_data=pkg_data, project_shortname=project_shortname
    )
    file_name = "internal.R"

    # the R source directory for the package won't exist on first call
    # create the R directory if it is missing
    if not os.path.exists("R"):
        os.makedirs("R")

    file_path = os.path.join("R", file_name)
    with open(file_path, "w", encoding="utf-8") as f:
        f.write(function_string)
        if has_wildcards:
            f.write(wildcard_helper)

    # now copy over all JS dependencies from the (Python) components dir
    # the inst/lib directory for the package won't exist on first call
    # create this directory if it is missing
    if os.path.exists("inst/deps"):
        shutil.rmtree("inst/deps")

    os.makedirs("inst/deps")

    for rel_dirname, _, filenames in os.walk(project_shortname):
        for filename in filenames:
            extension = os.path.splitext(filename)[1]

            if extension in [".py", ".pyc", ".json"]:
                continue

            target_dirname = os.path.join(
                os.path.join(
                    "inst/deps/", os.path.relpath(rel_dirname, project_shortname)
                )
            )

            if not os.path.exists(target_dirname):
                os.makedirs(target_dirname)

            shutil.copy(os.path.join(rel_dirname, filename), target_dirname)

def override_config(self, parameters, key=None, value=None, key_value_dict=None):
        self.uses_config_override = True
        if isinstance(parameters, torch.nn.Parameter):
            parameters = [parameters]
        if isinstance(parameters, torch.Tensor):
            parameters = [parameters]
        if key is not None and value is not None:
            assert key_value_dict is None
            key_value_dict = {key: value}

        if key_value_dict is not None:
            for p in parameters:
                if id(p) in self.pid2config:
                    self.pid2config[id(p)].update(key_value_dict)
                else:
                    self.pid2config[id(p)] = key_value_dict

def convert_file_size_to_int(size: int | str):
    if isinstance(size, int):
        return size
    if size.upper().endswith("GIB"):
        return int(size[:-3]) * (2**30)
    if size.upper().endswith("MIB"):
        return int(size[:-3]) * (2**20)
    if size.upper().endswith("KIB"):
        return int(size[:-3]) * (2**10)
    if size.upper().endswith("GB"):
        int_size = int(size[:-2]) * (10**9)
        return int_size // 8 if size.endswith("b") else int_size
    if size.upper().endswith("MB"):
        int_size = int(size[:-2]) * (10**6)
        return int_size // 8 if size.endswith("b") else int_size
    if size.upper().endswith("KB"):
        int_size = int(size[:-2]) * (10**3)
        return int_size // 8 if size.endswith("b") else int_size
    raise ValueError("`size` is not in a valid format. Use an integer followed by the unit, e.g., '5GB'.")

def get_pip_packages(run_lambda):
    # People generally have `pip` as `pip` or `pip3`
    def run_with_pip(pip):
        if get_platform() == "win32":
            grep_cmd = r"findstr /R 'numpy torch catalyst tensorflow tensorboard'"
        else:
            grep_cmd = r"grep 'torch\|numpy\|catalyst\|tensorflow\|tensorboard'"
        return run_and_read_all(run_lambda, pip + " list --format=freeze | " + grep_cmd)

    # Try to figure out if the user is running pip or pip3.
    out2 = run_with_pip("pip")
    out3 = run_with_pip("pip3")

    num_pips = len([x for x in [out2, out3] if x is not None])
    if num_pips == 0:
        return "pip", out2

    if num_pips == 1:
        if out2 is not None:
            return "pip", out2
        return "pip3", out3

    # num_pips is 2. Return pip3 by default b/c that most likely
    # is the one associated with Python 3
    return "pip3", out3

def lazily_locate_dotted_path(dotted_path):
    _validate_dotted_path(dotted_path)
    parts = dotted_path.split(".")

    module_name = ".".join(parts[:-1])
    first, middle, mod, symbol = parts[0], parts[1:-2], parts[-2], parts[-1]

    spec = importlib.util.find_spec(first)

    if spec is None:
        raise ModuleNotFoundError(
            "Error processing dotted "
            f"path {dotted_path!r}, "
            f"no module named {first!r}"
        )

    if spec.origin is None:
        raise ModuleNotFoundError(
            "Error processing dotted "
            f"path {dotted_path!r}: "
            f"{first!r} appears to be a namespace "
            "package, which are not supported"
        )

    origin = Path(spec.origin)
    location = origin.parent

    # a.b.c.d.e.f
    # a/__init__.py or a.py must exist
    # from b until d, there must be {name}/__init__.py
    # there must be e/__init__.py or e.py
    # f must be a symbol defined at e.py or e/__init__.py

    if len(parts) == 2:
        return _check_defines_function_with_name(origin, symbol, dotted_path)

    location = reduce(lambda x, y: x / y, [location] + middle)

    init = location / mod / "__init__.py"
    file_ = location / f"{mod}.py"

    if init.exists():
        return _check_defines_function_with_name(init, symbol, dotted_path)
    elif file_.exists():
        return _check_defines_function_with_name(file_, symbol, dotted_path)
    else:
        raise ModuleNotFoundError(
            f"No module named {module_name!r}. "
            f"Expected to find one of {str(init)!r} or "
            f"{str(file_)!r}, but none of those exist"
        )

def clean_sentence(line):
    # We remove some special characters and fix small errors in the data, to improve the quality of the data
    line = line.replace("\n", '') #{"text": "- Mor.\n", "label": "da"}
    line = line.replace("- ", '') #{"text": "- Mor.", "label": "da"}
    line = line.replace("_", '') #{"text": "- Mor.", "label": "da"}
    line = line.replace("\\", '')
    line = line.replace("\"", '')
    line = line.replace("  ", " ")
    remove_digits = str.maketrans('', '', digits)
    line = line.translate(remove_digits)
    words = line.split()
    new_words = []
    # Below fixes large I instead of l. Does not catch everything, but should also not really make any mistakes either
    for word in words:
        clean_word = word
        s = clean_word
        if clean_word[1:].__contains__("I"):
            indices = find(clean_word, "I")
            for indx in indices:
                if clean_word[indx-1].islower():
                    if len(clean_word) > indx + 1:
                        if clean_word[indx+1].islower():
                            s = s[:indx] + "l" + s[indx + 1:]
                    else:
                        s = s[:indx] + "l" + s[indx + 1:]
        new_words.append(s)
    new_line = " ".join(new_words)
    return new_line

def score_token_attr(
        examples: Iterable[Example],
        attr: str,
        *,
        getter: Callable[[Token, str], Any] = getattr,
        missing_values: Set[Any] = MISSING_VALUES,  # type: ignore[assignment]
        **cfg,
    ) -> Dict[str, Any]:
        tag_score = PRFScore()
        for example in examples:
            gold_doc = example.reference
            pred_doc = example.predicted
            align = example.alignment
            gold_tags = set()
            missing_indices = set()
            for gold_i, token in enumerate(gold_doc):
                value = getter(token, attr)
                if value not in missing_values:
                    gold_tags.add((gold_i, getter(token, attr)))
                else:
                    missing_indices.add(gold_i)
            pred_tags = set()
            for token in pred_doc:
                if token.orth_.isspace():
                    continue
                if align.x2y.lengths[token.i] == 1:
                    gold_i = align.x2y[token.i][0]
                    if gold_i not in missing_indices:
                        pred_tags.add((gold_i, getter(token, attr)))
            tag_score.score_set(pred_tags, gold_tags)
        score_key = f"{attr}_acc"
        if len(tag_score) == 0:
            return {score_key: None}
        else:
            return {score_key: tag_score.fscore}

def from_folder(cls, root, exts=('.jpg', '.jpeg', '.png'), no_class=False):
        if is_url(root):
            root = url_data(root)
        synsets = []
        items = {'image': [], 'label': []}
        if isinstance(root, Path):
            assert root.exists(), '{} not exist'.format(str(root))
            root = str(root.resolve())
        assert isinstance(root, str)
        root = os.path.abspath(os.path.expanduser(root))

        for folder in sorted(os.listdir(root)):
            path = os.path.join(root, folder)
            if not os.path.isdir(path):
                logger.debug('Ignoring %s, which is not a directory.', path, stacklevel=3)
                continue
            label = len(synsets)
            synsets.append(folder)
            for filename in sorted(os.listdir(path)):
                filename = os.path.join(path, filename)
                ext = os.path.splitext(filename)[1]
                if ext.lower() not in exts:
                    logger.debug('Ignoring %s of type %s. Only support %s',
                                 filename, ext, ', '.join(exts))
                    continue
                items['image'].append(filename)
                items['label'].append(label)
        return cls(items, classes=synsets, no_class=no_class)

def list_modified_files(self, dataset_id: str = None) -> List[str]:
        datasets = self._dependency_graph[self._id] if not dataset_id or dataset_id == self._id else [dataset_id]
        unified_list = dict()
        for ds_id in datasets:
            dataset = self.get(dataset_id=ds_id)
            unified_list.update(dict((k, v.hash) for k, v in dataset._dataset_file_entries.items()))
        modified_list = [
            k for k, v in self._dataset_file_entries.items() if k in unified_list and v.hash != unified_list[k]
        ]
        unified_list_sizes = dict()
        for ds_id in datasets:
            dataset = self.get(dataset_id=ds_id)
            for k, v in dataset._dataset_link_entries.items():
                unified_list_sizes[k] = v.size
                if k in dataset._dataset_file_entries:
                    unified_list_sizes[k] = dataset._dataset_file_entries[k].size
        for k, v in self._dataset_link_entries.items():
            if k not in unified_list_sizes:
                continue
            size = v.size
            if k in self._dataset_file_entries:
                size = self._dataset_file_entries[k].size
            if size != unified_list_sizes[k]:
                modified_list.append(k)
        return sorted(list(set(modified_list)))

def serialize_exception(e: BaseException) -> Dict[str, Any]:
    # Wrap unsafe exceptions before serialization
    e = wrap_exception(e)

    stacktrace = getattr(e, 'stacktrace', None)
    attributes = e.__dict__.copy()
    if 'stacktrace' in attributes:
        del attributes['stacktrace']
    for attr_k in list(attributes.keys()):
        attr_v = attributes[attr_k]
        if isinstance(attr_v, types.TracebackType):
            attributes[attr_k] = traceback.format_tb(attr_v)
        if isinstance(attr_v, backend.ResourceHandle):
            attributes[attr_k] = (
                serialize_utils.prepare_handle_for_backwards_compatibility(
                    attr_v))

    data = {
        'type': e.__class__.__name__,
        'message': str(e),
        'args': e.args,
        'attributes': attributes,
        'stacktrace': stacktrace,
    }
    if isinstance(e, SkyPilotExcludeArgsBaseException):
        data['args'] = tuple()
    return data

def get_attr(self, qualified_name: str, type_expr: Optional[Any] = None) -> fx.Node:
        node = self._graph.get_attr(qualified_name, type_expr)

        # Gets the actual value of the attribute if it exists so that we can use
        # it to set the 'spec' metadata
        def _maybe_get_attr_value(
            mod: torch.nn.Module, qualified_name: str
        ) -> Optional[torch.Tensor]:
            module_path, _, name = qualified_name.rpartition(".")

            try:
                submod: torch.nn.Module = mod.get_submodule(module_path)
            except AttributeError:
                warnings.warn(f"Failed to fetch module {module_path}!", stacklevel=1)
                return None

            # See if the value is a buffer
            if name in submod._buffers:
                return submod._buffers[name]

            # See if the value is a parameter
            if hasattr(submod, name):
                attr = getattr(submod, name)
                if isinstance(attr, torch.nn.Parameter):
                    return attr

            return None

        buffer = _maybe_get_attr_value(self.owning_module, qualified_name)
        if buffer is not None:
            node.meta["spec"] = TensorSpec.from_tensor(buffer, True)

        return node

def replace_table_and_column_names(query, table_mapping):
        # Pre-parse all subqueries in mapping to avoid repeated parsing
        parsed_mapping = {}
        for key, value in table_mapping.items():
            try:
                parsed_mapping[key] = parse_one(value)
            except ParseError:
                raise ValueError(f"{value} is not a valid SQL expression")

        def transform_node(node):
            # Handle Table nodes
            if isinstance(node, exp.Table):
                original_name = node.name

                if original_name in table_mapping:
                    alias = node.alias or original_name
                    mapped_value = parsed_mapping[original_name]
                    if isinstance(mapped_value, exp.Alias):
                        return exp.Subquery(
                            this=mapped_value.this.this,
                            alias=alias,
                        )
                    elif isinstance(mapped_value, exp.Column):
                        return exp.Table(this=mapped_value.this, alias=alias)
                    return exp.Subquery(this=mapped_value, alias=alias)

            return node

        # Parse the SQL query
        parsed = parse_one(query)

        # Transform the query
        transformed = parsed.transform(transform_node)
        transformed = transformed.transform(quote_identifiers)

        # Convert back to SQL string
        return transformed.sql(pretty=True)

def read_superlink_connection(
    connection_name: str | None = None,
) -> SuperLinkConnection:
    toml_dict, config_path = read_flower_config()

    try:
        superlink_config = toml_dict.get(SuperLinkConnectionTomlKey.SUPERLINK, {})

        # Load the default SuperLink connection when not provided
        if connection_name is None:
            connection_name = superlink_config.get(SuperLinkConnectionTomlKey.DEFAULT)

        # Exit when no connection name is available
        if connection_name is None:
            raise click.ClickException(
                "No SuperLink connection set. A SuperLink connection needs to be "
                "provided or one must be set as default in the Flower "
                f"configuration file ({config_path}). Specify a default SuperLink "
                "connection by adding: \n\n[superlink]\ndefault = 'connection_name'\n\n"
                f"to the Flower configuration file ({config_path})."
            )

        # Try to find the connection with the given name
        if connection_name not in superlink_config:
            msg = (
                f"SuperLink connection '{connection_name}' not found in the "
                f"Flower configuration file ({config_path})."
            )
            # If default was used, show a specific error message
            if connection_name == superlink_config.get(
                SuperLinkConnectionTomlKey.DEFAULT
            ):
                msg += (
                    f"\nPlease check that the default connection '{connection_name}' "
                    "is defined in the [superlink] section."
                )
            raise click.ClickException(msg)

        conn_dict = superlink_config[connection_name]
        return parse_superlink_connection(conn_dict, connection_name)

    except ValueError as err:
        raise click.ClickException(
            f"Failed to parse the Flower configuration file ({config_path}). {err}"
        ) from err
    except Exception as err:
        raise click.ClickException(
            f"An unexpected error occurred while reading the Flower configuration "
            f"file ({config_path}). {err}"
        ) from err

def minify_files(html: bool = True, css: bool = True, js: bool = True):
    minify, compress, jsmin = None, None, None
    try:
        if html:
            from minify_html import minify
        if css:
            from csscompressor import compress
        if js:
            import jsmin
    except ImportError as e:
        LOGGER.info(f"Missing required package: {e}")
        return

    stats = {}
    for ext, minifier in {
        "html": (lambda x: minify(x, keep_closing_tags=True, minify_css=True, minify_js=True)) if html else None,
        "css": compress if css else None,
        "js": jsmin.jsmin if js else None,
    }.items():
        orig = minified = 0
        files = list(SITE.rglob(f"*.{ext}"))
        if not files:
            continue
        pbar = TQDM(files, desc=f"Minifying {ext.upper()} - reduced 0.00% (0.00 KB saved)")
        for f in pbar:
            content = f.read_text(encoding="utf-8")
            out = minifier(content) if minifier else remove_comments_and_empty_lines(content, ext)
            orig += len(content)
            minified += len(out)
            f.write_text(out, encoding="utf-8")
            saved = orig - minified
            pct = (saved / orig) * 100 if orig else 0.0
            pbar.set_description(f"Minifying {ext.upper()} - reduced {pct:.2f}% ({saved / 1024:.2f} KB saved)")
        stats[ext] = {"original": orig, "minified": minified}

def call_openai_api(
        self,
        api_address,
        api_key,
        model_id,
        prompt,
        temperature,
        max_tokens,
        system_prompt,
    ):
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        messages = []
        if system_prompt:
            messages.append({"role": "system", "content": system_prompt})

        if hasattr(self, "has_image_reference") and self.has_image_reference:
            with open(self.image_path, "rb") as f:
                image_data = base64.b64encode(f.read()).decode("utf-8")

            messages.append(
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:image/jpeg;base64,{image_data}"
                            },
                        },
                        {"type": "text", "text": prompt},
                    ],
                }
            )
        else:
            messages.append({"role": "user", "content": prompt})

        data = {
            "model": model_id,
            "messages": messages,
            "temperature": (
                temperature / 100.0 if temperature > 2 else temperature
            ),
            "max_tokens": max_tokens,
        }

        # Ensure API address ends with correct path
        if not api_address.endswith("/"):
            api_address += "/"
        if not api_address.endswith("chat/completions"):
            api_address += "chat/completions"

        response = requests.post(
            api_address, headers=headers, json=data, timeout=REQUEST_TIMEOUT
        )
        response.raise_for_status()

        result = response.json()
        return result["choices"][0]["message"]["content"].strip()

def evaluate(
        self,
        ground_truth: TimeSeries,
        predict: Union[TimeSeries, List[TimeSeries]],
        metric: ForecastMetric = ForecastMetric.sMAPE,
    ):
        if self.model.target_seq_index is not None:
            name = ground_truth.names[self.model.target_seq_index]
            ground_truth = ground_truth.univariates[name].to_ts()
        if isinstance(predict, TimeSeries):
            if metric is not None:
                return metric.value(ground_truth, predict)
            return accumulate_forecast_score(ground_truth, predict)
        else:
            if metric is not None:
                weights = np.asarray([len(p) for p in predict if not p.is_empty()])
                vals = [metric.value(ground_truth, p) for p in predict if not p.is_empty()]
                return np.dot(weights / weights.sum(), vals)
            return [accumulate_forecast_score(ground_truth, p) for p in predict if not p.is_empty()]

def add_slice(
        self, name, input_name, output_name, axis, start_index=0, end_index=-1, stride=1
    ):
        spec_layer = self._add_generic_layer(name, [input_name], [output_name])
        spec_layer_params = spec_layer.slice

        # Set the parameters
        if start_index < 0:
            raise ValueError(
                "Invalid start_index value %d. Must be non-negative." % start_index
            )
        if stride < 1:
            raise ValueError("Invalid stride value %d. Must be positive." % stride)

        spec_layer_params.startIndex = start_index
        spec_layer_params.endIndex = end_index
        spec_layer_params.stride = stride

        axis = axis.lower() if isinstance(axis, str) else axis
        if axis == "channel":
            spec_layer_params.axis = _proto.NeuralNetwork_pb2.SliceLayerParams.SliceAxis.Value(
                "CHANNEL_AXIS"
            )
        elif axis == "height":
            spec_layer_params.axis = _proto.NeuralNetwork_pb2.SliceLayerParams.SliceAxis.Value(
                "HEIGHT_AXIS"
            )
        elif axis == "width":
            spec_layer_params.axis = _proto.NeuralNetwork_pb2.SliceLayerParams.SliceAxis.Value(
                "WIDTH_AXIS"
            )
        else:
            raise NotImplementedError("Unsupported Slice axis %s " % axis)
        return spec_layer

def has_same_spark_config(spark_session, spark_config: SparkConfig) -> bool:
    if spark_session is None:
        return False

    if spark_config:
        if (spark_config.app_name and spark_config.app_name
                != spark_session.conf.get('spark.app.name')):
            print('Different spark.app.name found!')
            return False
        if (spark_config.spark_master and spark_config.spark_master
                != spark_session.conf.get('spark.master')):
            print('Different spark.master found!')
            return False
        if (spark_config.spark_home and spark_config.spark_home
                != spark_session.conf.get('spark.home')):
            print('Different spark.home found!')
            return False
        if spark_config.executor_env:
            for key, value in spark_config.executor_env.items():
                if spark_session.conf.get(f'spark.executorEnv.{key}') != value:
                    print(f'Different spark.executorEnv.{key} found!')
                    return False
        if (spark_config.spark_jars and not contains_same_jars(
                spark_config.spark_jars, spark_session.conf.get('spark.jars'))):
            print('Different spark.jars found!')
            return False
        if spark_config.others:
            for key, value in spark_config.others.items():
                if spark_session.conf.get(key) != value:
                    print(f'Different {key} found!')
                    return False
    return True

def cutout_on_volume(
    volume: np.ndarray,
    holes: np.ndarray,
    fill: tuple[float, ...] | float | Literal["random", "random_uniform", "inpaint_telea", "inpaint_ns"],
    random_generator: np.random.Generator,
) -> np.ndarray:
    volume = volume.copy()

    # Handle inpainting methods
    if isinstance(fill, str):
        if fill in {"inpaint_telea", "inpaint_ns"}:
            processed_images = [
                apply_inpainting(img, holes, cast("Literal['inpaint_telea', 'inpaint_ns']", fill)) for img in volume
            ]
            result = np.array(processed_images)
            # Reshape to original volume shape: (D, H, W, C) or (D, H, W)
            return result.reshape(volume.shape)
        if fill == "random":
            return fill_volume_holes_with_random(volume, holes, random_generator, uniform=False)
        if fill == "random_uniform":
            return fill_volume_holes_with_random(volume, holes, random_generator, uniform=True)
        raise ValueError(f"Unsupported string fill: {fill}")

    # Convert numeric fill values to numpy array
    if isinstance(fill, (int, float)):
        fill_array = np.array(fill, dtype=volume.dtype)
        return fill_volume_holes_with_value(volume, holes, fill_array)

    # Handle sequence fill values
    fill_array = np.array(fill, dtype=volume.dtype)

    # For multi-channel images, verify fill matches number of channels
    if volume.ndim == 4:
        fill_array = fill_array.ravel()
        if fill_array.size != volume.shape[3]:
            raise ValueError(
                f"Fill value must have same number of channels as image. "
                f"Got {fill_array.size}, expected {volume.shape[3]}",
            )

    return fill_volume_holes_with_value(volume, holes, fill_array)

def get_command(id: str, public: bool, private: bool, path: str | None):
    if public and private:
        console.print("[red]Cannot specify both --public and --private.[/red]")
        sys.exit(1)

    client = APIClient()
    ns = "auto"
    try:
        if public:
            tpl = client.template.get_public(id)
            ns = "public"
        elif private:
            tpl = client.template.get_private(id)
            ns = "private"
        else:
            pubs = client.template.list_public()
            in_public = any(t.metadata and t.metadata.id_ == id for t in pubs)
            if in_public:
                tpl = client.template.get_public(id)
                ns = "public"
            else:
                tpl = client.template.get_private(id)
                ns = "private"
    except Exception as e:
        console.print(f"[red]Failed to get template '{id}':[/] {e}")
        sys.exit(1)

    data = tpl.model_dump() if hasattr(tpl, "model_dump") else tpl.dict()

    if path:
        try:
            path = resolve_save_path(path, f"template_{id}.json")
        except PathResolutionError as e:
            console.print(f"[red]Failed to save template: {e}[/]")
            sys.exit(1)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        console.print(f"[bold green]Saved template ({ns}) to:[/bold green] {path}")
    else:
        console.print_json(data=data)

def check_min_api_version(cls, min_api_version: str, raise_error: bool = False) -> bool:
        # If no session was created, create a default one, in order to get the backend api version.
        if cls._sessions_created <= 0:
            if cls._offline_mode:
                # allow to change the offline mode version by setting ENV_OFFLINE_MODE to the required API version
                if cls.api_version != cls._offline_default_version:
                    offline_api = ENV_OFFLINE_MODE.get(converter=lambda x: x)
                    if offline_api:
                        try:
                            # check cast to float, but leave original str if we pass it.
                            # minimum version is 2.3
                            if float(offline_api) >= 2.3:
                                cls._offline_default_version = str(offline_api)
                        except ValueError:
                            pass
                    cls.max_api_version = cls.api_version = cls._offline_default_version
            else:
                # if the requested version is lower than the minimum we support,
                # no need to actually check what the server has, we assume it must have at least our version.
                if cls._version_tuple(cls.api_version) >= cls._version_tuple(str(min_api_version)):
                    return True

                # noinspection PyBroadException
                try:
                    cls()
                except (MissingConfigError, ConfigurationError):
                    if raise_error and not ENV_IGNORE_MISSING_CONFIG.get():
                        raise
                except LoginError:
                    if raise_error:
                        raise
                except Exception:
                    pass

        return cls._version_tuple(cls.api_version) >= cls._version_tuple(str(min_api_version))

