        result = shared_canvas.update_element(
            element_id=element_id,
            content=content,
            position=position,
            modified_by="fairy-tool",
        )

        if result:
            return json.dumps(
                {
                    "success": True,
                    "element_id": element_id,
                    "message": f"Updated element {element_id}",
                }
            )
        else:
            return json.dumps(
                {
                    "success": False,
                    "error": f"Element {element_id} not found",
                }
            )

def emit_registry_lineage(
        self,
        registry: "BaseRegistry",
        project: str,
        allow_cache: bool = True,
    ) -> List[bool]:
        if not self.is_enabled:
            return []

        from feast.feature_view import FeatureView
        from feast.on_demand_feature_view import OnDemandFeatureView
        from feast.stream_feature_view import StreamFeatureView

        results = []

        # Get all feature views at once (includes FeatureView, StreamFeatureView, OnDemandFeatureView)
        all_feature_views: list = []
        try:
            all_feature_views = registry.list_all_feature_views(
                project=project, allow_cache=allow_cache
            )
        except Exception as e:
            logger.error(f"Error listing all feature views: {e}")

        # Emit lineage events for each feature view type
        for fv in all_feature_views:
            try:
                if isinstance(fv, OnDemandFeatureView):
                    result = self.emit_on_demand_feature_view_lineage(fv, project)
                elif isinstance(fv, StreamFeatureView):
                    result = self.emit_stream_feature_view_lineage(fv, project)
                elif isinstance(fv, FeatureView):
                    result = self.emit_feature_view_lineage(fv, project)
                else:
                    continue
                results.append(result)
            except Exception as e:
                logger.error(f"Error emitting lineage for feature view {fv.name}: {e}")

        # Emit events for feature services
        try:
            feature_services = registry.list_feature_services(
                project=project, allow_cache=allow_cache
            )
            for fs in feature_services:
                result = self.emit_feature_service_lineage(
                    fs, all_feature_views, project
                )
                results.append(result)
        except Exception as e:
            logger.error(f"Error emitting feature service lineage: {e}")

        logger.info(
            f"Emitted {sum(results)}/{len(results)} lineage events for registry"
        )
        return results

def extract_list_str(text: str, add_missing_right_bracket: bool = True) -> str:
    text = text.strip()
    start = text.find("[")
    if start == -1:
        log.error("No list found in the text.")
        # return None
        raise ValueError("No list found in the text.")

    # Attempt to find the matching closing bracket
    bracket_count = 0
    end = -1
    for i in range(start, len(text)):
        if text[i] == "[":
            bracket_count += 1
        elif text[i] == "]":
            bracket_count -= 1

        if bracket_count == 0:
            end = i
            break

    if end == -1 and add_missing_right_bracket:
        # If no closing bracket is found, but we are allowed to add one
        text += "]"
        end = len(text) - 1
    elif end == -1:
        log.error("Incomplete list found and add_missing_right_bracket is False.")
        # return None
        raise ValueError(
            "Incomplete list found and add_missing_right_bracket is False."
        )

    return text[start : end + 1]

def from_dict(cls, obj: dict) -> DockerRunLogData:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return DockerRunLogData.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in DockerRunLogData) in the input: " + str(obj))

        _obj = DockerRunLogData.parse_obj({
            "cursor": obj.get("cursor") if obj.get("cursor") is not None else 0,
            "logs": [DockerRunLogEntryData.from_dict(_item) for _item in obj.get("logs")] if obj.get("logs") is not None else None
        })
        return _obj

def is_sklearn_metric(obj, return_type=False):
    def _ret(res, typ):
        if return_type:
            return res, typ
        return res

    from skbase.base import BaseObject

    # if obj is a sktime BaseObject, return False right away
    if not is_in_sklearn(obj) or issubclass(type(obj), BaseObject):
        return _ret(False, None)

    # 1. Must be callable
    if not callable(obj):
        return _ret(False, None)

    # 2. Must be from sklearn.*
    mod = getattr(obj, "__module__", "")
    if not (mod.startswith("sklearn.") or mod == "sklearn"):
        return _ret(False, None)

    # 3. Must have correct signature
    try:
        sig = signature(obj)
    except (TypeError, ValueError):
        return _ret(False, None)

    params = list(sig.parameters.values())
    if len(params) < 2:
        return _ret(False, None)
    if params[0].name != "y_true":
        return _ret(False, None)
    # deterministic metrics have signature (y_true, y_pred, ...)
    # probabilistic metrics have signature (y_true, y_proba, ...)
    # earlier versions of sklearn sometimes use "y_prob" instead of "y_proba"
    if params[1].name not in {"y_pred", "y_proba", "y_prob"}:
        return _ret(False, None)

    if params[1].name == "y_pred":
        return _ret(True, "metric")
    if params[1].name in ["y_proba", "y_prob"]:
        return _ret(True, "metric_proba")

    # unreachable due to "not in" above, but for code checkers
    _ret(False, None)

def calculate_crop_start(self, tokenized_input):
        input_ids = tokenized_input["input_ids"][0].tolist()  # Get the first example's tokens

        marker = "<|im_start|>user\n"

        # Tokenize just the marker to get its token IDs
        marker_tokens = self.tokenizer(marker, add_special_tokens=False)["input_ids"]

        # Find the end position of the marker in the input sequence
        for i in range(len(input_ids) - len(marker_tokens) + 1):
            if input_ids[i : i + len(marker_tokens)] == marker_tokens:
                # Return the position after the marker
                return i + len(marker_tokens)

        # If marker not found, try to find based on special tokens
        if hasattr(self.tokenizer, "special_tokens_map"):
            # Check for user token or any other special token that might indicate user input start
            for token_name, token_value in self.tokenizer.special_tokens_map.items():
                if "user" in token_name.lower():
                    user_token_id = self.tokenizer.convert_tokens_to_ids(token_value)
                    if user_token_id in input_ids:
                        return input_ids.index(user_token_id) + 1

        # Default fallback: return 0 (no cropping)
        return 0

def style(
    text,
    fg=None,
    bg=None,
    bold=None,
    dim=None,
    underline=None,
    blink=None,
    reverse=None,
    reset=True,
):
    bits = []
    if fg:
        try:
            bits.append("\033[{}m".format(_ansi_colors[fg]))
        except KeyError:
            raise TypeError("Unknown color '{}'".format(fg))
    if bg:
        try:
            bits.append("\033[{}m".format(_ansi_colors[bg] + 10))
        except KeyError:
            raise TypeError("Unknown color '{}'".format(bg))
    if bold is not None:
        bits.append("\033[{}m".format(1 if bold else 22))
    if dim is not None:
        bits.append("\033[{}m".format(2 if dim else 22))
    if underline is not None:
        bits.append("\033[{}m".format(4 if underline else 24))
    if blink is not None:
        bits.append("\033[{}m".format(5 if blink else 25))
    if reverse is not None:
        bits.append("\033[{}m".format(7 if reverse else 27))
    bits.append(text)
    if reset:
        bits.append(_ansi_reset_all)
    return "".join(bits)

def batch_insert_ground_truth(
        self, ground_truths: List[groundtruth_schema.GroundTruth]
    ) -> List[types_schema.GroundTruthID]:
        with self.session.begin() as session:
            ground_truth_ids = [gt.ground_truth_id for gt in ground_truths]

            # Fetch existing GroundTruth records that match these ids in one query
            existing_ground_truths = (
                session.query(self.orm.GroundTruth)
                .filter(
                    self.orm.GroundTruth.ground_truth_id.in_(ground_truth_ids)
                )
                .all()
            )

            existing_ground_truth_dict = {
                gt.ground_truth_id: gt for gt in existing_ground_truths
            }

            ground_truths_to_insert = []
            for ground_truth in ground_truths:
                if ground_truth.ground_truth_id in existing_ground_truth_dict:
                    existing_record = existing_ground_truth_dict[
                        ground_truth.ground_truth_id
                    ]
                    # Update the existing record for idempotency
                    existing_record.ground_truth_json = (
                        ground_truth.model_dump_json()
                    )
                else:
                    new_ground_truth = self.orm.GroundTruth.parse(
                        ground_truth, redact_keys=self.redact_keys
                    )
                    ground_truths_to_insert.append(new_ground_truth)

            session.add_all(ground_truths_to_insert)
            return [gt.ground_truth_id for gt in ground_truths]

def zca_mean(
    inp: torch.Tensor, dim: int = 0, unbiased: bool = True, eps: float = 1e-6, return_inverse: bool = False
) -> Tuple[torch.Tensor, torch.Tensor, Optional[torch.Tensor]]:
    if not isinstance(inp, torch.Tensor):
        raise TypeError(f"Input type is not a torch.Tensor. Got {type(inp)}")

    if not isinstance(eps, float):
        raise TypeError(f"eps type is not a float. Got{type(eps)}")

    if not isinstance(unbiased, bool):
        raise TypeError(f"unbiased type is not bool. Got{type(unbiased)}")

    if not isinstance(dim, int):
        raise TypeError(f"Argument 'dim' must be of type int. Got {type(dim)}")

    if not isinstance(return_inverse, bool):
        raise TypeError(f"Argument return_inverse must be of type bool {type(return_inverse)}")

    inp_size = inp.size()

    if dim >= len(inp_size) or dim < -len(inp_size):
        raise IndexError(
            f"Dimension out of range (expected to be in range of [{-len(inp_size)},{len(inp_size) - 1}], but got {dim}"
        )

    if dim < 0:
        dim = len(inp_size) + dim

    feat_dims = torch.cat([torch.arange(0, dim), torch.arange(dim + 1, len(inp_size))])

    new_order: List[int] = torch.cat([torch.tensor([dim]), feat_dims]).tolist()

    inp_permute = inp.permute(new_order)

    N = inp_size[dim]
    feature_sizes = torch.tensor(inp_size[0:dim] + inp_size[dim + 1 : :])
    num_features: int = int(torch.prod(feature_sizes).item())

    mean: torch.Tensor = torch.mean(inp_permute, dim=0, keepdim=True)

    mean = mean.reshape((1, num_features))

    inp_center_flat: torch.Tensor = inp_permute.reshape((N, num_features)) - mean

    cov = inp_center_flat.t().mm(inp_center_flat)

    if unbiased:
        cov = cov / float(N - 1)
    else:
        cov = cov / float(N)

    U, S, _ = _torch_svd_cast(cov)

    S = S.reshape(-1, 1)
    S_inv_root: torch.Tensor = torch.rsqrt(S + eps)
    T: torch.Tensor = (U).mm(S_inv_root * U.t())

    T_inv: Optional[torch.Tensor] = None
    if return_inverse:
        T_inv = (U).mm(torch.sqrt(S + eps) * U.t())

    return T, mean, T_inv

def add_content_to_text(
    text: str,
    content: str,
    add_after: Optional[Union[str, Pattern]] = None,
    add_before: Optional[Union[str, Pattern]] = None,
    exact_match: bool = False,
) -> str:
    if add_after is None and add_before is None:
        raise ValueError("You need to pass either `add_after` or `add_before`")
    if add_after is not None and add_before is not None:
        raise ValueError("You can't pass both `add_after` or `add_before`")
    pattern = add_after if add_before is None else add_before

    def this_is_the_line(line):
        if isinstance(pattern, Pattern):
            return pattern.search(line) is not None
        elif exact_match:
            return pattern == line
        else:
            return pattern in line

    new_lines = []
    for line in text.split("\n"):
        if this_is_the_line(line):
            if add_before is not None:
                new_lines.append(content)
            new_lines.append(line)
            if add_after is not None:
                new_lines.append(content)
        else:
            new_lines.append(line)

    return "\n".join(new_lines)

def floyd_warshall_all_pairs_distance(graph, heuristic=None, directed=False):
    from collections import defaultdict
    g = graph.keys()
    d = defaultdict(lambda: defaultdict(lambda: 1e30)) # float('inf')
    p = defaultdict(dict) # Predecessors.
    for e in graph.edges:
        u = e.node1.id
        v = e.node2.id
        w = 1.0 - 0.5 * e.weight
        w = heuristic and heuristic(u, v) + w or w
        d[u][v] = min(w, d[u][v])
        d[u][u] = 0
        p[u][v] = u
        if not directed:
            d[v][u] = min(w, d[v][u])
            p[v][u] = v
    for w in g:
        dw = d[w]
        for u in g:
            du, duw = d[u], d[u][w]
            for v in g:
                # Performance optimization, assumes d[w][v] > 0.
                #if du[v] > duw + dw[v]:
                if du[v] > duw and du[v] > duw + dw[v]:
                    d[u][v] = duw + dw[v]
                    p[u][v] = p[w][v]

    class pdict(dict):
        def __init__(self, predecessors, *args, **kwargs):
            dict.__init__(self, *args, **kwargs)
            self.predecessors = predecessors
    return pdict(p, ((u, dict((v, w) for v, w in d[u].items() if w < 1e30)) for u in d))

def get_cuda_version(cuda_path=None):
    if cuda_path is None:
        cuda_path = find_cuda_path()

    version_file_path = os.path.join(cuda_path, "version.txt")
    if not os.path.exists(version_file_path):
        # Debian/Ubuntu repackaged CUDA path
        version_file_path = os.path.join(cuda_path, "lib", "cuda", "version.txt")
    try:
        with open(version_file_path) as f:
            version_str = f.read().strip().split()[-1]
            return tuple(int(field) for field in version_str.split("."))
    except FileNotFoundError:
        pass

    cmd = [os.path.join(cuda_path, "bin", "nvcc"), "--version"]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    (out, _) = proc.communicate()
    out = py_str(out)
    if proc.returncode == 0:
        release_line = next(line for line in out.split("\n") if "release" in line)
        release_fields = [s.strip() for s in release_line.split(",")]
        version_str = next(f[1:] for f in release_fields if f.startswith("V"))
        return tuple(int(field) for field in version_str.split("."))
    raise RuntimeError("Cannot read CUDA version file")

def create_recipe(
        self, recipe_type: RecipeType, **kwargs: Any
    ) -> Optional[ExportRecipe]:

        if recipe_type not in self.get_supported_recipes():
            return None

        # Validate kwargs
        self._validate_recipe_kwargs(recipe_type, **kwargs)

        if recipe_type == XNNPackRecipeType.FP32:
            return self._build_fp32_recipe(recipe_type)

        elif recipe_type == XNNPackRecipeType.PT2E_INT8_DYNAMIC_PER_CHANNEL:
            return self._build_quantized_recipe(
                recipe_type, is_per_channel=True, is_dynamic=True
            )

        elif recipe_type == XNNPackRecipeType.PT2E_INT8_STATIC_PER_CHANNEL:
            return self._build_quantized_recipe(
                recipe_type, is_per_channel=True, is_dynamic=False
            )

        elif recipe_type == XNNPackRecipeType.PT2E_INT8_STATIC_PER_TENSOR:
            return self._build_quantized_recipe(
                recipe_type, is_per_channel=False, is_dynamic=False
            )

        elif (
            recipe_type
            == XNNPackRecipeType.TORCHAO_INT8_DYNAMIC_ACT_INT4_WEIGHT_PER_CHANNEL
        ):
            return self._build_torchao_quantized_recipe(
                recipe_type=recipe_type,
                is_per_channel=True,
                weight_dtype=torch.int4,
            )

        elif (
            recipe_type
            == XNNPackRecipeType.TORCHAO_INT8_DYNAMIC_ACT_INT4_WEIGHT_PER_TENSOR
        ):
            group_size = kwargs.get("group_size", 32)
            return self._build_torchao_quantized_recipe(
                recipe_type=recipe_type,
                is_per_channel=False,
                weight_dtype=torch.int4,
                group_size=group_size,
            )
        return None

def free(self, blocks: Union[Iterable[int], int]) -> None:
        if isinstance(blocks, int):
            blocks = [blocks]

        for block in blocks:
            # Parse all blocks for validity before mutating the list.
            if block < 0 or block >= self._num_blocks:
                raise ValueError(f'Invalid block {block} provided to free')

            if self._blocks[block] != -1:
                raise ValueError(f'Block {block} is already free')

        for block in blocks:
            self._blocks[block] = self._head
            self._head = block
            self._free_blocks += 1

def markdown_to_html(md):
    if mistune_recent:

        class HighlightRenderer(mistune.HTMLRenderer):
            def block_code(self, code, lang=None):
                if lang:
                    lexer = get_lexer_by_name(lang, stripall=True)
                    formatter = html.HtmlFormatter()
                    return highlight(code, lexer, formatter)
                return "<pre><code>" + mistune.escape(code) + "</code></pre>"

        markdown = mistune.create_markdown(renderer=HighlightRenderer(escape=False))
        return markdown(md)
    else:

        class HighlightRenderer(mistune.Renderer):
            """mistune renderer with syntax highlighting

            Notes
            -----
            Source: https://github.com/lepture/mistune#renderer
            """

            def block_code(self, code, lang):
                if not lang:
                    return "\n<pre><code>%s</code></pre>\n" % mistune.escape(code)
                lexer = get_lexer_by_name(lang, stripall=True)
                formatter = html.HtmlFormatter()
                return highlight(code, lexer, formatter)

        renderer = HighlightRenderer()
        return mistune.markdown(md, escape=False, renderer=renderer)

def read_prefix_file(destination_file):
    destination = None
    known_prefixes = set()
    prefixes = []

    prefix_map = {}
    with open(destination_file, encoding="utf-8") as fin:
        for line in fin:
            line = line.strip()
            if line.startswith("#"):
                continue
            if not line:
                continue
            if line.endswith(":"):
                if destination is not None:
                    prefix_map[destination] = prefixes
                prefixes = []
                destination = line[:-1].strip().lower().replace(" ", "_")
            else:
                if not destination:
                    raise RuntimeError("Found a prefix before the first label was assigned when reading %s" % destination_file)
                prefixes.append(line)
                if line in known_prefixes:
                    raise RuntimeError("Found the same prefix twice! %s" % line)
                known_prefixes.add(line)

        if destination and prefixes:
            prefix_map[destination] = prefixes

    return prefix_map

async def validate_field(field_name: str, value: str = "", _user: User = Depends(get_current_user)) -> str:
    error_html = ""

    # Basic validation rules
    if field_name == "id":
        if not value or not value.strip():
            error_html = "Dataset ID is required"
        elif not value.replace("-", "").replace("_", "").isalnum():
            error_html = "Dataset ID must contain only letters, numbers, hyphens, and underscores"
        elif len(value) > 50:
            error_html = "Dataset ID must be 50 characters or less"

    elif field_name == "instance_data_dir":
        if not value or not value.strip():
            error_html = "Instance data directory is required"
        elif not value.startswith("/"):
            error_html = "Path must be absolute (start with /)"

    elif field_name == "resolution":
        try:
            res = int(value) if value else 0
            if res < 256:
                error_html = "Resolution must be at least 256"
            elif res > 4096:
                error_html = "Resolution must not exceed 4096"
            elif res % 64 != 0:
                error_html = "Resolution must be divisible by 64"
        except ValueError:
            error_html = "Resolution must be a valid number"

    elif field_name == "probability":
        try:
            prob = float(value) if value else 0
            if prob < 0 or prob > 1:
                error_html = "Probability must be between 0 and 1"
        except ValueError:
            error_html = "Probability must be a valid number"

    elif field_name == "repeats":
        try:
            repeats = int(value) if value else 0
            if repeats < 0:
                error_html = "Repeats must be 0 or greater"
        except ValueError:
            error_html = "Repeats must be a valid number"

    return error_html

def crawl_legend(self, ax: Any, legend: Any) -> None:
        legendElements = list(utils.iter_all_children(legend._legend_box, skipContainers=True))
        legendElements.append(legend.legendPatch)
        for child in legendElements:
            # force a large zorder so it appears on top
            child.set_zorder(1e6 + child.get_zorder())

            # reorder border box to make sure marks are visible
            if isinstance(child, matplotlib.patches.FancyBboxPatch):
                child.set_zorder(child.get_zorder() - 1)

            try:
                # What kind of object...
                if isinstance(child, matplotlib.patches.Patch):
                    self.draw_patch(ax, child, force_trans=ax.transAxes)
                elif isinstance(child, matplotlib.text.Text):
                    if child.get_text() != "None":
                        self.draw_text(ax, child, force_trans=ax.transAxes)
                elif isinstance(child, matplotlib.lines.Line2D):
                    self.draw_line(ax, child, force_trans=ax.transAxes)
                elif isinstance(child, matplotlib.collections.Collection):
                    self.draw_collection(ax, child, force_pathtrans=ax.transAxes)
                else:
                    warnings.warn("Legend element %s not impemented" % child)
            except NotImplementedError:
                warnings.warn("Legend element %s not impemented" % child)

def get_rnn_init_state(
    combiner_outputs: dict[str, torch.Tensor], sequence_reducer: SequenceReducer, num_layers: int
) -> torch.Tensor:
    if ENCODER_OUTPUT_STATE not in combiner_outputs:
        # Use the combiner's hidden state.
        encoder_output_state = combiner_outputs[HIDDEN]
    else:
        # Use the encoder's output state.
        encoder_output_state = combiner_outputs[ENCODER_OUTPUT_STATE]
        if isinstance(encoder_output_state, tuple):
            if len(encoder_output_state) == 2:
                # LSTM encoder. Use the hidden state and ignore the cell state.
                encoder_output_state = encoder_output_state[0]
            elif len(encoder_output_state) == 4:
                # Bi-directional LSTM encoder. Use the average of hidden states and ignore cell state.
                encoder_output_state = torch.mean([encoder_output_state[0], encoder_output_state[2]])
            else:
                raise ValueError(
                    f"Invalid sequence decoder inputs with keys: {combiner_outputs.keys()} with extracted encoder "
                    + f"state: {encoder_output_state.size()} that was invalid. Please double check the compatibility "
                    + "of your encoder and decoder."
                )

    if len(encoder_output_state.size()) > 3:
        raise ValueError("Init state for RNN decoders only works for 1d or 2d tensors (encoder_output).")

    if len(encoder_output_state.size()) == 3:
        # Reduce to [batch_size, hidden_size].
        encoder_output_state = sequence_reducer(encoder_output_state)

    return repeat_2D_tensor(encoder_output_state, num_layers)

def register_tool(self, tool: AgentTool) -> None:
        logger.debug(
            "tool_name=<%s>, tool_type=<%s>, is_dynamic=<%s> | registering tool",
            tool.tool_name,
            tool.tool_type,
            tool.is_dynamic,
        )

        # Check duplicate tool name, throw on duplicate tool names except if hot_reloading is enabled
        if tool.tool_name in self.registry and not tool.supports_hot_reload:
            raise ValueError(
                f"Tool name '{tool.tool_name}' already exists. Cannot register tools with exact same name."
            )

        # Check for normalized name conflicts (- vs _)
        if self.registry.get(tool.tool_name) is None:
            normalized_name = tool.tool_name.replace("-", "_")

            matching_tools = [
                tool_name
                for (tool_name, tool) in self.registry.items()
                if tool_name.replace("-", "_") == normalized_name
            ]

            if matching_tools:
                raise ValueError(
                    f"Tool name '{tool.tool_name}' already exists as '{matching_tools[0]}'."
                    " Cannot add a duplicate tool which differs by a '-' or '_'"
                )

        # Register in main registry
        self.registry[tool.tool_name] = tool

        # Register in dynamic tools if applicable
        if tool.is_dynamic:
            self.dynamic_tools[tool.tool_name] = tool

            if not tool.supports_hot_reload:
                logger.debug("tool_name=<%s>, tool_type=<%s> | skipping hot reloading", tool.tool_name, tool.tool_type)
                return

            logger.debug(
                "tool_name=<%s>, tool_registry=<%s>, dynamic_tools=<%s> | tool registered",
                tool.tool_name,
                list(self.registry.keys()),
                list(self.dynamic_tools.keys()),
            )

def extern(
    name: str,
    args: Sequence[Tensor | _tir.PrimExpr | int | float | str],
    out: OutType,
) -> OutType:
    from tvm import relax as rx  # pylint: disable=import-outside-toplevel

    def _convert(arg, name: str):
        if isinstance(arg, Tensor):
            return arg._expr  # pylint: disable=protected-access
        if isinstance(arg, int):
            return rx.PrimValue(_tir.IntImm("int64", arg))
        if isinstance(arg, float):
            return rx.PrimValue(_tir.FloatImm("float64", arg))
        if isinstance(arg, str):
            return rx.StringImm(arg)
        if isinstance(arg, _tir.PrimExpr):
            return rx.PrimValue(arg)
        if isinstance(arg, tuple | list):
            return rx.Tuple([_convert(e, f"{name}_{i}") for i, e in enumerate(arg)])
        raise TypeError(f"Unsupported input type: {type(arg)}")

    rx_inputs = _convert(args, "input")
    rx_outputs_sinfo = _convert(out, "dummy").struct_info
    return wrap_nested(
        _op.call_dps_packed(
            name,
            args=rx_inputs,
            out_sinfo=rx_outputs_sinfo,
        ),
        name,
    )  # type: ignore

def get_clean_fonts() -> list[str]:
    f_manager = font_manager.FontManager()
    fonts: dict[str, dict[str, bool]] = {}
    for fnt in f_manager.ttflist:
        if str(fnt.weight) in ("400", "normal", "regular"):
            fonts.setdefault(fnt.name, {})["regular"] = True
        if str(fnt.weight) in ("700", "bold"):
            fonts.setdefault(fnt.name, {})["bold"] = True
    valid_fonts = {key for key, val in fonts.items() if len(val) == 2}
    retval = sorted(list(valid_fonts.intersection(tk_font.families())))
    if not retval:
        # Return the font list with any @prefixed or non-Unicode characters stripped and default
        # prefixed
        logger.debug("No bold/regular fonts found. Running simple filter")
        retval = sorted([fnt for fnt in tk_font.families()
                         if not fnt.startswith("@") and not any(ord(c) > 127 for c in fnt)])
    return ["default"] + retval

def repair_multipolygon(shapely_multipolygon: MultiPolygon) -> MultiPolygon:
    if not shapely_multipolygon.is_valid:
        fixed_geometry = shapely_multipolygon.buffer(0)

        if fixed_geometry.is_valid:
            if isinstance(fixed_geometry, MultiPolygon):
                return fixed_geometry
            elif isinstance(fixed_geometry, Polygon):
                return MultiPolygon([fixed_geometry])
            elif isinstance(fixed_geometry, GeometryCollection):
                polygons = [geom for geom in fixed_geometry.geoms if isinstance(geom, Polygon)]
                return MultiPolygon(polygons) if polygons else shapely_multipolygon

    return shapely_multipolygon

def from_yaml(cls, yaml_dict):
        if isinstance(yaml_dict, IOBase):
            from snips_nlu.dataset.yaml_wrapper import yaml

            yaml_dict = yaml.safe_load(yaml_dict)

        object_type = yaml_dict.get("type")
        if object_type and object_type != "entity":
            raise EntityFormatError("Wrong type: '%s'" % object_type)
        entity_name = yaml_dict.get("name")
        if not entity_name:
            raise EntityFormatError("Missing 'name' attribute")
        auto_extensible = yaml_dict.get(AUTOMATICALLY_EXTENSIBLE, True)
        use_synonyms = yaml_dict.get(USE_SYNONYMS, True)
        matching_strictness = yaml_dict.get("matching_strictness", 1.0)
        utterances = []
        for entity_value in yaml_dict.get("values", []):
            if isinstance(entity_value, list):
                utterance = EntityUtterance(entity_value[0], entity_value[1:])
            elif isinstance(entity_value, str):
                utterance = EntityUtterance(entity_value)
            else:
                raise EntityFormatError(
                    "YAML entity values must be either strings or lists, but "
                    "found: %s" % type(entity_value))
            utterances.append(utterance)

        return cls(name=entity_name,
                   utterances=utterances,
                   automatically_extensible=auto_extensible,
                   use_synonyms=use_synonyms,
                   matching_strictness=matching_strictness)

def phonemize_gruut(self, text: str, separator: str = "|", tie=False) -> str:  # pylint: disable=unused-argument
        ph_list = []
        for sentence in gruut.sentences(text, lang=self.language, espeak=self.use_espeak_phonemes):
            for word in sentence:
                if word.is_break:
                    # Use actual character for break phoneme (e.g., comma)
                    if ph_list:
                        # Join with previous word
                        ph_list[-1].append(word.text)
                    else:
                        # First word is punctuation
                        ph_list.append([word.text])
                elif word.phonemes:
                    # Add phonemes for word
                    word_phonemes = []

                    for word_phoneme in word.phonemes:
                        if not self.keep_stress:
                            # Remove primary/secondary stress
                            word_phoneme = IPA.without_stress(word_phoneme)

                        word_phoneme = word_phoneme.translate(GRUUT_TRANS_TABLE)

                        if word_phoneme:
                            # Flatten phonemes
                            word_phonemes.extend(word_phoneme)

                    if word_phonemes:
                        ph_list.append(word_phonemes)

        ph_words = [separator.join(word_phonemes) for word_phonemes in ph_list]
        ph = f"{separator} ".join(ph_words)
        return ph

def set(self, value: T) -> None:
        if not self._name:
            raise ValueError("The name of this object should have been set before any value is"
                             "added")

        if self.datatype is list:
            if not isinstance(value, (str, list)):
                raise ValueError(f"[{self._name}] List values should be set as a Str or List. Got "
                                 f"{type(value)} ({value})")
            value = cast(T, self._parse_list(value))

        if not isinstance(value, self.datatype):
            raise ValueError(
                f"[{self._name}] Expected {self.datatype} got {type(value)} ({value})")

        if isinstance(self.choices, list) and self.choices:
            assert isinstance(value, (list, str))
            value = cast(T, self._validate_selection(value))

        if self.choices == "colorchooser":
            assert isinstance(value, str)
            if not value.startswith("#") or len(value) != 7:
                raise ValueError(f"Hex color codes should start with a '#' and be 6 "
                                 f"characters long. Got: '{value}'")

        self._value = value

def broadcast_parameters(params, root_rank=0, prefix=None):
    if size() == 1: return

    tensors = []
    names = []
    assert prefix is None or isinstance(prefix, str)
    prefix = prefix if prefix else ""
    try:
        from mxnet.gluon.parameter import ParameterDict
        valid_types = (dict, ParameterDict)
    except ImportError:
        valid_types = (dict,)
    if isinstance(params, valid_types):
        for name, p in sorted(params.items()):
            try:
                if isinstance(p, mx.gluon.parameter.Parameter):
                    tensors.append(p.data())
                else:
                    tensors.append(p)
                names.append(prefix + str(name))
            except mx.gluon.parameter.DeferredInitializationError:
                # Inject wrapper method with post-initialization broadcast to
                # handle parameters with deferred initialization
                # we use the key of params instead of param.name, since
                # param.name is no longer unique in MXNet 2.0
                new_init = _append_broadcast_init(p, root_rank, prefix + str(name))
                p._init_impl = types.MethodType(new_init, p)
    else:
        raise ValueError('invalid params of type: %s' % type(params))

    # Run broadcasts.
    for tensor, name in zip(tensors, names):
        broadcast_(tensor, root_rank, name=name)

def config_network_precision(network, config):
    # build two auxiliary indices
    out2layer = {}
    in2layer = {}
    for layer_idx in range(network.num_layers):
        layer = network.get_layer(layer_idx)
        for i in range(layer.num_outputs):
            output = layer.get_output(i)
            out2layer[output.name] = layer
        for i in range(layer.num_inputs):
            _input = layer.get_input(i)
            if _input.name in in2layer:
                in2layer[_input.name].append(layer)
            else:
                in2layer[_input.name] = [layer]

    net_input = network.get_input(0)
    assert net_input.name in in2layer

    # traverse the network/graph and specify precision and dynamic range
    for layer_idx in range(network.num_layers):
        # assume the traverse order is topological
        layer = network.get_layer(layer_idx)
        if layer.name in config:
            if layer.name[0:4] == 'Gemm':
                _handle_gemm(layer, config[layer.name], out2layer, in2layer)
            else:
                apply_precision_to_layer(layer, config[layer.name])
        else:
            precision, dynamic_range = propagate_from_low_bit_predecessor(layer, out2layer)
            if precision:
                layer.precision = precision
                layer.set_output_type(0, precision)
            if dynamic_range:
                out_tensor = layer.get_output(0)
                out_tensor.dynamic_range = dynamic_range

    print_layer_precisions(network)

def get_tightbbox(self, renderer=None, *, for_layout_only=False):
        if not self.get_visible() or for_layout_only and not self.get_in_layout():
            return
        if renderer is None:
            renderer = self.get_figure(root=True)._get_renderer()
        ticks_to_draw = self._update_ticks()

        self._update_label_position(renderer)

        # go back to just this axis's tick labels
        tlb1, tlb2 = self._get_ticklabel_bboxes(ticks_to_draw, renderer)

        self._update_offset_text_position(tlb1, tlb2)
        self.offsetText.set_text(self.major.formatter.get_offset())

        bboxes = [
            *(a.get_window_extent(renderer)
              for a in [self.offsetText]
              if a.get_visible()),
            *tlb1, *tlb2,
        ]
        # take care of label
        if self.label.get_visible():
            bb = self.label.get_window_extent(renderer)
            # for constrained/tight_layout, we want to ignore the label's
            # width/height because the adjustments they make can't be improved.
            # this code collapses the relevant direction
            if for_layout_only:
                if self.axis_name == "x" and bb.width > 0:
                    bb.x0 = (bb.x0 + bb.x1) / 2 - 0.5
                    bb.x1 = bb.x0 + 1.0
                if self.axis_name == "y" and bb.height > 0:
                    bb.y0 = (bb.y0 + bb.y1) / 2 - 0.5
                    bb.y1 = bb.y0 + 1.0
            bboxes.append(bb)
        bboxes = [b for b in bboxes if b._is_finite()]
        if bboxes:
            return mtransforms.Bbox.union(bboxes)
        else:
            return None

def cdist_normalized_cc(dataset1, dataset2, norms1, norms2, self_similarity):
    n_ts1, sz, d = dataset1.shape
    n_ts2 = dataset2.shape[0]
    assert d == dataset2.shape[2]
    dists = np.zeros((n_ts1, n_ts2))

    if (norms1 < 0.0).any():
        for i_ts1 in prange(n_ts1):
            norms1[i_ts1] = np.linalg.norm(dataset1[i_ts1, ...])
    if (norms2 < 0.0).any():
        for i_ts2 in prange(n_ts2):
            norms2[i_ts2] = np.linalg.norm(dataset2[i_ts2, ...])
    if self_similarity:
        for i in prange(1, n_ts1):
            for j in range(i):
                dists[i, j] = normalized_cc(
                    dataset1[i], dataset2[j], norm1=norms1[i], norm2=norms2[j]
                ).max()
        dists += dists.T
    else:
        for i in prange(n_ts1):
            for j in range(n_ts2):
                dists[i, j] = normalized_cc(
                    dataset1[i], dataset2[j], norm1=norms1[i], norm2=norms2[j]
                ).max()
    return dists

def update_provider(self, name: str, updates: Dict[str, Any]) -> bool:
        if name not in self._configs:
            return False

        config = self._configs[name]

        # Update config fields
        if "enabled" in updates:
            config.enabled = updates["enabled"]
        if "auto_create_users" in updates:
            config.auto_create_users = updates["auto_create_users"]
        if "level_mapping" in updates:
            config.level_mapping = updates["level_mapping"]
        if "default_levels" in updates:
            config.default_levels = updates["default_levels"]
        if "config" in updates:
            config.config.update(updates["config"])

        # Recreate provider with new config
        self._register_provider(config)

        if self._config_file:
            self._save_config()

        return True

def get_shapely_multipolygon(coco_segmentation: list[list]) -> MultiPolygon:
    def filter_polygons(geometry: GeometryCollection | Polygon | MultiPolygon) -> MultiPolygon:
        """Filters out and returns only Polygon or MultiPolygon components of a geometry.

        If geometry is a Polygon, it converts it into a MultiPolygon. If it's a GeometryCollection, it filters to create
        a MultiPolygon from any Polygons in the collection. Returns an empty MultiPolygon if no Polygon or MultiPolygon
        components are found.

        Args:
            geometry: A shapely geometry object (Polygon, MultiPolygon, GeometryCollection, etc.)

        Returns: MultiPolygon
        """
        if isinstance(geometry, Polygon):
            return MultiPolygon([geometry])
        elif isinstance(geometry, MultiPolygon):
            return geometry
        elif isinstance(geometry, GeometryCollection):
            polygons = [
                geom.geoms if isinstance(geom, MultiPolygon) else geom
                for geom in geometry.geoms
                if isinstance(geom, (Polygon, MultiPolygon))
            ]
            return MultiPolygon(polygons) if polygons else MultiPolygon()
        return MultiPolygon()

    polygon_list = []
    for coco_polygon in coco_segmentation:
        point_list = list(zip(coco_polygon[0::2], coco_polygon[1::2]))
        shapely_polygon = Polygon(point_list)
        polygon_list.append(shapely_polygon)
    shapely_multipolygon = MultiPolygon(polygon_list)

    if not shapely_multipolygon.is_valid:
        shapely_multipolygon = filter_polygons(make_valid(shapely_multipolygon))

    return shapely_multipolygon

def remove_long_sequences(self):
        max_len = self.params.max_model_input_size
        indices = self.lengths > max_len
        logger.info(f"Splitting {sum(indices)} too long sequences.")

        def divide_chunks(l, n):
            return [l[i : i + n] for i in range(0, len(l), n)]

        new_tok_ids = []
        new_lengths = []
        if self.params.mlm:
            cls_id, sep_id = self.params.special_tok_ids["cls_token"], self.params.special_tok_ids["sep_token"]
        else:
            cls_id, sep_id = self.params.special_tok_ids["bos_token"], self.params.special_tok_ids["eos_token"]

        for seq_, len_ in zip(self.token_ids, self.lengths):
            assert (seq_[0] == cls_id) and (seq_[-1] == sep_id), seq_
            if len_ <= max_len:
                new_tok_ids.append(seq_)
                new_lengths.append(len_)
            else:
                sub_seqs = []
                for sub_s in divide_chunks(seq_, max_len - 2):
                    if sub_s[0] != cls_id:
                        sub_s = np.insert(sub_s, 0, cls_id)
                    if sub_s[-1] != sep_id:
                        sub_s = np.insert(sub_s, len(sub_s), sep_id)
                    assert len(sub_s) <= max_len
                    assert (sub_s[0] == cls_id) and (sub_s[-1] == sep_id), sub_s
                    sub_seqs.append(sub_s)

                new_tok_ids.extend(sub_seqs)
                new_lengths.extend([len(l) for l in sub_seqs])

        self.token_ids = np.array(new_tok_ids)
        self.lengths = np.array(new_lengths)

def from_dict(cls, obj: dict) -> ConfigurationSetRequest:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return ConfigurationSetRequest.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in ConfigurationSetRequest) in the input: " + str(obj))

        _obj = ConfigurationSetRequest.parse_obj({
            "name": obj.get("name"),
            "configs": [ConfigurationEntry.from_dict(_item) for _item in obj.get("configs")] if obj.get("configs") is not None else None
        })
        return _obj

def stack_reshape(
    frame: DataFrame, level: list[int], set_levels: set[int], stack_cols: Index
) -> Series | DataFrame:
    # non-MultIndex takes a fast path.
    assert isinstance(frame.columns, MultiIndex)
    # If we need to drop `level` from columns, it needs to be in descending order
    drop_levnums = sorted(level, reverse=True)

    # Grab data for each unique index to be stacked
    buf = []
    for idx in stack_cols.unique():
        if len(frame.columns) == 1:
            data = frame.copy(deep=False)
        else:
            # Take the data from frame corresponding to this idx value
            if len(level) == 1:
                idx = (idx,)
            gen = iter(idx)
            column_indexer = tuple(
                next(gen) if k in set_levels else slice(None)
                for k in range(frame.columns.nlevels)
            )
            data = frame.loc[:, column_indexer]

        if len(level) < frame.columns.nlevels:
            data.columns = data.columns._drop_level_numbers(drop_levnums)
        elif stack_cols.nlevels == 1:
            if data.ndim == 1:
                data.name = 0
            else:
                data.columns = default_index(len(data.columns))
        buf.append(data)

    if len(buf) > 0 and not frame.empty:
        result = concat(buf, ignore_index=True)
    else:
        # input is empty
        if len(level) < frame.columns.nlevels:
            # concat column order may be different from dropping the levels
            new_columns = frame.columns._drop_level_numbers(drop_levnums).unique()
        else:
            new_columns = [0]  # type: ignore[assignment]
        result = DataFrame(columns=new_columns, dtype=frame._values.dtype)

    if len(level) < frame.columns.nlevels:
        # concat column order may be different from dropping the levels
        desired_columns = frame.columns._drop_level_numbers(drop_levnums).unique()
        if not result.columns.equals(desired_columns):
            result = result[desired_columns]

    return result

def get_ray_init_settings(config: Any | None = None) -> dict[str, Any]:
