def get_spine_visible(ax: Any, spine_key: str) -> bool:
    spine = ax.spines[spine_key]
    ax_frame_on = ax.get_frame_on()
    if check_maplotlib_max_version("3", "1"):
        spine_frame_like = spine.is_frame_like() if hasattr(spine, "is_frame_like") else True
    else:
        spine_frame_like = True
    if not spine.get_visible():
        return False
    elif not spine._edgecolor[-1]:  # user's may have set edgecolor alpha==0
        return False
    elif not ax_frame_on and spine_frame_like:
        return False
    elif ax_frame_on and spine_frame_like:
        return True
    elif not ax_frame_on and not spine_frame_like:
        return True  # we've already checked for that it's visible.
    else:
        return False  # oh man, and i thought we exhausted the options...

def get_shared_times_bounds(
    *series_or_times: Sequence[TimeSeries | pd.Index | None],
) -> tuple[pd.Index, pd.Index] | None:
    start_times, end_times = [], []
    for val in series_or_times:
        if (val is not None) and (len(val) > 0):
            start_times.append(
                val.start_time() if isinstance(val, TimeSeries) else val[0]
            )
            end_times.append(val.end_time() if isinstance(val, TimeSeries) else val[-1])
    if not start_times:
        bounds = None
    else:
        times_types = [type(time) for time in start_times]
        if not len(set(times_types)) == 1:
            raise_log(
                ValueError(
                    "Specified series and/or times must all have the same type of "
                    "`time_index` (i.e. all `pd.RangeIndex` or all `pd.DatetimeIndex`)."
                ),
                logger=logger,
            )
        # If `start_times` empty, no series were specified -> `bounds = (1, -1)` will
        # be 'converted' to `None` in next line:
        bounds = (max(start_times), min(end_times)) if start_times else (1, -1)
        # Specified timeseries share no overlapping periods.
        if bounds[1] < bounds[0]:
            bounds = None
    return bounds

def ScaledInitializer(out_dim, in_dim, scale, mode, distribution):
  if scale <= 0.:
    raise ValueError('scale must be positive float, {} given'.format(scale))
  if mode not in {'fan_in', 'fan_out', 'fan_avg'}:
    raise ValueError(
        'Invalid mode argument:, {}, must be either fan_in, fan_out or fan_avg'
        .format(mode))

  def Init(shape, rng, nonreceptive_dims=None):
    """Returns random values for initializing weights of the given `shape`."""
    shape = _PureShape(shape)
    fan_in, fan_out = _GetFans(shape, out_dim, in_dim, nonreceptive_dims)
    gain = scale
    if mode == 'fan_in':
      gain /= fan_in
    elif mode == 'fan_out':
      gain /= fan_out
    elif mode == 'fan_avg':
      gain /= (fan_in + fan_out) / 2
    if distribution == 'truncated_normal':
      # constant from scipy.stats.truncnorm.std(a=-2, b=2, loc=0., scale=1.)
      stddev = jnp.sqrt(gain) / .87962566103423978
      new_weights = random.truncated_normal(rng, -2, 2, shape) * stddev
      return new_weights.astype('float32')
    elif distribution == 'normal':
      new_weights = random.normal(rng, shape) * jnp.sqrt(gain)
      return new_weights.astype('float32')
    elif distribution == 'uniform':
      lim = jnp.sqrt(3. * gain)
      return random.uniform(rng, shape, jnp.float32, -lim, lim)
    else:
      raise ValueError('invalid distribution for ScaleInitializer')

  return Init

def fromstring(s):
        # Split off the comment (but don't split on '\#')
        m = re.match(r"(?P<rule>(\\.|[^#])*)(?P<comment>#.*)?", s)
        rule = m.group("rule").strip()
        comment = (m.group("comment") or "")[1:].strip()

        # Pattern bodies: chunk, strip, split, merge
        try:
            if not rule:
                raise ValueError("Empty chunk pattern")
            if rule[0] == "{" and rule[-1] == "}":
                return ChunkRule(rule[1:-1], comment)
            elif rule[0] == "}" and rule[-1] == "{":
                return StripRule(rule[1:-1], comment)
            elif "}{" in rule:
                left, right = rule.split("}{")
                return SplitRule(left, right, comment)
            elif "{}" in rule:
                left, right = rule.split("{}")
                return MergeRule(left, right, comment)
            elif re.match("[^{}]*{[^{}]*}[^{}]*", rule):
                left, chunk, right = re.split("[{}]", rule)
                return ChunkRuleWithContext(left, chunk, right, comment)
            else:
                raise ValueError("Illegal chunk pattern: %s" % rule)
        except (ValueError, re.error) as e:
            raise ValueError("Illegal chunk pattern: %s" % rule) from e

def create_rag_context(
    query: str,
    user_id: str,
    limit: int = 5,
) -> str:
    results = search_mem0_memory(
        query=query, user_id=user_id, limit=limit
    )

    if not results:
        return "No relevant information found in memory."

    context_parts = []
    for i, result in enumerate(results, 1):
        # Handle different result formats
        if isinstance(result, str):
            content = result
            filename = f"Memory {i}"
        elif isinstance(result, dict):
            # Extract content from various possible keys
            content = (
                result.get("memory")
                or result.get("content")
                or result.get("text")
                or result.get("message")
                or str(result)
            )
            # Extract metadata
            metadata = result.get("metadata", {})
            if isinstance(metadata, dict):
                filename = metadata.get("filename", f"Memory {i}")
            else:
                filename = f"Memory {i}"
        else:
            content = str(result)
            filename = f"Memory {i}"

        context_parts.append(
            f"[Document {i}: {filename}]\n{content}\n"
        )

    return "\n".join(context_parts)

def is_node_supported(
        self, submodules: typing.Mapping[str, torch.nn.Module], node: fx.Node
    ) -> bool:
        output_quantized = False
        input_quantized = False
        if node.target not in self.targeted_ops:
            return True

        elif node.target in (exir_ops.edge.aten.max_pool2d_with_indices.default,):
            users = node.users
            output_quantized = all(
                user.target == operator.getitem
                and all(user_user.target in Q_OPS for user_user in user.users)
                for user in users
            )
        elif FuseQuantizedActivationPass._is_fuseable_input(node):
            users = node.users
            output_quantized = all(
                FuseQuantizedActivationPass._is_fuseable_quantized_activation(user)
                for user in users
            )
        elif FuseQuantizedActivationPass._is_fuseable_quantized_activation(node):
            input_node = node.all_input_nodes[0]
            input_quantized = FuseQuantizedActivationPass._is_fuseable_input(input_node)

        input_quantized = input_quantized or all(
            (input_node.target in DQ_OPS)
            or _is_integer_dtype(get_first_fake_tensor(input_node).dtype)
            for input_node in node.all_input_nodes
        )

        if not input_quantized:
            self.reporter.report_reject(node, "One or more inputs were not quantized.")
            return False

        all_q_users = all((output_node.target in Q_OPS) for output_node in node.users)
        output_dtype = get_first_fake_tensor(node).dtype
        output_quantized = (
            output_quantized or all_q_users or _is_integer_dtype(output_dtype)
        )

        if not output_quantized:
            self.reporter.report_reject(node, "One or more outputs were not quantized.")
            return False
        return True

def check_concat_combiner_requirements(config: "ModelConfig") -> None:  # noqa: F821
    if config.model_type != MODEL_ECD:
        return
    if config.combiner.type != "concat":
        return

    has_unreduced_sequence_feature = False
    has_non_sequence_feature = False
    for input_feature in config.input_features:
        if (
            input_feature.type in {SEQUENCE, TEXT, TIMESERIES}
            and hasattr(input_feature.encoder, "reduce_output")
            and input_feature.encoder.reduce_output is None
        ):
            has_unreduced_sequence_feature = True
        else:
            has_non_sequence_feature = True

    if has_unreduced_sequence_feature and has_non_sequence_feature:
        raise ConfigValidationError(
            "The concat combiner cannot receive a mix of unreduced sequence features (3D) and non-sequence features "
            "(2D). Options: 1) Set reduce_output in sequence feature encoders to a value other than None to ensure 2D "
            "encoder outputs, 2) Choose a different combiner like `sequence_concat` which can handle a mix of 2D and "
            "3D encoder output shapes, or 3) Remove features to ensure that output shapes from all encoders are the "
            "same dimension (all 2D or all 3D)."
        )

def initvars(
    obj: object,
    include_defaults: bool = False,
    include_kwargs: bool = False,
    include_properties: bool = False,
) -> Dict[Any, Any]:
    assert hasattr(obj, '__init__')
    state = {k: v for k, v in obj.__dict__.items() if not k.startswith('_')}
    signature = extract_signature(obj.__init__)  # pylint: disable=redefined-outer-name
    bind = signature.bind(**state)

    if include_defaults is True:
        bind.apply_defaults()
        arguments = bind.arguments
    else:
        arguments = {
            k: v
            for k, v in bind.arguments.items()
            if signature.parameters[k].default != v
        }

    if not include_kwargs:
        arguments.pop('kwargs', None)

    if not include_properties:
        arguments.pop('properties_list', None)
        arguments.pop('image_properties', None)
        arguments.pop('label_properties', None)
        arguments.pop('prediction_properties', None)

    return arguments

def convert_visual_bert_checkpoint(checkpoint_path, pytorch_dump_folder_path):
    assert checkpoint_path.split("/")[-1] in ACCEPTABLE_CHECKPOINTS, (
        f"The checkpoint provided must be in {ACCEPTABLE_CHECKPOINTS}."
    )

    # Get Config
    if "pre" in checkpoint_path:
        model_type = "pretraining"
        if "vcr" in checkpoint_path:
            config_params = {"visual_embedding_dim": 512}
        elif "vqa_advanced" in checkpoint_path:
            config_params = {"visual_embedding_dim": 2048}
        elif "vqa" in checkpoint_path:
            config_params = {"visual_embedding_dim": 2048}
        elif "nlvr" in checkpoint_path:
            config_params = {"visual_embedding_dim": 1024}
        else:
            raise NotImplementedError(f"No implementation found for `{checkpoint_path}`.")
    else:
        if "vcr" in checkpoint_path:
            config_params = {"visual_embedding_dim": 512}
            model_type = "multichoice"
        elif "vqa_advanced" in checkpoint_path:
            config_params = {"visual_embedding_dim": 2048}
            model_type = "vqa_advanced"
        elif "vqa" in checkpoint_path:
            config_params = {"visual_embedding_dim": 2048, "num_labels": 3129}
            model_type = "vqa"
        elif "nlvr" in checkpoint_path:
            config_params = {
                "visual_embedding_dim": 1024,
                "num_labels": 2,
            }
            model_type = "nlvr"

    config = VisualBertConfig(**config_params)

    # Load State Dict
    state_dict = load_state_dict(checkpoint_path)

    new_state_dict = get_new_dict(state_dict, config)

    if model_type == "pretraining":
        model = VisualBertForPreTraining(config)
    elif model_type == "vqa":
        model = VisualBertForQuestionAnswering(config)
    elif model_type == "nlvr":
        model = VisualBertForVisualReasoning(config)
    elif model_type == "multichoice":
        model = VisualBertForMultipleChoice(config)

    model.load_state_dict(new_state_dict)
    # Save Checkpoints
    Path(pytorch_dump_folder_path).mkdir(exist_ok=True)
    model.save_pretrained(pytorch_dump_folder_path)

def cuda_toolkit_include_path() -> Tuple[str, str]:
    # Try finding CUDA
    cuda_home: Optional[Path] = None
    if cuda_home is None and os.getenv("CUDA_HOME"):
        # Check in CUDA_HOME
        cuda_home = Path(os.getenv("CUDA_HOME")) / "include"
    if cuda_home is None:
        # Check in NVCC
        nvcc_bin = shutil.which("nvcc")
        if nvcc_bin is not None:
            cuda_home = Path(nvcc_bin.rstrip("/bin/nvcc")) / "include"
    if cuda_home is None:
        # Last-ditch guess in /usr/local/cuda
        if Path("/usr/local/cuda").is_dir():
            cuda_home = Path("/usr/local/cuda") / "include"
    return cuda_home

def promote_input_dtypes(input_vars):
    def _is_same_dtype(dtype1, dtype2):
        return builtin_to_string(dtype1) == builtin_to_string(dtype2)

    def _promoted_var(var, promoted_dtype):
        if var.val is None:
            x = mb.cast(
                x=var, dtype=builtin_to_string(promoted_dtype), name=var.name + "_promoted")
        else:
            const_value_after_cast = cast_op_class.get_cast_value(var, builtin_to_string(promoted_dtype))
            x = mb.const(val=const_value_after_cast, name=var.name + "_promoted")
        return x

    for i, var in enumerate(input_vars):
        if not isinstance(var, Var):
            input_vars[i] = mb.const(val=var)

    promoted_dtype = promote_dtypes([var.dtype for var in input_vars])

    for i, var in enumerate(input_vars):
        if not _is_same_dtype(var.dtype, promoted_dtype):
            input_vars[i] = _promoted_var(var, promoted_dtype)

    return input_vars

def get_paths(
    patterns: Union[str, List[str]],
    recursive: bool = True,
    size: Optional[int] = None,
    exclude_regex: Optional[str] = None,
) -> Generator[str, None, None]:

    if isinstance(patterns, str):
        patterns = [patterns]

    regex_to_exclude = None
    if exclude_regex:
        try:
            regex_to_exclude = re.compile(exclude_regex)
        except re.error:
            raise ValueError(f'`{exclude_regex}` is not a valid regex.')

    def _iter_file_extensions(ps):
        return itertools.chain.from_iterable(
            glob.iglob(os.path.expanduser(p), recursive=recursive) for p in ps
        )

    num_docs = 0
    for file_path in _iter_file_extensions(patterns):
        if regex_to_exclude and regex_to_exclude.match(file_path):
            continue

        yield file_path

        num_docs += 1
        if size is not None and num_docs >= size:
            break

def feature_selection(self, top=100, method=CHISQUARED, threshold=0.0, weighted=False):
        if method is None:
            f = lambda w: 1.0
        if method in (X2, CHISQUARE, CHISQUARED, "X2"):
            f = lambda w: 1.0 - self.x2(w)
        if method in (IG, INFOGAIN):
            f = self.ig
        if method in (GR, GAINRATIO):
            f = self.gr
        if method == DF:
            f = self.df
        if hasattr(method, "__call__"):
            f = method
        subset = ((f(w), w) for w in self.terms if self.df(w) >= threshold)
        subset = sorted(subset, key=itemgetter(1))
        subset = sorted(subset, key=itemgetter(0), reverse=True)
        subset = subset[:top if top is not None else len(subset)]
        subset = subset if weighted else [w for x, w in subset]
        return subset

def find_matching_node_groups(
    terms: List[str], all_node_groups=None, *, is_exact_match: bool = False
):
    if not terms:
        return []
    if not all_node_groups:
        client = get_client()
        all_node_groups = client.nodegroup.list_all()

    seen_ids = set()
    matches = []
    for ng in all_node_groups:
        if is_exact_match:
            ok = any((t == ng.metadata.id_) or (t == ng.metadata.name) for t in terms)
        else:
            ok = any((t in ng.metadata.id_) or (t in ng.metadata.name) for t in terms)
        if ok:
            if ng.metadata.id_ in seen_ids:
                continue
            seen_ids.add(ng.metadata.id_)
            matches.append(ng)
    return matches

def get_last_daily_ci_run(token, workflow_run_id=None, workflow_id=None, commit_sha=None):
    headers = None
    if token is not None:
        headers = {"Accept": "application/vnd.github+json", "Authorization": f"Bearer {token}"}

    workflow_run = None
    if workflow_run_id is not None and workflow_run_id != "":
        workflow_run = requests.get(
            f"https://api.github.com/repos/huggingface/transformers/actions/runs/{workflow_run_id}", headers=headers
        ).json()
        return workflow_run

    workflow_runs = get_daily_ci_runs(token, workflow_id=workflow_id)
    for run in workflow_runs:
        if commit_sha in [None, ""] and run["status"] == "completed":
            workflow_run = run
            break
        # if `commit_sha` is specified, return the latest completed run with `workflow_run["head_sha"]` matching the specified sha.
        elif commit_sha not in [None, ""] and run["head_sha"] == commit_sha and run["status"] == "completed":
            workflow_run = run
            break

    return workflow_run

def add(
        self,
        embeddings: List[List[float]],
        routes: List[str],
        utterances: List[str],
        function_schemas: Optional[List[Dict[str, Any]]] = None,
        metadata_list: List[Dict[str, Any]] = [],
        **kwargs,
    ):
        embeds = np.array(embeddings)  # type: ignore
        routes_arr = np.array(routes)
        if isinstance(utterances[0], str):
            utterances_arr = np.array(utterances)
        else:
            utterances_arr = np.array(utterances, dtype=object)
        if self.index is None:
            self.index = embeds  # type: ignore
            self.routes = routes_arr
            self.utterances = utterances_arr
            self.metadata = (
                np.array(metadata_list, dtype=object)
                if metadata_list
                else np.array([{} for _ in utterances], dtype=object)
            )
        else:
            self.index = np.concatenate([self.index, embeds])
            self.routes = np.concatenate([self.routes, routes_arr])
            self.utterances = np.concatenate([self.utterances, utterances_arr])
            if self.metadata is not None:
                self.metadata = np.concatenate(
                    [
                        self.metadata,
                        np.array(metadata_list, dtype=object)
                        if metadata_list
                        else np.array([{} for _ in utterances], dtype=object),
                    ]
                )
            else:
                self.metadata = (
                    np.array(metadata_list, dtype=object)
                    if metadata_list
                    else np.array([{} for _ in utterances], dtype=object)
                )

def guess_mode(
        self,
        data: np.ndarray | torch.Tensor,
        file_type: str | None = None,
    ) -> str:
        # TODO: do we want to support dimensions being at the beginning of the array?
        ndims = data.ndim
        if util.is_pytorch_tensor_typename(util.get_full_typename(data)):
            # Torch tenors typically have the channels dimension first
            num_channels = data.shape[0]
        else:
            num_channels = data.shape[-1]

        if ndims == 2 or num_channels == 1:
            return "L"
        elif num_channels == 3:
            return "RGB"
        elif num_channels == 4:
            if file_type in ["jpg", "jpeg"]:
                wandb.termwarn(
                    "JPEG format does not support transparency. "
                    "Ignoring alpha channel.",
                    repeat=False,
                )
                return "RGB"
            else:
                return "RGBA"
        else:
            raise ValueError(
                f"Un-supported shape for image conversion {list(data.shape)}"
            )

def handle_property_type(
    property_type: str, item: dict[str, Any], expected_impact: ExpectedImpact = ExpectedImpact.HIGH
) -> list[ParameterBaseTypes | list[ParameterBaseTypes]]:
    parameter_metadata = item.get("parameter_metadata", None)
    if not parameter_metadata:
        return []

    # don't explore internal only parameters.
    if parameter_metadata.get("internal_only", True):
        return []

    # don't explore parameters that have expected impact less than HIGH.
    if parameter_metadata.get("expected_impact", ExpectedImpact.LOW) < expected_impact:
        return []

    if property_type == "number":
        return explore_number(item)
    elif property_type == "integer":
        return explore_integer(item)
    elif property_type == "string":
        return explore_string(item)
    elif property_type == "boolean":
        return explore_boolean()
    elif property_type == "null":
        return explore_null()
    elif property_type == "array":
        return explore_array(item)
    else:
        return []

def from_job_status(cls,
                        status: Optional['job_lib.JobStatus']) -> 'JobExitCode':
        # Import here to avoid circular imports
        # pylint: disable=import-outside-toplevel
        from sky.skylet import job_lib

        if status is None:
            return cls.NOT_FOUND

        if not status.is_terminal():
            return cls.NOT_FINISHED

        if status == job_lib.JobStatus.SUCCEEDED:
            return cls.SUCCEEDED

        if status == job_lib.JobStatus.CANCELLED:
            return cls.CANCELLED

        if status in job_lib.JobStatus.user_code_failure_states(
        ) or status == job_lib.JobStatus.FAILED_DRIVER:
            return cls.FAILED

        # Should not hit this case, but included to avoid errors
        return cls.FAILED

def format_timestamp(self, dt: datetime) -> str:
        ms = dt.strftime("%f")[:3]
        current_parts = [dt.strftime("%H"), dt.strftime("%M"), dt.strftime("%S"), ms]

        if self._last_datetime and dt < self._last_datetime:
            self._last_timestamp_parts = current_parts[:]
            self._last_datetime = dt
            return f"{current_parts[0]}:{current_parts[1]}:{current_parts[2]}.{current_parts[3]}"

        display_parts = []
        for i, (last, current) in enumerate(
            zip(self._last_timestamp_parts, current_parts)
        ):
            if current != last:
                display_parts = current_parts[i:]
                break
        else:
            display_parts = [current_parts[3]]

        self._last_timestamp_parts = current_parts[:]
        self._last_datetime = dt

        if len(display_parts) == 4:
            timestamp_str = f"{display_parts[0]}:{display_parts[1]}:{display_parts[2]}.{display_parts[3]}"
        elif len(display_parts) == 3:
            timestamp_str = f":{display_parts[0]}:{display_parts[1]}.{display_parts[2]}"
        elif len(display_parts) == 2:
            timestamp_str = f":{display_parts[0]}.{display_parts[1]}"
        else:
            timestamp_str = f".{display_parts[0]}"

        return f"{timestamp_str:>12}"

def receive_weights(
        self,
        policy_or_weights: (
            TensorDictBase | TensorDictModuleBase | nn.Module | dict | None
        ) = None,
        *,
        weights: TensorDictBase | dict | None = None,
        policy: TensorDictModuleBase | nn.Module | None = None,
    ) -> None:
        # Handle the different keyword argument forms
        if weights is not None:
            if policy_or_weights is not None:
                raise ValueError(
                    "Cannot specify both positional 'policy_or_weights' and keyword 'weights'"
                )
            if policy is not None:
                raise ValueError("Cannot specify both 'weights' and 'policy'")
            policy_or_weights = weights

        if policy is not None:
            if policy_or_weights is not None:
                raise ValueError(
                    "Cannot specify both positional 'policy_or_weights' and keyword 'policy'"
                )
            policy_or_weights = policy

        if getattr(self, "_receiver_schemes", None) is not None:
            if policy_or_weights is not None:
                raise ValueError(
                    "Cannot specify 'policy_or_weights' when using 'receiver_schemes'. Schemes should know how to get the weights."
                )
            self._receive_weights_scheme()
            return

        # No weight updater configured
        # For single-process collectors, apply weights locally if explicitly provided
        if policy_or_weights is not None:
            from torchrl.weight_update.weight_sync_schemes import WeightStrategy

            # Use WeightStrategy to apply weights properly
            strategy = WeightStrategy(extract_as="tensordict")

            # Extract weights if needed
            if isinstance(policy_or_weights, nn.Module):
                weights = strategy.extract_weights(policy_or_weights)
            else:
                weights = policy_or_weights

            # Apply to local policy
            if hasattr(self, "policy") and isinstance(self.policy, nn.Module):
                strategy.apply_weights(self.policy, weights)

def BoolEncoder(field_number, is_repeated, is_packed):
  false_byte = b'\x00'
  true_byte = b'\x01'
  if is_packed:
    tag_bytes = TagBytes(field_number, wire_format.WIRETYPE_LENGTH_DELIMITED)
    local_EncodeVarint = _EncodeVarint
    def EncodePackedField(write, value, deterministic):
      write(tag_bytes)
      local_EncodeVarint(write, len(value), deterministic)
      for element in value:
        if element:
          write(true_byte)
        else:
          write(false_byte)
    return EncodePackedField
  elif is_repeated:
    tag_bytes = TagBytes(field_number, wire_format.WIRETYPE_VARINT)
    def EncodeRepeatedField(write, value, unused_deterministic=None):
      for element in value:
        write(tag_bytes)
        if element:
          write(true_byte)
        else:
          write(false_byte)
    return EncodeRepeatedField
  else:
    tag_bytes = TagBytes(field_number, wire_format.WIRETYPE_VARINT)
    def EncodeField(write, value, unused_deterministic=None):
      write(tag_bytes)
      if value:
        return write(true_byte)
      return write(false_byte)
    return EncodeField

def train(self, max_epochs, load_latest=False, fail_safe=True):
        epoch = -1
        num_tries = 10
        for i in range(num_tries):
            try:
                if load_latest:
                    self.load_checkpoint()

                for epoch in range(self.epoch+1, max_epochs+1):
                    self.epoch = epoch

                    self.train_epoch()

                    if self.lr_scheduler is not None:
                        self.lr_scheduler.step()

                    if self._checkpoint_dir:
                        self.save_checkpoint()
            except:
                print('Training crashed at epoch {}'.format(epoch))
                if fail_safe:
                    self.epoch -= 1
                    load_latest = True
                    print('Traceback for the error!')
                    print(traceback.format_exc())
                    print('Restarting training from last epoch ...')
                else:
                    raise

        print('Finished training!')

def num_parameters(self, only_trainable: bool = False, exclude_embeddings: bool = False) -> int:
        if exclude_embeddings:
            embedding_param_names = [
                f"{name}.weight" for name, module_type in self.named_modules() if isinstance(module_type, nn.Embedding)
            ]

        is_loaded_in_4bit = getattr(self, "is_loaded_in_4bit", False)
        if is_loaded_in_4bit:
            import bitsandbytes as bnb

        total_params = 0
        for name, param in self.named_parameters():
            if exclude_embeddings and name in embedding_param_names:
                continue
            if param.requires_grad or not only_trainable:
                # For 4bit models, we need to multiply the number of parameters by 2 as half of the parameters are
                # used for the 4bit quantization (uint8 tensors are stored)
                if is_loaded_in_4bit and isinstance(param, bnb.nn.Params4bit):
                    if hasattr(param, "element_size"):
                        num_bytes = param.element_size()
                    elif hasattr(param, "quant_storage"):
                        num_bytes = param.quant_storage.itemsize
                    else:
                        num_bytes = 1
                    total_params += param.numel() * 2 * num_bytes
                else:
                    total_params += param.numel()

        return total_params

def tags_to_entities(tags: Iterable[str]) -> List[Tuple[str, int, int]]:
    entities = []
    start = None
    for i, tag in enumerate(tags):
        if tag is None or tag.startswith("-"):
            # TODO: We shouldn't be getting these malformed inputs. Fix this.
            if start is not None:
                start = None
            else:
                entities.append(("", i, i))
        elif tag.startswith("O"):
            pass
        elif tag.startswith("I"):
            if start is None:
                raise ValueError(
                    Errors.E067.format(start="I", tags=list(tags)[: i + 1])
                )
        elif tag.startswith("U"):
            entities.append((tag[2:], i, i))
        elif tag.startswith("B"):
            start = i
        elif tag.startswith("L"):
            if start is None:
                raise ValueError(
                    Errors.E067.format(start="L", tags=list(tags)[: i + 1])
                )
            entities.append((tag[2:], start, i))
            start = None
        else:
            raise ValueError(Errors.E068.format(tag=tag))
    return entities

def add_vision_dataset_transform(dataset: VisionDataset, transform: Callable, is_tensor_transform: bool = False):
    transform_added_logstring = textwrap.dedent(
        f"""Transform {transform} added to dataset.
        Dataset now has the following transforms: {dataset.transform}""",
    )

    if dataset.transform is None:
        dataset.transform = transform
        log.warning(transform_added_logstring)
    elif isinstance(dataset.transform, transforms.Compose):
        insertion_index = len(dataset.transform.transforms)
        for i, t in enumerate(dataset.transform.transforms):
            if isinstance(t, transforms.ToTensor):
                insertion_index = i
                break
        if is_tensor_transform:
            insertion_index += 1
        dataset.transform.transforms.insert(insertion_index, transform)
        log.warning(transform_added_logstring)
    else:  # transform is some other basic transform, join using Compose
        if isinstance(dataset.transform, transforms.ToTensor) and not is_tensor_transform:
            dataset.transform = transforms.Compose([transform, dataset.transform])
            log.warning(transform_added_logstring)
        else:
            dataset.transform = transforms.Compose([dataset.transform, transform])
            log.warning(transform_added_logstring)

def discover_agents(agent_name: str = None) -> Dict[str, Any]:
            try:
                if agent_name:
                    # Get specific agent info
                    if agent_name not in self.agents:
                        return {
                            "success": False,
                            "error": f"Agent '{agent_name}' not found",
                            "agents": [],
                        }

                    agent_info = self._get_agent_discovery_info(
                        agent_name
                    )
                    return {
                        "success": True,
                        "agents": [agent_info] if agent_info else [],
                    }
                else:
                    # Get all agents info
                    all_agents_info = []
                    for tool_name in self.agents.keys():
                        agent_info = self._get_agent_discovery_info(
                            tool_name
                        )
                        if agent_info:
                            all_agents_info.append(agent_info)

                    return {
                        "success": True,
                        "agents": all_agents_info,
                    }

            except Exception as e:
                error_msg = str(e)
                logger.error(
                    f"Error in discover_agents tool: {error_msg}"
                )
                return {
                    "success": False,
                    "error": error_msg,
                    "agents": [],
                }

def save_pretrained(self, save_directory: str | os.PathLike, **kwargs: Any):
        if os.path.isfile(save_directory):
            logger.error(f"Provided path ({save_directory}) should be a directory, not a file")
            return
        os.makedirs(save_directory, exist_ok=True)

        if hasattr(self, "_registered_impl"):
            # Add info to the config
            pipeline_info = self._registered_impl.copy()
            custom_pipelines = {}
            for task, info in pipeline_info.items():
                if info["impl"] != self.__class__:
                    continue

                info = info.copy()
                module_name = info["impl"].__module__
                last_module = module_name.split(".")[-1]
                # Change classes into their names/full names
                info["impl"] = f"{last_module}.{info['impl'].__name__}"
                info["pt"] = tuple(c.__name__ for c in info["pt"])

                custom_pipelines[task] = info
            self.model.config.custom_pipelines = custom_pipelines
            # Save the pipeline custom code
            custom_object_save(self, save_directory)

        self.model.save_pretrained(save_directory, **kwargs)

        if self.tokenizer is not None:
            self.tokenizer.save_pretrained(save_directory, **kwargs)

        if self.feature_extractor is not None:
            self.feature_extractor.save_pretrained(save_directory, **kwargs)

        if self.image_processor is not None:
            self.image_processor.save_pretrained(save_directory, **kwargs)

def click_event(event: int, x: int, y: int, flags: int, param) -> None:
    global selected_object_id, latest_detections
    if event == cv2.EVENT_LBUTTONDOWN:
        if not latest_detections:
            return
        min_area = float("inf")
        best_match = None
        for track in latest_detections:
            if len(track) < 6:
                continue
            x1, y1, x2, y2 = map(int, track[:4])
            if x1 <= x <= x2 and y1 <= y <= y2:
                area = max(0, x2 - x1) * max(0, y2 - y1)
                if area < min_area:
                    track_id = int(track[4]) if len(track) >= 7 else -1
                    class_id = int(track[6]) if len(track) >= 7 else int(track[5])
                    min_area = area
                    best_match = (track_id, classes.get(class_id, str(class_id)))
        if best_match:
            selected_object_id, label = best_match
            LOGGER.info(f"Tracking started: {label} (ID {selected_object_id})")

def autoguide(self, name, dist_constructor):
        if name not in self._priors:
            raise ValueError("There is no prior for parameter: {}".format(name))

        if dist_constructor not in [dist.Delta, dist.Normal, dist.MultivariateNormal]:
            raise NotImplementedError(
                "Unsupported distribution type: {}".format(dist_constructor)
            )

        # delete old guide
        if name in self._guides:
            dist_args = self._guides[name][1]
            for arg in dist_args:
                delattr(self, "{}_{}".format(name, arg))

        p = self._priors[name]()  # init_to_sample strategy
        if dist_constructor is dist.Delta:
            support = self._priors[name].support
            if _is_real_support(support):
                p_map = Parameter(p.detach())
            else:
                p_map = PyroParam(p.detach(), support)
            setattr(self, "{}_map".format(name), p_map)
            dist_args = ("map",)
        elif dist_constructor is dist.Normal:
            loc = Parameter(biject_to(self._priors[name].support).inv(p).detach())
            scale = PyroParam(loc.new_ones(loc.shape), constraints.positive)
            setattr(self, "{}_loc".format(name), loc)
            setattr(self, "{}_scale".format(name), scale)
            dist_args = ("loc", "scale")
        elif dist_constructor is dist.MultivariateNormal:
            loc = Parameter(biject_to(self._priors[name].support).inv(p).detach())
            identity = eye_like(loc, loc.size(-1))
            scale_tril = PyroParam(
                identity.repeat(loc.shape[:-1] + (1, 1)), constraints.lower_cholesky
            )
            setattr(self, "{}_loc".format(name), loc)
            setattr(self, "{}_scale_tril".format(name), scale_tril)
            dist_args = ("loc", "scale_tril")
        else:
            raise NotImplementedError

        self._guides[name] = (dist_constructor, dist_args)

def fit(self, X, y=None):
        # at fit, convert sparse matrices to csc for optimized computation of
        # the quantiles
        X = validate_data(
            self,
            X,
            accept_sparse="csc",
            dtype=FLOAT_DTYPES,
            ensure_all_finite="allow-nan",
        )

        q_min, q_max = self.quantile_range
        if not 0 <= q_min <= q_max <= 100:
            raise ValueError("Invalid quantile range: %s" % str(self.quantile_range))

        if self.with_centering:
            if sparse.issparse(X):
                raise ValueError(
                    "Cannot center sparse matrices: use `with_centering=False`"
                    " instead. See docstring for motivation and alternatives."
                )
            self.center_ = np.nanmedian(X, axis=0)
        else:
            self.center_ = None

        if self.with_scaling:
            quantiles = []
            for feature_idx in range(X.shape[1]):
                if sparse.issparse(X):
                    column_nnz_data = X.data[
                        X.indptr[feature_idx] : X.indptr[feature_idx + 1]
                    ]
                    column_data = np.zeros(shape=X.shape[0], dtype=X.dtype)
                    column_data[: len(column_nnz_data)] = column_nnz_data
                else:
                    column_data = X[:, feature_idx]

                quantiles.append(np.nanpercentile(column_data, self.quantile_range))

            quantiles = np.transpose(quantiles)

            self.scale_ = quantiles[1] - quantiles[0]
            self.scale_ = _handle_zeros_in_scale(self.scale_, copy=False)
            if self.unit_variance:
                adjust = stats.norm.ppf(q_max / 100.0) - stats.norm.ppf(q_min / 100.0)
                self.scale_ = self.scale_ / adjust
        else:
            self.scale_ = None

        return self

def eval_precision(self, eval_trackers=None):
        if eval_trackers is None:
            eval_trackers = self.dataset.tracker_names
        if isinstance(eval_trackers, str):
            eval_trackers = [eval_trackers]

        precision_ret = {}
        for tracker_name in eval_trackers:
            precision_ret_ = {}
            for video in self.dataset:
                gt_traj = np.array(video.gt_traj)
                if tracker_name not in video.pred_trajs:
                    tracker_traj = video.load_tracker(self.dataset.tracker_path,
                                                      tracker_name, False)
                    tracker_traj = np.array(tracker_traj)
                else:
                    tracker_traj = np.array(video.pred_trajs[tracker_name])
                n_frame = len(gt_traj)
                if hasattr(video, 'absent'):
                    gt_traj = gt_traj[video.absent == 1]
                    tracker_traj = tracker_traj[video.absent == 1]
                gt_center = self.convert_bb_to_center(gt_traj)
                tracker_center = self.convert_bb_to_center(tracker_traj)
                thresholds = np.arange(0, 51, 1)
                precision_ret_[video.name] = success_error(gt_center, tracker_center,
                                                           thresholds, n_frame)
            precision_ret[tracker_name] = precision_ret_
        return precision_ret

def update_pipeline_and_auto_class_table(table):
    auto_modules = [
        transformers_module.models.auto.modeling_auto,
        transformers_module.models.auto.modeling_tf_auto,
        transformers_module.models.auto.modeling_flax_auto,
    ]
    for pipeline_tag, model_mapping, auto_class in PIPELINE_TAGS_AND_AUTO_MODELS:
        model_mappings = [model_mapping, f"TF_{model_mapping}", f"FLAX_{model_mapping}"]
        auto_classes = [auto_class, f"TF_{auto_class}", f"Flax_{auto_class}"]
        # Loop through all three frameworks
        for module, cls, mapping in zip(auto_modules, auto_classes, model_mappings):
            # The type of pipeline may not exist in this framework
            if not hasattr(module, mapping):
                continue
            # First extract all model_names
            model_names = []
            for name in getattr(module, mapping).values():
                if isinstance(name, str):
                    model_names.append(name)
                else:
                    model_names.extend(list(name))

            # Add pipeline tag and auto model class for those models
            table.update({model_name: (pipeline_tag, cls) for model_name in model_names})

    return table

def run_partial(self, **kwargs):
        print("Running partial experiment...")
        if len(kwargs) > 1:
            raise RuntimeError("Not supported.")
        arg_name, arg_value = list(kwargs.items())[0]

        orginal_arg_value = arg_value
        if arg_name == "messages" and isinstance(arg_value, PromptSelector):
            arg_value = arg_value.for_openai_chat()

        partial_all_args = copy.deepcopy(self.all_args)
        partial_all_args[arg_name] = [arg_value]

        partial_argument_combos = [
            dict(zip(partial_all_args, val)) for val in itertools.product(*partial_all_args.values())
        ]
        original_n_results = len(self.queue.get_results()) if self.queue else 0

        # Execute partial experiment
        for combo in partial_argument_combos:
            self.queue.enqueue(
                self.completion_fn,
                # We need to filter out defaults that are invalid JSON from the request
                {k: v for k, v in combo.items() if (v is not None) and (v != float("inf"))},
            )

        # Verify new results are added
        if len(self.queue.get_results()) - original_n_results == 0:
            logging.error("No results. Something went wrong.")
            raise PromptExperimentException

        # Currently, it always append new rows to the results.
        # In the future, we may want to replace existing rows instead.
        self._construct_result_dfs(self.queue.get_input_args(), self.queue.get_results(), self.queue.get_latencies())

        # If `arg_value` didn't exist before, add to `argument_combos`, which will be used in the next `.run()`
        if arg_value not in self.all_args[arg_name]:
            if arg_name == "messages":
                if isinstance(orginal_arg_value, PromptSelector):
                    self.prompt_keys[
                        str(orginal_arg_value.for_openai_chat()[-1]["content"])
                    ] = orginal_arg_value.for_llama()
                else:
                    self.prompt_keys.append(arg_value)
            self.all_args[arg_name].append(arg_value)
            self.prepare()

def set_custom_fsdp_module_kwargs(module_kwargs: dict, process_group_cache: dict[tuple[int], Any]) -> dict:
    if ('sharding_strategy' in module_kwargs and module_kwargs['sharding_strategy'] not in SHARDING_MAP.values()):
        module_kwargs['sharding_strategy'] = SHARDING_MAP[module_kwargs['sharding_strategy'].upper()]
    if 'backward_prefetch' in module_kwargs:
        if module_kwargs['backward_prefetch'] not in BACKWARD_PREFETCH_MAP.values():
            module_kwargs['backward_prefetch'] = BACKWARD_PREFETCH_MAP[module_kwargs['backward_prefetch'].upper()]
    if 'cpu_offload' in module_kwargs and not isinstance(module_kwargs['cpu_offload'], CPUOffload):
        module_kwargs['cpu_offload'] = get_cpu_offload(cpu_offload=module_kwargs['cpu_offload'].upper())
    if 'mixed_precision' in module_kwargs and not isinstance(module_kwargs['mixed_precision'], MixedPrecision):
        # `precision` needs to set `'mixed_precision'`, but `precision` is not part of fsdp kwargs
        raise NotImplementedError(
            f"Automated setting of custom per module mixed_precision is not implemented, but it can be set if `isinstance(module_kwargs['mixed_precision'], MixedPrecision)`",
        )
    if 'process_group' in module_kwargs:
        # Call on every process group if it is a tuple/list of non-ints
        if type(module_kwargs['process_group']) in [
            list,
            tuple,
        ] and not all(isinstance(x, int) for x in module_kwargs['process_group']):
            module_kwargs['process_group'] = tuple(
                _get_process_group(pg, process_group_cache) for pg in module_kwargs['process_group']
            )
        else:
            module_kwargs['process_group'] = _get_process_group(module_kwargs['process_group'], process_group_cache)

    return module_kwargs

def validate_rule_info(rule: RuleInfo) -> list[str]:
    issues = []

    # Check required attributes are present and valid
    if not rule.code:
        issues.append("Missing rule code")
    elif not re.match(r'^M[BRF]\d{3}$', rule.code):
        issues.append(f"Invalid rule code format: {rule.code} (expected MB###, MR###, or MF###)")

    if not rule.name:
        issues.append("Missing rule name")

    if not rule.description:
        issues.append("Missing rule description")

    if not isinstance(rule.severity, Severity):
        issues.append(f"Invalid severity: {rule.severity}")

    if not isinstance(rule.fixable, (bool, str)) or (isinstance(rule.fixable, str) and rule.fixable != "unsafe"):
        issues.append(f"Fixable must be a boolean or 'unsafe', got {rule.fixable}")

    # Validate docstring exists and is properly formatted
    if not rule.docstring:
        issues.append("Missing docstring")
    else:
        lines = rule.docstring.split('\n')
        first_line = lines[0].strip() if lines else ""
        if first_line and ':' in first_line:
            docstring_code = first_line.split(':')[0].strip()
            if docstring_code != rule.code:
                issues.append(f"Docstring code '{docstring_code}' doesn't match class code '{rule.code}'")

    # Validate rule code matches severity prefix
    code_prefix = rule.code[:2]
    expected_prefixes = {
        Severity.BREAKING: "MB",
        Severity.RUNTIME: "MR",
        Severity.FORMATTING: "MF"
    }
    expected_prefix = expected_prefixes.get(rule.severity)
    if expected_prefix and code_prefix != expected_prefix:
        issues.append(f"Rule code prefix '{code_prefix}' doesn't match severity '{rule.severity.value}' (expected '{expected_prefix}')")

    return issues

def to_ms(self):
        #: we treat tick intervals is 5s, you could change it
        if self == IntervalLevel.LEVEL_TICK:
            return 5 * 1000
        if self == IntervalLevel.LEVEL_1MIN:
            return 60 * 1000
        if self == IntervalLevel.LEVEL_5MIN:
            return 5 * 60 * 1000
        if self == IntervalLevel.LEVEL_15MIN:
            return 15 * 60 * 1000
        if self == IntervalLevel.LEVEL_30MIN:
            return 30 * 60 * 1000
        if self == IntervalLevel.LEVEL_1HOUR:
            return 60 * 60 * 1000
        if self == IntervalLevel.LEVEL_4HOUR:
            return 4 * 60 * 60 * 1000
        if self == IntervalLevel.LEVEL_1DAY:
            return 24 * 60 * 60 * 1000
        if self == IntervalLevel.LEVEL_1WEEK:
            return 7 * 24 * 60 * 60 * 1000
        if self == IntervalLevel.LEVEL_1MON:
            return 31 * 7 * 24 * 60 * 60 * 1000

def execute_function_multithreaded(fn,
                                   args_list,
                                   block_until_all_done=True,
                                   max_concurrent_executions=1000):
    result_queue = queue.Queue()
    worker_queue = queue.Queue()

    for i, arg in enumerate(args_list):
        arg.append(i)
        worker_queue.put(arg)

    def fn_execute():
        while True:
            try:
                arg = worker_queue.get(block=False)
            except queue.Empty:
                return
            exec_index = arg[-1]
            res = fn(*arg[:-1])
            result_queue.put((exec_index, res))

    threads = []
    number_of_threads = min(max_concurrent_executions, len(args_list))

    for _ in range(number_of_threads):
        thread = in_thread(target=fn_execute, daemon=not block_until_all_done)
        threads.append(thread)

    # Returns the results only if block_until_all_done is set.
    results = None
    if block_until_all_done:

        # Because join() cannot be interrupted by signal, a single join()
        # needs to be separated into join()s with timeout in a while loop.
        have_alive_child = True
        while have_alive_child:
            have_alive_child = False
            for t in threads:
                t.join(0.1)
                if t.is_alive():
                    have_alive_child = True

        results = {}
        while not result_queue.empty():
            item = result_queue.get()
            results[item[0]] = item[1]

        if len(results) != len(args_list):
            raise RuntimeError(
                'Some threads for func {func} did not complete '
                'successfully.'.format(func=fn.__name__))
    return results

def generate_valid_param(constraint):
    if isinstance(constraint, _ArrayLikes):
        return np.array([1, 2, 3])

    if isinstance(constraint, _SparseMatrices):
        return csr_array([[0, 1], [1, 0]])

    if isinstance(constraint, _RandomStates):
        return np.random.RandomState(42)

    if isinstance(constraint, _Callables):
        return lambda x: x

    if isinstance(constraint, _NoneConstraint):
        return None

    if isinstance(constraint, _InstancesOf):
        if constraint.type is np.ndarray:
            # special case for ndarray since it can't be instantiated without arguments
            return np.array([1, 2, 3])

        if constraint.type in (Integral, Real):
            # special case for Integral and Real since they are abstract classes
            return 1

        return constraint.type()

    if isinstance(constraint, _Booleans):
        return True

    if isinstance(constraint, _VerboseHelper):
        return 1

    if isinstance(constraint, MissingValues) and constraint.numeric_only:
        return np.nan

    if isinstance(constraint, MissingValues) and not constraint.numeric_only:
        return "missing"

    if isinstance(constraint, HasMethods):
        return type(
            "ValidHasMethods", (), {m: lambda self: None for m in constraint.methods}
        )()

    if isinstance(constraint, _IterablesNotString):
        return [1, 2, 3]

    if isinstance(constraint, _CVObjects):
        return 5

    if isinstance(constraint, Options):  # includes StrOptions
        for option in constraint.options:
            return option

    if isinstance(constraint, Interval):
        interval = constraint
        if interval.left is None and interval.right is None:
            return 0
        elif interval.left is None:
            return interval.right - 1
        elif interval.right is None:
            return interval.left + 1
        else:
            if interval.type is Real:
                return (interval.left + interval.right) / 2
            else:
                return interval.left + 1

    raise ValueError(f"Unknown constraint type: {constraint}")

def build_payload(
    *,
    display_name: str,
    machine_type: str,
    image_uri: str,
    args: List[str],
    accelerator_type: str = '',
    accelerator_count: int = 0,
    encryption_spec_key_name: str = '',
    labels: Optional[Dict[str, str]] = None,
    scheduling: Optional[Dict[str, Any]] = None,
    base_output_directory: Optional[str] = None,
    tensorboard: Optional[str] = None,
) -> Dict[str, Any]:
  payload = {
      'display_name': display_name,
      'job_spec': {
          'worker_pool_specs': [{
              'replica_count': '1',
              'machine_spec': {'machine_type': str(machine_type)},
              'container_spec': {'image_uri': str(image_uri), 'args': args},
          }]
      },
  }

  if accelerator_type and accelerator_count:
    payload['job_spec']['worker_pool_specs'][0]['machine_spec'][
        'accelerator_type'
    ] = str(accelerator_type)
    payload['job_spec']['worker_pool_specs'][0]['machine_spec'][
        'accelerator_count'
    ] = accelerator_count
  elif accelerator_type and accelerator_count < 1:
    raise ValueError(
        'Accelerator count must be at least 1 if accelerator type '
        f'is specified. Received accelerator_count == {accelerator_count}'
    )
  elif accelerator_count and not accelerator_type:
    raise ValueError(
        'Accelerator type must be specified if accelerator count is not 0.'
        f'Received accelerator_type == {accelerator_type}.'
    )

  if encryption_spec_key_name:
    payload['encryption_spec'] = {'kms_key_name': encryption_spec_key_name}

  if labels:
    payload['labels'] = labels

  if scheduling:
    payload['job_spec']['scheduling'] = scheduling

  if base_output_directory:
    payload['job_spec']['base_output_directory'] = {
        'output_uri_prefix': base_output_directory
    }

  if tensorboard:
    payload['job_spec']['tensorboard'] = tensorboard

  return payload

def from_result(
        results: Any,
        artifact_name: str = "result",
        did_extension: Optional["DIDAgentExtension"] = None,
    ) -> list[Artifact]:
        # Convert result to appropriate part type
        if isinstance(results, str):
            parts = [{"kind": "text", "text": results}]
        elif (
            isinstance(results, (list, tuple))
            and results
            and all(isinstance(item, str) for item in results)
        ):
            # Join streaming results efficiently
            parts = [{"kind": "text", "text": "\n".join(results)}]
        else:
            # Structured data
            parts = [{"kind": "data", "data": {"result": results}}]

        # Apply DID signing if available
        if did_extension:
            metadata_key = app_settings.did.agent_extension_metadata
            # Cast parts to list[dict[str, Any]] to allow metadata assignment
            from typing import cast

            typed_parts_list = cast(list[dict[str, Any]], parts)
            for part in typed_parts_list:
                if part.get("kind") == "text" and "text" in part:
                    text_value = part["text"]
                    if isinstance(text_value, str):
                        if "metadata" not in part:
                            part["metadata"] = {}
                        metadata = part["metadata"]
                        if isinstance(metadata, dict):
                            metadata[metadata_key] = did_extension.sign_text(text_value)
            parts = typed_parts_list

        # Convert dict parts to proper Part types for Artifact
        final_parts: list[Part] = [
            PartConverter.dict_to_part(p) if isinstance(p, dict) else p for p in parts
        ]
        return [Artifact(artifact_id=uuid4(), name=artifact_name, parts=final_parts)]

def is_model_xgboost(data: Any) -> bool:
    if inspect.isclass(data):
        return False

    # Check for direct instance of Booster
    if inspect.isclass(data):
        # Checking if it's a class reference rather than an instance
        if "xgboost.core.Booster" == f"{data.__module__}.{data.__qualname__}":
            return True
    else:
        # Check based on instance attributes and methods
        if hasattr(data, "__class__"):
            class_name = f"{data.__class__.__module__}.{data.__class__.__qualname__}"
            if class_name.startswith("xgboost.core.Booster"):
                return True

    # Check for sklearn API models (like XGBClassifier, XGBRegressor)
    # These models have a get_booster() method
    if hasattr(data, "get_booster"):
        return True

    return False

def parse_agent_interface_format(
    feature_screen=None,
    feature_minimap=None,
    rgb_screen=None,
    rgb_minimap=None,
    action_space=None,
    action_delays=None,
    **kwargs):
  if feature_screen or feature_minimap:
    feature_dimensions = Dimensions(feature_screen, feature_minimap)
  else:
    feature_dimensions = None

  if rgb_screen or rgb_minimap:
    rgb_dimensions = Dimensions(rgb_screen, rgb_minimap)
  else:
    rgb_dimensions = None

  def _action_delay_fn(delays):
    """Delay frequencies per game loop delay -> fn returning game loop delay."""
    if not delays:
      return None
    else:
      total = sum(delays)
      cumulative_sum = np.cumsum([delay / total for delay in delays])
      def fn():
        sample = random.uniform(0, 1) - EPSILON
        for i, cumulative in enumerate(cumulative_sum):
          if sample <= cumulative:
            return i + 1
        raise ValueError("Failed to sample action delay??")
      return fn

  return AgentInterfaceFormat(
      feature_dimensions=feature_dimensions,
      rgb_dimensions=rgb_dimensions,
      action_space=(action_space and actions.ActionSpace[action_space.upper()]),
      action_delay_fn=_action_delay_fn(action_delays),
      **kwargs)

def set_video(
        self,
        video_path: str,
        output_dir: str = None,
        frame_rate: Optional[int] = None,
        prefix: str = "",
    ) -> None:

        if isinstance(video_path, str):
            if video_path.startswith("http"):
                video_path = common.download_file(video_path)
            if os.path.isfile(video_path):
                if output_dir is None:
                    output_dir = common.make_temp_dir()
                    if not os.path.exists(output_dir):
                        os.makedirs(output_dir)
                print(f"Output directory: {output_dir}")
                common.video_to_images(
                    video_path, output_dir, frame_rate=frame_rate, prefix=prefix
                )

            elif os.path.isdir(video_path):
                files = sorted(os.listdir(video_path))
                if len(files) == 0:
                    raise ValueError(f"No files found in {video_path}.")
                elif files[0].endswith(".tif"):
                    self._tif_source = os.path.join(video_path, files[0])
                    self._tif_dir = video_path
                    self._tif_names = files
                    video_path = common.geotiff_to_jpg_batch(video_path)
                output_dir = video_path

            if not os.path.exists(video_path):
                raise ValueError(f"Input path {video_path} does not exist.")
        else:
            raise ValueError("Input video_path must be a string.")

        self.video_path = output_dir
        self._num_images = len(os.listdir(output_dir))
        self._frame_names = sorted(os.listdir(output_dir))
        self.inference_state = self.predictor.init_state(video_path=output_dir)

def thread_executor(max_workers: int = DEFAULT_MAX_WORKERS,
                    disable_tqdm: bool = False,
                    tqdm_desc: str = None,
                    fault_tolerant: bool = False):

    def decorator(func):

        @wraps(func)
        def wrapper(iterable, *args, **kwargs):
            results = []
            # Create a tqdm progress bar with the total number of items to process
            with tqdm(
                    unit_scale=True,
                    unit_divisor=1024,
                    initial=0,
                    total=len(iterable),
                    desc=tqdm_desc or f'Processing {len(iterable)} items',
                    disable=disable_tqdm,
            ) as pbar:
                # Define a wrapper function to update the progress bar
                with ThreadPoolExecutor(max_workers=max_workers) as executor:
                    # Submit all tasks
                    futures = {
                        executor.submit(func, item, *args, **kwargs): item
                        for item in iterable
                    }

                    # Update the progress bar as tasks complete
                    failed_items = []
                    for future in as_completed(futures):
                        pbar.update(1)
                        if fault_tolerant:
                            try:
                                results.append(future.result())
                            except Exception as e:
                                item = futures[future]
                                logger.error(f'Task failed for {item}: {e}')
                                failed_items.append((item, e))
                        else:
                            results.append(future.result())
            if fault_tolerant:
                return results, failed_items
            return results

        return wrapper

    return decorator

def device(x: _ArrayApiObj, /) -> Device:
    if is_numpy_array(x):
        return "cpu"
    elif is_dask_array(x):
        # Peek at the metadata of the Dask array to determine type
        if is_numpy_array(x._meta):
            # Must be on CPU since backed by numpy
            return "cpu"
        return _DASK_DEVICE
    elif is_jax_array(x):
        # FIXME Jitted JAX arrays do not have a device attribute
        #       https://github.com/jax-ml/jax/issues/26000
        #       Return None in this case. Note that this workaround breaks
        #       the standard and will result in new arrays being created on the
        #       default device instead of the same device as the input array(s).
        x_device = getattr(x, "device", None)
        # Older JAX releases had .device() as a method, which has been replaced
        # with a property in accordance with the standard.
        if inspect.ismethod(x_device):
            return x_device()
        else:
            return x_device
    elif is_pydata_sparse_array(x):
        # `sparse` will gain `.device`, so check for this first.
        x_device = getattr(x, "device", None)
        if x_device is not None:
            return x_device
        # Everything but DOK has this attr.
        try:
            inner = x.data  # pyright: ignore
        except AttributeError:
            return "cpu"
        # Return the device of the constituent array
        return device(inner)  # pyright: ignore
    return x.device  # type: ignore  # pyright: ignore

def get_array_module(*args):
    is_chainerx_available = chainerx.is_available()
    if is_chainerx_available or cuda.available:
        arrays = []
        for arg in args:
            # Unwrap arrays
            if isinstance(arg, chainer.variable.Variable):
                array = arg.data
            else:
                array = arg
            if is_chainerx_available and isinstance(array, chainerx.ndarray):
                return chainerx
            arrays.append(array)
        if cuda.available:
            return cuda.cupy.get_array_module(*arrays)
    return numpy

def log_ai_function(response: str, file_name: str, log: bool = True, log_path: str = './logs/', overwrite: bool = True):
    if log:
        # Ensure the directory exists
        os.makedirs(log_path, exist_ok=True)

        # file_name = 'data_wrangler.py'
        file_path = os.path.join(log_path, file_name)

        if not overwrite:
            # If file already exists and we're NOT overwriting, we create a new name
            if os.path.exists(file_path):
                # Use an incremental suffix (e.g., data_wrangler_1.py, data_wrangler_2.py, etc.)
                # or a time-based suffix if you prefer.
                base_name, ext = os.path.splitext(file_name)
                i = 1
                while True:
                    new_file_name = f"{base_name}_{i}{ext}"
                    new_file_path = os.path.join(log_path, new_file_name)
                    if not os.path.exists(new_file_path):
                        file_path = new_file_path
                        file_name = new_file_name
                        break
                    i += 1

        # Write the file
        with open(file_path, 'w', encoding='utf-8') as file:
            file.write(response)

        print(f"      File saved to: {file_path}")

        return (file_path, file_name)

    else:
        return (None, None)

def get_frameworks() -> List[str]:
    _frameworks: List[str] = []
    supported_frameworks = ["pytorch", "jax"]

    # Check environment variable
    if os.getenv("NVTE_FRAMEWORK"):
        _frameworks.extend(os.getenv("NVTE_FRAMEWORK").split(","))

    # Check command-line arguments
    for arg in sys.argv.copy():
        if arg.startswith("--framework="):
            _frameworks.extend(arg.replace("--framework=", "").split(","))
            sys.argv.remove(arg)

    # Detect installed frameworks if not explicitly specified
    if not _frameworks:
        try:
            import torch
        except ImportError:
            pass
        else:
            _frameworks.append("pytorch")
        try:
            import jax
        except ImportError:
            pass
        else:
            _frameworks.append("jax")

    # Special framework names
    if "all" in _frameworks:
        _frameworks = supported_frameworks.copy()
    if "none" in _frameworks:
        _frameworks = []

    # Check that frameworks are valid
    _frameworks = [framework.lower() for framework in _frameworks]
    for framework in _frameworks:
        if framework not in supported_frameworks:
            raise ValueError(f"Transformer Engine does not support framework={framework}")

    return _frameworks

def cutout_on_volumes(
    volumes: np.ndarray,
    holes: np.ndarray,
    fill: tuple[float, ...] | float | Literal["random", "random_uniform", "inpaint_telea", "inpaint_ns"],
    random_generator: np.random.Generator,
) -> np.ndarray:
    volumes = volumes.copy()

    # Handle inpainting methods
    if isinstance(fill, str):
        if fill in {"inpaint_telea", "inpaint_ns"}:
            processed_images = [
                apply_inpainting(img, holes, cast("Literal['inpaint_telea', 'inpaint_ns']", fill))
                for volume in volumes
                for img in volume
            ]
            result = np.array(processed_images)
            # Reshape to original batch of volumes shape: (N, D, H, W, C) or (N, D, H, W)
            return result.reshape(volumes.shape)
        if fill == "random":
            return fill_volumes_holes_with_random(volumes, holes, random_generator, uniform=False)
        if fill == "random_uniform":
            return fill_volumes_holes_with_random(volumes, holes, random_generator, uniform=True)
        raise ValueError(f"Unsupported string fill: {fill}")

    # Convert numeric fill values to numpy array
    if isinstance(fill, (int, float)):
        fill_array = np.array(fill, dtype=volumes.dtype)
        return fill_volumes_holes_with_value(volumes, holes, fill_array)

    # Handle sequence fill values
    fill_array = np.array(fill, dtype=volumes.dtype)

    # For multi-channel images, verify fill matches number of channels
    if volumes.ndim == 5:
        fill_array = fill_array.ravel()
        if fill_array.size != volumes.shape[4]:
            raise ValueError(
                f"Fill value must have same number of channels as image. "
                f"Got {fill_array.size}, expected {volumes.shape[4]}",
            )

    return fill_volumes_holes_with_value(volumes, holes, fill_array)

def xp2tensorflow(
    xp_tensor: ArrayXd, requires_grad: bool = False, as_variable: bool = False
) -> "tf.Tensor":  # type: ignore  # pragma: no cover
    assert_tensorflow_installed()
    if hasattr(xp_tensor, "toDlpack"):
        dlpack_tensor = xp_tensor.toDlpack()  # type: ignore
        tf_tensor = tf.experimental.dlpack.from_dlpack(dlpack_tensor)  # type: ignore
    elif hasattr(xp_tensor, "__dlpack__"):
        dlpack_tensor = xp_tensor.__dlpack__()  # type: ignore
        tf_tensor = tf.experimental.dlpack.from_dlpack(dlpack_tensor)  # type: ignore
    else:
        tf_tensor = tf.convert_to_tensor(xp_tensor)  # type: ignore
    if as_variable:
        # tf.Variable() automatically puts in GPU if available.
        # So we need to control it using the context manager
        with tf.device(tf_tensor.device):  # type: ignore
            tf_tensor = tf.Variable(tf_tensor, trainable=requires_grad)  # type: ignore
    if requires_grad is False and as_variable is False:
        # tf.stop_gradient() automatically puts in GPU if available.
        # So we need to control it using the context manager
        with tf.device(tf_tensor.device):  # type: ignore
            tf_tensor = tf.stop_gradient(tf_tensor)  # type: ignore
    return tf_tensor

def misc_to_space_after(misc):
    if not misc:
        return " "
    pieces = misc.split("|")
    if any(piece.lower() == "spaceafter=no" for piece in pieces):
        return ""
    if "SpaceAfter=Yes" in pieces:
        # as of UD 2.11, the Cantonese treebank had this as a misc feature
        return " "
    if "SpaceAfter=No~" in pieces:
        # as of UD 2.11, a weird typo in the Russian Taiga dataset
        return ""
    for piece in pieces:
        if piece.startswith("SpaceAfter=") or piece.startswith("SpacesAfter="):
            misc_space = piece.split("=", maxsplit=1)[1]
            return unescape_misc_space(misc_space)
    return " "

def predict_proba(self, X):
        check_is_fitted(self)

        if not self._is_fitted:
            raise NotFittedError(
                f"This instance of {self.__class__.__name__} has not "
                f"been fitted yet; please call `fit` first."
            )

        # treat case of single class seen in fit
        if self.n_classes_ == 1:
            return np.repeat([[1]], X.shape[0], axis=0)

        if isinstance(X, np.ndarray) and len(X.shape) == 3 and X.shape[1] == 1:
            X = np.reshape(X, (X.shape[0], -1))
        elif not isinstance(X, np.ndarray) or len(X.shape) > 2:
            raise ValueError(
                "ContinuousIntervalTree is not a time series classifier. "
                "A valid sklearn input such as a 2d numpy array is required."
                "Sparse input formats are currently not supported."
            )
        X = self._validate_data_version_safe(
            X=X, reset=False, force_all_finite="allow-nan"
        )

        dists = np.zeros((X.shape[0], self.n_classes_))
        for i in range(X.shape[0]):
            dists[i] = self._root.predict_proba(X[i], self.n_classes_)
        return dists

def compute_ema(
    model: torch.nn.Module,
    ema_model: Union[torch.nn.Module, EMAParameters],
    smoothing: float = 0.99,
) -> None:
    model_context_manager = get_model_context_manager(model)

    with model_context_manager:
        with torch.no_grad():
            # If the ema model is a pytorch module, can just use the state_dict
            if isinstance(ema_model, torch.nn.Module):
                ema_params = ema_model.state_dict()
                for name, param in itertools.chain(model.named_parameters(), model.named_buffers()):
                    if name in ema_params:
                        ema_params[name].copy_(ema_params[name] * smoothing + param.data * (1. - smoothing))
            # Otherwise, the ema model needs to define the named_parameters and named_buffers dictionaries
            # These should contain the parameters and buffers to average.
            elif isinstance(ema_model, EMAParameters):
                ema_parameters = ema_model.named_parameters_dict
                ema_buffers = ema_model.named_buffers_dict
                for name, param in itertools.chain(model.named_parameters(), model.named_buffers()):
                    if name in ema_parameters:
                        ema_parameters[name].copy_(ema_parameters[name] * smoothing + param.data * (1. - smoothing))
                    if name in ema_buffers:
                        ema_buffers[name].copy_(ema_buffers[name] * smoothing + param.data * (1. - smoothing))
            else:
                raise ValueError('ema_model must be a torch.nn.Module or EMAParameters')

def unset(
    setting_names: Annotated[
        list[str], cyclopts.Parameter(help="Setting names to unset")
    ],
    *,
    yes: Annotated[
        bool, cyclopts.Parameter("--yes", alias="-y", help="Skip confirmation")
    ] = False,
) -> None:
    valid_setting_names = _get_valid_setting_names(Settings)
    settings_context = prefect.context.get_settings_context()
    profiles = prefect.settings.load_profiles()
    profile = profiles[settings_context.profile.name]
    parsed: set[Setting] = set()

    for setting_name in setting_names:
        if setting_name not in valid_setting_names:
            exit_with_error(f"Unknown setting name {setting_name!r}.")
        parsed.add(_get_settings_fields(Settings)[setting_name])

    for setting in parsed:
        if setting not in profile.settings:
            exit_with_error(f"{setting.name!r} is not set in profile {profile.name!r}.")

    if not yes and _cli.is_interactive():
        from rich.prompt import Confirm

        if not Confirm.ask(
            f"Are you sure you want to unset the following setting(s): "
            f"{listrepr(setting_names)}?",
            console=_cli.console,
        ):
            exit_with_error("Unset aborted.")

    profiles.update_profile(
        name=profile.name, settings={setting_name: None for setting_name in parsed}
    )

    for setting_name in setting_names:
        _cli.console.print(f"Unset {setting_name!r}.")
        if setting_name in os.environ:
            _cli.console.print(
                f"[yellow]{setting_name!r} is also set by an environment variable. "
                f"Use `unset {setting_name}` to clear it."
            )

    prefect.settings.save_profiles(profiles)
    exit_with_success(f"Updated profile {profile.name!r}.")

def check_stage(current_stage: str, configs: ConfigRecord) -> None:
    # Check the existence of Config.STAGE
    if Key.STAGE not in configs:
        raise KeyError(
            f"The required key '{Key.STAGE}' is missing from the ConfigRecord."
        )

    # Check the value type of the Config.STAGE
    next_stage = configs[Key.STAGE]
    if not isinstance(next_stage, str):
        raise TypeError(
            f"The value for the key '{Key.STAGE}' must be of type {str}, "
            f"but got {type(next_stage)} instead."
        )

    # Check the validity of the next stage
    if next_stage == Stage.SETUP:
        if current_stage != Stage.UNMASK:
            log(WARNING, "Restart from the setup stage")
    # If stage is not "setup",
    # the stage from configs should be the expected next stage
    else:
        stages = Stage.all()
        expected_next_stage = stages[(stages.index(current_stage) + 1) % len(stages)]
        if next_stage != expected_next_stage:
            raise ValueError(
                "Abort secure aggregation: "
                f"expect {expected_next_stage} stage, but receive {next_stage} stage"
            )

def split_array_at_indices(
    x: np.ndarray, split_idx: np.ndarray
) -> List[List[np.ndarray]]:
    if split_idx.ndim != 1:
        raise ValueError("Variable `split_idx` must be a 1-D numpy array.")
    if split_idx.dtype != np.int64:
        raise ValueError("Variable `split_idx` must be of type np.int64.")
    if split_idx[0] != 0:
        raise ValueError("First value of `split_idx` must be 0.")
    if split_idx[-1] >= x.shape[0]:
        raise ValueError(
            """Last value in `split_idx` must be less than
            the number of samples in `x`."""
        )
    if not np.all(split_idx[:-1] <= split_idx[1:]):
        raise ValueError("Items in `split_idx` must be in increasing order.")

    num_splits: int = len(split_idx)
    split_idx = np.append(split_idx, x.shape[0])

    list_samples_split: List[List[np.ndarray]] = [[] for _ in range(num_splits)]
    for j in range(num_splits):
        tmp_x = x[split_idx[j] : split_idx[j + 1]]  # noqa: E203
        for sample in tmp_x:
            list_samples_split[j].append(sample)

    return list_samples_split

def update_alias_docstring(name, obj, lines):
    arr = name.rsplit(".", 1)
    if len(arr) != 2:
        return
    target_mod, target_name = arr

    if target_mod not in tvm_alias_check_map:
        return
    if not hasattr(obj, "__module__"):
        return
    obj_mod = obj.__module__

    for amod in tvm_alias_check_map[target_mod]:
        if not obj_mod.startswith(amod):
            continue

        if hasattr(sys.modules[amod], target_name):
            obj_type = ":py:func" if callable(obj) else ":py:class"
            lines.append(f".. rubric:: Alias of {obj_type}:`{amod}.{target_name}`")

def locate(self, sprite=None, game_frame=None, screen_region=None, use_global_location=True):
        constellation_of_pixel_images = sprite.generate_constellation_of_pixels_images()
        location = None

        frame = game_frame.frame

        if screen_region is not None:
            frame = serpent.cv.extract_region_from_image(frame, screen_region)

        for i in range(len(constellation_of_pixel_images)):
            constellation_of_pixels_item = list(sprite.constellation_of_pixels[i].items())[0]

            query_coordinates = constellation_of_pixels_item[0]
            query_rgb = constellation_of_pixels_item[1]

            rgb_coordinates = Sprite.locate_color(query_rgb, image=frame)

            rgb_coordinates = list(map(lambda yx: (yx[0] - query_coordinates[0], yx[1] - query_coordinates[1]), rgb_coordinates))

            maximum_y = frame.shape[0] - constellation_of_pixel_images[i].shape[0]
            maximum_x = frame.shape[1] - constellation_of_pixel_images[i].shape[1]

            for y, x in rgb_coordinates:
                if y < 0 or x < 0 or y > maximum_y or x > maximum_x:
                    continue

                for yx, rgb in sprite.constellation_of_pixels[i].items():
                    if tuple(frame[y + yx[0], x + yx[1], :]) != rgb:
                        break
                else:
                    location = (
                        y,
                        x,
                        y + constellation_of_pixel_images[i].shape[0],
                        x + constellation_of_pixel_images[i].shape[1]
                    )

        if location is not None and screen_region is not None and use_global_location:
            location = (
                location[0] + screen_region[0],
                location[1] + screen_region[1],
                location[2] + screen_region[0],
                location[3] + screen_region[1]
            )

        return location

def apply_colormap(
    image: Float[Tensor, "*bs channels"],
    colormap_options: ColormapOptions = ColormapOptions(),
    eps: float = 1e-9,
) -> Float[Tensor, "*bs rgb=3"]:

    # default for rgb images
    if image.shape[-1] == 3:
        return image

    # rendering depth outputs
    if image.shape[-1] == 1 and torch.is_floating_point(image):
        output = image
        if colormap_options.normalize:
            output = output - torch.min(output)
            output = output / (torch.max(output) + eps)
        output = (
            output * (colormap_options.colormap_max - colormap_options.colormap_min) + colormap_options.colormap_min
        )
        output = torch.clip(output, 0, 1)
        if colormap_options.invert:
            output = 1 - output
        return apply_float_colormap(output, colormap=colormap_options.colormap)

    # rendering boolean outputs
    if image.dtype == torch.bool:
        return apply_boolean_colormap(image)

    if image.shape[-1] > 3:
        return apply_pca_colormap(image)

    raise NotImplementedError

def predict_proba_one(self, x):
        # If the tree hasn't seen any sample, then it should return
        # the default empty dict

        if not self._is_initialized:
            return {}

        # Find leaf using direct traversal, handling missing features
        current = self._root
        while not current.is_leaf:
            if current.feature in x:
                if x[current.feature] <= current.threshold:
                    current = current.children[0]
                else:
                    current = current.children[1]
            else:
                # Missing feature: follow the most traversed path
                _, current = current.most_common_path()

        if not self.use_aggregation:
            return self._predict(current)

        # Use Cython for the entire upward aggregation walk
        n_classes = len(self._classes)
        scores = predict_proba_upward_c(current, n_classes, self.dirichlet)

        return {self._idx_to_class[i]: scores[i] for i in range(n_classes)}

def get_valid_frames(cap, num_frames, vlen, sample='rand'):
    acc_samples = min(num_frames, vlen)
    intervals = np.linspace(
        start=0, stop=vlen, num=acc_samples + 1).astype(int)
    ranges = []
    for idx, interv in enumerate(intervals[:-1]):
        ranges.append((interv, intervals[idx + 1] - 1))
    if sample == 'rand':
        frame_idxs = [random.choice(range(x[0], x[1])) for x in ranges]
    else:
        frame_idxs = [(x[0] + x[1]) // 2 for x in ranges]

    frames = []
    for index in frame_idxs:
        cap.set(cv2.CAP_PROP_POS_FRAMES, index)
        ret, frame = cap.read()
        if not ret:
            n_tries = 5
            for _ in range(n_tries):
                ret, frame = cap.read()
                if ret:
                    break
        if not ret:
            return None, None

        frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
        frame = torch.from_numpy(frame)
        frame = frame.permute(2, 0, 1)
        frames.append(frame)

    while len(frames) < num_frames:
        frames.append(frames[-1].clone())

    return frames, frame_idxs

def create_graph_schema(self, nodes=None):
        graph_schema = {nt: set() for nt in self.node_types}
        edge_types = set()

        if nodes is None:
            selector = slice(None)
        else:
            node_ilocs = self._nodes.ids.to_iloc(nodes)
            selector = np.isin(self._edges.sources, node_ilocs) & np.isin(
                self._edges.targets, node_ilocs
            )

        for n1, rel, n2 in self._unique_type_triples(selector=selector):
            edge_type_tri = EdgeType(n1, rel, n2)
            edge_types.add(edge_type_tri)
            graph_schema[n1].add(edge_type_tri)

            if not self.is_directed():
                edge_type_tri = EdgeType(n2, rel, n1)
                edge_types.add(edge_type_tri)
                graph_schema[n2].add(edge_type_tri)

        # Create ordered list of edge_types
        edge_types = sorted(edge_types)

        # Create keys for node and edge types
        schema = {
            node_label: sorted(node_data)
            for node_label, node_data in graph_schema.items()
        }

        return GraphSchema(
            self.is_directed(), sorted(self.node_types), edge_types, schema
        )

def dump_dataflow_images(df, index=0, batched=True,
                         number=1000, output_dir=None,
                         scale=1, resize=None, viz=None,
                         flipRGB=False):
    if output_dir:
        mkdir_p(output_dir)
    if viz is not None:
        viz = shape2d(viz)
        vizsize = viz[0] * viz[1]
    if resize is not None:
        resize = tuple(shape2d(resize))
    vizlist = []

    df.reset_state()
    cnt = 0
    while True:
        for dp in df:
            if not batched:
                imgbatch = [dp[index]]
            else:
                imgbatch = dp[index]
            for img in imgbatch:
                cnt += 1
                if cnt == number:
                    return
                if scale != 1:
                    img = img * scale
                if resize is not None:
                    img = cv2.resize(img, resize)
                if flipRGB:
                    img = img[:, :, ::-1]
                if output_dir:
                    fname = os.path.join(output_dir, '{:03d}.jpg'.format(cnt))
                    cv2.imwrite(fname, img)
                if viz is not None:
                    vizlist.append(img)
            if viz is not None and len(vizlist) >= vizsize:
                stack_patches(
                    vizlist[:vizsize],
                    nr_row=viz[0], nr_col=viz[1], viz=True)
                vizlist = vizlist[vizsize:]

def parse_headers(cls, data: Iterable[List[str]]) -> Tuple[List, Iterable]:
        data = iter(data)
        header_rows = []

        # Try to parse a three-line header
        lines = []
        try:
            lines.append(list(next(data)))
            lines.append(list(next(data)))
            lines.append(list(next(data)))
        except StopIteration:
            lines, data = [], chain(lines, data)
        if lines:
            l1, l2, l3 = lines
            # Three-line header if line 2 & 3 match (1st line can be anything)
            if cls.__header_test2(l2) and cls.__header_test3(l3):
                header_rows = [l1, l2, l3]
            else:
                lines, data = [], chain((l1, l2, l3), data)

        # Try to parse a single-line header
        if not header_rows:
            try:
                lines.append(list(next(data)))
            except StopIteration:
                pass
            if lines:
                # Header if none of the values in line 1 parses as a number
                if not all(cls.__is_number(i) for i in lines[0]):
                    header_rows = [lines[0]]
                else:
                    data = chain(lines, data)

        return header_rows, data

def get(self, object_type="all", as_object=False):
        names_dict = self._get()

        if object_type != "all" and object_type not in names_dict:
            raise KeyError(
                f"Invalid object_type '{object_type}'. "
                f"Available keys: {list(names_dict.keys())}"
            )

        items = (
            [item for items in names_dict.values() for item in items]
            if object_type == "all"
            else names_dict[object_type]
        )

        if not as_object:
            return [
                item
                if isinstance(item, str)
                else (item.__name__ if callable(item) else type(item).__name__)
                for item in items
            ]

        # as_object=True path
        if self._cached_objects is None:
            self._cached_objects = {}

        if object_type not in self._cached_objects:
            processed = []
            for item in items:
                if isinstance(item, str):
                    processed.append(craft(item))
                else:
                    processed.append(item)
            self._cached_objects[object_type] = processed

        return self._cached_objects[object_type]

def tf_lite_type_to_numpy(tfl_type: TensorType) -> np.ScalarType:  # noqa C901
    if tfl_type == TensorType.FLOAT32:
        return np.dtype(np.float32)

    elif tfl_type == TensorType.UINT8:
        return np.dtype(np.uint8)

    elif tfl_type == TensorType.INT8:
        return np.dtype(np.int8)

    elif tfl_type == TensorType.UINT16:
        return np.dtype(np.uint16)

    elif tfl_type == TensorType.INT16:
        return np.dtype(np.int16)

    elif tfl_type == TensorType.INT32:
        return np.dtype(np.int32)

    elif tfl_type == TensorType.INT64:
        return np.dtype(np.int64)

    elif tfl_type == TensorType.STRING:
        return np.dtype(np.string_)

    elif tfl_type == TensorType.BOOL:
        return np.dtype(np.bool_)

    elif tfl_type == TensorType.FLOAT16:
        return np.dtype(np.float16)

    elif tfl_type == TensorType.FLOAT64:
        return np.dtype(np.float64)

    elif tfl_type == TensorType.UINT32:
        return np.dtype(np.uint32)

    elif tfl_type == TensorType.UINT64:
        return np.dtype(np.uint64)

    elif tfl_type == TensorType.COMPLEX64:
        return np.dtype(np.complex64)

    elif tfl_type == TensorType.COMPLEX128:
        return np.dtype(np.complex128)

    else:
        logger.e(
            logger.Code.CONVERSION_IMPOSSIBLE,
            f"Cannot convert NeutronIR type '{tfl_type}' to numpy dtype.",
        )

def receive_weights(
        self,
        timeout: float | None = None,
        *,
        weights: Any = None,
        model: Any = None,
        strategy: WeightStrategy | None = None,
    ) -> Any | None:
        if self._store is None or self._rank is None:
            return None

        # Use provided weights buffer or fallback to stored one
        weights_buffer = weights if weights is not None else self._weights_buffer

        # Receive weights via torch.distributed into the buffer
        if self._sync or timeout is None:
            # Blocking receive - no timeout support
            if self._sync:
                weights_buffer.recv(src=0)
            else:
                weights_buffer.irecv(src=0)
        else:
            # Non-blocking receive with timeout support
            futures = weights_buffer.irecv(src=0, return_premature=True)
            if futures:
                start_time = time.monotonic()
                while True:
                    # Check if all futures are complete
                    all_complete = all(f.is_completed() for f in futures)
                    if all_complete:
                        break
                    # Check timeout
                    elapsed = time.monotonic() - start_time
                    if elapsed >= timeout:
                        # Timeout expired before receiving all weights
                        return None
                    # Small sleep to avoid busy-waiting
                    time.sleep(0.001)

        # Apply weights if model and strategy provided
        if model is not None and strategy is not None:
            strategy.apply_weights(model, weights_buffer)

        return weights_buffer

def get_ww_types_from_features(
    features,
    entityset,
    pass_columns=None,
    cutoff_time=None,
):
    if pass_columns is None:
        pass_columns = []
    logical_types = {}
    semantic_tags = {}
    origins = {}

    for feature in features:
        names = feature.get_feature_names()
        for name in names:
            logical_types[name] = feature.column_schema.logical_type
            semantic_tags[name] = feature.column_schema.semantic_tags.copy()
            semantic_tags[name] -= {"index", "time_index"}

            if logical_types[name] is None and "numeric" in semantic_tags[name]:
                logical_types[name] = Double
            if all([f.primitive is None for f in feature.get_dependencies(deep=True)]):
                origins[name] = "base"
            else:
                origins[name] = "engineered"

    if pass_columns:
        cutoff_schema = cutoff_time.ww.schema
        for column in pass_columns:
            logical_types[column] = cutoff_schema.logical_types[column]
            semantic_tags[column] = cutoff_schema.semantic_tags[column]
            origins[column] = "base"

    ww_init = {
        "logical_types": logical_types,
        "semantic_tags": semantic_tags,
        "column_origins": origins,
    }
    return ww_init

def update_weights(
        self, node: TensorDictBase, action_idx: int, reward: float
    ) -> None:
        if not (0 <= reward <= 1):
            warnings.warn(
                f"Reward {reward} is outside the expected [0,1] range for EXP3.",
                UserWarning,
            )

        weights = node.get(self.weights_key)
        action_probs = node.get(self.score_key)
        k = weights.shape[-1]

        if weights.ndim == 1:
            current_weight = weights[action_idx]
            prob_i = action_probs[action_idx]
        elif weights.ndim > 1:
            current_weight = weights[..., action_idx]
            prob_i = action_probs[..., action_idx]
        else:
            raise ValueError(f"Invalid weights dimensions: {weights.ndim}")

        if torch.any(prob_i <= 0):
            prob_i_val = prob_i.item() if prob_i.numel() == 1 else prob_i
            warnings.warn(
                f"Probability p_i(t) for action {action_idx} is {prob_i_val}. "
                "Weight will not be updated for zero probability actions.",
                UserWarning,
            )
            # Don't update weights for zero probability - just return
            return

        reward_tensor = torch.as_tensor(
            reward, device=current_weight.device, dtype=current_weight.dtype
        )
        exponent = (self.gamma / k) * (reward_tensor / prob_i)
        new_weight = current_weight * torch.exp(exponent)

        if weights.ndim == 1:
            weights[action_idx] = new_weight
        else:
            weights[..., action_idx] = new_weight
        node.set(self.weights_key, weights)

def lemmatize_det(
        self, word: str, features: List[str], rule: str, index: List[str]
    ) -> List[str]:

        # Initialize empty lists for the generated lemmas
        possible_lemmas = []
        selected_lemmas = []

        # First, search in rules specific to determiners
        for old, new in self.lookups.get_table("lemma_rules").get("det", []):
            if word == old:
                return [new]
        # If none of the specific rules apply, search in the common rules for
        # determiners and pronouns that follow a unique pattern for
        # lemmatization. If the word is in the list, return the corresponding
        # lemma.
        for old, new in self.lookups.get_table("lemma_rules").get(
            "det_and_pron_fixed", []
        ):
            if word == old:
                return [new]
        # If the word is not in the list of unique determiners and pronouns,
        # apply general rules of lemmatization. Include the original word in the        # list of possible lemmas.
        for old, new in self.lookups.get_table("lemma_rules").get(
            "det_and_pron_general", []
        ):
            possible_lemma = re.sub(old + "$", new, word)
            possible_lemmas.append(possible_lemma)
        possible_lemmas.append(word)

        if len(possible_lemmas) == 1:
            return possible_lemmas
        elif len(possible_lemmas) > 1:
            for lemma in possible_lemmas:
                if lemma in index:
                    selected_lemmas.append(lemma)
            if len(selected_lemmas) >= 1:
                return selected_lemmas
            else:
                return possible_lemmas
        else:
            return []

def batch_fetch_nodes(
        self,
        node_groups: List[Union[str, DedicatedNodeGroup]],
        concurrency: int = 8,
        return_exceptions: bool = False,
    ) -> List[Union[List[Node], Exception]]:
        if not node_groups:
            return []

        max_workers = min(max(1, concurrency), len(node_groups))

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            if not return_exceptions:
                results_no_exc: List[List[Node]] = []
                for nodes in executor.map(self.list_nodes, node_groups):
                    results_no_exc.append(nodes)
                return results_no_exc
            else:
                futures = [executor.submit(self.list_nodes, ng) for ng in node_groups]
                results_mixed: List[Union[List[Node], Exception]] = []
                for fut in futures:
                    try:
                        results_mixed.append(fut.result())
                    except Exception as e:
                        results_mixed.append(e)
                return results_mixed

def import_keras():
    def import_from_keras():
        try:
            import keras  # noqa

            if hasattr(keras.utils, "Sequence"):
                return (keras.utils.Sequence,), True
            else:
                return (keras.utils.PyDataset,), True
        except ImportError:
            return tuple(), False

    def import_from_tensforflow():
        try:
            from tensorflow import keras

            if hasattr(keras.utils, "Sequence"):
                return (keras.utils.Sequence,), True
            else:
                return (keras.utils.PyDataset,), True
        except ImportError:
            return tuple(), False

    ParentClassKeras, has_keras_k = import_from_keras()
    ParentClassTensorflow, has_keras_tf = import_from_tensforflow()
    has_keras = has_keras_k or has_keras_tf
    if has_keras:
        if has_keras_k:
            ParentClass = ParentClassKeras
        else:
            ParentClass = ParentClassTensorflow
    else:
        ParentClass = (object,)
    return ParentClass, has_keras

def read_train_file(zip_filename, filename, pipe):
    sentiment_data = []
    with zipfile.ZipFile(zip_filename) as zin:
        with zin.open(filename) as fin:
            for line_idx, line in enumerate(fin):
                if isinstance(line, bytes):
                    line = line.decode("utf-8")
                pieces = line.split(maxsplit=1)
                if len(pieces) < 2:
                    continue
                pieces = pieces[1].rsplit(maxsplit=1)
                if len(pieces) < 2:
                    continue
                text, label = pieces
                try:
                    label = convert_label(label)
                except ValueError:
                    raise ValueError("Unexpected train label %s at line %d\n%s" % (label, line_idx, line))
                sentiment_data.append(SentimentDatum(label, text))

    print("Read %d texts from %s - %s" % (len(sentiment_data), zip_filename, filename))
    sentiment_data = tokenize(sentiment_data, pipe)
    return sentiment_data

def from_corpus(corpus, id2word=None):
        result = Dictionary()
        max_id = -1
        for docno, document in enumerate(corpus):
            if docno % 10000 == 0:
                logger.info("adding document #%i to %s", docno, result)
            result.num_docs += 1
            result.num_nnz += len(document)
            for wordid, word_freq in document:
                max_id = max(wordid, max_id)
                result.num_pos += word_freq
                result.dfs[wordid] = result.dfs.get(wordid, 0) + 1

        if id2word is None:
            # make sure length(result) == get_max_id(corpus) + 1
            result.token2id = {str(i): i for i in range(max_id + 1)}
        else:
            # id=>word mapping given: simply copy it
            result.token2id = {utils.to_unicode(token): idx for idx, token in id2word.items()}
        for idx in result.token2id.values():
            # make sure all token ids have a valid `dfs` entry
            result.dfs[idx] = result.dfs.get(idx, 0)

        logger.info(
            "built %s from %i documents (total %i corpus positions)",
            result, result.num_docs, result.num_pos
        )
        return result

def to_annotated_string(
    variable_data: dict[Name, VariableData],
    names: tuple[Name, ...],
    allowed_refs: set[Name],
) -> dict[str, str]:
    response: dict[str, str] = {}
    if not variable_data:
        return response
    for name in names:
        if variable_data.get(name):
            variable = variable_data[name]
            annotation = variable.annotation_data
            if annotation:
                if annotation.refs - allowed_refs:
                    # replace unescaped quotes with escaped quotes
                    safe_repr = re.sub(r'(?<!\\)"', r'\\"', annotation.repr)
                    response[name] = f'"{safe_repr}"'
                else:
                    response[name] = annotation.repr
    return response

def calc_pad_dims_1D(X_shape, l_out, kernel_width, stride, dilation=0, causal=False):
    if not isinstance(X_shape, tuple):
        raise ValueError("`X_shape` must be of type tuple")

    if not isinstance(l_out, int):
        raise ValueError("`l_out` must be of type int")

    if not isinstance(kernel_width, int):
        raise ValueError("`kernel_width` must be of type int")

    if not isinstance(stride, int):
        raise ValueError("`stride` must be of type int")

    d = dilation
    fw = kernel_width
    n_ex, l_in, in_ch = X_shape

    # update effective filter shape based on dilation factor
    _fw = fw * (d + 1) - d
    total_pad = int((stride * (l_out - 1) + _fw - l_in))

    if not causal:
        pw = total_pad // 2
        l_out1 = int(1 + (l_in + 2 * pw - _fw) / stride)

        # add asymmetric padding pixels to right / bottom
        pw1, pw2 = pw, pw
        if l_out1 == l_out - 1:
            pw1, pw2 = pw, pw + 1
        elif l_out1 != l_out:
            raise AssertionError

    if causal:
        # if this is a causal convolution, only pad the left side of the
        # sequence
        pw1, pw2 = total_pad, 0
        l_out1 = int(1 + (l_in + total_pad - _fw) / stride)
        assert l_out1 == l_out

    if any(np.array([pw1, pw2]) < 0):
        raise ValueError("Padding cannot be less than 0. Got: {}".format((pw1, pw2)))
    return (pw1, pw2)

def resolve_value_placeholders(value: Any, *, variables: Mapping[str, object] | None = None) -> Any:
    if isinstance(value, str):
        return resolve_string_placeholders(value, variables=variables)
    if isinstance(value, list):
        return [resolve_value_placeholders(item, variables=variables) for item in value]
    if isinstance(value, tuple):
        return tuple(resolve_value_placeholders(item, variables=variables) for item in value)
    if isinstance(value, dict):
        return {key: resolve_value_placeholders(item, variables=variables) for key, item in value.items()}
    return value

def apply_filters(entries: Iterable[str], sample: str) -> str:
        result = sample or ""
        for raw_entry in entries:
            if raw_entry is None:
                continue
            entry = str(raw_entry)
            if not entry:
                continue

            if entry.startswith("s/") and entry.count("/") >= 2:
                try:
                    _, pattern, replacement, *_ = entry.split("/", 3)
                except ValueError:
                    pattern = ""
                    replacement = ""
                if pattern:
                    try:
                        result = re.sub(pattern, replacement, result)
                    except re.error as exc:  # pragma: no cover - invalid regex
                        logger.debug("Failed to apply sed-like replacement '%s': %s", entry, exc)

            if entry and result:
                result = result.replace(entry, "")

            try:
                regex = re.compile(entry)
            except re.error:
                continue
            try:
                result = regex.sub("", result)
            except re.error:
                logger.debug("Regex substitution failed for '%s'", entry)
        return result

def pauli_to_binary(pauli_word, n_qubits=None, wire_map=None, check_is_pauli_word=True):
    wire_map = wire_map or {w: i for i, w in enumerate(pauli_word.wires)}

    if check_is_pauli_word and not is_pauli_word(pauli_word):
        raise TypeError(f"Expected a Pauli word Operator instance, instead got {pauli_word}.")

    pw = next(iter(pauli_word.pauli_rep))

    n_qubits_min = max(wire_map.values()) + 1
    if n_qubits is None:
        n_qubits = n_qubits_min
    elif n_qubits < n_qubits_min:
        raise ValueError(
            f"n_qubits must support the highest mapped wire index {n_qubits_min},"
            f" instead got n_qubits={n_qubits}."
        )

    binary_pauli = np.zeros(2 * n_qubits)

    for wire, pauli_type in pw.items():
        if pauli_type == "X":
            binary_pauli[wire_map[wire]] = 1
        elif pauli_type == "Y":
            binary_pauli[wire_map[wire]] = 1
            binary_pauli[n_qubits + wire_map[wire]] = 1
        elif pauli_type == "Z":
            binary_pauli[n_qubits + wire_map[wire]] = 1
    return binary_pauli

def object_to_numpy(data, expected_dtype=None, expected_ndim=None) -> t.Union[np.ndarray, Number, str]:
    if data is None:
        return None
    if is_torch_object(data):
        result = data.cpu().detach().numpy()
    elif is_tensorflow_object(data):
        result = data.cpu().numpy()
    elif isinstance(data, np.ndarray):
        result = data
    elif isinstance(data, (Number, str)):
        return data
    else:
        result = np.array(data)

    if expected_dtype is not None:
        result = result.astype(expected_dtype)
    if len(result.shape) == 0:
        result = result.item()
    elif len(result.shape) == 1 and result.shape[0] > 0 and expected_ndim == 2:
        result = result.reshape(1, result.shape[0])
    return result

def find_usable_cuda_devices(num_devices: int = -1) -> list[int]:
    if num_devices == 0:
        return []
    visible_devices = _get_all_visible_cuda_devices()
    if not visible_devices:
        raise ValueError(
            f"You requested to find {num_devices} devices but there are no visible CUDA devices on this machine."
        )
    if num_devices > len(visible_devices):
        raise ValueError(
            f"You requested to find {num_devices} devices but this machine only has {len(visible_devices)} GPUs."
        )

    available_devices = []
    unavailable_devices = []

    for gpu_idx in visible_devices:
        try:
            torch.tensor(0, device=torch.device("cuda", gpu_idx))
        except RuntimeError:
            unavailable_devices.append(gpu_idx)
            continue

        available_devices.append(gpu_idx)
        if len(available_devices) == num_devices:
            # exit early if we found the right number of GPUs
            break

    if num_devices != -1 and len(available_devices) != num_devices:
        raise RuntimeError(
            f"You requested to find {num_devices} devices but only {len(available_devices)} are currently available."
            f" The devices {unavailable_devices} are occupied by other processes and can't be used at the moment."
        )
    return available_devices

def fix_close_shift_shift(gold_transition, pred_transition, gold_sequence, gold_index, root_labels, ambiguous, late):
    if not isinstance(gold_transition, CloseConstituent):
        return None
    if not isinstance(pred_transition, Shift):
        return None
    if len(gold_sequence) < gold_index + 2:
        return None
    start_index = gold_index + 1
    start_index = advance_past_unaries(gold_sequence, start_index)
    if len(gold_sequence) < start_index + 2:
        return None
    if not isinstance(gold_sequence[start_index], Shift):
        return None

    end_index = find_in_order_constituent_end(gold_sequence, start_index)
    if end_index is None:
        return None
    # if this *isn't* a close, we don't allow it in the unambiguous case
    # that case seems to be ambiguous...
    #   stuff_1 close stuff_2 stuff_3
    # if you would normally start building stuff_3,
    # it is not clear if you want to close at the end of
    # stuff_2 or build stuff_3 instead.
    if ambiguous and isinstance(gold_sequence[end_index], CloseConstituent):
        return None
    elif not ambiguous and isinstance(gold_sequence[end_index], Shift):
        return None

    # close at the end of the brackets, rather than once the first bracket is finished
    if late:
        end_index = advance_past_constituents(gold_sequence, start_index)

    return gold_sequence[:gold_index] + gold_sequence[start_index:end_index] + [CloseConstituent()] + gold_sequence[end_index:]

def forward(self, inputs):
        has_batch_dim = len(inputs.shape) > 1

        # in case the input has more than one batch dimension
        if has_batch_dim:
            batch_dims = inputs.shape[:-1]
            inputs = torch.reshape(inputs, (-1, inputs.shape[-1]))

        # calculate the forward pass as usual
        results = self._evaluate_qnode(inputs)

        if isinstance(results, tuple):
            if has_batch_dim:
                results = [torch.reshape(r, (*batch_dims, *r.shape[1:])) for r in results]
            return torch.stack(results, dim=0)

        # reshape to the correct number of batch dims
        if has_batch_dim:
            results = torch.reshape(results, (*batch_dims, *results.shape[1:]))

        return results

def standard_model_file_name(args, model_type, **kwargs):
    embedding = embedding_name(args)

    finetune = ""
    transformer_lr = ""
    if args.get("bert_finetune", False):
        finetune = "finetuned"
        if "bert_learning_rate" in args:
            transformer_lr = "{}".format(args["bert_learning_rate"])

    use_peft = "nopeft"
    if args.get("bert_finetune", False) and args.get("use_peft", False):
        use_peft = "peft"

    bert_finetuning = ""
    if args.get("bert_finetune", False):
        if args.get("use_peft", False):
            bert_finetuning = "peft"
        else:
            bert_finetuning = "ft"

    seed = args.get('seed', None)
    if seed is None:
        seed = ""
    else:
        seed = str(seed)

    format_args = {
        "batch_size":      args['batch_size'],
        "bert_finetuning": bert_finetuning,
        "embedding":       embedding,
        "finetune":        finetune,
        "peft":            use_peft,
        "seed":            seed,
        "shorthand":       args['shorthand'],
        "transformer_lr":  transformer_lr,
    }
    format_args.update(**kwargs)
    model_file = args['save_name'].format(**format_args)
    model_file = re.sub("_+", "_", model_file)

    model_dir = os.path.split(model_file)[0]

    if not os.path.exists(os.path.join(args['save_dir'], model_file)) and os.path.exists(model_file):
        return model_file
    if model_dir.startswith(args['save_dir']):
        return model_file
    return os.path.join(args['save_dir'], model_file)

def post_process_keypoint_matching(
        self,
        outputs: "EfficientLoFTRKeypointMatchingOutput",
        target_sizes: TensorType | list[tuple],
        threshold: float = 0.0,
    ) -> list[dict[str, torch.Tensor]]:
        if outputs.matches.shape[0] != len(target_sizes):
            raise ValueError("Make sure that you pass in as many target sizes as the batch dimension of the mask")
        if not all(len(target_size) == 2 for target_size in target_sizes):
            raise ValueError("Each element of target_sizes must contain the size (h, w) of each image of the batch")

        if isinstance(target_sizes, list):
            image_pair_sizes = torch.tensor(target_sizes, device=outputs.matches.device)
        else:
            if target_sizes.shape[1] != 2 or target_sizes.shape[2] != 2:
                raise ValueError(
                    "Each element of target_sizes must contain the size (h, w) of each image of the batch"
                )
            image_pair_sizes = target_sizes

        keypoints = outputs.keypoints.clone()
        keypoints = keypoints * image_pair_sizes.flip(-1).reshape(-1, 2, 1, 2)
        keypoints = keypoints.to(torch.int32)

        results = []
        for keypoints_pair, matches, scores in zip(keypoints, outputs.matches, outputs.matching_scores):
            # Filter out matches with low scores
            valid_matches = torch.logical_and(scores > threshold, matches > -1)

            matched_keypoints0 = keypoints_pair[0][valid_matches[0]]
            matched_keypoints1 = keypoints_pair[1][valid_matches[1]]
            matching_scores = scores[0][valid_matches[0]]

            results.append(
                {
                    "keypoints0": matched_keypoints0,
                    "keypoints1": matched_keypoints1,
                    "matching_scores": matching_scores,
                }
            )

        return results

def to_val(self, s):
        if s is None:
            return ValueUnknown

        if isinstance(s, Integral):
            return s
        if isinstance(s, Real):
            return s if isnan(s) else floor(s + 0.25)
        if s in self.unknown_str:
            return ValueUnknown
        if not isinstance(s, str):
            raise TypeError('Cannot convert {} to value of "{}"'.format(
                type(s).__name__, self.name))
        if s not in self._value_index:
            raise ValueError(f"Value {s} does not exist")
        return self._value_index[s]

def parse_sm_config() -> dict[str, Any]:
    conf = {}

    if os.path.exists(sm_files.SM_PARAM_CONFIG):
        conf["sagemaker_training_job_name"] = os.getenv("TRAINING_JOB_NAME")

        # Hyperparameter searches quote configs...
        with open(sm_files.SM_PARAM_CONFIG) as fid:
            for key, val in json.load(fid).items():
                cast = val.strip('"')
                if re.match(r"^-?[\d]+$", cast):
                    cast = int(cast)
                elif re.match(r"^-?[.\d]+$", cast):
                    cast = float(cast)
                conf[key] = cast

    if env := os.environ.get("SM_TRAINING_ENV"):
        try:
            conf.update(json.loads(env))
        except json.JSONDecodeError:
            warnings.warn(
                "Failed to parse SM_TRAINING_ENV not valid JSON string",
                stacklevel=2,
            )

    return conf

def start_services(
    *,
    background: Annotated[
        bool,
        cyclopts.Parameter(
            "--background", alias="-b", help="Run the services in the background."
        ),
    ] = False,
):
    from prefect.cli._server_utils import (
        SERVICES_PID_FILE,
        _cleanup_pid_file,
        _is_process_running,
        _read_pid_file,
        _run_all_services,
        _write_pid_file,
    )
    from prefect.server.services.base import Service

    SERVICES_PID_FILE.parent.mkdir(parents=True, exist_ok=True)

    if SERVICES_PID_FILE.exists():
        pid = _read_pid_file(SERVICES_PID_FILE)
        if pid is not None and _is_process_running(pid):
            _cli.console.print(
                "\n[yellow]Services are already running in the background.[/]"
                "\n[blue]Use[/] [yellow]`prefect server services stop`[/] [blue]to stop them.[/]"
            )
            raise SystemExit(1)
        else:
            _cleanup_pid_file(SERVICES_PID_FILE)

    if not Service.enabled_services():
        _cli.console.print("[red]No services are enabled![/]")
        raise SystemExit(1)

    if not background:
        _cli.console.print("\n[blue]Starting services... Press CTRL+C to stop[/]\n")
        try:
            asyncio.run(_run_all_services())
        except KeyboardInterrupt:
            pass
        _cli.console.print("\n[green]All services stopped.[/]")
        return

    process = subprocess.Popen(
        ["prefect", "server", "services", "manager"],
        env=os.environ.copy(),
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=(os.name != "nt"),
        creationflags=subprocess.CREATE_NEW_PROCESS_GROUP if os.name == "nt" else 0,
    )

    if process.poll() is not None:
        _cli.console.print("[red]Failed to start services in the background![/]")
        raise SystemExit(1)

    _write_pid_file(SERVICES_PID_FILE, process.pid)
    _cli.console.print(
        "\n[green]Services are running in the background.[/]"
        "\n[blue]Use[/] [yellow]`prefect server services stop`[/] [blue]to stop them.[/]"
    )

def base_model_to_dict(
        self,
        pydantic_type: type[BaseModel],
        output_str: bool = False,
        *args: Any,
        **kwargs: Any,
    ) -> Union[dict[str, Any], str]:
        if pydantic_type is None:
            raise ToolValidationError(
                "Pydantic type parameter cannot be None"
            )

        if not issubclass(pydantic_type, BaseModel):
            raise ToolValidationError(
                "pydantic_type must be a subclass of BaseModel"
            )

        try:
            self._log_if_verbose(
                "info",
                f"Converting Pydantic model {pydantic_type.__name__} to schema",
            )

            # Get the base function schema
            base_result = base_model_to_openai_function(
                pydantic_type, output_str=output_str, *args, **kwargs
            )

            # If output_str is True, return the string directly
            if output_str and isinstance(base_result, str):
                return base_result

            # Extract the function definition from the functions array
            if (
                "functions" in base_result
                and len(base_result["functions"]) > 0
            ):
                function_def = base_result["functions"][0]

                # Return in proper OpenAI function calling format
                result = {
                    "type": "function",
                    "function": function_def,
                }
            else:
                raise FunctionSchemaError(
                    "Failed to extract function definition from base_model_to_openai_function result"
                )

            self._log_if_verbose(
                "info",
                f"Successfully converted model {pydantic_type.__name__}",
            )
            return result

        except Exception as e:
            self._log_if_verbose(
                "error",
                f"Failed to convert model {pydantic_type.__name__}: {e}",
            )
            raise FunctionSchemaError(
                f"Failed to convert Pydantic model to schema: {e}"
            ) from e

def to_config(self, ignore_default_config=None):
        cfg = Config()
        args_dict = addict.Dict()

        if ignore_default_config is None:
            ignore_default_config = self.use_model_config

        for f in fields(self):
            cfg_node = f.metadata.get('cfg_node')
            cfg_setter = f.metadata.get('cfg_setter') or (lambda x: x)
            if cfg_node is not None:
                if f.name in self.manual_args or not ignore_default_config:
                    if isinstance(cfg_node, str):
                        cfg_node = [cfg_node]
                    for _node in cfg_node:
                        cfg.merge_from_dict(
                            {_node: cfg_setter(getattr(self, f.name))})
            else:
                args_dict[f.name] = getattr(self, f.name)

        cfg.merge_from_dict(self._unknown_args)
        return cfg, args_dict

def sample_function(
    user_train, usernum, itemnum, batch_size, maxlen, result_queue, seed
):

    def sample():

        user = np.random.randint(1, usernum + 1)
        while len(user_train[user]) <= 1:
            user = np.random.randint(1, usernum + 1)

        seq = np.zeros([maxlen], dtype=np.int32)
        pos = np.zeros([maxlen], dtype=np.int32)
        neg = np.zeros([maxlen], dtype=np.int32)
        nxt = user_train[user][-1]
        idx = maxlen - 1

        ts = set(user_train[user])
        for i in reversed(user_train[user][:-1]):
            seq[idx] = i
            pos[idx] = nxt
            if nxt != 0:
                neg[idx] = random_neq(1, itemnum + 1, ts)
            nxt = i
            idx -= 1
            if idx == -1:
                break

        return (user, seq, pos, neg)

    np.random.seed(seed)
    while True:
        one_batch = []
        for i in range(batch_size):
            one_batch.append(sample())

        result_queue.put(zip(*one_batch))

def filter_repo_objects(
        items: Iterable[T],
        *,
        allow_patterns: Optional[Union[List[str], str]] = None,
        ignore_patterns: Optional[Union[List[str], str]] = None,
        key: Optional[Callable[[T], str]] = None,
    ) -> Generator[T, None, None]:

        allow_patterns = allow_patterns if allow_patterns else None
        ignore_patterns = ignore_patterns if ignore_patterns else None

        if isinstance(allow_patterns, str):
            allow_patterns = [allow_patterns]

        if isinstance(ignore_patterns, str):
            ignore_patterns = [ignore_patterns]

        if allow_patterns is not None:
            allow_patterns = [
                RepoUtils._add_wildcard_to_directories(p)
                for p in allow_patterns
            ]
        if ignore_patterns is not None:
            ignore_patterns = [
                RepoUtils._add_wildcard_to_directories(p)
                for p in ignore_patterns
            ]

        if key is None:

            def _identity(item: T) -> str:
                if isinstance(item, str):
                    return item
                if isinstance(item, Path):
                    return str(item)
                raise ValueError(
                    f'Please provide `key` argument in `filter_repo_objects`: `{item}` is not a string.'
                )

            key = _identity  # Items must be `str` or `Path`, otherwise raise ValueError

        for item in items:
            path = key(item)

            # Skip if there's an allowlist and path doesn't match any
            if allow_patterns is not None and not any(
                    fnmatch(path, r) for r in allow_patterns):
                continue

            # Skip if there's a denylist and path matches any
            if ignore_patterns is not None and any(
                    fnmatch(path, r) for r in ignore_patterns):
                continue

            yield item

def check_constraints(self, node: torch.fx.Node, ep: ExportedProgram) -> bool:
        if not self.check_common_constraints(node, ep):
            return False

        new_shape = node.args[1]

        # Check for symbolic dims. They aren't lowerable to XNNPACK currently.
        symbolic_dim_indices = [
            i for i, d in enumerate(new_shape) if not isinstance(d, int)
        ]
        if not all(isinstance(n, int) for n in new_shape):
            why(
                node,
                reason=f"Symbolic reshape is not supported. Output shape is {new_shape} and dims at {symbolic_dim_indices} are symbolic.",
            )
            return False

        dynamic_dim_indices = [i for i, d in enumerate(new_shape) if d == -1]
        if len(dynamic_dim_indices) > 1:
            why(
                node,
                reason=f"Only a single inferred dimension is supported. Output shape is {new_shape} and dims {dynamic_dim_indices} are inferred.",
            )
            return False

        return True

def delete_annotations_in_range(self, start_idx, end_idx):
        deleted_count = 0

        for i in range(start_idx - 1, end_idx):
            if i >= len(self.image_file_list):
                break

            image_file = self.image_file_list[i]
            label_dir = os.path.dirname(image_file)
            if self.parent.output_dir:
                label_dir = self.parent.output_dir

            filename = os.path.basename(image_file)
            label_file = os.path.join(
                label_dir, os.path.splitext(filename)[0] + ".json"
            )

            if os.path.exists(label_file):
                try:
                    os.remove(label_file)
                    deleted_count += 1

                    item = self.parent.file_list_widget.item(i)
                    if item:
                        item.setCheckState(Qt.CheckState.Unchecked)
                except Exception as e:
                    logger.error(f"Error deleting {label_file}: {e}")

        logger.info(
            f"Deleted {deleted_count} annotation files in range {start_idx}-{end_idx}"
        )

        template = self.tr("Deleted %s annotation files")
        popup = Popup(
            template % deleted_count,
            self.parent,
            icon=new_icon_path("copy-green", "svg"),
        )
        popup.show_popup(self.parent, position="center")

def parse_kvs_argument_callback(
    ctx: Context,
    params: Parameter,
    value: tuple[str, ...],  # pylint: disable=unused-argument
) -> t.List[tuple[str, str]]:
    key_vals: t.List[tuple[str, str]] = []
    for key_val in value:
        key, val = key_val.split("=", maxsplit=1)
        if not key or not val:
            raise click.BadParameter(f"Invalid key-value pair: {key_val}")
        if val.startswith("@"):
            filename = resolve_user_filepath(val[1:], ctx=None, secure=False)
            if not os.path.exists(filename) or not os.path.isfile(filename):
                raise click.BadParameter(f"Invalid file path: {filename}")
            # read the file content
            with open(filename, "r") as f:
                val = f.read()
        key_vals.append((key, val))
    return key_vals

def compute_twe_return_path(
    cost_matrix: np.ndarray, bounding_matrix: np.ndarray
) -> list[tuple]:
    x_size, y_size = cost_matrix.shape
    for i in range(x_size):
        for j in range(y_size):
            if not np.isfinite(bounding_matrix[i, j]):
                cost_matrix[i, j] = np.inf

    i = cost_matrix.shape[0] - 1
    j = cost_matrix.shape[1] - 1
    alignment = []
    while True:
        alignment.append((i - 1, j - 1))

        if alignment[-1] == (0, 0):
            break

        arr = np.array(
            [
                cost_matrix[i - 1, j - 1],
                cost_matrix[i - 1, j],
                cost_matrix[i, j - 1],
            ]
        )
        min_index = np.argmin(arr)

        if min_index == 0:
            i = i - 1
            j = j - 1
        elif min_index == 1:
            i = i - 1
        else:
            j = j - 1

    return alignment[::-1]

def param_init(module, init="ortho"):
    for m in module.modules():
        if isinstance(m, nn.Conv2d):  # or isinstance(m, nn.Linear):
            # print('Update init of ', m)
            if init == "he":
                n = m.kernel_size[0] * m.kernel_size[1] * m.out_channels
                m.weight.data.normal_(0, math.sqrt(2.0 / n))
            elif init == "ortho":
                nn.init.orthogonal_(m.weight)
        if isinstance(m, nn.Linear):
            nn.init.normal_(m.weight, mean=0, std=0.0001)
            # n = m.weight.size(1)
            # m.weight.data.normal_(0, math.sqrt(2. / n))
        elif isinstance(m, nn.BatchNorm2d):
            # print('Update init of ', m)
            m.weight.data.fill_(1)
            m.bias.data.zero_()

def shutdown(
        self, timeout: float | None = None, shutdown_ray: bool = False
    ) -> None:
        self._stop_event.set()
        if self._collection_thread is not None and self._collection_thread.is_alive():
            self._collection_thread.join(
                timeout=timeout if timeout is not None else 5.0
            )
        self.stop_remote_collectors()

        # Clean up weight sync schemes AFTER workers have exited
        if getattr(self, "_weight_sync_schemes", None) is not None:
            torchrl_logger.debug("shutting down weight sync schemes")
            for scheme in self._weight_sync_schemes.values():
                try:
                    scheme.shutdown()
                except Exception as e:
                    torchrl_logger.warning(
                        f"Error shutting down weight sync scheme: {e}"
                    )
            self._weight_sync_schemes = None

        if shutdown_ray:
            ray.shutdown()

