def fully_qualified_table_name(self) -> str:
        if not self.table:
            return ""

        # self.table may already contain the database and schema
        parts = self.table.split(".")
        if len(parts) == 3:
            database, schema, table = parts
        elif len(parts) == 2:
            database = self.database
            schema, table = parts
        elif len(parts) == 1:
            database = self.database
            schema = self.schema
            table = parts[0]
        else:
            raise ValueError(
                f"Invalid table name: {self.table} - can't determine database and schema"
            )

        if database and schema:
            return f"{database}.{schema}.{table}"
        elif schema:
            return f"{schema}.{table}"
        else:
            return table

def adjacency(graph, directed=False, reversed=False, stochastic=False, heuristic=None):
    # Caching a heuristic from a method won't work.
    # Bound method objects are transient,
    # i.e., id(object.method) returns a new value each time.
    if graph._adjacency is not None and \
       graph._adjacency[1:] == (directed, reversed, stochastic, heuristic and heuristic.__code__):
        return graph._adjacency[0]
    map = {}
    for n in graph.nodes:
        map[n.id] = {}
    for e in graph.edges:
        id1, id2 = not reversed and (e.node1.id, e.node2.id) or (e.node2.id, e.node1.id)
        map[id1][id2] = 1.0 - 0.5 * e.weight
        if heuristic:
            map[id1][id2] += heuristic(id1, id2)
        if not directed:
            map[id2][id1] = map[id1][id2]
    if stochastic:
        for id1 in map:
            n = sum(map[id1].values())
            for id2 in map[id1]:
                map[id1][id2] /= n
    # Cache the adjacency map: this makes dijkstra_shortest_path() 2x faster in repeated use.
    graph._adjacency = (map, directed, reversed, stochastic, heuristic and heuristic.__code__)
    return map

def mitigate_depolarizing_noise(K, num_wires, method, use_entries=None):
    dim = 2**num_wires

    if method == "single":
        if use_entries is None:
            use_entries = (0,)

        if K[use_entries[0], use_entries[0]] <= (1 / dim):
            raise ValueError(
                "The single noise mitigation method cannot be applied "
                "as the single diagonal element specified is too small."
            )

        diagonal_element = K[use_entries[0], use_entries[0]]
        noise_rate = (1 - diagonal_element) * dim / (dim - 1)
        mitigated_matrix = (K - noise_rate / dim) / (1 - noise_rate)

    elif method == "average":
        if use_entries is None:
            diagonal_elements = np.diag(K)
        else:
            diagonal_elements = np.diag(K)[np.array(use_entries)]

        if np.mean(diagonal_elements) <= 1 / dim:
            raise ValueError(
                "The average noise mitigation method cannot be applied "
                "as the average of the used diagonal terms is too small."
            )

        noise_rates = (1 - diagonal_elements) * dim / (dim - 1)
        mean_noise_rate = np.mean(noise_rates)
        mitigated_matrix = (K - mean_noise_rate / dim) / (1 - mean_noise_rate)

    elif method == "split_channel":
        if np.any(np.diag(K) <= 1 / dim):
            raise ValueError(
                "The split channel noise mitigation method cannot be applied "
                "to the input matrix as its diagonal terms are too small."
            )

        eff_noise_rates = np.clip((1 - np.diag(K)) * dim / (dim - 1), 0.0, 1.0)
        noise_rates = 1 - np.sqrt(1 - eff_noise_rates)
        inverse_noise = (
            -np.outer(noise_rates, noise_rates)
            + noise_rates.reshape((1, len(K)))
            + noise_rates.reshape((len(K), 1))
        )

        mitigated_matrix = (K - inverse_noise / dim) / (1 - inverse_noise)
    else:
        raise ValueError(
            "Incorrect noise depolarization mitigation method specified. "
            "Accepted strategies are: 'single', 'average' and 'split_channel'."
        )

    return mitigated_matrix

def get_fields_for_tab(self, tab_name: str, context: Optional[Dict[str, Any]] = None) -> List[Any]:
        cache_key = f"tab_{tab_name}"
        if context:
            context_key = tuple(sorted(context.items()))
            cache_key = f"{cache_key}_{context_key}"

        # Check if we have valid cached data
        if cache_key in self._fields_cache and self._is_cache_valid(cache_key):
            logger.debug(f"Returning cached fields for tab '{tab_name}'")
            return self._fields_cache[cache_key]

        registry = self._get_registry()
        if registry is None:
            logger.warning(f"Field registry not available, returning empty list for tab '{tab_name}'")
            logger.warning(f"Import error: {self._import_error}")
            return []

        try:
            try:
                if context:
                    fields = registry.get_fields_for_tab(tab_name, context)
                else:
                    fields = registry.get_fields_for_tab(tab_name)
            except TypeError:
                # Registry implementation may not accept context parameter
                fields = registry.get_fields_for_tab(tab_name)
            self._fields_cache[cache_key] = fields
            self._cache_timestamps[cache_key] = time.time()
            logger.debug(f"Cached {len(fields)} fields for tab '{tab_name}'")
            return fields
        except Exception as e:
            logger.error(f"Error getting fields for tab '{tab_name}': {e}", exc_info=True)
            return []

def input_dtypes_are_supported(node: torch.fx.Node) -> bool:
    if not is_tensor_node(node):
        return True

    # Iterate over all the args of the node
    for arg_node in node.args:
        # The arg could be a single node, or a list (e.g., first arg of cat)
        if isinstance(arg_node, torch.fx.Node):
            if not output_dtypes_are_supported(arg_node):
                return False
        elif isinstance(arg_node, (list, tuple)):
            if not all(output_dtypes_are_supported(x) for x in arg_node):
                return False

    return True

def css_calc(x, left: float, right: float, align: str, color: str | list | tuple):
        if pd.isna(x):
            return base_css

        if isinstance(color, (list, tuple)):
            color = color[0] if x < 0 else color[1]
        assert isinstance(color, str)  # mypy redefinition

        x = left if x < left else x
        x = right if x > right else x  # trim data if outside of the window

        start: float = 0
        end: float = 1

        if align == "left":
            # all proportions are measured from the left side between left and right
            end = (x - left) / (right - left)

        elif align == "right":
            # all proportions are measured from the right side between left and right
            start = (x - left) / (right - left)

        else:
            z_frac: float = 0.5  # location of zero based on the left-right range
            if align == "zero":
                # all proportions are measured from the center at zero
                limit: float = max(abs(left), abs(right))
                left, right = -limit, limit
            elif align == "mid":
                # bars drawn from zero either leftwards or rightwards with center at mid
                mid: float = (left + right) / 2
                z_frac = (
                    -mid / (right - left) + 0.5 if mid < 0 else -left / (right - left)
                )

            if x < 0:
                start, end = (x - left) / (right - left), z_frac
            else:
                start, end = z_frac, (x - left) / (right - left)

        ret = css_bar(start * width, end * width, color)
        if height < 1 and "background: linear-gradient(" in ret:
            return (
                ret + f" no-repeat center; background-size: 100% {height * 100:.1f}%;"
            )
        else:
            return ret

def posterior_replay(model, posterior_samples, *args, **kwargs):
    posterior_samples = posterior_samples.copy()
    num_samples = kwargs.pop("num_samples", None)
    assert (
        posterior_samples or num_samples
    ), "`num_samples` must be provided if `posterior_samples` is empty."
    if num_samples is None:
        num_samples = list(posterior_samples.values())[0].shape[0]

    return_samples = defaultdict(list)
    for i in range(num_samples):
        conditioned_nodes = {k: v[i] for k, v in posterior_samples.items()}
        collapsed_trace = poutine.trace(
            poutine.condition(collapse_conjugate(model), conditioned_nodes)
        ).get_trace(*args, **kwargs)
        trace = poutine.trace(uncollapse_conjugate(model, collapsed_trace)).get_trace(
            *args, **kwargs
        )
        for name, site in trace.iter_stochastic_nodes():
            if not site_is_subsample(site):
                return_samples[name].append(site["value"])

    return {k: torch.stack(v) for k, v in return_samples.items()}

def perform_keep_shape_video(f: Callable[..., torch.Tensor]) -> Callable[..., torch.Tensor]:
    @wraps(f)
    def _wrapper(input: torch.Tensor, *args: Any, **kwargs: Any) -> torch.Tensor:
        if not isinstance(input, torch.Tensor):
            raise TypeError(f"Input input type is not a torch.Tensor. Got {type(input)}")

        if input.numel() == 0:
            raise ValueError("Invalid input tensor, it is empty.")

        input_shape = input.shape
        input = _to_bcdhw(input)  # view input as (B, C, D, H, W)
        output = f(input, *args, **kwargs)
        if len(input_shape) == 4:
            output = output[0]

        if len(input_shape) == 3:
            output = output[0, 0]

        if len(input_shape) > 5:
            output = output.view(*(input_shape[:-4] + output.shape[-4:]))

        return output

    return _wrapper

def is_bool_indexer(key: Any) -> bool:
    if isinstance(
        key,
        (ABCSeries, np.ndarray, ABCIndex, ABCExtensionArray, ABCNumpyExtensionArray),
    ) and not isinstance(key, ABCMultiIndex):
        if key.dtype == np.object_:
            key_array = np.asarray(key)

            if not lib.is_bool_array(key_array):
                na_msg = "Cannot mask with non-boolean array containing NA / NaN values"
                if lib.is_bool_array(key_array, skipna=True):
                    # Don't raise on e.g. ["A", "B", np.nan], see
                    #  test_loc_getitem_list_of_labels_categoricalindex_with_na
                    raise ValueError(na_msg)
                return False
            return True
        elif is_bool_dtype(key.dtype):
            return True
    elif isinstance(key, list):
        # check if np.array(key).dtype would be bool
        if len(key) > 0:
            if type(key) is not list:
                # GH#42461 cython will raise TypeError if we pass a subclass
                key = list(key)
            return lib.is_bool_list(key)

    return False

def clip_tensors_by_global_norm(input_tensors, max_norm=1.0, global_norm=None, mpu=None, eps=1e-6, use_graph=False):
    if global_norm is None:
        global_norm = get_global_norm_of_tensors(input_tensors, mpu=mpu, use_graph=use_graph)
    clip_coef = max_norm / (global_norm + eps)
    if clip_coef < 1:
        if use_graph:

            def clip_tensors(_tensor_list, _clip_coef_tensor):
                for t in _tensor_list:
                    t.detach().mul_(_clip_coef_tensor)

            if 'clip_coef_tensor' not in graph_cache:
                # Alloc memory
                graph_cache['clip_coef_tensor'] = torch.tensor(clip_coef,
                                                               dtype=torch.float32).to(get_accelerator().device_name())
            clip_coef_tensor = graph_cache['clip_coef_tensor']
            clip_coef_tensor.copy_(torch.tensor(clip_coef, dtype=torch.float32))
            graph_process(False, clip_tensors, input_tensors, clip_coef_tensor)

        else:
            for t in input_tensors:
                t.detach().mul_(clip_coef)
    return global_norm

def compute_bleu(reference_corpus,
                 translation_corpus,
                 max_order=4,
                 use_bp=True):
  reference_length = 0
  translation_length = 0
  bp = 1.0
  geo_mean = 0

  matches_by_order = [0] * max_order
  possible_matches_by_order = [0] * max_order
  precisions = []

  for (references, translations) in zip(reference_corpus, translation_corpus):
    reference_length += len(references)
    translation_length += len(translations)
    ref_ngram_counts = _get_ngrams(references, max_order)
    translation_ngram_counts = _get_ngrams(translations, max_order)

    overlap = dict((ngram,
                    min(count, translation_ngram_counts[ngram]))
                   for ngram, count in ref_ngram_counts.items())

    for ngram in overlap:
      matches_by_order[len(ngram) - 1] += overlap[ngram]
    for ngram in translation_ngram_counts:
      possible_matches_by_order[len(ngram)-1] += translation_ngram_counts[ngram]
  precisions = [0] * max_order
  smooth = 1.0
  for i in range(0, max_order):
    if possible_matches_by_order[i] > 0:
      precisions[i] = matches_by_order[i] / possible_matches_by_order[i]
      if matches_by_order[i] > 0:
        precisions[i] = matches_by_order[i] / possible_matches_by_order[i]
      else:
        smooth *= 2
        precisions[i] = 1.0 / (smooth * possible_matches_by_order[i])
    else:
      precisions[i] = 0.0

  if max(precisions) > 0:
    p_log_sum = sum(math.log(p) for p in precisions if p)
    geo_mean = math.exp(p_log_sum/max_order)

  if use_bp:
    if not reference_length:
      bp = 1.0
    else:
      ratio = translation_length / reference_length
      if ratio <= 0.0:
        bp = 0.0
      elif ratio >= 1.0:
        bp = 1.0
      else:
        bp = math.exp(1 - 1. / ratio)
  bleu = geo_mean * bp
  return np.float32(bleu)

def get_split(args):
    splits = []
    if args.split.find(',') != -1:
        splits = [float(s) for s in args.split.split(',')]
    elif args.split.find('/') != -1:
        splits = [float(s) for s in args.split.split('/')]
    else:
        splits = [float(args.split)]
    split_total = sum(splits)
    if split_total < 1.:
        splits.append(1 - split_total)
    while len(splits) < 3:
        splits.append(0.)
    splits = splits[:3]
    if args.valid_data is not None:
        splits[1] = 0.
    if args.test_data is not None:
        splits[2] = 0.
    final_sum = sum(splits)
    return [s / final_sum for s in splits]

def update_upstream_blocks(
        self,
        upstream_blocks: List[Any],
        variables: Dict = None,
        **kwargs,
    ) -> None:
        upstream_blocks_previous = self.upstream_blocks
        super().update_upstream_blocks(upstream_blocks)

        if BlockLanguage.SQL != self.language or self.pipeline is None:
            return

        upstream_blocks_previous_by_uuid = {b.uuid: b for b in upstream_blocks_previous}
        upstream_blocks_by_uuid = {b.uuid: b for b in self.upstream_blocks}

        removed_upstream_blocks = [
            b for b in upstream_blocks_previous if b.uuid not in upstream_blocks_by_uuid]
        new_upstream_blocks = [
            b for b in self.upstream_blocks if b.uuid not in upstream_blocks_previous_by_uuid]

        if any(not isinstance(b, self.__class__)
               for b in (removed_upstream_blocks + new_upstream_blocks)):
            self.__class__.update_sources(
                self.pipeline.blocks_by_uuid, variables=self.pipeline.variables)

def load_preset_dict_from_location(location: str) -> dict:
    p = urlparse(location)
    fragment = p.fragment or None

    # Strip fragment for retrieval
    p_no_frag = p._replace(fragment="")
    location_no_frag = urlunparse(p_no_frag)

    if p.scheme in ("", "file"):
        path = location_no_frag if p.scheme == "" else p_no_frag.path
        if not os.path.exists(path):
            raise FileNotFoundError(path)
        with open(path, "rb") as f:
            data = f.read()
    elif p.scheme == "s3":
        data = _read_bytes_from_s3(location_no_frag)
    elif p.scheme in ("http", "https"):
        data = _read_bytes_from_http(location_no_frag)
    else:
        raise ValueError(f"Unsupported preset URI scheme {p.scheme!r} in {location!r}")

    import yaml

    loaded = yaml.safe_load(data)
    if loaded is None:
        loaded = {}
    if not isinstance(loaded, dict):
        raise TypeError(f"Preset YAML must be a dict at top-level, got {type(loaded)} from {location!r}")

    if fragment is not None:
        if fragment not in loaded:
            raise KeyError(
                f"Preset fragment {fragment!r} not found in {location_no_frag!r}. "
                f"Available keys: {list(loaded.keys())}"
            )
        selected = loaded[fragment] or {}
        if not isinstance(selected, dict):
            raise TypeError(f"Preset {fragment!r} in {location_no_frag!r} must be a dict, got {type(selected)}")
        return selected

    return loaded

def filter_english_datasets():
    english_datasets = []

    response = requests.get("https://huggingface.co/api/datasets?full=true")
    tags = response.json()
    while "next" in response.links:
        # Handle pagination of `/api/datasets` endpoint
        response = requests.get(response.links["next"]["url"])
        tags += response.json()

    for dataset in tags:
        dataset_name = dataset["id"]

        is_community_dataset = "/" in dataset_name
        if is_community_dataset:
            user = dataset_name.split("/")[0]
            if user in INCLUDED_USERS:
                english_datasets.append(dataset_name)
            continue

        if "cardData" not in dataset:
            continue
        metadata = dataset["cardData"]

        if "language" not in metadata:
            continue
        languages = metadata["language"]

        if "en" in languages or "en-US" in languages:
            english_datasets.append(dataset_name)

    return sorted(english_datasets)

def validate_fields_in_config(
    config: dict[str, Any],
) -> tuple[bool, list[str], list[str]]:
    errors = []
    warnings = []

    if "project" not in config:
        errors.append("Missing [project] section")
    else:
        if "name" not in config["project"]:
            errors.append('Property "name" missing in [project]')
        if "version" not in config["project"]:
            errors.append('Property "version" missing in [project]')
        if "description" not in config["project"]:
            warnings.append('Recommended property "description" missing in [project]')
        if "license" not in config["project"]:
            warnings.append('Recommended property "license" missing in [project]')

    if (
        "tool" not in config
        or "flwr" not in config["tool"]
        or "app" not in config["tool"]["flwr"]
    ):
        errors.append("Missing [tool.flwr.app] section")
    else:
        if "publisher" not in config["tool"]["flwr"]["app"]:
            errors.append('Property "publisher" missing in [tool.flwr.app]')
        _validate_pattern_list(config["tool"]["flwr"]["app"], FAB_INCLUDE_KEY, errors)
        _validate_pattern_list(config["tool"]["flwr"]["app"], FAB_EXCLUDE_KEY, errors)
        if "config" in config["tool"]["flwr"]["app"]:
            _validate_run_config(config["tool"]["flwr"]["app"]["config"], errors)
        if "components" not in config["tool"]["flwr"]["app"]:
            errors.append("Missing [tool.flwr.app.components] section")
        else:
            if "serverapp" not in config["tool"]["flwr"]["app"]["components"]:
                errors.append(
                    'Property "serverapp" missing in [tool.flwr.app.components]'
                )
            if "clientapp" not in config["tool"]["flwr"]["app"]["components"]:
                errors.append(
                    'Property "clientapp" missing in [tool.flwr.app.components]'
                )

    return len(errors) == 0, errors, warnings

def check_source(
    source: str | int | Path | list | tuple | np.ndarray | Image.Image | torch.Tensor,
) -> tuple[Any, bool, bool, bool, bool, bool]:
    webcam, screenshot, from_img, in_memory, tensor = False, False, False, False, False
    if isinstance(source, (str, int, Path)):  # int for local usb camera
        source = str(source)
        source_lower = source.lower()
        is_url = source_lower.startswith(("https://", "http://", "rtsp://", "rtmp://", "tcp://"))
        is_file = (urlsplit(source_lower).path if is_url else source_lower).rpartition(".")[-1] in (
            IMG_FORMATS | VID_FORMATS
        )
        webcam = source.isnumeric() or source.endswith(".streams") or (is_url and not is_file)
        screenshot = source_lower == "screen"
        if is_url and is_file:
            source = check_file(source)  # download
    elif isinstance(source, LOADERS):
        in_memory = True
    elif isinstance(source, (list, tuple)):
        source = autocast_list(source)  # convert all list elements to PIL or np arrays
        from_img = True
    elif isinstance(source, (Image.Image, np.ndarray)):
        from_img = True
    elif isinstance(source, torch.Tensor):
        tensor = True
    else:
        raise TypeError("Unsupported image type. For supported types see https://docs.ultralytics.com/modes/predict")

    return source, webcam, screenshot, from_img, in_memory, tensor

def values_equal(old: object, new: object) -> bool:
            # Components are a special case. Component attributes are dirty iff
            # the component isn't reconciled, i.e. it is a new component
            if isinstance(new, rio.Component):
                if old is new:
                    return True

                try:
                    new_before_reconciliation = (
                        reconciled_components_new_to_old[new]
                    )
                except KeyError:
                    return False
                else:
                    return old is new_before_reconciliation

            # Lists are compared element-wise
            if isinstance(new, list):
                if not isinstance(old, list):
                    return False

                old = t.cast(list[object], old)
                new = t.cast(list[object], new)

                if len(old) != len(new):
                    return False

                for old_item, new_item in zip(old, new):
                    if not values_equal(old_item, new_item):
                        return False

                return True

            # Otherwise attempt to compare the values
            try:
                return bool(old == new)
            except Exception:
                return old is new

def get_lexer_by_name(_alias, **options):
    if not _alias:
        raise ClassNotFound('no lexer for alias %r found' % _alias)

    # lookup builtin lexers
    for module_name, name, aliases, _, _ in itervalues(LEXERS):
        if _alias.lower() in aliases:
            if name not in _lexer_cache:
                _load_lexers(module_name)
            return _lexer_cache[name](**options)
    # continue with lexers from setuptools entrypoints
    for cls in find_plugin_lexers():
        if _alias.lower() in cls.aliases:
            return cls(**options)
    raise ClassNotFound('no lexer for alias %r found' % _alias)

def read_tex_files(file_path:str, demacro:bool=False)->str:
    tex = ''
    try:
        with tempfile.TemporaryDirectory() as tempdir:
            try:
                tf = tarfile.open(file_path, 'r')
                tf.extractall(tempdir)
                tf.close()
                texfiles = [os.path.abspath(x) for x in glob.glob(os.path.join(tempdir, '**', '*.tex'), recursive=True)]
            except tarfile.ReadError as e:
                texfiles = [file_path]  # [os.path.join(tempdir, file_path+'.tex')]
            if demacro:
                ret = subprocess.run(['de-macro', *texfiles], cwd=tempdir, capture_output=True)
                if ret.returncode == 0:
                    texfiles = glob.glob(os.path.join(tempdir, '**', '*-clean.tex'), recursive=True)
            for texfile in texfiles:
                try:
                    ct = open(texfile, 'r', encoding='utf-8').read()
                    tex += ct
                except UnicodeDecodeError as e:
                    logging.debug(e)
                    pass
    except Exception as e:
        logging.debug('Could not read %s: %s' % (file_path, str(e)))
        raise e
    tex = pydemacro(tex)
    return tex

def get_thumbnails(
        self,
        image_paths: List[Path],
        max_size: int = DEFAULT_THUMBNAIL_SIZE,
        limit: int = 50,
        offset: int = 0,
    ) -> List[ThumbnailInfo]:
        # Clamp max_size
        max_size = min(max(max_size, 64), self.MAX_THUMBNAIL_SIZE)

        thumbnails = []
        # Apply pagination
        paths_slice = image_paths[offset : offset + limit]

        for path in paths_slice:
            if isinstance(path, str):
                path = Path(path)

            try:
                self._validate_path(path)
            except ValueError:
                continue

            if not path.exists() or not self._is_image_file(path):
                continue

            try:
                thumbnail_data = self._generate_thumbnail(path, max_size)
                if thumbnail_data:
                    thumbnails.append(
                        ThumbnailInfo(
                            path=str(path),
                            filename=path.name,
                            thumbnail=thumbnail_data,
                        )
                    )
            except Exception as e:
                logger.warning(f"Failed to generate thumbnail for {path}: {e}")
                continue

        return thumbnails

def data_section(self, tokens, labeled=None):
        # Check if the tokens are labeled or unlabeled.  If unlabeled,
        # then use 'None'
        if labeled is None:
            labeled = tokens and isinstance(tokens[0], (tuple, list))
        if not labeled:
            tokens = [(tok, None) for tok in tokens]

        # Data section
        s = "\n@DATA\n"
        for tok, label in tokens:
            for fname, ftype in self._features:
                s += "%s," % self._fmt_arff_val(tok.get(fname))
            s += "%s\n" % self._fmt_arff_val(label)

        return s

def check_all_models_are_tested():
    modules = get_model_modules()
    test_files = get_model_test_files()
    failures = []
    for module in modules:
        # Matches a module to its test file.
        test_file = [file for file in test_files if f"test_{module.__name__.split('.')[-1]}.py" in file]
        if len(test_file) == 0:
            failures.append(f"{module.__name__} does not have its corresponding test file {test_file}.")
        elif len(test_file) > 1:
            failures.append(f"{module.__name__} has several test files: {test_file}.")
        else:
            test_file = test_file[0]
            new_failures = check_models_are_tested(module, test_file)
            if new_failures is not None:
                failures += new_failures
    if len(failures) > 0:
        raise Exception(f"There were {len(failures)} failures:\n" + "\n".join(failures))

def apply_empty_result(self):
        assert callable(self.func)

        # we are not asked to reduce or infer reduction
        # so just return a copy of the existing object
        if self.result_type not in ["reduce", None]:
            return self.obj.copy()

        # we may need to infer
        should_reduce = self.result_type == "reduce"

        from pandas import Series

        if not should_reduce:
            try:
                if self.axis == 0:
                    r = self.func(
                        Series([], dtype=np.float64), *self.args, **self.kwargs
                    )
                else:
                    r = self.func(
                        Series(index=self.columns, dtype=np.float64),
                        *self.args,
                        **self.kwargs,
                    )
            except Exception:
                pass
            else:
                should_reduce = not isinstance(r, Series)

        if should_reduce:
            if len(self.agg_axis):
                r = self.func(Series([], dtype=np.float64), *self.args, **self.kwargs)
            else:
                r = np.nan

            return self.obj._constructor_sliced(r, index=self.agg_axis)
        else:
            return self.obj.copy()

def get_transport_config(self) -> Dict[str, Any]:
        config: Dict[str, Any] = {"type": self.transport_type}

        if self.transport_type == "http":
            if not self.transport_url:
                raise ValueError("transport_url is required for HTTP transport")
            config["url"] = self.transport_url
            config["endpoint"] = self.transport_endpoint
            if self.api_key:
                config["auth"] = {
                    "type": "api_key",
                    "apiKey": self.api_key,
                }
        elif self.transport_type == "file":
            config["log_file_path"] = self.additional_config.get(
                "log_file_path", "openlineage_events.json"
            )
        elif self.transport_type == "kafka":
            config["bootstrap_servers"] = self.additional_config.get(
                "bootstrap_servers"
            )
            config["topic"] = self.additional_config.get("topic", "openlineage.events")

        # Merge additional config
        config.update(self.additional_config)

        return config

def find_constants(blocks: List[Block]) -> Dict[Var, List[Var]]:
        unique2duplicates: Dict[Var, List[Var]] = {}

        # instead of brute-force C_N^2 comparison, use a hash map to be O(N)
        constant_dict: Dict[Tuple[str, types.type, Tuple[int], str], List[Var]] = {}
        for block in blocks:
            for op in list(block.operations):
                if op.op_type != "const":
                    continue

                constant_var = op.outputs[0]
                if isinstance(constant_var, ListVar):
                    continue

                if not const_deduplication.should_be_deduplicated(constant_var.val):
                    continue

                shape = constant_var.shape
                dtype = constant_var.dtype
                value = constant_var.val

                hash = hashlib.sha1(
                    np.ascontiguousarray(value.reshape(-1)[: const_deduplication.LENGTH_OF_HASHKEY])
                ).hexdigest()
                if hasattr(op, "weight_key"):
                    key = (op.weight_key, dtype, shape, hash)
                else:
                    key = (dtype, shape, hash)

                if key not in constant_dict:
                    constant_dict[key] = [constant_var]
                    unique2duplicates[constant_var] = []
                else:
                    hash_collisions = constant_dict[key]

                    existing_constant_var = None
                    for var in hash_collisions:
                        if np.allclose(
                            value,
                            var.val,
                            rtol=0.0,
                            atol=const_deduplication.DTYPE2ATOL.get(dtype, 1e-12),
                        ):
                            existing_constant_var = var
                            break

                    if existing_constant_var is None:
                        hash_collisions.append(constant_var)
                        unique2duplicates[constant_var] = []
                    else:
                        unique2duplicates[existing_constant_var].append(constant_var)

        return unique2duplicates

def complete_value(exe_context, return_type, field_asts, info, result):
    # If field type is NonNull, complete for inner type, and throw field error if result is null.

    if is_thenable(result):
        return Promise.resolve(result).then(
            lambda resolved: complete_value(
                exe_context,
                return_type,
                field_asts,
                info,
                resolved
            ),
            lambda error: Promise.rejected(GraphQLLocatedError(field_asts, original_error=error))
        )

    # print return_type, type(result)
    if isinstance(result, Exception):
        raise GraphQLLocatedError(field_asts, original_error=result)

    if isinstance(return_type, GraphQLNonNull):
        return complete_nonnull_value(exe_context, return_type, field_asts, info, result)

    # If result is null-like, return null.
    if result is None:
        return None

    # If field type is List, complete each item in the list with the inner type
    if isinstance(return_type, GraphQLList):
        return complete_list_value(exe_context, return_type, field_asts, info, result)

    # If field type is Scalar or Enum, serialize to a valid value, returning null if coercion is not possible.
    if isinstance(return_type, (GraphQLScalarType, GraphQLEnumType)):
        return complete_leaf_value(return_type, result)

    if isinstance(return_type, (GraphQLInterfaceType, GraphQLUnionType)):
        return complete_abstract_value(exe_context, return_type, field_asts, info, result)

    if isinstance(return_type, GraphQLObjectType):
        return complete_object_value(exe_context, return_type, field_asts, info, result)

    assert False, u'Cannot complete value of unexpected type "{}".'.format(return_type)

def post_init(self):
        if self.bits not in [2, 3, 4, 8]:
            raise ValueError(f"Only support quantization to [2,3,4,8] bits but found {self.bits}")
        if self.group_size != -1 and self.group_size <= 0:
            raise ValueError("group_size must be greater than 0 or equal to -1")
        if not (0 < self.damp_percent < 1):
            raise ValueError("damp_percent must between 0 and 1.")
        if self.dataset is not None:
            if isinstance(self.dataset, str):
                if self.dataset not in ["wikitext2", "c4", "c4-new"]:
                    raise ValueError(
                        f"""You have entered a string value for dataset. You can only choose between
                        ['wikitext2','c4','c4-new'], but we found {self.dataset}"""
                    )
            elif not isinstance(self.dataset, list):
                raise ValueError(
                    f"""dataset needs to be either a list of string or a value in
                    ['wikitext2','c4','c4-new'], but we found {self.dataset}"""
                )

        # act_group_order is only applicable when `desc_act = False`
        if self.desc_act and self.act_group_aware:
            self.act_group_aware = False
            logger.warning("`act_group_aware` has been auto-disabled as it is not compatible with `desc_act = True`.")

        # make sure backend default stays consistent with gptqmodel expectations
        if self.backend is None:
            self.backend = "auto"
        if self.modules_in_block_to_quantize is not None:
            optimum_version = version.parse(importlib.metadata.version("optimum"))
            if optimum_version < version.parse("1.15.0"):
                raise ValueError(
                    "You current version of `optimum` does not support `modules_in_block_to_quantize` quantization argument, please upgrade `optimum` package to a version superior than 1.15.0 ."
                )

def extract_lines_before_tables(lines:List[str]):
    out = []

    before = None
    in_table = False
    for l in lines:
        if l.startswith("|") and not in_table:
            if before is not None:
                out.append(before)
            in_table = True
        elif in_table and not l.startswith("|"):
            in_table = False
            before = None
            if l.strip() != "":
                before = l.strip()
        elif l.strip() != "":
            before = l.strip()

    return out

def serializer(extension_mapping=None, *, fallback=False, defaults=None, unpack=False):
    def _serializer(fn):
        extension_mapping_final = _build_extension_mapping_final(
            extension_mapping, defaults, fn, _DEFAULTS, "serializer"
        )

        try:
            serializer_fallback = _EXTERNAL[fallback]
        except KeyError:
            error = True
        else:
            error = False

        if error:
            raise ValueError(
                f"Invalid fallback argument {fallback!r} "
                f"in function {fn.__name__!r}. Must be one of "
                "True, 'joblib', or 'cloudpickle'"
            )

        if serializer_fallback is None and fallback in {"cloudpickle", "joblib"}:
            raise ModuleNotFoundError(
                f"Error serializing with function {fn.__name__!r}. "
                f"{fallback} is not installed"
            )

        n_params = len(signature(fn).parameters)
        if n_params != 2:
            raise TypeError(
                f"Expected serializer {fn.__name__!r} "
                f"to take 2 arguments, but it takes {n_params!r}"
            )

        @wraps(fn)
        def wrapper(obj, product):
            if isinstance(product, MetaProduct):
                _validate_obj(obj, product)

                for key, value in obj.items():
                    _serialize_product(
                        value,
                        product[key],
                        extension_mapping_final,
                        fallback,
                        serializer_fallback,
                        fn,
                        unpack,
                    )
            else:
                _serialize_product(
                    obj,
                    product,
                    extension_mapping_final,
                    fallback,
                    serializer_fallback,
                    fn,
                    unpack,
                )

        return wrapper

    return _serializer

def delete_session(self, session_id: str, **kwargs: Any) -> None:
        session_prefix = self._get_session_path(session_id)
        try:
            paginator = self.client.get_paginator("list_objects_v2")
            pages = paginator.paginate(Bucket=self.bucket, Prefix=session_prefix)

            objects_to_delete = []
            for page in pages:
                if "Contents" in page:
                    objects_to_delete.extend([{"Key": obj["Key"]} for obj in page["Contents"]])

            if not objects_to_delete:
                raise SessionException(f"Session {session_id} does not exist")

            # Delete objects in batches
            for i in range(0, len(objects_to_delete), 1000):
                batch = objects_to_delete[i : i + 1000]
                self.client.delete_objects(Bucket=self.bucket, Delete={"Objects": batch})

        except ClientError as e:
            raise SessionException(f"S3 error deleting session {session_id}: {e}") from e

def create_mask_for_prediction_frequency(prediction_frequency, ds, forecast_lag):
    masks = []
    for count, (key, value) in enumerate(prediction_frequency.items()):
        if count > 0 and forecast_lag > 1:
            target_time = value + 1
        else:
            target_time = value + forecast_lag
        if key == "daily-hour":
            target_time = target_time % 24
            mask = ds.dt.hour == target_time
        elif key == "weekly-day":
            target_time = target_time % 7
            mask = ds.dt.dayofweek == target_time
        elif key == "monthly-day":
            num_days = ds.dt.daysinmonth
            target_time = target_time % num_days
            mask = (ds.dt.day == target_time).reset_index(drop=True)
        elif key == "yearly-month":
            target_time = target_time % 12 if target_time > 12 else target_time
            target_time = 1 if target_time == 0 else target_time
            mask = ds.dt.month == target_time
        elif key == "hourly-minute":
            target_time = target_time % 60
            mask = ds.dt.minute == target_time
        else:
            raise ValueError(f"prediction_frequency {key} not supported")
        masks.append(mask)
    mask = np.ones((len(ds),), dtype=bool)
    for m in masks:
        mask = mask & m
    return mask

def extend(self, *args, **kwargs):
        if len(args) > 1:
            raise TypeError("extend() takes at most 1 positional "
                            "arguments ({} given)".format(len(args)))
        other = args[0] if len(args) >= 1 else ()

        if isinstance(other, HTTPHeaderDict):
            for key, val in other.iteritems():
                self.add(key, val)
        elif isinstance(other, Mapping):
            for key in other:
                self.add(key, other[key])
        elif hasattr(other, "keys"):
            for key in other.keys():
                self.add(key, other[key])
        else:
            for key, value in other:
                self.add(key, value)

        for key, value in kwargs.items():
            self.add(key, value)

async def add_user_model(entry: UserModelEntry) -> JSONResponse:
        # Validate provider exists
        if entry.provider_type == "builtin":
            if entry.provider_id not in ModelProviderName.__members__:
                raise HTTPException(
                    status_code=400, detail=f"Invalid provider: {entry.provider_id}"
                )
            # Check if provider is configured
            provider_warning = provider_warnings.get(
                ModelProviderName(entry.provider_id)
            )
            if provider_warning:
                for key in provider_warning.required_config_keys:
                    if Config.shared().get_value(key) is None:
                        raise HTTPException(
                            status_code=400,
                            detail=f"Provider {entry.provider_id} is not configured. Please set up API keys first.",
                        )
        else:
            providers = Config.shared().openai_compatible_providers or []
            if not any(p.get("name") == entry.provider_id for p in providers):
                raise HTTPException(
                    status_code=400,
                    detail=f"Custom provider not found: {entry.provider_id}",
                )

        # Add to registry
        registry = Config.shared().user_model_registry or []

        # Check for exact duplicate (all identifying fields must match)
        if any(
            e.get("provider_id") == entry.provider_id
            and e.get("model_id") == entry.model_id
            and e.get("name") == entry.name
            and e.get("overrides") == (entry.overrides if entry.overrides else None)
            for e in registry
        ):
            raise HTTPException(status_code=400, detail="Model already exists")

        registry.append(entry.model_dump(exclude_none=True))
        Config.shared().user_model_registry = registry

        return JSONResponse(status_code=200, content={"message": "Model added"})

async def check_all_stale_credentials(
    days: int = Query(90, ge=1, le=365, description="Credentials older than this many days"),
    admin: User = Depends(require_permission("admin.users")),
) -> Dict[str, Any]:
    from datetime import datetime, timedelta, timezone

    store = _get_store()

    # Get all users
    users = await store.list_users(include_inactive=False)
    cutoff = datetime.now(timezone.utc) - timedelta(days=days)

    users_with_stale = []
    total_stale = 0

    for user in users:
        credentials = await store.list_provider_credentials(user.id)
        stale_count = 0

        for cred in credentials:
            updated_at = cred.get("updated_at")
            if updated_at:
                try:
                    updated = datetime.fromisoformat(updated_at.replace("Z", "+00:00"))
                    if updated < cutoff:
                        stale_count += 1
                except (ValueError, TypeError):
                    pass

        if stale_count > 0:
            users_with_stale.append(
                {
                    "user_id": user.id,
                    "username": user.username,
                    "stale_count": stale_count,
                }
            )
            total_stale += stale_count

    return {
        "threshold_days": days,
        "total_stale": total_stale,
        "users_with_stale": users_with_stale,
    }

def add_parallel_chain(
        self,
        sources: List[Union[Node, Agent, str]],
        targets: List[Union[Node, Agent, str]],
        **kwargs: Any,
    ) -> List[Edge]:
        if self.verbose:
            logger.info(
                f"Creating parallel chain: {len(sources)} sources -> {len(targets)} targets"
            )

        created_edges = []

        try:
            for source in sources:
                for target in targets:
                    edge = Edge.from_nodes(source, target, **kwargs)

                    # Validate nodes exist
                    if edge.source not in self.nodes:
                        error_msg = f"Source node '{edge.source}' does not exist in GraphWorkflow"
                        logger.error(error_msg)
                        raise ValueError(error_msg)

                    if edge.target not in self.nodes:
                        error_msg = f"Target node '{edge.target}' does not exist in GraphWorkflow"
                        logger.error(error_msg)
                        raise ValueError(error_msg)

                    self.edges.append(edge)
                    self.graph_backend.add_edge(
                        edge.source,
                        edge.target,
                        **(edge.metadata or {}),
                    )
                    created_edges.append(edge)

                    if self.verbose:
                        logger.debug(
                            f"Added parallel edge: {edge.source} -> {edge.target}"
                        )

            self._invalidate_compilation()

            if self.verbose:
                logger.success(
                    f"Successfully created parallel chain with {len(created_edges)} edges"
                )

            return created_edges

        except Exception as e:
            logger.exception(
                f"Error in GraphWorkflow.add_parallel_chain: {e}"
            )
            raise e

def remove_dup_initializers(onnx_file_path):
    model_file_folder = os.path.dirname(onnx_file_path)
    model_file_name = os.path.basename(onnx_file_path)

    model = onnx.load(os.path.join(model_file_folder, model_file_name))

    inits = [i for i in model.graph.initializer]

    dup_set = set()
    dup_map = {}
    ind_to_replace = []

    total_reduced_size = 0

    for i in range(len(inits)):
        if i in dup_set:
            continue

        for j in range(i + 1, len(inits)):
            if j in dup_set:
                continue
            if _is_equal_tensor_proto(inits[i], inits[j]):
                dup_set.add(i)
                dup_set.add(j)

                dtype = inits[j].data_type
                mem_size = numpy.prod(inits[j].dims)
                if dtype == 1:
                    mem_size *= 4
                elif dtype == 6:
                    mem_size *= 4
                elif dtype == 7 or dtype == 11:
                    mem_size *= 8
                else:
                    print("unexpected data type: ", dtype)
                total_reduced_size += mem_size

                name_i = inits[i].name
                name_j = inits[j].name

                if name_i in dup_map:
                    dup_map[name_i].append(name_j)
                else:
                    dup_map[name_i] = [name_j]
                ind_to_replace.append((j, i))

    print("total reduced size: ", total_reduced_size / 1024 / 1024 / 1024, "GB")

    ind_to_replace = sorted(ind_to_replace)
    _remove_dup_initializers_from_model(model, model, ind_to_replace)

    optimized_model_file_name = "optimized_" + model_file_name
    new_model = os.path.join(model_file_folder, optimized_model_file_name)
    onnx.save(model, new_model)

    return new_model

def is_multilabel(y):
    xp, is_array_api_compliant = get_namespace(y)
    if hasattr(y, "__array__") or isinstance(y, Sequence) or is_array_api_compliant:
        # DeprecationWarning will be replaced by ValueError, see NEP 34
        # https://numpy.org/neps/nep-0034-infer-dtype-is-object.html
        check_y_kwargs = dict(
            accept_sparse=True,
            allow_nd=True,
            ensure_all_finite=False,
            ensure_2d=False,
            ensure_min_samples=0,
            ensure_min_features=0,
        )
        with warnings.catch_warnings():
            warnings.simplefilter("error", VisibleDeprecationWarning)
            try:
                y = check_array(y, dtype=None, **check_y_kwargs)
            except (VisibleDeprecationWarning, ValueError) as e:
                if str(e).startswith("Complex data not supported"):
                    raise

                # dtype=object should be provided explicitly for ragged arrays,
                # see NEP 34
                y = check_array(y, dtype=object, **check_y_kwargs)

    if not (hasattr(y, "shape") and y.ndim == 2 and y.shape[1] > 1):
        return False

    if issparse(y):
        if y.format in ("dok", "lil"):
            y = y.tocsr()
        labels = xp.unique_values(y.data)
        return len(y.data) == 0 or (
            (labels.size == 1 or ((labels.size == 2) and (0 in labels)))
            and (y.dtype.kind in "biu" or _is_integral_float(labels))  # bool, int, uint
        )
    else:
        labels = cached_unique(y, xp=xp)

        return labels.shape[0] < 3 and (
            xp.isdtype(y.dtype, ("bool", "signed integer", "unsigned integer"))
            or _is_integral_float(labels)
        )

def remove_ops(self, ops_to_remove: List[Operation]):
        self.validate()

        # Dedup ops because each op can only be deleted once.
        ops_to_remove_set = set(ops_to_remove)
        ops_to_remove = list(ops_to_remove_set)

        for op in ops_to_remove:
            for i, v in enumerate(op.outputs):
                # Check that the output Var isn't block's output
                if v in self._outputs:
                    raise ValueError(
                        f"cannot delete op {op.name} with output {i}: {v.name} that's block {self.name}'s output."
                    )

            for b in op.blocks:
                b.set_outputs([])
                b.remove_ops(b.operations)

            self.operations.remove(op)

            op.enclosing_block = None

            for v in op.get_flattened_inputs():
                v.remove_child_op(op)

            # Remove InternalVar from self._internal_vars
            for v in op.internal_inputs.values():
                self._internal_vars.remove(v)

        # In the end, we check no ops depend on removed op's outputs
        for op in ops_to_remove:
            for i, v in enumerate(op.outputs):
                if len(v.child_ops) > 0:
                    child_op_names = [s.name for s in v.child_ops]
                    raise ValueError(
                        f"Cannot delete op '{op.name}' with active output at id {i}: '{v.name}' used by ops {child_op_names}."
                    )

def parse_description_with_bboxes_from_text_and_spans(
        self,
        text: str,
        image_size: tuple[int, int],
        allow_empty_phrase: bool = False,
    ) -> list[dict[str, Any]]:
        text = text.replace("<s>", "").replace("</s>", "").replace("<pad>", "")

        if allow_empty_phrase:
            pattern = r"(?:(?:<loc_\d+>){4,})"
        else:
            pattern = r"([^<]+(?:<loc_\d+>){4,})"
        phrases = re.findall(pattern, text)

        text_pattern = r"^\s*(.*?)(?=<od>|</od>|<box>|</box>|<bbox>|</bbox>|<loc_)"
        box_pattern = r"<loc_(\d+)><loc_(\d+)><loc_(\d+)><loc_(\d+)>"

        instances = []
        for phrase_text in phrases:
            phrase_text = phrase_text.replace("<ground>", "", 1).replace("<obj>", "", 1)
            if not phrase_text and not allow_empty_phrase:
                continue
            match = re.search(text_pattern, phrase_text)
            if not match:
                continue
            phrase = match.group().strip()
            boxes_matches = list(re.finditer(box_pattern, phrase_text))
            if not boxes_matches:
                continue
            bbox_bins = [[int(m.group(j)) for j in range(1, 5)] for m in boxes_matches]
            bboxes = self.dequantize(torch.tensor(bbox_bins), size=image_size).tolist()

            phrase = phrase.encode("ascii", "ignore").decode("ascii")
            for bbox in bboxes:
                instance = {"bbox": bbox, "cat_name": phrase}
                instances.append(instance)

        return instances

def read_image(self, filepath: str, delete_problematic_images: bool = False):
        if isinstance(filepath, str):
            filepath = filepath.replace("\x00", "")
        try:
            file_data = self.read(filepath, as_byteIO=True)
            ext = os.path.splitext(filepath)[1].lower().strip(".")

            # Determine dataset type to handle ambiguous extensions (e.g., .mpeg is both audio and video)
            dataset_type = getattr(self, "dataset_type", None)
            try:
                dataset_type_enum = ensure_dataset_type(dataset_type, default=DatasetType.IMAGE)
            except ValueError:
                dataset_type_enum = DatasetType.IMAGE

            is_video_dataset = dataset_type_enum is DatasetType.VIDEO
            is_video_extension = ext in video_file_extensions

            # Only load as audio if it's an audio dataset OR (audio extension AND not a video extension)
            should_load_as_audio = dataset_type_enum is DatasetType.AUDIO or (
                ext in audio_file_extensions and not is_video_extension
            )

            if should_load_as_audio and not is_video_dataset:
                from simpletuner.helpers.audio import load_audio

                image = load_audio(file_data)
            elif is_video_extension:
                image = load_video(file_data)
            else:
                image = load_image(file_data)
            return image
        except Exception as e:
            import traceback

            logger.error(f"Encountered error opening image {filepath}: {e}, traceback: {traceback.format_exc()}")
            if delete_problematic_images:
                logger.error("Deleting image, because --delete_problematic_images is provided.")
                self.delete(filepath)
            else:
                exit(1)
                raise e

def fit(self, X, y, sample_weight=None):
        X, y = check_X_y(
            X,
            y,
            accept_sparse=["csc", "csr"],
            dtype=None,
            multi_output=self.multi_output,
        )

        if self.refit:
            self.regr_ = clone(self.regressors)
            self.meta_regr_ = clone(self.meta_regressor)
        else:
            self.regr_ = self.regressors
            self.meta_regr_ = self.meta_regressor

        if self.verbose > 0:
            print("Fitting %d regressors..." % (len(self.regressors)))

        for regr in self.regr_:
            if self.verbose > 0:
                i = self.regr_.index(regr) + 1
                print(
                    "Fitting regressor%d: %s (%d/%d)"
                    % (i, _name_estimators((regr,))[0][0], i, len(self.regr_))
                )

            if self.verbose > 2:
                if hasattr(regr, "verbose"):
                    regr.set_params(verbose=self.verbose - 2)

            if self.verbose > 1:
                print(_name_estimators((regr,))[0][1])

            if sample_weight is None:
                regr.fit(X, y)
            else:
                regr.fit(X, y, sample_weight=sample_weight)

        meta_features = self.predict_meta_features(X)

        if not self.use_features_in_secondary:
            # meta model uses the prediction outcomes only
            pass
        elif sparse.issparse(X):
            meta_features = sparse.hstack((X, meta_features))
        else:
            meta_features = np.hstack((X, meta_features))

        if sample_weight is None:
            self.meta_regr_.fit(meta_features, y)
        else:
            self.meta_regr_.fit(meta_features, y, sample_weight=sample_weight)

        # save meta-features for training data
        if self.store_train_meta_features:
            self.train_meta_features_ = meta_features
        return self

def to_numpy(obj):
    framework_to_numpy = {
        "pt": lambda obj: obj.detach().cpu().numpy(),
        "np": lambda obj: obj,
    }

    if isinstance(obj, (dict, UserDict)):
        return {k: to_numpy(v) for k, v in obj.items()}
    elif isinstance(obj, (list, tuple)):
        return np.array(obj)

    # This gives us a smart order to test the frameworks with the corresponding tests.
    framework_to_test_func = _get_frameworks_and_test_func(obj)
    for framework, test_func in framework_to_test_func.items():
        if test_func(obj):
            return framework_to_numpy[framework](obj)

    return obj

def reduce_per_replica(values, strategy, reduction):
    if reduction == "auto":
        if isinstance(strategy, tf.distribute.TPUStrategy):
            reduction = "first"
        else:
            reduction = "mean"

    def _reduce(v):
        """Reduce a single `PerReplica` object."""
        if _collective_all_reduce_multi_worker(strategy):
            if reduction == "concat":
                return _multi_worker_concat(v, strategy)
            elif reduction == "sum":
                return strategy.reduce("SUM", v)
            elif reduction == "mean":
                return strategy.reduce("MEAN", v, axis=0)

        if not _is_per_replica_instance(v):
            return v
        elif reduction == "first":
            return strategy.experimental_local_results(v)[0]
        elif reduction == "concat":
            if _is_tpu_multi_host(strategy):
                return _tpu_multi_host_concat(v, strategy)
            else:
                return concat(strategy.experimental_local_results(v))
        elif reduction == "sum":
            return tf.reduce_sum(strategy.experimental_local_results(v))
        elif reduction == "mean":
            return tf.reduce_mean(
                strategy.experimental_local_results(v), axis=0
            )
        else:
            raise ValueError(
                "`reduction` must be one of "
                '"first", "concat", "mean", "sum", or "auto". '
                f"Received: reduction={reduction}."
            )

    return tree.map_structure(_reduce, values)

def load(self, **kwargs) -> VideoLoadResult:
        if TYPE_CHECKING:
            import av
        else:
            av = import_library('av')

        with av.open(BytesIO(self), **kwargs) as container:
            audio_frames: List[np.ndarray] = []
            video_frames: List[np.ndarray] = []
            keyframe_indices: List[int] = []

            for frame in container.decode():
                if type(frame) == av.audio.frame.AudioFrame:
                    audio_frames.append(frame.to_ndarray())
                elif type(frame) == av.video.frame.VideoFrame:
                    if frame.key_frame == 1:
                        curr_index = len(video_frames)
                        keyframe_indices.append(curr_index)

                    video_frames.append(frame.to_ndarray(format='rgb24'))

        if len(audio_frames) == 0:
            audio = parse_obj_as(AudioNdArray, np.array(audio_frames))
        else:
            audio = parse_obj_as(AudioNdArray, np.stack(audio_frames))

        video = parse_obj_as(VideoNdArray, np.stack(video_frames))
        indices = parse_obj_as(NdArray, keyframe_indices)

        return VideoLoadResult(video=video, audio=audio, key_frame_indices=indices)

def control_group(self, control_group_id, ctrl, shift, alt):
    action = sc_pb.Action()
    select = action.action_ui.control_group

    mod = sc_ui.ActionControlGroup
    if not ctrl and not shift and not alt:
      select.action = mod.Recall
    elif ctrl and not shift and not alt:
      select.action = mod.Set
    elif not ctrl and shift and not alt:
      select.action = mod.Append
    elif not ctrl and not shift and alt:
      select.action = mod.SetAndSteal
    elif not ctrl and shift and alt:
      select.action = mod.AppendAndSteal
    else:
      return  # unknown
    select.control_group_index = control_group_id
    return action

def tool(  # type: ignore
    func: Callable[P, R] | None = None,
    description: str | None = None,
    inputSchema: JSONSchema | None = None,
    name: str | None = None,
    context: bool | str = False,
) -> DecoratedFunctionTool[P, R] | Callable[[Callable[P, R]], DecoratedFunctionTool[P, R]]:

    def decorator(f: T) -> "DecoratedFunctionTool[P, R]":
        # Resolve context parameter name
        if isinstance(context, bool):
            context_param = "tool_context" if context else None
        else:
            context_param = context.strip()
            if not context_param:
                raise ValueError("Context parameter name cannot be empty")

        # Create function tool metadata
        tool_meta = FunctionToolMetadata(f, context_param)
        tool_spec = tool_meta.extract_metadata()
        if name is not None:
            tool_spec["name"] = name
        if description is not None:
            tool_spec["description"] = description
        if inputSchema is not None:
            tool_spec["inputSchema"] = inputSchema

        tool_name = tool_spec.get("name", f.__name__)

        if not isinstance(tool_name, str):
            raise ValueError(f"Tool name must be a string, got {type(tool_name)}")

        return DecoratedFunctionTool(tool_name, tool_spec, f, tool_meta)

    # Handle both @tool and @tool() syntax
    if func is None:
        # Need to ignore type-checking here since it's hard to represent the support
        # for both flows using the type system
        return decorator

    return decorator(func)

def prefetch(dis_arrays: Sequence[Union[ShardedDeviceArray, DistributedArray,
                                        ReplicatedDistributedArray]]):
    group_by_mesh = defaultdict(list)
    for array in tree_leaves(dis_arrays):
        if isinstance(array, ShardedDeviceArray):
            array.copy_to_host_async()
        elif isinstance(array, DistributedArray):
            group_by_mesh[array.device_mesh].append(array)
        elif isinstance(array, ReplicatedDistributedArray):
            array = array.replica
            group_by_mesh[array.device_mesh].append(array)
        else:
            raise ValueError(f"Unhandled array type: {array}")

    for device_mesh, arrays in group_by_mesh.items():
        buf_refs = []
        host_local_ids = []
        for array in arrays:
            buf_refs.append(array.remote_ref)
            host_local_ids.append(array.one_replica_host_local_ids)

        np_arrays = device_mesh.get_remote_buffers(buf_refs,
                                                   host_local_ids,
                                                   batching=True)

        for array, np_value in zip(arrays, np_arrays):
            array._fetched_np_buffers = np_value  # pylint: disable=protected-access

def check_switch_splits(graph):
    msg0 = (
        "Step *{0.name}* is a switch split but defines {num} transitions. "
        "Switch splits must define at least 2 transitions."
    )
    msg1 = "Step *{0.name}* is a switch split but has no condition variable."
    msg2 = "Step *{0.name}* is a switch split but has no switch cases defined."

    for node in graph:
        if node.type == "split-switch":
            # Check at least 2 outputs
            if len(node.out_funcs) < 2:
                raise LintWarn(
                    msg0.format(node, num=len(node.out_funcs)),
                    node.func_lineno,
                    node.source_file,
                )

            # Check condition exists
            if not node.condition:
                raise LintWarn(
                    msg1.format(node),
                    node.func_lineno,
                    node.source_file,
                )

            # Check switch cases exist
            if not node.switch_cases:
                raise LintWarn(
                    msg2.format(node),
                    node.func_lineno,
                    node.source_file,
                )

def restore_offload_state(_pipeline, is_model_cpu_offload, is_sequential_cpu_offload, is_group_offload):
    if _pipeline is None:
        return

    if is_model_cpu_offload and hasattr(_pipeline, "enable_model_cpu_offload"):
        _pipeline.enable_model_cpu_offload()
    elif is_sequential_cpu_offload and hasattr(_pipeline, "enable_sequential_cpu_offload"):
        _pipeline.enable_sequential_cpu_offload()
    elif is_group_offload and _maybe_remove_and_reapply_group_offloading and hasattr(_pipeline, "components"):
        for component in _pipeline.components.values():
            if isinstance(component, torch.nn.Module):
                _maybe_remove_and_reapply_group_offloading(component)

def check_cfg(cfg: dict, hard: bool = True) -> None:
    for k, v in cfg.items():
        if v is not None:  # None values may be from optional args
            if k in CFG_FLOAT_KEYS and not isinstance(v, FLOAT_OR_INT):
                if hard:
                    raise TypeError(
                        f"'{k}={v}' is of invalid type {type(v).__name__}. "
                        f"Valid '{k}' types are int (i.e. '{k}=0') or float (i.e. '{k}=0.5')"
                    )
                cfg[k] = float(v)
            elif k in CFG_FRACTION_KEYS:
                if not isinstance(v, FLOAT_OR_INT):
                    if hard:
                        raise TypeError(
                            f"'{k}={v}' is of invalid type {type(v).__name__}. "
                            f"Valid '{k}' types are int (i.e. '{k}=0') or float (i.e. '{k}=0.5')"
                        )
                    cfg[k] = v = float(v)
                if not (0.0 <= v <= 1.0):
                    raise ValueError(f"'{k}={v}' is an invalid value. Valid '{k}' values are between 0.0 and 1.0.")
            elif k in CFG_INT_KEYS and not isinstance(v, int):
                if hard:
                    raise TypeError(
                        f"'{k}={v}' is of invalid type {type(v).__name__}. '{k}' must be an int (i.e. '{k}=8')"
                    )
                cfg[k] = int(v)
            elif k in CFG_BOOL_KEYS and not isinstance(v, bool):
                if hard:
                    raise TypeError(
                        f"'{k}={v}' is of invalid type {type(v).__name__}. "
                        f"'{k}' must be a bool (i.e. '{k}=True' or '{k}=False')"
                    )
                cfg[k] = bool(v)

def to_example(dictionary):
  features = {}
  for (k, v) in six.iteritems(dictionary):
    if not v:
      raise ValueError("Empty generated field: %s" % str((k, v)))
    # Subtly in PY2 vs PY3, map is not scriptable in py3. As a result,
    # map objects will fail with TypeError, unless converted to a list.
    if six.PY3 and isinstance(v, map):
      v = list(v)
    if (isinstance(v[0], six.integer_types) or
        np.issubdtype(type(v[0]), np.integer)):
      features[k] = tf.train.Feature(int64_list=tf.train.Int64List(value=v))
    elif isinstance(v[0], float):
      features[k] = tf.train.Feature(float_list=tf.train.FloatList(value=v))
    elif isinstance(v[0], six.string_types):
      if not six.PY2:  # Convert in python 3.
        v = [bytes(x, "utf-8") for x in v]
      features[k] = tf.train.Feature(bytes_list=tf.train.BytesList(value=v))
    elif isinstance(v[0], bytes):
      features[k] = tf.train.Feature(bytes_list=tf.train.BytesList(value=v))
    else:
      raise ValueError("Value for %s is not a recognized type; v: %s type: %s" %
                       (k, str(v[0]), str(type(v[0]))))
  return tf.train.Example(features=tf.train.Features(feature=features))

def to(
        self, t: Union[Type[trt.EngineCapability], Type[EngineCapability]]
    ) -> Union[trt.EngineCapability, EngineCapability]:
        if t == trt.EngineCapability:
            if self == EngineCapability.STANDARD:
                return trt.EngineCapability.STANDARD
            elif self == EngineCapability.SAFETY:
                return trt.EngineCapability.SAFETY
            elif self == EngineCapability.DLA_STANDALONE:
                return trt.EngineCapability.DLA_STANDALONE
            else:
                raise ValueError("Provided an unsupported engine capability")

        elif t == EngineCapability:
            return self

        elif ENABLED_FEATURES.torchscript_frontend:
            from torch_tensorrt import _C

            if t == _C.EngineCapability:
                if self == EngineCapability.STANDARD:
                    return _C.EngineCapability.STANDARD
                elif self == EngineCapability.SAFETY:
                    return _C.EngineCapability.SAFETY
                elif self == EngineCapability.DLA_STANDALONE:
                    return _C.EngineCapability.DLA_STANDALONE
                else:
                    raise ValueError("Provided an unsupported engine capability")
        # else: # commented out for mypy
        raise TypeError(
            "Provided unsupported destination type for engine capability type conversion"
        )

def add_optimizer_variables(
        self, trainable_variables, name, initializer="zeros"
    ):
        name_list = name
        initializer_list = initializer
        if isinstance(name, str):
            # Single name/initializer.
            name_list = [name]
            initializer_list = [initializer]
        else:
            # Multiple names/initializers.
            # If there is only one initializer, use it for all names.
            if isinstance(initializer, str) or isinstance(
                initializer, initializers.Initializer
            ):
                initializer_list = [initializer] * len(name_list)

        if len(name_list) != len(initializer_list):
            raise ValueError(
                f"The number of provided names must match the number of "
                f"provided initializers.  Received name='{name}', "
                f"initializer='{initializer}'"
            )

        # Build up lists of optimizer variables.
        optimizer_variables = tuple([] for _ in name_list)
        for variable in trainable_variables:
            # Interleaves adding variables for backward-compatibility.
            if not self._overwrite_variable_with_gradient(variable):
                for i, (var_name, var_init) in enumerate(
                    zip(name_list, initializer_list)
                ):
                    optimizer_variables[i].append(
                        self.add_variable_from_reference(
                            variable,
                            name=var_name,
                            initializer=var_init,
                        )
                    )
            else:
                for i in range(len(name_list)):
                    optimizer_variables[i].append(None)

        # If single input name, return the single list.
        if isinstance(name, str):
            return optimizer_variables[0]

        return optimizer_variables

def register(
        config_class,
        slow_image_processor_class: type | None = None,
        fast_image_processor_class: type | None = None,
        image_processor_classes: dict[str, type] | None = None,
        exist_ok: bool = False,
    ):
        # Handle backward compatibility: convert old parameters to new format
        if image_processor_classes is None:
            image_processor_classes = {}
            if slow_image_processor_class is not None:
                image_processor_classes["pil"] = slow_image_processor_class
            if fast_image_processor_class is not None:
                image_processor_classes["torchvision"] = fast_image_processor_class

        if not image_processor_classes:
            raise ValueError(
                "You need to specify at least one image processor class. "
                "Use `image_processor_classes={'backend_name': ProcessorClass}` or the deprecated "
                "`slow_image_processor_class`/`fast_image_processor_class` parameters."
            )

        # Avoid resetting existing processors if we are passing partial updates
        if config_class in IMAGE_PROCESSOR_MAPPING._extra_content:
            existing_mapping = IMAGE_PROCESSOR_MAPPING[config_class]
            existing_mapping.update(image_processor_classes)
            image_processor_classes = existing_mapping

        # Validate that all classes are proper image processor classes
        from ...image_processing_utils import BaseImageProcessor

        for backend_key, processor_class in image_processor_classes.items():
            if processor_class is not None and not issubclass(processor_class, BaseImageProcessor):
                raise ValueError(
                    f"Image processor class for backend '{backend_key}' must inherit from `BaseImageProcessor`. "
                    f"Got: {processor_class}"
                )
        IMAGE_PROCESSOR_MAPPING.register(config_class, image_processor_classes, exist_ok=exist_ok)

def apply_class_remap(args, det_cfg: dict) -> None:
    bench_cfg: dict = {}
    benchmark_id = (
        getattr(args, "benchmark_id", None)
        or getattr(args, "dataset_id", None)
        or getattr(args, "benchmark", None)
    )
    if benchmark_id:
        try:
            bench_cfg = (load_benchmark_cfg(benchmark_id) or {}).get("benchmark", {})
        except Exception:
            pass

    if str(bench_cfg.get("box_type", "")).lower() == "obb":
        return

    remap_result = build_gt_class_remap(
        bench_cfg,
        det_cfg,
        benchmark_name=getattr(args, "benchmark", ""),
        model_stem=args.detector[0].stem,
    )
    if remap_result is not None:
        remap_dict, new_class_ids, new_class_names = remap_result
        distractor_ids = [int(key) for key in bench_cfg.get("distractor_classes", {}).keys()]
        args.gt_class_remap = remap_dict
        args.gt_class_distractor_ids = distractor_ids
        args.remapped_class_ids = new_class_ids
        args.remapped_class_names = [name.lower() for name in new_class_names]

def parse_model_grpc(model_metadata, model_config):
    if len(model_metadata.inputs) != 1:
        raise Exception("expecting 1 input, got {}".format(len(model_metadata.inputs)))
    if len(model_metadata.outputs) != 1:
        raise Exception(
            "expecting 1 output, got {}".format(len(model_metadata.outputs))
        )

    if len(model_config.input) != 1:
        raise Exception(
            "expecting 1 input in model configuration, got {}".format(
                len(model_config.input)
            )
        )

    input_metadata = model_metadata.inputs[0]
    output_metadata = model_metadata.outputs[0]

    batch_dim = model_config.max_batch_size > 0
    expected_dims = 1 + (1 if batch_dim else 0)

    if len(input_metadata.shape) != expected_dims:
        raise Exception(
            "expecting input to have {} dimensions, model '{}' input has {}".format(
                expected_dims, model_metadata.name, len(input_metadata.shape)
            )
        )

    if len(output_metadata.shape) != expected_dims:
        raise Exception(
            "expecting output to have {} dimensions, model '{}' output has {}".format(
                expected_dims, model_metadata.name, len(output_metadata.shape)
            )
        )

    if input_metadata.shape[-1] != -1:
        raise Exception(
            "expecting input to have variable shape [-1], model '{}' input has {}".format(
                model_metadata.name, input_metadata.shape
            )
        )

    if output_metadata.shape[-1] != -1:
        raise Exception(
            "expecting output to have variable shape [-1], model '{}' output has {}".format(
                model_metadata.name, output_metadata.shape
            )
        )

    return (
        model_config.max_batch_size,
        input_metadata.name,
        output_metadata.name,
        input_metadata.datatype,
    )

def language_callback(lexer, match):
    l = None
    m = language_re.match(lexer.text[match.end():match.end()+100])
    if m is not None:
        l = lexer._get_lexer(m.group(1))
    else:
        m = list(language_re.finditer(
            lexer.text[max(0, match.start()-100):match.start()]))
        if m:
            l = lexer._get_lexer(m[-1].group(1))
        else:
            m = list(do_re.finditer(
                lexer.text[max(0, match.start()-25):match.start()]))
            if m:
                l = lexer._get_lexer('plpgsql')

    # 1 = $, 2 = delimiter, 3 = $
    yield (match.start(1), String, match.group(1))
    yield (match.start(2), String.Delimiter, match.group(2))
    yield (match.start(3), String, match.group(3))
    # 4 = string contents
    if l:
        for x in l.get_tokens_unprocessed(match.group(4)):
            yield x
    else:
        yield (match.start(4), String, match.group(4))
    # 5 = $, 6 = delimiter, 7 = $
    yield (match.start(5), String, match.group(5))
    yield (match.start(6), String.Delimiter, match.group(6))
    yield (match.start(7), String, match.group(7))

def outs2results(bboxes=None,
                 labels=None,
                 masks=None,
                 ids=None,
                 num_classes=None,
                 **kwargs):
    assert labels is not None
    assert num_classes is not None

    results = dict()

    if ids is not None:
        valid_inds = ids > -1
        ids = ids[valid_inds]
        labels = labels[valid_inds]

    if bboxes is not None:
        if ids is not None:
            bboxes = bboxes[valid_inds]
            if bboxes.shape[0] == 0:
                bbox_results = [
                    np.zeros((0, 6), dtype=np.float32)
                    for i in range(num_classes)
                ]
            else:
                if isinstance(bboxes, torch.Tensor):
                    bboxes = bboxes.cpu().numpy()
                    labels = labels.cpu().numpy()
                    ids = ids.cpu().numpy()
                bbox_results = [
                    np.concatenate(
                        (ids[labels == i, None], bboxes[labels == i, :]),
                        axis=1) for i in range(num_classes)
                ]
        else:
            bbox_results = bbox2result(bboxes, labels, num_classes)
        results['bbox_results'] = bbox_results

    if masks is not None:
        if ids is not None:
            masks = masks[valid_inds]
        if isinstance(masks, torch.Tensor):
            masks = masks.detach().cpu().numpy()
        masks_results = [[] for _ in range(num_classes)]
        for i in range(bboxes.shape[0]):
            masks_results[labels[i]].append(masks[i])
        results['mask_results'] = masks_results

    return results

def get_pil_img_dim(img_path):
    try:
        if isinstance(img_path, str):
            with PIL.Image.open(img_path) as img:
                return img.size[0], img.size[1]
        elif isinstance(img_path, bytes):
            with PIL.Image.open(io.BytesIO(img_path)) as img:
                return img.size[0], img.size[1]
        elif isinstance(img_path, PIL.Image.Image):
            return img_path.size[0], img_path.size[1]
        else:
            raise ValueError(f"Invalid image path type: {type(img_path)}")

    except Exception as e:
        logger.error(
            f"Error reading image dimensions from {img_path}: {str(e)}"
        )
        raise

async def count_work_queue_active_slots_bulk(
    db: PrefectDBInterface,
    session: AsyncSession,
    work_queue_ids: Sequence[UUID],
) -> dict[UUID, int]:
    if not work_queue_ids:
        return {}

    # Load only id and filter to classify queue types without full ORM hydration
    query = select(db.WorkQueue.id, db.WorkQueue.filter).where(
        db.WorkQueue.id.in_(work_queue_ids)
    )
    result = await session.execute(query)
    rows = result.all()

    standard_ids: list[UUID] = []
    legacy_filters: list[tuple[UUID, Any]] = []
    for wq_id, wq_filter in rows:
        if wq_filter is not None:
            legacy_filters.append((wq_id, wq_filter))
        else:
            standard_ids.append(wq_id)

    counts: dict[UUID, int] = {}

    if standard_ids:
        bulk_query = (
            select(
                db.FlowRun.work_queue_id,
                sa.func.count(db.FlowRun.id),
            )
            .select_from(db.FlowRun)
            .where(
                db.FlowRun.work_queue_id.in_(standard_ids),
                db.FlowRun.state_type.in_(SLOT_OCCUPYING_STATES),
            )
            .group_by(db.FlowRun.work_queue_id)
        )
        bulk_result = await session.execute(bulk_query)
        counts.update(dict(bulk_result.all()))

    for wq_id, wq_filter in legacy_filters:
        queue_filter = TypeAdapter(schemas.core.QueueFilter).validate_python(wq_filter)
        counts[wq_id] = await _count_legacy_queue_active_slots(session, queue_filter)

    return counts

def transform(self, X):
        check_is_fitted(self)

        # Need not validate X again as it would have already been validated
        # in the Imputer calling MissingIndicator
        if not self._precomputed:
            X = self._validate_input(X, in_fit=False)
        else:
            if not (hasattr(X, "dtype") and X.dtype.kind == "b"):
                raise ValueError("precomputed is True but the input data is not a mask")

        imputer_mask, features = self._get_missing_features_info(X)

        if self.features == "missing-only":
            features_diff_fit_trans = np.setdiff1d(features, self.features_)
            if self.error_on_new and features_diff_fit_trans.size > 0:
                raise ValueError(
                    "The features {} have missing values "
                    "in transform but have no missing values "
                    "in fit.".format(features_diff_fit_trans)
                )

            if self.features_.size < self._n_features:
                imputer_mask = imputer_mask[:, self.features_]

        return imputer_mask

def get_tflite_tensor_shape_with_explicit_padding(
    tflite_shape: List[int], explicit_padding: List[List[int]]
) -> List[int]:

    if (len(tflite_shape) != len(explicit_padding)) or any(
        len(sub_list) != 2 for sub_list in explicit_padding
    ):
        logger.e(
            logger.Code.INTERNAL_ERROR,
            f"Cannot apply padding '{explicit_padding}' to NeutronIR shape '{tflite_shape}'!",
        )

    total_padding = [
        start + end for start, end in explicit_padding
    ]  # Total padding for each dimension

    padded_shape = []
    for dimension, padding in zip(tflite_shape, total_padding):
        if isinstance(dimension, int) and dimension > 0:
            padded_shape.append(dimension + padding)

        else:
            # Variable shape

            if padding == 0:
                padded_shape.append(dimension)

            else:
                # Cannot add padding to a variable dimension.
                logger.e(
                    logger.Code.CONVERSION_IMPOSSIBLE,
                    "Adding explicit padding to a variable sized tensor is not supported!",
                )

    return padded_shape

def forward(self, x, layers=None, **kwargs):
        if layers is None:
            layers = ['prob']

        if kwargs:
            argument.check_unexpected_kwargs(
                kwargs, train='train argument is not supported anymore. '
                'Use chainer.using_config')
            argument.assert_kwargs_empty(kwargs)

        h = x
        activations = {}
        inception_4a_cache = None
        inception_4d_cache = None
        target_layers = set(layers)
        for key, funcs in self.functions.items():
            if not target_layers:
                break

            if key == 'loss1_fc2':
                h = inception_4a_cache
            elif key == 'loss2_fc2':
                h = inception_4d_cache

            for func in funcs:
                h = func(h)
            if key in target_layers:
                activations[key] = h
                target_layers.remove(key)

            if key == 'inception_4a':
                inception_4a_cache = h
            elif key == 'inception_4d':
                inception_4d_cache = h

        return activations

def from_dict(
        cls: type[SpecificPreTrainedConfigType], config_dict: dict[str, Any], **kwargs
    ) -> SpecificPreTrainedConfigType:
        return_unused_kwargs = kwargs.pop("return_unused_kwargs", False)

        # The commit hash might have been updated in the `config_dict`, we don't want the kwargs to erase that update.
        if "_commit_hash" in kwargs and "_commit_hash" in config_dict:
            kwargs.setdefault("_commit_hash", config_dict["_commit_hash"])

        # To remove arg here are those passed along for our internal telemetry but we still need to remove them
        to_remove = ["_from_auto", "_from_pipeline"]
        valid_fields = [
            "num_labels",
            "attn_implementation",
            "experts_implementation",
            "output_attentions",
            "torch_dtype",
            "dtype",
            "name_or_path",
        ]
        for key, value in kwargs.items():
            if key in valid_fields:
                if key not in ["torch_dtype", "dtype"]:
                    config_dict[key] = value
                    to_remove.append(key)
                elif value != "auto":
                    config_dict[key] = value

        config = cls(**config_dict)

        for key, value in kwargs.items():
            if hasattr(config, key):
                current_attr = getattr(config, key)
                # To authorize passing a custom subconfig as kwarg in models that have nested configs.
                # We need to update only custom kwarg values instead and keep other attr in subconfig.
                if isinstance(current_attr, PreTrainedConfig) and isinstance(value, dict):
                    current_attr_updated = current_attr.to_dict()
                    current_attr_updated.update(value)
                    value = current_attr.__class__(**current_attr_updated)
                setattr(config, key, value)
                to_remove.append(key)

        for key in to_remove:
            kwargs.pop(key, None)

        logger.info(f"Model config {config}")
        if return_unused_kwargs:
            return config, kwargs
        else:
            return config

def info(name=None, show_only_latest=True, name_only=False):
    information = _load_info()

    if name is not None:
        corpora = information['corpora']
        models = information['models']
        if name in corpora:
            return information['corpora'][name]
        elif name in models:
            return information['models'][name]
        else:
            raise ValueError("Incorrect model/corpus name")

    if not show_only_latest:
        return information

    if name_only:
        return {"corpora": list(information['corpora'].keys()), "models": list(information['models'])}

    return {
        "corpora": {name: data for (name, data) in information['corpora'].items() if data.get("latest", True)},
        "models": {name: data for (name, data) in information['models'].items() if data.get("latest", True)}
    }

def size_of_subgraphs(self, subgraphs: List[Subgraph]) -> List[int]:
        state_dict = self.module.state_dict(keep_vars=True)
        sizes = []
        weight_visited_nodes = set()
        for subgraph in subgraphs:
            nodes_in_subgraph = set(subgraph.nodes)
            stack = subgraph.nodes.copy()
            size = 0
            while stack:
                node = stack.pop()
                if node in weight_visited_nodes:
                    continue
                weight_visited_nodes.add(node)
                if node.op == "get_attr":
                    weight = state_dict.get(node.target, None)
                    if weight is None:
                        logger.warning(f"Weight {node.target} not found in state_dict")
                        continue
                    size += weight.numel() * weight.element_size()
                    continue
                if node not in nodes_in_subgraph:
                    # Trace to other subgraphs
                    continue
                for input_node in node._input_nodes:
                    if input_node not in weight_visited_nodes:
                        stack.append(input_node)
            sizes.append(size)
        return sizes

def comp_types(val: KernelTypes, input_val: ValueType) -> Optional[bool]:  # noqa
    if isinstance(val, Int):
        return isinstance(input_val, type(val.int_val))
    elif isinstance(val, Bool):
        return isinstance(input_val, type(val.bool_val))
    elif isinstance(val, Double):
        return isinstance(input_val, type(val.double_val))
    elif isinstance(val, String):
        return isinstance(input_val, type(val.string_val))
    elif isinstance(val, Tensor):
        return isinstance(input_val, torch.Tensor)
    elif isinstance(val, IntList):
        if not isinstance(input_val, list):
            return False
        return all(isinstance(x, int) for x in input_val)
    elif isinstance(val, BoolList):
        if not isinstance(input_val, list):
            return False
        return all(isinstance(x, bool) for x in input_val)
    elif isinstance(val, DoubleList):
        if not isinstance(input_val, list):
            return False
        return all(isinstance(x, float) for x in input_val)
    elif isinstance(val, (TensorList, OptionalTensorList)):
        if not isinstance(input_val, list):
            return False
        return all(isinstance(x, torch.Tensor) for x in input_val)
    elif isinstance(val, Null):
        raise TypeError("Setting a value where there should be a Null")

async def do_data_loading(self) -> AsyncIterator[Tuple[int, Any]]:
        if self.model is None:
            await self.setup_model()

        preprocessing_tasks = []
        buffer_size = self.batch_size * 2

        async for idx, item in self.get_dataset_iterator():
            # Clean up completed tasks when buffer is full
            if len(preprocessing_tasks) >= buffer_size:
                done, pending = await asyncio.wait(
                    preprocessing_tasks, return_when=asyncio.FIRST_COMPLETED)
                preprocessing_tasks = list(pending)

                for task in done:
                    result = await task
                    if result is not None:
                        yield result

            # Start new preprocessing task
            async def preprocess_with_index(idx, item):
                async with self.preprocessing_semaphore:
                    processed = await self._preprocess_input(item)
                    if processed is not None:
                        return (idx, processed)
                    return None

            task = asyncio.create_task(preprocess_with_index(idx, item))
            preprocessing_tasks.append(task)

        # Wait for and yield remaining results
        if preprocessing_tasks:
            done = await asyncio.gather(*preprocessing_tasks)
            for result in done:
                if result is not None:
                    yield result

def parallelize_model(
    model: torch.nn.Module,
    config: FSDP2Config,
    optimizer: Optional[torch.optim.Optimizer] = None,
    precision: Optional[Union[str, Precision]] = None,
    fsdp_wrap_policy: Optional[CustomPolicy] = None,
    activation_checkpointing_check_fn: Optional[Callable] = None,
    param_init_fn: Callable[[torch.nn.Module], None] = lambda m: None,
):
    if precision is None:
        precision = Precision.AMP_FP16 if isinstance(get_device(), DeviceGPU) else Precision.FP32
    elif isinstance(precision, str):
        precision = Precision(precision)
    _validate_precision(precision, get_device())

    if activation_checkpointing_check_fn is not None:
        if not config.activation_checkpointing and not config.activation_cpu_offload:
            raise ValueError(
                'Activation checkpointing or offloading must be enabled if activation_checkpointing_check_fn is provided',
            )

    if config.activation_checkpointing or config.activation_cpu_offload:
        apply_ac(
            model,
            config.activation_checkpointing,
            config.activation_cpu_offload,
            activation_checkpointing_check_fn,
        )

    # Use the context manager for optimizer synchronization if optimizer is provided
    with sync_optimizer_and_model_params(optimizer, model) if optimizer is not None else nullcontext():
        _parallelize_model_helper(model, config, precision, fsdp_wrap_policy, param_init_fn)

def superreload(
    module: types.ModuleType, old_objects: OldObjectsMapping | None
) -> types.ModuleType:
    if old_objects is None:
        old_objects = {}

    # collect old objects in the module
    for name, obj in module.__dict__.items():
        append_obj(module, old_objects, name, obj)

    # reload module
    old_dict: dict[str, Any] | None = None
    try:
        # clear namespace first from old cruft
        old_dict = module.__dict__.copy()
        old_name = module.__name__
        module.__dict__.clear()
        module.__dict__["__name__"] = old_name
        module.__dict__["__loader__"] = old_dict["__loader__"]
    except (TypeError, AttributeError, KeyError):
        pass

    try:
        module = reload(module)
    except Exception as e:
        # User introduced a SyntaxError, ModuleNotFoundError, etc -- they
        # should be told, and module dict should not be restored, ie don't fail
        # silently.
        #
        # It's possible that the module fails to reload for some other reason.
        # In this case, too, the failure shouldn't be silent!
        sys.stderr.write(
            f"Error trying to reload module {module.__name__}: {e!s} \n"
        )
        tmpio = io.StringIO()
        traceback.print_exc(file=tmpio)
        tmpio.seek(0)
        write_traceback(tmpio.read())
        raise

    # iterate over all objects and update functions & classes
    for name, new_obj in module.__dict__.items():
        key = (module.__name__, name)
        if key not in old_objects:
            continue

        new_refs = []
        for old_ref in old_objects[key]:
            old_obj = old_ref()
            if old_obj is None:
                continue
            new_refs.append(old_ref)
            update_generic(old_obj, new_obj)

        if new_refs:
            old_objects[key] = new_refs
        else:
            del old_objects[key]

    return module

def fill_domain_from_dict(the_domain, the_dict: dict, the_map: dict = None, default_func=lambda x: x):
    if not the_map:
        the_map = {}
        for k in the_dict:
            the_map[k] = (k, default_func)

    for k, v in the_map.items():
        if isinstance(v, tuple):
            field_in_dict = v[0]
            the_func = v[1]
        else:
            field_in_dict = v
            the_func = default_func

        the_value = the_dict.get(field_in_dict)
        if the_value is not None:
            to_value = the_value
            if to_value in none_values:
                setattr(the_domain, k, None)
            else:
                result_value = the_func(to_value)
                setattr(the_domain, k, result_value)
                exec("the_domain.{}=result_value".format(k))

async def run(self, query: str, top_k: int | None = None) -> str:
        success = False
        top_k = top_k or self.max_results
        payload = {"query": query, "top_k": min(top_k, 50)}

        self._ensure_client()

        tried_servers: set[str] = set()
        last_error: str = ""
        result: str = ""

        # Try servers with automatic failover
        for attempt in range(self.max_retries):
            server_url = self._get_next_server(exclude=tried_servers)
            if server_url is None:
                break

            tried_servers.add(server_url)

            try:
                response = await self._client.post(f"{server_url}/retrieve", json=payload)

                if not response.is_success:
                    last_error = f"Server {server_url} returned {response.status_code}"
                    continue  # Try next server

                response_data = response.json()
                results = response_data.get("results", [])

                success = True
                if not results:
                    result = "No relevant documents found for the query."
                else:
                    result = self._format_search_results(results)
                break  # Success, exit loop

            except httpx.TimeoutException:
                last_error = f"Timeout on {server_url}"
                continue  # Try next server
            except httpx.ConnectError:
                last_error = f"Connection failed to {server_url}"
                continue  # Try next server
            except Exception as e:
                last_error = f"Error on {server_url}: {str(e)}"
                continue  # Try next server

        # Handle failure case
        if not success:
            if last_error:
                result = f"Error: All servers failed. Last error: {last_error}"
            else:
                result = "Error: No retrieval servers available."

        return result

def adjust_height_after_animation(self):
        # Prevent recursion
        if self.resize_in_progress:
            return

        self.resize_in_progress = True
        try:
            if isinstance(self.content_label, QWebEngineView):
                # Check if document.body exists before accessing scrollHeight
                self.content_label.page().runJavaScript(
                    "document.body ? document.body.scrollHeight : 0;",
                    self.apply_webview_height,
                )
                return

            bubble_height = self.bubble.sizeHint().height()
            if bubble_height <= 0:
                content_height = self.content_label.heightForWidth(
                    self.content_label.width()
                )
                if content_height <= 0:
                    content_height = self.content_label.sizeHint().height()
                bubble_height = content_height + self.animation_min_height

            self.setMaximumHeight(bubble_height)
            self.updateGeometry()
        finally:
            self.resize_in_progress = False

def download_file(
    url=None,
    output=None,
    quiet=False,
    proxy=None,
    speed=None,
    use_cookies=True,
    verify=True,
    id=None,
    fuzzy=False,
    resume=False,
    unzip=True,
    overwrite=False,
    subfolder=False,
):
    import zipfile

    try:
        import gdown
    except ImportError:
        print(
            "The gdown package is required for this function. Use `pip install gdown` to install it."
        )
        return

    if output is None:
        if isinstance(url, str) and url.startswith("http"):
            output = os.path.basename(url)

    out_dir = os.path.abspath(os.path.dirname(output))
    if not os.path.exists(out_dir):
        os.makedirs(out_dir)

    if isinstance(url, str):
        if os.path.exists(os.path.abspath(output)) and (not overwrite):
            print(
                f"{output} already exists. Skip downloading. Set overwrite=True to overwrite."
            )
            return os.path.abspath(output)
        else:
            url = github_raw_url(url)

    if "https://drive.google.com/file/d/" in url:
        fuzzy = True

    output = gdown.download(
        url, output, quiet, proxy, speed, use_cookies, verify, id, fuzzy, resume
    )

    if unzip and output.endswith(".zip"):
        with zipfile.ZipFile(output, "r") as zip_ref:
            if not quiet:
                print("Extracting files...")
            if subfolder:
                basename = os.path.splitext(os.path.basename(output))[0]

                output = os.path.join(out_dir, basename)
                if not os.path.exists(output):
                    os.makedirs(output)
                zip_ref.extractall(output)
            else:
                zip_ref.extractall(os.path.dirname(output))

    return os.path.abspath(output)

def get_hf_config_from_composer_state_dict(
    state_dict: dict[str, Any],
    config_overrides: Optional[dict[str, Any]] = None,
) -> 'PretrainedConfig':
    try:
        import transformers
    except ImportError as e:
        raise MissingConditionalImportError(
            extra_deps_group='nlp',
            conda_package='transformers',
            conda_channel='conda-forge',
        ) from e

    if config_overrides is None:
        config_overrides = {}

    hf_config_dict = state_dict['state']['integrations']['huggingface']['model']['config']['content']
    # Update the config with any extra args needed
    hf_config_dict.update(config_overrides)
    # JSON keys need to be converted back to ints, huggingface does not auto convert them along this code path
    if 'id2label' in hf_config_dict:
        hf_config_dict['id2label'] = {int(k): v for k, v in hf_config_dict['id2label'].items()}

    try:
        return transformers.AutoConfig.for_model(**hf_config_dict)
    except ValueError:
        model_type = hf_config_dict.get('model_type')
        try:
            return transformers.AutoConfig.from_pretrained(hf_config_dict['_name_or_path'], **hf_config_dict)
        except KeyError:
            raise Exception(
                f'Could not load config from state dict using either `for_model` or `from_pretrained`.'
                f'Please make sure that the model_type={model_type} is valid, or that the'
                f'config has a valid `_name_or_path`.',
            )

def from_dict(cls, obj: dict) -> GeneralInformation:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return GeneralInformation.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in GeneralInformation) in the input: " + str(obj))

        _obj = GeneralInformation.parse_obj({
            "worker_information": WorkerInformation.from_dict(obj.get("workerInformation")) if obj.get("workerInformation") is not None else None,
            "run_information": RunInformation.from_dict(obj.get("runInformation")) if obj.get("runInformation") is not None else None,
            "dataset_information": DatasetInformation.from_dict(obj.get("datasetInformation")) if obj.get("datasetInformation") is not None else None,
            "annotation_savings": AnnotationSavings.from_dict(obj.get("annotationSavings")) if obj.get("annotationSavings") is not None else None,
            "selected_and_removed_image_examples": [SelectedAndRemovedImagePair.from_dict(_item) for _item in obj.get("selectedAndRemovedImageExamples")] if obj.get("selectedAndRemovedImageExamples") is not None else None
        })
        return _obj

def save_quantized_model(model, safetensors_path):
    tensors = {}
    subclass_meta = {}

    seen = set()
    for key, val in list(model.named_parameters()) + list(model.named_buffers()):
        if key in seen:
            continue
        seen.add(key)

        if val.device.type == "meta":
            continue

        if hasattr(val, "__tensor_flatten__"):
            inner_names, attrs = val.__tensor_flatten__()
            meta = {"_type": type(val).__qualname__}
            for attr_name, attr_val in attrs.items():
                if isinstance(attr_val, torch.Size):
                    meta[attr_name] = list(attr_val)
                elif isinstance(attr_val, torch.dtype):
                    meta[attr_name] = str(attr_val)
                else:
                    meta[attr_name] = attr_val
            subclass_meta[key] = meta

            for name in inner_names:
                inner_tensor = getattr(val, name)
                tensors[f"{key}.__{name}"] = inner_tensor.contiguous()
        else:
            tensors[key] = val.data.contiguous()

    header_metadata = {}
    if subclass_meta:
        header_metadata["quantization"] = json.dumps(subclass_meta)

    save_file(tensors, safetensors_path, metadata=header_metadata)
    return len(tensors)

def format_tensor_metadata(metadata: Union[Any, Sequence[Any]]) -> str:
        # If the provided data is a simple TensorMetadata object, parse it
        if isinstance(metadata, TensorMetadata) or issubclass(
            type(metadata), torch.Tensor
        ):
            return f"{tuple(metadata.shape)}@{metadata.dtype}"  # type: ignore
        # If the provided data is a scalar, return it as is
        elif isinstance(metadata, (int, float, bool)):
            return f"{metadata}@Python-{type(metadata)}"
        # If the provided data is a SymInt, return it as is
        elif isinstance(metadata, (torch.SymInt)):
            return f"{metadata}@SymInt"
        # If the provided data is a sequence, recursively parse it
        elif isinstance(metadata, collections.abc.Sequence):
            formatted_str = "("
            for meta in metadata:
                formatted_str += format_tensor_metadata(meta) + ", "

            return formatted_str[:-2] + ")"
        else:
            _LOGGER.warning(
                f"Detected unparsable type in node formatting: {type(metadata)}"
            )
            return ""

def linkcode_resolve(domain, info):
    import mne

    if domain != "py":
        return None

    modname = info["module"]
    fullname = info["fullname"]

    submod = sys.modules.get(modname)
    if submod is None:
        return None

    obj = submod
    for part in fullname.split("."):
        try:
            obj = getattr(obj, part)
        except Exception:
            return None
    # deal with our decorators properly
    while hasattr(obj, "__wrapped__"):
        obj = obj.__wrapped__

    try:
        fn = inspect.getsourcefile(obj)
    except Exception:
        fn = None
    if not fn:
        try:
            fn = inspect.getsourcefile(sys.modules[obj.__module__])
        except Exception:
            fn = None
    if not fn:
        return None
    fn = op.relpath(fn, start=op.dirname(mne.__file__))
    fn = "/".join(op.normpath(fn).split(os.sep))  # in case on Windows

    try:
        source, lineno = inspect.getsourcelines(obj)
    except Exception:
        lineno = None

    if lineno:
        linespec = f"#L{lineno}-L{lineno + len(source) - 1}"
    else:
        linespec = ""

    if "dev" in mne.__version__:
        kind = "main"
    else:
        kind = "maint/" + ".".join(mne.__version__.split(".")[:2])
    return f"http://github.com/mne-tools/mne-python/blob/{kind}/mne/{fn}{linespec}"

def on_auto_decode_timeout(self):
        if (
            not self.auto_decode_mode
            or self.auto_labeling_mode.shape_type != AutoLabelingMode.POINT
        ):
            return

        flag = -1
        if self.auto_labeling_mode.edit_mode == AutoLabelingMode.ADD:
            flag = 1
        elif self.auto_labeling_mode.edit_mode == AutoLabelingMode.REMOVE:
            flag = 0
        if flag == -1:
            return

        if self.auto_decode_mode and self.last_mouse_pos:
            if len(self.auto_decode_tracklet) >= MAX_AUTO_DECODE_MARKS:
                self.auto_decode_tracklet.pop(0)

            marks = {
                "type": "point",
                "data": [
                    int(self.last_mouse_pos.x()),
                    int(self.last_mouse_pos.y()),
                ],
                "label": flag,
            }
            self.auto_decode_tracklet.append(marks)
            self.auto_decode_requested.emit(self.auto_decode_tracklet)

def get_parameter_dtype(parameter: Union[nn.Module, GenerationMixin, "ModuleUtilsMixin"]):
    last_dtype = None
    for t in parameter.parameters():
        last_dtype = t.dtype
        if t.is_floating_point():
            return t.dtype

    if last_dtype is not None:
        # if no floating dtype was found return whatever the first dtype is
        return last_dtype

    else:
        # For nn.DataParallel compatibility in PyTorch > 1.5
        def find_tensor_attributes(module: nn.Module) -> List[Tuple[str, Tensor]]:
            tuples = [(k, v) for k, v in module.__dict__.items() if torch.is_tensor(v)]
            return tuples

        gen = parameter._named_members(get_members_fn=find_tensor_attributes)
        last_tuple = None
        for tuple in gen:
            last_tuple = tuple
            if tuple[1].is_floating_point():
                return tuple[1].dtype

        # fallback to the last dtype
        return last_tuple[1].dtype

def check_disallowed_symbols_build_dir(nm: str, cxxfilt: str, build_root: Path) -> int:
    symbols = get_cached_symbols(nm, build_root)
    symbol_list = list(symbols.values())
    demangle_symbols(cxxfilt, symbol_list)
    check_disallowed_symbols(cxxfilt, symbol_list)
    disallowed_symbols = filter(lambda symbol: symbol.disallowed, symbol_list)

    disallowed_by_file = {}
    for symbol in disallowed_symbols:
        for file in symbol.sources:
            if file not in disallowed_by_file:
                disallowed_by_file[file] = []
            disallowed_by_file[file].append(symbol)

    for file, symbols in disallowed_by_file.items():
        print(f"{file} contains disallowed symbols:")
        for symbol in symbols:
            print(" *", symbol.demangled)
        print()

    if len(disallowed_by_file) > 0:
        return STATUS_ERROR

    return STATUS_OK

def read_logic(s, logic_parser=None, encoding=None):
    if encoding is not None:
        s = s.decode(encoding)
    if logic_parser is None:
        logic_parser = LogicParser()

    statements = []
    for linenum, line in enumerate(s.splitlines()):
        line = line.strip()
        if line.startswith("#") or line == "":
            continue
        try:
            statements.append(logic_parser.parse(line))
        except LogicalExpressionException as e:
            raise ValueError(f"Unable to parse line {linenum}: {line}") from e
    return statements

def code_line(func, show_source: bool = False) -> Optional[str]:
    if isinstance(func, inspect.FrameInfo):
        ret = f"{func.filename}:{func.lineno}"
        if show_source and func.code_context is not None:
            ret += "\n"
            for line in func.code_context:
                ret += "\t" + line

        return ret

    if inspect.isframe(func):
        code = func.f_code
        ret = f"{func.f_code.co_filename}:{func.f_code.co_firstlineno}"

    elif safe_hasattr(func, "__code__"):
        code = func.__code__
        ret = f"{code.co_filename}:{code.co_firstlineno}"

    else:
        return None

    if show_source:
        try:
            ret += "\n"
            for line in inspect.getsourcelines(func)[0]:
                ret += "\t" + str(line)
        except OSError as e:
            ret += f"Source code cannot be retrieved: {e}"

    return ret

def make_compound_path(cls, *args):
        if not args:
            return Path(np.empty([0, 2], dtype=np.float32))
        vertices = np.concatenate([path.vertices for path in args])
        codes = np.empty(len(vertices), dtype=cls.code_type)
        i = 0
        for path in args:
            size = len(path.vertices)
            if path.codes is None:
                if size:
                    codes[i] = cls.MOVETO
                    codes[i+1:i+size] = cls.LINETO
            else:
                codes[i:i+size] = path.codes
            i += size
        not_stop_mask = codes != cls.STOP  # Remove STOPs, as internal STOPs are a bug.
        return cls(vertices[not_stop_mask], codes[not_stop_mask])

def add(
        self, item: Any, index: Optional[int] = None, apply_transformer: bool = True
    ):
        transformed_items: Dict[str, List] = {}
        if apply_transformer:
            for key, transformer in self.transformer_setups.items():
                transformed_docs = []
                map_fn = self.mapper_setups.get(key, None)
                if map_fn is not None:
                    transformed_docs = transformer([map_fn(item)])
                else:
                    transformed_docs = transformer([item])
                transformed_items[key] = transformed_docs

        if index is not None:
            self.items.insert(index, item)
            for key, transformed_docs in transformed_items.items():
                for doc in transformed_docs:
                    self.transformed_items[key].insert(index, doc)
        else:
            self.items.append(item)
            for key, transformed_docs in transformed_items.items():
                self.transformed_items[key].extend(transformed_docs)

async def search_rag_config(
        project_id: Annotated[
            str, Path(description="The unique identifier of the project.")
        ],
        rag_config_id: Annotated[
            str, Path(description="The unique identifier of the RAG configuration.")
        ],
        request: RagSearchRequest,
    ) -> RagSearchResponse:
        project = project_from_id(project_id)

        # Get the RAG config and associated configs
        rag_config = RagConfig.from_id_and_parent_path(rag_config_id, project.path)
        if rag_config is None:
            raise HTTPException(
                status_code=404,
                detail="RAG config not found",
            )

        if rag_config.is_archived:
            raise HTTPException(
                status_code=422,
                detail="This RAG configuration is archived. You must unarchive it to use it.",
            )

        # Empty query - return empty results
        if not request.query.strip():
            return RagSearchResponse(results=[])

        # we do a tool call to have the exact same behavior as during a live LLM tool call
        rag_tool = tool_from_id(
            f"{RAG_TOOL_ID_PREFIX}{rag_config_id}",
            task=Task(
                name="Fake RAG Search",
                instruction="This is a dummy task to match the params expected by the tool_from_id factory, but is not a real task.",
                parent=project,
            ),
        )
        if not isinstance(rag_tool, RagTool):
            raise HTTPException(
                status_code=400,
                detail="Retrieved RAG tool is not a RagTool",
            )

        try:
            search_results = await rag_tool.search(query=request.query)
            return RagSearchResponse(results=search_results)
        except Exception as e:
            logger.error(f"Search failed: {e}")
            raise HTTPException(
                status_code=500,
                detail=f"Search failed: {e!s}",
            )

def register_gemma3_sdpa_pass(index: int = 0, model_config: Any = None) -> None:
    @_aten_lowering_pass(index=index, model_config=model_config)
    def gemma3_sdpa_pass(
        gm: torch.fx.GraphModule, settings: CompilationSettings
    ) -> torch.fx.GraphModule:
        """SDPA pass specifically for Gemma3 models with sliding window attention."""
        config = get_lowering_pass_config(gemma3_sdpa_pass)
        sliding_window = None
        layer_types = None
        model_config = config.get("model_config", None)
        if not isinstance(model_config, Gemma3TextConfig):
            logger.warning(
                f"Expected Gemma3TextConfig, got {type(model_config)}, will use default SDPA replacement instead"
            )
        else:
            sliding_window = getattr(model_config, "sliding_window", None)
            layer_types = getattr(model_config, "layer_types", None)
            logger.debug(
                f"got Gemma3 config: sliding_window={sliding_window}, layer_types={layer_types}"
            )

        index = 0
        for node in gm.graph.nodes:
            if node.op == "call_function" and node.target in REPLACEABLE_ATEN_OPS:
                sliding_window_size = None
                if (
                    sliding_window is not None
                    and sliding_window > 0
                    and layer_types is not None
                    and index < len(layer_types)
                ):
                    if layer_types[index] == "sliding_attention":
                        sliding_window_size = sliding_window
                index += 1

                # Process the node
                logger.debug(
                    f"Applying Gemma3-specific SDPA replacement with {node.name=}, {node.target=}, {sliding_window_size=}"
                )
                gm = _process_sdpa_node(gm, node, settings, sliding_window_size)

        clean_up_graph_after_modifications(gm)
        logger.debug("Applied Gemma3-specific SDPA replacement")
        return gm

def aggregate_evaluate(
        self,
        server_round: int,
        results: List[Tuple[ClientProxy, EvaluateRes]],
        failures: List[Union[Tuple[ClientProxy, FitRes], BaseException]],
    ) -> Tuple[Optional[float], Dict[str, Scalar]]:
        if not results:
            return None, {}
        # Do not aggregate if there are failures and failures are not accepted
        if not self.accept_failures and failures:
            return None, {}
        loss_aggregated = weighted_loss_avg(
            [
                (
                    evaluate_res.num_examples,
                    evaluate_res.loss,
                )
                for _, evaluate_res in results
            ]
        )

        num_total_evaluation_examples = sum(
            [evaluate_res.num_examples for _, evaluate_res in results]
        )
        weighted_metric = [
            evaluate_res.num_examples * evaluate_res.metrics["loss"]
            for _, evaluate_res in results
        ]

        metrics_aggregated = {}
        metrics_aggregated["loss"] = (
            sum(weighted_metric) / num_total_evaluation_examples
        )

        return loss_aggregated, metrics_aggregated

def check_model_list():
    # Get the models from the directory structure of `src/transformers/models/`
    import transformers as tfrs

    models_dir = os.path.join(PATH_TO_TRANSFORMERS, "models")
    _models = []
    for model in os.listdir(models_dir):
        if model == "deprecated":
            continue
        model_dir = os.path.join(models_dir, model)
        if os.path.isdir(model_dir) and "__init__.py" in os.listdir(model_dir):
            # If the init is empty, and there are only two files, it's likely that there's just a conversion
            # script. Those should not be in the init.
            if (Path(model_dir) / "__init__.py").read_text().strip() == "":
                continue

            _models.append(model)

    # Get the models in the submodule `transformers.models`
    models = [model for model in dir(tfrs.models) if not model.startswith("__")]

    missing_models = sorted(set(_models).difference(models))
    if missing_models:
        raise Exception(
            f"The following models should be included in {models_dir}/__init__.py: {','.join(missing_models)}."
        )

def load_tools_from_module_path(module_tool_path: str) -> list[AgentTool]:
    if ":" in module_tool_path:
        module_path, tool_func_name = module_tool_path.split(":")
    else:
        module_path, tool_func_name = (module_tool_path, None)

    try:
        module = importlib.import_module(module_path)
    except ModuleNotFoundError as e:
        raise AttributeError(f'Tool string: "{module_tool_path}" is not a valid tool string.') from e

    # If a ':' is present in the string, then its a targeted function in a module
    if tool_func_name:
        if hasattr(module, tool_func_name):
            target_tool = getattr(module, tool_func_name)
            if isinstance(target_tool, DecoratedFunctionTool):
                return [target_tool]

        raise AttributeError(f"Tool {tool_func_name} not found in module {module_path}")

    # Else, try to import all of the @tool decorated tools, or the module based tool
    module_name = module_path.split(".")[-1]
    return load_tools_from_module(module, module_name)

def apply_codec(
        self,
        preset: str = None,
        format: str = "wav",
        encoding: str = None,
        bits_per_sample: int = None,
        compression: int = None,
    ):  # pragma: no cover
        torchaudio_version_070 = "0.7" in torchaudio.__version__
        if torchaudio_version_070:
            return self

        kwargs = {
            "format": format,
            "encoding": encoding,
            "bits_per_sample": bits_per_sample,
            "compression": compression,
        }

        if preset is not None:
            if preset in self.CODEC_PRESETS:
                kwargs = self.CODEC_PRESETS[preset]
            else:
                raise ValueError(
                    f"Unknown preset: {preset}. "
                    f"Known presets: {list(self.CODEC_PRESETS.keys())}"
                )

        waveform = self._to_2d()
        if kwargs["format"] in ["vorbis", "mp3", "ogg", "amr-nb"]:
            # Apply it in a for loop
            augmented = torch.cat(
                [
                    torchaudio.functional.apply_codec(
                        waveform[i][None, :], self.sample_rate, **kwargs
                    )
                    for i in range(waveform.shape[0])
                ],
                dim=0,
            )
        else:
            augmented = torchaudio.functional.apply_codec(
                waveform, self.sample_rate, **kwargs
            )
        augmented = self._to_3d(augmented)

        self.audio_data = augmented
        return self

def eval_result_entries_to_yaml(entries: list[EvalResultEntry]) -> list[dict[str, Any]]:
    result = []
    for entry in entries:
        # build the dataset object
        dataset: dict[str, Any] = {"id": entry.dataset_id, "task_id": entry.task_id}
        if entry.dataset_revision is not None:
            dataset["revision"] = entry.dataset_revision

        data: dict[str, Any] = {"dataset": dataset, "value": entry.value}
        if entry.verify_token is not None:
            data["verifyToken"] = entry.verify_token
        if entry.date is not None:
            data["date"] = entry.date
        # build the source object
        if entry.source_url is not None:
            source: dict[str, Any] = {"url": entry.source_url}
            if entry.source_name is not None:
                source["name"] = entry.source_name
            if entry.source_user is not None:
                source["user"] = entry.source_user
            if entry.source_org is not None:
                source["org"] = entry.source_org
            data["source"] = source
        if entry.notes is not None:
            data["notes"] = entry.notes

        result.append(data)
    return result

def from_3d_numpy_to_multi_index(
    X, instance_index=None, time_index=None, column_names=None
):
    if X.ndim != 3:
        msg = " ".join(
            [
                "Input should be 3-dimensional NumPy array with shape",
                "(n_instances, n_columns, n_timepoints).",
            ]
        )
        raise TypeError(msg)

    n_instances, n_columns, n_timepoints = X.shape
    multi_index = pd.MultiIndex.from_product(
        [range(n_instances), range(n_columns), range(n_timepoints)],
        names=["instances", "columns", "timepoints"],
    )

    X_mi = pd.DataFrame({"X": X.flatten()}, index=multi_index)
    X_mi = X_mi.unstack(level="columns")

    # Assign column names
    if column_names is None:
        X_mi.columns = _make_column_names(n_columns)

    else:
        X_mi.columns = column_names

    index_rename_dict = {}
    if instance_index is not None:
        index_rename_dict["instances"] = instance_index

    if time_index is not None:
        index_rename_dict["timepoints"] = time_index

    if len(index_rename_dict) > 0:
        X_mi = X_mi.rename_axis(index=index_rename_dict)

    return X_mi

def close(fig: None | int | str | Figure | Literal["all"] = None) -> None:
    if fig is None:
        manager = _pylab_helpers.Gcf.get_active()
        if manager is None:
            return
        else:
            _pylab_helpers.Gcf.destroy(manager)
    elif fig == 'all':
        _pylab_helpers.Gcf.destroy_all()
    elif isinstance(fig, int):
        _pylab_helpers.Gcf.destroy(fig)
    elif hasattr(fig, 'int'):  # UUIDs get converted to ints by figure().
        _pylab_helpers.Gcf.destroy(fig.int)
    elif isinstance(fig, str):
        all_labels = get_figlabels()
        if fig in all_labels:
            num = get_fignums()[all_labels.index(fig)]
            _pylab_helpers.Gcf.destroy(num)
    elif isinstance(fig, Figure):
        _pylab_helpers.Gcf.destroy_fig(fig)
    else:
        _api.check_isinstance(  # type: ignore[unreachable]
            (Figure, int, str, None), fig=fig)

def initialize(self, corpus):
        logger.info("calculating counts")
        glob_freq = {}
        glob_num_words, doc_no = 0, -1
        for doc_no, bow in enumerate(corpus):
            if doc_no % 10000 == 0:
                logger.info("PROGRESS: processing document #%i", doc_no)
            glob_num_words += len(bow)
            for term_id, term_count in bow:
                glob_freq[term_id] = glob_freq.get(term_id, 0) + term_count

        # keep some stats about the training corpus
        self.n_docs = doc_no + 1
        self.n_words = glob_num_words

        # and finally compute the global weights
        logger.info(
            "calculating global log entropy weights for %i documents and %i features (%i matrix non-zeros)",
            self.n_docs, len(glob_freq), self.n_words
        )
        logger.debug('iterating over corpus')

        # initialize doc_no2 index in case corpus is empty
        doc_no2 = 0
        for doc_no2, bow in enumerate(corpus):
            for key, freq in bow:
                p = (float(freq) / glob_freq[key]) * math.log(float(freq) / glob_freq[key])
                self.entr[key] = self.entr.get(key, 0.0) + p
        if doc_no2 != doc_no:
            raise ValueError("LogEntropyModel doesn't support generators as training data")

        logger.debug('iterating over keys')
        for key in self.entr:
            self.entr[key] = 1 + self.entr[key] / math.log(self.n_docs + 1)

def fit(self, x_train, y_train, x_val=None, y_val=None):
        if not isinstance(x_train, np.ndarray) or not isinstance(y_train, np.ndarray):
            raise ValueError("x_train and y_train must be numpy arrays")

        if (x_val is not None and y_val is None) or (
            x_val is None and y_val is not None
        ):
            raise ValueError(
                "Either both x_val and y_val should be None or both should be numpy arrays."
            )

        if x_val is not None and y_val is not None:
            if not isinstance(x_val, np.ndarray) or not isinstance(y_val, np.ndarray):
                raise ValueError("x_train and y_train must be numpy arrays")

            self.early_stopping = True
            print(
                "Using Early Stopping based on performance evaluated on given validation set."
            )

        if len(x_train.shape) == 1:
            self.n_classes = 1
        else:
            self.n_classes = x_train.shape[1]

        if self.n_classes > 1:
            self._fit_temperature_scaling(x_train, y_train, x_val, y_val)
        else:
            self._fit_platt_scaling(x_train.reshape(-1, 1), y_train.reshape(-1, 1))

def blend_images(
    img1,
    img2,
    alpha=0.5,
    output=False,
    show=True,
    figsize=(12, 10),
    axis="off",
    **kwargs,
):
    # Resize the images to have the same dimensions
    if isinstance(img1, str):
        if img1.startswith("http"):
            img1 = download_file(img1)

        if not os.path.exists(img1):
            raise ValueError(f"Input path {img1} does not exist.")

        img1 = cv2.imread(img1)

    if isinstance(img2, str):
        if img2.startswith("http"):
            img2 = download_file(img2)

        if not os.path.exists(img2):
            raise ValueError(f"Input path {img2} does not exist.")

        img2 = cv2.imread(img2)

    if img1.dtype == np.float32:
        img1 = (img1 * 255).astype(np.uint8)

    if img2.dtype == np.float32:
        img2 = (img2 * 255).astype(np.uint8)

    if img1.dtype != img2.dtype:
        img2 = img2.astype(img1.dtype)

    img1 = cv2.resize(img1, (img2.shape[1], img2.shape[0]))

    # Blend the images using the addWeighted function
    beta = 1 - alpha
    blend_img = cv2.addWeighted(img1, alpha, img2, beta, 0, **kwargs)

    if output:
        array_to_image(blend_img, output, img2)

    if show:
        import matplotlib.pyplot as plt

        plt.figure(figsize=figsize)
        plt.imshow(blend_img)
        plt.axis(axis)
        plt.show()
    else:
        return blend_img

def shutdown(
        self,
        timeout: float | None = None,
        close_env: bool = True,
        raise_on_error: bool = True,
    ) -> None:
        try:
            if not self.closed:
                # Stop the background thread if one is running (from .start())
                # before tearing down the env it may still be using.
                self._stop = True
                if hasattr(self, "_thread") and self._thread.is_alive():
                    self._thread.join(timeout=timeout)
                self.closed = True
                del self._carrier
                if self._use_buffers:
                    del self._final_rollout
                if close_env and not self.env.is_closed:
                    self.env.close(raise_if_closed=raise_on_error)
                del self.env
            return
        except Exception as e:
            if raise_on_error:
                raise e
            else:
                pass

def check_validity(self, queue, observables):
        for o in queue:
            operation_name = o.name

            if isinstance(o, MidMeasure) and not self.capabilities().get(
                "supports_mid_measure", False
            ):
                raise DeviceError(
                    f"Mid-circuit measurements are not natively supported on device {self.short_name}. "
                    "Apply the @qml.defer_measurements decorator to your quantum function to "
                    "simulate the application of mid-circuit measurements on this device."
                )

            if isinstance(o, Projector):
                raise ValueError(f"Postselection is not supported on the {self.name} device.")

            if not self.stopping_condition(o):
                raise DeviceError(
                    f"Gate {operation_name} not supported on device {self.short_name}"
                )

        for o in observables:
            if isinstance(o, MeasurementProcess):
                o = o.obs
                if o is None:
                    continue

            if isinstance(o, Prod):

                supports_prod = self.supports_observable(o.name)
                if not supports_prod:
                    raise DeviceError(f"Observable Prod not supported on device {self.short_name}")

                simplified_op = o.simplify()
                if isinstance(simplified_op, Prod):
                    for i in o.simplify().operands:
                        if not self.supports_observable(i.name):
                            raise DeviceError(
                                f"Observable {i.name} not supported on device {self.short_name}"
                            )

            else:
                observable_name = o.name

                if not self.supports_observable(observable_name):
                    raise DeviceError(
                        f"Observable {observable_name} not supported on device {self.short_name}"
                    )

def cancel_sub_agent_tasks_tool(
    agent: Any, agent_name: str, **kwargs
) -> str:
    registry = _find_registry(agent)
    if registry is None:
        return (
            "Error: Sub-agent registry is not available on this agent "
            "instance. Async tasks cannot be cancelled."
        )

    matches = _resolve_sub_agents_by_name(agent, agent_name)
    if not matches:
        return (
            f"Error: No sub-agents found with name '{agent_name}'. "
            "Use create_sub_agent first."
        )

    sub_agent_objects = {
        data["agent"] for _, data in matches if "agent" in data
    }

    cancelled = 0
    not_cancellable = 0

    for task_id, st in registry.tasks.items():
        task_agent = getattr(st, "agent", None)
        if (
            task_agent in sub_agent_objects
            or getattr(task_agent, "agent_name", None) == agent_name
        ):
            if st.status in (
                TaskStatus.COMPLETED,
                TaskStatus.FAILED,
                TaskStatus.CANCELLED,
            ):
                not_cancellable += 1
                continue
            if registry.cancel(task_id):
                cancelled += 1
            else:
                not_cancellable += 1

    if cancelled == 0 and not_cancellable == 0:
        msg = (
            f"No async tasks are currently registered for sub-agent "
            f"'{agent_name}'."
        )
    else:
        msg = (
            f"Cancelled {cancelled} async task(s) and skipped "
            f"{not_cancellable} already finished or non-cancellable "
            f"task(s) for sub-agent '{agent_name}'."
        )

    agent.short_memory.add(
        role="Sub-Agent Execution",
        content=msg,
    )
    if getattr(agent, "verbose", False):
        logger.info(msg)
    return msg

def scan(init, update, state_placeholder, inputs=None, name="scan", tag="", attrs=None):
    if _tag.TagScope.get_current() is not None:
        if tag != "":
            raise ValueError("nested tag is not allowed for now")
        tag = _tag.TagScope.get_current().tag
    if isinstance(init, _tensor.Tensor):
        init = [init]
    if isinstance(update, _tensor.Tensor):
        update = [update]
    if isinstance(state_placeholder, _tensor.Tensor):
        state_placeholder = [state_placeholder]
    if isinstance(inputs, _tensor.Tensor):
        inputs = [inputs]
    if inputs is None:
        inputs = []
    if len(init) != len(update) or len(init) != len(state_placeholder):
        raise ValueError("init, update, state_placeholder must have same length")
    axis = tvm.tirx.IterVar((init[0].shape[0], update[0].shape[0]), f"{name}.idx", 3)
    op = _ffi_api.ScanOp(name, tag, attrs, axis, init, update, state_placeholder, inputs)
    res = [op.output(i) for i in range(len(update))]
    return res[0] if len(res) == 1 else res

def is_text_column(data: pd.Series) -> bool:
    if len(data) > 5000:
        # Sample to speed-up type inference
        data = data.sample(n=5000, random_state=0)
    try:
        data_unique = data.unique()
        num_unique = len(data_unique)
        num_rows = len(data)
        unique_ratio = num_unique / num_rows
        if unique_ratio <= 0.01:
            return False
        try:
            avg_words = pd.Series(data_unique).str.split().str.len().mean()
        except AttributeError:
            return False
        if avg_words < 3:
            return False
    except:
        return False
    return True

def add(self, d):
        summaries = self._summaries
        for k, v in six.iteritems(d):
            w = 1
            if isinstance(v, tuple):
                w = v[1]
                v = v[0]
                if isinstance(w, variable.Variable):
                    w = w.array
                if not numpy.isscalar(w) and not getattr(w, 'ndim', -1) == 0:
                    raise ValueError(
                        'Given weight to {} was not scalar.'.format(k))
            if isinstance(v, variable.Variable):
                v = v.array
            if numpy.isscalar(v) or getattr(v, 'ndim', -1) == 0:
                summaries[k].add(v, weight=w)

def setup_execution_config(
        self, config: ExecutionConfig | None = None, circuit: QuantumScript | None = None
    ) -> ExecutionConfig:

        if self.__class__.preprocess is not Device.preprocess:
            if config:
                return self.preprocess(config)[1]
            return self.preprocess()[1]

        if config is None:
            config = ExecutionConfig()

        if self.supports_derivatives(config) and config.gradient_method in ("best", None):
            return replace(config, gradient_method="device")

        shots_present = bool(circuit is not None and bool(circuit.shots))
        validate_mcm_method(self.capabilities, config.mcm_config.mcm_method, shots_present)
        if config.mcm_config.mcm_method is None and self.capabilities is not None:
            # This is a sensible default strategy for resolving the MCM method based on declared
            # capabilities of a device, but if a device wishes to do this differently, it should
            # override the ``setup_execution_config`` method itself.
            default_mcm_method = _default_mcm_method(self.capabilities, shots_present)
            new_mcm_config = replace(config.mcm_config, mcm_method=default_mcm_method)
            config = replace(config, mcm_config=new_mcm_config)

        return config

def get_source_for_theme(theme: rio.Theme, *, create_theme_pair: bool) -> str:
    # Find all parameters which must be passed to create this theme
    theme_parameters = get_minimum_theme_kwargs(theme)

    # Build the source
    theme_or_themes = "themes" if create_theme_pair else "theme"
    result = io.StringIO()
    result.write(f"# Create the {theme_or_themes}\n")

    if create_theme_pair:
        result.write("themes = rio.Theme.pair_from_colors(")
        theme_parameters.pop("mode", None)
    else:
        result.write("theme = rio.Theme.from_colors(")

    if theme_parameters:
        result.write("\n")

        for key, value in theme_parameters.items():
            result.write(f"    {key}=")

            if isinstance(value, rio.Color):
                hex_value = value.hexa
                if len(hex_value) == 8 and hex_value.endswith("ff"):
                    hex_value = hex_value[:-2]

                result.write(f"rio.Color.from_hex({hex_value!r})")
            elif isinstance(value, bool):
                result.write("True" if value else "False")
            elif isinstance(value, (int, float)):
                result.write(f"{value:.2f}")
            elif isinstance(value, str):
                result.write(repr(value))
            else:
                raise NotImplementedError(f"Unsupported type: {type(value)}")

            result.write(",\n")

    result.write(")\n")
    result.write("\n")
    result.write(
        f"# And apply {'them' if create_theme_pair else 'it'} to your app\n"
    )
    result.write("app = rio.App(\n")
    result.write("    ...\n")
    result.write(f"    theme={theme_or_themes},\n")
    result.write("    ...\n")
    result.write(")")

    # Done
    return result.getvalue()

def greater_is_better(self):
        from deepchecks.tabular.metric_utils.scorers import regression_scorers_lower_is_better_dict

        lower_is_better_names = set(regression_scorers_lower_is_better_dict.keys())
        if not hasattr(self, 'scorers'):
            raise NotImplementedError('ReduceMetricClassMixin must be used with a check that has a scorers attribute')
        elif isinstance(self.scorers, dict):
            names = list(self.scorers.keys())
        elif isinstance(self.scorers, list):
            names = self.scorers
        else:
            raise NotImplementedError('ReduceMetricClassMixin must be used with a check that has a scorers attribute'
                                      ' of type DeepcheckScorer or dict')

        names = [x.lower().replace(' ', '_') for x in names]
        if all((name in lower_is_better_names) for name in names):
            return False
        elif all((name not in lower_is_better_names) for name in names):
            return True
        else:
            raise DeepchecksValueError('Cannot reduce metric class with mixed scorers')

def load_typed_config(
        config_key: str,
        user_config: Dict[str, Any],
        config_class: Type[T],
        type_field: str = "type",
        valid_types: Optional[List[str]] = None,
        default_type: Optional[str] = None,
        env_prefix: str = "",
        type_specific_loaders: Optional[
            Dict[str, Callable[[str], Dict[str, Any]]]
        ] = None,
    ) -> Optional[T]:
        # Check if user already provided config
        if config_key in user_config:
            config_dict = user_config[config_key]
            config_type = config_dict.get(type_field)

            # Validate type
            if valid_types and config_type not in valid_types:
                logger.warning(
                    f"Invalid {config_key} type: {config_type}, using {default_type}"
                )
                config_type = default_type

            return config_class(**config_dict)

        # Load from environment
        env_type_key = f"{env_prefix}TYPE"
        config_type = os.getenv(env_type_key, default_type)

        if not config_type:
            return None

        # Validate type
        if valid_types and config_type not in valid_types:
            logger.warning(
                f"Invalid {config_key} type: {config_type}, using {default_type}"
            )
            config_type = default_type

        logger.debug(f"Loaded {env_type_key} from environment: {config_type}")

        # Load type-specific settings
        config_data = {type_field: config_type}

        if type_specific_loaders and config_type in type_specific_loaders:
            loader = type_specific_loaders[config_type]
            type_specific_data = loader(env_prefix)
            config_data.update(type_specific_data)

        return config_class(**config_data)

def add_edges_from_source(
        self,
        source: Union[Node, Agent, str],
        targets: List[Union[Node, Agent, str]],
        **kwargs: Any,
    ) -> List[Edge]:
        if self.verbose:
            logger.info(
                f"Adding fan-out edges from {source} to {len(targets)} targets: {targets}"
            )

        created_edges = []

        try:
            for target in targets:
                edge = Edge.from_nodes(source, target, **kwargs)

                # Validate nodes exist
                if edge.source not in self.nodes:
                    error_msg = f"Source node '{edge.source}' does not exist in GraphWorkflow"
                    logger.error(error_msg)
                    raise ValueError(error_msg)

                if edge.target not in self.nodes:
                    error_msg = f"Target node '{edge.target}' does not exist in GraphWorkflow"
                    logger.error(error_msg)
                    raise ValueError(error_msg)

                self.edges.append(edge)
                self.graph_backend.add_edge(
                    edge.source, edge.target, **(edge.metadata or {})
                )
                created_edges.append(edge)

                if self.verbose:
                    logger.debug(
                        f"Added fan-out edge: {edge.source} -> {edge.target}"
                    )

            self._invalidate_compilation()

            if self.verbose:
                logger.success(
                    f"Successfully added {len(created_edges)} fan-out edges from {source}"
                )

            return created_edges

        except Exception as e:
            logger.exception(
                f"Error in GraphWorkflow.add_edges_from_source: {e}"
            )
            raise e

def get_column_definition(self):
        column_definition = self._column_definition

        # Sanity checks first.
        # Ensure only one ID and time column exist
        def _check_single_column(input_type):
            length = len([tup for tup in column_definition if tup[2] == input_type])

            if length != 1:
                raise ValueError("Illegal number of inputs ({}) of type {}".format(length, input_type))

        _check_single_column(InputTypes.ID)
        _check_single_column(InputTypes.TIME)

        identifier = [tup for tup in column_definition if tup[2] == InputTypes.ID]
        time = [tup for tup in column_definition if tup[2] == InputTypes.TIME]
        real_inputs = [
            tup
            for tup in column_definition
            if tup[1] == DataTypes.REAL_VALUED and tup[2] not in {InputTypes.ID, InputTypes.TIME}
        ]
        categorical_inputs = [
            tup
            for tup in column_definition
            if tup[1] == DataTypes.CATEGORICAL and tup[2] not in {InputTypes.ID, InputTypes.TIME}
        ]

        return identifier + time + real_inputs + categorical_inputs

def get_agg_config(
    net: Module, trainloader: DataLoader, p_s: List[float]
) -> FJORD_CONFIG_TYPE:
    Logger.get().info("Constructing OD model configuration for aggregation.")
    device = next(net.parameters()).device
    images, _ = next(iter(trainloader))
    images = images.to(device)
    layers = net_to_state_dict_layers(net)
    # init min dims in networks
    config: FJORD_CONFIG_TYPE = {p: [{} for _ in layers] for p in p_s}
    config["layer"] = []
    config["layer_p"] = []
    with torch.no_grad():
        for p in p_s:
            max_sampler = ODSampler(
                p_s=[p],
                max_p=p,
                model=net,
            )
            net(images, sampler=max_sampler)
            for i, layer in enumerate(layers):
                if isinstance(layer, (ODConv2d, ODLinear)):
                    config[p][i]["in_dim"] = layer.last_input_dim
                    config[p][i]["out_dim"] = layer.last_output_dim
                elif isinstance(layer, ODBatchNorm2d):
                    config[p][i]["in_dim"] = None
                    config[p][i]["out_dim"] = layer.p_to_num_features[p]
                elif isinstance(layer, torch.nn.BatchNorm2d):
                    pass
                else:
                    raise ValueError(f"Unsupported layer {layer.__class__.__name__}")
    for layer in layers:
        config["layer"].append(layer.__class__.__name__)
        if hasattr(layer, "p"):
            config["layer_p"].append(layer.p)
        else:
            config["layer_p"].append(None)
    return config

def parity_matrix(
    circ: QuantumScript, wire_order: Sequence | None = None
) -> tuple[TensorLike, PostprocessingFn]:

    def postprocessing_fn(tapes):
        # This is required in a qml.transforms.transform (see docs therein)
        circ = tapes[0]
        wires = circ.wires

        w_order = wire_order

        if w_order is None:
            w_order = wires

        if not qml.wires.Wires(w_order).contains_wires(wires):
            raise qml.wires.WireError(
                f"The provided wire_order {w_order} does not contain all wires of the circuit {wires}"
            )

        if any(op.name != "CNOT" for op in circ.operations):
            raise TypeError(
                f"parity_matrix requires all input circuits to consist solely of CNOT gates. Received circuit with the following gates: {circ.operations}"
            )

        wire_map = {wire: idx for idx, wire in enumerate(w_order)}

        P = np.eye(len(w_order), dtype=int)
        for op in circ.operations:
            control, target = op.wires
            P[wire_map[target]] += P[wire_map[control]]

        return P % 2

    return [circ], postprocessing_fn

def unpack_params(params, attr_name, buffer,
                  transfer_dtype, zero_fill, stream=None):
    if len(params) == 0:
        return
    xp = chainer.backend.get_array_module(getattr(params[0], attr_name))
    offset = 0
    for param in params:
        v = getattr(param, attr_name)
        if attr_name == 'grad' and v is None and zero_fill:
            v = param.xp.empty_like(param.data)
            setattr(param, attr_name, v)
        size = v.size * np.dtype(transfer_dtype).itemsize
        grad_dtype = v.dtype
        if grad_dtype != transfer_dtype:
            v = xp.array(v, copy=False, dtype=transfer_dtype)
        buffer.to_device(v, size, offset, stream)
        offset += size
        if grad_dtype != transfer_dtype:
            # avoid using setattr as ChainerX array cannot be directly updated
            getattr(param, attr_name)[...] = v.astype(grad_dtype)

def save_swarm_state(
    swarm_instance: Any,
    swarm_workspace_dir: str,
    state_data: Optional[Dict[str, Any]] = None,
) -> Optional[str]:
    if not swarm_workspace_dir:
        return None

    try:
        # Build state dictionary
        state_dict = {
            "timestamp": datetime.now().isoformat(),
            "swarm_name": getattr(swarm_instance, "name", "unnamed"),
            "swarm_id": getattr(swarm_instance, "id", None),
            "swarm_type": getattr(swarm_instance, "swarm_type", None),
        }

        # Add conversation history if available
        if hasattr(swarm_instance, "swarm") and hasattr(
            swarm_instance.swarm, "conversation"
        ):
            try:
                conversation = swarm_instance.swarm.conversation
                if hasattr(conversation, "to_dict"):
                    state_dict["conversation"] = (
                        conversation.to_dict()
                    )
                elif hasattr(conversation, "conversation_history"):
                    state_dict["conversation"] = (
                        conversation.conversation_history
                    )
            except Exception as e:
                logger.debug(f"Could not save conversation: {e}")

        # Add logs if available
        if hasattr(swarm_instance, "logs"):
            state_dict["logs"] = [
                log if not callable(log) else str(log)
                for log in swarm_instance.logs
            ]

        # Add additional state data if provided
        if state_data:
            state_dict.update(state_data)

        # Convert to JSON string
        state_json = json.dumps(state_dict, indent=2, default=str)

        # Save to file
        state_path = create_file_in_folder(
            swarm_workspace_dir, "state.json", state_json
        )

        if state_path:
            logger.debug(f"Saved swarm state to {state_path}")
        return state_path

    except Exception as e:
        logger.warning(f"Failed to save swarm state: {e}")
        return None

def fpg_step(tree, minsup, colnames, max_len, verbose):
    count = 0
    items = tree.nodes.keys()
    if tree.is_path():
        # If the tree is a path, we can combinatorally generate all
        # remaining itemsets without generating additional conditional trees
        size_remain = len(items) + 1
        if max_len:
            size_remain = max_len - len(tree.cond_items) + 1
        for i in range(1, size_remain):
            for itemset in itertools.combinations(items, i):
                count += 1
                support = min([tree.nodes[i][0].count for i in itemset])
                yield support, tree.cond_items + list(itemset)
    elif not max_len or max_len > len(tree.cond_items):
        for item in items:
            count += 1
            support = sum([node.count for node in tree.nodes[item]])
            yield support, tree.cond_items + [item]

    if verbose:
        tree.print_status(count, colnames)

    # Generate conditional trees to generate frequent itemsets one item larger
    if not tree.is_path() and (not max_len or max_len > len(tree.cond_items)):
        for item in items:
            cond_tree = tree.conditional_tree(item, minsup)
            for sup, iset in fpg_step(cond_tree, minsup, colnames, max_len, verbose):
                yield sup, iset

def parallel_imap_unordered(
    func: Callable[[_A], _R],
    iterable: Iterable[_A],
    max_parallel: Optional[int] = None,
    dir: Optional[str] = None,
) -> Iterator[_R]:
    if max_parallel is None:
        # Lazy import to save on startup time for metaflow as a whole
        from multiprocessing import cpu_count

        max_parallel = cpu_count()

    args_iter = iter(iterable)
    pids = [_spawn(func, arg, dir) for arg in islice(args_iter, max_parallel)]

    while pids:
        for idx, pid_info in enumerate(pids):
            pid, output_file = pid_info
            pid, exit_code = os.waitpid(pid, os.WNOHANG)
            if pid:
                pids.pop(idx)
                break
        else:
            time.sleep(0.1)  # Wait a bit before re-checking
            continue

        if exit_code:
            raise MulticoreException("Child failed")

        with open(output_file, "rb") as f:
            yield pickle.load(f)
        os.remove(output_file)

        arg = list(islice(args_iter, 1))
        if arg:
            pids.insert(0, _spawn(func, arg[0], dir))

def is_dynamic_block_child(block, include_reduce_output: Optional[bool] = None) -> bool:
    if not block:
        return False

    if block.is_dynamic_v2:
        return block.is_dynamic_child

    dynamic_or_child = []

    for upstream_block in block.upstream_blocks:
        if is_dynamic_block(upstream_block) or is_dynamic_block_child(
            upstream_block, include_reduce_output=include_reduce_output
        ):
            dynamic_or_child.append(upstream_block)

    if len(dynamic_or_child) == 0:
        return False

    if include_reduce_output:
        return len(dynamic_or_child) >= 1

    dynamic_or_child_with_reduce = list(
        filter(lambda x: should_reduce_output(x), dynamic_or_child)
    )

    return len(dynamic_or_child) > len(dynamic_or_child_with_reduce)

def vector(self):
        if not self._vector:
            # See the Vector class below = a dict with extra functionality (copy, norm).
            # When a document is added/deleted from a model, the cached vector is deleted.
            w = getattr(self.model, "weight", TF)
            if w not in (TF, TFIDF, IG, INFOGAIN, GR, GAINRATIO, BINARY):
                f = lambda w: float(self._terms[w]); w=None
            if w == BINARY:
                f = lambda w: int(self._terms[w] > 0)
            if w == TF:
                f = self.tf
            if w == TFIDF:
                f = self.tf_idf
            if w in (IG, INFOGAIN):
                f = self.model.ig
            if w in (GR, GAINRATIO):
                f = self.model.gr
            self._vector = Vector(((w, f(w)) for w in self.terms), weight=w)
        return self._vector

def get_orthogonal_matrix(self, mat):
        matrix = []
        for m in mat:
            if len(m) == 0:
                matrix.append([])
                continue
            if m.data.dtype != torch.float:
                float_data = False
                original_type = m.data.dtype
                original_device = m.data.device
                matrix.append(m.data.float())
            else:
                float_data = True
                matrix.append(m.data)

        final = []
        for m in matrix:
            if len(m) == 0:
                final.append([])
                continue
            try:
                _, Q = torch.linalg.eigh(m + 1e-30 * torch.eye(m.shape[0], device=m.device))
            except:
                _, Q = torch.linalg.eigh(m.to(torch.float64) + 1e-30 * torch.eye(m.shape[0], device=m.device))
                Q = Q.to(m.dtype)
            Q = torch.flip(Q, [1])

            if not float_data:
                Q = Q.to(original_device).type(original_type)
            final.append(Q)
        return final

def delete_message(self):
        dialog = self.window()

        # Find this message's index in the chat messages layout
        message_widgets = []
        for i in range(dialog.chat_messages_layout.count()):
            item = dialog.chat_messages_layout.itemAt(i)
            if (
                item
                and item.widget()
                and isinstance(item.widget(), ChatMessage)
            ):
                message_widgets.append(item.widget())

        if self in message_widgets:
            message_index = message_widgets.index(self)

            # Remove this message from the layout
            dialog.chat_messages_layout.removeWidget(self)

            # Update chat history
            if hasattr(dialog, "chat_history") and 0 <= message_index < len(
                dialog.chat_history
            ):
                dialog.chat_history.pop(message_index)

                # If this is a file-based chat, update the stored data
                if (
                    hasattr(dialog, "parent")
                    and callable(dialog.parent)
                    and dialog.parent()
                ):
                    parent = dialog.parent()
                    if hasattr(parent, "other_data") and hasattr(
                        parent, "filename"
                    ):
                        if (
                            parent.filename
                            and "chat_history" in parent.other_data
                        ):
                            parent.other_data["chat_history"] = (
                                dialog.chat_history
                            )
                            parent.set_dirty()

            # Delete the widget
            self.setParent(None)
            self.deleteLater()

def seq_kernel(
    X,
    kernelfun=None,
    L=2,
    D=1,
    theta=1.0,
    normalize=False,
    lowrank=False,
    rankbound=float("inf"),
):
    N = np.shape(X)[0]
    KSeq = np.zeros((N, N))

    if kernelfun is None:
        kernelfun = partial(k_euclid, scale=1)

    if not lowrank:
        if D == 1:
            for row1ind in range(N):
                for row2ind in range(row1ind + 1):
                    KSeq[row1ind, row2ind] = sqize_kernel(
                        K=kernelfun(X[row1ind].T, X[row2ind].T),
                        L=L,
                        theta=theta,
                        normalize=normalize,
                    )
        else:
            for row1ind in range(N):
                for row2ind in range(row1ind + 1):
                    KSeq[row1ind, row2ind] = sqize_kernel_ho(
                        K=kernelfun(X[row1ind].T, X[row2ind].T),
                        L=L,
                        D=D,
                        theta=theta,
                        normalize=normalize,
                    )
    else:
        R = sqize_kernel_low_rank_fast(
            K=X.transpose([0, 2, 1]),
            L=L,
            theta=theta,
            normalize=normalize,
            rankbound=rankbound,
        )
        KSeq = np.inner(R, R)
        # todo: kernelfun gives back a LRdec object
        #  for now, linear low-rank approximation is done
        # KSeq[row1ind,row2ind] = qqize_kernel_low_rank(
        #   kernelfun(X[row1ind].T,X[row2ind].T),L,theta,normalize = True)
    return mirror(KSeq)

def slice_bounds(sequence, slice_obj, allow_step=False):
    start, stop = (slice_obj.start, slice_obj.stop)

    # If allow_step is true, then include the step in our return
    # value tuple.
    if allow_step:
        step = slice_obj.step
        if step is None:
            step = 1
        # Use a recursive call without allow_step to find the slice
        # bounds.  If step is negative, then the roles of start and
        # stop (in terms of default values, etc), are swapped.
        if step < 0:
            start, stop = slice_bounds(sequence, slice(stop, start))
        else:
            start, stop = slice_bounds(sequence, slice(start, stop))
        return start, stop, step

    # Otherwise, make sure that no non-default step value is used.
    elif slice_obj.step not in (None, 1):
        raise ValueError(
            "slices with steps are not supported by %s" % sequence.__class__.__name__
        )

    # Supply default offsets.
    if start is None:
        start = 0
    if stop is None:
        stop = len(sequence)

    # Handle negative indices.
    if start < 0:
        start = max(0, len(sequence) + start)
    if stop < 0:
        stop = max(0, len(sequence) + stop)

    # Make sure stop doesn't go past the end of the list.  Note that
    # we avoid calculating len(sequence) if possible, because for lazy
    # sequences, calculating the length of a sequence can be expensive.
    if stop > 0:
        try:
            sequence[stop - 1]
        except IndexError:
            stop = len(sequence)

    # Make sure start isn't past stop.
    start = min(start, stop)

    # That's all folks!
    return start, stop

def post_process_grounded_object_detection(
        self,
        outputs: "OwlViTObjectDetectionOutput",
        threshold: float = 0.1,
        target_sizes: TensorType | list[tuple] | None = None,
        text_labels: list[list[str]] | None = None,
    ):
        output = self.image_processor.post_process_object_detection(
            outputs=outputs, threshold=threshold, target_sizes=target_sizes
        )

        if text_labels is not None and len(text_labels) != len(output):
            raise ValueError("Make sure that you pass in as many lists of text labels as images")

        # adding text labels to the output
        if text_labels is not None:
            for image_output, image_text_labels in zip(output, text_labels):
                object_text_labels = [image_text_labels[i] for i in image_output["labels"]]
                image_output["text_labels"] = object_text_labels
        else:
            for image_output in output:
                image_output["text_labels"] = None

        return output

def read_notebook(path):
    # Load the Jupyter Notebook
    with open(path, "r") as notebook_file:
        notebook_content = nbformat.read(notebook_file, as_version=4)

    # Search for parameters and store them in a dictionary
    results = {}
    for cell in notebook_content.cells:
        if cell.cell_type == "code" and "outputs" in cell:
            for outputs in cell.outputs:
                if "metadata" in outputs and "notebook_utils" in outputs.metadata:
                    name = outputs.data[NOTEBOOK_OUTPUT_CONTENT_TYPE]["name"]
                    data = outputs.data[NOTEBOOK_OUTPUT_CONTENT_TYPE]["data"]
                    results[name] = data
    return results

def cross_entropy_with_probs(
    input: torch.Tensor,
    target: torch.Tensor,
    weight: Optional[torch.Tensor] = None,
    reduction: str = "mean",
) -> torch.Tensor:
    num_points, num_classes = input.shape
    # Note that t.new_zeros, t.new_full put tensor on same device as t
    cum_losses = input.new_zeros(num_points)
    for y in range(num_classes):
        target_temp = input.new_full((num_points,), y, dtype=torch.long)
        y_loss = F.cross_entropy(input, target_temp, reduction="none")
        if weight is not None:
            y_loss = y_loss * weight[y]
        cum_losses += target[:, y].float() * y_loss

    if reduction == "none":
        return cum_losses
    elif reduction == "mean":
        return cum_losses.mean()
    elif reduction == "sum":
        return cum_losses.sum()
    else:
        raise ValueError("Keyword 'reduction' must be one of ['none', 'mean', 'sum']")

def from_feast_to_spark_type(feast_type) -> Optional[SparkDataType]:
    from feast.types import (
        Array,
        PrimitiveFeastType,
        Set,
        Struct,
    )

    if isinstance(feast_type, Struct):
        from pyspark.sql.types import StructField

        spark_fields = []
        for name, ftype in feast_type.fields.items():
            spark_type = from_feast_to_spark_type(ftype)
            if spark_type is None:
                return None
            spark_fields.append(StructField(name, spark_type, nullable=True))
        return StructType(spark_fields)

    if isinstance(feast_type, PrimitiveFeastType):
        mapping = {
            PrimitiveFeastType.BYTES: BinaryType(),
            PrimitiveFeastType.STRING: StringType(),
            PrimitiveFeastType.INT32: IntegerType(),
            PrimitiveFeastType.INT64: LongType(),
            PrimitiveFeastType.FLOAT64: DoubleType(),
            PrimitiveFeastType.FLOAT32: FloatType(),
            PrimitiveFeastType.BOOL: BooleanType(),
            PrimitiveFeastType.UNIX_TIMESTAMP: TimestampType(),
            PrimitiveFeastType.MAP: MapType(StringType(), StringType()),
            PrimitiveFeastType.JSON: StringType(),
        }
        return mapping.get(feast_type)

    if isinstance(feast_type, Array):
        base_type = feast_type.base_type
        if isinstance(base_type, Struct):
            inner = from_feast_to_spark_type(base_type)
            return ArrayType(inner) if inner else None
        if isinstance(base_type, PrimitiveFeastType):
            if base_type == PrimitiveFeastType.MAP:
                return ArrayType(MapType(StringType(), StringType()))
            inner = from_feast_to_spark_type(base_type)
            return ArrayType(inner) if inner else None

    if isinstance(feast_type, Set):
        inner = from_feast_to_spark_type(feast_type.base_type)
        return ArrayType(inner) if inner else None

    return None

def compress(condition, a, axis=None):
  condition = asarray(condition, dtype=bool)
  a = asarray(a)

  if condition.ndim != 1:
    raise ValueError('condition must be a 1-d array.')
  # `np.compress` treats scalars as 1-d arrays.
  if a.ndim == 0:
    a = ravel(a)

  if axis is None:
    a = ravel(a)
    axis = 0

  if axis < 0:
    axis += a.ndim

  assert axis >= 0 and axis < a.ndim

  # `tf.boolean_mask` requires the first dimensions of array and condition to
  # match. `np.compress` pads condition with False when it is shorter.
  condition_t = condition.data
  a_t = a.data
  if condition.shape[0] < a.shape[axis]:
    padding = tf.fill([a.shape[axis] - condition.shape[0]], False)
    condition_t = tf.concat([condition_t, padding], axis=0)
  return utils.tensor_to_ndarray(tf.boolean_mask(tensor=a_t, mask=condition_t,
                                                 axis=axis))

def leading_dim(self):
        if self.A.layout == LayoutType.RowMajor:
            lda = "K"
        elif self.A.layout == LayoutType.ColumnMajor:
            lda = "M"
        else:
            ValueError("The layout of A is not implemented.")

        if self.B.layout == LayoutType.RowMajor:
            ldb = "N"
        elif self.B.layout == LayoutType.ColumnMajor:
            ldb = "K"
        else:
            ValueError("The layout of B is not implemented.")

        if self.C.layout == LayoutType.RowMajor:
            ldc = "N"
        elif self.C.layout == LayoutType.ColumnMajor:
            ldc = "M"
        else:
            ValueError("The layout of B is not implemented.")

        return substitute_template(
            "int lda = ${lda_val};\n\tint ldb = ${ldb_val};\n\tint ldc = ${ldc_val};\n",
            {"lda_val": lda, "ldb_val": ldb, "ldc_val": ldc},
        )

def call_hook(self, hook_name, input_object, position=None, *args, **kwargs):
        import sys

        if hook_name not in self.all_hook_names:
            raise AttributeError("No such hook %r" % hook_name)
        hook = getattr(self, hook_name + "_hook")
        if not callable(hook):
            raise TypeError("Hook is not callable: %r" % (hook,))
        try:
            rval = hook(input_object, *args, **kwargs)
        except JSONSkipHook:
            raise  # Do nothing
        except Exception as err:
            exc_info = sys.exc_info()
            if hook_name.startswith("encode_"):
                ex_class = JSONEncodeHookError
            else:
                ex_class = JSONDecodeHookError

            if isinstance(err, JSONStopProcessing):
                severity = "fatal"
            else:
                severity = "error"

            newerr = ex_class(
                hook_name,
                exc_info,
                input_object,
                *args,
                position=position,
                severity=severity,
            )

            # Simulate Python 3's: "raise X from Y" exception chaining
            newerr.__cause__ = err
            newerr.__traceback__ = exc_info[2]
            raise newerr
        return rval

def load_state_dict(checkpoint_file: Union[str, os.PathLike]):
    if checkpoint_file.endswith(".safetensors") and is_safetensors_available():
        # Check format of the archive
        with safe_open(checkpoint_file, framework="pt") as f:
            metadata = f.metadata()
        if metadata.get("format") not in ["pt", "tf", "flax"]:
            raise OSError(
                f"The safetensors archive passed at {checkpoint_file} does not contain the valid metadata. Make sure "
                "you save your model with the `save_pretrained` method."
            )
        elif metadata["format"] != "pt":
            raise NotImplementedError(
                f"Conversion from a {metadata['format']} safetensors archive to PyTorch is not implemented yet."
            )
        return safe_load_file(checkpoint_file)
    try:
        return torch.load(checkpoint_file, map_location="cpu")
    except Exception as e:
        try:
            with open(checkpoint_file) as f:
                if f.read().startswith("version"):
                    raise OSError(
                        "You seem to have cloned a repository without having git-lfs installed. Please install "
                        "git-lfs and run `git lfs install` followed by `git lfs pull` in the folder "
                        "you cloned."
                    )
                else:
                    raise ValueError(
                        f"Unable to locate the file {checkpoint_file} which is necessary to load this pretrained "
                        "model. Make sure you have saved the model properly."
                    ) from e
        except (UnicodeDecodeError, ValueError):
            raise OSError(
                f"Unable to load weights from pytorch checkpoint file for '{checkpoint_file}' "
                f"at '{checkpoint_file}'. "
                "If you tried to load a PyTorch model from a TF 2.0 checkpoint, please set from_tf=True."
            )

def compute_min_return_path(
    cost_matrix: np.ndarray, bounding_matrix: np.ndarray
) -> list[tuple]:
    x_size, y_size = cost_matrix.shape

    for i in range(x_size):
        for j in range(y_size):
            if not np.isfinite(bounding_matrix[i, j]):
                cost_matrix[i, j] = np.inf

    i = x_size - 1
    j = y_size - 1
    alignment = []
    while True:
        alignment.append((i, j))

        if alignment[-1] == (0, 0):
            break

        arr = np.array(
            [
                cost_matrix[i - 1, j - 1],
                cost_matrix[i - 1, j],
                cost_matrix[i, j - 1],
            ]
        )
        min_index = np.argmin(arr)

        if min_index == 0:
            i = i - 1
            j = j - 1
        elif min_index == 1:
            i = i - 1
        else:
            j = j - 1

    return alignment[::-1]

def history(
        self,
        samples: int = 500,
        keys: list[str] | None = None,
        x_axis: str = "_step",
        pandas: bool = True,
        stream: Literal["default", "system"] = "default",
    ) -> list[dict[str, Any]] | pd.DataFrame:
        if keys is not None and not isinstance(keys, list):
            wandb.termerror("keys must be specified in a list")
            return []
        if keys is not None and len(keys) > 0 and not isinstance(keys[0], str):
            wandb.termerror("keys argument must be a list of strings")
            return []

        if keys and stream != "default":
            wandb.termerror("stream must be default when specifying keys")
            return []
        elif keys:
            lines = self._sampled_history(keys=keys, x_axis=x_axis, samples=samples)
        else:
            lines = self._full_history(samples=samples, stream=stream)
        if pandas:
            pd = util.get_module("pandas")
            if pd:
                lines = pd.DataFrame.from_records(lines)
            else:
                wandb.termwarn("Unable to load pandas, call history with pandas=False")
        return lines

def conv2d_hwcn_python(a_np, w_np, stride, padding):
    in_height, in_width, in_channel, batch = a_np.shape
    kernel_h, kernel_w, _, num_filter = w_np.shape
    if isinstance(stride, int):
        stride_h = stride_w = stride
    else:
        stride_h, stride_w = stride

    pad_top, pad_left, pad_bottom, pad_right = get_pad_tuple(padding, (kernel_h, kernel_w))
    pad_h = pad_top + pad_bottom
    pad_w = pad_left + pad_right
    # compute the output shape
    out_channel = num_filter
    out_height = (in_height - kernel_h + pad_h) // stride_h + 1
    out_width = (in_width - kernel_w + pad_w) // stride_w + 1
    # change the layout from HWCN to NCHW
    at = a_np.transpose((3, 2, 0, 1))
    wt = w_np.transpose((3, 2, 0, 1))
    bt = np.zeros((batch, out_channel, out_height, out_width))
    # computation
    for n in range(batch):
        for f in range(out_channel):
            for c in range(in_channel):
                if pad_h > 0 or pad_w > 0:
                    apad = np.zeros((in_height + pad_h, in_width + pad_w))
                    apad[pad_top : pad_top + in_height, pad_left : pad_left + in_width] = at[n, c]
                else:
                    apad = at[n, c]
                out = scipy.signal.convolve2d(apad, np.rot90(np.rot90(wt[f, c])), mode="valid")
                bt[n, f] += out[::stride_h, ::stride_w]
    return bt.transpose((2, 3, 1, 0))

async def bedrock_weather_tool_handler(
        response: ConversationMessage,
        conversation: list[dict[str, Any]]
    ) -> ConversationMessage:
        response_content_blocks = response.content
        tool_results = []

        if not response_content_blocks:
            raise ValueError("No content blocks in response")

        for content_block in response_content_blocks:
            # Handle regular text content if present
            if "text" in content_block:
                continue

            # Process tool use requests
            if "toolUse" in content_block:
                tool_use_block = content_block["toolUse"]
                tool_use_name = tool_use_block.get("name")

                if tool_use_name == "get_weather":
                    tool_response = get_weather(tool_use_block["input"].get('city'))
                    tool_results.append({
                        "toolResult": {
                            "toolUseId": tool_use_block["toolUseId"],
                            "content": [{"json": {"result": tool_response}}],
                        }
                    })

        return ConversationMessage(
            role=ParticipantRole.USER.value,
            content=tool_results
        )

def solarize(
    input: torch.Tensor,
    thresholds: Union[float, torch.Tensor] = 0.5,
    additions: Optional[Union[float, torch.Tensor]] = None,
) -> torch.Tensor:
    if not isinstance(input, torch.Tensor):
        raise TypeError(f"Input type is not a torch.Tensor. Got {type(input)}")

    if not isinstance(thresholds, (float, torch.Tensor)):
        raise TypeError(f"The factor should be either a float or torch.Tensor. Got {type(thresholds)}")

    if isinstance(thresholds, float):
        thresholds = torch.as_tensor(thresholds)

    if additions is not None:
        if not isinstance(additions, (float, torch.Tensor)):
            raise TypeError(f"The factor should be either a float or torch.Tensor. Got {type(additions)}")

        if isinstance(additions, float):
            additions = torch.as_tensor(additions)

        if not torch.all((additions < 0.5) * (additions > -0.5)):
            raise AssertionError(f"The value of 'addition' is between -0.5 and 0.5. Got {additions}.")

        if isinstance(additions, torch.Tensor) and len(additions.shape) != 0:
            if not (input.size(0) == len(additions) and len(additions.shape) == 1):
                raise AssertionError(f"additions must be a 1-d vector of shape ({input.size(0)},). Got {additions}")
            # TODO: I am not happy about this line, but no easy to do batch-wise operation
            additions = additions.to(input.device).to(input.dtype)
            additions = torch.stack([x.expand(*input.shape[-3:]) for x in additions])
        input = input + additions
        input = input.clamp(0.0, 1.0)

    return _solarize(input, thresholds)

def parse_tweets_set(
    filename, label, word_tokenizer=None, sent_tokenizer=None, skip_header=True
):
    tweets = []
    if not sent_tokenizer:
        sent_tokenizer = PunktTokenizer()

    with codecs.open(filename, "rt") as csvfile:
        reader = csv.reader(csvfile)
        if skip_header:
            next(reader, None)  # skip the header
        i = 0
        for tweet_id, text in reader:
            # text = text[1]
            i += 1
            sys.stdout.write(f"Loaded {i} tweets\r")
            # Apply sentence and word tokenizer to text
            if word_tokenizer:
                tweet = [
                    w
                    for sent in sent_tokenizer.tokenize(text)
                    for w in word_tokenizer.tokenize(sent)
                ]
            else:
                tweet = text
            tweets.append((tweet, label))

    print(f"Loaded {i} tweets")
    return tweets

def torch_load(self, filename: str) -> torch.Tensor:
        if not self.exists(filename):
            error_msg = f"{filename} not found."
            logger.error(error_msg)
            raise FileNotFoundError(error_msg)

        try:
            with self.read(filename, as_byteIO=True) as stored_tensor:
                if self.compress_cache:
                    stored_tensor = self._decompress_torch(stored_tensor)
                stored_tensor.seek(0)
                loaded_tensor = torch.load(stored_tensor, map_location="cpu")
            return loaded_tensor
        except Exception as e:
            logger.error(f"Failed to load torch file '{filename}': {e}", exc_info=True)
            if "invalid load key" in str(e):
                try:
                    self.delete(filename)
                    logger.info(f"Deleted corrupt torch file: {filename}")
                except Exception as del_e:
                    logger.error(f"Failed to delete corrupt torch file {filename}: {del_e}")
            raise e

def topological_ordering(self):
        ordering = []
        visited = set()

        def dfs(v_i, path=None):
            """A simple DFS helper routine"""
            path = set([v_i]) if path is None else path
            for nbr_i in self.get_neighbors(v_i):
                if nbr_i in path:
                    return True  # cycle detected!
                elif nbr_i not in visited:
                    visited.add(nbr_i)
                    path.add(nbr_i)
                    is_cyclic = dfs(nbr_i, path)
                    if is_cyclic:
                        return True

            # insert to the beginning of the ordering
            ordering.insert(0, v_i)
            path -= set([v_i])
            return False

        for s_i in self.indices:
            if s_i not in visited:
                visited.add(s_i)
                is_cyclic = dfs(s_i)

                if is_cyclic:
                    return None

        return ordering

def apply_gt_class_remap(
    source: Path,
    remap: dict[int, int],
    distractor_ids: Optional[list[int]] = None,
) -> None:
    distractor_set = set(distractor_ids or [])
    keep_ids = set(remap.keys()) | distractor_set

    gt_files = list(source.glob("*/gt/gt_temp.txt"))
    if not gt_files:
        LOGGER.warning(f"apply_gt_class_remap: no gt_temp.txt files found under {source}")
        return

    for gt_file in gt_files:
        try:
            data = np.loadtxt(gt_file, delimiter=",")
        except Exception as exc:
            LOGGER.warning(f"apply_gt_class_remap: could not read {gt_file}: {exc}")
            continue

        if data.size == 0:
            continue

        if data.ndim == 1:
            data = data.reshape(1, -1)

        class_col = data[:, 7].astype(int)
        data = data[np.isin(class_col, list(keep_ids))]

        if data.size == 0:
            np.savetxt(gt_file, data, delimiter=",")
            continue

        class_col = data[:, 7].astype(int)
        for old_id, new_id in remap.items():
            data[class_col == old_id, 7] = new_id

        np.savetxt(gt_file, data, delimiter=",", fmt="%g")

def solve_sum_einsum(parsed_vectors, vars):
    def solve_sum_einsum_one_step(src_axes, used_by_other_axes, x):
        dst_axes = []
        for axis in src_axes:
            if axis not in used_by_other_axes:
                continue
            dst_axes.append(axis)
        summed_axis_indices = [i for i in range(len(src_axes)) if src_axes[i] not in dst_axes]
        if summed_axis_indices:
            x = mb.reduce_sum(x=x, axes=summed_axis_indices)
        return dst_axes, x

    ret_parsed_vectors = []
    parsed_vectors = list(parsed_vectors)
    for i, var in enumerate(vars):
        used_by_other_axes = []
        for j, parsed_vector in enumerate(parsed_vectors):
            if i != j:
                used_by_other_axes += parsed_vector
        dst_axes, var = solve_sum_einsum_one_step(parsed_vectors[i], used_by_other_axes, vars[i])
        ret_parsed_vectors.append(dst_axes)
        vars[i] = var
    ret_parsed_vectors.append(parsed_vectors[-1])
    return ret_parsed_vectors, vars

def encode(text):
  if not text:
    return []
  ret = []
  token_start = 0
  # Classify each character in the input string
  is_alnum = [c in _ALPHANUMERIC_CHAR_SET for c in text]
  for pos in range(1, len(text)):
    if is_alnum[pos] != is_alnum[pos - 1]:
      token = text[token_start:pos]
      if token != u" " or token_start == 0:
        ret.append(token)
      token_start = pos
  final_token = text[token_start:]
  ret.append(final_token)
  return ret

def get_merged_mask(pred1: ObjectPrediction, pred2: ObjectPrediction) -> Mask:
    mask1 = pred1.mask
    mask2 = pred2.mask

    if mask1 is None or mask2 is None:
        raise ValueError("Both predictions must have masks to merge them")

    # buffer(0) is a quickhack to fix invalid polygons most of the time
    poly1 = get_shapely_multipolygon(mask1.segmentation).buffer(0)
    poly2 = get_shapely_multipolygon(mask2.segmentation).buffer(0)

    if poly1.is_empty:
        poly1 = coco_segmentation_to_shapely(mask1.segmentation)
    if poly2.is_empty:
        poly2 = coco_segmentation_to_shapely(mask2.segmentation)

    union_poly = poly1.union(poly2)
    if not hasattr(union_poly, "geoms"):
        union_poly = MultiPolygon([union_poly])
    else:
        union_poly = MultiPolygon([g.buffer(0) for g in union_poly.geoms if isinstance(g, Polygon)])
    union = ShapelyAnnotation(multipolygon=union_poly).to_coco_segmentation()
    return Mask(
        segmentation=union,  # type: ignore[arg-type]
        full_shape=mask1.full_shape,
        shift_amount=mask1.shift_amount,
    )

def using(_other, **kwargs):
    gt_kwargs = {}
    if 'state' in kwargs:
        s = kwargs.pop('state')
        if isinstance(s, (list, tuple)):
            gt_kwargs['stack'] = s
        else:
            gt_kwargs['stack'] = ('root', s)

    if _other is this:
        def callback(lexer, match, ctx=None):
            # if keyword arguments are given the callback
            # function has to create a new lexer instance
            if kwargs:
                # XXX: cache that somehow
                kwargs.update(lexer.options)
                lx = lexer.__class__(**kwargs)
            else:
                lx = lexer
            s = match.start()
            for i, t, v in lx.get_tokens_unprocessed(match.group(), **gt_kwargs):
                yield i + s, t, v
            if ctx:
                ctx.pos = match.end()
    else:
        def callback(lexer, match, ctx=None):
            # XXX: cache that somehow
            kwargs.update(lexer.options)
            lx = _other(**kwargs)

            s = match.start()
            for i, t, v in lx.get_tokens_unprocessed(match.group(), **gt_kwargs):
                yield i + s, t, v
            if ctx:
                ctx.pos = match.end()
    return callback

def read_message():
    global _use_ndjson

    line = sys.stdin.readline()
    if not line:
        return None

    line = line.decode('utf-8').rstrip('\r\n')

    if line.lower().startswith("content-length:"):
        try:
            content_length = int(line.split(":", 1)[1].strip())
        except ValueError:
            return None

        while True:
            hdr = sys.stdin.readline()
            if not hdr:
                return None
            hdr = hdr.decode('utf-8').rstrip('\r\n')
            if hdr == "":
                break

        body = sys.stdin.read(content_length)
        try:
            return json.loads(body.decode('utf-8'))
        except Exception:
            return None

    elif line.startswith("{") or line.startswith("["):
        _use_ndjson = True
        try:
            return json.loads(line)
        except Exception:
            return None

    return None

def score_dataset(model, dataset, label_map=None,
                  remap_labels=None, forgive_unmapped_labels=False):
    model.eval()
    if label_map is None:
        label_map = {x: y for (y, x) in enumerate(model.labels)}
    correct = 0
    dataset_lengths = data.sort_dataset_by_len(dataset)

    for length in dataset_lengths.keys():
        # TODO: possibly break this up into smaller batches
        batch = dataset_lengths[length]
        expected_labels = [label_map[x.sentiment] for x in batch]

        output = model(batch)

        for i in range(len(expected_labels)):
            predicted = torch.argmax(output[i])
            predicted_label = predicted.item()
            if remap_labels:
                if predicted_label in remap_labels:
                    predicted_label = remap_labels[predicted_label]
                else:
                    found = False
                    if forgive_unmapped_labels:
                        items = []
                        for j in range(len(output[i])):
                            items.append((output[i][j].item(), j))
                        items.sort(key=lambda x: -x[0])
                        for _, item in items:
                            if item in remap_labels:
                                predicted_label = remap_labels[item]
                                found = True
                                break
                    # if slack guesses allowed, none of the existing
                    # labels matched, so we count it wrong.  if slack
                    # guesses not allowed, just count it wrong
                    if not found:
                        continue

            if predicted_label == expected_labels[i]:
                correct = correct + 1
    return correct

def log_metrics(self, metrics, epoch):
        if self.csv:
            keys, vals = list(metrics.keys()), list(metrics.values())
            n = len(metrics) + 1  # number of cols
            s = "" if self.csv.exists() else (("%23s," * n % tuple(["epoch", *keys])).rstrip(",") + "\n")  # header
            with open(self.csv, "a") as f:
                f.write(s + ("%23.5g," * n % tuple([epoch, *vals])).rstrip(",") + "\n")

        if self.tb:
            for k, v in metrics.items():
                self.tb.add_scalar(k, v, epoch)

        if self.wandb:
            self.wandb.log(metrics, step=epoch)

def process_multiclass_components(
    outputs: torch.Tensor,
    targets: torch.Tensor,
    argmax_dim: int = -1,
    num_classes: Optional[int] = None,
) -> Tuple[torch.Tensor, torch.Tensor, int]:
    # @TODO: better multiclass preprocessing, label -> class_id mapping
    if not torch.is_tensor(outputs):
        outputs = torch.from_numpy(np.array(outputs))
    if not torch.is_tensor(targets):
        targets = torch.from_numpy(np.array(targets))

    if outputs.dim() == targets.dim() + 1:
        # looks like we have scores/probabilities in our outputs
        # let's convert them to final model predictions
        num_classes = max(
            outputs.shape[argmax_dim], int(targets.max().detach().item() + 1)
        )
        outputs = torch.argmax(outputs, dim=argmax_dim)
    if num_classes is None:
        # as far as we expect the outputs/targets tensors to be int64
        # we could find number of classes as max available number
        num_classes = max(
            int(outputs.max().detach().item() + 1),
            int(targets.max().detach().item() + 1),
        )

    if outputs.dim() == 1:
        outputs = outputs.view(-1, 1)
    elif outputs.dim() == 2 and outputs.size(0) == 1:
        # transpose case
        outputs.permute(1, 0)
    else:
        assert outputs.size(1) == 1 and outputs.dim() == 2, (
            "Wrong `outputs` shape, "
            "expected 1D or 2D with size 1 in the second dim "
            "got {}".format(outputs.shape)
        )

    if targets.dim() == 1:
        targets = targets.view(-1, 1)
    elif targets.dim() == 2 and targets.size(0) == 1:
        # transpose case
        targets.permute(1, 0)
    else:
        assert targets.size(1) == 1 and targets.dim() == 2, (
            "Wrong `outputs` shape, " "expected 1D or 2D with size 1 in the second dim"
        )

    return outputs, targets, num_classes

def fit(
        self,
        series: TimeSeriesLike,
        past_covariates: TimeSeriesLike | None = None,
        future_covariates: TimeSeriesLike | None = None,
        verbose: bool | None = None,
    ) -> "GlobalForecastingModel":

        if isinstance(series, TimeSeries):
            # if only one series is provided, save it for prediction time (including covariates, if available)
            self.training_series = series
            if past_covariates is not None:
                self.past_covariate_series = past_covariates
            if future_covariates is not None:
                self.future_covariate_series = future_covariates
            if (
                series.static_covariates is not None
                and self.supports_static_covariates
                and self.considers_static_covariates
            ):
                self.static_covariates = series.static_covariates
        else:
            if past_covariates is not None:
                self._expect_past_covariates = True
            if future_covariates is not None:
                self._expect_future_covariates = True
            if (
                get_single_series(series).static_covariates is not None
                and self.supports_static_covariates
                and self.considers_static_covariates
            ):
                self.static_covariates = series[0].static_covariates
                self._expect_static_covariates = True

        if past_covariates is not None:
            self._uses_past_covariates = True
        if future_covariates is not None:
            self._uses_future_covariates = True
        if (
            get_single_series(series).static_covariates is not None
            and self.supports_static_covariates
            and self.considers_static_covariates
        ):
            self._uses_static_covariates = True
        self._fit_called = True
        return self

def turn_operator_to_identity(self, t_op: tflite_model.Operator):
        if len(t_op.tmp_inputs) != 1:
            logger.e(
                logger.Code.INTERNAL_ERROR,
                "turn_operator_to_identity(): Operator doesn't have 1 input!",
            )

        if len(t_op.tmp_outputs) != 1:
            logger.e(
                logger.Code.INTERNAL_ERROR,
                "turn_operator_to_identity(): Operator doesn't have 1 output!",
            )

        if t_op.tmp_inputs[0].rank <= 6:
            # Create regular `Transpose`.
            t_op.builtin_options = transpose_options.Transpose()
        else:
            # 6D and bigger require the Flex delegate `Transpose`.
            if t_op.tmp_inputs[0].quantization is not None:
                logger.e(
                    logger.Code.CONVERSION_IMPOSSIBLE,
                    "Conversion requires the addition of a `Transpose` operator with more than 6 dimensions, "
                    "which doesn't support quantization.",
                )

            if not self.conversion_config.allow_select_ops:
                logger.e(
                    logger.Code.CONVERSION_IMPOSSIBLE,
                    "Conversion requires the addition of a `Transpose` operator with more than 6 dimensions, "
                    "which requires the use of Flex delegate. "
                    + logger.Message.ALLOW_SELECT_OPS,
                )

            t_op.custom_options = FlexTranspose()

        rank = t_op.tmp_inputs[0].rank
        identity = np.asarray(range(rank), np.int32)
        identity_tensor = self.create_tensor_for_data(identity, "identity")
        t_op.tmp_inputs.append(identity_tensor)

def from_model(cls, model_space: ModelSpace, evaluator: Evaluator | None = None,
                   dummy_input: tuple[int, ...] | tuple[torch.Tensor, ...] | list[int] | None = None) -> GraphModelSpace:
        if isinstance(dummy_input, list):
            dummy_input = tuple(dummy_input)

        try:
            script_module = torch.jit.script(model_space)
        except:
            _logger.error('Your base model cannot be parsed by torch.jit.script, please fix the following error:')
            raise
        if dummy_input is not None:
            if isinstance(dummy_input, tuple) and all(isinstance(i, int) for i in dummy_input):
                dummy_input = torch.randn(*dummy_input)  # type: ignore
            converter = GraphConverterWithShape()
            base_model_ir = cls.convert_to_graph(script_module, model_space, converter, dummy_input=dummy_input)
        else:
            base_model_ir = cls.convert_to_graph(script_module, model_space)

        mutator_generated = len(base_model_ir.mutators) > 0

        if hasattr(model_space, 'mutables'):
            for mutable in model_space.mutables:
                if isinstance(mutable, Mutator) and mutator_generated:
                    base_model_ir.mutators.append(mutable)
                elif not isinstance(mutable, Mutator):
                    _logger.warning(f'Mutable is not a mutator. Will be ignored: {mutable}')

        base_model_ir.evaluator = evaluator

        mutators = process_inline_mutation(base_model_ir)
        if len(base_model_ir.mutators) > 0 and mutators:
            _logger.warning('Some mutators have been generated automatically. '
                            'We do not recommend a mixed usage of generated mutator and manually defined mutator, '
                            'because sometimes it induces unexpected side effects.')
        base_model_ir.mutators.extend(mutators)

        return base_model_ir

def build_watch_args(self):
        watch_args = {}

        # Check each parameter and append to watch_args if present
        if hasattr(self.config, 'batch_size') and self.config.batch_size is not None:
            watch_args['batch_size'] = self.config.batch_size

        if hasattr(self.config, 'pipeline') and self.config.pipeline is not None:
            watch_args['pipeline'] = self.config.pipeline

        if hasattr(self.config, 'operation_time') and self.config.operation_time is not None:
            watch_args['operation_time'] = self.config.operation_time

        if hasattr(self.config, 'start_after') and self.config.start_after is not None:
            watch_args['start_after'] = self.config.start_after

        if hasattr(self.config, 'full_document'):
            watch_args['full_document'] = self.config.full_document

        return watch_args

async def send(self, input_data: BidiAgentInput | dict[str, Any]) -> None:
        if not self._started:
            raise RuntimeError("agent not started | call start before sending")

        input_event: BidiInputEvent

        if isinstance(input_data, str):
            input_event = BidiTextInputEvent(text=input_data)

        elif isinstance(input_data, BidiInputEvent):
            input_event = input_data

        elif isinstance(input_data, dict) and "type" in input_data:
            input_type = input_data["type"]
            input_data = {key: value for key, value in input_data.items() if key != "type"}
            if input_type == "bidi_text_input":
                input_event = BidiTextInputEvent(**input_data)
            elif input_type == "bidi_audio_input":
                input_event = BidiAudioInputEvent(**input_data)
            elif input_type == "bidi_image_input":
                input_event = BidiImageInputEvent(**input_data)
            else:
                raise ValueError(f"input_type=<{input_type}> | input type not supported")

        else:
            raise ValueError("invalid input | must be str, BidiInputEvent, or event dict")

        await self._loop.send(input_event)

def save(self, path):
        self.path = path
        if not os.path.isdir(self.path):
            os.makedirs(self.path)

        for k in self.G.keys():
            with open(os.path.join(self.path, str(k) + ".json"), "w") as fp:
                if isinstance(self.G[k], list):
                    for l in self.G[k]:
                        json.dump(l, fp)
                        fp.write("\n")
                elif isinstance(self.G[k], OrderedDict) or isinstance(self.G[k], dict):
                    json.dump(self.G[k], fp)
                else:
                    print(
                        "type(G[",
                        k,
                        "]): unexpected type",
                        type(self.G[k]).__name__,
                        ", stopping.",
                    )
                    raise ()

def add_edge(self, start, end, prob):
		if self.distributions is None:
			raise ValueError("Must add distributions before edges.")

		n = self.n_distributions

		if start == self.start:
			if self.starts is None:
				self.starts = torch.empty(n, dtype=self.dtype, 
					device=self.device) - inf

			idx = self.distributions.index(end)
			self.starts[idx] = math.log(prob)

		elif end == self.end:
			if self.ends is None:
				self.ends = torch.empty(n, dtype=self.dtype, 
					device=self.device) - inf

			idx = self.distributions.index(start)
			self.ends[idx] = math.log(prob)

		else:
			if self.edges is None:
				self.edges = torch.empty((n, n), dtype=self.dtype, 
					device=self.device) - inf

			idx1 = self.distributions.index(start)
			idx2 = self.distributions.index(end)

			self.edges[idx1, idx2] = math.log(prob)

def read_prepared_samples(
    dataset_dir: str, input_spec: list[ModelInputSpec]
) -> list[tuple[np.ndarray, ...]]:
    all_samples = []

    # Multi-input: samples are in numbered subdirectories
    if len(input_spec) > 1:
        sample_dirs = sorted(
            [
                d
                for d in os.listdir(dataset_dir)
                if os.path.isdir(os.path.join(dataset_dir, d))
            ]
        )

        for sample_name in sample_dirs:
            sample_dir = os.path.join(dataset_dir, sample_name)
            current_samples = []

            for spec_idx, spec in enumerate(input_spec):
                bin_file_path = os.path.join(
                    sample_dir, f"{str(spec_idx).zfill(2)}.bin"
                )
                sample_vector = np.fromfile(bin_file_path, dtype=spec.type).reshape(
                    spec.shape
                )
                current_samples.append(sample_vector)

            all_samples.append(tuple(current_samples))

    # Single-input: binary files are directly in dataset_dir
    else:
        bin_files = sorted([f for f in os.listdir(dataset_dir) if f.endswith(".bin")])

        for bin_file in bin_files:
            bin_file_path = os.path.join(dataset_dir, bin_file)
            sample_vector = np.fromfile(
                bin_file_path, dtype=input_spec[0].type
            ).reshape(input_spec[0].shape)
            all_samples.append((sample_vector,))

    return all_samples

def dump(obj, file=None, file_format=None, **kwargs):
    if isinstance(file, Path):
        file = str(file)
    if file_format is None:
        if isinstance(file, str):
            file_format = file.split('.')[-1]
        elif file is None:
            raise ValueError(
                'file_format must be specified since file is None')
    if file_format not in format_handlers:
        raise TypeError(f'Unsupported format: {file_format}')

    handler = format_handlers[file_format]
    if file is None:
        return handler.dump_to_str(obj, **kwargs)
    elif isinstance(file, str):
        if handler.text_mode:
            with StringIO() as f:
                handler.dump(obj, f, **kwargs)
                File.write_text(f.getvalue(), file)
        else:
            with BytesIO() as f:
                handler.dump(obj, f, **kwargs)
                File.write(f.getvalue(), file)
    elif hasattr(file, 'write'):
        handler.dump(obj, file, **kwargs)
    else:
        raise TypeError('"file" must be a filename str or a file-object')

def is_node_tosa_supported(self, node: fx.Node, tosa_spec: TosaSpecification):
        shape = cast(torch.Tensor, node.all_input_nodes[0].meta["val"]).shape
        kernel = cast(tuple[int, int], node.args[1])
        stride = cast(tuple[int, int], node.args[2])
        padding = cast(tuple[int, int], node.args[3]) if len(node.args) >= 4 else (0, 0)
        dilation = (
            cast(tuple[int, int], node.args[4]) if len(node.args) >= 5 else (1, 1)
        )

        if not dilation_check(shape, kernel, stride, padding, dilation):
            self.reporter.report_reject(
                node,
                f"Maxpool2d with dilation {dilation} needs stride = 1, got stride {stride}",
            )
            return False

        # U55 case, Vela 4.2.0 (25.02 release)
        if not tosa_spec.is_U55_subset:
            return True

        if not kernel_check(kernel):
            self.reporter.report_reject(
                node,
                f"Maxpool2d needs kernel_y < 256, kernel_x*kernel_y<=65536, got {kernel}",
            )
            return False
        if not dim_check(shape):
            self.reporter.report_reject(
                node,
                f"Maxpool2d needs N == 1, rest dims <= 65536, got shape {list(shape)}",
            )
            return False
        if not stride_check(stride):
            self.reporter.report_reject(
                node, f"Maxpool2d needs stride <= 3, got {stride}"
            )
            return False
        return True

def get_errors_from_single_artifact(artifact_zip_path, job_links=None):
    errors = []
    failed_tests = []
    job_name = None

    with zipfile.ZipFile(artifact_zip_path) as z:
        for filename in z.namelist():
            if not os.path.isdir(filename):
                # read the file
                if filename in ["failures_line.txt", "summary_short.txt", "job_name.txt"]:
                    with z.open(filename) as f:
                        for line in f:
                            line = line.decode("UTF-8").strip()
                            if filename == "failures_line.txt":
                                try:
                                    # `error_line` is the place where `error` occurs
                                    error_line = line[: line.index(": ")]
                                    error = line[line.index(": ") + len(": ") :]
                                    errors.append([error_line, error])
                                except Exception:
                                    # skip un-related lines that don't match the expected format
                                    logger.debug(f"Skipping unrelated line: {line}")
                            elif filename == "summary_short.txt" and line.startswith("FAILED "):
                                # `test` is the test method that failed
                                test = line[len("FAILED ") :]
                                failed_tests.append(test)
                            elif filename == "job_name.txt":
                                job_name = line

    if len(errors) != len(failed_tests):
        raise ValueError(
            f"`errors` and `failed_tests` should have the same number of elements. Got {len(errors)} for `errors` "
            f"and {len(failed_tests)} for `failed_tests` instead. The test reports in {artifact_zip_path} have some"
            " problem."
        )

    job_link = None
    if job_name and job_links:
        job_link = job_links.get(job_name, None)

    # A list with elements of the form (line of error, error, failed test)
    result = [x + [y] + [job_link] for x, y in zip(errors, failed_tests)]

    return result

def fast_parse(*,
               file_id: str,
               mmcif_string: str,
               catch_all_errors: bool = True) -> ParsingResult:
    errors = {}
    try:
        parser = MMCIFParser(QUIET=True)
        # handle = io.StringIO(mmcif_string)
        # full_structure = parser.get_structure('', handle)
        parsed_info = parser._mmcif_dict  # pylint:disable=protected-access

        # Ensure all values are lists, even if singletons.
        for key, value in parsed_info.items():
            if not isinstance(value, list):
                parsed_info[key] = [value]

        header = _get_header(parsed_info)

        # Determine the protein chains, and their start numbers according to the
        # internal mmCIF numbering scheme (likely but not guaranteed to be 1).
        valid_chains = _get_protein_chains(parsed_info=parsed_info)
        if not valid_chains:
            return ParsingResult(
                None, {(file_id, ''): 'No protein chains found in this file.'})

        mmcif_to_author_chain_id = {}
        # seq_to_structure_mappings = {}
        for atom in _get_atom_site_list(parsed_info):
            if atom.model_num != '1':
                # We only process the first model at the moment.
                continue
            mmcif_to_author_chain_id[
                atom.mmcif_chain_id] = atom.author_chain_id

        mmcif_object = MmcifObject(
            file_id=file_id,
            header=header,
            structure=None,
            chain_to_seqres=None,
            seqres_to_structure=None,
            raw_string=parsed_info,
            mmcif_to_author_chain_id=mmcif_to_author_chain_id,
            valid_chains=valid_chains,
        )

        return ParsingResult(mmcif_object=mmcif_object, errors=errors)
    except Exception as e:  # pylint:disable=broad-except
        errors[(file_id, '')] = e
        if not catch_all_errors:
            raise
        return ParsingResult(mmcif_object=None, errors=errors)

def read_dig_localite(fname, nasion=None, lpa=None, rpa=None):
    ch_pos = {}
    with open(fname) as f:
        f.readline()  # skip first row
        for row in f:
            _, name, x, y, z = row.split(",")
            ch_pos[name] = np.array((float(x), float(y), float(z))) / 1000

    if nasion is not None:
        nasion = ch_pos.pop(nasion)
    if lpa is not None:
        lpa = ch_pos.pop(lpa)
    if rpa is not None:
        rpa = ch_pos.pop(rpa)

    return make_dig_montage(ch_pos, nasion, lpa, rpa)

def config(self, recursive=False, **kwargs):
        keys = {"dump_all", "exclude", "include"}
        for k, v in kwargs.items():
            if k in keys:
                attr_name = f"_{k}"
                setattr(self, attr_name, v)
            else:
                raise KeyError(f"Unknown parameter: {k}")

        if recursive:
            for obj in self.__dict__.values():
                # set flag to prevent endless loop
                self.__dict__[self.FLAG_KEY] = True
                if isinstance(obj, Serializable) and self.FLAG_KEY not in obj.__dict__:
                    obj.config(recursive=True, **kwargs)
                del self.__dict__[self.FLAG_KEY]

def clear_messages_after(self, index):
        message_widgets = []
        for i in range(self.chat_messages_layout.count()):
            item = self.chat_messages_layout.itemAt(i)
            if (
                item
                and item.widget()
                and isinstance(item.widget(), ChatMessage)
            ):
                message_widgets.append((i, item.widget()))

        # Identify which items to remove (in reverse order to avoid index issues)
        to_remove = []
        for i, (layout_index, widget) in enumerate(message_widgets):
            if i >= index:
                to_remove.append((layout_index, widget))

        # Remove widgets in reverse order
        for layout_index, widget in reversed(to_remove):
            self.chat_messages_layout.removeWidget(widget)
            widget.setParent(None)
            widget.deleteLater()

        # Update chat history to match
        if len(to_remove) > 0:
            self.chat_history = self.chat_history[:index]

        # Make sure we still have a stretch at the end
        has_stretch = False
        for i in range(self.chat_messages_layout.count()):
            item = self.chat_messages_layout.itemAt(i)
            if item and item.spacerItem():
                has_stretch = True
                break
        if not has_stretch:
            self.chat_messages_layout.addStretch()

        # Force update layout
        QApplication.processEvents()

def make_safe_for_json(obj: Any) -> Any:
    if isinstance(obj, Mapping):
        return {k: make_safe_for_json(v) for k, v in obj.items()}
    elif isinstance(obj, str):
        # str's are Sequence, so we need to short-circuit
        return obj
    elif isinstance(obj, Sequence):
        return [make_safe_for_json(v) for v in obj]
    elif isinstance(obj, float):
        # W&B backend and UI handle these strings
        if obj != obj:  # standard way to check for NaN
            return "NaN"
        elif obj == float("+inf"):
            return "Infinity"
        elif obj == float("-inf"):
            return "-Infinity"
    return obj

def restore_loops(self) -> None:
        if not self._loaded_checkpoint:
            return

        fit_loop = self.trainer.fit_loop
        assert self.trainer.state.fn is not None
        state_dict = self._loaded_checkpoint.get("loops")
        if state_dict is not None:
            if self.trainer.state.fn == TrainerFn.FITTING:
                fit_loop.load_state_dict(state_dict["fit_loop"])
            elif self.trainer.state.fn == TrainerFn.VALIDATING:
                self.trainer.validate_loop.load_state_dict(state_dict["validate_loop"])
            elif self.trainer.state.fn == TrainerFn.TESTING:
                self.trainer.test_loop.load_state_dict(state_dict["test_loop"])
            elif self.trainer.state.fn == TrainerFn.PREDICTING:
                self.trainer.predict_loop.load_state_dict(state_dict["predict_loop"])

        if self.trainer.state.fn != TrainerFn.FITTING:
            return

        # crash if max_epochs is lower then the current epoch from the checkpoint
        if (
            self.trainer.max_epochs != -1
            and self.trainer.max_epochs is not None
            and self.trainer.current_epoch > self.trainer.max_epochs
        ):
            raise MisconfigurationException(
                f"You restored a checkpoint with current_epoch={self.trainer.current_epoch},"
                f" but you have set Trainer(max_epochs={self.trainer.max_epochs})."
            )

def compute_rouge_python(cand, ref, is_input_files=False, language="en"):
    supported_langauges = ["en", "hi"]
    if language not in supported_langauges:
        raise Exception(
            "Language {0} is not supported. Supported languages are: {1}.".format(
                language, supported_langauges
            )
        )

    if is_input_files:
        candidates = [line.strip() for line in open(cand, encoding="utf-8")]
        references = [line.strip() for line in open(ref, encoding="utf-8")]
    else:
        candidates = cand
        references = ref

    print("Number of candidates: {}".format(len(candidates)))
    print("Number of references: {}".format(len(references)))
    assert len(candidates) == len(references)

    if language == "en":
        evaluator = Rouge(
            metrics=["rouge-n", "rouge-l"], max_n=2, limit_length=False, apply_avg=True
        )
    else:
        evaluator = RougeExt(
            metrics=["rouge-n", "rouge-l"],
            max_n=2,
            limit_length=False,
            apply_avg=True,
            language=language,
        )

    scores = evaluator.get_scores(candidates, [[it] for it in references])

    return scores

def add_default_tags(self, example: Dict[str, Any]) -> None:
        messages = example['messages']
        for media_key, media_tag in [('videos', '<video>'), ('images', '<image>'), ('audios', '<audio>')]:
            if example.get(media_key):
                _messages = [message for message in messages if message['role']!='system']
                n_round = len(_messages)
                assert n_round % 2 == 0
                history = [_messages[i:i+2] for i in range(n_round // 2)]
                if self.infer_media_type == 'round':
                    for i, h, m in zip(range(n_round // 2), history, example[media_key]):
                        num_media_tags = len(re.findall(media_tag, h[0]['content']))
                        if m:
                            assert num_media_tags <= 1, (
                                'The model includes at most one media per round. However, '
                                f'this round contains {num_media_tags} media_tags. query: {h[0]}')
                            if num_media_tags == 0:
                                h[0]['content'] = media_tag + h[0]['content']
                        else:
                            assert num_media_tags == 0, f'Missing media. query: {h[0]}'
                    example[media_key] = [m for m in example[media_key] if m]
                else:
                    num_media_tags = len(re.findall(media_tag, '\n'.join([h[0]['content'] for h in history])))
                    example[media_key] = [m for m in example[media_key] if m]
                    num_media = len(example[media_key])
                    num_new_tags = num_media - num_media_tags
                    assert num_new_tags >= 0, f'Number of media: {num_media}, number of media_tags: {num_media_tags}'
                    history[0][0]['content'] = media_tag * num_new_tags + history[0][0]['content']

def check_no_exclusive_keys(spec: TensorSpec, recurse: bool = True):
    if isinstance(spec, StackedComposite):
        keys = set(spec.keys())
        for inner_td in spec._specs:
            if recurse and not check_no_exclusive_keys(inner_td):
                return False
            if set(inner_td.keys()) != keys:
                return False
    elif isinstance(spec, Composite) and recurse:
        for value in spec.values():
            if not check_no_exclusive_keys(value):
                return False
    else:
        return True
    return True

def report_accuracy(metric,
                    extended_log=False):
    def create_msg(name, value):
        if type(value) in [list, tuple]:
            if extended_log:
                return "{}={} ({})".format("{}", "/".join(["{:.4f}"] * len(value)), "/".join(["{}"] * len(value))).\
                    format(name, *(value + value))
            else:
                return "{}={}".format("{}", "/".join(["{:.4f}"] * len(value))).format(name, *value)
        else:
            if extended_log:
                return "{name}={value:.4f} ({value})".format(name=name, value=value)
            else:
                return "{name}={value:.4f}".format(name=name, value=value)

    metric_info = metric.get()
    if isinstance(metric, CompositeEvalMetric):
        msg = ", ".join([create_msg(name=m[0], value=m[1]) for m in zip(*metric_info)])
    elif isinstance(metric, EvalMetric):
        msg = create_msg(name=metric_info[0], value=metric_info[1])
    else:
        raise Exception("Wrong metric type: {}".format(type(metric)))
    return msg

def compute_vjp_single(dy, jac, num=None):
    if jac is None:
        return None

    dy_row = math.reshape(dy, [-1])

    if num is None:
        num = math.shape(dy_row)[0]

    if not isinstance(dy_row, np.ndarray):
        jac = _convert(jac, dy_row)

    # Note: For generality, all exception type warnings are disabled.
    # TODO: Excplictly catalogue and update raises for known types.

    # Single measurement with a single param
    if not isinstance(jac, (tuple, list, autograd.builtins.SequenceBox)):
        # No trainable parameters
        if jac.shape == (0,):
            res = math.zeros((1, 0))
            return res
        # Single measurement with no dimension e.g. expval or with dimension e.g. probs
        if num == 1:
            jac = math.squeeze(jac)
        jac = math.reshape(jac, (-1, 1))
        try:
            res = dy_row @ jac

        except Exception:  # pylint: disable=broad-except
            res = math.tensordot(jac, dy_row, [[0], [0]])

    # Single measurement with multiple params
    else:
        # No trainable parameters (adjoint)
        if len(jac) == 0:
            res = math.zeros((1, 0))
            return res
        # Single measurement with no dimension e.g. expval
        if num == 1:
            jac = math.reshape(math.stack(jac), (1, -1))
            try:
                res = dy_row @ jac
            # pylint: disable=broad-except
            except (
                Exception
            ):  # pragma: no cover (TensorFlow tests were disabled during deprecation)
                res = math.tensordot(jac, dy_row, [[0], [0]])

        # Single measurement with dimension e.g. probs
        else:
            jac = math.reshape(math.stack(jac), (-1, num))
            try:
                res = jac @ dy_row
            # pylint: disable=broad-except
            except (
                Exception
            ):  # pragma: no cover (TensorFlow tests were disabled during deprecation)
                res = math.tensordot(jac, dy_row, [[1], [0]])

    return res

def get_required_cloud_features(
            self) -> Set[clouds.CloudImplementationFeatures]:
        features = set()
        if self.use_spot:
            features.add(clouds.CloudImplementationFeatures.SPOT_INSTANCE)
        if (self.disk_tier is not None and
                self.disk_tier != resources_utils.DiskTier.BEST):
            features.add(clouds.CloudImplementationFeatures.CUSTOM_DISK_TIER)
        if (self.network_tier is not None and
                self.network_tier == resources_utils.NetworkTier.BEST):
            features.add(clouds.CloudImplementationFeatures.CUSTOM_NETWORK_TIER)
        if self.extract_docker_image() is not None:
            features.add(clouds.CloudImplementationFeatures.DOCKER_IMAGE)
        elif self.image_id is not None:
            features.add(clouds.CloudImplementationFeatures.IMAGE_ID)
        if self.ports is not None:
            features.add(clouds.CloudImplementationFeatures.OPEN_PORTS)
        if self.volumes is not None:
            for volume in self.volumes:
                if 'disk_tier' in volume and volume[
                        'disk_tier'] != resources_utils.DiskTier.BEST:
                    features.add(
                        clouds.CloudImplementationFeatures.CUSTOM_DISK_TIER)
        if self._local_disk is not None:
            features.add(clouds.CloudImplementationFeatures.LOCAL_DISK)
        return features

def repo_exists(
            self,
            repo_id: str,
            *,
            repo_type: Optional[str] = None,
            endpoint: Optional[str] = None,
            re_raise: Optional[bool] = False,
            token: Optional[str] = None
    ) -> bool:
        if endpoint is None:
            endpoint = self.endpoint
        if (repo_type is not None) and repo_type.lower() not in REPO_TYPE_SUPPORT:
            raise Exception('Not support repo-type: %s' % repo_type)
        if (repo_id is None) or repo_id.count('/') != 1:
            raise Exception('Invalid repo_id: %s, must be of format namespace/name' % repo_type)

        cookies = self.get_cookies(access_token=token, cookies_required=False)
        owner_or_group, name = model_id_to_group_owner_name(repo_id)
        if (repo_type is not None) and repo_type.lower() == REPO_TYPE_DATASET:
            path = f'{endpoint}/api/v1/datasets/{owner_or_group}/{name}'
        else:
            path = f'{endpoint}/api/v1/models/{owner_or_group}/{name}'

        r = self.session.get(path, cookies=cookies,
                             headers=self.builder_headers(self.headers))
        code = handle_http_response(r, logger, cookies, repo_id, False)
        if code == 200:
            return True
        elif code == 404:
            if re_raise:
                raise HTTPError(r)
            else:
                return False
        else:
            logger.warn(f'Check repo_exists return status code {code}.')
            raise Exception(
                'Failed to check existence of repo: %s, make sure you have access authorization.'
                % repo_type)

