            if self.comet_logger:
                self.comet_logger.on_pretrain_routine_end(paths)
            if self.clearml:
                for path in paths:
                    self.clearml.log_plot(title=path.stem, plot_path=path)

def mask_missing(arr: ArrayLike, value) -> npt.NDArray[np.bool_]:
    dtype, value = infer_dtype_from(value)

    if (
        isinstance(arr.dtype, (BaseMaskedDtype, ArrowDtype))
        and lib.is_float(value)
        and np.isnan(value)
        and not is_nan_na()
    ):
        # TODO: this should be done in an EA method?
        if arr.dtype.kind == "f":
            # GH#55127
            if isinstance(arr.dtype, BaseMaskedDtype):
                # error: "ExtensionArray" has no attribute "_data"  [attr-defined]
                mask = np.isnan(arr._data) & ~arr.isna()  # type: ignore[attr-defined]
                return mask
            else:
                # error: "ExtensionArray" has no attribute "_pa_array"  [attr-defined]
                import pyarrow.compute as pc

                mask = pc.is_nan(arr._pa_array).fill_null(False).to_numpy()  # type: ignore[attr-defined]
                return mask

        elif arr.dtype.kind in "iu":
            # GH#51237
            mask = np.zeros(arr.shape, dtype=bool)
            return mask

    if isna(value):
        return isna(arr)

    # GH 21977
    mask = np.zeros(arr.shape, dtype=bool)
    if (
        is_numeric_dtype(arr.dtype)
        and not is_bool_dtype(arr.dtype)
        and lib.is_bool(value)
    ):
        # e.g. test_replace_ea_float_with_bool, see GH#62048
        pass
    elif (
        is_bool_dtype(arr.dtype) and is_numeric_dtype(dtype) and not lib.is_bool(value)
    ):
        # e.g. test_replace_ea_float_with_bool, see GH#62048
        pass
    elif is_numeric_dtype(arr.dtype) and isinstance(value, str):
        # GH#29553 prevent numpy deprecation warnings
        pass
    elif is_object_dtype(arr.dtype):
        # pre-compute mask to avoid comparison to NA
        # e.g. test_replace_na_in_obj_column
        arr_mask = ~isna(arr)
        mask[arr_mask] = arr[arr_mask] == value
    else:
        new_mask = arr == value

        if not isinstance(new_mask, np.ndarray):
            # usually BooleanArray
            new_mask = new_mask.to_numpy(dtype=bool, na_value=False)
        mask = new_mask

    return mask

def format_error(cls, error: List[str], block_uuid: str = None) -> List[str]:
        initial_regex = r'.*execute_custom_code\(\).*'
        end_search_string = block_uuid if block_uuid else 'execute_block_function'
        end_regex = r'.*' + re.escape(end_search_string) + r'.*'
        custom_block_end_regex = r'.*data_preparation\/models\/block.*'

        initial_idx = 0
        end_idx = 0
        custom_block_end_idx = 0
        for idx, line in enumerate(error):
            ansi_escape = re.compile(r'\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])')
            line_without_ansi = ansi_escape.sub('', line)
            # The "execute_custom_code" method may appear in multiple lines of the stack trace, so
            # we just want to fetch the index of the first occurrence.
            if re.match(initial_regex, line_without_ansi) and not initial_idx:
                initial_idx = idx
            if re.match(end_regex, line_without_ansi):
                end_idx = idx
            if re.match(custom_block_end_regex, line_without_ansi):
                custom_block_end_idx = idx

        # Replace hard-to-read dark blue font with yellow font
        error = [e.replace('[0;34m', '[0;33m') for e in error]

        try:
            if initial_idx and end_idx:
                return error[: initial_idx - 1] + error[end_idx:]
            elif initial_idx and custom_block_end_idx:
                return error[: initial_idx - 1] + error[custom_block_end_idx:]
        except Exception:
            pass

        return error

def chatterbot_bigram_indexer(document):
    if not Doc.has_extension('search_index'):
        Doc.set_extension('search_index', default='')

    tokens = [
        token for token in document if not (token.is_punct or token.is_stop)
    ]

    # Fall back to including stop words if needed
    if not tokens or len(tokens) == 1:
        tokens = [
            token for token in document if not (token.is_punct)
        ]

    # Pairs consist of the part-of-speech of the first token and the
    # lemma of the second token in the bigram. This provides a good
    # balance of generalization and specificity for matching.
    bigram_pairs = [
        f"{tokens[i - 1].pos_}:{tokens[i].lemma_.lower()}"
        for i in range(1, len(tokens))
    ]

    if not bigram_pairs:

        text_without_punctuation = document.text.translate(
            punctuation_table
        )
        if len(text_without_punctuation) >= 1:
            text = text_without_punctuation.lower()
        else:
            text = document.text.lower()

        bigram_pairs = [text]

    # Assign a custom attribute at the Doc level
    document._.search_index = ' '.join(bigram_pairs)

    return document

def get_current_raw_objective(self, task: Union[ClearmlJob, Task]) -> (int, float):
        if isinstance(task, Task):
            task_id = task.id
        elif isinstance(task, ClearmlJob):
            task_id = task.task_id()
        else:
            task_id = task

        if not task_id:
            raise ValueError("Task ID not provided")

        # send request
        # noinspection PyBroadException
        try:
            # noinspection PyProtectedMember
            res = Task._get_default_session().send(
                events_service.ScalarMetricsIterHistogramRequest(task=task_id, key="iter", samples=None),
            )
        except Exception:
            res = None

        if not res:
            return None
        response = res.wait()
        if not response.ok() or not response.response_data:
            return None

        scalars = response.response_data
        # noinspection PyBroadException
        try:
            return (
                scalars[self.title][self.series]["x"][-1],
                scalars[self.title][self.series]["y"][-1],
            )
        except Exception:
            return None

