                        tf.write(imgfile.read())
                        self.img_file_names.append({"path": tf.name, "name": imgfile.name})

def post_process_semantic_segmentation(self, outputs, target_sizes: List[Tuple] = None):
        logits = outputs.logits

        # Resize logits and compute semantic segmentation maps
        if target_sizes is not None:
            if len(logits) != len(target_sizes):
                raise ValueError(
                    "Make sure that you pass in as many target sizes as the batch dimension of the logits"
                )

            if is_torch_tensor(target_sizes):
                target_sizes = target_sizes.numpy()

            semantic_segmentation = []

            for idx in range(len(logits)):
                resized_logits = torch.nn.functional.interpolate(
                    logits[idx].unsqueeze(dim=0), size=target_sizes[idx], mode="bilinear", align_corners=False
                )
                semantic_map = resized_logits[0].argmax(dim=0)
                semantic_segmentation.append(semantic_map)
        else:
            semantic_segmentation = logits.argmax(dim=1)
            semantic_segmentation = [semantic_segmentation[i] for i in range(semantic_segmentation.shape[0])]

        return semantic_segmentation

def inverse_depth_smoothness_loss(idepth: torch.Tensor, image: torch.Tensor) -> torch.Tensor:
    if not isinstance(idepth, torch.Tensor):
        raise TypeError(f"Input idepth type is not a torch.Tensor. Got {type(idepth)}")

    if not isinstance(image, torch.Tensor):
        raise TypeError(f"Input image type is not a torch.Tensor. Got {type(image)}")

    if not len(idepth.shape) == 4:
        raise ValueError(f"Invalid idepth shape, we expect BxCxHxW. Got: {idepth.shape}")

    if not len(image.shape) == 4:
        raise ValueError(f"Invalid image shape, we expect BxCxHxW. Got: {image.shape}")

    if not idepth.shape[-2:] == image.shape[-2:]:
        raise ValueError(f"idepth and image shapes must be the same. Got: {idepth.shape} and {image.shape}")

    if not idepth.device == image.device:
        raise ValueError(f"idepth and image must be in the same device. Got: {idepth.device} and {image.device}")

    if not idepth.dtype == image.dtype:
        raise ValueError(f"idepth and image must be in the same dtype. Got: {idepth.dtype} and {image.dtype}")

    # compute the gradients
    idepth_dx: torch.Tensor = _gradient_x(idepth)
    idepth_dy: torch.Tensor = _gradient_y(idepth)
    image_dx: torch.Tensor = _gradient_x(image)
    image_dy: torch.Tensor = _gradient_y(image)

    # compute image weights
    weights_x: torch.Tensor = torch.exp(-torch.mean(torch.abs(image_dx), dim=1, keepdim=True))
    weights_y: torch.Tensor = torch.exp(-torch.mean(torch.abs(image_dy), dim=1, keepdim=True))

    # apply image weights to depth
    smoothness_x: torch.Tensor = torch.abs(idepth_dx * weights_x)
    smoothness_y: torch.Tensor = torch.abs(idepth_dy * weights_y)

    return torch.mean(smoothness_x) + torch.mean(smoothness_y)

def start(self):
        if not self._reset_called:
            self.ds.reset_state()
        itr = self.ds.__iter__()
        if self.warmup:
            for _ in tqdm.trange(self.warmup, **get_tqdm_kwargs()):
                next(itr)
        # add smoothing for speed benchmark
        with get_tqdm(total=self.test_size,
                      leave=True, smoothing=0.2) as pbar:
            for idx, dp in enumerate(itr):
                pbar.update()
                if idx == self.test_size - 1:
                    break

def flatten_data(df: DataFrame, key_type="block_id", with_sample_id=True):
    sample_id_index = (
        df.data_manager.loc_block(df.data_manager.schema.sample_id_name, with_offset=False)
        if (with_sample_id or key_type == "sample_id")
        else None
    )

    def _flatten(kvs):
        for block_id, blocks in kvs:
            flat_blocks = [Block.transform_block_to_list(block) for block in blocks]
            block_num = len(flat_blocks)
            if key_type == "block_id":
                for row_id in range(len(blocks[0])):
                    if with_sample_id:
                        yield (block_id, row_id), (
                            flat_blocks[sample_id_index][row_id],
                            [flat_blocks[i][row_id] for i in range(block_num)],
                        )
                    else:
                        yield (block_id, row_id), [flat_blocks[i][row_id] for i in range(block_num)]
            else:
                for row_id in range(len(blocks[0])):
                    yield flat_blocks[sample_id_index][row_id], [flat_blocks[i][row_id] for i in range(block_num)]

    if key_type in ["block_id", "sample_id"]:
        return df.block_table.mapPartitions(_flatten, use_previous_behavior=False)
    else:
        raise ValueError(f"Not Implement key_type={key_type} of flatten_data.")

def push_image(
    image_id: str,
    registry_url: str,
    name: str,
    tag: Optional[str] = None,
    stream_progress_to: Optional[TextIO] = None,
) -> str:

    if not tag:
        tag = slugify(prefect.types._datetime.now("UTC").isoformat())

    _, registry, _, _, _ = urlsplit(registry_url)
    repository = f"{registry}/{name}"

    with docker_client() as client:
        image: "Image" = client.images.get(image_id)
        image.tag(repository, tag=tag)  # type: ignore  # typing stub is not complete
        events = cast(
            Iterator[dict[str, Any]],
            client.api.push(repository, tag=tag, stream=True, decode=True),  # type: ignore  # typing stub is not complete
        )
        try:
            for event in events:
                if "status" in event:
                    if not stream_progress_to:
                        continue
                    stream_progress_to.write(event["status"])
                    if "progress" in event:
                        stream_progress_to.write(" " + event["progress"])
                    stream_progress_to.write("\n")
                    stream_progress_to.flush()
                elif "error" in event:
                    raise PushError(event["error"])
        finally:
            client.api.remove_image(f"{repository}:{tag}", noprune=True)  # type: ignore  # typing stub is not complete

    return f"{repository}:{tag}"

def select_modules_by_config(model: torch.nn.Module, \
                             config: Dict[str, Any]) -> Tuple[Dict[str, torch.nn.Module], Dict[str, Any], List[Tuple[str]]]:
    # intersection(union(op_names, op_names_re), op_types) - exclude_op_names - exclude_op_names_re - exclude_op_types
    name2module = {}
    type2names = defaultdict(set)
    for module_name, module in model.named_modules(remove_duplicate=False):
        name2module[module_name] = module
        type2names[type(module).__name__].add(module_name)

    config = deepcopy(config)
    op_names = config.pop('op_names', None)
    op_types = config.pop('op_types', None)
    op_names_re = config.pop('op_names_re', None)
    exclude_op_names = config.pop('exclude_op_names', list())
    exclude_op_types = config.pop('exclude_op_types', list())
    exclude_op_names_re = config.pop('exclude_op_names_re', list())
    fuse_names = config.pop('fuse_names', list())

    selected_op_names = set(op_names) if op_names else set()

    for op_name_re in (op_names_re if op_names_re else []):
        for op_name in name2module:
            if re.match(op_name_re, op_name):
                selected_op_names.add(op_name)

    if op_types:
        selected_by_op_types = set()
        for op_type in op_types:
            selected_by_op_types.update(type2names.get(op_type, set()))
        if op_names or op_names_re:
            selected_op_names.intersection_update(selected_by_op_types)
        else:
            selected_op_names.update(selected_by_op_types)

    selected_op_names.difference_update(exclude_op_names)

    for op_name_re in exclude_op_names_re:
        for op_name in name2module:
            if re.match(op_name_re, op_name) and op_name in selected_op_names:
                selected_op_names.remove(op_name)

    for op_type in exclude_op_types:
        selected_op_names.difference_update(type2names.get(op_type, set()))

    return {module_name: name2module[module_name] for module_name in selected_op_names}, config, fuse_names

def from_pretrained(cls, pretrained_model_name_or_path, **kwargs):
        cache_dir = kwargs.pop("cache_dir", None)
        proxies = kwargs.pop("proxies", None)
        return_unused_kwargs = kwargs.pop("return_unused_kwargs", False)
        from_pipeline = kwargs.pop("_from_pipeline", None)

        user_agent = {"file_type": "model_card"}
        if from_pipeline is not None:
            user_agent["using_pipeline"] = from_pipeline

        is_local = os.path.isdir(pretrained_model_name_or_path)
        if os.path.isfile(pretrained_model_name_or_path):
            resolved_model_card_file = pretrained_model_name_or_path
            is_local = True
        else:
            try:
                # Load from URL or cache if already cached
                resolved_model_card_file = cached_file(
                    pretrained_model_name_or_path,
                    filename=MODEL_CARD_NAME,
                    cache_dir=cache_dir,
                    proxies=proxies,
                    user_agent=user_agent,
                )
                if is_local:
                    logger.info(f"loading model card file {resolved_model_card_file}")
                else:
                    logger.info(f"loading model card file {MODEL_CARD_NAME} from cache at {resolved_model_card_file}")
                # Load model card
                modelcard = cls.from_json_file(resolved_model_card_file)

            except (EnvironmentError, json.JSONDecodeError):
                # We fall back on creating an empty model card
                modelcard = cls()

        # Update model card with kwargs if needed
        to_remove = []
        for key, value in kwargs.items():
            if hasattr(modelcard, key):
                setattr(modelcard, key, value)
                to_remove.append(key)
        for key in to_remove:
            kwargs.pop(key, None)

        logger.info(f"Model card: {modelcard}")
        if return_unused_kwargs:
            return modelcard, kwargs
        else:
            return modelcard

def moveaxis(a, source, destination):  # pylint: disable=missing-docstring
  if not source and not destination:
    return a

  a = asarray(a).data

  if isinstance(source, int):
    source = (source,)
  if isinstance(destination, int):
    destination = (destination,)

  a_rank = utils._maybe_static(tf.rank(a))  # pylint: disable=protected-access

  def _correct_axis(axis, rank):
    if axis < 0:
      return axis + rank
    return axis

  source = tuple(_correct_axis(axis, a_rank) for axis in source)
  destination = tuple(_correct_axis(axis, a_rank) for axis in destination)

  if a.shape.rank is not None:
    perm = [i for i in range(a_rank) if i not in source]
    for dest, src in sorted(zip(destination, source)):
      assert dest <= len(perm)
      perm.insert(dest, src)
  else:
    r = tf.range(a_rank)

    def _remove_indices(a, b):
      """Remove indices (`b`) from `a`."""
      items = tf.unstack(tf.sort(tf.stack(b)), num=len(b))

      i = 0
      result = []

      for item in items:
        result.append(a[i:item])
        i = item + 1

      result.append(a[i:])

      return tf.concat(result, 0)

    minus_sources = _remove_indices(r, source)
    minus_dest = _remove_indices(r, destination)

    perm = tf.scatter_nd(tf.expand_dims(minus_dest, 1), minus_sources, [a_rank])
    perm = tf.tensor_scatter_nd_update(perm, tf.expand_dims(destination, 1),
                                       source)
  a = tf.transpose(a, perm)

  return utils.tensor_to_ndarray(a)

def read_beamformer(fname):
    read_hdf5, _ = _import_h5io_funcs()
    beamformer = read_hdf5(fname, title="mnepython")
    if "csd" in beamformer:
        beamformer["csd"] = CrossSpectralDensity(**beamformer["csd"])
    # h5io seems to cast `bool` to `int` on round-trip, probably a bug
    # we should fix at some point (if possible -- could be HDF5 limitation)
    for key in ("normalize_fwd", "is_free_ori", "is_ssp"):
        if key in beamformer:
            beamformer[key] = bool(beamformer[key])
    for key in ("data_cov", "noise_cov"):
        if beamformer.get(key) is not None:
            for pi, p in enumerate(beamformer[key]["projs"]):
                p = Projection(**p)
                p["active"] = bool(p["active"])
                beamformer[key]["projs"][pi] = p
            beamformer[key] = Covariance(
                *[
                    beamformer[key].get(arg)
                    for arg in (
                        "data",
                        "names",
                        "bads",
                        "projs",
                        "nfree",
                        "eig",
                        "eigvec",
                        "method",
                        "loglik",
                    )
                ]
            )
    return Beamformer(beamformer)

def get_namespace(
    *arrays, remove_none=True, remove_types=REMOVE_TYPES_DEFAULT, xp=None
):
    array_api_dispatch = get_config()["array_api_dispatch"]
    if not array_api_dispatch:
        if xp is not None:
            return xp, False
        else:
            return np_compat, False

    if xp is not None:
        return xp, True

    arrays = _remove_non_arrays(
        *arrays,
        remove_none=remove_none,
        remove_types=remove_types,
    )

    # get_namespace can be called by helper functions that are used both in
    # array API compatible code and non-array API Cython related code. To
    # support the latter on NumPy inputs without raising a TypeError, we
    # unwrap potential Cython memoryview slices here.
    arrays = _unwrap_memoryviewslices(*arrays)

    if not arrays:
        return np_compat, False

    _check_array_api_dispatch(array_api_dispatch)

    namespace = array_api_compat.get_namespace(*arrays)
    is_array_api_compliant = True

    if namespace.__name__ == "array_api_strict" and hasattr(
        namespace, "set_array_api_strict_flags"
    ):
        namespace.set_array_api_strict_flags(api_version="2024.12")

    return namespace, is_array_api_compliant

def weighted_percentile(a, q, weights=None, sorter=None, is_filtered=False):
    if weights is None:
        weights = np.ones_like(a)
    if q > 100 or q < 0:
        raise ValueError("q should be in-between 0 and 100, got %d" % q)

    a = np.asarray(a, dtype=np.float32)
    weights = np.asarray(weights, dtype=np.float32)
    if len(a) != len(weights):
        raise ValueError("a and weights should have the same length.")

    if sorter is not None:
        a = a[sorter]
        weights = weights[sorter]

    if not is_filtered:
        nz = weights != 0
        a = a[nz]
        weights = weights[nz]

    if sorter is None:
        sorted_indices = np.argsort(a)
        sorted_a = a[sorted_indices]
        sorted_weights = weights[sorted_indices]
    else:
        sorted_a = a
        sorted_weights = weights

    # Step 1
    sorted_cum_weights = np.cumsum(sorted_weights)
    total = sorted_cum_weights[-1]

    # Step 2
    partial_sum = 100.0 / total * (sorted_cum_weights - sorted_weights / 2.0)
    start = np.searchsorted(partial_sum, q) - 1
    if start == len(sorted_cum_weights) - 1:
        return sorted_a[-1]
    if start == -1:
        return sorted_a[0]

    # Step 3.
    fraction = (q - partial_sum[start]) / (partial_sum[start + 1] - partial_sum[start])
    return sorted_a[start] + fraction * (sorted_a[start + 1] - sorted_a[start])

def fuse_permute_matmul(gm: torch.fx.GraphModule, input: Input):
    for node in gm.graph.nodes:
        if node.target == acc_ops.matmul:
            lhs, rhs = node.kwargs["input"], node.kwargs["other"]
            lhs_transposed = rhs_tranposed = False
            skip = False

            if lhs.target == acc_ops.permute and check_permute(lhs):
                lhs_transposed = True
                lhs = lhs.kwargs["input"]

            if rhs.target == acc_ops.permute and check_permute(rhs):
                rhs_tranposed = True
                rhs = rhs.kwargs["input"]

            if (not skip) and (lhs_transposed or rhs_tranposed):
                with gm.graph.inserting_before(node):
                    fused_node = gm.graph.call_function(
                        trt_transposed_matmul,
                        args=(lhs, rhs, lhs_transposed, rhs_tranposed),
                    )
                node.replace_all_uses_with(fused_node)

    gm.graph.eliminate_dead_code()
    gm.graph.lint()
    gm.recompile()
    return gm

def get_numeric_sort_key_fn(numeric_values):
    value_types = _get_all_types(numeric_values)
    if len(value_types) != 1:
        raise ValueError(f"No common value type in {numeric_values}")

    value_type = next(iter(value_types))
    if value_type == NUMBER_TYPE:
        # Primitive values are simple floats, nothing to do here.
        return _get_value_as_primitive_value

    # The type can only be Date at this point which means the primitive type
    # is a float triple.
    valid_indexes = set(range(_DATE_TUPLE_SIZE))

    for numeric_value in numeric_values:
        value = _get_value_as_primitive_value(numeric_value)
        assert isinstance(value, tuple)
        for tuple_index, inner_value in enumerate(value):
            if inner_value is None:
                valid_indexes.discard(tuple_index)

    if not valid_indexes:
        raise ValueError(f"No common value in {numeric_values}")

    def _sort_key_fn(numeric_value):
        value = _get_value_as_primitive_value(numeric_value)
        return tuple(value[index] for index in valid_indexes)

    return _sort_key_fn

def compile(self) -> None:
        # Skip compilation if already compiled and graph structure hasn't changed
        if self._compiled:
            if self.verbose:
                logger.debug(
                    "GraphWorkflow already compiled, skipping recompilation"
                )
            return

        if self.verbose:
            logger.info("Starting GraphWorkflow compilation")

        compile_start_time = time.time()

        try:
            if not self.entry_points:
                if self.verbose:
                    logger.debug("Auto-setting entry points")
                self.auto_set_entry_points()

            if not self.end_points:
                if self.verbose:
                    logger.debug("Auto-setting end points")
                self.auto_set_end_points()

            if self.verbose:
                logger.debug(f"Entry points: {self.entry_points}")
                logger.debug(f"End points: {self.end_points}")

            # Pre-compute topological layers for efficient execution
            if self.verbose:
                logger.debug("Computing topological layers")

            sorted_layers = (
                self.graph_backend.topological_generations()
            )
            self._sorted_layers = sorted_layers

            # Cache compilation timestamp for debugging
            self._compilation_timestamp = time.time()
            self._compiled = True

            compile_time = time.time() - compile_start_time

            # Log compilation caching info for multi-loop scenarios
            cache_msg = ""
            if self.max_loops > 1:
                cache_msg = f" (cached for {self.max_loops} loops)"

            logger.info(
                f"GraphWorkflow compiled successfully: {len(self._sorted_layers)} layers, {len(self.nodes)} nodes (took {compile_time:.3f}s){cache_msg}"
            )

            if self.verbose:
                for i, layer in enumerate(self._sorted_layers):
                    logger.debug(f"Layer {i}: {layer}")

        except Exception as e:
            logger.exception(
                f"Error in GraphWorkflow compilation: {e}"
            )
            raise e

def correct_for_frame_skip(cfg: DictConfig) -> DictConfig:  # noqa: F821
    def _hasattr(field):
        local_cfg = cfg
        fields = field.split(".")
        for f in fields:
            if not hasattr(local_cfg, f):
                return False
            local_cfg = getattr(local_cfg, f)
        else:
            return True

    def _getattr(field):
        local_cfg = cfg
        fields = field.split(".")
        for f in fields:
            local_cfg = getattr(local_cfg, f)
        return local_cfg

    def _setattr(field, val):
        local_cfg = cfg
        fields = field.split(".")
        for f in fields[:-1]:
            local_cfg = getattr(local_cfg, f)
        setattr(local_cfg, field[-1], val)

    # Adapt all frame counts wrt frame_skip
    frame_skip = cfg.env.frame_skip
    if frame_skip != 1:
        fields = [
            "collector.max_frames_per_traj",
            "collector.total_frames",
            "collector.frames_per_batch",
            "logger.record_frames",
            "exploration.annealing_frames",
            "collector.init_random_frames",
            "env.init_env_steps",
            "env.noops",
        ]
        for field in fields:
            if _hasattr(cfg, field):
                _setattr(field, _getattr(field) // frame_skip)
    return cfg

def conv(name, x, output_channels, filter_size=None, stride=None,
         logscale_factor=3.0, apply_actnorm=True, conv_init="default",
         dilations=None):
  if conv_init == "zeros" and apply_actnorm:
    raise ValueError("apply_actnorm is unstable when init is set to zeros.")

  x_shape = common_layers.shape_list(x)
  is_2d = len(x_shape) == 4
  num_steps = x_shape[1]

  # set filter_size, stride and in_channels
  if is_2d:
    if filter_size is None:
      filter_size = [3, 3]
    if stride is None:
      stride = [1, 1]
    if dilations is None:
      dilations = [1, 1, 1, 1]
    actnorm_func = actnorm
    x = add_edge_bias(x, filter_size=filter_size)
    conv_filter = tf.nn.conv2d
  else:
    if filter_size is None:
      if num_steps == 1:
        filter_size = [1, 3, 3]
      else:
        filter_size = [2, 3, 3]
    if stride is None:
      stride = [1, 1, 1]
    if dilations is None:
      dilations = [1, 1, 1, 1, 1]
    actnorm_func = actnorm_3d
    x = time_pad(x, filter_size=filter_size, dilations=dilations)
    conv_filter = tf.nn.conv3d

  in_channels = common_layers.shape_list(x)[-1]
  filter_shape = filter_size + [in_channels, output_channels]
  stride_shape = [1] + stride + [1]

  with tf.variable_scope(name, reuse=tf.AUTO_REUSE):

    if conv_init == "default":
      initializer = default_initializer()
    elif conv_init == "zeros":
      initializer = tf.zeros_initializer()

    w = tf.get_variable("W", filter_shape, tf.float32, initializer=initializer)
    x = conv_filter(x, w, stride_shape, padding="VALID", dilations=dilations)
    if apply_actnorm:
      x, _ = actnorm_func("actnorm", x, logscale_factor=logscale_factor)
    else:
      x += tf.get_variable("b", [1, 1, 1, output_channels],
                           initializer=tf.zeros_initializer())
      logs = tf.get_variable("logs", [1, output_channels],
                             initializer=tf.zeros_initializer())
      x *= tf.exp(logs * logscale_factor)
    return x

def GetFeature(self, request: RegistryServer_pb2.GetFeatureRequest, context):
        allow_cache = getattr(request, "allow_cache", True)
        feature_views = self.proxied_registry.list_all_feature_views(
            project=request.project,
            allow_cache=allow_cache,
        )
        permitted_fvs = permitted_resources(
            resources=cast(list[FeastObject], feature_views),
            actions=AuthzedAction.DESCRIBE,
        )
        for fv in permitted_fvs:
            fv_name = getattr(fv, "name", None)
            for feature in getattr(fv, "features", []):
                if fv_name == request.feature_view and feature.name == request.name:
                    # Get owner and timestamps from feature view
                    owner = ""
                    created_timestamp = None
                    last_updated_timestamp = None

                    if hasattr(fv, "spec") and hasattr(fv.spec, "owner"):
                        owner = getattr(fv.spec, "owner", "")

                    if hasattr(fv, "meta"):
                        if hasattr(fv.meta, "created_timestamp"):
                            created_timestamp = fv.meta.created_timestamp
                        if hasattr(fv.meta, "last_updated_timestamp"):
                            last_updated_timestamp = fv.meta.last_updated_timestamp

                    return Feature(
                        name=feature.name,
                        feature_view=fv_name if fv_name is not None else "",
                        type=str(feature.dtype)
                        if hasattr(feature, "dtype")
                        else str(feature.valueType),
                        description=getattr(feature, "description", ""),
                        owner=owner,
                        created_timestamp=created_timestamp,
                        last_updated_timestamp=last_updated_timestamp,
                        tags=getattr(feature, "tags", {}),
                    )
        raise FeastObjectNotFoundException(
            f"Feature {request.name} not found in feature view {request.feature_view} in project {request.project}"
        )

def check_distribution_compatibility(
    dist_old: BaseDistribution, dist_new: BaseDistribution
) -> None:

    if dist_old.__class__ != dist_new.__class__:
        raise ValueError("Cannot set different distribution kind to the same parameter name.")

    if isinstance(dist_old, (FloatDistribution, IntDistribution)):
        # For mypy.
        assert isinstance(dist_new, (FloatDistribution, IntDistribution))

        if dist_old.log != dist_new.log:
            raise ValueError("Cannot set different log configuration to the same parameter name.")

    if not isinstance(dist_old, CategoricalDistribution):
        return
    if not isinstance(dist_new, CategoricalDistribution):
        return
    if dist_old != dist_new:
        raise ValueError(
            CategoricalDistribution.__name__ + " does not support dynamic value space."
        )

def handle_semantic_tokens(tokens, config, sample_id, parts, request):
    responses = []
    _tokens = tokens[1:].clone()

    if not config.share_codebook_embeddings:
        for i in range(len(_tokens)):
            _tokens[i] -= config.codebook_size * i

    # If streaming, send the VQ parts directly
    if request.streaming:
        responses.append(
            ServeStreamResponse(
                sample_id=sample_id,
                delta=ServeStreamDelta(part=ServeVQPart(codes=_tokens.tolist())),
            )
        )
    else:
        # If not streaming, accumulate the VQ parts
        if not parts[sample_id] or not isinstance(parts[sample_id][-1], ServeVQPart):
            parts[sample_id].append(ServeVQPart(codes=_tokens.tolist()))
        else:
            # Accumulate the codes
            for codebook_id, value in enumerate(_tokens):
                parts[sample_id][-1].codes[codebook_id].append(value.item())

    return responses

def calculate_neg_cross_entropy_per_sample(labels, probas: np.ndarray,
                                           model_classes: Optional[List] = None,
                                           index=None, is_multilabel: bool = False, eps=1e-15) -> pd.Series:
    if not is_multilabel:
        if index is None and isinstance(labels, pd.Series):
            index = labels.index

        # transform categorical labels into integers
        if model_classes is not None:
            if any(x not in model_classes for x in labels):
                raise DeepchecksValueError(
                    f'Label observed values {sorted(np.unique(labels))} contain values '
                    f'that are not found in the model classes: {model_classes}.')
            if probas.shape[1] != len(model_classes):
                raise DeepchecksValueError(
                    f'Predicted probabilities shape {probas.shape} does not match the number of classes found in'
                    f' the labels: {model_classes}.')
            labels = pd.Series(labels).apply(list(model_classes).index)

        num_samples, num_classes = probas.shape
        one_hot_labels = np.zeros((num_samples, num_classes))
        one_hot_labels[list(np.arange(num_samples)), list(labels)] = 1
    else:
        one_hot_labels = labels

    return pd.Series(np.sum(one_hot_labels * np.log(probas + eps), axis=1), index=index)

def add_data_entries(
        self,
        data_entries,
        upload_local_files_destination: Optional[str] = None,
        batch_size: int = 1000,
        max_workers: Optional[int] = None,
        show_progress: bool = True,
        upload_retries: int = 5,
        force_upload: bool = False,
        max_request_size_mb: int = None,
        hash_sources: bool = False,
    ):
        HyperDataset._verify_upload_destination(upload_local_files_destination)
        errors = {"upload": {}, "register": {}}
        should_commit = False
        with ThreadPoolExecutor(max_workers=max_workers or psutil.cpu_count()) as thread_pool:
            for i in range(0, len(data_entries), batch_size):
                batched_data_entries = data_entries[i: i + batch_size]
                upload_errors = self._upload_data_entries(
                    data_entries=batched_data_entries,
                    upload_destination=upload_local_files_destination,
                    retries=upload_retries,
                    force_upload=force_upload,
                    hash_sources=hash_sources,
                    thread_pool=thread_pool,
                )
                if max_request_size_mb:
                    register_errors = self._register_data_entries_batched_request_size(
                        data_entries=batched_data_entries, max_request_size_mb=max_request_size_mb
                    )
                else:
                    register_errors = self._register_data_entries(data_entries=batched_data_entries)
                register_errors = register_errors or {}
                errors["upload"].update(upload_errors)
                errors["register"].update(register_errors)
                if batched_data_entries and len(register_errors) < len(batched_data_entries):
                    should_commit = True
        if should_commit:
            try:
                self.commit_version()
            except Exception as exc:
                errors["register"][COMMIT_ERROR_KEY] = exc
        return errors

def func_load(code, defaults=None, closure=None, globs=None):
    if isinstance(code, (tuple, list)):  # unpack previous dump
        code, defaults, closure = code
        if isinstance(defaults, list):
            defaults = tuple(defaults)

    def ensure_value_to_cell(value):
        """Ensures that a value is converted to a python cell object.

        Args:
            value: Any value that needs to be casted to the cell type

        Returns:
            A value wrapped as a cell object (see function "func_load")
        """

        def dummy_fn():
            value  # just access it so it gets captured in .__closure__

        cell_value = dummy_fn.__closure__[0]
        if not isinstance(value, type(cell_value)):
            return cell_value
        return value

    if closure is not None:
        closure = tuple(ensure_value_to_cell(_) for _ in closure)
    try:
        raw_code = codecs.decode(code.encode("ascii"), "base64")
    except (UnicodeEncodeError, binascii.Error):
        raw_code = code.encode("raw_unicode_escape")
    code = marshal.loads(raw_code)
    if globs is None:
        globs = globals()
    return python_types.FunctionType(
        code, globs, name=code.co_name, argdefs=defaults, closure=closure
    )

def get_cond_latents(all_latents=None, hparams=None):
  cond_latents = None
  if hparams.gen_mode == "conditional":
    if hparams.latent_dist_encoder in ["conv_net", "conv3d_net"]:
      num_cond_latents = (hparams.num_cond_latents +
                          int(hparams.cond_first_frame))
      if len(all_latents) >= num_cond_latents:
        cond_latents = all_latents[-hparams.num_cond_latents:]
        if hparams.cond_first_frame:
          cond_latents = [all_latents[0]] + cond_latents
    elif hparams.latent_dist_encoder in ["pointwise", "conv_lstm"]:
      if all_latents:
        cond_latents = all_latents[-1]

  if hparams.gen_mode == "conditional":
    global_step = tf.train.get_or_create_global_step()
    condition = tf.greater(global_step, hparams.pretrain_steps)
  else:
    condition = tf.constant(False, dtype=tf.bool)
  return condition, cond_latents

def dunder_get(_dict: Any, key: str) -> Any:
    if _dict is None:
        return None

    part1: Union[str, int]
    try:
        part1, part2 = key.split('__', 1)
    except ValueError:
        part1, part2 = key, ''

    try:
        part1 = int(part1)  # parse int parameter
    except ValueError:
        pass

    if isinstance(part1, int):
        result = _dict[part1]
    elif isinstance(_dict, dict):
        result = _dict[part1]
    elif isinstance(_dict, Sequence):
        result = _dict[int(part1)]
    else:
        result = getattr(_dict, part1)

    return dunder_get(result, part2) if part2 else result

def do_naive_bayes_prediction(x, observed_class_distribution: dict, splitters: dict):
    total_weight = sum(observed_class_distribution.values())
    if not observed_class_distribution or total_weight == 0:
        # No observed class distributions, all classes equal
        return {}

    # Pre-resolve log-probability methods to avoid repeated getattr in the inner loop
    if splitters:
        _splitter_log_probas = {
            att_idx: getattr(obs, "cond_log_proba", None)
            for att_idx, obs in splitters.items()
            if att_idx in x
        }
    else:
        _splitter_log_probas = {}

    votes = {}
    for class_index, class_weight in observed_class_distribution.items():
        # Prior
        if class_weight > 0:
            votes[class_index] = math.log(class_weight / total_weight)
        else:
            votes[class_index] = 0.0
            continue

        for att_idx, log_proba in _splitter_log_probas.items():
            # Use log-probability directly when available (avoids exp+log round-trip)
            if log_proba is not None:
                log_p = log_proba(x[att_idx], class_index)
                if log_p > -math.inf:
                    votes[class_index] += log_p
            else:
                tmp = splitters[att_idx].cond_proba(x[att_idx], class_index)
                votes[class_index] += math.log(tmp) if tmp > 0 else 0.0

    # Max log-likelihood
    max_ll = max(votes.values())
    # Apply the log-sum-exp trick (https://stats.stackexchange.com/a/253319)
    lse = max_ll + math.log(sum(math.exp(log_proba - max_ll) for log_proba in votes.values()))

    for class_index in votes:
        votes[class_index] = math.exp(votes[class_index] - lse)

    return votes

def get_locales(
    prefix: str | None = None,
    normalize: bool = True,
) -> list[str]:
    if platform.system() in ("Linux", "Darwin"):
        raw_locales = subprocess.check_output(["locale", "-a"])
    else:
        # Other platforms e.g. windows platforms don't define "locale -a"
        #  Note: is_platform_windows causes circular import here
        return []

    try:
        # raw_locales is "\n" separated list of locales
        # it may contain non-decodable parts, so split
        # extract what we can and then rejoin.
        split_raw_locales = raw_locales.split(b"\n")
        out_locales = []
        for x in split_raw_locales:
            try:
                out_locales.append(
                    str(x, encoding=cast("str", options.display.encoding))
                )
            except UnicodeError:
                # 'locale -a' is used to populated 'raw_locales' and on
                # Redhat 7 Linux (and maybe others) prints locale names
                # using windows-1252 encoding.  Bug only triggered by
                # a few special characters and when there is an
                # extensive list of installed locales.
                out_locales.append(str(x, encoding="windows-1252"))

    except TypeError:
        pass

    if prefix is None:
        return _valid_locales(out_locales, normalize)

    pattern = re.compile(f"{prefix}.*")
    found = pattern.findall("\n".join(out_locales))
    return _valid_locales(found, normalize)

def load_weights_only(
    model, filepath, skip_mismatch=False, objects_to_skip=None
):
    if not model.built:
        raise ValueError(
            "You are loading weights into a model that has not yet been built. "
            "Try building the model first by calling it on some data or "
            "by using `build()`."
        )

    archive = None
    tmp_dir = None
    filepath_str = str(filepath)

    try:
        if file_utils.is_remote_path(filepath_str):
            tmp_dir = get_temp_dir()
            local_filepath = os.path.join(
                tmp_dir, os.path.basename(filepath_str)
            )
            file_utils.copy(filepath_str, local_filepath)
            filepath_str = filepath = local_filepath

        if filepath_str.endswith("weights.h5"):
            weights_store = H5IOStore(filepath, mode="r")
        elif filepath_str.endswith("weights.json"):
            weights_store = ShardedH5IOStore(filepath, mode="r")
        elif filepath_str.endswith(".keras"):
            archive = zipfile.ZipFile(filepath, "r")
            weights_store = H5IOStore(_VARS_FNAME_H5, archive=archive, mode="r")

        failed_saveables = set()
        if objects_to_skip is not None:
            visited_saveables = set(id(o) for o in objects_to_skip)
        else:
            visited_saveables = set()
        error_msgs = {}
        _load_state(
            model,
            weights_store=weights_store,
            assets_store=None,
            inner_path="",
            skip_mismatch=skip_mismatch,
            visited_saveables=visited_saveables,
            failed_saveables=failed_saveables,
            error_msgs=error_msgs,
        )
        weights_store.close()
        if archive:
            archive.close()

        if failed_saveables:
            _raise_loading_failure(error_msgs, warn_only=skip_mismatch)
    finally:
        if tmp_dir is not None:
            shutil.rmtree(tmp_dir)

def interpret(self, node: QASMNode, context: dict, **inputs):
        context = Context(context)
        self.inputs = inputs

        # begin recursive descent traversal
        try:
            for value in node.__dict__.values():
                if not isinstance(value, list):
                    value = [value]
                for item in value:
                    if isinstance(item, QASMNode):
                        self.visit(item, context)
        except EndProgram:
            pass

        if len(self.found_inputs) != len(inputs):
            raise ValueError(
                f"Got the wrong input parameters {list(inputs.keys())} to QASM, expecting {self.found_inputs}."
            )

        for output in self.outputs:
            context["return"][output] = context.retrieve_variable(output)

        return context

def pyplot_show(cls, *, block=None):
        managers = Gcf.get_all_fig_managers()
        if not managers:
            return
        for manager in managers:
            try:
                manager.show()  # Emits a warning for non-interactive backend.
            except NonGuiException as exc:
                _api.warn_external(str(exc))
        if block is None:
            # Hack: Are we in IPython's %pylab mode?  In pylab mode, IPython
            # (>= 0.10) tacks a _needmain attribute onto pyplot.show (always
            # set to False).
            pyplot_show = getattr(sys.modules.get("matplotlib.pyplot"), "show", None)
            ipython_pylab = hasattr(pyplot_show, "_needmain")
            block = not ipython_pylab and not is_interactive()
        if block:
            cls.start_main_loop()

def get_standalone_and_tied_modules(modules: list[nn.Module]) -> tuple[list[nn.Module], set[nn.Module]]:
    # Find all tied parameters (parameters that share the same memory) between modules
    seen_params: set[nn.Parameter] = set()
    tied_params: set[nn.Parameter] = set()
    for module in modules:
        for param in module.parameters():
            if param in seen_params:
                tied_params.add(param)
        # seen_params is only updated at module granularity
        for param in module.parameters():
            seen_params.add(param)

    # if a module has tied parameters, we add it to modules_with_tied_params
    modules_with_tied_params = set()
    for module in modules:
        for param in module.parameters():
            if param in tied_params:
                modules_with_tied_params.add(module)
                break

    # Modules to shard are those that have parameters and don't have tied parameters
    modules_to_shard = [
        module for module in modules if module not in modules_with_tied_params and
        next(module.parameters(), None) is not None  # Filter out modules with no parameters
    ]

    return modules_to_shard, modules_with_tied_params

def propagate_global_parameters(benchmarking_config: dict[str, Any]) -> dict[str, Any]:
    for experiment in benchmarking_config["experiments"]:
        if "experiment_name" not in experiment:
            experiment["experiment_name"] = benchmarking_config["experiment_name"]
        if "export" not in experiment:
            experiment["export"] = benchmarking_config["export"]
        if "hyperopt" not in experiment:
            experiment["hyperopt"] = benchmarking_config["hyperopt"]
        if "process_config_file_path" not in experiment:
            experiment["process_config_file_path"] = benchmarking_config["process_config_file_path"]
        if "profiler" not in experiment:
            experiment["profiler"] = benchmarking_config["profiler"]
    return benchmarking_config

def ones_matrix_band_part(rows, cols, num_lower, num_upper, out_shape=None):
  if all([isinstance(el, int) for el in [rows, cols, num_lower, num_upper]]):
    # Needed info is constant, so we construct in numpy
    if num_lower < 0:
      num_lower = rows - 1
    if num_upper < 0:
      num_upper = cols - 1
    lower_mask = np.tri(cols, rows, num_lower).T
    upper_mask = np.tri(rows, cols, num_upper)
    band = np.ones((rows, cols)) * lower_mask * upper_mask
    if out_shape:
      band = band.reshape(out_shape)
    band = tf.constant(band, tf.float32)
  else:
    band = tf.linalg.band_part(
        tf.ones([rows, cols]), tf.cast(num_lower, tf.int64),
        tf.cast(num_upper, tf.int64))
    if out_shape:
      band = tf.reshape(band, out_shape)

  return band

def set_bbox(self, rectprops):
        if rectprops is not None:
            props = rectprops.copy()
            boxstyle = props.pop("boxstyle", None)
            pad = props.pop("pad", None)
            if boxstyle is None:
                boxstyle = "square"
                if pad is None:
                    pad = 4  # points
                pad /= self.get_size()  # to fraction of font size
            else:
                if pad is None:
                    pad = 0.3
            # boxstyle could be a callable or a string
            if isinstance(boxstyle, str) and "pad" not in boxstyle:
                boxstyle += ",pad=%0.2f" % pad
            self._bbox_patch = FancyBboxPatch(
                (0, 0), 1, 1,
                boxstyle=boxstyle, transform=IdentityTransform(), **props)
        else:
            self._bbox_patch = None

        self._update_clip_properties()

def to_string(self, node=None, level=0):
        if node is None:
            if self.node is None:
                return '(null node)'
            else:
                node = self.node
        n = node.contents
        if self.type == Classification:
            format_str = format_leaf = format_node = None
        else:
            format_str = f"({self.domain.class_var.format_str}: %s)"
            format_leaf = " --> " + format_str
            format_node = "%s " + format_str
        if n.children_size == 0:
            if self.type == Classification:
                node_cont = [round(n.dist[i], 1)
                             for i in range(self.cls_vals)]
                index = node_cont.index(max(node_cont))
                major_class = self.cls_vars[0].values[index]
                return ' --> %s (%s)' % (major_class, node_cont)
            else:
                return format_leaf % (n.sum / n.n, n.n)
        else:
            attr = self.dom_attr[n.split_attr]
            node_desc = attr.name
            indent = '\n' + '   ' * level
            if self.type == Classification:
                node_cont = [round(n.dist[i], 1)
                             for i in range(self.cls_vals)]
                ret_str = indent + '%s (%s)' % (node_desc, node_cont)
            else:
                ret_str = indent + format_node % (node_desc, n.sum / n.n, n.n)
            for i in range(n.children_size):
                if attr.is_continuous:
                    split = '<=' if i % 2 == 0 else '>'
                    split += attr.format_str % n.split
                    ret_str += indent + ': %s' % split
                else:
                    ret_str += indent + ': %s' % attr.values[i]
                ret_str += self.to_string(n.children[i], level + 1)
            return ret_str

async def judge_response(self, question: str, reference_answer: str, assistant_answer: str) -> dict[str, Any]:
        try:
            prompt = self.judge_prompt.format(
                question=question,
                reference_answer=reference_answer,
                assistant_answer=assistant_answer,
            )

            messages = [{"role": "user", "content": prompt}]

            # Use appropriate token parameter based on model
            if "o3" in self.judge_engine.model.lower() or "o1" in self.judge_engine.model.lower():
                response = await self.judge_engine.get_model_response(messages=messages, max_completion_tokens=1000)
            else:
                response = await self.judge_engine.get_model_response(messages=messages, temperature=0.1, max_tokens=1000)

            judgment_text = response.text if hasattr(response, "text") else str(response)

            # Parse binary yes/no from judge output
            is_correct = False
            if "correct:" in judgment_text.lower():
                # Extract the yes/no after "correct:"
                try:
                    correct_line = [line for line in judgment_text.lower().split("\n") if "correct:" in line][0]
                    is_correct = "yes" in correct_line
                except (IndexError, ValueError):
                    is_correct = False

            return {
                "judgment": judgment_text,
                "is_correct": is_correct,
            }

        except Exception as e:
            print(f"Judge error: {e}")
            return {"judgment": f"Judge error: {e}", "is_correct": False}

def from_dict(cls, theme: dict[str, dict[str, str]]) -> ThemeClass:
        from gradio import __version__

        theme_gradio_version = theme.get("gradio_version")
        if theme_gradio_version:
            try:
                if __version__.split(".")[:2] != theme_gradio_version.split(".")[:2]:
                    warnings.warn(
                        f"This theme was created for Gradio {theme_gradio_version}, "
                        f"but you are using Gradio {__version__}. "
                        "Some styles may not work as expected."
                    )
            except (ValueError, IndexError):
                pass

        new_theme = cls()
        for prop, value in theme["theme"].items():
            setattr(new_theme, prop, value)

        # For backwards compatibility, load attributes in base theme not in the loaded theme from the base theme.
        base = Base()
        for attr in base.__dict__:
            if not attr.startswith("_") and not hasattr(new_theme, attr):
                setattr(new_theme, attr, getattr(base, attr))

        return new_theme

def on_key_press(self, event):
        if not event.inaxes:
            return
        if event.key == 't':
            self.showverts = not self.showverts
            self.line.set_visible(self.showverts)
            if not self.showverts:
                self._ind = None
        elif event.key == 'd':
            ind = self.get_ind_under_point(event)
            if ind is not None:
                self.poly.xy = np.delete(self.poly.xy,
                                         ind, axis=0)
                self.line.set_data(zip(*self.poly.xy))
        elif event.key == 'i':
            xys = self.poly.get_transform().transform(self.poly.xy)
            p = event.x, event.y  # display coords
            for i in range(len(xys) - 1):
                s0 = xys[i]
                s1 = xys[i + 1]
                d = dist_point_to_segment(p, s0, s1)
                if d <= self.epsilon:
                    self.poly.xy = np.insert(
                        self.poly.xy, i+1,
                        [event.xdata, event.ydata],
                        axis=0)
                    self.line.set_data(zip(*self.poly.xy))
                    break
        if self.line.stale:
            self.canvas.draw_idle()

def build_orbax_abstract_pytree(checkpoint_path, ref_state=None):
    if backend.backend() != "jax":
        return None

    if get_distribution() is None:
        return None

    import jax

    pytree_meta = ocp.pytree_metadata(checkpoint_path).metadata

    def _to_abstract(meta, ref=None):
        """Convert metadata leaf to `jax.ShapeDtypeStruct` with sharding."""
        if hasattr(meta, "shape") and hasattr(meta, "dtype"):
            sharding = getattr(ref, "sharding", None)
            return jax.ShapeDtypeStruct(
                meta.shape, meta.dtype, sharding=sharding
            )
        if isinstance(meta, dict):
            r = ref if isinstance(ref, dict) else {}
            return {k: _to_abstract(v, r.get(k)) for k, v in meta.items()}
        return None

    return {
        key: _to_abstract(val, (ref_state or {}).get(key))
        for key, val in pytree_meta.items()
    }

def is_incomplete_option(all_args, cmd_param):
    if not isinstance(cmd_param, Option):
        return False
    if cmd_param.is_flag:
        return False
    last_option = None
    for index, arg_str in enumerate(
        reversed([arg for arg in all_args if arg != WORDBREAK])
    ):
        if index + 1 > cmd_param.nargs:
            break
        if start_of_option(arg_str):
            last_option = arg_str

    return True if last_option and last_option in cmd_param.opts else False

def get_split_data_size(train_size, validate_size, test_size, data_count):
    # check & transform data set sizes
    if isinstance(test_size, float) or isinstance(train_size, float) or isinstance(validate_size, float):
        total_size = 1.0
    else:
        total_size = data_count
    if train_size is None:
        if validate_size is None:
            train_size = total_size - test_size
            validate_size = total_size - (test_size + train_size)
        else:
            if test_size is None:
                test_size = 0
            train_size = total_size - (validate_size + test_size)
    elif test_size is None:
        if validate_size is None:
            test_size = total_size - train_size
            validate_size = total_size - (test_size + train_size)
        else:
            test_size = total_size - (validate_size + train_size)
    elif validate_size is None:
        if train_size is None:
            train_size = total_size - test_size
        validate_size = total_size - (test_size + train_size)

    if abs((abs(train_size) + abs(test_size) + abs(validate_size)) - total_size) > 1e-6:
        raise ValueError(f"train_size, test_size, validate_size should sum up to 1.0 or data count")

    if isinstance(train_size, float):
        train_size = round(train_size * data_count)
        validate_size = round(validate_size * data_count)
        test_size = total_size - train_size - validate_size
    return train_size, validate_size, test_size

def ensure_frozen(mutable: Mutable | Any, *, strict: bool = True, sample: Sample | None = None, retries: int = 1000) -> Any:
    if not isinstance(mutable, Mutable):
        return mutable

    # If we're in a frozen context, just use the current.
    if sample is None:
        ctx = frozen_context.current()
        if ctx is not None:
            sample = ctx

    if sample is not None:
        # If we have a sample, we can just use it.
        # Use freeze here to detect potential label mismatch errors.
        try:
            return mutable.freeze(sample)
        except:
            _logger.error(
                'Failed to freeze mutable %s with sample %s. '
                'In NAS, please make sure to have registered it via add_mutable(). '
                'Otherwise, please make sure you are not inside a frozen_context.',
                mutable, sample)
            raise
    else:
        if retries < 0 or (_ENSURE_FROZEN_STRICT and strict):
            raise RuntimeError(
                f'No frozen context is found for {mutable!r}. Assuming no context. '
                'If you are using NAS, you are probably using `ensure_frozen` in forward, or outside the init of ModelSpace. '
                'Please avoid doing this as they will lead to erroneous results.'
            )

        # TODO: Currently only mutable parameters in NAS evaluator end up here.
        # It might cause consistency issues between multiple parameters without context.
        # I don't want to throw a warning here, but there should be a smarter way to do this.
        return mutable.robust_default(retries=retries)

def build_features(self, return_types=None, verbose=False):
        all_features = {}

        self.where_clauses = defaultdict(set)

        if return_types is None:
            return_types = [
                ColumnSchema(semantic_tags=["numeric"]),
                ColumnSchema(semantic_tags=["category"]),
                ColumnSchema(logical_type=Boolean),
                ColumnSchema(logical_type=BooleanNullable),
            ]
        elif return_types == "all":
            pass
        else:
            msg = "return_types must be a list, or 'all'"
            assert isinstance(return_types, list), msg

        self._run_dfs(
            self.es[self.target_dataframe_name],
            RelationshipPath([]),
            all_features,
            max_depth=self.max_depth,
        )

        new_features = list(all_features[self.target_dataframe_name].values())

        def filt(f):
            # remove identity features of the ID field of the target dataframe
            if (
                isinstance(f, IdentityFeature)
                and f.dataframe_name == self.target_dataframe_name
                and f.column_name == self.es[self.target_dataframe_name].ww.index
            ):
                return False

            return True

        # filter out features with undesired return types
        if return_types != "all":
            new_features = [
                f
                for f in new_features
                if any(
                    True
                    for schema in return_types
                    if is_valid_input(f.column_schema, schema)
                )
            ]
        new_features = list(filter(filt, new_features))

        new_features.sort(key=lambda f: f.get_depth())

        new_features = self._filter_features(new_features)

        if self.max_features > 0:
            new_features = new_features[: self.max_features]

        if verbose:
            print("Built {} features".format(len(new_features)))
            verbose = None
        return new_features

def tokenize(self, text: TextInput, **kwargs) -> list[str]:
        split_special_tokens = kwargs.pop("split_special_tokens", self.split_special_tokens)
        text, kwargs = self.prepare_for_tokenization(text, **kwargs)

        if split_special_tokens:
            # Don't split on any tokens - just tokenize directly
            return self._tokenize(text)

        # Split on added tokens
        tokens = self.tokens_trie.split(text)
        no_split_token = self._added_tokens_encoder.keys()

        # Handle added token properties (lstrip, rstrip, single_word)
        for i, token in enumerate(tokens):
            if token in no_split_token:
                tok_extended = self._added_tokens_decoder.get(self._added_tokens_encoder[token])
                left = tokens[i - 1] if i > 0 else None
                right = tokens[i + 1] if i < len(tokens) - 1 else None

                if isinstance(tok_extended, AddedToken):
                    if tok_extended.rstrip and right:
                        tokens[i + 1] = right.lstrip()
                    if tok_extended.lstrip and left:
                        tokens[i - 1] = left.rstrip()
                    if tok_extended.single_word:
                        if left and left[-1] != " ":
                            tokens[i - 1] += token
                            tokens[i] = ""
                        elif right and right[0] != " ":
                            tokens[i + 1] = token + tokens[i + 1]
                            tokens[i] = ""

        # Tokenize non-added tokens
        result = []
        all_special_tokens_set = set(self.all_special_tokens)
        for token in tokens:
            if not token:
                continue
            if token in no_split_token or token in all_special_tokens_set:
                result.append(token)
            else:
                result.extend(self._tokenize(token))

        return result

def cleanup(self) -> bool:
        if getattr(self, "_cleaned_up", False):
            return False

        self._cleaned_up = True

        # Get the directory to clean up
        scratch_dir = getattr(self, "scratch_dir", None)
        if scratch_dir is None:
            # No scratch dir - check if storage has memmap tensors with temp paths
            storage = getattr(self, "_storage", None)
            if storage is not None and is_tensor_collection(storage):
                # Get all memmap file paths and find their common directory
                paths = set()
                try:
                    for tensor in storage.values(include_nested=True, leaves_only=True):
                        if hasattr(tensor, "filename") and tensor.filename:
                            paths.add(os.path.dirname(tensor.filename))
                except Exception:
                    # Storage might be in an invalid state during cleanup
                    pass
                for path in paths:
                    if (
                        path
                        and os.path.isdir(path)
                        and path.startswith(tempfile.gettempdir())
                    ):
                        try:
                            shutil.rmtree(path)
                            torchrl_logger.debug(f"Cleaned up memmap directory: {path}")
                        except Exception:
                            # Ignore errors - file might be in use or already deleted
                            pass
                return bool(paths)
            return False

        # Clean up the scratch directory
        scratch_dir = scratch_dir.rstrip("/")
        if os.path.isdir(scratch_dir):
            try:
                shutil.rmtree(scratch_dir)
                torchrl_logger.debug(f"Cleaned up memmap directory: {scratch_dir}")
                return True
            except Exception as e:
                torchrl_logger.warning(f"Failed to clean up memmap directory: {e}")
                return False
        return False

def extract_validation_audio(self, pipeline_result: Any, expected_count: Optional[int] = None) -> Optional[list[Any]]:
        audio = None
        if hasattr(pipeline_result, "audio"):
            audio = pipeline_result.audio
        elif hasattr(pipeline_result, "audios"):
            audio = pipeline_result.audios

        if audio is None:
            return None

        if isinstance(audio, (list, tuple)):
            items = []
            for item in audio:
                if torch.is_tensor(item):
                    items.append(item.detach().cpu())
                else:
                    items.append(item)
        elif torch.is_tensor(audio) or isinstance(audio, np.ndarray):
            if torch.is_tensor(audio):
                audio = audio.detach().cpu()
            if getattr(audio, "ndim", 0) >= 3:
                items = [audio[idx] for idx in range(audio.shape[0])]
            else:
                items = [audio]
        else:
            logger.warning("Unsupported validation audio payload type %s", type(audio))
            return None

        if expected_count is not None and len(items) != expected_count:
            raise ValueError(f"Validation audio count ({len(items)}) does not match validation samples ({expected_count}).")

        return items

def convert_conll_token(token_conll):
        token_dict = {}
        for field, field_idx in FIELD_TO_IDX.items():
            value = token_conll[field_idx]
            if value == '' and field is FEATS:
                continue
            elif value != '_':
                if field is HEAD:
                    token_dict[field] = int(value)
                else:
                    token_dict[field] = value
        # special case if text is '_'
        if token_conll[FIELD_TO_IDX[TEXT]] == '_':
            token_dict[TEXT] = token_conll[FIELD_TO_IDX[TEXT]]
            token_dict[LEMMA] = token_conll[FIELD_TO_IDX[LEMMA]]
        return token_dict

def to(
        self,
        t: Union[Type[trt.DeviceType], Type[DeviceType]],
        use_default: bool = False,
    ) -> Union[trt.DeviceType, DeviceType]:

        if t == trt.DeviceType:
            if self == DeviceType.GPU:
                return trt.DeviceType.GPU
            elif self == DeviceType.DLA:
                return trt.DeviceType.DLA
            elif use_default:
                return trt.DeviceType.GPU
            else:
                raise ValueError(
                    "Provided an unsupported device type (support: GPU/DLA)"
                )

        elif t == DeviceType:
            return self

        elif ENABLED_FEATURES.torchscript_frontend:
            from torch_tensorrt import _C

            if t == _C.DeviceType:
                if self == DeviceType.GPU:
                    return _C.DeviceType.GPU
                elif self == DeviceType.DLA:
                    return _C.DeviceType.DLA
                else:
                    raise ValueError(
                        "Provided an unsupported device type (support: GPU/DLA)"
                    )
        # else: # commented out for mypy
        raise TypeError(
            "Provided unsupported destination type for device type conversion"
        )

def add(self, other, tol=None):
        if tol is None:
            tol = self.tol

        if isinstance(other, (qml.pauli.PauliWord, qml.pauli.PauliSentence, Operator)):
            other = [other]

        other = [
            qml.pauli.pauli_sentence(op) if not isinstance(op, qml.pauli.PauliSentence) else op
            for op in other
        ]

        for ps in other:
            # TODO: Potential speed-up by computing the maximal linear independent set for all current basis vectors + other, essentially algorithm1 in https://arxiv.org/abs/1012.5256
            (
                self._M,
                self._pw_to_idx,
                self._rank,
                self._num_pw,
                is_independent,
            ) = self._check_independence(
                self._M, ps, self._pw_to_idx, self._rank, self._num_pw, tol
            )
            if is_independent:
                self._basis.append(ps)
        return self._basis

def update_document_parent_tags(tag: Tag, new_parent: Tag) -> None:
    doc_tag_relationship = Document.tags.through

    doc_ids: list[int] = list(
        Document.objects.filter(tags=tag).values_list("pk", flat=True),
    )

    if not doc_ids:
        return

    parent_ids = [new_parent.id, *new_parent.get_ancestors_pks()]

    parent_ids = list(dict.fromkeys(parent_ids))

    existing_pairs = set(
        doc_tag_relationship.objects.filter(
            document_id__in=doc_ids,
            tag_id__in=parent_ids,
        ).values_list("document_id", "tag_id"),
    )

    to_create: list = []
    affected: set[int] = set()

    for doc_id in doc_ids:
        for parent_id in parent_ids:
            if (doc_id, parent_id) in existing_pairs:
                continue

            to_create.append(
                doc_tag_relationship(document_id=doc_id, tag_id=parent_id),
            )
            affected.add(doc_id)

    if to_create:
        doc_tag_relationship.objects.bulk_create(
            to_create,
            ignore_conflicts=True,
        )

    if affected:
        bulk_update_documents.delay(document_ids=list(affected))

def refresh(self, instance_ids: List[str]) -> None:
        if not os.path.exists(self.path):
            return
        with open(self.path, 'r', encoding='utf-8') as f:
            metadata = json.load(f)
        for instance_id in list(metadata.keys()):
            if instance_id not in instance_ids:
                del metadata[instance_id]
        if not metadata:
            os.remove(self.path)
            return
        with open(self.path, 'w', encoding='utf-8') as f:
            json.dump(metadata, f)

def group_observables(
    observables: list["qml.operation.Operator"],
    coefficients: TensorLike | None = None,
    grouping_type: Literal["qwc", "commuting", "anticommuting"] = "qwc",
    method: Literal["lf", "rlf", "dsatur", "gis"] = "lf",
):

    if coefficients is not None and qml.math.shape(coefficients)[0] != len(observables):
        raise IndexError("The coefficients list must be the same length as the observables list.")

    # Separate observables based on whether they have wires or not.
    no_wires_obs, wires_obs = [], []

    for ob in observables:
        if len(ob.wires) == 0:
            no_wires_obs.append(ob)
        else:
            wires_obs.append(ob)

    # Handle case where all observables have no wires
    if not wires_obs:
        if coefficients is None:
            return [observables]
        return [observables], [coefficients]

    # Initialize PauliGroupingStrategy
    pauli_groupper = PauliGroupingStrategy(
        wires_obs, grouping_type=grouping_type, graph_colourer=method
    )

    partitioned_paulis = pauli_groupper.partition_observables()

    # Add observables without wires back to the first partition
    partitioned_paulis[0].extend(no_wires_obs)

    if coefficients is None:
        return partitioned_paulis

    partitioned_coeffs = _partition_coeffs(partitioned_paulis, observables, coefficients)

    return partitioned_paulis, partitioned_coeffs

def repr_class(
    obj,
    attributes: list[str] | dict[str, Any],
    max_characters_before_break: int = 100,
    extra_attributes: dict[str, Any] = None,
) -> str:
    if extra_attributes is None:
        extra_attributes = {}
    # get attributes
    if isinstance(attributes, tuple | list):
        attributes = {
            name: getattr(obj, name) for name in attributes if hasattr(obj, name)
        }
    attributes_strings = [f"{name}={repr(value)}" for name, value in attributes.items()]
    # get header
    header_name = obj.__class__.__name__
    # add extra attributes
    if len(extra_attributes) > 0:
        extra_attributes_strings = [
            f"{name}={repr(value)}" for name, value in extra_attributes.items()
        ]
        if (
            len(header_name) + 2 + len(", ".join(extra_attributes_strings))
            > max_characters_before_break
        ):
            header = f"{header_name}[\n\t" + ",\n\t".join(attributes_strings) + "\n]("
        else:
            header = f"{header_name}[{', '.join(extra_attributes_strings)}]("
    else:
        header = f"{header_name}("

    # create final representation
    attributes_string = ", ".join(attributes_strings)
    if (
        len(attributes_string) + len(header.split("\n")[-1]) + 1
        > max_characters_before_break
    ):
        attributes_string = "\n\t" + ",\n\t".join(attributes_strings) + "\n"
    return f"{header}{attributes_string})"

def fit(self, X, y, sample_weight=None, **fit_params):
        if not hasattr(self.estimator, "fit"):
            raise ValueError("The base estimator should implement a fit method")

        y = validate_data(self, X="no_validation", y=y, multi_output=True)

        if is_classifier(self):
            check_classification_targets(y)

        if y.ndim == 1:
            raise ValueError(
                "y must have at least two dimensions for "
                "multi-output regression but has only one."
            )

        if _routing_enabled():
            if sample_weight is not None:
                fit_params["sample_weight"] = sample_weight
            routed_params = process_routing(
                self,
                "fit",
                **fit_params,
            )
        else:
            if sample_weight is not None and not has_fit_parameter(
                self.estimator, "sample_weight"
            ):
                raise ValueError(
                    "Underlying estimator does not support sample weights."
                )

            fit_params_validated = _check_method_params(X, params=fit_params)
            routed_params = Bunch(estimator=Bunch(fit=fit_params_validated))
            if sample_weight is not None:
                routed_params.estimator.fit["sample_weight"] = sample_weight

        self.estimators_ = Parallel(n_jobs=self.n_jobs)(
            delayed(_fit_estimator)(
                self.estimator, X, y[:, i], **routed_params.estimator.fit
            )
            for i in range(y.shape[1])
        )

        if hasattr(self.estimators_[0], "n_features_in_"):
            self.n_features_in_ = self.estimators_[0].n_features_in_
        if hasattr(self.estimators_[0], "feature_names_in_"):
            self.feature_names_in_ = self.estimators_[0].feature_names_in_

        return self

def rebase(self, start_index: int = None, end_index: int = None):
        storage_si = self.start_index
        storage_ei = self.end_index
        if storage_si is None or storage_ei is None:
            raise ValueError("storage.start_index or storage.end_index is None, storage may not exist")

        start_index = storage_si if start_index is None else start_index
        end_index = storage_ei if end_index is None else end_index

        if start_index is None or end_index is None:
            logger.warning("both start_index and end_index are None, or storage does not exist; rebase is ignored")
            return

        if start_index < 0 or end_index < 0:
            logger.warning("start_index or end_index cannot be less than 0")
            return
        if start_index > end_index:
            logger.warning(
                f"start_index({start_index}) > end_index({end_index}), rebase is ignored; "
                f"if you need to clear the FeatureStorage, please execute: FeatureStorage.clear"
            )
            return

        if start_index <= storage_si:
            self.write([np.nan] * (storage_si - start_index), start_index)
        else:
            self.rewrite(self[start_index:].values, start_index)

        if end_index >= self.end_index:
            self.write([np.nan] * (end_index - self.end_index))
        else:
            self.rewrite(self[: end_index + 1].values, start_index)

def gen_dependency_with_stages(
    compute_stages: List[PipelineComputation],
    num_mesh: int,
    apply_grad_stages: List[PipelineComputation] = ()):
    n_stages = len(compute_stages) + len(apply_grad_stages)
    d = np.zeros([n_stages, n_stages], dtype=int)
    var_stage_id = {}
    fwd_intermediate_vars = OrderedSet()
    for i, stage in enumerate(itertools.chain(compute_stages,
                                              apply_grad_stages)):
        for var in stage.invars:
            if var in var_stage_id:
                d[i, var_stage_id[var]] = 1
                if i < num_mesh and var_stage_id[var] != 2 * num_mesh - i - 1:
                    # not the var from forward to backward. we don't care them.
                    # not the var on the backward side
                    fwd_intermediate_vars.add(var)
            else:
                # Assume the var is from global_invars
                pass
        for var in stage.outvars:
            var_stage_id[var] = i

    return d, fwd_intermediate_vars

def process_document(file_path: str) -> str:
            if not os.path.exists(file_path):
                return f"Error: File not found - {file_path}"

            try:
                if file_path.lower().endswith(".pdf"):
                    with open(file_path, "rb") as file:
                        pdf_reader = PyPDF2.PdfReader(file)
                        text = ""
                        for page in pdf_reader.pages:
                            text += page.extract_text() + "\n"
                        return text
                else:
                    # Handle other document types (txt, docx, etc.)
                    with open(
                        file_path, "r", encoding="utf-8"
                    ) as file:
                        return file.read()
            except Exception as e:
                return f"Error processing {file_path}: {str(e)}"

def result(
        self: Self,
        timeout: float | None = None,
        raise_on_failure: bool = True,
    ) -> list[R]:
        # Build a mapping from each unique future to every index it occupies
        # so that we can handle duplicates and preserve ordering.
        future_to_indices: dict[PrefectFuture[R], list[int]] = {}
        for idx, future in enumerate(self):
            future_to_indices.setdefault(future, []).append(idx)

        results: list[R] = [None] * len(self)  # type: ignore[list-item]

        try:
            # Wrap the entire loop in timeout_context so that both the wait
            # for futures *and* any slow result retrieval (e.g. large data
            # deserialization) are bounded by the caller's timeout.
            with timeout_context(timeout):
                # as_completed de-duplicates internally; each unique future
                # is yielded exactly once, in completion order.
                for future in as_completed(list(self), timeout=timeout):
                    result = future.result(raise_on_failure=raise_on_failure)
                    for i in future_to_indices[future]:
                        results[i] = result
        except TimeoutError as exc:
            # timeout came from inside the task
            if "Scope timed out after {timeout} second(s)." not in str(exc):
                raise
            raise TimeoutError(
                f"Timed out waiting for all futures to complete within {timeout} seconds"
            ) from exc

        return results

def to_pyro_module_(m: torch.nn.Module, recurse: bool = True) -> None:
    if not isinstance(m, torch.nn.Module):
        raise TypeError("Expected an nn.Module instance but got a {}".format(type(m)))

    if isinstance(m, PyroModule):
        if recurse:
            for name, module in list(m._modules.items()):
                if TYPE_CHECKING:
                    assert module is not None
                to_pyro_module_(module)
                setattr(m, name, module)
        return

    # Change m's type in-place.
    m.__class__ = PyroModule[m.__class__]
    assert isinstance(m, PyroModule)
    m._pyro_name = ""
    m._pyro_context = _Context()
    m._pyro_params = OrderedDict()
    m._pyro_samples = OrderedDict()

    # Reregister parameters and submodules.
    for name, param in list(m._parameters.items()):
        setattr(m, name, param)
    for name, module in list(m._modules.items()):
        if recurse:
            if TYPE_CHECKING:
                assert module is not None
            to_pyro_module_(module)
        setattr(m, name, module)

def get_xyz_dict(free_only=True):
    import collections

    import xyzservices.providers as xyz

    def _unpack_sub_parameters(var, param):
        temp = var
        for sub_param in param.split("."):
            temp = getattr(temp, sub_param)
        return temp

    xyz_dict = {}
    for item in xyz.values():
        try:
            name = item["name"]
            tile = _unpack_sub_parameters(xyz, name)
            if _unpack_sub_parameters(xyz, name).requires_token():
                if free_only:
                    pass
                else:
                    xyz_dict[name] = tile
            else:
                xyz_dict[name] = tile

        except Exception:
            for sub_item in item:
                name = item[sub_item]["name"]
                tile = _unpack_sub_parameters(xyz, name)
                if _unpack_sub_parameters(xyz, name).requires_token():
                    if free_only:
                        pass
                    else:
                        xyz_dict[name] = tile
                else:
                    xyz_dict[name] = tile

    xyz_dict = collections.OrderedDict(sorted(xyz_dict.items()))
    return xyz_dict

def attach(
        self,
        engine: Engine,
        event: str | Events | CallableEventWithFilter | EventsList = Events.ITERATION_COMPLETED,
    ) -> None:
        if hasattr(engine.state, self.param_name):
            if self.create_new:
                raise ValueError(
                    f"Attribute '{self.param_name}' already exists in the engine.state. "
                    f"This may be a conflict between multiple handlers. "
                    f"Please choose another name."
                )
        else:
            if not self.create_new:
                warnings.warn(
                    f"Attribute '{self.param_name}' is not defined in the engine.state. "
                    f"{type(self).__name__} will create it. Remove this warning by setting create_new=True."
                )
            setattr(engine.state, self.param_name, None)

        if self.save_history:
            if not hasattr(engine.state, "param_history") or engine.state.param_history is None:
                setattr(engine.state, "param_history", {})
            engine.state.param_history.setdefault(self.param_name, [])  # type: ignore[attr-defined]

        engine.add_event_handler(event, self)

def putmask(self, mask: npt.NDArray[np.bool_], value: object) -> Index:
        mask, noop = validate_putmask(self._values, mask)
        if noop:
            return self.copy()

        if self.dtype != object and is_valid_na_for_dtype(value, self.dtype):
            # e.g. None -> np.nan, see also Block._standardize_fill_value
            value = self._na_value

        try:
            converted = self._validate_fill_value(value)
        except (LossySetitemError, ValueError, TypeError) as err:
            if is_object_dtype(self.dtype):  # pragma: no cover
                raise err

            # See also: Block.coerce_to_target_dtype
            dtype = self._find_common_type_compat(value)
            if dtype == self.dtype:
                # GH#56376 avoid RecursionError
                raise AssertionError(
                    "Something has gone wrong. Please report a bug at "
                    "github.com/pandas-dev/pandas"
                ) from err
            return self.astype(dtype).putmask(mask, value)

        values = self._values.copy()

        if isinstance(values, np.ndarray):
            converted = setitem_datetimelike_compat(values, mask.sum(), converted)
            if isinstance(converted, tuple):
                # GH#37681 np.putmask unpacks tuples, so wrap in an
                #  object array to ensure the tuple is treated as a scalar
                fill_arr = np.empty(1, dtype=object)
                fill_arr[0] = converted
                converted = fill_arr
            np.putmask(values, mask, converted)  # pyright: ignore[reportArgumentType]

        else:
            # Note: we use the original value here, not converted, as
            #  _validate_fill_value is not idempotent
            values._putmask(mask, value)

        return self._shallow_copy(values)

def get_feature_arraycol_map(processor, max_category_levels):
    feature_preserving_transforms = set(
        ["continuous", "skewed", "ordinal", "bool", "remainder"]
    )  # these transforms do not alter dimensionality of feature
    feature_arraycol_map = {}  # unordered version
    current_colindex = 0
    for transformer in processor.transformers_:
        transformer_name = transformer[0]
        transformed_features = transformer[2]
        if transformer_name in feature_preserving_transforms:
            for feature in transformed_features:
                if feature in feature_arraycol_map:
                    raise ValueError("same feature is processed by two different column transformers: %s" % feature)
                feature_arraycol_map[feature] = [current_colindex]
                current_colindex += 1
        elif transformer_name == "onehot":
            oh_encoder = [step for (name, step) in transformer[1].steps if name == "onehot"][0]
            for i in range(len(transformed_features)):
                feature = transformed_features[i]
                if feature in feature_arraycol_map:
                    raise ValueError("same feature is processed by two different column transformers: %s" % feature)
                oh_dimensionality = min(len(oh_encoder.categories_[i]), max_category_levels + 1)
                feature_arraycol_map[feature] = list(range(current_colindex, current_colindex + oh_dimensionality))
                current_colindex += oh_dimensionality
        else:
            raise ValueError("unknown transformer encountered: %s" % transformer_name)
    return OrderedDict([(key, feature_arraycol_map[key]) for key in feature_arraycol_map])

def supervised_training_step_amp(
    model: torch.nn.Module,
    optimizer: torch.optim.Optimizer,
    loss_fn: Callable[[Any, Any], torch.Tensor] | torch.nn.Module,
    device: str | torch.device | None = None,
    non_blocking: bool = False,
    prepare_batch: Callable = _prepare_batch,
    model_transform: Callable[[Any], Any] = lambda output: output,
    output_transform: Callable[[Any, Any, Any, torch.Tensor], Any] = lambda x, y, y_pred, loss: loss.item(),
    scaler: GradScaler | None = None,
    gradient_accumulation_steps: int = 1,
    model_fn: Callable[[torch.nn.Module, Any], Any] = lambda model, x: model(x),
) -> Callable:

    try:
        from torch.amp import autocast
    except ImportError:
        raise ImportError("Please install torch>=1.12.0 to use amp_mode='amp'.")

    if gradient_accumulation_steps <= 0:
        raise ValueError(
            "Gradient_accumulation_steps must be strictly positive. "
            "No gradient accumulation if the value set to one (default)."
        )

    def update(engine: Engine, batch: Sequence[torch.Tensor]) -> Any | tuple[torch.Tensor]:
        if (engine.state.iteration - 1) % gradient_accumulation_steps == 0:
            optimizer.zero_grad()
        model.train()
        x, y = prepare_batch(batch, device=device, non_blocking=non_blocking)
        with autocast("cuda", enabled=True):
            output = model_fn(model, x)
            y_pred = model_transform(output)
            loss = loss_fn(y_pred, y)
            if gradient_accumulation_steps > 1:
                loss = loss / gradient_accumulation_steps
        if scaler:
            cast(torch.Tensor, scaler.scale(loss)).backward()
            if engine.state.iteration % gradient_accumulation_steps == 0:
                scaler.step(optimizer)
                scaler.update()
        else:
            loss.backward()
            if engine.state.iteration % gradient_accumulation_steps == 0:
                optimizer.step()
        return output_transform(x, y, y_pred, loss * gradient_accumulation_steps)

    return update

def dag_from_functions(
    functions,
    output="output",
    params=None,
    parallel=False,
    dependencies=None,
    hot_reload=True,
):
    dependencies = dependencies or dict()
    params = params or dict()

    # NOTE: cache_rendered_status isn't doing anything. I modified Product
    # to look at the hot_reload flag for the hot reloading to work. I don't
    # think we're using the cache_rendered_status anywhere, so we should
    # delete it.
    configurator = DAGConfigurator()
    configurator.params.hot_reload = hot_reload
    dag = configurator.create()

    if parallel:
        dag.executor = ParallelDill()
    else:
        # need to disable subprocess, otherwise pickling will fail since
        # functions might be defined in the __main__ module
        dag.executor = Serial(build_in_subprocess=False)

    for callable_ in functions:
        if callable_.__name__ in params:
            params_task = params[callable_.__name__]
        else:
            params_task = dict()

        # if decorated, call with grid
        if hasattr(callable_, "__ploomber_grid__"):
            for i, items in enumerate(
                chain(
                    *(ParamGrid(grid).product() for grid in callable_.__ploomber_grid__)
                )
            ):
                _make_task(
                    callable_,
                    dag=dag,
                    params={**params_task, **items},
                    output=output,
                    call_with_args=callable_.__name__ in dependencies,
                    suffix=i,
                )
        else:
            _make_task(
                callable_,
                dag=dag,
                params=params_task,
                output=output,
                call_with_args=callable_.__name__ in dependencies,
            )

    for name in dag._iter():
        # check if there are manually declared dependencies
        if name in dependencies:
            upstream = dependencies[name]
        else:
            upstream = _get_upstream(dag[name].source.primitive)

        for up in upstream:
            dag[name].set_upstream(dag[up])

    return dag

def execute_function_with_dict(
        self, func_dict: dict, func_name: Optional[str] = None
    ) -> Any:
        if not isinstance(func_dict, dict):
            raise ToolValidationError(
                "func_dict must be a dictionary"
            )

        try:
            self._log_if_verbose(
                "debug", f"Executing function with dict: {func_dict}"
            )

            # Check if func_name is provided in the dict or as parameter
            if func_name is None:
                func_name = func_dict.get("name") or func_dict.get(
                    "function_name"
                )
                if func_name is None:
                    raise ToolValidationError(
                        "Function name not provided and not found in func_dict"
                    )

            self._log_if_verbose(
                "debug", f"Looking for function: {func_name}"
            )

            # Find the function
            func = self.find_function_name(func_name)
            if func is None:
                raise ToolNotFoundError(
                    f"Function {func_name} not found"
                )

            # Remove function name from parameters before executing
            execution_dict = func_dict.copy()
            execution_dict.pop("name", None)
            execution_dict.pop("function_name", None)

            self._log_if_verbose(
                "debug", f"Executing function {func_name}"
            )
            result = func(**execution_dict)

            self._log_if_verbose(
                "debug", f"Successfully executed {func_name}"
            )
            return result

        except (ToolValidationError, ToolNotFoundError):
            raise
        except Exception as e:
            self._log_if_verbose(
                "error", f"Failed to execute function with dict: {e}"
            )
            raise ToolExecutionError(
                f"Failed to execute function with dict: {e}"
            ) from e

def run(
        self,
        task: str,
        img: Optional[str] = None,
        imgs: Optional[List[str]] = None,
        streaming_callback: Optional[
            Callable[[str, str, bool], None]
        ] = None,
    ):
        try:
            if self.show_dashboard:
                result = self.run_with_dashboard(
                    task, img, imgs, streaming_callback
                )
            else:
                result = self._run(
                    task, img, imgs, streaming_callback
                )

            # Save conversation history after successful execution
            if self.autosave and self.swarm_workspace_dir:
                try:
                    self._save_conversation_history()
                except Exception as e:
                    logger.warning(
                        f"Failed to save conversation history: {e}"
                    )

            return result
        except Exception:
            # Save conversation history on error
            if self.autosave and self.swarm_workspace_dir:
                try:
                    self._save_conversation_history()
                except Exception as save_error:
                    logger.warning(
                        f"Failed to save conversation history on error: {save_error}"
                    )
            raise
        finally:
            # Always cleanup resources
            self.cleanup()

def init_entities(self):
        if self.entity_provider == self.provider and self.entity_schema == self.data_schema:
            self.entity_session = self.session
        else:
            self.entity_session = get_db_session(provider=self.entity_provider, data_schema=self.entity_schema)

        if self.day_data:
            if not self.end_timestamp:
                self.end_timestamp = now_date_time_str()
            df = self.data_schema.query_data(
                start_timestamp=self.end_timestamp, columns=["entity_id", "timestamp"], provider=self.provider
            )
            if pd_is_not_null(df):
                entity_ids = df["entity_id"].tolist()
                self.logger.info(f"ignore entity_ids:{entity_ids}")
                if self.entity_filters:
                    self.entity_filters.append(self.entity_schema.entity_id.notin_(entity_ids))
                else:
                    self.entity_filters = [self.entity_schema.entity_id.notin_(entity_ids)]

        #: init the entity list
        self.entities = get_entities(
            session=self.entity_session,
            entity_schema=self.entity_schema,
            exchanges=self.exchanges,
            entity_ids=self.entity_ids,
            codes=self.codes,
            return_type="domain",
            provider=self.entity_provider,
            filters=self.entity_filters,
        )

def process_directive(match: re.Match) -> str:
    obj_path = match.group(1)
    options_text = match.group(2) or ""

    # Parse options (simple YAML-like parsing)
    options = {}
    current_key = None
    current_list = []

    # Normalize indentation by removing common leading whitespace
    lines = options_text.split("\n")
    non_empty_lines = [l for l in lines if l.strip()]
    if non_empty_lines:
        min_indent = min(len(l) - len(l.lstrip()) for l in non_empty_lines)
        normalized_lines = [
            (l[min_indent:] if len(l) > min_indent else l) for l in lines
        ]
    else:
        normalized_lines = lines

    for line in normalized_lines:
        if not line.strip():
            continue

        # Check indentation level (relative to normalized base)
        indent = len(line) - len(line.lstrip())
        line = line.strip()

        if indent == 0 and ":" in line:
            # Save previous list if exists
            if current_key and current_list:
                options[current_key] = current_list
                current_list = []

            # New key
            key, value = line.split(":", 1)
            current_key = key.strip()
            value = value.strip()

            if value:
                # Inline value
                if value.lower() == "true":
                    options[current_key] = True
                elif value.lower() == "false":
                    options[current_key] = False
                elif value.isdigit():
                    options[current_key] = int(value)
                else:
                    options[current_key] = value
                current_key = None
        elif line.startswith("- ") and current_key:
            # List item
            current_list.append(line[2:].strip())

    # Save final list if exists
    if current_key and current_list:
        options[current_key] = current_list

    return render_api_doc(obj_path, options)

def compute_execution_waves(
        self,
        nodes: dict[str, DbtNode] | None = None,
    ) -> list[ExecutionWave]:
        if nodes is None:
            nodes = self.get_executable_nodes()

        if not nodes:
            return []

        # Build in-degree map (count of unresolved dependencies)
        in_degree: dict[str, int] = {}
        for node_id, node in nodes.items():
            # Only count dependencies that are in our executable nodes
            deps_in_graph = [d for d in node.depends_on if d in nodes]
            in_degree[node_id] = len(deps_in_graph)

        # Build dependents map (who depends on each node)
        dependents: dict[str, list[str]] = {node_id: [] for node_id in nodes}
        for node_id, node in nodes.items():
            for dep_id in node.depends_on:
                if dep_id in dependents:
                    dependents[dep_id].append(node_id)

        # Kahn's algorithm
        waves: list[ExecutionWave] = []
        current_wave = [node_id for node_id, degree in in_degree.items() if degree == 0]

        processed_count = 0
        wave_number = 0

        while current_wave:
            # Create wave with current nodes
            wave_nodes = [nodes[node_id] for node_id in current_wave]
            waves.append(ExecutionWave(wave_number=wave_number, nodes=wave_nodes))
            processed_count += len(current_wave)

            # Find next wave
            next_wave: list[str] = []
            for node_id in current_wave:
                for dependent_id in dependents[node_id]:
                    in_degree[dependent_id] -= 1
                    if in_degree[dependent_id] == 0:
                        next_wave.append(dependent_id)

            current_wave = next_wave
            wave_number += 1

        # Check for cycles
        if processed_count != len(nodes):
            raise ValueError(
                "Dependency graph contains cycles. "
                f"Processed {processed_count} of {len(nodes)} nodes."
            )

        return waves

def lift(
    mod: nn.Module,
    *,
    name: str,
) -> Callable[..., Any]:
  mod = _flax_transform_with_state(mod)
  init_fn, updater = hk.lift_with_state(mod.init, name=name, allow_reuse=True)
  updater._used = True  # pylint: disable=protected-access

  def wrapped(*args, **kwargs):
    init_kwargs = dict(kwargs)
    if hk.running_init():
      if 'rngs' not in init_kwargs:
        init_rng = hk.maybe_next_rng_key()
      elif isinstance(init_kwargs['rngs'], Mapping):
        init_rng = dict(init_kwargs.pop('rngs'))
        if 'params' not in init_rng:
          rng = hk.maybe_next_rng_key()
          if rng is not None:
            init_rng['params'] = rng
      else:
        raise flax.errors.InvalidRngError(
            'rngs should be a dictionary mapping strings to `jax.PRNGKey`.'
        )
    else:
      init_rng = None
    params, state = init_fn(init_rng, *args, **init_kwargs)
    out, state = mod.apply(params, state, None, *args, **kwargs)
    updater._used = False  # pylint: disable=protected-access
    updater.update(state)
    return out

  return wrapped

def step(self):
        if self._chart is None:
            raise ValueError("Parser must be initialized first")
        while True:
            self._restart = False
            w = 50 // (self._chart.num_leaves() + 1)

            for e in self._parse():
                if self._trace > 1:
                    print(self._current_chartrule)
                if self._trace > 0:
                    print(self._chart.pretty_format_edge(e, w))
                yield e
                if self._restart:
                    break
            else:
                yield None  # No more edges.

def switch_image(self, mode):
        if not self.parent().image_list:
            return

        if mode == "jump":
            user_input = int(self.page_input.text())
            current_index = user_input - 1
            if current_index < 0 or current_index >= len(
                self.parent().image_list
            ):
                return
        elif mode == "prev":
            current_index = self.parent().image_list.index(
                self.parent().filename
            )
            if current_index <= 0:
                return
            current_index -= 1
        elif mode == "next":
            current_index = self.parent().image_list.index(
                self.parent().filename
            )
            if current_index >= len(self.parent().image_list) - 1:
                return
            current_index += 1

        try:
            self.switching_image = True

            original_sizes = self.main_splitter.sizes()
            was_collapsed = original_sizes[0] == 0

            self.save_current_image_data()
            new_file = self.parent().image_list[current_index]
            self.parent().load_file(new_file)
            self.update_image_display()
            self.update_navigation_state()
            self.clear_all_components_silent()
            self.load_current_image_data()

            def restore_panel_state():
                if was_collapsed:
                    self.main_splitter.setSizes([0, PANEL_SIZE])
                    self.toggle_panel_button_right.setVisible(True)
                else:
                    self.main_splitter.setSizes([PANEL_SIZE, PANEL_SIZE])
                    self.toggle_panel_button_right.setVisible(False)

            QTimer.singleShot(10, restore_panel_state)

            self.switching_image = False
        except (ValueError, AttributeError):
            self.switching_image = False

def score_file(filename):
  # Prepare model.
  hparams = create_hparams()
  encoders = registry.problem(FLAGS.problem).feature_encoders(FLAGS.data_dir)
  has_inputs = "inputs" in encoders

  # Prepare features for feeding into the model.
  if has_inputs:
    inputs_ph = tf.placeholder(dtype=tf.int32)  # Just length dimension.
    batch_inputs = tf.reshape(inputs_ph, [1, -1, 1, 1])  # Make it 4D.
  targets_ph = tf.placeholder(dtype=tf.int32)  # Just length dimension.
  batch_targets = tf.reshape(targets_ph, [1, -1, 1, 1])  # Make it 4D.
  if has_inputs:
    features = {"inputs": batch_inputs, "targets": batch_targets}
  else:
    features = {"targets": batch_targets}

  # Prepare the model and the graph when model runs on features.
  model = registry.model(FLAGS.model)(hparams, tf_estimator.ModeKeys.EVAL)
  _, losses = model(features)
  saver = tf.train.Saver()

  with tf.Session() as sess:
    # Load weights from checkpoint.
    if FLAGS.checkpoint_path is None:
      ckpts = tf.train.get_checkpoint_state(FLAGS.output_dir)
      ckpt = ckpts.model_checkpoint_path
    else:
      ckpt = FLAGS.checkpoint_path
    saver.restore(sess, ckpt)
    # Run on each line.
    with tf.gfile.Open(filename) as f:
      lines = f.readlines()
    results = []
    for line in lines:
      tab_split = line.split("\t")
      if len(tab_split) > 2:
        raise ValueError("Each line must have at most one tab separator.")
      if len(tab_split) == 1:
        targets = tab_split[0].strip()
      else:
        targets = tab_split[1].strip()
        inputs = tab_split[0].strip()
      # Run encoders and append EOS symbol.
      targets_numpy = encoders["targets"].encode(
          targets) + [text_encoder.EOS_ID]
      if has_inputs:
        inputs_numpy = encoders["inputs"].encode(inputs) + [text_encoder.EOS_ID]
      # Prepare the feed.
      if has_inputs:
        feed = {inputs_ph: inputs_numpy, targets_ph: targets_numpy}
      else:
        feed = {targets_ph: targets_numpy}
      # Get the score.
      np_loss = sess.run(losses["training"], feed)
      results.append(np_loss)
  return results

def read_metrics_from_file(
    metrics_file_path: str, problem_type: str
) -> Tuple[Dict[str, Any], Optional[List[Dict[str, Any]]]]:
  with open(metrics_file_path) as metrics_file:
    all_metrics = json.loads(metrics_file.read())
    if problem_type in ULM_TASKS:
      return {'metrics': to_value(all_metrics)}, None
    all_metrics = all_metrics['slicedMetrics']
    all_sliced_metrics = []
    for slice_idx in range(len(all_metrics)):
      one_slice = all_metrics[slice_idx]
      if problem_type == 'classification':
        if (
            'metrics' in one_slice
            and 'classification' in one_slice['metrics']
            and 'confusionMatrix' in one_slice['metrics']['classification']
            and 'annotationSpecs'
            in one_slice['metrics']['classification']['confusionMatrix']
            and 'confidenceMetrics' in one_slice['metrics']['classification']
            and len(
                one_slice['metrics']['classification']['confusionMatrix'][
                    'annotationSpecs'
                ]
            )
            > 100
        ):
          confidence_metrics = one_slice['metrics']['classification'][
              'confidenceMetrics'
          ]
          for idx in range(len(confidence_metrics)):
            if 'confusionMatrix' in confidence_metrics[idx]:
              del confidence_metrics[idx]['confusionMatrix']
          one_slice['metrics']['classification'][
              'confidenceMetrics'
          ] = confidence_metrics

      all_sliced_metrics.append({
          **one_slice,
          'metrics': to_value(next(iter(one_slice['metrics'].values()))),
      })
  overall_slice = all_sliced_metrics[0]
  sliced_metrics = all_sliced_metrics[1:]
  return overall_slice, sliced_metrics

def predict_residuals(self, y=None, X=None):
        self.check_is_fitted()

        # clone self._fh to avoid any side-effects to self due to calling _check_fh
        # and predict()
        if self._fh is not None:
            fh_orig = deepcopy(self._fh)
        else:
            fh_orig = None

        # if no y is passed, the so far observed y is used
        if y is None and self.get_config()["remember_data"]:
            y = self._y

        # we want residuals, so fh must be the index of y
        # if data frame: take directly from y
        # to avoid issues with _set_fh, we convert to relative if self.fh is
        if isinstance(y, (pd.DataFrame, pd.Series)):
            fh = ForecastingHorizon(y.index, is_relative=False, freq=self._cutoff)
            if self._fh is not None and self.fh.is_relative:
                fh = fh.to_relative(self._cutoff)
            fh = self._check_fh(fh)
        # if np.ndarray, rows are not indexed
        # so will be interpreted as range(len), or existing fh if it is stored
        elif isinstance(y, np.ndarray):
            if self._fh is None:
                fh = range(y.shape[0])
            else:
                fh = self.fh
        else:
            raise TypeError("y must be a supported Series mtype")

        y_pred = self.predict(fh=fh, X=X)

        if type(y_pred) is not type(y):
            y = convert_to(y, self._y_metadata["mtype"])

        y_res = y - y_pred

        # write fh back to self that was given before calling predict_residuals to
        # avoid side-effects
        self._fh = fh_orig

        return y_res

def runtime_checkable(cls):
        if not issubclass(cls, typing.Generic) or not getattr(cls, '_is_protocol', False):
            raise TypeError(f'@runtime_checkable can be only applied to protocol classes,'
                            f' got {cls!r}')
        cls._is_runtime_protocol = True

        # typing.Protocol classes on <=3.11 break if we execute this block,
        # because typing.Protocol classes on <=3.11 don't have a
        # `__protocol_attrs__` attribute, and this block relies on the
        # `__protocol_attrs__` attribute. Meanwhile, typing.Protocol classes on 3.12.2+
        # break if we *don't* execute this block, because *they* assume that all
        # protocol classes have a `__non_callable_proto_members__` attribute
        # (which this block sets)
        if isinstance(cls, _ProtocolMeta) or sys.version_info >= (3, 12, 2):
            # PEP 544 prohibits using issubclass()
            # with protocols that have non-method members.
            # See gh-113320 for why we compute this attribute here,
            # rather than in `_ProtocolMeta.__init__`
            cls.__non_callable_proto_members__ = set()
            for attr in cls.__protocol_attrs__:
                try:
                    is_callable = callable(getattr(cls, attr, None))
                except Exception as e:
                    raise TypeError(
                        f"Failed to determine whether protocol member {attr!r} "
                        "is a method member"
                    ) from e
                else:
                    if not is_callable:
                        cls.__non_callable_proto_members__.add(attr)

        return cls

def squeeze_features(protein):
    if len(protein['aatype'].shape) == 2:
        protein['aatype'] = torch.argmax(protein['aatype'], dim=-1)
    if 'resolution' in protein and len(protein['resolution'].shape) == 1:
        # use tensor for resolution
        protein['resolution'] = protein['resolution'][0]
    for k in [
            'domain_name',
            'msa',
            'num_alignments',
            'seq_length',
            'sequence',
            'superfamily',
            'deletion_matrix',
            'between_segment_residues',
            'residue_index',
            'template_all_atom_mask',
    ]:
        if k in protein and len(protein[k].shape):
            final_dim = protein[k].shape[-1]
            if isinstance(final_dim, int) and final_dim == 1:
                if torch.is_tensor(protein[k]):
                    protein[k] = torch.squeeze(protein[k], dim=-1)
                else:
                    protein[k] = np.squeeze(protein[k], axis=-1)

    for k in ['seq_length', 'num_alignments']:
        if k in protein and len(protein[k].shape):
            protein[k] = protein[k][0]

    return protein

def transform_data(self, func, idx=None, tmin_idx=None, tmax_idx=None):
        if idx is None:
            # use all time courses by default
            idx = slice(None, None)

        if self._kernel is None and self._sens_data is None:
            if self._kernel_removed:
                warn(
                    "Performance can be improved by not accessing the data "
                    "attribute before calling this method."
                )

            # transform source space data directly
            data_t = func(self.data[idx, ..., tmin_idx:tmax_idx])

            if isinstance(data_t, tuple):
                # use only first return value
                data_t = data_t[0]
        else:
            # apply transform in sensor space
            sens_data_t = func(self._sens_data[:, tmin_idx:tmax_idx])

            if isinstance(sens_data_t, tuple):
                # use only first return value
                sens_data_t = sens_data_t[0]

            # apply inverse
            data_shape = sens_data_t.shape
            if len(data_shape) > 2:
                # flatten the last dimensions
                sens_data_t = sens_data_t.reshape(
                    data_shape[0], np.prod(data_shape[1:])
                )

            data_t = np.dot(self._kernel[idx, :], sens_data_t)

            # restore original shape if necessary
            if len(data_shape) > 2:
                data_t = data_t.reshape(data_t.shape[0], *data_shape[1:])

        return data_t

def findsource(obj):
    import linecache  # pylint: disable=import-outside-toplevel

    if not inspect.isclass(obj):
        return _findsource(obj)

    file = inspect.getsourcefile(obj)
    if file:
        linecache.checkcache(file)
    else:
        file = inspect.getfile(obj)
        if not (file.startswith("<") and file.endswith(">")):
            raise OSError("source code not available")

    module = inspect.getmodule(obj, file)
    if module:
        lines = linecache.getlines(file, module.__dict__)
    else:
        lines = linecache.getlines(file)
    if not lines:
        raise OSError("could not get source code")
    qual_names = obj.__qualname__.replace(".<locals>", "<locals>").split(".")
    in_comment = 0
    scope_stack = []
    indent_info = {}
    for i, line in enumerate(lines):
        n_comment = line.count('"""')
        if n_comment:
            # update multi-line comments status
            in_comment = in_comment ^ (n_comment & 1)
            continue
        if in_comment:
            # skip lines within multi-line comments
            continue
        indent = len(line) - len(line.lstrip())
        tokens = line.split()
        if len(tokens) > 1:
            name = None
            if tokens[0] == "def":
                name = tokens[1].split(":")[0].split("(")[0] + "<locals>"
            elif tokens[0] == "class":
                name = tokens[1].split(":")[0].split("(")[0]
            # pop scope if we are less indented
            while scope_stack and indent_info[scope_stack[-1]] >= indent:
                scope_stack.pop()
            if name:
                scope_stack.append(name)
                indent_info[name] = indent
                if scope_stack == qual_names:
                    return lines, i

    raise OSError("could not find class definition")

def on_fit_epoch_end(self, vals, epoch, best_fitness, fi):
        x = dict(zip(self.keys, vals))
        if self.csv:
            file = self.save_dir / "results.csv"
            n = len(x) + 1  # number of cols
            s = "" if file.exists() else (("%20s," * n % tuple(["epoch", *self.keys])).rstrip(",") + "\n")  # add header
            with open(file, "a") as f:
                f.write(s + ("%20.5g," * n % tuple([epoch, *vals])).rstrip(",") + "\n")
        if self.ndjson_console or self.ndjson_file:
            json_data = json.dumps(dict(epoch=epoch, **x), default=_json_default)
        if self.ndjson_console:
            print(json_data)
        if self.ndjson_file:
            file = self.save_dir / "results.ndjson"
            with open(file, "a") as f:
                print(json_data, file=f)

        if self.tb:
            for k, v in x.items():
                self.tb.add_scalar(k, v, epoch)
        elif self.clearml:  # log to ClearML if TensorBoard not used
            self.clearml.log_scalars(x, epoch)

        if self.wandb:
            if best_fitness == fi:
                best_results = [epoch, *vals[3:7]]
                for i, name in enumerate(self.best_keys):
                    self.wandb.wandb_run.summary[name] = best_results[i]  # log best results in the summary
            self.wandb.log(x)
            self.wandb.end_epoch()

        if self.clearml:
            self.clearml.current_epoch_logged_images = set()  # reset epoch image limit
            self.clearml.current_epoch += 1

        if self.comet_logger:
            self.comet_logger.on_fit_epoch_end(x, epoch=epoch)

def is_qwc(pauli_vec_1, pauli_vec_2):
    if isinstance(pauli_vec_1, (list, tuple)):
        pauli_vec_1 = np.asarray(pauli_vec_1)
    if isinstance(pauli_vec_2, (list, tuple)):
        pauli_vec_2 = np.asarray(pauli_vec_2)

    if len(pauli_vec_1) != len(pauli_vec_2):
        raise ValueError(
            f"Vectors a and b must be the same dimension, instead got "
            f"shapes {np.shape(pauli_vec_1)} and {np.shape(pauli_vec_2)}."
        )

    if len(pauli_vec_1) % 2 != 0:
        raise ValueError(
            f"Symplectic vector-space must have even dimension, instead got vectors of shape {np.shape(pauli_vec_1)}."
        )

    if not (
        np.array_equal(pauli_vec_1, pauli_vec_1.astype(bool))
        and np.array_equal(pauli_vec_2, pauli_vec_2.astype(bool))
    ):
        raise ValueError(
            f"Vectors a and b must have strictly binary components, instead got {pauli_vec_1} and {pauli_vec_2}"
        )

    n_qubits = int(len(pauli_vec_1) / 2)

    for i in range(n_qubits):
        first_vec_ith_qubit_paulix = pauli_vec_1[i]
        first_vec_ith_qubit_pauliz = pauli_vec_1[n_qubits + i]
        second_vec_ith_qubit_paulix = pauli_vec_2[i]
        second_vec_ith_qubit_pauliz = pauli_vec_2[n_qubits + i]

        first_vec_qubit_i_is_identity = (
            first_vec_ith_qubit_paulix == first_vec_ith_qubit_pauliz == 0
        )
        second_vec_qubit_i_is_identity = (
            second_vec_ith_qubit_paulix == second_vec_ith_qubit_pauliz == 0
        )
        both_vecs_qubit_i_have_same_x = first_vec_ith_qubit_paulix == second_vec_ith_qubit_paulix
        both_vecs_qubit_i_have_same_z = first_vec_ith_qubit_pauliz == second_vec_ith_qubit_pauliz

        if not (
            ((first_vec_qubit_i_is_identity) or (second_vec_qubit_i_is_identity))
            or ((both_vecs_qubit_i_have_same_x) and (both_vecs_qubit_i_have_same_z))
        ):
            return False

    return True

def fetch(
        self, symbol: str, name: str, end_index: Optional[int] = None
    ) -> pd.DataFrame:
        model_sym = ModelSymbol(name, symbol)
        if model_sym in self._sym_inputs:
            df = self._sym_inputs[model_sym]
            return df if end_index is None else df.loc[: end_index - 1]
        input_ = {}
        for col in self._scope.all_data_cols:
            data = self._col_scope.fetch(symbol, col)
            if data is not None:
                input_[col] = data
        if not self._scope.has_model_source(name):
            raise ValueError(f"Model {name!r} not found.")
        for ind_name in self._scope.get_indicator_names(name):
            input_[ind_name] = self._ind_scope.fetch(symbol, ind_name)
        df = pd.DataFrame.from_dict(input_)
        if model_sym not in self._models:
            raise ValueError(f"Model {name!r} not found for {symbol}.")
        trained_model = self._models[model_sym]
        if trained_model.input_cols is not None:
            for input_col in trained_model.input_cols:
                if input_col not in df.columns:
                    raise ValueError(
                        f"Missing column {input_col!r} for input data to "
                        f"model {model_sym.model_name!r}."
                    )
            df = df[list(trained_model.input_cols)]
        model_source = self._scope.get_model_source(name)
        if not trained_model.input_cols or model_source._input_data_fn:
            df = model_source.prepare_input_data(df)
        self._sym_inputs[model_sym] = df
        return df if end_index is None else df.loc[: end_index - 1]

def check_sub_agent_status_tool(
    agent: Any, agent_name: str, **kwargs
) -> str:
    registry = _find_registry(agent)
    matches = _resolve_sub_agents_by_name(agent, agent_name)
    if not matches:
        return (
            f"Error: No sub-agents found with name '{agent_name}'. "
            "Use create_sub_agent first."
        )

    # Collect tasks whose agent matches any of the resolved sub-agent objects
    sub_agent_objects = {
        data["agent"] for _, data in matches if "agent" in data
    }
    tasks_by_agent = {}
    for task_id, st in registry.tasks.items():
        task_agent = getattr(st, "agent", None)
        if (
            task_agent in sub_agent_objects
            or getattr(task_agent, "agent_name", None) == agent_name
        ):
            tasks_by_agent.setdefault(task_agent, []).append(
                (task_id, st)
            )

    if not tasks_by_agent:
        return f"No async tasks found in registry for sub-agent '{agent_name}'."

    lines: List[str] = [
        f"Async status for sub-agent '{agent_name}':",
    ]

    for task_agent, task_entries in tasks_by_agent.items():
        display_name = getattr(
            task_agent, "agent_name", repr(task_agent)
        )
        lines.append(f"\nSub-agent: {display_name}")
        for task_id, st in task_entries:
            duration = (
                st.completed_at - st.created_at
                if st.completed_at is not None
                else None
            )
            duration_str = (
                f"{duration:.2f}s"
                if duration is not None
                else "in-progress"
            )
            lines.append(
                f"- Task ID: {task_id} | "
                f"status={st.status.value} | "
                f"depth={st.depth} | "
                f"retries={st.retries}/{st.max_retries} | "
                f"duration={duration_str}"
            )

    result_msg = "\n".join(lines)
    agent.short_memory.add(
        role="Sub-Agent Execution",
        content=result_msg,
    )
    if getattr(agent, "verbose", False):
        logger.info(result_msg)
    return result_msg

def get_user_organizations(self, force_refresh: bool = False) -> Dict[str, Any]:
        # Check if we have a valid cache
        current_time = time.time()
        cache_age = current_time - self._orgs_cache_time

        if not force_refresh and self._orgs_cache is not None and cache_age < self.CACHE_TTL:
            return self._orgs_cache

        try:
            token = hf_get_token()
            if not token:
                token_path = Path.home() / ".cache" / "huggingface" / "token"
                if token_path.exists():
                    with open(token_path, "r") as f:
                        token = f.read().strip()

            if not token:
                raise PublishingServiceError(
                    "No HuggingFace token found. Please run 'huggingface-cli login'.",
                    status.HTTP_401_UNAUTHORIZED,
                )

            # Get user info from HuggingFace API
            user_info = self.api.whoami(token=token)
            username = user_info.get("name")

            # Get organizations
            organizations: List[str] = []
            orgs_info = user_info.get("orgs", [])
            if orgs_info:
                organizations = [org.get("name") for org in orgs_info if org.get("name")]

            result = {
                "username": username,
                "organizations": organizations,
                "namespaces": [username] + organizations,
            }

            # Update cache
            self._orgs_cache = result
            self._orgs_cache_time = current_time

            return result

        except PublishingServiceError:
            raise
        except Exception as e:
            raise PublishingServiceError(
                f"Failed to get user organizations: {str(e)}",
                status.HTTP_500_INTERNAL_SERVER_ERROR,
            ) from e

def walk(top, topdown=True, onerror=None, followlinks=False, depth=0):
    islink, join, isdir = os.path.islink, os.path.join, os.path.isdir

    try:
        # Should be O(1) since it's probably just reading your filesystem journal
        names = os.listdir(top)
    except OSError as err:
        if onerror is not None:
            onerror(err)
        return

    dirs, nondirs = [], []

    # O(n) where n = number of files in the directory
    for name in names:
        if isdir(join(top, name)):
            dirs.append(name)
        else:
            nondirs.append(name)

    if topdown:
        yield depth, top, dirs, nondirs

    # Again O(n), where n = number of directories in the directory
    for name in dirs:
        new_path = join(top, name)
        if followlinks or not islink(new_path):

            # Generator so besides the recursive `walk()` call, no additional cost here.
            for x in walk(new_path, topdown, onerror, followlinks, depth + 1):
                yield x
    if not topdown:
        yield depth, top, dirs, nondirs

def replace_node(self, old: "Model", new: "Model") -> bool:
        seen = False

        # We need to replace nodes in topological order of the transposed graph
        # to ensure that a node's dependencies are processed before the node.
        # This is equivalent to a post-order traversal of the original graph.
        for node in list(self.walk(order="dfs_post")):
            if node is old:
                seen = True
            else:
                node._layers = [
                    new if layer is old else layer for layer in node._layers
                ]
                for name in node.ref_names:
                    if node.get_ref(name) is old:
                        node.set_ref(name, new)

        return seen

def get_image_size(
        self,
        image: "torch.Tensor",
        limit_side_len: int,
        limit_type: str,
        max_side_limit: int,
    ):
        _, height, width = image.shape
        height, width = int(height), int(width)

        if limit_type == "max":
            if max(height, width) > limit_side_len:
                ratio = float(limit_side_len) / max(height, width)
            else:
                ratio = 1.0
        elif limit_type == "min":
            if min(height, width) < limit_side_len:
                ratio = float(limit_side_len) / min(height, width)
            else:
                ratio = 1.0
        elif limit_type == "resize_long":
            ratio = float(limit_side_len) / max(height, width)
        else:
            raise ValueError(f"PPOCRV5ServerDetImageProcessor does not support limit type: {limit_type}")

        resize_height = int(height * ratio)
        resize_width = int(width * ratio)

        if max_side_limit is not None and max(resize_height, resize_width) > max_side_limit:
            ratio = float(max_side_limit) / max(resize_height, resize_width)
            resize_height = int(resize_height * ratio)
            resize_width = int(resize_width * ratio)

        resize_height = max(int(round(resize_height / 32) * 32), 32)
        resize_width = max(int(round(resize_width / 32) * 32), 32)

        return SizeDict(height=resize_height, width=resize_width), torch.tensor(
            [height, width], dtype=torch.float32, device=image.device
        )

async def run_command(
        self,
        command: str,
        success_message: Optional[str] = None,
        failure_message: Optional[str] = None,
        ignore_if_exists: bool = False,
        return_json: bool = False,
    ) -> str | dict[str, Any] | None:
        try:
            result = await run_process(shlex.split(command), check=False)
            output = result.stdout.decode("utf-8").strip()

            if result.returncode != 0:
                error_message = result.stderr.decode("utf-8")
                if ignore_if_exists and "already exists" in error_message:
                    if success_message:
                        self._console.print(
                            f"{success_message} (already exists)", style="yellow"
                        )
                    return ("exists", None)
                else:
                    if failure_message:
                        self._console.print(
                            f"{failure_message}: {result.stderr.decode('utf-8')}",
                            style="red",
                        )
                    raise subprocess.CalledProcessError(
                        result.returncode,
                        command,
                        output=result.stdout,
                        stderr=result.stderr,
                    )
            if success_message:
                self._console.print(success_message, style="green")

            if return_json:
                try:
                    return json.loads(output)
                except json.JSONDecodeError as e:
                    self._console.print(f"Failed to decode JSON: {e}", style="red")
                    raise e

            return output

        except subprocess.CalledProcessError as e:
            self._console.print(f"Command execution failed: {e}", style="red")
            return

def masks2segments(masks, strategy="largest"):
    segments = []
    for x in masks.int().cpu().numpy().astype("uint8"):
        c = cv2.findContours(x, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)[0]
        if c:
            if strategy == "concat":  # concatenate all segments
                c = np.concatenate([x.reshape(-1, 2) for x in c])
            elif strategy == "largest":  # select largest segment
                c = np.array(c[np.array([len(x) for x in c]).argmax()]).reshape(-1, 2)
        else:
            c = np.zeros((0, 2))  # no segments found
        segments.append(c.astype("float32"))
    return segments

def collect_sequence_info(self, sequence_types: Tuple[str, ...]) -> Dict[str, Dict[str, list]]:
        sequence_traces = {}
        if isinstance(sequence_types, str):
            sequence_types = (sequence_types,)
        for seq_type in sequence_types:
            seq_cls = Sequence.registry.get(seq_type, None)
            if seq_cls is None:
                raise ValueError(f"'{seq_type}' is not a valid Sequence")
            assert issubclass(seq_cls, Sequence)
            dtypes = seq_cls.allowed_dtypes()
            dtype_traces = set()
            for dtype in dtypes:
                try:
                    dtype_trace_tree = self.meta_tree.collect(('traces_types', dtype))
                    for ctx_id, seqs in dtype_trace_tree.items():
                        for seq_name in seqs.keys():
                            dtype_traces.add((ctx_id, seq_name))
                except KeyError:
                    pass
            if 'float' in dtypes:  # old sequences without dtype set are considered float sequences
                try:
                    dtype_trace_tree = self.meta_tree.collect('traces')
                    for ctx_id, seqs in dtype_trace_tree.items():
                        for seq_name in seqs.keys():
                            dtype_traces.add((ctx_id, seq_name))
                except KeyError:
                    pass
            traces_info = defaultdict(list)
            for ctx_id, seq_name in dtype_traces:
                traces_info[seq_name].append(self.meta_tree['contexts', ctx_id])
            sequence_traces[seq_type] = traces_info
        return sequence_traces

def clean_attributes(obj, include_props: bool = False) -> Dict[str, Any]:
    keys = dir(obj)

    ret = {}

    for k in keys:
        if k.startswith("__"):
            # These are typically very internal components not meant to be
            # exposed beyond immediate definitions. Ignoring these.
            continue

        if include_props and k.startswith("_") and k[1:] in keys:
            # Objects often have properties named `name` with their values
            # coming from `_name`. This check lets avoid including both the
            # property and the value.
            continue

        try:
            v = safe_getattr(obj, k, get_prop=include_props)

            if isinstance(v, python_utils.OpaqueWrapper):
                # Don't expose the contents of opaque wrappers.
                continue

            ret[k] = v

        except Exception as e:
            logger.debug(str(e))
            logger.debug(str(e.__traceback__))

    return ret

def scan_history(
        self,
        keys: list[str] | None = None,
        page_size: int = 1_000,
        min_step: int | None = None,
        max_step: int | None = None,
    ) -> Iterator[dict[str, Any]]:
        if keys is not None and not isinstance(keys, list):
            wandb.termerror("keys must be specified in a list")
            return []
        if keys is not None and len(keys) > 0 and not isinstance(keys[0], str):
            wandb.termerror("keys argument must be a list of strings")
            return []

        last_step = self.lastHistoryStep
        # set defaults for min/max step
        if min_step is None:
            min_step = 0
        if max_step is None:
            max_step = last_step + 1
        # if the max step is past the actual last step, clamp it down
        if max_step > last_step:
            max_step = last_step + 1
        if keys is None:
            return public.HistoryScan(
                run=self,
                client=self.client,
                page_size=page_size,
                min_step=min_step,
                max_step=max_step,
            )
        else:
            return public.SampledHistoryScan(
                run=self,
                client=self.client,
                keys=keys,
                page_size=page_size,
                min_step=min_step,
                max_step=max_step,
            )

def prompt_for_config(context, no_input=False):
    cookiecutter_dict = OrderedDict([])
    env = StrictEnvironment(context=context)

    # First pass: Handle simple and raw variables, plus choices.
    # These must be done first because the dictionaries keys and
    # values might refer to them.
    for key, raw in context["cookiecutter"].items():
        if key.startswith("_"):
            cookiecutter_dict[key] = raw
            continue

        try:
            if isinstance(raw, list):
                if isinstance(raw[0], dict):
                    val = _prompt_choice_and_subitems(
                        cookiecutter_dict, env, key, raw, no_input
                    )
                    cookiecutter_dict[key] = val
                else:
                    # We are dealing with a choice variable
                    val = prompt_choice_for_config(
                        cookiecutter_dict, env, key, raw, no_input
                    )
                    cookiecutter_dict[key] = val
            elif not isinstance(raw, dict):
                # We are dealing with a regular variable
                val = render_variable(env, raw, cookiecutter_dict)

                if not no_input:
                    val = read_user_variable(key, val)

                cookiecutter_dict[key] = val
        except UndefinedError as err:
            msg = "Unable to render variable '{}'".format(key)
            raise UndefinedVariableInTemplate(msg, err, context)

    # Second pass; handle the dictionaries.
    for key, raw in context["cookiecutter"].items():
        try:
            if isinstance(raw, dict):
                # We are dealing with a dict variable
                val = render_variable(env, raw, cookiecutter_dict)

                if not no_input:
                    val = read_user_dict(  # noqa: F821 referencable in patched context
                        key, val
                    )

                cookiecutter_dict[key] = val
        except UndefinedError as err:
            msg = "Unable to render variable '{}'".format(key)
            raise UndefinedVariableInTemplate(msg, err, context)

    return cookiecutter_dict

def find_lexer_class_by_name(_alias):
    if not _alias:
        raise ClassNotFound('no lexer for alias %r found' % _alias)
    # lookup builtin lexers
    for module_name, name, aliases, _, _ in itervalues(LEXERS):
        if _alias.lower() in aliases:
            if name not in _lexer_cache:
                _load_lexers(module_name)
            return _lexer_cache[name]
    # continue with lexers from setuptools entrypoints
    for cls in find_plugin_lexers():
        if _alias.lower() in cls.aliases:
            return cls
    raise ClassNotFound('no lexer for alias %r found' % _alias)

def construct_execution_config(
    qnode: QNode, resolve: bool | None = True
) -> Callable[P, ExecutionConfig]:

    @functools.wraps(qnode)
    def wrapper(*args, **kwargs) -> ExecutionConfig:
        mcm_config = qml.devices.MCMConfig(
            postselect_mode=qnode.execute_kwargs["postselect_mode"],
            mcm_method=qnode.execute_kwargs["mcm_method"],
        )

        grad_on_execution = qnode.execute_kwargs["grad_on_execution"]
        if qnode.interface in {Interface.JAX.value, Interface.JAX_JIT.value}:
            grad_on_execution = False
        elif grad_on_execution == "best":
            grad_on_execution = None

        config = qml.devices.ExecutionConfig(
            interface=qnode.interface,
            gradient_method=qnode.diff_method,
            grad_on_execution=grad_on_execution,
            use_device_jacobian_product=qnode.execute_kwargs["device_vjp"],
            derivative_order=qnode.execute_kwargs["max_diff"],
            gradient_keyword_arguments=qnode.gradient_kwargs,
            mcm_config=mcm_config,
        )
        if resolve:
            if type(qnode).__name__ == "TorchLayer":
                # avoid triggering import of torch if its not needed.
                x = args[0]
                kwargs = {
                    **{arg: weight.to(x) for arg, weight in qnode.qnode_weights.items()},
                }
            shots = qnode._get_shots(kwargs)  # pylint: disable=protected-access
            tape = qml.tape.make_qscript(qnode.func, shots=shots)(*args, **kwargs)
            batch, _ = qnode.compile_pipeline((tape,))
            config = _resolve_execution_config(config, qnode.device, batch)

        return config

    return wrapper

def try_obtain_root_certificates(
    args: argparse.Namespace,
    grpc_server_address: str,
) -> bytes | str | None:
    root_cert_path: str | None = args.root_certificates
    if args.insecure:
        if root_cert_path is not None:
            sys.exit(
                "Conflicting options: The '--insecure' flag disables HTTPS, "
                "but '--root-certificates' was also specified. Please remove "
                "the '--root-certificates' option when running in insecure mode, "
                "or omit '--insecure' to use HTTPS."
            )
        log(
            WARN,
            "Option `--insecure` was set. Starting insecure HTTP channel to %s.",
            grpc_server_address,
        )
        root_certificates = None
    else:
        # Load the certificates if provided, or load the system certificates
        if root_cert_path is None:
            log(INFO, "Using system certificates for TLS connection")
            root_certificates = None
        elif not isfile(root_cert_path):
            log(ERROR, "Path argument `--root-certificates` does not point to a file.")
            sys.exit(1)
        else:
            root_certificates = Path(root_cert_path).expanduser().read_bytes()
        log(
            DEBUG,
            "Starting secure HTTPS channel to %s "
            "with the following certificates: %s.",
            grpc_server_address,
            root_cert_path,
        )
    if args.transport == TRANSPORT_TYPE_REST:
        return root_cert_path
    return root_certificates

def trace_node_users_to_constrain_repset(  # noqa: C901
        self,
        origin_node: torch.fx.Node,
        repset: utils.TensorRepSet,
        search_depth: list[int] | None = None,
    ) -> utils.TensorRepSet:
        # Optionally limit the total number of nodes explored to improve export
        # time. search_depth is a mutable list so that all branches of a fan-out
        # share a single counter, preventing exponential blowup.
        if self.max_trace_search_depth is not None:
            if search_depth is None:
                search_depth = [self.max_trace_search_depth]
            search_depth[0] -= 1
            if search_depth[0] <= 0:
                return repset

        users_to_trace = origin_node.users

        sync_outs_repr = True
        if self.is_valid_op_node(origin_node):
            sync_outs_repr = self.get_node_cached_repsets(origin_node).sync_outs_repr

        if utils.num_tensors_in_node(origin_node) > 1 and not sync_outs_repr:
            users_to_trace = []
            for usage_node in origin_node.users:
                if usage_node.target == operator.getitem and usage_node.args[1] == 1:
                    users_to_trace.append(usage_node)

        for usage_node in users_to_trace:
            arg_i_in_user = None
            for i in range(len(usage_node.args)):
                if origin_node == usage_node.args[i]:
                    arg_i_in_user = i
                    break

            if arg_i_in_user is not None:
                repset = self.constrain_repset_with_user(
                    usage_node, arg_i_in_user, repset, search_depth
                )

            if repset.is_constrained():
                return repset

        return repset

def get_model_pred_proba_dict(
        self,
        X: pd.DataFrame,
        models: list[str],
        model_pred_proba_dict: dict | None = None,
        model_pred_time_dict: dict | None = None,
        record_pred_time: bool = False,
        use_val_cache: bool = False,
    ):
        if model_pred_proba_dict is None:
            model_pred_proba_dict = {}
        if model_pred_time_dict is None:
            model_pred_time_dict = {}

        if use_val_cache:
            _, model_pred_proba_dict = self._update_pred_proba_dict_with_val_cache(
                model_set=set(models), model_pred_proba_dict=model_pred_proba_dict
            )
        if not model_pred_proba_dict:
            model_pred_order = self._construct_model_pred_order(models)
        else:
            model_pred_order = self._construct_model_pred_order_with_pred_dict(
                models, models_to_ignore=list(model_pred_proba_dict.keys())
            )
        if use_val_cache:
            model_set, model_pred_proba_dict = self._update_pred_proba_dict_with_val_cache(
                model_set=set(model_pred_order), model_pred_proba_dict=model_pred_proba_dict
            )
            model_pred_order = [model for model in model_pred_order if model in model_set]

        # Compute model predictions in topological order
        for model_name in model_pred_order:
            if record_pred_time:
                time_start = time.time()

            model = self.load_model(model_name=model_name)
            if isinstance(model, StackerEnsembleModel):
                preprocess_kwargs = dict(infer=False, model_pred_proba_dict=model_pred_proba_dict)
                model_pred_proba_dict[model_name] = model.predict_proba(X, **preprocess_kwargs)
            else:
                model_pred_proba_dict[model_name] = model.predict_proba(X)

            if record_pred_time:
                time_end = time.time()
                model_pred_time_dict[model_name] = time_end - time_start

        if record_pred_time:
            return model_pred_proba_dict, model_pred_time_dict
        else:
            return model_pred_proba_dict

def explode_key_values(
    primary_key: str,
    mapping: Dict[str, List[Dict[Literal["key", "values"], Any]]],
    process_key: Callable[[str, str], str] = lambda _, s: s,
) -> List[Dict[str, Any]]:
    all_combinations = {
        primary: (
            itertools.product(
                *[
                    [(option["key"], value) for value in option["values"]]
                    for option in choices
                ]
            )
            if choices
            else []
        )
        for primary, choices in mapping.items()
    }

    # Generate configs
    configs = []
    for primary, combinations in all_combinations.items():
        if not combinations:
            configs.append({primary_key: primary})
        for item in combinations:
            primary_config = {primary_key: primary}
            for key, value in item:
                if isinstance(key, (list, tuple)):
                    primary_config.update(
                        {
                            process_key(primary, k): v
                            for k, v in zip(key, value)
                        }
                    )
                else:
                    primary_config[process_key(primary, key)] = value
            configs.append(primary_config)

    # Explode repetitions
    result = []
    for config in configs:
        if "__repeat__" in config:
            for _ in range(config["__repeat__"]):
                result.append(
                    {k: v for k, v in config.items() if k != "__repeat__"}
                )
        else:
            result.append(config)

    return result

def download(self, url: str, show_status=True):
        import requests

        # Create the data directory if it does not already exist
        if not os.path.exists(self.data_directory):
            os.makedirs(self.data_directory)

        file_name = url.split('/')[-1]
        file_path = os.path.join(self.data_directory, file_name)

        # Do not download the data if it already exists
        if self.is_downloaded(file_path):
            return file_path

        with open(file_path, 'wb') as open_file:
            if show_status:
                print('Downloading %s' % url)
            response = requests.get(url, stream=True)
            total_length = response.headers.get('content-length')

            if total_length is None:
                # No content length header
                open_file.write(response.content)
            else:
                for data in tqdm(
                    response.iter_content(chunk_size=4096),
                    desc='Downloading',
                    disable=not show_status
                ):
                    open_file.write(data)

        if show_status:
            print('Download location: %s' % file_path)
        return file_path

def get_mutable_buffer_names(self) -> List[str]:
        assert self._mlx_graph is not None, "Must call build() first"

        names = []
        for name, slot in self.slot_manager.name_to_slot.items():
            if isinstance(slot, tuple):
                continue
            if slot.id_space != IdSpace.MutableBuffer:
                continue
            if slot in self._slot_to_final_tid:
                names.append((name, self._slot_to_final_tid[slot]))

        # Sort by Tid and return just the names
        names.sort(key=lambda x: x[1])
        return [n for n, _ in names]

def encode_number(self, n, state):
        if isinstance(n, complex):
            if n.imag:
                raise JSONEncodeError(
                    "Can not encode a complex number that has a non-zero imaginary part",
                    n,
                )
            n = n.real

        if isinstance(n, json_int):
            state.append(n.json_format())
            return

        if isinstance(n, int):
            state.append(str(n))
            return

        if decimal and isinstance(n, decimal.Decimal):
            if n.is_nan():  # Could be 'NaN' or 'sNaN'
                state.append("NaN")
            elif n.is_infinite():
                if n.is_signed():
                    state.append("-Infinity")
                else:
                    state.append("Infinity")
            else:
                s = str(n).lower()
                if "e" not in s and "." not in s:
                    s = s + ".0"
                state.append(s)
            return

        global nan, inf, neginf  # noqa
        if n is nan:
            state.append("NaN")
        elif n is inf:
            state.append("Infinity")
        elif n is neginf:
            state.append("-Infinity")
        elif isinstance(n, float):
            # Check for non-numbers.
            # In python nan == inf == -inf, so must use repr() to distinguish
            reprn = repr(n).lower()
            if ("inf" in reprn and "-" in reprn) or n == neginf:
                state.append("-Infinity")
            elif "inf" in reprn or n is inf:
                state.append("Infinity")
            elif "nan" in reprn or n is nan:
                state.append("NaN")
            else:
                # A normal float.
                state.append(repr(n))
        else:
            raise TypeError(
                "encode_number expected an integral, float, or decimal number type",
                type(n),
            )

def replace_with_quanto_layers(
    model,
    quantization_config=None,
    modules_to_not_convert: list[str] | None = None,
):
    from optimum.quanto import QLayerNorm, QLinear, qfloat8, qint2, qint4, qint8

    w_mapping = {"float8": qfloat8, "int8": qint8, "int4": qint4, "int2": qint2}
    a_mapping = {None: None, "float8": qfloat8, "int8": qint8}

    has_been_replaced = False
    for module_name, module in model.named_modules():
        if not should_convert_module(module_name, modules_to_not_convert):
            continue
        with torch.device("meta"):
            new_module = None
            if isinstance(module, nn.Linear):
                new_module = QLinear(
                    in_features=module.in_features,
                    out_features=module.out_features,
                    bias=module.bias is not None,
                    dtype=module.weight.dtype,
                    weights=w_mapping[quantization_config.weights],
                    activations=a_mapping[quantization_config.activations],
                )
            elif isinstance(module, torch.nn.LayerNorm) and quantization_config.activations is not None:
                new_module = QLayerNorm(
                    module.normalized_shape,
                    module.eps,
                    module.elementwise_affine,
                    module.bias is not None,
                    activations=a_mapping[quantization_config.activations],
                )
            if new_module is not None:
                has_been_replaced = True
                model.set_submodule(module_name, new_module)

    if not has_been_replaced:
        logger.warning(
            "You are loading your model using quanto but no linear modules were found in your model."
            " Please double check your model architecture, or submit an issue on github if you think this is"
            " a bug."
        )

    return model

def resample(self, n=MINORITY):
        # Based on:
        # Liu, Ghosh & Martin (2007). Generative oversampling for mining imbalanced datasets.
        # http://wwwmath.uni-muenster.de/u/lammers/EDU/ws07/Softcomputing/Literatur/4-DMI5467.pdf
        #
        # p1: {class: count}
        # p2: {class: max(len(vector))}
        # p3: {class: {feature: [weights]}}
        p1 = defaultdict(int)
        p2 = defaultdict(int)
        p3 = defaultdict(lambda: defaultdict(list))
        for d in self.documents:
            p1[d.type] += 1
        for d in self.documents:
            p2[d.type] = max(p2[d.type], len(d.terms))
        for d in self.documents:
            for f, w in d.terms.items():
                p3[d.type][f].append(w)
        # List features with weight 0.0.
        for t in p3:
            for f in p3[t]:
                p3[t][f].extend([0] * (p1[t] - len(p3[t][f])))
        if n == MINORITY:
            n = min(p1.values() or [0])
        if n == MAJORITY:
            n = max(p1.values() or [0])
        a = []
        x = defaultdict(int)
        # 1) Undersampling.
        for d in self.documents:
            if x[d.type] < n:
                x[d.type] += 1
                a.append(d)
        # 2) Oversampling.
        # Generate new documents in minority classes,
        # taking into account the number of features
        # and feature weights in existing documents.
        for t, i in p1.items():
            for j in range(i, n):
                v = {}
                for f in shuffled(p3[t].keys()[:p2[t]]):
                    w = choice(p3[t][f])
                    w = w if v else p3[t][f][0]
                    if w:
                        v[f] = w
                a.append(Document(v))
        self.clear()
        self.extend(a)
        return self

def extract_rels(subjclass, objclass, doc, corpus="ace", pattern=None, window=10):
    if subjclass and subjclass not in NE_CLASSES[corpus]:
        if _expand(subjclass) in NE_CLASSES[corpus]:
            subjclass = _expand(subjclass)
        else:
            raise ValueError(
                "your value for the subject type has not been recognized: %s"
                % subjclass
            )
    if objclass and objclass not in NE_CLASSES[corpus]:
        if _expand(objclass) in NE_CLASSES[corpus]:
            objclass = _expand(objclass)
        else:
            raise ValueError(
                "your value for the object type has not been recognized: %s" % objclass
            )

    if corpus == "ace" or corpus == "conll2002":
        pairs = tree2semi_rel(doc)
    elif corpus == "ieer":
        pairs = tree2semi_rel(doc.text) + tree2semi_rel(doc.headline)
    else:
        raise ValueError("corpus type not recognized")

    reldicts = semi_rel2reldict(pairs)

    relfilter = lambda x: (
        x["subjclass"] == subjclass
        and len(x["filler"].split()) <= window
        and pattern.match(x["filler"])
        and x["objclass"] == objclass
    )

    return list(filter(relfilter, reldicts))

def get_window_extent(self, renderer=None):
        # make sure the location is updated so that transforms etc are correct:
        self._adjust_location()
        bb = super().get_window_extent(renderer=renderer)
        if self.axis is None or not self.axis.get_visible():
            return bb
        bboxes = [bb]
        drawn_ticks = self.axis._update_ticks()

        major_tick = next(iter({*drawn_ticks} & {*self.axis.majorTicks}), None)
        minor_tick = next(iter({*drawn_ticks} & {*self.axis.minorTicks}), None)
        for tick in [major_tick, minor_tick]:
            if tick is None:
                continue
            bb0 = bb.frozen()
            tickl = tick._size
            tickdir = tick._tickdir
            if tickdir == 'out':
                padout = 1
                padin = 0
            elif tickdir == 'in':
                padout = 0
                padin = 1
            else:
                padout = 0.5
                padin = 0.5
            dpi = self.get_figure(root=True).dpi
            padout = padout * tickl / 72 * dpi
            padin = padin * tickl / 72 * dpi

            if tick.tick1line.get_visible():
                if self.spine_type == 'left':
                    bb0.x0 = bb0.x0 - padout
                    bb0.x1 = bb0.x1 + padin
                elif self.spine_type == 'bottom':
                    bb0.y0 = bb0.y0 - padout
                    bb0.y1 = bb0.y1 + padin

            if tick.tick2line.get_visible():
                if self.spine_type == 'right':
                    bb0.x1 = bb0.x1 + padout
                    bb0.x0 = bb0.x0 - padin
                elif self.spine_type == 'top':
                    bb0.y1 = bb0.y1 + padout
                    bb0.y0 = bb0.y0 - padout
            bboxes.append(bb0)

        return mtransforms.Bbox.union(bboxes)

def remove_cluster(cluster_name: str, terminate: bool) -> None:
    engine = _db_manager.get_engine()
    cluster_hash = _get_hash_for_existing_cluster(cluster_name)
    usage_intervals = _get_cluster_usage_intervals(cluster_hash)
    provision_log_path = get_cluster_provision_log_path(cluster_name)

    with orm.Session(engine) as session:
        # usage_intervals is not None and not empty
        if usage_intervals:
            assert cluster_hash is not None, cluster_name
            start_time = usage_intervals.pop()[0]
            end_time = int(time.time())
            usage_intervals.append((start_time, end_time))
            _set_cluster_usage_intervals(cluster_hash, usage_intervals)

        if provision_log_path:
            assert cluster_hash is not None, cluster_name
            session.query(cluster_history_table).filter_by(
                cluster_hash=cluster_hash
            ).filter(
                cluster_history_table.c.provision_log_path.is_(None)
            ).update({
                cluster_history_table.c.provision_log_path: provision_log_path
            })

        if terminate:
            session.query(cluster_table).filter_by(name=cluster_name).delete()
        else:
            handle = get_handle_from_cluster_name(cluster_name)
            if handle is None:
                return
            # Must invalidate IP list to avoid directly trying to ssh into a
            # stopped VM, which leads to timeout.
            if hasattr(handle, 'stable_internal_external_ips'):
                handle = typing.cast('backends.CloudVmRayResourceHandle',
                                     handle)
                handle.stable_internal_external_ips = None
            current_time = int(time.time())
            session.query(cluster_table).filter_by(name=cluster_name).update({
                cluster_table.c.handle: pickle.dumps(handle),
                cluster_table.c.status: status_lib.ClusterStatus.STOPPED.value,
                cluster_table.c.status_updated_at: current_time
            })
        session.commit()

def get_symbol(num_classes, num_layers, image_shape, conv_workspace=256, dtype='float32', **kwargs):
    image_shape = [int(l) for l in image_shape.split(',')]
    (nchannel, height, width) = image_shape
    if height <= 28:
        num_stages = 3
        if (num_layers-2) % 9 == 0 and num_layers >= 164:
            per_unit = [(num_layers-2)//9]
            filter_list = [16, 64, 128, 256]
            bottle_neck = True
        elif (num_layers-2) % 6 == 0 and num_layers < 164:
            per_unit = [(num_layers-2)//6]
            filter_list = [16, 16, 32, 64]
            bottle_neck = False
        else:
            raise ValueError("no experiments done on num_layers {}, you can do it yourself".format(num_layers))
        units = per_unit * num_stages
    else:
        if num_layers >= 50:
            filter_list = [64, 256, 512, 1024, 2048]
            bottle_neck = True
        else:
            filter_list = [64, 64, 128, 256, 512]
            bottle_neck = False
        num_stages = 4
        if num_layers == 18:
            units = [2, 2, 2, 2]
        elif num_layers == 34:
            units = [3, 4, 6, 3]
        elif num_layers == 50:
            units = [3, 4, 6, 3]
        elif num_layers == 101:
            units = [3, 4, 23, 3]
        elif num_layers == 152:
            units = [3, 8, 36, 3]
        elif num_layers == 200:
            units = [3, 24, 36, 3]
        elif num_layers == 269:
            units = [3, 30, 48, 8]
        else:
            raise ValueError("no experiments done on num_layers {}, you can do it yourself".format(num_layers))

    return resnet(units       = units,
                  num_stages  = num_stages,
                  filter_list = filter_list,
                  num_classes = num_classes,
                  image_shape = image_shape,
                  bottle_neck = bottle_neck,
                  workspace   = conv_workspace,
                  dtype       = dtype)

