def extract_access_token(self, **kwargs) -> str:
        if "metadata" not in kwargs:
            raise ValueError("Missing keywork argument 'metadata'")
        if not isinstance(kwargs["metadata"], dict):
            raise ValueError(
                f"The keywork argument 'metadata' is not of the expected type {dict.__name__} but {type(kwargs['metadata'])}"
            )

        access_token = None
        metadata = kwargs["metadata"]
        if isinstance(metadata, dict):
            for header in metadata:
                if header.lower() == "authorization":
                    return self._extract_bearer_token(metadata[header])

        if access_token is None:
            raise AuthenticationError("Missing authorization header")

        return access_token

def is_torch_musa_available(check_device=False) -> bool:
    if not is_torch_available() or not _is_package_available("torch_musa")[0]:
        return False

    import torch
    import torch_musa  # noqa: F401

    torch_musa_min_version = "0.33.0"
    accelerate_available, accelerate_version = _is_package_available("accelerate", return_version=True)
    if accelerate_available and version.parse(accelerate_version) < version.parse(torch_musa_min_version):
        return False

    if check_device:
        try:
            # Will raise a RuntimeError if no MUSA is found
            if hasattr(torch, "musa"):
                _ = torch.musa.device_count()
                return torch.musa.is_available()
            return False
        except RuntimeError:
            return False
    return hasattr(torch, "musa") and torch.musa.is_available()

def is_monotonically_increasing(obj):
    index_cols = get_mi_cols(obj)

    # Series with no index columns
    if len(index_cols) == 0:
        return True

    # check for Series scitype
    if len(index_cols) == 1:
        if obj[index_cols[0]].is_sorted():
            return True

    # check for Panel and Hierarchical scitype
    else:
        import polars as pl

        index_df = obj.with_columns(index_cols)
        grouped = index_df.group_by(index_cols[:-1]).agg([pl.col(index_cols[-1])])
        last_index_col = grouped.select([index_cols[-1]])
        for val in last_index_col.iter_rows():
            # iter rows returns a list of tuples
            if not pl.Series(val[0]).is_sorted():
                return False
        return True

    return False

def get_all_artifact_meta(
    study_or_trial: Trial | FrozenTrial | Study, *, storage: BaseStorage | None = None
) -> list[ArtifactMeta]:
    if isinstance(study_or_trial, Trial) and storage is None:
        storage = study_or_trial.storage
    elif isinstance(study_or_trial, Study) and storage is None:
        storage = study_or_trial._storage

    if storage is None:
        raise ValueError("storage is required for FrozenTrial.")

    if isinstance(study_or_trial, (Trial, FrozenTrial)):
        system_attrs = storage.get_trial_system_attrs(study_or_trial._trial_id)
    else:
        system_attrs = storage.get_study_system_attrs(study_or_trial._study_id)

    artifact_meta_list: list[ArtifactMeta] = []
    for attr_key, attr_json_string in system_attrs.items():
        if not attr_key.startswith(ARTIFACTS_ATTR_PREFIX):
            continue

        attr_content = json.loads(attr_json_string)
        artifact_meta = ArtifactMeta(
            artifact_id=attr_content["artifact_id"],
            filename=attr_content["filename"],
            mimetype=attr_content["mimetype"],
            encoding=attr_content["encoding"],
        )
        artifact_meta_list.append(artifact_meta)

    return artifact_meta_list

def preprocess_example_common(example, mode, hparams):
  if "inputs" in example and hparams.max_input_seq_length > 0:
    example["inputs"] = example["inputs"][:hparams.max_input_seq_length]
  if hparams.prepend_mode != "none":
    if mode == tf_estimator.ModeKeys.PREDICT:
      example["partial_targets"] = tf.concat([example["inputs"], [0]], 0)
    else:
      example["targets"] = tf.concat(
          [example["inputs"], [0], example["targets"]], 0)
  if "targets" in example and hparams.max_target_seq_length > 0:
    example["targets"] = example["targets"][:hparams.max_target_seq_length]
  if hparams.split_to_length:
    new_example = {}
    for k, v in six.iteritems(example):
      if k == "targets" or k == "inputs":
        new_example[k] = tf.reshape(v, [-1, hparams.split_to_length, 1, 1])
      else:
        tf.logging.warning("Dropping feature %s" % k)
    return tf.data.Dataset.from_tensor_slices(new_example)
  return example

def blob_name_to_layers(nn_layers):
        output_to_layers = {}
        for layer in nn_layers:
            for input in layer.input:
                if input not in output_to_layers:
                    output_to_layers[input] = [layer]
                else:
                    output_to_layers[input].append(layer)

        input_to_parent_layers = {}
        for layer in nn_layers:
            for output in layer.output:
                if not layer.WhichOneof("layer") == "copy":
                    assert output not in input_to_parent_layers, \
                        "'{}' blob is generated by more than 1 layers".format(output)
                input_to_parent_layers[output] = layer

        return input_to_parent_layers, output_to_layers

def detect_seasonal_period(
    y: np.ndarray, max_period: int = 365
) -> Optional[int]:
    y = np.asarray(y, dtype=float)
    n = len(y)
    if n < 4:
        return None

    max_lag = min(max_period, n // 2)
    if max_lag < 2:
        return None

    # Compute normalised autocorrelation for lags 1..max_lag
    y_centered = y - np.mean(y)
    var = np.dot(y_centered, y_centered)
    if var == 0:
        return None

    acf = np.array(
        [np.dot(y_centered[lag:], y_centered[:-lag]) / var for lag in range(1, max_lag + 1)]
    )

    # Find peaks: acf[i] > acf[i-1] and acf[i] > acf[i+1]
    peak_indices = []
    for i in range(1, len(acf) - 1):
        if acf[i] > acf[i - 1] and acf[i] > acf[i + 1]:
            peak_indices.append(i)

    if not peak_indices:
        return None

    # Pick the first significant peak (> 2/sqrt(n) significance threshold)
    threshold = 2.0 / np.sqrt(n)
    for idx in peak_indices:
        if acf[idx] > threshold:
            return idx + 1  # lag is 1-indexed

    return None

def is_defined_in_class(frames: list[FrameType], obj: Any) -> bool:
    def _is_tvmscript_class_annotator(line: str) -> bool:
        """Checks if the line contains a TVMScript annotator for a class

        These match either `@I.ir_module` or `@R.rewriter`, or their
        imported names `@ir_module` or `@rewriter`.
        """

        return line.startswith("@") and ("ir_module" in line or "rewriter" in line)

    if len(frames) > 2:
        frame_info = frames[2]
        code_context = frame_info.code_context
        if code_context is None:
            return False
        line = code_context[0].strip()
        if _is_tvmscript_class_annotator(line):
            return True
        if line.startswith("class"):
            lineno = frame_info.lineno
            if lineno >= 2:
                source, _ = findsource(obj)
                line = source[lineno - 2].strip()
                if _is_tvmscript_class_annotator(line):
                    return True
    return False

async def list_prompt_optimization_jobs(
        project_id: Annotated[
            str, Path(description="The unique identifier of the project.")
        ],
        task_id: Annotated[
            str,
            Path(description="The unique identifier of the task within the project."),
        ],
        update_status: Annotated[
            bool,
            Query(
                description="Whether to update the status of non-final jobs from the remote server."
            ),
        ] = False,
    ) -> list[PromptOptimizationJob]:
        task = task_from_id(project_id, task_id)
        prompt_optimization_jobs = task.prompt_optimization_jobs()

        if update_status:
            try:
                server_client = get_authenticated_client(_get_api_key())
                if isinstance(server_client, AuthenticatedClient):
                    # Filter jobs that need status updates
                    jobs_to_update = [
                        job
                        for job in prompt_optimization_jobs
                        if not is_job_status_final(job.latest_status)
                    ]

                    # Update in batches of 5 in parallel
                    batch_size = 5
                    for i in range(0, len(jobs_to_update), batch_size):
                        batch = jobs_to_update[i : i + batch_size]

                        # this swallows the exceptions from each call, which is fine
                        await asyncio.gather(
                            *[
                                update_prompt_optimization_job_and_create_artifacts(
                                    job, server_client
                                )
                                for job in batch
                            ],
                            return_exceptions=True,
                        )
            except Exception as e:
                logger.error(
                    f"Error updating Prompt Optimization job statuses: {e}",
                    exc_info=True,
                )

        return prompt_optimization_jobs

