def map_scores_to_timestamps(window_scores, window_size, step,
                              n_timestamps, aggregation='max'):
    scores = np.full(n_timestamps, np.nan)
    counts = np.zeros(n_timestamps)

    for i, score in enumerate(window_scores):
        start = i * step
        end = min(start + window_size, n_timestamps)
        if aggregation == 'max':
            for j in range(start, end):
                if np.isnan(scores[j]) or score > scores[j]:
                    scores[j] = score
        else:  # mean
            for j in range(start, end):
                if np.isnan(scores[j]):
                    scores[j] = score
                else:
                    scores[j] += score
                counts[j] += 1

    if aggregation == 'mean':
        mask = counts > 0
        scores[mask] /= counts[mask]

    valid_mask = ~np.isnan(scores)
    return scores, valid_mask

def update_key_name(mapping: dict[str, Any]) -> dict[str, Any]:
    # (pattern, value) -> list[set[int]] (per-star index values)
    not_mapping = False
    if not isinstance(mapping, dict):
        mapping = {k: k for k in mapping}
        not_mapping = True

    bucket: dict[str, list[set[int] | Any]] = defaultdict(list)
    for key, val in mapping.items():
        digs = _DIGIT_RX.findall(key)
        patt = _pattern_of(key)
        for i, d in enumerate(digs):
            if len(bucket[patt]) <= i:
                bucket[patt].append(set())
            bucket[patt][i].add(int(d))
        bucket[patt].append(val)

    out_items = {}
    for patt, values in bucket.items():
        sets, val = values[:-1], values[-1]
        parts = patt.split("*")  # stars are between parts
        final = parts[0]
        for i in range(1, len(parts)):
            if i - 1 < len(sets) and sets[i - 1]:
                insert = _fmt_indices(sorted(sets[i - 1]))
                if len(sets[i - 1]) > 1:
                    final += "{" + insert + "}"
                else:
                    final += insert
            else:
                final += "*"
            final += parts[i]

        out_items[final] = val
    out = OrderedDict(out_items)
    if not_mapping:
        return out.keys()
    return out

def get_sklearn_tag(estimator, tagname):
    from sktime.utils.dependencies import _check_soft_dependencies

    if tagname == "capability:multioutput":
        if _check_soft_dependencies("scikit-learn<1.6", severity="none"):
            return estimator._get_tags().get("multioutput", False)
        else:
            from sklearn.utils import get_tags

            return get_tags(estimator).target_tags.multi_output

    elif tagname == "capability:categorical":
        if _check_soft_dependencies("scikit-learn<1.6", severity="none"):
            if hasattr(estimator, "_get_tags"):
                categorical_list = ["categorical", "1dlabels", "2dlabels"]
                tag_values = estimator._get_tags()["X_types"]
                return any(val in tag_values for val in categorical_list)
        else:
            from sklearn.utils import get_tags

            cat1 = get_tags(estimator).input_tags.categorical
            cat2 = get_tags(estimator).target_tags.one_d_labels
            cat3 = get_tags(estimator).target_tags.two_d_labels
            return cat1 or cat2 or cat3
        return False

    elif tagname == "fit_is_empty":
        if _check_soft_dependencies("scikit-learn>=1.6", severity="none"):
            from sklearn.utils import get_tags

            return not get_tags(estimator).requires_fit
        else:
            if hasattr(estimator, "_get_tags"):
                return estimator._get_tags()["stateless"]
            else:
                return False

def undelete_deleted_message(self, message: Message | UUID):
        message_id = None
        if isinstance(message, UUID):
            message_id = message
        elif isinstance(message, Message):
            message_id = message.id
        else:
            raise OasstError("Server error", OasstErrorCode.SERVER_ERROR1, HTTPStatus.INTERNAL_SERVER_ERROR)

        query = update(Message).where(Message.id == message_id).values(deleted=False)
        self.db.execute(query)

        parent_id = None
        if isinstance(message, UUID):
            parent_id = self.db.query(Message.parent_id).where(Message.id == message_id).first()[0]
        elif isinstance(message, Message):
            parent_id = message.parent_id

        if parent_id is None:
            return

        # Fetching the entire parent_message so there is no parent_id query executed after
        parent_message: Message = self.db.query(Message).where(Message.id == parent_id).first()

        if parent_message is not None:
            self.undelete_deleted_message(parent_message)

def aggregate_words(self, entities: list[dict], aggregation_strategy: AggregationStrategy) -> list[dict]:
        if aggregation_strategy in {
            AggregationStrategy.NONE,
            AggregationStrategy.SIMPLE,
        }:
            raise ValueError("NONE and SIMPLE strategies are invalid for word aggregation")

        word_entities = []
        word_group = None
        for entity in entities:
            if word_group is None:
                word_group = [entity]
            elif entity["is_subword"]:
                word_group.append(entity)
            else:
                word_entities.append(self.aggregate_word(word_group, aggregation_strategy))
                word_group = [entity]
        # Last item
        if word_group is not None:
            word_entities.append(self.aggregate_word(word_group, aggregation_strategy))
        return word_entities

