        tests = json.dumps(tests)

        if dataset_name == "livecodebench":
            starter_code = example.get("starter_code", None)
            question = fetch_live_code_bench_system_prompt(question, starter_code)
        if isinstance(question, dict):
            question = json.dumps(question)
        data = {
            "data_source": dataset_name,
            "prompt": [{"role": "user", "content": question}],
            "ability": "code",
            "reward_model": {"style": "rule", "ground_truth": tests},
            "extra_info": {
                "split": split,
                "index": idx,
                "reference": example.get("completion", None),  # For leetcode
                "task": {"data_source": dataset_name, "question": question, "ground_truth": tests},
            },
        }
        return data

    return process_fn

def sum(
        self,
        numeric_only: bool = False,
        engine=None,
        engine_kwargs=None,
    ):
        if not self.adjust:
            raise NotImplementedError("sum is not implemented with adjust=False")
        if self.times is not None:
            raise NotImplementedError("sum is not implemented with times")
        if maybe_use_numba(engine):
            if self.method == "single":
                func = generate_numba_ewm_func
            else:
                func = generate_numba_ewm_table_func
            ewm_func = func(
                **get_jit_arguments(engine_kwargs),
                com=self._com,
                adjust=self.adjust,
                ignore_na=self.ignore_na,
                deltas=tuple(self._deltas),
                normalize=False,
            )
            return self._apply(ewm_func, name="sum")
        elif engine in ("cython", None):
            if engine_kwargs is not None:
                raise ValueError("cython engine does not accept engine_kwargs")

            deltas = None if self.times is None else self._deltas
            window_func = partial(
                window_aggregations.ewm,
                com=self._com,
                adjust=self.adjust,
                ignore_na=self.ignore_na,
                deltas=deltas,
                normalize=False,
            )
            return self._apply(window_func, name="sum", numeric_only=numeric_only)
        else:
            raise ValueError("engine must be either 'numba' or 'cython'")

def map_estimate(self, name):
        site = self.prototype_trace.nodes[name]
        fn = site["fn"]
        event_dim = fn.event_dim
        init_needed = not hasattr(self, name)
        if init_needed:
            init_value = site["value"].detach()
        with ExitStack() as stack:
            for frame in site["cond_indep_stack"]:
                plate = self.plate(frame.name)
                if plate not in runtime._PYRO_STACK:
                    stack.enter_context(plate)
                elif init_needed and plate.subsample_size < plate.size:
                    # Repeat the init_value to full size.
                    dim = plate.dim - event_dim
                    assert init_value.size(dim) == plate.subsample_size
                    ind = torch.arange(plate.size, device=init_value.device)
                    ind = ind % plate.subsample_size
                    init_value = init_value.index_select(dim, ind)
            if init_needed:
                setattr(self, name, PyroParam(init_value, fn.support, event_dim))
            value = getattr(self, name)
            return pyro.sample(name, dist.Delta(value, event_dim=event_dim))

def compute(self) -> Any:
        # ddp hotfix, could be done better
        # but metric must handle DDP on it's own
        if self._ddp_backend == "xla":
            device = get_device()
            for key in self.statistics:
                key_statistics = torch.tensor([self.statistics[key]], device=device)
                key_statistics = xm.all_gather(key_statistics).sum(dim=0).cpu().numpy()
                self.statistics[key] = key_statistics
        elif self._ddp_backend == "ddp":
            for key in self.statistics:
                value: List[np.ndarray] = all_gather(self.statistics[key])
                value: np.ndarray = np.sum(np.vstack(value), axis=0)
                self.statistics[key] = value

        per_class, micro, macro, weighted = get_aggregated_metrics(
            tp=self.statistics["tp"],
            fp=self.statistics["fp"],
            fn=self.statistics["fn"],
            support=self.statistics["support"],
            zero_division=self.zero_division,
        )
        if self.compute_per_class_metrics:
            return per_class, micro, macro, weighted
        else:
            return [], micro, macro, weighted

def search_knowledge_base(query: str) -> str:
    query_lower = query.lower()
    results = []
    for key, value in _KNOWLEDGE_BASE.items():
        if key in query_lower or any(word in query_lower for word in key.split()):
            results.append(value)
    if not results:
        # Fuzzy: check if any KB entry mentions terms from the query
        for key, value in _KNOWLEDGE_BASE.items():
            if any(word in value.lower() for word in query_lower.split() if len(word) > 3):
                results.append(value)
    return "\n\n".join(results) if results else f"No information found for: {query}"

def link(*figs, include_events=None, exclude_events=None, verbose=None):
    if include_events is not None:
        include_events = set(include_events)
    if exclude_events is not None:
        exclude_events = set(exclude_events)

    # Make sure the event channels of the figures are setup properly.
    for fig in figs:
        _get_event_channel(fig)
        if fig not in _event_channel_links:
            _event_channel_links[fig] = weakref.WeakKeyDictionary()

    # Link the event channels
    for fig1 in figs:
        for fig2 in figs:
            if fig1 is not fig2:
                _event_channel_links[fig1][fig2] = (include_events, exclude_events)

def aggregate(
    workers: List[Callable],
    task: str = None,
    type: HistoryOutputType = "all",
    aggregator_model_name: str = "anthropic/claude-3-sonnet-20240229",
):

    if task is None:
        raise ValueError("Task is required in the aggregator block")

    if workers is None:
        raise ValueError(
            "Workers is required in the aggregator block"
        )

    if not isinstance(workers, list):
        raise ValueError("Workers must be a list of Callable")

    if not all(isinstance(worker, Callable) for worker in workers):
        raise ValueError("Workers must be a list of Callable")

    conversation = Conversation()

    aggregator_agent = Agent(
        agent_name="Aggregator",
        agent_description="Expert agent specializing in analyzing and synthesizing multi-agent conversations",
        system_prompt=AGGREGATOR_SYSTEM_PROMPT,
        max_loops=1,
        model_name=aggregator_model_name,
        output_type="final",
        max_tokens=4000,
    )

    results = run_agents_concurrently(agents=workers, task=task)

    # Zip the results with the agents
    for result, agent in zip(results, workers):
        conversation.add(content=result, role=agent.agent_name)

    final_result = aggregator_agent.run(
        task=aggregator_agent_task_prompt(task, workers, conversation)
    )

    conversation.add(
        content=final_result, role=aggregator_agent.agent_name
    )

    return history_output_formatter(
        conversation=conversation, type=type
    )

