def add_motors(physics, model, lumbar_joints, cervical_joints, caudal_joints):
  # Fixed Tendons:
  spinal_joints = collections.OrderedDict()
  spinal_joints['lumbar_'] = lumbar_joints
  spinal_joints['cervical_'] = cervical_joints
  spinal_joints['caudal_'] = caudal_joints
  tendons = []
  for region in spinal_joints.keys():
    for direction in ['extend', 'bend', 'twist']:
      joints = [
          joint for joint in spinal_joints[region] if direction in joint.name
      ]
      if joints:
        tendon = model.tendon.add(
            'fixed', name=region + direction, dclass=joints[0].dclass
        )
        tendons.append(tendon)
        joint_inertia = physics.bind(joints).M0
        coefs = joint_inertia**0.25
        coefs /= coefs.sum()
        coefs *= len(joints)
        for i, joint in enumerate(joints):
          tendon.add('joint', joint=joint, coef=coefs[i])

  # Actuators:
  all_spinal_joints = []
  for region in spinal_joints.values():
    all_spinal_joints.extend(region)
  root_joint = model.find('joint', 'root')
  actuated_joints = [
      joint
      for joint in model.find_all('joint')
      if joint not in all_spinal_joints and joint is not root_joint
  ]
  for tendon in tendons:
    gain = 0.0
    for joint in tendon.joint:
      # joint.joint.user = physics.bind(joint.joint).damping
      def_joint = model.default.find('default', joint.joint.dclass)
      j_gain = def_joint.general.gainprm or def_joint.parent.general.gainprm
      gain += j_gain[0] * joint.coef
    gain /= len(tendon.joint)

    model.actuator.add(
        'general', tendon=tendon, name=tendon.name, dclass=tendon.dclass
    )

  for joint in actuated_joints:
    model.actuator.add(
        'general', joint=joint, name=joint.name, dclass=joint.dclass
    )

  return actuated_joints

def check_scoring(scoring, allow_y_pred_benchmark=False, obj=None):
    # Note symmetric=True is default arg for MeanAbsolutePercentageError
    from sktime.performance_metrics.base import BaseMetric
    from sktime.performance_metrics.forecasting import (
        MeanAbsolutePercentageError,
        make_forecasting_scorer,
    )

    if scoring is None:
        return MeanAbsolutePercentageError()

    if obj is not None:
        obj_str = f" of {str(obj)}"
    else:
        obj_str = ""

    msg = (
        f"scoring parameter{obj_str} must be one of the following: "
        "(1) an sktime metric, descendant of BaseMetric; (2) a callable with signature "
        "(y_true: 1D np.ndarray, y_pred: 1D np.ndarray) -> float, "
        "assuming np.ndarrays being of the same length, and lower being better; "
        "(3) a string, resolvable by registry.resolve_alias to an object of either "
        "type (1) or (2)"
    )

    # deal with case (3) first - if string, try to resolve and return
    if isinstance(scoring, str):
        # lazy import of sktime.registry to avoid circular imports
        # and to ensure maximal decoupling from registry
        from sktime.registry import resolve_alias

        return resolve_alias(scoring)

    # check case (1) and case (2)
    # note: BaseMetric descendants are callable, so this is the same as
    # if not callable(scoring) and not isinstance(scoring, BaseMetric)
    if not callable(scoring):
        raise TypeError(msg)

    if not isinstance(scoring, BaseMetric):
        scoring = make_forecasting_scorer(func=scoring, greater_is_better=False)

    if hasattr(scoring, "get_class_tag"):
        scoring_req_bench = scoring.get_class_tag("requires-y-pred-benchmark", False)
        if scoring_req_bench and not allow_y_pred_benchmark:
            msg = (
                "Scoring requiring benchmark forecasts (y_pred_benchmark) are not "
                "fully supported yet. Please use a performance metric that does not "
                "require y_pred_benchmark as a keyword argument in its call signature."
            )
            raise NotImplementedError(msg)

    return scoring

def save_final_weights(model, args, accelerator, processor=None, tokenizer=None):
    unwrapped_model = accelerator.unwrap_model(model)
    is_main_process = accelerator.is_main_process
    save_path = args.external_save_dir
    model_name = args.model_name.lower()

    unwrapped_model.config.save_pretrained(save_path)

    if args.save_hf_model:
        save_pretrained(unwrapped_model, save_path, is_main_process, accelerator.save)

        if "idefics" in model_name or "fuyu" in model_name:
            save_pretrained(processor, save_path, is_main_process, accelerator.save)

        if "llama2" in model_name:
            save_pretrained(tokenizer, save_path, is_main_process, accelerator.save)
    else:
        # Save based on the distributed type
        if accelerator.distributed_type == "DEEPSPEED" and accelerator.state.deepspeed_plugin.zero_stage == 3:
            checkpoint_dict = accelerator.get_state_dict(model)
        else:
            checkpoint_dict = get_checkpoint(model=unwrapped_model)

        if accelerator.distributed_type == "DEEPSPEED" and accelerator.state.deepspeed_plugin.zero_stage == 3:
            trainable_params_name = [name for name, p in unwrapped_model.named_parameters() if p.requires_grad]
            checkpoint_dict = {k: v for k, v in checkpoint_dict.items() if k in trainable_params_name}

        save_checkpoint(checkpoint_dict, save_path, is_main_process, accelerator.save)

def paired_ttest_kfold_cv(
    estimator1, estimator2, X, y, cv=10, scoring=None, shuffle=False, random_seed=None
):

    if not shuffle:
        kf = KFold(n_splits=cv, shuffle=shuffle)
    else:
        kf = KFold(n_splits=cv, random_state=random_seed, shuffle=shuffle)

    if scoring is None:
        est_type = _infer_estimator_type(estimator1)
        if est_type == "classifier":
            scoring = "accuracy"
        elif est_type == "regressor":
            scoring = "r2"
        else:
            raise AttributeError("Estimator must be a Classifier or Regressor.")
    if isinstance(scoring, str):
        scorer = get_scorer(scoring)
    else:
        scorer = scoring

    score_diff = []

    for train_index, test_index in kf.split(X):
        X_train, X_test = X[train_index], X[test_index]
        y_train, y_test = y[train_index], y[test_index]

        estimator1.fit(X_train, y_train)
        estimator2.fit(X_train, y_train)

        est1_score = scorer(estimator1, X_test, y_test)
        est2_score = scorer(estimator2, X_test, y_test)
        score_diff.append(est1_score - est2_score)

    avg_diff = np.mean(score_diff)

    numerator = avg_diff * np.sqrt(cv)
    denominator = np.sqrt(
        sum([(diff - avg_diff) ** 2 for diff in score_diff]) / (cv - 1)
    )
    t_stat = numerator / denominator

    pvalue = stats.t.sf(np.abs(t_stat), cv - 1) * 2.0
    return float(t_stat), float(pvalue)

def filter(
        self, iterable: Iterable[UnparsedVersionVar], prereleases: Optional[bool] = None
    ) -> Iterator[UnparsedVersionVar]:
        # Determine if we're forcing a prerelease or not, if we're not forcing
        # one for this particular filter call, then we'll use whatever the
        # SpecifierSet thinks for whether or not we should support prereleases.
        if prereleases is None:
            prereleases = self.prereleases

        # If we have any specifiers, then we want to wrap our iterable in the
        # filter method for each one, this will act as a logical AND amongst
        # each specifier.
        if self._specs:
            for spec in self._specs:
                iterable = spec.filter(iterable, prereleases=bool(prereleases))
            return iter(iterable)
        # If we do not have any specifiers, then we need to have a rough filter
        # which will filter out any pre-releases, unless there are no final
        # releases.
        else:
            filtered: List[UnparsedVersionVar] = []
            found_prereleases: List[UnparsedVersionVar] = []

            for item in iterable:
                parsed_version = _coerce_version(item)

                # Store any item which is a pre-release for later unless we've
                # already found a final version or we are accepting prereleases
                if parsed_version.is_prerelease and not prereleases:
                    if not filtered:
                        found_prereleases.append(item)
                else:
                    filtered.append(item)

            # If we've found no items except for pre-releases, then we'll go
            # ahead and use the pre-releases
            if not filtered and found_prereleases and prereleases is None:
                return iter(found_prereleases)

            return iter(filtered)

def FloatRangeTupleDataclassField(
    n: int = 2,
    default: tuple | None = (0.9, 0.999),
    allow_none: bool = False,
    min: int | None = 0,
    max: int | None = 1,
    description: str = "",
    parameter_metadata: ParameterMetadata = None,
):
    if default is not None:
        if n != len(default):
            raise ValueError(f"Dimension of tuple '{n}' must match dimension of default val. '{default}'")
        for v in default:
            if min is not None and v < min:
                raise ValueError(f"Invalid default: value {v} below minimum {min}")
            if max is not None and v > max:
                raise ValueError(f"Invalid default: value {v} above maximum {max}")
    if default is None and not allow_none:
        raise ValueError("Default value must not be None if allow_none is False")

    extra_kwargs = {}
    if allow_none:
        extra_kwargs["allow_none"] = True
    json_extra = _make_json_schema_extra(
        description=description,
        parameter_metadata=parameter_metadata,
        _float_tuple_range={"n": n, "min": min, "max": max},
        **extra_kwargs,
    )
    return Field(default=default, description=description, json_schema_extra=json_extra)

def find_program(basename):
    names = [basename]
    if os.name == "nt":
        # Windows platforms
        extensions = (".exe", ".bat", ".cmd", ".dll")
        if not basename.endswith(extensions):
            names = [basename + ext for ext in extensions] + [basename]
    for name in names:
        path = is_program_installed(name)
        if path:
            return path

def add_enumerated_multiarray_shapes(spec, feature_name, shapes):
    if not isinstance(shapes, list):
        shapes = [shapes]

    for shape in shapes:
        if not isinstance(shape, NeuralNetworkMultiArrayShape):
            raise Exception(
                "Shape ranges should be of type NeuralNetworkMultiArrayShape"
            )
        shape._validate_multiarray_shape()

    feature = _get_feature(spec, feature_name)
    if feature.type.WhichOneof("Type") != "multiArrayType":
        raise Exception(
            "Trying to add enumerated shapes to " "a non-multiArray feature type"
        )

    if feature.type.multiArrayType.WhichOneof("ShapeFlexibility") != "enumeratedShapes":
        feature.type.multiArrayType.ClearField("ShapeFlexibility")

    eshape_len = len(feature.type.multiArrayType.enumeratedShapes.shapes)

    # Add default array shape to list of enumerated shapes if enumerated shapes
    # field is currently empty
    if eshape_len == 0:
        fixed_shape = feature.type.multiArrayType.shape
        if len(fixed_shape) == 1:
            fs = NeuralNetworkMultiArrayShape(fixed_shape[0])
            shapes.append(fs)
        elif len(fixed_shape) == 3:
            fs = NeuralNetworkMultiArrayShape()
            fs.set_channel_shape(fixed_shape[0])
            fs.set_height_shape(fixed_shape[1])
            fs.set_width_shape(fixed_shape[2])
            shapes.append(fs)
        else:
            raise Exception(
                "Original fixed multiArray shape for {} is invalid".format(feature_name)
            )

    for shape in shapes:
        s = feature.type.multiArrayType.enumeratedShapes.shapes.add()
        s.shape.extend(shape.multiarray_shape)

    # Bump up specification version
    spec.specificationVersion = max(
        _MINIMUM_FLEXIBLE_SHAPES_SPEC_VERSION, spec.specificationVersion
    )

def get_app_server_host(cls, config: Optional[ConfigTree] = None) -> str:
        if not config:
            from ...config import config_obj

            config = config_obj

        # get from config/environment
        web_host = ENV_WEB_HOST.get(default=config.get("api.web_server", "")).rstrip("/")
        if web_host:
            return web_host

        # return default
        host = cls.get_api_server_host(config)
        if host == cls.default_host and cls.default_web:
            return cls.default_web

        # compose ourselves
        if "://demoapi." in host:
            return host.replace("://demoapi.", "://demoapp.", 1)
        if "://api." in host:
            return host.replace("://api.", "://app.", 1)

        parsed = urlparse(host)
        if parsed.port == 8008:
            return host.replace(":8008", ":8080", 1)

        raise ValueError("Could not detect ClearML web application server")

def cosine_schedule(
    step: int,
    max_steps: int,
    start_value: float,
    end_value: float,
    period: Optional[int] = None,
) -> float:
    if step < 0:
        raise ValueError(f"Current step number {step} can't be negative.")
    if max_steps < 0:
        raise ValueError(f"Total step number {max_steps} can't be negative.")
    if period is None and step > max_steps:
        warnings.warn(
            f"Current step number {step} exceeds max_steps {max_steps}.",
            category=RuntimeWarning,
        )
    if period is not None and period <= 0:
        raise ValueError(f"Period {period} must be >= 1")

    decay: float
    if period is not None:  # "cycle" based on period, if provided
        decay = (
            end_value
            - (end_value - start_value) * (np.cos(2 * np.pi * step / period) + 1) / 2
        )
    elif max_steps <= 1:
        # Avoid division by zero
        decay = end_value
    elif step >= max_steps - 1:
        # Special case for Pytorch Lightning which updates LR scheduler also for epoch
        # after last training epoch.
        decay = end_value
    else:
        decay = (
            end_value
            - (end_value - start_value)
            * (np.cos(np.pi * step / (max_steps - 1)) + 1)
            / 2
        )
    return decay

def validate_layers_block_type(self):
        if not isinstance(self.layers_block_type, list):
            raise ValueError(
                f"`layers_block_type` must be a list of strings. Got type: {type(self.layers_block_type)}"
            )

        valid_types = {"mamba", "attention", "moe"}
        if not all(block_type in valid_types for block_type in self.layers_block_type):
            invalid = set(self.layers_block_type) - valid_types
            raise ValueError(f"`layers_block_type` contains invalid types: {invalid}. Must be one of: {valid_types}")

        if self.num_nextn_predict_layers > 0:
            if self.mtp_layers_block_type is None:
                raise ValueError(
                    "mtp_layers_block_type is required when num_nextn_predict_layers > 0. "
                    "Please provide an explicit list of layer types for MTP layers. "
                    "Example: mtp_layers_block_type=['attention', 'moe']"
                )

            if not isinstance(self.mtp_layers_block_type, list):
                raise ValueError(
                    f"`mtp_layers_block_type` must be a list of strings. Got type: {type(self.mtp_layers_block_type)}"
                )

            valid_types = {"mamba", "attention", "moe"}
            if not all(block_type in valid_types for block_type in self.mtp_layers_block_type):
                invalid = set(self.mtp_layers_block_type) - valid_types
                raise ValueError(
                    f"`mtp_layers_block_type` contains invalid types: {invalid}. Must be one of: {valid_types}"
                )

def parse_bullet_entry(line: str) -> dict | None:
    line = line.strip()
    if not line.startswith("*") and not line.startswith("-"):
        return None
    line = line.lstrip("*- ").strip()
    if not line:
        return None

    # Check if line starts with a markdown link [Name](url) vs plain text.
    # Plain text entries like "AirSim (archived) - ..." have no name link;
    # RE_LINK.search would wrongly match [[github](...)] badges instead.
    if line.startswith("[") and not line.startswith("[["):
        m = RE_LINK.match(line)
        if m:
            name = m.group(1)
            url = m.group(2)
        else:
            name = line.split(" - ")[0].split(" [[")[0].strip()
            name = re.sub(r"\(archived\)", "", name).strip()
            url = None
    else:
        # Plain text name (no homepage link)
        name = line.split(" - ")[0].split(" [[")[0].strip()
        name = re.sub(r"\(archived\)", "", name).strip()
        url = None

    entry: dict = {"name": name}
    if url:
        entry["url"] = url

    # Check for archived flag
    if "(archived)" in line:
        entry["archived"] = True
        line = line.replace("(archived)", "").strip()

    # Extract github/bitbucket/gitlab
    github = _extract_github(line)
    if github:
        entry["github"] = github
    else:
        bb = _extract_bitbucket(line)
        if bb:
            entry["bitbucket"] = bb
        gl = _extract_gitlab(line)
        if gl:
            entry["gitlab"] = gl

    # Extract description (text after " - " separator)
    desc_m = re.search(r"\]\([^)]+\)\s*-\s*(.+?)(?:\s*\[\[|\s*$)", line)
    if not desc_m:
        # Fallback for plain-text name entries: "Name - Description [[github..."
        desc_m = re.search(r"^[^[\]]+?\s-\s(.+?)(?:\s*\[\[|\s*$)", line)
    if desc_m:
        desc = _clean_desc(desc_m.group(1))
        if desc:
            entry["description"] = desc

    return entry

def QSettings_readArray(settings, key, scheme):
    # type: (QSettings, str, Mapping[str, ValueSpec]) -> List[Dict[str, Any]]
    items = []
    count = settings.beginReadArray(key)

    def normalize_spec(spec):
        if isinstance(spec, tuple):
            if len(spec) != 2:
                raise ValueError("len(spec) != 2")
            type_, default = spec
        else:
            type_, default = spec, None
        return type_, default

    specs = {
        name: normalize_spec(spec) for name, spec in scheme.items()
    }
    for i in range(count):
        settings.setArrayIndex(i)
        item = {}
        for key, (type_, default) in specs.items():
            value = settings.value(key, type=type_, defaultValue=default)
            item[key] = value
        items.append(item)
    settings.endArray()
    return items

def get_preprocessors(self, preprocessor):
        train_preprocessor = None
        eval_preprocessor = None
        if isinstance(preprocessor, Preprocessor):
            train_preprocessor = preprocessor
            eval_preprocessor = preprocessor
        elif isinstance(preprocessor, Mapping):
            if ConfigKeys.train in preprocessor:
                assert isinstance(preprocessor[ConfigKeys.train], Callable)
                train_preprocessor = preprocessor[ConfigKeys.train]
            if ConfigKeys.val in preprocessor:
                assert isinstance(preprocessor[ConfigKeys.val], Callable)
                eval_preprocessor = preprocessor[ConfigKeys.val]
        elif hasattr(self.cfg, ConfigFields.preprocessor
                     ) and self.cfg.preprocessor is not None:
            train_preprocessor, eval_preprocessor = self.build_preprocessor()

        if train_preprocessor is not None:
            train_preprocessor.mode = ModeKeys.TRAIN
        if eval_preprocessor is not None:
            eval_preprocessor.mode = ModeKeys.EVAL
        return train_preprocessor, eval_preprocessor

def count(words=[], top=None, threshold=0, stemmer=None, exclude=[], stopwords=False, language=None, **kwargs):
    # An optional dict-parameter can be used to specify a subclass of dict,
    # e.g., count(words, dict=readonlydict) as used in Document.
    count = kwargs.get("dict", dict)()
    for w in words:
        w1 = w
        w2 = w
        if hasattr(w, "string"): # pattern.en.Word
            w1 = w.string.lower()
        if isinstance(w, str):
            w1 = w.lower()
            w2 = w.lower()
        if (stopwords or w1 not in _stopwords.get(language or "en", ())) and w1 not in exclude:
            if stemmer is not None:
                w2 = stem(w2, stemmer, **kwargs).lower()
            dict.__setitem__(count, w2, (w2 in count) and count[w2] + 1 or 1)
    for k in list(count.keys()):
        if count[k] <= threshold:
            dict.__delitem__(count, k)
    if top is not None:
        count = count.__class__(heapq.nsmallest(top, list(count.items()), key=lambda kv: (-kv[1], kv[0])))
    return count

def check_ip_allowlist(client_ip: str, allowed_ips: List[str]) -> bool:
    import ipaddress

    try:
        client_addr = ipaddress.ip_address(client_ip)
    except ValueError:
        return False

    for allowed in allowed_ips:
        try:
            if "/" in allowed:
                if client_addr in ipaddress.ip_network(allowed, strict=False):
                    return True
            else:
                if client_addr == ipaddress.ip_address(allowed):
                    return True
        except ValueError:
            continue

    return False

def to_df(
        self,
        validation_reference=None,
        timeout: Optional[int] = None,
    ) -> pd.DataFrame:
        if self._result_df is None:
            if self.on_demand_feature_views:
                # Use parent implementation for ODFV processing
                logger.info(
                    f"Processing {len(self.on_demand_feature_views)} on-demand feature views"
                )
                self._result_df = super().to_df(
                    validation_reference=validation_reference, timeout=timeout
                )
            else:
                # Direct conversion from Ray Dataset
                self._ensure_executed()
                assert self._result_dataset is not None, (
                    "Dataset should not be None after execution"
                )
                self._result_df = self._result_dataset.to_pandas()

        # Handle validation if provided
        if validation_reference:
            try:
                validation_result = validation_reference.profile.validate(
                    self._result_df
                )
                if not validation_result.is_success:
                    raise ValidationFailed(validation_result)
            except ImportError:
                logger.warning("DQM profiler not available, skipping validation")
            except Exception as e:
                logger.error(f"Validation failed: {e}")
                raise ValueError(f"Data validation failed: {e}")

        return self._result_df

def get_type_family_raw(dtype) -> str:
    try:
        if isinstance(dtype, pd.SparseDtype):
            dtype = dtype.subtype
        if dtype.name == "category":
            return "category"
        if "datetime" in dtype.name:
            return "datetime"
        if "string" in dtype.name:
            return "object"
        elif np.issubdtype(dtype, np.integer):
            return "int"
        elif np.issubdtype(dtype, np.floating):
            return "float"
    except Exception as err:
        logger.error(
            f"Warning: dtype {dtype} is not recognized as a valid dtype by numpy! "
            f"AutoGluon may incorrectly handle this feature..."
        )
        logger.error(err)

    if dtype.name in ["bool", "bool_"]:
        return "bool"
    elif dtype.name in ["str", "string", "object"]:
        return "object"
    else:
        return dtype.name

def get_json_result(self) -> LintResultJSON:
        from marimo._lint.formatters import (
            FileErrorJSON,
            IssueJSON,
            JSONFormatter,
        )

        json_formatter = JSONFormatter()
        issues: list[IssueJSON] = []

        for file_status in self.files:
            if file_status.failed:
                # Add file-level errors
                error: FileErrorJSON = {
                    "type": "error",
                    "filename": file_status.file,
                    "error": file_status.message,
                }
                issues.append(error)
            elif not file_status.skipped:
                # Add diagnostics from successfully processed files
                for diagnostic in file_status.diagnostics:
                    diagnostic_dict = json_formatter.to_json_dict(
                        diagnostic, file_status.file
                    )
                    issues.append(diagnostic_dict)

        return LintResultJSON(
            issues=issues,
            summary={
                "total_files": len(self.files),
                "files_with_issues": len(
                    [
                        f
                        for f in self.files
                        if (f.diagnostics and not f.skipped and not f.failed)
                        or f.failed
                    ]
                ),
                "total_issues": self.issues_count,
                "fixed_issues": self.fixed_count,
                "errored": self.errored,
            },
        )

def make_records(
        self,
        config: SendManagerConfig,
    ) -> Iterable[pb.Record]:
        yield self._make_run_record()
        yield self._make_telem_record()

        include_artifacts = config.log_artifacts or config.use_artifacts
        yield self._make_files_record(
            include_artifacts, config.files, config.media, config.code
        )

        if (
            config.use_artifacts
            and (used_artifacts := self.run.used_artifacts()) is not None
        ):
            for artifact in used_artifacts:
                yield self._make_artifact_record(artifact, use_artifact=True)

        if config.log_artifacts and (artifacts := self.run.artifacts()) is not None:
            for artifact in artifacts:
                yield self._make_artifact_record(artifact)

        if config.history:
            yield from self._make_history_records()

        if config.summary:
            yield self._make_summary_record()

        if config.terminal_output and (lines := self.run.logs()) is not None:
            for line in lines:
                yield self._make_output_record(line)

def get_content(self) -> bytes:
        if isinstance(self.content, bytes):
            pass
        elif isinstance(self.content, str):
            if _is_valid_url(self.content):
                # First, load from the URL, and then convert to BytesIO.
                try:
                    res = requests.get(self.content)
                    res.raise_for_status()
                except Exception:
                    raise ValueError(
                        f"Failed to download content from url: {self.content}"
                    )
                self.content = res.content
            elif re.match(r"^data:.*;base64,", self.content):
                self.content = base64.b64decode(self.content.split(",")[1])
            else:
                raise RuntimeError(
                    "You encountered a programming error. The File object passed"
                    " validation, but it seems that the content is neither a valid URL"
                    " nor a base64 encoded string. Please report this to Lepton. Got:"
                    f" {self.content}"
                )
        else:
            raise RuntimeError(
                "You encountered a programming error. The File object passed"
                " validation, but it seems that the content is illegal. Please report"
                f" this to Lepton. Got: {self.content}"
            )
        return self.content

def utteranceids(
        self, dialect=None, sex=None, spkrid=None, sent_type=None, sentid=None
    ):
        if isinstance(dialect, str):
            dialect = [dialect]
        if isinstance(sex, str):
            sex = [sex]
        if isinstance(spkrid, str):
            spkrid = [spkrid]
        if isinstance(sent_type, str):
            sent_type = [sent_type]
        if isinstance(sentid, str):
            sentid = [sentid]

        utterances = self._utterances[:]
        if dialect is not None:
            utterances = [u for u in utterances if u[2] in dialect]
        if sex is not None:
            utterances = [u for u in utterances if u[4] in sex]
        if spkrid is not None:
            utterances = [u for u in utterances if u[:9] in spkrid]
        if sent_type is not None:
            utterances = [u for u in utterances if u[11] in sent_type]
        if sentid is not None:
            utterances = [u for u in utterances if u[10:] in spkrid]
        return utterances

def on_train_start(self, trainer: "pl.Trainer", *args: Any, **kwargs: Any) -> None:
        if not trainer.loggers:
            raise MisconfigurationException(
                "Cannot use `LearningRateMonitor` callback with `Trainer` that has no logger."
            )

        if self.log_momentum:

            def _check_no_key(key: str) -> bool:
                if trainer.lr_scheduler_configs:
                    return any(
                        key not in config.scheduler.optimizer.defaults for config in trainer.lr_scheduler_configs
                    )

                return any(key not in optimizer.defaults for optimizer in trainer.optimizers)

            if _check_no_key("momentum") and _check_no_key("betas"):
                rank_zero_warn(
                    "You have set log_momentum=True, but some optimizers do not"
                    " have momentum. This will log a value 0 for the momentum.",
                    category=RuntimeWarning,
                )

        # Find names for schedulers
        names: list[list[str]] = []
        (
            sched_hparam_keys,
            optimizers_with_scheduler,
            optimizers_with_scheduler_types,
        ) = self._find_names_from_schedulers(trainer.lr_scheduler_configs)
        names.extend(sched_hparam_keys)

        # Find names for leftover optimizers
        optimizer_hparam_keys, _ = self._find_names_from_optimizers(
            trainer.optimizers,
            seen_optimizers=optimizers_with_scheduler,
            seen_optimizer_types=optimizers_with_scheduler_types,
        )
        names.extend(optimizer_hparam_keys)

        # Initialize for storing values
        names_flatten = list(itertools.chain.from_iterable(names))
        self.lrs = {name: [] for name in names_flatten}
        self.last_momentum_values = {name + "-momentum": None for name in names_flatten}
        self.last_weight_decay_values = {name + "-weight_decay": None for name in names_flatten}

def output_for_reasoning(self, response: any):
        output_parts = []

        # Check if reasoning content is available
        if (
            hasattr(response.choices[0].message, "reasoning_content")
            and response.choices[0].message.reasoning_content
        ):
            output_parts.append(
                f"Reasoning Content:\n{response.choices[0].message.reasoning_content}\n"
            )

        # Check if thinking blocks are available (Anthropic models)
        if (
            hasattr(response.choices[0].message, "thinking_blocks")
            and response.choices[0].message.thinking_blocks
        ):
            output_parts.append("Thinking Blocks:")
            for i, block in enumerate(
                response.choices[0].message.thinking_blocks, 1
            ):
                block_type = block.get("type", "")
                thinking = block.get("thinking", "")
                output_parts.append(
                    f"Block {i} (Type: {block_type}):"
                )
                output_parts.append(f"  Thinking: {thinking}")
                output_parts.append("")

        # Include tools if available
        if (
            hasattr(response.choices[0].message, "tool_calls")
            and response.choices[0].message.tool_calls
        ):
            output_parts.append(
                f"Tools:\n{self.output_for_tools(response)}\n"
            )

        # Always include the main content
        content = response.choices[0].message.content
        if content:
            output_parts.append(f"Content:\n{content}")

        # Join all parts into a single string
        return "\n".join(output_parts)

def check_str_for_functions_valid(self, output: str) -> bool:
        if not isinstance(output, str):
            raise ToolValidationError("Output must be a string")

        if self.function_map is None:
            self._log_if_verbose(
                "warning",
                "Function map is None, cannot validate function names",
            )
            return False

        try:
            self._log_if_verbose(
                "debug",
                f"Validating output string: {output[:100]}...",
            )

            # Parse the output as JSON
            try:
                data = json.loads(output)
            except json.JSONDecodeError:
                self._log_if_verbose(
                    "debug", "Output is not valid JSON"
                )
                return False

            # Check if the output matches the expected schema
            if (
                data.get("type") == "function"
                and "function" in data
                and "name" in data["function"]
            ):
                # Check if the function name matches any name in the function map
                function_name = data["function"]["name"]
                if function_name in self.function_map:
                    self._log_if_verbose(
                        "debug",
                        f"Valid function call for {function_name}",
                    )
                    return True
                else:
                    self._log_if_verbose(
                        "debug",
                        f"Function {function_name} not found in function map",
                    )
                    return False
            else:
                self._log_if_verbose(
                    "debug",
                    "Output does not match expected function call schema",
                )
                return False

        except Exception as e:
            self._log_if_verbose(
                "error", f"Error validating output: {e}"
            )
            return False

def is_var_visible_in_block(self, var: Var, upto_op: Optional[Operation] = None):
        if not DEBUG:
            # Only in debug mode, there is a chance that self.operations is type of list when executing this function.
            assert isinstance(
                self.operations, CacheDoublyLinkedList
            ), "operations must be type of CacheDoublyLinkedList."

        if var in self._internal_vars:
            return True

        inputs = list(self.inputs.values()) if isinstance(self, Function) else self.inputs
        if var in inputs:
            return True

        if upto_op is None:
            if var.op in self.operations:
                return True
        else:
            if isinstance(self.operations, list):
                # This could only happen in debug mode
                assert DEBUG is True, "block.operations can only be type of list in debug mode."
                idx = self.find_op_id_in_block(upto_op)
                for i in range(idx - 1, -1, -1):
                    if var.op is self.operations[i]:
                        return True
            else:
                cursor = self.operations._get_node_from_op(upto_op).prev
                while cursor is not None:
                    if cursor.op is var.op:
                        return True
                    cursor = cursor.prev

        if self.outer_op is not None:
            enclosing_block = self.outer_op.enclosing_block
            if enclosing_block.is_var_visible_in_block(var, upto_op=self.outer_op):
                return True

        return False

def fetch_webpage(url: str) -> dict:
    try:
        headers = {"User-Agent": "Mozilla/5.0"}
        req = urllib.request.Request(url, headers=headers)

        with urllib.request.urlopen(req, timeout=10) as response:
            html = response.read().decode("utf-8")

            title = ""
            if "<title>" in html:
                start = html.find("<title>") + 7
                end = html.find("</title>", start)
                title = html[start:end]

            text = html
            for tag in ["<script", "<style", "<nav", "<footer"]:
                while tag in text:
                    start = text.find(tag)
                    end = text.find(">", start) + 1
                    close_tag = f"</{tag[1:]}"
                    if close_tag in text[end:]:
                        end = text.find(close_tag, end) + len(close_tag) + 1
                    text = text[:start] + text[end:]

            for tag in ["<", ">"]:
                text = text.replace(tag, " ")

            lines = [line.strip() for line in text.split("\n") if line.strip()]
            content = " ".join(lines)[:3000]

            return {
                "success": True,
                "url": url,
                "title": title,
                "content": content,
            }

    except Exception as e:
        return {"success": False, "error": str(e)}

def expected_calibration_error(prediction_probabilities, accuracy, confidence):
    if not isinstance(prediction_probabilities, np.ndarray):
        raise ValueError(
            "Parameter prediction_probabilities must be type numpy.ndarray but given object of type {}".format(
                type(prediction_probabilities).__name__
            )
        )
    if not isinstance(accuracy, np.ndarray):
        raise ValueError(
            "Parameter accuracy must be type numpy.ndarray but given object of type {}".format(
                type(accuracy).__name__
            )
        )
    if not isinstance(confidence, np.ndarray):
        raise ValueError(
            "Parameter confidence must be type numpy.ndarray but given object of type {}".format(
                type(confidence).__name__
            )
        )

    if len(accuracy) != len(confidence):
        raise ValueError(
            "Arrays accuracy and confidence should have the same size but instead received {} and {} respectively.".format(
                len(accuracy), len(confidence)
            )
        )

    n_bins = len(accuracy)  # the number of bins
    n = len(prediction_probabilities)  # number of samples
    h = np.histogram(a=prediction_probabilities, range=(0, 1), bins=n_bins)[
        0
    ]  # just the counts
    ece = 0
    for m in np.arange(n_bins):
        ece = ece + (h[m] / n) * np.abs(accuracy[m] - confidence[m])
    return ece

def make_batched_env(
    create_env_fn, num_workers, batched_env_type="parallel", device=None, **kwargs
):
    from torchrl.envs import AsyncEnvPool, ParallelEnv, SerialEnv

    if create_env_fn is None:
        raise ValueError("create_env_fn must be provided")

    if num_workers is None:
        raise ValueError("num_workers must be provided")

    # If create_env_fn is a config object, create a lambda that instantiates it each time
    if isinstance(create_env_fn, EnvBase):
        # Already an instance (either instantiated config or actual env), wrap in lambda
        env_instance = create_env_fn

        def env_fn(env_instance=env_instance):
            return env_instance

    else:
        env_fn = create_env_fn
    assert callable(env_fn), env_fn

    # Add device to kwargs if provided
    if device is not None:
        kwargs["device"] = device

    if batched_env_type == "parallel":
        return ParallelEnv(num_workers, env_fn, **kwargs)
    elif batched_env_type == "serial":
        return SerialEnv(num_workers, env_fn, **kwargs)
    elif batched_env_type == "async":
        return AsyncEnvPool([env_fn] * num_workers, **kwargs)
    else:
        raise ValueError(f"Unknown batched_env_type: {batched_env_type}")

def stochastic_rsi(
    values: NDArray[np.float64],
    rsi_lookback: int,
    sto_lookback: int,
    smoothing: float = 0.0,
) -> NDArray[np.float64]:
    assert rsi_lookback > 0
    assert sto_lookback > 0
    assert smoothing >= 0
    n = len(values)
    front_bad = rsi_lookback + sto_lookback - 1
    if front_bad > n:
        front_bad = n
    output = np.zeros(n)
    if rsi_lookback >= n:
        return output
    for i in range(front_bad):
        output[i] = 0
    up_sum = dn_sum = 1.0e-60
    for i in range(1, rsi_lookback):
        diff = values[i] - values[i - 1]
        if diff > 0.0:
            up_sum += diff
        else:
            dn_sum -= diff
    up_sum /= rsi_lookback - 1
    dn_sum /= rsi_lookback - 1
    work1 = np.zeros(n)
    for i in range(rsi_lookback, n):
        diff = values[i] - values[i - 1]
        if diff > 0.0:
            up_sum = ((rsi_lookback - 1) * up_sum + diff) / rsi_lookback
            dn_sum *= (rsi_lookback - 1.0) / rsi_lookback
        else:
            dn_sum = ((rsi_lookback - 1) * dn_sum - diff) / rsi_lookback
            up_sum *= (rsi_lookback - 1.0) / rsi_lookback
        work1[i] = 100.0 * up_sum / (up_sum + dn_sum)
    for i in range(front_bad, n):
        min_val = 1.0e60
        max_val = -1.0e60
        for j in range(sto_lookback):
            if work1[i - j] > max_val:
                max_val = work1[i - j]
            if work1[i - j] < min_val:
                min_val = work1[i - j]
        output[i] = (
            100.0 * (work1[i] - min_val) / (max_val - min_val + 1.0e-60) - 50.0
        )
    if smoothing > 1:
        alpha = 2.0 / (smoothing + 1.0)
        smoothed = output[front_bad]
        for i in range(front_bad + 1, n):
            smoothed = alpha * output[i] + (1.0 - alpha) * smoothed
            output[i] = smoothed
    return output

def get_channel_types(self, picks=None, unique=False, only_data_chs=False):
        info = self if isinstance(self, Info) else self.info
        none = "data" if only_data_chs else "all"
        picks = _picks_to_idx(info, picks, none, (), allow_empty=False)
        ch_types = [channel_type(info, pick) for pick in picks]
        if only_data_chs:
            ch_types = [
                ch_type for ch_type in ch_types if ch_type in _DATA_CH_TYPES_SPLIT
            ]
        if unique:
            # set does not preserve order but dict does, so let's just use it
            ch_types = list({k: k for k in ch_types}.keys())
        return ch_types

def get_dataclass_schema(
    cls,
    exclude: ExcludeType = None,
    type_var_map: Optional[Dict] = None,
) -> Dict[str, Dict[str, object]]:

    if not is_dataclass(cls):
        raise ValueError(
            "Provided class is not a dataclass, please decorate your class with @dataclass"
        )

    type_var_map = type_var_map or {}

    # TODO: Add support for having a description in the dataclass
    schema = {
        "type": cls.__name__,
        "properties": {},
        "required": [],
        # "description": cls.__doc__ if cls.__doc__ else "",
    }
    # get the exclude list for the current class
    current_exclude = exclude.get(cls.__name__, []) if exclude else []

    # handle Combination of Enum and dataclass
    if issubclass(cls, Enum):
        schema["type"] = get_type_schema(cls, exclude, type_var_map)
        return schema

    for f in fields(cls):
        if f.name in current_exclude:
            continue
        # prepare field schema, it weill be done recursively for nested dataclasses

        field_type = type_var_map.get(f.type, f.type)
        field_schema = {"type": get_type_schema(field_type, exclude, type_var_map)}

        # check required field
        is_required = _is_required_field(f)
        if is_required:
            schema["required"].append(f.name)

        # add metadata to the field schema
        if f.metadata:
            field_schema.update(f.metadata)
        # handle nested dataclasses and complex types

        schema["properties"][f.name] = field_schema

    return schema

def synset(self, id, pos=ADJECTIVE):
        id = str(id).zfill(8)
        if not id.startswith(("n-", "v-", "a-", "r-")):
            if pos == NOUN:
                id = "n-" + id
            if pos == VERB:
                id = "v-" + id
            if pos == ADJECTIVE:
                id = "a-" + id
            if pos == ADVERB:
                id = "r-" + id
        if dict.__len__(self) == 0:
            self.load()
        try:
            return tuple(self._synsets[id])[:2]
        except KeyError: # Some WordNet id's are not zero padded.
            return tuple(self._synsets.get(re.sub(r"-0+", "-", id), (0.0, 0.0))[:2])

def validate_annotation_content(self, experiment_config, spec_key, builtin_name):
        if experiment_config.get('useAnnotation'):
            if experiment_config.get('searchSpacePath'):
                raise SchemaError('If you set useAnnotation=true, please leave searchSpacePath empty')
        else:
            # validate searchSpaceFile
            if experiment_config[spec_key].get(builtin_name) == 'NetworkMorphism':
                return
            if experiment_config[spec_key].get(builtin_name):
                if experiment_config.get('searchSpacePath') is None:
                    raise SchemaError('Please set searchSpacePath!')
                self.validate_search_space_content(experiment_config)

def compute_croppings_to_reach_powers_of(arr, height_base, width_base,
                                         allow_zero_exponent=False):
    def _compute_axis_value(axis_size, base):
        if base is None:
            return 0, 0
        if axis_size == 0:
            to_crop = 0
        elif axis_size < base:
            # crop down to B^0 = 1
            to_crop = axis_size - 1 if allow_zero_exponent else 0
        else:
            # log_{base}(axis_size) in numpy
            exponent = np.log(axis_size) / np.log(base)

            to_crop = axis_size - (base ** int(exponent))

        return int(np.floor(to_crop/2)), int(np.ceil(to_crop/2))

    _assert_two_or_three_dims(arr)

    if height_base is not None:
        assert height_base > 1, (
            "Can only crop to base larger than 1, got %d." % (height_base,))
    if width_base is not None:
        assert width_base > 1, (
            "Can only crop to base larger than 1, got %d." % (width_base,))

    shape = arr.shape if hasattr(arr, "shape") else arr
    height, width = shape[0:2]

    top, bottom = _compute_axis_value(height, height_base)
    left, right = _compute_axis_value(width, width_base)

    return top, right, bottom, left

def retrieve_eval_images(dataset_name=None):
    eval_datasets = StateTracker.get_data_backends(_type="eval", _types=None)
    output = {}
    eval_samples = None
    from simpletuner.helpers.training.collate import collate_fn

    new_sample = None
    # We loop until we successfully retrieve one collated batch or exhaust the data.
    while new_sample is None:
        # Decide which dataset(s) to pull from
        if dataset_name is not None:
            # Only attempt to pull from the requested dataset
            dataset_keys = [dataset_name]
        else:
            # Fallback: iterate over *all* eval datasets
            dataset_keys = list(eval_datasets.keys())

        for ds_name in dataset_keys:
            dataset = eval_datasets.get(ds_name)
            if not dataset or "train_dataset" not in dataset:
                logger.debug(f"Skipping eval set {ds_name} because it lacks a dataloader.")
                continue
            try:
                new_sample = next(dataset["sampler"].__iter__())
                data_loaded = dataset["train_dataset"].__getitem__(new_sample)
                if data_loaded:
                    output = collate_fn([data_loaded])
                # Indicate that we've found a batch and can break out of the loop
                new_sample = False
                break

            except MultiDatasetExhausted as e:
                logger.debug(f"Ran out of evaluation samples for dataset {ds_name}. Resetting buckets.")
                dataset["sampler"]._reset_buckets(raise_exhaustion_signal=False)
                # We re-raise if we've exhausted this dataset. If `dataset_name` is set,
                # we effectively stop; if it's None, we move to the next dataset.
                if dataset_name is not None:
                    raise e

    return output

def run(self):
        deleted_self = False
        while self.should_keep_running() and not deleted_self:
            inotify_events = self._inotify.read_events()
            for inotify_event in inotify_events:
                logger.debug("in-event %s", inotify_event)
                if inotify_event.is_moved_to:

                    def matching_from_event(event):
                        return (not isinstance(event, tuple) and event.is_moved_from
                                and event.cookie == inotify_event.cookie)

                    from_event = self._queue.remove(matching_from_event)
                    if from_event is not None:
                        self._queue.put((from_event, inotify_event))
                    else:
                        logger.debug("could not find matching move_from event")
                        self._queue.put(inotify_event)
                else:
                    self._queue.put(inotify_event)

                if inotify_event.is_delete_self and \
                        inotify_event.src_path == self._inotify.path:
                    # Deleted the watched directory, stop watching for events
                    deleted_self = True

def serialize_parameters(
        self, parameters: dict[str, Any | PrefectFuture[Any] | State]
    ) -> dict[str, Any]:
        serialized_parameters: dict[str, Any] = {}
        for key, value in parameters.items():
            # do not serialize the bound self object
            if self.ismethod and value is getattr(self.fn, "__prefect_self__", None):
                continue
            if self.isclassmethod and value is getattr(
                self.fn, "__prefect_cls__", None
            ):
                continue
            if isinstance(value, (PrefectFuture, State)):
                # Don't call jsonable_encoder() on a PrefectFuture or State to
                # avoid triggering a __getitem__ call
                serialized_parameters[key] = f"<{type(value).__name__}>"
                continue
            try:
                from fastapi.encoders import jsonable_encoder

                serialized_parameters[key] = jsonable_encoder(value)
            except (TypeError, ValueError):
                logger.debug(
                    f"Parameter {key!r} for flow {self.name!r} is unserializable. "
                    f"Type {type(value).__name__!r} and will not be stored "
                    "in the backend."
                )
                serialized_parameters[key] = f"<{type(value).__name__}>"
        return serialized_parameters

def get_versions(self) -> dict[tuple[int, int], str]:
        retval: dict[tuple[int, int], str] = {}
        assert winreg is not None
        reg_key = r"SOFTWARE\NVIDIA Corporation\GPU Computing Toolkit\CUDA"
        paths = {k.lower().replace("cuda_path_", "").replace("_", "."): v
                 for k, v in os.environ.items()
                 if "cuda_path_v" in k.lower()}
        try:
            with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,  # type:ignore[attr-defined]
                                reg_key) as key:
                for version in self._enum_subkeys(key):
                    vers_tuple = self._tuple_from_string(version[1:])
                    if vers_tuple is not None:
                        retval[vers_tuple] = paths.get(version, "")
        except FileNotFoundError:
            logger.debug("Could not find Windows Registry key '%s'", reg_key)
        return {k: retval[k] for k in sorted(retval)}

def expand_out_dim_graph(
    graph: GraphProto,
    dim_idx: int,
    inplace: bool | None = False,
) -> GraphProto:
    if not isinstance(graph, GraphProto):
        raise TypeError("graph argument is not an ONNX graph")

    if not inplace:
        g = GraphProto()
        g.CopyFrom(graph)
    else:
        g = graph

    orig_out_names = [output.name for output in g.output]

    for n in g.node:
        for i, out in enumerate(n.output):
            if out in orig_out_names:
                n.output[i] = out + f"_collapsed_dim_{dim_idx}"
        for i, inp in enumerate(n.input):
            if inp in orig_out_names:
                n.input[i] = inp + f"_collapsed_dim_{dim_idx}"

    expand_dim_k = g.name + "_expand_out_dim_idx"
    g.node.append(
        helper.make_node(
            "Constant",
            inputs=[],
            outputs=[expand_dim_k],
            name=f"{expand_dim_k}-constant",
            value=helper.make_tensor(
                name=f"{expand_dim_k}-value",
                data_type=TensorProto.INT64,
                dims=[
                    1,
                ],
                vals=[
                    dim_idx,
                ],
            ),
        )
    )

    for _ in range(len(g.output)):
        o = g.output.pop(0)
        prev_output = o.name + f"_collapsed_dim_{dim_idx}"
        g.node.append(
            helper.make_node(
                "Unsqueeze",
                inputs=[prev_output, expand_dim_k],
                outputs=[o.name],
                name=f"unsqueeze-{o.name}",
            )
        )
        new_shape = [d.dim_value for d in o.type.tensor_type.shape.dim]
        new_shape.insert(dim_idx, 1)
        g.output.append(
            helper.make_tensor_value_info(
                o.name, o.type.tensor_type.elem_type, new_shape
            )
        )
    return g

def normalize_kwargs(kw, alias_mapping=None):
    from matplotlib.artist import Artist

    # deal with default value of alias_mapping
    if (isinstance(alias_mapping, type) and issubclass(alias_mapping, Artist)
          or isinstance(alias_mapping, Artist)):
        alias_to_prop = getattr(alias_mapping, "_alias_to_prop", {})
    else:
        if alias_mapping is None:
            alias_mapping = {}
        _api.warn_deprecated("3.11", message=(
            "Passing a dict or None as alias_mapping to normalize_kwargs is "
            "deprecated since %(since)s and support will be removed "
            "%(removal)s; pass an Artist instance or type instead."))
        # Convert old format to new format.
        alias_to_prop = {alias: prop for prop, aliases in alias_mapping.items()
                         for alias in aliases}

    if kw is None:
        return {}

    canonicalized = {alias_to_prop.get(k, k): v for k, v in kw.items()}
    if len(canonicalized) == len(kw):
        return canonicalized

    canonical_to_seen = {}
    for k in kw:
        canonical = alias_to_prop.get(k, k)
        if canonical in canonical_to_seen:
            raise TypeError(f"Got both {canonical_to_seen[canonical]!r} and "
                            f"{k!r}, which are aliases of one another")
        canonical_to_seen[canonical] = k

def to_arrow(
        self,
        validation_reference=None,
        timeout: Optional[int] = None,
    ) -> pa.Table:
        if self._result_arrow is None:
            if self.on_demand_feature_views:
                # Use parent implementation for ODFV processing
                self._result_arrow = super().to_arrow(
                    validation_reference=validation_reference, timeout=timeout
                )
            else:
                # Direct conversion from Ray Dataset
                self._ensure_executed()
                assert self._result_dataset is not None, (
                    "Dataset should not be None after execution"
                )
                self._result_arrow = self._result_dataset.to_pandas().to_arrow()

        # Handle validation if provided
        if validation_reference:
            try:
                df = self._result_arrow.to_pandas()
                validation_result = validation_reference.profile.validate(df)
                if not validation_result.is_success:
                    raise ValidationFailed(validation_result)
            except ImportError:
                logger.warning("DQM profiler not available, skipping validation")
            except Exception as e:
                logger.error(f"Validation failed: {e}")
                raise ValueError(f"Data validation failed: {e}")

        return self._result_arrow

def publish_attention_max_logits(
    query: torch.Tensor,
    key: torch.Tensor,
    attn_mask: Optional[torch.Tensor],
    q_param: Optional[torch.nn.Parameter],
    k_param: Optional[torch.nn.Parameter],
) -> None:
    q_name = AttentionBackendController.lookup_param_name(q_param) if q_param is not None else ""
    k_name = AttentionBackendController.lookup_param_name(k_param) if k_param is not None else ""
    if not q_name and not k_name:
        return

    q_norm = _as_bhsd(query)
    k_norm = _as_bhsd(key)
    if q_norm is None or k_norm is None:
        return

    max_per_head = _compute_max_logits(q_norm, k_norm, attn_mask)
    if max_per_head is None:
        return

    payload: Dict[str, torch.Tensor] = {}
    if q_name:
        payload[q_name] = max_per_head
    if k_name:
        payload[k_name] = max_per_head

    if payload:
        AttentionBackendController.publish_attention_max_logits(payload)

def map_blender_tree(
    context: bpy.types.Context, callback: Callable[[ObjectRef], Any]
) -> Sequence[Any]:
  # Collect all nodes to explore - objects and bones alike
  assert context.scene is not None
  to_explore = [ObjectRef.new_object(o) for o in context.scene.objects]
  armatures = [o for o in context.scene.objects if o.type == 'ARMATURE']
  for armature in armatures:
    for bone in armature.data.bones:
      to_explore.append(ObjectRef.new_bone(armature, bone))

  explored = set()
  explored.add(NoneRef)
  result = []

  while to_explore:
    obj_ref: ObjectRef = to_explore[0]
    to_explore = to_explore[1:]

    if obj_ref.parent in explored:
      explored.add(obj_ref)
      result.append(callback(obj_ref))
    else:
      to_explore.append(obj_ref)

  return result

def create_from_columns(self, columns, relevant_keys, get_selected):
        var_dict = {}
        for atr_type in self.atr_types:
            container = {}
            for table_key in relevant_keys:
                table = self.data[table_key].table
                if atr_type == 'attributes':
                    if get_selected:
                        atrs = list(compress(table.domain.attributes,
                                             [c.name in columns for c in table.domain.attributes]))
                    else:
                        atrs = getattr(table.domain, atr_type)
                else:
                    atrs = getattr(table.domain, atr_type)
                merge_vars = self.curry_merge(table_key, atr_type)
                container = reduce(merge_vars, atrs, container)
            var_dict[atr_type] = container

        if get_selected:
            annotated = self.extract_columnwise(var_dict, None)
        else:
            annotated = self.extract_columnwise(var_dict, columns)

        return annotated

def coerce_scitype(
    obj,
    to_scitype,
    from_scitype=None,
    clone_obj=True,
    raise_on_unknown=False,
    raise_on_mismatch=False,
    msg="Error in object scitype check.",
):
    from sktime.base._base import _safe_clone
    from sktime.registry._scitype import scitype
    from sktime.utils.sklearn import is_sklearn_estimator, sklearn_scitype

    if isinstance(from_scitype, str):
        from_scitype = [from_scitype]
    if isinstance(from_scitype, list) and len(from_scitype) == 0:
        from_scitype = None
    # from_scitype is now a list or None

    # we need to detect the scitype if it is not provided as an assumption
    need_detect = from_scitype is None or len(from_scitype) >= 2 or raise_on_mismatch
    if need_detect:
        if is_sklearn_estimator(obj):
            detected_scitype = f"{sklearn_scitype(obj)}_tabular"
        else:
            detected_scitype = scitype(
                obj, force_single_scitype=True, raise_on_unknown=raise_on_unknown
            )

    # case 1: detected scitype is not assumed scitype
    mismatch_raise = (
        need_detect
        and from_scitype is not None
        and detected_scitype not in from_scitype
    )

    if mismatch_raise:
        # if raise_on_mismatch, raise an error
        if raise_on_mismatch:
            raise TypeError(
                f"{msg} Expected object scitype {from_scitype}, "
                f"but found {detected_scitype}."
            )
        # otherwise, return the object unmodified
        else:
            return obj

    if from_scitype is None or len(from_scitype) >= 2:
        from_scitype = detected_scitype
    else:
        from_scitype = from_scitype[0]

    if clone_obj:
        obj = _safe_clone(obj)

    if (from_scitype, to_scitype) not in _coerce_register:
        return obj

    if isinstance(from_scitype, list) and detected_scitype not in from_scitype:
        return obj

    # now we know that we have a coercion function in the register
    coerce_func = _coerce_register[(from_scitype, to_scitype)]

    coerced_obj = coerce_func(obj)
    return coerced_obj

def write_dig_points(fid, dig, block=False, coord_frame=None, *, ch_names=None):
    if dig is not None:
        data_size = 5 * 4
        if block:
            start_block(fid, FIFF.FIFFB_ISOTRAK)
        if coord_frame is not None:
            write_int(fid, FIFF.FIFF_MNE_COORD_FRAME, coord_frame)
        for d in dig:
            fid.write(np.array(FIFF.FIFF_DIG_POINT, ">i4").tobytes())
            fid.write(np.array(FIFF.FIFFT_DIG_POINT_STRUCT, ">i4").tobytes())
            fid.write(np.array(data_size, dtype=">i4").tobytes())
            fid.write(np.array(FIFF.FIFFV_NEXT_SEQ, ">i4").tobytes())
            #   Start writing fiffDigPointRec
            fid.write(np.array(d["kind"], ">i4").tobytes())
            fid.write(np.array(d["ident"], ">i4").tobytes())
            fid.write(np.array(d["r"][:3], ">f4").tobytes())
        if ch_names is not None:
            write_name_list_sanitized(
                fid, FIFF.FIFF_MNE_CH_NAME_LIST, ch_names, "ch_names"
            )
        if block:
            end_block(fid, FIFF.FIFFB_ISOTRAK)

def get_installed_pkgs_detail() -> Dict[str, Union[Tuple[str, str], Dict[str, Tuple[str, str]]]]:
    mapping = dict()

    for path in sys.path:
        if os.path.isdir(path) and path.rstrip("/").endswith(("site-packages", "dist-packages")):
            new_mapping = _search_path(path)
            # BUGFIX:
            # override with previous, just like python resolves imports, the first match is the one used.
            # unlike the original implementation, where the last one is used.
            new_mapping.update(mapping)
            mapping = new_mapping

    # HACK: prefer tensorflow_gpu over tensorflow
    if "tensorflow_gpu" in mapping:
        mapping["tensorflow"] = mapping["tensorflow_gpu"]

    # HACK: prefer tensorflow_macos over tensorflow
    if "tensorflow_macos" in mapping:
        p = mapping.pop("tensorflow_macos", None)
        if p and isinstance(p, (tuple, list)) and len(p) == 2:
            mapping["tensorflow"] = ("tensorflow", p[1])

    return mapping

def prepare_weights(
        self,
        weights: Any,
        model_id: str,
        strategy: WeightStrategy,
        context: Any = None,
    ) -> Any:
        # Default implementation: extract from model or pass through
        if weights is None and context is not None:
            # Try to resolve and extract from model in context
            try:
                model = _resolve_model(context, model_id)
                return strategy.extract_weights(model)
            except (AttributeError, KeyError):
                pass
            # Try fallback policy
            if model_id == "policy" and hasattr(context, "_fallback_policy"):
                if context._fallback_policy is not None:
                    return strategy.extract_weights(context._fallback_policy)
            return None

        if isinstance(weights, nn.Module):
            return strategy.extract_weights(weights)
        elif isinstance(weights, str):
            # String reference to model
            if context is not None:
                model = _resolve_model(context, weights)
                return strategy.extract_weights(model)
            raise ValueError(
                f"Cannot resolve string reference '{weights}' without context"
            )
        else:
            # Already extracted weights (TensorDict, dict, etc.)
            return weights

def after_report(self, run_context, metrics: list[dict], checkpoint=None) -> None:
        for result in metrics:
            progress_bar_opts = result.get("progress_bar")
            if not progress_bar_opts:
                continue
            # Skip commands received by non-coordinators
            if not progress_bar_opts["is_coordinator"]:
                continue
            _id = progress_bar_opts["id"]
            action = progress_bar_opts.get("action")
            if action == "create":
                progress_bar_config = progress_bar_opts.get("config")
                self.progess_bars[_id] = tqdm.tqdm(**progress_bar_config)
            elif action == "close":
                if _id in self.progess_bars:
                    self.progess_bars[_id].close()
            elif action == "update":
                update_by = progress_bar_opts.get("update_by", 1)
                if _id in self.progess_bars:
                    self.progess_bars[_id].update(update_by)

def current_platform(cls) -> Platform:
        import platform

        if platform.system().lower().startswith("linux"):
            # linux
            if platform.machine().lower().startswith("aarch64"):
                return Platform.LINUX_AARCH64
            elif platform.machine().lower().startswith("x86_64"):
                return Platform.LINUX_X86_64

        elif platform.system().lower().startswith("windows"):
            # Windows...
            if platform.machine().lower().startswith("amd64"):
                return Platform.WIN_X86_64

        return Platform.UNKNOWN

def available_actions(self, obs):
    available_actions = set()
    hide_specific_actions = self._agent_interface_format.hide_specific_actions
    for i, func in actions.FUNCTIONS_AVAILABLE.items():
      if func.avail_fn(obs):
        available_actions.add(i)
    for a in obs.abilities:
      if a.ability_id not in actions.ABILITY_IDS:
        logging.warning("Unknown ability %s seen as available.", a.ability_id)
        continue
      found_applicable = False
      for func in actions.ABILITY_IDS[a.ability_id]:
        if func.function_type in actions.POINT_REQUIRED_FUNCS[a.requires_point]:
          if func.general_id == 0 or not hide_specific_actions:
            available_actions.add(func.id)
            found_applicable = True
          if func.general_id != 0:  # Always offer generic actions.
            for general_func in actions.ABILITY_IDS[func.general_id]:
              if general_func.function_type is func.function_type:
                # Only the right type. Don't want to expose the general action
                # to minimap if only the screen version is available.
                available_actions.add(general_func.id)
                found_applicable = True
                break
      if not found_applicable:
        raise ValueError("Failed to find applicable action for {}".format(a))
    return list(available_actions)

def prepare_input_data(self, input_data, name="", category_map=None):
        print ("-"*40 + " Preparing %s" % name)
        X = input_data[self.continuous_columns].values.astype(np.float32)
        Y = input_data[self.label_column].values.astype(np.float32)
        Y = Y.reshape([-1, 1])
        if self.verbose:
            print ("  Y shape=%s, X shape=%s" % (Y.shape, X.shape))

        X_dict = {"wide_X": X}

        if 'deep' in self.model_type:
            # map categorical value strings to integers
            td = input_data
            if category_map is None:
                category_map = {}
                for cc in self.categorical_columns:
                    if not cc in td.columns:
                        continue
                    cc_values = sorted(td[cc].unique())
                    cc_max = 1+len(cc_values)
                    cc_map = dict(zip(cc_values, range(1, cc_max)))	# start from 1 to avoid 0:0 mapping (save 0 for missing)
                    if self.verbose:
                        print ("  category %s max=%s,  map=%s" % (cc, cc_max, cc_map))
                    category_map[cc] = cc_map

            td = td.replace(category_map)

            # bin ages (cuts off extreme values)
            age_bins = [ 0, 12, 18, 25, 30, 35, 40, 45, 50, 55, 60, 65, 80, 65535 ]
            td['age_binned'] = pd.cut(td['age'], age_bins, labels=False)
            td = td.replace({'age_binned': {np.nan: 0}})
            print ("  %d age bins: age bins = %s" % (len(age_bins), age_bins))

            X_dict.update({ ("%s_in" % cc): td[cc].values.astype(np.int32).reshape([-1, 1]) for cc in self.categorical_columns})

        Y_dict = {"Y": Y}
        if self.verbose:
            print ("-"*40)
        return X_dict, Y_dict, category_map

def yield_containers(root: dict | list) -> Iterator[dict]:
    if isinstance(root, dict):
        for k, v in root.items():
            if k == "containers":
                if isinstance(v, list):
                    yield from v
            elif isinstance(v, (dict, list)):
                yield from yield_containers(v)
    elif isinstance(root, list):
        for item in root:
            yield from yield_containers(item)

def apply_proj(self, verbose=None):
        from ..epochs import BaseEpochs
        from ..evoked import Evoked
        from ..io import BaseRaw

        if self.info["projs"] is None or len(self.info["projs"]) == 0:
            logger.info(
                "No projector specified for this dataset. "
                "Please consider the method self.add_proj."
            )
            return self

        # Exit delayed mode if you apply proj
        if isinstance(self, BaseEpochs) and self._do_delayed_proj:
            logger.info("Leaving delayed SSP mode.")
            self._do_delayed_proj = False

        if all(p["active"] for p in self.info["projs"]):
            logger.info(
                "Projections have already been applied. Setting proj attribute to True."
            )
            return self

        _projector, info = setup_proj(
            deepcopy(self.info), add_eeg_ref=False, activate=True
        )
        # let's not raise a RuntimeError here, otherwise interactive plotting
        if _projector is None:  # won't be fun.
            logger.info("The projections don't apply to these data. Doing nothing.")
            return self
        self._projector, self.info = _projector, info
        if isinstance(self, BaseRaw | Evoked):
            if self.preload:
                self._data = np.dot(self._projector, self._data)
        else:  # BaseEpochs
            if self.preload:
                for ii, e in enumerate(self._data):
                    self._data[ii] = self._project_epoch(e)
            else:
                self.load_data()  # will automatically apply
        logger.info("SSP projectors applied...")
        return self

def update_envs(
            self, envs: Union[None, List[Tuple[str, str]],
                              Dict[str, str]]) -> 'Task':
        if envs is None:
            envs = {}
        if isinstance(envs, (list, tuple)):
            keys = set(env[0] for env in envs)
            if len(keys) != len(envs):
                with ux_utils.print_exception_no_traceback():
                    raise ValueError('Duplicate env keys provided.')
            envs = dict(envs)
        if isinstance(envs, dict):
            for key in envs:
                if not isinstance(key, str):
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError('Env keys must be strings.')
                if not common_utils.is_valid_env_var(key):
                    with ux_utils.print_exception_no_traceback():
                        raise ValueError(f'Invalid env key: {key}')
        else:
            with ux_utils.print_exception_no_traceback():
                raise ValueError(
                    'envs must be List[Tuple[str, str]] or Dict[str, str]: '
                    f'{envs}')
        self._envs.update(envs)
        # If the update_envs() is called after set_resources(), we need to
        # manually update docker login config in task resources, in case the
        # docker login envs are newly added.
        if _check_docker_login_config(self._envs, self._secrets):
            self.resources = _with_docker_login_config(self.resources,
                                                       self._envs,
                                                       self._secrets)
        self.resources = _with_docker_username_for_runpod(
            self.resources, self._envs, self._secrets)
        return self

def digraph(
        self,
        inputs,
        rel=lambda s: s.hypernyms(),
        pos=None,
        maxdepth=-1,
        shapes=None,
        attr=None,
        verbose=False,
    ):
        from nltk.util import edge_closure, edges2dot

        synsets = set()
        edges = set()
        if not shapes:
            shapes = dict()
        if not attr:
            attr = dict()

        def add_lemma(lem):
            ss = lem.synset()
            synsets.add(ss)
            edges.add((lem, ss))

        for node in inputs:
            typ = type(node)
            if typ == Synset:
                synsets.add(node)
            elif typ == Lemma:
                add_lemma(node)
            elif typ == str:
                for lemma in self.lemmas(node, pos):
                    add_lemma(lemma)

        for ss in synsets:
            edges = edges.union(edge_closure(ss, rel, maxdepth, verbose))
        dot_string = edges2dot(sorted(list(edges)), shapes=shapes, attr=attr)
        return dot_string

def ic(self, corpus, weight_senses_equally=False, smoothing=1.0):
        counts = FreqDist()
        for ww in corpus.words():
            counts[ww] += 1

        ic = {}
        for pp in POS_LIST:
            ic[pp] = defaultdict(float)

        # Initialize the counts with the smoothing value
        if smoothing > 0.0:
            for pp in POS_LIST:
                ic[pp][0] = smoothing
            for ss in self.all_synsets():
                pos = ss._pos
                if pos == ADJ_SAT:
                    pos = ADJ
                ic[pos][ss._offset] = smoothing

        for ww in counts:
            possible_synsets = self.synsets(ww)
            if len(possible_synsets) == 0:
                continue

            # Distribute weight among possible synsets
            weight = float(counts[ww])
            if not weight_senses_equally:
                weight /= float(len(possible_synsets))

            for ss in possible_synsets:
                pos = ss._pos
                if pos == ADJ_SAT:
                    pos = ADJ
                for level in ss._iter_hypernym_lists():
                    for hh in level:
                        ic[pos][hh._offset] += weight
                # Add the weight to the root
                ic[pos][0] += weight
        return ic

def set_params(self, **params):
        if not params:
            # Simple optimization to gain speed (inspect is slow)
            return self
        valid_params = self.get_params(deep=True)

        nested_params = defaultdict(dict)  # grouped by prefix
        for key, value in params.items():
            key, delim, sub_key = key.partition("__")
            if key not in valid_params:
                local_valid_params = self._get_param_names()
                raise ValueError(
                    f"Invalid parameter {key!r} for estimator {self}. "
                    f"Valid parameters are: {local_valid_params!r}."
                )

            if delim:
                nested_params[key][sub_key] = value
            else:
                setattr(self, key, value)
                valid_params[key] = value

        for key, sub_params in nested_params.items():
            valid_params[key].set_params(**sub_params)

        return self

def only_nodes(self, *node_names: str) -> Pipeline:
        unregistered_nodes = set(node_names) - set(self._nodes_by_name.keys())
        if unregistered_nodes:
            # check if unregistered nodes are available under namespace
            namespaces = []
            for unregistered_node in unregistered_nodes:
                namespaces.extend(
                    [
                        node_name
                        for node_name in self._nodes_by_name.keys()
                        if node_name.endswith(f".{unregistered_node}")
                    ]
                )
            if namespaces:
                raise ValueError(
                    f"Pipeline does not contain nodes named {list(unregistered_nodes)}. "
                    f"Did you mean: {namespaces}?"
                )
            raise ValueError(
                f"Pipeline does not contain nodes named {list(unregistered_nodes)}."
            )

        nodes = [self._nodes_by_name[name] for name in node_names]
        return Pipeline(nodes)

def clean_model_doc_toc(model_doc):
    counts = defaultdict(int)
    for doc in model_doc:
        counts[doc["local"]] += 1
    duplicates = [key for key, value in counts.items() if value > 1]

    new_doc = []
    for duplicate_key in duplicates:
        titles = list(set(doc["title"] for doc in model_doc if doc["local"] == duplicate_key))
        if len(titles) > 1:
            raise ValueError(
                f"{duplicate_key} is present several times in the documentation table of content at "
                "`docs/source/en/_toctree.yml` with different *Title* values. Choose one of those and remove the "
                "others."
            )
        # Only add this once
        new_doc.append({"local": duplicate_key, "title": titles[0]})

    # Add none duplicate-keys
    new_doc.extend([doc for doc in model_doc if counts[doc["local"]] == 1])

    # Sort
    return sorted(new_doc, key=lambda s: s["title"].lower())

def json_to_data(json_string: str, custom_objects: dict[str, Any] | None = None) -> dict[str, Any]:
    if custom_objects is not None and not isinstance(custom_objects, dict):
        raise ValueError("custom_objects argument must be a dict or None")

    json_dict = json.loads(json_string)
    # This will be filled with deserialized data
    return_data = {}
    for data_key, data_item in json_dict.items():
        if custom_objects is not None and data_key in custom_objects.keys():
            # If item is provided in custom_objects, replace
            # the one from JSON with the one in custom_objects
            return_data[data_key] = custom_objects[data_key]
        elif isinstance(data_item, dict) and ":serialized:" in data_item.keys():
            # If item is dictionary with ":serialized:"
            # key, this means it is serialized with cloudpickle.
            serialization = data_item[":serialized:"]
            # Try-except deserialization in case we run into
            # errors. If so, we can tell bit more information to
            # user.
            try:
                base64_object = base64.b64decode(serialization.encode())
                deserialized_object = cloudpickle.loads(base64_object)
            except (RuntimeError, TypeError, AttributeError) as e:
                warnings.warn(
                    f"Could not deserialize object {data_key}. "
                    "Consider using `custom_objects` argument to replace "
                    "this object.\n"
                    f"Exception: {e}"
                )
            else:
                return_data[data_key] = deserialized_object
        else:
            # Read as it is
            return_data[data_key] = data_item
    return return_data

