def discover_methods() -> t.Tuple[t.Dict[str, TrainerConfig], t.Dict[str, str]]:
    methods = {}
    descriptions = {}
    discovered_entry_points = entry_points(group="nerfstudio.method_configs")
    for name in discovered_entry_points.names:
        spec = discovered_entry_points[name].load()
        if not isinstance(spec, MethodSpecification):
            CONSOLE.print(
                f"[bold yellow]Warning: Could not entry point {spec} as it is not an instance of MethodSpecification"
            )
            continue
        spec = t.cast(MethodSpecification, spec)
        methods[spec.config.method_name] = spec.config
        descriptions[spec.config.method_name] = spec.description

    if "NERFSTUDIO_METHOD_CONFIGS" in os.environ:
        try:
            strings = os.environ["NERFSTUDIO_METHOD_CONFIGS"].split(",")
            for definition in strings:
                if not definition:
                    continue
                name, path = definition.split("=")
                CONSOLE.print(f"[bold green]Info: Loading method {name} from environment variable")
                module, config_name = path.split(":")
                method_config = getattr(importlib.import_module(module), config_name)

                # method_config specified as function or class -> instance
                if callable(method_config):
                    method_config = method_config()

                # check for valid instance type
                if not isinstance(method_config, MethodSpecification):
                    raise TypeError("Method is not an instance of MethodSpecification")

                # save to methods
                methods[name] = method_config.config
                descriptions[name] = method_config.description
        except Exception:
            CONSOLE.print_exception()
            CONSOLE.print("[bold red]Error: Could not load methods from environment variable NERFSTUDIO_METHOD_CONFIGS")

    return methods, descriptions

def cached_path(url_or_filename, cache_dir=None):
    if cache_dir is None:
        cache_dir = PYTORCH_PRETRAINED_BERT_CACHE
    if sys.version_info[0] == 3 and isinstance(url_or_filename, Path):
        url_or_filename = str(url_or_filename)
    if sys.version_info[0] == 3 and isinstance(cache_dir, Path):
        cache_dir = str(cache_dir)

    parsed = urlparse(url_or_filename)

    if parsed.scheme in ('http', 'https', 's3'):
        # URL, so get it from the cache (downloading if necessary)
        return get_from_cache(url_or_filename, cache_dir)
    elif os.path.exists(url_or_filename):
        # File, and it exists.
        return url_or_filename
    elif parsed.scheme == '':
        # File, but it doesn't exist.
        raise EnvironmentError('file {} not found'.format(url_or_filename))
    else:
        # Something unknown
        raise ValueError(
            'unable to parse {} as a URL or as a local path'.format(
                url_or_filename))

def transitive_closure(graph, reflexive=False):
    if reflexive:
        base_set = lambda k: {k}
    else:
        base_set = lambda k: set()
    # The graph U_i in the article:
    agenda_graph = {k: graph[k].copy() for k in graph}
    # The graph M_i in the article:
    closure_graph = {k: base_set(k) for k in graph}
    for i in graph:
        agenda = agenda_graph[i]
        closure = closure_graph[i]
        while agenda:
            j = agenda.pop()
            closure.add(j)
            closure |= closure_graph.setdefault(j, base_set(j))
            agenda |= agenda_graph.get(j, base_set(j))
            agenda -= closure
    return closure_graph

def apply_hadamard(op: ops.Hadamard, state, is_state_batched: bool = False, debugger=None, **_):
    n_dim = math.ndim(state)
    state_interface = math.get_interface(state)

    if state_interface == "autograd":
        if n_dim < EINSUM_STATE_WIRECOUNT_PERF_THRESHOLD:
            return apply_operation_einsum(op, state, is_state_batched=is_state_batched)
        return apply_operation_tensordot(op, state, is_state_batched=is_state_batched)

    if (
        n_dim >= 9 and state_interface == "tensorflow"
    ):  # pragma: no cover (TensorFlow tests were disabled during deprecation)
        return apply_operation_tensordot(op, state, is_state_batched=is_state_batched)

    if state_interface == "numpy":
        # H uses direct matrix application since its coefficients are constant;
        # no parameter-dependent logic needed unlike RX/RY/RZ.
        axis = op.wires[0] + is_state_batched
        state_dtype = np.dtype(state.dtype)
        mat = _HADAMARD_CACHE.get(state_dtype)
        if mat is None:
            mat = _HADAMARD_MAT.astype(state_dtype, copy=False)
            _HADAMARD_CACHE[state_dtype] = mat
        return _apply_single_qubit_np(mat, state, axis)

    if n_dim < EINSUM_STATE_WIRECOUNT_PERF_THRESHOLD:
        return apply_operation_einsum(op, state, is_state_batched=is_state_batched)
    return apply_operation_tensordot(op, state, is_state_batched=is_state_batched)

def format_commands(self, ctx, formatter):
        commands = []
        for name in self.list_commands(ctx):
            spec = self._COMMANDS.get(name)
            if spec is None:
                continue
            _mod, _attr, short_help = spec
            commands.append((name, short_help))

        if commands:
            # Match Click's default column width calculation
            limit = formatter.width - 6 - max(len(name) for name, _ in commands)
            rows = []
            for name, help_text in commands:
                rows.append((name, click.utils.make_str(help_text)[:limit] if limit > 0 else ""))
            with formatter.section("Commands"):
                formatter.write_dl(rows)

def initialize_observation_norm_transforms(
    proof_environment: EnvBase,
    num_iter: int = 1000,
    key: str | tuple[str, ...] = None,
):
    if not isinstance(proof_environment.transform, Compose) and not isinstance(
        proof_environment.transform, ObservationNorm
    ):
        return

    if key is None:
        keys = list(proof_environment.base_env.observation_spec.keys(True, True))
        key = keys.pop()
        if len(keys):
            raise RuntimeError(
                f"More than one key exists in the observation_specs: {[key] + keys} were found, "
                "thus initialize_observation_norm_transforms cannot infer which to compute the stats of."
            )

    if isinstance(proof_environment.transform, Compose):
        for transform in proof_environment.transform:
            if isinstance(transform, ObservationNorm) and not transform.initialized:
                transform.init_stats(num_iter=num_iter, key=key)
    elif not proof_environment.transform.initialized:
        proof_environment.transform.init_stats(num_iter=num_iter, key=key)

def validate_benchmarking_config(benchmarking_config: dict[str, Any]) -> None:
    if "experiment_name" not in benchmarking_config and not all(
        "experiment_name" in experiment for experiment in benchmarking_config["experiments"]
    ):
        raise ValueError("You must either specify a global experiment name or an experiment name for each experiment.")
    if "export" not in benchmarking_config:
        raise ValueError("""You must specify export parameters. Example:
            export:
              export_artifacts: true
              export_base_path: s3://benchmarking.us-west-2.ludwig.com/bench/    # include the slash at the end.
        """)
    if "experiments" not in benchmarking_config:
        raise ValueError("You must specify a list of experiments.")
    for experiment in benchmarking_config["experiments"]:
        if "dataset_name" not in experiment:
            raise ValueError("A Ludwig dataset must be specified.")

def save_corpus(fname, corpus, id2word=None, metadata=False):
        if id2word is None:
            logger.info("no word id mapping provided; initializing from corpus")
            id2word = utils.dict_from_corpus(corpus)

        logger.info("storing corpus in List-Of-Words format into %s" % fname)
        truncated = 0
        offsets = []
        with utils.open(fname, 'wb') as fout:
            fout.write(utils.to_utf8('%i\n' % len(corpus)))
            for doc in corpus:
                words = []
                for wordid, value in doc:
                    if abs(int(value) - value) > 1e-6:
                        truncated += 1
                    words.extend([utils.to_unicode(id2word[wordid])] * int(value))
                offsets.append(fout.tell())
                fout.write(utils.to_utf8('%s\n' % ' '.join(words)))

        if truncated:
            logger.warning(
                "List-of-words format can only save vectors with integer elements; "
                "%i float entries were truncated to integer value", truncated
            )
        return offsets

def check_integrity_and_batch(*datasets):
        not_broken = tf.constant(True)
        if "frame_number" in datasets[0]:
          frame_numbers = [dataset["frame_number"][0] for dataset in datasets]

          not_broken = tf.equal(frame_numbers[-1] - frame_numbers[0],
                                num_frames - 1)
          if self.only_keep_videos_from_0th_frame:
            not_broken = tf.logical_and(not_broken, tf.equal(
                frame_numbers[0], 0))
          if self.avoid_overlapping_frames:
            non_overlap = tf.equal(tf.mod(frame_numbers[0], num_frames), 0)
            not_broken = tf.logical_and(not_broken, non_overlap)
        else:
          tf.logging.warning("use_not_breaking_batching is True but "
                             "no frame_number is in the dataset.")

        features = {}
        for key in datasets[0].keys():
          values = [dataset[key] for dataset in datasets]
          batch = tf.stack(values)
          features[key] = batch
        return features, not_broken

def postprocess_update_dict(
    block: Component | BlockContext, update_dict: dict, postprocess: bool = True
):
    from gradio.components import HTML

    value = update_dict.pop("value", components._Keywords.NO_VALUE)

    props = None
    if isinstance(block, HTML):
        sig = inspect.signature(HTML.__init__)
        constructor_params = set(sig.parameters.keys())
        props = {k: v for k, v in update_dict.items() if k not in constructor_params}
    update_dict = {k: getattr(block, k) for k in update_dict if hasattr(block, k)}
    if props:
        update_dict["props"] = props

    if value is not components._Keywords.NO_VALUE:
        if postprocess:
            update_dict["value"] = block.postprocess(value)
            if isinstance(update_dict["value"], (GradioModel, GradioRootModel)):
                update_dict["value"] = update_dict["value"].model_dump()
        else:
            update_dict["value"] = value
    update_dict["__type__"] = "update"
    return update_dict

