        # label = row["label"]
        image_id = idx

        image_info = _get_image_info(image_path)
        if image_info:
            image_entry = {
                "file_name": image_path,
                "height": image_info["height"],
                "width": image_info["width"],
                "id": image_id,
            }
            output_json_dict["images"].append(image_entry)
        else:
            continue

        for roi in rois:
            xmin, ymin, xmax, ymax, class_label = roi
            x, y, w, h = bbox_xyxy_to_xywh([xmin, ymin, xmax, ymax])

            ann = {
                "area": w * h,
                "iscrowd": 0,
                "bbox": [x, y, w, h],
                "category_id": class_label,
                "ignore": 0,
                "segmentation": [],  # This script is not for segmentation
                "image_id": image_id,
                "id": bbox_count,
            }
            bbox_count += 1

            output_json_dict["annotations"].append(ann)

            if class_label not in unique_classes:
                unique_classes[class_label] = len(unique_classes)

    for class_name, id in unique_classes.items():
        output_json_dict["categories"].append({"supercategory": "none", "id": id, "name": class_name})

    if save_path and save_path.endswith(".json"):
        with open(save_path, "w") as fp:
            json.dump(output_json_dict, fp)

    return output_json_dict

def extract_source_metadata(
    workflow_class: Any | None = None,
    agent_class: Any | None = None,
    workflow_args: dict | None = None,
    env_args: dict | None = None,
) -> dict[str, str]:
    source_metadata: dict[str, str] = {}

    def _extract_source(obj: Any, name_key: str, source_key: str, default_name: str) -> None:
        """Extract source code from a class or function."""
        if obj is None:
            return
        try:
            source_metadata[source_key] = inspect.getsource(obj)
            source_metadata[name_key] = obj.__name__
        except Exception:
            source_metadata[name_key] = getattr(obj, "__name__", default_name)
            if source_metadata[name_key] == "<lambda>":
                source_metadata[source_key] = "# Lambda function - source not available"

    # Extract workflow class source
    if workflow_class:
        _extract_source(workflow_class, "workflow_class", "workflow_source", "Workflow")

    # Extract agent class source
    if agent_class:
        _extract_source(agent_class, "agent_class", "agent_source", "Agent")

    # Extract reward function (from workflow_args or env_args)
    reward_fn = None
    if workflow_args:
        reward_fn = workflow_args.get("reward_function")
    if reward_fn is None and env_args:
        reward_fn = env_args.get("reward_fn")
    if reward_fn:
        _extract_source(reward_fn, "reward_fn_name", "reward_fn_source", "reward_fn")

    return source_metadata

def build_model(task: str, model_name: str) -> Any:
    # singleton design pattern
    global cached_models

    if task not in AVAILABLE_MODELS.keys():
        raise UnimplementedError(f"unimplemented task - {task}")

    if "cached_models" not in globals():
        cached_models = {current_task: {} for current_task in AVAILABLE_MODELS.keys()}

    if cached_models[task].get(model_name) is None:
        model = AVAILABLE_MODELS[task].get(model_name)  # type: ignore[literal-required]
        if model:
            cached_models[task][model_name] = model()
        else:
            raise UnimplementedError(f"Invalid model_name passed - {task}/{model_name}")

    return cached_models[task][model_name]

def pad_to_square(
        self,
        images: "torch.Tensor",
        background_color: int | tuple[int, int, int] = 0,
    ) -> "torch.Tensor":
        height, width = images.shape[-2:]
        num_channels = images.shape[1]
        batch_size = images.shape[0]

        if height == width:
            return images

        max_dim = max(height, width)

        # Ensure background_color is the correct shape
        if isinstance(background_color, int):
            background_color = [background_color]
        elif len(background_color) != num_channels:
            raise ValueError(
                f"background_color must have no more than {num_channels} elements to match the number of channels"
            )

        padded_images = torch.zeros(
            (batch_size, num_channels, max_dim, max_dim), dtype=images.dtype, device=images.device
        )
        for i, color in enumerate(background_color):
            padded_images[:, i, :, :] = color
        if width > height:
            start = (max_dim - height) // 2
            padded_images[:, :, start : start + height, :] = images
        else:
            start = (max_dim - width) // 2
            padded_images[:, :, :, start : start + width] = images

        return padded_images

def call(self, x):
        # Currently GraphSAGE & HinSage output a list of two tensors being the embeddings
        # for each of the nodes in the link. However, GCN, GAT & other full-batch methods
        # return a tensor of shape (1, N, 2, M).
        # Detect and support both inputs
        if isinstance(x, (list, tuple)):
            if len(x) != 2:
                raise ValueError("Expecting a list of length 2 for link embedding")
            x0, x1 = x
        elif isinstance(x, tf.Tensor):
            if int(x.shape[self.axis]) != 2:
                raise ValueError(
                    "Expecting a tensor of shape 2 along specified axis for link embedding"
                )
            x0, x1 = tf.unstack(x, axis=self.axis)
        else:
            raise TypeError("Expected a list, tuple, or Tensor as input")

        # Apply different ways to combine the node embeddings to a link embedding.
        if self.method in ["ip", "dot"]:
            out = tf.reduce_sum(x0 * x1, axis=-1, keepdims=True)

        elif self.method == "l1":
            # l1(u,v)_i = |u_i - v_i| - vector of the same size as u,v
            out = tf.abs(x0 - x1)

        elif self.method == "l2":
            # l2(u,v)_i = (u_i - v_i)^2 - vector of the same size as u,v
            out = tf.square(x0 - x1)

        elif self.method in ["mul", "hadamard"]:
            out = tf.multiply(x0, x1)

        elif self.method == "concat":
            out = Concatenate()([x0, x1])

        elif self.method == "avg":
            out = Average()([x0, x1])

        else:
            raise NotImplementedError(
                "{}: the requested method '{}' is not known/not implemented".format(
                    name, edge_embedding_method
                )
            )

        # Apply activation function
        out = self.activation(out)

        return out

def run_source_freshness(
    settings: Any,
    target_path: Path | None = None,
    target: str | None = None,
) -> dict[str, SourceFreshnessResult]:
    output_target = target_path or settings.target_path
    output_path = settings.project_dir / output_target / "sources.json"

    # Remove any pre-existing sources.json so a failed run cannot
    # silently reuse stale data from a previous invocation.
    if output_path.exists():
        output_path.unlink()

    with settings.resolve_profiles_yml() as resolved_profiles_dir:
        args = [
            "source",
            "freshness",
            "--project-dir",
            str(settings.project_dir),
            "--profiles-dir",
            resolved_profiles_dir,
        ]
        args.extend(["--target-path", str(output_target)])
        if target is not None:
            args.extend(["--target", target])

        try:
            dbtRunner().invoke(args)
        except Exception:
            logger.warning(
                "dbt source freshness command raised an exception",
                exc_info=True,
            )
            return {}

    # dbt source freshness returns success=False when sources are stale
    # but still writes sources.json. Only treat it as failure if the
    # output file was not written.
    if not output_path.exists():
        logger.warning(
            "dbt source freshness did not produce %s; "
            "freshness features will be disabled for this run",
            output_path,
        )
        return {}

    try:
        return parse_source_freshness_results(output_path)
    except Exception:
        logger.warning(
            "Failed to parse source freshness results from %s",
            output_path,
            exc_info=True,
        )
        return {}

def get_all_arguments(self) -> Dict[str, Dict[str, Any]]:
        if self._arg_help_cache is not None:
            return self._arg_help_cache

        self._arg_help_cache = {}

        for action in self._parser._actions:
            # Skip help action
            if isinstance(action, argparse._HelpAction):
                continue

            # Get the primary argument name (prefer long form)
            arg_names = action.option_strings
            if not arg_names:
                continue

            # Use the long form (--argument) as the key
            primary_name = None
            for name in arg_names:
                if name.startswith("--"):
                    primary_name = name
                    break

            if not primary_name:
                primary_name = arg_names[0]

            # Extract metadata
            self._arg_help_cache[primary_name] = {
                "names": arg_names,
                "help": action.help or "",
                "type": action.type.__name__ if action.type else "str",
                "default": action.default,
                "choices": action.choices,
                "required": action.required if hasattr(action, "required") else False,
                "dest": action.dest,
                "nargs": action.nargs,
                "const": action.const,
                "metavar": action.metavar,
            }

            # Special handling for store_true/store_false actions
            if isinstance(action, argparse._StoreTrueAction):
                self._arg_help_cache[primary_name]["type"] = "bool"
                self._arg_help_cache[primary_name]["default"] = False
            elif isinstance(action, argparse._StoreFalseAction):
                self._arg_help_cache[primary_name]["type"] = "bool"
                self._arg_help_cache[primary_name]["default"] = True

        return self._arg_help_cache

def fix_wrong_open_stuff_unary(gold_transition, pred_transition, gold_sequence, gold_index, root_labels, model, state):
    if gold_transition == pred_transition:
        return None

    if not isinstance(gold_transition, OpenConstituent):
        return None
    if not isinstance(pred_transition, OpenConstituent):
        return None
    # TODO: Here we could advance past unary transitions while
    # watching for hitting pred_transition.  However, that is an open
    # question... is it better to try to keep such an Open as part of
    # the sequence, or is it better to skip them and attach the inner
    # nodes to the upper level
    stuff_start = gold_index + 1
    if not isinstance(gold_sequence[stuff_start], Shift):
        return None
    stuff_end = advance_past_constituents(gold_sequence, stuff_start)
    if stuff_end is None:
        return None
    # at this point, stuff_end points to the Close which occurred after stuff_2
    # also, stuff_start points to the first transition which makes stuff_2, the Shift
    cur_index = stuff_end + 1
    while isinstance(gold_sequence[cur_index], OpenConstituent):
        if gold_sequence[cur_index] == pred_transition:
            return gold_sequence[:gold_index] + [pred_transition] + gold_sequence[stuff_start:stuff_end] + gold_sequence[cur_index+1:]
        # this was an OpenConstituent, but not the OpenConstituent we guessed
        # maybe there's a unary transition which lets us try again
        if cur_index + 2 < len(gold_sequence) and isinstance(gold_sequence[cur_index + 1], CloseConstituent):
            cur_index = cur_index + 2
        else:
            break

    # oh well, none of this worked
    return None

def stringify_default(default: Any) -> str:
    if isinstance(default, bool):
        # We need to test for bool first as a bool passes isinstance(xxx, (int, float))
        return f"`{default}`"
    elif isinstance(default, enum.Enum):
        # We need to test for enum first as an enum with int values will pass isinstance(xxx, (int, float))
        return f"`{str(default)}`"
    elif isinstance(default, int):
        return str(default)
    elif isinstance(default, float):
        result = str(default)
        return str(round(default, 2)) if len(result) > 6 else result
    elif isinstance(default, str):
        return str(default) if default.isnumeric() else f'`"{default}"`'
    elif isinstance(default, type):
        return f"`{default.__name__}`"
    else:
        return f"`{default}`"

def parse_results(self, metric):
        max_throughput = sys.float_info.min
        best_exp_id = -1
        for exp_id, (exp, err) in self.finished_experiments.items():
            if err:
                logger.info(
                    f"The experiment exp_id = {exp_id}, exp_name = {exp['name']}, did not run successfully with error = {err}, thus a metrics.txt does not exist for it. Check the stderr.log in {exp['result_dir']}"
                )
                continue

            metric_file = exp["ds_config"][AUTOTUNING][AUTOTUNING_METRIC_PATH]

            if os.path.exists(metric_file):
                with open(metric_file, 'r') as f:
                    results = hjson.load(f)
                    curr_throughput = results[metric]
                    if curr_throughput > max_throughput:
                        max_throughput = curr_throughput
                        best_exp_id = exp_id
                    exp['results'] = results

        if best_exp_id != -1:
            best_exp, _ = self.finished_experiments[best_exp_id]
            return best_exp, max_throughput

        return exp, None

def weights(self):
        # Return only `Variables` directly owned by layers and sub-layers.
        # Also deduplicate them.
        weights = []
        seen_ids = set()
        for w in self._trainable_variables + self._non_trainable_variables:
            if id(w) not in seen_ids:
                weights.append(w)
                seen_ids.add(id(w))
        for layer in self._layers:
            for w in layer.weights:
                if id(w) not in seen_ids:
                    weights.append(w)
                    seen_ids.add(id(w))
        return weights

def guess_lexer(_text, **options):
    # try to get a vim modeline first
    ft = get_filetype_from_buffer(_text)

    if ft is not None:
        try:
            return get_lexer_by_name(ft, **options)
        except ClassNotFound:
            pass

    best_lexer = [0.0, None]
    for lexer in _iter_lexerclasses():
        rv = lexer.analyse_text(_text)
        if rv == 1.0:
            return lexer(**options)
        if rv > best_lexer[0]:
            best_lexer[:] = (rv, lexer)
    if not best_lexer[0] or best_lexer[1] is None:
        raise ClassNotFound('no lexer matching the text found')
    return best_lexer[1](**options)

def download_from_url(url: str, root: str = None, hash_prefix: str = None):
    if root is None:
        root = os.path.expanduser('~/.towhee/checkpoints')
    os.makedirs(root, exist_ok=True)
    with request.urlopen(url) as r:
        d = r.headers['content-disposition']
    if d:
        filename = d.split('=')[-1].split(' ')[-1]
        if filename.startswith(('UTF-', 'utf-')):
            filename = filename[5:]
        for char in ['\'', '"', '\\', ',']:
            filename = filename.replace(char, '')
    else:
        filename = os.path.basename(url)

    if hash_prefix == 'default':
        hash_prefix = url.split('/')[-2]

    # Check target file
    download_target = os.path.join(root, filename)

    if os.path.exists(download_target) and not os.path.isfile(download_target):
        raise RuntimeError(f'{download_target} exists and is not a regular file.')

    if os.path.isfile(download_target):
        if hash_prefix:
            if checksum(download_target, hash_prefix):
                warnings.warn(f'{download_target} exists and passed checksum. Using the existed one.')
                return download_target
            else:
                warnings.warn(f'{download_target} exists, '
                              f'but the checksum does not match; re-downloading file.')
        else:
            warnings.warn(f'{download_target} exists and skipped checksum. Using the existed one.')
            return download_target

    # Download from url
    with request.urlopen(url) as source, open(download_target, 'wb') as output:
        with tqdm(total=int(source.info().get('Content-Length')),
                  ncols=80, unit='iB', unit_scale=True, unit_divisor=1024) as loop:
            while True:
                buffer = source.read(8192)
                if not buffer:
                    break

                output.write(buffer)
                loop.update(len(buffer))

    # Checksum if hash_prefix is not None
    if hash_prefix:
        assert checksum(download_target, hash_prefix), \
            'Model has been downloaded but the hash checksum does not not match.'

    return download_target

def from_json(cls, path):
        model = json.load(open(path, 'r'))
        model = cls._byte2string(model)

        # Convert the lists back to arrays
        for param_type in ['model_params', 'hyper_params']:
            for k in model[param_type].keys():
                param = model[param_type][k]
                if type(param) is list:
                    try:
                        arr = np.array(param)
                        if arr.dtype == object:
                            # Then maybe it was rather a list of arrays
                            # This is very hacky...
                            arr = [np.array(p) for p in param]
                    except ValueError:
                        arr = [np.array(p) for p in param]
                    model[param_type][k] = arr

        return cls._organize_model(cls, model)

def raw_preprocess(raw, path_to_raw):
    module = raw.get("_module")
    preprocessed = {}

    if module:
        if raw["_module"] == "{{here}}":
            if path_to_raw is not None:
                preprocessed["_module"] = path_to_raw.parent
            else:
                raise ValueError(
                    "_module cannot be {{here}} if " "not loaded from a file"
                )
        else:
            # check if it's a filesystem path
            as_path = Path(module)

            if as_path.exists():
                if as_path.is_file():
                    raise ValueError(
                        'Could not resolve _module "{}", '
                        "expected a module or a directory but got a "
                        "file".format(module)
                    )
                else:
                    path_to_module = as_path

            # must be a dotted path
            else:
                module_spec = importlib.util.find_spec(module)

                # package does not exist
                if module_spec is None:
                    raise ValueError(
                        'Could not resolve _module "{}", '
                        "it is not a valid module "
                        "nor a directory".format(module)
                    )
                else:
                    path_to_module = Path(module_spec.origin).parent

            preprocessed["_module"] = path_to_module

    return preprocessed

def is_intensity_only(self, strict: bool = True) -> bool:
        for arg in self.children():
            if isinstance(arg, ImageSequential) and not arg.is_intensity_only(strict):
                return False
            elif isinstance(arg, ImageSequential):
                pass
            elif isinstance(arg, K.IntensityAugmentationBase2D):
                pass
            elif strict:
                # disallow non-registered ops if in strict mode
                # TODO: add an ops register module
                return False
        return True

def finalize(
        self, model: _Optional[_torch.nn.Module] = None, inplace: bool = False
    ) -> _torch.nn.Module:
        if not self._is_prepared:
            _logger.warning(
                "Model has not been prepared for QAT. This API call "
                "will be a no-op. prepare method must be called before "
                "a call to the finalize method."
            )
            return self._model
        if model is None:
            model = self._model
        if not inplace:
            model = _copy.deepcopy(model)
        model.eval()
        convert_custom_config = _ConvertCustomConfig().set_preserved_attributes(
            self._config.preserved_attributes
        )
        finalized_model = _convert_to_reference_fx(
            model,
            convert_custom_config=convert_custom_config,
            qconfig_mapping=self._qconfig_mapping,
            backend_config=_get_backend_config(),
        )

        # PyTorch fx QAT does not properly handle the clipping of < 8-bit weights during
        # finalization so have to apply the utility method below after finalization to clip
        # the de-quantized weights.
        _pre_apply_weight_quant(finalized_model)

        _register_metadata_version(finalized_model)
        for name, submodule in finalized_model.named_modules(remove_duplicate=True):
            if hasattr(submodule, "weight_scale"):
                _register_compression_metadata(submodule)

        if model is None:
            self._model = finalized_model
        return finalized_model

def filter_trajectories_by_reward(filter_option: str):
        if filter_option == "All Trajectories":
            return all_trajs
        elif filter_option == "Zero Reward (Failed)":
            return [t for t in all_trajs if float(t.reward) == 0.0]
        elif filter_option == "Nonzero Reward (Partial/Full Success)":
            return [t for t in all_trajs if float(t.reward) > 0.0]
        elif filter_option == "Perfect Score (Reward = 1)":
            return [t for t in all_trajs if float(t.reward) == 1.0]
        else:
            return all_trajs

async def get_model_flavours_html(model_family: str, current_value: str = "", _user: User = Depends(get_current_user)):
    if model_family == "loading":
        return """
        <option value="">Loading flavours...</option>
        """

    if model_families is not _MODEL_FAMILY_SENTINEL and model_family not in model_families:  # type: ignore[operator]
        return """
        <option value="">Select a valid model family</option>
        """

    try:
        if model_families is not _MODEL_FAMILY_SENTINEL:
            result = {"flavours": list(get_model_flavour_choices(model_family))}
        else:
            result = MODELS_SERVICE.get_model_flavours(model_family)
    except ModelServiceError as exc:
        if exc.status_code == 404:
            return """
            <option value="">Select a model family first</option>
            """
        return """
        <option value="">Error loading flavours</option>
        """

    flavours = result.get("flavours", [])
    if not flavours:
        return """
        <option value="">No flavours available</option>
        """

    options = ['<option value="">Default</option>']
    for flavour in flavours:
        selected = "selected" if flavour == current_value else ""
        options.append(f'<option value="{flavour}" {selected}>{flavour}</option>')

    return "\n".join(options)

