def render_body(
        self,
        *,
        include_init_island: bool = True,
        max_width: str | None = None,
        margin: str | None = None,
        style: str | None = None,
    ) -> str:

        rendered_stubs = []
        for stub in self._stubs:
            rendered_stubs.append(stub.render())

        if include_init_island:
            init_island = self.render_init_island()
            rendered_stubs = [init_island] + rendered_stubs

        body = "\n".join(rendered_stubs)

        if margin is None:
            margin = "auto"
        if max_width is None:
            width = self._config.width
            if width == "compact" or width == "normal":
                max_width = "740px"
            elif width == "medium":
                max_width = "1110px"
            else:
                max_width = "none"

        if style is None:
            style = f"margin: {margin}; max-width: {max_width};"

        return dedent(
            f"""
                <div style="{style}">
                  {body}
                </div>
                """
        ).strip()

def resource_partition(
    gm: torch.fx.GraphModule,
    cpu_memory_budget: int,
) -> torch.fx.GraphModule:

    # Construct
    for name, _ in gm.named_children():
        submodule = getattr(gm, name)
        if (
            not isinstance(submodule, torch.fx.graph_module.GraphModule)
            or "_run_on_acc" not in name
        ):
            continue
        partitioner = ResourcePartitioner(
            submodule,
            submodule_name=name,
            cpu_memory_budget=cpu_memory_budget,
        )

        partitioned_graph = partitioner.partition_graph()
        setattr(gm, name, partitioned_graph)

    for name, module in list(gm.named_children()):
        split = False
        if "_run_on_acc" in name:
            for subname, submodule in module.named_children():
                if "resource_split" in subname:
                    split = True
                    setattr(gm, subname, submodule)
            if split:
                _inline_module(gm, name)
                delattr(gm, name)

    gm.recompile()
    return gm

def inspect_wandb_transaction_log(wandb_file: str, pause: bool = False) -> None:
    def _robust_scan(_ds: datastore.DataStore):
        """Attempt to scan data, handling incomplete files."""
        try:
            return _ds.scan_data()
        except AssertionError as e:
            if _ds.in_last_block():
                wandb.termwarn(
                    f".wandb file is incomplete ({e}), be sure to sync this run "
                    "again once it's finished"
                )
                return None
            else:
                raise

    ds = datastore.DataStore()
    try:
        ds.open_for_scan(wandb_file)
    except AssertionError as e:
        print(f".wandb file is empty ({e}), skipping: {wandb_file}")
        return

    while True:
        data = _robust_scan(ds)
        if data is None:
            break
        pb = wandb_internal_pb2.Record()
        pb.ParseFromString(data)
        record_type = pb.WhichOneof("record_type")
        print(f"RECORD TYPE: {record_type}")
        print(pb)
        print()
        if pause:
            input()

def decode_example(
        self,
        value: Union[str, Example],
        token_per_repo_id: Optional[dict[str, Union[bool, str]]] = None,
    ) -> "VideoDecoder":
        if not self.decode:
            raise RuntimeError("Decoding is disabled for this feature. Please use Video(decode=True) instead.")

        if config.TORCHCODEC_AVAILABLE:
            from torchcodec.decoders import VideoDecoder

        else:
            raise ImportError("To support decoding videos, please install 'torchcodec'.")

        if token_per_repo_id is None:
            token_per_repo_id = {}

        if isinstance(value, str):
            path, bytes_ = value, None
        else:
            path, bytes_ = value["path"], value["bytes"]

        if bytes_ is None:
            if path is None:
                raise ValueError(f"A video should have one of 'path' or 'bytes' but both are None in {value}.")
            elif is_local_path(path):
                video = VideoDecoder(
                    path,
                    stream_index=self.stream_index,
                    dimension_order=self.dimension_order,
                    num_ffmpeg_threads=self.num_ffmpeg_threads,
                    device=self.device,
                    seek_mode=self.seek_mode,
                )
            else:
                video = hf_video_reader(
                    path,
                    token_per_repo_id=token_per_repo_id,
                    dimension_order=self.dimension_order,
                    num_ffmpeg_threads=self.num_ffmpeg_threads,
                    device=self.device,
                    seek_mode=self.seek_mode,
                )
        else:
            video = VideoDecoder(
                bytes_,
                stream_index=self.stream_index,
                dimension_order=self.dimension_order,
                num_ffmpeg_threads=self.num_ffmpeg_threads,
                device=self.device,
                seek_mode=self.seek_mode,
            )
        video._hf_encoded = {"path": path, "bytes": bytes_}
        video.metadata.path = path
        return video

def load(self) -> kmodels.Model:
        logger.debug("Loading model: %s", self.filename)
        if self._is_predict and not self.model_exists:
            logger.error("Model could not be found in folder '%s'. Exiting", self._model_dir)
            sys.exit(1)

        try:
            model = kmodels.load_model(self.filename, compile=False)
        except RuntimeError as err:
            if "unable to get link info" in str(err).lower():
                msg = (f"Unable to load the model from '{self.filename}'. This may be a "
                       "temporary error but most likely means that your model has corrupted.\n"
                       "You can try to load the model again but if the problem persists you "
                       "should use the Restore Tool to restore your model from backup.\n"
                       f"Original error: {str(err)}")
                raise FaceswapError(msg) from err
            raise err
        except KeyError as err:
            if "unable to open object" in str(err).lower():
                msg = (f"Unable to load the model from '{self.filename}'. This may be a "
                       "temporary error but most likely means that your model has corrupted.\n"
                       "You can try to load the model again but if the problem persists you "
                       "should use the Restore Tool to restore your model from backup.\n"
                       f"Original error: {str(err)}")
                raise FaceswapError(msg) from err
            if 'parameter name can\\\'t contain "."' in str(err).lower():
                PatchKerasConfig(self.filename)()
                return self.load()
            raise err
        except TypeError as err:
            if any(x in str(err) for x in ("Could not locate class 'Conv2D'",
                                           "Could not locate class 'DepthwiseConv2D'")):
                PatchKerasConfig(self.filename)()
                return self.load()
            raise err

        logger.info("Loaded model from disk: '%s'", self.filename)
        return model  # pyright:ignore[reportReturnType]

def run_agents_concurrently(
    agents: List["AgentType"],
    task: str,
    img: Optional[str] = None,
    max_workers: Optional[int] = None,
    return_agent_output_dict: bool = False,
) -> Any:
    try:
        if max_workers is None:
            num_cores = os.cpu_count()
            max_workers = int(num_cores * 0.95) if num_cores else 1

        futures = []
        agent_id_map = {}

        with concurrent.futures.ThreadPoolExecutor(
            max_workers=max_workers
        ) as executor:
            for agent in agents:
                agent_kwargs = {}
                if task is not None:
                    agent_kwargs["task"] = task
                if img is not None:
                    agent_kwargs["img"] = img
                future = executor.submit(agent.run, **agent_kwargs)
                futures.append(future)
                agent_id_map[future] = agent

            if return_agent_output_dict:
                # Use agent name as key, preserve input order
                output_dict = {}
                for agent, future in zip(agents, futures):
                    try:
                        result = future.result()
                    except Exception as e:
                        result = e
                    # Prefer .agent_name or .name, fallback to str(agent)
                    name = (
                        getattr(agent, "agent_name", None)
                        or getattr(agent, "name", None)
                        or str(agent)
                    )
                    output_dict[name] = result
                return output_dict
            else:
                results = []
                for future in concurrent.futures.as_completed(
                    futures
                ):
                    try:
                        result = future.result()
                        results.append(result)
                    except Exception as e:
                        results.append(e)
                return results

    except Exception as e:
        logger.error(
            f"Error running_agents_concurrently: {e} Traceback: {e.__traceback__}"
        )
        raise e

def infer_categorical_features(
    X: np.ndarray,
    *,
    min_samples_for_inference: int,
    max_unique_for_category: int,
    min_unique_for_numerical: int,
    provided: Sequence[int] | None = None,
) -> list[int]:
    # We presume everything is numerical and go from there
    maybe_categoricals = () if provided is None else provided
    large_enough_x_to_infer_categorical = X.shape[0] > min_samples_for_inference
    indices = []

    for ix, col in enumerate(X.T):
        # Calculate total distinct values once, treating NaN as a category.
        try:
            s = pd.Series(col)
            # counts NaN/None as a category
            num_distinct = s.nunique(dropna=False)
        except TypeError as e:
            # e.g. "unhashable type: 'dict'" when object arrays contain dicts
            raise TypeError(
                "argument must be a string or a number"
                "(columns must only contain strings or numbers)"
            ) from e
        if ix in maybe_categoricals:
            if num_distinct <= max_unique_for_category:
                indices.append(ix)
        elif (
            large_enough_x_to_infer_categorical
            and num_distinct < min_unique_for_numerical
        ):
            indices.append(ix)

    return indices

def get_all_inputs(nodes: Dict[str, NodeRepr], top_sort: list):
        all_nodes = [InputConst.name]
        all_inputs = dict((name, nodes[InputConst.name].outputs) for name in nodes)
        for name in top_sort[1:]:
            if nodes[name].iter_info.type == ConcatConst.name:
                pre_name = all_nodes.pop()
                while name in nodes[pre_name].next_nodes:
                    nodes[name].inputs += nodes[pre_name].outputs
                    if len(all_nodes) == 0:
                        break
                    pre_name = all_nodes.pop()
                nodes[name].outputs = nodes[name].inputs
            all_nodes.append(name)
            if nodes[name].next_nodes is None:
                continue
            for n in nodes[name].next_nodes:
                all_inputs[n] = all_inputs[n] + nodes[name].outputs + all_inputs[name]
        return all_inputs

def use(self, styles: dict[str, Any]) -> Styler:
        self._todo.extend(styles.get("apply", []))
        table_attributes: str = self.table_attributes or ""
        obj_table_atts: str = (
            ""
            if styles.get("table_attributes") is None
            else str(styles.get("table_attributes"))
        )
        self.set_table_attributes((table_attributes + " " + obj_table_atts).strip())
        if styles.get("table_styles"):
            self.set_table_styles(styles.get("table_styles"), overwrite=False)

        for obj in ["index", "columns"]:
            hide_obj = styles.get("hide_" + obj)
            if hide_obj is not None:
                if isinstance(hide_obj, bool):
                    n = getattr(self, obj).nlevels
                    setattr(self, "hide_" + obj + "_", [hide_obj] * n)
                else:
                    setattr(self, "hide_" + obj + "_", hide_obj)

        self.hide_index_names = styles.get("hide_index_names", False)
        self.hide_column_names = styles.get("hide_column_names", False)
        if styles.get("css"):
            self.css = styles.get("css")  # type: ignore[assignment]
        return self

def forward(self, inputs: list[torch.Tensor]) -> list[torch.Tensor]:
        x = inputs
        if self.num_branches == 1:
            return [self.branches[0](x[0])]
        assert self.fuse_layers is not None

        for i in range(self.num_branches):
            x[i] = self.branches[i](x[i])

        x_fuse = []
        for i, fuse_layer in enumerate(T.cast(list[nn.ModuleList], self.fuse_layers)):
            y = x[0] if i == 0 else fuse_layer[0](x[0])
            for j in range(1, self.num_branches):
                if i == j:
                    y = y + x[j]
                elif j > i:
                    y = y + F.interpolate(fuse_layer[j](x[j]),
                                          size=[x[i].shape[2], x[i].shape[3]],
                                          mode="bilinear")
                else:
                    y = y + fuse_layer[j](x[j])
            x_fuse.append(self.relu(y))
        return x_fuse

def find_lexer_class(name):
    if name in _lexer_cache:
        return _lexer_cache[name]
    # lookup builtin lexers
    for module_name, lname, aliases, _, _ in itervalues(LEXERS):
        if name == lname:
            _load_lexers(module_name)
            return _lexer_cache[name]
    # continue with lexers from setuptools entrypoints
    for cls in find_plugin_lexers():
        if cls.name == name:
            return cls

def submit_glue(config_path, output_path, download):
    model, data_gen, task_name = split_config(config_path, download)

    if task_name == 'cola':
        submission = get_predictions(model, data_gen, 'acceptable')

    elif task_name.startswith('mnli'):
        submission = get_predictions(model, data_gen)

    elif task_name == 'mrpc':
        submission = get_predictions(model, data_gen, 'equivalent')

    elif task_name == 'sst2':
        submission = get_predictions(model, data_gen, 'positive')

    elif task_name == 'stsb':
        submission = get_predictions(model, data_gen, None, True)

    elif task_name == 'wnli':
        submission = get_predictions(model, data_gen, 'entailment')

    elif task_name in GLUE_TASKS:
        submission = get_predictions(model, data_gen)
    else:
        raise ValueError(f'Unexpected GLUE task name: {task_name}')

    save_path = output_path or f'{GLUE_TASKS[task_name]}.tsv'
    save_path = expand_path(save_path)
    save_path.parent.mkdir(parents=True, exist_ok=True)
    save_array = np.vstack(([list(submission.keys())], np.array(list(submission.values())).transpose()))
    np.savetxt(save_path, save_array, delimiter='\t', fmt='%s')
    log.info(f'Prediction saved to {save_path}')

def get_databases(
        self,
        *,
        include_schemas: bool | Literal["auto"],
        include_tables: bool | Literal["auto"],
        include_table_details: bool | Literal["auto"],
    ) -> list[Database]:
        _ = include_schemas  # ClickHouse doesn't have schemas

        if self._connection is None:
            return []

        if not DependencyManager.pandas.has():
            LOGGER.info("Unable to get databases without pandas")
            return []

        import pandas as pd

        databases: list[Database] = []
        try:
            db_df = self._connection.query_df("SHOW DATABASES")
        except Exception:
            LOGGER.warning("Failed to get databases", exc_info=True)
            return databases

        if not isinstance(db_df, pd.DataFrame):
            LOGGER.warning(
                f"Failed to convert database result to DataFrame, result: {db_df!s}"
            )
            return databases

        include_table_details = self._resolve_should_auto_discover(
            include_table_details
        )

        # Assume the first column contains the database names.
        if db_df.empty:
            return databases

        db_names = db_df[db_df.columns[0]].tolist()
        for db in db_names:
            db_name = cast(str, db)
            # Skip introspection for meta tables for performance
            if db_name.lower() in self._meta_dbs or not include_tables:
                tables = []
            else:
                tables = self.get_tables_in_schema(
                    schema=NO_SCHEMA_NAME,
                    database=db,
                    include_table_details=include_table_details,
                )
            databases.append(
                Database(
                    name=db,
                    dialect=self.dialect,
                    engine=self._engine_name,
                    # ClickHouse does not have schemas
                    schemas=[Schema(name=NO_SCHEMA_NAME, tables=tables)],
                )
            )
        return databases

def add_const(const_context, builder, name, val):
    for const_set in const_context:
        if name in const_set:
            logger.warning("Const {} was already added.".format(name))
            return
    if not isinstance(val, (_np.ndarray, _np.generic)):
        val = _np.array([val])
    if val.dtype != float:
        # nn proto only supports float32 activation. (e.g., pred in cond op
        # needs to be converted to float)
        val = val.astype(float)
    rank = len(val.shape)
    if rank == 0:
        builder.add_load_constant_nd(
            name=name, output_name=name, constant_value=val.reshape([1]), shape=[1]
        )
    else:
        builder.add_load_constant_nd(
            name=name, output_name=name, constant_value=val, shape=val.shape
        )
    const_context[-1].add(name)
    logger.info("added const {} for builder {}".format(name, builder))

def make_constraint(constraint):
    if isinstance(constraint, str) and constraint == "array-like":
        return _ArrayLikes()
    if isinstance(constraint, str) and constraint == "sparse matrix":
        return _SparseMatrices()
    if isinstance(constraint, str) and constraint == "random_state":
        return _RandomStates()
    if constraint is callable:
        return _Callables()
    if constraint is None:
        return _NoneConstraint()
    if isinstance(constraint, type):
        return _InstancesOf(constraint)
    if isinstance(
        constraint, (Interval, StrOptions, Options, HasMethods, MissingValues)
    ):
        return constraint
    if isinstance(constraint, str) and constraint == "boolean":
        return _Booleans()
    if isinstance(constraint, str) and constraint == "verbose":
        return _VerboseHelper()
    if isinstance(constraint, str) and constraint == "cv_object":
        return _CVObjects()
    if isinstance(constraint, Hidden):
        constraint = make_constraint(constraint.constraint)
        constraint.hidden = True
        return constraint
    if (isinstance(constraint, str) and constraint == "nan") or (
        isinstance(constraint, float) and np.isnan(constraint)
    ):
        return _NanConstraint()
    raise ValueError(f"Unknown constraint type: {constraint}")

def load_data(cls, path: str) -> "Dataset":
        if not os.path.exists(path):
            raise FileNotFoundError(f"Dataset file not found at {path}")

        file_ext = os.path.splitext(path)[1].lower()

        if file_ext == ".json":
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        elif file_ext == ".jsonl":
            data = []
            with open(path, encoding="utf-8") as f:
                for line in f:
                    data.append(json.loads(line))
        elif file_ext == ".csv":
            import pandas as pd

            data = pd.read_csv(path).to_dict("records")
        elif file_ext == ".parquet":
            import pandas as pd

            data = pd.read_parquet(path).to_dict("records")
        elif file_ext == ".arrow":
            data = DatasetRegistry._load_arrow_ipc(path)
        else:
            raise ValueError(f"Unsupported file format: {file_ext}")

        return cls(data=data)

def compute_weighted_metric(
    y: np.ndarray, y_pred: np.ndarray, metric: Scorer, weights: np.ndarray, weight_evaluation: bool = None, **kwargs
) -> float:
    logger.log(
        30,
        "WARNING: `compute_weighted_metric` is deprecated as of AutoGluon 1.2 and will be removed in AutoGluon 1.4. "
        "Please use `autogluon.core.metrics.compute_metric` instead.",
    )
    if not metric.needs_quantile:
        kwargs.pop("quantile_levels", None)
    if weight_evaluation is None:
        weight_evaluation = weights is not None
    if weight_evaluation and weights is None:
        raise ValueError("Sample weights cannot be None when weight_evaluation=True.")
    if not weight_evaluation:
        return metric(y, y_pred, **kwargs)
    try:
        weighted_metric = metric(y, y_pred, sample_weight=weights, **kwargs)
    except (ValueError, TypeError, KeyError):
        if hasattr(metric, "name"):
            metric_name = metric.name
        else:
            metric_name = metric
        logger.log(
            30,
            f"WARNING: eval_metric='{metric_name}' does not support sample weights so they will be ignored in reported metric.",
        )
        weighted_metric = metric(y, y_pred, **kwargs)
    return weighted_metric

def get_relevant_data_table(text_data: TextData, data_type: str, columns: Union[Hashable, List[Hashable], None],
                            ignore_columns: Union[Hashable, List[Hashable], None], n_top_features: Optional[int]):
    if data_type == 'metadata':
        relevant_metadata = text_data.metadata[text_data.categorical_metadata + text_data.numerical_metadata]
        features = select_from_dataframe(relevant_metadata, columns, ignore_columns)
        cat_features = [col for col in features.columns if col in text_data.categorical_metadata]

    elif data_type == 'properties':
        features = select_from_dataframe(text_data.properties, columns, ignore_columns)
        cat_features = [col for col in features.columns if col in text_data.categorical_properties]
    else:
        raise DeepchecksProcessError(f'Unknown segment_by value: {data_type}')

    if features.shape[1] < 2:
        raise DeepchecksNotSupportedError('Check requires to have at least two '
                                          f'{data_type} columns in order to run.')

    if n_top_features is not None and n_top_features < features.shape[1]:
        _warn_n_top_columns(data_type, n_top_features)
        features = features.iloc[:, np.random.choice(features.shape[1], n_top_features, replace=False)]

    return features, cat_features

def teardown(self) -> None:
        if self.stdout is not None:
            self.stdout._stop()
        if self.stderr is not None:
            self.stderr._stop()
        if self.stdin is not None:
            self.stdin._stop()
        self.stream.stop()

        if self.module_watcher is not None:
            self.module_watcher.stop()

        # TODO(akshayka): There's a memory leak in run mode, with memory
        # usage increasing with each session creation. Somehow the kernel
        # globals appear to leak, even though the thread exits. As a hack we
        # manually clear kernel memory.
        self._module.__dict__.clear()

        # Teardown lifespans
        if self._lifespan is not None:
            asyncio.run(self._lifespan.__aexit__(None, None, None))

def propagate_in_video_iterator(
        self,
        inference_session: Sam3TrackerVideoInferenceSession,
        start_frame_idx: int | None = None,
        max_frame_num_to_track: int | None = None,
        reverse: bool = False,
        show_progress_bar: bool = False,
    ) -> Iterator[Sam3TrackerVideoSegmentationOutput]:
        num_frames = inference_session.num_frames

        # set start index, end index, and processing order
        if start_frame_idx is None:
            # default: start from the earliest frame with input points
            frames_with_inputs = [
                frame_idx
                for obj_output_dict in inference_session.output_dict_per_obj.values()
                for frame_idx in obj_output_dict["cond_frame_outputs"]
            ]
            if not frames_with_inputs:
                raise ValueError(
                    "Cannot determine the starting frame index; please specify it manually, or run inference on a frame with inputs first."
                )
            start_frame_idx = min(frames_with_inputs)
        if max_frame_num_to_track is None:
            # default: track all the frames in the video
            max_frame_num_to_track = num_frames
        if reverse:
            end_frame_idx = max(start_frame_idx - max_frame_num_to_track, 0)
            if start_frame_idx > 0:
                processing_order = range(start_frame_idx, end_frame_idx - 1, -1)
            else:
                processing_order = []  # skip reverse tracking if starting from frame 0
        else:
            end_frame_idx = min(start_frame_idx + max_frame_num_to_track, num_frames - 1)
            processing_order = range(start_frame_idx, end_frame_idx + 1)

        for frame_idx in tqdm(processing_order, desc="propagate in video", disable=not show_progress_bar):
            sam3_tracker_video_output = self(inference_session, frame_idx=frame_idx, reverse=reverse)
            yield sam3_tracker_video_output

def precision_at_k(
        self,
        query: str,
        retrieved_context_chunks: List[str],
        relevance_scores: Optional[List[float]] = None,
        k: Optional[int] = None,
    ) -> float:
        ground_truth_context_chunks = (
            self._find_golden_context_chunks_and_scores(query)
        )
        if ground_truth_context_chunks:
            k = k or len(retrieved_context_chunks)

            # Extract ground truth chunks
            golden_chunks = set(
                chunk[0] for chunk in ground_truth_context_chunks
            )

            # Sort retrieved chunks by relevance scores if scores are provided
            if relevance_scores:
                # Get the top-k threshold score (with tie handling)
                sorted_scores = sorted(relevance_scores, reverse=True)
                kth_score = sorted_scores[min(k - 1, len(sorted_scores) - 1)]

                # Include all indices with scores >= kth score
                top_k_indices = [
                    i
                    for i, score in enumerate(relevance_scores)
                    if score >= kth_score
                ]
                retrieved_top_k = [
                    retrieved_context_chunks[i] for i in top_k_indices
                ]
            else:
                # If no relevance scores, use the top-k retrieved chunks as they are
                retrieved_top_k = retrieved_context_chunks[:k]

            # Calculate precision at k with tie handling
            relevant_retrieved = len([
                chunk for chunk in retrieved_top_k if chunk in golden_chunks
            ])
            return (
                relevant_retrieved / len(retrieved_top_k)
                if len(retrieved_top_k) > 0
                else 0.0
            )
        else:
            return np.nan

def fit(self, X: np.ndarray, y: np.ndarray = None) -> None:
        count, ndim = X.shape
        pca_transformer = PCA(n_components=20, random_state=42)
        # Clamp contamination rate in case that IQR method gives bad results
        contamination_rate = max(self.estimate_contamination_rate(X), MIN_CONTAMINATION_RATE)
        contamination_rate = min(contamination_rate, MAX_CONTAMINATION_RATE)

        if ndim > 20:
            X = pca_transformer.fit_transform(X)
        if self.method == 'auto':
            if ndim <= 5:
                self.method = 'lof'
            else:
                self.method = 'itree'
        if self.method == 'lof':
            if count < 10:
                n_neighbors = 2
            elif count < 500:
                n_neighbors = count // 10 + 1
            elif contamination_rate <= 0.1:
                n_neighbors = 20
            else:
                n_neighbors = 35
            self.outlier_remover = LocalOutlierFactor(
                n_neighbors=n_neighbors,
                n_jobs=-1,
                contamination=contamination_rate,
            )
        elif self.method == 'itree':
            self.outlier_remover = IsolationForest(
                contamination=contamination_rate,
                n_estimators=100,
                n_jobs=-1,
                random_state=42,
            )
            self.outlier_remover.fit(X, y)

def evaluate_classifier_with_probabilities(
    model, data, probabilities="probabilities", verbose=False
):

    model = _get_model(model)
    if verbose:
        print("")
        print("Other Framework\t\tPredicted")

    max_probability_error, num_key_mismatch = 0, 0

    for _, row in data.iterrows():
        input_dict = {k: v for k, v in dict(row).items() if k != probabilities}
        _remove_invalid_keys(input_dict, model)
        predicted_values = model.predict(input_dict)[_to_unicode(probabilities)]
        other_values = row[probabilities]

        if set(predicted_values.keys()) != set(other_values.keys()):
            if verbose:
                print(
                    "Different classes: ",
                    str(predicted_values.keys()),
                    str(other_values.keys()),
                )
            num_key_mismatch += 1
            continue

        for cur_class, cur_predicted_class_values in predicted_values.items():
            delta = cur_predicted_class_values - other_values[cur_class]
            if verbose:
                print(delta, cur_predicted_class_values, other_values[cur_class])

            max_probability_error = max(abs(delta), max_probability_error)

        if verbose:
            print("")

    ret = {
        "num_samples": len(data),
        "max_probability_error": max_probability_error,
        "num_key_mismatch": num_key_mismatch,
    }

    if verbose:
        print("results: {}".format(ret))

    return ret

def is_subperiod(source, target) -> bool:
    if target is None or source is None:
        return False
    source = _maybe_coerce_freq(source)
    target = _maybe_coerce_freq(target)

    if _is_annual(target):
        if _is_annual(source):
            return get_rule_month(source) == get_rule_month(target)
        if _is_quarterly(source):
            return _quarter_months_conform(
                get_rule_month(source), get_rule_month(target)
            )
        return source in {"D", "C", "B", "M", "h", "min", "s", "ms", "us", "ns"}
    elif _is_quarterly(target):
        if _is_quarterly(source):
            return _quarter_months_conform(
                get_rule_month(source), get_rule_month(target)
            )
        return source in {"D", "C", "B", "M", "h", "min", "s", "ms", "us", "ns"}
    elif _is_monthly(target):
        return source in {target, "D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif _is_weekly(target):
        return source in {target, "D", "C", "B", "h", "min", "s", "ms", "us", "ns"}
    elif target == "B":
        return source in {"B", "h", "min", "s", "ms", "us", "ns"}
    elif target == "C":
        return source in {"C", "h", "min", "s", "ms", "us", "ns"}
    elif target == "D":
        return source in {"D", "h", "min", "s", "ms", "us", "ns"}
    elif target == "h":
        return source in {"h", "min", "s", "ms", "us", "ns"}
    elif target == "min":
        return source in {"min", "s", "ms", "us", "ns"}
    elif target == "s":
        return source in {"s", "ms", "us", "ns"}
    elif target == "ms":
        return source in {"ms", "us", "ns"}
    elif target == "us":
        return source in {"us", "ns"}
    elif target == "ns":
        return source in {"ns"}
    else:
        return False

def one_hot(y, num_labels="auto", dtype="float"):
    if not (num_labels == "auto" or isinstance(num_labels, int)):
        raise AttributeError('num_labels must be an integer or "auto"')
    if isinstance(y, list):
        yt = np.asarray(y)
    else:
        yt = y
    if not len(yt.shape) == 1:
        raise AttributeError("y array must be 1-dimensional")
    if num_labels == "auto":
        # uniq = np.unique(yt).shape[0]
        uniq = np.max(yt + 1)
    else:
        uniq = num_labels
    if uniq == 1:
        ary = np.array([[0.0]], dtype=dtype)

    else:
        ary = np.zeros((len(y), uniq))
        for i, val in enumerate(y):
            ary[i, val] = 1

    return ary.astype(dtype)

def get_model_config(model_name: str):
    config = None
    sizes = ["tiny", "small", "medium", "large", "xlarge"]
    for size in sizes:
        if size in model_name:
            config = MODEL_CONFIGS[size]
            config["backbone_config"] = BACKBONE_CONFIGS[size]

    # Default to base configuration
    if config is None:
        config = MODEL_CONFIGS["base"]
        config["backbone_config"] = BACKBONE_CONFIGS["base"]
    config["backbone_config"]["model_type"] = "lw_detr_vit"

    if "objects365" in model_name:
        config["num_labels"] = 366
    elif "coco" in model_name :
        config["num_labels"] = 91
    else :
        config["num_labels"] = 20

    return config

