def save_video_segments(self, output_dir: str, img_ext: str = "png") -> None:
        from PIL import Image

        def save_image_from_dict(
            data, output_path="output_image.png", crs_source=None, **kwargs
        ):
            # Find the shape of the first array in the dictionary (assuming all arrays have the same shape)
            array_shape = next(iter(data.values())).shape[1:]

            # Initialize an empty array with the same shape as the arrays in the dictionary, filled with zeros
            output_array = np.zeros(array_shape, dtype=np.uint8)

            # Iterate over each key and array in the dictionary
            for key, array in data.items():
                # Assign the key value wherever the boolean array is True
                output_array[array[0]] = key

            if crs_source is None:
                # Convert the output array to a PIL image
                image = Image.fromarray(output_array)

                # Save the image
                image.save(output_path)
            else:
                output_path = output_path.replace(".png", ".tif")
                common.array_to_image(output_array, output_path, crs_source, **kwargs)

        num_frames = len(self.video_segments)
        num_digits = len(str(num_frames))

        if hasattr(self, "_tif_source") and self._tif_source.endswith(".tif"):
            crs_source = self._tif_source
            filenames = self._tif_names
        else:
            crs_source = None
            filenames = None

        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        # Initialize the tqdm progress bar
        for frame_idx, video_segment in tqdm(
            self.video_segments.items(), desc="Rendering frames", total=num_frames
        ):
            if filenames is None:
                output_path = os.path.join(
                    output_dir, f"{str(frame_idx).zfill(num_digits)}.{img_ext}"
                )
            else:
                output_path = os.path.join(output_dir, filenames[frame_idx])
            save_image_from_dict(video_segment, output_path, crs_source)

def draw_rectangle(
    image: torch.Tensor, rectangle: torch.Tensor, color: Optional[torch.Tensor] = None, fill: Optional[bool] = None
) -> torch.Tensor:
    batch, c, h, w = image.shape
    batch_rect, num_rectangle, num_points = rectangle.shape
    if batch != batch_rect:
        raise AssertionError("Image batch and rectangle batch must be equal")
    if num_points != 4:
        raise AssertionError("Number of points in rectangle must be 4")

    # clone rectangle, in case it's been expanded assignment from clipping causes problems
    rectangle = rectangle.long().clone()

    # clip rectangle to hxw bounds
    rectangle[:, :, 1::2] = torch.clamp(rectangle[:, :, 1::2], 0, h - 1)
    rectangle[:, :, ::2] = torch.clamp(rectangle[:, :, ::2], 0, w - 1)

    if color is None:
        color = torch.tensor([0.0] * c).expand(batch, num_rectangle, c)

    if fill is None:
        fill = False

    if len(color.shape) == 1:
        color = color.expand(batch, num_rectangle, c)
    b, n, color_channels = color.shape

    if color_channels == 1 and c == 3:
        color = color.expand(batch, num_rectangle, c)

    for b in range(batch):
        for n in range(num_rectangle):
            if fill:
                image[
                    b,
                    :,
                    int(rectangle[b, n, 1]) : int(rectangle[b, n, 3] + 1),
                    int(rectangle[b, n, 0]) : int(rectangle[b, n, 2] + 1),
                ] = color[b, n, :, None, None]
            else:
                image[b, :, int(rectangle[b, n, 1]) : int(rectangle[b, n, 3] + 1), rectangle[b, n, 0]] = color[
                    b, n, :, None
                ]
                image[b, :, int(rectangle[b, n, 1]) : int(rectangle[b, n, 3] + 1), rectangle[b, n, 2]] = color[
                    b, n, :, None
                ]
                image[b, :, rectangle[b, n, 1], int(rectangle[b, n, 0]) : int(rectangle[b, n, 2] + 1)] = color[
                    b, n, :, None
                ]
                image[b, :, rectangle[b, n, 3], int(rectangle[b, n, 0]) : int(rectangle[b, n, 2] + 1)] = color[
                    b, n, :, None
                ]

    return image

def dict_expansion(self, word):
        expansion = self.expansion_dict.get(word)
        if expansion is not None:
            return expansion

        if word.isupper():
            expansion = self.expansion_dict.get(word.lower())
            if expansion is not None:
                return expansion.upper()

        if word[0].isupper() and word[1:].islower():
            expansion = self.expansion_dict.get(word.lower())
            if expansion is not None:
                return expansion[0].upper() + expansion[1:]

        # could build a truecasing model of some kind to handle cRaZyCaSe...
        # but that's probably too much effort
        return None

def write(self, writer_gen=None, path=None, skip_header=False):
        if path is None:
            path = self.path + '.results'
        print('generating csv at ' + path)
        with open(path, 'w') as csvfile:
            c = csv.writer(csvfile, delimiter=self.delim)
            if writer_gen is not None:
                # if first item of generator is a header of what the metrics mean then write header to csv file
                if not skip_header:
                    header = (self.label_key, ) + tuple(
                        next(writer_gen)) + (self.text_key, )
                    c.writerow(header)
                for i, row in enumerate(writer_gen):
                    row = (self.Y[i], ) + tuple(row) + (self.X[i], )
                    c.writerow(row)
            else:
                c.writerow([self.label_key, self.text_key])
                for row in zip(self.Y, self.X):
                    c.writerow(row)

def prefetch_local_sources(
        self,
        num_workers: int = None,
        wait: bool = True,
        query_cache_size: int = None,
        get_previews: bool = False,
        get_masks: bool = True,
        force_download: bool = False,
    ):
        from concurrent.futures import ThreadPoolExecutor, as_completed

        self._ensure_created()

        it = self.get_iterator(query_cache_size=query_cache_size)

        def _extract_uris(data_entry):
            uris = []
            sources = ["source"]
            if get_previews:
                sources += ["preview_source"]
            if get_masks:
                sources += ["mask_source"]
            for source in sources:
                for data_sub_entry in data_entry:
                    url = data_sub_entry.get_source(source)
                    if url:
                        uris.append(url)
            return uris

        # Prefetch using a thread pool
        futures = []
        with ThreadPoolExecutor(max_workers=num_workers) as pool:
            for data_entry in it:
                for uri in _extract_uris(data_entry):
                    futures.append(
                        pool.submit(
                            StorageManagerDiskSpaceFileSizeStrategy.get_local_copy,
                            uri,
                            None,
                            True,
                            None,
                            force_download,
                        )
                    )
            if wait:
                for f in as_completed(futures):
                    try:
                        _ = f.result()
                    except Exception:
                        continue

def get_distributions(dat, skipDiscrete=False, skipContinuous=False):
    vars = dat.domain.variables
    if skipDiscrete:
        if skipContinuous:
            return []
        columns = [i for i, var in enumerate(vars) if var.is_continuous]
    elif skipContinuous:
        columns = [i for i, var in enumerate(vars) if var.is_discrete]
    else:
        columns = None
    try:
        dist_unks = dat._compute_distributions(columns)
        if columns is None:
            columns = np.arange(len(vars))
        distributions = []
        for col, (dist, unks) in zip(columns, dist_unks):
            distributions.append(get_distribution(dist, vars[col], unks))
    except NotImplementedError:
        if columns is None:
            columns = np.arange(len(vars))
        distributions = [get_distribution(dat, i) for i in columns]
    return distributions

def modes(valid_types):
  mp_id = uuid.uuid4()

  @utils.decorator
  def _wrapper(f, instance, args, kwargs):
    """Decorator to cast inputs and outputs for mixed precision.

    Args:
      f: function to handle mixed precision casting for.
      instance: instance of f.
      args: positional arguments to f.
      kwargs: keyword arguments to f.

    Returns:
      A wrapped version of `f` that casts input Variables and Tensors to the
      global mixed_precision_mode dtype if that dtype is legal for this function
      as determined by `valid_types`.
    """
    new_dtype = _get_mixed_precision_mode()
    if new_dtype is None or new_dtype not in valid_types:
      # TODO(loreno): consider throwing an error or doing nothing if input dtype
      # doesn't match any valid types
      return f(*args, **kwargs)

    if instance is None:
      if not _wrapper.seen_none:
        # TODO(loreno): Make this thread safe
        res = f(*args, **kwargs)
        _wrapper.seen_none = True
        return res
      return _cast_call(f, new_dtype, args, kwargs)

    else:
      seen = getattr(instance, _MP_SEEN_PROPERTY, None)
      if seen is None:
        seen = set()
        # TODO(loreno): use a weakrefset to address instances that define slots
        setattr(instance, _MP_SEEN_PROPERTY, seen)
      if mp_id not in seen:
        res = f(*args, **kwargs)
        seen.add(mp_id)
        return res
      return _cast_call(f, new_dtype, args, kwargs)

  _wrapper.seen_none = False
  return _wrapper

def tokenize(self, x):
        if isinstance(x, list) and all([isinstance(_x, list) for _x in x]):
            d = None
            for l in x:
                t = self.tokenizer(
                    l,
                    padding="max_length",
                    max_length=384,
                    truncation=True,
                    return_tensors="pt",
                )
                t["sizes"] = torch.tensor([len(l)])
                if d is not None:
                    for k in d.keys():
                        d[k] = torch.cat((d[k], t[k]), 0)
                else:
                    d = t

            d["start_token_id"] = torch.tensor(self.tokenizer.convert_tokens_to_ids("[E]"))
            d["end_token_id"] = torch.tensor(self.tokenizer.convert_tokens_to_ids("[/E]"))

        elif isinstance(x, list) and all([isinstance(_x, str) for _x in x]):
            d = self.tokenizer(
                x,
                padding="max_length",
                max_length=384,
                truncation=True,
                return_tensors="pt",
            )

        else:
            raise Exception(
                "Type of parameter x was not recognized! Only `list of strings` for query or `list of lists of"
                " strings` for supports are supported."
            )

        return d

def from_dict(cls, obj: dict) -> ProfileBasicData:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return ProfileBasicData.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in ProfileBasicData) in the input: " + str(obj))

        _obj = ProfileBasicData.parse_obj({
            "id": obj.get("id"),
            "nickname": obj.get("nickname"),
            "name": obj.get("name"),
            "given_name": obj.get("givenName"),
            "family_name": obj.get("familyName"),
            "email": obj.get("email"),
            "created_at": obj.get("createdAt"),
            "teams": [TeamBasicData.from_dict(_item) for _item in obj.get("teams")] if obj.get("teams") is not None else None
        })
        return _obj

def parse_ocr_from_text_and_spans(
        self, text: str, pattern: str | None, image_size: tuple[int, int], area_threshold: float = 0.0
    ) -> list[dict[str, Any]]:
        text = text.replace("<s>", "").replace("</s>", "").replace("<pad>", "")
        if pattern is None:
            pattern = r"(.+?)<loc_(\d+)><loc_(\d+)><loc_(\d+)><loc_(\d+)><loc_(\d+)><loc_(\d+)><loc_(\d+)><loc_(\d+)>"

        matches = re.findall(pattern, text)
        instances = []
        width, height = image_size

        for content, *quad_str in matches:
            quad_bins = [int(i) for i in quad_str]
            quad_box = self.dequantize(torch.tensor(quad_bins).reshape(-1, 2), size=image_size).flatten().tolist()

            if area_threshold > 0:
                x_coords = quad_box[0::2]
                y_coords = quad_box[1::2]
                # Apply the Shoelace formula
                area = 0.5 * abs(
                    sum(x_coords[i] * y_coords[i + 1] - x_coords[i + 1] * y_coords[i] for i in range(4 - 1))
                )

                if area < (width * height) * area_threshold:
                    continue

            instances.append({"quad_box": quad_box, "text": content.strip()})
        return instances

def get_kuberay_config(self) -> Dict[str, Any]:
        if self._codeflare_config is not None:
            return self._codeflare_config

        # Get passthrough configuration from kuberay_conf first
        kuberay_conf = self._get_config_value("kuberay_conf", {}) or {}

        config = {
            "use_kuberay": (
                os.getenv("FEAST_USE_KUBERAY", "").lower() == "true"
                or self._get_config_value("use_kuberay", False)
            ),
            # Get values from kuberay_conf or environment variables
            "cluster_name": (
                os.getenv("FEAST_RAY_CLUSTER_NAME") or kuberay_conf.get("cluster_name")
            ),
            "namespace": (
                os.getenv("FEAST_RAY_NAMESPACE")
                or kuberay_conf.get("namespace", "default")
            ),
        }

        # Add authentication configuration from kuberay_conf or environment variables
        auth_token = (
            os.getenv("FEAST_RAY_AUTH_TOKEN")
            or os.getenv("RAY_AUTH_TOKEN")
            or kuberay_conf.get("auth_token")
        )
        if auth_token:
            config["auth_token"] = auth_token

        # Add authentication server URL
        auth_server = (
            os.getenv("FEAST_RAY_AUTH_SERVER")
            or os.getenv("RAY_AUTH_SERVER")
            or kuberay_conf.get("auth_server")
        )
        if auth_server:
            config["auth_server"] = auth_server

        # Add skip TLS verification setting
        skip_tls = os.getenv(
            "FEAST_RAY_SKIP_TLS", ""
        ).lower() == "true" or kuberay_conf.get("skip_tls", False)
        config["skip_tls"] = skip_tls

        # Add any additional configuration from kuberay_conf
        for key, value in kuberay_conf.items():
            if key not in config:  # Don't override already processed keys
                config[key] = value

        self._codeflare_config = config
        return config

def printFrames(self, node: fx.Node) -> None:
        if (
            self.show_src
            and "stack_trace" in node.meta
            and len(node.meta["stack_trace"]) > 0
        ):
            try:
                stack_trace = json.loads(node.meta["stack_trace"])
                is_json = True
            except json.decoder.JSONDecodeError:
                is_json = False

            if not is_json:
                logging.debug(node.meta["stack_trace"])
                return

            frame_list = []  # tuple of filename, frame name, line number and line
            for frame in stack_trace:
                filename = frame["filename"]
                name = frame["name"]
                lineno = frame["lineno"]
                line = frame["line"]
                if not self.show_full_path:
                    filename = os.path.basename(filename)
                mark = "#link-tree/"
                if mark in filename:
                    filename = filename.split(mark)[-1]

                if not self.path_filter_re or self.path_filter_re.search(filename):
                    frame_list.append((filename, name, lineno, line))

            if not self.show_all_frames:
                frame_list = frame_list[-1:]
            for filename, name, lineno, line in frame_list:
                logging.debug(f"      > {filename}:{lineno} in {name}: {line}")

def grad(f, has_aux=False):
  def check_loss_shape(np_loss):
    if not isinstance(np_loss, tf_np.ndarray):
      raise ValueError(
          "The result of the function to take gradient must be an ndarray.")
    if not np_loss.shape.is_compatible_with([]):
      raise ValueError(
          "The result of the function to take gradient must be a scalar.")

  def _f(params, *args):
    """The gradient function to be returned."""
    with tf.GradientTape() as g:
      g.watch(tf.nest.flatten(params))
      outputs = f(params, *args)
      if has_aux:
        np_loss, aux = outputs
      else:
        np_loss = outputs
      check_loss_shape(np_loss)
      tf_grads = g.gradient(np_loss, params)
      if has_aux:
        res = (tf_grads, aux)
      else:
        res = tf_grads
      return _tf_to_np(res)

  return _f

def fp8_optimizers_supported() -> bool:
    override = os.environ.get("SIMPLETUNER_ENABLE_FP8_OPTIMIZERS")
    if override is not None:
        return _is_truthy(override)

    if not torch.cuda.is_available():
        return False

    try:
        device_count = torch.cuda.device_count()
    except Exception:
        device_count = 0

    for index in range(device_count):
        try:
            major, _ = torch.cuda.get_device_capability(index)
        except (AssertionError, RuntimeError, ValueError):
            continue

        if major >= 9:
            return True

    return False

def get_image_processor_class_from_name(class_name: str):
    if class_name == "BaseImageProcessorFast":
        # kept for backward compatibility - return TorchvisionBackend
        from ...image_processing_backends import TorchvisionBackend

        return TorchvisionBackend

    # First, check registered extra content (user-registered classes)
    for mapping in IMAGE_PROCESSOR_MAPPING._extra_content.values():
        for extractor_class in mapping.values():
            if isinstance(extractor_class, type) and getattr(extractor_class, "__name__", None) == class_name:
                return extractor_class

    # Check the mapping names - class names are either base (torchvision) or base+Pil (pil)
    for model_type, extractors_dict in IMAGE_PROCESSOR_MAPPING_NAMES.items():
        if class_name in extractors_dict.values():
            module_name = model_type_to_module_name(model_type)
            module = importlib.import_module(f".{module_name}", "transformers.models")
            try:
                return getattr(module, class_name)
            except AttributeError:
                continue

    # Fallback: class may be in main init (e.g. when dep is missing, returns dummy)
    main_module = importlib.import_module("transformers")
    if hasattr(main_module, class_name):
        return getattr(main_module, class_name)

    return None

def trace_to_formatted_conversation_history(
        trace: list[ChatCompletionMessageParam],
    ) -> str:
        conversation_history = ""
        for index, message in enumerate(trace):
            message_details = EvalTraceFormatter.message_details_from_message(message)

            role_label = None
            tag = None
            content = None

            if message_details.role == "tool" and message_details.content:
                origin_tool_call_name = (
                    EvalTraceFormatter.origin_tool_call_name_from_message(
                        message, trace
                    )
                )

                if origin_tool_call_name:
                    role_label = message_details.role
                    tag = f"{message_details.role}_tool_message"
                    content = message_details.content

            else:
                if message_details.reasoning_content:
                    role_label = f"{message_details.role} reasoning"
                    tag = f"{message_details.role}_reasoning_message"
                    content = message_details.reasoning_content

                if message_details.tool_calls:
                    role_label = f"{message_details.role} requested tool calls"
                    tag = f"{message_details.role}_requested_tool_calls"
                    content = message_details.tool_calls

                if message_details.content:
                    role_label = message_details.role
                    tag = f"{message_details.role}_message"
                    content = message_details.content

            if role_label and tag and content:
                if index > 0:
                    conversation_history += "\n\n"
                conversation_history += f"{role_label}:\n<{tag}>\n{content}\n</{tag}>"

        return conversation_history

def make_path(self):
        if not self.points:
            return QtGui.QPainterPath()
        if self.shape_type == "rectangle":
            path = QtGui.QPainterPath(self.points[0])
            for p in self.points[1:]:
                path.lineTo(p)
        elif self.shape_type == "cuboid":
            path = QtGui.QPainterPath(self.points[0])
            if len(self.points) >= 4:
                for p in self.points[1:4]:
                    path.lineTo(p)
                path.closeSubpath()
            if len(self.points) >= 8:
                back_path = QtGui.QPainterPath(self.points[4])
                for p in self.points[5:8]:
                    back_path.lineTo(p)
                back_path.closeSubpath()
                path.addPath(back_path)
        elif self.shape_type == "circle":
            path = QtGui.QPainterPath()
            if len(self.points) == 2:
                rectangle = self.get_circle_rect_from_line(self.points)
                path.addEllipse(rectangle)
        else:
            path = QtGui.QPainterPath(self.points[0])
            for p in self.points[1:]:
                path.lineTo(p)
        return path

def try_resume(
        self,
        new_session_id: SessionId,
        file_key: MarimoFileKey,
    ) -> Session | None:
        import os

        # Find sessions with the same file
        sessions_with_file = []
        for session in self._repository.get_all():
            session_id = self._repository.get_session_id(session)
            if session_id and session.app_file_manager.path == os.path.abspath(
                file_key
            ):
                sessions_with_file.append((session_id, session))

        if len(sessions_with_file) == 0:
            return None

        if len(sessions_with_file) > 1:
            from marimo._server.exceptions import InvalidSessionException

            raise InvalidSessionException(
                "Only one session should exist while editing"
            )

        session_id, session = sessions_with_file[0]
        connection_state = session.connection_state()

        if connection_state == ConnectionState.ORPHANED:
            LOGGER.debug(
                f"Found a resumable EDIT session: prev_id={session_id}"
            )
            # Update session ID
            self._repository.update_session_id_sync(session_id, new_session_id)
            return session

        LOGGER.debug(
            "Session is not resumable, current state: %s",
            connection_state,
        )
        return None

def parse(training_path, query, verbose=False, intents_filter=None):
    import csv
    import logging
    from builtins import input, str
    from snips_nlu import SnipsNLUEngine
    from snips_nlu.cli.utils import set_nlu_logger

    if verbose == 1:
        set_nlu_logger(logging.INFO)
    elif verbose >= 2:
        set_nlu_logger(logging.DEBUG)
    if intents_filter:
        # use csv in order to properly handle commas and other special
        # characters in intent names
        intents_filter = next(csv.reader([intents_filter]))
    else:
        intents_filter = None

    engine = SnipsNLUEngine.from_path(training_path)

    if query:
        print_parsing_result(engine, query, intents_filter)
        return

    while True:
        query = input("Enter a query (type 'q' to quit): ").strip()
        if not isinstance(query, str):
            query = query.decode("utf-8")
        if query == "q":
            break
        print_parsing_result(engine, query, intents_filter)

def adjoint_jacobian(tape: QuantumScript, state=None):
    # Map wires if custom wire labels used
    tape = tape.map_to_standard_wires()

    if isinstance(tape.measurements[0], qml.measurements.StateMP):
        return _adjoint_jacobian_state(tape)

    ket = state if state is not None else get_final_state(tape)[0]

    n_obs = len(tape.observables)
    bras = np.empty([n_obs] + [2] * len(tape.wires), dtype=np.complex128)
    for kk, obs in enumerate(tape.observables):
        bras[kk, ...] = 2 * apply_operation(obs, ket)

    jac = np.zeros((len(tape.observables), len(tape.trainable_params)))

    param_number = len(tape.get_parameters(trainable_only=False, operations_only=True)) - 1
    trainable_param_number = len(tape.trainable_params) - 1
    for op in reversed(tape.operations[tape.num_preps :]):
        if isinstance(op, qml.Snapshot):
            continue
        adj_op = qml.adjoint(op)
        ket = apply_operation(adj_op, ket)

        if op.num_params == 1:
            if param_number in tape.trainable_params:
                d_op_matrix = operation_derivative(op)
                ket_temp = apply_operation(qml.QubitUnitary(d_op_matrix, wires=op.wires), ket)
                jac[:, trainable_param_number] = _dot_product_real(bras, ket_temp, len(tape.wires))

                trainable_param_number -= 1
            param_number -= 1

        for kk in range(n_obs):
            bras[kk, ...] = apply_operation(adj_op, bras[kk, ...])

    # Post-process the Jacobian matrix for the new return
    jac = np.squeeze(jac)

    if jac.ndim == 0:
        return np.array(jac)

    if jac.ndim == 1:
        return tuple(np.array(j) for j in jac)

    # must be 2-dimensional
    return tuple(tuple(np.array(j_) for j_ in j) for j in jac)

def get_attribution_headers() -> dict[str, str]:
    headers: dict[str, str] = {}

    # Worker context (passed via environment variables from worker to flow run process)
    if worker_id := os.environ.get("PREFECT__WORKER_ID"):
        headers["X-Prefect-Worker-Id"] = worker_id
    if worker_name := os.environ.get("PREFECT__WORKER_NAME"):
        headers["X-Prefect-Worker-Name"] = worker_name

    # Flow and deployment context - try to get from context first, fall back to env vars
    # Import here to avoid circular imports
    from prefect.context import FlowRunContext

    flow_run_ctx = FlowRunContext.get()

    if flow_run_ctx and flow_run_ctx.flow_run:
        flow_run = flow_run_ctx.flow_run

        # Flow info (use getattr for safety with mock/minimal FlowRun objects)
        if flow_id := getattr(flow_run, "flow_id", None):
            headers["X-Prefect-Flow-Id"] = str(flow_id)
        if flow_run_ctx.flow and getattr(flow_run_ctx.flow, "name", None):
            headers["X-Prefect-Flow-Name"] = flow_run_ctx.flow.name

        # Deployment info from flow run
        if deployment_id := getattr(flow_run, "deployment_id", None):
            headers["X-Prefect-Deployment-Id"] = str(deployment_id)
        # Deployment name is not on FlowRun, fall back to env var
        if deployment_name := os.environ.get("PREFECT__DEPLOYMENT_NAME"):
            headers["X-Prefect-Deployment-Name"] = deployment_name
    else:
        # Fall back to environment variables
        if flow_id := os.environ.get("PREFECT__FLOW_ID"):
            headers["X-Prefect-Flow-Id"] = flow_id
        if flow_name := os.environ.get("PREFECT__FLOW_NAME"):
            headers["X-Prefect-Flow-Name"] = flow_name
        if deployment_id := os.environ.get("PREFECT__DEPLOYMENT_ID"):
            headers["X-Prefect-Deployment-Id"] = deployment_id
        if deployment_name := os.environ.get("PREFECT__DEPLOYMENT_NAME"):
            headers["X-Prefect-Deployment-Name"] = deployment_name

    return headers

def make_eval_fn_with_agent(
    agent_type, eval_mode, planner_hparams, model_dir, log_every_steps=None,
    video_writers=(), random_starts_step_limit=None
):
  def eval_fn(env, loop_hparams, policy_hparams, policy_dir, sampling_temp):
    """Eval function."""
    base_env = env
    env = rl_utils.BatchStackWrapper(env, loop_hparams.frame_stack_size)
    agent = make_agent_from_hparams(
        agent_type, base_env, env, loop_hparams, policy_hparams,
        planner_hparams, model_dir, policy_dir, sampling_temp, video_writers
    )

    if eval_mode == "agent_simulated":
      real_env = base_env.new_like(batch_size=1)
      stacked_env = rl_utils.BatchStackWrapper(
          real_env, loop_hparams.frame_stack_size
      )
      collect_frames_for_random_starts(
          real_env, stacked_env, agent, loop_hparams.frame_stack_size,
          random_starts_step_limit, log_every_steps
      )
      initial_frame_chooser = rl_utils.make_initial_frame_chooser(
          real_env, loop_hparams.frame_stack_size,
          simulation_random_starts=True,
          simulation_flip_first_random_for_beginning=False,
          split=None,
      )
      env_fn = rl.make_simulated_env_fn_from_hparams(
          real_env, loop_hparams, batch_size=loop_hparams.eval_batch_size,
          initial_frame_chooser=initial_frame_chooser, model_dir=model_dir
      )
      sim_env = env_fn(in_graph=False)
      env = rl_utils.BatchStackWrapper(sim_env, loop_hparams.frame_stack_size)

    kwargs = {}
    if not agent.records_own_videos:
      kwargs["video_writers"] = video_writers
    step_limit = base_env.rl_env_max_episode_steps
    if step_limit == -1:
      step_limit = None
    rl_utils.run_rollouts(
        env, agent, env.reset(), log_every_steps=log_every_steps,
        step_limit=step_limit, **kwargs
    )
    if eval_mode == "agent_real":
      assert len(base_env.current_epoch_rollouts()) == env.batch_size
  return eval_fn

def remove_getattr_nodes(graph: InternalTorchIRGraph) -> None:
    getattr_nodes = []
    new_nodes = []

    for node in graph.nodes:

        for block in node.blocks:
            remove_getattr_nodes(block)

        if node.kind == "getattr":
            getattr_nodes.append(node)
        else:
            new_nodes.append(node)

    # check the getattr nodes not in the outputs
    for node in getattr_nodes:
        if node.name in graph.outputs:
            raise RuntimeError("{} should not be in the graph outputs.".format(node.name))

    # remove the getattr nodes
    graph.nodes = new_nodes

def resolve_task_from_pathspec(flow_name, pathspec):
    from metaflow import Flow, Step, Task
    from metaflow.exception import MetaflowNotFound

    # since pathspec can have many variations.
    pthsplits = pathspec.split("/")
    task = None
    run_id = None
    resolving_from = "task_pathspec"
    if len(pthsplits) == 1:
        # This means stepname
        resolving_from = "stepname"
        latest_run = Flow(flow_name).latest_run
        if latest_run is not None:
            run_id = latest_run.pathspec
            try:
                task = latest_run[pathspec].task
            except KeyError:
                pass
    elif len(pthsplits) == 2:
        # This means runid/stepname
        namespace(None)
        resolving_from = "step_pathspec"
        try:
            task = Step("/".join([flow_name, pathspec])).task
        except MetaflowNotFound:
            pass
    elif len(pthsplits) == 3:
        # this means runid/stepname/taskid
        namespace(None)
        resolving_from = "task_pathspec"
        try:
            task = Task("/".join([flow_name, pathspec]))
        except MetaflowNotFound:
            pass
    else:
        # raise exception for invalid pathspec format
        raise CommandException(
            msg="The PATHSPEC argument should be of the form 'stepname' Or '<runid>/<stepname>' Or '<runid>/<stepname>/<taskid>'"
        )

    if task is None:
        # raise Exception that task could not be resolved for the query.
        raise TaskNotFoundException(pathspec, resolving_from, run_id=run_id)

    return task

def post_vae_encode_transform_sample(self, sample):
        if sample is None:
            return sample
        if hasattr(sample, "latent_dist"):
            # Use mode() (mean) not sample() to match upstream training
            sample = sample.latent_dist.mode()
        elif hasattr(sample, "sample"):
            sample = sample.sample
        if isinstance(sample, Tensor) and sample.dim() == 4:
            if sample.shape[1] == 32:
                sample = self._patchify_latents(sample)
            sample = self._normalize_latents(sample)
        return sample

def generate_unique_filename(doc, *, archive_filename=False) -> Path:
    if archive_filename:
        old_filename: Path | None = (
            Path(doc.archive_filename) if doc.archive_filename else None
        )
        root = settings.ARCHIVE_DIR
    else:
        old_filename = Path(doc.filename) if doc.filename else None
        root = settings.ORIGINALS_DIR

    # If generating archive filenames, try to make a name that is similar to
    # the original filename first.

    if archive_filename and doc.filename:
        # Generate the full path using the same logic as generate_filename
        base_generated = generate_filename(doc, archive_filename=archive_filename)

        # Try to create a simple PDF version based on the original filename
        # but preserve any directory structure from the template
        if str(base_generated.parent) != ".":
            # Has directory structure, preserve it
            simple_pdf_name = base_generated.parent / (Path(doc.filename).stem + ".pdf")
        else:
            # No directory structure
            simple_pdf_name = Path(Path(doc.filename).stem + ".pdf")

        if simple_pdf_name == old_filename or not (root / simple_pdf_name).exists():
            return simple_pdf_name

    counter = 0

    while True:
        new_filename = generate_filename(
            doc,
            counter=counter,
            archive_filename=archive_filename,
        )
        if new_filename == old_filename:
            # still the same as before.
            return new_filename

        if (root / new_filename).exists():
            counter += 1
        else:
            return new_filename

def overlapping_ops(self) -> list[list[Operator]]:
        if self._overlapping_ops is not None:
            return self._overlapping_ops

        groups = []
        for op in self:
            # For every op, find all groups that have overlapping wires with it.
            i = 0
            first_group_idx = None
            while i < len(groups):
                if first_group_idx is None and any(wire in op.wires for wire in groups[i][1]):
                    # Found the first group that has overlapping wires with this op
                    groups[i][1] = groups[i][1] + op.wires
                    first_group_idx = i  # record the index of this group
                    i += 1
                elif first_group_idx is not None and any(wire in op.wires for wire in groups[i][1]):
                    # If the op has already been added to the first group, every subsequent
                    # group that overlaps with this op is merged into the first group
                    ops, wires = groups.pop(i)
                    groups[first_group_idx][0].extend(ops)
                    groups[first_group_idx][1] = groups[first_group_idx][1] + wires
                else:
                    i += 1
            if first_group_idx is not None:
                groups[first_group_idx][0].append(op)
            else:
                # Create new group
                groups.append([[op], op.wires])

        self._overlapping_ops = [group[0] for group in groups]
        return self._overlapping_ops

def add_child(self, model: AbstractModel | str, add_child_times: bool = False, add_child_resources: bool = False):
        if self.models is None:
            self.models = []
        if isinstance(model, str):
            model_name = model
            model = None
        else:
            model_name = model.name
        if self.low_memory:
            self.models.append(model_name)
        else:
            if model is None:
                model = self.load_child(model=model_name, verbose=False)
            self.models.append(model)
        if add_child_times:
            if model is None:
                model = self.load_child(model=model_name, verbose=False)
            self._add_child_times_to_bag(model=model)
        if add_child_resources:
            if model is None:
                model = self.load_child(model=model_name, verbose=False)
            self._add_child_num_cpus(num_cpus=model.fit_num_cpus)
            self._add_child_num_gpus(num_gpus=model.fit_num_gpus)

def iflatmap_unordered(
    pool: multiprocessing.pool.ThreadPool,
    func: Callable[..., Iterable[T]],
    *,
    kwargs_list: list[dict],
) -> Iterable[T]:
    queue: Queue[T] = Queue()
    async_results = [pool.apply_async(_write_generator_to_queue, (queue, func, kwargs)) for kwargs in kwargs_list]
    try:
        while True:
            try:
                yield queue.get(timeout=0.05)
            except Empty:
                if all(async_result.ready() for async_result in async_results) and queue.empty():
                    break
    except KeyboardInterrupt:
        pass
    finally:
        # we get the result in case there's an error to raise
        try:
            [async_result.get(timeout=0.05) for async_result in async_results]
        except multiprocessing.TimeoutError:
            pass

def user_authentication(request: Request):
    # priority: hf_token env var > oauth_info in session > token in bearer header
    # if "oauth_info" in request.session:
    if HF_TOKEN is not None:
        try:
            _ = token_verification(token=os.environ.get("HF_TOKEN"))
            return HF_TOKEN
        except Exception as e:
            logger.error(f"Failed to verify token: {e}")
            if IS_RUNNING_IN_SPACE:
                return templates.TemplateResponse("login.html", {"request": request})
            else:
                raise HTTPException(
                    status_code=status.HTTP_401_UNAUTHORIZED,
                    detail="Invalid or expired token: HF_TOKEN",
                )

    if IS_RUNNING_IN_SPACE and "oauth_info" in request.session:
        try:
            _ = token_verification(token=request.session["oauth_info"]["access_token"])
            return request.session["oauth_info"]["access_token"]
        except Exception as e:
            request.session.pop("oauth_info", None)
            logger.error(f"Failed to verify token: {e}")
            return templates.TemplateResponse("login.html", {"request": request})

    if IS_RUNNING_IN_SPACE:
        return templates.TemplateResponse("login.html", {"request": request})

    raise HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Invalid or expired token",
    )

def get_train_dataloader(self, dataset, adv_dataset, batch_size):
        # TODO: Add pairing option where we can pair original examples with adversarial examples.
        # Helper functions for collating data
        def collate_fn(data):
            input_texts = []
            targets = []
            is_adv_sample = []
            for item in data:
                if "_example_type" in item[0].keys():
                    # Get example type value from OrderedDict and remove it

                    adv = item[0].pop("_example_type")

                    # with _example_type removed from item[0] OrderedDict
                    # all other keys should be part of input
                    _input, label = item
                    if adv != "adversarial_example":
                        raise ValueError(
                            "`item` has length of 3 but last element is not for marking if the item is an `adversarial example`."
                        )
                    else:
                        is_adv_sample.append(True)
                else:
                    # else `len(item)` is 2.
                    _input, label = item
                    is_adv_sample.append(False)

                if isinstance(_input, collections.OrderedDict):
                    _input = tuple(_input.values())
                else:
                    _input = tuple(_input)

                if len(_input) == 1:
                    _input = _input[0]
                input_texts.append(_input)
                targets.append(label)

            return input_texts, torch.tensor(targets), torch.tensor(is_adv_sample)

        if adv_dataset:
            dataset = torch.utils.data.ConcatDataset([dataset, adv_dataset])

        train_dataloader = torch.utils.data.DataLoader(
            dataset,
            batch_size=batch_size,
            shuffle=True,
            collate_fn=collate_fn,
            pin_memory=True,
        )
        return train_dataloader

def search(self, query, type=SPARQL, start=1, count=10, sort=RELEVANCY, size=None, cached=False, **kwargs):
        if type not in (SPARQL,):
            raise SearchEngineTypeError
        if not query or count < 1 or start < 1:
            return Results(DBPEDIA, query, type)
        # 1) Construct request URL.
        url = URL(DBPEDIA, method=GET)
        url.query = {
            "format": "json",
             "query": "%s OFFSET %s LIMIT %s" % (query,
                        (start - 1) * min(count, 1000),
                        (start - 0) * min(count, 1000)
            )
        }
        # 2) Parse JSON response.
        try:
            data = URL(url).download(cached=cached, timeout=30, **kwargs)
            data = json.loads(data)
        except HTTP400BadRequest as e:
            raise DBPediaQueryError(e.src.read().splitlines()[0])
        except HTTP403Forbidden:
            raise SearchEngineLimitError
        results = Results(DBPEDIA, url.query, type)
        results.total = None
        for x in data["results"]["bindings"]:
            r = Result(url=None)
            for k in data["head"]["vars"]:
                t1 = x[k].get("type", "literal") # uri | literal | typed-literal
                t2 = x[k].get("datatype", "?")   # http://www.w3.org/2001/XMLSchema#float | int | date
                v = x[k].get("value")
                v = self.format(v)
                if t1 == "uri":
                    v = DBPediaResource(v)
                if t2.endswith("float"):
                    v = float(v)
                if t2.endswith("int"):
                    v = int(v)
                dict.__setitem__(r, k, v)
            results.append(r)
        return results

def sanitize_json_bigint(
    data: str | dict[str, Any] | list[dict[str, Any]],
    ensure_ascii: bool = True,
) -> str:
    from json import dumps, loads

    def convert_key(key: Any) -> Any:
        # Keys must be str, int, float, bool, or None
        if key is None:
            return key
        if isinstance(key, (str, int, float, bool)):
            return key
        return str(key)

    def convert_bigint(obj: Any) -> Any:
        if isinstance(obj, dict):
            return {convert_key(k): convert_bigint(v) for k, v in obj.items()}  # type: ignore
        elif isinstance(obj, list):
            return [convert_bigint(item) for item in obj]  # type: ignore
        elif isinstance(obj, int) and is_bigint(obj):
            # If the value is outside the safe integer range, convert it to an object with a $bigint key
            # Frontend will convert the object back to an integer.
            return {BIGINT_KEY: str(obj)}
        elif isinstance(obj, float) and is_bigint(obj):
            # Decimals are not handled currently, we just convert them to strings.
            return str(obj)
        else:
            return obj

    if isinstance(data, str):
        as_json = loads(data)
    else:
        as_json = data

    return dumps(
        convert_bigint(as_json),
        indent=None,
        separators=(",", ":"),
        default=enc_hook,
        ensure_ascii=ensure_ascii,
    )

def validate_and_format_dataset(dataset):
    from snips_nlu_parsers import get_all_languages

    if isinstance(dataset, Dataset):
        dataset = dataset.json

    # Make this function idempotent
    if dataset.get(VALIDATED, False):
        return dataset
    dataset = deepcopy(dataset)
    dataset = json.loads(json.dumps(dataset))
    validate_type(dataset, dict, object_label="dataset")
    mandatory_keys = [INTENTS, ENTITIES, LANGUAGE]
    for key in mandatory_keys:
        validate_key(dataset, key, object_label="dataset")
    validate_type(dataset[ENTITIES], dict, object_label="entities")
    validate_type(dataset[INTENTS], dict, object_label="intents")
    language = dataset[LANGUAGE]
    validate_type(language, str, object_label="language")
    if language not in get_all_languages():
        raise DatasetFormatError("Unknown language: '%s'" % language)

    dataset[INTENTS] = {
        intent_name: intent_data
        for intent_name, intent_data in sorted(iteritems(dataset[INTENTS]))}
    for intent in itervalues(dataset[INTENTS]):
        _validate_and_format_intent(intent, dataset[ENTITIES])

    utterance_entities_values = extract_utterance_entities(dataset)
    builtin_entity_parser = BuiltinEntityParser.build(dataset=dataset)

    dataset[ENTITIES] = {
        intent_name: entity_data
        for intent_name, entity_data in sorted(iteritems(dataset[ENTITIES]))}

    for entity_name, entity in iteritems(dataset[ENTITIES]):
        uterrance_entities = utterance_entities_values[entity_name]
        if is_builtin_entity(entity_name):
            dataset[ENTITIES][entity_name] = \
                _validate_and_format_builtin_entity(entity, uterrance_entities)
        else:
            dataset[ENTITIES][entity_name] = \
                _validate_and_format_custom_entity(
                    entity, uterrance_entities, language,
                    builtin_entity_parser)
    dataset[VALIDATED] = True
    return dataset

def image_id_from_k8s() -> str | None:
    token_path = "/var/run/secrets/kubernetes.io/serviceaccount/token"

    if not os.path.exists(token_path):
        return None

    try:
        with open(token_path) as token_file:
            token = token_file.read()
    except FileNotFoundError:
        logger.warning(f"Token file not found at {token_path}.")
        return None
    except PermissionError as e:
        current_uid = os.getuid()
        warning = (
            f"Unable to read the token file at {token_path} due to permission error ({e})."
            f"The current user id is {current_uid}. "
            "Consider changing the securityContext to run the container as the current user."
        )
        logger.warning(warning)
        wandb.termwarn(warning)
        return None

    if not token:
        return None

    import requests

    k8s_server = "https://{}:{}/api/v1/namespaces/{}/pods/{}".format(
        os.getenv("KUBERNETES_SERVICE_HOST"),
        os.getenv("KUBERNETES_PORT_443_TCP_PORT"),
        os.getenv("KUBERNETES_NAMESPACE", "default"),
        os.getenv("HOSTNAME"),
    )
    try:
        res = requests.get(
            k8s_server,
            verify="/var/run/secrets/kubernetes.io/serviceaccount/ca.crt",
            timeout=3,
            headers={"Authorization": f"Bearer {token}"},
        )
        res.raise_for_status()
    except requests.RequestException:
        return None
    try:
        return str(  # noqa: B005
            res.json()["status"]["containerStatuses"][0]["imageID"]
        ).strip("docker-pullable://")
    except (ValueError, KeyError, IndexError):
        logger.exception("Error checking kubernetes for image id")
        return None

def clear_current(self):
        reply = QMessageBox.question(
            self,
            self.tr("Confirm Clear"),
            self.tr("Are you sure you want to clear all current annotations?"),
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No,
        )

        if reply != QMessageBox.StandardButton.Yes:
            return

        for component_data in self.custom_components:
            widget = component_data["widget"]
            comp_type = component_data["type"]

            if comp_type == "QLineEdit":
                widget.clear()
            elif comp_type in ["QRadioButton", "QCheckBox"]:
                layout = widget.layout()
                for i in range(layout.count()):
                    item = layout.itemAt(i)
                    if item and item.widget():
                        item.widget().setChecked(False)
            elif comp_type == "QComboBox":
                widget.setCurrentIndex(0)

        self.save_current_image_data()

def select(self, index=None, delta=None, see=True):
        if (index is not None) and (delta is not None):
            raise ValueError("specify index or delta, but not both")

        # If delta was given, then calculate index.
        if delta is not None:
            if len(self.curselection()) == 0:
                index = -1 + delta
            else:
                index = int(self.curselection()[0]) + delta

        # Clear all selected rows.
        self.selection_clear(0, "end")

        # Select the specified index
        if index is not None:
            index = min(max(index, 0), self.size() - 1)
            # self.activate(index)
            self.selection_set(index)
            if see:
                self.see(index)

def compare_tensors_in_structures(inputs1: Union[List, Dict], inputs2: Union[List, Dict]) -> bool:
    if type(inputs1) != type(inputs2):  # Ensure types match
        return False

    if isinstance(inputs1, list) and isinstance(inputs2, list):
        if len(inputs1) != len(inputs2):
            return False
        for val1, val2 in zip(inputs1, inputs2):
            if isinstance(val1, torch.Tensor) and isinstance(val2, torch.Tensor):
                val1 = val1.to(torch.device(get_accelerator().current_device_name()))
                val2 = val2.to(torch.device(get_accelerator().current_device_name()))
                if not torch.equal(val1, val2):
                    return False
            elif val1 != val2:
                return False
        return True

    elif isinstance(inputs1, dict) and isinstance(inputs2, dict):
        if inputs1.keys() != inputs2.keys():
            return False
        for key in inputs1:
            val1, val2 = inputs1[key], inputs2[key]
            if isinstance(val1, torch.Tensor) and isinstance(val2, torch.Tensor):
                val1 = val1.to(torch.device(get_accelerator().current_device_name()))
                val2 = val2.to(torch.device(get_accelerator().current_device_name()))
                if not torch.equal(val1, val2):
                    return False
            elif val1 != val2:
                return False
        return True

    return False

def parse_icon_name(icon_name: str) -> tuple[str, str, str | None]:
    # Icon names used to use dashes instead of underscores. Replace them so that
    # old code continues to work.
    normalized_icon_name = icon_name.replace("-", "_")

    # Determine the icon set
    sections = normalized_icon_name.split("/")

    if len(sections) == 1:
        icon_set = "material"
        normalized_icon_name = sections[0]
    elif len(sections) == 2:
        icon_set, normalized_icon_name = sections
    else:
        raise AssetError(
            f"Invalid icon name `{icon_name}`. Icons names must be of the form `set/icon:variant`"
        )

    # Determine the icon name and variant
    if ".." in normalized_icon_name or "\\" in normalized_icon_name:
        raise AssetError(
            f"Invalid icon name `{icon_name}`. Traversal characters are not allowed."
        )

    sections = normalized_icon_name.split(":")

    if len(sections) == 1:
        return icon_set, sections[0], None

    if len(sections) == 2:
        return icon_set, sections[0], sections[1]

    raise AssetError(
        f"Invalid icon name `{icon_name}`. Icons names must be of the form `set/icon:variant`"
    )

def nltk_tree(sentence):
    from nltk import tree

    def do_pnp(pnp):
        # Returns the PNPChunk (and the contained Chunk objects) in NLTK bracket format.
        s = ' '.join([do_chunk(ch) for ch in pnp.chunks])
        return '(PNP %s)' % s

    def do_chunk(ch):
        # Returns the Chunk in NLTK bracket format. Recurse attached PNP's.
        s = ' '.join(['(%s %s)' % (w.pos, w.string) for w in ch.words])
        s += ' '.join([do_pnp(pnp) for pnp in ch.attachments])
        return '(%s %s)' % (ch.type, s)

    T = ['(S']
    v = [] # PNP's already visited.
    for ch in sentence.chunked():
        if not ch.pnp and isinstance(ch, Chink):
            T.append('(%s %s)' % (ch.words[0].pos, ch.words[0].string))
        elif not ch.pnp:
            T.append(do_chunk(ch))
        #elif ch.pnp not in v:
        elif ch.pnp.anchor is None and ch.pnp not in v:
            # The chunk is part of a PNP without an anchor.
            T.append(do_pnp(ch.pnp))
            v.append(ch.pnp)
    T.append(')')
    return tree.bracket_parse(' '.join(T))

def start_proc_mask_signal(proc):
    if not isinstance(proc, list):
        proc = [proc]

    with mask_sigint():
        for p in proc:
            if isinstance(p, mp.Process):
                if sys.version_info < (3, 4) or mp.get_start_method() == 'fork':
                    log_once("""
Starting a process with 'fork' method is efficient but not safe and may cause deadlock or crash.
Use 'forkserver' or 'spawn' method instead if you run into such issues.
See https://docs.python.org/3/library/multiprocessing.html#contexts-and-start-methods on how to set them.
""".replace("\n", ""),
'warn')  # noqa
            p.start()

def get_stats(self) -> dict[str, Any]:
        stats = {
            "strategies": self.strategies,
            "primary_strategy": self.strategy,  # For backward compatibility
            "num_actors": len(self.actors),
            "prefix_length": self.prefix_length,
            "overload_threshold": self.overload_threshold,
            "round_robin_index": self._round_robin_index,
            "actor_stats": [],
        }

        try:
            if self.async_vllm is not None:
                request_counts = self.async_vllm.get_num_unfinished_requests()
                cache_usages = self.async_vllm.get_cache_usage()
            else:
                request_futures = [
                    actor.get_num_unfinished_requests.remote() for actor in self.actors
                ]
                cache_futures = [
                    actor.get_cache_usage.remote() for actor in self.actors
                ]
            ray = _get_ray()
            request_counts = ray.get(request_futures)
            cache_usages = ray.get(cache_futures)

            for i, (requests, cache_usage) in enumerate(
                zip(request_counts, cache_usages)
            ):
                stats["actor_stats"].append(
                    {
                        "actor_index": i,
                        "pending_requests": requests,
                        "cache_usage": cache_usage,
                    }
                )

        except Exception as e:
            torchrl_logger.warning(f"Error gathering load balancer stats: {e}")
            stats["error"] = str(e)

        return stats

def pretty_format(self, width=70, prefix="", depth=4):
        # [xx] display default!!
        if self._fname is None:
            n = width - len(prefix) - 15
            return "{}{} {}\n".format(prefix, "." * n, self._label)
        s = ""
        for i, (fval, result) in enumerate(
            sorted(
                self._decisions.items(),
                key=lambda item: (item[0] in [None, False, True], str(item[0]).lower()),
            )
        ):
            hdr = f"{prefix}{self._fname}={fval}? "
            n = width - 15 - len(hdr)
            s += "{}{} {}\n".format(hdr, "." * (n), result._label)
            if result._fname is not None and depth > 1:
                s += result.pretty_format(width, prefix + "  ", depth - 1)
        if self._default is not None:
            n = width - len(prefix) - 21
            s += "{}else: {} {}\n".format(prefix, "." * n, self._default._label)
            if self._default._fname is not None and depth > 1:
                s += self._default.pretty_format(width, prefix + "  ", depth - 1)
        return s

def modify_group_id(
        self,
        updated_gid_info,
        deleted_gid_info: list,
        start_index: int = -1,
        end_index: int = -1,
    ):
        try:
            if start_index == -1:
                start_index = self.start_index
            if end_index == -1:
                end_index = self.end_index
            for i, image_file in enumerate(self.image_file_list):
                if i < start_index - 1 or i > end_index - 1:
                    continue
                label_dir, filename = os.path.split(image_file)
                if self.parent.output_dir:
                    label_dir = self.parent.output_dir
                label_file = os.path.join(
                    label_dir, os.path.splitext(filename)[0] + ".json"
                )
                if not os.path.exists(label_file):
                    continue
                with open(label_file, "r", encoding="utf-8") as f:
                    data = json.load(f)

                src_shapes, dst_shapes = data["shapes"], []
                for shape in reversed(src_shapes):
                    group_id = shape.get("group_id")
                    if group_id is not None:
                        group_id = int(group_id)
                        if group_id in updated_gid_info:
                            shape["group_id"] = updated_gid_info[group_id][
                                "new_gid"
                            ]
                        if group_id in deleted_gid_info:
                            src_shapes.remove(shape)
                            continue
                    dst_shapes.append(shape)
                data["shapes"] = dst_shapes

                with open(label_file, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=2, ensure_ascii=False)

            return True

        except Exception as e:
            logger.error(f"Error occurred while updating Group IDs: {e}")
            return False

def get_term_topics(self, word_id, minimum_probability=None, normalize=None):
        if minimum_probability is None:
            minimum_probability = self.minimum_probability
        minimum_probability = max(minimum_probability, 1e-8)

        # if user enters word instead of id in vocab, change to get id
        if isinstance(word_id, str):
            word_id = self.id2word.doc2bow([word_id])[0][0]

        values = []

        word_topics = self._W[word_id]

        if normalize is None:
            normalize = self.normalize
        if normalize and word_topics.sum() > 0:
            word_topics /= word_topics.sum()

        for topic_id in range(0, self.num_topics):
            word_coef = word_topics[topic_id]

            if word_coef >= minimum_probability:
                values.append((topic_id, word_coef))

        return values

def close_clients(self):
        # keep track of closed clients so we only call .close() once.
        # For most clients, calling .close() multiple times does not throw
        # any errors. However, when using google.cloud.bigquery.dbapi (and
        # possible others), calling .close() many times will throw an error
        closed = []

        for client in self.clients.values():
            if client not in closed:
                client.close()
                closed.append(client)

        for task_name in self._iter():
            task = self[task_name]

            if task.client and task.client not in closed:
                task.client.close()
                closed.append(task.client)

            if task.product.client and task.product.client not in closed:
                task.product.client.close()
                closed.append(task.product.client)

async def save_replicate_token(request: SaveTokenRequest) -> SaveTokenResponse:
    token = request.api_token.strip()

    if not token:
        return SaveTokenResponse(success=False, error="Token cannot be empty")

    # Basic validation - Replicate tokens start with r8_
    if not token.startswith("r8_"):
        return SaveTokenResponse(success=False, error="Invalid token format. Replicate tokens start with 'r8_'")

    secrets_mgr = get_secrets_manager()

    # Save the token
    success = secrets_mgr.set_replicate_token(token)

    if not success:
        return SaveTokenResponse(success=False, error="Failed to save token to file")

    file_path = str(secrets_mgr.get_secrets_file_path())

    # Validate the saved token by trying to connect
    try:
        client = ProviderFactory.get_provider("replicate")
        user_info = await client.validate_credentials()

        if user_info.get("error"):
            # Token saved but validation failed - keep it saved but warn user
            return SaveTokenResponse(
                success=True, file_path=file_path, error=f"Token saved but validation failed: {user_info.get('error')}"
            )

        return SaveTokenResponse(success=True, file_path=file_path)
    except Exception as exc:
        # Token saved but validation failed
        return SaveTokenResponse(success=True, file_path=file_path, error=f"Token saved but validation failed: {exc}")

def layer_description_builder(layer_information, id_to_node):
    layer_type = layer_information[0]

    layer_input_ids = layer_information[1]
    if isinstance(layer_input_ids, Iterable):
        layer_input = list(map(lambda x: id_to_node[x], layer_input_ids))
    else:
        layer_input = id_to_node[layer_input_ids]
    layer_output = id_to_node[layer_information[2]]
    if layer_type.startswith("StubConv"):
        input_channel = layer_information[3]
        filters = layer_information[4]
        kernel_size = layer_information[5]
        stride = layer_information[6]
        return globals()[layer_type](
            input_channel, filters, kernel_size, stride, layer_input, layer_output
        )
    elif layer_type.startswith("StubDense"):
        input_units = layer_information[3]
        units = layer_information[4]
        return globals()[layer_type](input_units, units, layer_input, layer_output)
    elif layer_type.startswith("StubBatchNormalization"):
        num_features = layer_information[3]
        return globals()[layer_type](num_features, layer_input, layer_output)
    elif layer_type.startswith("StubDropout"):
        rate = layer_information[3]
        return globals()[layer_type](rate, layer_input, layer_output)
    elif layer_type.startswith("StubPooling"):
        kernel_size = layer_information[3]
        stride = layer_information[4]
        padding = layer_information[5]
        return globals()[layer_type](kernel_size, stride, padding, layer_input, layer_output)
    else:
        return globals()[layer_type](layer_input, layer_output)

def wrap_results_for_axis(
        self, results: ResType, res_index: Index
    ) -> DataFrame | Series:

        if self.result_type == "reduce":
            # e.g. test_apply_dict GH#8735
            res = self.obj._constructor_sliced(results)
            res.index = res_index
            return res

        elif self.result_type is None and all(
            isinstance(x, dict) for x in results.values()
        ):
            # Our operation was a to_dict op e.g.
            #  test_apply_dict GH#8735, test_apply_reduce_to_dict GH#25196 #37544
            res = self.obj._constructor_sliced(results)
            res.index = res_index
            return res

        try:
            result = self.obj._constructor(data=results)
        except ValueError as err:
            if "All arrays must be of the same length" in str(err):
                # e.g. result = [[2, 3], [1.5], ['foo', 'bar']]
                #  see test_agg_listlike_result GH#29587
                res = self.obj._constructor_sliced(results)
                res.index = res_index
                return res
            else:
                raise

        if not isinstance(results[0], ABCSeries):
            if len(result.index) == len(self.res_columns):
                result.index = self.res_columns

        if len(result.columns) == len(res_index):
            result.columns = res_index

        return result

def kill_children_processes(parent_pids: Optional[Union[
    int, List[Optional[int]]]] = None,
                            force: bool = False) -> None:
    if isinstance(parent_pids, int):
        parent_pids = [parent_pids]

    parent_processes = []
    if parent_pids is None:
        parent_processes = [psutil.Process()]
    else:
        for pid in parent_pids:
            try:
                process = psutil.Process(pid)
            except psutil.NoSuchProcess:
                continue
            parent_processes.append(process)

    for parent_process in parent_processes:
        child_processes = parent_process.children(recursive=True)
        if parent_pids is not None:
            kill_process_with_grace_period(parent_process, force=force)
        logger.debug(f'Killing child processes: {child_processes}')
        for child in child_processes:
            kill_process_with_grace_period(child, force=force)

def get_list_from_env(
    key: str,
    separator: str = ",",
    default: list[T] | None = None,
    *,
    strip_whitespace: bool = True,
    remove_empty: bool = True,
    required: bool = False,
) -> list[str] | list[T]:
    # Get the environment variable value
    env_value = os.environ.get(key)

    # Handle required environment variables
    if required and env_value is None and default is None:
        raise ValueError(f"Required environment variable '{key}' is not set")

    if env_value:
        items = env_value.split(separator)
        if strip_whitespace:
            items = [item.strip() for item in items]
        if remove_empty:
            items = [item for item in items if item]
        return items
    elif default is not None:
        return default
    else:
        return []

def create_model_rate_mapping(self, num_users):
        client_model_rate = []

        if self.model_split_mode == "fix":
            mode_rate, proportion = [], []
            for comp_level_prop in self.model_mode:
                mode_rate.append(self.model_split_rate[comp_level_prop[0]])
                proportion.append(int(comp_level_prop[1:]))
            num_users_proportion = num_users // sum(proportion)
            for i, comp_level in enumerate(mode_rate):
                client_model_rate += np.repeat(
                    comp_level, num_users_proportion * proportion[i]
                ).tolist()
            client_model_rate = client_model_rate + [
                client_model_rate[-1] for _ in range(num_users - len(client_model_rate))
            ]
            # return client_model_rate

        elif self.model_split_mode == "dynamic":
            mode_rate, proportion = [], []

            for comp_level_prop in self.model_mode:
                mode_rate.append(self.model_split_rate[comp_level_prop[0]])
                proportion.append(int(comp_level_prop[1:]))

            proportion = (np.array(proportion) / sum(proportion)).tolist()

            rate_idx = torch.multinomial(
                torch.tensor(proportion), num_samples=num_users, replacement=True
            ).tolist()
            client_model_rate = np.array(mode_rate)[rate_idx]

            # return client_model_rate

        else:
            raise ValueError("Not valid model split mode")

        return client_model_rate

def cache_or_load_file(path, creator, loader):
    if os.path.exists(path):
        return loader(path)

    try:
        os.makedirs(_dataset_root)
    except OSError:
        if not os.path.isdir(_dataset_root):
            raise RuntimeError('cannot create dataset directory')

    lock_path = os.path.join(_dataset_root, '_create_lock')

    with utils.tempdir() as temp_dir:
        file_name = os.path.basename(path)
        temp_path = os.path.join(temp_dir, file_name)
        content = creator(temp_path)
        with filelock.FileLock(lock_path):
            if not os.path.exists(path):
                shutil.move(temp_path, path)

    return content

def measure_statistical(self, circuit, stim_circuit, seed=None):
        # Compute samples via circuits from tableau
        num_shots = circuit.shots.total_shots
        sample_seed = seed if isinstance(seed, int) else self._rng.integers(2**31 - 1, size=1)[0]

        results = []
        for meas in circuit.measurements:
            measurement_func = self._statistical_measurement_map.get(type(meas), None)
            if measurement_func is not None:
                res = measurement_func(meas, stim_circuit, shots=num_shots, seed=sample_seed)
            else:
                # Decide wire order
                meas_wires = meas.wires if meas.wires else range(stim_circuit.num_qubits)
                wire_order = {wire: idx for idx, wire in enumerate(meas.wires)}
                # Decide measurement op
                meas_op = meas.obs or ops.prod(*[ops.Z(idx) for idx in meas_wires])
                samples = self._measure_observable_sample(
                    meas_op, stim_circuit, num_shots, sample_seed
                )[0]
                # Check if the rotation was permissible
                if len(samples) > 1:
                    raise QuantumFunctionError(
                        f"Observable {meas_op.name} is not supported for rotating probabilities on {self.name}."
                    )
                # Process the result from samples
                res = meas.process_samples(samples=np.array(samples), wire_order=wire_order)
                # Post-processing for special cases
                if isinstance(meas, CountsMP):
                    res = res[0]
                elif isinstance(meas, SampleMP):
                    res = np.squeeze(res)

            results.append(res)

        return results

def backbone(backbone_name):
    if 'densenet' in backbone_name:
        from .densenet import DenseNetBackbone as b
    elif 'seresnext' in backbone_name or 'seresnet' in backbone_name or 'senet' in backbone_name:
        from .senet import SeBackbone as b
    elif 'resnet' in backbone_name:
        from .resnet import ResNetBackbone as b
    elif 'mobilenet' in backbone_name:
        from .mobilenet import MobileNetBackbone as b
    elif 'vgg' in backbone_name:
