    elif 'EfficientNet' in backbone_name:
        from .effnet import EfficientNetBackbone as b
    else:
        raise NotImplementedError('Backbone class for  \'{}\' not implemented.'.format(backbone))

    return b(backbone_name)

def setup_lazy_imports(
    lazy_imports: dict[str, str | tuple[str, str | None]],
    module_name: str,
    module_globals: dict[str, Any],
    extra_attrs: dict[str, Callable[[], Any]] | None = None,
) -> tuple[list[str], Callable[[str], Any], Callable[[], list[str]]]:
    # attrs are added to `__all__` of `__init__.py`
    all_names = list(lazy_imports.keys())
    if extra_attrs:
        all_names.extend(extra_attrs.keys())

    # `__getattr__` is called when accessing module / package attributes
    # e.g., `from darts.models import XXX` for the `darts.models` package
    def __getattr__(name: str) -> Any:
        if name in lazy_imports:
            # import attrs from darts package and cache it
            entry = lazy_imports[name]
            if isinstance(entry, str):
                module_path, optional_dep = entry, None
            else:
                module_path, optional_dep = entry

            try:
                module = importlib.import_module(module_path)
                value = getattr(module, name)
            except (ModuleNotFoundError, ImportError):
                # attr is not available; if it is an optional dependency, wrap it in
                # the `NotImportedModule`. Otherwise, raise an exception
                if optional_dep is not None:
                    from darts.utils.utils import NotImportedModule

                    value = NotImportedModule(module_name=optional_dep, warn=False)
                else:
                    raise
        elif extra_attrs is not None and name in extra_attrs:
            # special attrs that are not imported but computed within `__init__.py`
            value = extra_attrs[name]()
        else:
            raise AttributeError(f"module {module_name!r} has no attribute {name!r}")

        # cache the attr under globals to only invoke `__getattr__` only once per name
        module_globals[name] = value
        return value

    # attrs are added to `__dir__` of `__init__.py`
    def __dir__() -> list[str]:
        return all_names

    return all_names, __getattr__, __dir__

def tool_handling(self):
        # Convert all the tools into a list of dictionaries
        user_tools = (
            convert_multiple_functions_to_openai_function_schema(
                self.tools
            )
        )

        # Preserve existing tools in tools_list_dictionary (e.g., handoff tools)
        if self.tools_list_dictionary is None:
            self.tools_list_dictionary = []

        # Get existing tool names to avoid duplicates
        existing_tool_names = set()
        for tool in self.tools_list_dictionary:
            if isinstance(tool, dict) and "function" in tool:
                existing_tool_names.add(
                    tool["function"].get("name", "")
                )

        # Add user tools, avoiding duplicates
        for tool in user_tools:
            tool_name = tool.get("function", {}).get("name", "")
            if tool_name not in existing_tool_names:
                self.tools_list_dictionary.append(tool)
                existing_tool_names.add(tool_name)

        self.short_memory.add(
            role=self.agent_name,
            content=self.tools_list_dictionary,
        )

def slice_1d(self, dim: int, indices: Sequence[int]):
        if dim == 0:
            # slicing along the host dimension
            host_ids = [self.host_ids[x] for x in indices]
            host_info = [self.host_info[x] for x in host_ids]
            return VirtualPhysicalMesh(
                host_ids=host_ids,
                host_info=host_info,
                num_devices_per_host=self.num_devices_per_host,
                parent=self)
        else:
            # slicing along the device dimension

            # Check the validity of device_indices
            for i in range(len(indices)):
                for x in indices[i]:
                    assert x in self.devices[i]

            return VirtualPhysicalMesh(host_ids=self.host_ids,
                                       host_info=self.host_info,
                                       num_devices_per_host=len(indices[0]),
                                       parent=self,
                                       devices=indices)

async def exception_to_crashed_state(
    exc: BaseException,
    result_store: Optional["ResultStore"] = None,
) -> State:
    state_message = None

    if isinstance(exc, anyio.get_cancelled_exc_class()):
        state_message = "Execution was cancelled by the runtime environment."

    elif isinstance(exc, KeyboardInterrupt):
        state_message = "Execution was aborted by an interrupt signal."

    elif isinstance(exc, TerminationSignal):
        state_message = "Execution was aborted by a termination signal."

    elif isinstance(exc, SystemExit):
        state_message = "Execution was aborted by Python system exit call."

    elif isinstance(exc, (httpx.TimeoutException, httpx.ConnectError)):
        try:
            request: httpx.Request = exc.request
        except RuntimeError:
            # The request property is not set
            state_message = (
                "Request failed while attempting to contact the server:"
                f" {format_exception(exc)}"
            )
        else:
            # TODO: We can check if this is actually our API url
            state_message = f"Request to {request.url} failed: {format_exception(exc)}."

    else:
        state_message = (
            "Execution was interrupted by an unexpected exception:"
            f" {format_exception(exc)}"
        )

    if result_store:
        key = uuid.uuid4().hex
        data = result_store.create_result_record(exc, key=key)
    else:
        # Attach the exception for local usage, will not be available when retrieved
        # from the API
        data = exc

    return Crashed(message=state_message, data=data)

def get_param_to_custom_artifact_class(func: Callable) -> Dict[str, type]:
    param_to_artifact_cls: Dict[str, type] = {}
    kfp_artifact_classes = set(type_utils.ARTIFACT_CLASSES_MAPPING.values())

    signature = inspect.signature(func)
    for name, param in signature.parameters.items():
        annotation = param.annotation
        if type_annotations.is_Input_Output_artifact_annotation(annotation):
            artifact_class = type_annotations.get_io_artifact_class(annotation)
            if artifact_class not in kfp_artifact_classes:
                param_to_artifact_cls[name] = artifact_class
        elif type_annotations.issubclass_of_artifact(annotation):
            if annotation not in kfp_artifact_classes:
                param_to_artifact_cls[name] = artifact_class

    return_annotation = signature.return_annotation

    if return_annotation is inspect.Signature.empty:
        pass

    elif type_utils.is_typed_named_tuple_annotation(return_annotation):
        for name, annotation in return_annotation.__annotations__.items():
            if type_annotations.is_artifact_class(
                    annotation) and annotation not in kfp_artifact_classes:
                param_to_artifact_cls[f'{RETURN_PREFIX}{name}'] = annotation

    elif type_annotations.is_artifact_class(
            return_annotation
    ) and return_annotation not in kfp_artifact_classes:
        param_to_artifact_cls[RETURN_PREFIX] = return_annotation

    return param_to_artifact_cls

def log_deprecated(name="", text="", eos="", max_num_warnings=None):
    assert name or text
    if eos:
        eos = "after " + datetime(*map(int, eos.split("-"))).strftime("%d %b")
    if name:
        if eos:
            warn_msg = "%s will be deprecated %s. %s" % (name, eos, text)
        else:
            warn_msg = "%s was deprecated. %s" % (name, text)
    else:
        warn_msg = text
        if eos:
            warn_msg += " Legacy period ends %s" % eos

    if max_num_warnings is not None:
        if _DEPRECATED_LOG_NUM[warn_msg] >= max_num_warnings:
            return
        _DEPRECATED_LOG_NUM[warn_msg] += 1
    logger.warn("[Deprecated] " + warn_msg)

def get_donatable_intermediate(stages: Sequence[JaxPipelineComputation],
                               worker_stage_mapping, global_invars):
    global_invars = OrderedSet(global_invars)
    main_copy_at = {}
    stage_at = {}
    for mesh_idx, stage_indices in worker_stage_mapping.items():
        for stage_idx in stage_indices:
            stage = stages[stage_idx]
            for outvar in stage.outvars:
                main_copy_at[outvar] = mesh_idx
            stage_at[stage_idx] = mesh_idx

    donatable_list = []
    used = OrderedSet()
    for stage_idx in reversed(range(len(stages))):
        stage = stages[stage_idx]
        donatable = OrderedSet()
        for invar in stage.invars:
            if invar in global_invars:
                continue  # do not consider global inputs
            if main_copy_at[invar] != stage_at[stage_idx]:
                donatable.add(invar)  # not a main copy
            if invar not in used:
                donatable.add(invar)  # is a main copy never used
        used.update(stage.invars)
        donatable_list.append(donatable)
    donatable_list = list(reversed(donatable_list))
    return donatable_list

def list_agents() -> list[dict]:
    results: list[dict] = []

    # User-registered agents
    for name, info in sorted(_load_user_agents().items()):
        results.append(
            {
                "name": name,
                "source": "registered",
                "description": "",
                "module": info["import_path"],
            }
        )

    # Built-in agents from catalog
    seen_names = {r["name"] for r in results}
    try:
        catalog = _load_agent_catalog()
    except (FileNotFoundError, json.JSONDecodeError):
        catalog = {}

    for name, info in sorted(catalog.get("agents", {}).items()):
        if name not in seen_names:
            results.append(
                {
                    "name": name,
                    "source": "built-in",
                    "description": info.get("description", ""),
                    "module": f"{info.get('module', '')}.{info.get('function', '')}",
                }
            )

    # Plugin agents from entry points
    seen_names = {r["name"] for r in results}
    eps = entry_points(group="rllm.agents")
    for ep in eps:
        if ep.name not in seen_names:
            pkg = ep.dist.name if ep.dist else "unknown"
            results.append(
                {
                    "name": ep.name,
                    "source": f"plugin ({pkg})",
                    "description": "",
                    "module": str(ep.value),
                }
            )

    return results

def from_nested_to_2d_array(X, return_numpy=False):
    # TODO does not handle dataframes with nested series columns *and*
    #  standard columns containing only primitives

    # convert nested data into tabular data
    if isinstance(X, pd.Series):
        Xt = np.array(X.tolist())

    elif isinstance(X, pd.DataFrame):
        try:
            Xt = np.hstack([X.iloc[:, i].tolist() for i in range(X.shape[1])])

        # except strange key error for specific case
        except KeyError:
            if (X.shape == (1, 1)) and (X.iloc[0, 0].shape == (1,)):
                # in fact only breaks when an additional condition is met,
                # namely that the index of the time series of a single value
                # does not start with 0, e.g. pd.RangeIndex(9, 10) as is the
                # case in forecasting
                Xt = X.iloc[0, 0].values
            else:
                raise

        if Xt.ndim != 2:
            raise ValueError(
                "Tabularization failed, it's possible that not "
                "all series were of equal length"
            )

    else:
        raise ValueError(
            f"Expected input is pandas Series or pandas DataFrame, but found: {type(X)}"
        )

    if return_numpy:
        return Xt

    Xt = pd.DataFrame(Xt)

    # create column names from time index
    if X.ndim == 1:
        time_index = (
            X.iloc[0].index
            if hasattr(X.iloc[0], "index")
            else np.arange(X.iloc[0].shape[0])
        )
        columns = [f"{X.name}__{i}" for i in time_index]

    else:
        columns = []
        for colname, col in X.items():
            time_index = (
                col.iloc[0].index
                if hasattr(col.iloc[0], "index")
                else np.arange(col.iloc[0].shape[0])
            )
            columns.extend([f"{colname}__{i}" for i in time_index])

    Xt.index = X.index
    Xt.columns = columns
    return Xt

def assumptions(self):
        assumptions = self._command.assumptions()

        domain = list(get_domain(self._command.goal(), assumptions))

        # build a dictionary of obvious equalities
        eq_sets = SetHolder()
        for a in assumptions:
            if isinstance(a, EqualityExpression):
                av = a.first.variable
                bv = a.second.variable
                # put 'a' and 'b' in the same set
                eq_sets[av].add(bv)

        new_assumptions = []
        for i, a in enumerate(domain):
            for b in domain[i + 1 :]:
                # if a and b are not already in the same equality set
                if b not in eq_sets[a]:
                    newEqEx = EqualityExpression(
                        VariableExpression(a), VariableExpression(b)
                    )
                    if Prover9().prove(newEqEx, assumptions):
                        # we can prove that the names are the same entity.
                        # remember that they are equal so we don't re-check.
                        eq_sets[a].add(b)
                    else:
                        # we can't prove it, so assume unique names
                        new_assumptions.append(-newEqEx)

        return assumptions + new_assumptions

def make_prompt_and_parameters(
    tokenizer: transformers.PreTrainedTokenizer,
    work_request: inference.WorkRequest,
) -> tuple[str, interface.GenerateStreamParameters]:
    if settings.oa_protocol_version != "v2":
        raise RuntimeError(f"Unsupported oa protocol version: {settings.oa_protocol_version}")

    eos_token = ""
    if special_tokens["end"]:
        eos_token = special_tokens["end"]
    elif hasattr(tokenizer, "eos_token"):
        eos_token = tokenizer.eos_token

    def _prepare_message(message: inference.MessageRead) -> str:
        prefix = special_tokens["assistant"] if message.is_assistant else special_tokens["prompter"]
        return prefix + message.content + eos_token

    # Construct prompt
    messages = [_prepare_message(message) for message in work_request.thread.messages]

    # Prepend system prompt and custom_instructions if it was specified in work parameters
    work_params = work_request.parameters
    if work_params.system_prompt or work_params.user_profile or work_params.user_response_instructions:
        pre_prompt = special_tokens["system"] + (work_params.system_prompt or "")

        if work_params.user_profile or work_params.user_response_instructions:
            pre_prompt = f"""{pre_prompt}\n{CUSTOM_INSTRUCTIONS_PREFIX.format(user_profile=work_params.user_profile or "", user_response_instructions=work_params.user_response_instructions or "")}"""

        pre_prompt = pre_prompt + eos_token
        messages = [pre_prompt] + messages

    # Stringify and append assistant prefix to signify start of generation
    prompt = "".join(messages) + special_tokens["assistant"]

    parameters = interface.GenerateStreamParameters.from_work_parameters(work_request.parameters)
    if settings.use_stop_sequences:
        parameters.stop = [
            special_tokens["prompter"],
            special_tokens["assistant"],
            special_tokens["system"],
        ]
        if eos_token:
            parameters.stop.append(eos_token)
    else:
        parameters.stop = []

    return prompt, parameters

def unit_action(self, cmd, pos, shift):
    action = sc_pb.Action()
    if self._raw_actions:
      unit_command = action.action_raw.unit_command
      unit_command.ability_id = cmd.ability_id
      unit_command.queue_command = shift
      player_id = self._obs.observation.player_common.player_id
      unit_command.unit_tags.extend([u.tag for u, _ in self._visible_units()
                                     if u.is_selected and u.owner == player_id])
      if pos:
        for u, p in reversed(list(self._visible_units())):
          if pos.world_pos.contained_circle(p, u.radius):
            unit_command.target_unit_tag = u.tag
            break
        else:
          pos.world_pos.assign_to(unit_command.target_world_space_pos)
    else:
      if pos:
        action_spatial = pos.action_spatial(action)
        unit_command = action_spatial.unit_command
        unit_command.ability_id = cmd.ability_id
        unit_command.queue_command = shift
        if pos.surf.surf_type & SurfType.SCREEN:
          pos.obs_pos.assign_to(unit_command.target_screen_coord)
        elif pos.surf.surf_type & SurfType.MINIMAP:
          pos.obs_pos.assign_to(unit_command.target_minimap_coord)
      else:
        if self._feature_screen_px:
          action.action_feature_layer.unit_command.ability_id = cmd.ability_id
        else:
          action.action_render.unit_command.ability_id = cmd.ability_id

    self.clear_queued_action()
    return action

def reorder_encoder_out(self, encoder_out, new_order):
        # if encoder_out["last_hidden_state"] is None:
        if 'last_hidden_state' not in encoder_out:
            new_encoder_out = None
        else:
            new_encoder_out = encoder_out['last_hidden_state'].index_select(
                0, new_order)
        # if encoder_out["padding_mask"] is None:
        if 'padding_mask' not in encoder_out:
            new_encoder_padding_mask = None
        else:
            new_encoder_padding_mask = encoder_out[
                'padding_mask'].index_select(0, new_order)

        # if encoder_out["position_embedding"] is None:
        if 'position_embedding' not in encoder_out:
            new_position_embeddings = None
        else:
            new_position_embeddings = encoder_out[
                'position_embedding'].index_select(0, new_order)

        if 'hidden_states' not in encoder_out:
            new_encoer_states = None
        else:
            encoder_states = encoder_out['hidden_states']
            new_encoer_states = ()
            if len(encoder_states) > 0:
                for idx, state in enumerate(encoder_states):
                    new_encoer_states += (state.index_select(0, new_order), )

        if 'attentions' not in encoder_out:
            attentions = None
        else:
            attentions = encoder_out['attentions']

        return OFAEncoderOutput(
            last_hidden_state=new_encoder_out,  # B x T x C
            padding_mask=new_encoder_padding_mask,  # B x T
            hidden_states=new_encoer_states,  # List[T x B x C]
            attentions=attentions,
            position_embedding=new_position_embeddings  # B x T x C
        )

def iou_distance(atracks: list, btracks: list) -> np.ndarray:
    if (atracks and isinstance(atracks[0], np.ndarray)) or (btracks and isinstance(btracks[0], np.ndarray)):
        atlbrs = atracks
        btlbrs = btracks
    else:
        atlbrs = [track.xywha if track.angle is not None else track.xyxy for track in atracks]
        btlbrs = [track.xywha if track.angle is not None else track.xyxy for track in btracks]

    ious = np.zeros((len(atlbrs), len(btlbrs)), dtype=np.float32)
    if len(atlbrs) and len(btlbrs):
        if len(atlbrs[0]) == 5 and len(btlbrs[0]) == 5:
            ious = batch_probiou(
                np.ascontiguousarray(atlbrs, dtype=np.float32),
                np.ascontiguousarray(btlbrs, dtype=np.float32),
            ).numpy()
        else:
            ious = bbox_ioa(
                np.ascontiguousarray(atlbrs, dtype=np.float32),
                np.ascontiguousarray(btlbrs, dtype=np.float32),
                iou=True,
            )
    return 1 - ious  # cost matrix

def json2parameter(ss_spec, random_state):
    if isinstance(ss_spec, dict):
        if NodeType.TYPE in ss_spec.keys():
            _type = ss_spec[NodeType.TYPE]
            _value = ss_spec[NodeType.VALUE]
            if _type == 'choice':
                _index = random_state.randint(len(_value))
                chosen_params = json2parameter(ss_spec[NodeType.VALUE][_index], random_state)
            else:
                chosen_params = getattr(parameter_expressions, _type)(*(_value + [random_state]))
        else:
            chosen_params = dict()
            for key in ss_spec.keys():
                chosen_params[key] = json2parameter(ss_spec[key], random_state)
    elif isinstance(ss_spec, list):
        chosen_params = list()
        for _, subspec in enumerate(ss_spec):
            chosen_params.append(json2parameter(subspec, random_state))
    else:
        chosen_params = copy.deepcopy(ss_spec)
    return chosen_params

def get_fields_from_store_url(
        cls, store_url: str
    ) -> Tuple['StoreType', str, str, Optional[str], Optional[str]]:
        # The full path from the user config of IBM COS contains the region,
        # and Azure Blob Storage contains the storage account name, we need to
        # pass these information to the store constructor.
        storage_account_name = None
        region = None
        for store_type in StoreType:
            if store_url.startswith(store_type.store_prefix()):
                if store_type == StoreType.AZURE:
                    storage_account_name, bucket_name, sub_path = \
                        data_utils.split_az_path(store_url)
                elif store_type == StoreType.IBM:
                    bucket_name, sub_path, region = data_utils.split_cos_path(
                        store_url)
                elif store_type == StoreType.GCS:
                    bucket_name, sub_path = data_utils.split_gcs_path(store_url)
                else:
                    # Check compatible stores
                    for compatible_store_type, store_class in \
                        _S3_COMPATIBLE_STORES.items():
                        if store_type.value == compatible_store_type:
                            config = store_class.get_config()
                            bucket_name, sub_path = config.split_path(store_url)
                            break
                    else:
                        # If we get here, it's an unknown S3-compatible store
                        raise ValueError(
                            f'Unknown S3-compatible store type: {store_type}')
                return store_type, bucket_name, \
                    sub_path, storage_account_name, region
        raise ValueError(f'Unknown store URL: {store_url}')

def mutate_user_tags_for_run(
        cls, flow_id, run_id, tags_to_remove=None, tags_to_add=None
    ):
        # perform common validation, across all provider implementations
        if tags_to_remove is None:
            tags_to_remove = []
        if tags_to_add is None:
            tags_to_add = []
        if not tags_to_add and not tags_to_remove:
            raise MetaflowTaggingError("Must add or remove at least one tag")

        if is_stringish(tags_to_add):
            raise MetaflowTaggingError("tags_to_add may not be a string")

        if is_stringish(tags_to_remove):
            raise MetaflowTaggingError("tags_to_remove may not be a string")

        def _is_iterable(something):
            try:
                iter(something)
                return True
            except TypeError:
                return False

        if not _is_iterable(tags_to_add):
            raise MetaflowTaggingError("tags_to_add must be iterable")
        if not _is_iterable(tags_to_remove):
            raise MetaflowTaggingError("tags_to_remove must be iterable")

        # check each tag is valid
        for tag in chain(tags_to_add, tags_to_remove):
            validate_tag(tag)

        # onto subclass implementation
        final_user_tags = cls._mutate_user_tags_for_run(
            flow_id, run_id, tags_to_add=tags_to_add, tags_to_remove=tags_to_remove
        )
        return final_user_tags

def prepare_dataset(self, datasets: Union[Any, List[Any]]) -> Any:
        if not isinstance(datasets, (list, tuple)):
            datasets = [datasets]
        if self.mode == 'train':
            if len(datasets) == 1:
                return datasets[0]
            elif all([
                    isinstance(dataset, (Dataset, IterableDataset))
                    for dataset in datasets
            ]):
                dataset = concatenate_datasets(list(datasets))
                return dataset.shuffle(seed=self.seed)
            else:
                generator = np.random.default_rng(self.seed)
                _len = sum([len(dataset) for dataset in datasets])
                self.permutation = generator.permutation(_len)
            return super().prepare_dataset(datasets)
        else:
            self.datasets = datasets
            return self.datasets[0]

def construct_value(type_info: Dict[str, Union[str, Optional[str]]], value: Any) -> Any:
    type_name = type_info['name']

    if 'path' in type_info and 'variable_type' in type_info:
        return deserialize_custom_complex_objects(
            value,
            str(type_info['path']),
            VariableType(type_info['variable_type']),
        )

    if isinstance(value, pd.DataFrame):
        return pd.DataFrame(value)
    elif isinstance(value, pd.Series):
        return pd.Series(value)
    elif isinstance(value, pl.DataFrame):
        return pl.DataFrame(value)
    elif isinstance(value, pl.Series):
        return pl.Series(value)
    elif 'Timestamp' == type_name:
        return pd.Timestamp(value)
    elif 'datetime' == type_name:
        return datetime.fromisoformat(value)
    elif 'ndarray' == type_name:
        return np.array(value)
    elif 'DataFrame' == type_name and not isinstance(value, str):
        return pd.DataFrame(value)
    elif 'Series' == type_name and not isinstance(value, str):
        return pd.Series(value)
    elif 'tuple' == type_name:
        return tuple(value)
    elif 'set' == type_name:
        return set(value)
    elif 'int' == type_name:
        return int(value)
    elif 'float' == type_name:
        return float(value)
    elif 'str' == type_name:
        return str(value)
    elif 'bool' == type_name:
        return bool(value)
    elif not isinstance(value, str):
        # For simplicity, assuming direct values don't need complex deserialization
        module_name = type_info['module']
        class_name = type_info['name']
        module = importlib.import_module(str(module_name))
        class_ = getattr(module, str(class_name))
        return class_(value)

    return value

def compute(
        self,
        retrieved_contexts: List[List[str]],
        gt_contexts: List[List[str]],
    ) -> EvaluationResult:
        if len(retrieved_contexts) != len(gt_contexts):
            raise ValueError(
                "The number of retrieved context lists and ground truth context lists should be the same."
            )
        k = len(retrieved_contexts[0])
        metric_list = []
        for retrieved_context, gt_context in zip(retrieved_contexts, gt_contexts):

            metric = self.compute_single_item(retrieved_context, gt_context)
            metric_list.append(metric)

        # average through each key value

        avg_recall = sum([metric["recall"] for metric in metric_list]) / len(
            metric_list
        )
        avg_precision = sum([metric["precision"] for metric in metric_list]) / len(
            metric_list
        )

        return {
            "avg_recall": avg_recall,
            "avg_precision": avg_precision,
            "recall_list": [metric["recall"] for metric in metric_list],
            "precision_list": [metric["precision"] for metric in metric_list],
            "top_k": k,
        }

def edit_section(self, stdscr, tab_name: str, section_id: str) -> None:
        nav = MenuNavigator(stdscr)
        section_title = section_id.replace("_", " ").title()

        while True:
            fields, sections, _ = self._get_tab_structure(tab_name)
            section_fields = [field for field in fields if field.get("section_id") == section_id]

            if not section_fields:
                self.show_message(stdscr, "No fields available for this section with the current context.")
                return

            title_lookup = next((section.get("title") for section in sections if section["id"] == section_id), None)
            display_title = title_lookup or section_title

            menu_items: List[tuple[str, Any]] = []
            current_values: Dict[str, str] = {}

            for field in section_fields:
                label = field.get("label") or field["name"]
                if field.get("subsection"):
                    label = f"{label} [{field['subsection'].replace('_', ' ').title()}]"
                menu_items.append((label, partial(self.edit_field, tab_name=tab_name, field_name=field["name"])))
                current_values[label] = self._format_field_value(field)

            menu_key: Tuple[str, str] = (tab_name, section_id)
            last_selected = self._field_menu_indices.get(menu_key, 0)
            if menu_items:
                last_selected = max(0, min(last_selected, len(menu_items) - 1))
            else:
                last_selected = 0

            choice = nav.show_menu(display_title, menu_items, current_values, selected=last_selected)
            self._field_menu_indices[menu_key] = nav.last_selection

            if choice == -1:
                if self.confirm_quit(stdscr):
                    raise KeyboardInterrupt
            elif choice == -2:
                return
            else:
                menu_items[choice][1](stdscr)

def on_fit_epoch_end(self, vals, epoch, best_fitness, fi):
        x = dict(zip(self.keys, vals))
        if self.csv:
            file = self.save_dir / "results.csv"
            n = len(x) + 1  # number of cols
            s = "" if file.exists() else (("%20s," * n % tuple(["epoch", *self.keys])).rstrip(",") + "\n")  # add header
            with open(file, "a") as f:
                f.write(s + ("%20.5g," * n % tuple([epoch, *vals])).rstrip(",") + "\n")

        if self.tb:
            for k, v in x.items():
                self.tb.add_scalar(k, v, epoch)
        elif self.clearml:  # log to ClearML if TensorBoard not used
            for k, v in x.items():
                title, series = k.split("/")
                self.clearml.task.get_logger().report_scalar(title, series, v, epoch)

        if self.wandb:
            if best_fitness == fi:
                best_results = [epoch, *vals[3:7]]
                for i, name in enumerate(self.best_keys):
                    self.wandb.wandb_run.summary[name] = best_results[i]  # log best results in the summary
            self.wandb.log(x)
            self.wandb.end_epoch()

        if self.clearml:
            self.clearml.current_epoch_logged_images = set()  # reset epoch image limit
            self.clearml.current_epoch += 1

        if self.comet_logger:
            self.comet_logger.on_fit_epoch_end(x, epoch=epoch)

def drop_missing_from_df(df, drop_missing, predict_steps, n_lags):
    if not drop_missing:
        return df
    if n_lags == 0:
        return df
    while pd.isnull(df["y"][:-predict_steps]).any():
        window = []
        all_nan_idx = df[:-predict_steps].loc[df["y"][:-predict_steps].isnull()].index
        if len(all_nan_idx) > 0:
            for i in range(len(all_nan_idx)):
                window.append(all_nan_idx[i])
                # last window of NaNs has been detected
                if all_nan_idx.max() == all_nan_idx[i]:
                    break
                # detect one NaN window (=consecutive NaNs) at a time
                if all_nan_idx[i + 1] - all_nan_idx[i] > 1:
                    break
            # drop NaN window
            df = df.drop(df.index[window[0] : window[-1] + 1]).reset_index(drop=True)
            # drop lagged values if window does not occur at the beginning of df
            if window[0] - (n_lags - 1) >= 0:
                df = df.drop(df.index[(window[0] - (n_lags - 1)) : window[0]]).reset_index(drop=True)
    return df

def export_and_count_categories(
        self,
    ) -> Dict[str, int]:
        try:
            # Extract input and output messages
            input_messages = []
            output_messages = []

            for message in self.conversation_history:
                # Get message content and ensure it's a string
                content = message.get("content", "")
                if not isinstance(content, str):
                    content = str(content)

                # Sort messages by category
                category = message.get("category", "")
                if category == "input":
                    input_messages.append(content)
                elif category == "output":
                    output_messages.append(content)

            # Join messages with spaces
            all_input_text = " ".join(input_messages)
            all_output_text = " ".join(output_messages)

            print(all_input_text)
            print(all_output_text)

            # Count tokens only if there is text
            input_tokens = (
                count_tokens(
                    all_input_text, self.tokenizer_model_name
                )
                if all_input_text.strip()
                else 0
            )
            output_tokens = (
                count_tokens(
                    all_output_text, self.tokenizer_model_name
                )
                if all_output_text.strip()
                else 0
            )
            total_tokens = input_tokens + output_tokens

            return {
                "input_tokens": input_tokens,
                "output_tokens": output_tokens,
                "total_tokens": total_tokens,
            }

        except Exception as e:
            logger.error(
                f"Error in export_and_count_categories: {str(e)}"
            )
            return {
                "input_tokens": 0,
                "output_tokens": 0,
                "total_tokens": 0,
            }

def from_arrays(
        cls,
        arrays,
        sortorder: int | None = None,
        names: Sequence[Hashable] | Hashable | lib.NoDefault = lib.no_default,
    ) -> MultiIndex:
        error_msg = "Input must be a list / sequence of array-likes."
        if not is_list_like(arrays):
            raise TypeError(error_msg)
        if is_iterator(arrays):
            arrays = list(arrays)

        # Check if elements of array are list-like
        for array in arrays:
            if not is_list_like(array):
                raise TypeError(error_msg)

        # Check if lengths of all arrays are equal or not,
        # raise ValueError, if not
        for i in range(1, len(arrays)):
            if len(arrays[i]) != len(arrays[i - 1]):
                raise ValueError("all arrays must be same length")

        codes, levels = factorize_from_iterables(arrays)
        if names is lib.no_default:
            names = [getattr(arr, "name", None) for arr in arrays]

        return cls(
            levels=levels,
            codes=codes,
            sortorder=sortorder,
            names=names,
            verify_integrity=False,
        )

def check_X(
    X,
    enforce_univariate=False,
    enforce_min_instances=1,
    enforce_min_columns=1,
    coerce_to_numpy=False,
    coerce_to_pandas=False,
):
    # check input type
    if coerce_to_pandas and coerce_to_numpy:
        raise ValueError(
            "`coerce_to_pandas` and `coerce_to_numpy` cannot both be set to True"
        )

    if not isinstance(X, VALID_X_TYPES):
        raise ValueError(
            f"X must be a pd.DataFrame or a np.array, but found: {type(X)}"
        )

    # check np.array
    # check first if we have the right number of dimensions, otherwise we
    # may not be able to get the shape of the second dimension below
    if isinstance(X, np.ndarray):
        if X.ndim == 2:
            X = X.reshape(X.shape[0], 1, X.shape[1])
        elif X.ndim == 1 or X.ndim > 3:
            raise ValueError(
                f"If passed as a np.array, X must be a 2 or 3-dimensional "
                f"array, but found shape: {X.shape}"
            )
        if coerce_to_pandas:
            X = from_3d_numpy_to_nested(X)

    # enforce minimum number of columns
    n_columns = X.shape[1]
    if n_columns < enforce_min_columns:
        raise ValueError(
            f"X must contain at least: {enforce_min_columns} columns, "
            f"but found only: {n_columns}."
        )

    # enforce univariate data
    if enforce_univariate and n_columns > 1:
        raise ValueError(
            f"X must be univariate with X.shape[1] == 1, but found: "
            f"X.shape[1] == {n_columns}."
        )

    # enforce minimum number of instances
    if enforce_min_instances > 0:
        _enforce_min_instances(X, min_instances=enforce_min_instances)

    # check pd.DataFrame
    if isinstance(X, pd.DataFrame):
        if not _is_nested_dataframe(X):
            raise ValueError(
                "If passed as a pd.DataFrame, X must be a nested "
                "pd.DataFrame, with pd.Series or np.arrays inside cells."
            )
        # convert pd.DataFrame
        if coerce_to_numpy:
            X = from_nested_to_3d_numpy(X)

    return X

def fetch_df_by_index(
    df: pd.DataFrame,
    selector: Union[pd.Timestamp, slice, str, list, pd.Index],
    level: Union[str, int],
    fetch_orig=True,
) -> pd.DataFrame:
    # level = None -> use selector directly
    if level is None or isinstance(selector, pd.MultiIndex):
        return df.loc(axis=0)[selector]
    # Try to get the right index
    idx_slc = (selector, slice(None, None))
    if get_level_index(df, level) == 1:
        idx_slc = idx_slc[1], idx_slc[0]
    if fetch_orig:
        for slc in idx_slc:
            if slc != slice(None, None):
                return df.loc[pd.IndexSlice[idx_slc],]  # noqa: E231
        else:  # pylint: disable=W0120
            return df
    else:
        return df.loc[pd.IndexSlice[idx_slc],]  # noqa: E231

def concatenate(cls, tables, axis=0, *, ignore_domains=None):
        if axis not in (0, 1):
            raise ValueError("invalid axis")
        if ignore_domains is not None and axis != 0:
            raise ValueError("'ignore_domains' is incompatible with 'axis=1'")
        if not tables:
            raise ValueError('need at least one table to concatenate')

        if len(tables) == 1:
            return tables[0].copy()
        if axis == 0:
            conc = cls._concatenate_vertical(tables, bool(ignore_domains))
        else:
            conc = cls._concatenate_horizontal(tables)

        # TODO: Add attributes = {} to __init__
        conc.attributes = getattr(conc, "attributes", {})
        for table in reversed(tables):
            conc.attributes.update(table.attributes)

        names = [table.name for table in tables if table.name != "untitled"]
        if names:
            conc.name = names[0]
        return conc

def perturb_box(box, min_iou=0.5, sigma_factor=0.1):
    if isinstance(sigma_factor, list):
        # If list, sample one sigma_factor as current sigma factor
        c_sigma_factor = random.choice(sigma_factor)
    else:
        c_sigma_factor = sigma_factor

    if not isinstance(c_sigma_factor, torch.Tensor):
        c_sigma_factor = c_sigma_factor * torch.ones(4)

    perturb_factor = torch.sqrt(box[2] * box[3]) * c_sigma_factor

    # multiple tries to ensure that the perturbed box has iou > min_iou with the input box
    for i_ in range(100):
        c_x = box[0] + 0.5 * box[2]
        c_y = box[1] + 0.5 * box[3]
        c_x_per = random.gauss(c_x, perturb_factor[0])
        c_y_per = random.gauss(c_y, perturb_factor[1])

        w_per = random.gauss(box[2], perturb_factor[2])
        h_per = random.gauss(box[3], perturb_factor[3])

        if w_per <= 1:
            w_per = box[2] * rand_uniform(0.15, 0.5)

        if h_per <= 1:
            h_per = box[3] * rand_uniform(0.15, 0.5)

        box_per = torch.Tensor([c_x_per - 0.5 * w_per, c_y_per - 0.5 * h_per, w_per, h_per]).round()

        if box_per[2] <= 1:
            box_per[2] = box[2] * rand_uniform(0.15, 0.5)

        if box_per[3] <= 1:
            box_per[3] = box[3] * rand_uniform(0.15, 0.5)

        box_iou = iou(box.view(1, 4), box_per.view(1, 4))

        # if there is sufficient overlap, return
        if box_iou > min_iou:
            return box_per, box_iou

        # else reduce the perturb factor
        perturb_factor *= 0.9

    return box_per, box_iou

def save_tabpfn_model(
    model: TabPFNRegressor | TabPFNClassifier,
    save_path: Path | str | list[Path | str],
    additional_fields: dict[str, Any] | None = None,
) -> None:
    if len(model.models_) > 1 and (
        not isinstance(save_path, list) or len(save_path) != len(model.models_)
    ):
        raise ValueError(
            f"Your TabPFN estimator has multiple internal models ({len(model.models_)})"
            f", so you must provide a list of {len(model.models_)} save paths."
        )

    models = model.models_

    znorm_space_bardist = None
    if (
        hasattr(model, "znorm_space_bardist_")
        and model.znorm_space_bardist_ is not None  # type: ignore
    ):
        znorm_space_bardist = model.znorm_space_bardist_  # type: ignore

    configs = model.configs_
    save_paths = save_path if isinstance(save_path, list) else [save_path]

    for ens_model, config, path in zip(
        models,
        configs,
        save_paths,
    ):
        model_state = ens_model.state_dict()

        if znorm_space_bardist is not None:
            bardist_state = {
                f"criterion.{k}": v for k, v in znorm_space_bardist.state_dict().items()
            }
            state_dict = {**model_state, **bardist_state}
        else:
            state_dict = model_state

        architecture_name = _resolve_architecture_name(config)
        checkpoint = {
            "state_dict": state_dict,
            "config": asdict(config),
            "architecture_name": architecture_name,
        }

        if additional_fields is not None:
            checkpoint.update(additional_fields)

        torch.save(checkpoint, path)

def persist_config_bundle(bundle: TrainingConfigBundle) -> None:
    store = bundle.store
    state_store = bundle.state_store
    webui_defaults = bundle.webui_defaults

    if bundle.defaults_changed and state_store:
        state_store.save_defaults(webui_defaults)

    if bundle.save_options.get("create_backup", False):
        config_path = store._get_config_path(bundle.active_config)
        if config_path.exists():
            import shutil

            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_path = config_path.with_suffix(f".json.backup-{timestamp}")
            shutil.copy2(config_path, backup_path)
            logger.info("Created backup at %s", backup_path)

    store.save_trainer_config(bundle.active_config, bundle.save_config, overwrite=True)

    literal_scientific_keys = {
        key: value
        for key, value in bundle.save_config.items()
        if key in {"learning_rate", "lr_end"}
        and isinstance(value, str)
        and re.fullmatch(r"^-?\d+(?:\.\d+)?(?:[eE]-?\d+)$", value)
    }

    if literal_scientific_keys:
        config_path = store._get_config_path(bundle.active_config)
        try:
            contents = config_path.read_text(encoding="utf-8")
        except Exception:
            contents = ""

        if contents:
            for key, literal in literal_scientific_keys.items():
                pattern = re.compile(rf'("{re.escape(key)}"\s*:\s*)"{re.escape(literal)}"')

                def _replace(match, value=literal):
                    return f"{match.group(1)}{value}"

                contents = pattern.sub(_replace, contents)

            config_path.write_text(contents, encoding="utf-8")

    try:
        _load_active_config_cached.clear_cache()
    except AttributeError:
        pass

    if not store.get_active_config():
        store.set_active_config(bundle.active_config)

    APIState.set_state("training_config", bundle.complete_config)

def infer_type(field: FieldInfo, missing_value_percent: float, row_count: int) -> str:
    if field.dtype == DATE or field.dtype.startswith("datetime"):
        return DATE

    num_distinct_values = field.num_distinct_values
    distinct_values = field.distinct_values

    if num_distinct_values <= 1:
        return CATEGORY

    if num_distinct_values == 2 and missing_value_percent == 0:
        # Check that all distinct values are conventional bools.
        if strings_utils.are_conventional_bools(distinct_values):
            return BINARY

    if field.image_values >= 3:
        return IMAGE

    if field.audio_values >= 3:
        return AUDIO

    if strings_utils.are_all_datetimes(distinct_values):
        return DATE

    # Use CATEGORY if:
    # - The number of distinct values is significantly less than the total number of examples.
    # - The distinct values are not all numbers.
    # - The distinct values are all numbers but comprise of a perfectly sequential list of integers that suggests the
    #   values represent categories.
    valid_row_count = row_count * (1.0 - missing_value_percent)
    if num_distinct_values < valid_row_count * CATEGORY_TYPE_DISTINCT_VALUE_PERCENTAGE_CUTOFF and (
        (not strings_utils.are_all_numbers(distinct_values)) or strings_utils.are_sequential_integers(distinct_values)
    ):
        return CATEGORY

    # Use NUMBER if all of the distinct values are numbers.
    if strings_utils.are_all_numbers(distinct_values):
        return NUMBER

    # TODO (ASN): add other modalities (image, etc. )
    # Fallback to TEXT.
    return TEXT

def tvm_wrap_excepthook(exception_hook):
    def wrapper(exctype, value, trbk):
        """Clean subprocesses when TVM is interrupted."""
        if exctype is error.DiagnosticError and not _should_print_backtrace():
            # TODO(@jroesch): consider moving to C++?
            print("note: run with `TVM_BACKTRACE=1` environment variable to display a backtrace.")
        else:
            exception_hook(exctype, value, trbk)

        if hasattr(multiprocessing, "active_children"):
            # pylint: disable=not-callable
            for p in multiprocessing.active_children():
                p.terminate()

    return wrapper

def print_results(
    bench_results: list[dict[str, Any]], sort_by: str = "WxTime(ms)", desc: bool = True
):
    # pylint: disable=invalid-name, import-outside-toplevel
    try:
        import pandas as pd

        df = pd.DataFrame()
        for record in bench_results:
            df = pd.concat(
                [df, pd.DataFrame(record, index=[0])],
                ignore_index=True,
            )
        if sort_by is not None:
            if sort_by not in df.columns:
                raise ValueError(f"sort_by key {sort_by} not in benchmark results")
            df = df.sort_values(sort_by, ascending=not desc).reset_index().drop("index", axis=1)
        print(df)
    except ModuleNotFoundError:
        print("Pandas not found, printing results in raw format.")
        keys = []
        if len(bench_results) > 0:
            for key in bench_results[0]:
                keys.append(str(key))
        print("\t".join(keys))
        for record in bench_results:
            values = []
            for key in keys:
                values.append(str(record[key]))
            print("\t".join(values))
    print("\n")

def load_nnvocoder(
    cfg,
    vocoder_name,
    weights_file,
    from_multi_gpu=False,
):
    print("Loading Vocoder from Weights file: {}".format(weights_file))

    # Build model
    model = _vocoders[vocoder_name](cfg)
    if not os.path.isdir(weights_file):
        # Load from .pt file
        if vocoder_name in ["bigvgan", "hifigan", "melgan", "nsfhifigan"]:
            ckpt = torch.load(
                weights_file,
                map_location=(
                    torch.device("cuda")
                    if torch.cuda.is_available()
                    else torch.device("cpu")
                ),
            )
            if from_multi_gpu:
                pretrained_generator_dict = ckpt["generator_state_dict"]
                generator_dict = model.state_dict()

                new_generator_dict = {
                    k.split("module.")[-1]: v
                    for k, v in pretrained_generator_dict.items()
                    if (
                        k.split("module.")[-1] in generator_dict
                        and v.shape == generator_dict[k.split("module.")[-1]].shape
                    )
                }

                generator_dict.update(new_generator_dict)

                model.load_state_dict(generator_dict)
            else:
                model.load_state_dict(ckpt["generator_state_dict"])
        else:
            model.load_state_dict(torch.load(weights_file)["state_dict"])
    else:
        # Load from accelerator state dict
        weights_file = os.path.join(weights_file, "checkpoint")
        ls = [str(i) for i in Path(weights_file).glob("*") if not "audio" in str(i)]
        ls.sort(key=lambda x: int(x.split("_")[-3].split("-")[-1]), reverse=True)
        checkpoint_path = ls[0]
        accelerator = accelerate.Accelerator()
        model = accelerator.prepare(model)
        accelerator.load_state(checkpoint_path)

    if torch.cuda.is_available():
        model = model.cuda()

    model = model.eval()
    return model

def is_tensor(x):
    if is_torch_fx_proxy(x):
        return True
    if is_torch_available():
        import torch

        if isinstance(x, torch.Tensor):
            return True
    if is_tf_available():
        import tensorflow as tf

        if isinstance(x, tf.Tensor):
            return True

    if is_flax_available():
        import jax.numpy as jnp
        from jax.core import Tracer

        if isinstance(x, (jnp.ndarray, Tracer)):
            return True

    return isinstance(x, np.ndarray)

def max_models_from_num_samples_val(
    num_samples_val: int,
    points: PointsSpec = ((100, 3), (10_000, 25), (100_000, 100), None),
    *,
    rounding: str = "floor",  # "round" | "floor" | "ceil"
) -> Optional[int]:
    anchors, tail_none = _parse_points_spec(points)

    n = int(num_samples_val)
    if n <= 0:
        # conservative default: first anchor's value
        return anchors[0][1]

    # Tail behavior
    last_n, last_m = anchors[-1]
    if tail_none and n > last_n:
        return None

    # Clamp below first anchor
    first_n, first_m = anchors[0]
    if n <= first_n:
        return first_m

    # Find segment [i, i+1] such that anchors[i].n < n <= anchors[i+1].n
    for (n0, y0), (n1, y1) in zip(anchors, anchors[1:]):
        if n <= n1:
            y = _interp_loglog(n, n0, y0, n1, y1)

            if rounding == "floor":
                out = int(math.floor(y))
            elif rounding == "ceil":
                out = int(math.ceil(y))
            else:
                out = int(round(y))
            lo, hi = sorted((y0, y1))
            return max(lo, min(hi, out))

    # If we got here: n > last_n and tail_none is False => clamp to last
    return last_m

def resolve_weights(smartirs):
    if isinstance(smartirs, str) and re.match(r"...\....", smartirs):
        match = re.match(r"(?P<ddd>...)\.(?P<qqq>...)", smartirs)
        raise ValueError(
            "The notation {ddd}.{qqq} specifies two term-weighting schemes, "
            "one for collection documents ({ddd}) and one for queries ({qqq}). "
            "You must train two separate tf-idf models.".format(
                ddd=match.group("ddd"),
                qqq=match.group("qqq"),
            )
        )
    if not isinstance(smartirs, str) or len(smartirs) != 3:
        raise ValueError("Expected a string of length 3 got " + smartirs)

    w_tf, w_df, w_n = smartirs

    if w_tf not in 'btnaldL':
        raise ValueError("Expected term frequency weight to be one of 'btnaldL', got {}".format(w_tf))

    if w_df not in 'xnftp':
        raise ValueError("Expected inverse document frequency weight to be one of 'xnftp', got {}".format(w_df))

    if w_n not in 'xncub':
        raise ValueError("Expected normalization weight to be one of 'xncub', got {}".format(w_n))

    # resolve aliases
    if w_tf == "t":
        w_tf = "n"
    if w_df == "x":
        w_df = "n"
    if w_n == "x":
        w_n = "n"

    return w_tf + w_df + w_n

def find_placeholders(template: T) -> set[Placeholder]:
    seed: set[Placeholder] = set()
    if isinstance(template, (int, float, bool)):
        return seed
    if isinstance(template, str):
        result = PLACEHOLDER_CAPTURE_REGEX.findall(template)
        return {
            Placeholder(full_match, name, determine_placeholder_type(name))
            for full_match, name in result
        }
    elif isinstance(template, dict):
        return seed.union(*[find_placeholders(value) for value in template.values()])
    elif isinstance(template, list):
        return seed.union(*[find_placeholders(item) for item in template])
    else:
        raise ValueError(f"Unexpected type: {type(template)}")

def connect(self, task: "Task", name: Optional[str] = None, **kwargs: Any) -> None:
        if self._task != task:
            raise ValueError("Can only connect preexisting model to task, but this is a fresh model")

        if name:
            self._task_connect_name = name

        # we should set the task input model to point to us
        model = self._get_base_model()

        # only copy the model design if the task has no design to begin with
        # noinspection PyProtectedMember
        if not self._task._get_model_config_text():
            # noinspection PyProtectedMember
            task._set_model_config(
                config_text=model.model_design if hasattr(model, "model_design") else model.design.get("design", "")
            )
        if not self._task.get_labels_enumeration():
            task.set_model_label_enumeration(model.data.labels if hasattr(model, "data") else model.labels)

        if self._base_model:
            self._base_model.update_for_task(
                task_id=self._task.id,
                model_id=self.id,
                type_="output",
                name=self._task_connect_name,
            )

def log_state_dict_report(
    model,
    pretrained_model_name_or_path: str,
    ignore_mismatched_sizes: bool,
    loading_info: LoadStateDictInfo,
    logger: logging.Logger | None = None,
):
    if logger is None:
        logger = logging.getLogger(__name__)

    # Re-raise errors early if needed
    if loading_info.error_msgs:
        error_msg = "\n\t".join(loading_info.error_msgs)
        if "size mismatch" in error_msg:
            error_msg += (
                "\n\tYou may consider adding `ignore_mismatched_sizes=True` to `from_pretrained(...)` if appropriate."
            )
        raise RuntimeError(f"Error(s) in loading state_dict for {model.__class__.__name__}:\n\t{error_msg}")

    # Create the report table
    report = loading_info.create_loading_report()
    if report is None:
        return

    prelude = f"{PALETTE['bold']}{model.__class__.__name__} LOAD REPORT{PALETTE['reset']} from: {pretrained_model_name_or_path}\n"

    # Log the report as warning
    logger.warning(prelude + report)

    # Re-raise in those case, after the report
    if loading_info.conversion_errors:
        raise RuntimeError(
            "We encountered some issues during automatic conversion of the weights. For details look at the `CONVERSION` entries of "
            "the above report!"
        )
    if not ignore_mismatched_sizes and loading_info.mismatched_keys:
        raise RuntimeError(
            "You set `ignore_mismatched_sizes` to `False`, thus raising an error. For details look at the above report!"
        )

def copy_into(self, destination, override_attributes=False):
    newly_created_elements = {}
    destination._check_valid_attachment(self._source)  # pylint: disable=protected-access
    if override_attributes:
      destination.set_attributes(**self._source.get_attributes())
    else:
      destination._sync_attributes(self._source, copying=True)  # pylint: disable=protected-access
    for source_child in self._source.all_children():
      dest_child = None
      # First, if source_child has an identifier, we look for an existing child
      # element of self with the same identifier to override.
      if source_child.spec.identifier and override_attributes:
        identifier_attr = source_child.spec.identifier
        if identifier_attr == constants.CLASS:
          identifier_attr = constants.DCLASS
        identifier = getattr(source_child, identifier_attr)
        if identifier:
          dest_child = destination.find(source_child.spec.namespace, identifier)
        if dest_child is not None and dest_child.parent is not destination:
          raise ValueError(
              '<{}> with identifier {!r} is already a child of another element'
              .format(source_child.spec.namespace, identifier))
      # Next, we cover the case where either the child is not a repeated element
      # or if source_child has an identifier attribute but it isn't set.
      if not source_child.spec.repeated and dest_child is None:
        dest_child = destination.get_children(source_child.tag)

      # Add a new element if dest_child doesn't exist, either because it is
      # supposed to be a repeated child, or because it's an uncreated on-demand.
      if dest_child is None:
        dest_child = destination.add(
            source_child.tag, **source_child.get_attributes())
        newly_created_elements[source_child] = dest_child
        override_child_attributes = True
      else:
        override_child_attributes = override_attributes

      # Finally, copy attributes into dest_child.
      child_copier = Copier(source_child)
      newly_created_elements.update(
          child_copier.copy_into(dest_child, override_child_attributes))
    return newly_created_elements

def estimator_spec_eval(
      self, features, logits, labels, loss, restore_hook, use_tpu):
    hparams = self.hparams
    problem = hparams.problem
    if logits.get_shape().ndims == 3:
      logits = tf.expand_dims(tf.expand_dims(logits, 2), 3)

    # Support for multiproblem
    task_list = [problem]
    if hasattr(problem, "task_list"):
      task_list = problem.task_list

    eval_metrics_fns = metrics.create_evaluation_metrics(task_list, hparams)

    if use_tpu:
      def metric_fn(tf_logits, labels):
        with tf.device("cpu:0"), mtf.utils.outside_all_rewrites():
          eval_metrics = {}
          for metric_name, metric_fn in six.iteritems(eval_metrics_fns):
            if metric_name.split("/")[-1] not in t2t_model.TPU_METRIC_BLACKLIST:
              eval_metrics[metric_name] = metric_fn(
                  tf_logits, None, tf.identity(labels))
          return eval_metrics
      return tpu_estimator.TPUEstimatorSpec(
          tf_estimator.ModeKeys.EVAL,
          evaluation_hooks=[restore_hook],
          loss=loss,
          eval_metrics=(metric_fn, [logits, labels]))
    else:
      eval_metrics = {}
      predictions = {"predictions": logits}
      for metric_name, metric_fn in six.iteritems(eval_metrics_fns):
        eval_metrics[metric_name] = metric_fn(logits, features,
                                              features["targets"])

      return tf_estimator.EstimatorSpec(
          tf_estimator.ModeKeys.EVAL,
          predictions=predictions,
          eval_metric_ops=eval_metrics,
          evaluation_hooks=[restore_hook],
          loss=loss)

def list_conversations(
        cls, conversations_dir: Optional[str] = None
    ) -> List[Dict[str, str]]:
        conv_dir = conversations_dir or get_conversation_dir()
        if not os.path.exists(conv_dir):
            return []

        conversations = []
        seen_ids = (
            set()
        )  # Track seen conversation IDs to avoid duplicates

        for filename in os.listdir(conv_dir):
            if filename.endswith(".json"):
                try:
                    filepath = os.path.join(conv_dir, filename)
                    with open(filepath) as f:
                        data = json.load(f)
                        metadata = data.get("metadata", {})
                        conv_id = metadata.get("id")
                        name = metadata.get("name")
                        created_at = metadata.get("created_at")

                        # Skip if we've already seen this ID or if required fields are missing
                        if (
                            not all([conv_id, name, created_at])
                            or conv_id in seen_ids
                        ):
                            continue

                        seen_ids.add(conv_id)
                        conversations.append(
                            {
                                "id": conv_id,
                                "name": name,
                                "created_at": created_at,
                                "filepath": filepath,
                            }
                        )
                except json.JSONDecodeError:
                    logger.warning(
                        f"Skipping corrupted conversation file: {filename}"
                    )
                    continue
                except Exception as e:
                    logger.error(
                        f"Failed to read conversation {filename}: {str(e)}"
                    )
                    continue

        # Sort by creation date, newest first
        return sorted(
            conversations, key=lambda x: x["created_at"], reverse=True
        )

def schedule(self, task):
        with self.lock:
            for task_existing in self.tasks:
                if (task_existing.df == task.df) and task_existing.fingerprint() == task.fingerprint():
                    key = task.fingerprint()
                    logger.debug("Did not add already existing task with fingerprint: %r", key)
                    return task_existing

            if vaex.cache.is_on() and task.cacheable:
                key = task.fingerprint()                
                logger.debug("task fingerprint: %r (dataset fp=%r)", key, task.df.dataset.fingerprint)
                logger.debug("task repr: %r", task)
                result = vaex.cache.get(key, type="task")
                if result is not None:
                    logger.info("task not added, used cache key: %r", key)
                    task.fulfill(result)
                    return task
                else:
                    logger.info("task *will* be scheduled with cache key: %r", key)
            if task not in self.tasks:
                self.tasks.append(task)
                logger.info("task added, queue: %r", self.tasks)
                return task

def axis_shape_dims_for_broadcast_in_dim(axis, input_shape, insert_dims):
    if axis is None:
        raise ValueError("Received `None` value for `axis`")
    if isinstance(axis, int):
        axis = (axis,)
    # Check uniqueness.
    if len(set(axis)) != len(axis):
        raise ValueError(f"Repeated axis in `axis`: {axis}")
    result_dims = len(input_shape)
    if insert_dims:
        result_dims += len(axis)

    # Resolve negative values.
    canonical_axis = []
    for a in axis:
        if not -result_dims <= a < result_dims:
            raise ValueError(
                f"In `axis`, axis {a} is out of bounds for array "
                f"of dimension {result_dims}"
            )
        if a < 0:
            a = a + result_dims
        canonical_axis.append(a)

    # Check uniqueness again after resolving negative values.
    if len(set(canonical_axis)) != len(canonical_axis):
        raise ValueError(f"Repeated axis in `axis`: {canonical_axis}")
    canonical_axis = sorted(canonical_axis)

    # Compute output shape.
    output_shape = list(input_shape)
    for i in canonical_axis:
        if insert_dims:
            output_shape.insert(i, 1)
        else:
            output_shape[i] = 1
    broadcast_dims = [i for i in range(result_dims) if i not in canonical_axis]
    return canonical_axis, output_shape, broadcast_dims

def get_object_lineage_graph(
        self, registry: Registry, object_type: str, object_name: str, depth: int = 2
    ) -> Dict:
        direct_relationships, indirect_relationships = self.generate_lineage(registry)
        all_relationships = direct_relationships + indirect_relationships

        # Build adjacency graph
        graph: Dict[str, List[str]] = {}
        for rel in all_relationships:
            source_key = f"{rel.source.type.value}:{rel.source.name}"
            target_key = f"{rel.target.type.value}:{rel.target.name}"

            if source_key not in graph:
                graph[source_key] = []
            graph[source_key].append(target_key)

        # Perform BFS to get subgraph up to specified depth
        start_key = f"{object_type}:{object_name}"
        visited = set()
        result_nodes = set()
        result_edges = []

        def bfs(current_key, current_depth):
            if current_depth > depth or current_key in visited:
                return

            visited.add(current_key)
            result_nodes.add(current_key)

            if current_key in graph:
                for neighbor in graph[current_key]:
                    result_edges.append((current_key, neighbor))
                    result_nodes.add(neighbor)
                    bfs(neighbor, current_depth + 1)

        bfs(start_key, 0)

        return {"nodes": list(result_nodes), "edges": result_edges}

def batch_encode_candidates(self, text, **kwargs):
        # Always using a fixed sequence length to encode in order to stack candidates into a batch.
        kwargs["padding"] = PaddingStrategy.MAX_LENGTH

        batch_text = text
        batch_text_pair = kwargs.pop("text_pair", None)
        return_tensors = kwargs.pop("return_tensors", None)

        output_data = {
            "input_ids": [],
            "attention_mask": [],
            "token_type_ids": [],
        }

        for idx, candidate_text in enumerate(batch_text):
            if batch_text_pair is not None:
                candidate_text_pair = batch_text_pair[idx]
            else:
                candidate_text_pair = None

            encoded_candidates = super().__call__(candidate_text, candidate_text_pair, return_tensors=None, **kwargs)

            encoded_input_ids = encoded_candidates.get("input_ids")
            encoded_attention_mask = encoded_candidates.get("attention_mask")
            encoded_token_type_ids = encoded_candidates.get("token_type_ids")

            if encoded_input_ids is not None:
                output_data["input_ids"].append(encoded_input_ids)
            if encoded_attention_mask is not None:
                output_data["attention_mask"].append(encoded_attention_mask)
            if encoded_token_type_ids is not None:
                output_data["token_type_ids"].append(encoded_token_type_ids)

        output_data = dict((key, item) for key, item in output_data.items() if len(item) != 0)

        return BatchEncoding(output_data, tensor_type=return_tensors)

def fd_to_np(x, method='column_stack', axis=None, dtype=None):
    assert isinstance(x, OrderedDict), 'expected a feature dictionary'

    # passthrough if a feature
    if len(x) == 1:
        k = list(x.keys())[0]
        if dtype:
            return sparse_to_dense(x[k]).astype(dtype)
        return x[k]

    feature_names = list(x.keys())

    # shape of first feature
    # to ensure the leading dimensions are equal across features
    first_shape = None

    # check shapes and ensure everything is an ndarray
    for feature in feature_names:
        if isinstance(x[feature], np.ndarray):
            pass
        elif isinstance(x[feature], list):
            x[feature] = np.array(x[feature])
        elif isinstance(x[feature], scipy.sparse.csr_matrix):
            x[feature] = sparse_to_dense(x[feature])
        else:
            raise ValueError(
                'Unsupported container tensor type in feature dict: {}'.format(
                    str(type(x[feature]))
                )
            )
        if first_shape is None:
            first_shape = x[feature].shape
        assert first_shape[0] == x[feature].shape[0], 'incompatible shapes: {}, {}'.format(
            first_shape, x[feature].shape
        )
    if method == 'column_stack':
        out = np.column_stack([(x[key]) for key in x])
    elif method == 'stack':
        if axis:
            out = np.stack([(x[key]) for key in x], axis=axis)
        else:
            out = np.stack([(x[key]) for key in x], axis=-2)
    else:
        raise ValueError('unsupported method {}'.format(method))
    if dtype:
        return out.astype(dtype)
    return out

def forward(self, hidden_states, cls_index=None):
        if self.summary_type == 'last':
            output = hidden_states[:, -1]
        elif self.summary_type == 'first':
            output = hidden_states[:, 0]
        elif self.summary_type == 'mean':
            output = hidden_states.mean(dim=1)
        elif self.summary_type == 'cls_index':
            if cls_index is None:
                cls_index = torch.full_like(hidden_states[..., :1, :], hidden_states.shape[-2]-1, dtype=torch.long)
            else:
                cls_index = cls_index.unsqueeze(-1).unsqueeze(-1)
                cls_index = cls_index.expand((-1,) * (cls_index.dim()-1) + (hidden_states.size(-1),))
            # shape of cls_index: (bsz, XX, 1, hidden_size) where XX are optional leading dim of hidden_states
            output = hidden_states.gather(-2, cls_index).squeeze(-2) # shape (bsz, XX, hidden_size)
        elif self.summary_type == 'attn':
            raise NotImplementedError

        output = self.first_dropout(output)
        output = self.summary(output)
        output = self.activation(output)
        output = self.last_dropout(output)

        return output

def retrieve_model_classes(model_type: str, frameworks: Optional[List[str]] = None) -> Dict[str, List[str]]:
    if frameworks is None:
        frameworks = get_default_frameworks()

    modules = {
        "pt": auto_module.modeling_auto if is_torch_available() else None,
        "tf": auto_module.modeling_tf_auto if is_tf_available() else None,
        "flax": auto_module.modeling_flax_auto if is_flax_available() else None,
    }

    model_classes = {}
    for framework in frameworks:
        new_model_classes = []
        if modules[framework] is None:
            raise ValueError(f"You selected {framework} in the frameworks, but it is not installed.")
        model_mappings = [attr for attr in dir(modules[framework]) if _re_model_mapping.search(attr) is not None]
        for model_mapping_name in model_mappings:
            model_mapping = getattr(modules[framework], model_mapping_name)
            if model_type in model_mapping:
                new_model_classes.append(model_mapping[model_type])

        if len(new_model_classes) > 0:
            # Remove duplicates
            model_classes[framework] = list(set(new_model_classes))

    return model_classes

def from_task_and_inputs(
        cls,
        task: "Task[Any, Any]",
        task_run_id: UUID,
        task_inputs: Optional[dict[str, set[Any]]] = None,
        copy_to_child_ctx: bool = False,
    ) -> "AssetContext":
        from prefect.client.schemas import TaskRunResult
        from prefect.tasks import MaterializingTask

        upstream_assets: set[Asset] = set()

        flow_ctx = FlowRunContext.get()
        if task_inputs and flow_ctx:
            for name, inputs in task_inputs.items():
                # Parent task runs are not dependencies
                # that we want to track
                if name == "__parents__":
                    continue

                for task_input in inputs:
                    if isinstance(task_input, TaskRunResult):
                        task_assets = flow_ctx.task_run_assets.get(task_input.id)
                        if task_assets:
                            upstream_assets.update(task_assets)

        ctx = cls(
            direct_asset_dependencies=set(task.asset_deps)
            if task.asset_deps
            else set(),
            downstream_assets=set(task.assets)
            if isinstance(task, MaterializingTask) and task.assets
            else set(),
            upstream_assets=upstream_assets,
            materialized_by=task.materialized_by
            if isinstance(task, MaterializingTask)
            else None,
            task_run_id=task_run_id,
            copy_to_child_ctx=copy_to_child_ctx,
        )
        ctx.update_tracked_assets()

        return ctx

def variable_res_collate(batch: List[Dict]) -> Dict:
    images = []
    imgdata_lists = defaultdict(list)
    for data in batch:
        image = data.pop("image")
        images.append(image)
        topop = []
        for key, val in data.items():
            if isinstance(val, torch.Tensor):
                # if the value has same height and width as the image, assume that it should be collated accordingly.
                if len(val.shape) >= 2 and val.shape[:2] == image.shape[:2]:
                    imgdata_lists[key].append(val)
                    topop.append(key)
        # now that iteration is complete, the image data items can be removed from the batch
        for key in topop:
            del data[key]
    new_batch = nerfstudio_collate(batch)
    new_batch["image"] = images
    new_batch.update(imgdata_lists)

    return new_batch

async def send(
        self,
        content: BidiInputEvent | ToolResultEvent,
    ) -> None:
        if not self._connection_id:
            raise RuntimeError("model not started | call start before sending/receiving")

        if isinstance(content, BidiTextInputEvent):
            await self._send_text_content(content.text)
        elif isinstance(content, BidiAudioInputEvent):
            await self._send_audio_content(content)
        elif isinstance(content, BidiImageInputEvent):
            await self._send_image_content(content)
        elif isinstance(content, ToolResultEvent):
            tool_result = content.get("tool_result")
            if tool_result:
                await self._send_tool_result(tool_result)
        else:
            raise ValueError(f"content_type={type(content)} | content not supported")

def averaging_mechanism(averaging_method: str, scores_per_class, weights=None) -> Union[np.ndarray, float]:
    if averaging_method == 'binary':
        if len(scores_per_class) != 2:
            raise DeepchecksValueError('Averaging method "binary" can only be used in binary classification.')
        return scores_per_class[1]
    elif averaging_method == 'per_class':
        return np.asarray(scores_per_class)
    elif averaging_method == 'macro':
        # Classes that did not appear in the data are not considered as part of macro averaging.
        return np.mean(scores_per_class) if weights is None else np.mean(scores_per_class[weights != 0])
    elif averaging_method == 'weighted':
        if weights is None:
            raise DeepchecksValueError('Weights are required in order to apply weighted averaging method.')
        return np.multiply(scores_per_class, weights).sum() / sum(weights)
    else:
        raise DeepchecksValueError(f'Unknown averaging {averaging_method}')

def log_images(self, files, name="Images", epoch=0):
        files = [Path(f) for f in (files if isinstance(files, (tuple, list)) else [files])]  # to Path
        files = [f for f in files if f.exists()]  # filter by exists

        if self.tb:
            for f in files:
                self.tb.add_image(f.stem, cv2.imread(str(f))[..., ::-1], epoch, dataformats="HWC")

        if self.wandb:
            self.wandb.log({name: [wandb.Image(str(f), caption=f.name) for f in files]}, step=epoch)

def create_storage_config_from_env(user_config: Dict[str, Any]):
    from bindu.common.models import StorageConfig

    # Check if user already provided storage config
    if "storage" in user_config:
        storage_dict = user_config["storage"]
        storage_type = storage_dict.get("type")
        if storage_type not in ("postgres", "memory"):
            logger.warning(f"Invalid storage type: {storage_type}, using memory")
            storage_type = "memory"
        return StorageConfig(
            type=storage_type,
            database_url=storage_dict.get("postgres_url"),
        )

    # Load from environment
    storage_type = os.getenv("STORAGE_TYPE")
    if not storage_type:
        return None

    if storage_type not in ("postgres", "memory"):
        logger.warning(f"Invalid storage type: {storage_type}, using memory")
        storage_type = "memory"

    logger.debug(f"Loaded STORAGE_TYPE from environment: {storage_type}")

    # Get database URL from environment
    database_url = None
    if storage_type == "postgres":
        database_url = os.getenv("DATABASE_URL")
        if database_url:
            logger.debug("Loaded DATABASE_URL from environment")

    return StorageConfig(
        type=cast(Literal["postgres", "memory"], storage_type),
        database_url=database_url,
    )

def align_blocks(source_sents_lens, target_sents_lens, params=LanguageIndependent):
    alignment_types = list(params.PRIORS.keys())

    # there are always three rows in the history (with the last of them being filled)
    D = [[]]

    backlinks = {}

    for i in range(len(source_sents_lens) + 1):
        for j in range(len(target_sents_lens) + 1):
            min_dist = float("inf")
            min_align = None
            for a in alignment_types:
                prev_i = -1 - a[0]
                prev_j = j - a[1]
                if prev_i < -len(D) or prev_j < 0:
                    continue
                p = D[prev_i][prev_j] + align_log_prob(
                    i, j, source_sents_lens, target_sents_lens, a, params
                )
                if p < min_dist:
                    min_dist = p
                    min_align = a

            if min_dist == float("inf"):
                min_dist = 0

            backlinks[(i, j)] = min_align
            D[-1].append(min_dist)

        if len(D) > 2:
            D.pop(0)
        D.append([])

    return trace(backlinks, source_sents_lens, target_sents_lens)

def validate_view_content(view_dict: dict, variety: CollectionViewVariety) -> None:
    if variety == "flow":
        schema = flow_schema
    elif variety == "worker":
        schema = worker_schema
    elif variety == "block":
        schema = block_schema
    else:
        raise ValueError(f"Invalid variety: {variety}")

    validate = fastjsonschema.compile(schema)

    for collection_name, collection_metadata in view_dict.items():
        if variety == "block":
            collection_metadata = collection_metadata["block_types"]
        try:
            # raise validation errors if any metadata doesn't match the schema
            list(map(validate, collection_metadata.values()))
        except IndexError:  # to catch something like {"prefect-X": {}}
            raise ValueError("There's a key with empty value in this view!")
        print(f"  Validated {collection_name} summary in {variety} view!")

def get_tightbbox(self, renderer=None, *, call_axes_locator=True,
                      bbox_extra_artists=None, for_layout_only=False):

        bb = []
        if renderer is None:
            renderer = self.get_figure(root=True)._get_renderer()

        if not self.get_visible():
            return None

        locator = self.get_axes_locator()
        self.apply_aspect(
            locator(self, renderer) if locator and call_axes_locator else None)

        for axis in self._axis_map.values():
            if self.axison and axis.get_visible():
                ba = martist._get_tightbbox_for_layout_only(axis, renderer)
                if ba:
                    bb.append(ba)
        self._update_title_position(renderer)
        axbbox = self.get_window_extent(renderer)
        bb.append(axbbox)

        for title in [self.title, self._left_title, self._right_title]:
            if title.get_visible():
                bt = title.get_window_extent(renderer)
                if for_layout_only and bt.width > 0:
                    # make the title bbox 1 pixel wide so its width
                    # is not accounted for in bbox calculations in
                    # tight/constrained_layout
                    bt.x0 = (bt.x0 + bt.x1) / 2 - 0.5
                    bt.x1 = bt.x0 + 1.0
                bb.append(bt)

        bbox_artists = bbox_extra_artists
        if bbox_artists is None:
            bbox_artists = self.get_default_bbox_extra_artists()

        for a in bbox_artists:
            bbox = a.get_tightbbox(renderer)
            if bbox is not None and bbox._is_finite():
                bb.append(bbox)
        return mtransforms.Bbox.union(
            [b for b in bb if b.width != 0 or b.height != 0])

def get_events(
        self,
        app_name: Optional[str],
        app_version: Optional[str],
        record_ids: Optional[List[str]],
        start_time: Optional[datetime],
    ) -> pd.DataFrame:
        with self.session.begin() as session:
            where_clauses = []
            if app_name is not None:
                app_name_expr = self._json_extract_otel(
                    "resource_attributes", ResourceAttributes.APP_NAME
                )
                where_clauses.append(app_name_expr == app_name)
            if app_version is not None:
                app_version_expr = self._json_extract_otel(
                    "resource_attributes", ResourceAttributes.APP_VERSION
                )
                where_clauses.append(app_version_expr == app_version)
            if record_ids is not None:
                record_id_expr = self._json_extract_otel(
                    "record_attributes", SpanAttributes.RECORD_ID
                )
                where_clauses.append(record_id_expr.in_(record_ids))
            if start_time is not None:
                where_clauses.append(self.orm.Event.timestamp >= start_time)

            if len(where_clauses) == 0:
                q = sa.select(self.orm.Event)
            elif len(where_clauses) == 1:
                q = sa.select(self.orm.Event).where(where_clauses[0])
            else:
                q = sa.select(self.orm.Event).where(sa.and_(*where_clauses))
            return pd.read_sql(q, session.bind)

def dijkstra_shortest_path(graph, id1, id2, heuristic=None, directed=False):
    # Based on: Connelly Barnes, http://aspn.activestate.com/ASPN/Cookbook/Python/Recipe/119466
    def flatten(list):
        # Flattens a linked list of the form [0,[1,[2,[]]]]
        while len(list) > 0:
            yield list[0]
            list = list[1]
    G = adjacency(graph, directed=directed, heuristic=heuristic)
    q = [(0, id1, ())] # Heap of (cost, path_head, path_rest).
    visited = set()    # Visited nodes.
    while True:
        (cost1, n1, path) = heappop(q)
        if n1 not in visited:
            visited.add(n1)
        if n1 == id2:
            return list(flatten(path))[::-1] + [n1]
        path = (n1, path)
        for (n2, cost2) in G[n1].items():
            if n2 not in visited:
                heappush(q, (cost1 + cost2, n2, path))

def transverse_ising(
    lattice, n_cells, coupling=1.0, h=1.0, boundary_condition=False, neighbour_order=1
):
    lattice = generate_lattice(lattice, n_cells, boundary_condition, neighbour_order)

    if isinstance(coupling, (int, float, complex)):
        coupling = [coupling]
    coupling = math.asarray(coupling)

    hamiltonian = 0.0 * I(0)

    if coupling.shape not in [(neighbour_order,), (lattice.n_sites, lattice.n_sites)]:
        raise ValueError(
            f"The coupling parameter should be a number or an array of shape ({neighbour_order},) or ({lattice.n_sites},{lattice.n_sites})"
        )

    if coupling.shape == (neighbour_order,):
        for edge in lattice.edges:
            i, j, order = edge
            hamiltonian += -coupling[order] * (Z(i) @ Z(j))
    else:
        for edge in lattice.edges:
            i, j = edge[0:2]
            hamiltonian += -coupling[i][j] * (Z(i) @ Z(j))

    for vertex in range(lattice.n_sites):
        hamiltonian += -h * X(vertex)

    return hamiltonian.simplify()

def find_topics(
        self, search_term: str | None = None, image: str | None = None, top_n: int = 5
    ) -> Tuple[List[int], List[float]]:
        if self.embedding_model is None:
            raise Exception("This method can only be used if you did not use custom embeddings.")

        topic_list = list(self.topic_representations_.keys())
        topic_list.sort()

        # Extract search_term embeddings and compare with topic embeddings
        if search_term is not None:
            search_embedding = self._extract_embeddings([search_term], method="word", verbose=False).flatten()
        elif image is not None:
            search_embedding = self._extract_embeddings(
                [None], images=[image], method="document", verbose=False
            ).flatten()
        sims = cosine_similarity(search_embedding.reshape(1, -1), self.topic_embeddings_).flatten()

        # Extract topics most similar to search_term
        ids = np.argsort(sims)[-top_n:]
        similarity = [sims[i] for i in ids][::-1]
        similar_topics = [topic_list[index] for index in ids][::-1]

        return similar_topics, similarity

def container_component_dumps(obj: Any) -> Any:
  def collect_string_fields(obj: Any) -> List[str]:
    non_str_fields = []

    def inner_func(obj):
      if isinstance(obj, list):
        for e in obj:
          inner_func(e)
      elif isinstance(obj, dict):
        for _, v in obj.items():
          # InputValuePlaceholder keys will be caught at dict construction as `TypeError: unhashable type: InputValuePlaceholder`
          inner_func(v)
      elif (
          isinstance(obj, placeholders.InputValuePlaceholder)
          and obj._ir_type != "STRING"  # pylint: disable=protected-access
      ):
        non_str_fields.append(obj.input_name)

    inner_func(obj)

    return non_str_fields

  def custom_placeholder_encoder(obj: Any) -> str:
    if isinstance(obj, placeholders.Placeholder):
      return str(obj)
    raise TypeError(
        f"Object of type {obj.__class__.__name__!r} is not JSON serializable."
    )

  def unquote_nonstring_placeholders(
      json_string: str, strip_quotes_fields: List[str]
  ) -> str:
    for key in strip_quotes_fields:
      pattern = rf"\"\{{\{{\$\.inputs\.parameters\[(?:'|\"|\"){key}(?:'|\"|\")]\}}\}}\""
      repl = f"{{{{$.inputs.parameters['{key}']}}}}"
      json_string = re.sub(pattern, repl, json_string)
    return json_string

  string_fields = collect_string_fields(obj)
  json_string = json.dumps(obj, default=custom_placeholder_encoder)
  return unquote_nonstring_placeholders(json_string, string_fields)

def from_dict(cls, config_dict: Dict[str, Any]) -> "OptimizationConfig":
        def _get_cls_instance(cls_type, cls_attrs):
            if cls_attrs is None:
                return None
            converter = cattrs.Converter(forbid_extra_keys=True)
            if "config_type" in cls_attrs:
                cls_type = cls_attrs["config_type"]
                del cls_attrs["config_type"]
            class_type = getattr(sys.modules[__name__], cls_type)
            return class_type._from_dict(cls_attrs)

        def _check_config_dict(config_dict):
            valid_keys = ("config_type", "global_config", "op_name_configs", "op_type_configs")
            for k in config_dict:
                if k not in valid_keys:
                    raise ValueError(
                        f"Invalid key {k} to construct an OptimizationConfig object. Supported keys are {valid_keys}."
                    )

        _check_config_dict(config_dict)

        config_type = config_dict.get("config_type", None)
        if config_type is None or not isinstance(config_type, str):
            raise ValueError("config_type must be provided with type of string.")

        cls_attrs = {}
        if config_dict.get("global_config", None) is not None:
            cls_attrs["global_config"] = _get_cls_instance(
                config_type, config_dict["global_config"]
            )
        for key in ["op_type_configs", "op_name_configs"]:
            if config_dict.get(key, None) is None:
                continue
            if not isinstance(config_dict[key], dict):
                raise ValueError(f"{key} must be type of dict. Got {type(config_dict[key])}")
            cls_attrs[key] = {
                k: _get_cls_instance(config_type, v) for k, v in config_dict[key].items()
            }

        return cls(**cls_attrs)

def partition_column(
        dataset: Dataset,
        column_name: Hashable,
        max_segments: int = 10,
        max_cat_proportions: float = 0.9,
) -> List[DeepchecksFilter]:
    # pylint: disable=function-redefined,multiple-statements
    column = dataset.data[column_name]
    if column_name in dataset.numerical_features:
        percentile_values = numeric_segmentation_edges(column, max_segments)
        # If for some reason only single value in the column (and column not categorical) we will get single item
        if len(percentile_values) == 1:
            f = lambda df, val=percentile_values[0]: (df[column_name] == val)
            label = str(percentile_values[0])
            return [DeepchecksFilter([f], label)]

        filters = []
        for start, end in zip(percentile_values[:-1], percentile_values[1:]):
            # In case of the last range, the end is closed.
            if end == percentile_values[-1]:
                def f(df, a=start, b=end): return (df[column_name] >= a) & (df[column_name] <= b)
                label = f'[{format_number(start)} - {format_number(end)}]'
            else:
                def f(df, a=start, b=end): return (df[column_name] >= a) & (df[column_name] < b)
                label = f'[{format_number(start)} - {format_number(end)})'

            filters.append(DeepchecksFilter([f], label))
        return filters
    elif column_name in dataset.cat_features:
        # Get sorted histogram
        cat_hist_dict = column.value_counts()
        # Get index of last value in histogram to show
        n_large_cats = largest_category_index_up_to_ratio(cat_hist_dict, max_segments, max_cat_proportions)

        filters = []
        for i in range(n_large_cats):
            f = lambda df, val=cat_hist_dict.index[i]: df[column_name] == val
            filters.append(DeepchecksFilter([f], str(cat_hist_dict.index[i])))

        if len(cat_hist_dict) > n_large_cats:
            f = lambda df, values=cat_hist_dict.index[:n_large_cats]: ~df[column_name].isin(values)
            filters.append(DeepchecksFilter([f], 'Others'))

        return filters

async def workspace_set(
    *,
    workspace_handle: Annotated[
        str | None,
        cyclopts.Parameter(
            "--workspace",
            alias="-w",
            help="Full handle of workspace, in format '<account_handle>/<workspace_handle>'",
        ),
    ] = None,
):
    from prefect.client.cloud import CloudUnauthorizedError, get_cloud_client
    from prefect.settings import PREFECT_API_URL, update_current_profile

    confirm_logged_in(console=_cli.console)
    console = _cli.console

    async with get_cloud_client() as client:
        try:
            workspaces = await client.read_workspaces()
        except CloudUnauthorizedError:
            exit_with_error(
                "Unable to authenticate. Please ensure your credentials are correct."
            )

        if workspace_handle:
            # Search for the given workspace
            for workspace in workspaces:
                if workspace.handle == workspace_handle:
                    break
            else:
                exit_with_error(f"Workspace {workspace_handle!r} not found.")
        else:
            if not workspaces:
                exit_with_error("No workspaces found in the selected account.")

            # Store the original list of workspaces
            original_workspaces = workspaces.copy()

            go_back = True
            workspace = None
            loop_count = 0

            while go_back:
                loop_count += 1

                # If we're going back, use the original list of workspaces
                if loop_count > 1:
                    workspaces = original_workspaces.copy()

                workspace, go_back = await prompt_for_account_and_workspace(
                    workspaces, console
                )

            if workspace is None:
                exit_with_error("No workspace selected.")

        profile = update_current_profile({PREFECT_API_URL: workspace.api_url()})
        exit_with_success(
            f"Successfully set workspace to {workspace.handle!r} in profile"
            f" {profile.name!r}."
        )

def get_chat_template(self, chat_template: str | None = None, tools: list[dict] | None = None) -> str:
        # First, handle the cases when the model has a dict of multiple templates
        if isinstance(self.chat_template, dict):
            template_dict = self.chat_template
            if chat_template is not None and chat_template in template_dict:
                # The user can pass the name of a template to the chat template argument instead of an entire template
                chat_template = template_dict[chat_template]
            elif chat_template is None:
                if tools is not None and "tool_use" in template_dict:
                    chat_template = template_dict["tool_use"]
                elif "default" in template_dict:
                    chat_template = template_dict["default"]
                else:
                    raise ValueError(
                        "This model has multiple chat templates with no default specified! Please either pass a chat "
                        "template or the name of the template you wish to use to the `chat_template` argument. Available "
                        f"template names are {sorted(template_dict.keys())}."
                    )

        elif chat_template is None:
            # These are the cases when the model has a single template
            # priority: `chat_template` argument > `tokenizer.chat_template`
            if self.chat_template is not None:
                chat_template = self.chat_template
            else:
                raise ValueError(
                    "Cannot use chat template functions because tokenizer.chat_template is not set and no template "
                    "argument was passed! For information about writing templates and setting the "
                    "tokenizer.chat_template attribute, please see the documentation at "
                    "https://huggingface.co/docs/transformers/main/en/chat_templating"
                )

        return chat_template

def mutate(cls, module, name, memo, mutate_kwargs):
        if type(module) is Cell:
            op_factory = None  # not all the cells need to be replaced
            if module.op_candidates_factory is not None:
                op_factory = module.op_candidates_factory
                assert isinstance(op_factory, list) or isinstance(op_factory, dict), \
                    'Only support op_factory of type list or dict.'
            elif module.merge_op == 'loose_end':
                op_candidates_lc = module.ops[-1][-1]  # type: ignore
                assert isinstance(op_candidates_lc, LayerChoice)
                candidates = op_candidates_lc.candidates

                def _copy(_, __, ___, op):
                    return copy.deepcopy(op)

                if isinstance(candidates, list):
                    op_factory = [functools.partial(_copy, op=op) for op in candidates]
                elif isinstance(candidates, dict):
                    op_factory = {name: functools.partial(_copy, op=op) for name, op in candidates.items()}
                else:
                    raise ValueError(f'Unsupported type of candidates: {type(candidates)}')
            if op_factory is not None:
                return cls(
                    op_factory,
                    module.num_nodes,
                    module.num_ops_per_node,
                    module.num_predecessors,
                    module.preprocessor,
                    module.postprocessor,
                    module.concat_dim,
                    memo,
                    mutate_kwargs,
                    module.label
                )

def compute_node_depths(tree):
    def depth(node_index, current_node_index=0):
        """Compute the height of a node"""
        if current_node_index == node_index:
            return 0
        elif (
            tree.children_left[current_node_index]
            == tree.children_right[current_node_index]
        ):
            return -1
        else:
            # Compute the height of each subtree
            l_depth = depth(node_index, tree.children_left[current_node_index])
            r_depth = depth(node_index, tree.children_right[current_node_index])
            # The index is only in one of them
            if l_depth != -1:
                return l_depth + 1
            elif r_depth != -1:
                return r_depth + 1
            else:
                return -1

    node_depths = [depth(index) for index in range(tree.node_count)]

    return node_depths

def get_control(self) -> Literal["radio", "multi", "colorchooser", "scale"] | type[
            ttk.Combobox] | type[ttk.Checkbutton] | type[tk.Entry]:
        control: Literal["radio",
                         "multi",
                         "colorchooser",
                         "scale"] | type[ttk.Combobox] | type[ttk.Checkbutton] | type[tk.Entry]
        if self.choices and self.is_radio:
            control = "radio"
        elif self.choices and self.is_multi_option:
            control = "multi"
        elif self.choices and self.choices == "colorchooser":
            control = "colorchooser"
        elif self.choices:
            control = ttk.Combobox
        elif self.dtype == bool:
            control = ttk.Checkbutton
        elif self.dtype in (int, float):
            control = "scale"
        else:
            control = tk.Entry
        logger.debug("Setting control '%s' to %s", self.title, control)
        return control

def copy_with_new_structure(self, other):
        if self.constituency_composition != other.constituency_composition and self.constituency_composition != ConstituencyComposition.UNTIED_MAX:
            raise ValueError("Models are incompatible: self.constituency_composition == {}, other.constituency_composition == {}".format(self.constituency_composition, other.constituency_composition))
        for name, other_parameter in other.named_parameters():
            # this allows other.constituency_composition == UNTIED_MAX to fall through
            if name.startswith('reduce_linear.') and self.constituency_composition == ConstituencyComposition.UNTIED_MAX:
                if name == 'reduce_linear.weight':
                    my_parameter = self.reduce_linear_weight
                elif name == 'reduce_linear.bias':
                    my_parameter = self.reduce_linear_bias
                else:
                    raise ValueError("Unexpected other parameter name {}".format(name))
                for idx in range(len(self.constituent_opens)):
                    my_parameter[idx].data.copy_(other_parameter.data)
            elif name.startswith('word_lstm.weight_ih_l0'):
                # bottom layer shape may have changed from adding a new pattn / lattn block
                my_parameter = self.get_parameter(name)
                # -1 so that it can be converted easier to a different parameter
                copy_size = min(other_parameter.data.shape[-1], my_parameter.data.shape[-1])
                #new_values = my_parameter.data.clone().detach()
                new_values = torch.zeros_like(my_parameter.data)
                new_values[..., :copy_size] = other_parameter.data[..., :copy_size]
                my_parameter.data.copy_(new_values)
            else:
                try:
                    self.get_parameter(name).data.copy_(other_parameter.data)
                except AttributeError as e:
                    raise AttributeError("Could not process %s" % name) from e

def embed(self, sentences: Union[list[Sentence], Sentence]):
        # if only one sentence is passed, convert to list of sentence
        if isinstance(sentences, Sentence):
            sentences = [sentences]

        self.embeddings.embed(sentences)

        for sentence in sentences:
            word_embeddings = torch.cat([token.get_embedding().unsqueeze(0) for token in sentence.tokens], dim=0).to(
                flair.device
            )

            if self.fine_tune_mode in ["nonlinear", "linear"]:
                word_embeddings = self.embedding_flex(word_embeddings)

            if self.fine_tune_mode in ["nonlinear"]:
                word_embeddings = self.embedding_flex_nonlinear(word_embeddings)
                word_embeddings = self.embedding_flex_nonlinear_map(word_embeddings)

            if self.pooling == "mean":
                pooled_embedding = torch.mean(word_embeddings, 0)
            elif self.pooling == "max":
                pooled_embedding, _ = torch.max(word_embeddings, 0)
            elif self.pooling == "min":
                pooled_embedding, _ = torch.min(word_embeddings, 0)

            sentence.set_embedding(self.name, pooled_embedding)

def from_state_dict(cls, prefixed_dict) -> _Dict[str, "CompressionMetadata"]:
        param_to_metadata_dict = dict()
        for key, value in prefixed_dict.items():
            if key.startswith(STATE_DICT_METADATA_BUFFER_PREFIX) and key != METADATA_VERSION_BUFFER:
                prefix, param_name, metadata = key.split(BUFFER_NAME_SEPARATOR)
                if param_name not in param_to_metadata_dict:
                    param_to_metadata_dict[param_name] = {"param_name": param_name}
                # For compression type, convert tensor to list of strings
                if metadata == "compression_type":
                    value = [str(CompressionType(x)) for x in value.tolist()]
                param_to_metadata_dict[param_name][metadata] = value

        result = {
            pname: cls.from_dict(metadata) for pname, metadata in param_to_metadata_dict.items()
        }
        return result

def extract_model(
    input_path: str | os.PathLike,
    output_path: str | os.PathLike,
    input_names: list[str],
    output_names: list[str],
    check_model: bool = True,
    infer_shapes: bool = True,
) -> None:
    if not os.path.exists(input_path):
        raise ValueError(f"Invalid input model path: {input_path}")
    if not output_path:
        raise ValueError("Output model path shall not be empty!")
    if not input_names:
        raise ValueError("Input tensor names shall not be empty!")
    if not output_names:
        raise ValueError("Output tensor names shall not be empty!")

    if len(input_names) != len(set(input_names)):
        raise ValueError("Duplicate names found in the input tensor names.")
    if len(output_names) != len(set(output_names)):
        raise ValueError("Duplicate names found in the output tensor names.")

    if check_model:
        onnx.checker.check_model(input_path)

    if infer_shapes and os.path.getsize(input_path) > onnx.checker.MAXIMUM_PROTOBUF:
        onnx.shape_inference.infer_shapes_path(input_path, output_path)
        model = onnx.load(output_path)
    elif infer_shapes:
        model = onnx.load(input_path, load_external_data=False)
        model = onnx.shape_inference.infer_shapes(model)
        base_dir = os.path.dirname(input_path)
        onnx.load_external_data_for_model(model, base_dir)
    else:
        model = onnx.load(input_path)

    e = Extractor(model)
    extracted = e.extract_model(input_names, output_names)

    if extracted.ByteSize() > onnx.checker.MAXIMUM_PROTOBUF:
        location = os.path.basename(output_path) + ".data"
        onnx.save(extracted, output_path, save_as_external_data=True, location=location)
    else:
        onnx.save(extracted, output_path)

    if check_model:
        onnx.checker.check_model(output_path)

def should_include_node(ctx, directives):
    # TODO: Refactor based on latest code
    if directives:
        skip_ast = None

        for directive in directives:
            if directive.name.value == GraphQLSkipDirective.name:
                skip_ast = directive
                break

        if skip_ast:
            args = get_argument_values(
                GraphQLSkipDirective.args,
                skip_ast.arguments,
                ctx.variable_values,
            )
            if args.get('if') is True:
                return False

        include_ast = None

        for directive in directives:
            if directive.name.value == GraphQLIncludeDirective.name:
                include_ast = directive
                break

        if include_ast:
            args = get_argument_values(
                GraphQLIncludeDirective.args,
                include_ast.arguments,
                ctx.variable_values,
            )

            if args.get('if') is False:
                return False

    return True

def cuda_device_assert_guard(request):
    in_subprocess = os.environ.get("KORNIA_TEST_IN_SUBPROCESS")
    isolate = request.config.getoption("--isolate-half-precision", default=False)
    if not (in_subprocess or isolate):
        yield
        return

    if "device" not in request.fixturenames:
        yield
        return

    try:
        device = request.getfixturevalue("device")
    except pytest.FixtureLookupError:
        yield
        return

    if device.type != "cuda":
        yield
        return

    # Pre-test: verify the CUDA context is healthy.
    try:
        torch.cuda.synchronize(device)
    except RuntimeError:
        pytest.skip("CUDA context corrupted by a device-side assert in a previous test; run this test in isolation")

    yield

    # Post-test: drain the CUDA queue so any async device-side assert surfaces here,
    # in the test that caused it, rather than at the start of the next test.
    # Fail the test if a device-side assert is detected so it is not silently passed.
    try:
        torch.cuda.synchronize(device)
    except RuntimeError as exc:
        torch.cuda.empty_cache()
        pytest.fail(f"CUDA device-side assert triggered during this test: {exc}")

def convert_weights(model: nn.Module):
    def _convert_weights_to_fp16(ll):
        if isinstance(ll, (nn.Conv1d, nn.Conv2d, nn.Linear)):
            ll.weight.data = ll.weight.data.half()
            if ll.bias is not None:
                ll.bias.data = ll.bias.data.half()

        if isinstance(ll, nn.MultiheadAttention):
            for attr in [
                    *[f'{s}_proj_weight' for s in ['in', 'q', 'k', 'v']],
                    'in_proj_bias', 'bias_k', 'bias_v'
            ]:
                tensor = getattr(ll, attr)
                if tensor is not None:
                    tensor.data = tensor.data.half()

        for name in ['text_projection', 'proj']:
            if hasattr(ll, name):
                attr = getattr(ll, name)
                if attr is not None:
                    attr.data = attr.data.half()

    model.apply(_convert_weights_to_fp16)

def finalize_check_result(self, check_result, check, dataset_kind: DatasetKind = None):
        # Validate the check result type
        if isinstance(check_result, CheckFailure):
            return
        if not isinstance(check_result, CheckResult):
            raise DeepchecksValueError(f'Check {check.name()} expected to return CheckResult but got: '
                                       + type(check_result).__name__)

        # Set reference between the check result and check
        check_result.check = check
        # Calculate conditions results
        check_result.process_conditions()
        # Add sampling footnote if needed
        if hasattr(check, 'n_samples'):
            n_samples = getattr(check, 'n_samples')
            message = ''
            if dataset_kind:
                dataset = self.get_data_by_kind(dataset_kind)
                if dataset.is_sampled(n_samples):
                    message = f'Data is sampled from the original dataset, running on ' \
                              f'{dataset.len_when_sampled(n_samples)} samples out of {len(dataset)}.'
            else:
                if self._train is not None and self._train.is_sampled(n_samples):
                    message += f'Running on {self._train.len_when_sampled(n_samples)} <b>train</b> data samples ' \
                               f'out of {len(self._train)}.'
                if self._test is not None and self._test.is_sampled(n_samples):
                    if message:
                        message += ' '
                    message += f'Running on {self._test.len_when_sampled(n_samples)} <b>test</b> data samples ' \
                               f'out of {len(self._test)}.'

            if message:
                message = ('<p style="font-size:0.9em;line-height:1;"><i>'
                           f'Note - data sampling: {message} Sample size can be controlled with the "n_samples" '
                           'parameter.</i></p>')
                check_result.display.append(message)

def load_model(
    bento_model: str | Tag | bentoml.Model,
    init: bool = True,
    device: str | XlaBackend = "cpu",
) -> tuple[nn.Module, dict[str, t.Any]]:
    # NOTE: we need to hide all GPU from TensorFlow, otherwise it will try to allocate
    # memory on the GPU and make it unavailable for JAX.
    tf.config.experimental.set_visible_devices([], "GPU")

    if not isinstance(bento_model, bentoml.Model):
        bento_model = get(bento_model)
    if bento_model.info.module not in (MODULE_NAME, __name__):
        raise NotFound(
            f"Model {bento_model.tag} was saved with module {bento_model.info.module}, failed loading with {MODULE_NAME}."
        )
    if "_module" not in bento_model.custom_objects:
        raise BentoMLException(
            f"Model {bento_model.tag} was either corrupt or not saved with 'bentoml.flax.save_model()'."
        )
    module: nn.Module = bento_model.custom_objects["_module"]

    serialized = bento_model.path_of(MODEL_FILENAME)
    try:
        with open(serialized, "rb") as f:
            state_dict: dict[str, t.Any] = serialization.from_bytes(module, f.read())
    except (UnpicklingError, msgpack.exceptions.ExtraData, UnicodeDecodeError) as err:
        raise BentoMLException(
            f"Unable to covert model {bento_model.tag}'s state_dict: {err}"
        ) from None

    # ensure that all arrays are restored as jnp.ndarray
    # NOTE: This is to prevent a bug this will be fixed in Flax >= v0.3.4:
    # https://github.com/google/flax/issues/1261
    if init:
        state_dict = jax.tree_util.tree_map(jnp.array, state_dict)
    else:
        # keep the params on given device if we don't want to initialize
        state_dict = jax.tree_util.tree_map(
            lambda s: jax.device_put(s, jax.devices(device)[0]), state_dict
        )
    return module, state_dict

def raster_to_vector(source, output, simplify_tolerance=None, dst_crs=None):
    common = get_common_module()
    source = os.path.abspath(source)
    output = os.path.abspath(output)

    if not os.path.exists(source):
        raise FileNotFoundError(f"Source raster not found: {source}")

    parent = os.path.dirname(output)
    if parent:
        os.makedirs(parent, exist_ok=True)

    ext = os.path.splitext(output)[1].lower()

    kwargs = {"simplify_tolerance": simplify_tolerance}
    if dst_crs is not None:
        kwargs["dst_crs"] = dst_crs

    if ext == ".gpkg":
        common.raster_to_gpkg(source, output, **kwargs)
    elif ext == ".shp":
        common.raster_to_shp(source, output, **kwargs)
    elif ext == ".geojson":
        common.raster_to_geojson(source, output, **kwargs)
    else:
        common.raster_to_vector(source, output, **kwargs)

    gpd = get_geopandas()
    gdf = gpd.read_file(output)
    feature_count = len(gdf)

    result = {
        "output": output,
        "format": ext.lstrip("."),
        "feature_count": feature_count,
        "file_size": os.path.getsize(output) if os.path.exists(output) else 0,
    }

    return result

def parse_module_content(content: str) -> List[str]:
    objects = []
    current_object = []
    lines = content.split("\n")
    # Doc-styler takes everything between two triple quotes in docstrings, so we need a fake """ here to go with this.
    end_markers = [")", "]", "}", '"""']

    for line in lines:
        # End of an object
        is_valid_object = len(current_object) > 0
        if is_valid_object and len(current_object) == 1:
            is_valid_object = not current_object[0].startswith("# Copied from")
        if not is_empty_line(line) and find_indent(line) == 0 and is_valid_object:
            # Closing parts should be included in current object
            if line in end_markers:
                current_object.append(line)
                objects.append("\n".join(current_object))
                current_object = []
            else:
                objects.append("\n".join(current_object))
                current_object = [line]
        else:
            current_object.append(line)

    # Add last object
    if len(current_object) > 0:
        objects.append("\n".join(current_object))

    return objects

def local_disk_satisfied(requested: Optional[str],
                         launched: Optional[str]) -> bool:
    #  pylint: disable=line-too-long
    if requested is None:
        return True
    if launched is None:
        return False
    req_mode, req_size, req_at_least = parse_local_disk_str(requested)
    launched_mode, launched_size, _ = parse_local_disk_str(launched)

    if req_mode == 'nvme' and launched_mode != 'nvme':
        return False
    if req_mode == 'ssd' and launched_mode not in ('ssd', 'nvme'):
        return False

    if req_at_least:
        return launched_size >= req_size
    else:
        return abs(launched_size - req_size) < 1.0  # for float approx.

def bygroups(*args):
    def callback(lexer, match, ctx=None):
        for i, action in enumerate(args):
            if action is None:
                continue
            elif type(action) is _TokenType:
                data = match.group(i + 1)
                if data:
                    yield match.start(i + 1), action, data
            else:
                data = match.group(i + 1)
                if data is not None:
                    if ctx:
                        ctx.pos = match.start(i + 1)
                    for item in action(lexer,
                                       _PseudoMatch(match.start(i + 1), data), ctx):
                        if item:
                            yield item
        if ctx:
            ctx.pos = match.end()
    return callback

def prepend_function(builder: fb.Builder, data_type: TensorType):  # noqa C901
    if data_type == TensorType.UINT8:
        return builder.PrependUint8
    elif data_type == TensorType.UINT16:
        return builder.PrependUint16
    elif data_type == TensorType.UINT32:
        return builder.PrependUint32
    elif data_type == TensorType.UINT64:
        return builder.PrependUint64

    elif data_type == TensorType.INT8:
        return builder.PrependInt8
    elif data_type == TensorType.INT16:
        return builder.PrependInt16
    elif data_type == TensorType.INT32:
        return builder.PrependInt32
    elif data_type == TensorType.INT64:
        return builder.PrependInt64

    elif data_type == TensorType.FLOAT16:
        logger.w(
            "Flatbuffer prepend function for FLOAT16 datatype is not supported! Using default 16b alternative."
        )
        return builder.PrependInt16  # Might not work
    elif data_type == TensorType.FLOAT32:
        return builder.PrependFloat32
    elif data_type == TensorType.FLOAT64:
        return builder.PrependFloat64

    elif data_type == TensorType.BOOL:
        return builder.PrependBool

    logger.e(
        logger.Code.NOT_IMPLEMENTED,
        f"Unsupported flatbuffer prepend function for type '{data_type}'!",
    )

def y_shifted_sbd_vec(ref_ts, dataset, norm_ref, norms_dataset):
    n_ts = dataset.shape[0]
    sz = dataset.shape[1]
    d = dataset.shape[2]
    assert sz == ref_ts.shape[0] and d == ref_ts.shape[1]
    dataset_shifted = np.zeros((n_ts, sz, d))

    if norm_ref < 0:
        norm_ref = np.linalg.norm(ref_ts)
    if (norms_dataset < 0.0).any():
        for i_ts in prange(n_ts):
            norms_dataset[i_ts] = np.linalg.norm(dataset[i_ts, ...])

    for i in prange(n_ts):
        cc = normalized_cc(ref_ts, dataset[i], norm1=norm_ref, norm2=norms_dataset[i])
        idx = np.argmax(cc)
        shift = idx + 1 - sz
        if shift > 0:
            dataset_shifted[i, shift:] = dataset[i, :-shift, :]
        elif shift < 0:
            dataset_shifted[i, :shift] = dataset[i, -shift:, :]
        else:
            dataset_shifted[i] = dataset[i]

    return dataset_shifted

def validate_zip_archive(
    zip_obj_or_path, target_root, specific_member=None, context="ZipAudit"
):
    try:
        target = Path(target_root).resolve()

        def _audit(zf):
            members = (
                [specific_member] if specific_member is not None else zf.namelist()
            )
            for name in members:
                name_str = name.filename if hasattr(name, "filename") else str(name)
                if "\0" in name_str:
                    raise ValueError(f"Null byte in ZIP member: {name_str}")

                member_path = (target / name_str).resolve()
                if not (member_path == target or member_path.is_relative_to(target)):
                    msg = f"Security Violation [{context}]: Traversal member '{name_str}' detected."
                    if ENFORCE:
                        raise PermissionError(msg)
                    else:
                        warnings.warn(msg, RuntimeWarning, stacklevel=3)

        if isinstance(zip_obj_or_path, zipfile.ZipFile):
            _audit(zip_obj_or_path)
        else:
            with zipfile.ZipFile(zip_obj_or_path, "r") as zf:
                _audit(zf)
    except (PermissionError, ValueError):
        raise
    except (OSError, zipfile.BadZipFile):
        if ENFORCE:
            raise PermissionError("Zip validation failed")

def hypernyms(self, recursive=False, depth=None):
        p = [Synset(p) for p in self._wnsynset.hypernyms()]
        if depth is None and recursive is False:
            return p
        if depth == 0:
            return []
        if depth is not None:
            depth -= 1
        if depth is None or depth > 0:
            [p.extend(s.hypernyms(True, depth)) for s in list(p)]
        return p

def save(self, path: str | None = None, verbose: bool = True) -> str:
        if path is None:
            path = self.path
        file_path = os.path.join(path, self.model_file_name)
        _model = self.model
        if self.model is not None:
            if self._compiler is None:
                self._compiler = self._get_compiler()
                if self._compiler is not None and not self._compiler.save_in_pkl:
                    self._compiler.save(model=self.model, path=path)
            if self._compiler is not None and not self._compiler.save_in_pkl:
                self.model = None  # Don't save model in pkl
        save_pkl.save(path=file_path, object=self, verbose=verbose)
        self.model = _model
        return path

def get_okx_crypto_volume(symbol: str) -> str:
    try:
        if not symbol:
            return "Please provide a valid trading pair (e.g., 'BTC-USDT')"

        # Convert to uppercase and ensure proper format
        symbol = symbol.upper()
        if not symbol.endswith("-USDT"):
            symbol = f"{symbol}-USDT"

        # OKX API endpoint for ticker information
        url = f"https://www.okx.com/api/v5/market/ticker?instId={symbol}"

        # Make the API request
        response = requests.get(url)
        response.raise_for_status()

        data = response.json()

        if data.get("code") != "0":
            return f"Error: {data.get('msg', 'Unknown error')}"

        ticker_data = data.get("data", [{}])[0]
        if not ticker_data:
            return f"Could not find data for {symbol}. Please check the trading pair."

        volume_24h = float(ticker_data.get("vol24h", 0))
        base_currency = symbol.split("-")[0]
        return f"24h Trading Volume for {base_currency}/USDT: ${volume_24h:,.2f}"

    except requests.exceptions.RequestException as e:
        return f"Error fetching OKX data: {str(e)}"
    except Exception as e:
        return f"Error: {str(e)}"

def solve_slice_by_index_slice(x_shape, begin, end, stride, begin_mask, end_mask, squeeze_mask):
    # set default values for parameters
    rank = len(x_shape)
    begin = [int(i) for i in list(begin[:])]
    end = [int(i) for i in list(end[:])]
    if stride is None:
        stride = [1] * rank
    if begin_mask is None:
        begin_mask = [False] * rank
    if end_mask is None:
        end_mask = [False] * rank
    if squeeze_mask is None:
        squeeze_mask = [False] * rank

    # compute slices
    slices = []
    for idx, mask in enumerate(begin_mask):
        if mask:
            begin[idx] = None
    for idx, mask in enumerate(end_mask):
        if mask:
            end[idx] = None
    for idx, mask in enumerate(squeeze_mask):
        if mask:
            end[idx] = None
            stride[idx] = np.iinfo(
                np.int32
            ).max  # We slice out only 1 element by setting stride to INF
    for idx in range(rank):
        slices.append(slice(begin[idx], end[idx], stride[idx]))

    return tuple(slices)

def extract_quant_params_through_permute(
    module: torch.fx.GraphModule,
) -> dict[int, tuple[float, int, int, int, torch.dtype]]:
    quant_args: dict[int, tuple[float, int, int, int, torch.dtype]] = {}

    placeholder_idx = 0
    for node in module.graph.nodes:
        if node.op != "placeholder":
            continue
        for user in node.users:
            if user.target in (
                torch.ops.aten.permute.default,
                torch.ops.aten.permute_copy.default,
            ):
                for permute_user in user.users:
                    target_str = str(permute_user.target)
                    if "quantize_per_tensor" in target_str:
                        args = permute_user.args[1:]
                        if len(args) >= 5:
                            quant_args[placeholder_idx] = (
                                float(args[0]),  # scale
                                int(args[1]),  # zero_point
                                int(args[2]),  # qmin
                                int(args[3]),  # qmax
                                args[4],  # dtype
                            )
                        break
                break

        placeholder_idx += 1

    return quant_args

def to_timestamp(self, freq=None, how: str = "start") -> DatetimeArray:
        from pandas.core.arrays import DatetimeArray

        how = libperiod.validate_end_alias(how)

        if self.freq.base == "ns" or freq == "ns":
            unit = "ns"
        else:
            unit = "us"

        end = how == "E"
        if end:
            if freq == "B" or self.freq == "B":
                # roll forward to ensure we land on B date
                adjust = Timedelta(1, unit="D") - Timedelta(1, unit=unit)
                return self.to_timestamp(how="start") + adjust
            else:
                adjust = Timedelta(1, unit=unit)
                return (self + self.freq).to_timestamp(how="start") - adjust

        if freq is None:
            freq_code = self._dtype._get_to_timestamp_base()
            dtype = PeriodDtypeBase(freq_code, 1)
            freq = dtype._freqstr
            base = freq_code
        else:
            freq = Period._maybe_convert_freq(freq)
            base = freq._period_dtype_code

        new_parr = self.asfreq(freq, how=how)

        new_data = libperiod.periodarr_to_dt64arr(new_parr.asi8, base)
        dta = DatetimeArray._from_sequence(new_data, dtype=new_data.dtype)
        assert dta.unit == unit

        if self.freq.rule_code == "B":
            # See if we can retain BDay instead of Day in cases where
            #  len(self) is too small for infer_freq to distinguish between them
            diffs = libalgos.unique_deltas(self.asi8)
            if len(diffs) == 1:
                diff = diffs[0]
                if diff == self.dtype._n:
                    dta._freq = self.freq
                elif diff == 1:
                    dta._freq = self.freq.base
                # TODO: other cases?
            return dta
        else:
            dta = dta._with_freq("infer")
            if freq is not None:
                freq = to_offset(freq)
                if (
                    isinstance(dta.freq, Day)
                    and not isinstance(freq, Day)
                    and Timedelta(freq) == Timedelta(days=dta.freq.n)
                ):
                    dta._freq = freq
            return dta

def resource_shape_command(node_group=None, purpose=None):
    client = APIClient()
    node_groups = client.nodegroup.list_all()

    if node_group:
        filters = node_group
        node_groups = [
            ng
            for ng in node_groups
            if any((f in ng.metadata.id_) or (f in ng.metadata.name) for f in filters)
        ]

    table = Table(title="Resource Shapes by Node Group", show_lines=True)
    table.add_column("Node Group")
    table.add_column("Shapes")
    table.add_column("Detailed")

    wanted = {str(purpose).lower()} if purpose else {"pod", "deployment", "job"}

    for ng in node_groups:
        ng_name = ng.metadata.name
        ng_id = ng.metadata.id_

        shapes = client.shapes.list_shapes(node_group=ng_id, purpose=purpose)
        # Fallback to name if ID returns nothing
        if not shapes:
            try:
                shapes = client.shapes.list_shapes(node_group=ng_name, purpose=purpose)
            except Exception:
                shapes = []

        # NodeGroup column: name on first line, id on second line (only show on the first row per group)
        filtered = []
        for sh in shapes:
            spec = getattr(sh, "spec", None)
            listable = set((getattr(spec, "listable_in", None) or []))
            listable_lower = {str(x).lower() for x in listable}
            if listable_lower & wanted:
                filtered.append(sh)

        if not filtered:
            nodegroup_text = f"{ng_name}\n[dim]{ng_id}[/dim]"
            table.add_row(nodegroup_text, "[yellow]- none[/yellow]", "")
            continue

        first = True
        for sh in filtered:
            shape_text, detail_text = _format_shape_entry(sh)
            nodegroup_text = f"{ng_name}\n[dim]{ng_id}[/dim]" if first else ""
            table.add_row(nodegroup_text, shape_text, detail_text)
            first = False

    console.print(table)

def aggregate_fit(
        self,
        _: int,
        results: List[Tuple[ClientProxy, FitRes]],
        failures: List[Union[Tuple[ClientProxy, FitRes], BaseException]],
    ) -> Tuple[Optional[Parameters], Dict[str, Union[bool, bytes, float, int, str]]]:
        if not results:
            return None, {}
        # Do not aggregate if there are failures and failures are not accepted
        if not self.accept_failures and failures:
            return None, {}

        # Convert results
        key_name = "train_loss" if self.weight_strategy == "loss" else "wer"
        weights = None

        # Define ratio merge
        if self.weight_strategy == "num":
            weights_results = [
                (parameters_to_ndarrays(fit_res.parameters), fit_res.num_examples)
                for _, fit_res in results
            ]
            weights = aggregate(weights_results)
        else:
            weights_results = [
                (
                    parameters_to_ndarrays(fit_res.parameters),
                    int(fit_res.metrics[key_name]),
                )
                for _, fit_res in results
            ]
            weights = aggregate(weights_results)

        # Free memory for next round
        del results, weights_results
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        gc.collect()
        return ndarrays_to_parameters(weights), {}

def default_init_weights(module_list, scale=1, bias_fill=0, **kwargs):
    if not isinstance(module_list, list):
        module_list = [module_list]
    for module in module_list:
        for m in module.modules():
            if isinstance(m, nn.Conv2d):
                init.kaiming_normal_(m.weight, **kwargs)
                m.weight.data *= scale
                if m.bias is not None:
                    m.bias.data.fill_(bias_fill)
            elif isinstance(m, nn.Linear):
                init.kaiming_normal_(m.weight, **kwargs)
                m.weight.data *= scale
                if m.bias is not None:
                    m.bias.data.fill_(bias_fill)
            elif isinstance(m, _BatchNorm):
                init.constant_(m.weight, 1)
                if m.bias is not None:
                    m.bias.data.fill_(bias_fill)

def ensure_copy(self):
        def is_view(x):
            if not sp.issparse(x):
                return x.base is not None
            else:
                return x.data.base is not None

        if is_view(self._X):
            self._X = self._X.copy()
        if is_view(self._Y):
            self._Y = self._Y.copy()
        if is_view(self._metas):
            self._metas = self._metas.copy()
        if is_view(self._W):
            self._W = self._W.copy()
        if is_view(self.ids):
            self.ids = self.ids.copy()

def moe_unpermute(
    inp: torch.Tensor,
    row_id_map: torch.Tensor,
    merging_probs: Optional[torch.Tensor] = None,
    restore_shape: Optional[torch.Size] = None,
    map_type: str = "mask",
    probs: Optional[torch.Tensor] = None,
    pad_offsets: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    if probs is not None:
        if merging_probs is not None:
            raise ValueError(
                "Both merging_probs and probs kwarg are provided. probs is deprecated."
            )
        warnings.warn("probs kwarg is deprecated. Use merging_probs kwarg instead.")
        merging_probs = probs
    if map_type == "index":
        # Normalize probs
        if merging_probs is not None:
            if merging_probs.dtype != torch.float32:
                warnings.warn(
                    f"The data type of the input `probs` of Unpermute is {merging_probs.dtype}! "
                    "The recommended type is torch.float32."
                )
                merging_probs = merging_probs.to(torch.float32)
            num_tokens = merging_probs.size(0)
            topK = merging_probs.size(1)
        else:
            num_tokens = row_id_map.size(0)
            topK = 1
            merging_probs = torch.empty(0, device=inp.device)

        return torch.ops.te_moe.unpermute_index_map_fwd(
            inp, row_id_map, merging_probs, num_tokens, topK
        )
    if map_type == "mask":
        if restore_shape is None:
            restore_shape = inp.shape
        num_tokens, hidden_size = restore_shape
        num_experts = (row_id_map.size(1) - 1) // 2 if row_id_map.dim() > 1 else 0

        return torch.ops.te_moe.unpermute_mask_map_fwd(
            inp,
            row_id_map,
            merging_probs,
            num_tokens,
            num_experts,
            hidden_size,
            pad_offsets,
        )
    raise ValueError("map_type should be one of 'mask' or 'index'")

def fidelity(state0, state1, check_state=False, c_dtype="complex128"):
    # Cast as a c_dtype array
    state0 = math.cast(state0, dtype=c_dtype)
    state1 = math.cast(state1, dtype=c_dtype)

    if check_state:
        _check_density_matrix(state0)
        _check_density_matrix(state1)

    if math.shape(state0)[-1] != math.shape(state1)[-1]:
        raise ValueError("The two states must have the same number of wires.")

    batch_size0 = math.shape(state0)[0] if math.ndim(state0) > 2 else None
    batch_size1 = math.shape(state1)[0] if math.ndim(state1) > 2 else None

    if math.get_interface(state0) == "jax" or math.get_interface(state1) == "jax":
        if batch_size0 and not batch_size1:
            state1 = math.broadcast_to(state1, (batch_size0, *math.shape(state1)))
        elif not batch_size0 and batch_size1:
            state0 = math.broadcast_to(state0, (batch_size1, *math.shape(state0)))

    # Two mixed states
    _register_vjp(state0, state1)
    fid = math.compute_fidelity(state0, state1)
    return fid

def check_all_auto_mapping_names_in_config_mapping_names():
    # This is where we need to check we have all backends or the check is incomplete.
    check_missing_backends()

    failures = []
    # `TOKENIZER_PROCESSOR_MAPPING_NAMES` and `AutoTokenizer` is special, and don't need to follow the rule.
    mappings_to_check = {
        "IMAGE_PROCESSOR_MAPPING_NAMES": IMAGE_PROCESSOR_MAPPING_NAMES,
        "FEATURE_EXTRACTOR_MAPPING_NAMES": FEATURE_EXTRACTOR_MAPPING_NAMES,
        "PROCESSOR_MAPPING_NAMES": PROCESSOR_MAPPING_NAMES,
    }

    module = getattr(transformers.models.auto, "modeling_auto")
    # all mappings in a single auto modeling file
    mapping_names = [x for x in dir(module) if x.endswith("_MAPPING_NAMES")]
    mappings_to_check.update({name: getattr(module, name) for name in mapping_names})

    for name, mapping in mappings_to_check.items():
        for model_type in mapping:
            if model_type not in CONFIG_MAPPING_NAMES:
                failures.append(
                    f"`{model_type}` appears in the mapping `{name}` but it is not defined in the keys of "
                    "`CONFIG_MAPPING_NAMES`."
                )
    if len(failures) > 0:
        raise Exception(f"There were {len(failures)} failures:\n" + "\n".join(failures))

def set_derived_feature_columns_(config_obj: "ModelConfig"):
    for feature in config_obj.input_features:
        if feature.column is None:
            feature.column = feature.name
        if feature.proc_column is None:
            feature.proc_column = compute_feature_hash(feature.to_dict())

    for feature in config_obj.output_features:
        if feature.column is None:
            feature.column = feature.name
        if feature.proc_column is None:
            feature.proc_column = compute_feature_hash(feature.to_dict())

def random_dynamic_speaker(
    agents: List[str],
    response: str = "",
    strategy: str = "parallel",
    **kwargs,
) -> Union[str, List[str]]:
    if not agents:
        raise ValueError(
            "No agents provided for random dynamic selection"
        )

    # If no response provided, randomly select first agent
    if not response:
        return random.choice(agents)

    # Extract @mentions from the response
    mentions = re.findall(r"@(\w+)", response)

    # Filter mentions to only include valid agents
    valid_mentions = [
        mention for mention in mentions if mention in agents
    ]

    if not valid_mentions:
        # If no valid mentions, randomly select from all agents
        return random.choice(agents)

    # Handle multiple mentions based on strategy
    if strategy == "sequential":
        # Return the first mentioned agent for sequential execution
        return valid_mentions[0]
    elif strategy == "parallel":
        # Return all mentioned agents for parallel execution
        return valid_mentions
    else:
        raise ValueError(
            f"Invalid strategy: {strategy}. Must be 'sequential' or 'parallel'"
        )

def partitions(s, include_singles=True):
    if len(s) == 2:
        if include_singles:
            yield (s[0],), (s[1],)

        yield (tuple(s),)
    else:
        # pull off a single item and partition the rest
        if include_singles:
            if len(s) > 1:
                item_partition = (s[0],)
                rest = s[1:]
                rest_partitions = partitions(rest, include_singles)
                for p in rest_partitions:
                    yield ((item_partition),) + p
            else:
                yield (tuple(s),)

        # pull off a pair of items and partition the rest
        for idx1 in range(1, len(s)):
            item_partition = (s[0], s[idx1])
            rest = s[1:idx1] + s[idx1 + 1 :]
            rest_partitions = partitions(rest, include_singles)
            for p in rest_partitions:
                yield ((item_partition),) + p

def to_proto(self) -> OnDemandFeatureViewProto:
        meta = OnDemandFeatureViewMeta()
        if self.created_timestamp:
            meta.created_timestamp.FromDatetime(self.created_timestamp)
        if self.last_updated_timestamp:
            meta.last_updated_timestamp.FromDatetime(self.last_updated_timestamp)
        if self.current_version_number is not None:
            meta.current_version_number = self.current_version_number
        sources = {}
        for source_name, fv_projection in self.source_feature_view_projections.items():
            sources[source_name] = OnDemandSource(
                feature_view_projection=fv_projection.to_proto(),
            )
        for (
            source_name,
            request_sources,
        ) in self.source_request_sources.items():
            sources[source_name] = OnDemandSource(
                request_data_source=request_sources.to_proto()
            )

        feature_transformation = transformation_to_proto(self.feature_transformation)

        tags = dict(self.tags) if self.tags else {}
        if self.track_metrics:
            tags[self._TRACK_METRICS_TAG] = "true"
        else:
            tags.pop(self._TRACK_METRICS_TAG, None)

        spec = OnDemandFeatureViewSpec(
            name=self.name,
            entities=self.entities or None,
            entity_columns=[
                field.to_proto() for field in self.entity_columns if self.entity_columns
            ],
            features=[feature.to_proto() for feature in self.features],
            sources=sources,
            feature_transformation=feature_transformation,
            mode=self.mode,
            description=self.description,
            tags=tags,
            owner=self.owner,
            write_to_online_store=self.write_to_online_store,
            singleton=self.singleton or False,
            aggregations=self.aggregations,
            version=self.version,
        )
        return OnDemandFeatureViewProto(spec=spec, meta=meta)

def add_and_switch_to_new_task(
        self,
        task_name: str,
        label_dictionary: Union[list, set, Dictionary, str],
        label_type: str,
        multi_label: bool = True,
        force_switch: bool = False,
    ):
        if task_name in self._task_specific_attributes and not force_switch:
            log.warning(f"Task `{task_name}` already exists in TARS model. Switching to it.")
        else:
            # make label dictionary if no Dictionary object is passed
            if isinstance(label_dictionary, Dictionary):
                label_dictionary = label_dictionary.get_items()
            if isinstance(label_dictionary, str):
                label_dictionary = [label_dictionary]

            # prepare dictionary of tags (without B- I- prefixes and without UNK)
            tag_dictionary = Dictionary(add_unk=False)
            for tag in label_dictionary:
                if tag == "<unk>" or tag == "O":
                    continue
                if len(tag) > 1 and tag[1] == "-":
                    tag = tag[2:]
                    tag_dictionary.add_item(tag)
                else:
                    tag_dictionary.add_item(tag)

            self._task_specific_attributes[task_name] = {
                "label_dictionary": tag_dictionary,
                "label_type": label_type,
                "multi_label": multi_label,
            }

        self.switch_to_task(task_name)

def finish(self):
        if self._finished:
            return

        if "wandb" in self.logger:
            self.logger["wandb"].finish(exit_code=0)
        if "swanlab" in self.logger:
            self.logger["swanlab"].finish()
        if "vemlp_wandb" in self.logger:
            self.logger["vemlp_wandb"].finish(exit_code=0)
        if "tensorboard" in self.logger:
            self.logger["tensorboard"].finish()
        if "clearml" in self.logger:
            self.logger["clearml"].finish()
        if "trackio" in self.logger:
            self.logger["trackio"].finish()
        if "file" in self.logger:
            self.logger["file"].finish()
        if "ui" in self.logger:
            self.logger["ui"].finish()

        self.logger.clear()
        self._finished = True

def preprocess_text(input: TextPreprocessingInput) -> TextProcessingOutput:
    text = input.text

    if PreprocessingStep.REMOVE_SPECIAL_CHARACTERS in input.preprocessing_steps:
        text = re.sub(r"\W", " ", text)

    if PreprocessingStep.REMOVE_SINGLE_CHARACTERS in input.preprocessing_steps:
        text = re.sub(r"\s+[a-zA-Z]\s+", " ", text)

    if PreprocessingStep.CLEAN_MULTIPLE_SPACES in input.preprocessing_steps:
        text = re.sub(r"\s+", " ", text, flags=re.I)

    if PreprocessingStep.LOWERCASE in input.preprocessing_steps:
        text = text.lower()

    if PreprocessingStep.REMOVE_STOP_WORDS in input.preprocessing_steps:
        tokens = text.split()
        tokens = [word for word in tokens if word not in EN_STOP_WORDS]
        text = " ".join(tokens)

    return TextProcessingOutput(preprocessed_text=text)

def ner_token_f1(y_true, y_predicted, print_results=False):
    y_true = list(chain(*y_true))
    y_pred = list(chain(*y_predicted))

    # Drop BIO or BIOES markup
    assert all(len(tag.split('-')) <= 2 for tag in y_true)

    y_true = [tag.split('-')[-1] for tag in y_true]
    y_pred = [tag.split('-')[-1] for tag in y_pred]
    tags = set(y_true) | set(y_pred)
    tags_dict = {tag: n for n, tag in enumerate(tags)}

    y_true_inds = np.array([tags_dict[tag] for tag in y_true])
    y_pred_inds = np.array([tags_dict[tag] for tag in y_pred])

    results = {}
    for tag, tag_ind in tags_dict.items():
        if tag == 'O':
            continue
        tp = np.sum((y_true_inds == tag_ind) & (y_pred_inds == tag_ind))
        fn = np.sum((y_true_inds == tag_ind) & (y_pred_inds != tag_ind))
        fp = np.sum((y_true_inds != tag_ind) & (y_pred_inds == tag_ind))
        n_pred = np.sum(y_pred_inds == tag_ind)
        n_true = np.sum(y_true_inds == tag_ind)
        if tp + fp > 0:
            precision = tp / (tp + fp) * 100
        else:
            precision = 0
        if tp + fn > 0:
            recall = tp / (tp + fn) * 100
        else:
            recall = 0
        if precision + recall > 0:
            f1 = 2 * precision * recall / (precision + recall)
        else:
            f1 = 0
        results[tag] = {'precision': precision, 'recall': recall,
                        'f1': f1, 'n_true': n_true, 'n_pred': n_pred,
                        'tp': tp, 'fp': fp, 'fn': fn}

    results['__total__'], accuracy, total_true_entities, total_predicted_entities, total_correct = _global_stats_f1(
        results)
    n_tokens = len(y_true)
    if print_results:
        log.debug('TOKEN LEVEL F1')
        _print_conll_report(results, accuracy, total_true_entities, total_predicted_entities, n_tokens, total_correct)
    return results['__total__']['f1']

def save(forecaster, path: FILE_LIKE):
    # List of attributes to remove
    attrs_to_remove_forecaster = ["trainer"]
    attrs_to_remove_model = ["_trainer"]

    # Store removed attributes temporarily
    removed_attrs = {}

    # Remove specified attributes from forecaster
    for attr in attrs_to_remove_forecaster:
        if hasattr(forecaster, attr):
            removed_attrs[attr] = getattr(forecaster, attr)
            setattr(forecaster, attr, None)

    # Remove specified attributes from forecaster.model
    for attr in attrs_to_remove_model:
        if hasattr(forecaster.model, attr):
            removed_attrs[attr] = getattr(forecaster.model, attr)
            setattr(forecaster.model, attr, None)

    # Perform the save operation
    try:
        torch.save(forecaster, path)
    except Exception as e:
        print(f"An error occurred while saving the model: {e}")
        raise
    finally:
        # Restore the removed attributes
        for attr, value in removed_attrs.items():
            if hasattr(forecaster, attr):
                setattr(forecaster, attr, value)
            elif hasattr(forecaster.model, attr):
                setattr(forecaster.model, attr, value)

def dataflowblock_pass(
    pass_func=None, opt_level=None, name=None, required=None, traceable=False
) -> Callable | DataflowBlockPass:

    if opt_level is None:
        raise ValueError("Please provide opt_level for the dataflowblock pass.")

    required = required if required else []
    if not isinstance(required, list | tuple):
        raise TypeError("Required is expected to be the type of " + "list/tuple.")

    def create_dataflowblock_pass(pass_arg):
        """Internal function that creates a dataflowblock pass"""
        fname = name if name else pass_arg.__name__
        info = tvm.transform.PassInfo(opt_level, fname, required, traceable)
        if inspect.isclass(pass_arg):
            return _wrap_class_dataflowblock_pass(pass_arg, info)
        if not isinstance(pass_arg, types.FunctionType | types.LambdaType):
            raise TypeError("pass_func must be a callable for DataflowBlock pass")
        return _ffi_api.MakeDataflowBlockPass(pass_arg, info)  # type: ignore

    if pass_func:
        return create_dataflowblock_pass(pass_func)
    return create_dataflowblock_pass

def make_1020_channel_selections(info, midline="z", *, return_ch_names=False):
    _validate_type(info, "info")

    try:
        from .layout import find_layout

        layout = find_layout(info)
        pos = layout.pos
        ch_names = layout.names
    except RuntimeError:  # no channel positions found
        ch_names = info["ch_names"]
        pos = None

    selections = dict(Left=[], Midline=[], Right=[])
    for pick, channel in enumerate(ch_names):
        last_char = channel[-1].lower()  # in 10/20, last char codes hemisphere
        if last_char in midline:
            selection = "Midline"
        elif last_char.isdigit():
            selection = "Left" if int(last_char) % 2 else "Right"
        else:  # ignore the channel
            continue
        selections[selection].append(pick)

    if pos is not None:
        # sort channels from front to center
        # (y-coordinate of the position info in the layout)
        selections = {
            selection: np.array(picks)[pos[picks, 1].argsort()]
            for selection, picks in selections.items()
        }

    # convert channel indices to names if requested
    if return_ch_names:
        for selection, ch_indices in selections.items():
            selections[selection] = [info.ch_names[idx] for idx in ch_indices]

    return selections

def render_content_parts(self, parts: list) -> list:
        rendered_parts = []

        for part_type, content in parts:
            if part_type == "markdown":
                # Render markdown
                try:
                    md = Markdown(content, code_theme="monokai")
                    rendered_parts.append(md)
                except Exception:
                    # Fallback to plain text with error indication
                    rendered_parts.append(
                        Text(content, style="white")
                    )

            elif part_type == "code":
                # Render code with syntax highlighting
                lang, code = content
                try:
                    from rich.syntax import Syntax

                    syntax = Syntax(
                        code,
                        lang,
                        theme="monokai",
                        line_numbers=True,
                        word_wrap=True,
                    )
                    rendered_parts.append(syntax)
                except Exception:
                    # Fallback to text with code styling
                    rendered_parts.append(
                        Text(
                            f"```{lang}\n{code}\n```",
                            style="white on grey23",
                        )
                    )

        return rendered_parts

def collate_image_dataset_batch(self, batch: Dict, num_rays_per_batch: int, keep_full_image: bool = False):
        device = batch["image"].device
        num_images, image_height, image_width, _ = batch["image"].shape

        if "mask" in batch:
            if self.config.is_equirectangular:
                indices = self.sample_method_equirectangular(
                    num_rays_per_batch, num_images, image_height, image_width, mask=batch["mask"], device=device
                )
            elif self.config.fisheye_crop_radius is not None:
                indices = self.sample_method_fisheye(
                    num_rays_per_batch, num_images, image_height, image_width, mask=batch["mask"], device=device
                )
            else:
                indices = self.sample_method(
                    num_rays_per_batch, num_images, image_height, image_width, mask=batch["mask"], device=device
                )
        else:
            if self.config.is_equirectangular:
                indices = self.sample_method_equirectangular(
                    num_rays_per_batch, num_images, image_height, image_width, device=device
                )
            elif self.config.fisheye_crop_radius is not None:
                indices = self.sample_method_fisheye(
                    num_rays_per_batch, num_images, image_height, image_width, device=device
                )
            else:
                indices = self.sample_method(num_rays_per_batch, num_images, image_height, image_width, device=device)

        c, y, x = (i.flatten() for i in torch.split(indices, 1, dim=-1))
        c, y, x = c.cpu(), y.cpu(), x.cpu()
        collated_batch = {
            key: value[c, y, x] for key, value in batch.items() if key != "image_idx" and value is not None
        }
        assert collated_batch["image"].shape[0] == num_rays_per_batch

        # Needed to correct the random indices to their actual camera idx locations.
        indices[:, 0] = batch["image_idx"][c]
        collated_batch["indices"] = indices  # with the abs camera indices
        if keep_full_image:
            collated_batch["full_image"] = batch["image"]

        return collated_batch

def replace_linear(
    model,
    linear_replacement,
    skip_modules=("lm_head",),
    copy_weights=False,
    post_processing_function=None,
):
    for name, module in model.named_children():
        if len(list(module.children())) > 0:
            replace_linear(module, linear_replacement, skip_modules, copy_weights, post_processing_function)

        if isinstance(module, torch.nn.Linear) and name not in skip_modules:
            old_module = model._modules[name]
            model._modules[name] = linear_replacement(
                module.in_features,
                module.out_features,
                module.bias is not None,
            )
            if copy_weights:
                model._modules[name].weight = old_module.weight
                model._modules[name].bias = old_module.bias

            if post_processing_function is not None:
                func = getattr(module, post_processing_function, None)
                if func is not None:
                    func(module)
    return model

def load_image(
    image: Union[str, "PIL.Image.Image"],
    timeout: float | None = None,
) -> "PIL.Image.Image":
    requires_backends(load_image, ["vision"])
    if isinstance(image, str):
        if image.startswith("http://") or image.startswith("https://"):
            # We need to actually check for a real protocol, otherwise it's impossible to use a local file
            # like http_huggingface_co.png
            image = PIL.Image.open(BytesIO(httpx.get(image, timeout=timeout, follow_redirects=True).content))
        elif os.path.isfile(image):
            image = PIL.Image.open(image)
        else:
            if image.startswith("data:image/"):
                image = image.split(",")[1]

            # Try to load as base64
            try:
                b64 = base64.decodebytes(image.encode())
                image = PIL.Image.open(BytesIO(b64))
            except Exception as e:
                raise ValueError(
                    f"Incorrect image source. Must be a valid URL starting with `http://` or `https://`, a valid path to an image file, or a base64 encoded string. Got {image}. Failed with {e}"
                )
    elif not isinstance(image, PIL.Image.Image):
        raise TypeError(
            "Incorrect format used for image. Should be an url linking to an image, a base64 string, a local path, or a PIL image."
        )
    image = PIL.ImageOps.exif_transpose(image)
    image = image.convert("RGB")
    return image

def parent(self) -> Tree | None:
        parent = self._parent
        if parent is not None:
            # Check that all parents match
            queue = [parent]

            def maybe_flatten_list(maybe_nested_list):
                if isinstance(maybe_nested_list, list):
                    for p in maybe_nested_list:
                        if isinstance(p, list):
                            queue.append(p)
                        else:
                            yield p()
                else:
                    yield maybe_nested_list()

            parent_result = None
            while len(queue):
                local_result = None
                for r in maybe_flatten_list(queue.pop()):
                    if local_result is None:
                        local_result = r
                    elif r is not None and r is not local_result:
                        if isinstance(local_result, list):
                            local_result.append(r)
                        else:
                            local_result = [local_result, r]
                if local_result is None:
                    continue
                # replicate logic at macro level
                if parent_result is None:
                    parent_result = local_result
                else:
                    if isinstance(local_result, list):
                        local_result = [
                            r for r in local_result if r not in parent_result
                        ]
                    else:
                        local_result = [local_result]
                    if isinstance(parent_result, list):
                        parent_result.extend(local_result)
                    else:
                        parent_result = [parent_result, *local_result]
            if isinstance(parent_result, list):
                return TensorDict.lazy_stack(
                    [self._from_tensordict(r) for r in parent_result]
                )
            return self._from_tensordict(parent_result)

def get_row_iterator(iterable, options=None):
    options = options or {}

    for i in range(options.get('skip_rows', 0)):
        iterable.__next__()

    # Replace any NULL bytes in the line given to the DictReader
    reader = csv.DictReader(
        io.TextIOWrapper(iterable, encoding=options.get('encoding', 'utf-8')),
        fieldnames=None,
        restkey=SDC_EXTRA_COLUMN,
        delimiter=options.get('delimiter', ',')
    )

    if 'sanitize_header' in options and options['sanitize_header']:
        reader.fieldnames = [sanitize_colname(col) for col in reader.fieldnames].copy()

    headers = set(reader.fieldnames + SDC_META_COLUMNS)

    if options.get('key_properties'):
        key_properties = set(options['key_properties'])
        if not key_properties.issubset(headers):
            raise Exception('CSV file missing required headers: {}'
                            .format(key_properties - headers))

    if options.get('date_overrides'):
        date_overrides = set(options['date_overrides'])
        if not date_overrides.issubset(headers):
            raise Exception('CSV file missing date_overrides headers: {}'
                            .format(date_overrides - headers))
    return reader

def load_model(
    checkpoint_path: str,
    params_path: str,
    max_context_len: int,
    generate_full_logits: bool = True,
):
    with open(params_path, "r") as f:
        params = json.loads(f.read())

    args = ModelArgs(
        max_context_len=max_context_len,
        generate_full_logits=generate_full_logits,
        **params,
    )
    args.attention_type = "static_mha"
    args.attention_kwargs = {"decompose_sdpa_in_mha": True}

    with torch.device("meta"):
        model = construct_transformer(args)

    checkpoint = torch.load(
        checkpoint_path, map_location="cpu", mmap=True, weights_only=True
    )
    if "model" in checkpoint:
        checkpoint = checkpoint["model"]

    # Rename attention weight keys for static attention
    for i in range(len(model.layers)):
        if f"layers.{i}.attention.wq.weight" in checkpoint:
            checkpoint[f"layers.{i}.attention.wqs.0.weight"] = checkpoint.pop(
                f"layers.{i}.attention.wq.weight"
            )
        if f"layers.{i}.attention.wk.weight" in checkpoint:
            checkpoint[f"layers.{i}.attention.wks.0.weight"] = checkpoint.pop(
                f"layers.{i}.attention.wk.weight"
            )
        if f"layers.{i}.attention.wv.weight" in checkpoint:
            checkpoint[f"layers.{i}.attention.wvs.0.weight"] = checkpoint.pop(
                f"layers.{i}.attention.wv.weight"
            )

    missing, unexpected = model.load_state_dict(
        checkpoint,
        strict=False,
        assign=True,
    )
    if missing:
        print(f"Missing keys: {missing}")
    if unexpected:
        print(f"Unexpected keys: {unexpected}")

    return model, args

def find_adjacent_layers(node: torch.fx.Node,
                         module: torch.fx.GraphModule,
                         target_types: List[torch.nn.Module],
                         direction: str = 'parent') -> List[torch.fx.Node]:

    layers = []
    if direction == 'parent':
        nodes = node.all_input_nodes
    elif direction == 'child':
        nodes = node.users
    else:
        raise ValueError("search direction should be 'parent' or 'child'")

    for node in nodes:
        if node.op == 'call_module':
            target_module = module.get_submodule(node.target)
            if isinstance(target_module, tuple(target_types)):
                layers.append(node)
                continue
        elif channel_dependency_breakpoint(node):
            continue
        layers.extend(find_adjacent_layers(node, module, target_types, direction))
    return layers

def delete_custom_component(self):
        if not self.custom_components:
            QMessageBox.information(
                self,
                self.tr("Info"),
                self.tr("No custom components to delete!"),
            )
            return

        dialog = DeleteComponentDialog(self.custom_components, self)
        if dialog.exec() == QDialog.DialogCode.Accepted:
            selected_indices = dialog.get_selected_indices()

            if not selected_indices:
                return

            component_titles = [
                self.custom_components[i]["title"] for i in selected_indices
            ]
            if len(selected_indices) == 1:
                template = self.tr(
                    "Deleting component '%s' will remove all related annotation data from the current task.\n"
                    "Do you want to continue?"
                )
                msg_text = template % component_titles[0]
            else:
                template = self.tr(
                    "Deleting %d components (%s) will remove all related annotation data from the current task.\n"
                    "Do you want to continue?"
                )
                titles_str = ", ".join(
                    f"'{title}'" for title in component_titles
                )
                msg_text = template % (len(selected_indices), titles_str)

            reply = QMessageBox.question(
                self,
                self.tr("Confirm Delete"),
                msg_text,
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )

            if reply == QMessageBox.StandardButton.Yes:
                for index in selected_indices:
                    component_title = self.custom_components[index]["title"]
                    self.remove_component(index)
                    self.clean_all_labels_for_component(component_title)

async def shutdown(self) -> None:
        for worker in self._workers:
            try:
                worker.sandbox.close()
            except Exception:
                logger.warning("Failed to close sandbox %s", worker.name, exc_info=True)
        self._workers.clear()

        # Drain the queue
        while not self._available.empty():
            try:
                self._available.get_nowait()
            except asyncio.QueueEmpty:
                break

        if self._session is not None:
            await self._session.close()
            self._session = None

        if self._result_store is not None:
            self._result_store.close()

        self._initialized = False
        logger.info("SandboxOrchestrator shut down")

def get_metadata_by_filepath(self, filepath: str):
        if type(filepath) not in [tuple, list]:
            filepath = [filepath]
        if type(filepath) is tuple or type(filepath) is list:
            for path in filepath:
                abs_path = self.data_backend.get_abs_path(path)
                if path in self.image_metadata:
                    result = self.image_metadata.get(path, None)
                    if result is not None:
                        return result
                elif abs_path in self.image_metadata:
                    filepath = abs_path
                    result = self.image_metadata.get(filepath, None)
                    if result is not None:
                        return result
            return None

        meta = self.image_metadata.get(filepath, None)
        return meta

def add_logging_level(level_name, level_num, method_name=None):
    if method_name is None:
        method_name = level_name.lower()

    # If the level name is already defined as a top-level `logging`
    # constant, then adopt the existing numeric level.
    if hasattr(logging, level_name):
        existing_level_num = getattr(logging, level_name)
        assert isinstance(existing_level_num, int)
        level_num = existing_level_num

    def log_for_level(self, message, *args, **kwargs):
        if self.isEnabledFor(level_num):
            self._log(level_num, message, args, **kwargs)

    def log_to_root(message, *args, **kwargs):
        logging.log(level_num, message, *args, **kwargs)  # noqa: LOG015

    # getLevelName resolves the numeric log level if already defined,
    # otherwise returns a string
    if not isinstance(logging.getLevelName(level_name), int):
        logging.addLevelName(level_num, level_name)

    if not hasattr(logging, level_name):
        setattr(logging, level_name, level_num)

    if not hasattr(logging.getLoggerClass(), method_name):
        setattr(logging.getLoggerClass(), method_name, log_for_level)

    if not hasattr(logging, method_name):
        setattr(logging, method_name, log_to_root)

def to_sfm_string(tree, encoding=None, errors="strict", unicode_fields=None):
    if tree.tag == "record":
        root = Element("toolbox_data")
        root.append(tree)
        tree = root

    if tree.tag != "toolbox_data":
        raise ValueError("not a toolbox_data element structure")
    if encoding is None and unicode_fields is not None:
        raise ValueError(
            "if encoding is not specified then neither should unicode_fields"
        )
    l = []
    for rec in tree:
        l.append("\n")
        for field in rec:
            mkr = field.tag
            value = field.text
            if encoding is not None:
                if unicode_fields is not None and mkr in unicode_fields:
                    cur_encoding = "utf8"
                else:
                    cur_encoding = encoding
                if re.search(_is_value, value):
                    l.append((f"\\{mkr} {value}\n").encode(cur_encoding, errors))
                else:
                    l.append((f"\\{mkr}{value}\n").encode(cur_encoding, errors))
            else:
                if re.search(_is_value, value):
                    l.append(f"\\{mkr} {value}\n")
                else:
                    l.append(f"\\{mkr}{value}\n")
    return "".join(l[1:])

def debug_one(self, x: dict) -> str | None:
        if self._root is None:
            return

        # We'll redirect all the print statement to a buffer, we'll return the content of the
        # buffer at the end
        buffer = io.StringIO()
        _print = functools.partial(print, file=buffer)

        for node in self._root.walk(x, until_leaf=True):
            if isinstance(node, HTLeaf):
                _print(repr(node))
            elif isinstance(node, DTBranch):
                try:
                    child_index = node.branch_no(x)
                except KeyError:
                    child_index, _ = node.most_common_path()

                _print(node.repr_branch(child_index))

        return buffer.getvalue()

def tensor_to_image(tensor: torch.Tensor, keepdim: bool = False, force_contiguous: bool = False) -> Any:
    if not isinstance(tensor, torch.Tensor):
        raise TypeError(f"Input type is not a torch.Tensor. Got {type(tensor)}")

    if len(tensor.shape) > 4 or len(tensor.shape) < 2:
        raise ValueError("Input size must be a two, three or four dimensional tensor")

    input_shape = tensor.shape
    image = tensor.cpu().detach()

    if len(input_shape) == 2:
        # (H, W) -> (H, W)
        pass
    elif len(input_shape) == 3:
        # (C, H, W) -> (H, W, C)
        if input_shape[0] == 1:
            # Grayscale for proper plt.imshow needs to be (H,W)
            image = image.squeeze()
        else:
            image = image.permute(1, 2, 0)
    elif len(input_shape) == 4:
        # (B, C, H, W) -> (B, H, W, C)
        image = image.permute(0, 2, 3, 1)
        if input_shape[0] == 1 and not keepdim:
            image = image.squeeze(0)
        if input_shape[1] == 1:
            image = image.squeeze(-1)
    else:
        raise ValueError(f"Cannot process tensor with shape {input_shape}")

    # make sure the image is contiguous
    if force_contiguous:
        image = image.contiguous()

    return image.numpy()

async def upload_dir(self, source: str, destination: str) -> None:
        _logger.debug(f"Uploading directory {source} to {destination}")
        _err_prefix = (
            f"Could not upload directory {source} to GCS destination {destination}"
        )
        if not os.path.isdir(source):
            raise LaunchError(f"{_err_prefix}: Directory {source} does not exist.")
        match = GCS_URI_RE.match(destination)
        if not match:
            raise LaunchError(f"{_err_prefix}: Invalid GCS URI: {destination}")
        bucket = match.group(1)
        key = match.group(2).lstrip("/")
        google_storage_client = event_loop_thread_exec(google.cloud.storage.Client)
        credentials = await self.get_credentials()
        try:
            storage_client = await google_storage_client(credentials=credentials)
            bucket = await event_loop_thread_exec(storage_client.bucket)(bucket)
            for root, _, files in os.walk(source):
                for file in files:
                    local_path = os.path.join(root, file)
                    gcs_path = os.path.join(
                        key, os.path.relpath(local_path, source)
                    ).replace("\\", "/")
                    blob = await event_loop_thread_exec(bucket.blob)(gcs_path)
                    await event_loop_thread_exec(blob.upload_from_filename)(local_path)
        except google.api_core.exceptions.GoogleAPICallError as e:
            resp = e.response
            assert resp is not None
            try:
                message = resp.json()["error"]["message"]
            except Exception:
                message = str(resp)
            raise LaunchError(f"{_err_prefix}: {message}") from e
        except Exception as e:
            raise LaunchError(f"{_err_prefix}: GCS upload failed: {e}") from e

def collapse_variadic_parameters(
    fn: Callable[..., Any], parameters: dict[str, Any]
) -> dict[str, Any]:
    signature_parameters = inspect.signature(fn).parameters
    variadic_key = None
    for key, parameter in signature_parameters.items():
        if parameter.kind == parameter.VAR_KEYWORD:
            variadic_key = key
            break

    missing_parameters = set(parameters.keys()) - set(signature_parameters.keys())

    if not missing_parameters:
        # no missing parameters, return parameters unchanged
        return parameters

    if not variadic_key:
        raise ValueError(
            f"Signature for {fn} does not include any variadic keyword argument "
            "but parameters were given that are not present in the signature."
        )

    new_parameters = parameters.copy()
    new_parameters[variadic_key] = {
        key: new_parameters.pop(key) for key in missing_parameters
    }
    return new_parameters

def write(self) -> None:
        rio._logger.debug(f"Writing `{self.rio_toml_path}`")

        # Make sure the parent directory exists
        self.rio_toml_path.parent.mkdir(parents=True, exist_ok=True)

        # Fetch an up-to-date copy of the file contents, with all formatting
        # intact
        try:
            new_toml_dict = tomlkit.loads(self.rio_toml_path.read_text())

        # If it can't be read, preserve all known values
        except (OSError, tomlkit.exceptions.TOMLKitError):
            new_toml_dict = tomlkit.TOMLDocument()
            self._dirty_keys = set(self._toml_dict.keys())

        # Avoid writing the file if nothing changed
        if not self._dirty_keys:
            return

        # Update the freshly read toml with all latent changes
        for section_name, key_name in self._dirty_keys:
            # Get the section from the on-disk toml
            try:
                section = new_toml_dict[section_name]
            except KeyError:
                section = new_toml_dict[section_name] = tomlkit.table()

            # Get the key from the in-memory section. If it can't be found, the
            # key was deleted
            try:
                value = self._toml_dict[(section_name, key_name)]
            except KeyError:
                del section[key_name]  # type: ignore
            else:
                section[key_name] = value  # type: ignore

        # Write the file
        try:
            with self.rio_toml_path.open("w") as f:
                tomlkit.dump(new_toml_dict, f)

        except OSError as e:
            revel.fatal(
                f"Couldn't write `{self.rio_toml_path}`: {e}",
                status_code=1,
            )

        # The project's keys are now clean
        self._dirty_keys.clear()

def use_params(self, params: Dict[Tuple[int, str], FloatsXd]):
        backup = {}
        for name in self.param_names:
            key = (self.id, name)
            if key in params:
                backup[name] = self.get_param(name)
                self.set_param(name, params[key])

        with contextlib.ExitStack() as stack:
            for layer in self.layers:
                stack.enter_context(layer.use_params(params))
            for shim in self.shims:
                stack.enter_context(shim.use_params(params))
            yield
        if backup:
            for name, param in backup.items():
                self.set_param(name, param)

def update_from_env_vars(self, environ: Dict[str, Any]):
        env_prefix: str = "WANDB_"
        private_env_prefix: str = env_prefix + "_"
        special_env_var_names = {
            env.APP_URL: "app_url_override",
            "WANDB_SERVICE_TRANSPORT": "x_service_transport",
            env.DIR: "root_dir",
            env.NAME: "run_name",
            env.NOTES: "run_notes",
            env.TAGS: "run_tags",
            env.JOB_TYPE: "run_job_type",
            env.HTTP_TIMEOUT: "x_graphql_timeout_seconds",
            env.FILE_PUSHER_TIMEOUT: "x_file_transfer_timeout_seconds",
            env.USER_EMAIL: "email",
        }

        for setting, value in environ.items():
            if not setting.startswith(env_prefix):
                continue

            if setting in special_env_var_names:
                key = special_env_var_names[setting]
            elif setting.startswith(private_env_prefix):
                key = "x_" + setting[len(private_env_prefix) :].lower()
            else:
                # otherwise, strip the prefix and convert to lowercase
                key = setting[len(env_prefix) :].lower()

            if key not in self.__dict__:
                continue

            if key in ("ignore_globs", "run_tags"):
                value = value.split(",")

            if value is None:
                continue

            setattr(self, key, value)

def smartirs_wlocal(tf, local_scheme):
    if local_scheme == "n":
        return tf
    elif local_scheme == "l":
        return 1 + np.log2(tf)
    elif local_scheme == "d":
        return 1 + np.log2(1 + np.log2(tf))
    elif local_scheme == "a":
        return 0.5 + (0.5 * tf / tf.max(axis=0))
    elif local_scheme == "b":
        return tf.astype('bool').astype('int')
    elif local_scheme == "L":
        return (1 + np.log2(tf)) / (1 + np.log2(tf.mean(axis=0)))

def has_active_ssh_sessions() -> bool:
    try:
        pts_to_pid: dict[str, int] = {}
        for proc in psutil.process_iter(['pid', 'terminal']):
            terminal = proc.info['terminal']
            if terminal and terminal.startswith('/dev/pts/'):
                pts_to_pid.setdefault(terminal, proc.info['pid'])

        for pid in pts_to_pid.values():
            try:
                for parent in psutil.Process(pid).parents():
                    if parent.name() == 'sshd':
                        return True
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        return False
    except Exception as e:  # pylint: disable=broad-except
        logger.warning(f'Error checking active SSH sessions: {e}.')
        return False

def get_column_types(X: np.ndarray) -> list[str]:
        # TODO(eddiebergman): Bad to keep calling skew again and again here...
        column_types = []
        for col in range(X.shape[1]):
            if np.unique(X[:, col]).size < 10:
                column_types.append(f"ordinal_{col}")
            elif (
                _skew(X[:, col]) > 1.1
                and np.min(X[:, col]) >= 0
                and np.max(X[:, col]) <= 1
            ):
                column_types.append(f"skewed_pos_1_0_{col}")
            elif _skew(X[:, col]) > 1.1 and np.min(X[:, col]) > 0:
                column_types.append(f"skewed_pos_{col}")
            elif _skew(X[:, col]) > 1.1:
                column_types.append(f"skewed_{col}")
            elif shapiro(X[0:3000, col]).statistic > 0.95:
                column_types.append(f"normal_{col}")
            else:
                column_types.append(f"other_{col}")
        return column_types

def aggregate_metricrecords(
    records: list[RecordDict], weighting_metric_name: str
) -> MetricRecord:
    # Retrieve weighting factor from MetricRecord
    weights: list[float] = []
    for record in records:
        # Get the first (and only) MetricRecord in the record
        metricrecord = next(iter(record.metric_records.values()))
        # Because replies have been checked for consistency,
        # we can safely cast the weighting factor to float
        w = cast(float, metricrecord[weighting_metric_name])
        weights.append(w)

    # Average
    total_weight = sum(weights)
    weight_factors = [w / total_weight for w in weights]

    aggregated_metrics = MetricRecord()
    for record, weight in zip(records, weight_factors, strict=True):
        for record_item in record.metric_records.values():
            # aggregate in-place
            for key, value in record_item.items():
                if key == weighting_metric_name:
                    # We exclude the weighting key from the aggregated MetricRecord
                    continue
                if key not in aggregated_metrics:
                    if isinstance(value, list):
                        aggregated_metrics[key] = [v * weight for v in value]
                    else:
                        aggregated_metrics[key] = value * weight
                else:
                    if isinstance(value, list):
                        current_list = cast(list[float], aggregated_metrics[key])
                        aggregated_metrics[key] = [
                            curr + val * weight
                            for curr, val in zip(current_list, value, strict=True)
                        ]
                    else:
                        current_value = cast(float, aggregated_metrics[key])
                        aggregated_metrics[key] = current_value + value * weight

    return aggregated_metrics

def register_layer(
      fct_in,
      default_args=None,
      default_kwargs=None,
      use_dp=True,
      recompute_grad=False,
  ):
    # The kwargs given when calling the function overwrite the default ones
    fct_in = partial(fct_in, *(default_args or []), **(default_kwargs or {}))

    @functools.wraps(fct_in)
    def decorator(x, *args, **kwargs):
      """Call the layer function."""
      fct = fct_in  # For closure. Could use nonlocal with Python 3
      # Eventually create the memory optimized version of the function
      if recompute_grad:
        fct = partial(fct, **kwargs)  # recompute_grad only accept args
        fct = common_layers.recompute_grad(fct)
        kwargs = {}

      # Eventually use dp (if given and not MoE)
      if use_dp and dp is not None:
        y = dp(fct, x, *args, **kwargs)
      else:
        y = fct(x, *args, **kwargs)

      # Eventually capture the extra loss
      extra_loss = 0.0
      if isinstance(y, tuple):
        y, extra_loss = y

      return y, extra_loss

    return decorator

def pretty_print(self, normalize=None):
        if normalize is None:
            normalize = lambda x: x.replace("(", "-LRB-").replace(")", "-RRB-")

        indent = 0
        with StringIO() as buf:
            stack = deque()
            stack.append(self)
            while len(stack) > 0:
                node = stack.pop()

                if node is CLOSE_PAREN:
                    # if we're trying to pretty print trees, pop all off close parens
                    # then write a newline
                    while node is CLOSE_PAREN:
                        indent -= 1
                        buf.write(CLOSE_PAREN)
                        if len(stack) == 0:
                            node = None
                            break
                        node = stack.pop()
                    buf.write("\n")
                    if node is None:
                        break
                    stack.append(node)
                elif node.is_preterminal():
                    buf.write("  " * indent)
                    buf.write("%s%s %s%s" % (OPEN_PAREN, normalize(node.label), normalize(node.children[0].label), CLOSE_PAREN))
                    if len(stack) == 0 or stack[-1] is not CLOSE_PAREN:
                        buf.write("\n")
                elif all(x.is_preterminal() for x in node.children):
                    buf.write("  " * indent)
                    buf.write("%s%s" % (OPEN_PAREN, normalize(node.label)))
                    for child in node.children:
                        buf.write(" %s%s %s%s" % (OPEN_PAREN, normalize(child.label), normalize(child.children[0].label), CLOSE_PAREN))
                    buf.write(CLOSE_PAREN)
                    if len(stack) == 0 or stack[-1] is not CLOSE_PAREN:
                        buf.write("\n")
                else:
                    buf.write("  " * indent)
                    buf.write("%s%s\n" % (OPEN_PAREN, normalize(node.label)))
                    stack.append(CLOSE_PAREN)
                    for child in reversed(node.children):
                        stack.append(child)
                    indent += 1

            buf.seek(0)
            return buf.read()

def dependency_tree(
        self, filename: str | None = None
    ) -> DependencyTreeNode | None:

        # Skip if not a script and not inside a uv-managed project
        if filename is None and not self.is_in_uv_project:
            return None

        tree_cmd = [self._uv_bin, "tree", "--no-dedupe"]
        if filename:
            tree_cmd += ["--script", filename]

        try:
            result = subprocess.run(
                tree_cmd,
                capture_output=True,
                text=True,
                encoding="utf-8",
                check=True,
            )
            tree = parse_uv_tree(result.stdout)

            # If in a uv project and the only top-level item is the project itself,
            # return its dependencies directly
            if filename is None and len(tree.dependencies) == 1:
                return tree.dependencies[0]

            return tree

        except subprocess.CalledProcessError:
            # Only log error if the script has dependency metadata
            if filename and self._has_script_metadata(filename):
                LOGGER.error(f"Failed to get dependency tree for {filename}")
            return None

def get_calibration_config(self) -> Dict[str, Dict[str, Dict[str, torch.Tensor | Any]]]:
        calibration_config = defaultdict(dict)
        for module_name, wrapper in self._module_wrappers.items():
            for target_name, target_space in wrapper.quantization_target_spaces.items():
                calibration_config[module_name][target_name] = {
                    'scale': target_space.scale.cpu() if isinstance(target_space.scale, torch.Tensor) \
                        else target_space.scale,
                    'zero_point': target_space.zero_point.cpu() if isinstance(target_space.zero_point, torch.Tensor) \
                        else target_space.zero_point,
                    'quant_dtype': target_space.quant_dtype if target_space.quant_dtype else 'int8',
                    'quant_scheme': target_space.quant_scheme,
                    'quant_bits': target_space.quant_bits,
                }
                if target_space.tracked_max is not None:
                    calibration_config[module_name][target_name]['tracked_max'] = target_space.tracked_max.cpu()
                elif target_space.zero_point is not None and target_space.scale is not None:
                    tracked_max = target_space.scale * (target_space.qmax - target_space.zero_point)
                    calibration_config[module_name][target_name]['tracked_max'] = tracked_max.cpu()
                if target_space.tracked_min is not None:
                    calibration_config[module_name][target_name]['tracked_min'] = target_space.tracked_min.cpu()
                elif target_space.zero_point is not None and target_space.scale is not None:
                    tracked_min = target_space.scale * (target_space.qmin - target_space.zero_point)
                    calibration_config[module_name][target_name]['tracked_min'] = tracked_min.cpu()

        return calibration_config

def forecast(
        self,
        y: np.ndarray,
        h: int,
        X: Optional[np.ndarray] = None,
        X_future: Optional[np.ndarray] = None,
        level: Optional[List[int]] = None,
        fitted: bool = False,
    ):
        y = _ensure_float(y)
        mod = garch_model(y, p=self.p, q=self.q)
        fcst = garch_forecast(mod, h)
        keys = ["mean", "sigma2"]
        if fitted:
            keys.append("fitted")
        res = {key: fcst[key] for key in keys}
        if level is not None:
            level = sorted(level)
            if self.prediction_intervals is not None:
                res = self._add_predict_conformal_intervals(res, level)
            else:
                quantiles = _quantiles(level)
                lo = res["mean"].reshape(-1, 1) - quantiles * res["sigma2"].reshape(
                    -1, 1
                )
                hi = res["mean"].reshape(-1, 1) + quantiles * res["sigma2"].reshape(
                    -1, 1
                )
                lo = lo[:, ::-1]
                lo = {f"lo-{l}": lo[:, i] for i, l in enumerate(reversed(level))}
                hi = {f"hi-{l}": hi[:, i] for i, l in enumerate(level)}
                res = {**res, **lo, **hi}
            if fitted:
                se = _calculate_sigma(y - mod["fitted"], len(y) - 1)
                res = _add_fitted_pi(res=res, se=se, level=level)
        return res

def generate_samples(self, data_dir, tmp_dir, dataset_split):
    # If not training, do the same as before.
    if dataset_split != problem.DatasetSplit.TRAIN:
      for x in super(TranslateEnroWmtMultiSmall64k, self).generate_samples(
          data_dir, tmp_dir, dataset_split):
        yield x
      raise StopIteration
    # Now we assume we're training.
    counter = 0
    # The size of this data-set in total is around 614K, we want to sample so
    # that in expectation we take the requested number of samples in 1 go.
    sample_prob = self.how_many_examples_to_sample / float(614000)
    # Let's sample.
    for x in super(TranslateEnroWmtMultiSmall64k, self).generate_samples(
        data_dir, tmp_dir, dataset_split):
      if random.random() > sample_prob:
        continue
      counter += 1
      if counter > self.how_many_examples_to_sample:
        raise StopIteration
      yield x
    # We do it again if we don't have enough samples.
    if counter < self.how_many_examples_to_sample:
      for x in super(TranslateEnroWmtMultiSmall64k, self).generate_samples(
          data_dir, tmp_dir, dataset_split):
        if random.random() > sample_prob:
          continue
        counter += 1
        if counter > self.how_many_examples_to_sample:
          raise StopIteration
        yield x

def sort_auto_mapping(fname: str, overwrite: bool = False) -> bool | None:
    with open(fname, "r", encoding="utf-8") as f:
        content = f.read()

    lines = content.split("\n")
    new_lines = []
    line_idx = 0
    while line_idx < len(lines):
        if _re_intro_mapping.search(lines[line_idx]) is not None:
            # Start of a new mapping!
            indent = len(re.search(r"^(\s*)\S", lines[line_idx]).groups()[0]) + 8
            while not lines[line_idx].startswith(" " * indent + "("):
                new_lines.append(lines[line_idx])
                line_idx += 1

            blocks = []
            while lines[line_idx].strip() != "]":
                # Blocks either fit in one line or not
                if lines[line_idx].strip() == "(":
                    start_idx = line_idx
                    while not lines[line_idx].startswith(" " * indent + ")"):
                        line_idx += 1
                    blocks.append("\n".join(lines[start_idx : line_idx + 1]))
                else:
                    blocks.append(lines[line_idx])
                line_idx += 1

            # Sort blocks by their identifiers
            blocks = sorted(blocks, key=lambda x: _re_identifier.search(x).groups()[0])
            new_lines += blocks
        else:
            new_lines.append(lines[line_idx])
            line_idx += 1

    if overwrite:
        with open(fname, "w", encoding="utf-8") as f:
            f.write("\n".join(new_lines))
    else:
        return "\n".join(new_lines) != content

def class_encode_column(self, column: str, include_nulls: bool = False) -> "Dataset":
        # Sanity checks
        if column not in self._data.column_names:
            raise ValueError(f"Column ({column}) not in table columns ({self._data.column_names}).")
        src_feat = self._info.features[column]
        if not isinstance(src_feat, Value):
            raise ValueError(
                f"Class encoding is only supported for {Value.__name__} column, and column {column} is {type(src_feat).__name__}."
            )

        if src_feat.dtype != "string" or (include_nulls and None in self.unique(column)):

            def stringify_column(batch):
                batch[column] = [
                    str(sample) if include_nulls or sample is not None else None for sample in batch[column]
                ]
                return batch

            dset = self.map(
                stringify_column,
                batched=True,
                desc="Stringifying the column",
            )
        else:
            dset = self

        # Create the new feature
        class_names = sorted(str(sample) for sample in dset.unique(column) if include_nulls or sample is not None)
        dst_feat = ClassLabel(names=class_names)

        def cast_to_class_labels(batch):
            batch[column] = [
                dst_feat.str2int(str(sample)) if include_nulls or sample is not None else None
                for sample in batch[column]
            ]
            return batch

        new_features = dset.features.copy()
        new_features[column] = dst_feat

        dset = dset.map(
            cast_to_class_labels,
            batched=True,
            features=new_features,
            desc="Casting to class labels",
        )

        return dset

def maybe_replace_symbols_with_source_tensor_shape_variables(
    shape: SYMBOLIC_SHAPE_TYPE, source_tensors: List[Var]
) -> VARIABLE_SHAPE_TYPE:
    result_shape = []
    for size in shape:
        if is_symbolic(size):
            found_symbol_source = False
            for tensor in source_tensors:
                for i in range(tensor.rank):
                    if str(size) == str(tensor.shape[i]):
                        result_shape.append(pymil_value_at(mb.shape(x=tensor), i))
                        found_symbol_source = True
                        break
                if found_symbol_source:
                    break
            if not found_symbol_source:
                raise ValueError(f"Symbol {str(size)} not found in source tensor shapes")
        else:
            result_shape.append(size)
    return result_shape

def step(self, action: int) -> tuple[str, float, bool, dict]:
        if self._done:
            return self.render(), 0.0, True, {"action_is_effective": False}

        if action == ACTION_INVALID or action not in _DELTAS:
            return self.render(), 0.0, False, {"action_is_effective": False}

        prev = self._player
        dr, dc = _DELTAS[action]
        nr, nc = prev[0] + dr, prev[1] + dc

        # Boundary check
        if 0 <= nr < self.size and 0 <= nc < self.size:
            self._player = (nr, nc)

        tile = self._map[self._player[0]][self._player[1]]
        effective = self._player != prev

        if tile == "G":
            self._done = True
            return self.render(), 1.0, True, {"action_is_effective": effective}
        if tile == "H":
            self._done = True
            return self.render(), 0.0, True, {"action_is_effective": effective}

        return self.render(), 0.0, False, {"action_is_effective": effective}

def get_indices(self, table, selection):
        if self.selected_feature == IDENTITY_STR:
            items = table.ids
            ids = range(len(table))
        elif self.selected_feature == EQUALITY_STR:
            items, ids = np.unique(self._hashes(table), return_index=True)
        else:
            items = getattr(table[:, self.selected_feature], 'metas')
            if self.output_duplicates and selection:
                items, inverse = np.unique(items, return_inverse=True)
                ids = [np.nonzero(inverse == idx)[0] for idx in range(len(items))]
            else:
                items, ids = np.unique(items, return_index=True)

        if selection:
            return {item: idx for item, idx in zip(items, ids)
                    if item in self.selected_items}

        return dict(zip(items, ids))

def collect_granular(
        self,
        target: Optional[str] = None,
        with_deps: bool = False,
        recursive: bool = False,
        graph: Optional["DiGraph"] = None,
    ) -> list[StageInfo]:
        if not target:
            return [StageInfo(stage) for stage in self.repo.index.stages]

        target = as_posix(target)

        stages, file, _ = _collect_specific_target(self, target, with_deps, recursive)
        if not stages:
            if not (recursive and self.fs.isdir(target)):
                try:
                    (out,) = self.repo.find_outs_by_path(target, strict=False)
                    return [StageInfo(out.stage, self.fs.abspath(target))]
                except OutputNotFoundError:
                    pass

            from dvc.dvcfile import is_valid_filename
            from dvc.stage.exceptions import StageFileDoesNotExistError, StageNotFound

            try:
                stages = self.collect(target, with_deps, recursive, graph)
            except StageFileDoesNotExistError as exc:
                # collect() might try to use `target` as a stage name
                # and throw error that dvc.yaml does not exist, whereas it
                # should say that both stage name and file does not exist.
                if file and is_valid_filename(file):
                    raise
                raise NoOutputOrStageError(target, exc.file) from exc
            except StageNotFound as exc:
                raise NoOutputOrStageError(target, exc.file) from exc

        return [StageInfo(stage) for stage in stages]

def get_all_local_in_call_stack(
    key: str,
    func: Callable[[Callable], bool],
    offset: Optional[int] = 1,
    skip: Optional[Any] = None,  # really frame
) -> Iterator[Any]:

    frames_gen = stack_with_tasks()
    # NOTE: skipping offset frames is done below since the full stack may need
    # to be reconstructed there.

    # Using queue for frames as additional frames may be added due to handling threads.
    q = queue.Queue()
    for i, f in enumerate(frames_gen):
        if i == 0:
            # skip this method itself
            continue
        q.put(f)

    while not q.empty():
        f = q.get()

        if id(f.f_code) == id(_future_target_wrapper.__code__):
            locs = f.f_locals
            assert (
                "pre_start_stack" in locs
            ), "Pre thread start stack expected but not found."
            for fi in locs["pre_start_stack"].get():  # is WeakWrapper
                q.put(fi.frame)

            continue

        if offset is not None and offset > 0:
            offset -= 1
            continue

        if func(f.f_code):
            logger.debug(
                "Looking via %s; found %s", callable_name(func), str(f)
            )
            if skip is not None and f == skip:
                logger.debug("Skipping.")
                continue

            locs = f.f_locals
            if key in locs:
                yield locs[key]
            else:
                raise KeyError(f"No local named '{key}' found in frame {f}.")

    return

def sort(self, x: Dict, indices: List):
        if isinstance(x, list) and BBOX in x[0]:  # for detection outputs just sort the batches
            return [xi for _, xi in sorted(zip(indices, x), key=lambda ele: ele[0])]

        results = dict()
        for k, v in x.items():
            if isinstance(v, dict):
                results[k] = self.sort(v, indices)
            else:
                assert len(indices) == len(v), (
                    f"Size mismatch, {k}: {v} of len {len(v)} and indices {indices} of length {len(indices)}"
                )
                results[k] = [x for _, x in sorted(zip(indices, v), key=lambda ele: ele[0])]
                results[k] = torch.stack(results[k])

        return results

def step(self, actions) -> dm_env.TimeStep:
    if not self._initialized:
      return self.reset()

    converted_actions = []
    for i, (action, converter) in enumerate(zip(actions, self._converters)):
      if action is None:
        if self._target_game_loops[i] <= self._game_loop:
          raise RuntimeError('No action specified when its your turn.')
        converted_actions.append(sc2_actions.FUNCTIONS.no_op())
      else:
        if (self._target_game_loops[i] > self._game_loop and
            not self._allow_out_of_turn_actions):
          raise RuntimeError('Can\'t act when not your turn.')
        action_with_delay = converter.convert_action(action)
        self._target_game_loops[i] = self._game_loop + action_with_delay.delay
        num_actions = len(action_with_delay.request_action.actions)
        if not num_actions:
          converted_actions.append(sc2api_pb2.Action())
        else:
          converted_actions.append(
              [action_with_delay.request_action.actions[0]] * num_actions)

    min_delay = min(g for g in self._target_game_loops) - self._game_loop
    timestep = self._convert_timesteps(
        self._env.step(converted_actions, min_delay))

    self._game_loop = max(int(obs['game_loop']) for obs in timestep.observation)

    if timestep.last():
      self._initialized = False
      self._target_game_loops = [0] * len(self._target_game_loops)
    return timestep

def extract_access_token(self, **kwargs) -> str:
        if "headers" not in kwargs:
            raise ValueError("Missing keywork argument 'headers'")
        if not isinstance(kwargs["headers"], dict):
            raise ValueError(
                f"The keywork argument 'headers' is not of the expected type {dict.__name__}"
            )

        access_token = None
        headers = kwargs["headers"]
        if isinstance(headers, dict):
            for header in headers:
                if header.lower() == "authorization":
                    # With Arrow Flight, the header value is a list and we take the 0-th element
                    if not isinstance(headers[header], list):
                        raise AuthenticationError(
                            f"Authorization header must be of type list, found {type(headers[header])}"
                        )

                    return self._extract_bearer_token(headers[header][0])

        if access_token is None:
            raise AuthenticationError("Missing authorization header")

        return access_token

def parse(self, tokens):
        self._tokens = list(tokens)
        chart = []
        for i in range(0, len(self._tokens) + 1):
            chart.append([])
            for j in range(0, len(self._tokens) + 1):
                chart[i].append(ChartCell(i, j))
                if i == j + 1:
                    chart[i][j].add(DependencySpan(i - 1, i, i - 1, [-1], ["null"]))

        for i in range(1, len(self._tokens) + 1):
            for j in range(i - 2, -1, -1):
                for k in range(i - 1, j, -1):
                    for span1 in chart[k][j]._entries:
                        for span2 in chart[i][k]._entries:
                            for newspan in self.concatenate(span1, span2):
                                chart[i][j].add(newspan)

        for parse in chart[len(self._tokens)][0]._entries:
            conll_format = ""
            #            malt_format = ""
            for i in range(len(tokens)):
                #                malt_format += '%s\t%s\t%d\t%s\n' % (tokens[i], 'null', parse._arcs[i] + 1, 'null')
                # conll_format += '\t%d\t%s\t%s\t%s\t%s\t%s\t%d\t%s\t%s\t%s\n' % (i+1, tokens[i], tokens[i], 'null', 'null', 'null', parse._arcs[i] + 1, 'null', '-', '-')
                # Modify to comply with the new Dependency Graph requirement (at least must have an root elements)
                conll_format += "\t%d\t%s\t%s\t%s\t%s\t%s\t%d\t%s\t%s\t%s\n" % (
                    i + 1,
                    tokens[i],
                    tokens[i],
                    "null",
                    "null",
                    "null",
                    parse._arcs[i] + 1,
                    "ROOT",
                    "-",
                    "-",
                )
            dg = DependencyGraph(conll_format)
            #           if self.meets_arity(dg):
            yield dg.tree()

def stop(
        self,
        timeout: Optional[float] = None,
        wait_for_reporter: Optional[bool] = True,
    ) -> None:
        if not self._thread or not self._stop_event or not self.optimizer:
            if self._thread_reporter and wait_for_reporter:
                self._thread_reporter.join()
            return

        _thread = self._thread
        self._stop_event.set()
        self.optimizer.stop()

        # wait for optimizer thread
        if timeout is not None:
            _thread.join(timeout=timeout * 60.0)

        # stop all running tasks:
        for j in self.optimizer.get_running_jobs():
            j.abort()

        # clear thread
        self._thread = None
        if wait_for_reporter:
            # wait for reporter to flush
            self._thread_reporter.join()

def static_resource(namespace: str, filepath: Union[Path, str]) -> Path:
    if not isinstance(filepath, Path):
        filepath = Path(filepath)

    if sys.version_info >= (3, 14):
        from importlib.resources.abc import Traversable

        _trulens_resources: Traversable = importlib_resources.files(
            f"trulens.{namespace}"
        )
        with importlib_resources.as_file(
            _trulens_resources / filepath
        ) as _path:
            return _path
    elif sys.version_info >= (3, 9):
        # This does not exist in 3.8
        from importlib.abc import Traversable

        _trulens_resources: Traversable = importlib_resources.files(
            f"trulens.{namespace}"
        )
        with importlib_resources.as_file(
            _trulens_resources / filepath
        ) as _path:
            return _path
    else:
        # This is deprecated starting 3.11
        parts = filepath.parts
        with importlib_resources.path("trulens", parts[0]) as _path:
            # NOTE: resources.path does not allow the resource to include folders.
            for part in parts[1:]:
                _path = _path / part
            return _path

def download_debug_dump(dump_filename: str,
                        local_path: Optional[str] = None) -> str:
    response = server_common.make_authenticated_request(
        'GET',
        f'/debug/dump_download/{dump_filename}',
        stream=True,
    )

    with response:
        if response.status_code != 200:
            try:
                detail = response.json().get('detail', 'Unknown error')
            except (json.JSONDecodeError, ValueError):
                detail = response.text or f'HTTP {response.status_code}'
            raise exceptions.ClientError(
                f'Failed to download debug dump: {detail}')

        if local_path is None:
            local_path = dump_filename

        with open(local_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

    return local_path

async def get_lost_followers(self) -> list[ReceivedEvent]:
        cutoff_time = prefect.types._datetime.now("UTC") - PRECEDING_EVENT_LOOKBACK

        async with self._lock:
            lost_ids = [
                event_id
                for event_id, received_time in self._waitlist.items()
                if received_time <= cutoff_time
            ]

            # Remove lost followers from our tracking
            lost_events: list[ReceivedEvent] = []
            for event_id in lost_ids:
                if event_id in self._events:
                    event = self._events[event_id]
                    lost_events.append(event)

                    # Clean up tracking for this lost event
                    if event.follows and event.follows in self._followers:
                        self._followers[event.follows].discard(event_id)
                        if not self._followers[event.follows]:
                            del self._followers[event.follows]

                    del self._events[event_id]
                    del self._waitlist[event_id]

        return sorted(lost_events, key=lambda f: f.occurred)

def completed(self, engine: Engine, name: str) -> None:
        result = self.compute()
        if isinstance(result, Mapping):
            # Only raise conflict when we will set the mapping under `name`.
            if self._metrics_result_mode in ("named", "both") and name in result.keys():
                raise ValueError(f"Argument name '{name}' is conflicting with mapping keys: {list(result.keys())}")

            if self._metrics_result_mode in ("flatten", "both"):
                for key, value in result.items():
                    engine.state.metrics[key] = value

            if self._metrics_result_mode in ("named", "both"):
                engine.state.metrics[name] = result
        else:
            if isinstance(result, torch.Tensor):
                if len(result.size()) == 0:
                    result = result.item()
                elif "cpu" not in result.device.type:
                    result = result.cpu()

            engine.state.metrics[name] = result

def build_done_event(session: Session) -> str:
    cell_notif = session.session_view.cell_notifications.get(SCRATCH_CELL_ID)
    if cell_notif is None:
        return _format_sse("done", DoneSuccess(success=True))

    output = cell_notif.output

    # Error case
    if (
        output is not None
        and output.channel == CellChannel.MARIMO_ERROR
        and isinstance(output.data, list)
        and output.data
    ):
        err = output.data[0]
        error_data = ErrorData(
            type=type(err).__name__,
            msg=str(getattr(err, "msg", None) or err),
        )
        if hasattr(err, "exception_type"):
            error_data["exception_type"] = err.exception_type
            if err.exception_type in (
                "ModuleNotFoundError",
                "ImportError",
            ):
                error_data["msg"] += (
                    "\n\nHint: Use ctx.install_packages(...)"
                    " to install missing packages."
                )
        return _format_sse("done", DoneError(success=False, error=error_data))

    # Success case
    if output is not None:
        data = output.data
        if isinstance(data, dict):
            data = data.get("text/plain", data.get("text/html", str(data)))
        return _format_sse(
            "done",
            DoneSuccess(
                success=True,
                output=OutputData(
                    mimetype=str(output.mimetype), data=str(data)
                ),
            ),
        )

    return _format_sse("done", DoneSuccess(success=True))

def collect_project_tools(
    project: Project,
    allowed_tool_ids: Sequence[str] | None = None,
) -> list[ToolResolution]:

    allowed_set = set(allowed_tool_ids or [])
    missing_ids = set(allowed_set)
    resolutions: list[ToolResolution] = []

    for rag_config in project.rag_configs(readonly=True):
        if rag_config.is_archived:
            logger.debug(
                "Skipping archived RAG config %s",
                getattr(rag_config, "id", "<unknown>"),
            )
            continue

        tool_id = build_rag_tool_id(rag_config.id)

        if allowed_set and tool_id not in allowed_set:
            logger.debug(
                "Skipping tool %s because it is not in the allowed list", tool_id
            )
            continue

        tool = RagTool(tool_id, rag_config)
        resolutions.append(ToolResolution(tool_id=tool_id, tool=tool))
        missing_ids.discard(tool_id)

    for server in project.external_tool_servers(readonly=True):
        if server.type != ToolServerType.kiln_task:
            continue

        tool_id = build_kiln_task_tool_id(server.id)

        if allowed_set and tool_id not in allowed_set:
            logger.debug(
                "Skipping tool %s because it is not in the allowed list", tool_id
            )
            continue

        if project.id is None:
            raise ValueError("Project ID is required")

        tool = KilnTaskTool(project.id, tool_id, server)
        resolutions.append(ToolResolution(tool_id=tool_id, tool=tool))
        missing_ids.discard(tool_id)

    if missing_ids:
        raise ValueError(
            "Requested tool IDs were not found or are archived: "
            + ", ".join(sorted(missing_ids))
        )

    return resolutions

def parse_values(values, type_map, ignore_unknown=False):
  results_dictionary = {}
  pos = 0
  while pos < len(values):
    m = PARAM_RE.match(values, pos)
    if not m:
      raise ValueError('Malformed hyperparameter value: %s' % values[pos:])
    # Check that there is a comma between parameters and move past it.
    pos = m.end()
    # Parse the values.
    m_dict = m.groupdict()
    name = m_dict['name']
    if name not in type_map:
      if ignore_unknown:
        continue
      raise ValueError('Unknown hyperparameter type for %s' % name)
    type_ = type_map[name]

    # Set up correct parsing function (depending on whether type_ is a bool)
    if type_ == bool:

      def parse_bool(value):
        if value in ['true', 'True']:
          return True
        elif value in ['false', 'False']:
          return False
        else:
          try:
            return bool(int(value))
          except ValueError:
            _parse_fail(name, type_, value, values)

      parse = parse_bool
    else:
      parse = type_

    # If a singe value is provided
    if m_dict['val'] is not None:
      _process_scalar_value(name, parse, type_, m_dict, values,
                            results_dictionary)

    # If the assigned value is a list:
    elif m_dict['vals'] is not None:
      _process_list_value(name, parse, type_, m_dict, values,
                          results_dictionary)

    else:  # Not assigned a list or value
      _parse_fail(name, type_, '', values)

  return results_dictionary

def find_augmenters(self, func, parents=None, flat=True):
        if parents is None:
            parents = []

        result = []
        if func(self, parents):
            result.append(self)

        subparents = parents + [self]
        for lst in self.get_children_lists():
            for aug in lst:
                found = aug.find_augmenters(func, parents=subparents,
                                            flat=flat)
                if len(found) > 0:
                    if flat:
                        result.extend(found)
                    else:
                        result.append(found)
        return result

def evaluate_transformer(model, input_data, reference_output, verbose=False):
    model = _get_model(model)
    if verbose:
        print(model)
        print("")
        print("Other Framework\t\tPredicted")

    num_errors = 0
    for index, row in enumerate(input_data):
        assert isinstance(row, dict)
        sanitized_row = _sanitize_value(row)
        ref_data = _sanitize_value(reference_output[index])
        if verbose:
            print("Input:\n\t", str(row))
            print("Correct output:\n\t", str(ref_data))

        predicted = _sanitize_value(model.predict(sanitized_row))

        assert isinstance(ref_data, dict)
        assert isinstance(predicted, dict)

        predicted_trimmed = dict((k, predicted[k]) for k in ref_data.keys())

        if verbose:
            print("Predicted:\n\t", str(predicted_trimmed))

        if not _element_equal(predicted_trimmed, ref_data):
            num_errors += 1

    ret = {"num_samples": len(input_data), "num_errors": num_errors}

    if verbose:
        print("results: {}".format(ret))
    return ret

def init_vit_weights(module: nn.Module,trunc_normal_std=0.02, name: str = '', head_bias: float = 0., jax_impl: bool = False):
    if isinstance(module, nn.Linear):
        if name.startswith('head'):
            nn.init.zeros_(module.weight)
            nn.init.constant_(module.bias, head_bias)
        elif name.startswith('pre_logits'):
            lecun_normal_(module.weight)
            nn.init.zeros_(module.bias)
        else:
            if jax_impl:
                nn.init.xavier_uniform_(module.weight)
                if module.bias is not None:
                    if 'mlp' in name:
                        nn.init.normal_(module.bias, std=trunc_normal_std)
                    else:
                        nn.init.zeros_(module.bias)
            else:
                trunc_normal_(module.weight, std=trunc_normal_std)
                if module.bias is not None:
                    nn.init.zeros_(module.bias)
    elif jax_impl and isinstance(module, nn.Conv2d):
        # NOTE conv was left to pytorch default in my original init
        lecun_normal_(module.weight)
        if module.bias is not None:
            nn.init.zeros_(module.bias)
    elif isinstance(module, (nn.LayerNorm, nn.GroupNorm, nn.BatchNorm2d)):
        nn.init.zeros_(module.bias)
        nn.init.ones_(module.weight)
    elif isinstance(module, SpatialTemporalClsPositionalEncoding):
        for weights in module.parameters():
            nn.init.trunc_normal_(weights, std=trunc_normal_std)

def parse_service_config(
    ctx: click.Context | None,
    param: click.Parameter | None,
    value: tuple[str, ...] | None,
) -> dict[str, str]:
    if not value:
        return {}

    result = {}
    for config in value:
        if "=" not in config:
            raise click.BadParameter(
                f"Service must be in format 'serviceName=policy', got '{config}'"
            )

        service_name, policy = config.split("=", 1)
        service_name = service_name.strip()
        policy = policy.strip()
        if not service_name:
            raise click.BadParameter("Service name cannot be empty")

        # Simple validation for two policies
        if policy not in ["always", "never"]:
            raise click.BadParameter(
                f"Policy must be 'always' or 'never', got '{policy}'"
            )

        result[service_name] = policy

    return result

def set_site_to_xpos(self, physics, random_state, site, target_pos,
                       target_quat=None, max_ik_attempts=10):
    if isinstance(site, mjcf.Element):
      site_name = site.full_identifier
    elif isinstance(site, str):
      site_name = site
    else:
      raise ValueError('site should either be a string or mjcf.Element: got {}'
                       .format(site))
    if target_quat is None:
      target_quat = DOWN_QUATERNION
    lower, upper = self._get_joint_pos_sampling_bounds(physics)
    arm_joint_names = [joint.full_identifier for joint in self.joints]

    for _ in range(max_ik_attempts):
      result = inverse_kinematics.qpos_from_site_pose(
          physics=physics,
          site_name=site_name,
          target_pos=target_pos,
          target_quat=target_quat,
          joint_names=arm_joint_names,
          rot_weight=2,
          inplace=True)
      success = result.success

      # Canonicalise the angle to [0, 2*pi]
      if success:
        for arm_joint, low, high in zip(self.joints, lower, upper):
          arm_joint_mj = physics.bind(arm_joint)
          while arm_joint_mj.qpos >= high:
            arm_joint_mj.qpos -= 2*np.pi
          while arm_joint_mj.qpos < low:
            arm_joint_mj.qpos += 2*np.pi
            if arm_joint_mj.qpos > high:
              success = False
              break

      # If succeeded or only one attempt, break and do not randomize joints.
      if success or max_ik_attempts <= 1:
        break
      else:
        self.randomize_arm_joints(physics, random_state)

    return success

def decode_deltas_to_boxes(
    anchors,
    boxes_delta,
    anchor_format,
    box_format,
    encoded_format="center_yxhw",
    variance=None,
    image_shape=None,
):
    if variance is not None:
        variance = ops.convert_to_tensor(variance, "float32")
        var_len = variance.shape[-1]

        if var_len != 4:
            raise ValueError(f"`variance` must be length 4, got {variance}")

    if encoded_format not in ["center_xywh", "center_yxhw"]:
        raise ValueError(
            f"`encoded_format` should be 'center_xywh' or 'center_yxhw', "
            f"but got '{encoded_format}'."
        )

    if image_shape is None:
        height, width = None, None
    else:
        height, width, _ = image_shape

    def decode_single_level(anchor, box_delta):
        encoded_anchor = convert_format(
            anchor,
            source=anchor_format,
            target=encoded_format,
            height=height,
            width=width,
        )
        if variance is not None:
            box_delta = box_delta * variance
        # anchors be unbatched, boxes can either be batched or unbatched.
        box = ops.concatenate(
            [
                box_delta[..., :2] * encoded_anchor[..., 2:]
                + encoded_anchor[..., :2],
                ops.exp(box_delta[..., 2:]) * encoded_anchor[..., 2:],
            ],
            axis=-1,
        )
        box = convert_format(
            box,
            source=encoded_format,
            target=box_format,
            height=height,
            width=width,
        )
        return box

    if isinstance(anchors, dict) and isinstance(boxes_delta, dict):
        boxes = {}
        for lvl, anchor in anchors.items():
            boxes[lvl] = decode_single_level(anchor, boxes_delta[lvl])
        return boxes
    else:
        return decode_single_level(anchors, boxes_delta)

def create_modelconfig(model_name, max_batch_size, inputs, outputs, backend,
                       enable_dynamic_batching=False, preferred_batch_size=None,
                       max_queue_delay_microseconds=None,
                       instance_count=1, device_ids=None):
    config = 'name: "{}"\n'.format(model_name)
    config += 'backend: "{}"\n'.format(backend)
    if max_batch_size is not None:
        config += 'max_batch_size: {}\n'.format(max_batch_size)
    if enable_dynamic_batching:
        config += '''
dynamic_batching {
'''
        if preferred_batch_size is not None:
            config += '''
    preferred_batch_size: {}
'''.format(preferred_batch_size)
        if max_queue_delay_microseconds is not None:
            config += '''
    max_queue_delay_microseconds: {}
'''.format(max_queue_delay_microseconds)
        config += '''
}\n'''
    if inputs is not None:
        for input_name in inputs.keys():
            data_type, shape = inputs[input_name]
            config += '''
input [
  {{
    name: \"{}\"
    data_type: {}
    dims: {}
  }}
]\n'''.format(input_name, data_type, shape)
    if outputs is not None:
        for output_name in outputs.keys():
            data_type, shape = outputs[output_name]
            config += '''
output [
  {{
    name: \"{}\"
    data_type: {}
    dims: {}
  }}
]\n'''.format(output_name, data_type, shape)

    instance_count = 1 if instance_count is None else instance_count
    if device_ids is not None:
        config += '''
instance_group [
    {{
        kind: KIND_GPU
        count: {}
        gpus: {}
    }}
]\n'''.format(instance_count, device_ids)
    else:
        config += '''
instance_group [
    {{
        kind: KIND_CPU
        count: {}
    }}
]\n'''.format(instance_count)

    return config

def compute_future_scores(self, src_sentence):
        scores = defaultdict(lambda: defaultdict(lambda: float("-inf")))
        for seq_length in range(1, len(src_sentence) + 1):
            for start in range(0, len(src_sentence) - seq_length + 1):
                end = start + seq_length
                phrase = src_sentence[start:end]
                if phrase in self.phrase_table:
                    score = self.phrase_table.translations_for(phrase)[
                        0
                    ].log_prob  # pick best (first) translation
                    # Warning: API of language_model is subject to change
                    score += self.language_model.probability(phrase)
                    scores[start][end] = score

                # check if a better score can be obtained by combining
                # two child subsequences
                for mid in range(start + 1, end):
                    combined_score = scores[start][mid] + scores[mid][end]
                    if combined_score > scores[start][end]:
                        scores[start][end] = combined_score
        return scores

def retrieve_from_server(query: str, top_k: int = max_results) -> str:
        try:
            # Prepare request payload
            payload = {
                "query": query,
                "top_k": min(top_k, 50),  # Cap at 50 results
            }

            # Make request to retrieval server
            response = client.post(f"{server_url}/retrieve", json=payload)

            if not response.is_success:
                error_msg = f"Retrieval server error: {response.status_code}"
                if response.content:
                    try:
                        error_data = response.json()
                        error_msg += f" - {error_data.get('error', 'Unknown error')}"
                    except Exception:
                        error_msg += f" - {response.text}"
                return f"Error: {error_msg}"

            # Parse response
            response_data = response.json()
            results = response_data.get("results", [])

            if not results:
                return "No relevant documents found for the query."

            # Format results for LLM consumption
            formatted_results = []
            for i, result in enumerate(results[:max_results], 1):
                doc_id = result.get("id", f"doc_{i}")
                content = result.get("content", "")
                score = result.get("score", 0.0)

                # Truncate content if too long (keep first 300 characters)
                if len(content) > 300:
                    content = content[:300] + "..."

                formatted_result = f"[Document {i}] (ID: {doc_id}, Score: {score:.3f})\n{content}\n"
                formatted_results.append(formatted_result)

            return "\n".join(formatted_results)

        except httpx.TimeoutException:
            return f"Error: Request timeout after {timeout} seconds. Please check if the retrieval server is running."
        except httpx.ConnectError:
            return f"Error: Could not connect to retrieval server at {server_url}. Please ensure the server is running."
        except Exception as e:
            return f"Error: Unexpected error - {str(e)}"

def close(self) -> None:
        if self._agent_process is not None:
            self._agent_process.terminate()
            try:
                self._agent_process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                self._agent_process.kill()
                self._agent_process.wait()
            self._agent_process = None

        # Close log file handles
        for fh in getattr(self, "_log_files", ()):
            try:
                fh.close()
            except Exception:
                pass

        if os.path.exists(self._workdir):
            shutil.rmtree(self._workdir, ignore_errors=True)
        logger.info("LocalSandbox %s closed", self.name)

def create_initialized_headless_egl_display():
  all_devices = EGL.eglQueryDevicesEXT()
  selected_device = os.environ.get('MUJOCO_EGL_DEVICE_ID', None)
  if selected_device is None:
    candidates = all_devices
  else:
    device_idx = int(selected_device)
    if not 0 <= device_idx < len(all_devices):
      raise RuntimeError(
          f'MUJOCO_EGL_DEVICE_ID must be an integer between 0 and '
          f'{len(all_devices) - 1} (inclusive), got {device_idx}.')
    candidates = all_devices[device_idx:device_idx + 1]
  for device in candidates:
    display = EGL.eglGetPlatformDisplayEXT(
        EGL.EGL_PLATFORM_DEVICE_EXT, device, None)
    if display != EGL.EGL_NO_DISPLAY and EGL.eglGetError() == EGL.EGL_SUCCESS:
      # `eglInitialize` may or may not raise an exception on failure depending
      # on how PyOpenGL is configured. We therefore catch a `GLError` and also
      # manually check the output of `eglGetError()` here.
      try:
        initialized = EGL.eglInitialize(display, None, None)
      except error.GLError:
        pass
      else:
        if initialized == EGL.EGL_TRUE and EGL.eglGetError() == EGL.EGL_SUCCESS:
          return display
  return EGL.EGL_NO_DISPLAY

def make_nested_list_of_images(
    images: list[ImageInput] | ImageInput,
    expected_ndims: int = 3,
) -> list[ImageInput]:
    # If it's a list of batches, it's already in the right format
    if (
        isinstance(images, (list, tuple))
        and all(isinstance(images_i, (list, tuple)) for images_i in images)
        and all(is_valid_list_of_images(images_i) or not images_i for images_i in images)
    ):
        return images

    # If it's a list of images, it's a single batch, so convert it to a list of lists
    if isinstance(images, (list, tuple)) and is_valid_list_of_images(images):
        if is_pil_image(images[0]) or images[0].ndim == expected_ndims:
            return [images]
        if images[0].ndim == expected_ndims + 1:
            return [list(image) for image in images]

    # If it's a single image, convert it to a list of lists
    if is_valid_image(images):
        if is_pil_image(images) or images.ndim == expected_ndims:
            return [[images]]
        if images.ndim == expected_ndims + 1:
            return [list(images)]

    raise ValueError("Invalid input type. Must be a single image, a list of images, or a list of batches of images.")

def check_cartan_decomp(
    k: list[PauliSentence | TensorLike],
    m: list[PauliSentence | TensorLike],
    verbose=True,
):

    if any(isinstance(op, TensorLike) for op in k) or any(isinstance(op, TensorLike) for op in m):
        if not all(isinstance(op, TensorLike) for op in k) or not all(
            isinstance(op, TensorLike) for op in m
        ):
            raise TypeError(
                "All inputs `k`, `m` to check_cartan_decomp need to either be iterables of "
                f"operators or matrices. Received `k` of types {[type(op) for op in k]} and "
                f"`m` of types {[type(op) for op in m]}"
            )

    if any(isinstance(op, Operator) for op in k):
        k = [op.pauli_rep for op in k]
    if any(isinstance(op, Operator) for op in m):
        m = [op.pauli_rep for op in m]

    if any(isinstance(op, TensorLike) for op in k):
        k_space = k
    else:
        k_space = PauliVSpace(k, dtype=complex)

    if any(isinstance(op, TensorLike) for op in m):
        m_space = m
    else:
        m_space = PauliVSpace(m, dtype=complex)

    # Commutation relations for Cartan pair
    if not (check_kk := check_commutation_relation(k, k, k_space)):
        _ = print("[k, k] sub k not fulfilled") if verbose else None
    if not (check_km := check_commutation_relation(k, m, m_space)):
        _ = print("[k, m] sub m not fulfilled") if verbose else None
    if not (check_mm := check_commutation_relation(m, m, k_space)):
        _ = print("[m, m] sub k not fulfilled") if verbose else None

    return all([check_kk, check_km, check_mm])

async def async_move_resource_to_block_cache(
        self, url_or_file_path: str | Path | None
    ) -> str | None:
        if url_or_file_path is None:
            return None
        if isinstance(url_or_file_path, Path):
            url_or_file_path = str(url_or_file_path)

        if client_utils.is_http_url_like(url_or_file_path):
            temp_file_path = await processing_utils.async_ssrf_protected_download(
                url_or_file_path, cache_dir=self.GRADIO_CACHE
            )

            self.temp_files.add(temp_file_path)
        else:
            url_or_file_path = str(utils.abspath(url_or_file_path))
            if not utils.is_in_or_equal(url_or_file_path, self.GRADIO_CACHE):
                try:
                    temp_file_path = processing_utils.save_file_to_cache(
                        url_or_file_path, cache_dir=self.GRADIO_CACHE
                    )
                except FileNotFoundError:
                    # This can happen if when using gr.load() and the file is on a remote Space
                    # but the file is not the `value` of the component. For example, if the file
                    # is the `avatar_image` of the `Chatbot` component. In this case, we skip
                    # copying the file to the cache and just use the remote file path.
                    return url_or_file_path
            else:
                temp_file_path = url_or_file_path
            self.temp_files.add(temp_file_path)

        return temp_file_path

def resolve_conda_hook(manifest_hook=None):
    def wrap(path_or_cmd):
        if path_or_cmd.startswith("eval"):
            return path_or_cmd
        return f'eval "$({path_or_cmd} shell.bash hook)"'

    # 1. Manifest override
    if manifest_hook:
        return wrap(manifest_hook)
    # 2. Env var override
    env_hook = os.environ.get("ARIS_CONDA_HOOK")
    if env_hook:
        return wrap(env_hook)
    # 3. Auto-detect common install paths
    for p in (
        os.path.expanduser("~/anaconda3/bin/conda"),
        os.path.expanduser("~/miniconda3/bin/conda"),
        os.path.expanduser("~/miniforge3/bin/conda"),
        "/opt/anaconda3/bin/conda",
        "/opt/miniconda3/bin/conda",
        "/opt/miniforge3/bin/conda",
        "/usr/local/anaconda3/bin/conda",
        "/opt/homebrew/anaconda3/bin/conda",
    ):
        if os.path.exists(p):
            return wrap(p)
    # 4. Fall back to PATH
    out, rc = run("command -v conda 2>/dev/null")
    if rc == 0 and out.strip():
        return wrap(out.strip())
    # 5. Last resort
    return 'eval "$(conda shell.bash hook)"'

def make_decimal(self, s, sign="+"):
        if not decimal or self.float_type == NUMBER_FLOAT:
            return self.make_float(s, sign)

        if s.startswith("-") or s.startswith("+"):
            sign = s[0]
            s = s[1:]
        elif isinstance(sign, int):
            if sign < 0:
                sign = "-"
            else:
                sign = "+"

        try:
            f = self.decimal_context.create_decimal(s)
        except decimal.InvalidOperation:
            f = self.decimal_context.create_decimal("NaN")
        except decimal.Overflow:
            if sign == "-":
                f = self.decimal_context.create_decimal("-Infinity")
            else:
                f = self.decimal_context.create_decimal("Infinity")
        else:
            if sign == "-":
                f = f.copy_negate()
        return f

def reflect(object, quantify=True, replace=readable_types):
    _type = lambda object: type(object).__name__
    types = []
    # Classes and modules with a __dict__ attribute listing methods, functions etc.
    if hasattr(object, "__dict__"):
        # Function and method objects.
        if _type(object) in ("function", "instancemethod"):
            types.append(_type(object))
        # Classes and modules.
        else:
            for v in object.__dict__.values():
                try:
                    types.append(str(v.__classname__))
                except:
                    # Not a class after all (some stuff like ufunc in Numeric).
                    types.append(_type(v))
    # Lists and tuples can consist of several types of objects.
    elif isinstance(object, (list, tuple, set)):
        types += [_type(x) for x in object]
    # Dictionaries have keys pointing to objects.
    elif isinstance(object, dict):
        types += [_type(k) for k in object]
        types += [_type(v) for v in object.values()]
    else:
        types.append(_type(object))
    # Clean up type strings.
    m = {}
    for i in range(len(types)):
        k = types[i]
        # Execute the regular expressions once only,
        # next time we'll have the conversion cached.
        if k not in m:
            for a, b in replace:
                types[i] = re.sub(a, b, types[i])
            m[k] = types[i]
        types[i] = m[k]
    if not quantify:
        if not isinstance(object, (list, tuple, set, dict)) and not hasattr(object, "__dict__"):
            return types[0]
        return types
    return count(types, plural={"built-in function" : "built-in functions"})

def from_dict(cls, data: Dict[str, Any]) -> "StateBackendConfig":
        # Start with file config
        config_kwargs: Dict[str, Any] = {}

        # Map known keys
        key_mapping = {
            "backend": "backend",
            "url": "url",
            "pool_size": "pool_size",
            "timeout": "timeout",
            "key_prefix": "key_prefix",
            "sqlite_path": "sqlite_path",
            "sqlite_wal_mode": "sqlite_wal_mode",
            "sqlite_busy_timeout": "sqlite_busy_timeout",
            "min_pool_size": "min_pool_size",
            "max_pool_size": "max_pool_size",
            "pool_recycle": "pool_recycle",
            "redis_db": "redis_db",
            "redis_ssl": "redis_ssl",
            "redis_cluster_mode": "redis_cluster_mode",
            "cleanup_interval": "cleanup_interval",
            "cleanup_batch_size": "cleanup_batch_size",
        }

        for file_key, attr_name in key_mapping.items():
            if file_key in data:
                config_kwargs[attr_name] = data[file_key]

        # Collect unknown keys into options
        options = {k: v for k, v in data.items() if k not in key_mapping}
        if options:
            config_kwargs["options"] = options

        # Create config with file values
        config = cls(**config_kwargs)

        # Override with environment variables
        if os.environ.get("STATE_BACKEND"):
            config.backend = os.environ["STATE_BACKEND"]
        if os.environ.get("STATE_BACKEND_URL"):
            config.url = os.environ["STATE_BACKEND_URL"]
        if os.environ.get("STATE_BACKEND_POOL_SIZE"):
            config.pool_size = _get_env_int("STATE_BACKEND_POOL_SIZE", config.pool_size)
        if os.environ.get("STATE_BACKEND_TIMEOUT"):
            config.timeout = _get_env_float("STATE_BACKEND_TIMEOUT", config.timeout)
        if os.environ.get("STATE_BACKEND_KEY_PREFIX"):
            config.key_prefix = os.environ["STATE_BACKEND_KEY_PREFIX"]

        return config

def aggregate_partial_histograms(messages: Iterable[Message]):
    aggregated_hist = {}
    total_count = 0
    for rep in messages:
        if rep.has_error():
            continue
        query_results = rep.content["query_results"]
        # Sum metrics
        for k, v in query_results.items():
            if k in ["SepalLengthCm", "SepalWidthCm"]:
                if k in aggregated_hist:
                    aggregated_hist[k] += np.array(v)
                else:
                    aggregated_hist[k] = np.array(v)
            if "_count" in k:
                total_count += v

    # Verify aggregated histogram adds up to total reported count
    assert total_count == sum([sum(v) for v in aggregated_hist.values()])
    return aggregated_hist

def prompt(
    text,
    default=None,
    hide_input=False,
    confirmation_prompt=False,
    type=None,
    value_proc=None,
    prompt_suffix=": ",
    show_default=True,
    err=False,
    show_choices=True,
):
    result = None

    def prompt_func(text):
        f = hidden_prompt_func if hide_input else visible_prompt_func
        try:
            # Write the prompt separately so that we get nice
            # coloring through colorama on Windows
            echo(text, nl=False, err=err)
            return f("")
        except (KeyboardInterrupt, EOFError):
            # getpass doesn't print a newline if the user aborts input with ^C.
            # Allegedly this behavior is inherited from getpass(3).
            # A doc bug has been filed at https://bugs.python.org/issue24711
            if hide_input:
                echo(None, err=err)
            raise Abort()

    if value_proc is None:
        value_proc = convert_type(type, default)

    prompt = _build_prompt(
        text, prompt_suffix, show_default, default, show_choices, type
    )

    while 1:
        while 1:
            value = prompt_func(prompt)
            if value:
                break
            elif default is not None:
                if isinstance(value_proc, Path):
                    # validate Path default value(exists, dir_okay etc.)
                    value = default
                    break
                return default
        try:
            result = value_proc(value)
        except UsageError as e:
            echo("Error: {}".format(e.message), err=err)  # noqa: B306
            continue
        if not confirmation_prompt:
            return result
        while 1:
            value2 = prompt_func("Repeat for confirmation: ")
            if value2:
                break
        if value == value2:
            return result
        echo("Error: the two entered values do not match", err=err)

def kleene_and(
    left: bool | libmissing.NAType | np.ndarray,
    right: bool | libmissing.NAType | np.ndarray,
    left_mask: np.ndarray | None,
    right_mask: np.ndarray | None,
) -> tuple[npt.NDArray[np.bool_], npt.NDArray[np.bool_]]:
    # To reduce the number of cases, we ensure that `left` & `left_mask`
    # always come from an array, not a scalar. This is safe, since
    # A & B == B & A
    if left_mask is None:
        return kleene_and(right, left, right_mask, left_mask)

    if not isinstance(left, np.ndarray):
        raise TypeError("Either `left` or `right` need to be an np.ndarray.")
    raise_for_nan(right, method="and")

    if right is libmissing.NA:
        result = np.zeros_like(left)
    else:
        result = left & right

    if right_mask is None:
        # Scalar `right`
        if right is libmissing.NA:
            mask = (left & ~left_mask) | left_mask

        else:
            mask = left_mask.copy()
            if right is False:
                # unmask everything
                mask[:] = False
    else:
        # unmask where either left or right is False
        left_false = ~(left | left_mask)
        right_false = ~(right | right_mask)
        mask = (left_mask & ~right_false) | (right_mask & ~left_false)

    return result, mask

async def upload_to_docker_directory(
    upload_name: str = Form(
        default_factory=lambda: str(uuid.uuid4()), regex=r"^[a-z][a-z0-9-]*$"
    ),
    files: List[UploadFile] = File(...),
):
    if not settings.LOCAL:
        return JSONResponse(
            content={"error": "API only supported for local docker environment"},
            status_code=500,
        )
    logger.info(f"Uploading files to directory: {upload_name}")
    # create a folder within `/volumes/user_data/` that maps to `/app/user_data/` in the docker volume
    # this folder will be used to store the uploaded files
    folder_path = os.path.realpath(
        os.path.join(settings.LOCAL_DATA_DIRECTORY, upload_name)
    )
    if not folder_path.startswith(settings.LOCAL_DATA_DIRECTORY):
        return JSONResponse(
            content={"error": "Invalid upload path"},
            status_code=400,
        )

    # Create the folder if it does not exist, else raise an exception
    if os.path.exists(folder_path):
        return JSONResponse(
            content={"error": f"Folder already exists: {upload_name}"},
            status_code=500,
        )

    # Create the folder by the given name
    os.makedirs(folder_path)

    # Upload the files to the folder
    for file in files:
        logger.info(f"Copying file: {file.filename}, to folder: {folder_path}")
        file_path = os.path.realpath(os.path.join(folder_path, file.filename))
        if not file_path.startswith(folder_path):
            return JSONResponse(
                content={"error": "Invalid file path during upload"},
                status_code=400,
            )

        with open(file_path, "wb") as f:
            f.write(file.file.read())

    # Add the data source to the metadata store.
    return await add_data_source(
        CreateDataSource(
            type="localdir",
            uri=folder_path,
        )
    )

def convert_sklearn_isolation_forest(operator, device, extra_config):
    assert operator is not None, "Cannot convert None operator"

    tree_infos = operator.raw_operator.estimators_
    n_features = operator.raw_operator.n_features_in_
    # Following constants will be passed in the tree implementation to normalize the anomaly score.
    extra_config[constants.OFFSET] = operator.raw_operator.offset_
    if hasattr(operator.raw_operator, "threshold_"):
        extra_config[constants.IFOREST_THRESHOLD] = operator.raw_operator.threshold_
    extra_config[constants.MAX_SAMPLES] = operator.raw_operator.max_samples_

    # Predict in isolation forest sklearn implementation produce 2 classes: -1 (normal) & 1 (anomaly).
    classes = [-1, 1]

    tree_parameters, max_depth, tree_type = get_tree_params_and_type(
        tree_infos, _get_parameters_for_sklearn_iforest, extra_config
    )

    # Generate the tree implementation based on the selected strategy.
    if tree_type == TreeImpl.gemm:
        net_parameters = [
            get_parameters_for_gemm_common(
                tree_param.lefts, tree_param.rights, tree_param.features, tree_param.thresholds, tree_param.values, n_features
            )
            for tree_param in tree_parameters
        ]
        return GEMMIsolationForestImpl(operator, net_parameters, n_features, classes, extra_config=extra_config)

    net_parameters = [
        get_parameters_for_tree_trav_sklearn(
            tree_param.lefts, tree_param.rights, tree_param.features, tree_param.thresholds, tree_param.values, classes
        )
        for tree_param in tree_parameters
    ]
    if tree_type == TreeImpl.tree_trav:
        return TreeTraversalIsolationForestImpl(
            operator, net_parameters, max_depth, n_features, classes, extra_config=extra_config
        )
    else:  # Remaining possible case: tree_type == TreeImpl.perf_tree_trav
        return PerfectTreeTraversalIsolationForestImpl(
            operator, net_parameters, max_depth, n_features, classes, extra_config=extra_config
        )

def del_proj(self, idx="all"):
        if isinstance(idx, str) and idx == "all":
            idx = list(range(len(self.info["projs"])))
        idx = np.atleast_1d(np.array(idx, int)).ravel()

        for ii in idx:
            proj = self.info["projs"][ii]
            if proj["active"] and set(self.info["ch_names"]) & set(
                proj["data"]["col_names"]
            ):
                msg = (
                    f"Cannot remove projector that has already been "
                    f"applied, unless you first remove all channels it "
                    f"applies to. The problematic projector is: {proj}"
                )
                raise ValueError(msg)

        keep = np.ones(len(self.info["projs"]))
        keep[idx] = False  # works with negative indexing and does checks
        with self.info._unlock():
            self.info["projs"] = [p for p, k in zip(self.info["projs"], keep) if k]
        return self

def load_data(self, key, by_user=True):
        records = []
        key_col = self.col_user if by_user else self.col_test_batch

        # fast forward in file to user/test batch
        while (self.line_num == 0) or (self.row[key_col] != key):
            if self.end_of_file:
                raise MissingUserException(
                    "User {} not in file {}".format(key, self.filename)
                )
            next(self)
        # collect user/test batch data
        while self.row[key_col] == key:
            row = self.row
            if self.col_test_batch in row:
                del row[self.col_test_batch]
            records.append(row)
            if not self.end_of_file:
                next(self)
            else:
                break
        return pd.DataFrame.from_records(records)

def set(self, default_conf: str = "client", **kwargs):
        from .utils import set_log_with_config, get_module_logger, can_use_cache  # pylint: disable=C0415

        self.reset()

        _logging_config = kwargs.get("logging_config", self.logging_config)

        # set global config
        if _logging_config:
            set_log_with_config(_logging_config)

        logger = get_module_logger("Initialization", kwargs.get("logging_level", self.logging_level))
        logger.info(f"default_conf: {default_conf}.")

        self.set_mode(default_conf)
        self.set_region(kwargs.get("region", self["region"] if "region" in self else REG_CN))

        for k, v in kwargs.items():
            if k not in self:
                logger.warning("Unrecognized config %s" % k)
            self[k] = v

        self.resolve_path()

        if not (self["expression_cache"] is None and self["dataset_cache"] is None):
            # check redis
