                    )

def filter_res(self, res: np.ndarray, iou: float = None, area: str = None, max_dets: int = None):
        if iou:
            iou_i = [i for i, iou_thres in enumerate(self.iou_thresholds) if iou == iou_thres]
            res = res[iou_i, :, :, :]
        if area:
            area_i = [i for i, area_name in enumerate(self.area_ranges_names) if area == area_name]
            res = res[:, area_i, :, :]
        if max_dets:
            dets_i = [i for i, det in enumerate(self.max_detections_per_class) if max_dets == det]
            res = res[:, :, dets_i, :]
        return res

def convert_to_tensors(
        self,
        tensor_type: str | TensorType | None = None,
        skip_tensor_conversion: list[str] | set[str] | None = None,
    ):
        if tensor_type is None:
            return self

        is_tensor, as_tensor = self._get_is_as_tensor_fns(tensor_type)
        skip_tensor_conversion = (
            skip_tensor_conversion if skip_tensor_conversion is not None else self.skip_tensor_conversion
        )

        # Do the tensor conversion in batch
        for key, value in self.items():
            # Skip keys explicitly marked for no conversion
            if skip_tensor_conversion and key in skip_tensor_conversion:
                continue

            # Skip values that are not array-like
            if not _is_tensor_or_array_like(value):
                continue

            try:
                if not is_tensor(value):
                    tensor = as_tensor(value)
                    self[key] = tensor
            except Exception as e:
                if key == "overflowing_values":
                    raise ValueError(
                        f"Unable to create tensor for '{key}' with overflowing values of different lengths. "
                        f"Original error: {str(e)}"
                    ) from e
                raise ValueError(
                    f"Unable to convert output '{key}' (type: {type(value).__name__}) to tensor: {str(e)}\n"
                    f"You can try:\n"
                    f"  1. Use padding=True to ensure all outputs have the same shape\n"
                    f"  2. Set return_tensors=None to return Python objects instead of tensors"
                ) from e

        return self

def number(s):
    s = s.strip()
    s = s.lower()
    # Negative number.
    if s.startswith(MINUS):
        return -number(s.replace(MINUS, "", 1))
    # Strip commas and dashes ("seventy-five").
    # Split into integral and fractional part.
    s = s.replace("&", " %s " % CONJUNCTION)
    s = s.replace(THOUSANDS, "")
    s = s.replace("-", " ")
    s = s.split(RADIX)
    # Process fractional part.
    # Extract all the leading zeros.
    if len(s) > 1:
        f = " ".join(s[1:])      # zero point zero twelve => zero twelve
        f, z = zshift(f)              # zero twelve => (1, "twelve")
        f = float(number(f))          # "twelve" => 12.0
        f /= 10**(len(str(int(f))) + z) # 10**(len("12")+1) = 1000; 12.0 / 1000 => 0.012
    else:
        f = 0
    i = n = 0
    s = s[0].split()
    for j, x in enumerate(s):
        if x in NUMERALS:
            # Map words from the dictionary of numerals: "eleven" => 11.
            i += NUMERALS[x]
        elif x in NUMERALS_VERBOSE:
            # Map words from alternate numerals: "two dozen" => 2 * 12
            i = i * NUMERALS_VERBOSE[x][0] + NUMERALS_VERBOSE[x][1]
        elif x in O:
            # Map thousands from the dictionary of orders.
            # When a thousand is encountered, the subtotal is shifted to the total
            # and we start a new subtotal. An exception to this is when we
            # encouter two following thousands (e.g. two million vigintillion is one subtotal).
            i *= O[x]
            if j < len(s) - 1 and s[j + 1] in O:
                continue
            if O[x] > 100:
                n += i
                i = 0
        elif x == CONJUNCTION:
            pass
        else:
            # Words that are not in any dicionary may be numbers (e.g. "2.5" => 2.5).
            try:
                i += "." in x and float(x) or int(x)
            except:
                pass
    return n + i + f

def validate_and_get_arguments_from_body(self) -> dict:
        try:
            arguments = {
                "arguments": "{}",
                "type": self.get_body_argument("type")
            }
        except tornado.web.MissingArgumentError:
            raise Exception("No type provided.")

        try:
            arguments["arguments"] = self.get_body_argument("arguments")
        except tornado.web.MissingArgumentError:
            # If no arguments are provided, ignore error as arguments has been
            # set to a stringified JSON object by default.
            pass

        try:
            arguments["arguments"] = json.loads(arguments.get("arguments"))
        except json.decoder.JSONDecodeError as e:
            raise Exception("Invalid JSON provided as arguments: {}".format(str(e)))

        # If invalid JSON is provided that is incorrectly escaped
        # arguments.get("arguments") can be a string. This Ensure that
        # json.loads properly converts stringified JSON to dict.
        if type(arguments.get("arguments")) != dict:
            raise Exception("Invalid JSON provided as arguments!")

        try:
            arguments["source"] = self.get_body_argument("source")
        except tornado.web.MissingArgumentError:
            arguments["source"] = ""

        if arguments.get("type") != "custom":
            if len(arguments.get("source")) == 0:
                raise Exception("No source provided.")

        return arguments

def add_condition_outlier_ratio_less_or_equal(self: Self, threshold: float = 0.05,
                                                  properties_to_ignore: t.Optional[t.List[str]] = None) -> Self:

        def condition(result: t.Dict[str, t.Any]):
            failed_properties = []
            worst_property = ''
            worst_ratio = 0

            for property_name, info in result.items():
                if properties_to_ignore is not None and property_name in properties_to_ignore:
                    continue
                if isinstance(info, str):
                    continue
                if info['outlier_ratio'] > threshold:
                    failed_properties.append(property_name)
                if info['outlier_ratio'] > worst_ratio:
                    worst_property = property_name
                    worst_ratio = info['outlier_ratio']

            if len(failed_properties) > 0:
                return ConditionResult(ConditionCategory.FAIL,
                                       f'Found {len(failed_properties)} properties with outlier ratios above threshold.'
                                       f'</br>Property with highest ratio is {worst_property} with outlier ratio of '
                                       f'{format_percent(worst_ratio)}')
            else:
                return ConditionResult(ConditionCategory.PASS,
                                       f'All properties have outlier ratios below threshold. '
                                       f'Property with highest ratio is {worst_property} with outlier ratio of'
                                       f' {format_percent(worst_ratio)}')

        return self.add_condition(f'Outlier ratio in all properties is less or equal than {format_percent(threshold)}',
                                  condition)

def phi_4_hf_to_meta(state_dict: Dict[str, torch.Tensor]) -> Dict[str, torch.Tensor]:
    converted_state_dict = {}
    inverted_mapping_dict = {v: k for k, v in _HF_PHI_4_FROM_META.items()}

    for key, value in state_dict.items():
        if key.endswith("mlp.gate_up_proj.weight"):
            # Split the gate_up_proj into gate_proj and up_proj
            hidden_dim = value.shape[0] // 2
            assert 2 * hidden_dim == value.shape[0]
            gate = value[0:hidden_dim, :]
            up = value[hidden_dim:, :]
            for new_key, new_value in [("gate_proj", gate), ("up_proj", up)]:
                new_key = key.replace("gate_up_proj", new_key)
                new_key = get_mapped_key(new_key, inverted_mapping_dict)
                converted_state_dict[new_key] = new_value
        elif key.endswith("self_attn.qkv_proj.weight"):
            # Split the qkv_proj into q_proj, k_proj, and v_proj
            q_dim = value.shape[1]
            kv_dim = (value.shape[0] - q_dim) // 2
            assert 2 * kv_dim + q_dim == value.shape[0]
            q = value[0:q_dim, :]
            k = value[q_dim : (q_dim + kv_dim), :]
            v = value[(q_dim + kv_dim) :, :]
            for new_key, new_value in [("q_proj", q), ("k_proj", k), ("v_proj", v)]:
                new_key = key.replace("qkv_proj", new_key)
                new_key = get_mapped_key(new_key, inverted_mapping_dict)
                converted_state_dict[new_key] = new_value
        else:
            new_key = get_mapped_key(key, inverted_mapping_dict)
            converted_state_dict[new_key] = value
    return converted_state_dict

def add_scale(
        self,
        name,
        W,
        b,
        has_bias,
        input_name,
        output_name,
        shape_scale=None,
        shape_bias=None,
    ):

        if not shape_scale:
            shape_scale = [1]
        if not shape_bias:
            shape_bias = [1]

        spec_layer = self._add_generic_layer(name, [input_name], [output_name])
        spec_layer_params = spec_layer.scale

        spec_layer_params.hasBias = has_bias

        # add scale and its shape
        scale = spec_layer_params.scale
        spec_layer_params.shapeScale.extend(shape_scale)
        if isinstance(W, int):
            scale.floatValue.append(float(W))
        else:
            scale.floatValue.extend(W.flatten())
        if len(scale.floatValue) != _np.prod(shape_scale):
            raise ValueError(
                "Dimensions of 'shape_scale' do not match the size of the provided 'scale' parameter"
            )

        # add bias and its shape
        if has_bias:
            bias = spec_layer_params.bias
            spec_layer_params.shapeBias.extend(shape_bias)
            if isinstance(b, int):
                bias.floatValue.append(float(b))
            else:
                bias.floatValue.extend(b.flatten())
            if len(bias.floatValue) != _np.prod(shape_bias):
                raise ValueError(
                    "Dimensions of 'shape_bias' do not match the size of the provided 'b' parameter"
                )
        return spec_layer

def decorator(
    decorator_fn: Callable[[T, Any, Sequence[Any], Dict[str, Any]], Any],) -> T:

  @functools.wraps(decorator_fn)
  def _decorator(f):
    """Wraps f such that it returns the result of applying decorator_fn."""
    if _is_object(f):

      @functools.wraps(f.__call__)
      def _decorate_object(*args, **kwargs):
        return decorator_fn(f.__call__, f, args, kwargs)

      return _decorate_object

    if inspect.ismethod(f):

      @functools.wraps(f)
      def _decorate_bound_method(*args, **kwargs):
        return decorator_fn(f, f.__self__, args, kwargs)

      return _decorate_bound_method

    argspec = inspect.getfullargspec(f)
    if argspec.args and argspec.args[0] == "self":

      # TODO(b/123870292): Bound methods with multiple decorators can be
      # detected as unbound too, which breaks tf.function usage.
      # Attempt migrating to wrapt instead of using this custom approach.
      def _decorate_unbound_method(self, *args, **kwargs):
        bound_method = f.__get__(self, self.__class__)  # pytype: disable=attribute-error
        return decorator_fn(bound_method, self, args, kwargs)

      return _decorate_unbound_method

    @functools.wraps(f)
    def _decorate_fn(*args, **kwargs):
      return decorator_fn(f, None, args, kwargs)

    return _decorate_fn

  return _decorator

def check_imports(filename):
    with open(filename, "r", encoding="utf-8") as f:
        content = f.read()

    # Imports of the form `import xxx`
    imports = re.findall(r"^\s*import\s+(\S+)\s*$", content, flags=re.MULTILINE)
    # Imports of the form `from xxx import yyy`
    imports += re.findall(r"^\s*from\s+(\S+)\s+import", content, flags=re.MULTILINE)
    # Only keep the top-level module
    imports = [imp.split(".")[0] for imp in imports if not imp.startswith(".")]

    # Unique-ify and test we got them all
    imports = list(set(imports))
    missing_packages = []
    for imp in imports:
        try:
            importlib.import_module(imp)
        except ImportError:
            missing_packages.append(imp)

    if len(missing_packages) > 0:
        raise ImportError(
            "This modeling file requires the following packages that were not found in your environment: "
            f"{', '.join(missing_packages)}. Run `pip install {' '.join(missing_packages)}`"
        )

    return get_relative_imports(filename)

def backward(self, tensor: Tensor, *args: Any, model: Optional[_FabricModule] = None, **kwargs: Any) -> None:
        module = model._forward_module if model is not None else model
        module, _ = _unwrap_compiled(module)
        if isinstance(self._strategy, DeepSpeedStrategy):
            if model is None:
                if self._models_setup == 0:
                    raise RuntimeError("No models were set up for backward. Did you forget to call `fabric.setup()`?")
                if self._models_setup > 1:
                    raise ValueError(
                        "When using multiple models + deepspeed, please provide the model used to perform"
                        " the optimization: `self.backward(loss, model=model)`"
                    )
                module = self._strategy.model
            else:
                # requires to attach the current `DeepSpeedEngine` for the `_FabricOptimizer.step` call.
                self._strategy._deepspeed_engine = module

        lightning.fabric.wrappers._in_fabric_backward = True
        try:
            self._strategy.backward(tensor, module, *args, **kwargs)
        finally:
            lightning.fabric.wrappers._in_fabric_backward = False

def frames_list(self) -> list[int]:
        face_count_per_index = self._detected_faces.face_count_per_index
        if self._globals.var_filter_mode.get() == "No Faces":
            retval = [idx for idx, count in enumerate(face_count_per_index) if count == 0]
        elif self._globals.var_filter_mode.get() == "Multiple Faces":
            retval = [idx for idx, count in enumerate(face_count_per_index) if count > 1]
        elif self._globals.var_filter_mode.get() == "Has Face(s)":
            retval = [idx for idx, count in enumerate(face_count_per_index) if count != 0]
        elif self._globals.var_filter_mode.get() == "Misaligned Faces":
            distance = self._filter_distance
            retval = [idx for idx, frame in enumerate(self._detected_faces.current_faces)
                      if any(face.aligned.average_distance > distance for face in frame)]
        else:
            retval = list(range(len(face_count_per_index)))
        logger.trace("filter mode: %s, number_frames: %s",  # type:ignore[attr-defined]
                     self._globals.var_filter_mode.get(), len(retval))
        return retval

def group_by_keys_nothrow(data, keys=base_plus_ext, lcase=True, suffixes=None, handler=None):
    current_sample = None
    for filesample in data:
        assert isinstance(filesample, dict)
        fname, value = filesample["fname"], filesample["data"]
        prefix, suffix = keys(fname)
        if prefix is None:
            continue
        if lcase:
            suffix = suffix.lower()
        # FIXME webdataset version throws if suffix in current_sample, but we have a potential for
        #  this happening in the current LAION400m dataset if a tar ends with same prefix as the next
        #  begins, rare, but can happen since prefix aren't unique across tar files in that dataset
        if current_sample is None or prefix != current_sample["__key__"] or suffix in current_sample:
            if valid_sample(current_sample):
                yield current_sample
            current_sample = dict(__key__=prefix, __url__=filesample["__url__"])
        if suffixes is None or suffix in suffixes:
            current_sample[suffix] = value
    if valid_sample(current_sample):
        yield current_sample

def process_trajectories(trajectories: list[Trajectory], reward_threshold: float):
        sft_data = []

        for traj in trajectories:
            if not traj:
                continue

            reward = traj.reward

            if reward < reward_threshold:
                continue

            # Get chat_completions from the last step of the trajectory
            messages = None
            if traj.steps and hasattr(traj.steps[-1], "chat_completions"):
                messages = traj.steps[-1].chat_completions

            if not messages:
                continue

            clean_messages = [{"role": msg["role"], "content": str(msg["content"]).strip()} for msg in messages if isinstance(msg, dict) and msg.get("role") and str(msg.get("content", "")).strip()]

            if len(clean_messages) >= 2:
                sft_data.append({"messages": clean_messages})

        print(f"Processed {len(trajectories)} trajectories -> {len(sft_data)} valid examples")
        return sft_data

def get_exact_name(self, revs: Iterable[str]) -> dict[str, Optional[str]]:
        result: dict[str, Optional[str]] = {}
        exclude = f"{EXEC_NAMESPACE}/*"
        ref_dict = self.scm.describe(revs, base=EXPS_NAMESPACE, exclude=exclude)
        for rev in revs:
            name: Optional[str] = None
            ref = ref_dict[rev]
            if ref:
                try:
                    name = ExpRefInfo.from_ref(ref).name
                except InvalidExpRefError:
                    pass
            if not name:
                if rev in self.stash_revs:
                    name = self.stash_revs[rev].name
                else:
                    failed_stash = self.celery_queue.failed_stash
                    if failed_stash and rev in failed_stash.stash_revs:
                        name = failed_stash.stash_revs[rev].name
            result[rev] = name
        return result

async def aget_mcp_tools(
    server_path: Optional[str] = None,
    format: str = "openai",
    connection: Optional[MCPConnection] = None,
    transport: Optional[str] = None,
    verbose: bool = True,
    *args,
    **kwargs,
) -> List[Dict[str, Any]]:
    if verbose:
        logger.info(
            f"aget_mcp_tools called for server_path: {server_path}"
        )
    if transport is None:
        transport = auto_detect_transport(server_path)
    if exists(connection):
        headers, timeout, transport_from_conn, url = (
            connect_to_mcp_server(connection)
        )
        if transport_from_conn:
            transport = transport_from_conn
    else:
        headers, timeout, _transport, _url = (
            None,
            5,
            None,
            server_path,
        )
        url = server_path
    if verbose:
        logger.info(
            f"Fetching MCP tools from server: {server_path} using transport: {transport}"
        )
    try:
        async with get_mcp_client(
            transport,
            url=url,
            headers=headers,
            timeout=timeout,
            *args,
            **kwargs,
        ) as ctx:
            if len(ctx) == 2:
                read, write = ctx
            else:
                read, write, *_ = ctx
            async with ClientSession(read, write) as session:
                await session.initialize()
                tools = await load_mcp_tools(
                    session=session, format=format
                )
                if verbose:
                    logger.info(
                        f"Successfully fetched {len(tools)} tools"
                    )
                return tools
    except Exception as e:
        logger.error(
            f"Error fetching MCP tools: {str(e)}\n{traceback.format_exc()}"
        )
        raise MCPConnectionError(
            f"Failed to connect to MCP server: {str(e)}"
        )

def query(msg: Message, context: Context) -> Message:
    # Get database connection details from node config
    db_url: str = context.node_config.get(
        "db-url",
        "postgresql+psycopg://flwrlabs:flwrlabs@localhost:5432/flwrlabs",
    )
    table_name: str = context.node_config.get("table-name", "person_measurements")

    selected_features: list[str] = msg.content["config"]["selected_features"]
    feature_aggregation: list[str] = msg.content["config"]["feature_aggregation"]

    # Query database
    df = query_database(
        db_url=db_url,
        table_name=table_name,
        selected_features=selected_features,
    )

    # Compute aggregation metrics
    metrics = {}
    for feature in selected_features:
        if feature not in df.columns:
            raise ValueError(f"Feature '{feature}' not found in dataset columns.")

        for agg in feature_aggregation:
            if agg == "mean":
                metrics[f"{feature}_{agg}_sum"] = sum(df[feature])
                metrics[f"{feature}_{agg}_count"] = len(df[feature])
            elif agg == "std":
                metrics[f"{feature}_{agg}_sum"] = sum(df[feature])
                metrics[f"{feature}_{agg}_count"] = len(df[feature])
                metrics[f"{feature}_{agg}_sum_sqd"] = sum(df[feature] ** 2)
            else:
                raise ValueError(f"Aggregation method '{agg}' not recognized.")

    reply_content = RecordDict({"query_results": MetricRecord(metrics)})

    return Message(reply_content, reply_to=msg)

def grade(adjective, suffix=COMPARATIVE):
    n = _count_syllables(adjective)
    if adjective in grade_irregular:
        # A number of adjectives inflect irregularly.
        return grade_irregular[adjective][suffix != COMPARATIVE]
    elif adjective in grade_uninflected:
        # A number of adjectives don't inflect at all.
        return "%s %s" % (suffix == COMPARATIVE and "more" or "most", adjective)
    elif n <= 2 and adjective.endswith("e"):
        # With one syllable and ending with an e: larger, wiser.
        suffix = suffix.lstrip("e")
    elif n == 1 and len(adjective) >= 3 \
     and adjective[-1] not in VOWELS and adjective[-2] in VOWELS and adjective[-3] not in VOWELS:
        # With one syllable ending with consonant-vowel-consonant: bigger, thinner.
        if not adjective.endswith(("w")): # Exceptions: lower, newer.
            suffix = adjective[-1] + suffix
    elif n == 1:
        # With one syllable ending with more consonants or vowels: briefer.
        pass
    elif n == 2 and adjective.endswith("y"):
        # With two syllables ending with a y: funnier, hairier.
        adjective = adjective[:-1] + "i"
    elif n == 2 and adjective[-2:] in ("er", "le", "ow"):
        # With two syllables and specific suffixes: gentler, narrower.
        pass
    else:
        # With three or more syllables: more generous, more important.
        return "%s %s" % (suffix == COMPARATIVE and "more" or "most", adjective)
    return adjective + suffix

def update(self, weight=10.0, limit=0.5):
        GraphLayout.update(self)
        # Forces on all nodes due to node-node repulsions.
        for i, n1 in enumerate(self.graph.nodes):
            for j, n2 in enumerate(self.graph.nodes[i + 1:]):
                self._repulse(n1, n2)
        # Forces on nodes due to edge attractions.
        for e in self.graph.edges:
            self._attract(e.node1, e.node2, weight * e.weight, 1.0 / (e.length or 0.01))
        # Move nodes by given force.
        for n in self.graph.nodes:
            if not n.fixed:
                n._x += max(-limit, min(self.force * n.force.x, limit))
                n._y += max(-limit, min(self.force * n.force.y, limit))
            n.force.x = 0
            n.force.y = 0

def update_hessian_with_batch(self, input_batch):
        if input_batch is None:
            raise ValueError("Input tensor cannot be None.")

        if len(input_batch.shape) < 2:
            raise ValueError(
                "Input tensor must have rank >= 2 "
                f"(got rank {len(input_batch.shape)})."
            )
        if ops.size(input_batch) == 0:
            raise ValueError("Input tensor cannot be empty.")
        if len(input_batch.shape) > 2:
            # [batch, features]
            input_batch = ops.reshape(input_batch, (-1, input_batch.shape[-1]))
        x = ops.cast(input_batch, "float32")

        num_new_samples = ops.shape(x)[0]
        num_prev_samples = self.num_samples
        total_samples = ops.add(num_prev_samples, num_new_samples)

        if ops.shape(self.hessian)[0] != ops.shape(x)[-1]:
            raise ValueError(
                f"Hessian dimensions ({ops.shape(self.hessian)[0]}) do not "
                f"match input features ({ops.shape(x)[-1]})."
            )

        # gram_matrix: [features, features]
        gram_matrix = ops.matmul(ops.transpose(x), x)
        # Ensures numerical stability and symmetry in case of large floating
        # point activations.
        gram_matrix = ops.divide(
            ops.add(gram_matrix, ops.transpose(gram_matrix)), 2.0
        )

        # Decay previous mean and add current per-sample contribution
        # (factor 2/N)
        if self.num_samples > 0:
            self.hessian = ops.multiply(
                self.hessian, ops.divide(num_prev_samples, total_samples)
            )

        self.hessian = ops.add(
            self.hessian,
            ops.multiply(ops.divide(2.0, total_samples), gram_matrix),
        )

        self.num_samples = self.num_samples + ops.shape(x)[0] or 0

def call_feature(self, call, feat_config, layer_name, **kwargs):
        if call.__name__ == "inspect_tensor":
            kwargs_copy = kwargs.copy()
            for k in [
                "quantizer",
                "columnwise_quantized_tensor",
                "rowwise_quantized_tensor",
                "tp_size",
            ]:
                if k not in call.__code__.co_varnames:
                    kwargs_copy.pop(k, None)
        else:
            kwargs_copy = kwargs

        if call.__name__ == "inspect_tensor_postquantize":
            warnings.warn(
                "inspect_tensor_postquantize is deprecated, use inspect_tensor instead.",
                DeprecationWarning,
            )
            kwargs_copy = kwargs.copy()
            for k in ["tp_size"]:
                if k not in call.__code__.co_varnames:
                    kwargs_copy.pop(
                        k, None
                    )  # use None default to avoid KeyError if kwarg wasn't passed

        return call(feat_config, layer_name, **kwargs_copy)

def holidays(
        self, start=None, end=None, return_name: bool = False
    ) -> DatetimeIndex | Series:
        if self.rules is None:
            raise Exception(
                f"Holiday Calendar {self.name} does not have any rules specified"
            )

        if start is None:
            start = AbstractHolidayCalendar.start_date

        if end is None:
            end = AbstractHolidayCalendar.end_date

        start = Timestamp(start)
        end = Timestamp(end)

        # If we don't have a cache or the dates are outside the prior cache, we
        # get them again
        if self._cache is None or start < self._cache[0] or end > self._cache[1]:
            pre_holidays = [
                rule.dates(start, end, return_name=True) for rule in self.rules
            ]
            if pre_holidays:
                holidays = concat(pre_holidays)
            else:
                holidays = Series(index=DatetimeIndex([]), dtype=object)

            self._cache = (start, end, holidays.sort_index())

        holidays = self._cache[2]
        holidays = holidays[start:end]

        if return_name:
            return holidays
        else:
            return holidays.index

def softmax(x, axis=-1):
    # Don't use `backend.shape` since TensorFlow returns
    # symbolic tensors for unknown shape which can trigger
    # an error in TensorFlow graph execution.
    if isinstance(axis, int) and x.shape[axis] == 1:
        warnings.warn(
            f"You are using a softmax over axis {axis} "
            f"of a tensor of shape {x.shape}. This axis "
            "has size 1. The softmax operation will always return "
            "the value 1, which is likely not what you intended. "
            "Did you mean to use a sigmoid instead?"
        )
    if any_symbolic_tensors((x,)):
        return Softmax(axis).symbolic_call(x)
    if isinstance(axis, tuple):
        axis_to_keep = [v for v in range(len(x.shape)) if v not in axis]

        x_transposed = backend.numpy.transpose(x, axes=(*axis_to_keep, *axis))
        x_reshaped = backend.numpy.reshape(
            x_transposed, (*[x.shape[v] for v in axis_to_keep], -1)
        )

        x = backend.nn.softmax(x_reshaped, axis=-1)

        x = backend.numpy.reshape(x, x_transposed.shape)
        combined = [*axis_to_keep, *axis]
        x = backend.numpy.transpose(
            x,
            axes=sorted(range(len(combined)), key=combined.__getitem__),
        )
        return x
    else:
        return backend.nn.softmax(x, axis=axis)

def get_attn_bias_and_cat(x_list, branges=None):
    batch_sizes = [b.shape[0] for b in branges] if branges is not None else [x.shape[0] for x in x_list]
    all_shapes = tuple((b, x.shape[1]) for b, x in zip(batch_sizes, x_list))
    if all_shapes not in attn_bias_cache.keys():
        seqlens = []
        for b, x in zip(batch_sizes, x_list):
            for _ in range(b):
                seqlens.append(x.shape[1])
        attn_bias = fmha.BlockDiagonalMask.from_seqlens(seqlens)
        attn_bias._batch_sizes = batch_sizes
        attn_bias_cache[all_shapes] = attn_bias

    if branges is not None:
        cat_tensors = index_select_cat([x.flatten(1) for x in x_list], branges).view(1, -1, x_list[0].shape[-1])
    else:
        tensors_bs1 = tuple(x.reshape([1, -1, *x.shape[2:]]) for x in x_list)
        cat_tensors = torch.cat(tensors_bs1, dim=1)

    return attn_bias_cache[all_shapes], cat_tensors

def op_to_adjvec(
    ops: Iterable[PauliSentence | Operator | TensorLike],
    basis: PauliSentence | Operator | TensorLike,
    is_orthogonal: bool = True,
):

    if all(isinstance(op, Operator) for op in basis):
        ops = [op.pauli_rep for op in ops]
        basis = [op.pauli_rep for op in basis]

    # PauliSentence branch
    if all(isinstance(op, PauliSentence) for op in basis):
        return _op_to_adjvec_ps(ops, basis, is_orthogonal)

    # dense branch
    if all(
        isinstance(op, TensorLike) and not isinstance(op, (int, float, complex)) for op in basis
    ):
        if not all(isinstance(op, TensorLike) for op in ops):
            _n = int(math.round(math.log2(basis[0].shape[-1])))
            ops = math.array([matrix(op, wire_order=range(_n)) for op in ops])

        basis = math.array(basis)
        res = trace_inner_product(math.array(ops), basis).real
        if is_orthogonal:
            norm = math.real(math.einsum("bij,bji->b", basis, basis)) / math.shape(basis[0])[0]
            return res / norm
        gram = math.real(trace_inner_product(basis, basis))
        sqrtm_gram = sqrtm(gram)
        # Imaginary component is an artefact
        assert math.allclose(math.imag(sqrtm_gram), 0.0, atol=1e-16)
        return math.einsum("ij,kj->ki", math.linalg.pinv(sqrtm_gram.real), res)

    raise NotImplementedError(
        "At least one operator in the specified basis is of unsupported type, "
        "or not all operators are of the same type."
    )

def should_continue(
        self,
        *,
        max_handoffs: int,
        max_iterations: int,
        execution_timeout: float,
        repetitive_handoff_detection_window: int,
        repetitive_handoff_min_unique_agents: int,
    ) -> tuple[bool, str]:
        # Check handoff limit
        if len(self.node_history) >= max_handoffs:
            return False, f"Max handoffs reached: {max_handoffs}"

        # Check iteration limit
        if len(self.node_history) >= max_iterations:
            return False, f"Max iterations reached: {max_iterations}"

        # Check timeout
        elapsed = self.execution_time / 1000 + time.time() - self.start_time
        if elapsed > execution_timeout:
            return False, f"Execution timed out: {execution_timeout}s"

        # Check for repetitive handoffs (agents passing back and forth)
        if repetitive_handoff_detection_window > 0 and len(self.node_history) >= repetitive_handoff_detection_window:
            recent = self.node_history[-repetitive_handoff_detection_window:]
            unique_nodes = len(set(recent))
            if unique_nodes < repetitive_handoff_min_unique_agents:
                return (
                    False,
                    (
                        f"Repetitive handoff: {unique_nodes} unique nodes "
                        f"out of {repetitive_handoff_detection_window} recent iterations"
                    ),
                )

        return True, "Continuing"

def learn_many(self, X: pd.DataFrame, y: pd.Series | None = None, **params):
        steps = iter(self.steps.values())

        # Loop over the first n - 1 steps, which should all be transformers
        for t in itertools.islice(steps, len(self) - 1):
            if not self._LEARN_UNSUPERVISED_DURING_PREDICT:
                if isinstance(t, union.TransformerUnion):
                    for sub_t in t.transformers.values():
                        if not sub_t._supervised:
                            sub_t.learn_many(X)
                elif not t._supervised:
                    t.learn_many(X)

            X_pre = X
            X = t.transform_many(X=X)

            # The supervised transformers have to be updated.
            # Note that this is done after transforming in order to avoid target leakage.
            if isinstance(t, union.TransformerUnion):
                for sub_t in t.transformers.values():
                    if sub_t._supervised:
                        sub_t.learn_many(X=X_pre, y=y)

            elif t._supervised:
                t.learn_many(X=X_pre, y=y)

        last_step = next(steps)
        if last_step._supervised:
            last_step.learn_many(X=X, y=y, **params)
        else:
            last_step.learn_many(X=X, **params)

def serialize(
        value: Any,
        current_path: Optional[List[str]] = None,
        combine_values_and_column_types=combine_values_and_column_types,
        save_path=save_path,
    ) -> Any:
        serialized_value = None
        current_path = current_path or []

        full_save_path = os.path.join(save_path, *current_path) if save_path else None
        key_path = '.'.join(current_path)
        variable_type, _ = infer_variable_type(value)

        if isinstance(value, dict):
            serialized_value = {k: serialize(v, current_path + [k]) for k, v in value.items()}
        elif is_basic_iterable(value):
            value_iter = list(value) if isinstance(value, set) else value
            serialized_value = [
                serialize(
                    v,
                    current_path + [str(i)],
                )
                for i, v in enumerate(value_iter)
            ]
        else:
            if variable_type in [
                VariableType.CUSTOM_OBJECT,
                VariableType.MODEL_SKLEARN,
                VariableType.MODEL_XGBOOST,
            ]:
                if full_save_path:
                    os.makedirs(os.path.dirname(full_save_path), exist_ok=True)
                    _, full_save_path = save_custom_object(value, full_save_path, variable_type)

            serialized_value, _ = prepare_data_for_output(value)

        if current_path:
            update_column_types(
                value,
                key_path,
                variable_type=variable_type,
                full_save_path=full_save_path,
                serialized_value=serialized_value,
            )

        return serialized_value

def from_managed_job_status(
            cls,
            status: Optional['managed_jobs.ManagedJobStatus']) -> 'JobExitCode':
        # Import here to avoid circular imports
        # pylint: disable=import-outside-toplevel
        from sky import jobs as managed_jobs

        if status is None:
            return cls.NOT_FOUND

        if not status.is_terminal():
            return cls.NOT_FINISHED

        if status == managed_jobs.ManagedJobStatus.SUCCEEDED:
            return cls.SUCCEEDED

        if status == managed_jobs.ManagedJobStatus.CANCELLED:
            return cls.CANCELLED

        if status.is_failed():
            return cls.FAILED

        # Should not hit this case, but included to avoid errors
        return cls.FAILED

def merge_markdown(nb: nbf.notebooknode.NotebookNode) -> None:
    start_idx = None
    slices = []
    for i, cell in enumerate(nb["cells"]):
        if cell["cell_type"] == "markdown":
            if start_idx is None:
                start_idx = i
        else:
            if start_idx is not None:
                if i - start_idx > 1:
                    slices.append(slice(start_idx, i))
                start_idx = None
    for sl in slices[::-1]:
        nb["cells"][sl.start]["source"] = "\n\n".join([c["source"].rstrip() for c in nb["cells"][sl]])
        del nb["cells"][sl.start + 1: sl.stop]  # nb["cells"][sl] does not work properly

def identify_dense_edges(trace: Trace) -> None:
    for name, node in trace.nodes.items():
        if site_is_subsample(node):
            continue
        if node["type"] == "sample":
            for past_name, past_node in trace.nodes.items():
                if site_is_subsample(past_node):
                    continue
                if past_node["type"] == "sample":
                    if past_name == name:
                        break
                    past_node_independent = False
                    for query, target in zip(
                        node["cond_indep_stack"], past_node["cond_indep_stack"]
                    ):
                        if (
                            query.name == target.name
                            and query.counter != target.counter
                        ):
                            past_node_independent = True
                            break
                    if not past_node_independent:
                        trace.add_edge(past_name, name)

def run(self, artifact: PipelineArtifact) -> None:
        edge_program_manager = artifact.data

        if not isinstance(edge_program_manager, EdgeProgramManager):
            raise TypeError(
                f"Expected EdgeProgramManager but got {type(edge_program_manager)}"
            )

        if not self._edge_transform_passes and not self._edge_manager_transform_passes:
            self._artifact = artifact
            return

        # Detect if any callable returns PassManager
        pass_manager = None
        transform_passes = defaultdict(list)
        for method_name in edge_program_manager.methods:
            # Resolve transform passes if it's a callable
            ep = edge_program_manager.exported_program(method_name)
            for pass_callable in self._edge_transform_passes or []:
                if not callable(pass_callable):
                    raise ValueError(
                        "Transform passes must be a callable that resolves to passes"
                    )
                passes = pass_callable(method_name, ep)
                if isinstance(passes, PassManager):
                    pass_manager = passes
                    break
                else:
                    transform_passes[method_name].extend(passes)
            if pass_manager:
                break

        # Use PassManager directly if found, otherwise use dict
        final_passes = pass_manager if pass_manager else transform_passes

        # Apply edge transform passes
        edge_program_manager = edge_program_manager.transform(final_passes)

        # Run edge manager transform passes
        for pass_callable in self._edge_manager_transform_passes:
            passes = pass_callable(edge_program_manager)
            if passes:
                edge_program_manager = edge_program_manager.transform(passes)

        self._artifact = artifact.copy_with_new_data(edge_program_manager)

def load(cls, file="data.yaml", append_filename=False):
        instance = cls._get_instance()
        assert str(file).endswith((".yaml", ".yml")), f"Not a YAML file: {file}"

        # Read file content
        with open(file, errors="ignore", encoding="utf-8") as f:
            s = f.read()

        # Try loading YAML with fallback for problematic characters
        try:
            data = instance.yaml.load(s, Loader=instance.SafeLoader) or {}
        except Exception as e:
            # Remove problematic characters and retry
            s = re.sub(r"[^\x09\x0A\x0D\x20-\x7E\x85\xA0-\uD7FF\uE000-\uFFFD\U00010000-\U0010ffff]+", "", s)
            try:
                data = instance.yaml.load(s, Loader=instance.SafeLoader) or {}
            except Exception:
                raise ValueError(
                    f"YAML syntax error in '{file}': {e}\nVerify YAML with https://ray.run/tools/yaml-formatter"
                ) from None

        # Check for accidental user-error None strings (should be 'null' in YAML)
        if "None" in data.values():
            data = {k: None if v == "None" else v for k, v in data.items()}

        if append_filename:
            data["yaml_file"] = str(file)
        return data

def load(
        self,
        query_string: str,
        limit: int = QUERY_ROW_LIMIT,
        display_query: Union[str, None] = None,
        verbose: bool = True,
        *args,
        **kwargs,
    ) -> Union[DataFrame, None]:
        print_message = 'Loading data'
        if verbose:
            print_message += ' with query'

            if display_query:
                for line in display_query.split('\n'):
                    print_message += f'\n{line}'
            else:
                print_message += f'\n\n{query_string}\n\n'

        query_string = self._clean_query(query_string)

        try:
            with self.printer.print_msg(print_message):
                with self.conn.cursor() as cur:
                    return cur.execute(
                        self._enforce_limit(query_string, limit), *args, **kwargs
                    ).fetch_dataframe()
        except Exception as e:
            try:
                raw_string = str(e).replace('"', '\\"').replace("'", '"')
                error_message = json.loads(raw_string).get('M')
                if error_message:
                    print(f'\n\nError: {error_message}')
                else:
                    raise e
            except json.JSONDecodeError:
                raise e

def predict(self, X):
        if self.weights == "uniform":
            # In that case, we do not need the distances to perform
            # the weighting so we do not compute them.
            neigh_ind = self.kneighbors(X, return_distance=False)
            neigh_dist = None
        else:
            neigh_dist, neigh_ind = self.kneighbors(X)

        weights = _get_weights(neigh_dist, self.weights)

        _y = self._y
        if _y.ndim == 1:
            _y = _y.reshape((-1, 1))

        if weights is None:
            y_pred = np.mean(_y[neigh_ind], axis=1)
        else:
            y_pred = np.empty((neigh_dist.shape[0], _y.shape[1]), dtype=np.float64)
            denom = np.sum(weights, axis=1)

            for j in range(_y.shape[1]):
                num = np.sum(_y[neigh_ind, j] * weights, axis=1)
                y_pred[:, j] = num / denom

        if self._y.ndim == 1:
            y_pred = y_pred.ravel()

        return y_pred

def docstring_to_markdown(docstring):
    new_docstring_lst = []

    encountered_examples = False
    for idx, line in enumerate(docstring.split("\n")):
        line = line.strip()
        if set(line) in ({"-"}, {"="}):
            new_docstring_lst[idx - 1] = "**%s**" % new_docstring_lst[idx - 1]
        elif line.startswith(">>>"):
            if not encountered_examples:
                new_docstring_lst.append("```")
                encountered_examples = True
        new_docstring_lst.append(line)

    for idx, line in enumerate(new_docstring_lst[1:]):
        if line:
            if line.startswith("Description : "):
                new_docstring_lst[idx + 1] = new_docstring_lst[idx + 1].replace(
                    "Description : ", ""
                )
            elif " : " in line:
                line = line.replace(" : ", "` : ")
                new_docstring_lst[idx + 1] = "\n- `%s\n" % line
            elif "**" in new_docstring_lst[idx - 1] and "**" not in line:
                new_docstring_lst[idx + 1] = "\n%s" % line.lstrip()
            elif "**" not in line:
                new_docstring_lst[idx + 1] = "    %s" % line.lstrip()

    clean_lst = []
    for line in new_docstring_lst:
        if set(line.strip()) not in ({"-"}, {"="}):
            clean_lst.append(line)

    if encountered_examples:
        clean_lst.append("```")
    return clean_lst

def deps(self, value):
        graph = self._sent._enhanced_dependencies
        # if we don't have a graph, and we aren't trying to set any actual
        # dependencies, we can save the time of doing anything else
        if graph is None and value is None:
            return

        if graph is None:
            graph = nx.MultiDiGraph()
            self._sent._enhanced_dependencies = graph
        # need to make a new list: cannot iterate and delete at the same time
        if graph.has_node(self.id):
            in_edges = list(graph.in_edges(self.id))
            graph.remove_edges_from(in_edges)

        if value is None:
            return

        if isinstance(value, str):
            value = value.split("|")
        if all(isinstance(x, str) for x in value):
            value = [x.split(":", maxsplit=1) for x in value]
        for parent, dep in value:
            # we have to match the format of the IDs.  since the IDs
            # of the words are int if they aren't empty words, we need
            # to convert single int IDs into int instead of tuple
            parent = tuple(map(int, parent.split(".", maxsplit=1)))
            if len(parent) == 1:
                parent = parent[0]
            graph.add_edge(parent, self.id, dep)

def run_distillation_cache_generation(distiller: Optional[DistillationBase]) -> None:
    if distiller is None or not hasattr(distiller, "requires_distillation_cache"):
        return

    try:
        requires_cache = bool(distiller.requires_distillation_cache())
    except Exception:
        requires_cache = False

    if not requires_cache:
        return

    provider = distiller.get_ode_generator_provider() if hasattr(distiller, "get_ode_generator_provider") else None
    if provider is None or not hasattr(provider, "generate") or not callable(provider.generate):
        logger.debug("Distiller requested a cache but did not supply a valid ODE generator provider.")
        return

    required_type = None
    if hasattr(distiller, "get_required_distillation_cache_type"):
        required_type = distiller.get_required_distillation_cache_type()

    distillation_backends = StateTracker.get_data_backends(
        _type="distillation_cache",
        _types=["distillation_cache"],
    )

    if not distillation_backends:
        raise ValueError("Distillation method requires a distillation_cache dataset but none were configured.")

    selected_backends = {}
    for backend_id, backend in distillation_backends.items():
        backend_type = backend.get("distillation_type") or backend.get("config", {}).get("distillation_type")
        if required_type and backend_type != required_type:
            continue
        selected_backends[backend_id] = backend

    if required_type and not selected_backends:
        raise ValueError(
            f"Distillation method requested cache type '{required_type}' but no matching distillation_cache dataset was provided."
        )

    targets = selected_backends if selected_backends else distillation_backends

    for backend_id, backend in targets.items():
        cache = backend.get("distillation_cache")
        if cache is None:
            raise ValueError(f"Distillation cache backend '{backend_id}' is missing its cache instance.")
        provider.generate(cache, backend_config=backend.get("config", {}))

def infer_granularity(time_stamps, return_offset=False):
    # See if pandas can infer the granularity on its own
    orig_t = to_pd_datetime(time_stamps)
    if len(orig_t) > 2:
        freq = pd.infer_freq(orig_t)
    elif len(orig_t) == 2:
        freq = orig_t[1] - orig_t[0]
    else:
        raise ValueError("Need at least 2 timestamps to infer a granularity.")
    offset = pd.to_timedelta(0)
    if freq is not None:
        freq = pd_to_offset(freq)
        return (freq, offset) if return_offset else freq

    # Otherwise, start with the most commonly occurring timedelta
    dt = pd.to_timedelta(scipy.stats.mode(orig_t[1:] - orig_t[:-1], axis=None)[0].item())

    # Check if the data could be sampled at a k-monthly granularity.
    candidate_freqs = [dt]
    for k in range(math.ceil(dt / pd.Timedelta(days=31)), math.ceil(dt / pd.Timedelta(days=28))):
        candidate_freqs.extend([pd_to_offset(f"{k}MS"), pd_to_offset(f"{k}M")])

    # Pick the sampling frequency which has the most overlap with the actual timestamps
    freq2idx = {f: pd.date_range(start=orig_t[0], end=orig_t[-1], freq=f) for f in candidate_freqs}
    freq2offset = {f: get_date_offset(time_stamps=freq2idx[f], reference=orig_t) for f in candidate_freqs}
    freq = sorted(freq2idx.keys(), key=lambda f: len((freq2idx[f] + freq2offset[f]).intersection(orig_t)))[-1]
    return (freq, freq2offset[freq]) if return_offset else freq

def convert_weights(model: nn.Module):
    def _convert_weights_to_fp16(layer):
        if isinstance(layer, (nn.Conv1d, nn.Conv2d, nn.Linear)):
            layer.weight.data = layer.weight.data.half()
            if layer.bias is not None:
                layer.bias.data = layer.bias.data.half()

        if isinstance(layer, nn.MultiheadAttention):
            for attr in [
                    *[f'{s}_proj_weight' for s in ['in', 'q', 'k', 'v']],
                    'in_proj_bias', 'bias_k', 'bias_v'
            ]:
                tensor = getattr(layer, attr)
                if tensor is not None:
                    tensor.data = tensor.data.half()

        for name in ['text_projection', 'proj']:
            if hasattr(layer, name):
                attr = getattr(layer, name)
                if attr is not None:
                    attr.data = attr.data.half()

        for name in ['prompt_embeddings']:
            if hasattr(layer, name):
                attr = getattr(layer, name)
                if attr is not None:
                    attr.data = attr.data.half()

    model.apply(_convert_weights_to_fp16)

def after_substep(self, physics, unused_random_state):
    if self._hit:
      # Ball has already registered a valid contact within step (during one of
      # previous after_substep calls).
      return

    # Iterate through all contacts to find the first contact between the ball
    # and one of the registered entities.
    for contact in physics.data.contact:
      # Keep contacts that involve the ball and one of the registered entities.
      has_self = False
      for geom_id in (contact.geom1, contact.geom2):
        if geom_id == self._geom_id:
          has_self = True
        else:
          player = self._geom_id_to_player.get(geom_id)

      if has_self and player:
        # Detected a contact between the ball and an registered player.
        if self._last_hit is not None:
          self._intercepted = player.team != self._last_hit.team
        else:
          self._intercepted = True

        # Register repossessed before updating last_hit player.
        self._repossessed = player is not self._last_hit
        self._last_hit = player
        # Register hit event.
        self._hit = True
        break

def set_size_inches(self, w, h=None, forward=True):
        if h is None:  # Got called with a single pair as argument.
            w, h = w
        if w is None or h is None:
            raise ValueError(
                "Figure.set_size_inches does not accept None; provide both "
                "width and height explicitly")
        size = np.array([w, h])
        if not np.isfinite(size).all() or (size < 0).any():
            raise ValueError(f'figure size must be positive finite not {size}')
        self.bbox_inches.p1 = size
        if forward:
            manager = self.canvas.manager
            if manager is not None:
                manager.resize(*(size * self.dpi).astype(int))
        self.stale = True

def remove_model_config_classes_from_config_check(model_config_classes):
    filename = REPO_PATH / "utils/check_config_attributes.py"
    with open(filename, "r") as f:
        check_config_attributes = f.read()

    # Keep track as we have to delete comment above too
    in_special_cases_to_allow = False
    in_indent = False
    new_file_lines = []

    for line in check_config_attributes.split("\n"):
        indent = get_line_indent(line)
        if (line.strip() == "SPECIAL_CASES_TO_ALLOW = {") or (line.strip() == "SPECIAL_CASES_TO_ALLOW.update("):
            in_special_cases_to_allow = True

        elif in_special_cases_to_allow and indent == 0 and line.strip() in ("}", ")"):
            in_special_cases_to_allow = False

        if in_indent:
            if line.strip().endswith(("]", "],")):
                in_indent = False
            continue

        if in_special_cases_to_allow and any(
            model_config_class in line for model_config_class in model_config_classes
        ):
            # Remove comments above the model config class to remove
            while new_file_lines[-1].strip().startswith("#"):
                new_file_lines.pop()

            if line.strip().endswith("["):
                in_indent = True

            continue

        elif any(model_config_class in line for model_config_class in model_config_classes):
            continue

        new_file_lines.append(line)

    with open(filename, "w") as f:
        f.write("\n".join(new_file_lines))

def compute_forward(self, mix, targets, stage, noise=None):
        # Unpack lists and put tensors in the right device
        mix, mix_lens = mix
        mix, mix_lens = mix.to(self.device), mix_lens.to(self.device)

        # Convert targets to tensor
        targets = torch.cat(
            [
                targets[i][0].unsqueeze(-1)
                for i in range(self.hparams.num_spks)
            ],
            dim=-1,
        ).to(self.device)

        # Add speech distortions
        if stage == sb.Stage.TRAIN:
            with torch.no_grad():
                if self.hparams.use_speedperturb or self.hparams.use_rand_shift:
                    mix, targets = self.add_speed_perturb(targets, mix_lens)

                    mix = targets.sum(-1)

                if self.hparams.use_wavedrop:
                    mix = self.hparams.wavedrop(mix, mix_lens)

                if self.hparams.limit_training_signal_len:
                    mix, targets = self.cut_signals(mix, targets)

        # Separation
        mix_w = self.modules['encoder'](mix)
        est_mask = self.modules['masknet'](mix_w)
        mix_w = torch.stack([mix_w] * self.hparams.num_spks)
        sep_h = mix_w * est_mask

        # Decoding
        est_source = torch.cat(
            [
                self.modules['decoder'](sep_h[i]).unsqueeze(-1)
                for i in range(self.hparams.num_spks)
            ],
            dim=-1,
        )
        # T changed after conv1d in encoder, fix it here
        T_origin = mix.size(1)
        T_est = est_source.size(1)
        if T_origin > T_est:
            est_source = F.pad(est_source, (0, 0, 0, T_origin - T_est))
        else:
            est_source = est_source[:, :T_origin, :]

        return est_source, targets

def move_to_device(item, device, criterion_func=None):
    if (criterion_func is not None and criterion_func(item)):
        device_copy = item.to(device)
        item.data = device_copy.data
        return item
    elif isinstance(item, list):
        return [move_to_device(v, device, criterion_func) for v in item]
    elif isinstance(item, tuple):
        return tuple([move_to_device(v, device, criterion_func) for v in item])
    elif isinstance(item, dict):
        return {k: move_to_device(v, device, criterion_func) for k, v in item.items()}
    else:
        return item.to(device)

def ocr_to_dateparser_languages(ocr_languages: str) -> list[str]:
    loader = LocaleDataLoader()
    result = []
    try:
        for ocr_language in ocr_languages.split("+"):
            # Split into language and optional script
            ocr_lang_part, *script = ocr_language.split("_")
            ocr_script_part = script[0] if script else None

            language_part = OCR_TO_DATEPARSER_LANGUAGES.get(ocr_lang_part)
            if language_part is None:
                logger.debug(
                    f'Unable to map OCR language "{ocr_lang_part}" to dateparser locale. ',
                )
                continue

            # Ensure base language is supported by dateparser
            loader.get_locale_map(locales=[language_part])

            # Try to add the script part if it's supported by dateparser
            if ocr_script_part:
                dateparser_language = f"{language_part}-{ocr_script_part.title()}"
                try:
                    loader.get_locale_map(locales=[dateparser_language])
                except Exception:
                    logger.info(
                        f"Language variant '{dateparser_language}' not supported by dateparser; falling back to base language '{language_part}'. You can manually set PAPERLESS_DATE_PARSER_LANGUAGES if needed.",
                    )
                    dateparser_language = language_part
            else:
                dateparser_language = language_part
            if dateparser_language not in result:
                result.append(dateparser_language)
    except Exception as e:
        logger.warning(
            f"Error auto-configuring dateparser languages. Set PAPERLESS_DATE_PARSER_LANGUAGES parameter to avoid this. Detail: {e}",
        )
        return []
    if not result:
        logger.info(
            "Unable to automatically determine dateparser languages from OCR_LANGUAGE, falling back to multi-language support.",
        )
    return result

def get_serializer_from_filename(filename):
    logger.debug("filename: '%s'", filename)
    extension = os.path.splitext(filename)[1].lower()
    logger.debug("extension: '%s'", extension)

    if extension == ".json":
        retval = _JSONSerializer()
    elif extension in (".p", ".pickle"):
        retval = _PickleSerializer()
    elif extension == ".npy":
        retval = _NPYSerializer()
    elif extension == ".fsa":
        retval = _CompressedSerializer()
    elif extension in (".yaml", ".yml") and _HAS_YAML:
        retval = _YAMLSerializer()
    elif extension in (".yaml", ".yml"):
        logger.warning("You must have PyYAML installed to use YAML as the serializer.\n"
                       "Switching to JSON as the serializer.")
        retval = _JSONSerializer()
    else:
        logger.warning("Unrecognized extension: '%s'. Returning json serializer", extension)
        retval = _JSONSerializer()
    logger.debug(retval)
    return retval

def find_matching_trees(docs, num_sentences, accepted_trees, tag_pipe, parser_pipes, shuffle=True, chunk_size=10, max_len=140, min_len=10, output_ptb=False):
    if num_sentences < 0:
        tqdm_total = len(docs)
    else:
        tqdm_total = num_sentences

    if output_ptb:
        output_format = "{}"
    else:
        output_format = "{:L}"

    with tqdm(total=tqdm_total, leave=False) as pbar:
        if shuffle:
            random.shuffle(docs)
        new_trees = set()
        for chunk_start in range(0, len(docs), chunk_size):
            chunk = docs[chunk_start:chunk_start+chunk_size]
            chunk = [stanza.Document([], text=t) for t in chunk]

            if num_sentences < 0:
                pbar.update(len(chunk))

            # first, retag the sentences
            tag_pipe(chunk)

            chunk = [d for d in chunk if len(d.sentences) > 0]
            if max_len is not None:
                # for now, we don't have a good way to deal with sentences longer than the bert maxlen
                chunk = [d for d in chunk if max(len(s.words) for s in d.sentences) < max_len]
            if len(chunk) == 0:
                continue

            parses = []
            try:
                for pipe in parser_pipes:
                    pipe(chunk)
                    trees = [output_format.format(sent.constituency) for doc in chunk for sent in doc.sentences if len(sent.words) >= min_len]
                    parses.append(trees)
            except TextTooLongError as e:
                # easiest is to skip this chunk - could theoretically save the other sentences
                continue

            for tree in zip(*parses):
                if len(set(tree)) != 1:
                    continue
                tree = tree[0]
                if tree in accepted_trees:
                    continue
                if tree not in new_trees:
                    new_trees.add(tree)
                    if num_sentences >= 0:
                        pbar.update(1)
                if num_sentences >= 0 and len(new_trees) >= num_sentences:
                    return new_trees

    return new_trees

def construct_debug_handle_to_ops_mapping(self) -> Dict:
        debug_handle_to_ops_mapping = {}
        for function_name, function in self.functions.items():
            if ScopeSource.EXIR_DEBUG_HANDLE not in function._essential_scope_sources:
                raise NotImplementedError(
                    f"Function ({function_name}) must have EXIR_DEBUG_HANDLE as an essential scope source."
                )
            for operation in function.operations:
                # TODO (rdar://115846569): Handle multi-block case from EXIR
                if len(operation.blocks) > 0:
                    raise NotImplementedError("Multi-block case has not been supported yet")
                debug_handle = operation.scopes[ScopeSource.EXIR_DEBUG_HANDLE]
                if debug_handle is None:
                    continue
                debug_handle = debug_handle[0]
                if debug_handle not in debug_handle_to_ops_mapping:
                    debug_handle_to_ops_mapping[debug_handle] = []
                debug_handle_to_ops_mapping[debug_handle].append(
                    [
                        {"Type": "Program"},
                        {"Type": "Function", "Name": function_name},
                        {"Type": "Block"},
                        {
                            "Type": "Operation",
                            "Operator": operation.op_type,
                            "Output": operation.outputs[0].name,
                        },
                    ]
                )
        return debug_handle_to_ops_mapping

def pref(self, token):
        if len(token) > 5:
            for p3 in self.pr3:
                if token.startswith(p3):
                    return token[3:]
        if len(token) > 6:
            for p4 in self.pr4:
                if token.startswith(p4):
                    return token[4:]
        if len(token) > 5:
            for p3 in self.pr32:
                if token.startswith(p3):
                    return token[3:]
        if len(token) > 4:
            for p2 in self.pr2:
                if token.startswith(p2):
                    return token[2:]

def tensor_ir_op(
    func: _tir.PrimFunc,
    name_hint: str,
    args: Tensor | Sequence[Tensor | rx.ShapeExpr | _tir.PrimExpr],
    out: OutType,
) -> OutType:
    from tvm import relax as rx  # pylint: disable=import-outside-toplevel

    call_tir_args, tir_vars = [], []
    if not isinstance(args, tuple | list):
        args = [args]

    for arg in args:
        if isinstance(arg, Tensor):
            call_tir_args.append(arg._expr)
        elif isinstance(arg, rx.ShapeExpr | _tir.PrimExpr):
            tir_vars.append(arg)
        else:
            raise TypeError(
                "Unsupported type: tensor_ir_op args expect Tensor or ShapeExpr or PrimExpr,"
                f"but got {type(arg)}"
            )

    if isinstance(out, Tensor):
        out_sinfo = [out._expr.struct_info]
    else:
        out_sinfo = [x._expr.struct_info for x in out]

    bb = BlockBuilder.current()
    global_var = bb.add_func(func, name_hint)

    if len(tir_vars) == 0:
        tir_vars = None

    return wrap_nested(
        bb.emit(rx.call_tir(global_var, call_tir_args, out_sinfo, tir_vars=tir_vars)),
        name=name_hint,
    )

def reduce_by_model(logs, error_filter=None):
    logs = [(x[0], x[1], get_model(x[2])) for x in logs]
    logs = [x for x in logs if x[2] is not None]
    tests = {x[2] for x in logs}

    r = {}
    for test in tests:
        counter = Counter()
        # count by errors in `test`
        counter.update([x[1] for x in logs if x[2] == test])
        counts = counter.most_common()
        error_counts = {error: count for error, count in counts if (error_filter is None or error not in error_filter)}
        n_errors = sum(error_counts.values())
        if n_errors > 0:
            r[test] = {"count": n_errors, "errors": error_counts}

    r = dict(sorted(r.items(), key=lambda item: item[1]["count"], reverse=True))
    return r

def reduce_acc_nodes_non_tensor_output(self) -> None:
        while True:
            new_cpu_nodes: NodeList = []

            for acc_node in self.acc_nodes:
                if is_node_output_tensor(acc_node):
                    continue
                for user in acc_node.users:
                    if user not in self.acc_nodes:
                        new_cpu_nodes.append(acc_node)
                        break

            if not new_cpu_nodes:
                break

            for new_cpu_node in new_cpu_nodes:
                self.acc_nodes.remove(new_cpu_node)

            self.reduce_acc_nodes_non_tensor_input_helper(new_cpu_nodes)

def embed(self, sentences: Union[list[Sentence], Sentence]):
        everything_embedded: bool = True

        # if only one sentence is passed, convert to list of sentence
        if type(sentences) is Sentence:
            sentences = [sentences]

        for sentence in sentences:
            if self.name not in sentence._embeddings:
                everything_embedded = False

        if not everything_embedded:
            self.embeddings.embed(sentences)

            for sentence in sentences:
                word_embeddings = []
                for token in sentence.tokens:
                    word_embeddings.append(token.get_embedding().unsqueeze(0))

                word_embeddings = torch.cat(word_embeddings, dim=0).to(flair.device)

                mean_embedding = torch.mean(word_embeddings, 0)

                sentence.set_embedding(self.name, mean_embedding)

def bit_flip_mixer(graph: nx_Graph | rx.PyGraph, b: int):
    _validate_graph(graph)

    if b not in [0, 1]:
        raise ValueError(f"'b' must be either 0 or 1, got {b}")

    sign = 1 if b == 0 else -1

    coeffs = []
    terms = []

    is_rx = isinstance(graph, rx.PyGraph)
    graph_nodes = graph.node_indexes() if is_rx else graph.nodes

    # In RX each node is assigned to an integer index starting from 0;
    # thus, we use the following lambda function to get node-values.
    def get_nvalue(i):
        return graph.nodes()[i] if is_rx else i

    for i in graph_nodes:
        neighbours = sorted(graph.neighbors(i)) if is_rx else list(graph.neighbors(i))
        degree = len(neighbours)

        n_terms = [[X(get_nvalue(i))]] + [
            [Identity(get_nvalue(n)), Z(get_nvalue(n))] for n in neighbours
        ]
        n_coeffs = [[1, sign] for _ in neighbours]

        final_terms = [prod(*list(m)).simplify() for m in itertools.product(*n_terms)]

        final_coeffs = [
            (0.5**degree) * functools.reduce(lambda x, y: x * y, list(m), 1)
            for m in itertools.product(*n_coeffs)
        ]

        coeffs.extend(final_coeffs)
        terms.extend(final_terms)

    return LinearCombination(coeffs, terms)

def find_prepositions(chunked):
    # Tokens that are not part of a preposition just get the O-tag.
    for ch in chunked:
        ch.append("O")
    for i, chunk in enumerate(chunked):
        if chunk[2].endswith("PP") and chunk[-1] == "O":
            # Find PP followed by other PP, NP with nouns and pronouns, VP with a gerund.
            if i < len(chunked) - 1 and \
             (chunked[i + 1][2].endswith(("NP", "PP")) or \
              chunked[i + 1][1] in ("VBG", "VBN")):
                chunk[-1] = "B-PNP"
                pp = True
                for ch in chunked[i + 1:]:
                    if not (ch[2].endswith(("NP", "PP")) or ch[1] in ("VBG", "VBN")):
                        break
                    if ch[2].endswith("PP") and pp:
                        ch[-1] = "I-PNP"
                    if not ch[2].endswith("PP"):
                        ch[-1] = "I-PNP"
                        pp = False
    return chunked

def keyPressEvent(self, event):
        # pylint: disable=too-many-branches
        text, key = event.text(), event.key()
        alt = event.modifiers() & Qt.AltModifier
        shift = event.modifiers() & Qt.ShiftModifier
        ctrl = event.modifiers() & Qt.ControlModifier
        altgr = event.modifiers() and (key == Qt.Key_AltGr)
        # Needed to properly handle Neo2 and other keyboard layouts
        # See spyder-ide/spyder#11293
        neo2_level4 = (key == 0)  # AltGr (ISO_Level5_Shift) in Neo2 on Linux
        modifier = shift or ctrl or alt or altgr or neo2_level4
        if key in (Qt.Key_Return, Qt.Key_Enter, Qt.Key_Tab):
            # Check that what was selected can be selected,
            # otherwise timing issues
            item = self.currentItem()
            if item is None:
                item = self.item(0)

            if self.is_up_to_date(item=item):
                self.item_selected(item=item)
            else:
                self.hide()
                self.textedit.keyPressEvent(event)
        elif key == Qt.Key_Escape:
            self.hide()
        elif key in (Qt.Key_Left, Qt.Key_Right) or text in ('.', ':'):
            self.hide()
            self.textedit.keyPressEvent(event)
        elif key in (Qt.Key_Up, Qt.Key_Down, Qt.Key_PageUp, Qt.Key_PageDown,
                     Qt.Key_Home, Qt.Key_End) and not modifier:
            if key == Qt.Key_Up and self.currentRow() == 0:
                self.setCurrentRow(self.count() - 1)
            elif key == Qt.Key_Down and self.currentRow() == self.count() - 1:
                self.setCurrentRow(0)
            else:
                QListWidget.keyPressEvent(self, event)
        elif len(text) > 0 or key == Qt.Key_Backspace:
            self.textedit.keyPressEvent(event)
            self.update_current()
        elif modifier:
            self.textedit.keyPressEvent(event)
        else:
            self.hide()
            QListWidget.keyPressEvent(self, event)

def interpolate(input, size=None, scale_factor=None, mode="nearest", align_corners=None):
    if input.numel() > 0:
        return torch.nn.functional.interpolate(
            input, size, scale_factor, mode, align_corners=align_corners
        )

    def _check_size_scale_factor(dim):
        if size is None and scale_factor is None:
            raise ValueError("either size or scale_factor should be defined")
        if size is not None and scale_factor is not None:
            raise ValueError("only one of size or scale_factor should be defined")
        if (scale_factor is not None and isinstance(scale_factor, tuple) and len(scale_factor) != dim):
            raise ValueError(
                "scale_factor shape must match input shape. "
                "Input is {}D, scale_factor size is {}".format(dim, len(scale_factor))
            )

    def _output_size(dim):
        _check_size_scale_factor(dim)
        if size is not None:
            return size
        scale_factors = _ntuple(dim)(scale_factor)
        # math.floor might return float in py2.7
        return [int(math.floor(input.size(i + 2) * scale_factors[i])) for i in range(dim)]

    output_shape = tuple(_output_size(2))
    output_shape = input.shape[:-2] + output_shape
    return _NewEmptyTensorOp.apply(input, output_shape)

def action_stats(env, md_action, cont_action):
    if cont_action:
        action_dim = 1
        action_ids = None
        n_actions_per_dim = [np.inf]

        if md_action:
            action_dim = env.action_space.shape[0]
            n_actions_per_dim = [np.inf for _ in range(action_dim)]
    else:
        if md_action:
            n_actions_per_dim = [
                space.n if hasattr(space, "n") else np.inf
                for space in env.action_space.spaces
            ]
            action_ids = (
                None
                if np.inf in n_actions_per_dim
                else list(product(*[range(i) for i in n_actions_per_dim]))
            )
            action_dim = len(n_actions_per_dim)
        else:
            action_dim = 1
            n_actions_per_dim = [env.action_space.n]
            action_ids = list(range(n_actions_per_dim[0]))
    return n_actions_per_dim, action_ids, action_dim

def convert_Panel_to_Series(obj, store=None, return_to_mtype=False):
    if isinstance(obj, list):
        if len(obj) == 1:
            if return_to_mtype:
                return obj[0], "pd.DataFrame"
            else:
                return obj[0]
        else:
            raise ValueError("obj must be of length 1")

    if isinstance(obj, pd.DataFrame):
        obj.index = obj.index.droplevel(level=0)
        obj_mtype = "pd.DataFrame"

    if isinstance(obj, np.ndarray):
        if obj.ndim != 3 or obj.shape[0] != 1:
            raise ValueError("if obj is np.ndarray, must be of dim 3, with shape[0]=1")
        # from numpy3D to numpy2D
        # numpy2D = (time, variables)
        # numpy3D = (instances, variables, time)
        obj = np.reshape(obj, (obj.shape[1], obj.shape[2]))
        obj = np.swapaxes(obj, 0, 1)
        obj_mtype = "np.ndarray"

    if return_to_mtype:
        return obj, obj_mtype
    else:
        return obj

def train(
        self, tasks: list, train_func: Optional[Callable] = None, experiment_name: Optional[str] = None, **kwargs
    ) -> List[Recorder]:
        if isinstance(tasks, dict):
            tasks = [tasks]
        if len(tasks) == 0:
            return []
        if train_func is None:
            train_func = self.train_func
        if experiment_name is None:
            experiment_name = self.experiment_name
        recs = []
        for task in tqdm(tasks, desc="train tasks"):
            if self._call_in_subproc:
                get_module_logger("TrainerR").info("running models in sub process (for forcing release memroy).")
                train_func = call_in_subproc(train_func, C)
            rec = train_func(task, experiment_name, recorder_name=self.default_rec_name, **kwargs)
            rec.set_tags(**{self.STATUS_KEY: self.STATUS_BEGIN})
            recs.append(rec)
        return recs

def parse(self, datestr):
        if datestr in MISSING_VALUES:
            return Unknown

        datestr = datestr.strip().rstrip('Z')
        datestr = self._tzre_sub(datestr)

        if not self._matches_iso_format(datestr):
            try:
                # If it is a number, assume it is a unix timestamp
                value = float(datestr)
                self.have_date = self.have_time = 1
                return value
            except ValueError:
                raise self.InvalidDateTimeFormatError(datestr)

        try_order = self.__ISO_FORMATS_PROBE_SEQ
        for i, (have_date, have_time, fmt) in enumerate(
                map(self._ISO_FORMATS.__getitem__, try_order)):
            try:
                dt = datetime.strptime(datestr, fmt)
            except ValueError:
                continue
            else:
                # Pop this most-recently-used format index to front,
                # excluding last 2
                if 0 < i < len(try_order) - 2:
                    try_order = try_order.copy()
                    try_order[i], try_order[0] = try_order[0], try_order[i]
                    TimeVariable.__ISO_FORMATS_PROBE_SEQ = try_order
                self.have_date |= have_date
                self.have_time |= have_time
                if not have_date:
                    dt = dt.replace(self.UNIX_EPOCH.year,
                                    self.UNIX_EPOCH.month,
                                    self.UNIX_EPOCH.day)
                break
        else:
            raise self.InvalidDateTimeFormatError(datestr)

        offset = dt.utcoffset()
        self.timezone = timezone(offset) if offset is not None else None

        # Convert time to UTC timezone. In dates without timezone,
        # localtime is assumed. See also:
        # https://docs.python.org/3.4/library/datetime.html#datetime.datetime.timestamp
        if dt.tzinfo:
            dt -= dt.utcoffset()
        dt = dt.replace(tzinfo=timezone.utc)

        # Unix epoch is the origin, older dates are negative
        try:
            return dt.timestamp()
        except OverflowError:
            return -(self.UNIX_EPOCH - dt).total_seconds()

def has_file(
    path_or_repo: Union[str, os.PathLike],
    filename: str,
    revision: Optional[str] = None,
    proxies: Optional[Dict[str, str]] = None,
    use_auth_token: Optional[Union[bool, str]] = None,
):
    if os.path.isdir(path_or_repo):
        return os.path.isfile(os.path.join(path_or_repo, filename))

    url = hf_hub_url(path_or_repo, filename=filename, revision=revision)

    headers = {"user-agent": http_user_agent()}
    if isinstance(use_auth_token, str):
        headers["authorization"] = f"Bearer {use_auth_token}"
    elif use_auth_token:
        token = HfFolder.get_token()
        if token is None:
            raise EnvironmentError("You specified use_auth_token=True, but a huggingface token was not found.")
        headers["authorization"] = f"Bearer {token}"

    r = requests.head(url, headers=headers, allow_redirects=False, proxies=proxies, timeout=10)
    try:
        hf_raise_for_status(r)
        return True
    except RepositoryNotFoundError as e:
        logger.error(e)
        raise EnvironmentError(f"{path_or_repo} is not a local folder or a valid repository name on 'https://hf.co'.")
    except RevisionNotFoundError as e:
        logger.error(e)
        raise EnvironmentError(
            f"{revision} is not a valid git identifier (branch name, tag name or commit id) that exists for this "
            f"model name. Check the model page at 'https://huggingface.co/{path_or_repo}' for available revisions."
        )
    except requests.HTTPError:
        # We return false for EntryNotFoundError (logical) as well as any connection error.
        return False

def init_lyrics_embedder_training(self):
        if not getattr(self.config, "lyrics_embedder_train", False):
            return
        modules_fn = getattr(self.model, "get_lyrics_embedder_modules", None)
        if not callable(modules_fn):
            logger.warning("lyrics_embedder_train enabled, but model does not expose lyrics embedder modules.")
            return

        modules = modules_fn(unwrap=False) or []
        if not modules:
            logger.warning("lyrics_embedder_train enabled, but no lyrics embedder modules were found to unfreeze.")
            return

        enabled = []
        enable_fn = getattr(self.model, "enable_lyrics_embedder_training", None)
        if callable(enable_fn):
            enabled = enable_fn() or []
        else:
            for name, module in modules:
                if module is None:
                    continue
                module.requires_grad_(True)
                module.train()
                enabled.append(name)

        if enabled:
            logger.info("Enabled training for lyrics embedder modules: %s", ", ".join(enabled))

def compose_bmm(
    module: torch.fx.GraphModule,
) -> torch.fx.GraphModule:
    modified = False
    for n in module.graph.nodes:
        if n.op == "call_function" and n.target in (torch.ops.aten.bmm.default,):
            modified = True
            node = n
            input_n = node.all_input_nodes[0]
            other_n = node.all_input_nodes[1]
            output = next(iter(node.users))
            input_input_n = input_n.all_input_nodes[0]
            if (
                input_input_n.target != torch.ops.aten.expand.default
                and input_n.target != torch.ops.aten.view.default
            ):
                raise RuntimeError(
                    "Bmm is addressed in fixed pattern. A new pattern is met!"
                )
            real_input = input_input_n.all_input_nodes[0]
            input_other_n = other_n.all_input_nodes[0]
            if (
                input_other_n.target != torch.ops.aten.expand.default
                and other_n.target != torch.ops.aten.view.default
            ):
                raise RuntimeError(
                    "Bmm is addressed in fixed pattern. A new pattern is met!"
                )
            real_other = input_other_n.all_input_nodes[0]
            if len(real_other.meta["val"].size()) == 2:
                new_func = aten_compose_bmm_2d
            if len(real_other.meta["val"].size()) == 3:
                new_func = aten_compose_bmm_3d

            with module.graph.inserting_after(node):
                new_args = (real_input, real_other)
                new_node = module.graph.create_node(
                    "call_function",
                    new_func,
                    args=new_args,
                    kwargs=None,
                )
            output.replace_all_uses_with(new_node)

    module.graph.eliminate_dead_code()
    module.recompile()
    return PassResult(module, modified)

def from_dict(cls, obj: dict) -> DetectionTaskInformation:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return DetectionTaskInformation.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in DetectionTaskInformation) in the input: " + str(obj))

        _obj = DetectionTaskInformation.parse_obj({
            "bbox_examples": [DetectionFramePrediction.from_dict(_item) for _item in obj.get("bboxExamples")] if obj.get("bboxExamples") is not None else None,
            "crop_embedding_information": EmbeddingInformation.from_dict(obj.get("cropEmbeddingInformation")) if obj.get("cropEmbeddingInformation") is not None else None
        })
        return _obj

def convert_object_to_struct(obj, serialized_names: Mapping[str, str] = {}):
    signature = inspect.signature(obj.__init__)  #Needed for default values
    result = {}
    for python_name in signature.parameters:  #TODO: Make it possible to specify the field ordering regardless of the presence of default values
        value = getattr(obj, python_name)
        if python_name.startswith('_'):
            continue
        attr_name = serialized_names.get(python_name, python_name)
        if hasattr(value, 'to_dict'):
            result[attr_name] = value.to_dict()
        elif isinstance(value, list):
            result[attr_name] = [
                (x.to_dict() if hasattr(x, 'to_dict') else x) for x in value
            ]
        elif isinstance(value, dict):
            result[attr_name] = {
                k: (v.to_dict() if hasattr(v, 'to_dict') else v)
                for k, v in value.items()
            }
        else:
            param = signature.parameters.get(python_name, None)
            if param is None or param.default == inspect.Parameter.empty or value != param.default:
                result[attr_name] = value

    return result

def serialize_kubernetes_node_info(return_value: Dict[str, Any]) -> str:
    remote_api_version = versions.get_remote_api_version()
    if (return_value and remote_api_version is not None):
        for node_info in return_value.get('node_info_dict', {}).values():
            if remote_api_version < 25:
                # Remove is_ready field for old clients that don't recognize it
                node_info.pop('is_ready', None)
            if remote_api_version < 26:
                # Remove cpu_count, memory_gb, cpu_free, and
                # memory_free_gb fields for old clients that don't
                # recognize them
                node_info.pop('cpu_count', None)
                node_info.pop('memory_gb', None)
                node_info.pop('cpu_free', None)
                node_info.pop('memory_free_gb', None)
            if remote_api_version < 28:
                # Remove is_cordoned and taints fields for old clients that
                # don't recognize them
                node_info.pop('is_cordoned', None)
                node_info.pop('taints', None)
    return orjson.dumps(return_value).decode('utf-8')

def emit_call(
        self,
        name: str,
        args: list[tvm.runtime.Tensor | tvm.DataType] | None = None,
        dst: int | None = None,
    ) -> None:
        self._check_scope()
        if dst is None:
            dst = SpecialReg.VOID_ARG
        args_ = []
        if args is not None:
            for arg in args:
                if isinstance(arg, tuple):
                    shape_tuple = ShapeTuple(arg)
                    new_arg = self.convert_constant(shape_tuple)
                    args_.append(new_arg)
                elif isinstance(arg, tvm.runtime.Tensor | tvm.DataType | ShapeTuple):
                    new_arg = self.convert_constant(arg)
                    args_.append(new_arg)
                else:
                    args_.append(arg)
        _ffi_api.ExecBuilderEmitCall(self, name, args_, dst)  # type: ignore

def gen_batches(self, batch_size: int, shuffle: bool = None) \
            -> Generator[Tuple[List[str], List[int]], Any, None]:
        if shuffle is None:
            shuffle = self.shuffle

        if shuffle:
            _doc_ids = self.random.sample(self.doc_ids, len(self.doc_ids))
        else:
            _doc_ids = self.doc_ids

        if batch_size > 0:
            batches = [_doc_ids[i:i + batch_size] for i in
                       range(0, len(_doc_ids), batch_size)]
        else:
            batches = [_doc_ids]

        for i, doc_ids in enumerate(batches):
            docs = [self.get_doc_content(doc_id) for doc_id in doc_ids]
            doc_nums = [self.doc2index[doc_id] for doc_id in doc_ids]
            yield docs, zip(doc_ids, doc_nums)

def violin(coeffs, n_inputs, ax, colour_dict=None, show_freqs=True):
    coeffs = _validate_coefficients(coeffs, n_inputs, True)

    # Check axis shape
    if ax.size != 2:
        raise ValueError("Matplotlib axis should consist of two subplots.")

    if colour_dict is None:
        colour_dict = {"real": "purple", "imag": "green"}

    # Get the labels and data
    nvecs_formatted, data = _extract_data_and_labels(coeffs)

    for data_type, axis in zip(["real", "imag"], ax):
        violinplt = axis.violinplot(data[data_type], showextrema=False)
        for bd in violinplt["bodies"]:
            bd.set_color(colour_dict[data_type])
            bd.set_alpha(0.7)
        axis.set_ylabel(data_type)
        axis.xaxis.set_ticks(np.arange(1, len(data[data_type][0]) + 1))
        _adjust_spine_placement(axis)

    # Format axes
    ax[0].tick_params(axis="x", colors="white")  # hack to get rid of ticks but keep grid

    if show_freqs:
