        ax[1].xaxis.set_ticklabels(nvecs_formatted, fontsize=10, color="grey")
        ax[1].xaxis.set_ticks_position("top")
    else:
        ax[1].tick_params(axis="x", colors="white")  # hack to get rid of ticks but keep grid

    return ax

def make_monotonic(self):
        for cost_dict in [
                self.all_gather_cost_dict, self.all_reduce_cost_dict,
                self.all_to_all_cost_dict, self.reduce_scatter_cost_dict,
                self.dot_cost_dict
        ]:
            new_cost_dict = {}

            for key, value in cost_dict.items():
                sizes = np.array([x[0] for x in value])
                times = np.array([x[1] for x in value])

                # make bandwidth monotonically increasing
                bandwidth = sizes / times
                for i in range(1, len(bandwidth)):
                    bandwidth[i] = max(bandwidth[i], bandwidth[i - 1])

                new_times = np.empty_like(times)
                for i in range(len(times)):
                    if sizes[i] == 0 or bandwidth[i] == 0:
                        new_times[i] = value[i][1]
                    else:
                        new_times[i] = sizes[i] / bandwidth[i]

                new_value = [
                    (value[i][0], new_times[i]) for i in range(len(value))
                ]
                new_cost_dict[key] = new_value

            cost_dict.update(new_cost_dict)

def open_report(fname, **params):
    fname = str(_check_fname(fname=fname, overwrite="read", must_exist=False))
    if op.exists(fname):
        # Check **params with the loaded report
        read_hdf5, _ = _import_h5io_funcs()
        state = read_hdf5(fname, title="mnepython")
        for param, default in _backward_compat_map.items():
            state.setdefault(param, default)
        for param in params:
            if param not in state:
                raise ValueError(f"The loaded report has no attribute {param}")
            if params[param] != state[param]:
                raise ValueError(
                    f"Attribute '{param}' of loaded report ({params[param]}) does not "
                    f"match the given parameter ({state[param]})."
                )
        report = Report()
        report.__setstate__(state)
    else:
        report = Report(**params)
    # Keep track of the filename in case the Report object is used as a context
    # manager.
    report.fname = fname
    return report

def pack_trackingnet_results(tracker_name, param_name, run_id=None, output_name=None):
    if output_name is None:
        if run_id is None:
            output_name = '{}_{}'.format(tracker_name, param_name)
        else:
            output_name = '{}_{}_{:03d}'.format(tracker_name, param_name, run_id)

    output_path = os.path.join(env_settings().tn_packed_results_path, output_name)

    if not os.path.exists(output_path):
        os.makedirs(output_path)

    results_path = env_settings().results_path

    tn_dataset = get_dataset('trackingnet')

    for seq in tn_dataset:
        seq_name = seq.name

        if run_id is None:
            seq_results_path = '{}/{}/{}/{}.txt'.format(results_path, tracker_name, param_name, seq_name)
        else:
            seq_results_path = '{}/{}/{}_{:03d}/{}.txt'.format(results_path, tracker_name, param_name, run_id, seq_name)

        results = np.loadtxt(seq_results_path, dtype=np.float64)

        np.savetxt('{}/{}.txt'.format(output_path, seq_name), results, delimiter=',', fmt='%.2f')

    # Generate ZIP file
    shutil.make_archive(output_path, 'zip', output_path)

    # Remove raw text files
    shutil.rmtree(output_path)

def get_rotation_matrix2d(center: torch.Tensor, angle: torch.Tensor, scale: torch.Tensor) -> torch.Tensor:
    if not isinstance(center, torch.Tensor):
        raise TypeError(f"Input center type is not a torch.Tensor. Got {type(center)}")

    if not isinstance(angle, torch.Tensor):
        raise TypeError(f"Input angle type is not a torch.Tensor. Got {type(angle)}")

    if not isinstance(scale, torch.Tensor):
        raise TypeError(f"Input scale type is not a torch.Tensor. Got {type(scale)}")

    if not (len(center.shape) == 2 and center.shape[1] == 2):
        raise ValueError(f"Input center must be a Bx2 torch.Tensor. Got {center.shape}")

    if not len(angle.shape) == 1:
        raise ValueError(f"Input angle must be a B torch.Tensor. Got {angle.shape}")

    if not (len(scale.shape) == 2 and scale.shape[1] == 2):
        raise ValueError(f"Input scale must be a Bx2 torch.Tensor. Got {scale.shape}")

    if not (center.shape[0] == angle.shape[0] == scale.shape[0]):
        raise ValueError(
            f"Inputs must have same batch size dimension. Got center {center.shape}, angle {angle.shape} and scale "
            f"{scale.shape}"
        )

    if not (center.device == angle.device == scale.device) or not (center.dtype == angle.dtype == scale.dtype):
        raise ValueError(
            f"Inputs must have same device Got center ({center.device}, {center.dtype}), angle ({angle.device}, "
            f"{angle.dtype}) and scale ({scale.device}, {scale.dtype})"
        )

    shift_m = eye_like(3, center)
    shift_m[:, :2, 2] = center

    shift_m_inv = eye_like(3, center)
    shift_m_inv[:, :2, 2] = -center

    scale_m = eye_like(3, center)
    scale_m[:, 0, 0] *= scale[:, 0]
    scale_m[:, 1, 1] *= scale[:, 1]

    rotat_m = eye_like(3, center)
    rotat_m[:, :2, :2] = angle_to_rotation_matrix(angle)

    affine_m = shift_m @ rotat_m @ scale_m @ shift_m_inv
    return affine_m[:, :2, :]  # Bx2x3

def update_version(version, use_file_if_exists=True, create_file=False):
    try:
        if not os.getenv("RELEASE"):
            from datetime import date

            minor_version_file_path = os.path.join(AUTOGLUON_ROOT_PATH, "VERSION.minor")
            if use_file_if_exists and os.path.isfile(minor_version_file_path):
                with open(minor_version_file_path) as f:
                    day = f.read().strip()
            else:
                today = date.today()
                day = today.strftime("b%Y%m%d")
            version += day
    except Exception:
        pass
    if create_file and not os.getenv("RELEASE"):
        with open(os.path.join(AUTOGLUON_ROOT_PATH, "VERSION.minor"), "w") as f:
            f.write(day)
    return version

def load_app(  # pylint: disable= too-many-branches
    module_attribute_str: str,
    error_type: type[Exception],
    project_dir: str | Path | None = None,
) -> Any:
    with _import_lock:
        valid, error_msg = validate(module_attribute_str, check_module=False)
        if not valid and error_msg:
            raise error_type(error_msg) from None

        module_str, _, attributes_str = module_attribute_str.partition(":")

        try:
            # Initialize project path
            if project_dir is None:
                project_dir = Path.cwd()
            project_dir = Path(project_dir).absolute()

            # Unload modules if the project directory has changed
            if _current_sys_path and _current_sys_path != str(project_dir):
                _unload_modules(Path(_current_sys_path))

            # Set the system path
            _set_sys_path(project_dir)

            # Import the module
            if module_str not in sys.modules:
                module = importlib.import_module(module_str)
            else:
                module = sys.modules[module_str]

        except ModuleNotFoundError as err:
            raise error_type(
                f"Unable to load module {module_str}{OBJECT_REF_HELP_STR}",
            ) from err

        # Recursively load attribute
        attribute = module
        try:
            for attribute_str in attributes_str.split("."):
                attribute = getattr(attribute, attribute_str)
        except AttributeError as err:
            raise error_type(
                f"Unable to load attribute {attributes_str} from module {module_str}"
                f"{OBJECT_REF_HELP_STR}",
            ) from err

        return attribute

def ucd_find(self, ucds, exclude=[]):
        if isinstance(ucds, six.string_types):
            ucds = [ucds]
        if len(ucds) == 1:
            ucd = ucds[0]
            if ucd[0] == "^":  # we want it to start with
                ucd = ucd[1:]
                columns = [name for name in self.get_column_names() if self.ucds.get(name, "").startswith(ucd) and name not in exclude]
            else:
                columns = [name for name in self.get_column_names() if ucd in self.ucds.get(name, "") and name not in exclude]
            return None if len(columns) == 0 else columns[0]
        else:
            columns = [self.ucd_find([ucd], exclude=exclude) for ucd in ucds]
            return None if None in columns else columns

def upload_file_with_signed_url(
        self,
        file: Union[IOBase, None],
        signed_write_url: str,
        headers: Optional[Dict] = None,
        session: Optional[requests.Session] = None,
    ) -> Response:

        # check to see if server side encryption for S3 is desired
        # see https://docs.aws.amazon.com/AmazonS3/latest/userguide/UsingServerSideEncryption.html
        # see https://docs.aws.amazon.com/AmazonS3/latest/userguide/UsingKMSEncryption.html
        lightly_s3_sse_kms_key = os.environ.get(LIGHTLY_S3_SSE_KMS_KEY, "").strip()
        # Only set s3 related headers when we are talking with s3
        if (
            utils.get_signed_url_destination(signed_write_url) == DatasourceType.S3
            and lightly_s3_sse_kms_key
        ):
            if headers is None:
                headers = {}
            # don't override previously set SSE
            if "x-amz-server-side-encryption" not in headers:
                if lightly_s3_sse_kms_key.lower() == "true":
                    # enable SSE with the key of amazon
                    headers["x-amz-server-side-encryption"] = "AES256"
                else:
                    # enable SSE with specific customer KMS key
                    headers["x-amz-server-side-encryption"] = "aws:kms"
                    headers[
                        "x-amz-server-side-encryption-aws-kms-key-id"
                    ] = lightly_s3_sse_kms_key

        # start requests session and make put request
        sess = session or requests
        if headers is not None:
            response = sess.put(signed_write_url, data=file, headers=headers)
        else:
            response = sess.put(signed_write_url, data=file)
        response.raise_for_status()
        return response

def custom_vjp(f, f_fwd, f_bwd, nondiff_argnums=()):
  # Call backend custom_vjp if it exists.
  # TODO(lukaszkaiser): unify the APIs and remove nondiff_argnums altogether.
  if 'custom_vjp' in backend():
    return backend()['custom_vjp'](f, f_fwd, f_bwd)

  # Check that nondiff_argnums is (0, 1, ..., N) for some N.
  # Currently we only support nondiff_argnums at the front.
  counter = -1
  for i in nondiff_argnums:
    counter += 1
    if i != counter:
      raise ValueError('Currently we only support custom_vjps with all nondiff'
                       '_argnums up front, like (0,) or (0, 1) but not (1,) or'
                       ' (1, 2). Found: %s' % str(nondiff_argnums))

  # Use custom_grad.
  if counter == -1:  # no non-diff args
    def f_vjp(*args):
      out, residual = f_fwd(*args)
      def vjpfn(g):
        return f_bwd(residual, g)
      return out, vjpfn
    return backend()['custom_grad'](f_vjp, f)

  # Handle non-diff args by closure.
  def f_joint(*args):
    """This function takes all args, first counter+1 are non-diff ones."""
    nondiff_args = list(args[:counter+1])
    def f_diff(*diff_args):  # Takes only diff args, will define custom grad.
      args = nondiff_args + list(diff_args)
      return f(*args)
    def f_vjp(*diff_args):  # Custom VJP for diff args.
      args = nondiff_args + list(diff_args)
      out, residual = f_fwd(*args)
      def vjpfn(g):
        bwd_args = [residual, g]
        res = f_bwd(*bwd_args)
        return res[counter+1:]
      return out, vjpfn
    # This is the function taking only diff args with custom vjp.
    f_diff_vjp = backend()['custom_grad'](f_vjp, f_diff)
    # Call it on the diff args.
    return f_diff_vjp(*args[counter+1:])
  return f_joint

def determine_text_prefix(request_level_prefix: str, marqo_index: MarqoIndex, prefix_type: DeterminePrefixContentType) -> str:
    if request_level_prefix is not None:
        return request_level_prefix


    # Check for the presence of the textChunkPrefix or textQueryPrefix in the MarqoIndex object.
    if prefix_type == DeterminePrefixContentType.TextQuery and marqo_index.override_text_query_prefix is not None:
        return marqo_index.override_text_query_prefix
    elif prefix_type == DeterminePrefixContentType.TextChunk and marqo_index.override_text_chunk_prefix is not None:
        return marqo_index.override_text_chunk_prefix

    # Fallback to model_properties defined prefix
    try:
        model_properties = marqo_index.model.properties if marqo_index.model is not None else None
        if model_properties is None and marqo_index.model is not None:
            model_properties = get_model_properties_from_registry(marqo_index.model.name)

        if model_properties is not None:
            default_prefix = model_properties.get(prefix_type.value)
            return default_prefix if default_prefix is not None else ""
        else:
            raise ValueError(f"Model properties not found for model: {marqo_index.model.name}")
    except InvalidModelPropertiesError as e:
        raise e

    # If no prefix is found, return empty string ""
    return ""

def forward(self, query: str, top_k: int | None = None) -> ToolOutput:
        try:
            # Use provided parameters or defaults
            top_k = top_k or self.max_results

            # Prepare request payload
            payload = {
                "query": query,
                "top_k": min(top_k, 50),  # Cap at 50 results
            }

            # Make request to retrieval server
            response = self.client.post(f"{self.server_url}/retrieve", json=payload)

            if not response.is_success:
                error_msg = f"Retrieval server error: {response.status_code}"
                if response.content:
                    try:
                        error_data = response.json()
                        error_msg += f" - {error_data.get('error', 'Unknown error')}"
                    except Exception:
                        error_msg += f" - {response.text}"

                return ToolOutput(name=self.name, error=error_msg)

            # Parse response
            response_data = response.json()
            results = response_data.get("results", [])

            if not results:
                return ToolOutput(name=self.name, output="No relevant documents found for the query.")

            # Format results
            formatted_output = self._format_search_results(results)

            # Create metadata for potential downstream use
            metadata = {"query": query, "num_results": len(results), "retriever_type": "dense", "server_url": self.server_url}

            return ToolOutput(name=self.name, output=formatted_output, metadata=metadata)

        except httpx.TimeoutException:
            return ToolOutput(name=self.name, error=f"Request timeout after {self.timeout} seconds. Please check if the retrieval server is running.")
        except httpx.ConnectError:
            return ToolOutput(name=self.name, error=f"Could not connect to retrieval server at {self.server_url}. Please ensure the server is running.")
        except Exception as e:
            return ToolOutput(name=self.name, error=f"Unexpected error: {str(e)}")

def treebank_to_short_name(treebank):
    if treebank in treebank_special_cases:
        return treebank_special_cases.get(treebank)
    if SHORTNAME_RE.match(treebank):
        lang, corpus = treebank.split("_", 1)
        lang = lang_to_langcode(lang)
        return lang + "_" + corpus

    if treebank.startswith('UD_'):
        treebank = treebank[3:]
    # special case starting with zh in case the input is an already-converted ZH treebank
    if treebank.startswith("zh-hans") or treebank.startswith("zh-hant"):
        splits = (treebank[:len("zh-hans")], treebank[len("zh-hans")+1:])
    else:
        splits = treebank.split('-')
        if len(splits) == 1:
            splits = treebank.split("_", 1)
    assert len(splits) == 2, "Unable to process %s" % treebank
    lang, corpus = splits

    lcode = lang_to_langcode(lang)

    short = "{}_{}".format(lcode, corpus.lower())
    return short

def oneHotVector(self, domain, num):
        vector = [0, 0, 0, 0]
        if num == '':
            return vector
        if domain != 'train':
            if num == 0:
                vector = [1, 0, 0, 0]
            elif num == 1:
                vector = [0, 1, 0, 0]
            elif num <= 3:
                vector = [0, 0, 1, 0]
            else:
                vector = [0, 0, 0, 1]
        else:
            if num == 0:
                vector = [1, 0, 0, 0]
            elif num <= 5:
                vector = [0, 1, 0, 0]
            elif num <= 10:
                vector = [0, 0, 1, 0]
            else:
                vector = [0, 0, 0, 1]
        return vector

def moveto(self, x, y, anchor="NW"):
        x1, y1, x2, y2 = self.bbox()
        if anchor == "NW":
            self.move(x - x1, y - y1)
        if anchor == "N":
            self.move(x - x1 / 2 - x2 / 2, y - y1)
        if anchor == "NE":
            self.move(x - x2, y - y1)
        if anchor == "E":
            self.move(x - x2, y - y1 / 2 - y2 / 2)
        if anchor == "SE":
            self.move(x - x2, y - y2)
        if anchor == "S":
            self.move(x - x1 / 2 - x2 / 2, y - y2)
        if anchor == "SW":
            self.move(x - x1, y - y2)
        if anchor == "W":
            self.move(x - x1, y - y1 / 2 - y2 / 2)

def guide_generic(config):
    N_state = config["sizes"]["state"]

    if config["group"]["random"] == "continuous":
        loc_g = pyro.param("loc_group", lambda: torch.zeros((N_state**2,)))
        scale_g = pyro.param(
            "scale_group",
            lambda: torch.ones((N_state**2,)),
            constraint=constraints.positive,
        )

    # initialize individual-level random effect parameters
    N_c = config["sizes"]["group"]
    if config["individual"]["random"] == "continuous":
        loc_i = pyro.param(
            "loc_individual",
            lambda: torch.zeros(
                (
                    N_c,
                    N_state**2,
                )
            ),
        )
        scale_i = pyro.param(
            "scale_individual",
            lambda: torch.ones(
                (
                    N_c,
                    N_state**2,
                )
            ),
            constraint=constraints.positive,
        )

    N_c = config["sizes"]["group"]
    with pyro.plate("group", N_c, dim=-1):
        if config["group"]["random"] == "continuous":
            pyro.sample(
                "eps_g",
                dist.Normal(loc_g, scale_g).to_event(1),
            )  # infer={"num_samples": 10})

        N_s = config["sizes"]["individual"]
        with pyro.plate("individual", N_s, dim=-2), poutine.mask(
            mask=config["individual"]["mask"]
        ):
            # individual-level random effects
            if config["individual"]["random"] == "continuous":
                pyro.sample(
                    "eps_i",
                    dist.Normal(loc_i, scale_i).to_event(1),
                )  # infer={"num_samples": 10})

def fix_multiple_open_shift(gold_transition, pred_transition, gold_sequence, gold_index, root_labels, model, state):
    if not isinstance(pred_transition, Shift):
        return None

    if not isinstance(gold_transition, OpenConstituent):
        return None

    shift_index = gold_index
    while shift_index < len(gold_sequence) and isinstance(gold_sequence[shift_index], OpenConstituent):
        shift_index += 1
    if shift_index >= len(gold_sequence):
        raise AssertionError("Found a sequence of OpenConstituent at the end of a TOP_DOWN sequence!")
    if not isinstance(gold_sequence[shift_index], Shift):
        raise AssertionError("Expected to find a Shift after a sequence of OpenConstituent.  There should not be a %s" % gold_sequence[shift_index])

    #print("Input sequence: %s\nIndex %d\nGold %s Pred %s" % (gold_sequence, gold_index, gold_transition, pred_transition))
    updated_sequence = gold_sequence
    while shift_index > gold_index:
        close_index = advance_past_constituents(updated_sequence, shift_index)
        if close_index is None:
            raise AssertionError("Did not find a corresponding Close for this Open")
        # cut out the corresponding open and close
        updated_sequence = updated_sequence[:shift_index-1] + updated_sequence[shift_index:close_index] + updated_sequence[close_index+1:]
        shift_index -= 1
        #print("  %s" % updated_sequence)

    #print("Final updated sequence: %s" % updated_sequence)
    return updated_sequence

def sanitize_optimizer_block(config_section: Any) -> Tuple[Any, Optional[str]]:
    if not isinstance(config_section, dict):
        return config_section, None
    if "deepspeed_config_file" in config_section:
        return config_section, None

    fallback_source: Optional[str] = None
    optimizer_block = config_section.get("optimizer")
    if isinstance(optimizer_block, dict):
        normalized_name, fallback_source = normalize_optimizer_name(
            optimizer_block.get("type") or optimizer_block.get("name")
        )
        if normalized_name:
            optimizer_block["type"] = normalized_name
            optimizer_block.pop("name", None)
    elif isinstance(optimizer_block, str):
        normalized_name, fallback_source = normalize_optimizer_name(optimizer_block)
        if normalized_name:
            config_section["optimizer"] = {"type": normalized_name}
    return config_section, fallback_source

def check_shuffle_features_no_impact(model, dataset):
    from river import base
    from river.active.base import ActiveLearningClassifier
    from river.anomaly.base import AnomalyDetector

    params = seed_params(model._get_params(), seed=42)
    model = model.clone(params)
    shuffled = copy.deepcopy(model)

    for x, y in dataset:
        # Shuffle the features
        features = list(x.keys())
        random.shuffle(features)
        x_shuffled = {i: x[i] for i in features}

        assert x == x_shuffled  # order doesn't matter for dicts

        if isinstance(model, base.Classifier):
            try:
                y_pred = model.predict_proba_one(x)
                y_pred_shuffled = shuffled.predict_proba_one(x_shuffled)
            except NotImplementedError:
                y_pred = model.predict_one(x)
                y_pred_shuffled = shuffled.predict_one(x_shuffled)
        elif isinstance(model, AnomalyDetector):
            y_pred = model.score_one(x)
            y_pred_shuffled = shuffled.score_one(x_shuffled)
        else:
            y_pred = model.predict_one(x)
            y_pred_shuffled = shuffled.predict_one(x_shuffled)

        if isinstance(model, ActiveLearningClassifier):
            y_pred, _ = y_pred
            y_pred_shuffled, _ = y_pred_shuffled

        assert_predictions_are_close(y_pred, y_pred_shuffled)

        if isinstance(model, AnomalyDetector):
            model.learn_one(x)
            shuffled.learn_one(x_shuffled)
        else:
            model.learn_one(x, y)
            shuffled.learn_one(x_shuffled, y)

def example_generator(self, encoder, tmp_dir, task_id):
    filepaths = self.text_filepaths_for_task(tmp_dir, task_id)
    if task_id >= self.num_train_shards:
      # this is dev data - limit the total length.
      max_chars_per_file = self.max_dev_chars // (
          self.num_dev_shards * len(filepaths))
    else:
      max_chars_per_file = None
    tokens = []
    for ftext in self.file_generator(
        filepaths, max_chars_per_file=max_chars_per_file):
      tokens.extend(encoder.encode(ftext))
      pos = 0
      while pos + self.sequence_length <= len(tokens):
        yield {"targets": tokens[pos:pos + self.sequence_length]}
        pos += self.sequence_length
      if pos > 0:
        tokens = tokens[pos:]
    if self.remainder_policy == "pad":
      if tokens:
        targets = tokens + [0] * (self.sequence_length - len(tokens))
        yield {"targets": targets}
    else:
      assert self.remainder_policy == "drop"

def get_transform(self, img):
        # This should be an abstract method
        # But we provide an implementation that uses the old interface,
        # for backward compatibility
        log_once("The old augmentor interface was deprecated. "
                 "Please implement {} with `get_transform` instead!".format(self.__class__.__name__),
                 "warning")

        def legacy_augment_coords(self, coords, p):
            try:
                return self._augment_coords(coords, p)
            except AttributeError:
                pass
            try:
                return self.augment_coords(coords, p)
            except AttributeError:
                pass
            return coords  # this is the old default

        p = None  # the default return value for this method
        try:
            p = self._get_augment_params(img)
        except AttributeError:
            pass
        try:
            p = self.get_augment_params(img)
        except AttributeError:
            pass

        from .transform import BaseTransform, TransformFactory
        if isinstance(p, BaseTransform):  # some old augs return Transform already
            return p

        return TransformFactory(name="LegacyConversion -- " + str(self),
                                apply_image=lambda img: self._augment(img, p),
                                apply_coords=lambda coords: legacy_augment_coords(self, coords, p))

def parse_type_system_definition(parser):
    if not peek(parser, TokenKind.NAME):
        raise unexpected(parser)

    name = parser.token.value

    if name == 'schema':
        return parse_schema_definition(parser)

    elif name == 'scalar':
        return parse_scalar_type_definition(parser)

    elif name == 'type':
        return parse_object_type_definition(parser)

    elif name == 'interface':
        return parse_interface_type_definition(parser)

    elif name == 'union':
        return parse_union_type_definition(parser)

    elif name == 'enum':
        return parse_enum_type_definition(parser)

    elif name == 'input':
        return parse_input_object_type_definition(parser)

    elif name == 'extend':
        return parse_type_extension_definition(parser)

    elif name == 'directive':
        return parse_directive_definition(parser)

    raise unexpected(parser)

def emit_func_output(
        self,
        output: Expr | Tuple | list[Expr],
        params: Var | Tuple | list[Var] | None = None,
    ) -> GlobalVar:
        if self._func._is_emit_func_output_called:
            raise RuntimeError("emit_func_output must be called exactly once in a relax function.")
        self._func._is_emit_func_output_called = True

        if self._func._params is not None and params is not None:
            raise RuntimeError(
                "function parameters have been initialized in the function with scope."
            )

        if self._func._params is None and params is None:
            raise RuntimeError("Relax function must have parameter.")

        if self._func._params is None:
            self._func._params = params

        if BlockBuilder.current() is not self:
            raise RuntimeError("BlockBuilder.current() must be self.")

        output = self._normalize_python_tuple(output)

        block = self._end_block()
        if len(block.bindings) > 0:
            self._func._blocks.append(block)

        seqe = rx.SeqExpr(self._func._blocks, output)

        # If the parameters were not provided as part of
        # `bb.function()`, then any variables provided from the params
        # are not in scope.  Otherwise, TIR variables used in dynamic
        # inputs are removed as undefined (e.g. Replacing
        # `R.Tensor(["batch_size"])` with `R.Tensor(ndims=1)`).
        self.begin_scope(self._func._params)
        try:
            seqe = self.normalize(seqe)
        finally:
            self.end_scope()

        # do not specify ret_struct_info and let constructor deduce
        # from seqe.struct_info
        func = rx.Function(self._func._params, seqe, is_pure=self._func._is_pure)
        for key, value in self._func._attrs.items():
            func = func.with_attr(key, value)
        self.end_scope()
        return self.add_func(func, self._func._name)

def merge_custom_sections_with_field_sections(
        self, tab: str, field_sections: List[Dict[str, Any]]
    ) -> List[Dict[str, Any]]:
        custom_sections = self.get_custom_sections_for_tab(tab)

        # Create a map of field sections by ID for easy lookup
        field_section_map = {section["id"]: section for section in field_sections}

        # Merge all sections together
        merged_sections = []

        # Add custom sections
        for custom_section in custom_sections:
            merged_sections.append(custom_section)

        # Add field sections that aren't overridden by custom sections
        for field_section in field_sections:
            if field_section["id"] not in [cs["id"] for cs in custom_sections]:
                merged_sections.append(field_section)

        # Sort by order property (default to 100 for sections without order)
        merged_sections.sort(key=lambda s: s.get("order", 100))

        logger.debug(
            f"Merged sections for tab '{tab}': {len(merged_sections)} total "
            f"({len(custom_sections)} custom, {len(merged_sections) - len(custom_sections)} field-based)"
        )

        return merged_sections

def load_assistant_adapter(
    *,
    transformer,
    pipeline_cls,
    lora_path: str,
    adapter_name: str = "assistant",
    low_cpu_mem_usage: bool = False,
    weight_name: Optional[str] = None,
) -> bool:
    if not lora_path or transformer is None or pipeline_cls is None:
        return False

    lora_state_fn = getattr(pipeline_cls, "lora_state_dict", None)
    load_fn = getattr(pipeline_cls, "load_lora_into_transformer", None)
    if lora_state_fn is None or load_fn is None:
        return False

    state_kwargs = {}
    if "return_alphas" in inspect.signature(lora_state_fn).parameters:
        state_kwargs["return_alphas"] = True

    if weight_name is not None:
        state_kwargs["weight_name"] = weight_name

    lora_state = lora_state_fn(lora_path, **state_kwargs)
    network_alphas = None
    if isinstance(lora_state, tuple) and len(lora_state) == 2:
        state_dict, network_alphas = lora_state
    else:
        state_dict = lora_state
        network_alphas = None

    # Diffusers treats a non-None alpha map specially; only forward it when present.
    if not network_alphas:
        network_alphas = None
    load_kwargs = {
        "transformer": transformer,
        "adapter_name": adapter_name,
        "_pipeline": None,
        "network_alphas": network_alphas,
        "low_cpu_mem_usage": low_cpu_mem_usage,
    }
    _maybe_call_with_kwargs(load_fn, state_dict, **load_kwargs)
    freeze_adapter_parameters(transformer, adapter_name)
    return True

def prod(*ops, id=None, lazy=True):
    if len(ops) == 1:
        if isinstance(ops[0], qml.operation.Operator):
            return ops[0]

        fn = ops[0]

        if not callable(fn):
            raise TypeError(f"Unexpected argument of type {type(fn).__name__} passed to qml.prod")

        @wraps(fn)
        def wrapper(*args, **kwargs):

            # dequeue operators passed as arguments to the quantum function
            leaves, _ = qml.pytrees.flatten((args, kwargs), lambda obj: isinstance(obj, Operator))
            for l in leaves:
                if isinstance(l, Operator):
                    qml.QueuingManager.remove(l)

            qs = qml.tape.make_qscript(fn)(*args, **kwargs)
            if len(qs.operations) == 1:
                op = qs[0]
                if qml.QueuingManager.recording():
                    op = qml.apply(op)
                return op
            return prod(*qs.operations[::-1], id=id, lazy=lazy)

        return wrapper

    if lazy:
        return Prod(*ops, id=id)

    ops_simp = Prod(
        *itertools.chain.from_iterable([op if isinstance(op, Prod) else [op] for op in ops]),
        id=id,
    )

    for op in ops:
        QueuingManager.remove(op)

    return ops_simp

def move_to_device(obj: Union[torch.Tensor, nn.Module, Dict, List, Tuple], device: torch.device):
    if not isinstance(device, torch.device):
        raise ValueError(f"Invalid device: {device}. Ensure the device type is `torch.device`.")

    if torch.is_tensor(obj) or isinstance(obj, nn.Module):
        return obj.to(device)
    elif isinstance(obj, dict):
        res = {}
        for k, v in obj.items():
            res[k] = move_to_device(v, device)
        return res
    elif isinstance(obj, list) or isinstance(obj, tuple):
        res = []
        for v in obj:
            res.append(move_to_device(v, device))
        return res
    elif isinstance(obj, (int, float, str)):
        return obj
    else:
        raise TypeError(
            f"Invalid type {type(obj)} for move_to_device. "
            f"Make sure the object is one of these: a Pytorch tensor, a Pytorch module, "
            f"a dict or list of tensors or modules."
        )

def fontName(self, fontprop, subset=0):
        if isinstance(fontprop, FontPath):
            filenames = [fontprop]
        elif isinstance(fontprop, str):
            filenames = [FontPath(fontprop, 0)]
        elif mpl.rcParams['pdf.use14corefonts']:
            filenames = _fontManager._find_fonts_by_props(
                fontprop, fontext='afm', directory=RendererPdf._afm_font_dir
            )
        else:
            filenames = _fontManager._find_fonts_by_props(fontprop)
        first_Fx = None
        for fname in filenames:
            Fx = self._fontNames.get((fname, subset))
            if not first_Fx:
                first_Fx = Fx
            if Fx is None:
                Fx = next(self._internal_font_seq)
                self._fontNames[(fname, subset)] = Fx
                _log.debug('Assigning font %s (subset %d) = %r', Fx, subset, fname)
                if not first_Fx:
                    first_Fx = Fx

        # find_fontsprop's first value always adheres to
        # findfont's value, so technically no behaviour change
        return first_Fx

def find_filegroups(
    paths,
    substring="",
    extensions=None,
    validity_check=True,
    ignore_invisible=True,
    rstrip="",
    ignore_substring=None,
):
    n = len(paths)

    # must have same number of paths and extensions
    assert len(paths) >= 2
    if extensions:
        assert len(extensions) == n
    else:
        extensions = ["" for i in range(n)]

    base = find_files(
        path=paths[0],
        substring=substring,
        check_ext=extensions[0],
        ignore_invisible=ignore_invisible,
        ignore_substring=ignore_substring,
    )
    rest = [
        find_files(
            path=paths[i],
            substring=substring,
            check_ext=extensions[i],
            ignore_invisible=ignore_invisible,
            ignore_substring=ignore_substring,
        )
        for i in range(1, n)
    ]

    groups = {}
    for f in base:
        basename = os.path.splitext(os.path.basename(f))[0]
        basename = re.sub(r"\%s$" % rstrip, "", basename)
        groups[basename] = [f]

    # groups = {os.path.splitext(os.path.basename(f))[0].rstrip(rstrip):[f]
    #           for f in base}

    for idx, r in enumerate(rest):
        for f in r:
            basename, ext = os.path.splitext(os.path.basename(f))
            basename = re.sub(r"\%s$" % rstrip, "", basename)
            try:
                if extensions[idx + 1] == "" or ext == extensions[idx + 1]:
                    groups[basename].append(f)
            except KeyError:
                pass

    if validity_check:
        lens = [len(groups[k]) for k in groups.keys()]
        if len(set(lens)) > 1:
            raise ValueError(
                "Warning, some keys have more/less values than"
                " others. Set validity_check=False"
                " to ignore this warning."
            )

    return groups

def remove_files(
        self,
        dataset_path: Optional[str] = None,
        recursive: bool = True,
        verbose: bool = False,
    ) -> int:
        self._task.get_logger().report_text(
            "Removing files from dataset: {}".format(
                dict(dataset_path=dataset_path, recursive=recursive, verbose=verbose)
            ),
            print_console=False,
        )

        if dataset_path and dataset_path.startswith("/"):
            dataset_path = dataset_path[1:]

        org_files = list(self._dataset_file_entries.keys()) + list(self._dataset_link_entries.keys())

        self._dataset_file_entries = {
            k: v
            for k, v in self._dataset_file_entries.items()
            if not matches_any_wildcard(k, dataset_path, recursive=recursive)
        }
        self._dataset_link_entries = {
            k: v
            for k, v in self._dataset_link_entries.items()
            if not matches_any_wildcard(k, dataset_path, recursive=recursive)
            and not (matches_any_wildcard(v.link, dataset_path, recursive=recursive) or v.link == dataset_path)
        }

        removed = 0
        for f in org_files:
            if f not in self._dataset_file_entries and f not in self._dataset_link_entries:
                if verbose:
                    self._task.get_logger().report_text("Remove {}".format(f))
                removed += 1

        # update the task script
        self._add_script_call("remove_files", dataset_path=dataset_path, recursive=recursive)
        self._serialize()
        # Update state
        self.update_changed_files(num_files_removed=removed)
        return removed

def compute_matrix(phi: TensorLike, dimension: tuple[int, int]) -> TensorLike:
        d, t = dimension

        if (
            math.get_interface(phi) == "tensorflow"
        ):  # pragma: no cover (TensorFlow tests were disabled during deprecation)
            p = math.exp(1j * math.cast_like(phi, 1j))
            minus_p = math.exp(-1j * math.cast_like(phi, 1j))
            zeros = math.zeros_like(p)

            columns = []
            for i in range(t):
                columns.append(
                    [p if j == i else zeros for j in range(t)]
                    if i < d
                    else [minus_p if j == i else zeros for j in range(t)]
                )
            r = math.stack(columns, like="tensorflow", axis=-2)
            return r

        arg = 1j * phi
        prefactors = math.array([1] * d + [-1] * (t - d), like=phi)

        if math.ndim(arg) == 0:
            return math.diag(math.exp(arg * prefactors))

        diags = math.exp(math.outer(arg, prefactors))
        return math.stack([math.diag(d) for d in diags])

def draw_and_connect_keypoints(self, keypoints):
        visible = {}
        keypoint_names = self.metadata.get("keypoint_names")
        for idx, keypoint in enumerate(keypoints):
            # draw keypoint
            x, y, prob = keypoint
            if prob > _KEYPOINT_THRESHOLD:
                self.draw_circle((x, y), color=_RED)
                if keypoint_names:
                    keypoint_name = keypoint_names[idx]
                    visible[keypoint_name] = (x, y)

        if self.metadata.get("keypoint_connection_rules"):
            for kp0, kp1, color in self.metadata.keypoint_connection_rules:
                if kp0 in visible and kp1 in visible:
                    x0, y0 = visible[kp0]
                    x1, y1 = visible[kp1]
                    color = tuple(x / 255.0 for x in color)
                    self.draw_line([x0, x1], [y0, y1], color=color)

        # draw lines from nose to mid-shoulder and mid-shoulder to mid-hip
        # Note that this strategy is specific to person keypoints.
        # For other keypoints, it should just do nothing
        try:
            ls_x, ls_y = visible["left_shoulder"]
            rs_x, rs_y = visible["right_shoulder"]
            mid_shoulder_x, mid_shoulder_y = (ls_x + rs_x) / 2, (ls_y + rs_y) / 2
        except KeyError:
            pass
        else:
            # draw line from nose to mid-shoulder
            nose_x, nose_y = visible.get("nose", (None, None))
            if nose_x is not None:
                self.draw_line([nose_x, mid_shoulder_x], [nose_y, mid_shoulder_y], color=_RED)

            try:
                # draw line from mid-shoulder to mid-hip
                lh_x, lh_y = visible["left_hip"]
                rh_x, rh_y = visible["right_hip"]
            except KeyError:
                pass
            else:
                mid_hip_x, mid_hip_y = (lh_x + rh_x) / 2, (lh_y + rh_y) / 2
                self.draw_line([mid_hip_x, mid_shoulder_x], [mid_hip_y, mid_shoulder_y], color=_RED)
        return self.output

def move_to_project(
        cls,
        new_dataset_project: str,  # str
        dataset_project: str,  # str
        dataset_name: str,  # str
    ) -> None:
        if cls.is_offline():
            raise ValueError("Cannot move dataset project in offlime mode")
        if not bool(Session.check_min_api_server_version(cls.__min_api_version, raise_error=True)):
            LoggerRoot.get_base_logger().warning(
                "Could not move dataset to another project because API version < {}".format(cls.__min_api_version)
            )
            return
        # noinspection PyBroadException
        try:
            dataset_ids = cls._get_dataset_ids_respecting_params(
                dataset_project=dataset_project,
                dataset_name=dataset_name,
                entire_dataset=True,
                shallow_search=False,
                force=True,
                action="move",
            )
        except Exception as e:
            LoggerRoot.get_base_logger().warning("Error: {}".format(str(e)))
            return
        for dataset_id in dataset_ids:
            # noinspection PyBroadException
            try:
                dataset = cls.get(dataset_id=dataset_id, _dont_propulate_runtime_props=True)
            except Exception:
                dataset = None
            if not dataset:
                LoggerRoot.get_base_logger().warning("Could not find dataset to move to another project")
                continue
            cls._move_to_project_aux(dataset._task, new_dataset_project, dataset.name)

def shebang_matches(text, regex):
    index = text.find('\n')
    if index >= 0:
        first_line = text[:index].lower()
    else:
        first_line = text.lower()
    if first_line.startswith('#!'):
        try:
            found = [x for x in split_path_re.split(first_line[2:].strip())
                     if x and not x.startswith('-')][-1]
        except IndexError:
            return False
        regex = re.compile(r'^%s(\.(exe|cmd|bat|bin))?$' % regex, re.IGNORECASE)
        if regex.search(found) is not None:
            return True
    return False

def populate_native_const_model_hierarchy(graph: InternalTorchIRGraph) -> None:
    cached_model_hierarchy = {}
    child_ops = defaultdict(list)

    for node in graph.nodes:
        for b in node.blocks:
            populate_native_const_model_hierarchy(b)

    for node in graph.nodes:
        cached_model_hierarchy[node.name] = node.model_hierarchy
        for val in node.inputs:
            child_ops[val].append(node.name)

    for node in graph.nodes:
        if node.kind != "constant":
            continue
        if node.model_hierarchy == "" and len(child_ops[node.name]) == 1:
            node.model_hierarchy = cached_model_hierarchy[child_ops[node.name][0]]

def is_method_call(node, method_name):
    if not isinstance(node, nodes.Call):
        return False

    if isinstance(node.node, nodes.Getattr):
        # e.g. foo.bar()
        method = node.node.attr

    elif isinstance(node.node, nodes.Name):
        # e.g. bar()
        method = node.node.name

    elif isinstance(node.node, nodes.Getitem):
        # e.g. foo["bar"]()
        method = node.node.arg.value

    else:
        return False

    if isinstance(method_name, (list, tuple)):
        return method in method_name

    return method == method_name

def runner_service(runner: Runner, **kwargs: Unpack[Config]) -> Service[t.Any]:
    if not isinstance(runner, Runner):  # type: ignore
        raise ValueError(f"Expect an instance of Runner, but got {type(runner)}")

    class RunnerHandle(runner.runnable_class):
        def __init__(self) -> None:
            super().__init__(**runner.runnable_init_params)

    apis: dict[str, APIMethod[..., t.Any]] = {}
    assert runner.runnable_class.bentoml_runnable_methods__ is not None
    for method in runner.runner_methods:
        runnable_method = runner.runnable_class.bentoml_runnable_methods__[method.name]
        api = APIMethod(  # type: ignore
            func=runnable_method.func,
            batchable=runnable_method.config.batchable,
            batch_dim=runnable_method.config.batch_dim,
            max_batch_size=method.max_batch_size,
            max_latency_ms=method.max_latency_ms,
        )
        apis[method.name] = api
    config: Config = {}
    resource_config = runner.resource_config or {}
    if (
        "nvidia.com/gpu" in runner.runnable_class.SUPPORTED_RESOURCES
        and "nvidia.com/gpu" in resource_config
    ):
        gpus: list[int] | str | int = resource_config["nvidia.com/gpu"]
        if isinstance(gpus, str):
            gpus = int(gpus)
        elif isinstance(gpus, list):
            gpus = len(gpus)
        config["workers"] = int(gpus * runner.workers_per_resource)
    elif "cpus" in resource_config:
        config["workers"] = (
            math.ceil(resource_config["cpus"]) * runner.workers_per_resource
        )
    config.update(kwargs)
    return Service(
        name=runner.name,
        config=config,
        inner=RunnerHandle,
        models=[BentoModel(m.tag) for m in runner.models],
        apis=apis,
    )

def check_public_method_exists(documented_methods_map):
    failures = []
    for obj, methods in documented_methods_map.items():
        # Let's ensure there is no repetition
        if len(set(methods)) != len(methods):
            failures.append(f"Error in the documentation of {obj}: there are repeated documented methods.")

        # Navigates into the object, given the full import path
        nested_path = obj.split(".")
        submodule = transformers
        if len(nested_path) > 1:
            nested_submodules = nested_path[:-1]
            for submodule_name in nested_submodules:
                if submodule_name == "transformers":
                    continue

                try:
                    submodule = getattr(submodule, submodule_name)
                except AttributeError:
                    failures.append(f"Could not parse {submodule_name}. Are the required dependencies installed?")
                continue

        class_name = nested_path[-1]

        try:
            obj_class = getattr(submodule, class_name)
        except AttributeError:
            failures.append(f"Could not parse {class_name}. Are the required dependencies installed?")
            continue

        # Checks that all explicitly documented methods are defined in the class
        for method in methods:
            if method == "all":  # Special keyword to document all public methods
                continue
            try:
                if not hasattr(obj_class, method):
                    failures.append(
                        "The following public method is explicitly documented but not defined in the corresponding "
                        f"class. class: {obj}, method: {method}. If the method is defined, this error can be due to "
                        f"lacking dependencies."
                    )
            except ImportError:
                pass

    if len(failures) > 0:
        raise Exception("\n".join(failures))

def get_readout_errors(readout_relaxation_probs, readout_misclassification_probs):
    measure_funcs = []
    if readout_relaxation_probs is not None:
        try:
            with qml.queuing.QueuingManager.stop_recording():
                qml.QutritAmplitudeDamping(*readout_relaxation_probs, wires=0)
        except Exception as e:
            raise DeviceError("Applying damping readout error results in error.") from e
        measure_funcs.append(partial(qml.QutritAmplitudeDamping, *readout_relaxation_probs))
    if readout_misclassification_probs is not None:
        try:
            with qml.queuing.QueuingManager.stop_recording():
                qml.TritFlip(*readout_misclassification_probs, wires=0)
        except Exception as e:
            raise DeviceError("Applying trit flip readout error results in error.") from e
        measure_funcs.append(partial(qml.TritFlip, *readout_misclassification_probs))

    return None if len(measure_funcs) == 0 else measure_funcs

def parse_complex_tensor_structs(
    inputs: Input | torch.Tensor | Sequence[Any] | Dict[Any, Any],
    attribute_to_extract: str,
    apply_fn: Callable[[Any], Any] = lambda x: x,
) -> Any:
    if isinstance(inputs, (torch.Tensor, Input)):
        return apply_fn(getattr(inputs, attribute_to_extract, None))
    elif isinstance(inputs, (int, float, bool)):
        # inputs is a python scalar value
        inputs_torch = torch.tensor(inputs)
        return apply_fn(getattr(inputs_torch, attribute_to_extract, None))

    elif isinstance(inputs, (list, tuple)):
        torchtrt_input_list = []
        for input_obj in inputs:
            torchtrt_input = parse_complex_tensor_structs(
                input_obj, attribute_to_extract, apply_fn
            )
            torchtrt_input_list.append(torchtrt_input)

        return (
            torchtrt_input_list
            if isinstance(inputs, list)
            else tuple(torchtrt_input_list)
        )

    elif isinstance(inputs, dict):
        torchtrt_inputs_dict: Dict[Any, Any] = dict()

        for key, input_obj in inputs.items():
            torchtrt_input = parse_complex_tensor_structs(
                input_obj, attribute_to_extract, apply_fn
            )
            torchtrt_inputs_dict[key] = torchtrt_input

        return torchtrt_inputs_dict

    else:
        raise ValueError(
            f"Invalid input type {type(inputs)} encountered during Dynamo input parsing. "
            + "Allowed input types: {torch_tensorrt.Input, torch.Tensor, list, tuple, dict}"
        )

def format_log_data_value(data: Any) -> str:
    if data is None:
        return 'None'
    if isinstance(data, str):
        return f"\"{data}\""
    if isinstance(data, int):
        return str(data)
    if isinstance(data, float):
        return f'{data:.4f}'
    if isinstance(data, torch.Tensor):
        if data.shape == () or reduce(operator.mul, data.shape, 1) == 1:
            return format_log_data_value(data.cpu().item())
        return 'Tensor of shape ' + str(data.shape)
    if isinstance(data, collections.abc.Mapping):
        output = ['{ ']
        for k, v in data.items():
            assert isinstance(k, str)
            v = format_log_data_value(v)
            output.append(f"\"{k}\": {v}, ")
        output.append('}')
        return ''.join(output)
    if isinstance(data, collections.abc.Iterable):
        return '[' + ', '.join(format_log_data_value(v) for v in data) + ']'

    # Unknown format catch-all
    return str(data)

def encode_prompt(
        self,
        prompt: Union[str, List[str]],
        device: torch.device,
        num_images_per_prompt: int = 1,
    ) -> List[torch.Tensor]:
        if isinstance(prompt, str):
            prompt = [prompt]

        text_hiddens = []

        for p in prompt:
            ids = self.tokenizer(
                p,
                add_special_tokens=True,
                truncation=True,
                padding=False,
            )["input_ids"]

            if len(ids) == 0:
                if self.tokenizer.bos_token_id is not None:
                    ids = [self.tokenizer.bos_token_id]
                else:
                    ids = [0]

            input_ids = torch.tensor([ids], device=device)
            with torch.no_grad():
                outputs = self.text_encoder(
                    input_ids=input_ids,
                    output_hidden_states=True,
                )
                # Use second to last hidden state (matches training)
                hidden = outputs.hidden_states[-2][0]  # [T, H]

            # Repeat for num_images_per_prompt
            for _ in range(num_images_per_prompt):
                text_hiddens.append(hidden)

        return text_hiddens

def compose_chunk(
    module: torch.fx.GraphModule,
) -> torch.fx.GraphModule:

    def match_pattern(module, node):
        if node.op == "call_function" and node.target in (torch.ops.aten.split.Tensor,):
            div = node.args[1]
            input = node.args[0]
            if isinstance(div, int):
                return (False,)
            if div.target != operator.floordiv:
                return (False,)
            else:
                div_const = div.args[1]
                sub = div.args[0]
                if sub.target != operator.sub:
                    return (False,)
                else:
                    add = sub.args[0]
                    if add.target != operator.add:
                        return (False,)
                    else:
                        add_const = add.args[1]
                        if add_const != div_const:
                            return (False,)
                        symsize = add.args[0]
                        if symsize.target != torch.ops.aten.sym_size:
                            return (False,)
                        else:
                            symsize_input = symsize.args[0]
                            dim = symsize.args[1]
                            if symsize_input != input:
                                return (False,)

            return (True, div_const, dim)
        else:
            return (False,)

    modified = False
    for node in module.graph.nodes:
        res = match_pattern(module, node)
        if res[0]:
            modified = True
            with module.graph.inserting_after(node):
                new_args = (node.args[0], res[1], res[2])
                new_node = module.graph.create_node(
                    "call_function",
                    aten_compose_chunk,
                    args=new_args,
                    kwargs=None,
                )
            node.replace_all_uses_with(new_node)

    module.graph.eliminate_dead_code()
    module.recompile()
    return PassResult(module, modified)

def remove_unwanted_string(directory: str, target_string: str):
    for filename in os.listdir(directory):
        if filename.endswith(".rst"):
            filepath = os.path.join(directory, filename)
            with open(filepath, "r+") as file:
                lines = file.readlines()
                file.seek(0)
                file.truncate()
                for line in lines:
                    # Check if the line ends with 'module' and remove it
                    if line.strip().endswith(target_string):
                        line = line.replace(target_string, "")
                    file.write(line)

def array(val, dtype=None, copy=True, ndmin=0):  # pylint: disable=redefined-outer-name
  if dtype:
    dtype = utils.result_type(dtype)
  if isinstance(val, arrays_lib.ndarray):
    result_t = val.data
  else:
    result_t = val

  if copy and isinstance(result_t, tf.Tensor):
    # Note: In eager mode, a copy of `result_t` is made only if it is not on
    # the context device.
    result_t = tf.identity(result_t)

  if not isinstance(result_t, tf.Tensor):
    if not dtype:
      dtype = utils.result_type(result_t)
    # We can't call `convert_to_tensor(result_t, dtype=dtype)` here because
    # convert_to_tensor doesn't allow incompatible arguments such as (5.5, int)
    # while np.array allows them. We need to convert-then-cast.
    def maybe_data(x):
      if isinstance(x, arrays_lib.ndarray):
        return x.data
      return x

    # Handles lists of ndarrays
    result_t = tf.nest.map_structure(maybe_data, result_t)
    result_t = arrays_lib.convert_to_tensor(result_t)
    result_t = tf.cast(result_t, dtype=dtype)
  elif dtype:
    result_t = tf.cast(result_t, dtype)
  ndims = tf.rank(result_t)

  def true_fn():
    old_shape = tf.shape(result_t)
    new_shape = tf.concat([tf.ones(ndmin - ndims, tf.int32), old_shape], axis=0)
    return tf.reshape(result_t, new_shape)

  result_t = utils.cond(utils.greater(ndmin, ndims), true_fn, lambda: result_t)
  return arrays_lib.tensor_to_ndarray(result_t)

def send_request(self, request_type, request_content, msg_queue, msg_proc_func=None):
        head_info = {"version": qlib.__version__}

        def request_callback(*args):
            """callback_wrapper

            :param *args: args[0] is the response content
            """
            # args[0] is the response content
            self.logger.debug("receive data and enter queue")
            msg = dict(args[0])
            if msg["detailed_info"] is not None:
                if msg["status"] != 0:
                    self.logger.error(msg["detailed_info"])
                else:
                    self.logger.info(msg["detailed_info"])
            if msg["status"] != 0:
                ex = ValueError(f"Bad response(status=={msg['status']}), detailed info: {msg['detailed_info']}")
                msg_queue.put(ex)
            else:
                if msg_proc_func is not None:
                    try:
                        ret = msg_proc_func(msg["result"])
                    except Exception as e:
                        self.logger.exception("Error when processing message.")
                        ret = e
                else:
                    ret = msg["result"]
                msg_queue.put(ret)
            self.disconnect()
            self.logger.debug("disconnected")

        self.logger.debug("try connecting")
        self.connect_server()
        self.logger.debug("connected")
        # The pickle is for passing some parameters with special type(such as
        # pd.Timestamp)
        request_content = {"head": head_info, "body": json.dumps(request_content, default=str)}
        self.sio.on(request_type + "_response", request_callback)
        self.logger.debug("try sending")
        self.sio.emit(request_type + "_request", request_content)
        self.sio.wait()

def compute_decomposition(input_matrix, wires, tol=0):  # pylint:disable=arguments-differ
        alphas = math.arccos(input_matrix).flatten()
        thetas = compute_theta(alphas)

        auxiliary = [wires[0]]
        wires_i = wires[1 : 1 + len(wires) // 2][::-1]
        wires_j = wires[1 + len(wires) // 2 : len(wires)][::-1]

        code = gray_code(int(2 * math.log2(len(input_matrix))))
        control_wires = np.log2(code ^ np.roll(code, -1)).astype(int)

        wire_map = dict(enumerate(wires_j + wires_i))

        op_list = [Hadamard(w) for w in wires_i]

        nots = {}
        for theta, control_index in zip(thetas, control_wires):
            if math.is_abstract(theta):
                for c_wire in nots:
                    op_list.append(CNOT(wires=[c_wire] + auxiliary))
                op_list.append(RY(2 * theta, wires=auxiliary))
                nots = {}
                nots[wire_map[control_index]] = 1
                continue

            if math.abs(2 * theta) > tol:
                for c_wire in nots:
                    op_list.append(CNOT(wires=[c_wire] + auxiliary))
                op_list.append(RY(2 * theta, wires=auxiliary))
                nots = {}
            if wire_map[control_index] in nots:
                del nots[wire_map[control_index]]
            else:
                nots[wire_map[control_index]] = 1

        for c_wire in nots:
            op_list.append(CNOT([c_wire] + auxiliary))

        for w_i, w_j in zip(wires_i, wires_j):
            op_list.append(SWAP(wires=[w_i, w_j]))

        for w in wires_i:
            op_list.append(Hadamard(w))

        return op_list

def compute_vertex_channels(input_channels, output_channels, matrix):
    num_vertices = np.shape(matrix)[0]

    vertex_channels = [0] * num_vertices
    vertex_channels[0] = input_channels
    vertex_channels[num_vertices - 1] = output_channels

    if num_vertices == 2:
        # Edge case where module only has input and output vertices
        return vertex_channels

    # Compute the in-degree ignoring input, axis 0 is the src vertex and axis 1 is
    # the dst vertex. Summing over 0 gives the in-degree count of each vertex.
    in_degree = np.sum(matrix[1:], axis=0)
    interior_channels = output_channels // in_degree[num_vertices - 1]
    correction = output_channels % in_degree[num_vertices - 1]  # Remainder to add

    # Set channels of vertices that flow directly to output
    for v in range(1, num_vertices - 1):
        if matrix[v, num_vertices - 1]:
            vertex_channels[v] = interior_channels
            if correction:
                vertex_channels[v] += 1
                correction -= 1

    # Set channels for all other vertices to the max of the out edges, going backwards.
    # (num_vertices - 2) index skipped because it only connects to output.
    for v in range(num_vertices - 3, 0, -1):
        if not matrix[v, num_vertices - 1]:
            for dst in range(v + 1, num_vertices - 1):
                if matrix[v, dst]:
                    vertex_channels[v] = max(vertex_channels[v], vertex_channels[dst])
        assert vertex_channels[v] > 0

    _logger.debug('vertex_channels: %s', str(vertex_channels))

    # Sanity check, verify that channels never increase and final channels add up.
    final_fan_in = 0
    for v in range(1, num_vertices - 1):
        if matrix[v, num_vertices - 1]:
            final_fan_in += vertex_channels[v]
        for dst in range(v + 1, num_vertices - 1):
            if matrix[v, dst]:
                assert vertex_channels[v] >= vertex_channels[dst]
    assert final_fan_in == output_channels or num_vertices == 2
    # num_vertices == 2 means only input/output nodes, so 0 fan-in

    return vertex_channels

def transform_prediction(
        self,
        y_pred: Union[np.ndarray, dict],
        inverse_categorical: bool = True,
        return_proba: bool = False,
    ) -> NDArray:
        assert self._fit_called or self._fit_y_called, (
            "You will need to first call preprocessor.fit_y() before calling preprocessor.transform_prediction."
        )

        if self.label_type == CATEGORICAL:
            assert len(y_pred.shape) <= 2
            if len(y_pred.shape) == 2 and y_pred.shape[1] >= 2:
                y_pred = y_pred.argmax(axis=1)
            else:
                y_pred = (y_pred > 0.5).astype(int)
            # Transform the predicted label back to the original space (e.g., string values)
            if inverse_categorical:
                y_pred = self._label_generator.inverse_transform(y_pred)
        elif self.label_type == NUMERICAL:
            y_pred = self._label_scaler.inverse_transform(y_pred)
            y_pred = np.squeeze(y_pred)
            # Convert nan to 0
            y_pred = np.nan_to_num(y_pred)
        elif self.label_type == NER_ANNOTATION:
            y_pred = self._label_generator.inverse_transform(y_pred)

            if return_proba:
                y_pred = y_pred[-1]
            else:
                if inverse_categorical:
                    # Return annotations and offsets
                    y_pred = y_pred[1]
                else:
                    y_pred = y_pred[0]
        else:
            raise NotImplementedError

        return y_pred

def layout(self, divider=None):
        # Ensure matplotlib version compatibility
        if make_axes_locatable is None:
            raise YellowbrickValueError(
                (
                    "heatmap requires matplotlib 2.0.2 or greater "
                    "please upgrade matplotlib or set heatmap=False on the visualizer"
                )
            )

        # Create the new axes for the colorbar and heatmap
        if divider is None:
            divider = make_axes_locatable(self.ax)

        # Call to super class ensures that a colorbar is drawn when target is
        # continuous.
        super(PCA, self).layout(divider)

        if self.heatmap:

            # Axes for colorbar(for heatmap).
            if self._uax is None:
                self._uax = divider.append_axes("bottom", size="10%", pad=0.7)

            # Axes for heatmap
            if self._lax is None:
                self._lax = divider.append_axes("bottom", size="15%", pad=0.5)

def masks2segments(masks: np.ndarray | torch.Tensor, strategy: str = "all") -> list[np.ndarray]:
    from ultralytics.data.converter import merge_multi_segment

    masks = masks.astype("uint8") if isinstance(masks, np.ndarray) else masks.byte().cpu().numpy()
    segments = []
    for x in np.ascontiguousarray(masks):
        c = cv2.findContours(x, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)[0]
        if c:
            if strategy == "all":  # merge and concatenate all segments
                c = (
                    np.concatenate(merge_multi_segment([x.reshape(-1, 2) for x in c]))
                    if len(c) > 1
                    else c[0].reshape(-1, 2)
                )
            elif strategy == "largest":  # select largest segment
                c = np.array(c[np.array([len(x) for x in c]).argmax()]).reshape(-1, 2)
        else:
            c = np.zeros((0, 2))  # no segments found
        segments.append(c.astype("float32"))
    return segments

def write_image(path_file: str | Path, image: torch.Tensor, quality: int = 80) -> None:
    if not isinstance(path_file, Path):
        path_file = Path(path_file)

    KORNIA_CHECK(
        path_file.suffix in [".jpg", ".jpeg", ".png", ".tiff"],
        f"Invalid file extension: {path_file}, only .jpg, .jpeg, .png and .tiff are supported.",
    )

    KORNIA_CHECK(image.dim() >= 2, f"Invalid image shape: {image.shape}. Must be at least 2D.")

    img_np = tensor_to_image(image, keepdim=True, force_contiguous=True)  # HxWxC
    if img_np.ndim == 2:
        img_np = img_np[..., None]  # ensures channel dimension
    if image.dtype == torch.uint8:
        _write_uint8_image(path_file, img_np, quality)
    elif image.dtype == torch.uint16:
        _write_uint16_image(path_file, img_np)
    elif image.dtype == torch.float32:
        _write_float32_image(path_file, img_np)
    else:
        raise NotImplementedError(f"Unsupported image dtype: {image.dtype}")

def parse_ssh_connection(ssh_connection: Any) -> Tuple[Optional[str], int]:
    ssh_user: Optional[str] = None
    ssh_port: int = 22

    # Normalize into a list of tokens for easier processing.
    tokens: List[str] = []
    if isinstance(ssh_connection, str):
        try:
            tokens = shlex.split(ssh_connection)
        except Exception:  # pylint: disable=broad-except
            tokens = [ssh_connection]
    elif isinstance(ssh_connection, list):
        for elem in ssh_connection:
            if isinstance(elem, str):
                try:
                    tokens.extend(shlex.split(elem))
                except Exception:  # pylint: disable=broad-except
                    tokens.append(elem)
    else:
        # Unknown type; return defaults.
        return ssh_user, ssh_port

    # Find the first token containing '@' as the user@host candidate.
    user_host: Optional[str] = next((t for t in tokens if '@' in t), None)
    if user_host:
        ssh_user = user_host.split('@', 1)[0].strip()
        # Try host:port format (after '@').
        host_part = user_host.split('@', 1)[1]
        if ':' in host_part:
            _, maybe_port = host_part.rsplit(':', 1)
            try:
                ssh_port = int(maybe_port)
            except ValueError:
                pass

    # Check for '-p <port>' pair anywhere in the tokens. This takes priority.
    if '-p' in tokens:
        idx = tokens.index('-p')
        if idx + 1 < len(tokens):
            try:
                ssh_port = int(tokens[idx + 1])
            except ValueError:
                pass

    return ssh_user, ssh_port

def replace_with_mxfp4_linear(model, quantization_config=None, modules_to_not_convert: list[str] | None = None):
    if quantization_config.dequantize:
        return model

    from .hub_kernels import get_kernel

    global triton_kernels_hub
    triton_kernels_hub = get_kernel("kernels-community/gpt-oss-triton-kernels")

    has_been_replaced = False
    for module_name, module in model.named_modules():
        if not should_convert_module(module_name, modules_to_not_convert):
            continue
        if module.__class__.__name__ == "GptOssExperts" and not quantization_config.dequantize:
            with torch.device("meta"):
                model.set_submodule(module_name, Mxfp4GptOssExperts(model.config))
                has_been_replaced = True
        if module.__class__.__name__ == "GptOssMLP" and not quantization_config.dequantize:
            from types import MethodType

            module.forward = MethodType(mlp_forward, module)

    if not has_been_replaced:
        logger.warning(
            "You are loading your model using mixed-precision FP4 quantization but no linear modules were found in your model."
            " Please double check your model architecture, or submit an issue on github if you think this is"
            " a bug."
        )

    return model

def processing_fn(results: ResultBatch, tape, coeffs, generators_per_parameter):
    final_res = []
    for coeff, res in zip(coeffs, results):
        if not isinstance(res, (tuple, list)):
            res = [res]  # add singleton dimension back in for one measurement
        final_res.append([math.convert_like(2 * coeff * r, r) for r in res])

    # Post process for probs
    measurements_probs = [
        idx for idx, m in enumerate(tape.measurements) if isinstance(m, ProbabilityMP)
    ]
    if measurements_probs:
        for idx, res in enumerate(final_res):
            for prob_idx in measurements_probs:
                final_res[idx][prob_idx] = _postprocess_probs(
                    res[prob_idx], tape.measurements[prob_idx], tape
                )

    mps = (
        tape.measurements * tape.shots.num_copies
        if tape.shots.has_partitioned_shots
        else tape.measurements
    )
    # first index = into measurements, second index = into parameters
    grads = tuple([] for _ in mps)
    results = iter(final_res)
    for num_generators in generators_per_parameter:
        if num_generators == 0:
            for g_for_parameter, mp in zip(grads, mps):
                zeros_like_mp = np.zeros(
                    mp.shape(num_device_wires=len(tape.wires)), dtype=mp.numeric_type
                )
                g_for_parameter.append(zeros_like_mp)
        else:
            sub_results = islice(results, num_generators)  # take the next number of results
            # sum over batch, iterate over measurements
            summed_sub_results = (sum(r) for r in zip(*sub_results))

            for g_for_parameter, r in zip(grads, summed_sub_results, strict=True):
                g_for_parameter.append(r)

    if len(mps) == 1:
        return grads[0][0] if len(tape.trainable_params) == 1 else grads[0]
    return tuple(g[0] for g in grads) if len(tape.trainable_params) == 1 else grads

def query_nb201_trial_stats(arch, num_epochs, dataset, reduction=None, include_intermediates=False):
    if proxy.obj is None:
        proxy.initialize(load_benchmark('nasbench201'))

    fields = []
    if reduction == 'none':
        reduction = None
    if reduction == 'mean':
        for field_name in Nb201TrialStats._meta.sorted_field_names:
            if field_name not in ['id', 'config', 'seed']:
                fields.append(fn.AVG(getattr(Nb201TrialStats, field_name)).alias(field_name))
    elif reduction is None:
        fields.append(Nb201TrialStats)
    else:
        raise ValueError('Unsupported reduction: \'%s\'' % reduction)
    query = Nb201TrialStats.select(*fields, Nb201TrialConfig).join(Nb201TrialConfig)
    conditions = []
    if arch is not None:
        conditions.append(Nb201TrialConfig.arch == arch)
    if num_epochs is not None:
        conditions.append(Nb201TrialConfig.num_epochs == num_epochs)
    if dataset is not None:
        conditions.append(Nb201TrialConfig.dataset == dataset)
    if conditions:
        query = query.where(functools.reduce(lambda a, b: a & b, conditions))
    if reduction is not None:
        query = query.group_by(Nb201TrialStats.config)
    for trial in query:
        if include_intermediates:
            data = model_to_dict(trial)
            # exclude 'trial' from intermediates as it is already available in data
            data['intermediates'] = [
                {k: v for k, v in model_to_dict(t).items() if k != 'trial'} for t in trial.intermediates
            ]
            yield data
        else:
            yield model_to_dict(trial)

def taper_hf(generators, paulixops, paulix_sector, num_electrons, num_wires):
    # build the untapered Hartree Fock state
    hf = np.where(np.arange(num_wires) < num_electrons, 1, 0)

    # convert the HF state to a corresponding HF observable under the JW transform
    ferm_ps = PauliSentence({PauliWord({0: "I"}): 1.0})
    for idx, bit in enumerate(hf):
        if bit:
            ps = qml.jordan_wigner(qml.FermiC(idx), ps=True)
        else:
            ps = PauliSentence({PauliWord({idx: "I"}): 1.0})
        ferm_ps @= ps

    # taper the HF observable using the symmetries obtained from the molecular hamiltonian
    fermop_taper = _taper_pauli_sentence(ferm_ps, generators, paulixops, paulix_sector)
    fermop_ps = pauli_sentence(fermop_taper)
    fermop_mat = _binary_matrix_from_pws(list(fermop_ps), len(fermop_ps.wires))

    # build a wireset to match wires with that of the tapered Hamiltonian
    gen_wires = Wires.all_wires([generator.wires for generator in generators])
    xop_wires = Wires.all_wires([paulix_op.wires for paulix_op in paulixops])
    wireset = Wires.unique_wires([gen_wires, xop_wires])

    # iterate over the terms in tapered HF observable and build the tapered HF state
    tapered_hartree_fock = []
    for col in fermop_mat.T[fermop_mat.shape[1] // 2 :]:
        if 1 in col:
            tapered_hartree_fock.append(1)
        else:
            tapered_hartree_fock.append(0)
    while len(tapered_hartree_fock) < len(wireset):
        tapered_hartree_fock.append(0)

    return np.array(tapered_hartree_fock).astype(int)

def partition_data(dataset, datadir, partition, num_clients, beta):
    if dataset == "cifar10":
        X_train, y_train, X_test, y_test = load_cifar10_data(datadir)
    elif dataset == "cifar100":
        X_train, y_train, X_test, y_test = load_cifar100_data(datadir)

    n_train = y_train.shape[0]

    if partition in ("homo", "iid"):
        idxs = np.random.permutation(n_train)
        batch_idxs = np.array_split(idxs, num_clients)
        net_dataidx_map = {i: batch_idxs[i] for i in range(num_clients)}

    elif partition in ("noniid-labeldir", "noniid"):
        min_size = 0
        min_require_size = 10
        K = 10
        if dataset == "cifar100":
            K = 100
        elif dataset == "tinyimagenet":
            K = 200

        N = y_train.shape[0]
        net_dataidx_map = {}

        while min_size < min_require_size:
            idx_batch = [[] for _ in range(num_clients)]
            for k in range(K):
                idx_k = np.where(y_train == k)[0]
                np.random.shuffle(idx_k)
                proportions = np.random.dirichlet(np.repeat(beta, num_clients))
                proportions = np.array(
                    [
                        p * (len(idx_j) < N / num_clients)
                        for p, idx_j in zip(proportions, idx_batch)
                    ]
                )
                proportions = proportions / proportions.sum()
                proportions = (np.cumsum(proportions) * len(idx_k)).astype(int)[:-1]
                idx_batch = [
                    idx_j + idx.tolist()
                    for idx_j, idx in zip(idx_batch, np.split(idx_k, proportions))
                ]
                min_size = min([len(idx_j) for idx_j in idx_batch])
        for j in range(num_clients):
            np.random.shuffle(idx_batch[j])
            net_dataidx_map[j] = idx_batch[j]

    return (X_train, y_train, X_test, y_test, net_dataidx_map)

def get_encoder(self, modality: str | None = None):
        # NOTE: new models need to use existing names for layers if possible, so this list doesn't grow infinitely
        if modality in ["image", "video"]:
            possible_module_names = ["vision_tower", "visual", "vision_model", "vision_encoder", "image_tower"]
        elif modality == "audio":
            possible_module_names = ["audio_tower", "audio_encoder", "speech_encoder"]
        elif modality is None:
            possible_module_names = ["text_encoder", "encoder"]
        else:
            raise ValueError(f'Unnrecognized modality, has to be "image", "video" or "audio" but found {modality}')

        for name in possible_module_names:
            if hasattr(self, name):
                return getattr(self, name)

        if self.base_model is not self and hasattr(self.base_model, "get_encoder"):
            base_encoder = self.base_model.get_encoder(modality=modality)
            # Base model will always have attr `get_encoder` if inherited from `PreTrainedModel`
            # But it doesn't mean that the model has an encoder module, and we need to return `self`
            if base_encoder != self.base_model:
                return base_encoder

        # If this is a base transformer model (no encoder/model attributes), return self
        return self

def infer_archive_type(archive_path):
    # Get the path extension including multiple extensions, ex. ".tar.gz"
    extension = ".".join(["", *os.path.basename(archive_path).split(".")[1:]])
    extension = extension.lower()
    if extension.endswith(".tar.z") or extension.endswith(".tar.zip"):
        return ArchiveType.TAR_ZIP
    elif extension.endswith(".tar.bz2") or extension.endswith(".tbz2"):
        return ArchiveType.TAR_BZ2
    elif extension.endswith(".tar.gz") or extension.endswith(".tgz"):
        return ArchiveType.TAR_GZ
    elif extension.endswith(".tar"):
        return ArchiveType.TAR
    elif extension.endswith(".zip") or extension.endswith(".zipx"):
        return ArchiveType.ZIP
    elif extension.endswith(".gz") or extension.endswith(".gzip"):
        return ArchiveType.GZIP
    else:
        return ArchiveType.UNKNOWN

def get_average_per_class_confusion_matrix(
    labels: List[Dict[str, Any]],
    predictions: List[np.ndarray],
    num_procs: int = 1,
    class_names: Optional[Dict[Any, Any]] = None,
) -> Dict[Union[int, str], Dict[str, float]]:
    iou_thrs = np.linspace(0.5, 0.95, int(np.round((0.95 - 0.5) / 0.05)) + 1, endpoint=True)
    num_classes = len(predictions[0])
    if class_names is None:
        class_names = {str(i): int(i) for i in list(range(num_classes))}
    class_names = _sort_dict_to_list(class_names)
    avg_metrics = {class_num: {"TP": 0.0, "FP": 0.0, "FN": 0.0} for class_num in class_names}

    for iou_threshold in iou_thrs:
        results_dict = _get_per_class_confusion_matrix_dict_(
            labels, predictions, iou_threshold, num_procs
        )

        for class_num in results_dict:
            tp = results_dict[class_num]["TP"]
            fp = results_dict[class_num]["FP"]
            fn = results_dict[class_num]["FN"]

            avg_metrics[class_names[class_num]]["TP"] += tp
            avg_metrics[class_names[class_num]]["FP"] += fp
            avg_metrics[class_names[class_num]]["FN"] += fn

    num_thresholds = len(iou_thrs) * len(results_dict)
    for class_name in avg_metrics:
        avg_metrics[class_name]["TP"] /= num_thresholds
        avg_metrics[class_name]["FP"] /= num_thresholds
        avg_metrics[class_name]["FN"] /= num_thresholds
    return avg_metrics

def to_skip_connection_graph(graph):
    # The last conv layer cannot be widen since wider operator cannot be done
    # over the two sides of flatten.
    weighted_layer_ids = graph.skip_connection_layer_ids()
    valid_connection = []
    for skip_type in sorted(
            [NetworkDescriptor.ADD_CONNECT, NetworkDescriptor.CONCAT_CONNECT]):
        for index_a in range(len(weighted_layer_ids)):
            for index_b in range(len(weighted_layer_ids))[index_a + 1:]:
                valid_connection.append((index_a, index_b, skip_type))

    if not valid_connection:
        return graph
    for index_a, index_b, skip_type in sample(valid_connection, 1):
        a_id = weighted_layer_ids[index_a]
        b_id = weighted_layer_ids[index_b]
        if skip_type == NetworkDescriptor.ADD_CONNECT:
            graph.to_add_skip_model(a_id, b_id)
        else:
            graph.to_concat_skip_model(a_id, b_id)
    return graph

def from_repr(
        cls,
        memory_layout: VkMemoryLayout,
        storage_type: VkStorageType = VkStorageType.BUFFER,
    ) -> "PackedDimInfo":
        is_buffer = storage_type == VkStorageType.BUFFER

        if memory_layout == VkMemoryLayout.TENSOR_WIDTH_PACKED:
            return cls(
                packed_dim=0,
                packed_dim_block_size=1 if is_buffer else 4,
            )
        elif memory_layout == VkMemoryLayout.TENSOR_HEIGHT_PACKED:
            return cls(
                packed_dim=1,
                packed_dim_block_size=1 if is_buffer else 4,
            )
        elif memory_layout == VkMemoryLayout.TENSOR_CHANNELS_PACKED:
            return cls(
                packed_dim=2,
                packed_dim_block_size=1 if is_buffer else 4,
            )
        elif memory_layout == VkMemoryLayout.PACKED_INT8_4W:
            return cls(
                packed_dim=0,
                packed_dim_block_size=4,
            )
        elif memory_layout == VkMemoryLayout.PACKED_INT8_4W4C:
            return cls(
                packed_dim=2,
                packed_dim_block_size=4,
            )
        elif memory_layout == VkMemoryLayout.PACKED_INT8_4H4W:
            return cls(
                packed_dim=0,
                packed_dim_block_size=4,
            )
        elif memory_layout == VkMemoryLayout.PACKED_INT8_4C1W:
            return cls(
                packed_dim=2,
                packed_dim_block_size=4 if is_buffer else 16,
            )
        elif memory_layout == VkMemoryLayout.PACKED_INT8_CONV2D:
            return cls(
                packed_dim=2,
                packed_dim_block_size=4,
            )
        else:
            raise ValueError(f"Unknown memory layout: {memory_layout}")

def to_gray(self) -> Image:
        src = self._pixel_format.color_space
        data = self._data

        if src == ColorSpace.GRAY:
            return self

        is_channels_last = self._layout.channels_order == ChannelsOrder.CHANNELS_LAST
        if is_channels_last:
            data = data.permute(0, 3, 1, 2) if data.ndim == 4 else data.permute(2, 0, 1)

        # Perform the color space conversion
        if src == ColorSpace.RGB:
            out = kornia.color.rgb_to_grayscale(data)
        elif src == ColorSpace.BGR:
            out = kornia.color.bgr_to_grayscale(data)
        else:
            raise ValueError(f"Unsupported source color space for to_gray(): {src}")

        if is_channels_last:
            if out.ndim == 4:
                out = out.permute(0, 2, 3, 1)
            elif out.ndim == 3:
                out = out.permute(1, 2, 0)
            else:
                raise ValueError(f"Unexpected shape after grayscale conversion: {out.shape}")

        new_pf = PixelFormat(color_space=ColorSpace.GRAY, bit_depth=self._pixel_format.bit_depth)
        new_layout = ImageLayout(self._layout.image_size, channels=1, channels_order=self._layout.channels_order)
        return Image(out, new_pf, new_layout)

def slice_closed_jaxpr_by_full_pipeline_marks(
        closed_jaxpr: ClosedJaxpr) -> Sequence[JaxPipelineComputation]:
    global_consts_dir = dict(
        zip(closed_jaxpr.jaxpr.constvars, closed_jaxpr.consts))

    result_computations = []
    current_computation = None

    for eqn in closed_jaxpr.jaxpr.eqns:
        if eqn.primitive is pipeline_p and eqn.params["mark_type"] == "start":
            assert current_computation is None, (
                "Defining a pipeline computation "
                "inside a pipeline computation is "
                "not allowed.")
            current_computation = JaxPipelineComputation(
                name=eqn.params["name"])
            for var in eqn.invars:
                if isinstance(var, Literal):
                    pass
                elif var in global_consts_dir:
                    current_computation.consts_dir[var] = global_consts_dir[var]
                else:
                    current_computation.invars.append(var)

        for var in eqn.invars:
            if not isinstance(var, Literal) and var in global_consts_dir:
                current_computation.consts_dir[var] = global_consts_dir[var]

        assert current_computation is not None
        current_computation.eqns.append(eqn)

        if eqn.primitive is pipeline_p and eqn.params["mark_type"] == "end":
            assert current_computation is not None, (
                "Ending a pipeline computation before its start.")
            assert current_computation.name == eqn.params["name"], (
                "Ending a pipeline computation different from its start.")
            for var in eqn.outvars:
                current_computation.outvars.append(var)
            result_computations.append(current_computation)
            current_computation = None

    return result_computations

def make_alloc_node(
    graph_module: torch.fx.GraphModule,
    val: Union[
        Optional[FakeTensor], List[Optional[FakeTensor]], Tuple[Optional[FakeTensor]]
    ],
    tensor_meta: Union[
        Optional[TensorMetadata],
        List[Optional[TensorMetadata]],
        Tuple[Optional[TensorMetadata]],
    ],
) -> torch.fx.Node:
    if val is None:
        if tensor_meta is not None:
            assert isinstance(tensor_meta, TensorMetadata)
            alloc_spec = (tensor_meta.shape, tensor_meta.dtype)
        else:
            raise InternalError(
                "Memory allocator node needs FakeTensor val or TensorMetadata to proceed"
            )
    elif isinstance(val, FakeTensor):
        alloc_spec = (val.shape, val.dtype)
    else:
        assert isinstance(val, list) or isinstance(val, tuple)
        assert isinstance(tensor_meta, list) or isinstance(tensor_meta, tuple)
        alloc_spec: List[memory.AllocSpec] = []
        for v, t in zip(val, tensor_meta):
            if v is not None:
                # pyre-fixme[6]: For 1st argument expected
                #  `Union[List[Tuple[List[int], dtype]], Tuple[List[int], dtype]]` but
                #  got `Tuple[Size, dtype]`.
                alloc_spec.append((v.shape, v.dtype))
            elif t is not None:
                # pyre-fixme[6]: For 1st argument expected
                #  `Union[List[Tuple[List[int], dtype]], Tuple[List[int], dtype]]` but
                #  got `Tuple[Size, dtype]`.
                alloc_spec.append((t.shape, t.dtype))
            else:
                raise InternalError(
                    "Memory allocator node needs FakeTensor val or TensorMetadata to proceed"
                )

    alloc = graph_module.graph.call_function(memory.alloc, (alloc_spec,))
    alloc.meta["val"] = val
    alloc.meta["tensor_meta"] = tensor_meta
    return alloc

def assert_valid_inputs(
    labels: List[Dict[str, Any]],
    predictions,
    method: Optional[str] = None,
    threshold: Optional[float] = None,
):
    if len(labels) != len(predictions):
        raise ValueError(
            f"labels and predictions length needs to match. len(labels) == {len(labels)} while len(predictions) == {len(predictions)}."
        )
    # Typecheck labels and predictions
    if not isinstance(labels[0], dict):
        raise ValueError(
            f"Labels has to be a list of dicts. Instead it is list of {type(labels[0])}."
        )
    # check last column of predictions is probabilities ( < 1.)?
    if not isinstance(predictions[0], (list, np.ndarray)):
        raise ValueError(
            f"Prediction has to be a list or np.ndarray. Instead it is type {type(predictions[0])}."
        )
    if not predictions[0][0].shape[1] == 5:
        raise ValueError(
            f"Prediction values have to be of format [x1,y1,x2,y2,pred_prob]. Please refer to the documentation for predicted probabilities under object_detection.rank.get_label_quality_scores for details"
        )

    valid_methods = ["objectlab"]
    if method is not None and method not in valid_methods:
        raise ValueError(
            f"""
            {method} is not a valid object detection scoring method!
            Please choose a valid scoring_method: {valid_methods}
            """
        )

    if threshold is not None and threshold > 1.0:
        raise ValueError(
            f"""
            Threshold is a cutoff of predicted probabilities and therefore should be <= 1.
            """
        )

def cook_initial_point_generator(generator, **kwargs):
    if generator is None:
        generator = "random"
    elif isinstance(generator, str):
        generator = generator.lower()
        if generator not in ["sobol", "halton", "hammersly", "lhs", "random",
                             "grid"]:
            raise ValueError("Valid strings for the generator parameter "
                             " are: 'sobol', 'lhs', 'halton', 'hammersly',"
                             "'random', or 'grid' not "
                             "%s." % generator)
    elif not isinstance(generator, InitialPointGenerator):
        raise ValueError("generator has to be an InitialPointGenerator."
                         "Got %s" % (str(type(generator))))

    if isinstance(generator, str):
        if generator == "sobol":
            generator = Sobol()
        elif generator == "halton":
            generator = Halton()
        elif generator == "hammersly":
            generator = Hammersly()
        elif generator == "lhs":
            generator = Lhs()
        elif generator == "grid":
            generator = Grid()
        elif generator == "random":
            return None
    generator.set_params(**kwargs)
    return generator

def get_features_with_cacheable_fixed_embeddings(
    feature_configs: list[FeatureConfigDict], metadata: TrainingSetMetadataDict
) -> list[FeatureConfigDict]:
    features_to_encode = []
    for feature_config in feature_configs:
        # deal with encoders that have fixed preprocessing
        if ENCODER in feature_config:
            encoder_params = feature_config[ENCODER]
            if TYPE in encoder_params:
                preprocessing = metadata[feature_config[NAME]][PREPROCESSING]
                if preprocessing.get("cache_encoder_embeddings"):
                    # TODO(travis): passing in MODEL_ECD is a hack here that can be removed once we move to using
                    # the config object everywhere in preprocessing. Then we won't need to do the lookup on the
                    # encoder schema at all.
                    encoder_class = get_encoder_cls(MODEL_ECD, feature_config[TYPE], encoder_params[TYPE])
                    encoder = encoder_class.from_dict(encoder_params)
                    if not encoder.can_cache_embeddings():
                        raise ValueError(
                            f"Set `cache_encoder_embeddings=True` for feature {feature_config[NAME]} with "
                            f"encoder {encoder_params[TYPE]}, but encoder embeddings are not static."
                        )

                    # Convert to Ray Datasets, map batches to encode, then convert back to Dask
                    features_to_encode.append(feature_config)

    return features_to_encode

def configure_logger(
    verbose: int = 0,
    tensorboard_log: str | None = None,
    tb_log_name: str = "",
    reset_num_timesteps: bool = True,
) -> Logger:
    save_path, format_strings = None, ["stdout"]

    if tensorboard_log is not None and SummaryWriter is None:
        raise ImportError("Trying to log data to tensorboard but tensorboard is not installed.")

    if tensorboard_log is not None and SummaryWriter is not None:
        latest_run_id = get_latest_run_id(tensorboard_log, tb_log_name)
        if not reset_num_timesteps:
            # Continue training in the same directory
            latest_run_id -= 1
        save_path = os.path.join(tensorboard_log, f"{tb_log_name}_{latest_run_id + 1}")
        if verbose >= 1:
            format_strings = ["stdout", "tensorboard"]
        else:
            format_strings = ["tensorboard"]
    elif verbose == 0:
        format_strings = [""]
    return configure(save_path, format_strings=format_strings)

def get_model_list(filename: str, start_prompt: str, end_prompt: str) -> str:
    with open(os.path.join(REPO_PATH, filename), "r", encoding="utf-8", newline="\n") as f:
        lines = f.readlines()
    # Find the start of the list.
    start_index = 0
    while not lines[start_index].startswith(start_prompt):
        start_index += 1
    start_index += 1

    result = []
    current_line = ""
    end_index = start_index

    # Keep going until the end of the list.
    while not lines[end_index].startswith(end_prompt):
        if lines[end_index].startswith("1."):
            if len(current_line) > 1:
                result.append(current_line)
            current_line = lines[end_index]
        elif len(lines[end_index]) > 1:
            current_line = f"{current_line[:-1]} {lines[end_index].lstrip()}"
        end_index += 1
    if len(current_line) > 1:
        result.append(current_line)

    return "".join(result)

def get_texture_storage(block_info: SBlockInfo):
    # certain limitation of the Qualcomm devices. Subject to be determined for certain device
    # individually, but until we have access to remote device during compilation, we have to
    # define it uniformly for all target devices
    # spatial_limit = 16384, depth_limit = 2048
    # TODO: Check Write Bufs.
    shape = block_info.write_bufs[0].buf_region.buffer.shape

    spatial_limit = Target.current().attrs["texture_spatial_limit"]
    depth_limit = Target.current().attrs["texture_depth_limit"]

    if len(shape) > 4:
        if shape[0] < spatial_limit and shape[1] * shape[2] * shape[3] < spatial_limit:
            return "global.texture-weight"
        elif shape[0] < depth_limit and shape[2] * shape[3] < spatial_limit:
            return "global.texture-nhwc"
        elif (
            shape[0] * shape[1] < depth_limit
            and shape[2] < spatial_limit
            and shape[3] < spatial_limit
        ):
            return "global.texture"
    elif len(shape) > 3:
        if shape[0] < spatial_limit and shape[1] * shape[2] < spatial_limit:
            return "global.texture-weight"
        elif shape[0] < depth_limit and shape[1] < spatial_limit and shape[2] < spatial_limit:
            return "global.texture"
    elif len(shape) == 3:
        if shape[0] < spatial_limit and shape[1] < spatial_limit:
            return "global.texture-weight"

    return "global"

def pad(self, *args, **kwargs):
        # For backward compatibility
        if self._in_target_context_manager:
            return self.current_processor.pad(*args, **kwargs)

        input_features = kwargs.pop("input_features", None)
        labels = kwargs.pop("labels", None)
        if len(args) > 0:
            input_features = args[0]
            args = args[1:]

        if input_features is not None:
            input_features = self.feature_extractor.pad(input_features, *args, **kwargs)
        if labels is not None:
            labels = self.tokenizer.pad(labels, **kwargs)

        if labels is None:
            return input_features
        elif input_features is None:
            return labels
        else:
            input_features["labels"] = labels["input_ids"]
            return input_features

def rename_multiindex(idx, feature_names_out, idx_name="index"):
    if feature_names_out == "multiindex":
        return idx
    elif feature_names_out == "flat":
        return flatten_multiindex(idx)
    elif feature_names_out == "original":
        if idx.get_level_values(-1).is_unique:
            return idx.get_level_values(-1)
        else:
            raise ValueError(
                'Error, resulting index names when using "original" naming '
                f"for {idx_name} contains non-unique elements."
            )
    elif feature_names_out == "auto":
        original = idx.get_level_values(-1)
        idx_out = original.copy().values.astype("str")
        if original.is_unique:
            return pd.Index(idx_out)

        flat = flatten_multiindex(idx)
        duplicated = original.duplicated(keep=False)

        idx_out[duplicated] = flat[duplicated]
        return pd.Index(idx_out)
    else:
        raise ValueError(
            "invalid value for feature_names_out in rename_multiindex, "
            'must be one of "flat", "multiindex", "original", "auto", '
            f"but found {feature_names_out}"
        )

def setItemSelected(self, item, state):
        # type: (ClusterGraphicsItem, bool) -> None
        if state is False and item not in self._selection or \
                state is True and item in self._selection:
            return  # State unchanged

        if item in self._selection:
            if state is False:
                self._remove_selection(item)
                self._re_enumerate_selections()
                self.selectionChanged.emit()
        else:
            # If item is already inside another selected item,
            # remove that selection
            super_selection = self._selected_super_item(item)

            if super_selection:
                self._remove_selection(super_selection)
            # Remove selections this selection will override.
            sub_selections = self._selected_sub_items(item)

            for sub in sub_selections:
                self._remove_selection(sub)

            if state:
                self._add_selection(item)

            elif item in self._selection:
                self._remove_selection(item)

            self._re_enumerate_selections()
            self.selectionChanged.emit()

def legalize_passes(target: tvm.target.Target):
    if target.kind.name == "cuda":
        return backend.cuda.legalize_passes(target)
    if target.kind.name == "rocm":
        return backend.rocm.legalize_passes(target)
    if target.kind.name == "metal":
        return backend.gpu_generic.legalize_passes(target)
    if target.kind.name == "llvm":
        return backend.cpu_generic.legalize_passes(target)
    if target.kind.name == "opencl" and "adreno" in target.keys:
        return backend.adreno.legalize_passes(target)
    if BackendDispatcher.is_gpu_target(target):
        return backend.gpu_generic.legalize_passes(target)
    raise ValueError(f"Target {target} is not yet supported by legalize passes.")

def ensure_correct_data_format(
    t_op: tflite_model.Operator, builder: model_builder.ModelBuilder, ops: OpsList
):

    if t_op.tmp_inputs[0].tensor_format == DataFormat.FORMATLESS:
        # Nothing to be done. All tensors should be formatless.
        return

    # Permute the inputs.
    for idx, tensor in enumerate(t_op.tmp_inputs.copy()):
        if tensor.tensor_format.is_channels_last():
            revert_perm = translator.create_channels_last_to_channels_first_permutation(
                tensor.rank, return_list=True
            )
            if tensor_has_data(tensor):
                translator.permute_static_tensor(tensor, revert_perm)

            else:
                # Prepend a Transpose operator.
                transpose = builder.create_transpose_operator_before(
                    t_op, idx, revert_perm
                )
                ops.pre_ops.append(transpose)

            t_op.tmp_inputs[idx].tensor_format = DataFormat.FORMATLESS

    # LSTM/RNN produces 'FORMATLESS' outputs. However, if the output tensors have the 'channels_last' format, Transpose
    #  operators must be added, to actually make the inputs 'channels_last'.
    for idx, tensor in enumerate(t_op.tmp_outputs.copy()):
        if tensor.tensor_format.is_channels_last():
            # Append a Transpose operator.
            revert_perm = translator.create_channels_first_to_channels_last_permutation(
                tensor.rank, return_list=True
            )
            transpose = builder.create_transpose_operator_after(t_op, idx, revert_perm)
            ops.post_ops.append(transpose)

            t_op.tmp_outputs[idx].tensor_format = DataFormat.FORMATLESS

def suffixes(inflections=[], n=3, top=10, reverse=True):
    # This is utility function we use to train singularize() and lemma()
    # in pattern.de, pattern.es, pattern.fr, etc.
    d = {}
    for x, y in (reverse and (y, x) or (x, y) for x, y in inflections):
        x0 = x[:-n]      # be-   jeu-  hautai-
        x1 = x[-n:]      # -aux  -nes  -nes
        y1 = y[len(x0):] # -au   -ne   -n
        if x0 + y1 != y:
            continue
        if x1 not in d:
            d[x1] = {}
        if y1 not in d[x1]:
            d[x1][y1] = 0.0
        d[x1][y1] += 1.0
    # Sort by frequency of inflected suffix: 2x -nes, 1x -aux.
    # Sort by frequency of base suffixes for each inflection:
    # [(2, "nes", [("ne", 0.5), ("n", 0.5)]), (1, "aux", [("au", 1.0)])]
    d = [(int(sum(y.values())), x, y.items()) for x, y in d.items()]
    d = sorted(d, reverse=True)
    d = ((n, x, (sorted(y, key=itemgetter(1)))) for n, x, y in d)
    d = ((n, x, [(y, m / n) for y, m in y]) for n, x, y in d)
    return list(d)[:top]

def mark_plot_labels(app, document):
    for name, explicit in document.nametypes.items():
        if not explicit:
            continue
        labelid = document.nameids[name]
        if labelid is None:
            continue
        node = document.ids[labelid]
        if node.tagname in ('html_only', 'latex_only'):
            for n in node:
                if n.tagname == 'figure':
                    sectname = name
                    for c in n:
                        if c.tagname == 'caption':
                            sectname = c.astext()
                            break

                    node['ids'].remove(labelid)
                    node['names'].remove(name)
                    n['ids'].append(labelid)
                    n['names'].append(name)
                    document.settings.env.labels[name] = \
                        document.settings.env.docname, labelid, sectname
                    break

def print_tree_deps_of(module, all_edges=None):
    if all_edges is None:
        all_edges = create_reverse_dependency_tree()
    tree = get_tree_starting_at(module, all_edges)

    # The list of lines is a list of tuples (line_to_be_printed, module)
    # Keeping the modules lets us know where to insert each new lines in the list.
    lines = [(tree[0], tree[0])]
    for index in range(1, len(tree)):
        edges = tree[index]
        start_edges = {edge[0] for edge in edges}

        for start in start_edges:
            end_edges = {edge[1] for edge in edges if edge[0] == start}
            # We will insert all those edges just after the line showing start.
            pos = 0
            while lines[pos][1] != start:
                pos += 1
            lines = lines[: pos + 1] + [(" " * (2 * index) + end, end) for end in end_edges] + lines[pos + 1 :]

    for line in lines:
        # We don't print the refs that where just here to help build lines.
        print(line[0])

def close(self):
        with self._lock:
            if self._mode == _MODE_CLOSED:
                return
            try:
                if self._mode in (_MODE_READ, _MODE_READ_EOF):
                    self._decompressor = None
                elif self._mode == _MODE_WRITE:
                    self._fp.write(self._compressor.flush())
                    self._compressor = None
            finally:
                try:
                    if self._closefp:
                        self._fp.close()
                finally:
                    self._fp = None
                    self._closefp = False
                    self._mode = _MODE_CLOSED
                    self._buffer = b""
                    self._buffer_offset = 0

def cmd_jobs(args) -> int:
    jobs_action = getattr(args, "jobs_action", None)

    # Default to list if no subcommand given
    if jobs_action is None or jobs_action == "list":
        return _jobs_list(args)
    elif jobs_action == "submit":
        return _jobs_submit(args)
    elif jobs_action == "cancel":
        return _jobs_cancel(args)
    elif jobs_action == "delete":
        return _jobs_delete(args)
    elif jobs_action == "retry":
        return _jobs_retry(args)
    elif jobs_action == "logs":
        return _jobs_logs(args)
    elif jobs_action == "get":
