def get_hard_samples(
    df: pd.DataFrame, errors_index: pd.Index, embs: np.ndarray, num_clusters: int = 10
) -> Tuple[pd.DataFrame, Any]:
    from sklearn.metrics.pairwise import cosine_similarity

    # Upper triangle of cosine similarity matrix
    sim = np.triu(cosine_similarity(embs))

    top_indexes = []
    for row_idx in range(sim.shape[0]):
        sorted_idxs = np.argsort(sim[row_idx], axis=0)[::-1]
        for idx in sorted_idxs[: num_clusters + 1]:
            # Skip rows similarity to itself
            if idx == row_idx:
                continue
            top_indexes.append([[row_idx, idx], sim[row_idx, idx]])
    # Get most similar pairs
    top_indexes = sorted(top_indexes, key=lambda x: x[1], reverse=True)
    df_indexes = []
    for i in range(len(top_indexes)):
        row_idx, col_idx = top_indexes[i][0]
        if (row_idx in errors_index or col_idx in errors_index) and (
            df.iloc[row_idx]["label_str"] != df.iloc[col_idx]["label_str"]
        ):
            if row_idx not in df_indexes:
                df_indexes.append(row_idx)
            if col_idx not in df_indexes:
                df_indexes.append(col_idx)
    return df.iloc[df_indexes[:num_clusters]], None

def json2csv_preprocess(
    json_file,
    outfile,
    fields,
    encoding="utf8",
    errors="replace",
    gzip_compress=False,
    skip_retweets=True,
    skip_tongue_tweets=True,
    skip_ambiguous_tweets=True,
    strip_off_emoticons=True,
    remove_duplicates=True,
    limit=None,
):
    with codecs.open(json_file, encoding=encoding) as fp:
        (writer, outf) = _outf_writer(outfile, encoding, errors, gzip_compress)
        # write the list of fields as header
        writer.writerow(fields)

        if remove_duplicates:
            tweets_cache = []
        i = 0
        for line in fp:
            tweet = json.loads(line)
            row = extract_fields(tweet, fields)
            try:
                text = row[fields.index("text")]
                # Remove retweets
                if skip_retweets:
                    if re.search(r"\bRT\b", text):
                        continue
                # Remove tweets containing ":P" and ":-P" emoticons
                if skip_tongue_tweets:
                    if re.search(r"\:\-?P\b", text):
                        continue
                # Remove tweets containing both happy and sad emoticons
                if skip_ambiguous_tweets:
                    all_emoticons = EMOTICON_RE.findall(text)
                    if all_emoticons:
                        if (set(all_emoticons) & HAPPY) and (set(all_emoticons) & SAD):
                            continue
                # Strip off emoticons from all tweets
                if strip_off_emoticons:
                    row[fields.index("text")] = re.sub(
                        r"(?!\n)\s+", " ", EMOTICON_RE.sub("", text)
                    )
                # Remove duplicate tweets
                if remove_duplicates:
                    if row[fields.index("text")] in tweets_cache:
                        continue
                    else:
                        tweets_cache.append(row[fields.index("text")])
            except ValueError:
                pass
            writer.writerow(row)
            i += 1
            if limit and i >= limit:
                break
        outf.close()

def register_schema(
    db_name: str,
    schema_base: DeclarativeMeta,
    entity_type: str = None,
    internal: bool = False,
):
    schemas = []
    for item in schema_base.registry.mappers:
        cls = item.class_
        if type(cls) == DeclarativeMeta:
            if zvt_context.dbname_map_schemas.get(db_name):
                schemas = zvt_context.dbname_map_schemas[db_name]
            zvt_context.schemas.append(cls)
            if issubclass(cls, Mixin):
                cls._zvt_db_name = db_name
                cls._zvt_internal = internal  # internal=True: business data, no external data source
            if entity_type:
                add_to_map_list(the_map=zvt_context.entity_map_schemas, key=entity_type, value=cls)
            schemas.append(cls)

    zvt_context.dbname_map_schemas[db_name] = schemas
    zvt_context.dbname_map_base[db_name] = schema_base
    if internal:
        zvt_context.internal_db_names.add(db_name)

def setup_decorator(method):
        def wrapper(self, *args, **kwargs):
            # Extract detections and image from args
            dets = args[0]
            img = args[1] if len(args) > 1 else None

            # Unwrap `data` attribute if present
            if hasattr(dets, "data"):
                dets = dets.data

            # Convert memoryview to numpy array if needed
            if isinstance(dets, memoryview):
                dets = np.array(dets, dtype=np.float32)  # Adjust dtype if needed

            # First-time detection setup
            if not self._first_dets_processed and dets is not None:
                layout = infer_detection_layout(dets)
                if layout is not None:
                    if layout.is_obb and not self.supports_obb:
                        raise AssertionError(
                            f"{self.__class__.__name__} does not support OBB detections. "
                            "Use an OBB-capable tracker such as ByteTrack, BotSort, OCSort, or SFSORT."
                        )
                    self._set_detection_mode(layout.is_obb)
                    self._first_dets_processed = True

            # First frame image-based setup
            if not self._first_frame_processed and img is not None:
                self.h, self.w = img.shape[0:2]
                self.asso_func = AssociationFunction(
                    w=self.w, h=self.h, asso_mode=self.asso_func_name
                ).asso_func
                self._first_frame_processed = True

            # Call the original method with the unwrapped `dets`
            return method(self, dets, img, *args[2:], **kwargs)

        return wrapper

def preprocess_arguments(argsets, converters):
    result = {}
    for argset in argsets:
        for argname, argval in argset.items():
            # check that this argument is necessary
            if argname not in converters:
                raise ValueError(f"Unrecognized argument: {argname}")

            # potentially use this argument
            if argname not in result and argval is not None:
                # convert to right type
                argval = converters[argname](argval)

                # save
                result[argname] = argval

    # check that all arguments are covered
    if not len(converters.keys()) == len(result.keys()):
        missing = set(converters.keys()) - set(result.keys())
        s = f"The following arguments are missing: {list(missing)}"
        raise ValueError(s)

    return result

def merge_containers(left: V1Container, right: V1Container) -> V1Container:
    merged = V1Container(name="")

    for attr, left_value in merged.__dict__.items():
        left_value = left.__dict__[attr]
        right_value = right.__dict__[attr]
        # Special case for 'command' attribute
        if attr == "_command":
            if left_value is not None:
                setattr(merged, attr, left_value)
            else:
                setattr(merged, attr, right_value)
            continue

        if left_value is not None:
            # For attributes that are lists
            if isinstance(
                    left_value,
                    list) and attr in right.__dict__ and isinstance(
                    right_value,
                    list):
                setattr(merged, attr, left_value +
                        [item for item in right_value if item not in left_value])

            # For attributes that are dicts
            elif isinstance(left_value, dict) and attr in right.__dict__ and isinstance(
                    right_value, dict):
                merged_dict = left_value.copy()
                for key, val in right_value.items():
                    if key not in merged_dict:
                        merged_dict[key] = val
                setattr(merged, attr, merged_dict)

            # For other attributes
            else:
                setattr(merged, attr, left_value)

        elif attr in right.__dict__ and right_value is not None:
            setattr(merged, attr, right_value)

    return merged

def parse_spacy(self, X):
        spacy = importlib.import_module("spacy")
        tagger = self.parser.split("_", 1)[1]
        nlp = spacy.load(tagger)

        if isinstance(X, list):
            for doc in X:
                tagged = nlp(doc)
                yield [
                    [(token.text, token.pos_) for token in sents]
                    for sents in tagged.sents
                ]
        elif isinstance(X, str):
            tagged = nlp(X)
            yield [
                [(token.text, token.pos_) for token in sents] for sents in tagged.sents
            ]

def validate_string_properties(
    properties: T,
    required_fields: list[str],
    optional_fields: list[str] | None = None,
) -> T:
    # Check that the required fields are present and not empty
    props_dict: dict[str, Any] = properties  # type: ignore[assignment]
    for field in required_fields:
        value = props_dict.get(field)
        if value is None or not value.strip():
            raise ValueError(f"{field} cannot be empty")

    # Check that optional fields are not empty if provided (but can be missing or None)
    if optional_fields:
        for field in optional_fields:
            value = props_dict.get(field)
            # If the field is present and not None, it must not be empty or whitespace-only
            if value is not None and not value.strip():
                raise ValueError(f"{field} if provided cannot be empty")

    # Check that there are no fields that shouldn't belong to the properties dictionary
    allowed_fields = set(required_fields)
    if optional_fields:
        allowed_fields.update(optional_fields)
    # spec_type is always allowed as it's present in all property TypedDicts
    allowed_fields.add("spec_type")

    for field in props_dict.keys():
        if field not in allowed_fields:
            raise ValueError(
                f"{field} is not a valid property for {type(properties).__name__}"
            )
    return properties

