def group_layers_by_attn_type(config: PreTrainedConfig) -> tuple[list[list[int]], list[str]]:
    # If the config has no layer_type attribute, it means all layers are the same attention type
    layer_types = getattr(config, "layer_types", None)
    if layer_types is None:
        attn_type = "sliding_attention" if getattr(config, "sliding_window", None) is not None else "full_attention"
        layer_types = [attn_type for _ in range(config.num_hidden_layers)]

    # We then count the number of layers of each type
    layer_counts = {}
    for i, layer_type in enumerate(layer_types):
        layer_counts[layer_type] = layer_counts.get(layer_type, []) + [i]

    # The size of all groups is the greatest common divisor of the number of layers of each type
    group_size = gcd(*[len(indices) for indices in layer_counts.values()])

    # We then group the layers by type
    layer_groups = []
    for layer_type, indices in layer_counts.items():
        for i in range(0, len(indices), group_size):
            layer_groups.append(indices[i : i + group_size])
    # And note the layer types
    group_types = [layer_types[lg[0]] for lg in layer_groups]
    return layer_groups, group_types

def reconstruct(data: tuple, wires: Wires, op_type: type[Operator], op_params: dict) -> Operator:
    if op_type not in _reconstructors and not op_type.resource_keys - {"num_wires"}:
        # Assume the default for simple gates. Since we don't actually have a Gate
        # class to use in an issubclass check, we use the resource_keys as a proxy.
        # A simple Gate wouldn't have any resource_keys defined. Another special case
        # is when an operator only has a single resource param that is the number of
        # wires. Such an operator also doesn't take anything beyond data and wires
        # in its constructor. The number of wires is typically redundant since this
        # information is apparant from the shape of the wires array already.
        return op_type(*data, wires=wires)

    if op_type is qml.ops.Adjoint:
        base_class, base_params = op_params["base_class"], op_params["base_params"]
        return qml.adjoint(reconstruct)(data, wires, base_class, base_params)

    if op_type is qml.ops.Controlled:
        # TODO: to be implemented in a follow-up PR [sc-110068]
        raise NotImplementedError  # pragma: no cover

    if issubclass(op_type, qml.ops.Pow):
        base_class, base_params = op_params["base_class"], op_params["base_params"]
        return qml.pow(reconstruct(data, wires, base_class, base_params), z=op_params["z"])

    if op_type in _reconstructors:
        return _reconstructors[op_type](*data, wires=wires, **op_params)

    raise NotImplementedError  # pragma: no cover

def fix_error(self, pred_transition, model, state):
        gold_transition = state.gold_sequence[state.num_transitions]
        if gold_transition == pred_transition:
            return self.repair_types.CORRECT, None

        for repair_type in self.repair_types:
            if repair_type.fn is None:
                continue
            if self.oracle_level is not None and repair_type.value > self.oracle_level and repair_type not in self.additional_levels and not repair_type.debug:
                continue
            if repair_type in self.deactivated_levels:
                continue
            repair = repair_type.fn(gold_transition, pred_transition, state.gold_sequence, state.num_transitions, self.root_labels, model, state)
            if repair is None:
                continue

            if isinstance(repair, tuple) and len(repair) == 2:
                return repair

            # TODO: could update all of the returns to be tuples of length 2
            if repair is not None:
                return repair_type, repair

        return self.repair_types.UNKNOWN, None

def fix_close_shift_ambiguous_later(gold_transition, pred_transition, gold_sequence, gold_index, root_labels, model, state):
    if not isinstance(pred_transition, Shift):
        return None

    if not isinstance(gold_transition, CloseConstituent):
        return None

    num_closes = 0
    while isinstance(gold_sequence[gold_index + num_closes], CloseConstituent):
        num_closes += 1

    if not isinstance(gold_sequence[gold_index + num_closes], Shift):
        # TODO: we should be able to handle this case too (an Open)
        # however, it will be rare once the parser gets going and it
        # would cause a lot of errors, anyway
        return None

    if isinstance(gold_sequence[gold_index + num_closes + 1], CloseConstituent):
        # this one should just have been satisfied in the non-ambiguous version
        return None

    # outer_close_index is now where the constituent which the broken constituent(s) reside inside gets closed
    outer_close_index = advance_past_constituents(gold_sequence, gold_index + num_closes)

    updated_sequence = gold_sequence[:gold_index] + gold_sequence[gold_index+num_closes:outer_close_index] + gold_sequence[gold_index:gold_index+num_closes] + gold_sequence[outer_close_index:]
    return updated_sequence

def json_friendly(  # noqa: C901
    obj: Any,
) -> tuple[Any, bool] | tuple[None | str | float, bool]:
    converted = True
    typename = get_full_typename(obj)

    if is_tf_eager_tensor_typename(typename):
        obj = obj.numpy()
    elif is_tf_tensor_typename(typename):
        try:
            obj = obj.eval()
        except RuntimeError:
            obj = obj.numpy()
    elif is_pytorch_tensor_typename(typename) or is_fastai_tensor_typename(typename):
        try:
            if obj.requires_grad:
                obj = obj.detach()
        except AttributeError:
            pass  # before 0.4 is only present on variables

        try:
            obj = obj.data
        except RuntimeError:
            pass  # happens for Tensors before 0.4

        if obj.size():
            obj = obj.cpu().detach().numpy()
        else:
            return obj.item(), True
    elif is_jax_tensor_typename(typename):
        obj = get_jax_tensor(obj)

    if is_numpy_array(obj):
        if obj.size == 1:
            obj = obj.flatten()[0]
        elif obj.size <= 32:
            obj = obj.tolist()
    elif np and isinstance(obj, np.generic):
        obj = _numpy_generic_convert(obj)
    elif isinstance(obj, bytes):
        obj = obj.decode("utf-8")
    elif isinstance(obj, (datetime, date)):
        obj = obj.isoformat()
    elif callable(obj):
        obj = (
            f"{obj.__module__}.{obj.__qualname__}"
            if hasattr(obj, "__qualname__") and hasattr(obj, "__module__")
            else str(obj)
        )
    elif isinstance(obj, float) and math.isnan(obj):
        obj = None
    elif isinstance(obj, dict) and np:
        obj, converted = _sanitize_numpy_keys(obj)
    elif isinstance(obj, set):
        # set is not json serializable, so we convert it to tuple
        obj = tuple(obj)
    elif isinstance(obj, enum.Enum):
        obj = obj.name
    else:
        converted = False
    if getsizeof(obj) > VALUE_BYTES_LIMIT:
        wandb.termwarn(
            f"Serializing object of type {type(obj).__name__} that is {getsizeof(obj)} bytes"
        )
    return obj, converted

def get_sdv_logger_config():
    store_path = Path(platformdirs.user_data_dir('sdv', 'sdv-dev'))
    config_path = Path(__file__).parent / 'sdv_logger_config.yml'
    logger_conf = {}

    try:
        store_path.mkdir(parents=True, exist_ok=True)

    except PermissionError:
        # No access to user's data.
        if os.access(config_path, os.W_OK):
            store_path = config_path.parent

        else:
            # No access to python env
            return logger_conf

    except OSError:
        # Read only system
        return logger_conf

    if (store_path / 'sdv_logger_config.yml').exists():
        config_path = store_path / 'sdv_logger_config.yml'

    elif os.access(store_path, os.W_OK):
        tmp_path = tempfile.mktemp(dir=store_path, suffix='.yml')
        shutil.copyfile(config_path, tmp_path)
        shutil.move(tmp_path, store_path / 'sdv_logger_config.yml')

    if os.access(config_path, os.R_OK):
        with open(config_path, 'r') as f:
            logger_conf = yaml.safe_load(f)

    for logger in logger_conf.get('loggers', {}).values():
        handler = logger.get('handlers', {})
        if handler.get('filename') == 'sdv_logs.csv':
            handler['filename'] = store_path / handler['filename']

    return logger_conf

def less_than(x, y):
        if isinstance(x, tuple) and isinstance(y, tuple):
            if len(x) < len(y):
                return True

            for a, b in zip(x, y):
                if a == b:
                    continue

                return less_than(a, b)

            return False

        if isinstance(x, tuple):
            return False

        if isinstance(y, tuple):
            return True

        return term_order[x] < term_order[y]

def generate_naive_order(self, mode):
        order = []
        if mode == "sendrecv":
            for i, (dst_tile, src_tiles,
                    _) in enumerate(self.dst_tile_to_src_tiles_map):
                for k, _ in enumerate(dst_tile.replica_device_strs):
                    for j, _ in enumerate(src_tiles):
                        order.append((i, k, j))
        elif mode == "broadcast":
            for i, (_, src_tiles,
                    _) in enumerate(self.dst_tile_to_src_tiles_map):
                for j, _ in enumerate(src_tiles):
                    order.append((i, j))
        else:
            raise NotImplementedError

        return order

def filter_pods(namespace: str,
                context: Optional[str],
                tag_filters: Dict[str, str],
                status_filters: Optional[List[str]] = None) -> Dict[str, Any]:
    non_included_pod_statuses = POD_STATUSES.copy()

    field_selector = ''
    if status_filters is not None:
        non_included_pod_statuses -= set(status_filters)
        field_selector = ','.join(
            [f'status.phase!={status}' for status in non_included_pod_statuses])

    label_selector = to_label_selector(tag_filters)
    pod_list = kubernetes.core_api(context).list_namespaced_pod(
        namespace, field_selector=field_selector, label_selector=label_selector)

    # Don't return pods marked for deletion,
    # i.e. pods with non-null metadata.DeletionTimestamp.
    pods = [
        pod for pod in pod_list.items if pod.metadata.deletion_timestamp is None
    ]

    # Sort pods by name, with workers sorted by their numeric suffix.
    # This ensures consistent ordering (e.g., cluster-head, cluster-worker1,
    # cluster-worker2, cluster-worker3, ...) even when Kubernetes API
    # returns them in arbitrary order. This works even if there were
    # somehow pod names other than head/worker ones, and those end up at
    # the end of the list.
    def get_pod_sort_key(
        pod: V1Pod
    ) -> Union[Tuple[Literal[0], str], Tuple[Literal[1], int], Tuple[Literal[2],
                                                                     str]]:
        name = pod.metadata.name
        name_suffix = name.split('-')[-1]
        if name_suffix == 'head':
            return (0, name)
        elif name_suffix.startswith('worker'):
            try:
                return (1, int(name_suffix.split('worker')[-1]))
            except (ValueError, IndexError):
                return (2, name)
        else:
            return (2, name)

    sorted_pods = sorted(pods, key=get_pod_sort_key)

    return {pod.metadata.name: pod for pod in sorted_pods}

def parse_simple_table(lines: list[str]) -> list[dict]:
    entries = []
    for line in lines:
        line = line.strip()
        if not line.startswith("|"):
            continue
        cells = [c.strip() for c in line.split("|")]
        cells = [c for c in cells if c != ""]
        if len(cells) < 1:
            continue
        name_cell = cells[0]
        if name_cell.startswith("-") or name_cell == "Name":
            continue

        m = RE_LINK.search(name_cell)
        if not m:
            continue
        name = m.group(1)
        url = m.group(2)

        entry: dict = {"name": name, "url": url}

        # Extract github from stars badge in second column
        full_line = line
        github = _extract_github(full_line)
        if github:
            entry["github"] = github

        entries.append(entry)
    return entries

def get_arg_tensor_source_repset(
        self, op_node: torch.fx.Node, arg_i: int
    ) -> utils.TensorRepSet:
        arg_node = op_node.args[arg_i]

        # For non-tensor arguments, return ALL_STORAGES_REPSET so that the respset does
        # not appear to be empty.
        if not utils.is_tensor_arg_node(arg_node):
            return utils.ALL_STORAGES_REPSET

        # Special case for cat - use the first tensor in the list as representative
        if isinstance(arg_node, list):
            arg_node = arg_node[0]

        if utils.has_node_repr(arg_node):
            arg_node_repr = utils.get_node_repr(arg_node)
            assert isinstance(arg_node_repr, utils.TensorRepr)
            return utils.make_tensor_repset(arg_node_repr)
        elif self.is_valid_op_node(arg_node):
            # Special case for getitem - propagate the node representation of the original node
            if op_node.target == operator.getitem:
                src_node = op_node.args[0]
                assert isinstance(src_node, torch.fx.Node)
                idx = op_node.args[1]
                assert isinstance(idx, int)

                src_node_repsets = self.get_node_cached_repsets(src_node)
                return src_node_repsets.get_out_repset(idx)

            src_node_repsets = self.get_node_cached_repsets(arg_node)
            return src_node_repsets.get_out_repset(0)

        # default return
        return utils.ANY_STORAGE

def benchmark_swarm_creation(
    swarm_types: List[str],
    num_iterations: int = 100,
    agents: List[Agent] = None,
) -> Dict[str, Dict[str, Any]]:
    if agents is None:
        agents = create_mock_agents()

    results = {}

    for swarm_type in swarm_types:
        print(f"Benchmarking {swarm_type}...")
        times = []

        for i in range(num_iterations):
            # Create a fresh SwarmRouter instance for each test
            router = SwarmRouter(
                name=f"test-router-{i}",
                agents=agents,
                swarm_type=swarm_type,
                telemetry_enabled=False,
            )

            # Time the _create_swarm method
            start_time = time.perf_counter()
            try:
                router._create_swarm(task="test task")
                end_time = time.perf_counter()
                times.append(end_time - start_time)
            except Exception as e:
                print(f"Failed to create {swarm_type}: {e}")
                continue

        if times:
            results[swarm_type] = {
                "mean_time": statistics.mean(times),
                "median_time": statistics.median(times),
                "min_time": min(times),
                "max_time": max(times),
                "std_dev": (
                    statistics.stdev(times) if len(times) > 1 else 0
                ),
                "total_iterations": len(times),
            }

    return results

def normalize_model_input(model,
                          model_revision,
                          third_party=None,
                          ignore_file_pattern=None):
    if isinstance(model, str) and is_official_hub_path(model, model_revision):
        # skip revision download if model is a local directory
        if not os.path.exists(model):
            # note that if there is already a local copy, snapshot_download will check and skip downloading
            user_agent = {Invoke.KEY: Invoke.PIPELINE}
            if third_party is not None:
                user_agent[ThirdParty.KEY] = third_party
            model = snapshot_download(
                model,
                revision=model_revision,
                user_agent=user_agent,
                ignore_file_pattern=ignore_file_pattern)
    elif isinstance(model, list) and isinstance(model[0], str):
        for idx in range(len(model)):
            if is_official_hub_path(
                    model[idx],
                    model_revision) and not os.path.exists(model[idx]):
                user_agent = {Invoke.KEY: Invoke.PIPELINE}
                if third_party is not None:
                    user_agent[ThirdParty.KEY] = third_party
                model[idx] = snapshot_download(
                    model[idx], revision=model_revision, user_agent=user_agent)
    return model

def create_markdown(module: DocumentedModule) -> Path:
    md_filepath = REFERENCE_DIR / module.path.relative_to(PACKAGE_DIR).with_suffix(".md")
    exists = md_filepath.exists()

    header_content = ""
    if exists:
        for part in md_filepath.read_text().split("---"):
            if "description:" in part or "comments:" in part:
                header_content += f"---{part}---\n\n"
    if not header_content:
        header_content = "---\ndescription: TODO ADD DESCRIPTION\nkeywords: TODO ADD KEYWORDS\n---\n\n"

    module_path_fs = module.module_path.replace(".", "/")
    url = f"https://github.com/{GITHUB_REPO}/blob/main/{module_path_fs}.py"
    pretty = url.replace("__init__.py", "\\_\\_init\\_\\_.py")  # Properly display __init__.py filenames

    title_content = f"# Reference for `{module_path_fs}.py`\n\n" + contribution_admonition(
        pretty, url, kind="success", title="Improvements"
    )

    md_filepath.parent.mkdir(parents=True, exist_ok=True)
    md_filepath.write_text(header_content + title_content + render_module_markdown(module))

    if not exists:
        subprocess.run(["git", "add", "-f", str(md_filepath)], check=True, cwd=REPO_ROOT)

    return _relative_to_workspace(md_filepath)

def after_evaluation(self, current_model_is_best, validation_scores, **kw):
        reduced_learning_rate: bool = self.scheduler.step(*validation_scores)

        # Save scheduler state after step
        if hasattr(self.trainer.model, "save_optimizer_state") and self.trainer.model.save_optimizer_state:
            self.trainer.model.scheduler_state_dict = self.scheduler.state_dict()

        self.store_learning_rate()

        bad_epochs = self.scheduler.num_bad_epochs
        if reduced_learning_rate:
            bad_epochs = self.patience + 1
            log.info(
                f" - {bad_epochs} epochs without improvement (above 'patience')"
                f"-> annealing learning_rate to {self.current_learning_rate}"
            )
        else:
            log.info(f" - {bad_epochs} epochs without improvement")

        self.trainer.dispatch(
            "metric_recorded",
            MetricRecord.scalar(name="bad_epochs", value=bad_epochs, global_step=self.scheduler.last_epoch + 1),
        )

        # stop training if learning rate becomes too small
        for lr in self.current_learning_rate:
            if lr < self.min_learning_rate:
                raise TrainingInterrupt("learning rate too small - quitting training!")

        # reload last best model if annealing with restarts is enabled
        if self.anneal_with_restarts and reduced_learning_rate and os.path.exists(self.base_path / "best-model.pt"):
            log.info("resetting to best model")
            self.model.load_state_dict(self.model.load(self.base_path / "best-model.pt").state_dict())

