def fix_close_shift_ambiguous_immediate(gold_transition, pred_transition, gold_sequence, gold_index, root_labels, model, state):
    if not isinstance(pred_transition, Shift):
        return None

    if not isinstance(gold_transition, CloseConstituent):
        return None

    num_closes = 0
    while isinstance(gold_sequence[gold_index + num_closes], CloseConstituent):
        num_closes += 1

    if not isinstance(gold_sequence[gold_index + num_closes], Shift):
        # TODO: we should be able to handle this case too (an Open)
        # however, it will be rare once the parser gets going and it
        # would cause a lot of errors, anyway
        return None

    if isinstance(gold_sequence[gold_index + num_closes + 1], CloseConstituent):
        # this one should just have been satisfied in the non-ambiguous version
        return None

    updated_sequence = gold_sequence[:gold_index] + [pred_transition] + gold_sequence[gold_index:gold_index+num_closes] + gold_sequence[gold_index+num_closes+1:]
    return updated_sequence

def download(self) -> None:
        if self._check_exists():
            return

        os.makedirs(self.raw_folder, exist_ok=True)

        # download files
        for filename, md5 in self.resources:
            errors = []
            for mirror in self.mirrors:
                url = f"{mirror}{filename}?raw=true"
                try:
                    datasets.utils.download_and_extract_archive(
                        url, download_root=self.raw_folder, filename=filename, md5=md5
                    )
                except datasets.URLError as e:
                    errors.append(e)
                    continue
                break
            else:
                s = f"Error downloading {filename}:\n"
                for mirror, err in zip(self.mirrors, errors):
                    s += f"Tried {mirror}, got:\n{str(err)}\n"
                raise RuntimeError(s)

def map(self, fn, *iterables, **kwargs):
        timeout = kwargs.get('timeout')
        if timeout is not None:
            end_time = timeout + time.time()

        fs = [self.submit(fn, *args) for args in itertools.izip(*iterables)]

        # Yield must be hidden in closure so that the futures are submitted
        # before the first iterator value is required.
        def result_iterator():
            try:
                for future in fs:
                    if timeout is None:
                        yield future.result()
                    else:
                        yield future.result(end_time - time.time())
            finally:
                for future in fs:
                    future.cancel()
        return result_iterator()

def from_model_config(cls, model_config: Union["PreTrainedConfig", dict]) -> "GenerationConfig":
        config_dict = model_config.to_dict() if not isinstance(model_config, dict) else model_config
        config_dict.pop("_from_model_config", None)

        # Removes all `None` from the model config dict -- this lets the generation config defaults to take hold
        config_dict = {key: value for key, value in config_dict.items() if value is not None}
        generation_config = cls.from_dict(config_dict, return_unused_kwargs=False, _from_model_config=True)

        # Special case: some models have generation attributes set in the decoder. Use them if still unset in the
        # generation config (which in turn is defined from the outer attributes of model config).
        if isinstance(model_config, dict):
            decoder_possible_text_config_names = ("decoder", "generator", "text_config")
            for text_config_name in decoder_possible_text_config_names:
                if text_config := model_config.get(text_config_name):
                    model_config = text_config
                    break
        else:
            model_config = model_config.get_text_config(decoder=True)
            model_config = model_config.to_dict()

        default_generation_config = GenerationConfig()
        for attr in generation_config.to_dict():
            is_unset = getattr(generation_config, attr) == getattr(default_generation_config, attr)
            if attr in model_config and is_unset:
                setattr(generation_config, attr, model_config[attr])

        # If any `output_...` flag is set to `True`, we ensure `return_dict_in_generate` is set to `True`.
        if not generation_config.return_dict_in_generate:
            if any(
                getattr(generation_config, extra_output_flag, False)
                for extra_output_flag in generation_config.extra_output_flags
            ):
                generation_config.return_dict_in_generate = True

        # Hash to detect whether the instance was modified
        generation_config._original_object_hash = hash(generation_config)
        return generation_config

def get_layer_construction_costs(jaxpr, cost_criteria="flops"):
    nontrivial = np.array([is_nontrivial(eqn) for eqn in jaxpr.eqns],
                          dtype=np.int32)
    input_sizes = jaxpr_eqns_input_sizes(jaxpr)
    if cost_criteria == "flops":
        compute_costs = np.array([
            eqn_flops(eqn) if nt else 0
            for nt, eqn in zip(nontrivial, jaxpr.eqns)
        ],
                                 dtype=np.float64)
    elif cost_criteria == "count":
        compute_costs = np.array([
            heavy_count(eqn) if nt else 0
            for nt, eqn in zip(nontrivial, jaxpr.eqns)
        ],
                                 dtype=np.float64)
    elif cost_criteria == "input_memory":
        cost_fn = partial(global_invar_size, set(jaxpr.jaxpr.invars))
        compute_costs = np.array([cost_fn(eqn) for eqn in jaxpr.eqns],
                                 dtype=np.float64)
    else:
        raise ValueError(f"Unrecoginzed cost criteria {cost_criteria}")
    return nontrivial, input_sizes, compute_costs

def variables(self, ourself=False, expand_virtual=True, include_virtual=True):
        variables = set()
        def record(varname):
            # always do this for selection
            if self._selection and self.df.has_selection(varname):
                selection = self.df.get_selection(varname)
                variables.update(selection.dependencies(self.df))
            # do this recursively for virtual columns
            if varname in self.ds.virtual_columns and varname not in variables:
                if (include_virtual and (varname != self.expression)) or (varname == self.expression and ourself):
                    variables.add(varname)
                if expand_virtual:
                    variables.update(self.df[self.df.virtual_columns[varname]].variables(ourself=include_virtual, include_virtual=include_virtual))
            # we usually don't want to record ourself
            elif varname != self.expression or ourself:
                variables.add(varname)

        expresso.translate(self.ast, record)
        # df is a buildin, don't record it, if df is a column name, it will be collected as
        # df['df']
        variables -= {'df'}
        for varname in self._ast_slices:
            if varname in self.df.virtual_columns and varname not in variables:
                if (include_virtual and (f"df['{varname}']" != self.expression)) or (f"df['{varname}']" == self.expression and ourself):
                    variables.add(varname)
                if expand_virtual:
                    if varname in self.df.virtual_columns:
                        variables |= self.df[self.df.virtual_columns[varname]].variables(ourself=include_virtual, include_virtual=include_virtual)
            elif f"df['{varname}']" != self.expression or ourself:
                variables.add(varname)

        return variables

def cycler(*args, **kwargs):
    if args and kwargs:
        raise TypeError("cycler() can only accept positional OR keyword "
                        "arguments -- not both.")
    elif not args and not kwargs:
        raise TypeError("cycler() must have positional OR keyword arguments")

    if len(args) == 1:
        if not isinstance(args[0], Cycler):
            raise TypeError("If only one positional argument given, it must "
                            "be a Cycler instance.")
        return validate_cycler(args[0])
    elif len(args) == 2:
        pairs = [(args[0], args[1])]
    elif len(args) > 2:
        raise _api.nargs_error('cycler', '0-2', len(args))
    else:
        pairs = kwargs.items()

    validated = []
    for prop, vals in pairs:
        norm_prop = _prop_aliases.get(prop, prop)
        validator = _prop_validators.get(norm_prop, None)
        if validator is None:
            raise TypeError("Unknown artist property: %s" % prop)
        vals = validator(vals)
        # We will normalize the property names as well to reduce
        # the amount of alias handling code elsewhere.
        validated.append((norm_prop, vals))

    return reduce(operator.add, (ccycler(k, v) for k, v in validated))

def convert_json_field_to_pandas_type(field) -> str | CategoricalDtype:
    typ = field["type"]
    if typ == "string":
        return field.get("extDtype", None)
    elif typ == "integer":
        return field.get("extDtype", "int64")
    elif typ == "number":
        return field.get("extDtype", "float64")
    elif typ == "boolean":
        return field.get("extDtype", "bool")
    elif typ == "duration":
        return "timedelta64"
    elif typ == "datetime":
        if field.get("tz"):
            return f"datetime64[ns, {field['tz']}]"
        elif field.get("freq"):
            # GH#9586 rename frequency M to ME for offsets
            offset = to_offset(field["freq"])
            freq = PeriodDtype(offset)._freqstr
            # GH#47747 using datetime over period to minimize the change surface
            return f"period[{freq}]"
        else:
            return "datetime64[ns]"
    elif typ == "any":
        if "constraints" in field and "ordered" in field:
            return CategoricalDtype(
                categories=field["constraints"]["enum"], ordered=field["ordered"]
            )
        elif "extDtype" in field:
            return registry.find(field["extDtype"])
        else:
            return "object"

    raise ValueError(f"Unsupported or invalid field type: {typ}")

def get_pip_config_args() -> dict[str, str | list[str]]:
    key_map = {
        "global.index-url": "index_url",
        "global.extra-index-url": "extra_index_url",
        "global.trusted-host": "trusted_host",
        "global.find-links": "find_links",
    }

    try:
        result = subprocess.run(
            [sys.executable, "-m", "pip", "config", "list"],
            capture_output=True,
            text=True,
            check=True,
        )
        args: dict[str, str | list[str]] = {}
        for line in result.stdout.splitlines():
            if "=" not in line:
                continue
            raw_key, raw_value = line.split("=", 1)
            key = raw_key.strip()
            value = raw_value.strip().strip("'\"")
            mapped_key = key_map.get(key)
            if mapped_key and value:
                if mapped_key in ("extra_index_url", "find_links", "trusted_host"):
                    existing = args.get(mapped_key)
                    if existing is None:
                        args[mapped_key] = value
                    elif isinstance(existing, list):
                        existing.append(value)
                    else:
                        args[mapped_key] = [existing, value]
                else:
                    args[mapped_key] = value

        return args
    except subprocess.CalledProcessError:
        return {}

def data_to_batches(data, batch_size, eval_mode, sort_during_eval, min_length_to_batch_separately):
    res = []

    if not eval_mode:
        # sort sentences (roughly) by length for better memory utilization
        data = sorted(data, key = lambda x: len(x[0]), reverse=random.random() > .5)
        data_orig_idx = None
    elif sort_during_eval:
        (data, ), data_orig_idx = sort_all([data], [len(x[0]) for x in data])
    else:
        data_orig_idx = None

    current = []
    currentlen = 0
    for x in data:
        if min_length_to_batch_separately is not None and len(x[0]) > min_length_to_batch_separately:
            if currentlen > 0:
                res.append(current)
                current = []
                currentlen = 0
            res.append([x])
        else:
            if len(x[0]) + currentlen > batch_size and currentlen > 0:
                res.append(current)
                current = []
                currentlen = 0
            current.append(x)
            currentlen += len(x[0])

    if currentlen > 0:
        res.append(current)

    return res, data_orig_idx

def save_artifacts(self, artifacts_iter, len_hint=0):
        artifact_names = []

        def pickle_iter():
            for name, obj in artifacts_iter:
                encode_type = "gzip+pickle-v4"
                if encode_type in self._encodings:
                    try:
                        blob = pickle.dumps(obj, protocol=4)
                    except TypeError as e:
                        raise UnpicklableArtifactException(name) from e
                else:
                    try:
                        blob = pickle.dumps(obj, protocol=2)
                        encode_type = "gzip+pickle-v2"
                    except (SystemError, OverflowError) as e:
                        raise DataException(
                            "Artifact *%s* is very large (over 2GB). "
                            "You need to use Python 3.6 or newer if you want to "
                            "serialize large objects." % name
                        ) from e
                    except TypeError as e:
                        raise UnpicklableArtifactException(name) from e

                self._info[name] = {
                    "size": len(blob),
                    "type": str(type(obj)),
                    "encoding": encode_type,
                }

                artifact_names.append(name)
                yield blob

        # Use the content-addressed store to store all artifacts
        save_result = self._ca_store.save_blobs(pickle_iter(), len_hint=len_hint)
        for name, result in zip(artifact_names, save_result):
            self._objects[name] = result.key

def get_weight_norm(parameters, norm_type=2, mpu=None):
    if isinstance(parameters, torch.Tensor):
        parameters = [parameters]

    norm_type = float(norm_type)
    if norm_type == inf:
        total_norm = max(p.data.abs().max() for p in parameters)
        total_norm_cuda = get_accelerator().FloatTensor([float(total_norm)])
        # Take max across all GPUs.
        if mpu is not None:
            dist.all_reduce(total_norm_cuda, op=dist.ReduceOp.MAX, group=mpu.get_model_parallel_group())
        total_norm = total_norm_cuda[0].item()
    else:
        total_norm = 0.
        tensor_mp_rank = bwc_tensor_model_parallel_rank(mpu=mpu)
        for p in parameters:
            # Pipeline parallelism may replicate parameters. Avoid multi-counting.
            if hasattr(p, PIPE_REPLICATED) and p.ds_pipe_replicated:
                continue

            # Filter to avoid over-counting replicated tensors from tensor
            # model parallelism
            if (tensor_mp_rank > 0) and not is_model_parallel_parameter(p):
                continue

            param_norm = p.data.float().norm(norm_type)
            total_norm += param_norm**norm_type

        # Sum across all model parallel GPUs.
        total_norm_cuda = get_accelerator().FloatTensor([float(total_norm)])
        if mpu is not None:
            dist.all_reduce(total_norm_cuda, op=dist.ReduceOp.SUM, group=mpu.get_model_parallel_group())
        total_norm = total_norm_cuda[0].item()**(1. / norm_type)

    if total_norm == float('inf') or total_norm == -float('inf') or total_norm != total_norm:
        total_norm = -1

    return total_norm

def should_redact_header(key: str) -> bool:
    key = key.lower()
    if key in {"authorization", "traceparent", "via"}:
        return True
    if key.startswith("x-forwarded"):
        return True
    if key.startswith("x-b3"):
        return True
    if key.startswith("x-cloud-trace"):
        return True
    if key.startswith("x-envoy"):
        return True
    if key.startswith("x-prefect"):
        return True

    return False

def generate_composer_model_policy(composer_model: ComposerModel) -> CustomPolicy:
    # Filter the specific deprecation warning to only appear once.
    warnings.filterwarnings(
        'once',
        category=DeprecationWarning,
        message='The _fsdp_wrap attribute will be removed in a future release. Please use fsdp_wrap_fn instead.',
    )

    cached_submodules_to_wrap: dict[nn.Module, bool | dict[str, Any]] = {composer_model: False}
    for child in composer_model.children():
        if isinstance(child, Metric | MetricCollection):
            for module in child.modules():
                cached_submodules_to_wrap[module] = False
            continue
        # this can be overwritten by the _fsdp_wrap attribute or fsdp_wrap_fn
        cached_submodules_to_wrap[child] = True
        fsdp_wrap_fn = getattr(child, 'fsdp_wrap_fn', lambda x: cached_submodules_to_wrap.get(x, False))
        for child_module in child.modules():
            if hasattr(child_module, '_fsdp_wrap'):
                warnings.warn(
                    DeprecationWarning(
                        'The _fsdp_wrap attribute will be removed in a future release. Please use fsdp_wrap_fn instead.',
                    ),
                )
                cached_submodules_to_wrap[child_module] = bool(child_module._fsdp_wrap)
            elif child_module is child:
                continue
            else:
                res = fsdp_wrap_fn(child_module)
                if isinstance(res, dict) and not set(res.keys()).issubset(FSDP2Config.settable_attrs()):
                    raise KeyError(
                        f'Invalid FSDP2 config keys in wrap_fn return value. Valid keys are: {FSDP2Config.settable_attrs()}',
                    )
                cached_submodules_to_wrap[child_module] = res

    def lambda_fn(current_module: nn.Module) -> bool | dict[str, Any]:
        return cached_submodules_to_wrap.get(current_module, False)

    return CustomPolicy(lambda_fn)

def train_on_batch(self, *args):
        log.debug(f'Training for {args}')
        error_msg = f'Len of arguments {len(args)} is WRONG. ' \
                    f'Correct is {2 * self.n_tasks} as n_tasks is {self.n_tasks}'
        if len(args) != 2 * self.n_tasks:
            raise Exception(error_msg)
        ids_to_iterate = [k for k in range(self.n_tasks) if len(args[k]) > 0]
        if len(ids_to_iterate) == 0:
            raise Exception(f'No examples given! Given args {args}')
        elif len(ids_to_iterate) > 1:
            raise Exception('Samples from more than 1 task in train_on_batch')
        task_id = ids_to_iterate[0]
        _input, batch_size = self._make_input(task_features=args[task_id], task_id=task_id,
                                              labels=args[task_id + self.n_tasks])
        if _input == {}:
            raise Exception('Empty input!')

        if self.prev_id is None:
            self.prev_id = task_id
        elif self.prev_id != task_id and not self.printed:
            log.info('Seen samples from different tasks')
            self.printed = True
        if 'token_type_ids' not in _input:
            _input['token_type_ids'] = None
        loss, logits = self.model(task_id=task_id, **_input)
        if self.is_data_parallel:
            loss = loss.mean()
        loss = loss / self.gradient_accumulation_steps
        loss.backward()

        # Clip the norm of the gradients to 1.0.
        # This is to help prevent the "exploding gradients" problem.
        if self.clip_norm:
            torch.nn.utils.clip_grad_norm_(self.model.parameters(), self.clip_norm)

        if (self.steps_taken + 1) % self.gradient_accumulation_steps == 0 or (
                self.steps_per_epoch is not None and (self.steps_taken + 1) % self.steps_per_epoch == 0):
            self.optimizer.step()
            self.optimizer.zero_grad()
        self.train_losses[task_id] = loss.item()
        self.steps_taken += 1
        log.debug(f'train {task_id} {logits}')
        return {"losses": self.train_losses}

def allocate_hexagon_array(
    dev, tensor_shape=None, dtype=None, data=None, axis_separators=None, mem_scope=None
):
    if tensor_shape is None:
        assert data is not None, "Must provide either tensor shape or numpy data array"
        tensor_shape = data.shape
    elif data is not None:
        assert tensor_shape == data.shape, (
            "Mismatch between provided tensor shape and numpy data array shape"
        )

    if dtype is None:
        assert data is not None, "Must provide either dtype or numpy data array"
        dtype = data.dtype.name
    elif data is not None:
        assert dtype == data.dtype, "Mismatch between provided dtype and numpy data array dtype"

    if axis_separators is None:
        axis_separators = []

    boundaries = [0, *axis_separators, len(tensor_shape)]
    physical_shape = [
        numpy.prod(tensor_shape[dim_i:dim_f]) for dim_i, dim_f in itertools.pairwise(boundaries)
    ]

    arr = tvm.runtime.empty(physical_shape, dtype=dtype, device=dev, mem_scope=mem_scope)

    if data is not None:
        arr.copyfrom(data.reshape(physical_shape))

    return arr._create_view(tensor_shape)

def require_version(requirement: str, hint: str | None = None) -> None:
    hint = f"\n{hint}" if hint is not None else ""

    # non-versioned check
    if re.match(r"^[\w_\-\d]+$", requirement):
        pkg, op, want_ver = requirement, None, None
    else:
        match = re.findall(r"^([^!=<>\s]+)([\s!=<>]{1,2}.+)", requirement)
        if not match:
            raise ValueError(
                "requirement needs to be in the pip package format, .e.g., package_a==1.23, or package_b>=1.23, but"
                f" got {requirement}"
            )
        pkg, want_full = match[0]
        want_range = want_full.split(",")  # there could be multiple requirements
        wanted = {}
        for w in want_range:
            match = re.findall(r"^([\s!=<>]{1,2})(.+)", w)
            if not match:
                raise ValueError(
                    "requirement needs to be in the pip package format, .e.g., package_a==1.23, or package_b>=1.23,"
                    f" but got {requirement}"
                )
            op, want_ver = match[0]
            wanted[op] = want_ver
            if op not in ops:
                raise ValueError(f"{requirement}: need one of {list(ops.keys())}, but got {op}")

    # special case
    if pkg == "python":
        got_ver = ".".join([str(x) for x in sys.version_info[:3]])
        for op, want_ver in wanted.items():
            _compare_versions(op, got_ver, want_ver, requirement, pkg, hint)
        return

    # check if any version is installed
    try:
        got_ver = importlib.metadata.version(pkg)
    except importlib.metadata.PackageNotFoundError:
        raise importlib.metadata.PackageNotFoundError(
            f"The '{requirement}' distribution was not found and is required by this application. {hint}"
        )

    # check that the right version is installed if version number or a range was provided
    if want_ver is not None:
        for op, want_ver in wanted.items():
            _compare_versions(op, got_ver, want_ver, requirement, pkg, hint)

def resolve_command(
        self, ctx: click.Context, args: list[str]
    ) -> tuple[str | None, click.Command | None, list[str]]:
        cmd_name = make_str(args[0])
        original_cmd_name = cmd_name

        cmd = self.get_command(ctx, cmd_name)
        if cmd is None and ctx.token_normalize_func is not None:
            cmd_name = ctx.token_normalize_func(cmd_name)
            cmd = self.get_command(ctx, cmd_name)

        if cmd is None and not ctx.resilient_parsing:
            if _split_option_token(cmd_name)[0]:
                self.parse_args(ctx, args)

            command_names: list[str] = []
            for name in self.list_commands(ctx):
                command = self.get_command(ctx, name)
                if command is None or command.hidden:
                    continue
                command_names.append(name)
            suggestions = suggest_commands(original_cmd_name, command_names)
            if len(suggestions) == 1:
                ctx.fail(
                    f"unrecognized command {original_cmd_name!r}\n\n"
                    f"  tip: a similar command exists: {suggestions[0]!r}"
                )
            if len(suggestions) > 1:
                joined = ", ".join(repr(item) for item in suggestions)
                ctx.fail(
                    f"unrecognized command {original_cmd_name!r}\n\n"
                    f"  tip: some similar commands exist: {joined}"
                )
            ctx.fail(f"unrecognized command {original_cmd_name!r}")

        return cmd_name if cmd else None, cmd, args[1:]

def forward(self, code: str, timeout: int = 20, **kwargs) -> CodeToolOutput:
        id = kwargs.get("id", None)
        max_retries = kwargs.get("max_retries", 3)

        if id:
            self.cur_sandbox_idx = id % self.n_sandboxes
        else:
            # Round-robin distribution
            self.cur_sandbox_idx = (self.cur_sandbox_idx + 1) % self.n_sandboxes
        sandbox = self.sandboxes[self.cur_sandbox_idx]

        while max_retries > 0:
            try:
                execution = sandbox.run_code(code, timeout=timeout)
                break
            except Exception:
                max_retries -= 1
                if max_retries == 0:
                    self._restart_sandbox(self.cur_sandbox_idx)
                    return CodeToolOutput(name=self.name or "e2b_python", error="Sandbox error, please try again.")

        # Create a CodeToolOutput object instead of a dictionary
        result = None
        stdout = None
        stderr = None

        if execution.results:
            assert len(execution.results) == 1, "Only one result is supported"
            result = execution.results[0].text

        if execution.logs:
            assert len(execution.logs.stdout) == 1, "Only one stdout is supported"
            stdout = execution.logs.stdout[0]

        if execution.error:
            stderr = f"{execution.error.traceback}"

        return CodeToolOutput(name=self.name or "e2b_python", stdout=stdout or None, stderr=stderr or None, output=result or None)

def add_node(node, parents, dag):
            if type(node) == str:
                task = self.states[node].to_task()
                if parents:
                    for parent in parents:
                        # Handle foreach nodes.
                        if self.states[node].is_mapper_node:
                            task = task.expand(mapper_arr=XComArg(parent))
                        parent >> task
                return [task]  # Return Parent

            # this means a split from parent
            if type(node) == list:
                # this means branching since everything within the list is a list
                if all(isinstance(n, list) for n in node):
                    curr_parents = parents
                    parent_list = []
                    for node_list in node:
                        last_parent = add_node(node_list, curr_parents, dag)
                        parent_list.extend(last_parent)
                    return parent_list
                else:
                    # this means no branching and everything within the list is not a list and can be actual nodes.
                    curr_parents = parents
                    for node_x in node:
                        curr_parents = add_node(node_x, curr_parents, dag)
                    return curr_parents

def prompt_builder_from_id(prompt_id: PromptId, task: Task) -> BasePromptBuilder:
    # Saved prompts are prefixed with "id::"
    if prompt_id.startswith("id::"):
        prompt_id = prompt_id[4:]
        return SavedPromptBuilder(task, prompt_id)

    # Task run config prompts are prefixed with "task_run_config::"
    # task_run_config::[project_id]::[task_id]::[run_config_id]
    if prompt_id.startswith("task_run_config::"):
        return TaskRunConfigPromptBuilder(task, prompt_id)

    # Fine-tune prompts are prefixed with "fine_tune_prompt::"
    if prompt_id.startswith("fine_tune_prompt::"):
        prompt_id = prompt_id[18:]
        return FineTunePromptBuilder(task, prompt_id)

    # Check if the prompt_id matches any enum value
    if prompt_id not in [member.value for member in PromptGenerators]:
        raise ValueError(f"Unknown prompt generator: {prompt_id}")
    typed_prompt_generator = PromptGenerators(prompt_id)

    match typed_prompt_generator:
        case PromptGenerators.SIMPLE:
            return SimplePromptBuilder(task)
        case PromptGenerators.FEW_SHOT:
            return FewShotPromptBuilder(task)
        case PromptGenerators.MULTI_SHOT:
            return MultiShotPromptBuilder(task)
        case PromptGenerators.REPAIRS:
            return RepairsPromptBuilder(task)
        case PromptGenerators.SIMPLE_CHAIN_OF_THOUGHT:
            return SimpleChainOfThoughtPromptBuilder(task)
        case PromptGenerators.FEW_SHOT_CHAIN_OF_THOUGHT:
            return FewShotChainOfThoughtPromptBuilder(task)
        case PromptGenerators.MULTI_SHOT_CHAIN_OF_THOUGHT:
            return MultiShotChainOfThoughtPromptBuilder(task)
        case _:
            # Type checking will find missing cases
            raise_exhaustive_enum_error(typed_prompt_generator)

def get_field_value(
        self, field: FieldInfo, field_name: str
    ) -> Tuple[Any, str, bool]:
        if field.validation_alias:
            # Use validation alias as the key to ensure profile value does not
            # higher priority sources. Lower priority sources that use the
            # field name can override higher priority sources that use the
            # validation alias as seen in https://github.com/PrefectHQ/prefect/issues/15981
            if isinstance(field.validation_alias, str):
                value = self.profile_settings.get(field.validation_alias.upper())
                if value is not None:
                    return value, field.validation_alias, self.field_is_complex(field)
            elif isinstance(field.validation_alias, AliasChoices):
                value = None
                lowest_priority_alias = next(
                    choice
                    for choice in reversed(field.validation_alias.choices)
                    if isinstance(choice, str)
                )
                for alias in field.validation_alias.choices:
                    if not isinstance(alias, str):
                        continue
                    value = self.profile_settings.get(alias.upper())
                    if value is not None:
                        return (
                            value,
                            lowest_priority_alias,
                            self.field_is_complex(field),
                        )

        name = f"{self.config.get('env_prefix', '')}{field_name.upper()}"
        value = self.profile_settings.get(name)
        return value, field_name, self.field_is_complex(field)

def generate_prefixed_scalar(self) -> list[dict[str, int]]:
        # Generate dense metrics if applicable
        dense_metrics = {
            f"dense/accuracy{i}": random.randint(1, 10**2)
            for i in range(self.dense_metric_count)
        }

        # Log example dense metric if available
        if dense_metrics:
            example_key = next(iter(dense_metrics))
            logger.info(f"Example dense metric: {example_key}")

        if self.sparse_stride_size > 0:
            # Generate a single payload for sparse logging every X steps
            self.sparse_metrics = {
                f"sparse/acc{i}": random.randint(1, 10**2)
                for i in range(self.sparse_metric_count)
            }

            payloads = [{**dense_metrics}]

        else:
            # Generate payloads with sparse metrics + optional dense metrics prepended
            payloads = [
                {
                    **dense_metrics,
                    **{
                        f"eval{x}/loss{i}": random.randint(1, 10**2)
                        for i in range(self.metrics_count_per_step // 2)
                    },
                    **{
                        f"rank{x}/accuracy{i}": random.randint(1, 10**2)
                        for i in range(self.metrics_count_per_step // 2)
                    },
                }
                for x in range(self.num_of_unique_payload)
            ]

        return payloads

def from_repr(desc):
        if desc == 'Shift':
            return Shift()
        if desc == 'CloseConstituent':
            return CloseConstituent()
        labels = desc.split("(", maxsplit=1)
        if labels[0] not in ('CompoundUnary', 'OpenConstituent', 'Finalize'):
            raise ValueError("Unknown Transition %s" % desc)
        if len(labels) == 1:
            raise ValueError("Unexpected Transition repr, %s needs labels" % labels[0])
        if labels[1][-1] != ')':
            raise ValueError("Expected Transition repr for %s: %s(labels)" % (labels[0], labels[0]))
        trans_type = labels[0]
        labels = labels[1][:-1]
        labels = ast.literal_eval(labels)
        if trans_type == 'CompoundUnary':
            return CompoundUnary(*labels)
        if trans_type == 'OpenConstituent':
            return OpenConstituent(*labels)
        if trans_type == 'Finalize':
            return Finalize(*labels)
        raise ValueError("Unexpected Transition %s" % desc)

def check_bool_expr_is_true(bool_expr, vranges, cond=None):
    if cond is not None:
        bool_expr = tvm.te.any(tvm.tirx.Not(cond), bool_expr)

    def _run_expr(expr, vranges):
        """Evaluate expr for every value of free variables
        given by vranges and return the tensor of results.
        """

        def _compute_body(*us):
            vmap = {v: u + r.min for (v, r), u in zip(vranges.items(), us)}
            return tvm.tirx.stmt_functor.substitute(expr, vmap)

        A = tvm.te.compute([r.extent.value for v, r in vranges.items()], _compute_body)
        args = [tvm.runtime.empty(A.shape, A.dtype)]
        mod = tvm.compile(tvm.IRModule.from_expr(tvm.te.create_prim_func([A])))
        mod(*args)
        return args[0].numpy()

    res = _run_expr(bool_expr, vranges)
    if not np.all(res):
        indices = list(np.argwhere(res == 0)[0])
        counterex = [(str(v), i + r.min) for (v, r), i in zip(vranges.items(), indices)]
        counterex = sorted(counterex, key=lambda x: x[0])
        counterex = ", ".join([v + " = " + str(i) for v, i in counterex])
        ana = tvm.arith.Analyzer()
        raise AssertionError(
            f"Expression {ana.simplify(bool_expr)}\nis not true on {vranges}\n"
            f"Counterexample: {counterex}"
        )

def get_diff_for_doctesting(repo: Repo, base_commit: str, commits: list[str]) -> list[str]:
    print("\n### DIFF ###\n")
    code_diff = []
    for commit in commits:
        for diff_obj in commit.diff(base_commit):
            # We only consider Python files and doc files.
            if not diff_obj.b_path.endswith(".py") and not diff_obj.b_path.endswith(".md"):
                continue
            # We always add new python/md files
            if diff_obj.change_type == "A":
                code_diff.append(diff_obj.b_path)
            # Now for modified files
            elif diff_obj.change_type in ["M", "R"]:
                # In case of renames, we'll look at the tests using both the old and new name.
                if diff_obj.a_path != diff_obj.b_path:
                    code_diff.extend([diff_obj.a_path, diff_obj.b_path])
                else:
                    # Otherwise, we check modifications contain some doc example(s).
                    if diff_contains_doc_examples(repo, commit, diff_obj.b_path):
                        code_diff.append(diff_obj.a_path)
                    else:
                        print(f"Ignoring diff in {diff_obj.b_path} as it doesn't contain any doc example.")

    return code_diff

async def list_virtual_env_packages(
        self, model_name: str, worker_ip: Optional[str] = None
    ) -> Dict[str, Any]:
        if not model_name:
            raise ValueError("model_name is required")

        target_ip_worker_ref = (
            self._get_worker_ref_by_ip(worker_ip) if worker_ip is not None else None
        )
        if (
            worker_ip is not None
            and not self.is_local_deployment()
            and target_ip_worker_ref is None
        ):
            raise ValueError(f"Worker ip address {worker_ip} is not in the cluster.")

        # If specific worker is requested, query only that worker
        if target_ip_worker_ref:
            return await target_ip_worker_ref.list_virtual_env_packages(model_name)

        # Otherwise, try all workers until we find the virtual environment
        for worker in self._worker_address_to_worker.values():
            try:
                package_info = await worker.list_virtual_env_packages(model_name)
                if "error" not in package_info:
                    return package_info
            except Exception as e:
                logger.debug(
                    f"Worker doesn't have virtual environment for {model_name}: {e}"
                )

        # If no worker has the virtual environment
        return {
            "model_name": model_name,
            "worker_ip": None,
            "error": f"Virtual environment for model {model_name} not found on any worker",
        }

def download(url, path=None, overwrite=False, sha1_hash=None):
    if path is None:
        fname = url.split('/')[-1]
    else:
        path = os.path.expanduser(path)
        if os.path.isdir(path):
            fname = os.path.join(path, url.split('/')[-1])
        else:
            fname = path

    if overwrite or not os.path.exists(fname) or (sha1_hash and not check_sha1(fname, sha1_hash)):
        dirname = os.path.dirname(os.path.abspath(os.path.expanduser(fname)))
        if not os.path.exists(dirname):
            os.makedirs(dirname)

        print('Downloading %s from %s...'%(fname, url))
        r = requests.get(url, stream=True)
        if r.status_code != 200:
            raise RuntimeError("Failed downloading url %s"%url)
        total_length = r.headers.get('content-length')
        with open(fname, 'wb') as f:
            if total_length is None: # no content length header
                for chunk in r.iter_content(chunk_size=1024):
                    if chunk: # filter out keep-alive new chunks
                        f.write(chunk)
            else:
                total_length = int(total_length)
                for chunk in tqdm(r.iter_content(chunk_size=1024),
                                  total=int(total_length / 1024. + 0.5),
                                  unit='KB', unit_scale=False, dynamic_ncols=True):
                    f.write(chunk)

        if sha1_hash and not check_sha1(fname, sha1_hash):
            raise UserWarning('File {} is downloaded but the content hash does not match. ' \
                              'The repo may be outdated or download may be incomplete. ' \
                              'If the "repo_url" is overridden, consider switching to ' \
                              'the default repo.'.format(fname))

    return fname

def filter_state_dict_peft(
    state_dict: dict[str, Any],
    peft_config: 'PeftConfig',
    adapter_name: str = 'default',
    remove_adapter_names: bool = True,
) -> dict[str, Any]:

    if peft_config.peft_type != 'LORA':
        raise NotImplementedError(f'Only LoRA PEFT is supported. Got {peft_config.peft_type}')

    # Filtering copied from https://github.com/huggingface/peft/blob/4186c9b104644fd247a4cc0dc2dfc1ede4665204/src/peft/utils/save_and_load.py#L68C1-L86C116
    bias = peft_config.bias  # type: ignore
    if bias == 'none':
        to_return = {k: state_dict[k] for k in state_dict if 'lora_' in k}
    elif bias == 'all':
        to_return = {k: state_dict[k] for k in state_dict if 'lora_' in k or 'bias' in k}
    elif bias == 'lora_only':
        to_return = {}
        for k in state_dict:
            if 'lora_' in k:
                to_return[k] = state_dict[k]
                bias_name = k.split('lora_')[0] + 'bias'
                if bias_name in state_dict:
                    to_return[bias_name] = state_dict[bias_name]
    else:
        raise NotImplementedError
    to_return = {k: v for k, v in to_return.items() if (('lora_' in k and adapter_name in k) or ('bias' in k))}

    if remove_adapter_names:
        to_return = {k.replace(f'.{adapter_name}', ''): v for k, v in to_return.items()}
    return to_return

def json_format(self):
        fmt = self._jsonfmt
        if fmt == NUMBER_FORMAT_HEX:
            return format(self, "#x")
        elif fmt == NUMBER_FORMAT_OCTAL:
            return format(self, "#o")
        elif fmt == NUMBER_FORMAT_BINARY:
            return format(self, "#b")
        elif fmt == NUMBER_FORMAT_LEGACYOCTAL:
            if self == 0:
                return "0"  # For some reason Python's int doesn't do '00'
            elif self < 0:
                return "-0%o" % (-self)
            else:
                return "0%o" % self
        else:
            return str(self)

def TruncateToLength(len_map=None):  # pylint: disable=invalid-name
  @debug_data_pipeline.debug_pipeline
  def _truncate_to_length(generator):
    for example in generator:
      if isinstance(example, np.ndarray):
        example = (example,)
      if isinstance(example, (list, tuple)):
        example = list(example)
        if len_map is not None:
          for key, max_len in len_map.items():
            example_len = example[key].shape
            if example_len > max_len:
              example[key] = np.resize(example[key], max_len)
        output = tuple(example)
      else:
        output = None
        raise ValueError(f'Unknown example type: {example}')
      yield output

  return _truncate_to_length

def write_line(self, values):
        if self.inner_table is None:
            self.inner_table = [list(values.keys()), list(values.values())]
        else:
            columns = self.inner_table[0]
            for key in values:
                if key not in columns:
                    columns.append(key)
            self.inner_table[0] = columns
            if len(self.inner_table) > 1:
                last_values = self.inner_table[-1]
                first_column = self.inner_table[0][0]
                if last_values[0] != values[first_column]:
                    # write new line
                    self.inner_table.append([values.get(c, "No Log") for c in columns])
                else:
                    # update last line
                    new_values = values
                    for c in columns:
                        if c not in new_values:
                            new_values[c] = last_values[columns.index(c)]
                    self.inner_table[-1] = [new_values[c] for c in columns]
            else:
                self.inner_table.append([values[c] for c in columns])

def builder_from_config(
    config: dict[str, Any] | None,
    environment: AbstractEnvironment,
    registry: AbstractRegistry,
) -> AbstractBuilder:
    if not config:
        if is_docker_installed():
            from .builder.docker_builder import DockerBuilder

            return DockerBuilder.from_config(
                {}, environment, registry
            )  # This is the default builder.

        from .builder.noop import NoOpBuilder

        return NoOpBuilder.from_config({}, environment, registry)

    builder_type = config.get("type")
    if builder_type is None:
        raise LaunchError(
            "Could not create builder from config. Builder type not specified"
        )
    if builder_type == "docker":
        from .builder.docker_builder import DockerBuilder

        return DockerBuilder.from_config(config, environment, registry)
    if builder_type == "kaniko":
        from .builder.kaniko_builder import KanikoBuilder

        return KanikoBuilder.from_config(config, environment, registry)
    if builder_type == "noop":
        from .builder.noop import NoOpBuilder

        return NoOpBuilder.from_config(config, environment, registry)
    raise LaunchError(
        f"Could not create builder from config. Invalid builder type: {builder_type}"
    )

def visit_expr_stmt(self: Parser, node: doc.Expr) -> None:
    res = self.eval_expr(node.value)
    if res is None:
        pass
    elif isinstance(res, Frame):
        res.add_callback(partial(res.__exit__, None, None, None))
        res.__enter__()
    elif isinstance(res, Var):
        # Standalone Var expression (e.g. from T.bind(value, var=v)) --
        # the Bind statement was already emitted to the parent frame by the FFI call,
        # so just discard the returned Var.
        pass
    elif isinstance(res, PrimExpr):
        T.evaluate(res)
    elif isinstance(res, int | bool):
        T.evaluate(tvm.tirx.const(res))
    elif isinstance(res, tvm.relax.Call) and not res.args:
        # Using GlobalVar.__call__ with no arguments is ambiguous, as
        # each IR has a different function Call representation.  If
        # this occurs, convert to the TIR representation.
        T.evaluate(tvm.tirx.call_tir(res.op))
    elif isinstance(res, str):
        # Ignore docstrings
        pass
    elif isinstance(res, tvm.tirx.stmt.BufferStore):
        T.buffer_store(res.buffer, res.value, res.indices, res.predicate)
    else:
        self.report_error(node, f"Parsing resulted in unexpected type {type(res)}")

def recv(self):
        # pylint: disable=import-outside-toplevel
        import cloudpickle

        try:
            len_data = self._reader.read(4)
        except OSError:
            raise self._child_process_error()

        if len(len_data) == 0:
            raise self._child_process_error()

        try:
            recv_bytes = struct.unpack("<i", len_data)[0]
            status, value = cloudpickle.loads(self._reader.read(recv_bytes))
        except OSError:
            raise self._child_process_error()

        if status == StatusKind.COMPLETE:
            return value
        if status == StatusKind.EXCEPTION:
            raise value
        assert status == StatusKind.TIMEOUT
        # kill and lazily restart the process in the next send.
        self.kill()
        raise TimeoutError()

def execute_func_expr(
        self,
        expr: Union[FunctionExpression, Parameter],
        map_fn: Callable = lambda x: x.data,
    ) -> Union[FunctionOutput, Parameter]:

        if isinstance(expr, Parameter):

            func: Parameter = self.parse_func_expr(expr, map_fn=map_fn)
            if not isinstance(func, Parameter):
                raise ValueError(f"Error parsing function expression: {expr}")

            # execute the function
            output: Parameter = self.execute_func(func)
            if not isinstance(output, Parameter):
                raise ValueError(f"Error executing function expression: {expr}")
            output.predecessors.add(expr)
            return output
        else:

            try:
                func: Function = self.parse_func_expr(expr)
                if not isinstance(func, Function):
                    raise ValueError(f"Error parsing function expression: {expr}")

                return self.execute_func(func)
            except Exception as e:
                # NOTE: if the function expression is not a function call, try to execute it as a function expression
                log.error(f"Error {e} executing function expression: {expr}")
                return FunctionOutput(
                    name=expr.action, input=expr, output=None, error=None
                )

def walk(self, key: ContainerKey = b''):
        path = self.absolute_path(key)
        walker = self.parent.walk(path)
        p = None
        while True:
            if p is None:
                next_key = next(walker)
            else:
                next_key = walker.send(p)
            if next_key is None:
                return
            if path:
                _prefix, _path, next_key = next_key.partition(path)
                # assert not _prefix and _path == path
                if _prefix or _path != path:
                    return

            key = yield next_key
            p = self.absolute_path(key)

def save(cls, file="data.yaml", data=None, header=""):
        instance = cls._get_instance()
        if data is None:
            data = {}

        # Create parent directories if needed
        file = Path(file)
        file.parent.mkdir(parents=True, exist_ok=True)

        # Convert non-serializable objects to strings
        valid_types = int, float, str, bool, list, tuple, dict, type(None)
        for k, v in data.items():
            if not isinstance(v, valid_types):
                data[k] = str(v)

        # Write YAML file
        with open(file, "w", errors="ignore", encoding="utf-8") as f:
            if header:
                f.write(header)
            instance.yaml.dump(data, f, sort_keys=False, allow_unicode=True, Dumper=instance.SafeDumper)

def convert_pre(self, el: Tag, text: str, **kwargs) -> str:
        code_el = el.find("code")
        if code_el:
            # Extract raw text, stripping all Pygments <span> tags
            raw_code = code_el.get_text()
            # Try to detect language from class
            lang = ""
            classes = list(el.get("class", [])) + list(
                code_el.get("class", [])
            )
            for cls in classes:
                if isinstance(cls, str) and cls.startswith("language-"):
                    lang = cls.replace("language-", "")
                    break
            # Also check parent div for language class
            parent = el.parent
            if not lang and parent and parent.name == "div":
                for cls in parent.get("class", []):
                    if isinstance(cls, str) and cls.startswith("language-"):
                        lang = cls.replace("language-", "")
                        break
            return f"\n```{lang}\n{raw_code.strip()}\n```\n\n"
        return f"\n```\n{text.strip()}\n```\n\n"

def max(self, dim=None, keepdim=False, one_hot=True):
    method = cfg.safety.mpc.functions.max_method
    if dim is None:
        if method in ["log_reduction", "double_log_reduction"]:
            # max_result can be obtained directly
            max_result = _max_helper_all_tree_reductions(self, method=method)
        else:
            # max_result needs to be obtained through argmax
            with cfg.temp_override({"functions.max_method": method}):
                argmax_result = self.argmax(one_hot=True)
            max_result = self.mul(argmax_result).sum()
        return max_result
    else:
        argmax_result, max_result = _argmax_helper(self, dim=dim, one_hot=True, method=method, _return_max=True)
        if max_result is None:
            max_result = (self * argmax_result).sum(dim=dim, keepdim=keepdim)
        if keepdim:
            max_result = max_result.unsqueeze(dim) if max_result.dim() < self.dim() else max_result
        if one_hot:
            return max_result, argmax_result
        else:
            return (
                max_result,
                _one_hot_to_index(argmax_result, dim, keepdim, self.device),
            )

def validate_properties(properties: List[Dict[str, Any]]):
    if not isinstance(properties, list):
        raise DeepchecksValueError(
            'Expected properties to be a list, '
            f'instead got {type(properties).__name__}'
        )

    if len(properties) == 0:
        raise DeepchecksValueError('Properties list can\'t be empty')

    expected_keys = ('name', 'method', 'output_type')
    output_types = ('categorical', 'numerical', 'class_id')

    errors = []

    for index, image_property in enumerate(properties):
        if not isinstance(image_property, dict) or not all(key in image_property for key in expected_keys):
            errors.append(
                f'Item #{index}: property must be of type dict, '
                f'and include keys {expected_keys}.'
            )
            continue

        image_property['name'] = property_name = image_property.get('name') or f'#{index}'
        difference = sorted(set(expected_keys).difference(set(image_property.keys())))

        if len(difference) > 0:
            errors.append(
                f'Property {property_name}: dictionary must include keys {expected_keys}. '
                f'Next keys are missed {difference}'
            )
            continue

        property_output_type = image_property['output_type']

        if property_output_type not in output_types:
            errors.append(
                f'Property {property_name}: field "output_type" must be one of {output_types}, '
                f'instead got {property_output_type}'
            )

    if len(errors) > 0:
        errors = '\n+ '.join(errors)
        raise DeepchecksValueError(f'List of properties contains next problems:\n+ {errors}')

    return properties

def resolve_backend() -> str:
    global _resolved_cache
    if _resolved_cache is not None:
        return _resolved_cache

    if _backend != "auto":
        _resolved_cache = _backend
        return _backend

    # Auto-detect: prefer torchvision on GPU, then numba, then numpy
    if is_available("torchvision"):
        try:
            import torch

            if torch.cuda.is_available():
                _resolved_cache = "torchvision"
                return _resolved_cache
        except ImportError:
            pass

    if is_available("numba"):
        _resolved_cache = "numba"
        return _resolved_cache

    _resolved_cache = "numpy"
    return _resolved_cache

def set_level(level: str | int = logging.WARNING) -> None:
    global _LOG_LEVEL
    if isinstance(level, str):
        _LOG_LEVEL = log_level_string_to_int(level)
    elif level not in [
        logging.DEBUG,
        logging.INFO,
        logging.WARNING,
        logging.ERROR,
        logging.CRITICAL,
    ]:
        raise ValueError(f"Unrecognized log level {level}")
    else:
        _LOG_LEVEL = level

    for logger in _LOGGERS.values():
        # We have to set update the logger's level in order
        # for its handlers level's to be respected.
        # but it needs to be set to the minimum LOG_LEVEL and INFO
        # so the file handler can still pick it up
        logger.setLevel(min(_LOG_LEVEL, logging.INFO))
        for handler in logger.handlers:
            if isinstance(handler, logging.FileHandler):
                # Don't increase the log level of a file handler
                handler.setLevel(min(_LOG_LEVEL, handler.level))
            elif isinstance(handler, logging.StreamHandler):
                handler.setLevel(_LOG_LEVEL)

def handle_engine_signals(flow_run_id: UUID | None = None):
    try:
        yield
    except Abort:
        if flow_run_id:
            msg = f"Execution of flow run '{flow_run_id}' aborted by orchestrator."
        else:
            msg = "Execution aborted by orchestrator."
        engine_logger.info(msg)
        exit(0)
    except Pause:
        if flow_run_id:
            msg = f"Execution of flow run '{flow_run_id}' is paused."
        else:
            msg = "Execution is paused."
        engine_logger.info(msg)
        exit(0)
    except TerminationSignal:
        # A TerminationSignal can mean either:
        # - an expected runner-driven control action (today: cancel intent),
        # - or a raw external termination with no runner intent attached.
        #
        # Only the first case should translate to a clean process exit.
        if get_intent() == "cancel":
            if flow_run_id:
                msg = f"Execution of flow run '{flow_run_id}' was cancelled."
            else:
                msg = "Execution was cancelled."
            engine_logger.info(msg)
            clear_intent()
            exit(0)
        raise
    except Exception:
        if flow_run_id:
            msg = f"Execution of flow run '{flow_run_id}' exited with unexpected exception"
        else:
            msg = "Execution exited with unexpected exception"
        engine_logger.error(msg, exc_info=True)
        exit(1)
    except BaseException:
        if flow_run_id:
            msg = f"Execution of flow run '{flow_run_id}' interrupted by base exception"
        else:
            msg = "Execution interrupted by base exception"
        engine_logger.error(msg, exc_info=True)
        # Let the exit code be determined by the base exception type
        raise

def hotspots(
    config: HotspotsConfig, df: DataFrame
) -> tuple[DataFrame, float, list[tuple[Feature, FeatureStats, list[int]]]]:
    original_num_total = df.shape[0]
    df = df[df[config.score_column].notna()]
    num_total = df.shape[0]
    if num_total < original_num_total:
        logging.warning(
            f"{original_num_total - num_total} samples without a score, skipping them"
        )
    avg_score = df[config.score_column].mean()

    logging.info("starting initial round...")
    df, index, fs = initial_round(config, df)
    logging.info(f"initial round finished with {len(fs)} features")

    original_fs = {f: copy.deepcopy(s) for f, s in fs}

    scores = df[config.score_column]

    outs = []

    fs_listed = set()

    for round_ix in range(config.num_rounds):
        if not fs:
            logging.info("not enough eligible features, stopping...")
            break

        top_feature_name = fs[0][0]

        logging.info(f"ROUND {round_ix} WITH TOP FEATURE {top_feature_name}")

        outs.append((
            top_feature_name,
            original_fs[top_feature_name],
            index[top_feature_name],
        ))
        fs_listed.add(top_feature_name)

        scores, fs = do_round(scores, index, fs, config.higher_is_better)

        while fs and is_feature_unwanted(index, fs_listed, fs[0][0]):
            fs = fs[1:]

        if not fs:
            break

    return (df, avg_score, outs)

def character_ngrams(string="", n=3, top=None, threshold=0, exclude=[], **kwargs):
    # An optional dict-parameter can be used to specify a subclass of dict,
    # e.g., count(words, dict=readonlydict) as used in Document.
    count = defaultdict(int)
    if n > 0:
        for i in range(len(string) - n + 1):
            w = string[i:i + n]
            if w not in exclude:
                count[w] += 1
    if threshold > 0:
        count = dict((k, v) for k, v in count.items() if v > threshold)
    if top is not None:
        count = dict(heapq.nsmallest(top, list(count.items()), key=lambda kv: (-kv[1], kv[0])))
    return kwargs.get("dict", dict)(count)

def copy_example_assets(app, exception):
    if exception is not None:
        return

    import glob
    import shutil

    # Only copy assets for HTML builds
    if app.builder.name != 'html':
        return

    # Find the examples directory relative to docs/source
    examples_dir = os.path.abspath(os.path.join(app.srcdir, '../../examples'))

    if os.path.exists(examples_dir):
        # Find all assets directories in examples
        for assets_dir in glob.glob(os.path.join(examples_dir, '*/assets')):
            if os.path.exists(assets_dir):
                # Destination directory in the built HTML
                dest_dir = os.path.join(app.outdir, 'examples', 'applications',
                                        'assets')
                os.makedirs(dest_dir, exist_ok=True)

                # Copy all files from assets directory
                for file in os.listdir(assets_dir):
                    src = os.path.join(assets_dir, file)
                    dst = os.path.join(dest_dir, file)
                    if os.path.isfile(src):
                        shutil.copy2(src, dst)
                        print(f'Copied asset: {file}')

def format(self, record: logging.LogRecord) -> str:
        record = self._lower_external(record)
        record = self._format_warnings(record)
        record.message = record.getMessage()
        # strip newlines
        if record.levelno < 30 and ("\n" in record.message or "\r" in record.message):
            record.message = record.message.replace("\n", "\\n").replace("\r", "\\r")

        if self.usesTime():
            record.asctime = self.formatTime(record, self.datefmt)
        msg = self.formatMessage(record)
        if record.exc_info:
            # Cache the traceback text to avoid converting it multiple times
            # (it's constant anyway)
            if not record.exc_text:
                record.exc_text = self.formatException(record.exc_info)
        if record.exc_text:
            if msg[-1:] != "\n":
                msg = msg + "\n"
            msg = msg + record.exc_text
        if record.stack_info:
            if msg[-1:] != "\n":
                msg = msg + "\n"
            msg = msg + self.formatStack(record.stack_info)
        return msg

def sum(self, fmin=None, fmax=None):
        if self._is_sum:
            raise RuntimeError(
                "This CSD matrix already represents a mean or sum across frequencies."
            )

        # Deal with the various ways in which fmin and fmax can be specified
        if fmin is None and fmax is None:
            fmin = [self.frequencies[0]]
            fmax = [self.frequencies[-1]]
        else:
            if isinstance(fmin, numbers.Number):
                fmin = [fmin]
            if isinstance(fmax, numbers.Number):
                fmax = [fmax]
            if fmin is None:
                fmin = [self.frequencies[0]] * len(fmax)
            if fmax is None:
                fmax = [self.frequencies[-1]] * len(fmin)

        if any(fmin_ > fmax_ for fmin_, fmax_ in zip(fmin, fmax)):
            raise ValueError(
                "Some lower bounds are higher than the corresponding upper bounds."
            )

        # Find the index of the lower bound of each frequency bin
        fmin_inds = [self._get_frequency_index(f) for f in fmin]
        fmax_inds = [self._get_frequency_index(f) + 1 for f in fmax]

        if len(fmin_inds) != len(fmax_inds):
            raise ValueError("The length of fmin does not match the length of fmax.")

        # Sum across each frequency bin
        n_bins = len(fmin_inds)
        new_data = np.zeros((self._data.shape[0], n_bins), dtype=self._data.dtype)
        new_frequencies = []
        for i, (min_ind, max_ind) in enumerate(zip(fmin_inds, fmax_inds)):
            new_data[:, i] = self._data[:, min_ind:max_ind].sum(axis=1)
            new_frequencies.append(self.frequencies[min_ind:max_ind])

        csd_out = CrossSpectralDensity(
            data=new_data,
            ch_names=self.ch_names,
            tmin=self.tmin,
            tmax=self.tmax,
            frequencies=new_frequencies,
            n_fft=self.n_fft,
            projs=self.projs,
        )
        return csd_out

def check_commutation_relation(
    ops1: list[PauliSentence | TensorLike],
    ops2: list[PauliSentence | TensorLike],
    vspace: PauliVSpace | list[PauliSentence | TensorLike],
):

    ops1_is_tensor = any(isinstance(op, TensorLike) for op in ops1)
    ops2_is_tensor = any(isinstance(op, TensorLike) for op in ops2)
    if not isinstance(vspace, PauliVSpace):
        vspace_is_tensor = any(isinstance(op, TensorLike) for op in vspace)
        if any(isinstance(op, Operator) for op in vspace):
            vspace = PauliVSpace(vspace, dtype=complex)

    else:
        vspace_is_tensor = False

    all_tensors = all((ops1_is_tensor, ops2_is_tensor, vspace_is_tensor))
    any_tensors = any((ops1_is_tensor, ops2_is_tensor, vspace_is_tensor))
    if not all_tensors and any_tensors:
        raise TypeError(
            "All inputs `ops1`, `ops2` and `vspace` to qml.liealg.check_commutation_relation need to either be iterables of operators or matrices."
        )

    if all_tensors:
        all_coms = _all_coms(ops1, ops2)
        return _is_subspace(all_coms, vspace)

    if any(isinstance(op, Operator) for op in ops1):
        ops1 = [op.pauli_rep for op in ops1]

    if any(isinstance(op, Operator) for op in ops2):
        ops2 = [op.pauli_rep for op in ops2]

    for o1 in ops1:
        for o2 in ops2:
            com = o1.commutator(o2)
            com.simplify()
            if len(com) != 0:
                if vspace.is_independent(com):
                    return False

    return True

def get_measurement_function(
    measurementprocess: MeasurementProcess, state: TensorLike
) -> Callable[[MeasurementProcess, TensorLike, bool, list[Callable]], TensorLike]:
    if isinstance(measurementprocess, StateMeasurement):
        if isinstance(measurementprocess.mv, MeasurementValue):
            return state_diagonalizing_gates
        if isinstance(measurementprocess, ExpectationMP):
            if measurementprocess.obs.name == "SparseHamiltonian":
                return csr_dot_products_density_matrix

            if measurementprocess.obs.name == "Hermitian":
                return full_dot_products_density_matrix

            backprop_mode = math.get_interface(state, *measurementprocess.obs.data) != "numpy"
            if isinstance(measurementprocess.obs, LinearCombination):

                # need to work out thresholds for when it's faster to use "backprop mode"
                if backprop_mode:
                    return sum_of_terms_method

                if not all(obs.has_sparse_matrix for obs in measurementprocess.obs.terms()[1]):
                    return sum_of_terms_method

                return csr_dot_products_density_matrix

            if isinstance(measurementprocess.obs, Sum):
                if backprop_mode:
                    # always use sum_of_terms_method for Sum observables in backprop mode
                    return sum_of_terms_method

                if not all(obs.has_sparse_matrix for obs in measurementprocess.obs):
                    return sum_of_terms_method

                if (
                    measurementprocess.obs.has_overlapping_wires
                    and len(measurementprocess.obs.wires) > 7
                ):
                    # Use tensor contraction for `Sum` expectation values with non-commuting summands
                    # and 8 or more wires as it's faster than using eigenvalues.

                    return csr_dot_products_density_matrix
        if measurementprocess.obs is None or measurementprocess.obs.has_diagonalizing_gates:
            return state_diagonalizing_gates

    raise NotImplementedError

def markdown_to_tups(self, markdown_text: str) -> List[Tuple[Optional[str], str]]:
        markdown_tups: List[Tuple[Optional[str], str]] = []
        lines = markdown_text.split("\n")

        current_header = None
        current_text = ""

        for line in lines:
            header_match = re.match(r"^#+\s", line)
            if header_match:
                if current_header is not None:
                    if current_text == "" or None:
                        continue
                    markdown_tups = self.tups_chunk_append(markdown_tups, current_header, current_text)

                current_header = line
                current_text = ""
            else:
                current_text += line + "\n"
        markdown_tups = self.tups_chunk_append(markdown_tups, current_header, current_text)

        if current_header is not None:
            # pass linting, assert keys are defined
            markdown_tups = [
                (re.sub(r"#", "", cast(str, key)).strip(), re.sub(r"<.*?>", "", value))
                for key, value in markdown_tups
            ]
        else:
            markdown_tups = [
                (key, re.sub("\n", "", value)) for key, value in markdown_tups
            ]

        return markdown_tups

def flatten_processor_list(processor_list):
    flattened_processor_list = []
    dependencies_list = []
    for item in processor_list:
        processor, model_specs = item
        for model_spec in model_specs:
            package = model_spec.package
            dependencies = model_spec.dependencies
            flattened_processor_list.append([processor, package])
            if dependencies:
                dependencies_list += [tuple(dependency) for dependency in dependencies]
    dependencies_list = [list(item) for item in set(dependencies_list)]
    for processor, package in dependencies_list:
        logger.debug(f'Find dependency {processor}: {package}.')
    flattened_processor_list += dependencies_list
    return flattened_processor_list

def can_fuse(  # noqa: C901
        input_node: torch.fx.Node,
        bn: torch.fx.Node,
        program: ExportedProgram,
        why: WhyNoPartition | None = None,
    ) -> bool:

        if input_node.op != "call_function":
            return False

        if input_node.target not in (
            exir_ops.edge.aten.convolution.default,
            exir_ops.edge.aten.linear.default,
        ):
            if why:
                why("Input node must be a convolution or linear op.")
            return False

        is_conv = input_node.target == exir_ops.edge.aten.convolution.default

        # All users of the batch_norm node must be getitem ops.
        # batch_norm returns a 3-element tuple.
        # Each user must only access the first element of the tuple.
        if [
            (user.target == operator.getitem and user.args[1] == 0) for user in bn.users
        ].count(False):
            if why:
                why("Batch norm users must only access the output tensor.")
            return False

        input_node_weights = input_node.args[1]
        bn_weights = bn.args[1]

        # Check that the weights for conv or linear and batch_norm are both params.
        if not isinstance(input_node_weights, torch.fx.Node) or not isinstance(
            bn_weights, torch.fx.Node
        ):
            if why:
                why("Input node weights must be parameters.")
            return False

        if [
            is_param_node(program, node) for node in {input_node_weights, bn_weights}
        ].count(False):
            if why:
                why("Node weights must be static.")
            return False

        # Check the rank of the convolutution input - only Conv1d and 2d are supported.
        if is_conv:
            conv_input = input_node.args[0]
            if (
                not isinstance(conv_input, torch.fx.Node)
                or "val" not in conv_input.meta
                or len(conv_input.meta["val"].shape) not in (3, 4)
            ):
                if why:
                    why("Convolution input must be rank 3 or 4.")
                return False

        return True

def extract_tensor_meta(meta):
    special_dtype = meta.get(TosaSpecialDtype.meta_key())
    if special_dtype == TosaSpecialDtype.SHAPE:
        shape_len = len(meta["val"])
        return (ts.DType.SHAPE, (shape_len,), meta["tosa_dim_order"])

    if meta.get("val") is None:
        raise ValueError("Expected node.meta['val'] to be set to a FakeTensor")
    val = meta["val"]
    if type(val) is tuple:
        # TODO: should use first concrete representation
        val = val[0]
    if isinstance(val, list):
        if not val:
            raise ValueError("Expected node.meta['val'] list to be non-empty")
        # Use first concrete representation for multi-output ops.
        val = val[0]

    if not isinstance(val, torch._subclasses.fake_tensor.FakeTensor):
        raise ValueError(
            f"Expected first value in node.meta['val'] to be FakeTensor, got {val.__class__}"
        )
    dtype = map_dtype(val.dtype)
    shape = tuple(val.size())

    if meta.get("tosa_dim_order") is not None:
        dim_order = meta["tosa_dim_order"]
    else:
        dim_order = tuple(range(len(shape)))
    return (dtype, shape, dim_order)

def commutator(op1, op2, pauli=False):
    both_have_pauli_rep = op1.pauli_rep is not None and op2.pauli_rep is not None

    if pauli or both_have_pauli_rep:
        if not isinstance(op1, PauliSentence):
            op1 = qml.pauli.pauli_sentence(op1)
        if not isinstance(op2, PauliSentence):
            op2 = qml.pauli.pauli_sentence(op2)
        res = op1.commutator(op2)
        return res if pauli else res.operation(wire_order=res.wires)

    # If no pauli processing is possible, use operator arithmetic
    with qml.QueuingManager.stop_recording():
        if isinstance(op1, (PauliWord, PauliSentence)):
            op1 = op1.operation()
        if isinstance(op2, (PauliWord, PauliSentence)):
            op2 = op2.operation()

        res = qml.sum(qml.prod(op1, op2), qml.s_prod(-1.0, qml.prod(op2, op1)))
        res = res.simplify()
    return res

def log_hyperparams(
        self,
        params: Union[dict[str, Any], Namespace],
        metrics: Optional[dict[str, Any]] = None,
        step: Optional[int] = None,
    ) -> None:
        params = _convert_params(params)

        # format params into the suitable for tensorboard
        params = _flatten_dict(params)
        params = self._sanitize_params(params)

        if metrics is None:
            if self._default_hp_metric:
                metrics = {"hp_metric": -1}
        elif not isinstance(metrics, dict):
            metrics = {"hp_metric": metrics}

        if metrics:
            self.log_metrics(metrics, step)

            if _TENSORBOARD_AVAILABLE:
                from torch.utils.tensorboard.summary import hparams
            else:
                from tensorboardX.summary import hparams  # type: ignore[no-redef]

            exp, ssi, sei = hparams(params, metrics)
            writer = self.experiment._get_file_writer()
            writer.add_summary(exp, step)
            writer.add_summary(ssi, step)
            writer.add_summary(sei, step)

async def predict(messages):
        message = messages[-1].content
        history_langchain_format = []
        for msg in messages[:-1]:
            if msg.role == "user":
                history_langchain_format.append(HumanMessage(content=msg.content))
            elif msg.role == "assistant":
                history_langchain_format.append(AIMessage(content=msg.content))
        history_langchain_format.append(HumanMessage(content=message))

        query_rewrite = ""
        response = ""
        async for event in rag_chain.astream_events(
            {
                "input": message,
                "chat_history": history_langchain_format,
            },
            version="v1",
        ):
            if (
                event["name"] == "retrieve_documents"
                and "output" in event["data"]
                and event["data"]["output"] is not None
            ):
                sources = [
                    (doc.metadata["file_path"], doc.metadata["url"])
                    for doc in event["data"]["output"]
                ]
                # Deduplicate while preserving the order.
                sources = list(dict.fromkeys(sources))
                response += (
                    "## Sources:\n"
                    + "\n".join([source_md(s[0], s[1]) for s in sources])
                    + "\n## Response:\n"
                )

            elif event["event"] == "on_chat_model_stream":
                chunk = event["data"]["chunk"].content

                if "contextualize_q_llm" in event["tags"]:
                    query_rewrite += chunk
                else:
                    # This is the actual response to the user query.
                    if not response:
                        logging.info(f"Query rewrite: {query_rewrite}")
                    response += chunk
                    yield mo.md(response)

def map(
        self,
        fn: Callable[[np.ndarray], np.ndarray]
        | Callable[[TimeIndex, np.ndarray], np.ndarray],
    ) -> Self:  # noqa: E501
        if not isinstance(fn, Callable):
            raise_log(TypeError("fn must be a callable"), logger)

        if isinstance(fn, np.ufunc):
            if fn.nin == 1 and fn.nout == 1:
                num_args = 1
            elif fn.nin == 2 and fn.nout == 1:
                num_args = 2
            else:
                raise_log(
                    ValueError(
                        "fn must have either one or two arguments and return a single value"
                    ),
                    logger,
                )
        else:
            try:
                num_args = len(signature(fn).parameters)
            except ValueError:
                raise_log(
                    ValueError(
                        "inspect.signature(fn) failed. Try wrapping fn in a lambda, e.g. lambda x: fn(x)"
                    ),
                    logger,
                )

        if num_args == 1:  # apply fn on values directly
            values = fn(self._values)
        elif num_args == 2:
            # apply function on (times, values)
            values = fn(self._time_index, self._values)
        else:
            raise_log(ValueError("fn must accept either one or two arguments"), logger)

        if values.shape != self.shape:
            raise_log(
                ValueError(
                    f"fn must return an array of shape `{self.shape}`. Received shape `{values.shape}`"
                )
            )

        return self.__class__(
            times=self._time_index,
            values=values,
            components=self.components,
            **self._attrs,
        )

def fit_svi(
        self,
        dataset,
        epochs=2,
        batch_size=1,
        scheduler=None,
        jit=False,
    ):

        # Setup.
        if batch_size is not None:
            self.batch_size = batch_size
        if scheduler is None:
            scheduler = MultiStepLR(
                {
                    "optimizer": Adam,
                    "optim_args": {"lr": 0.01},
                    "milestones": [],
                    "gamma": 0.5,
                }
            )
        if self.is_cuda:
            device = torch.device("cuda")
        else:
            device = torch.device("cpu")
        # Initialize guide.
        self.guide(None, None)
        dataload = DataLoader(
            dataset,
            batch_size=batch_size,
            shuffle=True,
            pin_memory=self.pin_memory,
            generator=torch.Generator(device=device),
        )
        # Setup stochastic variational inference.
        if jit:
            elbo = JitTrace_ELBO(ignore_jit_warnings=True)
        else:
            elbo = Trace_ELBO()
        svi = SVI(self.model, self.guide, scheduler, loss=elbo)

        # Run inference.
        losses = []
        t0 = datetime.datetime.now()
        for epoch in range(epochs):
            for seq_data, L_data in dataload:
                if self.is_cuda:
                    seq_data = seq_data.cuda()
                loss = svi.step(
                    seq_data, torch.tensor(len(dataset) / seq_data.shape[0])
                )
                losses.append(loss)
                scheduler.step()
            print(epoch, loss, " ", datetime.datetime.now() - t0)
        return losses

def match_ngrams(sentence_ngrams, ngram_map, debug=False):
    if debug:
        print("NGRAMS FOR DEBUG SENTENCE:")
    potential_match = None
    unknown_ngram = 0
    for ngram in sentence_ngrams:
        con_matches = ngram_map[ngram]
        if debug:
            print("{} matched {}".format(ngram, len(con_matches)))
        if len(con_matches) == 0:
            unknown_ngram += 1
            continue
        if len(con_matches) > 1:
            continue
        # get the one & only element from the set
        con_match = next(iter(con_matches))
        if debug:
            print("  {}".format(con_match))
        if potential_match is None:
            potential_match = con_match
        elif potential_match != con_match:
            return None
    if unknown_ngram > len(sentence_ngrams) / 2:
        return None
    return potential_match

def to_dict(self) -> dict[str, Any]:
        d = asdict(self)

        # Replace Resources objects with their dict representations
        if isinstance(self.resources, SpecsResources):
            d["resources"] = self.resources.to_dict()
        elif isinstance(self.resources, list):
            d["resources"] = [r.to_dict() for r in self.resources]
        elif isinstance(self.resources, dict):
            d["resources"] = {
                k: (v.to_dict() if isinstance(v, SpecsResources) else [r.to_dict() for r in v])
                for k, v in self.resources.items()
            }

        return d

def expand(cls, featurelists, combinations=None, skipintersecting=True):
        def nonempty_powerset(xs):  # xs is a list
            # itertools docnonempty_powerset([1,2,3]) --> (1,) (2,) (3,) (1,2) (1,3) (2,3) (1,2,3)

            # find the correct tuple given combinations, one of {None, k, (k1,k2)}
            k = combinations  # for brevity
            combrange = (
                (1, len(xs) + 1)
                if k is None
                else (
                    (k, k + 1)  # n over 1 .. n over n (all non-empty combinations)
                    if isinstance(k, int)
                    else (k[0], k[1] + 1)
                )  # n over k (only
            )  # n over k1, n over k1+1... n over k2
            return it.chain.from_iterable(
                it.combinations(xs, r) for r in range(*combrange)
            )

        seentemplates = set()
        for picks in nonempty_powerset(featurelists):
            for pick in it.product(*picks):
                if any(
                    i != j and x.issuperset(y)
                    for (i, x) in enumerate(pick)
                    for (j, y) in enumerate(pick)
                ):
                    continue
                if skipintersecting and any(
                    i != j and x.intersects(y)
                    for (i, x) in enumerate(pick)
                    for (j, y) in enumerate(pick)
                ):
                    continue
                thistemplate = cls(*sorted(pick))
                strpick = str(thistemplate)
                #!!FIXME --this is hackish
                if strpick in seentemplates:  # already added
                    cls._poptemplate()
                    continue
                seentemplates.add(strpick)
                yield thistemplate

def append_extra_datapoint(to_data, from_data, index) -> DatasetLike:
    if not (type(from_data) is type(to_data)):
        raise ValueError("Cannot append datapoint from different type of data object.")

    if isinstance(to_data, np.ndarray):
        return np.vstack([to_data, from_data[index]])
    elif isinstance(from_data, (pd.DataFrame, pd.Series)):
        X_extra = from_data.iloc[[index]]  # type: ignore
        to_data = pd.concat([to_data, X_extra])
        return to_data.reset_index(drop=True)
    else:
        try:
            X_extra = from_data[index]
            try:
                return to_data.append(X_extra)
            except Exception:  # special append for sparse matrix
                return csr_vstack(to_data, X_extra)
        except Exception:
            raise TypeError("Data features X must support: X.append(X[i])")

def noniid(dataset, no_participants, alpha=0.5):
    np.random.seed(666)
    random.seed(666)
    cifar_classes = {}
    for ind, x in enumerate(dataset):
        _, label = x
        if label in cifar_classes:
            cifar_classes[label].append(ind)
        else:
            cifar_classes[label] = [ind]

    per_participant_list = defaultdict(list)
    no_classes = len(cifar_classes.keys())
    class_size = len(cifar_classes[0])
    datasize = {}
    for n in range(no_classes):
        random.shuffle(cifar_classes[n])
        sampled_probabilities = class_size * np.random.dirichlet(
            np.array(no_participants * [alpha])
        )
        for user in range(no_participants):
            no_imgs = int(round(sampled_probabilities[user]))
            datasize[user, n] = no_imgs
            sampled_list = cifar_classes[n][: min(len(cifar_classes[n]), no_imgs)]
            per_participant_list[user].extend(sampled_list)
            cifar_classes[n] = cifar_classes[n][min(len(cifar_classes[n]), no_imgs) :]
    train_img_size = np.zeros(no_participants)
    for i in range(no_participants):
        train_img_size[i] = sum([datasize[i, j] for j in range(no_classes)])
    clas_weight = np.zeros((no_participants, no_classes))
    for i in range(no_participants):
        for j in range(no_classes):
            clas_weight[i, j] = float(datasize[i, j]) / float((train_img_size[i]))
    return per_participant_list, clas_weight

def write_tokenizer(input_dir, output_dir):
    input_path = Path(input_dir)

    # Convert the pickle tokenizer to HF format
    tokenizer_pkl = input_path / "tokenizer.pkl"
    if tokenizer_pkl.exists():
        try:
            import pickle

            from transformers.integrations.tiktoken import convert_tiktoken_to_fast

            with open(tokenizer_pkl, "rb") as f:
                tok_pkl = pickle.load(f)
            convert_tiktoken_to_fast(tok_pkl, output_dir)
            print("Converted tokenizer.pkl to HuggingFace format")
        except Exception as e:
            print(f"Warning: Failed to convert tokenizer.pkl: {e}")
            # Fallback: copy tokenizer files if they exist
            for filename in ("tokenizer.json", "tokenizer_config.json"):
                src = input_path / filename
                if src.exists():
                    (Path(output_dir) / filename).write_bytes(src.read_bytes())
    else:
        # No pickle tokenizer, copy JSON files
        for filename in ("tokenizer.json", "tokenizer_config.json", "special_tokens_map.json"):
            src = input_path / filename
            if src.exists():
                (Path(output_dir) / filename).write_bytes(src.read_bytes())

    print("Tokenizer saved successfully.")

def df_to_fd(x, copy=False, nan_str='null', dtype=None):
    assert isinstance(x, pd.DataFrame), 'input must be a Pandas DataFrame'

    # Find NaN values in object type columns
    nan_indices = {}
    for feat in x:
        if x[feat].dtype == np.dtype('O'):
            nan_indices[feat] = np.where(x[feat].isna().values)[0]

    if dtype and not copy:
        copy = True
    if copy:
        if dtype:
            if isinstance(dtype, list):
                assert len(dtype) == len(
                    list(x)
                ), 'dtypes must be same length as there are features in DataFrame'
                out = OrderedDict((f, x[f].values.astype(dtype[i])) for i, f in enumerate(list(x)))
                for feat in nan_indices:
                    out[feat][nan_indices[feat]] = nan_str
                return out
            else:
                out = OrderedDict((f, x[f].values.astype(dtype)) for f in list(x))
                for feat in nan_indices:
                    out[feat][nan_indices[feat]] = nan_str
                return out
        else:
            out = OrderedDict((f, x[f].values.copy()) for f in list(x))
            for feat in nan_indices:
                out[feat][nan_indices[feat]] = nan_str
            return out

    out = OrderedDict((f, x[f].values.view()) for f in list(x))
    for feat in nan_indices:
        try:
            out[feat][nan_indices[feat]] = nan_str
        except ValueError:
            logger.exception(feat, x[feat].dtype)
    return out

def get_workflow_summary(self, markdown=False):
        if self.response and self.response.get("messages"):
            agents = []
            seen = set()
            allowed = {
                "sql_database_agent",
                "data_visualization_agent",
            }
            role_to_content = {}
            for msg in self.response["messages"]:
                role = getattr(msg, "role", None) or getattr(msg, "type", None)
                if role in allowed and role not in seen:
                    agents.append(role)
                    seen.add(role)
                if role in allowed and role not in role_to_content:
                    role_to_content[role] = getattr(msg, "content", "")
            agent_labels = [
                f"- **Agent {i + 1}:** {role}\n" for i, role in enumerate(agents)
            ]
            header = (
                f"# SQL Data Analyst Workflow Summary\n\nThis workflow contains {len(agents)} agents:\n\n"
                + "\n".join(agent_labels)
            )
            reports = []
            for role in agents:
                content = role_to_content.get(role, "")
                try:
                    reports.append(get_generic_summary(json.loads(content)))
                except Exception:
                    reports.append(content)
            summary = "\n\n" + header + "\n\n".join(reports)
            return Markdown(summary) if markdown else summary

def get_node_arg(args: list | dict, key: int | str | type, default_value=None):
    if isinstance(key, int):
        if 0 <= key < len(args):
            return args[key]
        elif key == len(args):
            if default_value is not None:
                return default_value
            else:
                raise RuntimeError(f"No defult value given for index {key}")
        else:
            raise RuntimeError(
                f"Out of bounds index {key} for getting value in args (of size {len(args)})"
            )
    elif isinstance(key, str):
        return args.get(key, default_value)  # type: ignore[union-attr]
    elif isclass(key):
        for arg in args:
            if isinstance(arg, key):
                return arg
        if default_value is not None:
            return default_value
        else:
            raise RuntimeError(f"No arg of type {key}")
    else:
        raise RuntimeError("Invalid type")

def build_reference_placeholders(update_nav: bool = True) -> list[str]:
    nav_items: list[str] = []
    created = 0
    orphans = set(REFERENCE_DIR.rglob("*.md"))

    for py_filepath in TQDM(list(PACKAGE_DIR.rglob("*.py")), desc="Building reference stubs", unit="file"):
        classes, functions = extract_classes_and_functions(py_filepath)
        if not classes and not functions:
            continue
        module_path = (
            f"{PACKAGE_DIR.name}.{py_filepath.relative_to(PACKAGE_DIR).with_suffix('').as_posix().replace('/', '.')}"
        )
        md_filepath = REFERENCE_DIR / py_filepath.relative_to(PACKAGE_DIR).with_suffix(".md")
        exists = md_filepath.exists()
        orphans.discard(md_filepath)
        md_rel = create_placeholder_markdown(py_filepath, module_path, classes, functions)
        nav_items.append(str(md_rel))
        if not exists:
            created += 1
    for orphan in orphans:
        orphan.unlink()
    if update_nav:
        update_mkdocs_file(create_nav_menu_yaml(nav_items))
    if created:
        LOGGER.info(f"Created {created} new reference stub files")
    return nav_items

def DistributedOptimizer(optimizer, name=None, use_locking=False, device_dense='',
                         device_sparse='', compression=Compression.none,
                         sparse_as_dense=False, backward_passes_per_step=1,
                         op=Average):
    if isinstance(optimizer, _LegacyOptimizer):
        if op == Adasum:
            raise ValueError('op == Adasum is not supported yet with ')
        else:
            if backward_passes_per_step > 1:
                raise ValueError('backward_passes_per_step>1 is not supported yet with '
                                 'op != Adasum')
            return _DistributedOptimizer(optimizer, name, use_locking, device_dense,
                                        device_sparse, compression, sparse_as_dense, op)
    elif isinstance(optimizer, tf.keras.optimizers.Optimizer):
        if op == Adasum:
            raise ValueError('op == Adasum is not supported yet with Keras')
        if backward_passes_per_step > 1:
            raise ValueError('backward_passes_per_step > 1 is not supported yet with Keras')
        import byteps.tensorflow.keras as bps_k
        return bps_k.DistributedOptimizer(optimizer, name, device_dense, device_sparse,
                                          compression, sparse_as_dense)
    else:
        raise ValueError('Provided optimizer doesn\'t inherit from either legacy '
                         'TensorFlow or Keras optimizer: %s' % optimizer)

def tokenize(
        self, text: str, convert_parentheses: bool = False, return_str: bool = False
    ) -> list[str]:
        if return_str is not False:
            warnings.warn(
                "Parameter 'return_str' has been deprecated and should no "
                "longer be used.",
                category=DeprecationWarning,
                stacklevel=2,
            )

        for regexp, substitution in self.STARTING_QUOTES:
            text = regexp.sub(substitution, text)

        for regexp, substitution in self.PUNCTUATION:
            text = regexp.sub(substitution, text)

        # Handles parentheses.
        regexp, substitution = self.PARENS_BRACKETS
        text = regexp.sub(substitution, text)
        # Optionally convert parentheses
        if convert_parentheses:
            for regexp, substitution in self.CONVERT_PARENTHESES:
                text = regexp.sub(substitution, text)

        # Handles double dash.
        regexp, substitution = self.DOUBLE_DASHES
        text = regexp.sub(substitution, text)

        # add extra space to make things easier
        text = " " + text + " "

        for regexp, substitution in self.ENDING_QUOTES:
            text = regexp.sub(substitution, text)

        for regexp in self.CONTRACTIONS2:
            text = regexp.sub(r" \1 \2 ", text)
        for regexp in self.CONTRACTIONS3:
            text = regexp.sub(r" \1 \2 ", text)

        # We are not using CONTRACTIONS4 since
        # they are also commented out in the SED scripts
        # for regexp in self._contractions.CONTRACTIONS4:
        #     text = regexp.sub(r' \1 \2 \3 ', text)

        return text.split()

def doc2bow(self, document, allow_update=False, return_missing=False):
        if isinstance(document, str):
            raise TypeError("doc2bow expects an array of unicode tokens on input, not a single string")

        # Construct (word, frequency) mapping.
        counter = defaultdict(int)
        for w in document:
            counter[w if isinstance(w, str) else str(w, 'utf-8')] += 1

        token2id = self.token2id
        if allow_update or return_missing:
            missing = sorted(x for x in counter.items() if x[0] not in token2id)
            if allow_update:
                for w, _ in missing:
                    # new id = number of ids made so far;
                    # NOTE this assumes there are no gaps in the id sequence!
                    token2id[w] = len(token2id)
        result = {token2id[w]: freq for w, freq in counter.items() if w in token2id}

        if allow_update:
            self.num_docs += 1
            self.num_pos += sum(counter.values())
            self.num_nnz += len(result)
            # keep track of document and collection frequencies
            for tokenid, freq in result.items():
                self.cfs[tokenid] = self.cfs.get(tokenid, 0) + freq
                self.dfs[tokenid] = self.dfs.get(tokenid, 0) + 1

        # return tokenids, in ascending id order
        result = sorted(result.items())
        if return_missing:
            return result, dict(missing)
        else:
            return result

def mouseDoubleClickEvent(self, ev):
        if self.is_loading:
            return

        # Handle auto decode mode double click to finish
        if (
            self.auto_decode_mode
            and self.is_auto_labeling
            and self.auto_decode_tracklet
        ):
            self.auto_decode_finish_requested.emit()
            return

        if self.editing() and self.double_click_edit_label:
            pos = self.transform_pos(ev.position())
            for shape in reversed(self.shapes):
                if not self.is_visible(shape):
                    continue
                hit = False
                if shape.shape_type in ["point", "line", "linestrip"]:
                    if (
                        shape.nearest_vertex(
                            pos, self.epsilon * 3 / self.scale
                        )
                        is not None
                    ):
                        hit = True
                elif len(shape.points) > 1 and shape.contains_point(pos):
                    hit = True
                if hit:
                    self._undo_pending_edge_point()
                    if shape not in self.selected_shapes:
                        self.selection_changed.emit([shape])
                    self.h_shape_is_selected = False
                    self.edit_label_requested.emit()
                    return

        # For polygon/quadrilateral the mousePress handler adds a spurious
        # duplicate point before this handler fires, so we pop it first.
        # For linestrip the press-added point IS the intended final point,
        # so we keep it and finalize directly.
        if self.double_click == "close" and self.can_close_shape():
            if self.create_mode == "linestrip":
                self.finalise()
            elif len(self.current) > 3:
                self.current.pop_point()
                self.finalise()

def generate_agent_trajectory(self, timing_raw=None, meta_info=None):
        if timing_raw is None:
            timing_raw = {}
        with marked_timer("collect_trajectory", timing_raw):
            trajectories = []
            if self.async_rollout_mode:
                gen_seq_generator = self.generate_agent_trajectories_async(timing_raw=timing_raw, meta_info=meta_info, mode="Token")
                for _, trajectory in enumerate(gen_seq_generator):
                    trajectories.append(trajectory)
            else:
                raise ValueError("Only async rollout mode is supported")
        # Sort trajectories by their idx, to ensure they are in order.
        trajectories.sort(key=lambda x: x["idx"])

        with marked_timer("transform_trajectory", timing_raw):
            # Transform the raw trajectories into DataProto format.
            final_gen_batch_output, metrics = self._transform_agent_trajectories(trajectories)
        return final_gen_batch_output, metrics

def extract_weights(self, source: Any) -> TensorDictBase | dict | None:
        if self.extract_as == "tensordict":
            # Extract as TensorDict
            if isinstance(source, nn.Module):
                td = TensorDict.from_module(source)
                # Also capture extra_state (e.g., VecNormV2 running stats)
                # which is not included in TensorDict.from_module()
                try:
                    extra = source.get_extra_state()
                except RuntimeError:
                    extra = None
                if extra:
                    td["__extra_state__"] = TensorDict(extra)
                return td
            elif isinstance(source, TensorDictBase):
                return source
            elif isinstance(source, dict):
                # Convert state_dict to TensorDict
                return TensorDict(source, batch_size=[])
            else:
                torchrl_logger.warning(
                    f"Unsupported source type for TensorDict extraction: {type(source)}"
                )
                return TensorDict(lock=True)
        elif self.extract_as == "state_dict":  # state_dict
            # Extract as state_dict
            if isinstance(source, nn.Module):
                if hasattr(source, "merge_and_unload"):
                    # LoRA model: merge weights to get clean parameter names
                    # that match vLLM's expected format
                    return source.merge_and_unload().state_dict()
                return source.state_dict()
            elif isinstance(source, dict):
                return source
            elif isinstance(source, TensorDictBase):
                # Convert TensorDict to state_dict
                return source.flatten_keys().to_dict()
            else:
                torchrl_logger.warning(
                    f"Unsupported source type for TensorDict extraction: {type(source)}"
                )
                return {}
        else:
            raise ValueError(
                f"Unknown extract_as: {self.extract_as}. Must be 'tensordict' or 'state_dict'."
            )

def blur_2d(
    input: torch.Tensor,
    channels: int = -1,
    stride: _size_2_t = 1,
    filter: Optional[torch.Tensor] = None,
) -> torch.Tensor:

    if filter is None:
        filter = _default_2d_filter()
    # The dynamic control flow branch below does not affect the padding as only h and w are used.
    padding = _padding_for_filt_2d_same(filter)

    if channels < 1:  # Use Dynamic Control Flow
        _, channels, h, w = input.shape

        if (filter.shape[0] == 1) and (channels > 1):
            # assume filt is already a rank 4 tensor
            filter = filter.repeat((channels, 1, 1, 1))

        _, _, filter_h, filter_w = filter.shape
        if h + 2 * padding[0] < filter_h:
            return input
        if w + 2 * padding[1] < filter_w:
            return input

    # Call F.conv2d without using keyword arguments as that triggers a bug in fx tracing quantization.
    return F.conv2d(input, filter, None, _pair(stride), _pair(padding), _pair(1), channels)

def render_modelspec_comment(value: Any, *, variables: Mapping[str, object] | None = None) -> str | None:
    if value is None:
        return None

    if isinstance(value, str):
        stripped = value.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            try:
                parsed = json.loads(stripped)
                if isinstance(parsed, list):
                    value = parsed
            except (json.JSONDecodeError, ValueError):
                pass

    if isinstance(value, list):
        value = "\n".join(str(item) for item in value)
    elif not isinstance(value, str):
        value = str(value)

    value = value.strip()
    if not value:
        return None

    value = resolve_string_placeholders(value, variables=variables)
    return value or None

def read_reports(workspace_path: Path | None) -> dict:
    # Look for reports in the absolute path where GitHub Actions writes them
    print(f"GitHub workspace: {workspace_path}")
    if workspace_path:
        reports_dir = Path(workspace_path) / ".github" / "test-reports"
    else:
        reports_dir = Path(".github/test-reports")
    print(f"Reports directory: {reports_dir}")

    # Look for XML files directly in the test-reports directory
    reports = list(reports_dir.glob("*.xml"))
    print(f"Found {len(reports)} report files")

    report_contents = {}
    for report_path in reports:
        try:
            with open(report_path, 'r', encoding='utf-8') as f:
                report_contents[Path(report_path).name] = f.read()
                print(f"Successfully read report: {Path(report_path).name}")
        except Exception as e:
            print(f"Warning: Failed to read report {report_path}: {str(e)}")
            continue

    if not report_contents:
        warnings.warn("No report contents were read")

    return report_contents

def get_workspace_users(workspace_config: Dict[str, Any]) -> List[str]:
    if workspace_config.get('private', False):
        user_ids = []
        workspace_user_name_or_ids = workspace_config.get('allowed_users', [])
        all_users = global_user_state.get_all_users()
        all_user_ids = {user.id for user in all_users}
        all_user_map = collections.defaultdict(list)
        for user in all_users:
            all_user_map[user.name].append(user.id)

        # Resolve user names to IDs
        for user_name_or_id in workspace_user_name_or_ids:
            if user_name_or_id in all_user_ids:
                user_ids.append(user_name_or_id)
            elif user_name_or_id in all_user_map:
                if len(all_user_map[user_name_or_id]) > 1:
                    user_ids_str = ', '.join(all_user_map[user_name_or_id])
                    raise ValueError(
                        f'User {user_name_or_id!r} has multiple IDs: '
                        f'{user_ids_str}. Please specify the user '
                        f'ID instead.')
                user_ids.append(all_user_map[user_name_or_id][0])
            else:
                logger.warning(
                    f'User {user_name_or_id!r} not found in all users')
                continue
        return user_ids
    else:
        # Public workspace - return '*' to indicate all users should have access
        return ['*']

def get_latest_forecast(
        self,
        fcst: pd.DataFrame,
        df_name: Optional[str] = None,
        include_history_data: bool = False,
        include_previous_forecasts: int = 0,
    ):
        if self.config_model.max_lags == 0:
            raise ValueError("Use the standard plot function for models without lags.")
        fcst = fcst.copy(deep=True)
        fcst, received_ID_col, received_single_time_series, _ = df_utils.check_multiple_series_id(fcst)
        if not received_single_time_series:
            if df_name not in fcst["ID"].unique():
                assert len(fcst["ID"].unique()) > 1
                raise Exception(
                    "Many time series are present in the pd.DataFrame (more than one ID). Please specify ID to be "
                    "forecasted. "
                )
            else:
                fcst = fcst[fcst["ID"] == df_name]
                log.info(f"Getting data from ID {df_name}")
        if include_history_data is None:
            fcst = fcst[-(include_previous_forecasts + self.config_model.n_forecasts + self.config_model.max_lags) :]
        elif include_history_data is False:
            fcst = fcst[-(include_previous_forecasts + self.config_model.n_forecasts) :]
        elif include_history_data is True:
            fcst = fcst
        fcst = utils.fcst_df_to_latest_forecast(
            fcst, self.config_model.quantiles, n_last=1 + include_previous_forecasts
        )
        return fcst

def decision_function(self, X):
        check_is_fitted(self, ['decision_scores_', 'threshold_', 'labels_'])

        if not isinstance(X, dict):
            raise TypeError(
                "MultiModalOD expects a dict input, got %s" % type(X))

        # Determine n_samples from first available modality
        n_samples = None
        for name in self.modality_names_:
            if name in X and X[name] is not None:
                data_i = X[name]
                n_samples = len(data_i) if isinstance(data_i, (list, tuple)) \
                    else data_i.shape[0]
                break
        if n_samples is None:
            raise ValueError("No modalities available in test input")

        test_scores = []
        for name in self.modality_names_:
            if name not in X or X[name] is None:
                # Impute mean score (0 after standardization)
                test_scores.append(np.zeros(n_samples))
            else:
                det = self.detectors_[name]
                scores_i = det.decision_function(X[name])

                if self.standardize_scores:
                    scores_i = self.score_scalers_[name].transform(
                        scores_i.reshape(-1, 1)).ravel()

                test_scores.append(scores_i)

        score_matrix = np.column_stack(test_scores)
        return self._combine(score_matrix)

def get_width(
    X: Union[ArrayXd, Ragged, Padded, Sequence[ArrayXd]], *, dim: int = -1
) -> int:
    if isinstance(X, Ragged):
        return get_width(X.data, dim=dim)
    elif isinstance(X, Padded):
        return get_width(X.data, dim=dim)
    elif hasattr(X, "shape") and hasattr(X, "ndim"):
        X = cast(ArrayXd, X)
        if len(X.shape) == 0:
            return 0
        elif len(X.shape) == 1:
            return int(X.max()) + 1
        else:
            return X.shape[dim]
    elif isinstance(X, (list, tuple)):
        if len(X) == 0:
            return 0
        else:
            return get_width(X[0], dim=dim)
    else:
        err = "Cannot get width of object: has neither shape nor __getitem__"
        raise ValueError(err)

def interpret_operation(self, op: Operator):
            if isinstance(op, QubitUnitary):
                ops = []
                with capture.pause():
                    matrix_shape = math.shape(op.parameters[0])
                    if matrix_shape == (2, 2):
                        ops = one_qubit_decomposition(op.parameters[0], op.wires[0])
                    elif matrix_shape == (4, 4):
                        ops = two_qubit_decomposition(op.parameters[0], op.wires)
                    else:
                        ops = [op]
                # List comprehensions are run in a separate scope.
                # The automatic insertion of __class__ and self for zero-argument super does not work in such a nested scope.
                # pylint: disable=super-with-arguments
                return [super(UnitaryToRotInterpreter, self).interpret_operation(o) for o in ops]

            return super().interpret_operation(op)

def generate_scalar(self) -> list[dict[str, int]]:
        # Generate dense metrics if applicable
        dense_metrics = {
            self.random_string(self.metric_key_size): random.randint(1, 10**2)
            for _ in range(self.dense_metric_count)
        }

        # Log example dense metric if available
        if dense_metrics:
            example_key = next(iter(dense_metrics))
            logger.info(f"Example dense metric: {example_key}")

        if self.sparse_stride_size > 0:
            # Generate a single payload for sparse logging every X steps
            self.sparse_metrics = {
                f"sparse/acc{i}": random.randint(1, 10**2)
                for i in range(self.sparse_metric_count)
            }

            payloads = [{**dense_metrics}]

        else:
            # Generate payloads with sparse metrics + optional dense metrics prepended
            payloads = [
                {
                    **dense_metrics,
                    **{
                        self.random_string(self.metric_key_size): random.randint(
                            1, 10**2
                        )
                        for _ in range(self.metrics_count_per_step)
                    },
                }
                for _ in range(self.num_of_unique_payload)
            ]

        return payloads

def from_yaml(cls, yml_path, namespace=None):
        with open(yml_path, 'rb') as f:
            config = yaml.safe_load(f)

        dimension_classes = {'real': Real,
                             'integer': Integer,
                             'categorical': Categorical}

        # Extract space options for configuration file
        if isinstance(config, dict):
            if namespace is None:
                options = next(iter(config.values()))
            else:
                options = config[namespace]
        elif isinstance(config, list):
            options = config
        else:
            raise TypeError('YaML does not specify a list or dictionary')

        # Populate list with Dimension objects
        dimensions = []
        for option in options:
            key = next(iter(option.keys()))
            # Make configuration case insensitive
            dimension_class = key.lower()
            values = {k.lower(): v for k, v in option[key].items()}
            if dimension_class in dimension_classes:
                # Instantiate Dimension subclass and add it to the list
                dimension = dimension_classes[dimension_class](**values)
                dimensions.append(dimension)

        space = cls(dimensions=dimensions)

        return space

def log_prob(self, hidden):
        if self.n_clusters == 0:
            logit = self._compute_logit(hidden, self.out_layers[0].weight, self.out_layers[0].bias, self.out_projs[0])
            return nn.functional.log_softmax(logit, dim=-1)
        else:
            # construct weights and biases
            weights, biases = [], []
            for i in range(len(self.cutoffs)):
                if self.div_val == 1:
                    l_idx, r_idx = self.cutoff_ends[i], self.cutoff_ends[i + 1]
                    weight_i = self.out_layers[0].weight[l_idx:r_idx]
                    bias_i = self.out_layers[0].bias[l_idx:r_idx]
                else:
                    weight_i = self.out_layers[i].weight
                    bias_i = self.out_layers[i].bias

                if i == 0:
                    weight_i = torch.cat([weight_i, self.cluster_weight], dim=0)
                    bias_i = torch.cat([bias_i, self.cluster_bias], dim=0)

                weights.append(weight_i)
                biases.append(bias_i)

            head_weight, head_bias, head_proj = weights[0], biases[0], self.out_projs[0]
            head_logit = self._compute_logit(hidden, head_weight, head_bias, head_proj)

            out = hidden.new_empty((head_logit.size(0), self.n_token))
            head_logprob = nn.functional.log_softmax(head_logit, dim=1)

            cutoff_values = [0] + self.cutoffs
            for i in range(len(cutoff_values) - 1):
                start_idx, stop_idx = cutoff_values[i], cutoff_values[i + 1]

                if i == 0:
                    out[:, : self.cutoffs[0]] = head_logprob[:, : self.cutoffs[0]]
                else:
                    weight_i, bias_i, proj_i = weights[i], biases[i], self.out_projs[i]

                    tail_logit_i = self._compute_logit(hidden, weight_i, bias_i, proj_i)
                    tail_logprob_i = nn.functional.log_softmax(tail_logit_i, dim=1)

                    logprob_i = head_logprob[:, -i] + tail_logprob_i
                    out[:, start_idx, stop_idx] = logprob_i

            return out

def inverse(  # type: ignore[override]
        self,
        *args: Union[DataType, Dict[str, DataType]],
        params: Optional[List[ParamItem]] = None,
        data_keys: Optional[Union[List[str], List[int], List[DataKey]]] = None,
    ) -> Union[DataType, List[DataType], Dict[str, DataType]]:
        original_keys = None
        if len(args) == 1 and isinstance(args[0], dict):
            original_keys, data_keys, args, invalid_data = self._preproc_dict_data(cast(Dict[str, DataType], args[0]))

        # args here should already be `DataType`
        # NOTE: how to right type to: unpacked args <-> tuple of args to unpack
        # issue with `self._preproc_dict_data` return args type

        self.transform_op.data_keys = self.transform_op.preproc_datakeys(data_keys)

        self._validate_args_datakeys(*args, data_keys=self.transform_op.data_keys)  # type: ignore

        in_args = self._arguments_preproc(*args, data_keys=self.transform_op.data_keys)  # type: ignore

        if params is None:
            if self._params is None:
                raise ValueError(
                    "No parameters available for inversing, please run a forward pass first "
                    "or passing valid params into this function."
                )
            params = self._params

        outputs: List[DataType] = in_args
        for param in params[::-1]:
            module = self.get_submodule(param.name)
            outputs = self.transform_op.inverse(  # type: ignore
                *outputs, module=module, param=param, extra_args=self.extra_args
            )
            if not isinstance(outputs, list | tuple):
                # Make sure we are unpacking a list whilst post-proc
                outputs = [outputs]

        outputs = self._arguments_postproc(args, outputs, data_keys=self.transform_op.data_keys)  # type: ignore

        if isinstance(original_keys, tuple):
            result = {k: v for v, k in zip(outputs, original_keys)}
            if invalid_data:
                result.update(invalid_data)
            return result

        if len(outputs) == 1 and isinstance(outputs, list):
            return outputs[0]

        return outputs

def all_tpls(project: str, entity_type: str):
    tpl_dir = os.path.join(os.path.dirname(__file__))
    tpl_files = list_all_files(tpl_dir, ext="template", return_base_name=True)
    tpls = []
    for tpl in tpl_files:
        data = resource_string(__name__, tpl)
        file_location = os.path.splitext(os.path.basename(tpl))[0]
        # we assure that line endings are converted to '\n' for all OS
        data = data.decode(encoding="utf-8").replace(os.linesep, "\n")

        # change path for specific file
        # domain
        if file_location == "kdata_common.py":
            file_location = f"{project}/domain/quotes/__init__.py"
        elif file_location == "meta.py":
            file_location = f"{project}/domain/{entity_type}_meta.py"
        # recorder
        elif file_location == "kdata_recorder.py":
            file_location = f"{project}/recorders/{entity_type}_kdata_recorder.py"
        elif file_location == "meta_recorder.py":
            file_location = f"{project}/recorders/{entity_type}_meta_recorder.py"
        # fill script
        elif file_location == "fill_project.py":
            file_location = f"{project}/fill_project.py"
        # tests
        elif file_location == "test_pass.py":
            file_location = f"tests/test_pass.py"
        elif file_location == "pkg_init.py":
            file_location = f"{project}/__init__.py"

        tpls.append((file_location, string.Template(data)))
    return tpls

def get(name, id, path, include_archived):
    if not name and not id:
        raise click.UsageError("You must provide either --name or --id.")
    if name and id:
        raise click.UsageError(
            "You cannot provide both --name and --id. Please specify only one."
        )

    client = APIClient()
    job_query_mode = (
        LeptonJobQueryMode.AliveAndArchive.value
        if include_archived
        else LeptonJobQueryMode.AliveOnly.value
    )
    target_jobs = []

    if id:
        job = client.job.get(id, job_query_mode=job_query_mode)
        target_jobs.append(job)

    if name:
        jobs = client.job.list_all(job_query_mode=job_query_mode, q=name)
        for job in jobs:
            if job.metadata.name == name:
                target_jobs.append(job)

    if len(target_jobs) == 0:
        search_type = "Name" if name else "ID"
        console.print(f"No job found for [red]{search_type}: {name or id}[/].")
        sys.exit(1)

    console.print(f"Job details for [green]{name or id}[/]:")
    for job in target_jobs:
        console.print(json.dumps(client.job.safe_json(job), indent=2))
        console.print("--------------------------\n")

    # Save spec to file if requested.
    if path:
        if len(target_jobs) != 1:
            console.print(
                "[red]Error[/]: --path option requires exactly one matched job. "
                "Please specify a unique --id or --name."
            )
            sys.exit(1)

        job = target_jobs[0]
        job_spec_json = job.spec.model_dump_json(indent=2, by_alias=True)

        # Determine final save path
        try:
            save_path = resolve_save_path(path, f"job-spec-{job.metadata.id_}.json")
        except PathResolutionError as e:
            console.print(f"[red]Failed to save job spec: {e}[/]")
            sys.exit(1)

        try:
            with open(save_path, "w") as f:
                f.write(job_spec_json)
            console.print(f"Job spec saved to [green]{save_path}[/].")
        except Exception as e:
            console.print(f"[red]Failed to save job spec: {e}[/]")
            sys.exit(1)

def DiceCoefficient(cm: ConfusionMatrix, ignore_index: int | None = None) -> MetricsLambda:
    if not isinstance(cm, ConfusionMatrix):
        raise TypeError(f"Argument cm should be instance of ConfusionMatrix, but given {type(cm)}")

    if ignore_index is not None:
        if not (isinstance(ignore_index, numbers.Integral) and 0 <= ignore_index < cm.num_classes):
            raise ValueError(
                f"ignore_index should be integer and in the range of [0, {cm.num_classes}), but given {ignore_index}"
            )

    # Increase floating point precision and pass to CPU
    cm = cm.to(torch.double)
    dice: MetricsLambda = 2.0 * cm.diag() / (cm.sum(dim=1) + cm.sum(dim=0) + 1e-15)

    if ignore_index is not None:
        ignore_idx: int = ignore_index  # used due to typing issues with mympy

        def ignore_index_fn(dice_vector: torch.Tensor) -> torch.Tensor:
            if ignore_idx >= len(dice_vector):
                raise ValueError(
                    f"ignore_index {ignore_idx} is larger than the length of Dice vector {len(dice_vector)}"
                )
            indices = list(range(len(dice_vector)))
            indices.remove(ignore_idx)
            return dice_vector[indices]

        return MetricsLambda(ignore_index_fn, dice)
    else:
        return dice

def difference(self, other: Axes, sort: bool | None = None) -> Index:
        self._validate_sort_keyword(sort)
        self._assert_can_do_setop(other)
        other, result_name = self._convert_can_do_setop(other)

        # Note: we do NOT call _dti_setop_align_tzs here, as there
        #  is no requirement that .difference be commutative, so it does
        #  not cast to object.

        if self.equals(other):
            # Note: we do not (yet) sort even if sort=None GH#24959
            return self[:0].rename(result_name)

        if len(other) == 0:
            # Note: we do not (yet) sort even if sort=None GH#24959
            result = self.unique().rename(result_name)
            if sort is True:
                return result.sort_values()
            return result

        if not self._should_compare(other):
            # Nothing matches -> difference is everything
            result = self.unique().rename(result_name)
            if sort is True:
                return result.sort_values()
            return result

        result = self._difference(other, sort=sort)
        return self._wrap_difference_result(other, result)

def read_single_tree(token_iterator, broken_ok):
    # we were called here at a open paren, so start the stack of
    # children with one empty list already on it
    children_stack = deque()
    children_stack.append([])
    text_stack = deque()
    text_stack.append([])

    token = next(token_iterator, None)
    token_iterator.set_mark()
    while token is not None:
        if token == OPEN_PAREN:
            children_stack.append([])
            text_stack.append([])
        elif token == CLOSE_PAREN:
            text = text_stack.pop()
            children = children_stack.pop()
            if text:
                pieces = " ".join(text).split()
                if len(pieces) == 1:
                    child = Tree(pieces[0], children)
                else:
                    # the assumption here is that a language such as VI may
                    # have spaces in the words, but it still represents
                    # just one child
                    label = pieces[0]
                    child_label = " ".join(pieces[1:])
                    if children:
                        if broken_ok:
                            child = Tree(label, children + [Tree(normalize(child_label))])
                        else:
                            raise MixedTreeError(token_iterator.line_num, child_label, children)
                    else:
                        child = Tree(label, Tree(normalize(child_label)))
                if not children_stack:
                    return child
            else:
                if not children_stack:
                    return Tree("ROOT", children)
                elif broken_ok:
                    child = Tree(None, children)
                else:
                    raise UnlabeledTreeError(token_iterator.line_num)
            children_stack[-1].append(child)
        else:
            text_stack[-1].append(token)
        token = next(token_iterator, None)
    raise UnclosedTreeError(token_iterator.get_mark())

def get_available_icons() -> list[tuple[str, str, tuple[str | None, ...]]]:
    global ALL_AVAILABLE_ICONS

    # Cached?
    if ALL_AVAILABLE_ICONS is not None:
        return ALL_AVAILABLE_ICONS

    # Nope, get to work. Iterate over all icons and variants and group them.
    result_dict: dict[str, tuple[str, str, set[str | None]]] = {}

    for icon_set in icon_registry.all_icon_sets():
        for icon_name, variant_name in icon_registry.all_icons_in_set(icon_set):
            key = f"{icon_set}/{icon_name}"

            try:
                _, _, variants = result_dict[key]
            except KeyError:
                variants = {variant_name}
                result_dict[key] = (icon_set, icon_name, variants)
            else:
                variants.add(variant_name)

    # Drop the dict
    as_list: list[t.Any] = list(result_dict.values())

    # Sort the result
    as_list.sort(key=lambda x: x[1])

    for ii, (icon_set, icon_name, variants) in enumerate(as_list):
        variants = tuple(sorted(variants, key=lambda x: "" if x is None else x))
        as_list[ii] = (icon_set, icon_name, variants)

    # Cache and return
    ALL_AVAILABLE_ICONS = as_list  # type: ignore
    return ALL_AVAILABLE_ICONS  # type: ignore

def set_resources(
        self, resources: Union['resources_lib.Resources',
                               List['resources_lib.Resources'],
                               Set['resources_lib.Resources'], Dict[str, Any]]
    ) -> 'Task':
        if isinstance(resources, dict):
            resources = resources_lib.Resources.from_yaml_config(resources)
        elif isinstance(resources, resources_lib.Resources):
            resources = {resources}
        self._ensure_consistent_priority(resources)
        # TODO(woosuk): Check if the resources are None.
        self.resources = _with_docker_login_config(resources, self.envs,
                                                   self.secrets)
        # Only have effect on RunPod.
        self.resources = _with_docker_username_for_runpod(
            self.resources, self.envs, self.secrets)

        # Evaluate if the task requires FUSE and set the requires_fuse flag
        for _, storage_obj in self.storage_mounts.items():
            if storage_obj.mode in storage_lib.MOUNTABLE_STORAGE_MODES:
                for r in self.resources:
                    r.set_requires_fuse(True)
                break

        return self

def delete_unrelated_rows(self, table_content: Dict, question: str, answer: List, delete_ratio: float):
        truncated_unrelated_indices = []
        related_indices = []
        if answer is None or len(answer) == 0:
            answer_set = set([])
        else:
            answer_set = set([ans_ex.lower() for ans_ex in answer])
        # add question key words into answer set
        if question is not None:
            answer_set.update(question.split())
        question_set = set(question.strip("?!.,").split(" "))
        row_max_len = len(table_content["rows"])
        for _row_idx, row in enumerate(table_content["rows"]):
            lower_row = set([str(cell).lower() for cell in row])
            if len(lower_row & answer_set) == 0 and len(lower_row & question_set) == 0:
                truncated_unrelated_indices.append(_row_idx)
            else:
                # add neighbours to preserve information aggressively
                related_indices.extend([_row_idx - 2, _row_idx - 1, _row_idx, _row_idx + 1, _row_idx + 2])

        # remove the neighbours
        truncated_unrelated_indices = [
            _row_idx for _row_idx in truncated_unrelated_indices if _row_idx not in related_indices
        ]
        # select some cases to drop
        drop_items = min(len(truncated_unrelated_indices), int(len(table_content["rows"]) * delete_ratio))
        drop_row_indices = random.choices(truncated_unrelated_indices, k=drop_items)

        for _row_idx in reversed(range(row_max_len)):
            if _row_idx in drop_row_indices:
                del table_content["rows"][_row_idx]

        # only when the drop ratio is too large, logging for warning.
        if "id" in table_content and len(drop_row_indices) > 0:
            logger.warning("Delete {:.2f} rows in table {}".format(len(drop_row_indices), table_content["id"]))

def extract_function_expression(
    text: str, add_missing_right_parenthesis: bool = True
) -> str:
    text = text.strip()
    start = text.find("(")
    if start == -1:
        raise ValueError(f"No function expression found in the text: {text}")

    brace_count = 0
    end = -1
    for i in range(start, len(text)):
        if text[i] == "(":
            brace_count += 1
        elif text[i] == ")":
            brace_count -= 1

        if brace_count == 0:
            end = i
            break

    if end == -1 and add_missing_right_parenthesis:
        # If no closing parenthesis is found, but we are allowed to add one
        text += ")"
        end = len(text) - 1
    elif end == -1:
        raise ValueError(
            "Incomplete function expression found and add_missing_right_parenthesis is False."
        )

    return text[: end + 1]

def clear_run_path_if_sweep_or_launch(
        self,
        init_settings: Settings,
    ) -> _PrinterCallback:
        when_doing_thing = ""

        if self._wl.settings.sweep_id:
            when_doing_thing = "when running a sweep"
        elif self._wl.settings.launch:
            when_doing_thing = "when running from a wandb launch context"

        if not when_doing_thing:
            return _noop_printer_callback()

        warnings = []

        def warn(key: str, value: str) -> None:
            warnings.append(f"Ignoring {key} {value!r} {when_doing_thing}.")

        if init_settings.project is not None:
            warn("project", init_settings.project)
            init_settings.project = None
        if init_settings.entity is not None:
            warn("entity", init_settings.entity)
            init_settings.entity = None
        if init_settings.run_id is not None:
            warn("run_id", init_settings.run_id)
            init_settings.run_id = None

        def print_warnings(run_printer: printer.Printer) -> None:
            for warning in warnings:
                run_printer.display(warning, level="warn")

        return print_warnings

def ticklabel_format(self, *, axis='both', style=None, scilimits=None,
                         useOffset=None, useLocale=None, useMathText=None):
        if isinstance(style, str):
            style = style.lower()
        axis = axis.lower()
        if scilimits is not None:
            try:
                m, n = scilimits
                m + n + 1  # check that both are numbers
            except (ValueError, TypeError) as err:
                raise ValueError("scilimits must be a sequence of 2 integers"
                                 ) from err
        STYLES = {'sci': True, 'scientific': True, 'plain': False, '': None, None: None}
        # The '' option is included for backwards-compatibility.
        is_sci_style = _api.getitem_checked(STYLES, style=style)
        axis_map = {**{k: [v] for k, v in self._axis_map.items()},
                    'both': list(self._axis_map.values())}
        axises = _api.getitem_checked(axis_map, axis=axis)
        try:
            for axis in axises:
                if is_sci_style is not None:
                    axis.major.formatter.set_scientific(is_sci_style)
                if scilimits is not None:
                    axis.major.formatter.set_powerlimits(scilimits)
                if useOffset is not None:
                    axis.major.formatter.set_useOffset(useOffset)
                if useLocale is not None:
                    axis.major.formatter.set_useLocale(useLocale)
                if useMathText is not None:
                    axis.major.formatter.set_useMathText(useMathText)
        except AttributeError as err:
            raise AttributeError(
                "This method only works with the ScalarFormatter") from err

async def update_level(
    level_id: int,
    request: UpdateLevelRequest,
    admin: User = Depends(require_permission("admin.levels")),
) -> LevelResponse:
    store = _get_store()

    level = await store.get_level(level_id)
    if not level:
        raise HTTPException(status_code=404, detail="Level not found")

    if level.is_system:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="Cannot modify system levels")

    # Build updates
    updates = {}
    if request.name is not None:
        # Check for duplicate name
        existing = await store.get_level_by_name(request.name)
        if existing and existing.id != level_id:
            raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"Level '{request.name}' already exists")
        updates["name"] = request.name

    if request.description is not None:
        updates["description"] = request.description

    if request.priority is not None:
        updates["priority"] = request.priority

    if request.permission_names is not None:
        await store.set_level_permissions(level_id, request.permission_names)

    if updates:
        await store.update_level(level_id, updates)

    # Reload the level
    level = await store.get_level(level_id)
    logger.info("Level updated by admin %s: %s", admin.username, level.name)

    return LevelResponse(
        id=level.id,
        name=level.name,
        description=level.description,
        priority=level.priority,
        is_system=level.is_system,
        permissions=sorted(level.permissions),
    )

def is_valid_print_variable(k, v, block_uuid):
    if f'{block_uuid}_' not in k:
        return False
    if type(v) is not str:
        return False
    # Not store empty json
    if v == '{}' or v == '':
        return False
    try:
        json_data = json.loads(v)
        # Not store empty data in json object
        if 'data' in json_data and not json_data['data']:
            return False
    except Exception:
        pass
    return True

def find_all_classes(module_path: Union[str, ModuleType], cls: type) -> List[type]:
    if isinstance(module_path, ModuleType):
        mod = module_path
    else:
        mod = importlib.import_module(module_path)

    cls_list = []

    def _append_cls(obj):
        # Leverage the closure trick to reuse code
        if isinstance(obj, type) and issubclass(obj, cls) and cls not in cls_list:
            cls_list.append(obj)

    for attr in dir(mod):
        _append_cls(getattr(mod, attr))

    if hasattr(mod, "__path__"):
        # if the model is a package
        for _, modname, _ in pkgutil.iter_modules(mod.__path__):
            sub_mod = importlib.import_module(f"{mod.__package__}.{modname}")
            for m_cls in find_all_classes(sub_mod, cls):
                _append_cls(m_cls)
    return cls_list

def load_glove(file_path: str, return_embedding_size: bool = False) -> dict[str, np.ndarray]:
    logger.info(f"  Loading Glove format file {file_path}")
    embeddings = {}
    embedding_size = 0

    # collect embeddings size assuming the first line is correct
    with open_file(file_path, "r", encoding="utf-8") as f:
        found_line = False
        while not found_line:
            line = f.readline()
            if line:
                embedding_size = len(line.split()) - 1
                found_line = True

    # collect embeddings
    with open_file(file_path, "r", encoding="utf-8") as f:
        for line_number, line in enumerate(f):
            if line:
                try:
                    split = line.split()
                    if len(split) != embedding_size + 1:
                        raise ValueError(
                            f"Line {line_number} is of length {len(split)}, "
                            f"while expected length is {embedding_size + 1}."
                        )
                    word = split[0]
                    embedding = np.array([float(val) for val in split[-embedding_size:]])
                    embeddings[word] = embedding
                except ValueError:
                    logger.warning(f"Line {line_number} in the GloVe file {file_path} is malformed, skipping it")
    logger.info(f"  {len(embeddings)} embeddings loaded")

    if return_embedding_size:
        return embeddings, embedding_size
    return embeddings

def insert_tosa_transposes(self, graph_module: torch.fx.GraphModule):
        for node in graph_module.graph.nodes:
            if node.op != "call_function":
                continue

            # Transpose views
            elif node.target == exir_ops.edge.aten.view_copy.default:
                input_node = node.args[0]
                input_shape = input_node.meta["val"].shape
                output_shape = node.meta["val"].shape
                self._insert_view_transpose(
                    input_shape,
                    output_shape,
                    node,
                    input_node,
                    graph_module,
                )

        output_node = graph_module.graph.output_node()

        # Transpose inputs if they are in (N)NCHW format
        inputs = [
            n for n in graph_module.graph.nodes if _is_input(n, self.exported_program)
        ]
        for input_node in inputs:
            input_dim_order = get_first_fake_tensor(input_node).dim_order()
            if input_dim_order in (NCHW_ORDER, NNCHW_ORDER, NNNCHW_ORDER):
                self.insert_output_transpose(input_node, graph_module)

        # Transpose outputs if they are in (N)NCHW format
        outputs = output_node.args[0]
        if not isinstance(outputs, (list, tuple)):
            raise TypeError(
                f"Expected output node args to be a list or tuple, got {type(outputs)}"
            )
        output_dim_orders = output_node.meta.get("original_dim_orders")
        if output_dim_orders is None:
            raise RuntimeError(f"{output_dim_orders=} is not supported.")

        for output_node_input, output_dim_order in zip(
            outputs, output_dim_orders, strict=True
        ):
            if output_dim_order in (
                NCHW_ORDER,
                NNCHW_ORDER,
                NNNCHW_ORDER,
            ):
                self.insert_input_transpose(
                    output_node, output_node_input, graph_module
                )

def get_audio_outputs(self) -> list[bytes]:
        # Drain queue first to get latest events
        events = self.get_events()
        audio_data = []
        for event in events:
            # Handle new TypedEvent format (bidi_audio_stream)
            if event.get("type") == "bidi_audio_stream":
                audio_b64 = event.get("audio")
                if audio_b64:
                    # Decode base64 to bytes
                    audio_data.append(base64.b64decode(audio_b64))
            # Handle legacy audioOutput events
            elif "audioOutput" in event:
                data = event["audioOutput"].get("audioData")
                if data:
                    audio_data.append(data)
        return audio_data

def compress_trace(self, trace_data: Dict[str, Any]) -> Dict[str, Any]:
        logger.info("DEBUG: LangGraphTraceProvider.compress_trace called")

        compressed = {}

        # Extract plan with full detail
        plan = self.extract_plan(trace_data)
        if plan:
            compressed["plan"] = plan

        tool_evidence = self._extract_tool_execution_evidence(trace_data)
        if tool_evidence:
            compressed["tool_execution_evidence"] = tool_evidence

        # Extract enhanced execution flow with reasoning chain
        execution_flow = self.extract_execution_flow(trace_data)
        if execution_flow:
