def asarray(
        self,
        data: Union[ArrayXd, Sequence[ArrayXd], Sequence[Any]],
        *,
        dtype: Optional[DTypes] = None,
    ) -> ArrayXd:
        if isinstance(data, self.xp.ndarray):
            if dtype is None:
                return data
            elif data.dtype == dtype:
                return data
            else:
                return self.xp.asarray(data, dtype=dtype)
        elif hasattr(data, "numpy"):
            # Handles PyTorch Tensor
            return data.numpy()  # type: ignore[union-attr]
        elif dtype is not None:
            return self.xp.array(data, dtype=dtype)
        else:
            return self.xp.array(data)

def make_stacked_attention_pattern(start_op: str, with_bias: bool = False, layout="BS3NH"):
    stacked_qkv = wildcard()
    ops = {}
    if start_op == "split":
        ops["split"] = qkv_tuple = is_op("relax.split")(stacked_qkv)
        query_raw = is_tuple_get_item(qkv_tuple, 0)
        key_raw = is_tuple_get_item(qkv_tuple, 1)
        value_raw = is_tuple_get_item(qkv_tuple, 2)
    elif start_op == "strided_slice":
        ops["strided_slice_query"] = query_raw = is_op("relax.strided_slice")(
            stacked_qkv, varg_default_wildcard=True
        )
        ops["strided_slice_key"] = key_raw = is_op("relax.strided_slice")(
            stacked_qkv, varg_default_wildcard=True
        )
        ops["strided_slice_value"] = value_raw = is_op("relax.strided_slice")(
            stacked_qkv, varg_default_wildcard=True
        )
    else:
        raise NotImplementedError()
    query_reshape_list = wildcard()
    key_reshape_list = wildcard()
    value_reshape_list = wildcard()
    if layout == "BS3NH":
        query = is_op("relax.reshape")(query_raw, query_reshape_list)
        key = is_op("relax.reshape")(key_raw, key_reshape_list)
        value = is_op("relax.reshape")(value_raw, value_reshape_list)
    elif layout == "SBN3H":
        ops["q_transpose"] = query = is_op("relax.permute_dims")(query_raw)
        ops["k_transpose"] = key = is_op("relax.permute_dims")(key_raw)
        ops["v_transpose"] = value = is_op("relax.permute_dims")(value_raw)
    annotations = {
        "stacked_qkv": stacked_qkv,
        "query_reshape_list": query_reshape_list,
        "key_reshape_list": key_reshape_list,
        "value_reshape_list": value_reshape_list,
        **ops,
    }
    if with_bias:
        bias = wildcard()
        annotations["bias"] = bias
        out = is_op("relax.nn.attention_bias")(query, key, value, bias)
    else:
        out = is_op("relax.nn.attention")(query, key, value)

    if layout == "SBN3H":
        out = is_op("relax.permute_dims")(out)

    return out, annotations

def forward(self, code: str, timeout: int = 12, session_id: str | None = None, **kwargs) -> CodeToolOutput:
        self.client.timeout = timeout
        try:
            # If session_id is provided, use it to maintain state
            if session_id:
                self.session_id = session_id
            # Execute the code
            response = self.client.code_interpreter.run(code=code, language="python", **kwargs)

            # Save the session_id for potential future use
            if hasattr(response.data, "session_id"):
                self.session_id = response.data.session_id
            # Process the outputs
            stdout = ""
            stderr = ""
            output = ""
            error = None

            for output_item in response.data.outputs:
                if output_item.type == "stdout":
                    stdout += output_item.data + "\n"
                elif output_item.type == "stderr":
                    stderr += output_item.data + "\n"
                elif output_item.type == "error":
                    error = output_item.data
                    stderr += output_item.data + "\n"
                else:
                    output += str(output_item.data) + "\n"

            # Return formatted output
            return CodeToolOutput(
                name=self.name or "together_python",
                output=output.strip() if output else None,
                stdout=stdout.strip() if stdout else None,
                stderr=stderr.strip() if stderr else None,
                error=error,
            )

        except Exception as e:
            return CodeToolOutput(name=self.name or "together_python", error=f"{type(e).__name__} - {str(e)}", stderr=str(e))

def rm_subdirs(path, onerror=None):
    # NOTE this code is adapted from the one in shutil.rmtree, and is
    # just as fast

    names = []
    try:
        names = os.listdir(path)
    except os.error as err:
        if onerror is not None:
            onerror(os.listdir, path, sys.exc_info())
        else:
            raise

    for name in names:
        fullname = os.path.join(path, name)
        if os.path.isdir(fullname):
            if onerror is not None:
                shutil.rmtree(fullname, False, onerror)
            else:
                # allow the rmtree to fail once, wait and re-try.
                # if the error is raised again, fail
                err_count = 0
                while True:
                    try:
                        shutil.rmtree(fullname, False, None)
                        break
                    except os.error:
                        if err_count > 0:
                            raise
                        err_count += 1
                        time.sleep(RM_SUBDIRS_RETRY_TIME)

def get_timeseries(self, metric: str) -> dict[str, Any]:
        # Check that desired metric is in present data
        if metric not in self.data.keys():
            raise ValueError(
                f'Invalid value for argument `metric`: {metric}. Requested '
                'metric is not present in self.data.keys().',
            )

        timeseries = {}
        # Iterate through datapoints
        for datapoint in self.data[metric]:
            timestamp, metric_value = datapoint
            timeseries.setdefault(metric, []).append(metric_value)
            # Iterate through time units and add them all!
            for field, time in timestamp.state_dict().items():
                time_value = time if isinstance(time, int) else time.total_seconds()
                timeseries.setdefault(field, []).append(time_value)
        # Convert to numpy arrays
        for k, v in timeseries.items():
            if isinstance(v[0], Tensor):
                v = Tensor(v).numpy()
            else:
                v = np.array(v)
            timeseries[k] = v
        return timeseries

def restore_elements_from_packed_bits(
    packed_values: np.ndarray, nbits: int, element_num: int, are_packed_values_signed: bool = False
) -> np.ndarray:
    if len(packed_values.shape) != 1:
        raise NotImplementedError(
            f"Only support 1-rank packed_values. But got {len(packed_values.shape)}"
        )

    if packed_values.dtype == np.int8:
        # As np.unpackbits only supports uint8, need to convert first.
        packed_values = packed_values.astype(np.uint8)
    elif packed_values.dtype != np.uint8:
        raise NotImplementedError(
            f"Only support int8 or uint8 packed_values, but got {packed_values.dtype}"
        )

    bitarray = np.unpackbits(packed_values, bitorder="little")
    pad_required = bitarray.size % nbits != 0
    if pad_required:
        bitarray = np.concatenate([bitarray, np.zeros(nbits - bitarray.size % nbits)]).astype(
            bitarray.dtype
        )
        if bitarray.size % nbits != 0:
            raise ValueError(
                f"The length of bitarray ({bitarray.size}) should be divisible by "
                f"nbits ({nbits})."
            )
    bitarray = bitarray.reshape(-1, nbits)[:element_num, :]
    # The np.packbits doesn't work well for signed int if we feed `bitarray` to it directly.
    # For example, the original signed int is -6, which is packed as 1010 for 4-bit representation,
    # and here `bitarray` is [[0, 1, 0, 1]], where the value will be interpreted as 10 (b'1010')
    # by np.packbits.
    # To make np.packbits work correctly, we need to repeat the sign bit. For example, 1010 will
    # become 11111010, where np.packbits can correctly handle and after converting to int8 it's -6.
    if are_packed_values_signed:
        # Repeat the sign bit to make uint8 to int8 works.
        bitarray = np.repeat(bitarray, [1] * (nbits - 1) + [8 - nbits + 1], axis=1)
    restored_elements = np.packbits(bitarray, bitorder="little", axis=-1).reshape(-1)
    if are_packed_values_signed:
        restored_elements = restored_elements.astype(np.int8)
    return restored_elements

def check_constraints(self, node: torch.fx.Node, ep: ExportedProgram) -> bool:
        if not self.check_common_constraints(node, ep):
            return False

        args = node.args

        ceil_mode = False  # default is False
        if len(args) >= 5:
            ceil_mode = cast(bool, args[4])

        count_include_pad = True  # default is True
        if len(args) >= 6:
            count_include_pad = cast(bool, args[5])

        kernel_size = cast(List[int], args[1])
        pooling_region = kernel_size[0] * kernel_size[1]
        divisor_override = pooling_region  # Default divisor is pooling_region
        if len(args) >= 7:
            divisor_override = cast(int, args[6])

        if ceil_mode:
            why(node, reason="ceil mode is not supported")
            return False

        if count_include_pad:
            why(
                node,
                reason="zero-padding in the averaging calculation is not supported",
            )
            return False

        if divisor_override != pooling_region:
            why(node, reason="divisor override is not supported")
            return False

        return True

def log_summary(
    model: Booster, feature_importance: bool = True, save_model_checkpoint: bool = False
) -> None:
    if wandb.run is None:
        raise wandb.Error("You must call wandb.init() before WandbCallback()")

    if not isinstance(model, Booster):
        raise wandb.Error("Model should be an instance of lightgbm.basic.Booster")

    wandb.run.summary["best_iteration"] = model.best_iteration
    wandb.run.summary["best_score"] = model.best_score

    # Log feature importance
    if feature_importance:
        _log_feature_importance(model)

    if save_model_checkpoint:
        _checkpoint_artifact(model, model.best_iteration, aliases=["best"])

    with wb_telemetry.context() as tel:
        tel.feature.lightgbm_log_summary = True

def dict_to_feature(feature_dict, keys, max_value=None):
    feature = []
    for key, val in feature_dict.items():  # First level
        if key not in keys:
            continue
        if val is None or val == "auto" or key == "autotuning" or val == "":
            continue
        if isinstance(val, dict):
            feature.append(dict_to_feature(val, max_value))
        else:
            feature.append(float(val))

    # normalization, should not matter in tree models
    if max_value is not None:
        norm_feature = []
        for f, mv in zip(feature, max_value):
            norm_feature.append(f / mv)
        feature = norm_feature

    return feature

def validate_project_name(name: str) -> str:
    if not name:
        raise ValueError("Project name cannot be empty")
    if not (registry_name := name.removeprefix(REGISTRY_PREFIX)):
        raise ValueError("Registry name cannot be empty")

    if len(name) > NAME_MAXLEN:
        if registry_name != name:
            msg = f"Invalid registry name {registry_name!r}, must be {NAME_MAXLEN - len(REGISTRY_PREFIX)!r} characters or less"
        else:
            msg = f"Invalid project name {name!r}, must be {NAME_MAXLEN!r} characters or less"
        raise ValueError(msg)

    # Find the first occurrence of any invalid character
    if invalid_chars := set(INVALID_URL_CHARS).intersection(name):
        error_name = registry_name or name
        invalid_chars_repr = ", ".join(sorted(map(repr, invalid_chars)))
        raise ValueError(
            f"Invalid project/registry name {error_name!r}, cannot contain characters: {invalid_chars_repr!s}"
        )
    return name

def forward(self, v: PreprocessingInput) -> torch.Tensor:
        if not torch.jit.isinstance(v, list[str]):
            raise ValueError(f"Unsupported input: {v}")

        if self.lowercase:
            sequences = [sequence.lower() for sequence in v]
        else:
            sequences = v

        unit_sequences = self.tokenizer(sequences)
        # refines type of unit_sequences from Any to List[List[str]]
        assert torch.jit.isinstance(unit_sequences, list[list[str]]), "unit_sequences is not a list of lists."

        set_matrix = torch.zeros(len(unit_sequences), self.vocab_size, dtype=torch.float32)
        for sample_idx, unit_sequence in enumerate(unit_sequences):
            sequence_length = len(unit_sequence)
            for i in range(sequence_length):
                curr_unit = unit_sequence[i]
                if curr_unit in self.unit_to_id:
                    curr_id = self.unit_to_id[curr_unit]
                else:
                    curr_id = self.unit_to_id[self.unknown_symbol]

                if self.is_bag:
                    set_matrix[sample_idx][curr_id] += 1
                else:
                    set_matrix[sample_idx][curr_id] = 1

        return set_matrix

def get_diff(repo, base_commit, commits):
    print("\n### DIFF ###\n")
    code_diff = []
    for commit in commits:
        for diff_obj in commit.diff(base_commit):
            # We always add new python files
            if diff_obj.change_type == "A" and diff_obj.b_path.endswith(".py"):
                code_diff.append(diff_obj.b_path)
            # We check that deleted python files won't break corresponding tests.
            elif diff_obj.change_type == "D" and diff_obj.a_path.endswith(".py"):
                code_diff.append(diff_obj.a_path)
            # Now for modified files
            elif diff_obj.change_type in ["M", "R"] and diff_obj.b_path.endswith(".py"):
                # In case of renames, we'll look at the tests using both the old and new name.
                if diff_obj.a_path != diff_obj.b_path:
                    code_diff.extend([diff_obj.a_path, diff_obj.b_path])
                else:
                    # Otherwise, we check modifications are in code and not docstrings.
                    if diff_is_docstring_only(repo, commit, diff_obj.b_path):
                        print(f"Ignoring diff in {diff_obj.b_path} as it only concerns docstrings or comments.")
                    else:
                        code_diff.append(diff_obj.a_path)

    return code_diff

def scenegraph(self, text, properties=None):
        # since we're using requests ourself,
        # check if the server has started or not
        if self.start_server is not StartServer.DONT_START:
            self.ensure_alive()

        if properties is None:
            properties = {}
        # the only thing the scenegraph knows how to use is text
        properties['inputFormat'] = 'text'
        ctype = "text/plain; charset=utf-8"
        # the json output format is much more useful
        properties['outputFormat'] = 'json'
        try:
            r = requests.post(
                self.endpoint + "/scenegraph",
                params={
                    'properties': str(properties)
                },
                data=text.encode('utf-8') if isinstance(text, str) else text,
                headers={'content-type': ctype},
                timeout=(self.timeout*2)/1000,
            )
            r.raise_for_status()
            if r.encoding is None:
                r.encoding = "utf-8"
            return json.loads(r.text)
        except requests.HTTPError as e:
            if r.text.startswith("Timeout"):
                raise TimeoutException(r.text)
            else:
                raise AnnotationException(r.text)
        except json.JSONDecodeError:
            raise AnnotationException(r.text)

def import_state(solver, tol=1e-15):
    method = str(solver.__str__)

    if "CISD" in method and "UCISD" not in method:
        wf_dict = _rcisd_state(solver, tol=tol)
    elif "UCISD" in method:
        wf_dict = _ucisd_state(solver, tol=tol)
    elif "CCSD" in method and "UCCSD" not in method:
        wf_dict = _rccsd_state(solver, tol=tol)
    elif "UCCSD" in method:
        wf_dict = _uccsd_state(solver, tol=tol)
    elif "tuple" in method and len(solver) == 2:
        if isinstance(solver[0][0], str):
            wf_dict = _shci_state(solver, tol=tol)
        elif isinstance(solver[0][0][0], int):
            wf_dict = _dmrg_state(solver, tol=tol)
        else:
            raise ValueError(
                "For tuple input, the supported objects are"
                " tuple(list[str], array[float]) for SHCI calculations with Dice library and "
                "tuple(list[int], array[float]) for DMRG calculations with the Block2 library."
            )
    else:
        raise ValueError(
            "The supported objects are RCISD, UCISD, RCCSD, and UCCSD for restricted and"
            " unrestricted configuration interaction and coupled cluster calculations, and"
            " tuple(list[str], array[float]) for SHCI calculations with Dice library and "
            "tuple(list[int], array[float]) for DMRG calculations with the Block2 library."
        )
    if "tuple" in method:
        wf = _wfdict_to_statevector(wf_dict, len(solver[0][0]))
    else:
        wf = _wfdict_to_statevector(wf_dict, solver.mol.nao)

    return wf

def interpolate(
    x: Tensor,
    size: int | tuple[int] | None = None,
    scale_factor: float | tuple[float] | None = None,
    mode: str = "nearest",
    align_corners: bool | None = None,
    recompute_scale_factor: bool | None = None,
    antialias: bool | None = None,
    data_layout: str | None = "NCHW",
    name: str = "interpolate",
):
    assert recompute_scale_factor is None, "recompute_scale_factor is not supported."
    assert antialias is None, "antialias is not supported."

    if size is None:
        size = []
        for i, dim in enumerate(data_layout):
            # Only upscale spatial dimensions.
            if dim not in ["N", "C"]:
                if isinstance(scale_factor, list | tuple):
                    size.append(int(x.shape[i] * scale_factor[len(size)]))
                else:
                    size.append(int(x.shape[i] * scale_factor))

    if mode.startswith("nearest"):
        mode = "nearest_neighbor"
    elif mode[0:2] == "bi":
        mode = mode[2:]

    if mode == "nearest_neighbor":
        coord_trans = "asymmetric"
    elif align_corners:
        coord_trans = "align_corners"
    else:
        coord_trans = "half_pixel"

    return wrap_nested(
        _op.image.resize2d(
            x._expr,
            size,
            layout=data_layout,
            method=mode,
            coordinate_transformation_mode=coord_trans,
        ),
        name,
    )

def parse_text_and_label(data,
                         mode,
                         first_sequence=None,
                         second_sequence=None,
                         label=None):
    text_a, text_b, labels = None, None, None
    if isinstance(data, str):
        text_a = data
    elif isinstance(data, tuple) or isinstance(data, list):
        if len(data) == 3:
            text_a, text_b, labels = data
        elif len(data) == 2:
            if mode == ModeKeys.INFERENCE:
                text_a, text_b = data
            else:
                text_a, labels = data
    elif isinstance(data, Mapping):
        text_a = data.get(first_sequence)
        text_b = data.get(second_sequence)
        if label is None or isinstance(label, str):
            labels = data.get(label)
        else:
            labels = [data.get(lb) for lb in label]
    return text_a, text_b, labels

def check_llm_quantization_backend_incompatibility(config: "ModelConfig") -> None:  # noqa: F821
    if config.model_type != MODEL_LLM:
        return

    if config.quantization is None:
        return

    backend_type = None
    if config.backend:
        backend_type = config.backend.get("type", None)

    # If backend was explicitly set to Ray, then we need to raise an error
    if backend_type == "ray":
        raise ConfigValidationError(f"LLM with quantization requires the 'local' backend, found: '{backend_type}'")

    # If the backend is not explicitly set, then we need to check if a Ray process is running
    # If a Ray process is running, then we need to raise an error because the backend will be set to Ray
    if config.backend is None:
        try:
            # May not be installed, so we need to catch the ImportError
            import ray

            if ray.is_initialized():
                raise ConfigValidationError(
                    "LLM with quantization requires the 'local' backend, but backend will be set "
                    "to Ray since Ray is already running locally."
                )
        except ImportError:
            pass

def apply_sorting(objects: List[Any], sort_by: str, sort_order: str) -> List[Any]:
    def get_nested_attr(obj, attr_path: str):
        """Get nested attribute using dot notation."""
        attrs = attr_path.split(".")
        current = obj
        for attr in attrs:
            if hasattr(current, attr):
                current = getattr(current, attr)
            elif isinstance(current, dict) and attr in current:
                current = current[attr]
            else:
                return None
        return current

    def sort_key(obj):
        value = get_nested_attr(obj, sort_by)
        if value is None:
            return ("", 0, None)

        if isinstance(value, str):
            return (value.lower(), 1, None)
        elif isinstance(value, (int, float)):
            return ("", 1, value)
        else:
            return (str(value).lower(), 1, None)

    reverse = sort_order.lower() == "desc"

    try:
        return sorted(objects, key=sort_key, reverse=reverse)
    except Exception as e:
        logger.warning(f"Failed to sort objects by '{sort_by}': {e}")
        return objects

def compute_kendall_tau(self, csv_data: DataFrame) -> float:
        concor = discor = 0

        for segment_id in sorted(csv_data.segment_id.unique()):
            group_csv_data = csv_data[csv_data.segment_id == segment_id]

            examples = group_csv_data.to_dict('records')

            for i in range(0, len(examples)):
                for j in range(i + 1, len(examples)):
                    if self.raw_score[i] - self.raw_score[
                            j] >= self.gap_threshold:
                        if self.score[i] > self.score[j]:
                            concor += 1
                        elif self.score[i] < self.score[j]:
                            discor += 1
                    elif self.raw_score[i] - self.raw_score[
                            j] <= -self.gap_threshold:
                        if self.score[i] < self.score[j]:
                            concor += 1
                        elif self.score[i] > self.score[j]:
                            discor += 1

        if concor + discor == 0:
            logger.warning(
                'We don\'t have available pairs when evaluation. '
                'Marking the kendall tau correlation as the lowest value (-1.0).'
            )
            return -1.0
        else:
            return (concor - discor) / (concor + discor)

def resolve_dot_names(
    config: Config, dot_names: List[Optional[str]]
) -> Tuple[Any, ...]:
    # TODO: include schema?
    resolved = {}
    output: List[Any] = []
    errors = []
    for name in dot_names:
        if name is None:
            output.append(name)
        else:
            section = name.split(".")[0]
            # We want to avoid resolving the same thing twice
            if section not in resolved:
                if registry.is_promise(config[section]):
                    # Otherwise we can't resolve [corpus] if it's a promise
                    result = registry.resolve({"config": config[section]})["config"]
                else:
                    result = registry.resolve(config[section])
                resolved[section] = result
            try:
                output.append(dot_to_object(resolved, name))  # type: ignore[arg-type]
            except KeyError:
                msg = f"not a valid section reference: {name}"
                errors.append({"loc": name.split("."), "msg": msg})
    if errors:
        raise ConfigValidationError(config=config, errors=errors)
    return tuple(output)

def convert_to_any_value(value: Any) -> AnyValue:
    if isinstance(value, tuple):
        value = list(value)
    any_value = AnyValue()

    if isinstance(value, str):
        any_value.string_value = value
    elif isinstance(value, bool):
        any_value.bool_value = value
    elif isinstance(value, int):
        any_value.int_value = value
    elif isinstance(value, float):
        any_value.double_value = value
    elif isinstance(value, bytes):
        any_value.bytes_value = value
    elif isinstance(value, list):
        array_value = ArrayValue()
        for item in value:
            array_value.values.append(convert_to_any_value(item))
        any_value.array_value.CopyFrom(array_value)
    elif isinstance(value, dict):
        kv_list = KeyValueList()
        for k, v in value.items():
            kv = KeyValue(key=k, value=convert_to_any_value(v))
            kv_list.values.append(kv)
        any_value.kvlist_value.CopyFrom(kv_list)
    else:
        raise ValueError(f"Unsupported value type: {type(value)}")

    return any_value

def compression_preparation(model, compression_technique_list, mpu):
    # Here we first replace all module with our linear wrapper
    for module_name, module in model.named_modules():
        if is_module_compressible(module, mpu):
            module_replacement(model, module_name, mpu=mpu)
    for module_name_lists, _, compression_technique in compression_technique_list:
        for mnl in module_name_lists:
            for module_name in mnl:
                module_replacement(model, module_name, compression_technique)

    return model

def set_train_data(self, data):
        self.cancel()
        self.Information.data_sampled.clear()
        self.Error.train_data_error.clear()

        if data is not None:
            data_errors = [
                ("Train dataset is empty.", len(data) == 0),
                (
                    "Train data input requires a target variable.",
                    not data.domain.class_vars
                ),
                ("Target variable has no values.", np.isnan(data.Y).all()),
                (
                    "Target variable has only one value.",
                    data.domain.has_discrete_class and len(unique(data.Y)) < 2
                ),
                ("Data has no features to learn from.", data.X.shape[1] == 0),
            ]

            for error_msg, cond in data_errors:
                if cond:
                    self.Error.train_data_error(error_msg)
                    data = None
                    break

        if isinstance(data, SqlTable):
            if len(data) < AUTO_DL_LIMIT:
                data = Table(data)
            else:
                self.Information.data_sampled()
                data_sample = data.sample_time(1, no_cache=True)
                data_sample.download_data(AUTO_DL_LIMIT, partial=True)
                data = Table(data_sample)

        self.train_data_missing_vals = \
            data is not None and np.isnan(data.Y).any()
        if self.train_data_missing_vals or self.test_data_missing_vals:
            self.Warning.missing_data(self._which_missing_data())
            if data:
                data = HasClass()(data)
        else:
            self.Warning.missing_data.clear()

        self.data = data
        self.closeContext()
        self._update_scorers()
        self._update_controls()
        if data is not None:
            self._update_class_selection()
            self.openContext(data.domain)
            if self.fold_feature_selected and bool(self.feature_model):
                self.resampling = OWTestAndScore.FeatureFold
        self._invalidate()

def np_from_file(file_path, compresslevel):
  if not tf.io.gfile.exists(file_path):
    raise FileNotFoundError(file_path)
  res = []
  with tf.io.gfile.GFile(file_path, 'rb') as f:
    with gzip.GzipFile(fileobj=f, compresslevel=compresslevel) as gzipf:
      while True:
        try:
          res.append(np.load(gzipf, allow_pickle=False))
        except Exception:  # pylint: disable=broad-except
          break
  return res

def count_message_tokens(messages: List[Dict]) -> int:
        total_tokens = 0
        for message in messages:
            content = message.get("content", "")
            if isinstance(content, str):
                total_tokens += num_tokens_from_string(content)
            elif isinstance(content, list):
                # Handle structured content (tool calls, etc.)
                for item in content:
                    if isinstance(item, dict):
                        total_tokens += num_tokens_from_string(str(item))
        return total_tokens

def load_pretrained_weights(model, weight_path):
    checkpoint = load_checkpoint(weight_path)
    if 'state_dict' in checkpoint:
        state_dict = checkpoint['state_dict']
    else:
        state_dict = checkpoint

    model_dict = model.state_dict()
    new_state_dict = OrderedDict()
    matched_layers, discarded_layers = [], []

    for k, v in state_dict.items():
        if k.startswith('module.'):
            k = k[7:] # discard module.

        if k in model_dict and model_dict[k].size() == v.size():
            new_state_dict[k] = v
            matched_layers.append(k)
        else:
            discarded_layers.append(k)

    model_dict.update(new_state_dict)
    model.load_state_dict(model_dict)

    if len(matched_layers) == 0:
        warnings.warn(
            'The pretrained weights "{}" cannot be loaded, '
            'please check the key names manually '
            '(** ignored and continue **)'.format(weight_path)
        )
    else:
        print(
            'Successfully loaded pretrained weights from "{}"'.
            format(weight_path)
        )
        if len(discarded_layers) > 0:
            print(
                '** The following layers are discarded '
                'due to unmatched keys or layer size: {}'.
                format(discarded_layers)
            )

def stop_all(state, user, name, node_group):
    if not state and not user and not name and not node_group:
        console.print("[red]Error[/]: You must provide at least one filter.")
        sys.exit(1)

    client = get_client()

    if node_group:
        resolve_node_groups(node_group, is_exact_match=True)

    list_params: dict[str, Any] = {}
    if state:
        list_params["status"] = list(state)
    if user:
        list_params["created_by"] = list(user)
    if name:
        list_params["q"] = name
    if node_group:
        list_params["node_groups"] = list(node_group)

    jobs = client.job.list_all(**list_params)

    job_filtered = _filter_jobs(
        jobs,
        exact_users=user,
        exact_names=name,
    )

    if len(job_filtered) == 0:
        console.print(
            "[yellow]No jobs matched your filters.[/]\n"
            "[cyan]Note[/]: stop-all requires an exact match for '--user' "
            "(User ID shown in `lep job list`). Please verify your input."
        )
        sys.exit(0)

    _display_jobs_table(
        job_filtered, dashboard_base_url=client.get_dashboard_base_url()
    )

    user_set = set(job.metadata.owner for job in job_filtered)

    console.print(f"Total [red]{len(job_filtered)}[/] jobs to stop.")
    console.print(
        f"These jobs belong to [green]{len(user_set)}[/] user(s):"
        f" [green]{', '.join(user_set)}[/]"
    )

    console.print("To confirm stop, please enter the number of jobs to stop:")
    try:
        confirm_count = int(click.prompt("Number of jobs to stop", type=int))
        if confirm_count != len(job_filtered):
            console.print(
                f"[red]Error[/]: Number mismatch. Expected {len(job_filtered)} jobs."
            )
            sys.exit(1)
    except ValueError:
        console.print("[red]Error[/]: Please enter a valid number.")
        sys.exit(1)

    for job in job_filtered:
        client.job.update(job.metadata.id_, spec={"spec": {"stopped": True}})
        console.print(f"Job [green]{job.metadata.id_}[/] stopped successfully.")

async def put_directory(
        self,
        local_path: Optional[str] = None,
        to_path: Optional[str] = None,
        ignore_file: Optional[str] = None,
    ) -> None:
        to_path = "" if to_path is None else to_path

        if local_path is None:
            local_path = "."

        included_files = None
        if ignore_file:
            with open(ignore_file, "r") as f:
                ignore_patterns = f.readlines()

            included_files = filter_files(local_path, ignore_patterns)

        for local_file_path in Path(local_path).expanduser().rglob("*"):
            if (
                included_files is not None
                and str(local_file_path.relative_to(local_path)) not in included_files
            ):
                continue
            elif not local_file_path.is_dir():
                remote_file_path = Path(to_path) / local_file_path.relative_to(
                    local_path
                )
                with open(local_file_path, "rb") as local_file:
                    local_file_content = local_file.read()

                await self.write_path(
                    remote_file_path.as_posix(), content=local_file_content
                )

def forward(self, *args, **kwargs):
        # if we've never run the model before, do so now so we can inspect the model structure
        if self.prototype_trace is None:
            self._setup_prototype(*args, **kwargs)

        plates = self._create_plates(*args, **kwargs)
        result = {}
        for name, site in self.prototype_trace.iter_stochastic_nodes():
            with ExitStack() as stack:
                for frame in site["cond_indep_stack"]:
                    if frame.vectorized:
                        stack.enter_context(plates[frame.name])
                attr_get = operator.attrgetter(name)
                result[name] = pyro.sample(
                    name, dist.Delta(attr_get(self), event_dim=site["fn"].event_dim)
                )
        return result

def stop(names: list[str]) -> None:
    all_good = True

    with _info_file() as info:
        if not names:
            names = list(info.servers.keys())

        if not names:
            _echo_bad("No servers to stop.")
            sys.exit(1)

        for name in names:
            server = info.servers.pop(name, None)
            if not server:
                _echo_bad(f"No server called {name!r}.")
                all_good = False
                continue

            if not server.managed:
                _echo_info(
                    f"Forgetting {name!r}, but not stopping it because"
                    + " it wasn't started by this script."
                )
                continue

            try:
                _stop_container(name)
            except Exception as e:
                traceback.print_exception(
                    type(e),
                    e,
                    e.__traceback__,
                    file=sys.stderr,
                )
                _echo_bad(f"Failed to stop {name!r}; forgetting it anyway.")
                all_good = False
            else:
                _echo_info(f"Shut down {name!r}.")

    if not all_good:
        sys.exit(1)

def update_metrics(ctx, yes):
    repo_path = ctx.obj['repo']
    repo = Repo.from_path(repo_path)

    click.secho(
        f"This command will update Runs from Aim Repo '{repo_path}' to the latest data format to ensure better "
        f'performance. Please make sure no Runs are active and Aim UI is not running.'
    )
    if yes:
        confirmed = True
    else:
        confirmed = click.confirm('Do you want to proceed?')
    if not confirmed:
        return

    index_manager = RepoIndexManager.get_index_manager(repo)
    hashes = repo.list_all_runs()
    for run_hash in tqdm.tqdm(hashes, desc='Updating runs', total=len(hashes)):
        meta_tree = repo.request_tree('meta', run_hash, read_only=False)
        meta_run_tree = meta_tree.subtree(('meta', 'chunks', run_hash))
        try:
            # check if the Run has already been updated.
            meta_run_tree.first_key('typed_traces')
            click.secho(f'Run {run_hash} is uo-to-date. Skipping.')
            continue
        except KeyError:
            for ctx_idx, run_ctx_dict in meta_run_tree.subtree('traces').items():
                assert isinstance(ctx_idx, int)
                for seq_name in run_ctx_dict.keys():
                    assert isinstance(seq_name, str)
                    dtype = run_ctx_dict[seq_name].get('dtype', 'float')
                    seq_type = SEQUENCE_TYPE_MAP.get(dtype, 'sequence')
                    meta_run_tree['typed_traces', seq_type, ctx_idx, seq_name] = 1
            index_manager.index(run_hash)

def calculate_distance(vec1: np.array, vec2: np.array, range_per_feature: np.array) -> float:
    sum_dist = 0
    num_features = 0
    for col_index in range(len(vec1)):
        if range_per_feature[col_index] == -1:
            # categorical feature
            if pd.isnull(vec1[col_index]) and pd.isnull(vec2[col_index]):
                sum_dist += 0
            elif (pd.isnull(vec1[col_index]) or pd.isnull(vec2[col_index])) or vec1[col_index] != vec2[col_index]:
                sum_dist += 1
            num_features += 1
        else:
            # numeric feature
            if pd.isnull(vec1[col_index]) or pd.isnull(vec2[col_index]):
                continue
            sum_dist += np.abs(vec1[col_index] - vec2[col_index]) / range_per_feature[col_index]
            num_features += 1

    if num_features == 0:
        return np.nan
    return sum_dist / num_features

def infer_matcher_loss(data_format: str, problem_type: str):
    if data_format == "pair":
        if problem_type is None:
            return [MULTI_NEGATIVES_SOFTMAX_LOSS]
        elif problem_type == BINARY:
            return [CONTRASTIVE_LOSS]
        elif problem_type == REGRESSION:
            return ["cosine_similarity_loss"]
        else:
            raise ValueError(f"Unsupported data format {data_format} with problem type {problem_type}")
    elif data_format == "triplet":
        if problem_type is None:
            return [MULTI_NEGATIVES_SOFTMAX_LOSS]
        else:
            raise ValueError(f"Unsupported data format {data_format} with problem type {problem_type}")
    else:
        raise ValueError(f"Unsupported data format: {data_format}")

def write_to_online_store(
    arrow_table: pa.Table,
    feature_view: Union[BatchFeatureView, StreamFeatureView, FeatureView],
    online_store: OnlineStore,
    repo_config: RepoConfig,
) -> None:
    if not getattr(feature_view, "online", False):
        return

    try:
        join_key_to_value_type: Dict[str, ValueType] = {}
        if hasattr(feature_view, "entity_columns") and feature_view.entity_columns:
            join_key_to_value_type = {
                entity.name: entity.dtype.to_value_type()
                for entity in feature_view.entity_columns
            }

        batch_size = repo_config.materialization_config.online_write_batch_size
        # Single batch if None (backward compatible), otherwise use configured batch_size
        batches = (
            [arrow_table]
            if batch_size is None
            else arrow_table.to_batches(max_chunksize=batch_size)
        )

        total_rows = 0
        for batch in batches:
            rows_to_write = _convert_arrow_to_proto(
                batch, feature_view, join_key_to_value_type
            )

            if rows_to_write:
                online_store.online_write_batch(
                    config=repo_config,
                    table=feature_view,
                    data=rows_to_write,
                    progress=lambda x: None,
                )
                total_rows += len(rows_to_write)

        if total_rows > 0:
            logger.debug(
                f"Successfully wrote {total_rows} rows to online store for {feature_view.name}"
            )
        else:
            logger.warning(f"No rows to write for {feature_view.name}")

    except Exception as e:
        logger.error(f"Failed to write to online store for {feature_view.name}: {e}")

def read_env_vars_and_defaults(var: str) -> Optional[str]:
    def none_if_empty(value: Optional[str]) -> Optional[str]:
        """Returns None if value is an empty string"""
        if value is not None and len(value) == 0:
            return None
        else:
            return value

    try:
        return none_if_empty(os.environ[var])
    except KeyError:
        try:
            default_val = configs.default_env_vars()[var]
            if isinstance(default_val, str):
                return none_if_empty(default_val)
            else:
                return default_val
        except KeyError:
            return None

def standardize(item, structure, array_dict_types):
    for k, v in structure.items():
        if k not in item:
            # If the structure/field does not exist
            if isinstance(v, dict) and (k not in array_dict_types):
                # If key k is of type dict, and not not a type list[dict]
                item[k] = {}
                standardize(item[k], v, array_dict_types)
            elif isinstance(v, dict) and (k in array_dict_types):
                # If key k is of type dict, and is actually of type list[dict],
                # just treat as a list and set to None by default
                item[k] = None
            else:
                # Assign a default type
                item[k] = v()
        else:
            # If the structure/field already exists and is a list or dict
            if isinstance(item[k], list):
                # ignore if item is a nested list structure or list of non-dicts
                condition = (
                    not (len(item[k]) > 0 and isinstance(item[k][0], list))
                ) and (
                    not (
                        len(item[k]) > 0 and not (isinstance(item[k][0], (list, dict)))
                    )
                )
                if condition:
                    for sub_item in item[k]:
                        standardize(sub_item, v, array_dict_types)
            elif isinstance(item[k], dict):
                standardize(item[k], v, array_dict_types)

def get_feature_view_by_name(
        self, fv_name: str, name_alias: str, project: str
    ) -> FeatureView:
        try:
            fv = self.store.registry.get_feature_view(name=fv_name, project=project)
            if name_alias is not None:
                for fs in self.store.registry.list_feature_services(project=project):
                    for p in fs.feature_view_projections:
                        if p.name_alias == name_alias:
                            logger.debug(
                                f"Found matching FeatureService {fs.name} with projection {p}"
                            )
                            fv = fv.with_projection(p)
            return fv
        except FeatureViewNotFoundException:
            try:
                return self.store.registry.get_stream_feature_view(
                    name=fv_name, project=project
                )
            except Exception as e:
                logger.error(
                    f"Cannot find any FeatureView by name {fv_name} in project {project}"
                )
                raise e

def get_slice_bound(self, label: Hashable, side: Literal["left", "right"]) -> int:
        if side not in ("left", "right"):
            raise ValueError(
                "Invalid value for side kwarg, must be either "
                f"'left' or 'right': {side}"
            )

        original_label = label

        # For datetime indices label may be a string that has to be converted
        # to datetime boundary according to its resolution.
        label = self._maybe_cast_slice_bound(label, side)

        # we need to look up the label
        try:
            slc = self.get_loc(label)
        except KeyError:
            try:
                return self._searchsorted_monotonic(label, side)
            except ValueError:
                raise KeyError(
                    f"Cannot get {side} slice bound for non-monotonic index "
                    f"with a missing label {original_label!r}. "
                    "Either sort the index or specify an existing label."
                ) from None

        if isinstance(slc, np.ndarray):
            # get_loc may return a boolean array, which
            # is OK as long as they are representable by a slice.
            assert is_bool_dtype(slc.dtype)
            slc = lib.maybe_booleans_to_slice(slc.view("u1"))  # type: ignore[assignment]
            if isinstance(slc, np.ndarray):
                raise KeyError(
                    f"Cannot get {side} slice bound for non-unique "
                    f"label: {original_label!r}"
                )

        if isinstance(slc, slice):
            if side == "left":
                return slc.start
            else:
                return slc.stop
        elif side == "right":
            return slc + 1
        else:
            return slc

def check_storage_credentials() -> Tuple[bool, Optional[str]]:
    def _profile_exists(file_path: str, header: str) -> bool:
        expanded = os.path.expanduser(file_path)
        if not os.path.isfile(expanded):
            return False
        with open(expanded, 'r', encoding='utf-8') as f:
            return any(header in line for line in f)

    hints = None
    profile_in_cred = _profile_exists(VASTDATA_CREDENTIALS_PATH,
                                      f'[{VASTDATA_PROFILE_NAME}]')
    profile_in_config = _profile_exists(VASTDATA_CONFIG_PATH,
                                        f'[profile {VASTDATA_PROFILE_NAME}]')

    if not profile_in_cred:
        hints = (f'[{VASTDATA_PROFILE_NAME}] profile is not set in '
                 f'{VASTDATA_CREDENTIALS_PATH}.')
    if not profile_in_config:
        if hints:
            hints += ' Additionally, '
        else:
            hints = ''
        hints += (f'[{VASTDATA_PROFILE_NAME}] profile is not set in '
                  f'{VASTDATA_CONFIG_PATH}.')

    if hints:
        hints += ' Run the following commands:'
        if not profile_in_cred:
            hints += f'\n{_INDENT_PREFIX}  $ pip install "skypilot[vastdata]"'
            hints += (f'\n{_INDENT_PREFIX}  $ AWS_SHARED_CREDENTIALS_FILE='
                      f'{VASTDATA_CREDENTIALS_PATH} aws configure --profile '
                      f'{VASTDATA_PROFILE_NAME}')
        if not profile_in_config:
            hints += (f'\n{_INDENT_PREFIX}  $ AWS_CONFIG_FILE='
                      f'{VASTDATA_CONFIG_PATH} aws configure set endpoint_url'
                      f' <ENDPOINT_URL> --profile '
                      f'{VASTDATA_PROFILE_NAME}')
            hints += (f'\n{_INDENT_PREFIX} For more information, see: '
                      'https://docs.skypilot.co/en/latest/'
                      'getting-started/installation.html#vastdata')

    return (False, hints) if hints else (True, hints)

def plot_lags(series, lags=1, suptitle=None):
    from sktime.utils.dependencies import _check_soft_dependencies

    _check_soft_dependencies("matplotlib")
    import matplotlib.pyplot as plt
    import numpy as np
    import pandas as pd

    from sktime.utils.validation.forecasting import check_y

    check_y(series)

    if isinstance(lags, int):
        single_lag = True
        lags = [lags]
    elif isinstance(lags, (tuple, list, np.ndarray)):
        single_lag = False
    else:
        raise ValueError("`lags should be an integer, tuple, list, or np.ndarray.")

    length = len(lags)
    n_cols = min(3, length)
    n_rows = math.ceil(length / n_cols)
    fig, ax = plt.subplots(
        nrows=n_rows,
        ncols=n_cols,
        figsize=(8, 6 * n_rows),
        sharex=True,
        sharey=True,
    )
    if single_lag:
        axes = ax
        pd.plotting.lag_plot(series, lag=lags[0], ax=axes)
    else:
        axes = ax.ravel()
        for i, val in enumerate(lags):
            pd.plotting.lag_plot(series, lag=val, ax=axes[i])

    if suptitle is None:
        fig.suptitle(
            f"Plot of series against lags {', '.join([str(lag) for lag in lags])}",
            size="xx-large",
        )
    else:
        fig.suptitle(suptitle, size="xx-large")

    return fig, np.array(fig.get_axes())

def min(
        self,
        axis: AxisInt | None = None,
        skipna: bool = True,
        *args: Any,
        **kwargs: Any,
    ) -> object:
        nv.validate_min(args, kwargs)
        nv.validate_minmax_axis(axis)

        if not len(self):
            return self._na_value

        if len(self) and self.is_monotonic_increasing:
            # quick check
            first = self[0]
            if not isna(first):
                return maybe_unbox_numpy_scalar(first)

        if not self._is_multi and self.hasnans:
            # Take advantage of cache
            mask = self._isnan
            if not skipna or mask.all():
                return self._na_value

        if not self._is_multi and not isinstance(self._values, np.ndarray):
            return self._values._reduce(name="min", skipna=skipna)

        return maybe_unbox_numpy_scalar(nanops.nanmin(self._values, skipna=skipna))

def convert_all_safetensors_to_bins(folder: str):
    for file in os.listdir(folder):
        path = os.path.join(folder, file)
        if file.endswith(".safetensors"):
            new_path = path.replace(".safetensors", ".bin").replace("model", "pytorch_model")
            state_dict = load_file(path)
            os.remove(path)
            torch.save(state_dict, new_path)
        # Adapt the index as well
        elif file == SAFE_WEIGHTS_INDEX_NAME:
            new_path = os.path.join(folder, WEIGHTS_INDEX_NAME)
            with open(path) as f:
                index = json.loads(f.read())
            os.remove(path)
            if "weight_map" in index.keys():
                weight_map = index["weight_map"]
                new_weight_map = {}
                for k, v in weight_map.items():
                    new_weight_map[k] = v.replace(".safetensors", ".bin").replace("model", "pytorch_model")
            index["weight_map"] = new_weight_map
            with open(new_path, "w") as f:
                f.write(json.dumps(index, indent=4))

def reshard_for_pipeline_parallelism(num_layers, state_dict):
    pp_rank = parallel_state.get_pipeline_model_parallel_rank()
    pp_size = parallel_state.get_pipeline_model_parallel_world_size()

    stage_layers = num_layers // pp_size
    pp_offset = pp_rank * stage_layers

    encoder_layers_key = "model.language_model.encoder.layers."

    def filter_in_pp_rank(key):
        if key.startswith(encoder_layers_key):
            layer_idx = int(key.split(".")[4])
            return pp_offset <= layer_idx < (pp_offset + stage_layers)
        elif key.startswith("model.language_model.encoder.final_layernorm") and not pp_rank == (pp_size - 1):
            return False
        else:
            return True

    def shift_layer_idx(key):
        """If the key is for a transformer layer, shift down the layer index to select the
        correct layer for this pipeline stage."""
        if key.startswith(encoder_layers_key):
            layer_idx = int(key.split(".")[4])
            return f"{encoder_layers_key}{str(layer_idx - pp_offset)}.{'.'.join(key.split('.')[5:])}"
        else:
            return key

    state_dict = {shift_layer_idx(k): v for k, v in state_dict.items() if filter_in_pp_rank(k)}

    return state_dict

def decode_example(self, value: dict, token_per_repo_id=None) -> "Nifti1ImageWrapper":
        if config.NIBABEL_AVAILABLE:
            import nibabel as nib
        else:
            raise ImportError("To support decoding NIfTI files, please install 'nibabel'.")

        if token_per_repo_id is None:
            token_per_repo_id = {}

        path, bytes_ = value["path"], value["bytes"]
        if bytes_ is None:
            if path is None:
                raise ValueError(f"A nifti should have one of 'path' or 'bytes' but both are None in {value}.")
            else:
                # gzipped files have the structure: 'gzip://T1.nii::<local_path>'
                if path.startswith("gzip://") and is_local_path(path.split("::")[-1]):
                    path = path.split("::")[-1]
                if is_local_path(path):
                    nifti = nib.load(path)
                else:
                    source_url = path.split("::")[-1]
                    pattern = (
                        config.HUB_DATASETS_URL
                        if source_url.startswith(config.HF_ENDPOINT)
                        else config.HUB_DATASETS_HFFS_URL
                    )
                    source_url_fields = string_to_dict(source_url, pattern)
                    token = (
                        token_per_repo_id.get(source_url_fields["repo_id"]) if source_url_fields is not None else None
                    )
                    download_config = DownloadConfig(token=token)
                    with xopen(path, "rb", download_config=download_config) as f:
                        nifti = nib.load(f)
        else:
            import gzip

            if (
                bytes_[:2] == b"\x1f\x8b"
            ):  # gzip magic number, see https://stackoverflow.com/a/76055284/9534390 or "Magic number" on https://en.wikipedia.org/wiki/Gzip
                bytes_ = gzip.decompress(bytes_)

            nifti = nib.Nifti1Image.from_bytes(bytes_)

        return Nifti1ImageWrapper(nifti)

def http_user_agent(user_agent: dict | str | None = None) -> str:
    ua = f"transformers/{__version__}; python/{sys.version.split()[0]}; session_id/{SESSION_ID}"
    if is_torch_available():
        ua += f"; torch/{get_torch_version()}"
    if constants.HF_HUB_DISABLE_TELEMETRY:
        return ua + "; telemetry/off"
    if is_training_run_on_sagemaker():
        ua += "; " + "; ".join(f"{k}/{v}" for k, v in define_sagemaker_information().items())
    # CI will set this value to True
    if os.environ.get("TRANSFORMERS_IS_CI", "").upper() in ENV_VARS_TRUE_VALUES:
        ua += "; is_ci/true"
    if isinstance(user_agent, dict):
        ua += "; " + "; ".join(f"{k}/{v}" for k, v in user_agent.items())
    elif isinstance(user_agent, str):
        ua += "; " + user_agent
    return ua

def subprocess_run_for_testing(command, env=None, timeout=60, stdout=None,
                               stderr=None, check=False, text=True,
                               capture_output=False, **kwargs):
    if sys.platform == 'emscripten':
        import pytest
        pytest.skip('emscripten does not support subprocesses')
    if capture_output:
        stdout = stderr = subprocess.PIPE
    # Add CREATE_NO_WINDOW flag on Windows to prevent console window overhead
    # This is added in an attempt to fix flaky timeouts of subprocesses on Windows
    if sys.platform == 'win32':
        if 'creationflags' not in kwargs:
            kwargs['creationflags'] = subprocess.CREATE_NO_WINDOW
        else:
            kwargs['creationflags'] |= subprocess.CREATE_NO_WINDOW
    try:
        proc = subprocess.run(
            command, env=env,
            timeout=timeout, check=check,
            stdout=stdout, stderr=stderr,
            text=text, **kwargs
        )
    except BlockingIOError:
        if sys.platform == "cygwin":
            # Might want to make this more specific
            import pytest
            pytest.xfail("Fork failure")
        raise
    except subprocess.CalledProcessError as e:
        if e.stdout:
            _log.error(f"Subprocess output:\n{e.stdout}")
        if e.stderr:
            _log.error(f"Subprocess error:\n{e.stderr}")
        raise e
    if proc.stdout:
        _log.debug(f"Subprocess output:\n{proc.stdout}")
    if proc.stderr:
        _log.debug(f"Subprocess error:\n{proc.stderr}")
    return proc

def get_many(
        self,
        keys: Iterable[Union[str, S3GetObject]],
        return_missing: bool = False,
        return_info: bool = True,
    ) -> List[S3Object]:

        def _get():
            res = self._read_many_files(
                "get",
                map(self._url_and_range, keys),
                allow_missing=return_missing,
                verify=True,
                verbose=False,
                info=return_info,
                listing=True,
            )

            for s3prefix, s3url, fname in res:
                if return_info:
                    if fname:
                        # We have a metadata file to read from
                        with open(
                            os.path.join(self._tmpdir, "%s_meta" % fname), "r"
                        ) as f:
                            info = json.load(f)
                        range_info = info.get("range_result")
                        if range_info:
                            range_info = RangeInfo(
                                range_info["total"],
                                request_offset=range_info["start"],
                                request_length=range_info["end"]
                                - range_info["start"]
                                + 1,
                            )
                            yield self._s3root, s3url, os.path.join(
                                self._tmpdir, fname
                            ), None, info.get("content_type"), info.get(
                                "metadata", {}
                            ), range_info, info[
                                "last_modified"
                            ], info.get(
                                "encryption"
                            )
                    else:
                        yield self._s3root, s3prefix, None
                else:
                    if fname:
                        yield self._s3root, s3url, os.path.join(self._tmpdir, fname)
                    else:
                        # missing entries per return_missing=True
                        yield self._s3root, s3prefix, None

        return list(starmap(S3Object, _get()))

def check_connections(gd):
    # check that inputs and outputs line up
    for k, v in gd.items():
        for i in v.inputs:
            if isinstance(i, str):
                assert k in gd[i].outputs
            else:
                assert k in gd[i.name].outputs
        for i in v.outputs:
            inputs = [
                inp if isinstance(inp, str) else inp.name
                for inp in gd[i].inputs
            ]
            assert k in inputs
        for i in v.control_inputs:
            if isinstance(i, str):
                assert k in gd[i].control_outputs
            else:
                assert k in gd[i.name].control_outputs
        for i in v.control_outputs:
            control_inputs = [
                inp if isinstance(inp, str) else inp.name
                for inp in gd[i].control_inputs
            ]
            assert k in control_inputs

def load(cls, path):
        # Open unicode file.
        s = open(path, "rb").read()
        s = s.lstrip(codecs.BOM_UTF8)
        s = decode_utf8(s)
        a = {}
        v = {}
        # Parse document name and type.
        # Parse document terms and frequency.
        for s in s.splitlines():
            if s.startswith("#"): # comment
                a["description"] = a.get("description", "") + s.lstrip("#").strip() + "\n"
            elif s.startswith("@name:"):
                a["name"] = s[len("@name:") + 1:].replace("\\n", "\n")
            elif s.startswith("@type:"):
                a["type"] = s[len("@type:") + 1:].replace("\\n", "\n")
            elif s.startswith("@language:"):
                a["lang"] = s[len("@lang:") + 1:].replace("\\n", "\n")
            else:
                s = s.split(" ")
                w, f = " ".join(s[:-1]), s[-1]
                if f.isdigit():
                    v[w] = int(f)
                else:
                    v[w] = float(f)
        return cls(v, name = a.get("name"),
                      type = a.get("type"),
                  language = a.get("lang"),
               description = a.get("description").rstrip("\n"))

def speaker_diarization_evaluation(folder_name, lda_dimensions):
    types = ('*.wav', )
    wav_files = []
    for files in types:
        wav_files.extend(glob.glob(os.path.join(folder_name, files)))

    wav_files = sorted(wav_files)

    # get number of unique speakers per file (from ground-truth)    
    num_speakers = []
    for wav_file in wav_files:
        gt_file = wav_file.replace('.wav', '.segments')
        if os.path.isfile(gt_file):
            _, _, seg_labs = read_segmentation_gt(gt_file)
            num_speakers.append(len(list(set(seg_labs))))
