def augment_brackets(sents, ratio=0.1):
    new_sents = []
    for sent in sents:
        text_idx = find_text_idx(sent)
        text_line = sent[text_idx]
        if text_line.count("[") > 0 or text_line.count("]") > 0:
            # found a square bracket, so, never mind
            return sents

    for sent in sents:
        if random.random() > ratio:
            continue

        text_idx = find_text_idx(sent)
        text_line = sent[text_idx]
        if text_line.count("(") == 0 and text_line.count(")") == 0:
            continue

        text_line = text_line.replace("(", "[").replace(")", "]")
        new_sent = list(sent)
        new_sent[text_idx] = text_line
        for idx, line in enumerate(new_sent):
            if line.startswith("#"):
                continue
            pieces = line.split("\t")
            if pieces[1] == '(':
                pieces[1] = '['
            elif pieces[1] == ')':
                pieces[1] = ']'
            new_sent[idx] = "\t".join(pieces)
        new_sents.append(new_sent)

    if len(new_sents) > 0:
        print("Added %d sentences with parens replaced with square brackets" % len(new_sents))

    return sents + new_sents

def forward(model: Tok2VecListener, inputs, is_train: bool):
    if is_train:
        # This might occur during training when the tok2vec layer is frozen / hasn't been updated.
        # In that case, it should be set to "annotating" so we can retrieve the embeddings from the doc.
        if model._batch_id is None:
            outputs = []
            for doc in inputs:
                if doc.tensor.size == 0:
                    raise ValueError(Errors.E203.format(name="tok2vec"))
                else:
                    outputs.append(doc.tensor)
            return outputs, _empty_backprop
        else:
            model.verify_inputs(inputs)
            return model._outputs, model._backprop
    else:
        # This is pretty grim, but it's hard to do better :(.
        # It's hard to avoid relying on the doc.tensor attribute, because the
        # pipeline components can batch the data differently during prediction.
        # That doesn't happen in update, where the nlp object works on batches
        # of data.
        # When the components batch differently, we don't receive a matching
        # prediction from the upstream, so we can't predict.
        outputs = []
        width = model.get_dim("nO")
        for doc in inputs:
            if doc.tensor.size == 0:
                # But we do need to do *something* if the tensor hasn't been set.
                # The compromise is to at least return data of the right shape,
                # so the output is valid.
                outputs.append(model.ops.alloc2f(len(doc), width))
            else:
                outputs.append(doc.tensor)
        return outputs, _empty_backprop

def format_parameters(parameters: Parameters, formatted_search_space: FormattedSearchSpace) -> FormattedParameters:
    # I don't like this function. It's better to use checkpoint for resuming.
    ret = {}
    for key, spec in formatted_search_space.items():
        if not spec.is_activated_in(ret):
            continue
        value: Any = parameters
        for name in key:
            if isinstance(name, str):
                value = value[name]
        if spec.categorical:
            if spec.type == 'randint':
                lower = min(math.ceil(float(x)) for x in spec.values)
                ret[key] = value - lower
            elif _is_nested_choices(spec.values):
                names = [nested['_name'] for nested in spec.values]
                ret[key] = names.index(value['_name'])
            else:
                ret[key] = spec.values.index(value)
        else:
            if spec.log_distributed:
                value = math.log(value)
            ret[key] = value
    return ret

def set_experts_implementation(self, experts_implementation: str | dict):
        requested_implementation = (
            experts_implementation
            if not isinstance(experts_implementation, dict)
            else experts_implementation.get("", self.config._experts_implementation)
        )

        if requested_implementation != self.config._experts_implementation:
            requested_implementation = self._check_and_adjust_experts_implementation(requested_implementation)
            # Apply the change (on the internal attr, to avoid setting it recursively)
            self.config._experts_implementation_internal = requested_implementation

        # Apply it to all submodels as well
        for submodule in self.modules():
            # We found a submodel (which is not self) with a different config (otherwise, it may be the same "actual model",
            # e.g. ForCausalLM has a Model inside, but no need to check it again)
            if (
                submodule is not self
                and isinstance(submodule, PreTrainedModel)
                and submodule.config.__class__ != self.config.__class__
            ):
                # Set the experts on the submodule
                sub_implementation = requested_implementation
                if isinstance(experts_implementation, dict):
                    for subconfig_key in self.config.sub_configs:
                        # We need to check for exact object match here, with `is`
                        if getattr(self.config, subconfig_key) is submodule.config:
                            sub_implementation = experts_implementation.get(
                                subconfig_key, submodule.config._experts_implementation
                            )
                            break
                # Check the module can use correctly, otherwise we raise an error if requested experts can't be set for submodule
                sub_implementation = submodule.get_correct_experts_implementation(sub_implementation)
                submodule.config._experts_implementation_internal = sub_implementation

def get_torch_storage_size(tensor: "torch.Tensor") -> int:
    try:
        from torch.distributed.tensor import DTensor

        if isinstance(tensor, DTensor):
            # this returns the size of the FULL tensor in bytes
            return tensor.nbytes
    except ImportError:
        pass

    try:
        # for torch 2.1 and above we can also handle tensor subclasses
        from torch.utils._python_dispatch import is_traceable_wrapper_subclass

        if is_traceable_wrapper_subclass(tensor):
            attrs, _ = tensor.__tensor_flatten__()  # type: ignore[attr-defined]
            return sum(get_torch_storage_size(getattr(tensor, attr)) for attr in attrs)
    except ImportError:
        # for torch version less than 2.1, we can fall back to original implementation
        pass

    try:
        return tensor.untyped_storage().nbytes()
    except AttributeError:
        # Fallback for torch==1.10
        try:
            return tensor.storage().size() * _get_dtype_size(tensor.dtype)
        except NotImplementedError:
            # Fallback for meta storage
            # On torch >=2.0 this is the tensor size
            return tensor.nelement() * _get_dtype_size(tensor.dtype)

def prune_intermediate_layers(node):
    if not node.get("children"):
        return
    layer_blocks = [(i, child) for i, child in enumerate(node["children"]) if is_layer_block(child)]

    if len(layer_blocks) > 2:
        to_remove = [i for i, _ in layer_blocks[1:-1]]
        node["children"] = [child for i, child in enumerate(node["children"]) if i not in to_remove]

    for child in node["children"]:
        prune_intermediate_layers(child)

def merge_class(base, other):
        try:
            other = other.rules
        except AttributeError:
            pass

        if not isinstance(other, list):
            other = [other]
        other_holidays = {holiday.name: holiday for holiday in other}

        try:
            base = base.rules
        except AttributeError:
            pass

        if not isinstance(base, list):
            base = [base]
        base_holidays = {holiday.name: holiday for holiday in base}

        other_holidays.update(base_holidays)
        return list(other_holidays.values())

def read_download_metadata(local_dir: Path, filename: str) -> LocalDownloadFileMetadata | None:
    paths = get_local_download_paths(local_dir, filename)
    with WeakFileLock(paths.lock_path):
        if paths.metadata_path.exists():
            try:
                with paths.metadata_path.open() as f:
                    commit_hash = f.readline().strip()
                    etag = f.readline().strip()
                    timestamp = float(f.readline().strip())
                    metadata = LocalDownloadFileMetadata(
                        filename=filename,
                        commit_hash=commit_hash,
                        etag=etag,
                        timestamp=timestamp,
                    )
            except Exception as e:
                # remove the metadata file if it is corrupted / not the right format
                logger.warning(
                    f"Invalid metadata file {paths.metadata_path}: {e}. Removing it from disk and continue."
                )
                try:
                    paths.metadata_path.unlink()
                except Exception as e:
                    logger.warning(f"Could not remove corrupted metadata file {paths.metadata_path}: {e}")
                return None

            try:
                # check if the file exists and hasn't been modified since the metadata was saved
                stat = paths.file_path.stat()
                if (
                    stat.st_mtime - 1 <= metadata.timestamp
                ):  # allow 1s difference as stat.st_mtime might not be precise
                    return metadata
                logger.info(f"Ignored metadata for '{filename}' (outdated). Will re-compute hash.")
            except FileNotFoundError:
                # file does not exist => metadata is outdated
                return None
    return None

def compute_module_sizes(
    model: "PreTrainedModel",
    hf_quantizer: "HfQuantizer | None" = None,
    buffers_only: bool = False,
    only_modules: bool = True,
) -> tuple[dict[str, int], dict[str, int]]:
    all_module_sizes = defaultdict(int)
    leaves_module_sizes = defaultdict(int)

    if buffers_only:
        iterator = model.named_buffers()
    else:
        # We need parameters + buffers here, as state_dict does not count non-persistent buffers which are taking space
        def all_tensors():
            yield from model.named_parameters()
            yield from model.named_buffers()

        iterator = all_tensors()

    tied_keys = getattr(model, "all_tied_weights_keys", {}).keys()
    for name, param in iterator:
        # Do not count tied keys (the model is usually not tied yet here, so they will appear in the iterator)
        # If the model is already tied, then they simply do not appear in the iterator anyway (remove_duplicates=True by default)
        if name in tied_keys:
            continue
        if hf_quantizer is not None:
            dtype_size = hf_quantizer.param_element_size(model, name, param)
        else:
            dtype_size = param.element_size()
        size = param.numel() * dtype_size
        name_parts = name.split(".")
        for idx in range(len(name_parts)):
            all_module_sizes[".".join(name_parts[:idx])] += size
        if "." in name:
            leaves_module_sizes[name.rsplit(".", 1)[0]] += size
        # If we want to also have the full leaves in `all_module_sizes`
        if not only_modules:
            all_module_sizes[name] += size

    return all_module_sizes, leaves_module_sizes

def handle_multiple_handoffs(
        self, boss_response_str: dict, task: str
    ) -> dict:

        # Validate that the selected agents exist
        for handoff in boss_response_str["handoffs"]:
            if handoff["agent_name"] not in self.agents:
                raise ValueError(
                    f"Boss selected unknown agent: {handoff.agent_name}"
                )

        # Get the selected agents and their tasks
        selected_agents = []
        final_tasks = []
        skipped_agents = []

        for handoff in boss_response_str["handoffs"]:
            agent = self.agents[handoff["agent_name"]]
            final_task = handoff["task"] or task

            # Skip execution if task is null/None and skip_null_tasks is True
            if self.skip_null_tasks and (
                final_task is None or final_task == ""
            ):
                if self.print_on:
                    logger.info(
                        f"Skipping execution for agent {agent.agent_name} - task is null/None"
                    )
                skipped_agents.append(agent.agent_name)
                continue

            selected_agents.append(agent)
            final_tasks.append(final_task)

        # Execute agents only if there are valid tasks
        if selected_agents:
            # Use the agents' run method directly
            agent_responses = [
                agent.run(final_task)
                for agent, final_task in zip(
                    selected_agents, final_tasks
                )
            ]

            self.conversation.add(
                role=selected_agents[0].agent_name,
                content=agent_responses[0],
            )

def count_used_parameters_in_backward(parameters: Sequence[torch.nn.Parameter]) -> int:
    assert check_internal_apis_for_count_used_parameters(), (
        "count_used_parameters_in_backward requires internal PyTorch APIs that are not available "
        "in this PyTorch build.")

    from torch.autograd.graph import _get_grad_fn_or_grad_acc
    if torch._C._current_graph_task_id() == -1:
        raise RuntimeError("count_used_parameters_in_backward must be called during backward execution")

    seen_nodes = set()
    for param in parameters:
        if not isinstance(param, torch.Tensor) or not param.requires_grad:
            continue

        # Backward hooks run with grad mode disabled, but PyTorch <=2.4's
        # _get_grad_fn_or_grad_acc() requires grad mode for leaf params.
        with torch.enable_grad():
            grad_fn = _get_grad_fn_or_grad_acc(param)
        if grad_fn is None:
            continue

        if grad_fn in seen_nodes:
            continue

        seen_nodes.add(grad_fn)

    if not seen_nodes:
        return 0

    participating = sum(map(torch._C._will_engine_execute_node, seen_nodes))
    return int(participating)

def cohens_kappa(
        self, scores: Union[List[float], List[List]], threshold=0.5
    ) -> float:
        if isinstance(scores[0], List):
            scores = [score for score, _ in scores]

        if len(self.true_labels) != len(scores):
            raise ValueError(
                "The length of true_labels and scores must be the same."
            )
        #  convert to categorical if necessary
        if any(isinstance(score, float) for score in scores):
            # threshold at 0.5 for binary classification
            scores = [1 if score >= threshold else 0 for score in scores]

        if any(isinstance(label, float) for label in self.true_labels):
            self.true_labels = [
                1 if label >= threshold else 0 for label in self.true_labels
            ]

        kappa = cohen_kappa_score(self.true_labels, scores)
        return kappa

def list_archive(archive_path, archive_type: ArchiveType | None = None) -> list[str]:
    if archive_type is None:
        archive_type = infer_archive_type(archive_path)
    if archive_type == ArchiveType.UNKNOWN:
        logger.error(
            f"Could not infer type of archive {archive_path}.  May be an unsupported archive type."
            "Specify archive_type in the dataset config if this file has an unknown file extension."
        )
        return []
    if archive_type == ArchiveType.ZIP:
        with ZipFile(archive_path) as zfile:
            return zfile.namelist()
    elif archive_type == ArchiveType.GZIP:
        return [".".join(archive_path.split(".")[:-1])]  # Path minus the .gz extension
    elif archive_type in {ArchiveType.TAR, ArchiveType.TAR_ZIP, ArchiveType.TAR_BZ2, ArchiveType.TAR_GZ}:
        with tarfile.open(archive_path) as tar_file:
            return tar_file.getnames()
    else:
        logger.error(f"Unsupported archive: {archive_path}")
    return []

async def acall(self, docs: List[str], truncate: bool = True) -> List[List[float]]:
        if self._async_client is None:
            raise ValueError("OpenAI async client is not initialized.")
        embeds = None

        if truncate:
            # check if any document exceeds token limit and truncate if so
            docs = [self._truncate(doc) for doc in docs]

        # Exponential backoff
        for j in range(self.max_retries + 1):
            try:
                embeds = await self._async_client.embeddings.create(
                    input=docs,
                    model=self.name,
                    dimensions=self.dimensions,  # type: ignore[arg-type]  # NotGiven vs Omit - ignore type errors between openai SDK <2.0.0 and >=2.0.0
                )
                if embeds.data:
                    break
            except OpenAIError as e:
                logger.error("Exception occurred", exc_info=True)
                if self.max_retries != 0 and j < self.max_retries:
                    await asleep(2**j)
                    logger.warning(
                        f"Retrying in {2**j} seconds due to OpenAIError: {e}"
                    )
                else:
                    raise

            except Exception as e:
                logger.error(f"OpenAI API call failed. Error: {e}")
                raise ValueError(f"OpenAI API call failed. Error: {e}") from e

        if (
            not embeds
            or not isinstance(embeds, CreateEmbeddingResponse)
            or not embeds.data
        ):
            logger.info(f"Returned embeddings: {embeds}")
            raise ValueError("No embeddings returned.")

        embeddings = [embeds_obj.embedding for embeds_obj in embeds.data]
        return embeddings

def include_object(
    object: sqlalchemy.schema.SchemaItem,
    name: str,
    type_: str,
    reflected: bool,
    compare_to: Optional[sqlalchemy.schema.SchemaItem],
) -> bool:

    # because of the dynamic inheritance pattern used by the Prefect database,
    # it is difficult to get alembic to resolve references to indexes on inherited models
    #
    # to keep autogenerated migration code clean, we ignore the following indexes:
    # * functional indexes (ending in 'desc', 'asc'), if an index with the same name already exists
    # * trigram indexes that already exist
    # * case_insensitive indexes that already exist
    # * indexes that don't yet exist but have .ddl_if(dialect=...) metadata that doesn't match
    #   the current dialect.
    if type_ == "index":
        if not reflected:
            if name.endswith(("asc", "desc")):
                return compare_to is None or object.name != compare_to.name
            if (ddl_if := object._ddl_if) is not None and ddl_if.dialect is not None:
                desired: set[str] = (
                    {ddl_if.dialect}
                    if isinstance(ddl_if.dialect, str)
                    else set(ddl_if.dialect)
                )
                return dialect.name in desired

        else:  # reflected
            if name.startswith("gin") or name.endswith("case_insensitive"):
                return False

    # SQLite doesn't have an enum type, so reflection always comes back with
    # a VARCHAR column, which doesn't match. Skip columns where the type
    # doesn't match
    if (
        dialect.name == "sqlite"
        and type_ == "column"
        and object.type.__visit_name__ == "enum"
        and compare_to is not None
    ):
        return compare_to.type.__visit_name__ == "enum"

    return True

def get_content(
        self, name: str, content_type: ContentType, timeout: Optional[float] = None
    ) -> Optional[bytes]:
        # Wait for at least the blob to be formed
        _ = self.blob_with_timeout(timeout=timeout)
        if content_type == ContentType.USER_CONTENT:
            for path, arcname in self.user_tuples():
                if name == arcname:
                    return open(path, "rb").read()
            return None
        elif content_type in (
            ContentType.CODE_CONTENT,
            ContentType.MODULE_CONTENT,
            ContentType.OTHER_CONTENT,
        ):
            mangled_name = self._mfcontent.get_archive_filename(name, content_type)
            for path_or_bytes, arcname in self._mfcontent.contents(content_type):
                if mangled_name == arcname:
                    if isinstance(path_or_bytes, bytes):
                        # In case this is generated content like an INFO file
                        return path_or_bytes
                    # Otherwise, it is a file path
                    return open(path_or_bytes, "rb").read()
            return None
        raise ValueError(f"Unknown content type: {content_type}")

def max_pool(
    inputs,
    pool_size,
    strides=None,
    padding="valid",
    data_format=None,
):
    inputs = convert_to_tensor(inputs)
    num_spatial_dims = inputs.ndim - 2
    pool_size = standardize_tuple(pool_size, num_spatial_dims, "pool_size")
    if strides is None:
        strides = pool_size
    else:
        strides = standardize_tuple(strides, num_spatial_dims, "strides")

    data_format = backend.standardize_data_format(data_format)
    if data_format == "channels_last":
        inputs = _transpose_spatial_inputs(inputs)

    if padding == "same":
        # Torch does not natively support `"same"` padding, we need to manually
        # apply the right amount of padding to `inputs`.
        inputs, padding = _apply_same_padding(
            inputs, pool_size, strides, data_format, "pooling"
        )
    else:
        padding = 0

    device = get_device()
    # Torch max pooling ops do not support symbolic tensors.
    # Create a real tensor to execute the ops.
    if device == "meta":
        inputs = torch.empty(
            size=inputs.shape, dtype=inputs.dtype, device="cpu"
        )

    if num_spatial_dims == 1:
        outputs = tnn.max_pool1d(
            inputs, kernel_size=pool_size, stride=strides, padding=padding
        )
    elif num_spatial_dims == 2:
        outputs = tnn.max_pool2d(
            inputs, kernel_size=pool_size, stride=strides, padding=padding
        )
    elif num_spatial_dims == 3:
        outputs = tnn.max_pool3d(
            inputs, kernel_size=pool_size, stride=strides, padding=padding
        )
    else:
        raise ValueError(
            "Inputs to pooling op must have ndim=3, 4 or 5, "
            "corresponding to 1D, 2D and 3D inputs. "
            f"Received input shape: {inputs.shape}."
        )

    outputs = outputs.to(device)
    if data_format == "channels_last":
        outputs = _transpose_spatial_outputs(outputs)
    return outputs

def convert_step_to_command(
    step: dict[str, Any], key: str, quiet: bool = False
) -> list[str]:
    step_keys = list(step.keys())

    if len(step_keys) != 1:
        raise ValueError("Expected exactly one function in step")

    function_fqn = step_keys[0]
    function_args = step[function_fqn]
    requires: list[str] | str = function_args.get("requires", [])
    launcher = function_args.get("launcher")

    if isinstance(requires, str):
        requires = [requires]

    if launcher is not None:
        command = validate_bundle_step_launcher(launcher)
        if requires:
            raise ValueError(
                "Bundle step launcher cannot be combined with step requirements"
            )
    else:
        command = ["uv", "run"]

        if quiet:
            command.append("--quiet")

        # Add the `--with` argument to handle dependencies for running the step
        if requires:
            command.extend(["--with", ",".join(requires)])

        # Add the `--python` argument to handle the Python version for running the step
        python_version = sys.version_info
        command.extend(["--python", f"{python_version.major}.{python_version.minor}"])

    # Add the `-m` argument to defined the function to run
    command.extend(["-m", function_fqn])

    # Add any arguments with values defined in the step
    for arg_name, arg_value in function_args.items():
        if arg_name in {"launcher", "requires"}:
            continue

        command.extend([f"--{slugify(arg_name)}", arg_value])

    # Add the `--key` argument to specify the remote file name
    command.extend(["--key", key])

    return command

def post_init(self):
        if not isinstance(self.load_in_4bit, bool):
            raise TypeError("load_in_4bit must be a boolean")

        if not isinstance(self.load_in_8bit, bool):
