                if isinstance(experiments_dict[key]['endTime'], int) else experiments_dict[key]['endTime'])
    print(EXPERIMENT_INFORMATION_FORMAT % experiment_information)
    return experiment_id_list

def update(self, metric_value, epoch=None):
        if _is_real_number(epoch):
            if _is_real_number(self.last_epoch):
                diff_epoch = epoch - self.last_epoch
            else:
                diff_epoch = 1
            self.last_epoch = epoch
        else:
            diff_epoch = 1
        if not _is_real_number(metric_value):
            return
        if self.metric_fn is not None:
            metric_value = self.metric_fn(metric_value)

        if metric_value > self.max_value:
            self._should_stop = True
            self._message = 'EarlyStop given {} vs. max {}'.format(metric_value, self.max_value)
        else:
            if metric_value - self.min_delta > self.best:
                self.best = metric_value
                self.wait = 0
            else:
                self.wait += diff_epoch
                if self.wait >= self.patience:
                    self._should_stop = True
                    self._message = 'EarlyStop after {} epochs: no better than {}'.format(self.patience, self.best)

def transform(self, func, idx=None, tmin=None, tmax=None, copy=False):
        # min and max data indices to include
        times = 1000.0 * self.times
        t_idx = np.where(_time_mask(times, tmin, tmax, sfreq=self.sfreq))[0]
        if tmin is None:
            tmin_idx = None
        else:
            tmin_idx = t_idx[0]

        if tmax is None:
            tmax_idx = None
        else:
            # +1, because upper boundary needs to include the last sample
            tmax_idx = t_idx[-1] + 1

        data_t = self.transform_data(
            func, idx=idx, tmin_idx=tmin_idx, tmax_idx=tmax_idx
        )

        # account for change in n_vertices
        if idx is not None:
            idx_lh = idx[idx < len(self.lh_vertno)]
            idx_rh = idx[idx >= len(self.lh_vertno)] - len(self.lh_vertno)
            verts_lh = self.lh_vertno[idx_lh]
            verts_rh = self.rh_vertno[idx_rh]
        else:
            verts_lh = self.lh_vertno
            verts_rh = self.rh_vertno
        verts = [verts_lh, verts_rh]

        tmin_idx = 0 if tmin_idx is None else tmin_idx
        tmin = self.times[tmin_idx]

        if data_t.ndim > 2:
            # return list of stcs if transformed data has dimensionality > 2
            if copy:
                stcs = [
                    SourceEstimate(
                        data_t[:, :, a], verts, tmin, self.tstep, self.subject
                    )
                    for a in range(data_t.shape[-1])
                ]
            else:
                raise ValueError(
                    "copy must be True if transformed data has more than 2 dimensions"
                )
        else:
            # return new or overwritten stc
            stcs = self if not copy else self.copy()
            stcs.vertices = verts
            stcs.data = data_t
            stcs.tmin = tmin

        return stcs

def is_node_supported(
        self, submodules: typing.Mapping[str, torch.nn.Module], node: fx.Node
    ) -> bool:
        if is_submodule_node(node):
            return True
        input_nodes = (
            input_node
            for input_node in node.all_input_nodes
            if input_node.op != "get_attr"
        )
        # check if any input node has an unsupported rank
        for input_node in input_nodes:
            input_node_shape = get_first_fake_tensor(input_node).shape
            if len(input_node_shape) > self.max_rank:
                self.reporter.report_reject(
                    node,
                    f"{node.name} has input_node {input_node.name} with shape {input_node_shape}, "
                    f"rank {len(input_node_shape)} which is unsupported. "
                    f"Max supported rank is {self.max_rank}.",
                )
                return False

        meta_val = node.meta["val"]
        if isinstance(
            meta_val, (Sequence, torch.fx.immutable_collections.immutable_list)
        ):
            for val in meta_val:
                if isinstance(val, FakeTensor):
                    if len(val.shape) > self.max_rank:
                        self.reporter.report_reject(
                            node,
                            f"{node.name} has a shape {val.shape}, rank {len(val.shape)} which is unsupported."
                            f"Max supported rank is {self.max_rank}.",
                        )
                        return False
        elif isinstance(meta_val, FakeTensor):
            if len(meta_val.shape) > self.max_rank:
                self.reporter.report_reject(
                    node,
                    f"{node.name} has shape {meta_val.shape}, rank={len(meta_val.shape)} which is unsupported."
                    f"Max supported rank is {self.max_rank}.",
                )
                return False
        return True

def url_relative_to_base(base: URL, other: URL) -> URL:
    # Verify the URLs have the same scheme and host
    if base.scheme.lower() != other.scheme.lower():
        raise ValueError(
            f'URLs have different schemes: "{base.scheme}" and "{other.scheme}"'
        )

    base_host = None if base.host is None else base.host.lower()
    other_host = None if other.host is None else other.host.lower()

    if base_host != other_host:
        raise ValueError(
            f'URLs have different hosts: "{base.host}" and "{other.host}"'
        )

    # Get the path segments of the URLs
    base_parts = base.parts
    other_parts = other.parts

    # Strip empty segments
    if base_parts and base_parts[-1] == "":
        base_parts = base_parts[:-1]

    if other_parts and other_parts[-1] == "":
        other_parts = other_parts[:-1]

    # See if the base is a parent of the other URL
    for base_part, other_part in zip(base_parts, other_parts):
        if base_part != other_part:
            # Log a warning if the only difference is casing
            if base_part.lower() == other_part.lower():
                message = f"`{base}` is not considered a base URL of `{other}`, because the URL paths are cased differently. This is considered a different, as by the URL specification. If you were trying to navigate to your own site and it didn't pick this up check your spelling."
                raise ValueError(message)

            raise ValueError(
                f"`{base}` is not a base URL of `{other}`. The paths differ at `{base_part}` and `{other_part}`"
            )

    # Remove the common parts from the URL
    other_parts = other_parts[len(base_parts) :]
    return URL.build(
        path="/".join(other_parts),
        query=other.query,
        fragment=other.fragment,
    )

def read_xml_file(input_filename):
    with open(input_filename, encoding="utf-8") as fin:
        dataset = ET.parse(fin)
    dataset = dataset.getroot()
    corpus = dataset.find("{http://nlx.di.fc.ul.pt}corpus")
    if not corpus:
        raise ValueError("Unexpected dataset structure : no 'corpus'")
    trees = []
    for sentence in corpus:
        if sentence.tag != "{http://nlx.di.fc.ul.pt}sentence":
            raise ValueError("Unexpected sentence tag: {}".format(sentence.tag))
        id_node = None
        raw_node = None
        tree_nodde = None
        for node in sentence:
            if node.tag == '{http://nlx.di.fc.ul.pt}id':
                id_node = node
            elif node.tag == '{http://nlx.di.fc.ul.pt}raw':
                raw_node = node
            elif node.tag == '{http://nlx.di.fc.ul.pt}tree':
                tree_node = node
            else:
                raise ValueError("Unexpected tag in sentence {}: {}".format(sentence, node.tag))
        if id_node is None or raw_node is None or tree_node is None:
            raise ValueError("Missing node in sentence {}".format(sentence))
        tree_id = "".join(id_node.itertext())
        tree_text = "".join(tree_node.itertext())
        trees.append((tree_id, tree_text))
    return trees

def make_weak_ref(x):
    def convert_to_torch_tensor(tensor: Union[_WeakRefTensor, torch.Tensor]) -> torch.Tensor:
        """
        This function is to convert the `_WeakRefTensor` to torch.Tensor.
        """
        if isinstance(tensor, torch.Tensor):
            return tensor

        old_ptr = tensor.data_ptr()
        new_tensor = torch.as_tensor(tensor).view(tensor.dtype)
        new_ptr = new_tensor.data_ptr()
        if old_ptr != new_ptr:
            raise RuntimeError("Data pointer mismatch after converting to torch.Tensor")
        return new_tensor

    if isinstance(x, torch.Tensor):
        return (
            convert_to_torch_tensor(_WeakRefTensor(x.data_ptr(), x.dtype, x.shape))
            if x.is_cuda
            else x
        )
    if isinstance(x, tuple):
        return tuple(make_weak_ref(i) for i in x)
    if isinstance(x, list):
        return [make_weak_ref(i) for i in x]
    if isinstance(x, dict):
        return {k: make_weak_ref(v) for k, v in x.items()}
    if isinstance(x, (int, float, bool)):
        return x
    if x is None:
        return None
    raise TypeError(
        f"Invalid type {type(x).__name__} to make weak ref. "
        "Valid types are: torch.Tensor, tuple, list, dict, int, float, bool, and None."
    )

def findBracketBackward(self, block, column, bracket):
        if bracket in ('(', ')'):
            opening = '('
            closing = ')'
        elif bracket in ('[', ']'):
            opening = '['
            closing = ']'
        elif bracket in ('{', '}'):
            opening = '{'
            closing = '}'
        else:
            raise AssertionError('Invalid bracket "%s"' % bracket)

        depth = 1
        for foundBlock, foundColumn, char in self.iterateCharsBackwardFrom(block, column):
            if not self._qpart.isComment(foundBlock.blockNumber(), foundColumn):
                if char == opening:
                    depth = depth - 1
                elif char == closing:
                    depth = depth + 1

                if depth == 0:
                    return foundBlock, foundColumn
        raise ValueError('Not found')

def FDR(p_values: Iterable, dependent=False, m=None, ordered=False) -> Iterable:
    if p_values is None or len(p_values) == 0 or \
            (m is not None and m <= 0):
        return None

    is_list = isinstance(p_values, list)
    p_values = np.array(p_values)
    if m is None:
        m = len(p_values)
    if not ordered:
        ordered = (np.diff(p_values) >= 0).all()
        if not ordered:
            indices = np.argsort(p_values)
            p_values = p_values[indices]

    if dependent:  # correct q for dependent tests
        m *= sum(1 / np.arange(1, m + 1))

    fdrs = (p_values * m / np.arange(1, len(p_values) + 1))[::-1]
    fdrs = np.array(np.minimum.accumulate(fdrs)[::-1])
    if not ordered:
        fdrs[indices] = fdrs.copy()
    return fdrs if not is_list else list(fdrs)

def build_vocab(self, relations, update=False):
        old_index_to_key_len = len(self.kv.index_to_key)

        logger.info("loading relations from train data..")
        for relation in relations:
            if len(relation) != 2:
                raise ValueError('Relation pair "%s" should have exactly two items' % repr(relation))
            for item in relation:
                if item in self.kv.key_to_index:
                    self.kv.set_vecattr(item, 'count', self.kv.get_vecattr(item, 'count') + 1)
                else:
                    self.kv.key_to_index[item] = len(self.kv.index_to_key)
                    self.kv.index_to_key.append(item)
                    self.kv.set_vecattr(item, 'count', 1)

            node_1, node_2 = relation
            node_1_index, node_2_index = self.kv.key_to_index[node_1], self.kv.key_to_index[node_2]
            self.node_relations[node_1_index].add(node_2_index)
            relation = (node_1_index, node_2_index)
            self.all_relations.append(relation)
        logger.info("loaded %d relations from train data, %d nodes", len(self.all_relations), len(self.kv))
        self.indices_set = set(range(len(self.kv.index_to_key)))  # Set of all node indices
        self.indices_array = np.fromiter(range(len(self.kv.index_to_key)), dtype=int)  # Numpy array of all node indices
        self._init_node_probabilities()

        if not update:
            self._init_embeddings()
        else:
            self._update_embeddings(old_index_to_key_len)

def get_closest_index(in_x, rounding_method, boxes, use_int_div=False):
    if use_int_div:
        closest_x_index = in_x.astype("int32")
        return closest_x_index

    if rounding_method == "round" or boxes is not None:
        closest_x_index = te.round(in_x).astype("int32")
    elif rounding_method == "round_prefer_floor":
        closest_x_index = te.ceil(in_x - 0.5).astype("int32")
    elif rounding_method == "round_prefer_ceil":
        closest_x_index = te.floor(in_x + 0.5).astype("int32")
    elif rounding_method == "floor":
        # Add epsilon to floor to prevent gpu rounding errors.
        epsilon = 1e-5
        closest_x_index = te.floor(in_x + epsilon).astype("int32")
    elif rounding_method == "ceil":
        # Subract epsilon from ceil to prevent gpu rounding errors.
        epsilon = 1e-5
        closest_x_index = te.ceil(in_x - epsilon).astype("int32")
    else:
        raise ValueError(f"Unknown rounding method: {rounding_method}")
    return closest_x_index

def set_data(self, data):
        def _check_and_set_data(data):
            self.clear_messages()
            if data and data.is_sparse():
                self.Warning.sparse_not_supported()
                return False
            if data:
                if not data.domain.attributes:
                    self.Warning.no_input_variables()
                    data = None
                elif len(data.domain.attributes) > 2:
                    self.Information.use_first_two()
            self.input_data = data
            self.btResetToInput.setDisabled(data is None)
            return bool(data)

        if not _check_and_set_data(data):
            return

        X = np.array([scale(vals) for vals in data.X[:, :2].T]).T
        try:
            y = next(cls for cls in data.domain.class_vars if cls.is_discrete)
        except StopIteration:
            if data.domain.class_vars:
                self.Warning.continuous_target()
            self.input_classes = ["C1"]
            self.input_colors = None
            y = np.zeros(len(data))
        else:
            self.input_classes = y.values
            self.input_colors = y.palette

            y = data[:, y].Y

        self.input_has_attr2 = len(data.domain.attributes) >= 2
        if not self.input_has_attr2:
            self.input_data = np.column_stack((X, np.zeros(len(data)), y))
        else:
            self.input_data = np.column_stack((X, y))
        self.reset_to_input()
        self.commit.now()

def format_metrics(metrics, task, err_msg):
    result = {}
    sources = ['both', 'search', 'zhidao']
    if err_msg is not None:
        return {'errorMsg': str(err_msg), 'errorCode': 1, 'data': []}
    data = []
    if task != 'all' and task != 'main':
        sources = ['both']

    if task == 'entity':
        metric_names = ['Bleu-4', 'Rouge-L']
        metric_names_prf = ['F1', 'Precision', 'Recall']
        for name in metric_names + metric_names_prf:
            for src in sources:
                obj = {
                    'name': name,
                    'value': round(metrics[src].get(name, 0) * 100, 2),
                    'type': src,
                }
                data.append(obj)
    elif task == 'yesno':
        metric_names = ['Bleu-4', 'Rouge-L']
        details = ['Yes', 'No', 'Depends']
        src = sources[0]
        for name in metric_names:
            obj = {
                'name': name,
                'value': round(metrics[src].get(name, 0) * 100, 2),
                'type': 'All',
            }
            data.append(obj)
            for d in details:
                obj = {
                    'name': name,
                    'value': round(metrics[src].get(d + '|' + name, 0) * 100,
                                   2),
                    'type': d
                }
                data.append(obj)
    else:
        metric_names = ['Bleu-4', 'Rouge-L']
        for name in metric_names:
            for src in sources:
                obj = {
                    'name': name,
                    'value': round(metrics[src].get(name, 0) * 100, 2),
                    'type': src
                }
                data.append(obj)

    result['data'] = data
    result['errorCode'] = 0
    result['errorMsg'] = 'success'

    return result

def analyze_results(import_dict_objects: dict[str, list[str]], type_hint_objects: dict[str, list[str]]) -> list[str]:
    def find_duplicates(seq):
        return [k for k, v in collections.Counter(seq).items() if v > 1]

    # If one backend is missing from the other part of the init, error early.
    if list(import_dict_objects.keys()) != list(type_hint_objects.keys()):
        return ["Both sides of the init do not have the same backends!"]

    errors = []
    # Find all errors.
    for key in import_dict_objects:
        # Duplicate imports in any half.
        duplicate_imports = find_duplicates(import_dict_objects[key])
        if duplicate_imports:
            errors.append(f"Duplicate _import_structure definitions for: {duplicate_imports}")
        duplicate_type_hints = find_duplicates(type_hint_objects[key])
        if duplicate_type_hints:
            errors.append(f"Duplicate TYPE_CHECKING objects for: {duplicate_type_hints}")

        # Missing imports in either part of the init.
        if sorted(set(import_dict_objects[key])) != sorted(set(type_hint_objects[key])):
            name = "base imports" if key == "none" else f"{key} backend"
            errors.append(f"Differences for {name}:")
            for a in type_hint_objects[key]:
                if a not in import_dict_objects[key]:
                    errors.append(f"  {a} in TYPE_HINT but not in _import_structure.")
            for a in import_dict_objects[key]:
                if a not in type_hint_objects[key]:
                    errors.append(f"  {a} in _import_structure but not in TYPE_HINT.")
    return errors

def combine_event_ids(epochs, old_event_ids, new_event_id, copy=True):
    epochs = epochs.copy() if copy else epochs
    old_event_ids = np.asanyarray(old_event_ids)
    if isinstance(new_event_id, int):
        new_event_id = {str(new_event_id): new_event_id}
    else:
        if not isinstance(new_event_id, dict):
            raise ValueError("new_event_id must be a dict or int")
        if not len(list(new_event_id.keys())) == 1:
            raise ValueError("new_event_id dict must have one entry")
    new_event_num = list(new_event_id.values())[0]
    new_event_num = operator.index(new_event_num)
    if new_event_num in epochs.event_id.values():
        raise ValueError("new_event_id value must not already exist")
    # could use .pop() here, but if a latter one doesn't exist, we're
    # in trouble, so run them all here and pop() later
    old_event_nums = np.array([epochs.event_id[key] for key in old_event_ids])
    # find the ones to replace
    inds = np.any(
        epochs.events[:, 2][:, np.newaxis] == old_event_nums[np.newaxis, :], axis=1
    )
    # replace the event numbers in the events list
    epochs.events[inds, 2] = new_event_num
    # delete old entries
    for key in old_event_ids:
        epochs.event_id.pop(key)
    # add the new entry
    epochs.event_id.update(new_event_id)
    return epochs

def extract(infile, outfile):
    lines = infile.readlines()
    sentences = []
    cur_sentence = []
    for idx, line in enumerate(lines):
        line = line.strip()
        if not line:
            # if we're currently reading a sentence, append it to the list
            if cur_sentence:
                sentences.append(cur_sentence)
                cur_sentence = []
            continue

        pieces = line.split("\t")
        if len(pieces) < 12:
            raise ValueError("Unexpected line length in the SUC3 dataset at %d" % idx)
        if pieces[10] == 'O':
            cur_sentence.append((pieces[1], "O"))
        else:
            cur_sentence.append((pieces[1], "%s-%s" % (pieces[10], pieces[11])))
    if cur_sentence:
        sentences.append(cur_sentence)

    for sentence in sentences:
        for word in sentence:
            outfile.write("%s\t%s\n" % word)
        outfile.write("\n")

    return len(sentences)

def get_tools_for_multiple_mcp_servers(
    urls: List[str],
    connections: List[MCPConnection] = None,
    format: str = "openai",
    output_type: Literal["json", "dict", "str"] = "str",
    max_workers: Optional[int] = None,
    transport: Optional[str] = None,
    verbose: bool = True,
) -> List[Dict[str, Any]]:
    if verbose:
        logger.info(
            f"get_tools_for_multiple_mcp_servers called for {len(urls)} urls."
        )

    tools = []

    (
        min(32, os.cpu_count() + 4)
        if max_workers is None
        else max_workers
    )

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        if exists(connections):
            future_to_url = {
                executor.submit(
                    _fetch_tools_for_server,
                    url,
                    connection,
                    format,
                    transport,
                    verbose,
                ): url
                for url, connection in zip(urls, connections)
            }
        else:
            future_to_url = {
                executor.submit(
                    _fetch_tools_for_server,
                    url,
                    None,
                    format,
                    transport,
                    verbose,
                ): url
                for url in urls
            }
        for future in as_completed(future_to_url):
            url = future_to_url[future]
            try:
                server_tools = future.result()
                tools.extend(server_tools)
            except Exception as e:
                logger.error(
                    f"Error fetching tools from {url}: {str(e)}\n{traceback.format_exc()}"
                )
                raise MCPExecutionError(
                    f"Failed to fetch tools from {url}: {str(e)}"
                )
    return tools

def soft_sort(
    elements: list[T],
    key: t.Callable[[T], int | None],
) -> None:

    # To ensure we can keep the original order, add the current index to all
    # items.
    keyed_elements = [
        (element, index, key(element)) for index, element in enumerate(elements)
    ]

    # Assign positions to all elements with a provided key. This maps the
    # original index to the assigned position.
    assigned_positions: dict[int, int] = {}

    for _, original_index, key_value in keyed_elements:
        if key_value is None:
            continue

        assigned_positions[original_index] = key_value

    # Assign positions to all other elements
    ii = 0

    for _, original_index, key_value in keyed_elements:
        if key_value is not None:
            continue

        while ii in assigned_positions.values():
            ii += 1

        assigned_positions[original_index] = ii
        ii += 1

    # Sort the elements, taking care to preserve the original order between
    # items with the same key.
    def regular_sort_key(item: tuple[T, int, int | None]) -> tuple[int, int]:
        _, original_index, _ = item
        return assigned_positions[original_index], original_index

    keyed_elements.sort(key=regular_sort_key)

    # Reassign the elements to the original list
    elements.clear()

    for element, _, _ in keyed_elements:
        elements.append(element)

def dispatch_fill_zeros(op, left, right, result):
    if op is divmod:
        result = (
            mask_zero_div_zero(left, right, result[0]),
            _fill_zeros(result[1], left, right),
        )
    elif op is roperator.rdivmod:
        result = (
            mask_zero_div_zero(right, left, result[0]),
            _fill_zeros(result[1], right, left),
        )
    elif op is operator.floordiv:
        # Note: no need to do this for truediv; numpy behaves the way
        #  we want.
        result = mask_zero_div_zero(left, right, result)
    elif op is roperator.rfloordiv:
        # Note: no need to do this for rtruediv; numpy behaves the wayS
        #  we want.
        result = mask_zero_div_zero(right, left, result)
    elif op is operator.mod:
        result = _fill_zeros(result, left, right)
    elif op is roperator.rmod:
        result = _fill_zeros(result, right, left)
    return result

def process_time_series(self, x) -> Tuple[np.ndarray, np.ndarray]:
        if x is None:
            return None, None

        # Initialize t0 if needed
        if self.t0 is None:
            if isinstance(x, TimeSeries):
                t0, tf = x.t0, x.tf
                self.t0 = t0
                self.dt = tf - t0 if tf != t0 else None
            elif isinstance(x, tuple) and len(x) == 2:
                self.t0 = x[0]
                self.dt = None
            else:
                x = np.asarray(x)
                self.t0 = 0
                self.dt = 1 if x.ndim < 1 else max(1, len(x) - 1)

        # Initialize dt if needed; this only happens for cases 1 and 2 above
        if self.dt is None:
            if isinstance(x, TimeSeries):
                tf = x.tf
            else:
                tf = x[0]
            if tf != self.t0:
                self.dt = tf - self.t0

        # Convert time series to numpy, or convert numpy array to pseudo time series
        if isinstance(x, TimeSeries):
            self.names = x.names
            t = x.np_time_stamps
            x = x.align().to_pd().values
        elif isinstance(x, tuple) and len(x) == 2:
            t, x = x
            t = np.asarray(t).reshape(1)
            x = np.asarray(x).reshape(1, -1)
            self.names = [0]
        else:
            x = np.asarray(x)
            x = x.reshape((1, 1) if x.ndim < 1 else (len(x), -1))
            t = np.arange(self.n, self.n + len(x))
            self.names = list(range(x.shape[-1]))
        t = (t - self.t0) / (self.dt or 1)

        if self.dim is None:
            self.dim = x.shape[-1]
        else:
            assert x.shape[-1] == self.dim, f"Expected input with dimension {self.dim} but got {x.shape[-1]}"

        return t, x

def check(self, include_self: bool = False, parents: bool = True):
        if include_self:
            # Some mlflow backend will not list the directly recursively.
            # So we force to the directly
            artifacts = {}

            def _get_arts(dirn):
                if dirn not in artifacts:
                    artifacts[dirn] = self.recorder.list_artifacts(dirn)
                return artifacts[dirn]

            for item in self.list():
                ps = self.get_path(item).split("/")
                dirn = "/".join(ps[:-1])
                if self.get_path(item) not in _get_arts(dirn):
                    raise FileNotFoundError
        if parents:
            if self.depend_cls is not None:
                with class_casting(self, self.depend_cls):
                    self.check(include_self=True)

def object_hash(x, h=None):
    if h is None:
        h = _empty_hash()
    if hasattr(x, "keys"):
        # dict-like types
        keys = _sort_keys(x)
        for key in keys:
            object_hash(key, h)
            object_hash(x[key], h)
    elif isinstance(x, bytes):
        # must come before "str" below
        h.update(x)
    elif isinstance(x, str | float | int | type(None)):
        h.update(str(type(x)).encode("utf-8"))
        h.update(str(x).encode("utf-8"))
    elif isinstance(x, np.ndarray | np.number | np.bool_):
        x = np.asarray(x)
        h.update(str(x.shape).encode("utf-8"))
        h.update(str(x.dtype).encode("utf-8"))
        h.update(x.tobytes())
    elif isinstance(x, datetime):
        object_hash(_dt_to_stamp(x))
    elif sparse.issparse(x):
        h.update(str(type(x)).encode("utf-8"))
        if not isinstance(x, sparse.csr_array | sparse.csc_array):
            raise RuntimeError(f"Unsupported sparse type {type(x)}")
        h.update(x.data.tobytes())
        h.update(x.indices.tobytes())
        h.update(x.indptr.tobytes())
    elif hasattr(x, "__len__"):
        # all other list-like types
        h.update(str(type(x)).encode("utf-8"))
        for xx in x:
            object_hash(xx, h)
    else:
        raise RuntimeError(f"unsupported type: {type(x)} ({x})")
    return int(h.hexdigest(), 16)

def prepare_te_modules_for_fsdp(fsdp_root: torch.nn.Module) -> None:
    if not isinstance(fsdp_root, FSDP):
        raise TypeError(f"Root module must be FSDP-wrapped, but got {type(fsdp_root).__name__}.")

    # If the root module is a TE module, inject FSDP information into it
    if _is_te_module(fsdp_root.module):
        if hasattr(fsdp_root, "primary_weights_in_fp8"):
            if fsdp_root.primary_weights_in_fp8:
                raise RuntimeError(
                    "TE modules with primary weights in FP8 cannot be FSDP-wrapped. "
                    "Please initialize your model without the te.quantized_model_init(...) context."
                )
        root_state = _get_module_fsdp_state(fsdp_root)
        if root_state is None:
            raise RuntimeError(
                f"Root module ({type(fsdp_root.module).__name__}) does not have a valid "
                "_FSDPState. Ensure the module is properly wrapped with FSDP."
            )
        fsdp_root.module.fast_setattr("fsdp_group", root_state.process_group)

    # Iterate through all FSDP-wrapped submodules and inject FSDP information into TE modules
    fsdp_states, fsdp_modules = _get_fsdp_states_with_modules(fsdp_root)
    for state, fsdp_module in zip(fsdp_states, fsdp_modules):
        if _is_te_module(fsdp_module.module):
            if hasattr(fsdp_module.module, "primary_weights_in_fp8"):
                if fsdp_module.module.primary_weights_in_fp8:
                    raise RuntimeError(
                        f"TE module '{type(fsdp_module.module).__name__}' with primary weights "
                        "in FP8 cannot be FSDP-wrapped. Please initialize your model without "
                        "the te.quantized_model_init(...) context."
                    )
            fsdp_module.module.fast_setattr("fsdp_group", state.process_group)

def embed(self, documents: List[str], images: List[str] | None = None, verbose: bool = False) -> np.ndarray:
        # Embed documents
        doc_embeddings = None
        if documents[0] is not None:
            doc_embeddings = self.embed_documents(documents)

        # Embed images
        image_embeddings = None
        if isinstance(images, list):
            image_embeddings = self.embed_images(images, verbose)

        # Average embeddings
        averaged_embeddings = None
        if doc_embeddings is not None and image_embeddings is not None:
            averaged_embeddings = np.mean([doc_embeddings, image_embeddings], axis=0)

        if averaged_embeddings is not None:
            return averaged_embeddings
        elif doc_embeddings is not None:
            return doc_embeddings
        elif image_embeddings is not None:
            return image_embeddings

def estimate_eta(self, current_step: float | None, total_steps: float | None) -> float | None:
        if current_step is None or total_steps is None:
            return None
        steps_remaining = max(float(total_steps) - float(current_step), 0.0)
        if steps_remaining <= 0:
            return 0.0
        rates = self._compute_window_rates()
        steps_per_minute: float | None = None
        for window_minutes in sorted(self._windows, reverse=True):
            rate = rates.get(window_minutes)
            if rate:
                steps_per_minute = rate
                break
        if steps_per_minute is None:
            steps_per_minute = self._overall_rate()
        if steps_per_minute is None or steps_per_minute <= 0:
            return None
        steps_per_second = steps_per_minute / 60.0
        if steps_per_second <= 0:
            return None
        eta_seconds = steps_remaining / steps_per_second
        if math.isinf(eta_seconds) or eta_seconds != eta_seconds:
            return None
        return eta_seconds

def to_dataframe(self):
        result_per_metric = {}
        gts = {}
        preds = {}
        train_data = {}
        for fold_idx, fold in self.folds.items():
            for score_name, score_value in fold.scores.items():
                if score_name not in result_per_metric:
                    result_per_metric[score_name] = {}
                result_per_metric[score_name][f"fold_{fold_idx}_test"] = score_value
            if fold.ground_truth is not None:
                gts[f"ground_truth_fold_{fold_idx}"] = [fold.ground_truth]
            if fold.predictions is not None:
                preds[f"predictions_fold_{fold_idx}"] = [fold.predictions]
            if fold.train_data is not None:
                train_data[f"train_data_fold_{fold_idx}"] = [fold.train_data]
        for metric, mean in self.means.items():
            result_per_metric[metric]["mean"] = mean
        for metric, std in self.stds.items():
            result_per_metric[metric]["std"] = std

        return pd.concat(
            [
                pd.DataFrame(
                    {"validation_id": [self.task_id], "model_id": [self.model_id]}
                ),
                pd.json_normalize(result_per_metric, sep="_"),
                pd.DataFrame(gts),
                pd.DataFrame(preds),
                pd.DataFrame(train_data),
            ],
            axis=1,
        )

def is_dtype(cls, dtype: object) -> bool:
        dtype = getattr(dtype, "dtype", dtype)

        if isinstance(dtype, (ABCSeries, ABCIndex, ABCDataFrame, np.dtype)):
            # https://github.com/pandas-dev/pandas/issues/22960
            # avoid passing data to `construct_from_string`. This could
            # cause a FutureWarning from numpy about failing elementwise
            # comparison from, e.g., comparing DataFrame == 'category'.
            return False
        elif dtype is None:
            return False
        elif isinstance(dtype, cls):
            return True
        if isinstance(dtype, str):
            try:
                return cls.construct_from_string(dtype) is not None
            except TypeError:
                return False
        return False

def get_model(model_version: str, model_id: Optional[str] = None, **kwargs):
    if model_version not in _DEFAULT_MODEL_IDS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Invalid model_version '{model_version}'. "
                f"Must be one of: {list(_DEFAULT_MODEL_IDS.keys())}"
            ),
        )

    if not model_id:
        model_id = _DEFAULT_MODEL_IDS[model_version]

    valid_ids = _AVAILABLE_MODELS[model_version]
    if model_id not in valid_ids:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Invalid model_id '{model_id}' for {model_version}. "
                f"Must be one of: {valid_ids}"
            ),
        )

    key = (model_version, model_id)
    with _model_cache_lock:
        if key in _model_cache:
            logger.info("Model cache hit for %s", key)
            return _model_cache[key]

        logger.info("Loading model %s", key)
        extra = _EXTRAS_MAP.get(model_version, model_version)
        try:
            if model_version == "sam":
                from samgeo.samgeo import SamGeo

                model = SamGeo(model_type=model_id, **kwargs)
            elif model_version == "sam2":
                from samgeo.samgeo2 import SamGeo2

                model = SamGeo2(model_id=model_id, **kwargs)
            elif model_version == "sam3":
                from samgeo.samgeo3 import SamGeo3

                kwargs.setdefault("enable_inst_interactivity", True)
                model = SamGeo3(**kwargs)
        except ImportError as e:
            raise HTTPException(
                status_code=503,
                detail=(
                    f"Dependencies for {model_version} are not installed. "
                    f"Install with: pip install segment-geospatial[{extra}]. "
                    f"Error: {e}"
                ),
            )
        _model_cache[key] = (model, threading.Lock())
        return _model_cache[key]

def run_threaded(num_threads=4, calls_per_thread=10):
  def decorator(test_method):
    """Decorator around the test method."""
    @functools.wraps(test_method)  # Needed for `named_parameters` to work.
    def decorated_method(self, *args, **kwargs):
      """Actual method this factory will return."""
      exceptions = []
      def worker():
        try:
          for _ in range(calls_per_thread):
            test_method(self, *args, **kwargs)
        except Exception as exc:  # pylint: disable=broad-except
          # Appending to Python list is thread-safe:
          # http://effbot.org/pyfaq/what-kinds-of-global-value-mutation-are-thread-safe.htm
          exceptions.append(exc)
      if num_threads is not None:
        threads = [threading.Thread(target=worker, name='thread_{}'.format(i))
                   for i in range(num_threads)]
        for thread in threads:
          thread.start()
        for thread in threads:
          thread.join()
      else:
        worker()
      for exc in exceptions:
        raise exc
    return decorated_method
  return decorator

def augment_data(
    X, feature_metadata: FeatureMetadata, augmentation_data=None, augment_method="spunge", augment_args=None
):
    if augment_args is None:
        augment_args = {}
    if augmentation_data is not None:
        X_aug = augmentation_data
    else:
        if "num_augmented_samples" not in augment_args:
            if "max_size" not in augment_args:
                augment_args["max_size"] = np.inf
            augment_args["num_augmented_samples"] = int(
                min(augment_args["max_size"], augment_args["size_factor"] * len(X))
            )

        if augment_method == "spunge":
            X_aug = spunge_augment(X, feature_metadata, **augment_args)
        elif augment_method == "munge":
            X_aug = munge_augment(X, feature_metadata, **augment_args)
        else:
            raise ValueError(f"unknown augment_method: {augment_method}")

    # return postprocess_augmented(X_aug, X)  # TODO: dropping duplicates is much more efficient, but may skew distribution for entirely-categorical data with few categories.
    logger.log(15, f"Augmented training dataset with {len(X_aug)} extra datapoints")
    return X_aug.reset_index(drop=True)

def remove_runs(ctx, hashes, corrupted, yes):
    if len(hashes) == 0 and corrupted is False:
        click.echo('Please specify Run hashes or `--corrupted` flag to delete runs.')
        exit(1)
    repo_path = ctx.obj['repo']
    repo = Repo.from_path(repo_path)

    if corrupted:
        run_hashes = repo.list_corrupted_runs()
    else:
        run_hashes = match_runs(repo, hashes)
    if len(run_hashes) == 0:
        click.echo('No matching runs found.')
        exit(0)

    if yes:
        confirmed = True
    else:
        confirmed = click.confirm(
            f'This command will permanently delete {len(run_hashes)} runs from aim repo '
            f"located at '{repo_path}'. Do you want to proceed?"
        )
    if not confirmed:
        return

    success, remaining_runs = repo.delete_runs(run_hashes)
    if success:
        click.echo(f'Successfully deleted {len(run_hashes)} runs.')
    else:
        click.echo('Something went wrong while deleting runs. Remaining runs are:', err=True)
        click.secho('\t'.join(remaining_runs), fg='yellow')

def split_load_kwargs(inputs, kwargs, ctx_list, batch_axis=0):
    def split_map(obj):
        if isinstance(obj, NDArray):
            return split_and_load(obj, ctx_list, batch_axis, even_split=False)
        if isinstance(obj, tuple) and len(obj) > 0:
            return list(zip(*map(split_map, obj)))
        if isinstance(obj, list) and len(obj) > 0:
            return list(map(list, zip(*map(split_map, obj))))
        if isinstance(obj, dict) and len(obj) > 0:
            return list(map(type(obj), zip(*map(split_map, obj.items()))))
        return [obj for _ in ctx_list]

    inputs = split_map(inputs) if inputs else []
    kwargs = split_map(kwargs) if kwargs else []
    if len(inputs) < len(kwargs):
        inputs.extend([() for _ in range(len(kwargs) - len(inputs))])
    elif len(kwargs) < len(inputs):
        kwargs.extend([{} for _ in range(len(inputs) - len(kwargs))])
    inputs = tuple(inputs)
    kwargs = tuple(kwargs)
    return inputs, kwargs

def get_words_and_spaces(
    words: Iterable[str], text: str
) -> Tuple[List[str], List[bool]]:
    if "".join("".join(words).split()) != "".join(text.split()):
        raise ValueError(Errors.E194.format(text=text, words=words))
    text_words = []
    text_spaces = []
    text_pos = 0
    # normalize words to remove all whitespace tokens
    norm_words = [word for word in words if not word.isspace()]
    # align words with text
    for word in norm_words:
        try:
            word_start = text[text_pos:].index(word)
        except ValueError:
            raise ValueError(Errors.E194.format(text=text, words=words)) from None
        if word_start > 0:
            text_words.append(text[text_pos : text_pos + word_start])
            text_spaces.append(False)
            text_pos += word_start
        text_words.append(word)
        text_spaces.append(False)
        text_pos += len(word)
        if text_pos < len(text) and text[text_pos] == " ":
            text_spaces[-1] = True
            text_pos += 1
    if text_pos < len(text):
        text_words.append(text[text_pos:])
        text_spaces.append(False)
    return (text_words, text_spaces)

def penntreebank2universal(token, tag):
    if tag.startswith(("NNP-", "NNPS-")):
        return (token, "%s-%s" % (NOUN, tag.split("-")[-1]))
    if tag in ("NN", "NNS", "NNP", "NNPS", "NP"):
        return (token, NOUN)
    if tag in ("MD", "VB", "VBD", "VBG", "VBN", "VBP", "VBZ"):
        return (token, VERB)
    if tag in ("JJ", "JJR", "JJS"):
        return (token, ADJ)
    if tag in ("RB", "RBR", "RBS", "WRB"):
        return (token, ADV)
    if tag in ("PR", "PRP", "PRP$", "WP", "WP$"):
        return (token, PRON)
    if tag in ("DT", "PDT", "WDT", "EX"):
        return (token, DET)
    if tag in ("IN", "PP"):
        return (token, PREP)
    if tag in ("CD", "NO"):
        return (token, NUM)
    if tag in ("CC", "CJ"):
        return (token, CONJ)
    if tag in ("UH",):
        return (token, INTJ)
    if tag in ("POS", "PT", "RP", "TO"):
        return (token, PRT)
    if tag in ("SYM", "LS", ".", "!", "?", ",", ":", "(", ")", "\"", "#", "$"):
        return (token, PUNC)
    return (token, X)

def transform_fixup_multiple_definitions(sources: list[str]) -> list[str]:
    try:
        cells = [
            compile_cell(source, cell_id=CellId_t(str(i)))
            for i, source in enumerate(sources)
        ]
    except SyntaxError:
        return sources

    graph = DirectedGraph()
    for cell in cells:
        graph.register_cell(cell_id=cell.cell_id, cell=cell)

    multiply_defined_names = graph.get_multiply_defined()
    if not multiply_defined_names:
        return sources

    name_transformations: dict[str, str] = {}
    for name in multiply_defined_names:
        if not graph.get_referring_cells(name, language="python"):
            name_transformations[name] = (
                "_" + name if not name.startswith("_") else name
            )

    def transform(source: str) -> str:
        try:
            tree = ast.parse(source)
            visitor = NameTransformer(name_transformations)
            transformed_tree = visitor.visit(tree)
            # Don't unparse if no changes were made
            # otherwise we lose comments and formatting
            if visitor.made_changes:
                return ast.unparse(transformed_tree)
            return source
        except SyntaxError:
            return source

    return [transform(source) for source in sources]

async def authenticate(
        self,
        credentials: Dict[str, Any],
    ) -> Tuple[bool, Optional[ExternalUser], Optional[str]]:
        username = credentials.get("username", "")
        password = credentials.get("password", "")

        if not username or not password:
            return False, None, "Username and password required"

        try:
            import ldap3

            # First, find the user
            user_dn, user_attrs = await self._find_user(username)

            if not user_dn:
                return False, None, "User not found"

            # Try to bind as the user
            server = ldap3.Server(
                self._server,
                use_ssl=self._use_ssl,
                get_info=ldap3.NONE,
            )

            conn = ldap3.Connection(
                server,
                user=user_dn,
                password=password,
                auto_bind=False,
            )

            try:
                if self._start_tls:
                    conn.start_tls()

                if not conn.bind():
                    return False, None, "Invalid credentials"

                # Get user groups (pass username for posixGroup support)
                groups = await self._get_user_groups(user_dn, username)

                # Create user object
                user = self._attrs_to_user(user_dn, user_attrs, groups)
                return True, user, None
            finally:
                try:
                    conn.unbind()
                except Exception:
                    pass

        except ImportError as exc:
            return False, None, str(exc)
        except Exception as exc:
            logger.error("LDAP auth failed: %s", exc, exc_info=True)
            return False, None, str(exc)

def need_compress_const(
        self, op: Operation, _is_deprecated: bool, weight_threshold: float
    ) -> bool:
        val = self._get_const_value(op)
        if _is_deprecated and weight_threshold != None:
            raise ValueError("weight_threshold cannot be set through the deprecated ct.compression_util API")

        if _is_deprecated:
            return should_use_weight_file(val)

        if not self._validate_child_constexpr_for_compress(op):
            return False

        if weight_threshold is None:
            raise ValueError("weight_threshold cannot be None")

        # Disable 1D tensor compression due to MIL 1D Tensor bug (rdar://113860800).
        if (
            not op.outputs[0].child_ops[0].op_type.startswith("constexpr_")
            and op.outputs[0].rank <= 1
        ):
            return False

        return (
            should_use_weight_file(val) and self._get_weight_to_compress_size(op) > weight_threshold
        )

def get_obs_shape(
    observation_space: spaces.Space,
) -> tuple[int, ...] | dict[str, tuple[int, ...]]:
    if isinstance(observation_space, spaces.Box):
        return observation_space.shape
    elif isinstance(observation_space, spaces.Discrete):
        # Observation is an int
        return (1,)
    elif isinstance(observation_space, spaces.MultiDiscrete):
        # Number of discrete features
        return (len(observation_space.nvec),)
    elif isinstance(observation_space, spaces.MultiBinary):
        # Number of binary features
        return observation_space.shape
    elif isinstance(observation_space, spaces.Dict):
        return {key: get_obs_shape(subspace) for (key, subspace) in observation_space.spaces.items()}  # type: ignore[misc]

    else:
        raise NotImplementedError(f"{observation_space} observation space is not supported")

def calculate_dynamic_shift_mu(self, noise_scheduler, latents: torch.Tensor | None):
        if latents is None:
            return None

        scheduler_config = getattr(noise_scheduler, "config", None)
        if scheduler_config is None:
            return None

        required_fields = [
            "base_image_seq_len",
            "max_image_seq_len",
            "base_shift",
            "max_shift",
        ]
        missing_fields = [field for field in required_fields if getattr(scheduler_config, field, None) is None]
        if missing_fields:
            raise ValueError(
                f"Cannot compute dynamic timestep shift; scheduler is missing config values: {', '.join(missing_fields)}"
            )

        patch_size = self._get_patch_size_for_dynamic_shift(noise_scheduler)
        if patch_size is None or patch_size <= 0:
            raise ValueError("Cannot compute dynamic timestep shift because no valid `patch_size` was found.")

        # Handle video latents [B, C, F, H, W] vs image latents [B, C, H, W]
        if latents.ndim == 5:
            num_frames, height, width = latents.shape[-3:]
        else:
            num_frames = 1
            height, width = latents.shape[-2:]

        # Compute sequence length (spatiotemporal for video, spatial for images)
        seq_len = num_frames * (int(height) // int(patch_size)) * (int(width) // int(patch_size))
        from simpletuner.helpers.models.sd3.pipeline import calculate_shift

        return calculate_shift(
            seq_len,
            scheduler_config.base_image_seq_len,
            scheduler_config.max_image_seq_len,
            scheduler_config.base_shift,
            scheduler_config.max_shift,
        )

def lower(op):
        dtype = op.dtype
        t = DataType(dtype)
        if get_type_registered(t.type_code):
            dtype = "uint" + str(t.bits)
            if t.lanes > 1:
                dtype += "x" + str(t.lanes)

        key = t.bits
        if isinstance(op, _Cast):
            src_bits = DataType(op.value.dtype).bits
            key = (src_bits, t.bits)

        if key not in extern_func_map:
            raise RuntimeError(f"missing key {key} in extern_func_map for {op}")

        if isinstance(op, _Cast):
            return call_pure_extern(dtype, extern_func_map[key], op.value)
        if isinstance(op, _FloatImm):
            return call_pure_extern(dtype, extern_func_map[key], op.value)
        if isinstance(op, _Call):
            return call_pure_extern(dtype, extern_func_map[key], *op.args)
        if isinstance(op, _BinaryOpExpr):
            return call_pure_extern(dtype, extern_func_map[key], op.a, op.b)

        raise RuntimeError(f"lowering unsupported op: {op}")

def object_size(x, memo=None):
    # Note: this will not process object arrays properly (since those only)
    # hold references
    if memo is None:
        memo = dict()
    id_ = id(x)
    if id_ in memo:
        return 0  # do not add already existing ones
    if isinstance(x, bytes | str | int | float | type(None) | Path):
        size = sys.getsizeof(x)
    elif isinstance(x, np.ndarray):
        # On newer versions of NumPy, just doing sys.getsizeof(x) works,
        # but on older ones you always get something small :(
        size = sys.getsizeof(np.array([]))
        if x.base is None or id(x.base) not in memo:
            size += x.nbytes
    elif isinstance(x, np.generic):
        size = x.nbytes
    elif isinstance(x, dict):
        size = sys.getsizeof(x)
        for key, value in x.items():
            size += object_size(key, memo)
            size += object_size(value, memo)
    elif isinstance(x, list | tuple):
        size = sys.getsizeof(x) + sum(object_size(xx, memo) for xx in x)
    elif isinstance(x, datetime):
        size = object_size(_dt_to_stamp(x), memo)
    elif isinstance(x, date):
        size = 24  # 3 8-byte integers
    elif _is_sparse_cs(x):
        size = sum(sys.getsizeof(xx) for xx in [x, x.data, x.indices, x.indptr])
    else:
        raise RuntimeError(f"unsupported type: {type(x)} ({x})")
    memo[id_] = size
    return size

def merge_cell_notification(
    previous: CellNotification | None,
    current: CellNotification,
) -> CellNotification:
    if previous is None:
        return current

    assert previous.cell_id == current.cell_id

    if current.status is None:
        current.status = previous.status

    # If we went from queued to running, clear the console.
    if current.status == "running" and previous.status == "queued":
        current.console = []
    else:
        combined_console: list[CellOutput] = as_list(previous.console)
        combined_console.extend(as_list(current.console))
        current.console = _merge_consecutive_console_outputs(combined_console)

    # If we went from running to running, use the previous timestamp.
    if current.status == "running" and previous.status == "running":
        current.timestamp = previous.timestamp

    if current.output is None:
        current.output = previous.output

    return current

def resolve_model_path(model_path, default_dir: Path = WEIGHTS) -> Path:
    path = Path(model_path)
    candidates = [path]
    if not path.is_absolute() and path.parent == Path("."):
        candidates.append(default_dir / path.name)

    for candidate in candidates:
        if candidate.exists():
            return candidate

    for candidate in candidates:
        parent = candidate.parent
        if not parent.exists():
            continue
        lowered_name = candidate.name.lower()
        for sibling in parent.iterdir():
            if sibling.name.lower() == lowered_name:
                return sibling

    return candidates[-1]

def transform_function_signatures(self, func: Function) -> None:
        # reset input signatures
        old_func_inputs = func.inputs
        new_func_inputs = {}
        cache_vars = {}

        # cast the new input into the original dtype
        for k, v in old_func_inputs.items():
            if v.is_tensor_or_scalar_of(self.origin_dtype):
                new_input = mb.placeholder(
                    shape=v.shape,
                    dtype=string_to_builtin(self.target_dtype),
                    name=v.name,
                ).outputs[0]

                if v in func.outputs:
                    new_outputs = []
                    for val in func.outputs:
                        new_outputs.append(new_input if val == v else val)
                    func.set_outputs(new_outputs)

                new_func_inputs[k] = new_input
                cast_input = mb.cast(
                    x=new_input,
                    dtype=self.origin_dtype,
                    before_op=func.operations[0] if len(func.operations) > 0 else None,
                )
                cache_vars[k] = cast_input
            else:
                new_func_inputs[k] = v
                cache_vars[k] = v

        # replace the use of the old input vars with the new cast var
        for k, v in old_func_inputs.items():
            func.replace_uses_of_var_after_op(
                anchor_op=None,
                old_var=v,
                new_var=cache_vars[k],
            )
        func._input_dict = new_func_inputs

        # reset output signatures
        if func.output_types is None:
            output_types = [input_types.TensorType(dtype=v.dtype) for v in func.outputs]
        else:
            output_types = func.output_types

        for idx, v in enumerate(output_types):
            if v.dtype == string_to_builtin(self.origin_dtype):
                output_types[idx] = input_types.TensorType(
                    dtype=string_to_builtin(self.target_dtype)
                )

        func.output_types = output_types

def get(self, s3_path, check_file=False):
        local_path = os.path.join(self.local_folder, s3_path)

        if os.path.exists(local_path):
            # If the file is in local cache and no check freshness needed, then
            # directly return the path.
            if not check_file:
                return local_path
            try:
                if not self._remote_is_different(local_path, s3_path):
                    return local_path
            except self.s3_client.exceptions.NoSuchKey:
                raise FileNotFoundError(f"{s3_path} not found in S3.")
            except (NoCredentialsError, PartialCredentialsError) as e:
                raise e
            except Exception as e:
                raise RuntimeError(f"Error checking {s3_path} in S3: {e}")
        # If we reached this point, we need to download the file from S3
        try:
            local_dir = os.path.dirname(local_path)
            if not os.path.exists(local_dir):
                os.makedirs(local_dir)
            self.s3_client.download_file(self.s3_bucket, s3_path, local_path)
            return local_path
        except Exception as e:
            raise RuntimeError(f"Error downloading {s3_path} in S3.") from e

def list_doc_entities(doc):
    entities = []
    for sentence in doc.sentences:
        current_entity = []
        previous_label = None
        for token in sentence.tokens:
            if token.ner == 'O' or token.ner.startswith("E-"):
                if token.ner.startswith("E-"):
                    current_entity.append(token.text)
                if current_entity:
                    assert previous_label is not None
                    entities.append((current_entity, previous_label))
                    current_entity = []
                    previous_label = None
            elif token.ner.startswith("I-"):
                if previous_label is not None and previous_label != 'O' and previous_label != token.ner[2:]:
                    if current_entity:
                        assert previous_label is not None
                        entities.append((current_entity, previous_label))
                        current_entity = []
                        previous_label = token.ner[2:]
                current_entity.append(token.text)
            elif token.ner.startswith("B-") or token.ner.startswith("S-"):
                if current_entity:
                    assert previous_label is not None
                    entities.append((current_entity, previous_label))
                    current_entity = []
                    previous_label = None
                current_entity.append(token.text)
                previous_label = token.ner[2:]
                if token.ner.startswith("S-"):
                    assert previous_label is not None
                    entities.append(current_entity)
                    current_entity = []
                    previous_label = None
            else:
                raise RuntimeError("Expected BIO(ES) format in the json file!")
            previous_label = token.ner[2:]
        if current_entity:
            assert previous_label is not None
            entities.append((current_entity, previous_label))
    entities = [(tuple(x[0]), x[1]) for x in entities]
    return entities

def js_run(settings, nics, env, command, stdout=None, stderr=None):
    mpi_impl_flags, _ = _get_mpi_implementation_flags(settings.tcp_flag, env=env)
    if mpi_impl_flags is None:
        raise Exception(_MPI_NOT_FOUND_ERROR_MSG)

    if not is_jsrun_installed():
        raise Exception(
            'horovod does not find the jsrun command.\n\n'
            'Please, make sure you are running on a cluster with jsrun installed or '
            'use one of the other launchers.')

    if nics and 'NCCL_SOCKET_IFNAME' not in env:
        env['NCCL_SOCKET_IFNAME'] = ','.join(nics)

    smpiargs = ' '.join(mpi_impl_flags)
    if settings.extra_mpi_args:
        smpiargs += ' ' + settings.extra_mpi_args

    if settings.binding_args:
        binding_args = settings.binding_args
    else:
        rf = generate_jsrun_rankfile(settings)
        if settings.verbose >= 2:
            safe_shell_exec.execute('cat {rf}'.format(rf=rf))
        binding_args = '--erf_input {rf}'.format(rf=rf)

    jsrun_command = (
        'jsrun {binding_args} '
        '{output_filename_arg} '
        '{smpiargs} '
        '{command}'
        .format(binding_args = binding_args,
                output_filename_arg='--stdio_stderr {file} --stdio_stdout {file}'.format(file=settings.output_filename)
                                    if settings.output_filename else '',
                smpiargs= '--smpiargs {args}'.format(args=quote(smpiargs)) if smpiargs else '',
                command=' '.join(quote(par) for par in command))
    )

    if settings.verbose >= 2:
        print(jsrun_command)

    # Execute the jsrun command.
    if settings.run_func_mode:
        exit_code = safe_shell_exec.execute(jsrun_command, env=env, stdout=stdout, stderr=stderr)
        if exit_code != 0:
            raise RuntimeError("jsrun failed with exit code {exit_code}".format(exit_code=exit_code))
    else:
        os.execve('/bin/sh', ['/bin/sh', '-c', jsrun_command], env)

def nested_simplify(obj, decimals=3):
    import numpy as np

    if isinstance(obj, list):
        return [nested_simplify(item, decimals) for item in obj]
    if isinstance(obj, tuple):
        return tuple(nested_simplify(item, decimals) for item in obj)
    elif isinstance(obj, np.ndarray):
        return nested_simplify(obj.tolist())
    elif isinstance(obj, Mapping):
        return {nested_simplify(k, decimals): nested_simplify(v, decimals) for k, v in obj.items()}
    elif isinstance(obj, (str, int, np.int64)) or obj is None:
        return obj
    elif is_torch_available() and isinstance(obj, torch.Tensor):
        return nested_simplify(obj.tolist(), decimals)
    elif isinstance(obj, float):
        return round(obj, decimals)
    elif isinstance(obj, (np.int32, np.float32, np.float16)):
        return nested_simplify(obj.item(), decimals)
    else:
        raise Exception(f"Not supported: {type(obj)}")

def calculate_qparams(self):
        if self.synchronize:
            self.min_val.data = _sync_tensor(self.min_val, _torch.distributed.ReduceOp.MIN).data
            self.max_val.data = _sync_tensor(self.max_val, _torch.distributed.ReduceOp.MAX).data

        scale, zero_point = self._calculate_qparams(self.min_val, self.max_val)

        if self.synchronize:
            scale.data = _sync_tensor(scale).data
            zero_point.data = _sync_tensor(zero_point).data

        # scale and zero-point are required to be 1-dimensional for export
        if self.ch_axis != -1:
            scale = _torch.squeeze(scale)
            zero_point = _torch.squeeze(zero_point)

        # See https://pytorch.org/docs/stable/generated/torch.ao.quantization.observer.MinMaxObserver.html
        # for information on how scale and zp are computed in PyTorch
        if _is_symmetric_quant(self.qscheme):
            if self.dtype == _torch.quint8 and not self.has_customized_qrange:
                zero_point.data.fill_(128.0)
            elif self.dtype == _torch.quint8:
                assert self.has_customized_qrange
                zero_point.data.fill_(float((self.quant_min + self.quant_max) // 2))
            else:
                assert self.dtype == _torch.qint8
                zero_point.data.zero_()
        else:
            zero_point.data.round_().clamp_(self.quant_min, self.quant_max)
            zero_point.data = zero_point.float().data

        zero_point = zero_point.int()

        return scale, zero_point

def contains_cycle(self):
        distances = {}

        for node in self.nodes.values():
            for dep in node["deps"]:
                key = tuple([node["address"], dep])
                distances[key] = 1

        for _ in self.nodes:
            new_entries = {}

            for pair1 in distances:
                for pair2 in distances:
                    if pair1[1] == pair2[0]:
                        key = tuple([pair1[0], pair2[1]])
                        new_entries[key] = distances[pair1] + distances[pair2]

            for pair in new_entries:
                distances[pair] = new_entries[pair]
                if pair[0] == pair[1]:
                    path = self.get_cycle_path(self.get_by_address(pair[0]), pair[0])
                    return path

        return False  # return []?

def cmp(field, value, comparison="=", escape=lambda v: _escape(v), table=""):
    # Use absolute field names if table name is given:
    if table:
        field = abs(table, field)
    # cmp("name", "Mar*") => "name like 'Mar%'".
    if isinstance(value, str) and (value.startswith(("*", "%")) or value.endswith(("*", "%"))):
        if comparison in ("=", "i=", "==", LIKE):
            return "%s like %s" % (field, escape(value.replace("*", "%")))
        if comparison in ("!=", "<>"):
            return "%s not like %s" % (field, escape(value.replace("*", "%")))
    # cmp("name", "markov") => "name" like 'markov'" (case-insensitive).
    if isinstance(value, str):
        if comparison == "i=":
            return "%s like %s" % (field, escape(value))
    # cmp("type", ("cat", "dog"), "!=") => "type not in ('cat','dog')".
    # cmp("amount", (10, 100), ":") => "amount between 10 and 100".
    if isinstance(value, (list, tuple)):
        if find(lambda v: isinstance(v, str) and (v.startswith("*") or v.endswith("*")), value):
            return "(%s)" % any(*[(field, v) for v in value]).sql(escape=escape)
        if comparison in ("=", "==", IN):
            return "%s in (%s)" % (field, ",".join(escape(v) for v in value))
        if comparison in ("!=", "<>"):
            return "%s not in (%s)" % (field, ",".join(escape(v) for v in value))
        if comparison in (":", BETWEEN):
            return "%s between %s and %s" % (field, escape(value[0]), escape(value[1]))
    # cmp("type", None, "!=") => "type is not null".
    if isinstance(value, type(None)):
        if comparison in ("=", "=="):
            return "%s is null" % field
        if comparison in ("!=", "<>"):
            return "%s is not null" % field
    # Using a subquery:
    if isinstance(value, Query):
        if comparison in ("=", "==", IN):
            return "%s in %s" % (field, escape(value))
        if comparison in ("!=", "<>"):
            return "%s not in %s" % (field, escape(value))
    return "%s%s%s" % (field, comparison, escape(value))

def set_meta_tensor(self, fwd: bool, recipe: Union[Recipe, List[Recipe]]) -> None:
        if isinstance(recipe, Recipe):
            recipe = [recipe]
        fp8_recipe_dpa = recipe[-1]
        fp8_meta_tensor_key = "scaling_fwd" if fwd else "scaling_bwd"

        # Return early if recipe state matches recipe
        if self.fp8_meta_tensors_initialized:
            recipe_state = self.fp8_meta[fp8_meta_tensor_key]
            if fp8_recipe_dpa.delayed() and isinstance(recipe_state, DelayedScalingRecipeState):
                self.adjust_amax_history_length(fp8_recipe_dpa.amax_history_len, fwd=fwd)
                return
            if fp8_recipe_dpa.mxfp8() and isinstance(recipe_state, MXFP8BlockScalingRecipeState):
                return
            if fp8_recipe_dpa.float8_current_scaling() and isinstance(
                recipe_state, Float8CurrentScalingRecipeState
            ):
                return
            if fp8_recipe_dpa.float8_block_scaling() and isinstance(
                recipe_state, Float8BlockScalingRecipeState
            ):
                return

        # When fp8_recipe=Float8CurrentScaling, recipe=[CS, DS], and QKV/dQKV, O/dO use CS quantizers, S/dP use DS quantizers.
        # See table above in init_fp8_metadata for more detail.
        num_gemms = [2, 1] if len(recipe) == 2 else [3]
        # Max. number of fp8 tensors per GEMM = 3 (input, weight, output) for fwd and
        # 2 (grad_output and grad_input) for bwd
        num_fp8_tensors = [x * 3 if fwd else x * 2 for x in num_gemms]

        # Initialize recipe state and quantizers
        recipe_states = [
            RecipeState.create(
                recipe[i],
                mode=("forward" if fwd else "backward"),
                num_quantizers=num_fp8_tensors[i],
            )
            for i in range(len(recipe))
        ]

        self.fp8_meta[fp8_meta_tensor_key] = (
            recipe_states[-1] if len(recipe) == 2 else recipe_states[0]
        )
        self.quantizers[fp8_meta_tensor_key] = []
        for recipe_state in recipe_states:
            self.quantizers[fp8_meta_tensor_key].extend(recipe_state.make_quantizers())

def classids(self, lemma=None, wordnetid=None, fileid=None, classid=None):
        if fileid is not None:
            return [c for (c, f) in self._class_to_fileid.items() if f == fileid]
        elif lemma is not None:
            return self._lemma_to_class[lemma]
        elif wordnetid is not None:
            return self._wordnet_to_class[wordnetid]
        elif classid is not None:
            xmltree = self.vnclass(classid)
            return [
                subclass.get("ID")
                for subclass in xmltree.findall("SUBCLASSES/VNSUBCLASS")
            ]
        else:
            return sorted(self._class_to_fileid.keys())

def PrePlot(num=None, rows=None, cols=None):
    if num:
        _Brewer.InitializeIter(num)

    if rows is None and cols is None:
        return

    if rows is not None and cols is None:
        cols = 1

    if cols is not None and rows is None:
        rows = 1

    # resize the image, depending on the number of rows and cols
    size_map = {(1, 1): (8, 6),
                (1, 2): (14, 6),
                (1, 3): (14, 6),
                (2, 2): (10, 10),
                (2, 3): (16, 10),
                (3, 1): (8, 10),
                }

    if (rows, cols) in size_map:
        fig = pyplot.gcf()
        fig.set_size_inches(*size_map[rows, cols])

    # create the first subplot
    if rows > 1 or cols > 1:
        pyplot.subplot(rows, cols, 1)
        global SUBPLOT_ROWS, SUBPLOT_COLS
        SUBPLOT_ROWS = rows
        SUBPLOT_COLS = cols

def print_colored_diff(expected: str, current: str) -> None:
    expected_lines = expected.splitlines(keepends=True)
    current_lines = current.splitlines(keepends=True)

    diff = unified_diff(
        current_lines, expected_lines, fromfile="Current content", tofile="Expected content", lineterm=""
    )

    for line in diff:
        line = line.rstrip("\n")
        if line.startswith("+++"):
            print(f"\033[92m{line}\033[0m")  # Green for additions
        elif line.startswith("---"):
            print(f"\033[91m{line}\033[0m")  # Red for deletions
        elif line.startswith("@@"):
            print(f"\033[96m{line}\033[0m")  # Cyan for context
        elif line.startswith("+"):
            print(f"\033[92m{line}\033[0m")  # Green for additions
        elif line.startswith("-"):
            print(f"\033[91m{line}\033[0m")  # Red for deletions
        else:
            print(line)  # Default color for context

async def resume(
    name: Annotated[Optional[str], cyclopts.Parameter(show=False)] = None,
    *,
    id: Annotated[
        Optional[str],
        cyclopts.Parameter("--id", help="An automation's id"),
    ] = None,
):
    from prefect.client.orchestration import get_client
    from prefect.exceptions import PrefectHTTPStatusError

    if not id and not name:
        exit_with_error("Please provide either a name or an id.")

    if name:
        async with get_client() as client:
            automation = await client.read_automations_by_name(name=name)
            if not automation:
                exit_with_error(
                    f"Automation with name {name!r} not found. You can also specify an id with the `--id` flag."
                )
            if len(automation) > 1:
                from prefect.cli._prompts import confirm

                if not confirm(
                    f"Multiple automations found with name {name!r}. Do you want to resume all of them?",
                    default=False,
                    console=_cli.console,
                ):
                    exit_with_error("Resume aborted.")

            for a in automation:
                await client.resume_automation(a.id)
            exit_with_success(
                f"Resumed automation(s) with name {name!r} and id(s) {', '.join([repr(str(a.id)) for a in automation])}."
            )

    elif id:
        async with get_client() as client:
            try:
                uuid_id = UUID(id)
                automation = await client.read_automation(uuid_id)
            except (PrefectHTTPStatusError, ValueError):
                exit_with_error(f"Automation with id {id!r} not found.")
            await client.resume_automation(automation.id)
            exit_with_success(f"Resumed automation with id {str(automation.id)!r}.")

def denormalize_latents_for_preview(self, latents: torch.Tensor) -> torch.Tensor:
        vae = self.get_vae()
        if vae is None:
            return latents
        scaling_factor = self._vae_scaling_factor()

        # Check config first (e.g., SDXL VAE stores stats in config)
        latents_mean = getattr(vae.config, "latents_mean", None)
        latents_std = getattr(vae.config, "latents_std", None)

        # Fallback to buffer attributes (e.g., LTX-2 VAE stores stats as registered buffers)
        if latents_mean is None:
            latents_mean = getattr(vae, "latents_mean", None)
        if latents_std is None:
            latents_std = getattr(vae, "latents_std", None)

        if latents.ndim == 4:
            view_shape = (1, latents.shape[1], 1, 1)
        elif latents.ndim == 5:
            view_shape = (1, latents.shape[1], 1, 1, 1)
        else:
            raise ValueError(f"Unsupported number of dimensions for latents: {latents.ndim}. Expected 4 or 5.")

        if latents_mean is not None and latents_std is not None:
            # Handle both tensor buffers and list/tuple config values
            if torch.is_tensor(latents_mean):
                mean = latents_mean.to(device=latents.device, dtype=latents.dtype).view(view_shape)
            else:
                mean = torch.tensor(latents_mean, device=latents.device, dtype=latents.dtype).view(view_shape)
            if torch.is_tensor(latents_std):
                std = latents_std.to(device=latents.device, dtype=latents.dtype).view(view_shape)
            else:
                std = torch.tensor(latents_std, device=latents.device, dtype=latents.dtype).view(view_shape)
            latents = latents * std / scaling_factor + mean
        else:
            latents = latents / scaling_factor
        return latents

def run(self) -> None:
        try:
            if self._status == StrategyStatus.RUNNING:
                raise RuntimeError('Strategy is already running.')

            if self._status == StrategyStatus.INTERRUPTED:
                raise RuntimeError('Strategy is interrupted. Please resume by creating a new strategy and load_state_dict.')

            if self._status != StrategyStatus.INITIALIZED:
                raise RuntimeError('Strategy should not be called twice.')

            self._status = StrategyStatus.RUNNING

            # Explore the model space.
            self._run()
            # Strategy doesn't wait for the models it submitted.

            _logger.debug('Strategy has successfully finished.')
            self._status = StrategyStatus.SUCCEEDED
        except KeyboardInterrupt:
            _logger.warning('Strategy is interrupted.')
            self._status = StrategyStatus.INTERRUPTED
            raise
        except:
            _logger.error('Strategy failed to execute.')
            self._status = StrategyStatus.FAILED
            raise
        finally:
            try:
                self._cleanup()
            except:
                _logger.exception('Exception raised during strategy cleanup. Ignore.')

def get_source_ancestors(
    node_id: str,
    all_nodes: dict[str, DbtNode],
) -> set[str]:
    sources: set[str] = set()
    visited: set[str] = set()

    def _walk(current_id: str) -> None:
        if current_id in visited:
            return
        visited.add(current_id)

        node = all_nodes.get(current_id)
        if node is None:
            return

        if node.resource_type == NodeType.Source:
            sources.add(current_id)
            return

        for dep_id in node.depends_on:
            _walk(dep_id)

    node = all_nodes.get(node_id)
    if node is None:
        return sources

    for dep_id in node.depends_on:
        _walk(dep_id)

    return sources

def post_process_semantic_segmentation(self, outputs, target_sizes: list[tuple] | None = None):
        import torch
        import torch.nn.functional as F

        logits = outputs.logits

        # Resize logits and compute semantic segmentation maps
        if target_sizes is not None:
            if len(logits) != len(target_sizes):
                raise ValueError(
                    "Make sure that you pass in as many target sizes as the batch dimension of the logits"
                )

            if isinstance(target_sizes, torch.Tensor):
                target_sizes = target_sizes.numpy()

            semantic_segmentation = []

            for idx in range(len(logits)):
                resized_logits = F.interpolate(
                    logits[idx].unsqueeze(dim=0), size=target_sizes[idx], mode="bilinear", align_corners=False
                )
                semantic_map = resized_logits[0].argmax(dim=0)
                semantic_segmentation.append(semantic_map)
        else:
            semantic_segmentation = logits.argmax(dim=1)
            semantic_segmentation = [semantic_segmentation[i] for i in range(semantic_segmentation.shape[0])]

        return semantic_segmentation

def clean_refs(value):
        if isinstance(value, dict):
            # Create a new dictionary without $ref keys and without values containing #/$defs
            cleaned_dict = {}
            for k, v in value.items():
                if k == '$ref':
                    continue
                cleaned_dict[k] = clean_refs(v)
            return cleaned_dict
        elif isinstance(value, list):
            # Process each item in the list
            return [clean_refs(item) for item in value]
        else:
            # Return primitive values as-is
            return value

def convert_legacy_checkpoint(old_path: str, new_path: str) -> None:
    old: dict[str, Any] = torch.load(old_path, map_location="cpu", weights_only=False)

    if "model" not in old:
        raise ValueError(
            f"The checkpoint at {old_path!r} does not contain a 'model' key."
            " Only RF-DETR legacy .pth files produced by engine.py are supported."
        )

    args_obj = old.get("args")
    if isinstance(args_obj, dict):
        hyper_parameters: dict[str, Any] = args_obj
    elif args_obj is None:
        hyper_parameters = {}
    else:
        try:
            hyper_parameters = vars(args_obj)
        except TypeError:
            logger.warning(
                "Cannot extract hyper_parameters from args of type %s; storing empty dict.",
                type(args_obj).__name__,
            )
            hyper_parameters = {}

    new: dict[str, Any] = {
        "state_dict": {"model." + k: v for k, v in old["model"].items()},
        "epoch": old.get("epoch", 0),
        "global_step": 0,
        "hyper_parameters": hyper_parameters,
        "legacy_checkpoint_format": True,
    }

    if "ema_model" in old:
        # Preserve EMA weights under a dedicated key.  Callback-specific state
        # keys are framework-internal and must not be written here.
        new["legacy_ema_state_dict"] = old["ema_model"]

    torch.save(new, new_path)

def get_gpu_instance_configurations(gpu_id: str) -> List[Dict[str, Any]]:
    instances = []
    detailed_gpu_1 = get_gpu_details(gpu_id, gpu_count=1)
    base_gpu_name = format_gpu_name(detailed_gpu_1)

    # If the GPU isn't in DEFAULT_GPU_INFO we default to a max of 8 GPUs
    if base_gpu_name in DEFAULT_GPU_INFO:
        max_gpu_count = DEFAULT_GPU_INFO[base_gpu_name].get(
            'max_count', DEFAULT_MAX_GPUS)
    else:
        max_gpu_count = DEFAULT_MAX_GPUS

    for gpu_count in range(1, int(max_gpu_count) + 1):
        # Get detailed GPU info for this count
        if gpu_count == 1:
            detailed_gpu = detailed_gpu_1
        else:
            detailed_gpu = get_gpu_details(gpu_id, gpu_count)

        # Only add secure clouds skipping community cloud instances.
        if not detailed_gpu['secureCloud']:
            continue

        # Get basic info including memory & vcpu from the returned data
        # If memory or vpcu is not available, skip this gpu count
        gpu_info = get_gpu_info(base_gpu_name, detailed_gpu, gpu_count)
        if gpu_info is None:
            continue

        spot_price = base_price = None
        if detailed_gpu['secureSpotPrice'] is not None:
            spot_price = format_price(detailed_gpu['secureSpotPrice'] *
                                      gpu_count)
        if detailed_gpu['securePrice'] is not None:
            base_price = format_price(detailed_gpu['securePrice'] * gpu_count)

        for region, zones in REGION_ZONES.items():
            for zone in zones:
                instances.append({
                    'InstanceType': f'{gpu_count}x_{base_gpu_name}_SECURE',
                    'AcceleratorName': base_gpu_name,
                    'AcceleratorCount': float(gpu_count),
                    'SpotPrice': spot_price,
                    'Price': base_price,
                    'Region': region,
                    'AvailabilityZone': zone,
                    **gpu_info
                })

    return instances

def split_on_batch(x):
      length = len(x.get_shape())
      size = hparams.video_num_input_frames
      if length < 1:
        raise ValueError("Batched tensor of length < 1.")
      if length == 1:
        return x[:size], x[size:]
      if length == 2:
        return x[:size, :], x[size:, :]
      if length == 3:
        return x[:size, :, :], x[size:, :, :]
      if length == 4:
        return x[:size, :, :, :], x[size:, :, :, :]
      # TODO(lukaszkaiser): use tf.split for the general case.
      raise ValueError("Batch splitting on general dimensions not done yet.")

def timestamp_to_datetime(self, timestamp, tzinfo=MARKER):
        if tzinfo is MARKER:  # allow to give tzinfo=None even if self.tzinfo is set
            tzinfo = self.tzinfo
        k = timestamp
        if tzinfo:
            k = (timestamp, repr(tzinfo))
        try:
            return TIMESTAMP_TO_DT_CACHE[k]
        except KeyError:
            pass
        if OVERFLOW32B_MODE:
            # degraded mode to workaround Y2038
            # see https://github.com/python/cpython/issues/101069
            result = EPOCH.replace(tzinfo=None) + datetime.timedelta(seconds=timestamp)
        else:
            result = datetime.datetime.fromtimestamp(timestamp, tz=tzutc()).replace(tzinfo=None)
        if tzinfo:
            result = result.replace(tzinfo=UTC_DT).astimezone(tzinfo)
        TIMESTAMP_TO_DT_CACHE[(result, repr(result.tzinfo))] = result
        return result

def get_autonomous_agent_prompt_with_context(
    agent_name: str = None,
    agent_description: str = None,
    available_tools: list = None,
) -> str:
    prompt = AUTONOMOUS_AGENT_SYSTEM_PROMPT

    if agent_name:
        prompt = prompt.replace(
            "You are an elite autonomous agent",
            f"You are {agent_name}, an elite autonomous agent",
        )

    if agent_description:
        prompt += f"\n\n## AGENT ROLE\n{agent_description}\n"

    if available_tools and len(available_tools) > 0:
