        prompt += (
            "\nUse these tools effectively to complete your tasks.\n"
        )

    return prompt

def labels_to_stc(
    labels, values, tmin=0, tstep=1, subject=None, src=None, verbose=None
):
    values = np.array(values, float)
    if values.ndim == 1:
        values = values[:, np.newaxis]
    if values.ndim != 2:
        raise ValueError(f"values must have 1 or 2 dimensions, got {values.ndim}")
    _validate_type(src, (SourceSpaces, None))
    if src is None:
        data, vertices, subject = _labels_to_stc_surf(
            labels, values, tmin, tstep, subject
        )
        klass = SourceEstimate
    else:
        kind = src.kind
        subject = _check_subject(
            src._subject, subject, first_kind="source space subject", raise_error=False
        )
        _check_option("source space kind", kind, ("surface", "volume"))
        if kind == "volume":
            klass = VolSourceEstimate
        else:
            klass = SourceEstimate
        # Easiest way is to get a dot-able operator and use it
        vertices = [s["vertno"].copy() for s in src]
        stc = klass(np.eye(sum(len(v) for v in vertices)), vertices, 0, 1, subject)
        label_op = extract_label_time_course(
            stc, labels, src=src, mode="mean", allow_empty=True
        )
        _check_values_labels(values, label_op.shape[0])
        rev_op = np.zeros(label_op.shape[::-1])
        rev_op[np.arange(label_op.shape[1]), np.argmax(label_op, axis=0)] = 1.0
        data = rev_op @ values
    return klass(data, vertices, tmin, tstep, subject, verbose=verbose)

def provide_defaults(
    data_name: str, params: list[dict[str:ParamName, str : ParamArg | ParamVal]]
) -> list[dict[str:ParamName, str : ParamArg | ParamVal]]:
    param_names = [param["name"] for param in params]
    if data_name == "qchem":
        if "basis" not in param_names:
            params.append({"default": True, "name": "basis"})
        if "bondlength" not in param_names:
            params.append({"default": True, "name": "bondlength"})

    if data_name == "qspin":
        if "periodicity" not in param_names:
            params.append({"default": True, "name": "periodicity"})
        if "lattice" not in param_names:
            params.append({"default": True, "name": "lattice"})
        if "layout" not in param_names:
            params.append({"default": True, "name": "layout"})

    return params

def materialize_tensors(self) -> dict[str, list[torch.Tensor]]:
        collected_tensors = {}
        for key in list(self.collected_tensors.keys()):
            # Remove from internal attribute
            tensors = self.collected_tensors.pop(key)
            # Async loading
            if isinstance(tensors[0], Future):
                tensors = [future.result() for future in tensors if future.result() is not None]
            # Sync loading
            elif callable(tensors[0]):
                tensors = [func() for func in tensors]
            # Add them to the new dictionary
            collected_tensors[key] = tensors

        return collected_tensors

def countdown_reward_fn(task_info: dict, action: str | Action) -> RewardOutput:
    try:
        if isinstance(action, Action):
            action = action.action

        # Extract basic info
        target = task_info.get("target")
        nums = task_info.get("nums", [])

        if target is None or not nums:
            return RewardOutput(reward=0.0, is_correct=False, metadata={"error": "Missing target or nums"})

        # Prepare ground_truth in the format expected by compute_score
        ground_truth = {"target": target, "numbers": nums}

        # Use the compute_score function to evaluate the solution
        score = compute_score(action, ground_truth)

        # Convert score to RewardOutput
        if score >= 1.0:
            return RewardOutput(reward=1.0, is_correct=True, metadata={"validation": "correct_solution"})
        elif score > 0.0:
            return RewardOutput(reward=0, is_correct=False, metadata={"validation": "partial_credit"})
        else:
            return RewardOutput(reward=0.0, is_correct=False, metadata={"validation": "incorrect_solution"})

    except Exception as e:
        return RewardOutput(reward=0.0, is_correct=False, metadata={"error": str(e)})

def from_2d_array_to_nested(
    X, index=None, columns=None, time_index=None, cells_as_numpy=False
):
    if (time_index is not None) and cells_as_numpy:
        raise ValueError(
            "`Time_index` cannot be specified when `return_arrays` is True, "
            "time index can only be set to "
            "pandas Series"
        )
    if isinstance(X, pd.DataFrame):
        X = X.to_numpy()

    container = np.array if cells_as_numpy else pd.Series

    # for 2d numpy array, rows represent instances, columns represent time points
    n_instances, n_timepoints = X.shape

    if time_index is None:
        time_index = np.arange(n_timepoints)
    kwargs = {"index": time_index}

    Xt = pd.DataFrame(
        pd.Series([container(X[i, :], **kwargs) for i in range(n_instances)])
    )
    if index is not None:
        Xt.index = index
    if columns is not None:
        Xt.columns = columns
    return Xt

def validate_parameter_constraints(parameter_constraints, params, caller_name):
    for param_name, param_val in params.items():
        # We allow parameters to not have a constraint so that third party estimators
        # can inherit from sklearn estimators without having to necessarily use the
        # validation tools.
        if param_name not in parameter_constraints:
            continue

        constraints = parameter_constraints[param_name]

        if constraints == "no_validation":
            continue

        constraints = [make_constraint(constraint) for constraint in constraints]

        for constraint in constraints:
            if constraint.is_satisfied_by(param_val):
                # this constraint is satisfied, no need to check further.
                break
        else:
            # No constraint is satisfied, raise with an informative message.

            # Ignore constraints that we don't want to expose in the error message,
            # i.e. options that are for internal purpose or not officially supported.
            constraints = [
                constraint for constraint in constraints if not constraint.hidden
            ]

            if len(constraints) == 1:
                constraints_str = f"{constraints[0]}"
            else:
                constraints_str = (
                    f"{', '.join([str(c) for c in constraints[:-1]])} or"
                    f" {constraints[-1]}"
                )

            raise InvalidParameterError(
                f"The {param_name!r} parameter of {caller_name} must be"
                f" {constraints_str}. Got {param_val!r} instead."
            )

def metric_results_to_df(results: dict, dataset: VisionData) -> pd.DataFrame:
    result_list = []
    for metric, scores in results.items():
        if isinstance(scores, Number):
            result_list.append([metric, pd.NA, pd.NA, scores])
        elif len(scores) == 1:
            result_list.append([metric, pd.NA, pd.NA, scores[0]])
        elif isinstance(scores, (torch.Tensor, list, np.ndarray, dict)):
            # Deepchecks scorers returns classification class scores as dict but object detection as array TODO: unify
            scores_iterator = scores.items() if isinstance(scores, dict) else enumerate(scores)
            for class_id, class_score in scores_iterator:
                class_name = dataset.label_map[class_id]
                # The data might contain fewer classes than the model was trained on. filtering out
                # any class id which is not presented in the data.
                if np.isnan(class_score) or class_name not in dataset.get_observed_classes() or class_score == -1:
                    continue
                result_list.append([metric, class_id, class_name, class_score])
        else:
            raise DeepchecksValueError(f'The metric {metric} returned a '
                                       f'{type(scores)} instead of an array/tensor')

    return pd.DataFrame(result_list, columns=['Metric', 'Class', 'Class Name', 'Value'])

def infer_label_column_type_by_problem_type(
    column_types: Dict,
    label_columns: Union[str, List[str]],
    problem_type: Optional[str],
    data: Optional[pd.DataFrame] = None,
    valid_data: Optional[pd.DataFrame] = None,
    allowable_label_types: Optional[List[str]] = (
        CATEGORICAL,
        NUMERICAL,
        NER_ANNOTATION,
        ROIS,
        SEMANTIC_SEGMENTATION_GT,
    ),
    fallback_label_type: Optional[str] = CATEGORICAL,
):
    if label_columns is None:
        return column_types

    if isinstance(label_columns, str):
        label_columns = [label_columns]

    for col_name in label_columns:
        # For zero-shot inference, label column is unnecessary
        if col_name not in column_types:
            continue
        if data is not None:
            check_missing_values(data=data, column_name=col_name, split="training")
        if valid_data is not None:
            check_missing_values(data=valid_data, column_name=col_name, split="validation")
        if column_types[col_name] == NULL:
            raise ValueError(
                f"Label column '{col_name}' contains only one label class. Make sure it has at least two label classes."
            )
        if problem_type in [MULTICLASS, BINARY, CLASSIFICATION]:
            column_types[col_name] = CATEGORICAL
        elif problem_type == REGRESSION:
            column_types[col_name] = NUMERICAL
        elif problem_type == NER:
            column_types[col_name] = NER_ANNOTATION
        elif problem_type == OBJECT_DETECTION:
            column_types[col_name] = ROIS
        elif problem_type == SEMANTIC_SEGMENTATION:
            column_types[col_name] = SEMANTIC_SEGMENTATION_GT

        if column_types[col_name] not in allowable_label_types:
            column_types[col_name] = fallback_label_type

    return column_types

def logits_to_probabilities(
        self,
        raw_logits: np.ndarray | torch.Tensor,
        *,
        softmax_temperature: float | None = None,
        average_before_softmax: bool | None = None,
        balance_probabilities: bool | None = None,
    ) -> torch.Tensor:
        raw_logits = (
            raw_logits
            if isinstance(raw_logits, torch.Tensor)
            else torch.from_numpy(np.asarray(raw_logits))
        )
        used_temperature = (
            softmax_temperature
            if softmax_temperature is not None
            else getattr(self, "softmax_temperature_", self.softmax_temperature)
        )
        use_average_before_softmax = (
            self.average_before_softmax
            if average_before_softmax is None
            else average_before_softmax
        )
        use_balance = (
            self.balance_probabilities
            if balance_probabilities is None
            else balance_probabilities
        )

        steps: list[Callable[[torch.Tensor], torch.Tensor]] = []

        if used_temperature != 1.0:

            def apply_temp(t: torch.Tensor) -> torch.Tensor:
                return t / used_temperature

            steps.append(apply_temp)

        if raw_logits.ndim >= 3:
            if use_average_before_softmax:
                steps.append(self._average_across_estimators)
                steps.append(self._apply_softmax)
            else:
                steps.append(self._apply_softmax)
                steps.append(self._average_across_estimators)
        elif raw_logits.ndim == 2:
            steps.append(self._apply_softmax)
        else:
            raise ValueError(
                f"Expected logits with 2 or more dims, got {raw_logits.ndim}"
            )

        if use_balance:
            steps.append(self._apply_balancing)

        output = raw_logits
        for fn in steps:
            output = fn(output)

        return output

def forward(self, pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        if not (pred.shape[2:] == target.shape[2:] and pred.size(0) == target.size(0) and target.size(1) == 1):
            raise ValueError(
                "Prediction and target need to be of same size, and target should not be one-hot."
                f"Got {pred.shape} and {target.shape}."
            )

        if pred.size(1) < target.max().item():
            raise ValueError("Invalid target value.")

        out = torch.stack(
            [
                self.perform_erosion(
                    pred[:, i : i + 1],
                    torch.where(
                        target == i,
                        torch.tensor(1, device=target.device, dtype=target.dtype),
                        torch.tensor(0, device=target.device, dtype=target.dtype),
                    ),
                )
                for i in range(pred.size(1))
            ]
        )

        if self.reduction == "mean":
            out = out.mean()
        elif self.reduction == "sum":
            out = out.sum()
        elif self.reduction == "none":
            pass
        else:
            raise NotImplementedError(f"reduction `{self.reduction}` has not been implemented yet.")

        return out

def gridsearch(Classifier, documents=[], folds=10, **kwargs):
    def product(*args):
        # Yields the cartesian product of given iterables:
        # list(product([1, 2], [3, 4])) => [(1, 3), (1, 4), (2, 3), (2, 4)]
        p = [[]]
        for iterable in args:
            p = [x + [y] for x in p for y in iterable]
        for p in p:
            yield tuple(p)
    s = [] # [((A, P, R, F, o), parameters), ...]
    p = [] # [[("c", 0.1), ("c", 10), ...],
           #  [("gamma", 0.1), ("gamma", 0.2), ...], ...]
    for k, v in kwargs.items():
        p.append([(k, v) for v in v])
    for p in product(*p):
        p = dict(p)
        s.append((K_fold_cross_validation(Classifier, documents, folds, **p), p))
    return sorted(s, reverse=True)

def flush_memory(flush_compile: bool = True) -> None:
    gc.collect()
    # If needed, flush everything related to torch.compile
    if flush_compile:
        # Dynamo resets
        torch._dynamo.reset()
        torch._dynamo.reset_code_caches()
        if hasattr(torch._inductor, "codecache"):
            # Clear FX graph cache
            if hasattr(torch._inductor.codecache, "FxGraphCache"):
                torch._inductor.codecache.FxGraphCache.clear()
            # Clear PyCodeCache
            if hasattr(torch._inductor.codecache, "PyCodeCache"):
                torch._inductor.codecache.PyCodeCache.cache_clear()
            # Clear TritonFuture cache (for async compilation)
            if hasattr(torch._inductor.codecache, "TritonFuture"):
                if hasattr(torch._inductor.codecache.TritonFuture, "_compile_cache"):
                    torch._inductor.codecache.TritonFuture._compile_cache.clear()
    # Clear device cache
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
        torch.cuda.synchronize()
    elif is_torch_xpu_available():
        torch.xpu.empty_cache()
        torch.xpu.synchronize()
    gc.collect()

def add_noindex_to_estimator_stubs(app, docname, source):
    if not docname.startswith("code/api/"):
        return

    content = source[0]
    # Update the regex to match either ops or templates
    if not re.search(r"\bpennylane\.estimator\.(ops|templates)\b", content):
        return

    def _add_noindex_func(match):
        """Replacement function for re.sub to add :noindex: idempotently."""
        directive_block = match.group(0)
        if ":noindex:" in directive_block:
            return directive_block
        return f"{match.group(1)}\n   :noindex:{match.group(2)}"

    # TODO [sc-99226]: Replace with :no-index-entry: when support for sphinx >=8.2 is available.
    new_content, num_subs = re.subn(
        r"(^\s*\.\.\s+auto(?:class|function|method)::.*?)(\n\s*($|\S.*))",
        _add_noindex_func,
        content,
        flags=re.MULTILINE | re.DOTALL,
    )

    if num_subs:
        source[0] = new_content
        logger.info(f"[add_noindex] Patched {docname} with :noindex: directive.")

def get_covar_weights(self, covar_input=None) -> torch.Tensor:
        if self.config_lagged_regressors is not None and self.config_lagged_regressors.regressors is not None:
            # Accumulate the lags of the covariates
            covar_splits = np.add.accumulate(
                [covar.n_lags for _, covar in self.config_lagged_regressors.regressors.items()][:-1]
            ).tolist()
            # If actual covariates are provided, use them to compute the attributions
            if covar_input is not None:
                covar_input = torch.cat([covar for _, covar in covar_input.items()], axis=1)
            # Calculate the attributions w.r.t. the inputs
            if self.config_lagged_regressors.layers == []:
                attributions = self.covar_net[0].weight
            else:
                attributions = interprete_model(self, "covar_net", "forward_covar_net", covar_input)
            # Split the attributions into the different covariates
            attributions_split = torch.tensor_split(
                attributions,
                covar_splits,
                axis=1,
            )
            # Combine attributions and covariate name
            covar_attributions = dict(zip(self.config_lagged_regressors.regressors.keys(), attributions_split))
        else:
            covar_attributions = None
        return covar_attributions

def format_multiannotator_labels(labels: LabelLike) -> Tuple[pd.DataFrame, dict]:
    if isinstance(labels, pd.DataFrame):
        np_labels = labels.values
    elif isinstance(labels, np.ndarray):
        np_labels = labels
    else:
        raise TypeError("labels must be 2D numpy array or pandas DataFrame")

    unique_labels = pd.unique(np_labels.ravel())

    try:
        unique_labels = unique_labels[~np.isnan(unique_labels)]
        unique_labels.sort()
    except TypeError:  # np.unique / np.sort cannot handle string values or pd.NA types
        nan_mask = np.array([(l is np.nan) or (l is pd.NA) or (l == "nan") for l in unique_labels])
        unique_labels = unique_labels[~nan_mask]
        unique_labels.sort()

    # convert float labels (that arose because np.nan is float type) to int
    if unique_labels.dtype == "float":
        unique_labels = unique_labels.astype("int")

    label_map = {label: i for i, label in enumerate(unique_labels)}
    inverse_map = {i: label for label, i in label_map.items()}

    if isinstance(labels, np.ndarray):
        labels = pd.DataFrame(labels)

    formatted_labels = labels.replace(label_map)

    return formatted_labels, inverse_map

def load_image(img_data: Union[bytes, IO[Any], str]) -> Image.Image:
    if isinstance(img_data, str):
        with open(img_data, "rb") as file:
            img_data = file.read()
    elif hasattr(img_data, "read"):
        # Check if it's file-like object.
        img_data = img_data.read()

    # remove iCCP chunk if found
    img_data = remove_iccp_chunk(img_data)

    # Try to preload the image bytes with channels unchanged to determine
    # if the image has an alpha channel. If it does we should add a white
    # background to it using PIL.
    has_alpha = False
    try:
        image_preload = tsr.imdecode_py(img_data, -1)  # -1 = IMREAD_UNCHANGED
        if image_preload is not None and len(image_preload.shape) >= 3 and image_preload.shape[2] == 4:
            has_alpha = True
        del image_preload
    except Exception:
        # If trainingsample fails, we'll use PIL fallback regardless
        pass

    img = None
    if not has_alpha:
        try:
            img = decode_image_with_trainingsample(img_data)
        except Exception:
            # If trainingsample fails, fall back to PIL
            pass
    if img is None:
        img = decode_image_with_pil(img_data)
    return img

def median_filter(x: torch.Tensor, filter_width: int):
    pad_width = filter_width // 2
    if x.shape[-1] <= pad_width:
        # F.pad requires the padding width to be smaller than the input dimension
        return x

    if (ndim := x.ndim) <= 2:
        # `F.pad` does not support 1D or 2D inputs for reflect padding but supports 3D and 4D
        x = x[None, None, :]

    assert (
        filter_width > 0 and filter_width % 2 == 1
    ), "`filter_width` should be an odd number"

    result = None
    x = F.pad(x, (filter_width // 2, filter_width // 2, 0, 0), mode="reflect")
    if x.is_cuda:
        try:
            from .triton_ops import median_filter_cuda

            result = median_filter_cuda(x, filter_width)
        except (RuntimeError, subprocess.CalledProcessError):
            warnings.warn(
                "Failed to launch Triton kernels, likely due to missing CUDA toolkit; "
                "falling back to a slower median kernel implementation..."
            )

    if result is None:
        # sort() is faster than torch.median (https://github.com/pytorch/pytorch/issues/51450)
        result = x.unfold(-1, filter_width, 1).sort()[0][..., filter_width // 2]

    if ndim <= 2:
        result = result[0, 0]

    return result

def json2space(in_x, name=NodeType.ROOT):
    out_y = copy.deepcopy(in_x)
    if isinstance(in_x, dict):
        if NodeType.TYPE in in_x.keys():
            _type = in_x[NodeType.TYPE]
            name = name + '-' + _type
            _value = json2space(in_x[NodeType.VALUE], name=name)
            if _type == 'choice':
                out_y = hp.hp.choice(name, _value)
            elif _type == 'randint':
                out_y = hp.hp.randint(name, _value[1] - _value[0])
            else:
                if _type in ['loguniform', 'qloguniform']:
                    _value[:2] = np.log(_value[:2])
                out_y = getattr(hp.hp, _type)(name, *_value)
        else:
            out_y = dict()
            for key in in_x.keys():
                out_y[key] = json2space(in_x[key], name + '[%s]' % str(key))
    elif isinstance(in_x, list):
        out_y = list()
        for i, x_i in enumerate(in_x):
            if isinstance(x_i, dict):
                if NodeType.NAME not in x_i.keys():
                    raise RuntimeError(
                        '\'_name\' key is not found in this nested search space.'
                    )
            out_y.append(json2space(x_i, name + '[%d]' % i))
    return out_y

def finalize_response(
    request, finished, decode_buffer, tokenizer, parts, stats, finish_reason
):
    responses = []

    # Send the remaining text buffers
    for sample_id in range(request.num_samples):
        responses.extend(
            send_reset_buffer(sample_id, decode_buffer, tokenizer, parts, request)
        )

    # Calculate the final stats
    stats["total_time"] = (time.time() - stats["start_time"]) * 1000
    stats["total_tokens"] = stats["tokens_count"]

    # If streaming, send the final chunks for each sample
    if request.streaming:
        for sample_id in range(request.num_samples):
            if finished[sample_id]:
                continue
            responses.append(
                ServeStreamResponse(
                    finish_reason=finish_reason, stats=stats, sample_id=sample_id
                )
            )
    else:
        # If not streaming, send the full messages for each sample
        full_messages = [
            ServeMessage(role="assistant", parts=parts[i])
            for i in range(request.num_samples)
        ]
        responses.append(
            ServeResponse(
                messages=full_messages,
                finish_reason=finish_reason,
                stats=stats,
            )
        )

    return responses

