        print("Opening in browser:", url)

def augment(imgs, hflip=True, rotation=True, vflip=False):
    hflip = hflip and random.random() < 0.5
    if vflip or rotation:
        vflip = random.random() < 0.5
    rot90 = rotation and random.random() < 0.5

    def _augment(img):
        if hflip:  # horizontal
            img = img[:, ::-1, :].copy()
        if vflip:  # vertical
            img = img[::-1, :, :].copy()
        if rot90:
            img = img.transpose(1, 0, 2)
        return img

    if not isinstance(imgs, list):
        imgs = [imgs]
    imgs = [_augment(img) for img in imgs]
    if len(imgs) == 1:
        imgs = imgs[0]

    return imgs

def lookup_codec(encoding):
        import codecs

        if isinstance(encoding, codecs.CodecInfo):
            return encoding
        encoding = encoding.lower()
        import codecs

        if helpers.always_use_custom_codecs:
            # Try custom utf32 first, then standard python codecs
            cdk = utf32.lookup(encoding)
            if not cdk:
                try:
                    cdk = codecs.lookup(encoding)
                except LookupError:
                    cdk = None
        else:
            # Try standard python codecs first, then custom utf32
            try:
                cdk = codecs.lookup(encoding)
            except LookupError:
                cdk = utf32.lookup(encoding)
        return cdk

def validate_and_accept(self):
        title = self.title_input.text().strip()
        if not title:
            QMessageBox.warning(
                self,
                self.tr("Warning"),
                self.tr("Component title cannot be empty!"),
            )
            return

        if hasattr(self.parent_dialog, "check_duplicate_title"):
            original_title = (
                self.edit_data["title"] if self.edit_data else None
            )
            if self.parent_dialog.check_duplicate_title(title, original_title):
                QMessageBox.warning(
                    self,
                    self.tr("Warning"),
                    self.tr("Component title already exists!"),
                )
                return

        comp_type = self.type_combo.currentText()
        if comp_type != "QLineEdit":
            options_text = self.options_input.toPlainText().strip()
            if not options_text:
                QMessageBox.warning(
                    self,
                    self.tr("Warning"),
                    self.tr(
                        "Options cannot be empty for this component type!"
                    ),
                )
                return

            options = [
                opt.strip() for opt in options_text.split("\n") if opt.strip()
            ]
            if len(options) != len(set(options)):
                QMessageBox.warning(
                    self,
                    self.tr("Warning"),
                    self.tr("Duplicate options are not allowed!"),
                )
                return

        self.accept()

async def update_organization(
    org_id: int,
    request: UpdateOrgRequest,
    user=Depends(require_permission("org.edit")),
):
    require_org_access(user, org_id)

    from ..services.cloud.container import get_user_store

    user_store = get_user_store()

    org = await user_store.get_organization(org_id)
    if not org:
        raise HTTPException(404, "Organization not found")

    # Build update dict
    updates = {}
    if request.name is not None:
        updates["name"] = request.name
    if request.description is not None:
        updates["description"] = request.description
    if request.is_active is not None:
        updates["is_active"] = 1 if request.is_active else 0
