def iter_source(source: Any, vid_stride: int = 1) -> Iterator[tuple[str, np.ndarray]]:
    if isinstance(source, np.ndarray):
        yield "", source
        return

    if isinstance(source, (list, tuple)):
        for item in source:
            yield from iter_source(item, vid_stride=vid_stride)
        return

    if isinstance(source, (str, Path)):
        source_str = str(source)

        if "://" in source_str:
            yield from _yield_video(source_str, vid_stride=vid_stride)
            return

        if any(ch in source_str for ch in "*?[]"):
            for match in sorted(glob(source_str)):
                yield from iter_source(match, vid_stride=vid_stride)
            return

        path = Path(source_str)
        if path.is_file():
            suffix = path.suffix.lower()
            if suffix in IMAGE_EXTS:
                yield from _yield_image(path)
                return
            if suffix in MANIFEST_EXTS:
                yield from _yield_manifest(path, vid_stride=vid_stride)
                return
            yield from _yield_video(str(path), vid_stride=vid_stride)
            return

        if path.is_dir():
            yield from _yield_directory(path, vid_stride=vid_stride)
            return

        try:
            cam_id = int(source_str)
        except ValueError:
            LOGGER.error(f"Could not open source: {source}")
            return

        yield from _yield_video(cam_id, vid_stride=vid_stride, label=str(cam_id))
        return

    try:
        cam_id = int(source)
    except (TypeError, ValueError):
        LOGGER.error(f"Could not open source: {source}")
        return

    yield from _yield_video(cam_id, vid_stride=vid_stride, label=str(cam_id))

def rename_source_key(
    source_key: str,
    weight_renamings: list[WeightRenaming],
    weight_converters: list[WeightConverter],
    prefix: str | None = None,
    meta_state_dict: dict | None = None,
) -> tuple[str, str | None]:
    renamed_key = source_key
    # 1. apply all renamings in turns (if multiple match, it's the responsibility of the mappings to make sure they
    # are coherent)
    for renaming in weight_renamings:
        renamed_key, _ = renaming.rename_source_key(renamed_key)

    # 2. apply renaming through weight conversions on the key if we have any WeightConverter (here we stop after
    # the first match, as we assume only 1 converter can match any source key)
    source_pattern = None
    for converter in weight_converters:
        renamed_key, source_pattern = converter.rename_source_key(renamed_key)
        if source_pattern is not None:
            break

    # 3. check if we need to add or remove prefix if necessary (only during loading, not saving)
    if prefix is not None and meta_state_dict is not None:
        if (
            renamed_key.startswith(prefix)
            and meta_state_dict.get(re.sub(f"^{prefix}.", "", renamed_key, count=1)) is not None
        ):
            renamed_key = re.sub(f"^{prefix}.", "", renamed_key, count=1)
        elif meta_state_dict.get(f"{prefix}.{renamed_key}") is not None:
            renamed_key = f"{prefix}.{renamed_key}"

    return renamed_key, source_pattern

def concat(docs):
    if len(docs) == 1:
        return docs[0]
    if len(docs) == 0:
        raise ValueError("concat() expects at least one object!")

    types = {d.__class__ for d in docs}

    # If they're all strings, use string concatenation.
    if all(isinstance(doc, str) for doc in docs):
        return "".join(docs)

    # If they're all corpus views, then use ConcatenatedCorpusView.
    for typ in types:
        if not issubclass(typ, (StreamBackedCorpusView, ConcatenatedCorpusView)):
            break
    else:
        return ConcatenatedCorpusView(docs)

    # If they're all lazy sequences, use a lazy concatenation
    for typ in types:
        if not issubclass(typ, AbstractLazySequence):
            break
    else:
        return LazyConcatenation(docs)

    # Otherwise, see what we can do:
    if len(types) == 1:
        typ = list(types)[0]

        if issubclass(typ, list):
            return reduce((lambda a, b: a + b), docs, [])

        if issubclass(typ, tuple):
            return reduce((lambda a, b: a + b), docs, ())

        if ElementTree.iselement(typ):
            xmltree = ElementTree.Element("documents")
            for doc in docs:
                xmltree.append(doc)
            return xmltree

    # No method found!
    raise ValueError("Don't know how to concatenate types: %r" % types)

