        else:
            main_module_name = revel.input(
                prompt="What is the name of the main module?",
                default=main_module_name,
            )

        return RioProjectConfig.create(
            project_directory / "rio.toml",
            main_module=main_module_name,
            project_type="website",
        )

def collect_required_tool_servers(
    tasks: list[Task], run_configs: dict[str, TaskRunConfig]
) -> set[str]:
    server_ids: set[str] = set()

    for task in tasks:
        run_config = run_configs.get(task.id)  # type: ignore
        if not run_config:
            continue

        tools = get_tools_from_run_config(run_config)
        for tool_id in tools:
            tool_type = classify_tool_id(tool_id)

            if tool_type == "kiln_task":
                server_id = kiln_task_server_id_from_tool_id(tool_id)
                server_ids.add(server_id)
            elif tool_type in ("mcp_remote", "mcp_local"):
                server_id, _ = mcp_server_and_tool_name_from_id(tool_id)
                server_ids.add(server_id)

    return server_ids

def get_top_experiments_id_metrics_pair(
        self,
        top_k: int,
        all_metrics: bool = False,
        only_completed: bool = False,
    ) -> Sequence[Union[str, dict]]:
        additional_filters = dict(page_size=int(top_k), page=0)
        if only_completed:
            additional_filters["status"] = ["completed"]

        # noinspection PyProtectedMember
        top_tasks_ids_metric = self._get_child_tasks_ids(
            parent_task_id=self._job_parent_id or self._base_task_id,
            order_by=self._objective_metric._get_last_metrics_encode_field()[0],
            additional_filters=additional_filters,
            additional_fields=["last_metrics"],
        )

        title_series = self._objective_metric.get_objective_metric() if not all_metrics else (None, None)
        titles = [ts[0] for ts in title_series]
        series = [ts[1] for ts in title_series]
        return [
            (
                i,
                {
                    "{}/{}".format(v["metric"], v["variant"]): v
                    for variant in metric.values()
                    for v in variant.values()
                    if all_metrics or (v["metric"] in titles and v["variant"] in series)
                },
            )
            for i, metric in top_tasks_ids_metric
        ]

def estimator_spec_train(self, loss, num_async_replicas=1, use_tpu=False):
    train_op = self.optimize(loss, num_async_replicas=num_async_replicas,
                             use_tpu=use_tpu)

    if use_tpu:
      if self._hparams.warm_start_from:
        def scaffold_fn():
          self.initialize_from_ckpt(self._hparams.warm_start_from)
          return tf.train.Scaffold()
      else:
        scaffold_fn = None

      # Note: important to call this before remove_summaries()
      if self.hparams.tpu_enable_host_call:
        host_call = self.create_train_host_call()
      else:
        host_call = None

      remove_summaries()

      return contrib.tpu().TPUEstimatorSpec(
          tf_estimator.ModeKeys.TRAIN,
          loss=loss,
          train_op=train_op,
          host_call=host_call,
          scaffold_fn=scaffold_fn)
    else:
      if self._hparams.warm_start_from:
        self.initialize_from_ckpt(self._hparams.warm_start_from)

      # When loading weights from a pre-trained model, you want to be able to
      # load separate weights into the encoder and decoder.
      if self._hparams.warm_start_from_second:
        self.initialize_from_ckpt(self._hparams.warm_start_from_second)

      return tf_estimator.EstimatorSpec(
          tf_estimator.ModeKeys.TRAIN, loss=loss, train_op=train_op)

def validate_model_compatibility(self, teacher, student):
        if (
            self.teacher_layer_name is not None
            or self.student_layer_name is not None
        ):
            teacher_is_subclassed = (
                not hasattr(teacher, "inputs") or teacher.inputs is None
            )
            student_is_subclassed = (
                not hasattr(student, "inputs") or student.inputs is None
            )

            if teacher_is_subclassed or student_is_subclassed:
                subclassed_models = []
                if teacher_is_subclassed:
                    subclassed_models.append("teacher")
                if student_is_subclassed:
                    subclassed_models.append("student")

                models_str = " and ".join(subclassed_models)
                raise ValueError(
                    f"FeatureDistillation with specific layer names requires "
                    f"Functional or Sequential models. The {models_str} "
                    f"model(s) appear to be subclassed (no symbolic "
                    f"inputs/outputs). Either use Functional/Sequential "
                    f"models, or use FeatureDistillation without layer names "
                    f"(to distill final outputs only), or use "
                    f"LogitsDistillation instead."
                )

        if self.teacher_layer_name is not None:
            try:
                teacher.get_layer(name=self.teacher_layer_name)
            except ValueError as e:
                raise ValueError(f"In teacher model: {e}")

        if self.student_layer_name is not None:
            try:
                student.get_layer(name=self.student_layer_name)
            except ValueError as e:
                raise ValueError(f"In student model: {e}")

def get_scope_info(self) -> Tuple[List[str], List[str]]:
        def _trim_scopename_for_weight(scope_names: List[str]) -> List[str]:
            weight_name = scope_names[-1]
            if scope_names[:-1] != weight_name.split(".")[:-1]:
                return scope_names
            scope_names[-1] = weight_name.split(".")[-1]
            return scope_names

        if self.model_hierarchy == "" or self.model_hierarchy is None:
            scopes = []
        else:
            scopes = self.model_hierarchy.split(".")
        scope_names, scope_types = [], []
        for val in scopes:
            if val == "":
                scope_names.append("UNKNOWN_SCOPE_NAME")
                scope_types.append("UNKNOWN_SCOPE_TYPE")
                continue
            if val.count("(") != 1 or val.count(")") != 1:
                raise ValueError(f"{val} is not a valid model hierarchy string.")
            lower_idx, upper_idx = val.index("("), val.index(")")
            scope_names.append(val[:lower_idx])
            scope_types.append(val[lower_idx + 1 : upper_idx])
        scope_names.append(self.name)
        scope_types.append(self.kind)
        if self.kind == "getattr":
            scope_names = _trim_scopename_for_weight(scope_names)
        return scope_names, scope_types

def get_imports(filename: str | os.PathLike) -> list[str]:
    with open(filename, encoding="utf-8") as f:
        content = f.read()
    imported_modules = set()

    import transformers.utils

    def recursive_look_for_imports(node):
        if isinstance(node, ast.Try):
            return  # Don't recurse into Try blocks and ignore imports in them
        elif isinstance(node, ast.If):
            test = node.test
            for condition_node in ast.walk(test):
                if isinstance(condition_node, ast.Call):
                    check_function = getattr(condition_node.func, "id", "")
                    if (
                        check_function.endswith("available")
                        and check_function.startswith("is_flash_attn")
                        or hasattr(transformers.utils.import_utils, check_function)
                    ):
                        # Don't recurse into "if flash_attn_available()" or any "if library_available" blocks
                        # that appears in `transformers.utils.import_utils` and ignore imports in them
                        return
        elif isinstance(node, ast.Import):
            # Handle 'import x' statements
            for alias in node.names:
                top_module = alias.name.split(".")[0]
                if top_module:
                    imported_modules.add(top_module)
        elif isinstance(node, ast.ImportFrom):
            # Handle 'from x import y' statements, ignoring relative imports
            if node.level == 0 and node.module:
                top_module = node.module.split(".")[0]
                if top_module:
                    imported_modules.add(top_module)

        # Recursively visit all children
        for child in ast.iter_child_nodes(node):
            recursive_look_for_imports(child)

    tree = ast.parse(content)
    recursive_look_for_imports(tree)

    return sorted(imported_modules)

def compute_sparsity_compact2origin(origin_model: Module, compact_model: Module, config_list: List[Dict]) -> List[Dict]:
    compact2origin_sparsity = []
    for config in config_list:
        left_weight_num = 0
        total_weight_num = 0
        for module_name, module in origin_model.named_modules():
            module_type = type(module).__name__
            if 'op_types' in config and module_type not in config['op_types']:
                continue
            if 'op_names' in config and module_name not in config['op_names']:
                continue
            total_weight_num += module.weight.data.numel()  # type: ignore
        for module_name, module in compact_model.named_modules():
            module_type = type(module).__name__
            if 'op_types' in config and module_type not in config['op_types']:
                continue
            if 'op_names' in config and module_name not in config['op_names']:
                continue
            left_weight_num += module.weight.data.numel()  # type: ignore
        compact2origin_sparsity.append(deepcopy(config))
        compact2origin_sparsity[-1]['total_sparsity'] = 1 - left_weight_num / total_weight_num
    return compact2origin_sparsity

def get_ghstack_dependent_prs(
    repo: GitRepo, pr: GitHubPR, only_closed: bool = True
) -> List[Tuple[str, GitHubPR]]:
    assert pr.is_ghstack_pr()
    orig_ref = f"{repo.remote}/{pr.get_ghstack_orig_ref()}"
    rev_list = repo.revlist(f"{pr.default_branch()}..{orig_ref}")
    if len(rev_list) == 0:
        raise RuntimeError(
            f"PR {pr.pr_num} does not have any revisions associated with it"
        )
    skip_len = len(rev_list) - 1
    for branch in repo.branches_containing_ref(orig_ref):
        candidate = repo.revlist(f"{pr.default_branch()}..{branch}")
        # Pick longest candidate
        if len(candidate) > len(rev_list):
            candidate, rev_list = rev_list, candidate
        # Validate that candidate always ends rev-list
        if rev_list[-len(candidate) :] != candidate:
            raise RuntimeError(
                f"Branch {branch} revlist {', '.join(candidate)} is not a subset of {', '.join(rev_list)}"
            )
    # Remove commits original PR depends on
    if skip_len > 0:
        rev_list = rev_list[:-skip_len]
    rc: List[Tuple[str, GitHubPR]] = []
    for pr_, sha in _revlist_to_prs(repo, pr, rev_list):
        if not pr_.is_closed():
            if not only_closed:
                rc.append(("", pr_))
            continue
        commit_sha = get_pr_commit_sha(repo, pr_)
        rc.append((commit_sha, pr_))
    return rc

def skip_comment(self, state):
        buf = state.buf
        uniws = self.options.unicode_whitespace
        s = buf.peekstr(2)
        if s != "//" and s != "/*":
            return None
        state.push_cond(
            self.options.comments, "Comments are not allowed in strict JSON"
        )
        start_position = buf.position
        buf.skip(2)
        multiline = s == "/*"
        saw_close = False
        while not buf.at_end:
            if multiline:
                if buf.peekstr(2) == "*/":
                    buf.skip(2)
                    saw_close = True
                    break
                elif buf.peekstr(2) == "/*":
                    state.push_error(
                        "Multiline /* */ comments may not nest",
                        outer_position=start_position,
                        context="Comment",
                    )
            else:
                if buf.at_eol(uniws):
                    buf.skip_to_next_line(uniws)
                    saw_close = True
                    break
            buf.pop()

        if not saw_close and multiline:
            state.push_error(
                "Comment was never terminated",
                outer_position=start_position,
                context="Comment",
            )
        state.stats.num_comments += 1

def run_sequence(seq: Sequence, tracker: Tracker, debug=False, visdom_info=None):
    def _results_exist():
        if seq.dataset == 'oxuva':
            vid_id, obj_id = seq.name.split('_')[:2]
            pred_file = os.path.join(tracker.results_dir, '{}_{}.csv'.format(vid_id, obj_id))
            return os.path.isfile(pred_file)
        elif seq.object_ids is None:
            bbox_file = '{}/{}.txt'.format(tracker.results_dir, seq.name)
            return os.path.isfile(bbox_file)
        else:
            bbox_files = ['{}/{}_{}.txt'.format(tracker.results_dir, seq.name, obj_id) for obj_id in seq.object_ids]
            missing = [not os.path.isfile(f) for f in bbox_files]
            return sum(missing) == 0

    visdom_info = {} if visdom_info is None else visdom_info

    if _results_exist() and not debug:
        print('FPS: {}'.format(-1))
        return

    print('Tracker: {} {} {} ,  Sequence: {}'.format(tracker.name, tracker.parameter_name, tracker.run_id, seq.name))

    if debug:
        output = tracker.run_sequence(seq, debug=debug, visdom_info=visdom_info)
    else:
        try:
            output = tracker.run_sequence(seq, debug=debug, visdom_info=visdom_info)
        except Exception as e:
            print(e)
            return

    sys.stdout.flush()

    if isinstance(output['time'][0], (dict, OrderedDict)):
        exec_time = sum([sum(times.values()) for times in output['time']])
        num_frames = len(output['time'])
    else:
        exec_time = sum(output['time'])
        num_frames = len(output['time'])

    print('FPS: {}'.format(num_frames / exec_time))

    if not debug:
        if seq.dataset == 'oxuva':
            _save_tracker_output_oxuva(seq, tracker, output)
        else:
            _save_tracker_output(seq, tracker, output)

def resolve_pos(orth, tag, next_tag):
    # Some tokens have their UD tag decided based on the POS of the following
    # token.

    # apply orth based mapping
    if tag in TAG_ORTH_MAP:
        orth_map = TAG_ORTH_MAP[tag]
        if orth in orth_map:
            return orth_map[orth], None  # current_pos, next_pos

    # apply tag bi-gram mapping
    if next_tag:
        tag_bigram = tag, next_tag
        if tag_bigram in TAG_BIGRAM_MAP:
            current_pos, next_pos = TAG_BIGRAM_MAP[tag_bigram]
            if current_pos is None:  # apply tag uni-gram mapping for current_pos
                return (
                    TAG_MAP[tag][POS],
                    next_pos,
                )  # only next_pos is identified by tag bi-gram mapping
            else:
                return current_pos, next_pos

    # apply tag uni-gram mapping
    return TAG_MAP[tag][POS], None

def concat(data_list: Union[SingleData], axis=0) -> MultiData:
    if axis == 0:
        raise NotImplementedError(f"please implement this func when axis == 0")
    elif axis == 1:
        # get all index and row
        all_index = set()
        for index_data in data_list:
            all_index = all_index | set(index_data.index)
        all_index = list(all_index)
        all_index.sort()
        all_index_map = dict(zip(all_index, range(len(all_index))))

        # concat all
        tmp_data = np.full((len(all_index), len(data_list)), np.nan)
        for data_id, index_data in enumerate(data_list):
            assert isinstance(index_data, SingleData)
            now_data_map = [all_index_map[index] for index in index_data.index]
            tmp_data[now_data_map, data_id] = index_data.data
        return MultiData(tmp_data, all_index)
    else:
        raise ValueError(f"axis must be 0 or 1")

def fit(self, X, y=None):
        feature_names = []
        vocab = {}

        for x in X:
            for f, v in x.items():
                if isinstance(v, str):
                    feature_name = "%s%s%s" % (f, self.separator, v)
                elif isinstance(v, Number) or (v is None):
                    feature_name = f
                elif isinstance(v, Mapping):
                    raise TypeError(
                        f"Unsupported value type {type(v)} "
                        f"for {f}: {v}.\n"
                        "Mapping objects are not supported."
                    )
                elif isinstance(v, Iterable):
                    feature_name = None
                    self._add_iterable_element(f, v, feature_names, vocab)

                if feature_name is not None:
                    if feature_name not in vocab:
                        vocab[feature_name] = len(feature_names)
                        feature_names.append(feature_name)

        if self.sort:
            feature_names.sort()
            vocab = {f: i for i, f in enumerate(feature_names)}

        self.feature_names_ = feature_names
        self.vocabulary_ = vocab

        return self

def find_matching_model_files(check_all: bool = False):
    module_diff_files = None
    if not check_all:
        module_diff_files = set()
        repo = Repo(PATH_TO_REPO)
        # Diff from index to unstaged files
        for modified_file_diff in repo.index.diff(None):
            if modified_file_diff.a_path.startswith("src/transformers"):
                module_diff_files.add(os.path.join(PATH_TO_REPO, modified_file_diff.a_path))
        # Diff from index to `main`
        for modified_file_diff in repo.index.diff(repo.refs.main.commit):
            if modified_file_diff.a_path.startswith("src/transformers"):
                module_diff_files.add(os.path.join(PATH_TO_REPO, modified_file_diff.a_path))
        # quick escape route: if there are no module files in the diff, skip this check
        if len(module_diff_files) == 0:
            return None

    modeling_glob_pattern = os.path.join(PATH_TO_TRANSFORMERS, "models/**/modeling_**")
    potential_files = glob.glob(modeling_glob_pattern)
    image_processing_glob_pattern = os.path.join(PATH_TO_TRANSFORMERS, "models/**/image_processing_*_fast.py")
    potential_files += glob.glob(image_processing_glob_pattern)
    processing_glob_pattern = os.path.join(PATH_TO_TRANSFORMERS, "models/**/processing_*.py")
    potential_files += glob.glob(processing_glob_pattern)
    configuration_glob_pattern = os.path.join(PATH_TO_TRANSFORMERS, "models/**/configuration_*.py")
    potential_files += glob.glob(configuration_glob_pattern)
    matching_files = []
    for file_path in potential_files:
        if os.path.isfile(file_path):
            matching_files.append(file_path)
    if not check_all:
        # intersect with module_diff_files
        matching_files = sorted([file for file in matching_files if file in module_diff_files])

    return matching_files

def load_from_yaml(self, filename: str):
        if filename is not None and os.path.exists(filename):
            try:
                with open(filename, "r", encoding="utf-8") as f:
                    data = yaml.safe_load(f)

                # Load metadata
                metadata = data.get("metadata", {})
                # Update all metadata attributes
                for key, value in metadata.items():
                    if hasattr(self, key):
                        setattr(self, key, value)

                # Load conversation history
                self.conversation_history = data.get(
                    "conversation_history", []
                )
                self._str_cache = None

                logger.info(
                    f"Successfully loaded conversation from {filename}"
                )
            except Exception as e:
                logger.error(
                    f"Failed to load conversation: {str(e)}\nTraceback: {traceback.format_exc()}"
                )
                raise

def format(self, record: logging.LogRecord) -> str:
        # Base log entry
        log_entry: Dict[str, Any] = {}

        # Timestamp
        if self.timestamp_format == "unix":
            log_entry["timestamp"] = record.created
        else:
            log_entry["timestamp"] = datetime.fromtimestamp(record.created, tz=timezone.utc).isoformat()

        # Standard fields
        log_entry["level"] = record.levelname
        log_entry["logger"] = record.name
        log_entry["message"] = record.getMessage()

        # Correlation ID from thread-local storage
        correlation_id = get_correlation_id()
        if correlation_id:
            log_entry["correlation_id"] = correlation_id

        # Source location
        log_entry["source"] = {
            "file": record.filename,
            "line": record.lineno,
            "function": record.funcName,
        }

        # Exception info
        if record.exc_info:
            log_entry["exception"] = self.formatException(record.exc_info)

        # Stack info
        if self.include_stack_info and record.stack_info:
            log_entry["stack_info"] = record.stack_info

        # Extra fields from the record
        if self.include_extra:
            extra = {}
            for key, value in record.__dict__.items():
                if key not in logging.LogRecord.__dict__ and key not in self.STANDARD_FIELDS and not key.startswith("_"):
                    # Try to serialize the value
                    try:
                        json.dumps(value)
                        extra[key] = value
                    except (TypeError, ValueError):
                        extra[key] = str(value)

            if extra:
                log_entry["extra"] = extra

        return json.dumps(log_entry, default=str)

def build_one_token_sequence_from_text(
        self,
        text: Dict[str, str],
        is_training: bool,
    ) -> Dict:
        # tokenize text
        tokens = {}
        warnings.filterwarnings("ignore", "Token indices sequence length is longer than.*result in indexing errors")

        if self.template_config.turn_on:
            template, applied_template = self.template_engine.sample_and_apply_template(text)
            if template:
                answer_choices = template.get_answer_choices_list(text)
                text = {}
                text[TEXT_TOKEN_IDS] = applied_template[0]
                text[CHOICES_IDS] = answer_choices

        for col_name, col_text in text.items():
            if is_training:
                if self.dropout > 0 and random.uniform(0, 1) <= self.dropout:
                    col_text = ""
                elif self.train_augmenter is not None:
                    # naive way to detect categorical/numerical text:
                    if len(col_text.split(" ")) >= self.text_detection_length:
                        col_text = self.train_augmenter(col_text)
                        # After text augmentation, "col_text" may become a list. An error will be raised when calling "tokenizer.encode".
                        if type(col_text) == list and len(col_text) == 1:
                            col_text = col_text[0]

            if col_name == CHOICES_IDS:
                answer_ids = self.tokenizer(
                    col_text,
                    padding="max_length",
                    max_length=self.template_engine.get_max_choice_length(self.tokenizer),
                )["input_ids"]
                tokens[col_name] = answer_ids
                continue
            col_tokens = self.tokenizer.encode(
                col_text,
                add_special_tokens=False,
                truncation=False,
            )
            tokens[col_name] = np.array(col_tokens, dtype=np.int32)
        # build token sequence
        return self.build_one_token_sequence(tokens)

def process_multilabel_components(
    outputs: torch.Tensor, targets: torch.Tensor, weights: Optional[torch.Tensor] = None
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor, int]:
    if not torch.is_tensor(outputs):
        outputs = torch.from_numpy(outputs)
    if not torch.is_tensor(targets):
        targets = torch.from_numpy(targets)
    if weights is not None:
        if not torch.is_tensor(weights):
            weights = torch.from_numpy(weights)
        weights = weights.squeeze()

    if outputs.dim() == 1:
        outputs = outputs.view(-1, 1)
    else:
        assert outputs.dim() == 2, (
            "wrong `outputs` size " "(should be 1D or 2D with one column per class)"
        )

    if targets.dim() == 1:
        if outputs.shape[1] > 1:
            # multiclass case
            num_classes = outputs.shape[1]
            targets = F.one_hot(targets, num_classes).float()
        else:
            # binary case
            num_classes = 2
            targets = targets.view(-1, 1)
    else:
        assert targets.dim() == 2, (
            "wrong `targets` size " "(should be 1D or 2D with one column per class)"
        )
        num_classes = outputs.shape[-1]

    if weights is not None:
        assert weights.dim() == 1, "Weights dimension should be 1"
        assert weights.numel() == targets.size(
            0
        ), "Weights dimension 1 should be the same as that of target"
        assert torch.min(weights) >= 0, "Weight should be non-negative only"

    assert torch.equal(targets ** 2, targets), "targets should be binary (0 or 1)"

    return outputs, targets, weights, num_classes

def get_cudnn_version(run_lambda):
    if get_platform() == "win32":
        system_root = os.environ.get("SYSTEMROOT", "C:\\Windows")
        cuda_path = os.environ.get("CUDA_PATH", "%CUDA_PATH%")
        where_cmd = os.path.join(system_root, "System32", "where")
        cudnn_cmd = '{} /R "{}\\bin" cudnn*.dll'.format(where_cmd, cuda_path)
    elif get_platform() == "darwin":
        # CUDA libraries and drivers can be found in /usr/local/cuda/. See
        # https://docs.nvidia.com/cuda/archive/10.1/cuda-installation-guide-mac-os-x/index.html#3.2-Install
        # Use CUDNN_LIBRARY when cudnn library is installed elsewhere.
        cudnn_cmd = "ls /usr/local/cuda/lib/libcudnn*"
    else:
        cudnn_cmd = 'ldconfig -p | grep libcudnn | rev | cut -d" " -f1 | rev'
    rc, out, _ = run_lambda(cudnn_cmd)
    # find will return 1 if there are permission errors or if not found
    if len(out) == 0 or (rc != 1 and rc != 0):
        cudnn_lib = os.environ.get("CUDNN_LIBRARY")
        if cudnn_lib is not None and os.path.isfile(cudnn_lib):
            return os.path.realpath(cudnn_lib)
        return None
    files_set = set()
    for fn in out.split("\n"):
        fn = os.path.realpath(fn)  # eliminate symbolic links
        if os.path.isfile(fn):
            files_set.add(fn)
    if not files_set:
        return None
    # Alphabetize the result because the order is non-deterministic otherwise
    files = sorted(files_set)
    if len(files) == 1:
        return files[0]
    result = "\n".join(files)
    return "Probably one of the following:\n{}".format(result)

def verb_t2(self, token):
        if len(token) > 6:
            for s2 in self.pl_si2:
                # ^Siin Taa
                if token.startswith(self.verb_pr2[0]) and token.endswith(s2):
                    return token[2:-2]
            # ^Siin Yaa, Alif Noon$
            if token.startswith(self.verb_pr2[1]) and token.endswith(self.pl_si2[0]):
                return token[2:-2]
            # ^Siin Yaa, Waaw Noon$
            if token.startswith(self.verb_pr2[1]) and token.endswith(self.pl_si2[2]):
                return token[2:-2]
        # ^Siin Taa, Noon$
        if (
            len(token) > 5
            and token.startswith(self.verb_pr2[0])
            and token.endswith("\u0646")
        ):
            return token[2:-1]
        # ^Siin Yaa, Noon$
        if (
            len(token) > 5
            and token.startswith(self.verb_pr2[1])
            and token.endswith("\u0646")
        ):
            return token[2:-1]

def compute(self, metrics: Union[str, list] = None, k: Optional[int] = 10):
        if isinstance(metrics, str):
            metrics = [metrics]
        if not metrics:  # no metric is provided
            metrics = self.supported_metrics.keys()

        return_res = {}

        eval_res = np.mean(
            [list(self._compute_one(idx, k)) for idx in self.results.keys()],
            axis=0,
        )

        for metric in metrics:
            metric = metric.lower()
            if metric in self.supported_metrics:
                return_res.update({f"{metric}@{k}": eval_res[self.supported_metrics[metric]]})

        return return_res

def fit_transform(self, raw_documents, y=None):
        # We intentionally don't call the transform method to make
        # fit_transform overridable without unwanted side effects in
        # TfidfVectorizer.
        if isinstance(raw_documents, str):
            raise ValueError(
                "Iterable over raw text documents expected, string object received."
            )

        self._validate_ngram_range()
        self._warn_for_unused_params()
        self._validate_vocabulary()
        max_df = self.max_df
        min_df = self.min_df
        max_features = self.max_features

        if self.fixed_vocabulary_ and self.lowercase:
            for term in self.vocabulary:
                if any(map(str.isupper, term)):
                    warnings.warn(
                        "Upper case characters found in"
                        " vocabulary while 'lowercase'"
                        " is True. These entries will not"
                        " be matched with any documents"
                    )
                    break

        vocabulary, X = self._count_vocab(raw_documents, self.fixed_vocabulary_)

        if self.binary:
            X.data.fill(1)

        if not self.fixed_vocabulary_:
            n_doc = X.shape[0]
            max_doc_count = max_df if isinstance(max_df, Integral) else max_df * n_doc
            min_doc_count = min_df if isinstance(min_df, Integral) else min_df * n_doc
            if max_doc_count < min_doc_count:
                raise ValueError("max_df corresponds to < documents than min_df")
            if max_features is not None:
                X = self._sort_features(X, vocabulary)
            X = self._limit_features(
                X, vocabulary, max_doc_count, min_doc_count, max_features
            )
            if max_features is None:
                X = self._sort_features(X, vocabulary)
            self.vocabulary_ = vocabulary

        return _align_api_if_sparse(X)

def transform_trajectory_groups_to_datums(
    trajectory_groups: list[TrajectoryGroup],
    algorithm_config: AlgorithmConfig,
) -> tuple[list[tinker.Datum] | dict[str, list[tinker.Datum]], dict]:
    # step 1: compute advantages (skip if already pre-computed by buffer)
    has_advantages = any(step.advantage is not None for group in trajectory_groups for traj in group.trajectories for step in traj.steps)
    if has_advantages:
        adv_metrics = {}
    else:
        adv_metrics = collect_reward_and_advantage_from_trajectory_groups(trajectory_groups, algorithm_config)

    if algorithm_config.estimator_map:
        datums_dict = defaultdict(list)
    else:
        datums = []

    # step 2: iterate over all steps and build the Tinker Datum objects
    seqs_per_traj = []
    seq_lengths = []
    for group in trajectory_groups:
        for trajectory in group.trajectories:
            traj_datums = trajectory_to_datums(trajectory, router_replay=algorithm_config.router_replay)
            seqs_per_traj.append(len(traj_datums))
            for d in traj_datums:
                seq_lengths.append(d.model_input.length)
            if algorithm_config.estimator_map:
                datums_dict[group.group_role].extend(traj_datums)
            else:
                datums.extend(traj_datums)

    if seqs_per_traj:
        import numpy as _np

        adv_metrics["batch/seqs_per_traj/mean"] = _np.mean(seqs_per_traj)
        adv_metrics["batch/seqs_per_traj/min"] = _np.min(seqs_per_traj)
        adv_metrics["batch/seqs_per_traj/max"] = _np.max(seqs_per_traj)
        adv_metrics["batch/seq_length/mean"] = _np.mean(seq_lengths)
        adv_metrics["batch/seq_length/min"] = _np.min(seq_lengths)
        adv_metrics["batch/seq_length/max"] = _np.max(seq_lengths)

    return (datums if not algorithm_config.estimator_map else datums_dict), adv_metrics

def extract_input_shapes_from_graph(
    module: GraphModule,
) -> dict[int, tuple[int, ...]]:
    input_shapes: dict[int, tuple[int, ...]] = {}
    idx = 0
    for node in module.graph.nodes:
        if node.op == "placeholder":
            # Get the tensor_meta from the node if available
            if "val" in node.meta:
                val = node.meta["val"]
                if isinstance(val, torch.Tensor):
                    input_shapes[idx] = tuple(val.shape)
                elif hasattr(val, "shape"):
                    input_shapes[idx] = tuple(val.shape)
            idx += 1
    return input_shapes

def suggest_commands(token: str, candidates: Iterable[str]) -> list[str]:
    lowered = _lower_map(candidates)
    if not lowered:
        return []

    token_lower = token.lower()
    if token_lower in lowered:
        return [lowered[token_lower]]

    close = get_close_matches(
        token_lower,
        list(lowered.keys()),
        n=3,
        cutoff=0.6,
    )
    if close:
        return [lowered[item] for item in close]

    ranked = sorted(
        (
            (edit_distance(token_lower, key), value)
            for key, value in lowered.items()
        ),
        key=lambda item: (item[0], item[1]),
    )
    if not ranked:
        return []

    min_distance = ranked[0][0]
    if min_distance > 2:
        return []

    closest_values = [
        value for distance, value in ranked if distance == min_distance
    ]
    return closest_values[:3]

def unwrap_data_objects(rec):
    # Return early if we got here with a list of strings, no denesting required
    if not isinstance(rec, dict):
        return rec

    for k, v in rec.items():  # pylint: disable=invalid-name
        if k == "data" and 'object' in rec and rec['object'] == 'list':
            if isinstance(v, dict):
                return unwrap_data_objects(v)
            if isinstance(v, list):
                return [unwrap_data_objects(o) for o in v]
            return v
        if isinstance(v, dict):
            rec[k] = unwrap_data_objects(v)
        if isinstance(v, list):
            rec[k] = [unwrap_data_objects(o) for o in rec[k]]
    return rec

def get_schedule_with_warmup_and_decay(
    config: LRSchedulerConfig,
    optimizer: Optimizer,
    step_info: StepInfo,
) -> LambdaLR:
    decay = config.decay

    # OneCycleLR manages warmup and decay internally - skip the SequentialLR wrapper.
    if decay == "one_cycle":
        if step_info.num_warmup_steps > 0:
            logger.warning(
                "decay='one_cycle' includes its own warmup phase controlled by `pct_start`. "
                "The `warmup_fraction`/`warmup_evaluations` settings will be ignored."
            )
        return init_one_cycle(config, optimizer, step_info)

    # WSD manages its own warmup internally via wsd_warmup_fraction.
    if decay == "wsd" and step_info.num_warmup_steps > 0:
        logger.warning(
            "decay='wsd' includes its own warmup phase controlled by `wsd_warmup_fraction`. "
            "The external `warmup_fraction`/`warmup_evaluations` settings will be ignored for WSD."
        )

    schedulers = []

    # Warmup scheduler.
    if step_info.num_warmup_steps > 0 and decay != "wsd":
        warmup_scheduler = LambdaLR(
            optimizer,
            lambda current_step: float(current_step) / float(max(1, step_info.num_warmup_steps)),
        )
        schedulers.append(warmup_scheduler)

    # Decay scheduler.
    decay_scheduler = decay_registry[decay](config, optimizer, step_info)
    schedulers.append(decay_scheduler)

    if len(schedulers) == 1:
        # Only one scheduler, so no need to wrap in a SequentialLR.
        return schedulers[0]

    # Return a SequentialLR that applies the warmup and decay schedulers in order
    # with the warmup scheduler only applied for the first num_warmup_steps steps.
    return SequentialLR(optimizer, schedulers=schedulers, milestones=[step_info.num_warmup_steps])

def load_model(filepath, custom_objects=None, compile=True, safe_mode=True):
    if isinstance(filepath, io.IOBase):
        return _load_model_from_fileobj(
            filepath, custom_objects, compile, safe_mode
        )
    elif str(filepath).startswith("hf://"):
        if huggingface_hub is None:
            raise ImportError(
                "To load models from the Hugging Face Hub, "
                "you must install the `huggingface_hub` package."
            )

        repo_id = filepath[5:]
        folder_path = huggingface_hub.snapshot_download(
            repo_id=repo_id,
            library_name="keras",
            library_version=keras_version,
        )
        return _load_model_from_dir(
            folder_path, custom_objects, compile, safe_mode
        )
    else:
        filepath = str(filepath)
        if not filepath.endswith(".keras"):
            is_keras_dir = file_utils.isdir(filepath) and file_utils.exists(
                file_utils.join(filepath, "config.json")
            )
            if is_keras_dir:
                return _load_model_from_dir(
                    filepath, custom_objects, compile, safe_mode
                )
            raise ValueError(
                "Invalid filename: expected a `.keras` extension. "
                f"Received: filepath={filepath}"
            )
        with open(filepath, "rb") as f:
            return _load_model_from_fileobj(
                f, custom_objects, compile, safe_mode
            )

def recall_at_k(
        self,
        query: str,
        retrieved_context_chunks: List[str],
        relevance_scores: Optional[List[float]] = None,
        k: Optional[int] = None,
    ) -> float:
        ground_truth_context_chunks = (
            self._find_golden_context_chunks_and_scores(query)
        )
        if ground_truth_context_chunks:
            k = k or len(retrieved_context_chunks)

            # Extract ground truth chunks
            golden_chunks = set(
                chunk[0] for chunk in ground_truth_context_chunks
            )

            # Sort retrieved chunks by relevance scores if scores are provided
            if relevance_scores:
                # Get the top-k threshold score (with tie handling)
                sorted_scores = sorted(relevance_scores, reverse=True)
                kth_score = sorted_scores[min(k - 1, len(sorted_scores) - 1)]

                # Include all indices with scores >= kth score
                top_k_indices = [
                    i
                    for i, score in enumerate(relevance_scores)
                    if score >= kth_score
                ]
                retrieved_top_k = [
                    retrieved_context_chunks[i] for i in top_k_indices
                ]
            else:
                # If no relevance scores, use the top-k retrieved chunks as they are
                retrieved_top_k = retrieved_context_chunks[:k]

            # Calculate recall at k with tie handling
            relevant_retrieved = len([
                chunk for chunk in retrieved_top_k if chunk in golden_chunks
            ])
            return (
                relevant_retrieved / len(golden_chunks)
                if len(golden_chunks) > 0
                else 0.0
            )
        else:
            return np.nan

def decode_example(self, value: dict, token_per_repo_id=None) -> "PIL.Image.Image":
        if not self.decode:
            raise RuntimeError("Decoding is disabled for this feature. Please use Image(decode=True) instead.")

        if config.PIL_AVAILABLE:
            import PIL.Image
            import PIL.ImageOps
        else:
            raise ImportError("To support decoding images, please install 'Pillow'.")

        if token_per_repo_id is None:
            token_per_repo_id = {}

        path, bytes_ = value["path"], value["bytes"]
        if bytes_ is None:
            if path is None:
                raise ValueError(f"An image should have one of 'path' or 'bytes' but both are None in {value}.")
            else:
                if is_local_path(path):
                    image = PIL.Image.open(path)
                else:
                    source_url = path.split("::")[-1]
                    pattern = (
                        config.HUB_DATASETS_URL
                        if source_url.startswith(config.HF_ENDPOINT)
                        else config.HUB_DATASETS_HFFS_URL
                    )
                    source_url_fields = string_to_dict(source_url, pattern)
                    token = (
                        token_per_repo_id.get(source_url_fields["repo_id"]) if source_url_fields is not None else None
                    )
                    download_config = DownloadConfig(token=token)
                    with xopen(path, "rb", download_config=download_config) as f:
                        bytes_ = BytesIO(f.read())
                    image = PIL.Image.open(bytes_)
        else:
            image = PIL.Image.open(BytesIO(bytes_))
        image.load()  # to avoid "Too many open files" errors
        if image.getexif().get(PIL.Image.ExifTags.Base.Orientation) is not None:
            image = PIL.ImageOps.exif_transpose(image)
        if self.mode and self.mode != image.mode:
            image = image.convert(self.mode)
        return image

def build_charlm_vocab(path, cutoff=0):
    counter = Counter()
    if os.path.isdir(path):
        filenames = sorted(os.listdir(path))
    else:
        filenames = [os.path.split(path)[1]]
        path = os.path.split(path)[0]

    for filename in filenames:
        filename = os.path.join(path, filename)
        with open_read_text(filename) as fin:
            for line in fin:
                counter.update(list(line))

    if len(counter) == 0:
        raise ValueError("Training data was empty!")
    # remove infrequent characters from vocab
    for k in list(counter.keys()):
        if counter[k] < cutoff:
            del counter[k]
    # a singleton list of all characters
    data = [sorted([x[0] for x in counter.most_common()])]
    if len(data[0]) == 0:
        raise ValueError("All characters in the training data were less frequent than --cutoff!")
    vocab = CharVocab(data) # skip cutoff argument because this has been dealt with
    return vocab

def image(
    src: ImageLike,
    alt: str | None = None,
    width: int | str | None = None,
    height: int | str | None = None,
    rounded: bool = False,
    style: dict[str, Any] | None = None,
    caption: str | None = None,
    vmin: float | None = None,
    vmax: float | None = None,
) -> Html:
    # Convert to virtual file
    resolved_src: str | None
    src = _normalize_image(src, vmin=vmin, vmax=vmax)
    # TODO: Consider downsampling here. This is something matplotlib does
    # implicitly, and can potentially remove the bottle-neck of very large
    # images.
    if isinstance(src, (io.BufferedReader, io.BytesIO)):
        src.seek(0)
        resolved_src = mo_data.image(src.read()).url
    elif isinstance(src, bytes):
        resolved_src = mo_data.image(src).url
    elif isinstance(src, Path):
        resolved_src = mo_data.image(src.read_bytes(), ext=src.suffix).url
    elif isinstance(src, str) and os.path.isfile(
        expanded_path := os.path.expanduser(src)
    ):
        src = Path(expanded_path)
        resolved_src = mo_data.image(src.read_bytes(), ext=src.suffix).url
    else:
        resolved_src = io_to_data_url(src, fallback_mime_type="image/png")

    styles = create_style(
        {
            "width": normalize_dimension(width),
            "height": normalize_dimension(height),
            "border-radius": "4px" if rounded else None,
            **(style or {}),
        }
    )
    img = h.img(src=resolved_src, alt=alt, style=styles)
    if caption is not None:
        return Html(
            h.figure(
                [
                    img,
                    h.figcaption(
                        [caption],
                        style="color: var(--muted-foreground); "
                        "text-align: center; margin-top: 0.5rem;",
                    ),
                ],
                style="display: flex; flex-direction: column;",
            )
        )
    return Html(img)

def Json(obj: _InputType) -> _OutputType:
  if (
      isinstance(obj, str)
      or isinstance(obj, int)
      or isinstance(obj, float)
      or isinstance(obj, bool)
  ):
    return json.dumps(obj)
  if isinstance(obj, placeholders.Placeholder):
    if isinstance(obj, placeholders.ConcatPlaceholder) or isinstance(
        obj, placeholders.IfPresentPlaceholder
    ):
      return obj
    if isinstance(obj, placeholders.InputValuePlaceholder):
      # pylint: disable-next=protected-access
      if obj._ir_type != 'STRING':
        return obj
    # For string placeholders.
    return _SmartConcatList(['"', obj, '"']).Build()
  if isinstance(obj, list):
    return _SmartConcatList(['[', Concat(*obj), ']']).Build()
  if isinstance(obj, dict):
    concat_list = _SmartConcatList(['{'])
    is_first_item = True
    for key, value in obj.items():
      concat_list.Append(_DictEntry(key, value, is_first_item))
      is_first_item = False
    concat_list.Append('}')
    return concat_list.Build()
  raise ValueError(
      f'{obj} of type {type(obj)} is not supported by Json. Only Python'
      ' primitive types, lists, dicts, and kfp placeholders are supported.'
  )

def partial_fit(self, X, y, classes=None, sample_weight=None, **partial_fit_params):
        _raise_for_params(partial_fit_params, self, "partial_fit")

        first_time = not hasattr(self, "estimators_")

        y = validate_data(self, X="no_validation", y=y, multi_output=True)

        if y.ndim == 1:
            raise ValueError(
                "y must have at least two dimensions for "
                "multi-output regression but has only one."
            )

        if _routing_enabled():
            if sample_weight is not None:
                partial_fit_params["sample_weight"] = sample_weight
            routed_params = process_routing(
                self,
                "partial_fit",
                **partial_fit_params,
            )
        else:
            if sample_weight is not None and not has_fit_parameter(
                self.estimator, "sample_weight"
            ):
                raise ValueError(
                    "Underlying estimator does not support sample weights."
                )

            if sample_weight is not None:
                routed_params = Bunch(
                    estimator=Bunch(partial_fit=Bunch(sample_weight=sample_weight))
                )
            else:
                routed_params = Bunch(estimator=Bunch(partial_fit=Bunch()))

        self.estimators_ = Parallel(n_jobs=self.n_jobs)(
            delayed(_partial_fit_estimator)(
                self.estimators_[i] if not first_time else self.estimator,
                X,
                y[:, i],
                classes[i] if classes is not None else None,
                partial_fit_params=routed_params.estimator.partial_fit,
                first_time=first_time,
            )
            for i in range(y.shape[1])
        )

        if first_time and hasattr(self.estimators_[0], "n_features_in_"):
            self.n_features_in_ = self.estimators_[0].n_features_in_
        if first_time and hasattr(self.estimators_[0], "feature_names_in_"):
            self.feature_names_in_ = self.estimators_[0].feature_names_in_

        return self

def random_method(decorated: Callable[..., T]) -> Callable[..., T]:
    # check that @random_method has been applied to a method.
    if not _is_method(decorated):
        raise_log(ValueError("@random_method can only be used on methods."), logger)

    @wraps(decorated)
    def decorator(self, *args, **kwargs) -> T:
        store_instance = False
        random_instance = None
        if "random_state" in kwargs.keys() and kwargs["random_state"] is not None:
            # get random state from model constructor or `predict()`
            random_instance = check_random_state(kwargs["random_state"])
            if not hasattr(self, "_random_instance"):
                # store random instance when called from model constructor
                store_instance = True
        elif not hasattr(self, "_random_instance"):
            # get random state for first time from other method
            store_instance = True
            random_instance = check_random_state(
                np.random.randint(0, high=MAX_NUMPY_SEED_VALUE)
            )

        # if no random instance is provided, use the one stored in the class
        if random_instance is None:
            random_instance = self._random_instance

        if store_instance:
            self._random_instance = random_instance

        # handle the randomness
        with fork_rng():
            manual_seed(random_instance.randint(0, high=MAX_TORCH_SEED_VALUE))
            return decorated(self, *args, **kwargs)

    return decorator

def inject_adaptation_to_linear_layer(
    model: nn.Module,
    peft: str,
    lora_r: int = None,
    lora_alpha: int = None,
    filter: Optional[List[str]] = None,
    module_filter: Optional[List[str]] = None,
    extra_trainable_params: Optional[List[str]] = None,
    **kwargs,
) -> nn.Module:
    for m_name, module in dict(model.named_modules()).items():
        if extra_trainable_params and any(re.match(filter_layer, m_name) for filter_layer in extra_trainable_params):
            continue
        if hasattr(model, "frozen_layers") and any(
            re.search(filter_layer, m_name) for filter_layer in model.frozen_layers
        ):
            continue
        if not module_filter or any(re.match(filter_module, m_name) for filter_module in module_filter):
            for c_name, layer in dict(module.named_children()).items():
                if not filter or any(re.match(filter_layer, c_name) for filter_layer in filter):
                    assert isinstance(layer, nn.Linear), (
                        f"LoRA can only be applied to torch.nn.Linear, but {layer} is {type(layer)}."
                    )
                    adaptation_layer = create_adaptation(peft, layer, lora_r, lora_alpha, **kwargs)
                    adaptation_layer.weight = layer.weight
                    adaptation_layer.bias = layer.bias
                    setattr(module, c_name, adaptation_layer)

    return model  # return model to enable method chaining

def parse_table_schema(json, precise_float: bool) -> DataFrame:
    table = ujson_loads(json, precise_float=precise_float)
    col_order = [field["name"] for field in table["schema"]["fields"]]
    df = DataFrame(table["data"], columns=col_order)[col_order]

    dtypes = {
        field["name"]: convert_json_field_to_pandas_type(field)
        for field in table["schema"]["fields"]
    }

    # No ISO constructor for Timedelta as of yet, so need to raise
    if "timedelta64" in dtypes.values():
        raise NotImplementedError(
            'table="orient" can not yet read ISO-formatted Timedelta data'
        )

    with option_context("future.distinguish_nan_and_na", False):
        df = df.astype(dtypes)

    if "primaryKey" in table["schema"]:
        df = df.set_index(table["schema"]["primaryKey"])
        if len(df.index.names) == 1:
            if df.index.name == "index":
                df.index.name = None
        else:
            df.index.names = [
                None if x.startswith("level_") else x for x in df.index.names
            ]

    return df

def parse_setup() -> Tuple[PackagesType, PackagesType, Set[str], Set[str]]:
    essential_packages: PackagesType = {}
    test_packages: PackagesType = {}
    essential_duplicates: Set[str] = set()
    test_duplicates: Set[str] = set()

    with open("setup.py") as setup_file:
        contents = setup_file.read()

    # Parse out essential packages.
    match = re.search(
        r"""install_requires=\[[\s\n]*['"](.*?)['"],?[\s\n]*\]""", contents, re.DOTALL
    )
    if match is not None:
        package_string = match.groups()[0].strip()
        for package in re.split(r"""['"],[\s\n]+['"]""", package_string):
            module, version = parse_package(package)
            if module in essential_packages:
                essential_duplicates.add(module)
            else:
                essential_packages[module] = version

    # Parse packages only needed for testing.
    match = re.search(
        r"""tests_require=\[[\s\n]*['"](.*?)['"],?[\s\n]*\]""", contents, re.DOTALL
    )
    if match is not None:
        package_string = match.groups()[0].strip()
        for package in re.split(r"""['"],[\s\n]+['"]""", package_string):
            module, version = parse_package(package)
            if module in test_packages:
                test_duplicates.add(module)
            else:
                test_packages[module] = version

    return essential_packages, test_packages, essential_duplicates, test_duplicates

def jaccard(vec1, vec2):
    # converting from sparse for easier manipulation
    if scipy.sparse.issparse(vec1):
        vec1 = vec1.toarray()
    if scipy.sparse.issparse(vec2):
        vec2 = vec2.toarray()
    if isbow(vec1) and isbow(vec2):
        # if it's in bow format, we use the following definitions:
        # union = sum of the 'weights' of both the bags
        # intersection = lowest weight for a particular id; basically the number of common words or items
        union = sum(weight for id_, weight in vec1) + sum(weight for id_, weight in vec2)
        vec1, vec2 = dict(vec1), dict(vec2)
        intersection = 0.0
        for feature_id, feature_weight in vec1.items():
            intersection += min(feature_weight, vec2.get(feature_id, 0.0))
        return 1 - float(intersection) / float(union)
    else:
        # if it isn't in bag of words format, we can use sets to calculate intersection and union
        if isinstance(vec1, np.ndarray):
            vec1 = vec1.tolist()
        if isinstance(vec2, np.ndarray):
            vec2 = vec2.tolist()
        vec1 = set(vec1)
        vec2 = set(vec2)
        intersection = vec1 & vec2
        union = vec1 | vec2
        return 1 - float(len(intersection)) / float(len(union))

def transform(
        self,
        y: Iterable,
        return_norm: bool = False,
        target_scale=None,
        ignore_na: bool = False,
    ) -> torch.Tensor | np.ndarray:
        if self.add_nan:
            if self.warn:
                cond = np.array([item not in self.classes_ for item in y])
                if cond.any():
                    warnings.warn(
                        (
                            f"Found {np.unique(np.asarray(y)[cond]).size} "
                            "unknown classes which were set to NaN"
                        ),
                        UserWarning,
                    )

            encoded = [self.classes_.get(v, 0) for v in y]

        else:
            if ignore_na:
                na_fill_value = next(iter(self.classes_.values()))
                encoded = [self.classes_.get(v, na_fill_value) for v in y]
            else:
                try:
                    encoded = [self.classes_[v] for v in y]
                except KeyError as e:
                    raise KeyError(
                        f"Unknown category '{e.args[0]}' encountered. "
                        "Set `add_nan=True` to allow unknown categories"
                    )

        if isinstance(y, torch.Tensor):
            encoded = torch.tensor(encoded, dtype=torch.long, device=y.device)
        else:
            encoded = np.array(encoded)

        if return_norm:
            return encoded, self.get_parameters()
        else:
            return encoded

def validate_edges(self, edges):
        if edges.shape[-2:] != self.event_shape:
            raise ValueError("Invalid edges shape: {}".format(edges.shape))

        # Verify canonical ordering.
        if not ((0 <= edges) & (edges < self.num_vertices)).all():
            raise ValueError("Invalid vertex ids:\n{}".format(edges))
        if not (edges[..., 0] < edges[..., 1]).all():
            raise ValueError("Vertices are not sorted in each edge:\n{}".format(edges))
        if not (
            (edges[..., :-1, 1] < edges[..., 1:, 1])
            | (
                (edges[..., :-1, 1] == edges[..., 1:, 1])
                & (edges[..., :-1, 0] < edges[..., 1:, 0])
            )
        ).all():
            raise ValueError(
                "Edges are not sorted colexicographically:\n{}".format(edges)
            )

        # Verify tree property, i.e. connectivity.
        V = self.num_vertices
        for i in itertools.product(*map(range, edges.shape[:-2])):
            edges_i = edges[i]
            connected = torch.eye(V, dtype=torch.float)
            connected[edges_i[:, 0], edges_i[:, 1]] = 1
            connected[edges_i[:, 1], edges_i[:, 0]] = 1
            for i in range(int(math.ceil(V**0.5))):
                connected = connected.mm(connected).clamp_(max=1)
            if not connected.min() > 0:
                raise ValueError("Edges do not constitute a tree:\n{}".format(edges_i))

def set_seed(seed: int, deterministic: bool = False):
    random.seed(seed)
    np.random.seed(seed)
    if is_torch_available():
        torch.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)
        # ^^ safe to call this function even if cuda is not available
        if deterministic:
            torch.use_deterministic_algorithms(True)
    if is_torch_mlu_available():
        torch.mlu.manual_seed_all(seed)
    if is_torch_musa_available():
        torch.musa.manual_seed_all(seed)
    if is_torch_npu_available():
        torch.npu.manual_seed_all(seed)
    if is_torch_hpu_available():
        torch.hpu.manual_seed_all(seed)
    if is_torch_xpu_available():
        torch.xpu.manual_seed_all(seed)

def fetch_all_issues(owner: str, repo: str, states: list[str] | None = None) -> list[dict]:
    if states is None:
        states = ["OPEN"]
    all_issues = []
    cursor = None
    page = 1
    max_retries = 5
    label = "/".join(s.lower() for s in states)

    while True:
        for attempt in range(max_retries):
            try:
                print(f"Fetching {label} issues page {page}...", file=sys.stderr)
                data = gh_graphql(
                    GRAPHQL_QUERY,
                    {
                        "owner": owner,
                        "repo": repo,
                        "cursor": cursor,
                        "states": states,
                    },
                )
                break
            except RuntimeError as e:
                wait = min(2**attempt, 60)
                print(f"Error on attempt {attempt + 1}: {e}", file=sys.stderr)
                if attempt < max_retries - 1:
                    print(f"Retrying in {wait}s...", file=sys.stderr)
                    time.sleep(wait)
                else:
                    raise

        rate = data["data"]["rateLimit"]
        print(f"  Rate limit: {rate['remaining']} remaining, cost: {rate['cost']}", file=sys.stderr)

        if rate["remaining"] < 100:
            reset_at = datetime.fromisoformat(rate["resetAt"].replace("Z", "+00:00"))
            wait_seconds = (reset_at - datetime.now(timezone.utc)).total_seconds() + 5
            if wait_seconds > 0:
                print(f"  Rate limit low, waiting {wait_seconds:.0f}s until reset...", file=sys.stderr)
                time.sleep(wait_seconds)

        issues_data = data["data"]["repository"]["issues"]
        raw_issues = issues_data["nodes"]
        total = issues_data["totalCount"]

        for raw in raw_issues:
            all_issues.append(transform_issue(raw))

        print(f"  Fetched {len(all_issues)}/{total} issues", file=sys.stderr)

        page_info = issues_data["pageInfo"]
        if not page_info["hasNextPage"]:
            break

        cursor = page_info["endCursor"]
        page += 1

    return all_issues

def setup_environment_from_example(example_name: str) -> dict:
    env = os.environ.copy()
    env["ENV"] = f"examples/{example_name}"

    examples_dir = get_examples_dir()
    example_path = examples_dir / example_name

    if example_path.is_dir():
        if (example_path / "config.json").exists():
            env["CONFIG_BACKEND"] = "json"
            env["CONFIG_PATH"] = str(example_path / "config")
        elif (example_path / "config.toml").exists():
            env["CONFIG_BACKEND"] = "toml"
            env["CONFIG_PATH"] = str(example_path / "config")
        elif (example_path / "config.env").exists():
            env["CONFIG_BACKEND"] = "env"
            env["CONFIG_PATH"] = str(example_path / "config")
        else:
            raise ValueError(f"No config file found in example {example_name}")
    elif example_path.is_file():
        if example_path.suffix == ".json":
            env["CONFIG_BACKEND"] = "json"
            env["CONFIG_PATH"] = str(example_path.with_suffix(""))
        elif example_path.suffix == ".toml":
            env["CONFIG_BACKEND"] = "toml"
            env["CONFIG_PATH"] = str(example_path.with_suffix(""))
        else:
            raise ValueError(f"Unsupported config file type: {example_path.suffix}")
    else:
        raise ValueError(f"Example {example_name} not found")

    if "TQDM_NCOLS" not in env:
        env["TQDM_NCOLS"] = "125"
    if "TQDM_LEAVE" not in env:
        env["TQDM_LEAVE"] = "false"

    env["TOKENIZERS_PARALLELISM"] = "false"

    platform = os.uname().sysname
    env["PLATFORM"] = platform
    if platform == "Darwin":
        env["MIXED_PRECISION"] = "no"

    if "TRAINING_NUM_PROCESSES" not in env:
        env["TRAINING_NUM_PROCESSES"] = "1"
    if "TRAINING_NUM_MACHINES" not in env:
        env["TRAINING_NUM_MACHINES"] = "1"
    if "MIXED_PRECISION" not in env:
        env["MIXED_PRECISION"] = "bf16"
    if "TRAINING_DYNAMO_BACKEND" not in env:
        env["TRAINING_DYNAMO_BACKEND"] = "no"

    return env

def parse_image_tag(name: str) -> tuple[str, Optional[str]]:
    tag = None
    name_parts = name.split("/")

    # First handles the simplest image names (DockerHub-based, index-free, potentially with a tag or digest)
    # - Example: simplename:latest or simplename@sha256:abc123
    if len(name_parts) == 1:
        if "@" in name_parts[0]:
            image_name, tag = name_parts[0].split("@")
        elif ":" in name_parts[0]:
            image_name, tag = name_parts[0].split(":")

        else:
            image_name = name_parts[0]
    else:
        # 1. Separates index (hostname.io or prefecthq) from path:tag (folder/subfolder:latest or prefect:latest)
        # 2. Separates path and tag/digest (if exists)
        # 3. Reunites index and path (without tag/digest) as image name
        index_name = name_parts[0]
        image_path = "/".join(name_parts[1:])

        if "@" in image_path:
            image_path, tag = image_path.split("@")
        elif ":" in image_path:
            image_path, tag = image_path.split(":")

        image_name = f"{index_name}/{image_path}"

    return image_name, tag

def edit_distance_filter(source_target_input, max_equal_to_diff_ratio=0):
  thrown_out_count = 0
  source_target_output = []

  if not max_equal_to_diff_ratio:
    return source_target_input, thrown_out_count

  for src_tgt in source_target_input:
    opcodes = fast_match_sequences(*src_tgt)
    diff_char_count = 0
    equal_char_count = 0
    for tag, i1, i2, j1, j2 in opcodes:
      if tag == "diff":
        # max() prevents double-counting substitutions.
        diff_char_count += max(i2 - i1, j2 - j1)
      else:
        equal_char_count += i2 - i1
    if diff_char_count <= max_equal_to_diff_ratio * equal_char_count:
      source_target_output.append(src_tgt)
    else:
      thrown_out_count += 1
  return source_target_output, thrown_out_count

def chunk_bytes_iter(iterator, chunk_len: int, stride: tuple[int, int], stream: bool = False):
    acc = b""
    stride_left, stride_right = stride
    if stride_left + stride_right >= chunk_len:
        raise ValueError(
            f"Stride needs to be strictly smaller than chunk_len: ({stride_left}, {stride_right}) vs {chunk_len}"
        )
    _stride_left = 0
    for raw in iterator:
        acc += raw
        if stream and len(acc) < chunk_len:
            stride = (_stride_left, 0)
            yield {"raw": acc[:chunk_len], "stride": stride, "partial": True}
        else:
            while len(acc) >= chunk_len:
                # We are flushing the accumulator
                stride = (_stride_left, stride_right)
                item = {"raw": acc[:chunk_len], "stride": stride}
                if stream:
                    item["partial"] = False
                yield item
                _stride_left = stride_left
                acc = acc[chunk_len - stride_left - stride_right :]
    # Last chunk
    if len(acc) > stride_left:
        item = {"raw": acc, "stride": (_stride_left, 0)}
        if stream:
            item["partial"] = False
        yield item

def tabulate(
    f: Callable[..., Any] | hk.Transformed | hk.TransformedWithState,
    *,
    columns: Sequence[str] | None = DEFAULT_COLUMNS,
    filters: Sequence[str] | None = DEFAULT_FILTERS,
    tabulate_kwargs={"tablefmt": "grid"},
) -> Callable[..., str]:
  # pylint: disable=line-too-long
  # pylint: enable=line-too-long
  f = eval_summary(f)

  if columns is None:
    columns = DEFAULT_COLUMNS
  else:
    invalid = [c for c in columns if c not in all_columns]
    if invalid:
      raise ValueError(
          f"Invalid column(s) {invalid}, valid columns {list(all_columns)}")

  if filters is None:
    filters = DEFAULT_FILTERS
  else:
    invalid = [f for f in filters if f not in all_filters]
    if invalid:
      raise ValueError(
          f"Invalid filter(s) {invalid}, valid filters {list(all_filters)}")

  columns = [all_columns[c] for c in columns]
  filters = [all_filters[f] for f in filters]

  def generate_summary(*args, **kwargs) -> str:
    """Generates a string summary of the given Haiku function."""
    rows = []
    for method_invocation in f(*args, **kwargs):
      if not all(filter.f(method_invocation) for filter in filters):
        continue

      row = [column.f(method_invocation) for column in columns]
      rows.append(row)

    if rows:
      headers = [col.header for col in columns]
      colalign = [col.align for col in columns]
      return tabulate_lib.tabulate(
          rows, headers=headers, colalign=colalign, **tabulate_kwargs)
    else:
      return "No modules matching filters."

  return generate_summary

def disable(self, *flags):
    old_bitmask = self.opt.disableflags
    new_bitmask = old_bitmask
    for flag in flags:
      if isinstance(flag, str):
        try:
          field_name = "mjDSBL_" + flag.upper()
          flag = getattr(mujoco.mjtDisableBit, field_name)
        except AttributeError:
          valid_names = [
              field_name.split("_")[1].lower()
              for field_name in list(mujoco.mjtDisableBit.__members__)[:-1]
          ]
          raise ValueError("'{}' is not a valid flag name. Valid names: {}"
                           .format(flag, ", ".join(valid_names))) from None
      elif isinstance(flag, int):
        flag = mujoco.mjtDisableBit(flag)
      new_bitmask |= flag.value
    self.opt.disableflags = new_bitmask
    try:
      yield
    finally:
      self.opt.disableflags = old_bitmask

def cache_locally(self, path, save_path=None):
        # todo : replace this function with the FileCache
        if save_path is None:
            if not is_file_present(self._temp_card_save_path):
                LocalStorage._makedirs(self._temp_card_save_path)
        else:
            save_dir = os.path.dirname(save_path)
            if save_dir != "" and not is_file_present(save_dir):
                LocalStorage._makedirs(os.path.dirname(save_path))

        with self._backend.load_bytes([path]) as get_results:
            for key, path, meta in get_results:
