                    return main_path

def prepare_data(self, batch):
        eqs, ims = batch.T
        tok = self.tokenizer(list(eqs), return_token_type_ids=False)
        # pad with bos and eos token
        for k, p in zip(tok, [[self.bos_token_id, self.eos_token_id], [1, 1]]):
            tok[k] = pad_sequence([torch.LongTensor([p[0]]+x+[p[1]]) for x in tok[k]], batch_first=True, padding_value=self.pad_token_id)
        # check if sequence length is too long
        if self.max_seq_len < tok['attention_mask'].shape[1]:
            return next(self)
        images = []
        for path in list(ims):
            im = cv2.imread(path)
            if im is None:
                print(path, 'not found!')
                continue
            im = cv2.cvtColor(im, cv2.COLOR_BGR2RGB)
            if not self.test:
                # sometimes convert to bitmask
                if np.random.random() < .04:
                    im[im != 255] = 0
            images.append(self.transform(image=im)['image'][:1])
        try:
            images = torch.cat(images).float().unsqueeze(1)
        except RuntimeError:
            logging.critical('Images not working: %s' % (' '.join(list(ims))))
            return None, None
        if self.pad:
            h, w = images.shape[2:]
            images = F.pad(images, (0, self.max_dimensions[0]-w, 0, self.max_dimensions[1]-h), value=1)
        return tok, images

def get_initializer(name, activation=None):
    if activation in [None, 'id', 'identity', 'linear', 'modrelu']:
        nonlinearity = 'linear'
    elif activation in ['relu', 'tanh', 'sigmoid']:
        nonlinearity = activation
    elif activation in ['gelu', 'swish', 'silu']:
        nonlinearity = 'relu' # Close to ReLU so approximate with ReLU's gain
    else:
        raise NotImplementedError(f'get_initializer: activation {activation} not supported')

    if name == 'uniform':
        initializer = partial(nn.init.kaiming_uniform_, nonlinearity=nonlinearity)
    elif name == 'normal':
        initializer = partial(nn.init.kaiming_normal_, nonlinearity=nonlinearity)
    elif name == 'xavier':
        initializer = nn.init.xavier_normal_
    elif name == 'zero':
        initializer = partial(nn.init.constant_, val=0)
    elif name == 'one':
        initializer = partial(nn.init.constant_, val=1)
    else:
        raise NotImplementedError(f'get_initializer: initializer type {name} not supported')

    return initializer

def git_get_keywords(versionfile_abs):
    # the code embedded in _version.py can just fetch the value of these
    # keywords. When used from setup.py, we don't want to import _version.py,
    # so we do it with a regexp instead. This function is not used from
    # _version.py.
    keywords = {}
    try:
        with open(versionfile_abs, "r") as fobj:
            for line in fobj:
                if line.strip().startswith("git_refnames ="):
                    mo = re.search(r'=\s*"(.*)"', line)
                    if mo:
                        keywords["refnames"] = mo.group(1)
                if line.strip().startswith("git_full ="):
                    mo = re.search(r'=\s*"(.*)"', line)
                    if mo:
                        keywords["full"] = mo.group(1)
                if line.strip().startswith("git_date ="):
                    mo = re.search(r'=\s*"(.*)"', line)
                    if mo:
                        keywords["date"] = mo.group(1)
    except OSError:
        pass
    return keywords

def list_checkpoints(self, environment_id: str, sort_by: str = "step-desc") -> Dict[str, Any]:
        try:
            manager = self._get_checkpoint_manager(environment_id)
            checkpoints = manager.list_checkpoints(include_metadata=True)

            # Always calculate size for each checkpoint
            for ckpt in checkpoints:
                ckpt_path = ckpt.get("path")
                if ckpt_path and os.path.exists(ckpt_path):
                    try:
                        size = sum(
                            os.path.getsize(os.path.join(dirpath, filename))
                            for dirpath, dirnames, filenames in os.walk(ckpt_path)
                            for filename in filenames
                        )
                        ckpt["size_bytes"] = size
                    except Exception:
                        ckpt["size_bytes"] = 0
                else:
                    ckpt["size_bytes"] = 0

            # Apply sorting
            if sort_by == "step-asc":
                checkpoints.sort(key=lambda x: x.get("step", 0), reverse=False)
            elif sort_by == "step-desc":
                checkpoints.sort(key=lambda x: x.get("step", 0), reverse=True)
            elif sort_by == "size-desc":
                checkpoints.sort(key=lambda x: x.get("size_bytes", 0), reverse=True)

            previews = [self._build_checkpoint_preview(environment_id, manager, ckpt) for ckpt in checkpoints]

            return {
                "environment": environment_id,
                "checkpoints": previews,
                "count": len(previews),
                "sort_by": sort_by,
            }

        except CheckpointsServiceError:
            raise
        except Exception as e:
            raise CheckpointsServiceError(
                f"Failed to list checkpoints: {str(e)}",
                status.HTTP_500_INTERNAL_SERVER_ERROR,
            ) from e

def equalize_bads(insts, interp_thresh=1.0, copy=True):
    if not 0 <= interp_thresh <= 1:
        raise ValueError(f"interp_thresh must be between 0 and 1, got {interp_thresh}")

    all_bads = list(set(chain.from_iterable([inst.info["bads"] for inst in insts])))
    if isinstance(insts[0], BaseEpochs):
        durations = [len(inst) * len(inst.times) for inst in insts]
    else:
        durations = [len(inst.times) for inst in insts]

    good_times = []
    for ch_name in all_bads:
        good_times.append(
            sum(
                durations[k]
                for k, inst in enumerate(insts)
                if ch_name not in inst.info["bads"]
            )
            / np.sum(durations)
        )

    bads_keep = [ch for k, ch in enumerate(all_bads) if good_times[k] < interp_thresh]
    if copy:
        insts = [inst.copy() for inst in insts]

    for inst in insts:
        if len(set(inst.info["bads"]) - set(bads_keep)):
            inst.interpolate_bads(exclude=bads_keep)
        inst.info["bads"] = bads_keep

    return insts

def from_pyflux_dataset(X):
    try:
        import pandas as pd
    except ImportError:
        raise ImportError("Conversion from/to pyflux cannot be performed "
                          "if pandas is not installed.")
    if not isinstance(X, pd.DataFrame):
        raise ValueError("X is not a valid input pyflux array. "
                         "A pandas DataFrame is expected.")
    data_dimensions = [col_name for col_name in X.columns]
    d = len(data_dimensions)
    n = 1

    max_sz = -1
    for dim_name in data_dimensions:
        if X[dim_name].size > max_sz:
            max_sz = X[dim_name].size

    tslearn_arr = numpy.empty((n, max_sz, d))
    tslearn_arr[:] = numpy.nan
    for di, dim_name in enumerate(data_dimensions):
        data = X[dim_name].values.copy()
        sz = len(data)
        tslearn_arr[0, :sz, di] = data
    return tslearn_arr

def limits(self, value, square=False):
        if isinstance(value, six.string_types):
            import re
            match = re.match(r"(\d*)(\D*)", value)
            if match is None:
                raise ValueError("do not understand limit specifier %r, examples are 90%, 3sigma")
            else:
                value, type = match.groups()
                import ast
                value = ast.literal_eval(value)
                type = type.strip()
                if type in ["s", "sigma"]:
                    return self.limits_sigma(value)
                elif type in ["ss", "sigmasquare"]:
                    return self.limits_sigma(value, square=True)
                elif type in ["%", "percent"]:
                    return self.limits_percentage(value)
                elif type in ["%s", "%square", "percentsquare"]:
                    return self.limits_percentage(value, square=True)
        if value is None:
            return self.limits_percentage(square=square)
        else:
            return value

def schedule_inline_blocks(
        sch: s_tir.Schedule, blocks: list[s_tir.schedule.SBlockRV]
    ) -> list[s_tir.schedule.SBlockRV]:

        if blocks is None:
            root_blk = analysis.get_root_block(sch)
            blocks = sch.get_child_blocks(root_blk)

        remaining_blocks = []
        for blk in blocks:
            block_info = analysis.get_sblock_info(sch, blk)
            if block_info.is_injective() and not block_info.is_data_pad(sch):
                if len(sch.get_consumers(blk)) == 1:
                    try:
                        sch.compute_inline(blk)
                    except Exception:  # pylint: disable=broad-exception-caught
                        remaining_blocks.append(blk)
                elif len(sch.get_producers(blk)) == 1:
                    inlined_once = False
                    try:
                        # Would cause an issue inlining to producer with multiple consumers
                        while (
                            len(sch.get_producers(blk)) == 1
                            and len(sch.get_consumers(sch.get_producers(blk)[0])) == 1
                        ):
                            sch.reverse_compute_inline(blk)
                            inlined_once = True
                    except Exception:  # pylint: disable=broad-exception-caught
                        break
                    if not inlined_once:
                        remaining_blocks.append(blk)
                else:
                    remaining_blocks.append(blk)
            else:
                remaining_blocks.append(blk)
        return remaining_blocks

def remove_pixelserver_from_notebook(file_path):
    with open(file_path, encoding='utf-8') as fd:
        raw_json = json.load(fd)

        if 'cells' not in raw_json:
            return

        cells = raw_json['cells']
        pixel_cells = []

        for idx, cell in enumerate(cells):
            if cell['cell_type'] != 'markdown':
                continue

            source = cell['source']
            for row in source:
                if row.startswith(SIGNATURE):
                    pixel_cells.append(idx)
                    print("Found pixelserver in file: \"{}\", cell {}".format(file_path, idx))

        for cell_id in pixel_cells[::-1]:
            cells.pop(cell_id)

    if pixel_cells:
        with open(file_path, 'w', encoding='utf-8') as fd:
            json.dump(raw_json, fd, indent=1)

def apply(self, prog):
        if not isinstance(prog, Program):
            raise TypeError('Transform "{}" can only be applied on PyMIL programs.'.format(self))

        if getattr(self, "skip_ops_by_type", set()) and self.op_selector is not None:
            raise ValueError(
                "The graph pass option `skip_ops_by_type` cannot be set along with "
                "the `op_selector` in FP16ComputePrecision. Please only use one "
                "method to control which ops to operate on."
            )

        @block_context_manager
        def apply_block(block):
            self._cache_vars.append({})
            for op in list(block.operations):
                for b in op.blocks:
                    apply_block(b)

                if self.is_valid_op(op):
                    need_transform: bool
                    if self.op_selector is not None:
                        need_transform = self.op_selector(op)
                    else:
                        need_transform = op.op_type not in getattr(self, "skip_ops_by_type", set())
                    if need_transform:
                        self.transform_op(op)
            self._cache_vars.pop()

        for f in prog.functions.values():
            apply_block(f)

def get_num_devices_for_whole_batch(sharding_spec, batch_dim=0):
    num_devices = 1
    for sharding in sharding_spec.sharding:
        if isinstance(sharding, pxla.Chunked):
            num_devices *= np.prod(sharding.chunks)

    for assignment in sharding_spec.mesh_mapping:
        if isinstance(assignment, pxla.Replicated):
            num_devices *= assignment.replicas

    sharding = sharding_spec.sharding[batch_dim]

    num_data_chunk = 1
    if isinstance(sharding, pxla.Chunked):
        num_data_chunk = np.prod(sharding.chunks)

        # Assert the data chunk is mapped to the first dim of device mesh
        for assignment in sharding_spec.mesh_mapping:
            if isinstance(assignment, pxla.ShardedAxis):
                assert assignment.axis == 0
                break

    return num_devices / num_data_chunk

def put_directory(
        self,
        local_path: Optional[str] = None,
        to_path: Optional[str] = None,
        ignore_file: Optional[str] = None,
    ) -> int:
        to_path = "" if to_path is None else to_path

        if local_path is None:
            local_path = "."

        included_files = None
        if ignore_file:
            with open(ignore_file, "r") as f:
                ignore_patterns = f.readlines()

            included_files = filter_files(local_path, ignore_patterns)

        uploaded_file_count = 0
        for local_file_path in Path(local_path).expanduser().rglob("*"):
            if (
                included_files is not None
                and str(local_file_path.relative_to(local_path)) not in included_files
            ):
                continue
            elif not local_file_path.is_dir():
                remote_file_path = Path(to_path) / local_file_path.relative_to(
                    local_path
                )
                with open(local_file_path, "rb") as local_file:
                    local_file_content = local_file.read()

                self.write_path(
                    remote_file_path.as_posix(), content=local_file_content, _sync=True
                )
                uploaded_file_count += 1

        return uploaded_file_count

def update_from_model(self, response: str, **kwargs) -> Action:
        tool_calls_dict = []
        assistant_content = response
        # Attempt to parse tool calls from string response
        try:
            tool_calls = self.tool_parser.parse(response)
            tool_calls_dict = [
                {
                    "id": str(uuid.uuid4()),
                    "type": "function",
                    "function": tool_call.to_dict(),
                }
                for tool_call in tool_calls
            ]

        except Exception as e:
            logger.error(f"Failed to parse tool calls from string response: {e}")
            tool_calls_dict = []  # Indicate no valid tool calls parsed

        # Append assistant message to chat history
        assistant_message = {"role": "assistant", "content": assistant_content}
        if len(tool_calls_dict) > 0:
            # Ensure arguments within tool_calls_dict are strings if needed by downstream processing
            for call in tool_calls_dict:
                if isinstance(call.get("function", {}).get("arguments"), dict):
                    call["function"]["arguments"] = json.dumps(call["function"]["arguments"])
        else:
            tool_calls_dict = [
                {
                    "id": str(uuid.uuid4()),
                    "type": "function",
                    "function": {
                        "name": "finish",
                        "arguments": {
                            "response": assistant_content,
                        },
                    },
                }
            ]

        self.messages.append(assistant_message)

        new_step = Step(chat_completions=copy.deepcopy(self.chat_completions), action=tool_calls_dict, model_response=response, observation=self.current_observation)
        self._trajectory.steps.append(new_step)

        return Action(action=tool_calls_dict)

def call_packed(
    func: py_str,
    *args: Expr,
    sinfo_args: StructInfo | list[StructInfo] | None = None,
    **kwargs: Any,
) -> Call:
    op = ExternFunc(func)
    args = py_tuple(convert_to_expr(a) for a in args)
    if sinfo_args is None:
        sinfo_args = []
    if isinstance(sinfo_args, py_tuple):  # type: ignore
        sinfo_args = list(sinfo_args)
    elif not isinstance(sinfo_args, list):
        sinfo_args = [sinfo_args]

    sinfo_args = [
        (
            sinfo()
            if callable(sinfo)
            else sinfo.asobject()
            if isinstance(sinfo, ObjectConvertible)
            else sinfo
        )
        for sinfo in sinfo_args
    ]

    is_default = False
    if "attrs_type_key" in kwargs:
        attrs_type_key = kwargs["attrs_type_key"]
        kwargs.pop("attrs_type_key")
    else:
        attrs_type_key = "ir.DictAttrs"
        is_default = True
    attrs = None
    if kwargs or not is_default:
        attrs = tvm.ir.attrs.make_node(attrs_type_key, **kwargs)

    return Call(op, args, attrs=attrs, sinfo_args=sinfo_args)

def sanitize_parameters_to_prune(
        pl_module: LightningModule, parameters_to_prune: _PARAM_LIST = (), parameter_names: Sequence[str] = ()
    ) -> _PARAM_LIST:
        parameters = parameter_names or ModelPruning.PARAMETER_NAMES

        current_modules = [m for m in pl_module.modules() if not isinstance(m, _MODULE_CONTAINERS)]

        if not parameters_to_prune:
            parameters_to_prune = [
                (m, p)
                for p in parameters
                for m in current_modules
                if getattr(m, p, None) is not None and isinstance(getattr(m, p, None), nn.Parameter)
            ]
        elif (
            isinstance(parameters_to_prune, (list, tuple))
            and len(parameters_to_prune) > 0
            and all(len(p) == 2 for p in parameters_to_prune)
            and all(isinstance(a, nn.Module) and isinstance(b, str) for a, b in parameters_to_prune)
        ):
            missing_modules, missing_parameters = [], []
            for module, name in parameters_to_prune:
                if module not in current_modules:
                    missing_modules.append(module)
                    continue
                if not hasattr(module, name):
                    missing_parameters.append(name)

            if missing_modules or missing_parameters:
                raise MisconfigurationException(
                    "Some provided `parameters_to_prune` don't exist in the model."
                    f" Found missing modules: {missing_modules} and missing parameters: {missing_parameters}"
                )
        else:
            raise MisconfigurationException(
                "The provided `parameters_to_prune` should either be list of tuple"
                " with 2 elements: (nn.Module, parameter_name_to_prune) or None"
            )

        return parameters_to_prune

def select_flow(
    flows: Iterable[Flow[P, R]],
    flow_name: Optional[str] = None,
    from_message: Optional[str] = None,
) -> Flow[P, R]:
    # Convert to flows by name
    flows_dict = {f.name: f for f in flows}

    # Add a leading space if given, otherwise use an empty string
    from_message = (" " + from_message) if from_message else ""
    if not Optional:
        raise MissingFlowError(f"No flows found{from_message}.")

    elif flow_name and flow_name not in flows_dict:
        raise MissingFlowError(
            f"Flow {flow_name!r} not found{from_message}. "
            f"Found the following flows: {listrepr(flows_dict.keys())}. "
            "Check to make sure that your flow function is decorated with `@flow`."
        )

    elif not flow_name and len(flows_dict) > 1:
        raise UnspecifiedFlowError(
            (
                f"Found {len(flows_dict)} flows{from_message}:"
                f" {listrepr(sorted(flows_dict.keys()))}. Specify a flow name to select a"
                " flow."
            ),
        )

    if flow_name:
        return flows_dict[flow_name]
    else:
        return list(flows_dict.values())[0]

def which(cmd, mode=os.F_OK | os.X_OK, path=None):
    # Check that a given file can be accessed with the correct mode.
    # Additionally check that `file` is not a directory, as on Windows
    # directories pass the os.access check.
    try:  # Forced testing
        from shutil import which as w

        return w(cmd, mode, path)
    except ImportError:

        def _access_check(fn, mode):
            return os.path.exists(fn) and os.access(fn, mode) and not os.path.isdir(fn)

        # If we're given a path with a directory part, look it up directly
        # rather than referring to PATH directories. This includes checking
        # relative to the current directory, e.g. ./script
        if os.path.dirname(cmd):
            if _access_check(cmd, mode):
                return cmd
            return None

        if path is None:
            path = os.environ.get("PATH", os.defpath)
        if not path:
            return None

        path = path.split(os.pathsep)

        files = [cmd]
        seen = set()
        for dir in path:
            normdir = os.path.normcase(dir)
            if normdir not in seen:
                seen.add(normdir)
                for thefile in files:
                    name = os.path.join(dir, thefile)
                    if _access_check(name, mode):
                        return name

        return None

def create_db_lock(
    session,
    lock: DBLocks,
    lock_timeout: int = 30000,  # 30 seconds
) -> Generator[None, None, None]:
    conn = session.get_bind().connect()
    dialect = conn.dialect

    lock_acquired = False

    try:
        if dialect.name == 'postgresql':
            conn.execute(
                text('SET LOCK_TIMEOUT to :timeout'), {'timeout': lock_timeout}
            )
            conn.execute(text('SELECT pg_advisory_lock(:id)'), {'id': lock.value})
        elif dialect.name == 'mysql' and dialect.server_version_info >= (5, 6):
            conn.execute(
                text('SELECT GET_LOCK(:id, :timeout)'),
                {'id': str(lock), 'timeout': lock_timeout},
            )

        lock_acquired = True
        yield
    finally:
        if dialect.name == 'postgresql':
            conn.execute(text('SET LOCK_TIMEOUT TO DEFAULT'))
            (unlocked,) = conn.execute(
                text('SELECT pg_advisory_unlock(:id)'), {'id': lock.value}
            ).fetchone()
            if lock_acquired and not unlocked:
                raise RuntimeError('Error releasing DB lock!')
        elif dialect.name == 'mysql' and dialect.server_version_info >= (5, 6):
            conn.execute(text('select RELEASE_LOCK(:id)'), {'id': str(lock)})

        conn.close()

def exists(
        cls,
        dataset_name: Optional[str] = None,
        version_name: Optional[str] = None,
        project_name: Optional[str] = None,
        *,
        dataset_id: Optional[str] = None,
        version_id: Optional[str] = None,
    ) -> bool:
        if dataset_name and dataset_id:
            raise ValueError("Provide either dataset_name or dataset_id, not both")
        if version_name and version_id:
            raise ValueError("Provide either version_name or version_id, not both")

        if not dataset_name and not dataset_id:
            raise ValueError("dataset_name or dataset_id must be provided")

        if dataset_id:
            ds = HyperDatasetManagementBackend.get_dataset_by_id(dataset_id)
            if not ds:
                return False
        else:
            session = Session()
            project_id = get_existing_project(session, project_name) if project_name else None
            ds = HyperDatasetManagementBackend.get_dataset(name=dataset_name, project_id=project_id)
            if not ds:
                return False

        dataset_id = getattr(ds, "id", None)
        if not dataset_id:
            return False

        if version_id in (None, "*") and version_name is None:
            return True

        if version_id not in (None, "*"):
            return HyperDatasetManagementBackend.version_exists(dataset_id=dataset_id, version_id=version_id)

        version = HyperDatasetManagementBackend.get_version(dataset_id=dataset_id, version_name=version_name)
        return bool(version)

def adaptive_average_pool(inputs, output_size, data_format=None):
    inputs = convert_to_tensor(inputs)
    num_spatial_dims = inputs.ndim - 2

    data_format = backend.standardize_data_format(data_format)
    orig_format = data_format
    if data_format == "channels_last":
        inputs = _transpose_spatial_inputs(inputs)

    if isinstance(output_size, int):
        torch_output_size = (
            output_size
            if num_spatial_dims == 1
            else (output_size,) * num_spatial_dims
        )
    else:
        torch_output_size = standardize_tuple(
            output_size, num_spatial_dims, "output_size"
        )

    if get_device() == "meta":
        inputs = torch.empty(
            size=inputs.shape, dtype=inputs.dtype, device="cpu"
        )

    if num_spatial_dims == 1:
        outputs = tnn.adaptive_avg_pool1d(inputs, output_size=torch_output_size)
    elif num_spatial_dims == 2:
        outputs = tnn.adaptive_avg_pool2d(inputs, output_size=torch_output_size)
    elif num_spatial_dims == 3:
        outputs = tnn.adaptive_avg_pool3d(inputs, output_size=torch_output_size)
    else:
        raise ValueError(
            "Inputs to adaptive average pooling must have ndim=3, 4 or 5, "
            f"Received input shape: {inputs.shape}."
        )

    if orig_format == "channels_last":
        outputs = _transpose_spatial_outputs(outputs)
    return outputs

def save_optimizer_weights_to_hdf5_group(hdf5_group, optimizer):
    from keras.src import optimizers

    if isinstance(optimizer, optimizers.Optimizer):
        symbolic_weights = optimizer.variables
    else:
        symbolic_weights = getattr(optimizer, "weights")
    if symbolic_weights:
        weights_group = hdf5_group.create_group("optimizer_weights")
        weight_names = [str(w.path).encode("utf8") for w in symbolic_weights]
        save_attributes_to_hdf5_group(
            weights_group, "weight_names", weight_names
        )
        weight_values = [backend.convert_to_numpy(w) for w in symbolic_weights]
        for name, val in zip(weight_names, weight_values):
            param_dset = weights_group.create_dataset(
                name, val.shape, dtype=val.dtype
            )
            if not val.shape:
                # scalar
                param_dset[()] = val
            else:
                param_dset[:] = val

def compute_score(solution_str, ground_truth, method="strict", format_score=0.1, score=1.0):
    target = ground_truth["target"]
    numbers = ground_truth["numbers"]

    equation = extract_solution(solution_str=solution_str)
    do_print = random.randint(1, 64) == 1

    if do_print:
        logger.debug(f"Target: {target} | Numbers: {numbers} | Equation: {equation} | Solution: {solution_str}")

    if equation is None:
        if do_print:
            logger.debug("No equation found")
        return 0

    # Validate equation uses correct numbers
    if not validate_equation(equation, numbers):
        if do_print:
            logger.debug("Invalid equation")
        return format_score

    # Evaluate equation
    try:
        result = evaluate_equation(equation)
        if result is None:
            if do_print:
                logger.debug("Could not evaluate equation")
            return format_score

        if abs(result - target) < 1e-5:  # Account for floating point precision
            if do_print:
                logger.debug(f"Correct equation: {equation} = {result}")
            return score
        else:
            if do_print:
                logger.debug(f"Wrong result: equation = {result}, target = {target}")
            return format_score
    except Exception:
        if do_print:
            logger.debug("Error evaluating equation")
        return format_score

def make_sparse_tensor_type_proto(
    elem_type: int,
    shape: Sequence[str | int | None] | None,
    shape_denotation: list[str] | None = None,
) -> TypeProto:
    type_proto = TypeProto()
    sparse_tensor_type_proto = type_proto.sparse_tensor_type
    sparse_tensor_type_proto.elem_type = elem_type
    sparse_tensor_shape_proto = sparse_tensor_type_proto.shape

    if shape is not None:
        # You might think this is a no-op (extending a normal Python
        # list by [] certainly is), but protobuf lists work a little
        # differently; if a field is never set, it is omitted from the
        # resulting protobuf; a list that is explicitly set to be
        # empty will get an (empty) entry in the protobuf. This
        # difference is visible to our consumers, so make sure we emit
        # an empty shape!
        sparse_tensor_shape_proto.dim.extend([])

        if shape_denotation and len(shape_denotation) != len(shape):
            raise ValueError(
                "Invalid shape_denotation. Must be of the same length as shape."
            )

        for i, d in enumerate(shape):
            dim = sparse_tensor_shape_proto.dim.add()
            if d is None:
                pass
            elif isinstance(d, int):
                dim.dim_value = d
            elif isinstance(d, str):
                dim.dim_param = d
            else:
                raise ValueError(
                    f"Invalid item in shape: {d}. Needs to be of int or text."
                )

            if shape_denotation:
                dim.denotation = shape_denotation[i]

    return type_proto

def type(self):
        pa_type = self.pyarrow_dtype
        if pa.types.is_integer(pa_type):
            return int
        elif pa.types.is_floating(pa_type):
            return float
        elif pa.types.is_string(pa_type) or pa.types.is_large_string(pa_type):
            return str
        elif (
            pa.types.is_binary(pa_type)
            or pa.types.is_fixed_size_binary(pa_type)
            or pa.types.is_large_binary(pa_type)
        ):
            return bytes
        elif pa.types.is_boolean(pa_type):
            return bool
        elif pa.types.is_duration(pa_type):
            if pa_type.unit == "ns":
                return Timedelta
            else:
                return timedelta
        elif pa.types.is_timestamp(pa_type):
            if pa_type.unit == "ns":
                return Timestamp
            else:
                return datetime
        elif pa.types.is_date(pa_type):
            return date
        elif pa.types.is_time(pa_type):
            return time
        elif pa.types.is_decimal(pa_type):
            return Decimal
        elif pa.types.is_dictionary(pa_type):
            # TODO: Potentially change this & CategoricalDtype.type to
            #  something more representative of the scalar
            return CategoricalDtypeType
        elif pa.types.is_list(pa_type) or pa.types.is_large_list(pa_type):
            return list
        elif pa.types.is_fixed_size_list(pa_type):
            return list
        elif pa.types.is_map(pa_type):
            return list
        elif pa.types.is_struct(pa_type):
            return dict
        elif pa.types.is_null(pa_type):
            # TODO: None? pd.NA? pa.null?
            return type(pa_type)
        elif isinstance(pa_type, pa.BaseExtensionType):
            return type(self)(pa_type.storage_type).type
        raise NotImplementedError(pa_type)

def layer_description_extractor(layer, node_to_id):
    layer_input = layer.input
    layer_output = layer.output
    if layer_input is not None:
        if isinstance(layer_input, Iterable):
            layer_input = list(map(lambda x: node_to_id[x], layer_input))
        else:
            layer_input = node_to_id[layer_input]

    if layer_output is not None:
        layer_output = node_to_id[layer_output]

    if isinstance(layer, StubConv):
        return (
            type(layer).__name__,
            layer_input,
            layer_output,
            layer.input_channel,
            layer.filters,
            layer.kernel_size,
            layer.stride,
            layer.padding,
        )
    elif isinstance(layer, (StubDense,)):
        return [
            type(layer).__name__,
            layer_input,
            layer_output,
            layer.input_units,
            layer.units,
        ]
    elif isinstance(layer, (StubBatchNormalization,)):
        return (type(layer).__name__, layer_input,
                layer_output, layer.num_features)
    elif isinstance(layer, (StubDropout,)):
        return (type(layer).__name__, layer_input, layer_output, layer.rate)
    elif isinstance(layer, StubPooling):
        return (
            type(layer).__name__,
            layer_input,
            layer_output,
            layer.kernel_size,
            layer.stride,
            layer.padding,
        )
    else:
        return (type(layer).__name__, layer_input, layer_output)

def minibatch_by_padded_size(
    seqs: Iterable[ItemT],
    size: Sizing,
    buffer: int = 256,
    discard_oversize: bool = False,
    get_length: Callable = len,
) -> Iterable[List[ItemT]]:
    if isinstance(size, int):
        size_ = itertools.repeat(size)  # type: Iterator[int]
    else:
        size_ = iter(size)
    for outer_batch in minibatch(seqs, size=buffer):
        outer_batch = list(outer_batch)
        target_size = next(size_)
        for indices in _batch_by_length(outer_batch, target_size, get_length):
            subbatch = [outer_batch[i] for i in indices]
            padded_size = max(len(seq) for seq in subbatch) * len(subbatch)
            if discard_oversize and padded_size >= target_size:
                pass
            else:
                yield subbatch

def invert_subselect_rows_by_indices_(self, indices, batch_subselected):
        for augm_name in _AUGMENTABLE_NAMES:
            column = getattr(self, augm_name)
            if column is not None:
                column_sub = getattr(batch_subselected, augm_name)
                if column_sub is None:
                    # list of indices was empty, resulting in the columns
                    # in the subselected batch being empty and replaced
                    # by Nones. We can just re-use the columns before
                    # subselection.
                    pass
                elif augm_name == "images" and ia.is_np_array(column):
                    # An array does not have to stay an array after
                    # augmentation. The shapes and/or dtypes of rows may
                    # change, turning the array into a list.
                    if ia.is_np_array(column_sub):
                        shapes = {column.shape[1:], column_sub.shape[1:]}
                        dtypes = {column.dtype.name, column_sub.dtype.name}
                    else:
                        shapes = set(
                            [column.shape[1:]]
                            + [image.shape for image in column_sub])
                        dtypes = set(
                            [column.dtype.name]
                            + [image.dtype.name for image in column_sub])

                    if len(shapes) == 1 and len(dtypes) == 1:
                        column[indices] = column_sub  # pylint: disable=unsupported-assignment-operation
                    else:
                        self.images = list(column)
                        for ith_index, index in enumerate(indices):
                            self.images[index] = column_sub[ith_index]
                else:
                    for ith_index, index in enumerate(indices):
                        column[index] = column_sub[ith_index]  # pylint: disable=unsupported-assignment-operation

        return self

def get_onnx_example(op_name, domain):
    if domain in (None, "ai.onnx"):
        modules = [
            f"onnx.backend.test.case.node.{op_name.lower()}",
            f"onnx.backend.test.case.node.{pascal_to_snake_case(op_name)}",
        ]
    else:
        domain_ = domain.replace(".", "_")
        modules = [
            f"onnx.backend.test.case.node.{domain_}.{op_name.lower()}",
            f"onnx.backend.test.case.node.{domain_}.{pascal_to_snake_case(op_name)}",
        ]
    module = None
    for m in modules:
        try:
            mod = importlib.import_module(m)
            module = m
        except ImportError:  # noqa: PERF203
            continue
    if module is None:
        # Unable to find an example for 'op_name'.
        return {}
    results: dict[str, Any] = {}
    for v in mod.__dict__.values():
        if not isinstance(v, _Exporter):
            continue
        code_cls = inspect.getsource(v)
        codes = code_cls.split("@staticmethod")
        for me in v.__dict__:
            if not me.startswith("export"):
                continue
            sub = f" {me}()"
            found = None
            for code in codes:
                if sub in code:
                    found = code
            if found is None:
                raise RuntimeError(f"Unable to find {sub!r} in\n{code_cls}")
            found = textwrap.dedent(found)
            lines = found.split("\n")
            first = 0
            for i in range(len(lines)):
                if lines[i].startswith("def "):
                    first = i + 1
            found = textwrap.dedent("\n".join(lines[first:]))
            key = me[len("export") :]
            if key == "":
                key = "default"
                if key in results:
                    key = f"example {len(results) + 1}"
            results[key] = _process_example(found)
    return results

def sldump(obj, file=None, file_format=None, **kwargs):
    if isinstance(file, Path):
        file = str(file)
    if file_format is None:
        if is_str(file):
            file_format = file.split(".")[-1]
        elif file is None:
            raise ValueError(
                "file_format must be specified since file is None"
            )
    if file_format not in file_handlers:
        raise TypeError(f"Unsupported format: {file_format}")

    handler = file_handlers[file_format]
    if file is None:
        return handler.dump_to_str(obj, **kwargs)
    elif is_str(file):
        handler.dump_to_path(obj, file, **kwargs)
    elif hasattr(file, "write"):
        handler.dump_to_fileobj(obj, file, **kwargs)
    else:
        raise TypeError('"file" must be a filename str or a file-object')

def compute(self, X, Y):
        loss = None
        if self.loss_type in ("mmd_lin", "mmd"):
            mmdloss = MMD_loss(kernel_type="linear")
            loss = mmdloss(X, Y)
        elif self.loss_type == "coral":
            loss = CORAL(X, Y, self.device)
        elif self.loss_type in ("cosine", "cos"):
            loss = 1 - cosine(X, Y)
        elif self.loss_type == "kl":
            loss = kl_div(X, Y)
        elif self.loss_type == "js":
            loss = js(X, Y)
        elif self.loss_type == "mine":
            mine_model = Mine_estimator(input_dim=self.input_dim, hidden_dim=60).to(self.device)
            loss = mine_model(X, Y)
        elif self.loss_type == "adv":
            loss = adv(X, Y, self.device, input_dim=self.input_dim, hidden_dim=32)
        elif self.loss_type == "mmd_rbf":
            mmdloss = MMD_loss(kernel_type="rbf")
            loss = mmdloss(X, Y)
        elif self.loss_type == "pairwise":
            pair_mat = pairwise_dist(X, Y)
            loss = torch.norm(pair_mat)

        return loss

def compute_score_parts(self) -> None:
        for name, site in self.nodes.items():
            if site["type"] == "sample" and "score_parts" not in site:
                if TYPE_CHECKING:
                    assert isinstance(site["fn"], Distribution)
                # Note that ScoreParts overloads the multiplication operator
                # to correctly scale each of its three parts.
                try:
                    value = site["fn"].score_parts(
                        site["value"], *site["args"], **site["kwargs"]
                    )
                except ValueError as e:
                    _, exc_value, traceback = sys.exc_info()
                    shapes = self.format_shapes(last_site=site["name"])
                    raise ValueError(
                        "Error while computing score_parts at site '{}':\n{}\n{}".format(
                            name, exc_value, shapes
                        )
                    ).with_traceback(traceback) from e
                site["unscaled_log_prob"] = value.log_prob
                value = value.scale_and_mask(site["scale"], site["mask"])
                site["score_parts"] = value
                site["log_prob"] = value.log_prob
                site["log_prob_sum"] = value.log_prob.sum()
                if is_validation_enabled():
                    warn_if_nan(
                        site["log_prob_sum"], "log_prob_sum at site '{}'".format(name)
                    )
                    warn_if_inf(
                        site["log_prob_sum"],
                        "log_prob_sum at site '{}'".format(name),
                        allow_neginf=True,
                    )

def CreateDropInputs(  # pylint: disable=invalid-name
    train=True, mathqa_format=False):
  if train:
    dataset = tfds.load(name='drop', split='train')
  else:
    dataset = tfds.load(name='drop', split='dev')
  dataset = tfds.as_numpy(dataset)

  def drop_yield_examples(generator=None):
    del generator
    while True:
      for example in itertools.cycle(dataset):
        input_values = 'drop question: ' + example['passage'].decode(
            'utf-8') + ' ' + example['question'].decode('utf-8')
        target_values = example['answer'].decode('utf-8')
        # Apparently the dataset has some empty "target values" -
        # when such a value is encountered, the Tokenizer decides to assign
        # to it a float32 tensor and the training fails.
        if not target_values:
          continue
        if mathqa_format:
          if target_values.replace('.', '', 1).isdigit():
            target_values = convert_to_subtract(
                convert_float_to_mathqa(target_values))
        yield input_values, target_values, np.array(
            [1] * len(target_values), dtype=np.int32)

  return drop_yield_examples

def get_data(self, frequency=None, index=None, as_cov=False):
        if frequency is None and index is None:
            if self._data.shape[1] > 1:
                raise ValueError(
                    "Specify either the frequency or index of "
                    "the frequency bin for which to obtain the "
                    "CSD matrix."
                )
            index = 0
        elif frequency is not None:
            if index is not None:
                raise ValueError("Cannot specify both a frequency and index.")
            index = self._get_frequency_index(frequency)

        data = _vector_to_sym_mat(self._data[:, index])
        if as_cov:
            # Pack the data into a Covariance object
            from ..cov import Covariance  # to avoid circular import

            return Covariance(
                data, self.ch_names, bads=[], projs=self.projs, nfree=self.n_fft
            )
        else:
            return data

def handle_condition(self, tok, indices):
        if tok == "not":
            return [self._handle_not()]

        if tok == "or":
            conds = [self._handle_binary_expression(self._make_or_expression)]
        elif tok == "imp":
            conds = [self._handle_binary_expression(self._make_imp_expression)]
        elif tok == "eq":
            conds = [self._handle_eq()]
        elif tok == "prop":
            conds = [self._handle_prop()]

        elif tok == "pred":
            conds = [self._handle_pred()]
        elif tok == "named":
            conds = [self._handle_named()]
        elif tok == "rel":
            conds = [self._handle_rel()]
        elif tok == "timex":
            conds = self._handle_timex()
        elif tok == "card":
            conds = [self._handle_card()]

        elif tok == "whq":
            conds = [self._handle_whq()]
        elif tok == "duplex":
            conds = [self._handle_duplex()]

        else:
            conds = []

        return sum(
            (
                [cond(sent_index, word_indices) for cond in conds]
                for sent_index, word_indices in self._sent_and_word_indices(indices)
            ),
            [],
        )

def parse_approval_response(body: str) -> str:
    # Clean and normalize the body
    cleaned = _clean_email_body(body)

    if not cleaned:
        return "unknown"

    # Try to match against the first line only (most reliable)
    first_line = cleaned.split("\n")[0].strip()

    # Single word responses are most reliable
    if len(first_line.split()) <= 3:
        # Check affirmative patterns first
        for pattern in AFFIRMATIVE_PATTERNS:
            if re.search(pattern, first_line, re.IGNORECASE | re.UNICODE):
                return "approve"

        # Then check rejection patterns
        for pattern in REJECTION_PATTERNS:
            if re.search(pattern, first_line, re.IGNORECASE | re.UNICODE):
                return "reject"

    # If first line didn't match, check full body
    # (less reliable as it may contain quoted text)
    for pattern in AFFIRMATIVE_PATTERNS:
        if re.search(pattern, cleaned, re.IGNORECASE | re.UNICODE):
            return "approve"

    for pattern in REJECTION_PATTERNS:
        if re.search(pattern, cleaned, re.IGNORECASE | re.UNICODE):
            return "reject"

    return "unknown"

def is_field_boolean(source: DataSource, field: str) -> bool:
    unique_values = source.df[field].unique()
    if len(unique_values) <= 3:
        for entry in unique_values:
            try:
                if np.isnan(entry):
                    continue
            except TypeError:
                # For some field types such as object arrays, np.isnan throws a TypeError
                # In this case, do nothing and proceed to checking if the entry is a bool object
                pass
            if isinstance(entry, bool):
                continue
            return False
        return True
    return False

def rematerialized_call(self, layer_call, *args, **kwargs):
        def compute_size(x):
            return (
                math.prod([d or 1 for d in x.shape])
                if isinstance(x, KerasTensor)
                else 0
            )

        # Full rematerialization
        if self._remat_mode.mode == "full":
            return remat.remat(layer_call)

        # Apply rematerialization to specific layers
        elif self._remat_mode.mode == "list_of_layers" and (
            self.name in self._remat_mode.layer_names
        ):
            return remat.remat(layer_call)

        # Apply rematerialization based on output size threshold
        elif self._remat_mode.mode == "larger_than":
            output_spec = self.compute_output_spec(*args, **kwargs)
            output_size = sum(
                tree.flatten(tree.map_structure(compute_size, output_spec))
            )
            if (
                output_size
                and output_size > self._remat_mode.output_size_threshold
            ):
                return remat.remat(layer_call)
        elif self._remat_mode.mode == "activations":
            has_activation = (
                hasattr(self, "activation") and self.activation is not None
            )
            if has_activation:

                @functools.wraps(layer_call)
                def rematerialized_activation_call_wrapper(*args, **kwargs):
                    original_activation = self.activation
                    self.activation = remat.remat(original_activation)
                    try:
                        return layer_call(*args, **kwargs)
                    finally:
                        self.activation = original_activation

                return rematerialized_activation_call_wrapper
        return layer_call

def getattr_migration(module_name: str) -> Callable[[str], Any]:
    def wrapper(name: str) -> object:
        """
        Raise a PrefectImportError if the object is not found, moved, or removed.
        """

        if name == "__path__":
            raise AttributeError(f"{module_name!r} object has no attribute {name!r}")
        import warnings

        from pydantic._internal._validators import import_string

        import_path = f"{module_name}:{name}"

        # Check if the attribute name corresponds to a moved or removed class or module
        if import_path in MOVED_IN_V3.keys():
            new_location = MOVED_IN_V3[import_path]
            warnings.warn(
                f"{import_path!r} has been moved to {new_location!r}. Importing from {new_location!r} instead. This warning will raise an error in a future release.",
                DeprecationWarning,
                stacklevel=2,
            )
            try:
                return import_string(new_location)
            except PydanticCustomError:
                return import_string_class_method(new_location)

        if import_path in REMOVED_IN_V3.keys():
            error_message = REMOVED_IN_V3[import_path]
            raise PrefectImportError(
                f"`{import_path}` has been removed. {error_message}"
            )

        globals: dict[str, Any] = sys.modules[module_name].__dict__
        if name in globals:
            return globals[name]

        raise AttributeError(f"module {module_name!r} has no attribute {name!r}")

    return wrapper

def add_token(token_list, word, token):
    if token is None and isinstance(word.id, int):
        raise AssertionError("Only expected word w/o token for 'extra' words")

    query_token = token_list.add()
    query_token.word = word.text
    query_token.value = word.text
    if word.lemma is not None:
        query_token.lemma = word.lemma
    if word.xpos is not None:
        query_token.pos = word.xpos
    if word.upos is not None:
        query_token.coarseTag = word.upos
    if word.feats and word.feats != "_":
        for feature in word.feats.split("|"):
            key, value = feature.split("=", maxsplit=1)
            query_token.conllUFeatures.key.append(key)
            query_token.conllUFeatures.value.append(value)
    if token is not None:
        if token.ner is not None:
            query_token.ner = token.ner
        if token is not None and len(token.id) > 1:
            query_token.mwtText = token.text
            query_token.isMWT = True
            query_token.isFirstMWT = token.id[0] == word.id
        if token.id[-1] != word.id:
            # if we are not the last word of an MWT token
            # we are absolutely not followed by space
            pass
        else:
            query_token.after = token.spaces_after

        query_token.index = word.id
    else:
        # presumably empty words won't really be written this way,
        # but we can still keep track of it
        query_token.after = misc_to_space_after(word.misc)

        query_token.index = word.id[0]
        query_token.emptyIndex = word.id[1]

    if word.misc and word.misc != "_":
        query_token.conllUMisc = word.misc
    if token is not None and token.misc and token.misc != "_":
        query_token.mwtMisc = token.misc

def partition_pauli_group(n_qubits: int) -> list[list[str]]:
    # Cover the case where n_qubits may be passed as a float
    if isinstance(n_qubits, float):
        if n_qubits.is_integer():
            n_qubits = int(n_qubits)

    # If not an int, or a float representing a int, raise an error
    if not isinstance(n_qubits, int):
        raise TypeError("Must specify an integer number of qubits.")

    if n_qubits < 0:
        raise ValueError("Number of qubits must be at least 0.")

    if n_qubits == 0:
        return [[""]]

    strings = set()  # tracks all the strings that have already been grouped
    groups = []

    # We know that I and Z always commute on a given qubit. The following generates all product
    # sequences of len(n_qubits) over "FXYZ", with F indicating a free slot that can be swapped for
    # the product over I and Z, and all other terms fixed to the given X/Y/Z. For example, if
    # ``n_qubits = 3`` our first value for ``string`` will be ``('F', 'F', 'F')``. We then expand
    # the product of I and Z over the three free slots, giving
    # ``['III', 'IIZ', 'IZI', 'IZZ', 'ZII', 'ZIZ', 'ZZI', 'ZZZ']``, which is our first group. The
    # next element of ``string`` will be ``('F', 'F', 'X')`` which we use to generate our second
    # group ``['IIX', 'IZX', 'ZIX', 'ZZX']``.
    for string in product("FXYZ", repeat=n_qubits):
        if string not in strings:
            num_free_slots = string.count("F")

            group = []
            commuting = product("IZ", repeat=num_free_slots)

            for commuting_string in commuting:
                commuting_string = list(commuting_string)
                new_string = tuple(commuting_string.pop(0) if s == "F" else s for s in string)

                if new_string not in strings:  # only add if string has not already been grouped
                    group.append("".join(new_string))
                    strings |= {new_string}

            if len(group) > 0:
                groups.append(group)

    return groups

def read_image_batch(self, s3_keys: list, delete_problematic_images: bool = False):
        batch = self.read_batch(s3_keys)
        output_images = []
        available_keys = []

        # Determine dataset type to handle ambiguous extensions (e.g., .mpeg is both audio and video)
        dataset_type = getattr(self, "dataset_type", None)
        try:
            dataset_type_enum = ensure_dataset_type(dataset_type, default=DatasetType.IMAGE)
        except ValueError:
            dataset_type_enum = DatasetType.IMAGE
        is_video_dataset = dataset_type_enum is DatasetType.VIDEO

        for s3_key, data in zip(s3_keys, batch):
            if data is None:
                logger.warning(f"Unable to load image '{s3_key}', skipping (no data).")
                continue
            try:
                # Check extension to decide loader
                ext = s3_key.rsplit(".", 1)[-1].lower() if "." in s3_key else ""
                buffer = BytesIO(data)

                is_video_extension = ext in video_file_extensions
                should_load_as_audio = dataset_type_enum is DatasetType.AUDIO or (
                    ext in audio_file_extensions and not is_video_extension
                )

                if should_load_as_audio and not is_video_dataset:
                    from simpletuner.helpers.audio import load_audio

                    image_data = load_audio(buffer)
                elif is_video_extension:
                    image_data = load_video(buffer)
                else:
                    image_data = load_image(buffer)

                if image_data is None:
                    logger.warning(f"Unable to load image '{s3_key}', skipping.")
                    continue
                output_images.append(image_data)
                available_keys.append(s3_key)
            except Exception as e:
                if delete_problematic_images:
                    logger.warning(f"Deleting image '{s3_key}' due to error: {e}")
                    self.delete(s3_key)
                else:
                    logger.warning(f"Problematic image/video {s3_key} encountered: {e}")

        return (available_keys, output_images)

def emit_event(
    event: str,
    resource: dict[str, str],
    occurred: datetime.datetime | None = None,
    related: list[dict[str, str]] | list[RelatedResource] | None = None,
    payload: dict[str, Any] | None = None,
    id: UUID | None = None,
    follows: Event | None = None,
    **kwargs: dict[str, Any] | None,
) -> Event | None:
    if not should_emit_events():
        return None

    try:
        operational_clients = [
            AssertingPassthroughEventsClient,
            AssertingEventsClient,
            PrefectCloudEventsClient,
            PrefectEventsClient,
            ProcessPoolForwardingEventsClient,
        ]
        worker_instance = EventsWorker.instance()

        if worker_instance.client_type not in operational_clients:
            return None

        event_kwargs: dict[str, Any] = {
            "event": event,
            "resource": resource,
            **kwargs,
        }

        if occurred is None:
            occurred = prefect.types._datetime.now("UTC")
        event_kwargs["occurred"] = occurred

        if related is not None:
            event_kwargs["related"] = related

        if payload is not None:
            event_kwargs["payload"] = payload

        if id is not None:
            event_kwargs["id"] = id

        if follows is not None:
            if -TIGHT_TIMING < (occurred - follows.occurred) < TIGHT_TIMING:
                event_kwargs["follows"] = follows.id

        event_obj = Event(**event_kwargs)

        max_size = get_current_settings().server.events.maximum_size_bytes
        if event_obj.size_bytes > max_size:
            raise EventTooLarge(event_obj.size_bytes, max_size)

        worker_instance.send(event_obj)

        return event_obj
    except EventTooLarge:
        raise
    except Exception:
        logger.exception(f"Error emitting event: {event}")
        return None

def keras_serializable(cls):
    initializer = cls.__init__

    config_class = getattr(cls, "config_class", None)
    if config_class is None:
        raise AttributeError("Must set `config_class` to use @keras_serializable")

    @functools.wraps(initializer)
    def wrapped_init(self, *args, **kwargs):
        config = args[0] if args and isinstance(args[0], PretrainedConfig) else kwargs.pop("config", None)

        if isinstance(config, dict):
            config = config_class.from_dict(config)
            initializer(self, config, *args, **kwargs)
        elif isinstance(config, PretrainedConfig):
            if len(args) > 0:
                initializer(self, *args, **kwargs)
            else:
                initializer(self, config, *args, **kwargs)
        else:
            raise ValueError("Must pass either `config` (PretrainedConfig) or `config` (dict)")

        self._config = config
        self._kwargs = kwargs

    cls.__init__ = wrapped_init

    if not hasattr(cls, "get_config"):
        raise TypeError("Only use @keras_serializable on tf.keras.layers.Layer subclasses")
    if hasattr(cls.get_config, "_is_default"):

        def get_config(self):
            cfg = super(cls, self).get_config()
            cfg["config"] = self._config.to_dict()
            cfg.update(self._kwargs)
            return cfg

        cls.get_config = get_config

    cls._keras_serializable = True
    if hasattr(tf.keras.utils, "register_keras_serializable"):
        cls = tf.keras.utils.register_keras_serializable()(cls)
    return cls

def dataframe(
        self,
        include_props: bool = True,
        include_params: bool = True,
    ) -> 'DataFrame':
        data = {
            'hash': self.hash,
        }

        if include_props:
            # TODO [GA]: Auto collect props based on StructuredRunMixin:
            #  - Exclude created_at, updated_at, finalized_at auto-populated fields
            #  - Collect list of representations in case of ModelMappedCollection's
            data['name'] = self.props.name
            data['description'] = self.props.description
            data['archived'] = self.props.archived
            data['creation_time'] = self.props.creation_time
            data['end_time'] = self.end_time
            data['active'] = self.active
            data['experiment'] = self.props.experiment
            data['tags'] = json.dumps(self.props.tags)

        if include_params:
            # TODO [GA]:
            #  - Move run params collection to utility function
            #  - Remove code duplication from Metric.dataframe
            for path, val in treeutils.unfold_tree(self[...], unfold_array=False, depth=3):
                s = ''
                for key in path:
                    if isinstance(key, str):
                        s += f'.{key}' if len(s) else f'{key}'
                    else:
                        s += f'[{key}]'

                if isinstance(val, (tuple, list, dict)):
                    val = json.dumps(val)
                if s not in data.keys():
                    data[s] = val

        import pandas as pd

        df = pd.DataFrame(data, index=[0])
        return df

def visit_Call(self, node: ast.Call) -> None:
        for keyword in node.keywords:
            if keyword.arg == "trust_remote_code":
                self._add(node, "`trust_remote_code` must not be passed as a keyword argument.")

            elif keyword.arg is None:
                value = keyword.value

                if isinstance(value, ast.Dict):
                    for key in value.keys:
                        if isinstance(key, ast.Constant) and key.value == "trust_remote_code":
                            self._add(node, "`trust_remote_code` must not be passed through `**kwargs`.")

                elif isinstance(value, ast.Call):
                    if isinstance(value.func, ast.Name) and value.func.id == "dict":
                        for kw in value.keywords:
                            if kw.arg == "trust_remote_code":
                                self._add(
                                    node,
                                    "`trust_remote_code` must not be passed through `**kwargs` (dict constructor).",
                                )

        self.generic_visit(node)

def parse_args_info(self, args: List[str], options):
        installed_package = []

        # the case of install with requirements
        if len(args) == 0:
            src_dir = options.src_dir
            requirements = options.requirements
            for requirement in requirements:
                package_info = {
                    'name': requirement,
                    'url': os.path.join(src_dir, requirement),
                    'desc': '',
                    'version': ''
                }

                installed_package.append(package_info)

        def get_package_info(package_name):
            from pathlib import Path
            package_info = {
                'name': package_name,
                'url': options.index_url,
                'desc': ''
            }

            # the case with git + http
            if package_name.split('.')[-1] == 'git':
                package_name = Path(package_name).stem

            plugin_installed, version = self.check_plugin_installed(
                package_name)
            if plugin_installed:
                package_info['version'] = version
                package_info['name'] = package_name
            else:
                logger.warning(
                    f'The package {package_name} is not in the lib, this might be happened'
                    f' when installing the package with git+https method, should be ignored'
                )
                package_info['version'] = ''

            return package_info

        for package in args:
            package_info = get_package_info(package)
            installed_package.append(package_info)

        return installed_package

def get(self, tag: Tag | str) -> Item:
        _tag = Tag.from_taglike(tag)
        if _tag.version is None or _tag.version == "latest":
            try:
                _tag.version = (self._path / _tag.latest_path()).read_text().strip()

                if not (self._path / _tag.path()).exists():
                    self._recreate_latest(_tag)
            except OSError:
                self._recreate_latest(_tag)

        path = _tag.path()
        if (self._path / path).exists():
            return self._get_item(_tag)

        matches = list(p for p in self._path.glob(f"{path}*/") if p.is_dir())
        if len(matches) == 1:
            return self._get_item(Tag(_tag.name, matches[0].name))
        elif len(matches) > 1:
            vers = [p.name for p in matches]
            raise BentoMLException(
                f"Multiple {_tag.name} versions found: {', '.join(vers)}"
            )
        # No match found
        cmd = (
            "bentoml models pull"
            if self._item_type.get_typename() == "Model"
            else "bentoml pull"
        )
        raise NotFound(
            f"{self._item_type.get_typename()} '{tag}' is not found in BentoML store {self._path}, "
            f"you may need to run `{cmd}` first"
        )

def to_dict(self):
        # Exclude non-init fields (they aren't user-facing config)
        d = {field.name: getattr(self, field.name) for field in fields(self) if field.init}

        for k, v in d.items():
            if isinstance(v, Enum):
                d[k] = v.value
            if isinstance(v, list) and len(v) > 0 and isinstance(v[0], Enum):
                d[k] = [x.value for x in v]
            if k.endswith("_token"):
                d[k] = f"<{k.upper()}>"
            # Serialize AcceleratorConfig to dict
            if is_accelerate_available() and isinstance(v, AcceleratorConfig):
                d[k] = v.to_dict()
            # Serialize quantization_config if nested inside model_init_kwargs
            if k == "model_init_kwargs" and isinstance(v, dict) and "quantization_config" in v:
                quantization_config = v.get("quantization_config")
                if quantization_config and not isinstance(quantization_config, dict):
                    d[k]["quantization_config"] = quantization_config.to_dict()
            if k == "parallelism_config" and v is not None:
                d[k] = v.to_json()

        self._dict_dtype_to_str(d)

        return d

def multifactor(factors='constant * linear_warmup * rsqrt_decay',
                constant=0.1,  # pylint: disable=redefined-outer-name
                warmup_steps=400,
                decay_factor=0.5,
                steps_per_decay=20000,
                steps_per_cycle=100000,
                second_constant=0.01,
                second_constant_step=10000,
                minimum=0):
  factors = [n.strip() for n in factors.split('*')]

  def learning_rate(step):
    """Step to learning rate function."""
    ret = 1.0
    for name in factors:
      if name == 'constant':
        ret *= constant
      elif name == 'two_constants':
        if step < second_constant_step:
          ret *= constant
        else:
          ret *= second_constant
      elif name == 'linear_warmup':
        ret *= jnp.minimum(1.0, step / warmup_steps)
      elif name == 'rsqrt_decay':
        ret /= jnp.sqrt(jnp.maximum(step, warmup_steps))
      elif name == 'rsqrt_normalized_decay':
        ret *= jnp.sqrt(warmup_steps)
        ret /= jnp.sqrt(jnp.maximum(step, warmup_steps))
      elif name == 'decay_every':
        ret *= (decay_factor ** (step//steps_per_decay))
      elif name == 'cosine_decay':
        progress = jnp.maximum(
            0.0, (step - warmup_steps) / float(steps_per_cycle))
        ret *= (0.5 * (1.0 + jnp.cos(jnp.pi * (progress % 1.0))))
      else:
        raise ValueError('Unknown factor %s.' % name)
    # TODO(henrykm): return float(jnp.max(minimum, ret)) would be
    # better but causes TypeError: 'numpy.float64' object cannot
    # be interpreted as an integer
    if ret <= minimum:
      return minimum
    return ret

  return learning_rate

def slice_indexer(self, start=None, end=None, step=None):
        # For historical reasons DatetimeIndex supports slices between two
        # instances of datetime.time as if it were applying a slice mask to
        # an array of (self.hour, self.minute, self.seconds, self.microsecond).
        if isinstance(start, dt.time) and isinstance(end, dt.time):
            if step is not None and step != 1:
                raise ValueError("Must have step size of 1 with time slices")
            return self.indexer_between_time(start, end)

        if isinstance(start, dt.time) or isinstance(end, dt.time):
            raise KeyError("Cannot mix time and non-time slice keys")

        def check_str_or_none(point) -> bool:
            return point is not None and not isinstance(point, str)

        # GH#33146 if start and end are combinations of str and None and Index is not
        # monotonic, we can not use Index.slice_indexer because it does not honor the
        # actual elements, is only searching for start and end
        if (
            check_str_or_none(start)
            or check_str_or_none(end)
            or self.is_monotonic_increasing
        ):
            return Index.slice_indexer(self, start, end, step)

        mask = np.array(True)
        in_index = True
        if start is not None:
            start_casted = self._maybe_cast_slice_bound(start, "left")
            mask = start_casted <= self
            in_index &= (start_casted == self).any()

        if end is not None:
            end_casted = self._maybe_cast_slice_bound(end, "right")
            mask = (self <= end_casted) & mask
            in_index &= (end_casted == self).any()

        if not in_index:
            raise KeyError(
                "Value based partial slicing on non-monotonic DatetimeIndexes "
                "with non-existing keys is not allowed.",
            )
        indexer = mask.nonzero()[0][::step]
        if len(indexer) == len(self):
            return slice(None)
        else:
            return indexer

def guess_language(self, text, return_all=False):
        self.last_distances = self.lang_dists(text)
        if not self.last_distances:
            if return_all:
                return []
            return None
        min_dist = min(self.last_distances.values())
        candidates = [
            lang for lang, dist in self.last_distances.items() if dist == min_dist
        ]
        all_languages = list(self.last_distances.keys())

        # Special case: all languages match equally (uninformative), return empty list/None
        if len(candidates) == len(all_languages):
            if return_all:
                return []
            return None

        if return_all:
            return candidates
        if len(candidates) == 1:
            return candidates[0]
        return None

def validate_expression(expression: str, target: int, numbers: list[int]) -> bool:
        if not re.fullmatch(r"[\d\s\+\-\*/\(\)\.]+", expression):
            return False
        used = [int(n) for n in re.findall(r"\d+", expression)]
        available = list(numbers)
        for n in used:
            if n in available:
                available.remove(n)
            else:
                return False
        try:
            result = eval(expression)  # noqa: S307
        except Exception:
            return False
        return abs(result - target) < 1e-9

def relax_assert_op(condition: tvm.Object, format_str: str, *format_args: tvm.Object) -> None:
    if not isinstance(format_str, str):
        raise ValueError(
            f"The format string argument to assert must be a string, given {type(format_str)})"
        )

    if isinstance(condition, bool | int):
        val = condition
    elif isinstance(condition, tvm.runtime.Tensor):
        # may happen if the original program had unknown shape or dtype for the tensor's type
        dtype = condition.dtype
        if dtype != "bool":
            raise ValueError(f"The condition must be a bool scalar, but given a {dtype} tensor")
        shape = condition.shape
        if len(shape) != 0:
            raise ValueError(f"The condition must be a scalar, but it has a shape of {shape}")

        val = condition.numpy()

    else:
        # should be guaranteed by the type system
        raise ValueError(
            f"The condition for relax assert must be a bool, int, or Tensor, "
            f"but received a {type(condition)}."
        )

    if not val:
        error_message = "Assertion Failed"
        if format_args or format_str != "":
            rendered = map(render_object, format_args)
            if format_str != "":
                error_message = format_str.format(*rendered)
            else:
                error_message = ", ".join(rendered)
        raise AssertionError(error_message)

def validate_schema_field(
    field: Dict, object_fields: Dict[str, ObjectField], action: str, stream_name: str
):
    field_name, field_type = field
    sf_field: ObjectField = object_fields.get(field_name)

    if field_name.startswith("_sdc_"):
        return

    if field_name == "Id":
        if action == "insert":
            raise InvalidStreamSchema(
                f"Id is not createable and should not be included on insert"
            )
        else:
            return

    if not sf_field:
        raise InvalidStreamSchema(f"{field_name} does not exist in your {stream_name} Object")

    if action in ["update", "upsert"]:
        if not sf_field.updateable:
            raise InvalidStreamSchema(
                f"{field_name} is not updatable for your {stream_name} Object, invalid for {action} action"
            )

    if action in ["insert", "upsert"]:
        if not sf_field.createable:
            raise InvalidStreamSchema(
                f"{field_name} is not creatable for your {stream_name} Object, invalid for {action} action"
            )

    if action in ["delete", "hard_delete"]:
        raise InvalidStreamSchema(
            f"Schema for the {action} action should only include Id"
        )

def categorical_crossentropy(target, output, from_logits=False, axis=-1):
    target = tf.convert_to_tensor(target)
    output = tf.convert_to_tensor(output)

    if len(target.shape) < 1:
        raise ValueError(
            "Arguments `target` and `output` must be at least rank 1. "
            "Received: "
            f"target.shape={target.shape}, output.shape={output.shape}"
        )
    if len(target.shape) != len(output.shape):
        raise ValueError(
            "Arguments `target` and `output` must have the same rank "
            "(ndim). Received: "
            f"target.shape={target.shape}, output.shape={output.shape}"
        )
    for e1, e2 in zip(target.shape, output.shape):
        if e1 is not None and e2 is not None and e1 != e2:
            raise ValueError(
                "Arguments `target` and `output` must have the same shape. "
                "Received: "
                f"target.shape={target.shape}, output.shape={output.shape}"
            )

    output, from_logits = _get_logits(
        output, from_logits, "Softmax", "categorical_crossentropy"
    )
    if from_logits:
        return tf.nn.softmax_cross_entropy_with_logits(
            labels=target, logits=output, axis=axis
        )

    # Adjust the predictions so that the probability of
    # each class for every sample adds up to 1
    # This is needed to ensure that the cross entropy is
    # computed correctly.
    output = output / tf.reduce_sum(output, axis, keepdims=True)

    # Compute cross entropy from probabilities.
    output = tf.clip_by_value(
        output, backend.epsilon(), 1.0 - backend.epsilon()
    )
    return -tf.reduce_sum(target * tf.math.log(output), axis)

def check_and_copy(
        self,
        source: Path,
        source_checksum: str | None,
        target: Path,
    ) -> None:

        target = target.resolve()
        if target in self.files_in_export_dir:
            self.files_in_export_dir.remove(target)

        perform_copy = False

        if target.exists():
            source_stat = source.stat()
            target_stat = target.stat()
            if self.compare_checksums and source_checksum:
                target_checksum = compute_checksum(target)
                perform_copy = target_checksum != source_checksum
            elif (
                source_stat.st_mtime != target_stat.st_mtime
                or source_stat.st_size != target_stat.st_size
            ):
                perform_copy = True
        else:
            # Copy if it does not exist
            perform_copy = True

        if perform_copy:
            target.parent.mkdir(parents=True, exist_ok=True)
            copy_file_with_basic_stats(source, target)

def is_compatible_type(t1: AnyType, t2: AnyType) -> bool:
    if get_origin(t1) is t.Union:
        return any((is_compatible_type(t2, arg_type) for arg_type in get_args(t1)))

    if get_origin(t2) is t.Union:
        return any((is_compatible_type(t1, arg_type) for arg_type in get_args(t2)))

    if isinstance(t1, LazyType):
        t1 = t1.get_class()

    if isinstance(t2, LazyType):
        t2 = t2.get_class()

    if isinstance(t1, type) and isinstance(t2, type):
        return issubclass(t1, t2) or issubclass(t2, t1)

    # catchall return true in unsupported cases so we don't error on unsupported types
    return True

def process_image(
        self,
        image: ImageInput,
        do_convert_rgb: bool | None = None,
        input_data_format: str | ChannelDimension | None = None,
        device: Optional["torch.device"] = None,
        **kwargs: Unpack[ImagesKwargs],
    ) -> "torch.Tensor":
        image_type = get_image_type(image)
        if image_type not in [ImageType.PIL, ImageType.TORCH, ImageType.NUMPY]:
            raise ValueError(f"Unsupported input image type {image_type}")

        if do_convert_rgb:
            image = self.convert_to_rgb(image)

        if image_type == ImageType.PIL:
            image = tvF.pil_to_tensor(image)
        elif image_type == ImageType.NUMPY:
            image = torch.from_numpy(image).contiguous()

        if image.ndim == 2:
            image = image.unsqueeze(0)

        if input_data_format is None:
            input_data_format = infer_channel_dimension_format(image)

        if input_data_format == ChannelDimension.LAST:
            image = image.permute(2, 0, 1).contiguous()

        if device is not None:
            image = image.to(device)

        return image

def validate_or_set_default_sorting_params(
    sort_by_options: List[str] = [],
    default_sort_by_option: str = "",
    default_sort_order: str = "asc",
) -> Callable:

    def set_input_or_default(
        sort_by: Optional[str] = Query(None), sort_order: Optional[str] = Query(None)
    ) -> dict:
        sorting_params = {}

        # If no sort options are configured, return defaults without validation
        if not sort_by_options:
            return {
                "sort_by": default_sort_by_option,
                "sort_order": sort_order if sort_order else default_sort_order,
            }

        # Validate and set sort_by parameter
        if sort_by:
            if sort_by in sort_by_options:
                sorting_params["sort_by"] = sort_by
            else:
                raise HTTPException(
                    status_code=400,
                    detail=f"Invalid sort_by parameter: '{sort_by}'. Valid options are: {sort_by_options}",
                )
        else:
            # Use default if not provided
            sorting_params["sort_by"] = default_sort_by_option

        # Validate and set sort_order parameter
        if sort_order:
            if sort_order in ["asc", "desc"]:
                sorting_params["sort_order"] = sort_order
            else:
                raise HTTPException(
                    status_code=400,
                    detail=f"Invalid sort_order parameter: '{sort_order}'. Valid options are: ['asc', 'desc']",
                )
        else:
            # Use default if not provided
            sorting_params["sort_order"] = default_sort_order

        return sorting_params

    return set_input_or_default

def encode(
        self,
        input_values: torch.Tensor,
        bandwidth: float | None = None,
        return_dict: bool | None = None,
    ) -> torch.Tensor | HiggsAudioV2TokenizerEncoderOutput:
        return_dict = return_dict if return_dict is not None else self.config.return_dict

        channels = input_values.shape[1]
        if channels != 1:
            raise ValueError(f"Audio must be mono, but got {channels}")

        if bandwidth is None:
            bandwidth = self.config.target_bandwidths[-1]
        elif bandwidth not in self.config.target_bandwidths:
            raise ValueError(
                f"This model doesn't support the bandwidth {bandwidth}. Select one of {self.config.target_bandwidths}."
            )

        e_semantic_input = self._extract_semantic_features(input_values).detach()
        e_semantic = self.encoder_semantic(e_semantic_input.transpose(1, 2))

        # original codebase infer to get the output length, but we can directly infer it
        # from the model and know whether we should pad
        if self._get_conv1d_output_lengths(input_values.shape[2], self.acoustic_encoder) != e_semantic.shape[2]:
            e_acoustic = self.acoustic_encoder(F.pad(input_values, (self.pad, self.pad)))
        else:
            e_acoustic = self.acoustic_encoder(input_values)

        embeddings = torch.cat([e_acoustic.to(e_semantic.device), e_semantic], dim=1)
        embeddings = self.fc(embeddings.transpose(1, 2)).transpose(1, 2)
        audio_codes = self.quantizer.encode(embeddings, bandwidth)
        audio_codes = audio_codes.transpose(0, 1)

        if not return_dict:
            return audio_codes

        return HiggsAudioV2TokenizerEncoderOutput(audio_codes)

def categorize_entries(
    entries: list[CategorizedEntry],
) -> dict[str, list[CategorizedEntry]]:
    # TODO: Could add more or be more granular
    categories = {
        "breaking": [],
        "bug": [],
        "enhancement": [],
        "documentation": [],
        "preview": [],
        "other": [],
        "highlights": [],
    }

    for entry in entries:
        if entry.pr is None:
            categories["other"].append(entry)
            continue

        label_names = {label.name for label in entry.pr.labels}

        # Skip entries labeled as "internal"
        if "internal" in label_names:
            continue

        if "release-highlight" in label_names:
            categories["highlights"].append(entry)

        if "breaking" in label_names:
            categories["breaking"].append(entry)
        elif "preview" in label_names:
            categories["preview"].append(entry)
        elif "bug" in label_names:
            categories["bug"].append(entry)
        elif "enhancement" in label_names:
            categories["enhancement"].append(entry)
        elif "documentation" in label_names:
            categories["documentation"].append(entry)
        else:
            categories["other"].append(entry)

    return categories

def named_components(
        self,
        memo: Optional[Set["Component"]] = None,
        prefix: str = "",
        remove_duplicate: bool = True,
        grad_component_only: bool = False,
    ):
        from adalflow.optim.grad_component import GradComponent

        if memo is None:
            memo = set()
        if self not in memo:
            if remove_duplicate:
                memo.add(self)
            if grad_component_only and isinstance(self, GradComponent):
                yield prefix, self
            elif not grad_component_only:
                yield prefix, self
            for name, component in self._components.items():
                if component is None:
                    continue
                if grad_component_only and not isinstance(component, GradComponent):
                    continue

                subcomponent_prefix = prefix + ("." if prefix else "") + name
                yield from component.named_components(
                    memo,
                    subcomponent_prefix,
                    remove_duplicate,
                    grad_component_only=grad_component_only,
                )

def block_cumsum(
        ty: T.int64,
        tx: T.int64,
        source_local: T.Buffer,
        output_shared: T.Buffer,
    ):
        # Inclusive scan inside thread
        for i in T.unroll(1, thread_elem):
            source_local[i] += source_local[i - 1]
        # Store data to shared memory
        for i in T.vectorized(thread_elem):
            output_shared[ty * warp_elem + tx * thread_elem + i] = source_local[i]
        # Inclusive scan inside warp
        for i in T.unroll(LOG_TX):
            for j in T.vectorized(thread_elem):
                idx: T.int64 = ty * warp_elem + tx * thread_elem
                if tx >= (1 << i):
                    output_shared[idx + j] += output_shared[
                        idx - (1 << i) * thread_elem + thread_elem - 1
                    ]
        # Inclusive scan inside block
        for i in T.unroll(1, TY):
            for j in T.vectorized(thread_elem):
                if ty == 0:
                    idx: T.int64 = i * warp_elem + tx * thread_elem
                    output_shared[idx + j] += output_shared[i * warp_elem - 1]

def set_activation_dtype(self, inp: torch.Tensor) -> None:
        # Native AMP (`torch.autocast`) gets highest priority
        if torch.is_autocast_enabled():
            self.fast_setattr("activation_dtype", torch_get_autocast_gpu_dtype())
            return
        dtype = inp.dtype
        # All checks after this have already been performed once, thus skip
        if self.activation_dtype == dtype:
            return

        if not self.allow_different_data_and_param_types:
            for name, param in self.named_parameters():
                if param is not None:
                    if dtype != param.dtype:
                        raise TypeError(
                            "Data types for parameters must match when outside of autocasted "
                            f"region. Found input dtype: {dtype} and {name!r} dtype: {param.dtype}"
                        )
        self.fast_setattr("activation_dtype", dtype)

def flatten_grouping(grouping, schema=None):
    stack = []
    result = []

    # Avoid repeated recursive Python calls by using an explicit stack
    push = stack.append
    pop = stack.pop

    # Only validate once at the top if schema is provided
    if schema is None:
        schema = grouping
    else:
        validate_grouping(grouping, schema)

    push((grouping, schema))
    while stack:
        group, sch = pop()
        # Inline isinstance checks for perf
        typ = type(sch)
        if typ is tuple or typ is list:
            # Avoid double recursion / excessive list construction
            for ge, se in zip(group, sch):
                push((ge, se))
        elif typ is dict:
            for k in sch:
                push((group[k], sch[k]))
        else:
            result.append(group)
    result.reverse()  # Since we LIFO, leaf values are in reverse order
    return result

def single_source_shortest_path_length(graph, source, *, cutoff=None):
    if sparse.issparse(graph):
        graph = graph.tolil()
    else:
        graph = sparse.lil_array(graph)
    seen = {}  # level (number of hops) when seen in BFS
    level = 0  # the current level
    next_level = [source]  # dict of nodes to check at next level
    while next_level:
        this_level = next_level  # advance to next level
        next_level = set()  # and start a new list (fringe)
        for v in this_level:
            if v not in seen:
                seen[v] = level  # set the level of vertex v
                next_level.update(graph.rows[v])
        if cutoff is not None and cutoff <= level:
            break
        level += 1
    return seen  # return all path lengths as dictionary

def forecast(
        self,
        y: np.ndarray,
        h: int,
        X: Optional[np.ndarray] = None,
        X_future: Optional[np.ndarray] = None,
        level: Optional[List[int]] = None,
        fitted: bool = False,
    ):
        y = _ensure_float(y)
        mod = tbats_selection(
            y=y,
            seasonal_periods=self.season_length,
            use_boxcox=self.use_boxcox,
            bc_lower_bound=self.bc_lower_bound,
            bc_upper_bound=self.bc_upper_bound,
            use_trend=self.use_trend,
            use_damped_trend=self.use_damped_trend,
            use_arma_errors=self.use_arma_errors,
        )
        fcst = tbats_forecast(mod, h)
        res = {"mean": fcst["mean"]}
        if fitted:
            res["fitted"] = mod["fitted"].ravel()
        if level is not None:
            level = sorted(level)
            sigmah = _compute_sigmah(mod, h)
            pred_int = _calculate_intervals(res, level, h, sigmah)
            res = {**res, **pred_int}
            if fitted:
                se = _calculate_sigma(mod["errors"], mod["errors"].shape[1])
                fitted_pred_int = _add_fitted_pi(res, se, level)
                res = {**res, **fitted_pred_int}
        if mod["BoxCox_lambda"] is not None:
            res_trans = {k: inv_boxcox(v, mod["BoxCox_lambda"]) for k, v in res.items()}
            for k, v in res_trans.items():
                res_trans[k] = np.where(np.isnan(v), res[k], v)
        else:
            res_trans = res
        return res_trans

def keycombos_to_frozensets(
    handler: rio.EventHandler | t.Mapping[KeyCombination, rio.EventHandler],
) -> rio.EventHandler | t.Mapping[frozenset[SoftwareKey], rio.EventHandler]:
    if handler is None:
        return handler

    if callable(handler):
        return handler

    result = dict[frozenset[SoftwareKey], rio.EventHandler]()

    for key_combination, handler in handler.items():
        if isinstance(key_combination, str):
            key_combination = t.cast(list[SoftwareKey], [key_combination])

        frozen_combination = frozenset(key_combination)
        if len(frozen_combination) != len(key_combination):
            raise ValueError(
                f"Duplicate key in key combination: {key_combination}"
            )

        for key in key_combination:
            if key in NAMED_SOFTWARE_KEYS:
                continue

            if len(key) != 1:
                raise ValueError(f"Invalid key in key combination: {key!r}")

            # if not key.islower():
            #     raise ValueError(
            #         f"Invalid key in key combination: {key!r} (Keys must be lower case)"
            #     )

        result[frozen_combination] = handler

    return result

def filter(data,
           max_length=10240,
           min_length=10,
           token_max_length=200,
           token_min_length=1,
           min_output_input_ratio=0.0005,
           max_output_input_ratio=1,
           mode='train'):
    for sample in data:
        sample['speech'], sample['sample_rate'] = torchaudio.load(BytesIO(sample['audio_data']))
        sample['speech'] = sample['speech'].mean(dim=0, keepdim=True)
        del sample['audio_data']
        # sample['wav'] is torch.Tensor, we have 100 frames every second
        num_frames = sample['speech'].size(1) / sample['sample_rate'] * 100
        if num_frames < min_length:
            continue
        if num_frames > max_length:
            continue
        if len(sample['text_token']) < token_min_length:
            continue
        if len(sample['text_token']) > token_max_length:
            continue
        if len(sample['speech_token']) == 0:
            continue
        if 'reject_speech_token' in sample and len(sample['reject_speech_token']) == 0:
            continue
        if num_frames != 0:
            if len(sample['text_token']) / num_frames < min_output_input_ratio:
                continue
            if len(sample['text_token']) / num_frames > max_output_input_ratio:
                continue
        yield sample

def forward(self, *args, **kwargs):
        with torch.no_grad():
            new_samples = self.sampler(*args, **kwargs)
            # Store samples
            self.source_samples.append(new_samples)
            self.source_samples = self.source_samples[self.source_samples_slice]
            if self.samples is None:
                # First set of samples
                self.samples = new_samples.clone()
                self.transition_count = torch.zeros_like(
                    new_samples.log_weights, dtype=torch.long
                )
            else:
                # Apply Metropolis-Hastings algorithm
                prob = torch.clamp(
                    new_samples.log_weights - self.samples.log_weights, max=0.0
                ).exp()
                idx = torch.rand(*prob.shape) <= prob
                self.transition_count[idx] += 1
                for field_desc in fields(self.samples):
                    field, new_field = getattr(self.samples, field_desc.name), getattr(
                        new_samples, field_desc.name
                    )
                    if isinstance(field, dict):
                        for key in field:
                            field[key][idx] = new_field[key][idx]
                    else:
                        field[idx] = new_field[idx]
        self.stored_samples.append(self.samples.clone())
        self.stored_samples = self.stored_samples[self.stored_samples_slice]
        return self.samples

def allreduce_grads_naive(all_grads, devices=None, average=True):
    if devices is not None:
        assert isinstance(devices, list), devices
        # device_setter = LeastLoadedDeviceSetter(None, devices)

    nr_tower = len(all_grads)
    if nr_tower == 1:
        return all_grads[0]

    def aggregate(grads):
        if average:
            return tf.multiply(tf.add_n(grads), 1.0 / nr_tower)
        else:
            return tf.add_n(grads)

    grads_ret = []  # N(rev) grads
    # reverse so the device placement makes the last part of model more balance?
    all_grads_rev = [x[::-1] for x in all_grads]   # K x N(rev)

    for idx, grads in enumerate(zip(*all_grads_rev)):
        # grads: K tensors
        if devices is None:
            grad = aggregate(grads)
        else:
            # dev = device_setter.place_with_balance(v.op)
            dev = devices[idx % len(devices)]
            with tf.device(dev):
                grad = aggregate(grads)
        grads_ret.append(grad)
    grads_ret = grads_ret[::-1]
    return grads_ret

