def create_or_merge(cls, owner, duplicate_type, photos, similarity_score=None):
        photo_list = list(photos)
        if len(photo_list) < 2:
            return None

        # Check if any photo is already in a duplicate group of the same type
        existing_duplicates = cls.objects.filter(
            photos__in=photo_list,
            duplicate_type=duplicate_type,
            owner=owner,
        ).distinct()

        if existing_duplicates.exists():
            # Merge all into the first existing duplicate group
            target_duplicate = existing_duplicates.first()
            for duplicate in existing_duplicates[1:]:
                target_duplicate.merge_with(duplicate)

            # Add any new photos to the group (ManyToMany)
            for photo in photo_list:
                if not photo.duplicates.filter(pk=target_duplicate.pk).exists():
                    photo.duplicates.add(target_duplicate)

            target_duplicate.calculate_potential_savings()
            return target_duplicate
        else:
            # Create new duplicate group
            duplicate = cls.objects.create(
                owner=owner,
                duplicate_type=duplicate_type,
                similarity_score=similarity_score,
            )

            # Associate photos (ManyToMany)
            for photo in photo_list:
                photo.duplicates.add(duplicate)

            duplicate.calculate_potential_savings()
            return duplicate

def gaussian_attack(ordered_results, states, **kwargs):
    magnitude = kwargs.get("magnitude", 0.0)
    dataset_name = kwargs.get("dataset_name", "no name")
    results = ordered_results.copy()

    def perturbate(vect):
        return vect + np.random.normal(loc=0, scale=magnitude, size=vect.size)

    for proxy, fitres in ordered_results:
        if states[fitres.metrics["cid"]]:
            params = parameters_to_ndarrays(fitres.parameters)
            if dataset_name == "income":
                new_params = [perturbate(layer) for layer in params]
            else:
                new_params = []
                for par in params:
                    # if par is an array of one element, it is a scalar
                    if par.size == 1:
                        new_params.append(perturbate(par))
                    else:
                        new_params.append(np.apply_along_axis(perturbate, 0, par))
            fitres.parameters = ndarrays_to_parameters(new_params)
            results[int(fitres.metrics["cid"])] = (proxy, fitres)
    return results, {}

def get_size_with_aspect_ratio_yolos(
    image_size: tuple[int, int], size: int, max_size: int | None = None, mod_size: int = 16
) -> tuple[int, int]:
    height, width = image_size
    raw_size = None
    if max_size is not None:
        min_original_size = float(min((height, width)))
        max_original_size = float(max((height, width)))
        if max_original_size / min_original_size * size > max_size:
            raw_size = max_size * min_original_size / max_original_size
            size = int(round(raw_size))

    if width < height:
        ow = size
        if max_size is not None and raw_size is not None:
            oh = int(raw_size * height / width)
        else:
            oh = int(size * height / width)
    elif (height <= width and height == size) or (width <= height and width == size):
        oh, ow = height, width
    else:
        oh = size
        if max_size is not None and raw_size is not None:
            ow = int(raw_size * width / height)
        else:
            ow = int(size * width / height)

    if mod_size is not None:
        ow = ow - (ow % mod_size)
        oh = oh - (oh % mod_size)

    return (oh, ow)

def remove(self, obj: BoundTransform | Transform):
        if not isinstance(obj, (Transform, BoundTransform)):
            raise TypeError("Only BoundTransform or Transform can be removed.")

        i = len(self) - 1
        while i >= 0:
            # pylint: disable=protected-access
            if (isinstance(obj, Transform) and obj == self[i]._transform) or self[i] == obj:
                removed = self._compile_pipeline.pop(i)
                self._markers = {k: (v - 1 if v > i else v) for k, v in self._markers.items()}

                # Remove the associated expand_transform if present
                if i > 0 and removed.expand_transform == self[i - 1]:
                    self._compile_pipeline.pop(i - 1)
                    self._markers = {
                        k: (v - 1 if v > i - 1 else v) for k, v in self._markers.items()
                    }
                    i -= 1
            i -= 1

def get_sections_for_tab(self, tab: str) -> List[Dict[str, Any]]:
        sections = {}
        fields = self.get_fields_for_tab(tab)

        for cfg_field in fields:
            if cfg_field.section not in sections:
                sections[cfg_field.section] = {
                    "id": cfg_field.section,
                    "title": cfg_field.section.replace("_", " ").title(),
                    "subsections": set(),
                    "empty_message": None,
                }
            if cfg_field.subsection:
                sections[cfg_field.section]["subsections"].add(cfg_field.subsection)

        # Convert sets to lists
        for section_id, section in sections.items():
            section["subsections"] = sorted(list(section["subsections"]))
            if section_id == "text_encoder_training":
                section["empty_message"] = "This model does not support text encoder training."

        return list(sections.values())

def generate_badge_json(history: list[dict], output_file: Path) -> None:
    if not history:
        badge_data = {
            "schemaVersion": 1,
            "label": "nightly",
            "message": "no data",
            "color": "lightgrey",
        }
    else:
        # Use the most recent day with data
        latest = next((d for d in history if d.get("orchestrator_ran")), None)

        if not latest:
            badge_data = {
                "schemaVersion": 1,
                "label": "nightly",
                "message": "no runs",
                "color": "lightgrey",
            }
        else:
            summary = latest.get("summary", {})
            success = summary.get("success", 0)
            failure = summary.get("failure", 0)
            total = success + failure + summary.get("other", 0)

            if failure == 0 and total > 0:
                color = "brightgreen"
                message = f"{success}/{total} passing"
            elif failure > 0 and success > failure:
                color = "yellow"
                message = f"{failure}/{total} failing"
            elif failure > 0:
                color = "red"
                message = f"{failure}/{total} failing"
            else:
                color = "lightgrey"
                message = "no data"

            badge_data = {
                "schemaVersion": 1,
                "label": "nightly",
                "message": message,
                "color": color,
            }

    with open(output_file, "w") as f:
        json.dump(badge_data, f, indent=2)

def extract_entity_from_scores(self, query, W_query, p_start, p_end, thresh=0.70):
        final_outputs = []
        for idx in range(len(W_query["input_ids"])):
            start_indexes = end_indexes = range(p_start.shape[1])

            output = []
            for start_id in start_indexes:
                for end_id in end_indexes:
                    if start_id < end_id:
                        output.append(
                            (
                                start_id,
                                end_id,
                                p_start[idx][start_id].item(),
                                p_end[idx][end_id].item(),
                            )
                        )

            output.sort(key=lambda tup: (tup[2] * tup[3]), reverse=True)
            temp = []
            for k in range(len(output)):
                if output[k][2] * output[k][3] >= thresh:
                    c_start_pos, c_end_pos = output[k][0], output[k][1]
                    decoded = self.tokenizer.decode(W_query["input_ids"][idx][c_start_pos:c_end_pos])
                    temp.append((decoded, output[k][2] * output[k][3]))

            final_outputs.append(temp)

        return final_outputs

def add_pdb_headers(prot: Protein, pdb_str: str) -> str:
    out_pdb_lines: list[str] = []
    lines = pdb_str.split("\n")

    remark = prot.remark
    if remark is not None:
        out_pdb_lines.append(f"REMARK {remark}")

    parents_per_chain: list[list[str]]
    if prot.parents is not None and len(prot.parents) > 0:
        parents_per_chain = []
        if prot.parents_chain_index is not None:
            parent_dict: dict[str, list[str]] = {}
            for p, i in zip(prot.parents, prot.parents_chain_index):
                parent_dict.setdefault(str(i), [])
                parent_dict[str(i)].append(p)

            max_idx = max(int(chain_idx) for chain_idx in parent_dict)
            for i in range(max_idx + 1):
                chain_parents = parent_dict.get(str(i), ["N/A"])
                parents_per_chain.append(chain_parents)
        else:
            parents_per_chain.append(list(prot.parents))
    else:
        parents_per_chain = [["N/A"]]

    def make_parent_line(p: Sequence[str]) -> str:
        return f"PARENT {' '.join(p)}"

    out_pdb_lines.append(make_parent_line(parents_per_chain[0]))

    chain_counter = 0
    for i, l in enumerate(lines):
        if "PARENT" not in l and "REMARK" not in l:
            out_pdb_lines.append(l)
        if "TER" in l and "END" not in lines[i + 1]:
            chain_counter += 1
            if not chain_counter >= len(parents_per_chain):
                chain_parents = parents_per_chain[chain_counter]
            else:
                chain_parents = ["N/A"]

            out_pdb_lines.append(make_parent_line(chain_parents))

    return "\n".join(out_pdb_lines)

def from_feast_type(
    feast_type: FeastType,
) -> ValueType:
    # Handle Struct types directly since they are not in the dict
    if isinstance(feast_type, Struct):
        return ValueType.STRUCT
    if isinstance(feast_type, Array) and isinstance(feast_type.base_type, Struct):
        return ValueType.STRUCT_LIST

    # Handle nested collection types
    if isinstance(feast_type, Array) and isinstance(feast_type.base_type, (Array, Set)):
        return ValueType.VALUE_LIST
    if isinstance(feast_type, Set) and isinstance(feast_type.base_type, (Array, Set)):
        return ValueType.VALUE_SET

    if feast_type in VALUE_TYPES_TO_FEAST_TYPES.values():
        return list(VALUE_TYPES_TO_FEAST_TYPES.keys())[
            list(VALUE_TYPES_TO_FEAST_TYPES.values()).index(feast_type)
        ]

    raise ValueError(f"Could not convert feast type {feast_type} to ValueType.")

def entry_point(root_path=None):
    # FIXME: rename env var used
    root_path = root_path or "."
    env_var = os.environ.get("ENTRY_POINT")

    if env_var:
        if len(Path(env_var).parts) > 1:
            raise ValueError(
                f"ENTRY_POINT ({env_var!r}) "
                "must be a filename and do not contain any "
                "directory components (e.g., pipeline.yaml, "
                "not path/to/pipeline.yaml)."
            )

        filename = env_var
    else:
        filename = "pipeline.yaml"

    # check if there's a config file
    path_to_config, _ = find_file_recursively(name="setup.cfg", starting_dir=root_path)

    if path_to_config:
        cfg = config.load_config(path_to_config)

        if cfg and cfg["ploomber"].get("entry-point"):
            parent = Path(path_to_config).parent
            entry_point = str(parent / cfg["ploomber"]["entry-point"])

            if not Path(entry_point).is_file():
                raise DAGSpecInvalidError(
                    "Skipping DAG initialization:"
                    " found setup.cfg but "
                    f"entry-point {entry_point!r} "
                    "does not exist"
                )

            return entry_point

    return entry_point_with_name(root_path=root_path, name=filename)

def single_tree_preds_from_each_client(
    trainloader: DataLoader,
    batch_size,
    client_tree_ensamples: Union[
        Tuple[XGBClassifier, int],
        Tuple[XGBRegressor, int],
        List[Union[Tuple[XGBClassifier, int], Tuple[XGBRegressor, int]]],
    ],
    n_estimators_client: int,
    client_num: int,
) -> Optional[Tuple[NDArray, NDArray]]:
    if trainloader is None:
        return None

    for local_dataset in trainloader:
        x_train, y_train = local_dataset[0], np.float32(local_dataset[1])

    preds_from_all_trees_from_all_clients = np.zeros(
        (x_train.shape[0], client_num * n_estimators_client), dtype=np.float32
    )
    if isinstance(client_tree_ensamples, list) is False:
        temp_trees = [client_tree_ensamples[0]] * client_num
    elif isinstance(client_tree_ensamples, list):
        client_tree_ensamples.sort(key=lambda x: x[1])
        temp_trees = [i[0] for i in client_tree_ensamples]
        if len(client_tree_ensamples) != client_num:
            temp_trees += [client_tree_ensamples[0][0]] * (
                client_num - len(client_tree_ensamples)
            )

    for i, _ in enumerate(temp_trees):
        for j in range(n_estimators_client):
            preds_from_all_trees_from_all_clients[:, i * n_estimators_client + j] = (
                single_tree_prediction(temp_trees[i], j, x_train)
            )

    preds_from_all_trees_from_all_clients = torch.from_numpy(
        np.expand_dims(preds_from_all_trees_from_all_clients, axis=1)
    )
    y_train = torch.from_numpy(np.expand_dims(y_train, axis=-1))
    tree_dataset = TensorDataset(preds_from_all_trees_from_all_clients, y_train)
    return get_dataloader(tree_dataset, "tree", batch_size)

