def visit(self, node: doc.AST) -> None:
        if isinstance(node, list | tuple):
            for item in node:
                self.visit(item)
            return
        if not isinstance(node, doc.AST):
            return
        name = node.__class__.__name__.split(".")[-1]
        if name in DEFAULT_VISIT:
            func = self.generic_visit
        else:
            func = getattr(self, "visit_" + name, None)
        if func is None:
            raise NotImplementedError(f"Visitor of AST node is not implemented: {name}")
        try:
            func(node)
        except Exception as err:  # pylint: disable=broad-except
            self.report_error(node, err)

def close_object_schemas(schema: Dict, strict: bool = False) -> Dict:
    def _normalize(node: Any) -> Any:
        if isinstance(node, list):
            return [_normalize(item) for item in node]

        if not isinstance(node, dict):
            return node

        normalized = deepcopy(node)

        for key in (
            "properties",
            "$defs",
            "definitions",
            "patternProperties",
            "dependentSchemas",
        ):
            if key in normalized and isinstance(normalized[key], dict):
                normalized[key] = {
                    child_key: _normalize(child_value)
                    for child_key, child_value in normalized[key].items()
                }

        for key in ("items", "additionalProperties", "not", "if", "then", "else"):
            if key in normalized:
                normalized[key] = _normalize(normalized[key])

        for key in ("prefixItems", "allOf", "anyOf", "oneOf"):
            if key in normalized and isinstance(normalized[key], list):
                normalized[key] = [_normalize(item) for item in normalized[key]]

        if (
            normalized.get("type") == "object"
            and "additionalProperties" not in normalized
        ):
            normalized["additionalProperties"] = False

        if (
            strict
            and normalized.get("type") == "object"
            and isinstance(normalized.get("properties"), dict)
        ):
            normalized["required"] = list(normalized["properties"].keys())

        return normalized

    return _normalize(schema)

def weights(self, weights):
    if isinstance(weights, dict) and weights == GET_WEIGHTS_FROM_CACHE:
      return
    if not self.sublayers:
      self._weights = weights
    else:
      # When having sublayers, self._weights just marks which are cached,
      # the actual weights are stored by sublayers.
      self._weights = []
      for w in weights:
        if isinstance(w, dict) and w == GET_WEIGHTS_FROM_CACHE:
          self._weights.append(w)
        else:
          self._weights.append(None)
      # Set sublayer weights.
      n_layers = len(self.sublayers)
      if len(weights) != n_layers:
        raise ValueError(
            f'Number of weight elements ({len(weights)}) does not equal the '
            f'number of sublayers ({n_layers}) in: {str(self)}.')
      for sublayer, sublayer_weights in zip(self.sublayers, weights):
        sublayer.weights = sublayer_weights

def generate(self) -> list[dict]:
        if self.data_type == "audio":
            return self.generate_audio()
        elif self.data_type == "scalar":
            return self.generate_scalar()
        elif self.data_type == "table":
            return self.generate_table()
        elif self.data_type == "image":
            return self.generate_image()
        elif self.data_type == "video":
            return self.generate_video()
        elif self.data_type == "prefixed_scalar":
            return self.generate_prefixed_scalar()

        else:
            raise ValueError(f"Invalid data type: {self.data_type}")

def strict(self, value: bool) -> None:
        if value == self._strict:
            return  # No change needed

        # Only validate if strict is being set to True and we have stored init args
        if value and hasattr(self, "_init_args"):
            # Get the list of valid arguments for this transform
            valid_args = {"p", "strict"}  # Base valid args
            if hasattr(self, "InitSchema"):
                valid_args.update(self.InitSchema.model_fields.keys())

            # Check for invalid arguments
            invalid_args = [name_arg for name_arg in self._init_args if name_arg not in valid_args]

            if invalid_args:
                message = (
                    f"Argument(s) '{', '.join(invalid_args)}' are not valid for transform {self.__class__.__name__}"
                )
                if value:  # In strict mode
                    raise ValueError(message)
                warn(message, stacklevel=2)

        self._strict = value

def aggregate_data(
        self, data_points: List[Optional[Dict]]
    ) -> Dict:
        prices = []
        volumes = []
        market_caps = []

        for data in data_points:
            if data and isinstance(data, dict):
                if data.get("price") is not None:
                    prices.append(float(data["price"]))
                if data.get("volume24h") is not None:
                    volumes.append(float(data["volume24h"]))
                if data.get("marketCap") is not None:
                    market_caps.append(float(data["marketCap"]))

        return {
            "price": {
                "mean": mean(prices) if prices else 0,
                "median": median(prices) if prices else 0,
                "min": min(prices) if prices else 0,
                "max": max(prices) if prices else 0,
                "sources": len(prices),
            },
            "volume_24h": {
                "mean": mean(volumes) if volumes else 0,
                "total": sum(volumes) if volumes else 0,
                "sources": len(volumes),
            },
            "market_cap": {
                "mean": mean(market_caps) if market_caps else 0,
                "median": median(market_caps) if market_caps else 0,
                "sources": len(market_caps),
            },
            "timestamp": datetime.now().isoformat(),
            "sources_total": len(
                [d for d in data_points if d is not None]
            ),
        }

def set_defaults(self, helptext: str = "") -> None:
        section = "global"
        logger.debug("[%s:%s] Adding defaults", self._plugin_group, section)

        if not helptext:
            logger.debug("No help text provided for '%s'. Not creating global section",
                         self.__module__)
            return

        self.add_section(section, helptext)

        for key, val in vars(sys.modules[self.__module__]).items():
            if isinstance(val, ConfigItem):
                self.add_item(section=section, title=key, config_item=val)
        logger.debug("[%s:%s] Added defaults", self._plugin_group, section)

        # Add global sub-sections
        for key, val in vars(sys.modules[self.__module__]).items():
            if inspect.isclass(val) and issubclass(val, GlobalSection) and val != GlobalSection:
                g_val = T.cast(GlobalSection, val)
                section_name = f"{section}.{key.lower()}"
                self.add_section(section_name, g_val.helptext)
                for opt_name, opt in g_val.__dict__.items():
                    if isinstance(opt, ConfigItem):
                        self.add_item(section=section_name, title=opt_name, config_item=opt)

def try_to_load_from_cache(
    repo_id: str,
    filename: str,
    cache_dir: Union[str, Path, None] = None,
    revision: Optional[str] = None,
) -> Optional[str]:
    if revision is None:
        revision = "main"

    if cache_dir is None:
        cache_dir = TRANSFORMERS_CACHE

    object_id = repo_id.replace("/", "--")
    repo_cache = os.path.join(cache_dir, f"models--{object_id}")
    if not os.path.isdir(repo_cache):
        # No cache for this model
        return None
    for subfolder in ["refs", "snapshots"]:
        if not os.path.isdir(os.path.join(repo_cache, subfolder)):
            return None

    # Resolve refs (for instance to convert main to the associated commit sha)
    cached_refs = os.listdir(os.path.join(repo_cache, "refs"))
    if revision in cached_refs:
        with open(os.path.join(repo_cache, "refs", revision)) as f:
            revision = f.read()

    if os.path.isfile(os.path.join(repo_cache, ".no_exist", revision, filename)):
        return _CACHED_NO_EXIST

    cached_shas = os.listdir(os.path.join(repo_cache, "snapshots"))
    if revision not in cached_shas:
        # No cache for this revision and we won't try to return a random revision
        return None

    cached_file = os.path.join(repo_cache, "snapshots", revision, filename)
    return cached_file if os.path.isfile(cached_file) else None

def collate_dicts(batch: List[Batch]) -> Batch:
    X_batch: Dict[str, Any] = defaultdict(list)
    Y_batch: Dict[str, Any] = defaultdict(list)

    for x_dict, y_dict in batch:
        for field_name, value in x_dict.items():
            X_batch[field_name].append(value)
        for label_name, value in y_dict.items():
            Y_batch[label_name].append(value)

    for field_name, values in X_batch.items():
        # Only merge list of tensors
        if isinstance(values[0], Tensor):
            X_batch[field_name] = list_to_tensor(values)

    for label_name, values in Y_batch.items():
        Y_batch[label_name] = list_to_tensor(values)

    return dict(X_batch), dict(Y_batch)

def tokenize_dialogue(  # noqa: C901
    dialogue: Union[str, Iterable[str]], tokenizer: Union[PreTrainedTokenizer, PreTrainedTokenizerFast], max_length=2048
) -> List[DialogMessage]:
    if isinstance(dialogue, str):
        bos_token = tokenizer.bos_token or tokenizer.eos_token
        dialogue = [bos_token, dialogue]
    elif isinstance(dialogue, Iterable):
        if len(dialogue) % 2 != 0:
            raise ValueError("Dialogue must have an even number of phrases, alternating prompt and output")
        dialogue = list(dialogue)

    if not dialogue[-1].endswith(tokenizer.eos_token):
        dialogue[-1] = dialogue[-1] + tokenizer.eos_token

    tokenized = [
        DialogMessage(is_output=i % 2 == 1, tokens=tuple(tokenizer(dialogue[i], add_special_tokens=False).input_ids))
        for i in range(len(dialogue))
    ]

    # flip to truncate from the left
    if tokenizer.truncation_side == "left":
        tokenized = [DialogMessage(is_output=m.is_output, tokens=m.tokens[::-1]) for m in tokenized[::-1]]

    # truncate if necessary
    lengths = [len(t.tokens) for t in tokenized]
    cumsum_lengths = [sum(lengths[:i]) for i in range(len(lengths))]
    truncated = [
        DialogMessage(is_output=t.is_output, tokens=t.tokens[: max(max_length - cl, 0)])
        for t, cl in zip(tokenized, cumsum_lengths)
    ]

    # flip back if was fliped to left truncate
    if tokenizer.truncation_side == "left":
        truncated = [DialogMessage(is_output=m.is_output, tokens=m.tokens[::-1]) for m in truncated[::-1]]

    # remove empty messages
    out = [t for t in truncated if len(t.tokens) > 0]

    if out[0].is_output:
        if sum(map(lambda msg: len(msg.tokens), out)) == max_length:
            if tokenizer.truncation_side == "left":
                out[0].tokens = out[0].tokens[1:]
            else:
                out[-1].tokens = out[-1].tokens[:-1]

        out.insert(0, DialogMessage(False, (tokenizer.bos_token_id,)))
    return out

def generation_attributes() -> Callable:
    def _extract(ret, exception, *args, **kwargs) -> Dict[str, Any]:
        result = {}

        # Extract input content from first positional arg (usually messages)
        if args:
            input_content = extract_input_content(args[0])
            if input_content:
                result["input_content"] = input_content

        # Extract output content and tool calls from return value
        if ret is not None:
            output_content = extract_output_content(ret)
            if output_content:
                result["output_content"] = output_content

            tool_calls = extract_tool_calls(ret)
            if tool_calls:
                result["tool_calls"] = tool_calls

        return result

    return _extract

def create_bag_transform(
    feature_count,
    feature_selection,
    relevant_features,
    sfa_words,
    bigrams,
    remove_repeat_words,
):
    # merging arrays
    all_win_words = np.zeros((len(sfa_words), feature_count), np.uint32)
    for j in prange(sfa_words.shape[0]):
        if len(relevant_features) == 0 and feature_selection == "none":
            # this mask is used to encode the repeated words
            if remove_repeat_words:
                masked = np.nonzero(sfa_words[j])
                all_win_words[j, :] = np.bincount(
                    sfa_words[j][masked], minlength=feature_count
                )
            else:
                all_win_words[j, :] = np.bincount(sfa_words[j], minlength=feature_count)
        else:
            if remove_repeat_words:
                if 0 in relevant_features:
                    del relevant_features[0]

            for _, key in enumerate(sfa_words[j]):
                if key in relevant_features:
                    o = relevant_features[key]
                    all_win_words[j, o] += 1

    return all_win_words, all_win_words.shape[1]

def convert_ids_to_tokens(
        self,
        batch_token_ids: Union[List[Union[int, str]], List[List[Union[int, str]]]],
        **kwargs,
    ) -> Union[List[str]]:
        assert self._model is not None
        if isinstance(batch_token_ids, (int, str)):
            return self._tokenizer.decode([int(str(batch_token_ids))])[0]

        batch_decoded_texts: List[str] = []

        # check if it's a nested list
        if (
            isinstance(batch_token_ids, list)
            and batch_token_ids
            and isinstance(batch_token_ids[0], list)
        ):
            for token_ids in batch_token_ids:
                token_ids = [int(token_id) for token_id in token_ids]  # type: ignore
                batch_decoded_texts.append(
                    self._tokenizer.convert_ids_to_tokens(token_ids)
                )
        else:
            batch_token_ids = [int(token_id) for token_id in batch_token_ids]  # type: ignore
            batch_decoded_texts = self._tokenizer.convert_ids_to_tokens(batch_token_ids)
        return batch_decoded_texts

def check_filename_pattern(photo, pattern_type="any"):
    if not photo.main_file:
        return False, None

    filename = os.path.basename(photo.main_file.path)
    basename = os.path.splitext(filename)[0]
    directory = os.path.dirname(photo.main_file.path)

    if pattern_type == "any" or pattern_type == "all":
        # Check all predefined patterns
        for pattern_name, (pattern, _) in BURST_FILENAME_PATTERNS.items():
            if re.search(pattern, basename, re.IGNORECASE):
                base = re.sub(
                    r"(_BURST\d+|_\d{3,}|\(\d+\)|_COVER)$",
                    "",
                    basename,
                    flags=re.IGNORECASE,
                )
                group_key = f"filename_{directory}_{base}"
                return True, group_key
    else:
        # Check specific pattern
        if pattern_type in BURST_FILENAME_PATTERNS:
            pattern, _ = BURST_FILENAME_PATTERNS[pattern_type]
            if re.search(pattern, basename, re.IGNORECASE):
                base = re.sub(
                    r"(_BURST\d+|_\d{3,}|\(\d+\)|_COVER)$",
                    "",
                    basename,
                    flags=re.IGNORECASE,
                )
                group_key = f"filename_{directory}_{base}"
                return True, group_key

    return False, None

def update_param_groups(
    optimizer: Optimizer,
    default_update: Optional[Dict[str, Any]] = None,
    updates: Optional[Iterable[Dict[str, Any]]] = None,
) -> None:
    if default_update is None:
        default_update = {}
    if updates is None:
        updates = []

    # Update the optimizer's param_groups with the provided default values.
    for key, value in default_update.items():
        for param_group in optimizer.param_groups:
            # Update the value only if it already exists in the param_group, we don't
            # want to accidentally add new keys/values.
            if key in param_group:
                param_group[key] = value

    # Update the optimizer's param_groups with the provided updates.
    for update in updates:
        found_group = False
        name = update["name"]
        for param_group in optimizer.param_groups:
            if param_group.get("name") == name:
                found_group = True
                for key, value in update.items():
                    if key in param_group:
                        param_group[key] = value
                    else:
                        raise ValueError(
                            f"Key '{key}' not found in param group with name '{name}'."
                        )
        if not found_group:
            raise ValueError(f"No param group with name '{name}' in optimizer.")

def get_gpu_model_params(model_class, use_gpu: bool) -> dict:
    if not use_gpu:
        return {}

    module = getattr(model_class, "__module__", "") or ""

    # XGBoost: use device="cuda"
    if "xgboost" in module:
        if is_gpu_available():
            return {"device": "cuda"}
        else:
            logger.warning(
                "GPU requested for %s but CUDA is not available. "
                "Falling back to CPU.",
                model_class.__name__,
            )
            return {}

    # LightGBM: use device="gpu"
    if "lightgbm" in module:
        if is_gpu_available():
            return {"device": "gpu"}
        else:
            logger.warning(
                "GPU requested for %s but CUDA is not available. "
                "Falling back to CPU.",
                model_class.__name__,
            )
            return {}

    # CatBoost: use task_type="GPU"
    if "catboost" in module:
        if is_gpu_available():
            return {"task_type": "GPU"}
        else:
            logger.warning(
                "GPU requested for %s but CUDA is not available. "
                "Falling back to CPU.",
                model_class.__name__,
            )
            return {}

    # cuML (RAPIDS): models are GPU-native, no extra params needed
    if "cuml" in module:
        if is_gpu_available():
            return {}
        else:
            logger.warning(
                "GPU requested for %s (cuML) but CUDA is not available. "
                "cuML requires a CUDA-capable GPU.",
                model_class.__name__,
            )
            return {}

    return {}

def get_data(self, session_id: int, metric: T.Literal["loss", "timestamps"]
                 ) -> dict[int, dict[str, np.ndarray | list[str]]] | None:
        if session_id is None:
            raw = self._data
        else:
            data = self._data.get(session_id)
            if not data:
                return None
            raw = {session_id: data}

        retval: dict[int, dict[str, np.ndarray | list[str]]] = {}
        for idx, data in raw.items():
            array = data.loss if metric == "loss" else data.timestamps
            val: dict[str, np.ndarray | list[str]] = {str(metric): array}
            if metric == "loss":
                val["labels"] = data.labels
            retval[idx] = val

        logger.debug("Obtained cached data: %s",
                     {session_id: {k: v.shape if isinstance(v, np.ndarray) else v
                                   for k, v in data.items()}
                      for session_id, data in retval.items()})
        return retval

def normalized_iterable(self):
        iterable = self.resolved_iterable
        if isinstance(iterable, Mapping):
            return {to_str(k): v for k, v in iterable.items()}

        assert isinstance(iterable, Sequence)
        if any(map(is_map_or_seq, iterable)):
            # if the list contains composite data, index are the keys
            return {to_str(idx): value for idx, value in enumerate(iterable)}

        # for simple lists, eg: ["foo", "bar"],  contents are the key itself
        return {to_str(value): value for value in iterable}

def cast_storage(self, storage: Union[pa.StringArray, pa.StructArray]) -> pa.StructArray:
        if pa.types.is_string(storage.type):
            bytes_array = pa.array([None] * len(storage), type=pa.binary())
            storage = pa.StructArray.from_arrays([bytes_array, storage], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_large_binary(storage.type):
            storage = array_cast(
                storage, pa.binary()
            )  # this can fail in case of big audios, paths should be used instead
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_binary(storage.type):
            path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([storage, path_array], ["bytes", "path"], mask=storage.is_null())
        elif pa.types.is_struct(storage.type) and storage.type.get_all_field_indices("array"):
            storage = pa.array(
                [Audio().encode_example(x) if x is not None else None for x in storage.to_numpy(zero_copy_only=False)]
            )
        elif pa.types.is_struct(storage.type):
            if storage.type.get_field_index("bytes") >= 0:
                bytes_array = storage.field("bytes")
            else:
                bytes_array = pa.array([None] * len(storage), type=pa.binary())
            if storage.type.get_field_index("path") >= 0:
                path_array = storage.field("path")
            else:
                path_array = pa.array([None] * len(storage), type=pa.string())
            storage = pa.StructArray.from_arrays([bytes_array, path_array], ["bytes", "path"], mask=storage.is_null())
        return array_cast(storage, self.pa_type)

def forward(
        self, hidden_states: torch.FloatTensor, cls_index: torch.LongTensor | None = None
    ) -> torch.FloatTensor:
        if self.summary_type == "last":
            output = hidden_states[:, -1]
        elif self.summary_type == "first":
            output = hidden_states[:, 0]
        elif self.summary_type == "mean":
            output = hidden_states.mean(dim=1)
        elif self.summary_type == "cls_index":
            if cls_index is None:
                cls_index = torch.full_like(
                    hidden_states[..., :1, :],
                    hidden_states.shape[-2] - 1,
                    dtype=torch.long,
                )
            else:
                cls_index = cls_index.unsqueeze(-1).unsqueeze(-1)
                cls_index = cls_index.expand((-1,) * (cls_index.dim() - 1) + (hidden_states.size(-1),))
            # shape of cls_index: (bsz, XX, 1, hidden_size) where XX are optional leading dim of hidden_states
            output = hidden_states.gather(-2, cls_index).squeeze(-2)  # shape (bsz, XX, hidden_size)
        elif self.summary_type == "attn":
            raise NotImplementedError

        output = self.first_dropout(output)
        output = self.summary(output)
        output = self.activation(output)
        output = self.last_dropout(output)

        return output

def get_metrics(metric_input):
    if metric_input is None:
        return False
    elif metric_input is False:
        return False
    elif metric_input is True:
        return {"MAE": METRICS["MAE"], "RMSE": METRICS["RMSE"]}
    elif isinstance(metric_input, str):
        if metric_input.upper() in METRICS.keys():
            return {metric_input: METRICS[metric_input.upper()]}
        else:
            raise ValueError("Received unsupported argument for collect_metrics.")
    elif isinstance(metric_input, list):
        if all([m.upper() in METRICS.keys() for m in metric_input]):
            return {m: METRICS[m.upper()] for m in metric_input}
        else:
            raise ValueError("Received unsupported argument for collect_metrics.")
    elif isinstance(metric_input, dict):
        # check if all values are names belonging to torchmetrics.Metric
        try:
            for _metric in metric_input.values():
                torchmetrics.__dict__[_metric]()
        except KeyError:
            raise ValueError(
                "Received unsupported argument for collect_metrics."
                "All metrics must be valid names of torchmetrics.Metric objects."
            )
        return {k: [v, {}] for k, v in metric_input.items()}
    else:
        raise ValueError("Received unsupported argument for collect_metrics.")

async def blocktype_inspect(
    slug: Annotated[str, cyclopts.Parameter(help="A block type slug")],
    *,
    output: Annotated[
        Optional[str],
        cyclopts.Parameter(
            "--output",
            alias="-o",
            help="Specify an output format. Currently supports: json",
        ),
    ] = None,
):
    from prefect.client.orchestration import get_client
    from prefect.exceptions import ObjectNotFound

    if output and output.lower() != "json":
        exit_with_error("Only 'json' output format is supported.")

    async with get_client() as client:
        try:
            block_type = await client.read_block_type_by_slug(slug)
        except ObjectNotFound:
            exit_with_error(f"Block type {slug!r} not found!")

        try:
            latest_schema = await client.get_most_recent_block_schema_for_block_type(
                block_type.id
            )
        except Exception:
            exit_with_error(f"Failed to fetch latest schema for the {slug} block type")

        if latest_schema is None:
            exit_with_error(f"No schema found for the {slug} block type")

        if output and output.lower() == "json":
            block_type_json = block_type.model_dump(mode="json")
            schema_json = latest_schema.model_dump(mode="json")
            json_output = orjson.dumps(
                {"block_type": block_type_json, "schema": schema_json},
                option=orjson.OPT_INDENT_2,
            ).decode()
            _cli.console.print(json_output, soft_wrap=True)
            return

        _cli.console.print(_display_block_type(block_type))
        _cli.console.print(_display_block_schema_properties(latest_schema.fields))

        latest_schema_extra_definitions = latest_schema.fields.get("definitions")
        if latest_schema_extra_definitions:
            _cli.console.print(
                _display_block_schema_extra_definitions(latest_schema_extra_definitions)
            )

def fix_dep_urls(
        requirements_txt: str, wheels_folder: str, pack_git_packages: bool = True
    ) -> None:
        from pip_requirements_parser import RequirementsFile
        from pip_requirements_parser import parse_reqparts_from_string

        parsed_requirements = RequirementsFile.from_file(
            requirements_txt, include_nested=True
        )
        for req in parsed_requirements.requirements:
            link = req.link
            if not link:
                continue

            if "/env/python/wheels" in link.url or "/src/wheels" in link.url:
                filename = link.filename
            elif pack_git_packages and link.url.startswith("git+"):
                # We are only able to handle SSH Git URLs
                url, ref = link.url_without_fragment[4:], ""
                if "@" in link.path:  # ssh://git@owner/repo@ref
                    url, _, ref = url.rpartition("@")
                filename = build_git_repo(
                    url, ref, link.subdirectory_fragment, wheels_folder
                )
            else:
                continue
            parsed_parts = parse_reqparts_from_string(f"./wheels/{filename}")
            req.link = parsed_parts.link
            req.req = parsed_parts.requirement
            req.requirement_line.line = f"./wheels/{filename}"

        with open(requirements_txt, "w") as f:
            f.write(parsed_requirements.dumps(preserve_one_empty_line=True))

def optimize_measurements(
    observables: Sequence[Operator],
    coefficients: Sequence[float] = None,
    grouping: str = "qwc",
    colouring_method: str = "lf",
) -> tuple:

    partition_indices = compute_partition_indices(
        observables, grouping_type=grouping, method=colouring_method
    )
    grouped_obs = [[observables[idx] for idx in group] for group in partition_indices]

    if grouping.lower() == "qwc":
        (
            post_rotations,
            diagonalized_groupings,
        ) = diagonalize_qwc_groupings(grouped_obs)
    else:
        raise NotImplementedError(
            f"Measurement reduction by '{grouping.lower()}' grouping not implemented."
        )

    result = (post_rotations, diagonalized_groupings)

    if coefficients:
        grouped_coeffs = [[coefficients[idx] for idx in group] for group in partition_indices]
        result += (grouped_coeffs,)

    return result

def generate_files(generator, output_filenames,
                   max_cases=None, cycle_every_n=1):
  if outputs_exist(output_filenames):
    tf.logging.info("Skipping generator because outputs files exists at {}"
                    .format(output_filenames))
    return
  tmp_filenames = [fname + ".incomplete" for fname in output_filenames]
  num_shards = len(output_filenames)
  # Check if is training or eval, ref: train_data_filenames().
  if num_shards > 0:
    if "-train" in output_filenames[0]:
      tag = "train"
    elif "-dev" in output_filenames[0]:
      tag = "eval"
    else:
      tag = "other"

  writers = [tf.python_io.TFRecordWriter(fname) for fname in tmp_filenames]
  counter, shard = 0, 0
  for case in generator:
    if case is None:
      continue
    if counter % 100000 == 0:
      tf.logging.info("Generating case %d." % counter)
    counter += 1
    if max_cases and counter > max_cases:
      break
    example = to_example(case)
    writers[shard].write(example.SerializeToString())
    if counter % cycle_every_n == 0:
      shard = (shard + 1) % num_shards

  for writer in writers:
    writer.close()

  for tmp_name, final_name in zip(tmp_filenames, output_filenames):
    tf.gfile.Rename(tmp_name, final_name)

  if num_shards > 0:
    if tag == "train":
      mlperf_log.transformer_print(
          key=mlperf_log.PREPROC_NUM_TRAIN_EXAMPLES, value=counter)
    elif tag == "eval":
      mlperf_log.transformer_print(
          key=mlperf_log.PREPROC_NUM_EVAL_EXAMPLES, value=counter)

  tf.logging.info("Generated %s Examples", counter)

def train(self, train_loader):
        for epoch in tqdm.trange(self.epoch_num,
                                 desc=f'Training: ',
                                 disable=not self.verbose == 1):
            start_time = time.time()
            overall_loss = []
            for batch_data in train_loader:
                loss = self.training_forward(batch_data)
                overall_loss.append(loss)
            # loss could be a tuple or a single value
            if isinstance(loss, (tuple, list)):
                overall_loss = np.mean([l for l in overall_loss])
            else:
                overall_loss = np.mean(overall_loss)

            # loss could be a tuple or a single value
            if self.verbose == 2:
                if isinstance(loss, (tuple, list)):
                    print(f'Epoch {epoch + 1}/{self.epoch_num},', end=' ')
                    for i, l in enumerate(loss):
                        print(f'loss_{i}={l:.4f}', end=', ')
                    print(f'time={time.time() - start_time:.2f}s')
                else:
                    print(f'Epoch {epoch + 1}/{self.epoch_num}, '
                          f'loss={overall_loss:.4f}, '
                          f'time={time.time() - start_time:.2f}s')

            self.epoch_update()

def save_from_cells(
        self,
        cells: Sequence[NotebookCell],
        *,
        expected_filename: Path | None = None,
        expected_generation: int | None = None,
    ) -> str:
        if self._filename is None:
            raise HTTPException(
                status_code=HTTPStatus.BAD_REQUEST,
                detail="Cannot save an unnamed notebook",
            )

        with self._save_lock:
            if expected_generation is not None:
                if expected_generation != self._autosave_generation:
                    return ""
            if expected_filename is not None:
                if self._filename is None or not self._is_same_path(
                    expected_filename
                ):
                    return ""

            self.app.with_data(
                cell_ids=[cell.id for cell in cells],
                codes=[cell.code for cell in cells],
                names=[cell.name for cell in cells],
                configs=[cell.config for cell in cells],
            )
            return self._save_file(
                self._filename,
                notebook=self.app.to_ir(),
                persist=True,
            )

def reshape_classifier_output(model, n=1000):
    from models.common import Classify

    name, m = list((model.model if hasattr(model, "model") else model).named_children())[-1]  # last module
    if isinstance(m, Classify):  # YOLOv3 Classify() head
        if m.linear.out_features != n:
            m.linear = nn.Linear(m.linear.in_features, n)
    elif isinstance(m, nn.Linear):  # ResNet, EfficientNet
        if m.out_features != n:
            setattr(model, name, nn.Linear(m.in_features, n))
    elif isinstance(m, nn.Sequential):
        types = [type(x) for x in m]
        if nn.Linear in types:
            i = types.index(nn.Linear)  # nn.Linear index
            if m[i].out_features != n:
                m[i] = nn.Linear(m[i].in_features, n)
        elif nn.Conv2d in types:
            i = types.index(nn.Conv2d)  # nn.Conv2d index
            if m[i].out_channels != n:
                m[i] = nn.Conv2d(m[i].in_channels, n, m[i].kernel_size, m[i].stride, bias=m[i].bias is not None)

async def before_model_callback(self, *, callback_context: CallbackContext, llm_request: LlmRequest) -> LlmResponse | None:
        self._pending_request = llm_request
        self._pending_agent_name = getattr(callback_context, "agent_name", self._agent_name)
        self._request_start_time = time.perf_counter()

        if getattr(llm_request, "model", None):
            self._model_name = llm_request.model

        # Capture user input from the first model call
        if self._user_input is None:
            for content in llm_request.contents or []:
                if getattr(content, "role", None) == "user":
                    texts = [p.text for p in (getattr(content, "parts", None) or []) if getattr(p, "text", None)]
                    if texts:
                        self._user_input = {"message": "\n".join(texts)}
                        break

        return None

def update_hints(self, method_id: Methods):
        if self.__interface_update:
            return

        method_id = Methods(method_id)
        args = self._get_values(method_id)
        keys = self.varkeys_for_selection()
        if method_id == Methods.Default:
            for key in keys:
                if key in self.var_hints:
                    del self.var_hints[key]
        else:
            self.var_hints.update(dict.fromkeys(keys, VarHint(method_id, args)))
        if keys == [DefaultKey]:
            invalidate = set(self.discretized_vars) - set(self.var_hints)
        else:
            invalidate = keys
        for key in invalidate:
            del self.discretized_vars[key]

        if keys == [DefaultKey]:
            self._update_default_model()
        self._update_discretizations()
        self.commit.deferred()

def stop(self, block: bool = True, timeout: float | None = None, keep_for_next_session: bool = False) -> None:
        if self.batch_processor is None:
            logger.warning("\nBatch processor was not initialized.")
        elif self.batch_processor.cache.use_prefix_sharing:
            logger.info(
                f"\nPrefix sharing was on. Total prefix length: {self.batch_processor.cache._total_prefix_length}"
            )

        if self._generation_thread is None:
            suffix = " Hence the unstarted manager will not be kept for next session." if keep_for_next_session else ""
            logger.warning("Manager not started." + suffix)
            return

        stop_trigger_time = perf_counter()
        if not self.stop_event.is_set():
            self.stop_event.set()
            logger.info("Stopping continuous batching manager...")

        if block:
            self.join(stop_trigger_time, timeout)

        # If the manager is not being kept for next session, we clear the batch processor
        if not keep_for_next_session:
            self.batch_processor = None
        # Otherwise, we keep the batch processor and cache the manager as a model attribute
        else:
            logger.info("Continuous batching manager will be kept for next session.")
            self.model._cached_continuous_batching_manager = self
        # In all cases, a little cleanup is good
        gc.collect()
        if torch.cuda.is_available():
            torch.cuda.empty_cache()

def coerce_value(type, value):
    if isinstance(type, GraphQLNonNull):
        # Note: we're not checking that the result of coerceValue is
        # non-null.
        # We only call this function after calling isValidValue.
        return coerce_value(type.of_type, value)

    if value is None:
        return None

    if isinstance(type, GraphQLList):
        item_type = type.of_type
        if not isinstance(value, str) and isinstance(value, Iterable):
            return [coerce_value(item_type, item) for item in value]
        else:
            return [coerce_value(item_type, value)]

    if isinstance(type, GraphQLInputObjectType):
        fields = type.fields
        obj = {}
        for field_name, field in fields.items():
            field_value = coerce_value(field.type, value.get(field_name))
            if field_value is None:
                field_value = field.default_value

            if field_value is not None:
                # We use out_name as the output name for the
                # dict if exists
                obj[field.out_name or field_name] = field_value

        return obj

    assert isinstance(type, (GraphQLScalarType, GraphQLEnumType)), \
        'Must be input type'

    return type.parse_value(value)

def hdbscan_delegator(model, func: str, embeddings: np.ndarray = None):
    try:
        import hdbscan
    except (ImportError, ModuleNotFoundError):
        hdbscan = type("hdbscan", (), {"HDBSCAN": None})()

    # Approximate predict
    if func == "approximate_predict":
        if isinstance(model, hdbscan.HDBSCAN):
            predictions, probabilities = hdbscan.approximate_predict(model, embeddings)
            return predictions, probabilities

        str_type_model = str(type(model)).lower()
        if "cuml" in str_type_model and "hdbscan" in str_type_model:
            from cuml.cluster import hdbscan as cuml_hdbscan

            predictions, probabilities = cuml_hdbscan.approximate_predict(model, embeddings)
            return predictions, probabilities

        predictions = model.predict(embeddings)
        return predictions, None

    # All points membership
    if func == "all_points_membership_vectors":
        if isinstance(model, hdbscan.HDBSCAN):
            return hdbscan.all_points_membership_vectors(model)

        str_type_model = str(type(model)).lower()
        if "cuml" in str_type_model and "hdbscan" in str_type_model:
            from cuml.cluster import hdbscan as cuml_hdbscan

            return cuml_hdbscan.all_points_membership_vectors(model)

        return None

    # membership_vector
    if func == "membership_vector":
        if isinstance(model, hdbscan.HDBSCAN):
            probabilities = hdbscan.membership_vector(model, embeddings)
            return probabilities

        str_type_model = str(type(model)).lower()
        if "cuml" in str_type_model and "hdbscan" in str_type_model:
            from cuml.cluster import hdbscan as cuml_hdbscan

            probabilities = cuml_hdbscan.membership_vector(model, embeddings)
            return probabilities

        return None

def dump_model(self, save_path: Optional[str] = None):
        if not save_path:
            save_path = self._save_path if self._save_path else "./"

        supported_models = {
            TIMM_IMAGE: TimmAutoModelForImagePrediction,
            HF_TEXT: HFAutoModelForTextPrediction,
            MMDET_IMAGE: MMDetAutoModelForObjectDetection,
        }

        models = defaultdict(list)
        # TODO: simplify the code
        if isinstance(self._model, AbstractMultimodalFusionModel) and isinstance(
            self._model.model, torch.nn.modules.container.ModuleList
        ):
            for per_model in self._model.model:
                for model_key, model_type in supported_models.items():
                    if isinstance(per_model, model_type):
                        models[model_key].append(per_model)
        else:
            for model_key, model_type in supported_models.items():
                if isinstance(self._model, model_type):
                    models[model_key].append(self._model)

        if not models:
            raise NotImplementedError(
                f"No models available for dump. Current supported models are: {supported_models.keys()}"
            )

        for model_key in models:
            for per_model in models[model_key]:
                subdir = os.path.join(save_path, per_model.prefix)
                os.makedirs(subdir, exist_ok=True)
                per_model.save(save_path=subdir)

        return save_path

def get_random_forward_sequence(self, with_mix: bool = True) -> Tuple[Iterator[Tuple[str, nn.Module]], bool]:
        if isinstance(self.random_apply, tuple):
            num_samples = int(torch.randint(*self.random_apply, (1,)).item())
        else:
            raise TypeError(f"random apply should be a tuple. Gotcha {type(self.random_apply)}")

        multinomial_weights = self.random_apply_weights.clone()
        # Mix augmentation can only be applied once per forward
        mix_indices = self.get_mix_augmentation_indices(self.named_children())

        multinomial_weights[mix_indices] = 0

        total_weight = multinomial_weights.sum()
        if total_weight == 0:
            indices = torch.tensor([], device=multinomial_weights.device, dtype=torch.long)
        else:
            indices = torch.multinomial(
                multinomial_weights,
                num_samples,
                replacement=num_samples > total_weight.item(),
            )

        mix_added = False
        if with_mix and len(mix_indices) != 0:
            # Make the selection fair.
            if (torch.rand(1) < ((len(mix_indices) + len(indices)) / len(self))).item():
                mix_idx = torch.multinomial((~multinomial_weights.bool()).float(), 1)
                if len(indices) == 0:
                    indices = mix_idx
                else:
                    indices[-1] = mix_idx
                indices = indices[torch.randperm(len(indices))]
                mix_added = True

        return self.get_children_by_indices(indices), mix_added

def pull_from_azure_blob_storage(
    container: str,
    folder: str,
    credentials: Dict[str, str],
):
    local_path = Path.cwd()
    if credentials.get("connection_string") is not None:
        container_client = ContainerClient.from_connection_string(
            credentials["connection_string"], container_name=container
        )
    elif credentials.get("account_url") is not None:
        container_client = ContainerClient(
            account_url=credentials["account_url"],
            container_name=container,
            credential=_get_azure_credential(credentials),
        )
    else:
        raise ValueError(
            "Credentials must contain either connection_string or account_url"
        )

    with container_client as client:
        for blob in client.list_blobs(name_starts_with=folder, include=["metadata"]):
            if blob.name.endswith("/"):
                continue
            blob_metadata = blob.metadata or {}
            if blob_metadata.get("hdi_isfolder") == "true":
                continue

            target = PurePosixPath(
                local_path
                / relative_path_to_current_platform(blob.name).relative_to(folder)
            )
            Path.mkdir(Path(target.parent), parents=True, exist_ok=True)
            with open(target, "wb") as f:
                client.download_blob(blob).readinto(f)

    return {
        "container": container,
        "folder": folder,
        "directory": local_path,
    }

def conditional_loss(
        self,
        model_pred: torch.Tensor,
        target: torch.Tensor,
        reduction: str = "mean",
        loss_type: str = "l2",
        huber_c: float = 0.1,
    ):
        if loss_type == "l2":
            loss = F.mse_loss(model_pred, target, reduction=reduction)
        elif loss_type == "huber":
            loss = 2 * huber_c * (torch.sqrt((model_pred - target) ** 2 + huber_c**2) - huber_c)
            if reduction == "mean":
                loss = torch.mean(loss)
            elif reduction == "sum":
                loss = torch.sum(loss)
        elif loss_type == "smooth_l1":
            loss = 2 * (torch.sqrt((model_pred - target) ** 2 + huber_c**2) - huber_c)
            if reduction == "mean":
                loss = torch.mean(loss)
            elif reduction == "sum":
                loss = torch.sum(loss)
        else:
            raise NotImplementedError(f"Unsupported Loss Type {loss_type}")
        return loss

def optimize_rng_use(fun):
  @functools.wraps(fun)
  def wrapper(*args, **kwargs):
    base.assert_context("optimize_rng_use")

    # Extract all current state.
    frame = base.current_frame()
    params = frame.params or None
    if params is not None:
      params = data_structures.to_haiku_dict(params)
    state = frame.state or None
    if state is not None:
      state = base.extract_state(state, initial=True)
    rng = frame.rng_stack.peek()
    if rng is not None:
      rng = rng.internal_state

    def pure_fun(params, state, rng, *args, **kwargs):
      with base.new_context(params=params, state=state, rng=rng):
        return fun(*args, **kwargs)

    with count_hk_rngs_requested() as rng_count_f:
      jax.eval_shape(pure_fun, params, state, rng, *args, **kwargs)
    rng_count = rng_count_f()

    if rng_count:
      base.current_frame().rng_stack.peek().reserve(rng_count)
    return fun(*args, **kwargs)

  return wrapper

def cocoeval(
    outputs: List,
    data: pd.DataFrame,
    anno_file: str,
    cache_path: str,
    metrics: Optional[Union[str, List]],
    tool="pycocotools",
):
    if (not tool) or tool == "pycocotools":
        result = cocoeval_pycocotools(outputs, data, anno_file, cache_path)
    elif tool == "torchmetrics":
        result = cocoeval_torchmetrics(outputs)
    else:
        raise ValueError(f"Unsupported eval_tool: {tool}")

    result = parse_detection_result(result)

    if metrics:
        if isinstance(metrics, str) and metrics.lower() in result:
            return {metrics.lower(): result[metrics.lower()]}
        elif isinstance(metrics, list):
            return {metric.lower(): result[metric.lower()] for metric in metrics}

    return result

def description_to_entityset(description, **kwargs):
    check_schema_version(description, "entityset")

    from featuretools.entityset import EntitySet

    # If data description was not read from disk, path is None.
    path = description.get("path")
    entityset = EntitySet(description["id"])

    for df in description["dataframes"].values():
        if path is not None:
            data_path = os.path.join(path, "data", df["name"])
            format = description.get("format")
            if format is not None:
                kwargs["format"] = format
                if format == "parquet" and df["loading_info"]["table_type"] == "pandas":
                    kwargs["filename"] = df["name"] + ".parquet"
            dataframe = read_woodwork_table(data_path, validate=False, **kwargs)
        else:
            dataframe = empty_dataframe(df)

        entityset.add_dataframe(dataframe)

    for relationship in description["relationships"]:
        rel = Relationship.from_dictionary(relationship, entityset)
        entityset.add_relationship(relationship=rel)

    return entityset

def visit_ClassDef(self, node: cst.ClassDef) -> None:
        if node.name.value == self.dataclass_name:
            body_statements = node.body.body
            for index, field in enumerate(body_statements):
                # Check if the statement is a simple statement (like a variable declaration)
                if isinstance(field, cst.SimpleStatementLine):
                    for stmt in field.body:
                        # Check if it's an annotated assignment (typical for dataclass fields)
                        if isinstance(stmt, cst.AnnAssign) and isinstance(stmt.target, cst.Name):
                            param_name = stmt.target.value
                            param_type = cst.Module([]).code_for_node(stmt.annotation.annotation)
                            docstring = self._extract_docstring(body_statements, index)
                            # Check if there's a default value
                            has_default = stmt.value is not None
                            default_value = cst.Module([]).code_for_node(stmt.value) if has_default else None

                            self.parameters[param_name] = {
                                "type": param_type,
                                "docstring": docstring,
                                "has_default": has_default,
                                "default_value": default_value,
                            }

def name(self, tag):
        for label in ["redundant", "grandfathered"]:
            val = None
            if tag in self.db[label]:
                val = f"{self.db[label][tag]['Description']}"
                note = f"The {tag!r} code is {label}"
            elif tag in self.db["deprecated"][label]:
                val = f"{self.db['deprecated'][label][tag]['Description']}"
                note = f"The {tag!r} code is {label} and deprecated"
                if "Preferred-Value" in self.db["deprecated"][label][tag]:
                    prefer = self.db["deprecated"][label][tag]["Preferred-Value"]
                    note += f", prefer {self.val2str(prefer)!r}"
            if val:
                warn(note)
                return val
        try:
            return self.lang2str(self.parse_tag(tag))
        except Exception:
            warn(f"Tag {tag!r} was not recognized")
            return None

def convert_constant_nodes_to_const_ops(tfssa):
    for fn_key in list(tfssa.functions.keys()):
        f = tfssa.functions[fn_key]
        for k in list(f.graph.keys()):
            v = f.graph.get(k, None)
            if v is None:
                continue
            if v.value is not None:
                v.op = "Const"
                # delete all upstream edges now that this is constant
                inv = v.inputs[:]
                for i in inv:
                    curnode = i
                    nextnode = v.name
                    disconnect_edge(f.graph, curnode, nextnode)

                    # keep deleting upwards as long as it is a chain
                    while curnode is not None:
                        prevnode = None
                        if len(f.graph[curnode].outputs) == 0:
                            if len(f.graph[curnode].inputs) == 1:
                                prevnode = f.graph[curnode].inputs[0]
                            delete_node(f.graph, curnode)
                        curnode = prevnode

def compose_input_data(x: List[Union[Tuple[Union[np.ndarray, list, spmatrix, str]],
                                         List[Union[np.ndarray, list, spmatrix, str]],
                                         np.ndarray, spmatrix]]) -> Union[spmatrix, np.ndarray]:
        x_features = []
        for i in range(len(x)):
            if ((isinstance(x[i], tuple) or isinstance(x[i], list) or isinstance(x[i], np.ndarray) and len(x[i]))
                    or (issparse(x[i]) and x[i].shape[0])):
                if issparse(x[i][0]):
                    x_features.append(vstack(list(x[i])))
                elif isinstance(x[i][0], np.ndarray) or isinstance(x[i][0], list):
                    x_features.append(np.vstack(list(x[i])))
                elif isinstance(x[i][0], str):
                    x_features.append(np.array(x[i]))
                else:
                    raise ConfigError('Not implemented this type of vectors')
            else:
                raise ConfigError("Input vectors cannot be empty")

        sparse = False
        for inp in x_features:
            if issparse(inp):
                sparse = True
        if sparse:
            x_features = hstack(list(x_features))
        else:
            x_features = np.hstack(list(x_features))

        return x_features

def gen_table_creation_query(
    dtypes: Mapping[str, str],
    schema_name: str,
    table_name: str,
    auto_clean_name: bool = True,
    case_sensitive: bool = False,
    unique_constraints: List[str] = None,
    overwrite_types: Dict = None,
    skip_semicolon_at_end: bool = False,
) -> str:
    if unique_constraints is None:
        unique_constraints = []
    query = []
    for cname in dtypes:
        if overwrite_types is not None and cname in overwrite_types.keys():
            dtypes[cname] = overwrite_types[cname]

        if auto_clean_name:
            cleaned_col_name = clean_name(cname, case_sensitive=case_sensitive)
        else:
            cleaned_col_name = cname

        query.append(f'"{cleaned_col_name}" {dtypes[cname]}')

    if schema_name:
        full_table_name = f'{schema_name}.{table_name}'
    else:
        full_table_name = table_name

    if unique_constraints:
        unique_constraints_clean = []
        for col in unique_constraints:
            if auto_clean_name:
                cleaned_col_name = clean_name(col, case_sensitive=case_sensitive)
            else:
                cleaned_col_name = col
            unique_constraints_clean.append(cleaned_col_name)
        unique_constraints_escaped = [f'"{col}"'
                                      for col in unique_constraints_clean]
        index_name = '_'.join([
            clean_name(full_table_name, case_sensitive=case_sensitive),
        ] + unique_constraints_clean)
        index_name = f'unique{index_name}'[:64]
        query.append(
            f"CONSTRAINT {index_name} UNIQUE ({', '.join(unique_constraints_escaped)})",
        )
    if skip_semicolon_at_end:
        return f'CREATE TABLE {full_table_name} (' + ','.join(query) + ')'
    return f'CREATE TABLE {full_table_name} (' + ','.join(query) + ');'

def generate_pip_from_conda(
    conda_path: pathlib.Path, pip_path: pathlib.Path, compare: bool = False
) -> bool:
    with conda_path.open() as file:
        deps = yaml.safe_load(file)["dependencies"]

    pip_deps = []
    for dep in deps:
        if isinstance(dep, str):
            conda_dep = conda_package_to_pip(dep)
            if conda_dep:
                pip_deps.append(conda_dep)
        elif isinstance(dep, dict) and len(dep) == 1 and "pip" in dep:
            pip_deps.extend(dep["pip"])
        else:
            raise ValueError(f"Unexpected dependency {dep}")

    header = (
        f"# This file is auto-generated from {conda_path.name}, do not modify.\n"
        "# See that file for comments about the need/usage of each dependency.\n\n"
    )
    pip_content = header + "\n".join(pip_deps) + "\n"

    if compare:
        with pip_path.open() as file:
            return pip_content != file.read()

    with pip_path.open("w") as file:
        file.write(pip_content)
    return False

def forward(
        self,
        y: np.ndarray,
        h: int,
        X: Optional[np.ndarray] = None,
        X_future: Optional[np.ndarray] = None,
        level: Optional[List[int]] = None,
        fitted: bool = False,
    ):
        if not hasattr(self, "model_"):
            raise Exception("You have to use the `fit` method first")
        y = _ensure_float(y)
        mod = forward_ces(self.model_, y=y)
        fcst = forecast_ces(mod, h, level=level)
        keys = ["mean"]
        if fitted:
            keys.append("fitted")
        res = {key: fcst[key] for key in keys}
        if level is not None:
            level = sorted(level)
            if self.prediction_intervals is not None:
                res = self._add_conformal_intervals(fcst=res, y=y, X=X, level=level)
            else:
                res = {
                    **res,
                    **{f"lo-{l}": fcst[f"lo-{l}"] for l in reversed(level)},
                    **{f"hi-{l}": fcst[f"hi-{l}"] for l in level},
                }
            if fitted:
                # add prediction intervals for fitted values
                se = _calculate_sigma(y - mod["fitted"], len(y))
                res = _add_fitted_pi(res=res, se=se, level=level)
        return res

def get_gpu_requirements(runtime_config: Dict[str, Any]) -> Tuple[int, Optional[List[int]]]:
    # Get num_processes from various sources
    num_processes = runtime_config.get("--num_processes") or runtime_config.get("num_processes") or 1
    try:
        num_processes = max(1, int(num_processes))
    except (TypeError, ValueError):
        num_processes = 1

    # Get device_ids if specified
    device_ids: Optional[List[int]] = None
    raw_device_ids = runtime_config.get("--accelerate_visible_devices") or runtime_config.get("accelerate_visible_devices")

    if raw_device_ids:
        if isinstance(raw_device_ids, str):
            parsed = []
            for token in raw_device_ids.split(","):
                token = token.strip()
                if token:
                    try:
                        parsed.append(int(token))
                    except ValueError:
                        pass
            if parsed:
                device_ids = parsed
        elif isinstance(raw_device_ids, (list, tuple)):
            parsed = []
            for item in raw_device_ids:
                try:
                    parsed.append(int(item))
                except (TypeError, ValueError):
                    pass
            if parsed:
                device_ids = parsed

    return (num_processes, device_ids)

def normalize_workflow_reference(workflow_value):
    if workflow_value is None:
        return None
    if isinstance(workflow_value, dict):
        return (
            workflow_value.get("id")
            or workflow_value.get("_id")
            or workflow_value.get("workflow_id")
        )
    if isinstance(workflow_value, str):
        value = workflow_value.strip()
        if not value:
            return ""
        try:
            parsed = json.loads(value)
            if isinstance(parsed, str):
                return parsed.strip()
            if isinstance(parsed, dict):
                return (
                    parsed.get("id") or parsed.get("_id") or parsed.get("workflow_id")
                )
        except json.JSONDecodeError:
            pass
        return value
    return str(workflow_value)

def debug(self, kind="ipdb"):
        if self.source.language != "python":
            raise NotImplementedError(
                'debug is not implemented for "{}" '
                "notebooks, only python is supported".format(self.source.language)
            )

        opts = {"ipdb", "pdb", "pm"}

        if kind not in opts:
            raise ValueError("kind must be one of {}".format(opts))

        nb = _read_rendered_notebook(self.source.nb_str_rendered)
        fd, tmp_path = tempfile.mkstemp(suffix=".py")
        os.close(fd)
        code = jupytext.writes(nb, version=nbformat.NO_CONVERT, fmt="py")
        _write_text_utf_8(tmp_path, code)

        if kind == "pm":
            # post-mortem debugging
            try:
                subprocess.run(["ipython", tmp_path, "--pdb"])
            finally:
                Path(tmp_path).unlink()
        else:
            if kind == "ipdb":
                from IPython.terminal.debugger import TerminalPdb, Pdb

                code = compile(source=code, filename=tmp_path, mode="exec")

                try:
                    # this seems to only work in a Terminal
                    debugger = TerminalPdb()
                except Exception:
                    # this works in a Jupyter notebook
                    debugger = Pdb()

            elif kind == "pdb":
                debugger = pdb

            try:
                debugger.run(code)
            finally:
                Path(tmp_path).unlink()

def FindInitializationErrors(self):
    errors = []  # simplify things

    for field in required_fields:
      if not self.HasField(field.name):
        errors.append(field.name)

    for field, value in self.ListFields():
      if field.cpp_type == _FieldDescriptor.CPPTYPE_MESSAGE:
        if field.is_extension:
          name = '(%s)' % field.full_name
        else:
          name = field.name

        if _IsMapField(field):
          if _IsMessageMapField(field):
            for key in value:
              element = value[key]
              prefix = '%s[%s].' % (name, key)
              sub_errors = element.FindInitializationErrors()
              errors += [prefix + error for error in sub_errors]
          else:
            # ScalarMaps can't have any initialization errors.
            pass
        elif field.label == _FieldDescriptor.LABEL_REPEATED:
          for i in range(len(value)):
            element = value[i]
            prefix = '%s[%d].' % (name, i)
            sub_errors = element.FindInitializationErrors()
            errors += [prefix + error for error in sub_errors]
        else:
          prefix = name + '.'
          sub_errors = value.FindInitializationErrors()
          errors += [prefix + error for error in sub_errors]

    return errors

def toggle(self, all=None, ticks=None, ticklabels=None, label=None):
        if all:
            _ticks, _ticklabels, _label = True, True, True
        elif all is not None:
            _ticks, _ticklabels, _label = False, False, False
        else:
            _ticks, _ticklabels, _label = None, None, None

        if ticks is not None:
            _ticks = ticks
        if ticklabels is not None:
            _ticklabels = ticklabels
        if label is not None:
            _label = label

        if _ticks is not None:
            self.major_ticks.set_visible(_ticks)
            self.minor_ticks.set_visible(_ticks)
        if _ticklabels is not None:
            self.major_ticklabels.set_visible(_ticklabels)
            self.minor_ticklabels.set_visible(_ticklabels)
        if _label is not None:
            self.label.set_visible(_label)

def from_pretrained(cls, pretrained_model_name_or_path, cache_dir=None, *inputs, **kwargs):
        vocab = TransfoXLTokenizer.from_pretrained(pretrained_model_name_or_path, *inputs, **kwargs)
        is_local = os.path.isdir(pretrained_model_name_or_path)
        # redirect to the cache, if necessary
        try:
            resolved_corpus_file = cached_file(pretrained_model_name_or_path, CORPUS_NAME, cache_dir=cache_dir)
        except EnvironmentError:
            logger.error(
                f"Corpus '{pretrained_model_name_or_path}' was not found in corpus list"
                f" ({', '.join(PRETRAINED_CORPUS_ARCHIVE_MAP.keys())}. We assumed '{pretrained_model_name_or_path}'"
                f" was a path or url but couldn't find files {CORPUS_NAME} at this path or url."
            )
            return None
        if is_local:
            logger.info(f"loading corpus file {resolved_corpus_file}")
        else:
            logger.info(f"loading corpus file {CORPUS_NAME} from cache at {resolved_corpus_file}")

        # Instantiate tokenizer.
        corpus = cls(*inputs, **kwargs)
        corpus_dict = torch.load(resolved_corpus_file)
        for key, value in corpus_dict.items():
            corpus.__dict__[key] = value
        corpus.vocab = vocab
        if corpus.train is not None:
            corpus.train = torch.tensor(corpus.train, dtype=torch.long)
        if corpus.valid is not None:
            corpus.valid = torch.tensor(corpus.valid, dtype=torch.long)
        if corpus.test is not None:
            corpus.test = torch.tensor(corpus.test, dtype=torch.long)
        return corpus

def as_dict(self):
    if self._dict is None:
      self._dict = dict()

      if self._proto.timesteps:
        initial_timestep = self._proto.timesteps[0]

        num_walkers = len(initial_timestep.walkers)
        for i in range(num_walkers):
          key_prefix = 'walker_{:d}/'.format(
              i) if num_walkers > 1 else 'walker/'
          for field in mocap_pb2.WalkerPose.DESCRIPTOR.fields:
            field_name = field.name

            def walker_field(timestep, i=i, field_name=field_name):
              values = getattr(timestep.walkers[i], field_name)
              if field_name in _REPEATED_POSITION_FIELDS:
                values = np.reshape(values, (-1, 3))
              elif field_name in _REPEATED_QUATERNION_FIELDS:
                values = np.reshape(values, (-1, 4))
              return np.array(values)

            self._dict[key_prefix + field_name] = walker_field

        num_props = len(initial_timestep.props)
        for i in range(len(initial_timestep.props)):
          key_prefix = 'prop_{:d}/'.format(i) if num_props > 1 else 'prop/'
          for field in mocap_pb2.PropPose.DESCRIPTOR.fields:
            field_name = field.name

            def prop_field(timestep, i=i, field_name=field_name):
              return np.array(getattr(timestep.props[i], field_name))

            self._dict[key_prefix + field_name] = prop_field

        self._create_all_items(self._dict)
        for k in self._dict:
          # make trajectory immutable by default
          self._dict[k].flags.writeable = False  # pytype: disable=attribute-error

    return {k: v[self._start_step:self._end_step]
            for k, v in self._dict.items()}

def handle_legacy_message_from_msgtype(
    client_fn: ClientFnExt, message: Message, context: Context
) -> Message:
    client = client_fn(context)

    # Check if NumPyClient is returend
    if isinstance(client, NumPyClient):
        client = client.to_client()
        log(
            WARN,
            "Deprecation Warning: The `client_fn` function must return an instance "
            "of `Client`, but an instance of `NumpyClient` was returned. "
            "Please use `NumPyClient.to_client()` method to convert it to `Client`.",
        )

    message_type = message.metadata.message_type

    # Handle GetPropertiesIns
    if message_type == MessageTypeLegacy.GET_PROPERTIES:
        get_properties_res = maybe_call_get_properties(
            client=client,
            get_properties_ins=recorddict_to_getpropertiesins(message.content),
        )
        out_recorddict = getpropertiesres_to_recorddict(get_properties_res)
    # Handle GetParametersIns
    elif message_type == MessageTypeLegacy.GET_PARAMETERS:
        get_parameters_res = maybe_call_get_parameters(
            client=client,
            get_parameters_ins=recorddict_to_getparametersins(message.content),
        )
        out_recorddict = getparametersres_to_recorddict(
            get_parameters_res, keep_input=False
        )
    # Handle FitIns
    elif message_type == MessageType.TRAIN:
        fit_res = maybe_call_fit(
            client=client,
            fit_ins=recorddict_to_fitins(message.content, keep_input=True),
        )
        out_recorddict = fitres_to_recorddict(fit_res, keep_input=False)
    # Handle EvaluateIns
    elif message_type == MessageType.EVALUATE:
        evaluate_res = maybe_call_evaluate(
            client=client,
            evaluate_ins=recorddict_to_evaluateins(message.content, keep_input=True),
        )
        out_recorddict = evaluateres_to_recorddict(evaluate_res)
    else:
        raise ValueError(f"Invalid message type: {message_type}")

    # Return Message
    return Message(out_recorddict, reply_to=message)

def log_metrics(
        self,
        x: dict[str, torch.Tensor],
        y: torch.Tensor,
        out: dict[str, torch.Tensor],
        prediction_kwargs: dict[str, Any] = None,
    ) -> None:
        # logging losses - for each target
        if prediction_kwargs is None:
            prediction_kwargs = {}
        y_hat_point = self.to_prediction(out, **prediction_kwargs)
        if isinstance(self.loss, MultiLoss):
            y_hat_point_detached = [p.detach() for p in y_hat_point]
        else:
            y_hat_point_detached = [y_hat_point.detach()]

        for metric in self.logging_metrics:
            for idx, y_point, y_part, encoder_target in zip(
                list(range(len(y_hat_point_detached))),
                y_hat_point_detached,
                to_list(y[0]),
                to_list(x["encoder_target"]),
            ):
                y_true = (y_part, y[1])
                if isinstance(metric, MASE):
                    loss_value = metric(
                        y_point,
                        y_true,
                        encoder_target=encoder_target,
                        encoder_lengths=x["encoder_lengths"],
                    )
                else:
                    loss_value = metric(y_point, y_true)
                if len(y_hat_point_detached) > 1:
                    target_tag = self.target_names[idx] + " "
                else:
                    target_tag = ""
                self.log(
                    f"{target_tag}{self.current_stage}_{metric.name}",
                    loss_value,
                    on_step=self.training,
                    on_epoch=True,
                    batch_size=len(x["decoder_target"]),
                )

def combine_signatures(sig1: Union[inspect.Signature, None], sig2: Union[inspect.Signature, None]):
    if sig1 is None:
        return sig2
    if sig2 is None:
        return sig1

    # Get all params from sig1
    sig1 = deepcopy(sig1)
    params = list(sig1.parameters.values())
    for n, param in enumerate(params):
        if param.kind in {inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD}:
            break
    else:
        n = len(params)

    # Add non-overlapping params from sig2
    for param in sig2.parameters.values():
        if param.kind in {inspect.Parameter.VAR_POSITIONAL, inspect.Parameter.VAR_KEYWORD}:
            break
        if param.name not in sig1.parameters:
            params.insert(n, param)
            n += 1

    return sig1.replace(parameters=params)

def get_upsampled_coco(
        self, upsample_ratio: int = 2, category_id: int = None
    ):
        upsampled_coco = Coco(
            name=self.name,
            image_dir=self.image_dir,
            remapping_dict=self.remapping_dict,
            ignore_negative_samples=self.ignore_negative_samples,
        )
        upsampled_coco.add_categories_from_coco_category_list(
            self.json_categories
        )
        for ind in range(upsample_ratio):
            for image_ind in range(len(self.images)):
                # calculate add_this_image
                if category_id is not None:
                    category_id_to_contains = defaultdict(lambda: 0)
                    annotation: CocoAnnotation
                    for annotation in self.images[image_ind].annotations:
                        category_id_to_contains[annotation.category_id] = 1
                    if category_id_to_contains[category_id]:
                        add_this_image = True
                    elif (
                        category_id == -1
                        and len(self.images[image_ind].annotations) == 0
                    ):
                        # if category_id is given as -1, select negative samples
                        add_this_image = True
                    elif ind == 0:
                        # in first iteration add all images
                        add_this_image = True
                    else:
                        add_this_image = False
                else:
                    add_this_image = True

                if add_this_image:
                    upsampled_coco.add_image(self.images[image_ind])

        return upsampled_coco

def to_dataframe(
        self, include_units: bool = False, include_delegate_debug_data: bool = False
    ) -> pd.DataFrame:

        units = " (" + self.target_time_scale.value + ")" if include_units else ""

        df = pd.concat([e.to_dataframe(units) for e in self.events], ignore_index=True)
        df.insert(
            0,
            "event_block_name",
            np.asarray([self.name for _ in range(len(self.events))]),
            allow_duplicates=True,
        )

        # Add Delegate Debug Metadata columns
        if include_delegate_debug_data:
            delegate_data = []
            for event in self.events:
                if (metadata := event.delegate_debug_metadatas) is not None and len(
                    metadata
                ) > 0:
                    if isinstance(metadata, list):
                        delegate_data.append(
                            pd.Series([metadata], index=["delegate_debug_metadata"])
                        )
                    elif isinstance(metadata, dict):
                        delegate_data.append(pd.Series(metadata))
                    else:
                        raise ValueError(
                            f"Unexpected type for delegate_debug_metadata: {type(metadata)}"
                        )
                else:
                    delegate_data.append(pd.Series())

            if any(not data.empty for data in delegate_data):
                df = pd.concat([df, pd.DataFrame(delegate_data)], axis=1)

        return df

def load_basisset(basis, element):
    try:
        # pylint: disable=import-outside-toplevel
        import basis_set_exchange as bse
    except ImportError as Error:
        raise ImportError(
            "This feature requires basis_set_exchange. "
            "It can be installed with: pip install basis-set-exchange."
        ) from Error

    orbital_map = {
        "[0]": "S",
        "[0, 1]": "SP",
        "[0, 1, 2]": "SPD",
        "[1]": "P",
        "[2]": "D",
        "[3]": "F",
        "[4]": "G",
        "[5]": "H",
        "[6]": "I",
    }

    atomic_number = atomic_numbers.get(element, None)
    if atomic_number is None:
        raise ValueError(f"Requested element {element} doesn't exist in the periodic table.")

    data = bse.get_basis(basis)["elements"][str(atomic_number)]["electron_shells"]

    orbitals = []
    exponents = []
    coefficients = []

    for term in data:
        if orbital_map[str(term["angular_momentum"])] == "SP":
            orbitals.append(["S", "P"])
        else:
            orbitals.append(
                [orbital_map[str(term["angular_momentum"])]] * len(term["coefficients"])
            )
        exponents.append(
            [list(map(float, item)) for item in [term["exponents"]] * len(term["coefficients"])]
        )
        coefficients.append([list(map(float, item)) for item in term["coefficients"]])

    return {
        "orbitals": list(itertools.chain(*orbitals)),
        "exponents": list(itertools.chain(*exponents)),
        "coefficients": list(itertools.chain(*coefficients)),
    }

def detect_function_type(cls, fn: Callable) -> FunctionType:
        if fn is None:
            raise ValueError("Function cannot be None")

        # Check for async generator functions
        if inspect.isasyncgenfunction(fn):
            return FunctionType.ASYNC_GENERATOR

        # Check for sync generator functions
        if inspect.isgeneratorfunction(fn):
            return FunctionType.SYNC_GENERATOR

        # Check for async functions (coroutines)
        if inspect.iscoroutinefunction(fn):
            return FunctionType.ASYNC

        # Check for regular functions
        if inspect.isfunction(fn) or inspect.ismethod(fn):
            return FunctionType.SYNC

        # Check for callable objects (like classes with __call__)
        if callable(fn):
            # For callable objects, we need to check their __call__ method
            if hasattr(fn, "__call__"):
                call_method = fn.__call__
                if inspect.ismethod(call_method):
                    # It's a bound method, check the underlying function
                    if inspect.isasyncgenfunction(call_method.__func__):
                        return FunctionType.ASYNC_GENERATOR
                    elif inspect.isgeneratorfunction(call_method.__func__):
                        return FunctionType.SYNC_GENERATOR
                    elif inspect.iscoroutinefunction(call_method.__func__):
                        return FunctionType.ASYNC
                    else:
                        return FunctionType.SYNC
                else:
                    # It's a function, check directly
                    if inspect.isasyncgenfunction(call_method):
                        return FunctionType.ASYNC_GENERATOR
                    elif inspect.isgeneratorfunction(call_method):
                        return FunctionType.SYNC_GENERATOR
                    elif inspect.iscoroutinefunction(call_method):
                        return FunctionType.ASYNC
                    else:
                        return FunctionType.SYNC

        raise ValueError(f"Cannot determine function type for {fn}")

def scalar_to_proto(scalar: typing.Scalar) -> Scalar:
    if isinstance(scalar, bool):
        return Scalar(bool=scalar)

    if isinstance(scalar, bytes):
        return Scalar(bytes=scalar)

    if isinstance(scalar, float):
        return Scalar(double=scalar)

    if isinstance(scalar, int):
        # Use uint64 for integers larger than the maximum value of sint64
        if scalar > INT64_MAX_VALUE:
            return Scalar(uint64=scalar)
        return Scalar(sint64=scalar)

    if isinstance(scalar, str):
        return Scalar(string=scalar)

    raise ValueError(
        f"Accepted types: {bool, bytes, float, int, str} (but not {type(scalar)})"
    )

def cmd_cloud(args) -> int:
    cloud_action = getattr(args, "cloud_action", None)

    if cloud_action is None:
        print("Error: Please specify a cloud command.")
        print("Usage: simpletuner cloud <command>")
        print("\nRun 'simpletuner cloud --help' for available commands.")
        return 1

    # Jobs subcommand group
    if cloud_action == "jobs":
        return _dispatch_cloud_jobs(args)

    # Configuration commands
    elif cloud_action == "config":
        return config.cmd_cloud_config(args)
    elif cloud_action == "cost-limit":
