def normalize(word):
    if not isinstance(word, str):
        word = str(word)
    if not isinstance(word, str):
        try:
            word = word.encode("utf-8", "ignore")
        except:
            pass
    for k, v in DIACRITICS.items():
        for v in v:
            word = word.replace(v, k)

    # Replace spaces with underscores
    word = word.replace(" ", "_")

    return word

def walk_directory(path: Path, suffix: Optional[str] = None) -> List[Path]:
    if not path.is_dir():
        return [path]
    paths = [path]
    locs = []
    seen = set()
    for path in paths:
        if str(path) in seen:
            continue
        seen.add(str(path))
        if path.parts[-1].startswith("."):
            continue
        elif path.is_dir():
            paths.extend(path.iterdir())
        elif suffix is not None and not path.parts[-1].endswith(suffix):
            continue
        else:
            locs.append(path)
    # It's good to sort these, in case the ordering messes up cache.
    locs.sort()
    return locs

def read_audio_file(input_file):
    sampling_rate = 0
    signal = np.array([])
    if isinstance(input_file, str):
        extension = os.path.splitext(input_file)[1].lower()
        if extension in ['.aif', '.aiff']:
            sampling_rate, signal = read_aif(input_file)
        elif extension in ['.wav']:
            sampling_rate, signal = wavfile.read(input_file) # from scipy.io
        elif extension in [".mp3", ".au", ".ogg"]:
            sampling_rate, signal = read_audio_generic(input_file)
        else:
            print("Error: unknown file type {extension}")
    else:
        sampling_rate, signal = read_audio_generic(input_file)

    if signal.ndim == 2 and signal.shape[1] == 1:
        signal = signal.flatten()

    return sampling_rate, signal

def has_fixture_decorator(node: ast.AST) -> bool:
    if not hasattr(node, "decorator_list"):
        return False
    if len(node.decorator_list) != 1:
        return False
    decorator = node.decorator_list[0]
    # @fixture or @fixture()
    if isinstance(decorator, ast.Name) and decorator.id == "fixture":
        return True
    if isinstance(decorator, ast.Call):
        func = decorator.func
        if isinstance(func, ast.Name) and func.id == "fixture":
            return True
    # @pytest.fixture or @pytest.fixture()
    is_pytest, attr = is_pytest_decorator(decorator)
    return is_pytest and attr == "fixture"

def make_container_ports_from_str_list(
    port_strings: List[str], *, strategy_free: bool = False
) -> List[ContainerPort]:

    parsed_ports = [
        make_container_port_from_string(p, strategy_free=strategy_free)
        for p in port_strings
    ]

    # Ensure at most one proxy across all ports
    if not strategy_free:
        proxy_count = sum(
            1
            for cp in parsed_ports
            if cp.expose_strategies
            and ContainerPortExposeStrategy.INGRESS_PROXY in cp.expose_strategies
        )
        if proxy_count > 1:
            raise ValueError(
                "Only one container port may use the 'proxy' strategy within a single"
                " job."
            )

    # Ensure no duplicate container_port numbers
    seen_ports = set()
    for cp in parsed_ports:
        if cp.container_port in seen_ports:
            raise ValueError(
                f"Duplicate container port '{cp.container_port}' detected in definition"
                " list."
            )
        seen_ports.add(cp.container_port)

    return parsed_ports

def pause(self):
        if self._running_free:
            for pipe in self.pipes:
                pipe.send((None, "pause"))
            # Make sure all workers are paused
            for i in range(len(self.pipes)):
                # Use timeout with health check to avoid hanging if a worker dies
                timeout = 30.0
                check_interval = 1.0
                elapsed = 0.0
                while elapsed < timeout:
                    try:
                        idx, msg = self.queue_out.get(timeout=check_interval)
                        break
                    except Exception:
                        elapsed += check_interval
                        _check_for_faulty_process(self.procs)
                else:
                    _check_for_faulty_process(self.procs)
                    raise TimeoutError(
                        f"Timed out waiting for worker {i} to pause after {timeout}s"
                    )
                if msg != "paused":
                    raise ValueError(f"Expected paused, but got {msg=}.")
                torchrl_logger.debug(f"Worker {idx} is paused.")
            self._running_free = False
            yield None
            for pipe in self.pipes:
                pipe.send((None, "restart"))
            self._running_free = True
        else:
            raise RuntimeError("Collector cannot be paused.")

def emit(self, record):
        try:
            if record.exc_info:
                _, exc, *_ = record.exc_info
                if hasattr(exc, "__pretty_exc__"):
                    try:
                        self.emit_pretty_exception(exc, verbose=_is_verbose())
                        if not _is_verbose():
                            return
                    except Exception:  # noqa: BLE001, S110
                        pass

            msg = self.format(record)
            Tqdm.write(msg, file=self.stream, end=getattr(self, "terminator", "\n"))
            self.flush()
        except (BrokenPipeError, RecursionError):
            raise
        except Exception:  # noqa: BLE001
            self.handleError(record)

def update_usage(self, rowwise_usage: bool = None, columnwise_usage: bool = None):
        if self.rowwise_gemm_tensor is not self.columnwise_gemm_tensor:
            # If the same object is used both for rowwise and columnwise gemms,
            # there is no benefit in erasing the usage of one of them.
            # And there are scenarios when not deleting the usage of one of them is needed.
            # For example when we want to recreate columnwise from rowwise.
            if rowwise_usage is False:
                self.rowwise_gemm_tensor = None
            if columnwise_usage is False:
                self.columnwise_gemm_tensor = None

        if isinstance(self.rowwise_gemm_tensor, QuantizedTensor):
            self.rowwise_gemm_tensor.update_usage(rowwise_usage, columnwise_usage)
        if isinstance(self.columnwise_gemm_tensor, QuantizedTensor):
            self.columnwise_gemm_tensor.update_usage(rowwise_usage, columnwise_usage)

        if rowwise_usage and self.rowwise_gemm_tensor is None:
            raise RuntimeError(
                "Cannot recreate rowwise tensor from columnwise tensor in debug mode."
            )

        if columnwise_usage and self.columnwise_gemm_tensor is None:
            raise RuntimeError(
                "Cannot recreate columnwise tensor from rowwise tensor is debug mode."
            )

def calculus_integrate(alphabet_size=26,
                       min_depth=0,
                       max_depth=2,
                       nbr_cases=10000):
  if max_depth < min_depth:
    raise ValueError("max_depth must be greater than or equal to min_depth. "
                     "Got max_depth=%s, min_depth=%s" % (max_depth, min_depth))

  # Don't allow alphabet to use capital letters. Those are reserved for function
  # names.
  if alphabet_size > 26:
    raise ValueError(
        "alphabet_size must not be greater than 26. Got %s." % alphabet_size)

  functions = {"log": "L"}
  alg_cfg = math_dataset_init(alphabet_size, digits=5, functions=functions)
  nbr_case = 0
  while nbr_case < nbr_cases:
    try:
      sample, target = generate_calculus_integrate_sample(
          alg_cfg.vlist,
          list(alg_cfg.ops.values()), min_depth, max_depth, alg_cfg.functions)
      yield {
          "inputs": alg_cfg.int_encoder(sample),
          "targets": alg_cfg.int_encoder(target)
      }
    except:  # pylint:disable=bare-except
      continue
    if nbr_case % 10000 == 0:
      print(" calculus_integrate: generating case %d." % nbr_case)
    nbr_case += 1

def parse_prompt_attention(text):
    res = []
    round_brackets = []
    square_brackets = []

    round_bracket_multiplier = 1.1
    square_bracket_multiplier = 1 / 1.1

    def multiply_range(start_position, multiplier):
        for p in range(start_position, len(res)):
            res[p][1] *= multiplier

    for m in re_attention.finditer(text):
        text = m.group(0)
        weight = m.group(1)

        if text.startswith('\\'):
            res.append([text[1:], 1.0])
        elif text == '(':
            round_brackets.append(len(res))
        elif text == '[':
            square_brackets.append(len(res))
        elif weight is not None and len(round_brackets) > 0:
            multiply_range(round_brackets.pop(), float(weight))
        elif text == ')' and len(round_brackets) > 0:
            multiply_range(round_brackets.pop(), round_bracket_multiplier)
        elif text == ']' and len(square_brackets) > 0:
            multiply_range(square_brackets.pop(), square_bracket_multiplier)
        else:
            res.append([text, 1.0])

    for pos in round_brackets:
        multiply_range(pos, round_bracket_multiplier)

    for pos in square_brackets:
        multiply_range(pos, square_bracket_multiplier)

    if len(res) == 0:
        res = [['', 1.0]]

    # merge runs of identical weights
    i = 0
    while i + 1 < len(res):
        if res[i][1] == res[i + 1][1]:
            res[i][0] += res[i + 1][0]
            res.pop(i + 1)
        else:
            i += 1

    return res

def prep_ckpt_file_path(self, trainer_state: Dict[str, Any] = None):
        if self.ckpt_file:
            return
        from adalflow.utils.global_config import get_adalflow_default_root_path

        if self.ckpt_path is None:
            default_root_path = get_adalflow_default_root_path()
            self.ckpt_path = os.path.join(
                default_root_path, "ckpt", self.adaltask.__class__.__name__
            )
            logger.debug(f"Checkpoint path: {self.ckpt_path}")
        os.makedirs(self.ckpt_path, exist_ok=True)
        # list all existing checkpoints with the same file name prefix
        hash_key = (
            trainer_state["hash_key"]
            if trainer_state and "hash_key" in trainer_state
            else str(uuid.uuid4())
        )

        # Add Gumbel configuration to filename
        gumbel_suffix = ""
        if hasattr(self, "use_gumbel_top_k") and self.use_gumbel_top_k:
            gumbel_suffix = "_gumbel"
            if hasattr(self, "use_evaluate_top_k") and self.use_evaluate_top_k:
                gumbel_suffix += f"_etopk{self.evaluate_top_k_k}"

        file_name_prefix = (
            f"{self.strategy}_max_steps_{self.max_steps}{gumbel_suffix}_{hash_key}"
        )
        ckpt_files = [
            f for f in os.listdir(self.ckpt_path) if f.startswith(file_name_prefix)
        ]
        run: int = 1

        if ckpt_files:
            # Sort files based on last modification time
            ckpt_files.sort(
                key=lambda x: os.path.getmtime(os.path.join(self.ckpt_path, x)),
                reverse=True,
            )
            latest_ckpt_file = ckpt_files[0]
            # get the run number
            run = int(latest_ckpt_file.split("_run_")[-1].split(".json")[0]) + 1
        else:
            latest_ckpt_file = None

        self.ckpt_file = os.path.join(
            self.ckpt_path, f"{file_name_prefix}_run_{run}.json"
        )

def step_if_break_fusion(
        self,
        subgraphs: List[Subgraph],
        leaf_nodes: set[torch.fx.Node],
        nodes_in_first_subgraph: set[torch.fx.Node],
        nodes_in_second_subgraph: set[torch.fx.Node],
    ) -> bool:

        def add_nodes(node: torch.fx.Node) -> None:
            """
            This function adds a node and all its previous nodes to the first subgraph and removes it from the second subgraph in post order.
            """
            if (
                node.op in CALLABLE_NODE_OPS
                and node not in nodes_in_first_subgraph
                and node in nodes_in_second_subgraph
            ):
                # Exclude all nodes already in the first subgraph
                nodes_in_first_subgraph.add(node)
                nodes_in_second_subgraph.remove(node)
                for input_node in node._input_nodes:
                    add_nodes(input_node)
                subgraphs[0].nodes.append(node)
                subgraphs[1].nodes.remove(node)

        fusion_broken = False
        for leaf in leaf_nodes:
            for node in self.fusion_patterns.get(leaf, []):
                if (
                    node not in nodes_in_first_subgraph
                    and node in nodes_in_second_subgraph
                ):
                    fusion_broken = True
                    add_nodes(node)

        return fusion_broken

def autosave_swarm(
    swarm_instance: Any,
    swarm_workspace_dir: Optional[str] = None,
    save_config: bool = True,
    save_state: bool = True,
    save_metadata: bool = False,
    execution_result: Optional[Any] = None,
    additional_data: Optional[Dict[str, Any]] = None,
) -> Dict[str, Optional[str]]:
    results = {"config": None, "state": None, "metadata": None}

    # Generate workspace directory if not provided
    if swarm_workspace_dir is None:
        class_name = swarm_instance.__class__.__name__
        swarm_name = getattr(swarm_instance, "name", "unnamed")
        swarm_workspace_dir = get_swarm_workspace_dir(
            class_name, swarm_name, use_timestamp=True
        )

    if not swarm_workspace_dir:
        logger.warning("Could not create swarm workspace directory")
        return results

    # Save configuration
    if save_config:
        results["config"] = save_swarm_config(
            swarm_instance, swarm_workspace_dir, additional_data
        )

    # Save state
    if save_state:
        state_data = (
            additional_data.get("state", {})
            if additional_data
            else {}
        )
        results["state"] = save_swarm_state(
            swarm_instance, swarm_workspace_dir, state_data
        )

    # Save metadata
    if save_metadata:
        execution_metadata = (
            additional_data.get("execution_metadata", {})
            if additional_data
            else {}
        )
        results["metadata"] = save_swarm_metadata(
            swarm_instance,
            swarm_workspace_dir,
            execution_result,
            execution_metadata,
        )

    return results

def plot(self, data=None, ax=None, holdon=False):
        if not (len(self.X.shape) == 2 and self.X.shape[1] == 2):
            raise AttributeError("Only support for visualizing 2D data.")

        if ax is None:
            _, ax = plt.subplots()

        if data is None:
            data = self.X
            assignments = self.assignments
        else:
            assignments = self.predict(data)

        COLOR = "bgrcmyk"
        cmap = lambda assignment: COLOR[int(assignment) % len(COLOR)]

        # generate grid
        delta = 0.025
        margin = 0.2
        xmax, ymax = self.X.max(axis=0) + margin
        xmin, ymin = self.X.min(axis=0) - margin
        axis_X, axis_Y = np.meshgrid(
            np.arange(xmin, xmax, delta), np.arange(ymin, ymax, delta)
        )

        def grid_gaussian_pdf(mean, cov):
            grid_array = np.array(list(zip(axis_X.flatten(), axis_Y.flatten())))
            return multivariate_normal.pdf(grid_array, mean, cov).reshape(axis_X.shape)

        # plot scatters
        if assignments is None:
            c = None
        else:
            c = [cmap(assignment) for assignment in assignments]
        ax.scatter(data[:, 0], data[:, 1], c=c)

        # plot contours
        for assignment in range(self.K):
            ax.contour(
                axis_X,
                axis_Y,
                grid_gaussian_pdf(self.means[assignment], self.covs[assignment]),
                colors=cmap(assignment),
            )

        if not holdon:
            plt.show()

def adapt(model, dataset):
        # Currently, only support using the original dataset to adapt all the
        # preprocessing layers before the first non-preprocessing layer.
        # TODO: Use PreprocessingStage for preprocessing layers adapt.
        # TODO: Use Keras Tuner for preprocessing layers adapt.
        x = tree.flatten(dataset)

        def get_output_layers(tensor):
            output_layers = []
            tensor = tree.flatten(tensor)[0]
            for layer in model.layers:
                if isinstance(layer, keras.layers.InputLayer):
                    continue
                input_node = tree.flatten(layer.input)[0]
                if input_node is tensor:
                    if isinstance(
                        layer,
                        keras_layers.PreprocessingLayer,
                    ) or hasattr(layer, "adapt"):
                        output_layers.append(layer)
            return output_layers

        dq = collections.deque()

        for index, input_node in enumerate(tree.flatten(model.input)):
            in_x = x[index]
            for layer in get_output_layers(input_node):
                dq.append((layer, in_x))

        while len(dq):
            layer, in_x = dq.popleft()
            layer.adapt(in_x)
            out_x = layer(in_x)
            for next_layer in get_output_layers(layer.output):
                dq.append((next_layer, out_x))

        return model

def put_many(
        self,
        key_objs: List[Union[Tuple[str, PutValue], S3PutObject]],
        overwrite: bool = True,
    ) -> List[Tuple[str, str]]:

        def _store():
            for key_obj in key_objs:
                if isinstance(key_obj, S3PutObject):
                    key = key_obj.key
                    obj = key_obj.value
                else:
                    key = key_obj[0]
                    obj = key_obj[1]
                store_info = {
                    "key": key,
                    "content_type": getattr(key_obj, "content_type", None),
                }
                metadata = getattr(key_obj, "metadata", None)
                if metadata:
                    store_info["metadata"] = {
                        "metaflow-user-attributes": json.dumps(metadata)
                    }
                if self._encryption:
                    store_info["encryption"] = self._encryption
                if isinstance(obj, (RawIOBase, BufferedIOBase)):
                    if not obj.readable() or not obj.seekable():
                        raise MetaflowS3InvalidObject(
                            "Object corresponding to the key '%s' is not readable or seekable"
                            % key
                        )
                else:
                    if not is_stringish(obj):
                        raise MetaflowS3InvalidObject(
                            "Object corresponding to the key '%s' is not a string "
                            "or a bytes object." % key
                        )
                    obj = to_fileobj(obj)
                with NamedTemporaryFile(
                    dir=self._tmpdir,
                    delete=False,
                    mode="wb",
                    prefix="metaflow.s3.put_many.",
                ) as tmp:
                    tmp.write(obj.read())
                    tmp.close()
                    yield tmp.name, self._url(key), store_info

        return self._put_many_files(_store(), overwrite)

def stream_logs(
    run_id: int, stub: ControlStub, duration: int, after_timestamp: float
) -> float:
    req = StreamLogsRequest(run_id=run_id, after_timestamp=after_timestamp)

    latest_timestamp = 0.0
    res = None

    with flwr_cli_grpc_exc_handler():
        try:
            for res in stub.StreamLogs(req, timeout=duration):
                print(res.log_output, end="")
            raise AllLogsRetrieved()
        except grpc.RpcError as e:
            # pylint: disable=E1101
            if e.code() != grpc.StatusCode.DEADLINE_EXCEEDED:
                raise e
        finally:
            if res is not None:
                latest_timestamp = cast(float, res.latest_timestamp)

    return max(latest_timestamp, after_timestamp)

def try_with_registry_fallback(f: Callable[..., T], *args, **kwargs) -> T:
    try:
        return f(*args, **kwargs)
    except Exception as initial_error:
        # Check if this is a Julia registry error by looking at the error message
        if "JuliaError" not in str(
            type(initial_error)
        ) or "Unsatisfiable requirements detected" not in str(initial_error):
            raise initial_error

        old_value = os.environ.get(PREFERENCE_KEY, None)
        if old_value == "eager":
            raise initial_error

        warnings.warn(
            "Initial Julia registry operation failed. Attempting to use the `eager` registry flavor of the Julia "
            + f"General registry from the Julia Pkg server (via the `{PREFERENCE_KEY}` environment variable)."
        )
        os.environ[PREFERENCE_KEY] = "eager"
        try:
            return f(*args, **kwargs)
        finally:
            if old_value is not None:
                os.environ[PREFERENCE_KEY] = old_value
            else:
                del os.environ[PREFERENCE_KEY]

def np_to_fd(x, axes=None, feature_names=None, copy=True, dtype=None):
    if dtype:
        copy = True
    assert isinstance(x, np.ndarray), 'input must be an ndarray'
    # pass-through 1D numpy array
    if x.ndim == 1:
        if feature_names:
            assert len(feature_names) == 1, '1D array detected but multiple feature names'
        fname = feature_names[0] if feature_names else 'c0'
        return OrderedDict([(fname, x)])
    view = x.view()
    view_t = np.transpose(view, axes=axes)
    # we usually want a copy since transpose
    # creates a non-contiguous array in memory for each feature we extract (which breaks some stuff)
    if copy:
        view_t = np.ascontiguousarray(view_t, dtype)
    cols = (
        feature_names
        if feature_names
        else ['c' + str(i) for i in six.moves.xrange(view_t.shape[0])]
    )
    return OrderedDict((cols[i], view_t[i]) for i in six.moves.xrange(view_t.shape[0]))

def template(self, values=None, create=True):
        idx = -1
        config = deepcopy(self.cfg[1])
        for counter, cfg in enumerate(config[0][0]):
            opt = cfg[0]
            if opt == "Annotate":
                ann_key = cfg[2]
                if ann_key == ["meta_schedule.parallel"]:
                    interval = self.power_of_two(5, 9)
                elif ann_key == ["meta_schedule.vectorize"]:
                    interval = self.power_of_two(4, 8)
                elif ann_key == ["pragma_auto_unroll_max_step"]:
                    interval = self.power_of_two(7, 11)
                elif ann_key == ["meta_schedule.thread_extent_low_inclusive"]:
                    interval = self.power_of_two(5, 6)
                elif ann_key == ["meta_schedule.thread_extent_high_inclusive"]:
                    interval = self.power_of_two(8, 12)
                else:
                    continue
                idx += 1
                key = f"ann_{idx}"
                ann_value = cfg[1][1]
                if create:
                    self.config_space[key] = self.add_space(interval, [ann_value])
                else:
                    cfg[1][1] = self.get_value(key, values[idx])
            elif opt == "SamplePerfectTile":
                tile = config[0][1]
                tile_idx = self.get_index(tile, counter)
                tile_val = tile[tile_idx][1]
                interval = self.power_of_two(1, 6)
                for i in range(len(tile_val)):
                    idx += 1
                    key = f"sp_{counter}_{idx}"
                    split = tile_val[i]
                    if create:
                        self.config_space[key] = self.add_space(interval, [split])
                    else:
                        config[0][1][tile_idx][1][i] = self.get_value(key, values[idx])
            elif opt == "TransformLayout":
                del config[0][0][counter]
        if create:
            return None
        return config

def wrap_generator(
    gen: Generator[T, None, None],
    on_iter: Optional[Callable[[], Any]] = None,
    wrap: Optional[Callable[[T], T]] = None,
    on_done: Optional[Callable[[List[T]], Any]] = None,
    context_vars: Optional[ContextVarsOrValues] = None,
) -> Generator[T, None, None]:

    def wrapper(gen):
        with with_context(context_vars):
            if on_iter is not None:
                on_iter()

            vals = []

            for val in gen:
                if wrap is not None:
                    # Allow handlers to transform the value.
                    val = wrap(val)

                vals.append(val)
                yield val

            if on_done is not None:
                on_done(vals)

    wrapper.__name__ = f"tru_wrapped_{gen.__class__.__name__}"

    return wrapper(gen)

def fit(self, X, y=None):
        if self.alphabet_size < 2:
            raise ValueError("Alphabet size must be an integer greater than 2")

        if self.word_length < 1:
            raise ValueError("Word length must be an integer greater than 1")

        if self.binning_method == "information-gain" and y is None:
            raise ValueError(
                "Class values must be provided for information gain binning"
            )

        if self.binning_method not in binning_methods:
            raise TypeError("binning_method must be one of: ", binning_methods)

        self.letter_bits = math.ceil(math.log2(self.alphabet_size))
        self.letter_max = pow(2, self.letter_bits) - 1
        self.word_bits = self.word_length * self.letter_bits
        self.max_bits = (
            self.word_bits * 2 if self.bigrams or self.skip_grams else self.word_bits
        )

        if self.typed_dict and self.max_bits > 64:
            raise ValueError(
                "Typed Dictionaries can only handle 64 bit words. "
                "ceil(log2(alphabet_size)) * word_length must be less than or equal "
                "to 64."
                "With bi-grams or skip-grams enabled, this bit limit is 32."
            )

        if self.typed_dict and self.levels > 15:
            raise ValueError(
                "Typed Dictionaries can only handle 15 levels "
                "(this is way to many anyway)."
            )

        X = check_X(X, enforce_univariate=True, coerce_to_numpy=True)
        X = X.squeeze(1)

        if self.levels > 1:
            quadrants = 0
            for i in range(self.levels):
                quadrants += pow(2, i)
            self.level_bits = math.ceil(math.log2(quadrants))
            self.level_max = pow(2, self.level_bits) - 1

        self.n_instances, self.series_length = X.shape
        self.breakpoints = self._binning(X, y)

        self._is_fitted = True
        self._is_vectorized = False
        return self

def requirementsSatisfied(required_state, local_state, req_type=None):
    for req_string in required_state:
        # parse requirement
        req = None
        for op_str, op in op_map.items():
            split = req_string.split(op_str)
            # if operation is not in req_string, continue
            if len(split) == 2:
                req = _Requirement(split[0], op, split[1])
                break

        if req is None:
            log.error("Invalid requirement specification: %s", req_string)
            return False

        compare_type = req_type or type(local_state[req.name])
        # check if local state satisfies required state (specification)
        if compare_type is bool:
            # boolean is a special case, where simply casting to bool does not produce target result
            required_value = bool_map[req.value]
        else:
            required_value = compare_type(req.value)
        local_value = compare_type(local_state[req.name])

        # finally, compare the values
        if not req.op(local_value, required_value):
            return False
    return True

def get_cross_slice_vars(jaxpr, slices):
    defined = {}
    stage_invars = [OrderedSet() for _ in slices]
    for invar in jaxpr.invars:
        defined[invar] = -1
    for invar in jaxpr.constvars:
        defined[invar] = -1
    for i, sliced in enumerate(slices):
        for eqn in sliced:
            for outvar in eqn.outvars:
                if isinstance(outvar, DropVar):
                    continue
                defined[outvar] = i
    for i, sliced in enumerate(slices):
        for eqn in sliced:
            for invar in eqn.invars:
                if not isinstance(invar, Var):
                    continue
                if defined[invar] >= 0 and defined[invar] != i:
                    stage_invars[i].add(invar)
    for i, invars in enumerate(stage_invars):
        print(f"Layer {i} has inputs:")
        for invar in invars:
            print(invar, invar.aval.shape, "from layer", defined[invar])

def forward(
        self,
        tensordict: TensorDictBase,
        *,
        tensordict_out: TensorDictBase | None = None,
        logits_only: bool = False,
        **kwargs,
    ) -> TensorDictBase:
        tensordict_orig = tensordict

        if not tensordict.ndim:
            return self.forward(lazy_stack([tensordict]), logits_only=logits_only)[0]
        elif tensordict.ndim > 1:
            return self.forward(tensordict.reshape(-1), logits_only=logits_only).view(
                tensordict.shape
            )

        if not isinstance(tensordict, LazyStackedTensorDict):
            tensordict = tensordict.to_lazystack(0)

        # Prepare output
        out = TensorDict(
            device=tensordict.device, batch_size=tensordict.batch_size
        ).to_lazystack(0)

        if self.input_mode == "history":
            out = self._generate_from_history(tensordict, out)
        elif self.input_mode == "text":
            out = self._generate_from_text(tensordict, out)
        elif self.input_mode == "tokens":
            out = self._generate_from_tokens(tensordict, out)

        # Handle inplace
        if tensordict_out is None:
            if self.inplace is True:
                tensordict_out = tensordict_orig
            elif self.inplace is False:
                tensordict_out = out
            elif self.inplace == "empty":
                tensordict_out = tensordict.empty()

        if tensordict_out is not None and tensordict_out is not out:
            result = tensordict_out.exclude(*self.out_keys, inplace=True)
            result.update(out, keys_to_update=self.out_keys)
        else:
            result = out

        return result

def make_batched_videos(videos) -> list[Union[np.ndarray, "torch.Tensor", "URL", "Path"]]:
    # Early exit for deeply nested list of image frame paths. We shouldn't flatten them
    try:
        if isinstance(videos[0][0], list) and isinstance(videos[0][0][0], str):
            return [image_paths for sublist in videos for image_paths in sublist]
    except (IndexError, TypeError):
        pass

    if is_batched_video(videos):
        return convert_pil_frames_to_video(list(videos))
    elif isinstance(videos, str) or is_valid_video(videos):
        return convert_pil_frames_to_video([videos])
    # only one frame passed, thus we unsqueeze time dim
    elif is_valid_image(videos):
        if isinstance(videos, PIL.Image.Image):
            videos = np.array(videos)
        return [videos[None, ...]]
    elif not isinstance(videos, list):
        raise ValueError(
            f"Invalid video input. Expected either a list of video frames or an input of 4 or 5 dimensions, but got"
            f" type {type(videos)}."
        )

    # Recursively flatten any nested structure
    flat_videos_list = []
    for item in videos:
        if isinstance(item, str) or is_valid_video(item):
            flat_videos_list.append(item)
        elif isinstance(item, list) and item:
            flat_videos_list.extend(make_batched_videos(item))

    flat_videos_list = convert_pil_frames_to_video(flat_videos_list)
    return flat_videos_list

def get_boto3_session(self) -> boto3.Session:
        if self.aws_secret_access_key:
            aws_secret_access_key = self.aws_secret_access_key.get_secret_value()
        else:
            aws_secret_access_key = None

        base_session = boto3.Session(
            aws_access_key_id=self.aws_access_key_id,
            aws_secret_access_key=aws_secret_access_key,
            aws_session_token=self.aws_session_token,
            profile_name=self.profile_name,
            region_name=self.region_name,
        )

        # If assume_role_arn is provided, assume the role
        if self.assume_role_arn:
            sts_client = base_session.client("sts")

            # Prepare assume_role parameters
            assume_role_params = {
                "RoleArn": self.assume_role_arn,
            }

            # Get parameters from assume_role_kwargs
            kwargs_override = self.assume_role_kwargs.get_params_override()

            # Add RoleSessionName if provided, otherwise generate a default
            if "RoleSessionName" in kwargs_override:
                assume_role_params["RoleSessionName"] = kwargs_override[
                    "RoleSessionName"
                ]
            else:
                assume_role_params["RoleSessionName"] = (
                    f"prefect-session-{uuid.uuid4().hex[:8]}"
                )

            # Add all other assume_role_kwargs (excluding RoleSessionName if it was in kwargs_override)
            for key, value in kwargs_override.items():
                if key != "RoleSessionName":  # Already handled above
                    assume_role_params[key] = value

            # Assume the role
            response = sts_client.assume_role(**assume_role_params)
            credentials = response["Credentials"]

            # Create a new session with the assumed role credentials
            return boto3.Session(
                aws_access_key_id=credentials["AccessKeyId"],
                aws_secret_access_key=credentials["SecretAccessKey"],
                aws_session_token=credentials["SessionToken"],
                region_name=self.region_name,
            )

        return base_session

def var(self, *args, **kwargs):
    # preprocess inputs:
    if len(args) == 0:
        dim = None
        unbiased = kwargs.get("unbiased", False)
        mean = self.mean()
    elif len(args) == 1:
        dim = args[0]
        unbiased = kwargs.get("unbiased", False)
        keepdim = kwargs.get("keepdim", False)
    elif len(args) == 2:
        dim, unbiased = args[0], args[1]
        keepdim = kwargs.get("keepdim", False)
    else:
        dim, unbiased, keepdim = args[0], args[1], args[2]

    if dim is not None:  # dimension is specified
        mean = self.mean(dim, keepdim=True)

    # Compute square error
    result = (self - mean).square()
    if dim is None:
        result = result.sum()
    else:
        result = result.sum(dim, keepdim=keepdim)

    # Determine divisor
    divisor = self.nelement() // result.nelement()
    if not unbiased:
        divisor -= 1

    # Compute mean square error
    if divisor in [0, 1]:
        return result
    return result.div(divisor)

def create_ascii_table(data: list[list[Any]]) -> str:
    if not data or not data[0]:
        return ""

    # Convert all elements to strings, handling None values as empty strings
    str_data = [[str(item) if item is not None else "" for item in row] for row in data]

    # Calculate column widths
    num_columns = max(len(row) for row in str_data)
    col_widths = [0] * num_columns
    for row in str_data:
        for i, cell in enumerate(row):
            if i < num_columns:
                col_widths[i] = max(col_widths[i], len(cell))

    # Define border part
    border = "+" + "+".join("-" * (w + 2) for w in col_widths) + "+"

    lines = [border]
    for i, row in enumerate(str_data):
        padded_row = row + [""] * (num_columns - len(row))
        content_row = "| " + " | ".join(cell.ljust(w) for cell, w in zip(padded_row, col_widths)) + " |"
        lines.append(content_row)
        if i == 0 or i == len(str_data) - 1:
            lines.append(border)

    return "\n".join(lines)

def create_slice_specs_list(
    list_of_feature_and_value: List[
        Dict[str, Union[float, int, str, List[float], bool]]
    ]
) -> List[ModelEvaluationSlice.Slice.SliceSpec]:
  slice_specs_list = []
  for feature_and_value in list_of_feature_and_value:
    configs = {}
    for feature, value in feature_and_value.items():
      if isinstance(value, bool):
        # Bool must be checked first, bool is a child of int in Python.
        configs[feature] = ModelEvaluationSlice.Slice.SliceSpec.SliceConfig(
            all_values=BoolValue(value=value)
        )
      elif isinstance(value, int) or isinstance(value, float):
        configs[feature] = ModelEvaluationSlice.Slice.SliceSpec.SliceConfig(
            value=ModelEvaluationSlice.Slice.SliceSpec.Value(
                float_value=float(value)
            )
        )
      elif isinstance(value, str):
        configs[feature] = ModelEvaluationSlice.Slice.SliceSpec.SliceConfig(
            value=ModelEvaluationSlice.Slice.SliceSpec.Value(string_value=value)
        )
      elif isinstance(value, list):
        configs[feature] = ModelEvaluationSlice.Slice.SliceSpec.SliceConfig(
            range_=ModelEvaluationSlice.Slice.SliceSpec.Range(
                low=value[0], high=value[1]
            )
        )
      else:
        raise ValueError(
            'Please provide a valid format of value for feature: {}. The'
            ' accepted formats are: bool, float, int, str and list.'.format(
                feature
            )
        )
    slice_spec = ModelEvaluationSlice.Slice.SliceSpec(configs=configs)
    slice_specs_list.append(json_format.MessageToDict(slice_spec._pb))
  return slice_specs_list

def resize_image_to_kb_base64(input_image, target_size_kb, mode="exact"):
    if isinstance(input_image, np.ndarray):
        img = Image.fromarray(input_image)
    elif isinstance(input_image, Image.Image):
        img = input_image
    else:
        raise ValueError("input_image must be a NumPy array or PIL Image.")

    # Convert image to RGB mode if it's not
    if img.mode != "RGB":
        img = img.convert("RGB")

    # Initial quality value
    quality = 95

    while True:
        # Create a BytesIO object to hold the image data in memory
        img_byte_arr = io.BytesIO()

        # Save the image to the BytesIO object with the current quality
        img.save(img_byte_arr, format="JPEG", quality=quality)

        # Get the size of the image in KB
        img_size_kb = len(img_byte_arr.getvalue()) / 1024

        # Check based on the mode
        if mode == "exact":
            # If the image size is equal to the target size, we can return it
            if img_size_kb == target_size_kb:
                break

            # If the image is smaller than the target size, add padding
            elif img_size_kb < target_size_kb:
                padding_size = int(
                    (target_size_kb * 1024) - len(img_byte_arr.getvalue())
                )
                padding = b"\x00" * padding_size
                img_byte_arr.write(padding)
                break

        elif mode == "max":
            # If the image size is within the target size, we can return it
            if img_size_kb <= target_size_kb or quality == 1:
                break

        elif mode == "min":
            # If the image size is greater than or equal to the target size, we can return it
            if img_size_kb >= target_size_kb:
                break

        # Reduce the quality if the image is still too large
        quality -= 5

        # Ensure quality does not go below 1
        if quality < 1:
            quality = 1

    # Encode the image data to base64
    img_base64 = base64.b64encode(img_byte_arr.getvalue()).decode("utf-8")
    return "data:image/png;base64," + img_base64

