def execute_eval(
        self,
        prepare_batch,
        model_predict,
        calculate_loss,
        get_prediction_target,
        noise_scheduler,
    ):
        if not self.accelerator.is_main_process:
            return {}

        # Decide if we pool or do separate passes
        pooling = getattr(self.config, "eval_dataset_pooling")
        eval_datasets = StateTracker.get_data_backends(_type="eval", _types=None)  # dict of {name: ...}
        if len(eval_datasets) == 0:
            return {}

        if pooling:
            # Single pass across ALL eval datasets
            logger.debug("Running a single pooled eval pass across all datasets.")
            pooled_losses = self._evaluate_dataset_pass(
                dataset_name=None,
                prepare_batch=prepare_batch,
                model_predict=model_predict,
                calculate_loss=calculate_loss,
                get_prediction_target=get_prediction_target,
                noise_scheduler=noise_scheduler,
            )
            # We'll store everything under a "pooled" key for consistency
            accumulated = {"pooled": pooled_losses}

        else:
            # Multiple passes: one per dataset
            logger.debug("Running separate eval passes for each dataset + pooled results.")
            accumulated = {}
            # We'll also keep an aggregator for the final 'pooled' pass
            from collections import defaultdict

            pooled_collector = defaultdict(list)

            for ds_name in eval_datasets.keys():
                ds_losses = self._evaluate_dataset_pass(
                    dataset_name=ds_name,
                    prepare_batch=prepare_batch,
                    model_predict=model_predict,
                    calculate_loss=calculate_loss,
                    get_prediction_target=get_prediction_target,
                    noise_scheduler=noise_scheduler,
                )
                accumulated[ds_name] = ds_losses

                # Collect them into the global "pooled" aggregator
                for tstep, losses in ds_losses.items():
                    pooled_collector[tstep].extend(losses)

        return accumulated

def data(self, data: Union[None, tvm.runtime.Tensor, np.ndarray, "torch.Tensor"]) -> None:
        if data is None:
            self._data = data
            return
        # Try to do zero-copy if possible
        if isinstance(data, tvm.runtime.Tensor):
            pass
        elif isinstance(data, np.ndarray):
            data = tvm.runtime.tensor(data)
        elif hasattr(data, "__dlpack__"):
            data = _from_dlpack(data)
        else:
            raise TypeError(f"Unsupported data type: {type(data)}")
        if data.shape != tuple(self.shape):
            raise ValueError(f"Shape mismatch: expected {tuple(self.shape)}, got {data.shape}")
        if data.dtype != self.dtype:
            raise ValueError(f"Dtype mismatch: expected {self.dtype}, got {data.dtype}")
        self._data = data

def take_snapshot(
        self,
        *,
        preset: SnapshotPreset | None = None,
        include: list[SnapshotField] | None = None,
        exclude: list[SnapshotField] | None = None,
        app_data: dict[str, Any] | None = None,
    ) -> Snapshot:
        fields = resolve_snapshot_fields(preset=preset, include=include, exclude=exclude)

        data: dict[str, Any] = {}
        if "messages" in fields:
            data["messages"] = copy.deepcopy(self.messages)
        if "state" in fields:
            data["state"] = self.state.get()
        if "conversation_manager_state" in fields:
            data["conversation_manager_state"] = self.conversation_manager.get_state()
        if "interrupt_state" in fields:
            data["interrupt_state"] = self._interrupt_state.to_dict()
        if "system_prompt" in fields:
            # Store the content-block representation so round-trips preserve caching hints and
            # other block-level metadata.
            data["system_prompt"] = copy.deepcopy(self._system_prompt_content)

        return Snapshot(
            scope="agent",
            schema_version=SNAPSHOT_SCHEMA_VERSION,
            data=data,
            app_data=copy.deepcopy(app_data) if app_data else {},
        )

def is_hierarchical(multiindex: pd.Index, raise_if_false=False) -> bool:
    # Handle the case where a DataFrame is passed
    if isinstance(multiindex, pd.DataFrame):
        multiindex = multiindex.index

    # If the index is not a MultiIndex, return True as it is "inherently hierarchical"
    if not isinstance(multiindex, pd.MultiIndex):
        return True

    # Determine if the MultiIndex is truly hierarchical
    for level in range(len(multiindex.levels) - 1):
        parent = multiindex.get_level_values(level)
        child = multiindex.get_level_values(level + 1)
        mapping = pd.DataFrame(
            {f"{level}": parent, f"{level + 1}": child}
        ).drop_duplicates()

        # Check if any child value appears under multiple parent values
        if mapping.duplicated(subset=f"{level + 1}").any():
            if raise_if_false:
                dups = mapping[
                    mapping.duplicated(subset=f"{level + 1}", keep=False)
                ].to_string()
                msg = f"Duplicate child values found for level: {level + 1}\n{dups}"
                raise Exception(msg)
            else:
                return False
    return True

def load_data_and_predictions(data_format: str = 'Dataset', load_train: bool = True, modify_timestamps: bool = True,
                              data_size: t.Optional[int] = 15000, random_state: int = 42) \
        -> t.Tuple[t.Union[Dataset, pd.DataFrame], np.ndarray]:
    if load_train:
        dataset = pd.read_csv(_TRAIN_DATA_URL)
    else:
        dataset = pd.read_csv(_TEST_DATA_URL)

    if data_size is not None:
        if data_size < len(dataset):
            dataset = dataset.sample(data_size, random_state=random_state)
        elif data_size > len(dataset):
            dataset = pd.concat([dataset] * math.ceil(data_size / len(dataset)), axis=0, ignore_index=True)
            dataset = dataset.sample(data_size, random_state=random_state)
            if not load_train:
                dataset = dataset.sort_values(_datetime)

    if modify_timestamps and not load_train:
        current_time = int(time.time())
        time_test_start = current_time - 86400 * 30  # Span data for 30 days
        dataset[_datetime] = np.sort(
            (np.random.rand(len(dataset)) * (current_time - time_test_start)) + time_test_start
        )
        dataset[_datetime] = dataset[_datetime].apply(lambda x: pd.Timestamp(x, unit='s'))

    predictions = np.asarray(dataset[_predictions])
    dataset.drop(_predictions, axis=1, inplace=True)
    if data_format == 'Dataset':
        dataset = Dataset(dataset, label=_target, cat_features=_CAT_FEATURES,
                          features=_FEATURES)
    return dataset, predictions

def parse_apps_arg(apps_arg: str | None) -> list[str] | None:
    if not apps_arg:
        return None

    path = Path(apps_arg)
    if path.is_file():
        apps = []
        for line in path.read_text(encoding="utf-8-sig").splitlines():
            line = line.strip()
            if line and not line.startswith("#"):
                apps.append(line)
        return apps or None

    apps = [a.strip() for a in apps_arg.split(",") if a.strip()]
    return apps or None

