async def test_connection(self) -> Tuple[bool, Optional[str]]:
        try:
            conn = self._get_connection()

            try:
                if self._start_tls:
                    conn.start_tls()

                if self._bind_dn:
                    if not conn.bind():
                        return False, f"Bind failed: {conn.result}"
                else:
                    conn.bind()

                return True, None
            finally:
                try:
                    conn.unbind()
                except Exception:
                    pass

        except ImportError as exc:
            return False, str(exc)
        except Exception as exc:
            return False, str(exc)

def marginalize_xhat_h(self, horizon: int, xhat_h: List[Optional[float]]):
        assert len(xhat_h) == len(self.backsteps)
        if all(x is None for x in xhat_h):
            t = self.last_train_time = self.last_train_time + horizon * self.timedelta
            raise RuntimeError(
                f"Not enough training data to forecast at horizon {horizon} "
                f"(estimated time {pd.to_datetime(t, unit='s')}, last train "
                f"time is {pd.to_datetime(self.last_train_time, unit='s')})"
            )

        # Get the non None xhat's & their corresponding std errs
        xhat_h, neg_err_h, pos_err_h, vel_errs, loss_errs = np.asarray(
            [
                (
                    x,
                    self.delta_estimator.neg_err(b + horizon),
                    self.delta_estimator.pos_err(b + horizon),
                    self.delta_estimator.vel_err(b + horizon),
                    self.delta_estimator.loss_err(b + horizon),
                )
                for x, b in zip(xhat_h, self.backsteps)
                if x is not None
            ],
            dtype=float,
        ).T

        if self.rho == 1.0:
            q = vel_errs
        elif self.rho == 0.0:
            q = loss_errs
        else:
            if (vel_errs == np.inf).all():
                vel_errs.fill(0)
            if (loss_errs == np.inf).all():
                loss_errs.fill(0)
            q = self.rho * vel_errs + (1 - self.rho) * loss_errs

        if (q == np.inf).all():
            q = np.ones(len(q))

        # Do a softmax to get probabilities
        q = np.exp(-(q - q.min()) * self.config.inflation)
        q = q / q.sum()

        # compute estimate with lower and upper bounds
        xhat, neg_err, pos_err = [np.sum(q * v).item() for v in (xhat_h, neg_err_h, pos_err_h)]
        return xhat, neg_err, pos_err

def read_image_batch(self, filepaths: List[str], delete_problematic_images: bool = False) -> Tuple[List[str], List[Any]]:
        if not isinstance(filepaths, list):
            raise ValueError(f"read_image_batch must be given a list of image filepaths. Received type: {type(filepaths)}")
        output_images = []
        available_keys = []
        for filepath in filepaths:
            try:
                image_data = self.read_image(filepath, delete_problematic_images)
                if image_data is None:
                    log_level = logging.WARNING if should_log() else logging.DEBUG
                    logger.log(log_level, f"Unable to load image '{filepath}', skipping.")
                    continue
                output_images.append(image_data)
                available_keys.append(filepath)
            except Exception as e:
                if delete_problematic_images:
                    logger.error(f"Deleting image '{filepath}', because --delete_problematic_images is provided. Error: {e}")
                    try:
                        self.delete(filepath)
                    except Exception as del_e:
                        logger.error(f"Failed to delete problematic image {filepath}: {del_e}")
                else:
                    log_level = logging.WARNING if should_log() else logging.DEBUG
                    logger.log(
                        log_level,
                        (
                            f"A problematic image {filepath} is detected, but we are not allowed to remove it, because "
                            f"--delete_problematic_images is not provided. Please correct this manually. Error: {e}"
                        ),
                    )
        return available_keys, output_images

def read_dduf_file(dduf_path: os.PathLike | str) -> dict[str, DDUFEntry]:
    entries = {}
    dduf_path = Path(dduf_path)
    logger.info(f"Reading DDUF file {dduf_path}")
    with zipfile.ZipFile(str(dduf_path), "r") as zf:
        for info in zf.infolist():
            logger.debug(f"Reading entry {info.filename}")
            if info.compress_type != zipfile.ZIP_STORED:
                raise DDUFCorruptedFileError("Data must not be compressed in DDUF file.")

            try:
                _validate_dduf_entry_name(info.filename)
            except DDUFInvalidEntryNameError as e:
                raise DDUFCorruptedFileError(f"Invalid entry name in DDUF file: {info.filename}") from e

            offset = _get_data_offset(zf, info)

            entries[info.filename] = DDUFEntry(
                filename=info.filename, offset=offset, length=info.file_size, dduf_path=dduf_path
            )

    # Consistency checks on the DDUF file
    if "model_index.json" not in entries:
        raise DDUFCorruptedFileError("Missing required 'model_index.json' entry in DDUF file.")
    index = json.loads(entries["model_index.json"].read_text())
    _validate_dduf_structure(index, entries.keys())

    logger.info(f"Done reading DDUF file {dduf_path}. Found {len(entries)} entries")
    return entries

def export(self, force: bool = True):
        try:
            # Validate export method
            if self.export_method not in ["json", "yaml"]:
                raise ValueError(
                    f"Invalid export_method: {self.export_method}. Must be 'json' or 'yaml'"
                )

            # Create directory if it doesn't exist
            save_dir = os.path.dirname(self.save_filepath)
            if save_dir:
                os.makedirs(save_dir, exist_ok=True)

            # Ensure filepath extension matches export method
            file_ext = os.path.splitext(self.save_filepath)[1].lower()
            expected_ext = (
                ".json" if self.export_method == "json" else ".yaml"
            )
            if file_ext != expected_ext:
                base_name = os.path.splitext(self.save_filepath)[0]
                self.save_filepath = f"{base_name}{expected_ext}"
                logger.warning(
                    f"Updated save filepath to match export method: {self.save_filepath}"
                )

            if self.export_method == "json":
                self.save_as_json(force=force)
            elif self.export_method == "yaml":
                self.save_as_yaml(force=force)

        except Exception as e:
            logger.error(
                f"Failed to export conversation to {self.save_filepath}: {str(e)}\nTraceback: {traceback.format_exc()}"
            )
            raise  # Re-raise to ensure the error is visible

def get_all_tools_config(self) -> dict[str, Any]:
        tool_config = {}
        logger.debug("getting tool configurations")

        # Add all registered tools
        for tool_name, tool in self.registry.items():
            # Make a deep copy to avoid modifying the original
            spec = tool.tool_spec.copy()
            try:
                # Normalize the schema before validation
                spec = normalize_tool_spec(spec)
                self.validate_tool_spec(spec)
                tool_config[tool_name] = spec
                logger.debug("tool_name=<%s> | loaded tool config", tool_name)
            except ValueError as e:
                logger.warning("tool_name=<%s> | spec validation failed | %s", tool_name, e)

        # Add any dynamic tools
        for tool_name, tool in self.dynamic_tools.items():
            if tool_name not in tool_config:
                # Make a deep copy to avoid modifying the original
                spec = tool.tool_spec.copy()
                try:
                    # Normalize the schema before validation
                    spec = normalize_tool_spec(spec)
                    self.validate_tool_spec(spec)
                    tool_config[tool_name] = spec
                    logger.debug("tool_name=<%s> | loaded dynamic tool config", tool_name)
                except ValueError as e:
                    logger.warning("tool_name=<%s> | dynamic tool spec validation failed | %s", tool_name, e)

        logger.debug("tool_count=<%s> | tools configured", len(tool_config))
        return tool_config

def nested_zip(objs):
  assert isinstance(objs, (list, tuple))
  assert objs, 'Cannot zip an empty sequence.'

  if _is_at_level(objs, 1):
    return tuple(objs)

  if _is_namedtuple_instance(objs[0]):
    return type(objs[0])(*nested_zip(list(map(list, objs))))
  if isinstance(objs[0], list):
    return [nested_zip([obj[i] for obj in objs]) for i in range(len(objs[0]))]
  if isinstance(objs[0], tuple):
    return nested_zip(list(map(list, objs)))
  if isinstance(objs[0], dict):
    return {k: nested_zip([obj[k] for obj in objs]) for k in objs[0]}

  raise ValueError('Non-exhaustive pattern match for {}.'.format(objs[0]))

def end_of_chunk(prev_tag, tag, prev_type, type_):
    chunk_end = False

    if prev_tag == "E":
        chunk_end = True
    if prev_tag == "S":
        chunk_end = True

    if prev_tag == "B" and tag == "B":
        chunk_end = True
    if prev_tag == "B" and tag == "S":
        chunk_end = True
    if prev_tag == "B" and tag == "O":
        chunk_end = True
    if (prev_tag == "I" or prev_tag == "M") and tag == "B":
        chunk_end = True
    if (prev_tag == "I" or prev_tag == "M") and tag == "S":
        chunk_end = True
    if (prev_tag == "I" or prev_tag == "M") and tag == "O":
        chunk_end = True

    if prev_tag != "O" and prev_tag != "." and prev_type != type_:
        chunk_end = True

    return chunk_end

def update_scene(self, step: int, num_rays_per_batch: Optional[int] = None) -> None:
        self.step = step

        if len(self.render_statemachines) == 0:
            return
        # this stops training while moving to make the response smoother
        while time.time() - self.last_move_time < 0.1:
            time.sleep(0.05)
        if self.trainer is not None and self.trainer.training_state == "training" and self.train_util != 1:
            if (
                EventName.TRAIN_RAYS_PER_SEC.value in GLOBAL_BUFFER["events"]
                and EventName.VIS_RAYS_PER_SEC.value in GLOBAL_BUFFER["events"]
            ):
                train_s = GLOBAL_BUFFER["events"][EventName.TRAIN_RAYS_PER_SEC.value]["avg"]
                vis_s = GLOBAL_BUFFER["events"][EventName.VIS_RAYS_PER_SEC.value]["avg"]
                train_util = self.train_util
                vis_n = self.control_panel.max_res**2
                train_n = num_rays_per_batch
                train_time = train_n / train_s
                vis_time = vis_n / vis_s

                render_freq = train_util * vis_time / (train_time - train_util * train_time)
            else:
                render_freq = 30
            if step > self.last_step + render_freq:
                self.last_step = step
                clients = self.viser_server.get_clients()
                for id in clients:
                    camera_state = self.get_camera_state(clients[id])
                    if camera_state is not None:
                        self.render_statemachines[id].action(RenderAction("step", camera_state))
                self.update_camera_poses()
                self.update_step(step)

def is_timm_local_checkpoint(pretrained_model_path: str) -> bool:
    if pretrained_model_path is None:
        return False

    # in case it's Path, not str
    pretrained_model_path = str(pretrained_model_path)

    is_file = os.path.isfile(pretrained_model_path)
    is_dir = os.path.isdir(pretrained_model_path)

    # pretrained_model_path is a file
    if is_file and pretrained_model_path.endswith(".json"):
        with open(pretrained_model_path) as f:
            config_dict = json.load(f)
        return is_timm_config_dict(config_dict)

    # pretrained_model_path is a directory with a config.json
    if is_dir and os.path.exists(os.path.join(pretrained_model_path, "config.json")):
        with open(os.path.join(pretrained_model_path, "config.json")) as f:
            config_dict = json.load(f)
        return is_timm_config_dict(config_dict)

    return False

def load(
    filepath_or_buffer: str | Path | TextIO,
    data_format: Literal["json", "yaml"] = "json",
    nonserializable: dict[str, Any] | None = None,
) -> object:
    check_data_format(data_format)

    if isinstance(filepath_or_buffer, (str, Path)):  # Assume it's a filepath
        with Path(filepath_or_buffer).open() as f:
            if data_format == "json":
                transform_dict = json.load(f)
            else:
                if not yaml_available:
                    msg = "You need to install PyYAML to load a pipeline in yaml format"
                    raise ValueError(msg)
                transform_dict = yaml.safe_load(f)
    elif data_format == "json":
        transform_dict = json.load(filepath_or_buffer)
    else:
        if not yaml_available:
            msg = "You need to install PyYAML to load a pipeline in yaml format"
            raise ValueError(msg)
        transform_dict = yaml.safe_load(filepath_or_buffer)

    return from_dict(transform_dict, nonserializable=nonserializable)

def path_of_module(self, mod: torch.nn.Module) -> str:
        # Prefer the O(1) algorithm
        if self.submodule_paths:
            path = self.submodule_paths.get(mod)
            # TODO: better infomation
            if path is None:
                if not hasattr(self.root, '_module_constants'):
                    self.root._module_constants = torch.nn.ModuleList()
                module_constants = self.root._module_constants
                assert isinstance(module_constants, torch.nn.ModuleList)
                if hasattr(mod, 'extra_repr'):
                    sub_path = _orig_type(mod).__name__ + mod.extra_repr()
                else:
                    sub_path = str(_orig_len(module_constants))
                if not hasattr(module_constants, sub_path):
                    module_constants.add_module(sub_path, mod)
                path = '_module_constants.%s' % sub_path
                self.submodule_paths[mod] = path
                return path
            assert isinstance(path, str)
            return path
        # O(N^2) fallback in the case that we didn't store the submodule
        # paths.
        else:
            for n, p in self.root.named_modules():
                if mod is p:
                    return n
            raise NameError('module is not installed as a submodule')

def cleanup(cls):
        # Remove entries from the outer cache where the target_tokenizer is no longer alive
        dead_keys = [key for key in cls._cache if key is None]
        for key in dead_keys:
            del cls._cache[key]

        # For each assistant_dict, remove entries where assistant_tokenizer is no longer alive
        for assistant_dict in cls._cache.values():
            dead_keys = [key for key in assistant_dict if key is None]
            for key in dead_keys:
                del assistant_dict[key]

def set_clim(self, vmin=None, vmax=None):
        if self.norm.n_components == 1:
            if vmax is None:
                try:
                    vmin, vmax = vmin
                except (TypeError, ValueError):
                    pass

        orig_vmin_vmax = self.norm.vmin, self.norm.vmax

        # Blocked context manager prevents callbacks from being triggered
        # until both vmin and vmax are updated
        with self.norm.callbacks.blocked(signal='changed'):
            # Since the @vmin/vmax.setter invokes colors._sanitize_extrema()
            # to sanitize the input, the input is not sanitized here
            if vmin is not None:
                self.norm.vmin = vmin
            if vmax is not None:
                self.norm.vmax = vmax

        # emit a update signal if the limits are changed
        if orig_vmin_vmax != (self.norm.vmin, self.norm.vmax):
            self.norm.callbacks.process('changed')

def does_model_contain_mlprogram(model) -> bool:
            model_type = model.WhichOneof("Type")

            if model_type == "mlProgram":
                return True
            elif model_type not in ("pipeline", "pipelineClassifier", "pipelineRegressor"):
                return False

            # Does this pipeline contain an mlprogram?
            if model_type == "pipeline":
                pipeline_models = model.pipeline.models
            elif model_type == "pipelineClassifier":
                pipeline_models = model.pipelineClassifier.pipeline.models
            else:
                assert model_type == "pipelineRegressor"
                pipeline_models = model.pipelineRegressor.pipeline.models

            for m in pipeline_models:
                if does_model_contain_mlprogram(m):
                    return True
            return False

def run_loop(agents, env, max_frames=0, max_episodes=0):
  total_frames = 0
  total_episodes = 0
  start_time = time.time()

  observation_spec = env.observation_spec()
  action_spec = env.action_spec()
  for agent, obs_spec, act_spec in zip(agents, observation_spec, action_spec):
    agent.setup(obs_spec, act_spec)

  try:
    while not max_episodes or total_episodes < max_episodes:
      total_episodes += 1
      timesteps = env.reset()
      for a in agents:
        a.reset()
      while True:
        total_frames += 1
        actions = [agent.step(timestep)
                   for agent, timestep in zip(agents, timesteps)]
        if max_frames and total_frames >= max_frames:
          return
        if timesteps[0].last():
          break
        timesteps = env.step(actions)
  except KeyboardInterrupt:
    pass
  finally:
    elapsed_time = time.time() - start_time
    print("Took %.3f seconds for %s steps: %.3f fps" % (
        elapsed_time, total_frames, total_frames / elapsed_time))

def Model(args, data):
    if args.heterogeneous:
        assert args.incubation_time == 0
        assert args.overdispersion == 0
        return HeterogeneousSIRModel(args.population, args.recovery_time, data)
    elif args.incubation_time > 0:
        assert args.incubation_time > 1
        if args.concentration < math.inf:
            return SuperspreadingSEIRModel(
                args.population, args.incubation_time, args.recovery_time, data
            )
        elif args.overdispersion > 0:
            return OverdispersedSEIRModel(
                args.population, args.incubation_time, args.recovery_time, data
            )
        else:
            return SimpleSEIRModel(
                args.population, args.incubation_time, args.recovery_time, data
            )
    else:
        if args.concentration < math.inf:
            return SuperspreadingSIRModel(args.population, args.recovery_time, data)
        elif args.overdispersion > 0:
            return OverdispersedSIRModel(args.population, args.recovery_time, data)
        else:
            return SimpleSIRModel(args.population, args.recovery_time, data)

def get_dependencies(self, deep=False, ignored=None, copy=True):
        deps = []

        for d in self.base_features[:]:
            deps += [d]

        if hasattr(self, "where") and self.where:
            deps += [self.where]

        if ignored is None:
            ignored = set([])
        deps = [d for d in deps if d.unique_name() not in ignored]

        if deep:
            for dep in deps[:]:  # copy so we don't modify list we iterate over
                deep_deps = dep.get_dependencies(deep, ignored)
                deps += deep_deps

        return deps

def convert_monomer_features(monomer_features: FeatureDict) -> FeatureDict:
    if monomer_features['template_aatype'].shape[0] == 0:
        monomer_features.update(
            empty_template_feats(monomer_features['aatype'].shape[0]))
    converted = {}
    unnecessary_leading_dim_feats = {
        'sequence',
        'domain_name',
        'num_alignments',
        'seq_length',
    }
    for feature_name, feature in monomer_features.items():
        if feature_name in unnecessary_leading_dim_feats:
            # asarray ensures it's a np.ndarray.
            feature = np.asarray(feature[0], dtype=feature.dtype)
        elif feature_name == 'aatype':
            # The multimer model performs the one-hot operation itself.
            feature = np.argmax(feature, axis=-1).astype(np.int32)
        elif feature_name == 'template_aatype':
            if feature.shape[0] > 0:
                feature = correct_template_restypes(feature)
        elif feature_name == 'template_all_atom_masks':
            feature_name = 'template_all_atom_mask'
        elif feature_name == 'msa':
            feature = feature.astype(np.uint8)

        if feature_name.endswith('_mask'):
            feature = feature.astype(np.float32)

        converted[feature_name] = feature

    if 'deletion_matrix_int' in monomer_features:
        monomer_features['deletion_matrix'] = monomer_features.pop(
            'deletion_matrix_int').astype(np.float32)

    converted.pop(
        'template_sum_probs'
    )  # zy: this input is checked to be dirty in shape. TODO: figure out why and make it right.
    return converted

def forward(self, *input, **kwargs):
        if not self.initialized_flamingo:
            raise ValueError("Flamingo layers are not initialized. Please call `init_flamingo` first.")

        input_ids = kwargs["input_ids"] if "input_ids" in kwargs else input[0]
        media_locations = input_ids == self.media_token_id
        # IMPORTANT: Force `attend_previous` to True when we place training data as <image>caption<|endofchunk|>
        # attend_previous = (
        #     (random.random() < 0.5) if self.use_media_placement_augmentation else False
        # )
        attend_previous = (random.random() < 0.5) if self.use_media_placement_augmentation else True
        # attend_previous = self.only_attend_previous

        if self.__class__.__name__ == "LlamaForCausalLM":
            for layer in self.get_decoder().layers:
                layer.condition_media_locations(media_locations)
                layer.condition_attend_previous(attend_previous)
        elif self.__class__.__name__ in ["MPTForCausalLM", "MosaicGPT"]:
            for layer in self.get_decoder().blocks:
                layer.condition_media_locations(media_locations)
                layer.condition_attend_previous(attend_previous)
        else:
            print("inavaliable text encoder")
        return super().forward(*input, **kwargs)  # Call the other parent's forward method

async def distributor() -> AsyncGenerator[messaging.MessageHandler, None]:
    async def message_handler(message: messaging.Message):
        assert message.data

        try:
            assert message.attributes
        except Exception:
            return

        if subscribers:
            try:
                log = Log.model_validate_json(message.data)
            except Exception as e:
                logger.warning(f"Failed to parse log message: {e}")
                return

            for queue in subscribers:
                filter = filters[queue]
                if not log_matches_filter(log, filter):
                    continue

                try:
                    queue.put_nowait(log)
                except asyncio.QueueFull:
                    continue

    yield message_handler

def parse(self, text, intents=None, top_n=None):
        if isinstance(intents, str):
            intents = {intents}
        elif isinstance(intents, list):
            intents = list(intents)

        if top_n is None:
            intent_result = self.intent_classifier.get_intent(text, intents)
            intent_name = intent_result[RES_INTENT_NAME]
            if intent_name is not None:
                slots = self.slot_fillers[intent_name].get_slots(text)
            else:
                slots = []
            return parsing_result(text, intent_result, slots)

        results = []
        intents_results = self.intent_classifier.get_intents(text)
        for intent_result in intents_results[:top_n]:
            intent_name = intent_result[RES_INTENT_NAME]
            if intent_name is not None:
                slots = self.slot_fillers[intent_name].get_slots(text)
            else:
                slots = []
            results.append(extraction_result(intent_result, slots))
        return results

