def get_next_parameters(self, ranges_to_skip=None):
        if ranges_to_skip is None:
            ranges_to_skip = set(self.results.index)

        if not isinstance(self.param_ranges, dict):
            raise ValueError("Only works for random search!")

        param_range_keys = list(self.param_ranges.keys())
        param_range_keys.sort()

        def _get_next():
            """Returns next hyperparameter set per try."""

            parameters = {k: np.random.choice(self.param_ranges[k]) for k in param_range_keys}

            # Adds fixed params
            for k in self.fixed_params:
                parameters[k] = self.fixed_params[k]

            return parameters

        for _ in range(self._max_tries):
            parameters = _get_next()
            name = self._get_name(parameters)

            if name not in ranges_to_skip:
                return parameters

        raise ValueError("Exceeded max number of hyperparameter searches!!")

def put(self, key: str, file_like: Union[IO, str, File]):
        if isinstance(file_like, File):
            context = nullcontext(file_like.get_bytesio())
        elif hasattr(file_like, "read"):
            context = nullcontext(file_like)
        elif isinstance(file_like, str) and os.path.isfile(file_like):
            context = open(file_like, "rb")
        else:
            raise TypeError(
                "file_like must be either a string, a lepton File class object, or "
                f"a file-like object, but got {type(file_like)}."
            )
        with context as opened_file:
            res = oss_api.put(self._conn, key, opened_file, self.bucket_name)
            if not res.ok:
                raise RuntimeError(
                    f"Failed to put object {key}. Error:"
                    f" {res.status_code} {res.content}."
                )
            # After upload, we return the url of the object.
            res = oss_api.get(self._conn, key, self.bucket_name, return_url=True)
            if not res.ok:
                raise RuntimeError(
                    f"Failed to get object {key}. Error:"
                    f" {res.status_code} {res.content}."
                )
            return res.headers["location"]

def evaluate_batch(self, batch, stage):
        snt_id = batch.id
        mixture = batch.mix_sig
        targets = [batch.s1_sig, batch.s2_sig]
        if self.hparams.num_spks == 3:
            targets.append(batch.s3_sig)

        with torch.no_grad():
            predictions, targets = self.compute_forward(
                mixture, targets, stage)
            loss = self.compute_objectives(predictions, targets)

        # Manage audio file saving
        if stage == sb.Stage.TEST and self.hparams.save_audio:
            if hasattr(self.hparams, 'n_audio_to_save'):
                if self.hparams.n_audio_to_save > 0:
                    self.save_audio(snt_id[0], mixture, targets, predictions)
                    self.hparams.n_audio_to_save += -1
            else:
                self.save_audio(snt_id[0], mixture, targets, predictions)

        return loss.mean().detach()

def format_speech_generation_kwargs(kwargs):
    # attribute kwargs to models
    kwargs_text = {}
    kwargs_speech = {}
    for key, value in kwargs.items():
        if key.startswith("text_"):
            key = key[len("text_") :]
            kwargs_text[key] = value
        elif key.startswith("speech_"):
            key = key[len("speech_") :]
            kwargs_speech[key] = value
        elif key == "generation_config":
            kwargs_text[key] = value
        else:
            # If the key is already in a specific config, then it's been set with a
            # submodules specific value and we don't override
            if key not in kwargs_text:
                kwargs_text[key] = value
            if key not in kwargs_speech:
                kwargs_speech[key] = value
    return kwargs_text, kwargs_speech

def query(self, payload, max_retries=3, retry_interval=5):
        headers = {
            "Accept": "application/json",
            "Authorization": f"Bearer {self.huggingface_api_key}",
            "Content-Type": "application/json",
        }
        for attempt in range(1, max_retries + 1):
            try:
                response = requests.post(
                    self.huggingface_url,
                    headers=headers,
                    json=payload,
                    # timeout=timeout_seconds,
                )
                if response.status_code == 503:
                    estimated_time = response.json().get("estimated_time", "")
                    if estimated_time:
                        logger.info(
                            f"Model Initializing wait for - {estimated_time:.2f}s "
                        )
                        time.sleep(estimated_time)
                        continue
                else:
                    response.raise_for_status()

            except requests.exceptions.RequestException:
                if attempt < max_retries - 1:
                    logger.info(f"Retrying attempt: {attempt} for payload: {payload} ")
                    time.sleep(retry_interval)
                    retry_interval += attempt
                else:
                    raise ValueError(
                        f"Query failed with status {response.status_code}: {response.text}"
                    )

        return response.json()

def compute_membership_strengths(
    knn_indices,
    knn_dists,
    sigmas,
    rhos,
    return_dists=False,
    bipartite=False,
):
    n_samples = knn_indices.shape[0]
    n_neighbors = knn_indices.shape[1]

    rows = np.zeros(knn_indices.size, dtype=np.int32)
    cols = np.zeros(knn_indices.size, dtype=np.int32)
    vals = np.zeros(knn_indices.size, dtype=np.float32)
    if return_dists:
        dists = np.zeros(knn_indices.size, dtype=np.float32)
    else:
        dists = None

    for i in range(n_samples):
        for j in range(n_neighbors):
            if knn_indices[i, j] == -1:
                continue  # We didn't get the full knn for i
            # If applied to an adjacency matrix points shouldn't be similar to themselves.
            # If applied to an incidence matrix (or bipartite) then the row and column indices are different.
            if (bipartite == False) & (knn_indices[i, j] == i):
                val = 0.0
            elif knn_dists[i, j] - rhos[i] <= 0.0 or sigmas[i] == 0.0:
                val = 1.0
            else:
                val = np.exp(-((knn_dists[i, j] - rhos[i]) / (sigmas[i])))

            rows[i * n_neighbors + j] = i
            cols[i * n_neighbors + j] = knn_indices[i, j]
            vals[i * n_neighbors + j] = val
            if return_dists:
                dists[i * n_neighbors + j] = knn_dists[i, j]

    return rows, cols, vals, dists

def resolution_metrics(
    resmat, src, function="psf", metric="peak_err", threshold=0.5, verbose=None
):
    # Check if input options are valid
    metrics = ("peak_err", "cog_err", "sd_ext", "maxrad_ext", "peak_amp", "sum_amp")
    if metric not in metrics:
        raise ValueError(f'"{metric}" is not a recognized metric.')

    if function not in ["psf", "ctf"]:
        raise ValueError(f"Not a recognised resolution function: {function}.")

    if metric in ("peak_err", "cog_err"):
        resolution_metric = _localisation_error(
            resmat, src, function=function, metric=metric
        )

    elif metric in ("sd_ext", "maxrad_ext"):
        resolution_metric = _spatial_extent(
            resmat, src, function=function, metric=metric, threshold=threshold
        )

    elif metric in ("peak_amp", "sum_amp"):
        resolution_metric = _relative_amplitude(
            resmat, src, function=function, metric=metric
        )

    # get vertices from source space
    vertno_lh = src[0]["vertno"]
    vertno_rh = src[1]["vertno"]
    vertno = [vertno_lh, vertno_rh]

    # Convert array to source estimate
    resolution_metric = SourceEstimate(resolution_metric, vertno, tmin=0.0, tstep=1.0)

    return resolution_metric

def render(self, force=False, show_progress=True, remote=False):
        g = self._to_graph(fmt="networkx")

        def unique(elements):
            elements_unique = []
            for elem in elements:
                if elem not in elements_unique:
                    elements_unique.append(elem)
            return elements_unique

        dags = unique([t.dag for t in g])

        # first render any other dags involved (this happens when some
        # upstream parameters come form other dags)
        # NOTE: for large compose dags it might be wasteful to render over
        # and over
        for dag in dags:
            if dag is not self:
                dag._render_current(
                    force=force, show_progress=show_progress, remote=remote
                )

        # then, render this dag
        self._render_current(force=force, show_progress=show_progress, remote=remote)

        return self

def color_palette(palette=None, n_colors=None):
    if palette is None:
        palette = get_color_cycle()
        if n_colors is None:
            n_colors = len(palette)

    elif not isinstance(palette, str):
        if n_colors is None:
            n_colors = len(palette)

    else:
        if palette.lower() not in PALETTES:
            raise YellowbrickValueError(
                "'{}' is not a recognized palette!".format(palette)
            )

        palette = PALETTES[palette.lower()]
        if n_colors is None:
            n_colors = len(palette)

    # Always return as many colors as we asked for
    pal_cycle = cycle(palette)
    palette = [next(pal_cycle) for _ in range(n_colors)]

    # Always return in RGB tuple format
    try:
        palette = map(mpl.colors.colorConverter.to_rgb, palette)
        palette = ColorPalette(palette)
    except ValueError:
        raise YellowbrickValueError(
            "Could not generate a palette for %s" % str(palette)
        )

    return palette

def formatted_code_block(
    code: str,
    attributes: dict[str, str] | None = None,
    is_qmd: bool = False,
) -> str:
    if attributes is None:
        attributes = {}
    language = attributes.pop("language", "python")
    attribute_str = " ".join(
        [""] + [f'{key}="{value}"' for key, value in attributes.items()]
    )
    guard = "```"
    while guard in code:
        guard += "`"

    # Quarto executable syntax with claimsLanguage() support
    # ```{marimo .python attr=...}
    if is_qmd:
        head = f"""{guard}{{marimo .{language}{attribute_str}}}"""
    # Compatible with GitHub syntax highlighting
    # ```python {.marimo attr=...}
    elif DependencyManager.new_superfences.has_required_version(quiet=True):
        head = f"""{guard}{language} {{.marimo{attribute_str}}}"""
    # ```{.python.marimo attr=...}
    else:
        head = f"""{guard}{{.{language}.marimo{attribute_str}}}"""
    return f"{head}\n{code}\n{guard}\n"

def export_masks(
    project, output, fmt="geotiff", simplify_tolerance=None, overwrite=False
):
    if fmt not in EXPORT_FORMATS:
        raise ValueError(
            f"Unknown export format: {fmt}. "
            f"Available: {', '.join(EXPORT_FORMATS.keys())}"
        )

    if not project.get("masks") or not project["masks"].get("path"):
        raise ValueError(
            "No masks generated. Run segmentation first "
            "(e.g., 'segment automatic -o masks.tif')."
        )

    mask_path = project["masks"]["path"]
    if not os.path.exists(mask_path):
        raise FileNotFoundError(f"Mask file not found: {mask_path}")

    output = os.path.abspath(output)
    if os.path.exists(output) and not overwrite:
        raise FileExistsError(
            f"Output file exists: {output}. Use --overwrite to replace."
        )

    parent = os.path.dirname(output)
    if parent:
        os.makedirs(parent, exist_ok=True)

    format_info = EXPORT_FORMATS[fmt]

    if format_info["type"] == "raster":
        _export_raster(mask_path, output, fmt)
    elif format_info["type"] == "vector":
        _export_vector(project, mask_path, output, fmt, simplify_tolerance)
    elif format_info["type"] == "image":
        _export_image(mask_path, output)

    file_size = os.path.getsize(output) if os.path.exists(output) else 0

    result = {
        "output": output,
        "format": fmt,
        "file_size": file_size,
        "source_masks": mask_path,
    }

    add_history_entry(
        project, "export", params={"format": fmt, "output": output}, result=result
    )

    return result

def tokenize(self, text):
        text = convert_to_unicode(text)

        output_tokens = []
        for token in whitespace_tokenize(text):
            chars = list(token)
            if len(chars) > self.max_input_chars_per_word:
                output_tokens.append(self.unk_token)
                continue

            is_bad = False
            start = 0
            sub_tokens = []
            while start < len(chars):
                end = len(chars)
                cur_substr = None
                while start < end:
                    substr = ''.join(chars[start:end])
                    if start > 0:
                        substr = '##' + substr
                    if substr in self.vocab:
                        cur_substr = substr
                        break
                    end -= 1
                if cur_substr is None:
                    is_bad = True
                    break
                sub_tokens.append(cur_substr)
                start = end

            if is_bad:
                output_tokens.append(self.unk_token)
            else:
                output_tokens.extend(sub_tokens)
        return output_tokens

def feature_extraction_fn(examples, check_image=True):
        model_inputs = {}

        if check_image:
            images = []
            to_keep = []
            for image_file in examples[image_column]:
                try:
                    img = Image.open(image_file)
                    images.append(img)
                    to_keep.append(True)
                except Exception:
                    to_keep.append(False)

            for k, v in examples.items():
                if k != image_column:
                    model_inputs[k] = v[to_keep]
        else:
            images = [Image.open(image_file) for image_file in examples[image_column]]

        encoder_inputs = feature_extractor(images=images, return_tensors="np")
        model_inputs["pixel_values"] = encoder_inputs.pixel_values

        return model_inputs

def lf_summary(
        self, Y: Optional[np.ndarray] = None, est_weights: Optional[np.ndarray] = None
    ) -> DataFrame:
        n, m = self.L.shape
        lf_names: Union[List[str], List[int]]
        d: OrderedDict[str, Series] = OrderedDict()
        if self._lf_names is not None:
            d["j"] = list(range(m))
            lf_names = self._lf_names
        else:
            lf_names = list(range(m))

        # Default LF stats
        d["Polarity"] = Series(data=self.lf_polarities(), index=lf_names)
        d["Coverage"] = Series(data=self.lf_coverages(), index=lf_names)
        d["Overlaps"] = Series(data=self.lf_overlaps(), index=lf_names)
        d["Conflicts"] = Series(data=self.lf_conflicts(), index=lf_names)

        if Y is not None:
            labels = np.unique(
                np.concatenate((Y.flatten(), self.L.flatten(), np.array([-1])))
            )
            confusions = [
                confusion_matrix(Y, self.L[:, i], labels=labels)[1:, 1:]
                for i in range(m)
            ]
            corrects = [np.diagonal(conf).sum() for conf in confusions]
            incorrects = [
                conf.sum() - correct for conf, correct in zip(confusions, corrects)
            ]
            accs = self.lf_empirical_accuracies(Y)
            d["Correct"] = Series(data=corrects, index=lf_names)
            d["Incorrect"] = Series(data=incorrects, index=lf_names)
            d["Emp. Acc."] = Series(data=accs, index=lf_names)

        if est_weights is not None:
            d["Learned Weight"] = Series(est_weights, index=lf_names)

        return DataFrame(data=d, index=lf_names)

def from_ids_and_parent_path(
        cls: Type[PT], ids: Set[str], parent_path: Path | None
    ) -> Dict[str, PT]:
        if parent_path is None:
            return {}

        children = {}

        # Note: we're using the in-file ID. We could make this faster using the path-ID if this becomes perf bottleneck, but it's better to have 1 source of truth.
        for child_path in cls.iterate_children_paths_of_parent_path(parent_path):
            child_id = ModelCache.shared().get_model_id(child_path, cls)
            if child_id in ids:
                children[child_id] = cls.load_from_file(child_path)
            if child_id is None:
                child = cls.load_from_file(child_path)
                if child.id in ids:
                    children[child.id] = child

        return children

def normalize_local_disk(local_disk: str) -> str:
    local_disk = str(local_disk).lower().strip()
    parts = local_disk.split(':')

    def _check_size(size_str: str) -> None:
        size_to_check = size_str.rstrip('+')
        try:
            size = float(size_to_check)
            if size <= 0:
                raise ValueError()
        except ValueError:
            with ux_utils.print_exception_no_traceback():
                raise ValueError(  # pylint: disable=raise-missing-from
                    f'Invalid local_disk: {local_disk!r}. '
                    'Expected "mode:size[+]", "mode", or "size[+]". Mode '
                    'must be "nvme" or "ssd", size must be positive (GB), '
                    'optionally with "+".')

    if len(parts) == 1:
        part = parts[0]
        if part in ('nvme', 'ssd'):
            mode = part
            size_str = DEFAULT_LOCAL_DISK_SIZE
        else:
            mode = 'nvme'
            size_str = part
            _check_size(size_str)
    elif len(parts) == 2:
        mode, size_str = parts
        if mode not in ('nvme', 'ssd'):
            raise ValueError(f'Invalid local_disk mode: {mode!r}. '
                             'Must be "nvme" or "ssd".')
        _check_size(size_str)
    else:
        raise ValueError(f'Invalid local_disk format: {local_disk!r}. '
                         'Expected "mode:size[+]", "mode", or "size[+]". '
                         'Examples: "nvme:1000+", "ssd:500", "nvme", "1000+".')

    return f'{mode}:{size_str}'

def status(self, layer: Union[str, int]):
        if isinstance(layer, str):
            if layer not in self.layer_names:
                raise ValueError(f'Layer does not exist: {layer}')
            for name, child in self.model.named_children():
                if name == layer:
                    outs = []
                    for param in child.parameters():
                        outs.append('unfrozen' if param.requires_grad else 'frozen')
                    print(f'Freeze status of layer {layer}: {outs}')
                    return outs
        if isinstance(layer, int):
            outs = []
            for param in list(self.model.children())[layer].parameters():
                outs.append('unfrozen' if param.requires_grad else 'frozen')
            print(f'Freeze status of layer {layer}: {outs}')
            return outs

def update_metadata(token, commit_sha):
    with tempfile.TemporaryDirectory() as tmp_dir:
        repo = Repository(
            tmp_dir, clone_from="huggingface/transformers-metadata", repo_type="dataset", use_auth_token=token
        )

        frameworks_table = get_frameworks_table()
        frameworks_dataset = Dataset.from_pandas(frameworks_table)
        frameworks_dataset.to_json(os.path.join(tmp_dir, "frameworks.json"))

        tags_dataset = Dataset.from_json(os.path.join(tmp_dir, "pipeline_tags.json"))
        table = {
            tags_dataset[i]["model_class"]: (tags_dataset[i]["pipeline_tag"], tags_dataset[i]["auto_class"])
            for i in range(len(tags_dataset))
        }
        table = update_pipeline_and_auto_class_table(table)

        # Sort the model classes to avoid some nondeterministic updates to create false update commits.
        model_classes = sorted(list(table.keys()))
        tags_table = pd.DataFrame(
            {
                "model_class": model_classes,
                "pipeline_tag": [table[m][0] for m in model_classes],
                "auto_class": [table[m][1] for m in model_classes],
            }
        )
        tags_dataset = Dataset.from_pandas(tags_table)
        tags_dataset.to_json(os.path.join(tmp_dir, "pipeline_tags.json"))

        if repo.is_repo_clean():
            print("Nothing to commit!")
        else:
            if commit_sha is not None:
                commit_message = (
                    f"Update with commit {commit_sha}\n\nSee: "
                    f"https://github.com/huggingface/transformers/commit/{commit_sha}"
                )
            else:
                commit_message = "Update"
            repo.push_to_hub(commit_message)

def assert_allclose(actual, desired, rtol=None, atol=None, dtype=None, **kwargs):
    if dtype is None:
        dtype = "float32" if isinstance(actual, float) else actual.dtype

    tols = {}
    if rtol is None or atol is None:
        tols = dtype_tols(dtype)
    if rtol is not None:
        tols["rtol"] = rtol
    if atol is not None:
        tols["atol"] = atol

    if not isinstance(actual, float):
        actual = actual.astype(jnp.float32)
    if not isinstance(desired, float):
        desired = desired.astype(jnp.float32)

    np.testing.assert_allclose(actual, desired, **tols, **kwargs)

def login(
    workspace_id: Optional[str] = None,
    auth_token: Optional[str] = None,
    url: Optional[str] = None,
):
    if workspace_id is None and auth_token is None and url is None:
        if WorkspaceInfoLocalRecord.get_current_workspace_id() is not None:
            # If we are already logged in, do nothing.
            return
    # First, update the workspace_id, auth_token, and url if they are None and
    # there are environment variables.
    workspace_id = (
        workspace_id if workspace_id else os.environ.get("LEPTON_WORKSPACE_ID")
    )
    auth_token = auth_token if auth_token else os.environ.get("LEPTON_WORKSPACE_TOKEN")
    # If workspace_id contains colon, it is a credential that also contains the token.
    if workspace_id and ":" in workspace_id:
        workspace_id, auth_token = workspace_id.split(":", 1)
    url = url if url else os.environ.get("LEPTON_WORKSPACE_URL")
    if workspace_id:
        if not auth_token:
            logger.warning("Warning: you have not specified an auth token.")
        WorkspaceInfoLocalRecord.set_and_save(workspace_id, auth_token, url)
    else:
        raise WorkspaceConfigurationError(
            "You must specify workspace_id or set LEPTON_WORKSPACE_ID in the"
            " environment. If you do not know your workspace id, go to"
            " https://dashboard.lepton.ai/credentials and login with the"
            " credential string via login(credential_string)."
        )

def generate_matrix(shape, dtype=float, **kwargs):
    singular_values, = argument.parse_kwargs(
        kwargs, ('singular_values', None),
    )

    if len(shape) <= 1:
        raise ValueError(
            'shape {} is invalid for matrices: too few axes'.format(shape)
        )
    # TODO(beam2d): consider supporting integer/boolean matrices
    dtype = numpy.dtype(dtype)
    if dtype.kind not in 'fc':
        raise TypeError('dtype {} is not supported'.format(dtype))

    if singular_values is None:
        raise TypeError('singular_values is not given')
    singular_values = numpy.asarray(singular_values)
    if not numpy.isrealobj(singular_values):
        raise TypeError('singular_values is not real')
    if (singular_values < 0).any():
        raise ValueError('negative singular value is given')

    if 0 in shape:
        # NumPy<1.16 does not support zero-sized matrices in svd, so skip it.
        # Try broadcast first to raise an error on shape mismatch.
        _broadcast_to(singular_values, shape[:-2] + (min(shape[-2:]),))
        return numpy.empty(shape, dtype=dtype)

    # Generate random matrices with given singular values. We simply generate
    # orthogonal vectors using SVD on random matrices and then combine them
    # with the given singular values.
    a = numpy.random.randn(*shape)
    if dtype.kind == 'c':
        a = a + 1j * numpy.random.randn(*shape)
    u, s, vh = numpy.linalg.svd(a, full_matrices=False)
    sv = _broadcast_to(singular_values, s.shape)
    a = numpy.einsum('...ik,...k,...kj->...ij', u, sv, vh)
    return a.astype(dtype)

def in_demo(trace=0, sql=True):
