def get_embedding_field_names(marqo_index: MarqoIndex, tensor_field_names: Optional[List[str]] = None) \
        -> (Tuple)[List[str], List[str]]:

    if marqo_index.type in {IndexType.Structured, IndexType.SemiStructured}:
        # For structured indexes, embeddings are stored per field
        if hasattr(marqo_index, 'tensor_fields'):
            if tensor_field_names:
                index_tensor_field_names = [tf.name for tf in marqo_index.tensor_fields]
                requested_tensor_fields = []
                for tf_name in tensor_field_names:
                    if tf_name in index_tensor_field_names:
                        # If tf_name is in index_tensor_field_names, append the corresponding item
                        # in marqo_index.tensor_fields that has that name
                        requested_tensor_fields.append(
                            next(tf for tf in marqo_index.tensor_fields if tf.name == tf_name)
                        )
                    else:
                        raise core_exceptions.InvalidArgumentError(
                            f"Tensor field '{tf_name}' not found in index '{marqo_index.name}'. "
                            f"Available tensor fields: {index_tensor_field_names}"
                        )
            else:
                requested_tensor_fields = marqo_index.tensor_fields

            return ([tf.name for tf in requested_tensor_fields],
                    [tf.embeddings_field_name for tf in requested_tensor_fields])
        else:
            # Index has no tensor fields at all
            raise core_exceptions.InvalidArgumentError(
                f"Index '{marqo_index.name}' has no tensor fields, cannot retrieve embeddings"
                f" for {tensor_field_names}"
            )
    else:
        raise InternalError(
            f"Attempting to retrieve only embeddings for unstructured index '{marqo_index.name}'"
            f" which was created before {MINIMUM_SEMI_STRUCTURED_INDEX_VERSION}. This functionality should be disabled."
        )

async def aput_directory(
        self,
        local_path: Optional[str] = None,
        to_path: Optional[str] = None,
        ignore_file: Optional[str] = None,
        overwrite: bool = True,
    ) -> int:
        if to_path is None:
            to_path = str(self.basepath)
        else:
            to_path = self._resolve_path(to_path)

        if local_path is None:
            local_path = "."

        included_files = None
        if ignore_file:
            with open(ignore_file) as f:
                ignore_patterns = f.readlines()

            included_files = filter_files(
                local_path, ignore_patterns, include_dirs=True
            )

        counter = 0
        for f in Path(local_path).rglob("*"):
            relative_path = f.relative_to(local_path)
            if included_files and str(relative_path) not in included_files:
                continue

            if to_path.endswith("/"):
                fpath = to_path + relative_path.as_posix()
            else:
                fpath = to_path + "/" + relative_path.as_posix()

            if f.is_dir():
                pass
            else:
                f = f.as_posix()
                if overwrite:
                    await run_sync_in_worker_thread(
                        self.filesystem.put_file, f, fpath, overwrite=True
                    )
                else:
                    await run_sync_in_worker_thread(self.filesystem.put_file, f, fpath)

                counter += 1

        return counter

def check_setitem_lengths(indexer, value, values) -> bool:
    no_op = False

    if isinstance(indexer, (np.ndarray, list)):
        # We can ignore other listlikes because they are either
        #  a) not necessarily 1-D indexers, e.g. tuple
        #  b) boolean indexers e.g. BoolArray
        if is_list_like(value):
            if len(indexer) != len(value) and values.ndim == 1:
                # boolean with truth values == len of the value is ok too
                if isinstance(indexer, list):
                    indexer = np.array(indexer)
                if not (
                    isinstance(indexer, np.ndarray)
                    and indexer.dtype == np.bool_
                    and indexer.sum() == len(value)
                ):
                    raise ValueError(
                        "cannot set using a list-like indexer "
                        "with a different length than the value"
                    )
            if not len(indexer):
                no_op = True

    elif isinstance(indexer, slice):
        if is_list_like(value):
            if len(value) != length_of_indexer(indexer, values) and values.ndim == 1:
                # In case of two dimensional value is used row-wise and broadcasted
                raise ValueError(
                    "cannot set using a slice indexer with a "
                    "different length than the value"
                )
            if not len(value):
                no_op = True

    return no_op

def init_instance_by_config(
    config: InstConf,
    default_module=None,
    accept_types: Union[type, Tuple[type]] = (),
    try_kwargs: Dict = {},
    **kwargs,
) -> Any:
    if isinstance(config, accept_types):
        return config

    if isinstance(config, (str, Path)):
        if isinstance(config, str):
            # path like 'file:///<path to pickle file>/obj.pkl'
            pr = urlparse(config)
            if pr.scheme == "file":
                # To enable relative path like file://data/a/b/c.pkl.  pr.netloc will be data
                path = pr.path
                if pr.netloc != "":
                    path = path.lstrip("/")

                pr_path = os.path.join(pr.netloc, path) if bool(pr.path) else pr.netloc
                with open(os.path.normpath(pr_path), "rb") as f:
                    return restricted_pickle_load(f)
        else:
            with config.open("rb") as f:
                return restricted_pickle_load(f)

    klass, cls_kwargs = get_callable_kwargs(config, default_module=default_module)

    try:
        return klass(**cls_kwargs, **try_kwargs, **kwargs)
    except (TypeError,):
        # TypeError for handling errors like
        # 1: `XXX() got multiple values for keyword argument 'YYY'`
        # 2: `XXX() got an unexpected keyword argument 'YYY'
        return klass(**cls_kwargs, **kwargs)

def process_horizons_and_targets(
    horizons: int | Sequence[int] | None = None,
    fallback_horizon: int | None = None,
    target_components: str | Sequence[str] | None = None,
    fallback_target_components: Sequence[str] | None = None,
    check_component_names: bool = False,
) -> tuple[Sequence[int], Sequence[str]]:

    if target_components is not None:
        if isinstance(target_components, str):
            target_components = [target_components]
        if check_component_names and fallback_target_components is not None:
            invalid_components = [
                target_name
                for target_name in target_components
                if target_name not in fallback_target_components
            ]
            raise_if(
                len(invalid_components) > 0,
                "Invalid `target_components`. The following components are not in the components of the "
                f"`background_series`: {invalid_components}. Provide some valid components from: "
                f"{fallback_target_components}.",
                logger,
            )
    else:
        target_components = fallback_target_components

    if horizons is not None:
        if isinstance(horizons, int):
            horizons = [horizons]

        if fallback_horizon is not None:
            raise_if(
                max(horizons) > fallback_horizon,
                "At least one of the `horizons` is larger than `output_chunk_length`.",
            )
        raise_if(min(horizons) < 1, "All `horizons` must be `>=1`.")
    else:
        horizons = range(1, fallback_horizon + 1)

    return horizons, target_components

def is_node_supported(self, _, node: torch.fx.Node) -> bool:
        if node.op != "call_function":
            return False

        options: list[str] = []
        if not isinstance(node.target, str):
            op_type = node.target.__name__
        else:
            op_type = str(node.target)

        if node.name in self._enabled_ops_by_name:
            return True

        supported_ops = (
            OperatorSupport(options)._support_dict | self.extended_support_dict
        )
        if op_type == "getitem":
            return True

        if "torch.ops." + str(op_type) in supported_ops:
            return True
        else:
            print("Op not supported: ", "torch.ops." + str(op_type))

        if op_type in self._op_types_to_skip or node.name in self._op_names_to_skip:
            print(
                f"[OpenVINO Backend] The {op_type} operator with name '{node.name}' is skipped."
            )
            return False

        return False

def write_megam_file(train_toks, encoding, stream, bernoulli=True, explicit=True):
    # Look up the set of labels.
    labels = encoding.labels()
    labelnum = {label: i for (i, label) in enumerate(labels)}

    # Write the file, which contains one line per instance.
    for featureset, label in train_toks:
        # First, the instance number (or, in the weighted multiclass case, the cost of each label).
        if hasattr(encoding, "cost"):
            stream.write(
                ":".join(str(encoding.cost(featureset, label, l)) for l in labels)
            )
        else:
            stream.write("%d" % labelnum[label])

        # For implicit file formats, just list the features that fire
        # for this instance's actual label.
        if not explicit:
            _write_megam_features(encoding.encode(featureset, label), stream, bernoulli)

        # For explicit formats, list the features that would fire for
        # any of the possible labels.
        else:
            for l in labels:
                stream.write(" #")
                _write_megam_features(encoding.encode(featureset, l), stream, bernoulli)

        # End of the instance.
        stream.write("\n")

def get_object(cls, obj_type, sub_type, filters, attempt, *args):
        type_order = ObjectOrder.type_to_order(obj_type)
        sub_order = ObjectOrder.type_to_order(sub_type)

        if type_order is None:
            raise MetaflowInternalError(msg="Cannot find type %s" % obj_type)
        if type_order >= ObjectOrder.type_to_order("metadata"):
            raise MetaflowInternalError(msg="Type %s is not allowed" % obj_type)

        if sub_order is None:
            raise MetaflowInternalError(msg="Cannot find subtype %s" % sub_type)

        if type_order >= sub_order:
            raise MetaflowInternalError(
                msg="Subtype %s not allowed for %s" % (sub_type, obj_type)
            )

        # Metadata is always only at the task level
        if sub_type == "metadata" and obj_type != "task":
            raise MetaflowInternalError(
                msg="Metadata can only be retrieved at the task level"
            )

        if attempt is not None:
            try:
                attempt_int = int(attempt)
                if attempt_int < 0:
                    raise ValueError("Attempt can only be positive")
            except ValueError:
                raise ValueError("Attempt can only be a positive integer")
        else:
            attempt_int = None

        pre_filter = cls._get_object_internal(
            obj_type, type_order, sub_type, sub_order, filters, attempt_int, *args
        )
        if attempt_int is None or sub_type != "metadata":
            # If no attempt or not for metadata, just return as is
            return pre_filter
        return MetadataProvider._reconstruct_metadata_for_attempt(
            pre_filter, attempt_int
        )

def manage_primitives(enable_names=None, disable_names=None, disable_all_first=False):
    enable_set = set(enable_names or [])
    disable_set = set(disable_names or [])

    if disable_all_first:
        for name, cls in _primitive_registry.items():
            if (
                isinstance(cls, type)
                and issubclass(cls, BasePrimitive)
                and cls is not BasePrimitive
            ):
                cls.set_enabled(False)

    # Apply enables
    for name in enable_set:
        cls = _primitive_registry.get(name)
        if cls and isinstance(cls, type) and issubclass(cls, BasePrimitive):
            cls.set_enabled(True)
        else:
            raise ValueError(f"Primitive not found in registry: {name}")

    # Apply disables (overrides enables if there's a conflict)
    for name in disable_set:
        cls = _primitive_registry.get(name)
        if cls and isinstance(cls, type) and issubclass(cls, BasePrimitive):
            cls.set_enabled(False)
        else:
            raise ValueError(f"Primitive not found in registry: {name}")

def fill_doc(f):
    docstring = f.__doc__
    if not docstring:
        return f
    lines = docstring.splitlines()
    # Find the minimum indent of the main docstring, after first line
    if len(lines) < 2:
        icount = 0
    else:
        icount = _indentcount_lines(lines[1:])
    # Insert this indent to dictionary docstrings
    try:
        indented = docdict_indented[icount]
    except KeyError:
        indent = " " * icount
        docdict_indented[icount] = indented = {}
        for name, dstr in docdict.items():
            lines = dstr.splitlines()
            try:
                newlines = [lines[0]]
                for line in lines[1:]:
                    newlines.append(indent + line)
                indented[name] = "\n".join(newlines)
            except IndexError:
                indented[name] = dstr
    try:
        f.__doc__ = docstring % indented
    except (TypeError, ValueError, KeyError) as exp:
        funcname = f.__name__
        funcname = docstring.split("\n")[0] if funcname is None else funcname
        raise RuntimeError(f"Error documenting {funcname}:\n{exp}")
    return f

def extract_article_content(
        cls, html_content: str, domain: str
    ) -> str:
        soup = BeautifulSoup(html_content, "html.parser")

        # Remove unwanted elements
        for element in soup.find_all(
            ["script", "style", "nav", "header", "footer", "iframe"]
        ):
            element.decompose()

        # Try domain-specific selector first
        if domain in cls.DOMAIN_SELECTORS:
            selector = cls.DOMAIN_SELECTORS[domain]["article"]
            content = soup.select_one(selector)
            if content:
                return cls.clean_text(content.get_text())

        # Fallback to common article containers
        article_containers = [
            "article",
            '[role="article"]',
            ".article-content",
            ".post-content",
            ".entry-content",
            "#main-content",
        ]

        for container in article_containers:
            content = soup.select_one(container)
            if content:
                return cls.clean_text(content.get_text())

        # Last resort: extract all paragraph text
        paragraphs = soup.find_all("p")
        if paragraphs:
            return cls.clean_text(
                " ".join(p.get_text() for p in paragraphs)
            )

        return cls.clean_text(soup.get_text())

def step_scheduler(
        self,
        model: L.LightningModule,
        scheduler_cfg: Optional[Mapping[str, Union[L.fabric.utilities.types.LRScheduler, bool, str, int]]],
        level: Literal["step", "epoch"],
        current_value: int,
    ) -> None:

        # no scheduler
        if scheduler_cfg is None:
            return

        # wrong interval (step vs. epoch)
        if scheduler_cfg["interval"] != level:
            return

        # right interval, but wrong step wrt frequency
        if current_value % cast(int, scheduler_cfg["frequency"]) != 0:
            return

        # assemble potential monitored values
        possible_monitor_vals = {None: None}
        if isinstance(self._current_train_return, torch.Tensor):
            possible_monitor_vals.update("train_loss", self._current_train_return)
        elif isinstance(self._current_train_return, Mapping):
            possible_monitor_vals.update({"train_" + k: v for k, v in self._current_train_return.items()})

        if isinstance(self._current_val_return, torch.Tensor):
            possible_monitor_vals.update("val_loss", self._current_val_return)
        elif isinstance(self._current_val_return, Mapping):
            possible_monitor_vals.update({"val_" + k: v for k, v in self._current_val_return.items()})

        try:
            monitor = possible_monitor_vals[cast(Optional[str], scheduler_cfg["monitor"])]
        except KeyError as ex:
            possible_keys = list(possible_monitor_vals.keys())
            raise KeyError(
                f"monitor {scheduler_cfg['monitor']} is invalid. Possible values are {possible_keys}."
            ) from ex

        # rely on model hook for actual step
        model.lr_scheduler_step(scheduler_cfg["scheduler"], monitor)

def delete(
        self,
        widget: bool = False,
        commit: bool = True,
        force: bool = False,
    ) -> None:
        from mage_ai.data_preparation.models.pipeline import Pipeline

        if self.pipeline is not None:
            self.pipeline.delete_block(
                self,
                widget=widget,
                commit=commit,
                force=force,
            )
            # For block_type SCRATCHPAD and MARKDOWN, also delete the file if possible
            if self.type in NON_PIPELINE_EXECUTABLE_BLOCK_TYPES:
                pipelines = Pipeline.get_pipelines_by_block(
                    self,
                    repo_path=self.pipeline.repo_path,
                    widget=widget,
                )
                pipelines = [
                    pipeline for pipeline in pipelines if self.pipeline_uuid != pipeline.uuid
                ]
                if len(pipelines) == 0:
                    os.remove(self.file_path)
            return

        # TODO (tommy dang): delete this block from all pipelines in all projects
        # If pipeline is not specified, delete the block from all pipelines and delete the file.
        pipelines = Pipeline.get_pipelines_by_block(self, repo_path=self.repo_path, widget=widget)
        if not force:
            for p in pipelines:
                if not p.block_deletable(self):
                    raise HasDownstreamDependencies(
                        f'Block {self.uuid} has downstream dependencies in pipeline {p.uuid}. '
                        'Please remove the dependencies before deleting the block.'
                    )

        for p in pipelines:
            p.delete_block(
                p.get_block(self.uuid, widget=widget),
                widget=widget,
                commit=commit,
                force=force,
            )

        os.remove(self.file_path)

def LRSchedulerDataclassField(description: str, default: dict = None):
    allow_none = True
    default = default or {}

    class LRSchedulerConfigField(schema_utils.SchemaField):
        """Custom field class for learning rate scheduler.

        Deserializes a dict to a valid instance of `LRSchedulerConfig` and creates a corresponding JSON schema for
        external usage.
        """

        def _deserialize(self, value, attr, data, **kwargs):
            if value is None:
                return value
            if isinstance(value, dict):
                try:
                    return LRSchedulerConfig.model_validate(value)
                except (TypeError, ConfigValidationError) as e:
                    raise ConfigValidationError(
                        f"Invalid params for learning rate scheduler: {value}, see LRSchedulerConfig class. Error: {e}"
                    )
            raise ConfigValidationError("Field should be None or dict")

        def _jsonschema_type_mapping(self):
            return {
                **schema_utils.unload_jsonschema_from_config_class(LRSchedulerConfig),
                "title": "learning_rate_scheduler_options",
                "description": description,
            }

    if not isinstance(default, dict):
        raise ConfigValidationError(f"Invalid default: `{default}`")

    load_default = lambda: LRSchedulerConfig.model_validate(default)
    try:
        dump_default = LRSchedulerConfig.model_validate(default).to_dict()
    except Exception:
        dump_default = default if isinstance(default, dict) else {}

    return field(
        metadata={
            "marshmallow_field": LRSchedulerConfigField(
                allow_none=allow_none,
                load_default=load_default,
                dump_default=dump_default,
                metadata={
                    "description": description,
                },
            )
        },
        default_factory=load_default,
    )

def validate_min_itemsize(self, min_itemsize) -> None:
        if min_itemsize is None:
            return
        if not isinstance(min_itemsize, dict):
            return

        q = self.queryables()
        for k in min_itemsize:
            # ok, apply generally
            if k == "values":
                continue
            if k not in q:
                raise ValueError(
                    f"min_itemsize has the key [{k}] which is not an axis or "
                    "data_column"
                )

def schedule_generic_jobs():
    try:
        # Get all jobs with INITIAL status across all repositories
        jobs = GenericJob.get_jobs_with_initial_status()
        job_manager = get_job_manager()

        if not jobs:
            return

        logger.info(f'Scheduling {len(jobs)} generic jobs')

        # Schedule each job with the job manager
        for job in jobs:
            try:
                if job.job_type == GenericJob.JobType.CANCEL_PIPELINE_RUN:
                    pipeline_run_id = job.payload.get('pipeline_run_id')
                    cancelled_block_run_ids = job.payload.get('cancelled_block_run_ids')
                    try:
                        kill_cancelled_runs(pipeline_run_id, cancelled_block_run_ids)
                    except Exception:
                        pass
                    # Add job to job manager for execution
                    job_manager.add_job(
                        JobType.GENERIC_JOB,
                        job.id,
                        on_pipeline_run_cancelled,
                        # args
                        job.id,
                        pipeline_run_id,
                        cancelled_block_run_ids,
                    )
                    job.mark_queued()
                    logger.info(f'Scheduled generic job {job.id} ({job.job_type})')
                else:
                    raise ValueError(f"Unknown job type: {job.job_type}")
            except Exception as e:
                error_message = f"Failed to schedule generic job: {str(e)}"
                logger.exception(f'Failed to schedule generic job {job.id}: {error_message}')
                job.mark_failed({'error': error_message})
    except Exception as e:
        logger.exception(f'Failed to schedule generic jobs: {e}')

def resam_ts_data(
    ts_feature: Union[pd.DataFrame, pd.Series],
    start_time: Union[str, pd.Timestamp] = None,
    end_time: Union[str, pd.Timestamp] = None,
    method: Union[str, Callable] = "last",
    method_kwargs: dict = {},
):

    selector_datetime = slice(start_time, end_time)

    from ..data.dataset.utils import get_level_index  # pylint: disable=C0415

    feature = lazy_sort_index(ts_feature)

    datetime_level = get_level_index(feature, level="datetime") == 0
    if datetime_level:
        feature = feature.loc[selector_datetime]
    else:
        feature = feature.loc(axis=0)[(slice(None), selector_datetime)]

    if feature.empty:
        return None
    if isinstance(feature.index, pd.MultiIndex):
        if callable(method):
            method_func = method
            return feature.groupby(level="instrument", group_keys=False).apply(method_func, **method_kwargs)
        elif isinstance(method, str):
            return getattr(feature.groupby(level="instrument", group_keys=False), method)(**method_kwargs)
    else:
        if callable(method):
            method_func = method
            return method_func(feature, **method_kwargs)
        elif isinstance(method, str):
            return getattr(feature, method)(**method_kwargs)
    return feature

def temporary_modules(modules=None, attributes=None):
    if modules is None:
        modules = {}
    if attributes is None:
        attributes = {}
    import sys
    from importlib import import_module

    try:
        # Set attributes in sys.modules under their old name
        for old, new in attributes.items():
            old_module, old_attr = old.rsplit(".", 1)
            new_module, new_attr = new.rsplit(".", 1)
            setattr(import_module(old_module), old_attr, getattr(import_module(new_module), new_attr))

        # Set modules in sys.modules under their old name
        for old, new in modules.items():
            sys.modules[old] = import_module(new)

        yield
    finally:
        # Remove the temporary module paths
        for old in modules:
            if old in sys.modules:
                del sys.modules[old]

def safe_rmtree(path: str) -> None:
    try:
        shutil.rmtree(path)
    except PermissionError:
        # Fallback: manual post-order traversal
        p = Path(path)
        for sub in sorted(
            p.rglob("*"), key=lambda x: -x.as_posix().count("/")
        ):
            try:
                if sub.is_file() or sub.is_symlink():
                    sub.unlink()
                elif sub.is_dir():
                    sub.rmdir()
            except Exception as inner_e:
                LOGGER.warning("Failed to delete %s: %s", sub, inner_e)
        try:
            p.rmdir()
        except Exception as final_e:
            LOGGER.warning("Failed to delete directory %s: %s", p, final_e)

def update_table_list_in_connection(
    connections: list[DataSourceConnection],
    sql_metadata: SQLMetadata,
    updated_table_list: list[DataTable],
) -> None:
    for connection in connections:
        if connection.name != sql_metadata.connection:
            continue

        for database in connection.databases:
            if database.name != sql_metadata.database:
                continue

            for schema in database.schemas:
                if schema.name != sql_metadata.schema:
                    continue

                schema.tables = updated_table_list
                return

def override_logger(
    newLevel: int = logging.DEBUG,
    fmtstr: str = "%(message)s",
    filename: Optional[str] = None,
) -> Generator[None, None, None]:
    try:
        oldLevel = logging.root.level
        logging.root.setLevel(newLevel)
        if fmtstr:
            newformatter = logging.Formatter(fmtstr, None, "%")
            oldFormatters = []
            for handler in logging.root.handlers:
                oldFormatters.append(handler.formatter)
                handler.formatter = newformatter
        filehandler = None
        if filename:
            filehandler = logging.FileHandler(filename, mode="w")
            logging.root.addHandler(filehandler)
        yield
    finally:
        logging.root.setLevel(oldLevel)
        if fmtstr:
            # pyre-fixme[61]: `oldFormatters` is undefined, or not always defined.
            for handler, formatter in zip(logging.root.handlers, oldFormatters):
                handler.formatter = formatter
        if filehandler:
            logging.root.removeHandler(filehandler)

def wait_for_server(
    server_url: str,
    timeout: float = 300.0,
    check_interval: float = 1.0,
    process: subprocess.Popen | None = None,
) -> bool:
    server_url = server_url.rstrip("/")
    health_url = f"{server_url}/health"

    start_time = time.time()
    while time.time() - start_time < timeout:
        # Check if subprocess died
        if process is not None:
            poll_result = process.poll()
            if poll_result is not None:
                raise RuntimeError(
                    f"SGLang server process died with exit code {poll_result}"
                )

        try:
            response = requests.get(health_url, timeout=5.0)
            if response.status_code == 200:
                torchrl_logger.info(f"SGLang server at {server_url} is ready")
                return True
        except requests.exceptions.RequestException:
            pass

        time.sleep(check_interval)

    raise TimeoutError(
        f"SGLang server at {server_url} did not become ready within {timeout}s"
    )

def init_weight_goog(m, n='', fix_group_fanout=True, last_bn=None):
    if isinstance(m, CondConv2d):
        fan_out = m.kernel_size[0] * m.kernel_size[1] * m.out_channels
        if fix_group_fanout:
            fan_out //= m.groups
        init_weight_fn = get_condconv_initializer(lambda w: w.data.normal_(
            0, math.sqrt(2.0 / fan_out)), m.num_experts, m.weight_shape)
        init_weight_fn(m.weight)
        if m.bias is not None:
            m.bias.data.zero_()
    elif isinstance(m, nn.Conv2d):
        fan_out = m.kernel_size[0] * m.kernel_size[1] * m.out_channels
        if fix_group_fanout:
            fan_out //= m.groups
        m.weight.data.normal_(0, math.sqrt(2.0 / fan_out))
        if m.bias is not None:
            m.bias.data.zero_()
    elif isinstance(m, nn.BatchNorm2d):
        if n in last_bn:
            m.weight.data.zero_()
            m.bias.data.zero_()
        else:
            m.weight.data.fill_(1.0)
            m.bias.data.zero_()
        m.weight.data.fill_(1.0)
        m.bias.data.zero_()
    elif isinstance(m, nn.Linear):
        fan_out = m.weight.size(0)  # fan-out
        fan_in = 0
        if 'routing_fn' in n:
            fan_in = m.weight.size(1)
        init_range = 1.0 / math.sqrt(fan_in + fan_out)
        m.weight.data.uniform_(-init_range, init_range)
        m.bias.data.zero_()

def get_biostars_dataset(start_idx=9557161, accept_threshold=1000000, sleep=0.1, folder="biostars"):
    headers = {"Content-Type": "application/json"}

    has_accepted_count = 0

    pbar = tqdm(range(start_idx, 0, -1), desc="Running ...")

    for idx in pbar:
        url = f"https://www.biostars.org/api/post/{idx}"
        file = os.path.join(folder, f"{idx}.json")

        if os.path.isfile(file):
            with open(file, "r") as f:
                data = json.load(f)

                if data.get("has_accepted"):
                    has_accepted_count += 1

            print(f"MSG: {file} exists. Skipping; Current accepted: {has_accepted_count}")
            continue

        r = requests.get(url, headers=headers)

        # print(r.status_code, r.reason)

        if r.status_code == 200:
            data = r.json()

            if data.get("has_accepted"):
                has_accepted_count += 1

            with open(file, "w") as f:
                json.dump(data, f)
            # print(f"MSG: File downloaded: {idx}; Current accepted: {has_accepted_count}")
        else:
            print("ERROR: Retrieving data: ", idx)
        time.sleep(sleep)

        if has_accepted_count == accept_threshold:
            print(f"{accept_threshold} entries with has_accepted found. Stopping.")
            break

        pbar.set_description(f"Item: {idx}; Accepted {has_accepted_count}")

def configure_zenflow(engine: "DeepSpeedEngine") -> None:
    zenflow_config = engine.zenflow_config()
    if zenflow_config == None:
        engine.zenflow = False
        return
    if not required_torch_version(min_version=2.1):
        raise ValueError(
            "Please use PyTorch 2.1 or later to enable ZenFlow. Alternatively, omit `zenflow` config in the config file to fall back to the default ZeRO-Offload optimizer."
        )

    engine.zenflow = True
    select_strategy = zenflow_config.select_strategy

    if select_strategy == 'auto':
        select_strategy = "epoch"
        if isinstance(zenflow_config.select_interval, int):
            raise Warning(
                "If use auto select strategy, select_interval will be set to 1 and select_strategy will be set to epoch, thus select_interval would be overwritten."
            )
        engine.select_interval = 1
    else:
        if isinstance(zenflow_config.select_interval, str):
            raise ValueError("If don't use auto select strategy, select_interval must be a number.")
        engine.select_interval = zenflow_config.select_interval

    if isinstance(zenflow_config.update_interval, str):
        engine.auto_update = True
        engine.update_interval = 0
    else:
        engine.auto_update = False
        engine.update_interval = int(zenflow_config.update_interval)

    if select_strategy == 'epoch':
        if engine.training_dataloader is not None:
            zenflow_config.steps_per_epoch = len(engine.training_dataloader)
            engine.select_interval = engine.select_interval * len(engine.training_dataloader)
        else:
            engine.select_interval = 0

    if not engine.auto_update and engine.select_interval != 0 and engine.select_interval < engine.update_interval:
        raise ValueError("Select interval must be greater or equal to update interval")

    engine.overlap_step = zenflow_config.overlap_step

    engine.full_warm_up_rounds = zenflow_config.full_warm_up_rounds

    engine._config.gradient_accumulation_steps = engine.update_interval

def bio2_to_bioes(tags):
    new_tags = []
    for i, tag in enumerate(tags):
        if tag in EMPTY_OR_O_TAG:
            new_tags.append(tag)
        else:
            if len(tag) < 2:
                raise Exception(f"Invalid BIO2 tag found: {tag}")
            else:
                if tag[:2] in ('I-', 'I_'): # convert to E- if next tag is not I-
                    if i+1 < len(tags) and tags[i+1][:2] in ('I-', 'I_'):
                        new_tags.append('I-' + tag[2:]) # compensate for underscores
                    else:
                        new_tags.append('E-' + tag[2:])
                elif tag[:2] in ('B-', 'B_'): # convert to S- if next tag is not I-
                    if i+1 < len(tags) and tags[i+1][:2] in ('I-', 'I_'):
                        new_tags.append('B-' + tag[2:])
                    else:
                        new_tags.append('S-' + tag[2:])
                else:
                    raise Exception(f"Invalid IOB tag found: {tag}")
    return new_tags

def process_and_raise_last_exception(self):
    err_type, err, tb = sys.exc_info()
    line_number_match = re.search(r'[Ll][Ii][Nn][Ee]\s*[:=]?\s*(\d+)', str(err))
    if line_number_match:
      xml_line_number = int(line_number_match.group(1))
      xml_line = self._xml_string.split('\n')[xml_line_number - 1]
      stripped_xml_line = xml_line.strip()
      comment_match = re.search(_DEBUG_METADATA_TAG_PREFIX, stripped_xml_line)
      if comment_match:
        stripped_xml_line = stripped_xml_line[:comment_match.start()]
    else:
      xml_line = ''
      stripped_xml_line = ''

    message_lines = []
    if debug_mode():
      if get_full_dump_dir():
        self.dump_full_debug_info_to_disk()
      message_lines.extend([
          'Compile error raised by Mujoco.',
          str(err)])
      if xml_line:
        message_lines.extend([
            stripped_xml_line,
            self._generate_debug_message_from_xml_line(xml_line)])
    else:
      message_lines.extend([
          'Compile error raised by Mujoco; ' +
          'run again with --pymjcf_debug for additional debug information.',
          str(err)
      ])
      if xml_line:
        message_lines.append(stripped_xml_line)

    raise err_type('\n'.join(message_lines)).with_traceback(tb)

def log_string_debug_func(func, log_level, use_entry, override=None):
    lgr = logging.getLogger(func.__module__)

    def _get_bound_signature(*args, **kwargs) -> str:
        s = inspect.signature(func)
        # pylint:disable = broad-except
        try:
            ba = s.bind(*args, **kwargs)
        except Exception as e:
            # If kwargs are concat onto args, attempt to unpack. Fail otherwise
            if len(args) == 2 and len(kwargs) == 0 and isinstance(args[1], dict):
                ba = s.bind(*args[0], **args[1])
            else:
                raise e
        ba.apply_defaults()
        if override and len(override):
            for k, v in override.keys():
                ba[k] = v

        f_string = str(ba).replace("BoundArguments ", func.__name__)
        return f_string

    @wraps(func)
    def wrapper_entry(*args, **kwargs):
        if lgr.isEnabledFor(log_level):  # pragma: no cover
            f_string = _get_bound_signature(*args, **kwargs)
            s_caller = "::L".join(
                [str(i) for i in inspect.getouterframes(inspect.currentframe(), 2)[1][1:3]]
            )
            lgr.debug(
                f"Calling {f_string} from {s_caller}",
                **_debug_log_kwargs,
            )
        return func(*args, **kwargs)

    @wraps(func)
    def wrapper_exit(*args, **kwargs):
        output = func(*args, **kwargs)
        if lgr.isEnabledFor(log_level):  # pragma: no cover
            f_string = _get_bound_signature(*args, **kwargs)
            s_caller = "::L".join(
                [str(i) for i in inspect.getouterframes(inspect.currentframe(), 2)[1][1:3]]
            )
            lgr.debug(
                f"Calling {f_string}={output} from {s_caller}",
                **{"stacklevel": 2},
            )
        return output

    return wrapper_entry if use_entry else wrapper_exit

def bitpack(data, bits, pack_axis, bit_axis, pack_type, name="QuantizeInput"):
    ishape = data.shape
    n = len(ishape)
    if pack_type == "uint8":
        data_width = 8
    elif pack_type == "uint16":
        data_width = 16
    elif pack_type == "uint32":
        data_width = 32
    elif pack_type == "uint64":
        data_width = 64

    # Data must be in multiples of the data_width
    assert get_const_int(ishape[pack_axis]) % data_width == 0, "Not a multiple of word size"

    shape_vec = list(ishape)
    shape_vec[pack_axis] = shape_vec[pack_axis] // data_width
    shape_vec.insert(bit_axis, 1)
    bitserial_oshape = tuple(shape_vec)
    masks = np.array([0x1, 0x2, 0x4, 0x8, 0x10, 0x20, 0x40, 0x80])

    # pack axis shifts if bit axis comes before
    if bit_axis <= pack_axis:
        pack_axis += 1

    def _bitpack(*indices):
        packed_data = [tvm.tirx.const(0, pack_type)] * bits
        for k in range(data_width):
            # Translate indices for packed data back to original
            idx = [0] * n
            j = 0
            for i in range(n + 1):
                if i == bit_axis:
                    continue
                if i == pack_axis:
                    idx[j] = indices[i] * data_width + k
                else:
                    idx[j] = indices[i]
                j += 1

            element = data(*idx)
            for b in range(bits):
                extracted_bit = ((element & tvm.tirx.const(masks[b], "int32")) >> b).astype(
                    pack_type
                )
                packed_data[b] = packed_data[b] | extracted_bit
                if k < data_width - 1:
                    packed_data[b] = packed_data[b] << 1

            if k == data_width - 1:
                return tuple(packed_data)
        return tuple(packed_data)

    output_tuple = te.compute(bitserial_oshape, _bitpack, name=name, tag="bitpack")

    if bits > 1:
        return concatenate(output_tuple, axis=bit_axis)
    return output_tuple

def deduplicate_dataset(
    dataset: Type[Dataset], jaccard_threshold: float = 0.85
) -> Tuple[Type[Dataset], List[List[Dict]]]:
    duplicate_clusters = make_duplicate_clusters(dataset, jaccard_threshold)
    duplicate_indices = set(x["base_index"] for cluster in duplicate_clusters for x in cluster)
    extreme_dict = {}
    extremes_clusters = find_extremes(duplicate_clusters, dataset, jaccard_threshold)
    for extremes in extremes_clusters:
        for element in extremes:
            extreme_dict[element["base_index"]] = element
    remove_indices = duplicate_indices - set(extreme_dict.keys())
    ds_filter = dataset.filter(lambda x, idx: idx not in remove_indices, with_indices=True)

    # update duplicate_clusters
    for cluster in duplicate_clusters:
        for element in cluster:
            element["is_extreme"] = element["base_index"] in extreme_dict
            if element["is_extreme"]:
                element["copies"] = extreme_dict[element["base_index"]]["copies"]

    print(f"Original dataset size: {len(dataset)}")
    print(f"Number of duplicate clusters: {len(duplicate_clusters)}")
    print(f"Files in duplicate cluster: {len(duplicate_indices)}")
    print(f"Unique files in duplicate cluster: {len(extreme_dict)}")
    print(f"Filtered dataset size: {len(ds_filter)}")

    return ds_filter, duplicate_clusters

def multinomial_goodness_of_fit(
    probs,
    counts,
    *,
    total_count=None,
    plot=False,
):
    assert probs.dim() == 1
    assert probs.shape == counts.shape
    if total_count is None:
        truncated = False
        total_count = int(counts.sum())
    else:
        truncated = True
        assert total_count >= counts.sum()
    if plot:
        print_histogram(probs, counts)

    chi_squared = 0
    dof = 0
    for p, c in zip(probs.tolist(), counts.tolist()):
        if abs(p - 1) < 1e-8:
            return 1 if c == total_count else 0
        assert p < 1, f"bad probability: {p:g}"
        if p > 0:
            mean = total_count * p
            variance = total_count * p * (1 - p)
            if not (variance > 1):
                raise InvalidTest("Goodness of fit is inaccurate; use more samples")
            chi_squared += (c - mean) ** 2 / variance
            dof += 1
        else:
            warnings.warn("Zero probability in goodness-of-fit test")
            if c > 0:
                return math.inf

    if not truncated:
        dof -= 1

    survival = chi2sf(chi_squared, dof)
    return survival

def clip(
    x: Array,
    /,
    min: float | Array | None = None,
    max: float | Array | None = None,
) -> Array:

    def _isscalar(a: float | Array | None, /) -> TypeIs[float | None]:
        return a is None or isinstance(a, (int, float))

    min_shape = () if _isscalar(min) else min.shape
    max_shape = () if _isscalar(max) else max.shape

    # TODO: This won't handle dask unknown shapes
    result_shape = np.broadcast_shapes(x.shape, min_shape, max_shape)

    if min is not None:
        min = da.broadcast_to(da.asarray(min), result_shape)
    if max is not None:
        max = da.broadcast_to(da.asarray(max), result_shape)

    if min is None and max is None:
        return da.positive(x)

    if min is None:
        return astype(da.minimum(x, max), x.dtype)
    if max is None:
        return astype(da.maximum(x, min), x.dtype)

    return astype(da.minimum(da.maximum(x, min), max), x.dtype)

def fetch_random_conversation(
        self,
        last_message_role: str = None,
        message_tree_id: Optional[UUID] = None,
        review_result: Optional[bool] = True,
        deleted: Optional[bool] = False,
    ) -> list[Message]:
        if message_tree_id:
            messages_tree = self.fetch_message_tree(message_tree_id, review_result=review_result, deleted=deleted)
        else:
            messages_tree = self.fetch_random_message_tree(
                last_message_role, review_result=review_result, deleted=deleted
            )
        if not messages_tree:
            raise OasstError("No message tree found", OasstErrorCode.NO_MESSAGE_TREE_FOUND)

        if last_message_role:
            conv_messages = [m for m in messages_tree if m.role == last_message_role]
            conv_messages = [random.choice(conv_messages)]
        else:
            conv_messages = [random.choice(messages_tree)]
        messages_tree = {m.id: m for m in messages_tree}

        while True:
            if not conv_messages[-1].parent_id:
                # reached the start of the conversation
                break

            parent_message = messages_tree[conv_messages[-1].parent_id]
            conv_messages.append(parent_message)

        return list(reversed(conv_messages))

def fromstring(lex_str, include_semantics=False):
    CCGVar.reset_id()
    primitives = []
    families = {}
    entries = defaultdict(list)
    for line in lex_str.splitlines():
        # Strip comments and leading/trailing whitespace.
        line = COMMENTS_RE.match(line).groups()[0].strip()
        if line == "":
            continue

        if line.startswith(":-"):
            # A line of primitive categories.
            # The first one is the target category
            # ie, :- S, N, NP, VP
            primitives = primitives + [
                prim.strip() for prim in line[2:].strip().split(",")
            ]
        else:
            # Either a family definition, or a word definition
            (ident, sep, rhs) = LEX_RE.match(line).groups()
            (catstr, semantics_str) = RHS_RE.match(rhs).groups()
            (cat, var) = augParseCategory(catstr, primitives, families)

            if sep == "::":
                # Family definition
                # ie, Det :: NP/N
                families[ident] = (cat, var)
            else:
                semantics = None
                if include_semantics is True:
                    if semantics_str is None:
                        raise AssertionError(
                            line
                            + " must contain semantics because include_semantics is set to True"
                        )
                    else:
                        semantics = Expression.fromstring(
                            SEMANTICS_RE.match(semantics_str).groups()[0]
                        )
                # Word definition
                # ie, which => (N\N)/(S/NP)
                entries[ident].append(Token(ident, cat, semantics))
    return CCGLexicon(primitives[0], primitives, families, entries)

def levenshtein(x, y, normalisation=1.0, max_distance=20):
    x_len, y_len = len(x), len(y)

    if abs(x_len - y_len) > max_distance:
        return float(max_distance) / normalisation

    if x_len == 0:
        return float(y_len) / normalisation
    if y_len == 0:
        return float(x_len) / normalisation

    v0 = np.arange(y_len + 1, dtype=np.float64)
    v1 = np.empty(y_len + 1, dtype=np.float64)

    for i in range(x_len):
        # First column: cost of deleting all chars up to i
        v1[0] = i + 1

        for j in range(y_len):
            deletion_cost = v0[j + 1] + 1
            insertion_cost = v1[j] + 1
            substitution_cost = v0[j] + (x[i] != y[j])

            v1[j + 1] = min(deletion_cost, insertion_cost, substitution_cost)

        v0, v1 = v1, v0

        if np.min(v0) > max_distance:
            return float(max_distance) / normalisation

    return float(v0[y_len]) / normalisation

def clear_tensor_data(*tensors: Tuple[Optional[torch.Tensor], ...]) -> None:
    for t in tensors:
        if t is not None:
            # Workaround for double buffering in cpu offload
            if hasattr(t, "_do_not_clear"):
                continue
            if hasattr(t, "get_data_tensors"):
                if any(hasattr(tensor, "_do_not_clear") for tensor in t.get_data_tensors()):
                    continue

            if hasattr(t, "clear"):
                t.clear()
            else:
                t.data = _empty_tensor()
            del t

def render_with_simple_syntax_highlighting(
        self, content: str
    ) -> list:
        parts = []
        current_pos = 0

        # Pattern to match code blocks with optional language specifier
        code_block_pattern = re.compile(
            r"```(?P<lang>\w+)?\n(?P<code>.*?)\n```",
            re.DOTALL | re.MULTILINE,
        )

        for match in code_block_pattern.finditer(content):
            # Add markdown content before code block
            if match.start() > current_pos:
                markdown_content = content[
                    current_pos : match.start()
                ].strip()
                if markdown_content:
                    parts.append(("markdown", markdown_content))

            # Add code block
            lang = match.group("lang") or "text"
            code = match.group("code")
            parts.append(("code", (lang, code)))

            current_pos = match.end()

        # Add remaining markdown content
        if current_pos < len(content):
            remaining = content[current_pos:].strip()
            if remaining:
                parts.append(("markdown", remaining))

        # If no parts found, treat entire content as markdown
        if not parts:
            parts.append(("markdown", content))

        return parts

def delete_stack(cf_client, stack_name: str, wait: bool = True) -> None:
    try:
        # Validate stack is CLI-managed
        if not validate_stack_is_cli_managed(cf_client, stack_name):
            typer.echo(
                f"Error: Stack '{stack_name}' was not deployed by prefect-aws CLI",
                err=True,
            )
            raise typer.Exit(1)

        with Progress(
            SpinnerColumn(),
            TextColumn("[progress.description]{task.description}"),
            console=console,
        ) as progress:
            task = progress.add_task(f"[red]Deleting stack {stack_name}...")

            cf_client.delete_stack(StackName=stack_name)

            if wait:
                # Wait for deletion to complete
                waiter = cf_client.get_waiter("stack_delete_complete")
                progress.update(
                    task, description="[yellow]Waiting for deletion to complete..."
                )
                waiter.wait(
                    StackName=stack_name, WaiterConfig={"Delay": 10, "MaxAttempts": 120}
                )

                progress.update(
                    task, description=f"[green]Stack {stack_name} deleted successfully!"
                )
            else:
                progress.update(
                    task,
                    description=f"[green]Stack {stack_name} deletion initiated. Check status with: prefect-aws ecs-worker status {stack_name}",
                )

    except ClientError as e:
        if (code := e.response.get("Error", {}).get("Code")) == "ValidationError":
            typer.echo(f"Error: Stack '{stack_name}' not found", err=True)
        else:
            typer.echo(f"Error deleting stack: {code}", err=True)
        raise typer.Exit(1)

def find_distance(
    alpha_embedding: Union[NDArray[Any], List[float]],
    beta_embedding: Union[NDArray[Any], List[float]],
    distance_metric: str,
) -> Union[np.float64, NDArray[Any]]:
    # Convert inputs to numpy arrays if necessary
    alpha_embedding = np.asarray(alpha_embedding)
    beta_embedding = np.asarray(beta_embedding)

    # Ensure that both embeddings are either 1D or 2D
    if alpha_embedding.ndim != beta_embedding.ndim or alpha_embedding.ndim not in (1, 2):
        raise ValueError(
            f"Both embeddings must be either 1D or 2D, but received "
            f"alpha shape: {alpha_embedding.shape}, beta shape: {beta_embedding.shape}"
        )

    if distance_metric == "cosine":
        distance = find_cosine_distance(alpha_embedding, beta_embedding)
    elif distance_metric == "angular":
        distance = find_angular_distance(alpha_embedding, beta_embedding)
    elif distance_metric == "euclidean":
        distance = find_euclidean_distance(alpha_embedding, beta_embedding)
    elif distance_metric == "euclidean_l2":
        axis = None if alpha_embedding.ndim == 1 else 1
        normalized_alpha = l2_normalize(alpha_embedding, axis=axis)
        normalized_beta = l2_normalize(beta_embedding, axis=axis)
        distance = find_euclidean_distance(normalized_alpha, normalized_beta)
    else:
        raise ValueError("Invalid distance_metric passed - ", distance_metric)
    return np.round(distance, 6)

def transform_image(
        self,
        df: pd.DataFrame,
    ) -> Tuple[Dict[str, List[List[str]]], Dict[str, str]]:
        assert self._fit_called or self._fit_x_called, (
            "You will need to first call preprocessor.fit_x() before calling preprocessor.transform_image."
        )

        image_features = {}
        image_types = {}
        for col_name in self._image_feature_names:
            col_value = df[col_name]
            col_type = self._column_types[col_name]

            if col_type == ROIS:
                processed_data = df[col_name].tolist()
            elif col_type in [IMAGE_PATH, IMAGE]:
                processed_data = col_value.apply(lambda ele: str(ele).split(";")).tolist()
            elif col_type == IMAGE_BYTEARRAY:
                processed_data = col_value.apply(lambda ele: ele if isinstance(ele, list) else [ele]).tolist()
            elif col_type == IMAGE_BASE64_STR:
                processed_data = col_value.apply(
                    lambda ele: (
                        [base64.b64decode(e) for e in ele] if isinstance(ele, list) else [base64.b64decode(ele)]
                    )
                ).tolist()
            elif col_type == f"{IMAGE}_{IDENTIFIER}":
                processed_data = col_value
            else:
                raise ValueError(f"Unknown image type {col_type} for column {col_name}")

            image_features[col_name] = processed_data
            image_types[col_name] = self._column_types[col_name]

        return image_features, image_types

def classify_tool_id(
    tool_id: str,
) -> Literal[
    "builtin", "kiln_task", "mcp_remote", "mcp_local", "rag", "skill", "unknown"
]:
    if tool_id in [member.value for member in KilnBuiltInToolId]:
        return "builtin"
    elif tool_id.startswith(KILN_TASK_TOOL_ID_PREFIX):
        return "kiln_task"
    elif tool_id.startswith(MCP_REMOTE_TOOL_ID_PREFIX):
        return "mcp_remote"
    elif tool_id.startswith(MCP_LOCAL_TOOL_ID_PREFIX):
        return "mcp_local"
    elif tool_id.startswith(RAG_TOOL_ID_PREFIX):
        return "rag"
    elif tool_id.startswith(SKILL_TOOL_ID_PREFIX):
        return "skill"
    else:
        return "unknown"

def rotate(self, rotation_index: int, images: np.ndarray) -> np.ndarray | None:
        if rotation_index == 0:
            return images
        if rotation_index >= len(self._angles):
            return None

        if self._channels_first is None:
            self._channels_first = images.shape[1] in (1, 3, 4)
            logger.debug("Set channels_first to %s", self._channels_first)

        if self._channels_first:
            images = images.transpose(0, 2, 3, 1)

        retval = np.empty(images.shape, images.dtype)
        mat = self._matrices[rotation_index]
        size = (self._size, self._size)

        for i, img in enumerate(images):
            cv2.warpAffine(img,
                           mat,
                           size,
                           dst=retval[i],
                           borderMode=cv2.BORDER_REPLICATE)

        if self._channels_first:
            retval = retval.transpose(0, 3, 1, 2)

        return retval

def update(
        self,
        scope: dict[str, Any],
        meta: dict[MetaKey, Any] | None = None,
        preserve_pointers: bool = True,
    ) -> None:
        for var, lookup in self.contextual_defs():
            if lookup not in scope:
                raise CacheException(
                    "Failure while saving cached values. "
                    "Cache expected a reference to a "
                    f"variable that is not present ({lookup})."
                )
            self.defs[var] = scope[lookup]

        self.meta = {}
        if meta is not None:
            for metakey, metavalue in meta.items():
                if metakey not in get_args(MetaKey):
                    raise CacheException(f"Unexpected meta key: {metakey}")
                self.meta[metakey] = metavalue
        self.meta["version"] = MARIMO_CACHE_VERSION

        defs = {**globals(), **scope}
        for ref in self.stateful_refs:
            if ref not in defs:
                raise CacheException(
                    "Failure while saving cached values. "
                    "Cache expected a reference to a "
                    f"variable that is not present ({ref})."
                )
            value = defs[ref]
            if isinstance(value, SetFunctor):
                self.defs[ref] = value._state()
            elif isinstance(value, UIElement):
                self.defs[ref] = value.value
            else:
                raise CacheException(
                    "Failure while saving cached values. "
                    "Unexpected stateful reference type "
                    f"({type(value)}:{ref})."
                )

        # Convert objects to stubs in both defs and meta
        memo: dict[int, Any] = {}  # Track processed objects to handle cycles
        for key, value in self.defs.items():
            self.defs[key] = self._convert_to_stub_if_needed(
                value, memo, preserve_pointers
            )

        for key, value in self.meta.items():
            self.meta[key] = self._convert_to_stub_if_needed(
                value, memo, preserve_pointers
            )

def on_event(event, func, args=(),
             stop=None, check_stop_interval_s=1.0,
             daemon=True, silent=False):
    if event is None:
        raise ValueError('Event must not be None')

    if not isinstance(args, tuple):
        raise ValueError('args must be a tuple, not {}, for a single argument use (arg,)'
                         .format(type(args)))

    if stop is None:
        if not daemon:
            raise ValueError('Stop event must be given for non-daemon event thread')

        def fn():
            event.wait()
            func(*args)
    else:
        def fn():
            while not event.is_set() and not stop.is_set():
                event.wait(timeout=check_stop_interval_s)
            if not stop.is_set():
                func(*args)

    return in_thread(fn, daemon=daemon, silent=silent)

def request_download_link(
    app_id: str, app_version: str | None, in_url: str, out_url: str
) -> tuple[str, list[dict[str, str]] | None, str | None]:
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    body = {
        "app_id": app_id,  # send raw string of app_id
        "app_version": app_version,
        "flwr_version": flwr_version,
    }

    try:
        resp = requests.post(in_url, headers=headers, data=json.dumps(body), timeout=20)
    except requests.RequestException as e:
        raise ValueError(f"Unable to connect to Platform API: {e}") from e

    if resp.status_code == 404:
        # Expecting a JSON body with a "detail" field
        try:
            error_message = resp.json().get("detail")
        except ValueError:
            # JSON parsing failed
            raise ValueError(f"{app_id} not found in Platform API.") from None

        if isinstance(error_message, dict):
            available_app_versions = error_message.get("available_app_versions", [])
            available_versions_str = (
                ", ".join(map(str, available_app_versions))
                if available_app_versions
                else "None"
            )
            raise ValueError(
                f"{app_id}=={app_version} not found in Platform API. "
                f"Available app versions for {app_id}: {available_versions_str}"
            )

        raise ValueError(f"{app_id} not found in Platform API.")

    if not resp.ok:
        raise ValueError(
            f"Platform API request failed with status {resp.status_code}. "
            f"Details: {resp.text}"
        )

    data = resp.json()
    if out_url not in data:
        raise ValueError("Invalid response from Platform API")

    verifications = data["verifications"] if "verifications" in data else None
    note = data["note"] if "note" in data else None

    return str(data[out_url]), verifications, note

def init_weights(self, pretrained=None):
        def _init_weights(m):
            if isinstance(m, nn.Linear):
                trunc_normal_(m.weight, std=.02)
                if isinstance(m, nn.Linear) and m.bias is not None:
                    nn.init.constant_(m.bias, 0)
            elif isinstance(m, nn.LayerNorm):
                nn.init.constant_(m.bias, 0)
                nn.init.constant_(m.weight, 1.0)

        if pretrained:
            self.pretrained = pretrained
        if isinstance(self.pretrained, str):
            self.apply(_init_weights)
            print(f'load model from: {self.pretrained}')

            if self.pretrained2d:
                # Inflate 2D model into 3D model.
                # self.inflate_weights(logger)
                self.inflate_weights()
            else:
                # Directly load 3D model.
                torch.load_checkpoint(self, self.pretrained, strict=False)
        elif self.pretrained is None:
            self.apply(_init_weights)
        else:
            raise TypeError('pretrained must be a str or None')

def filter_tokens(self, bad_ids=None, good_ids=None):
        if bad_ids is not None:
            bad_ids = set(bad_ids)
            self.token2id = {token: tokenid for token, tokenid in self.token2id.items() if tokenid not in bad_ids}
            self.cfs = {tokenid: freq for tokenid, freq in self.cfs.items() if tokenid not in bad_ids}
            self.dfs = {tokenid: freq for tokenid, freq in self.dfs.items() if tokenid not in bad_ids}
        if good_ids is not None:
            good_ids = set(good_ids)
            self.token2id = {token: tokenid for token, tokenid in self.token2id.items() if tokenid in good_ids}
            self.cfs = {tokenid: freq for tokenid, freq in self.cfs.items() if tokenid in good_ids}
            self.dfs = {tokenid: freq for tokenid, freq in self.dfs.items() if tokenid in good_ids}
        self.compactify()

def track(self, resource):
        if isinstance(resource, layers.Layer) and not resource.built:
            raise ValueError(
                "The layer provided has not yet been built. "
                "It must be built before export."
            )

        # Note: with the TensorFlow backend, Layers and Models fall into both
        # the Layer case and the Trackable case. The Trackable case is needed
        # for preprocessing layers in order to track lookup tables.
        if isinstance(resource, tf.__internal__.tracking.Trackable):
            if not hasattr(self, "_tracked"):
                self._tracked = []
            self._tracked.append(resource)

        if isinstance(resource, layers.Layer):
            self._backend_track_layer(resource)
        elif not isinstance(resource, tf.__internal__.tracking.Trackable):
            raise ValueError(
                "Invalid resource type. Expected a Keras `Layer` or `Model` "
                "or a TensorFlow `Trackable` object. "
                f"Received object {resource} of type '{type(resource)}'. "
            )

def warp_image_tps(
    image: torch.Tensor,
    kernel_centers: torch.Tensor,
    kernel_weights: torch.Tensor,
    affine_weights: torch.Tensor,
    align_corners: bool = False,
    padding_mode: str = "zeros",
) -> torch.Tensor:
    if not isinstance(image, torch.Tensor):
        raise TypeError(f"Input image is not torch.Tensor. Got {type(image)}")

    if not isinstance(kernel_centers, torch.Tensor):
        raise TypeError(f"Input kernel_centers is not torch.Tensor. Got {type(kernel_centers)}")

    if not isinstance(kernel_weights, torch.Tensor):
        raise TypeError(f"Input kernel_weights is not torch.Tensor. Got {type(kernel_weights)}")

    if not isinstance(affine_weights, torch.Tensor):
        raise TypeError(f"Input affine_weights is not torch.Tensor. Got {type(affine_weights)}")

    if not len(image.shape) == 4:
        raise ValueError(f"Invalid shape for image, expected BxCxHxW. Got {image.shape}")

    if not len(kernel_centers.shape) == 3:
        raise ValueError(f"Invalid shape for kernel_centers, expected BxNx2. Got {kernel_centers.shape}")

    if not len(kernel_weights.shape) == 3:
        raise ValueError(f"Invalid shape for kernel_weights, expected BxNx2. Got {kernel_weights.shape}")

    if not len(affine_weights.shape) == 3:
        raise ValueError(f"Invalid shape for affine_weights, expected BxNx2. Got {affine_weights.shape}")

    batch_size, _, h, w = image.shape
    coords: torch.Tensor = create_meshgrid(h, w, device=image.device, dtype=image.dtype, normalized_coordinates=True)
    coords = coords.reshape(-1, 2).expand(batch_size, -1, -1)
    warped: torch.Tensor = warp_points_tps(coords, kernel_centers, kernel_weights, affine_weights)
    warped = warped.view(-1, h, w, 2)
    warped_image: torch.Tensor = nn.functional.grid_sample(
        image, warped, padding_mode=padding_mode, align_corners=align_corners
    )

    return warped_image

def adaptive_max_pool(inputs, output_size, data_format=None):
    inputs = convert_to_tensor(inputs)
    num_spatial_dims = inputs.ndim - 2

    data_format = backend.standardize_data_format(data_format)
    orig_format = data_format
    if data_format == "channels_last":
        inputs = _transpose_spatial_inputs(inputs)

    if isinstance(output_size, int):
        torch_output_size = (
            output_size
            if num_spatial_dims == 1
            else (output_size,) * num_spatial_dims
        )
    else:
        torch_output_size = standardize_tuple(
            output_size, num_spatial_dims, "output_size"
        )

    if get_device() == "meta":
        inputs = torch.empty(
            size=inputs.shape, dtype=inputs.dtype, device="cpu"
        )

    if num_spatial_dims == 1:
        res = tnn.adaptive_max_pool1d(inputs, output_size=torch_output_size)
    elif num_spatial_dims == 2:
        res = tnn.adaptive_max_pool2d(inputs, output_size=torch_output_size)
    elif num_spatial_dims == 3:
        res = tnn.adaptive_max_pool3d(inputs, output_size=torch_output_size)
    else:
        raise ValueError(
            "Inputs to adaptive max pooling must have ndim=3, 4 or 5, "
            f"Received input shape: {inputs.shape}."
        )

    outputs = res[0] if isinstance(res, tuple) else res

    if orig_format == "channels_last":
        outputs = _transpose_spatial_outputs(outputs)
    return outputs

def normalize_data(
    data: torch.Tensor,
    *,
    normalize_positions: int = -1,
    return_scaling: bool = False,
    clip: bool = True,
    std_only: bool = False,
    mean: torch.Tensor | None = None,
    std: torch.Tensor | None = None,
) -> torch.Tensor | tuple[torch.Tensor, tuple[torch.Tensor, torch.Tensor]]:
    assert (mean is None) == (std is None), (
        "Either both or none of mean and std must be given"
    )
    if mean is None:
        if normalize_positions is not None and normalize_positions > 0:
            mean = torch_nanmean(data[:normalize_positions], axis=0)  # type: ignore
            std = torch_nanstd(data[:normalize_positions], axis=0)
        else:
            mean = torch_nanmean(data, axis=0)  # type: ignore
            std = torch_nanstd(data, axis=0)

        # Inplace assignments with functional equivalents to support autograd.
        std = torch.where(std == 0, torch.ones_like(std), std)

        if len(data) == 1 or normalize_positions == 1:
            std = torch.ones_like(std)

        if std_only:
            mean = torch.zeros_like(mean)

    assert mean is not None
    assert std is not None

    # Add epsilon for numerical stability
    data = (data - mean) / (std + 1e-16)

    if clip:
        data = torch.clip(data, min=-100, max=100)

    if return_scaling:
        return data, (mean, std)
    return data

async def restart(
        self, server_ids: list[LspServerId] | None = None
    ) -> LspRestartResponse:
        config = self.config_reader.get_config()
        restarted: list[LspServerId] = []
        errors: dict[LspServerId, str] = {}

        servers_to_restart: list[LspServerId] = []
        if server_ids is None:
            # Restart all failed/non-responsive servers
            for server_id, server in self.servers.items():
                if not self._is_enabled(config, server_id):
                    continue
                if isinstance(server, BaseLspServer):
                    is_running = server.is_running()
                    if server.has_failed():
                        servers_to_restart.append(LspServerId(server_id))
                    elif is_running:
                        is_responsive, _ = await server.ping()
                        if not is_responsive:
                            servers_to_restart.append(LspServerId(server_id))
        else:
            servers_to_restart = server_ids

        for server_id in servers_to_restart:
            sid = LspServerId(server_id)
            if server_id not in self.servers:
                errors[sid] = f"Unknown server: {server_id}"
                continue

            server = self.servers[server_id]
            if not isinstance(server, BaseLspServer):
                errors[sid] = "Server does not support restart"
                continue

            try:
                alert = await server.restart_server()
                if alert:
                    errors[sid] = alert.description
                else:
                    restarted.append(sid)
            except Exception as e:
                errors[sid] = str(e)

        return LspRestartResponse(
            success=len(errors) == 0,
            restarted=restarted,
            errors=errors,
        )

def extract_dynamic_var(
    func_dict: dict[
        tvm.ir.GlobalVar,
        dict[
            tvm.ir.GlobalVar,
            list[tuple[list, int]],
        ],
    ],
) -> dict[tvm.ir.GlobalVar, dict[str, str]]:
    dym_var_dict: dict[tvm.ir.GlobalVar, dict[str, str]] = {}
    for gv in func_dict:  # pylint: disable=invalid-name,too-many-nested-blocks
        dym_var_dict[gv] = {}
        for functor in func_dict[gv]:
            for arg_list, _ in func_dict[gv][functor]:
                flattened_arg_list = []
                for arg in arg_list:
                    if isinstance(arg, relax.TupleStructInfo):
                        flattened_arg_list.extend(arg.fields)
                    else:
                        flattened_arg_list.append(arg)
                for arg in flattened_arg_list:
                    if isinstance(arg, relax.TensorStructInfo):
                        for val in arg.shape.values:
                            if isinstance(val, tvm.tirx.Var):
                                dym_var_dict[gv][str(val)] = val.dtype
                    elif isinstance(arg, relax.ShapeStructInfo):
                        for val in arg.values:
                            if isinstance(val, tvm.tirx.Var):
                                dym_var_dict[gv][str(val)] = val.dtype
                    else:
                        raise NotImplementedError
    return dym_var_dict

def combinations(self, expressions_list=None, dimension=2, exclude=None, **kwargs):
        if dimension is not None:
            expressions_list = list(itertools.combinations(self.get_column_names(), dimension))
            if exclude is not None:
                import six

                def excluded(expressions):
                    if callable(exclude):
                        return exclude(expressions)
                    elif isinstance(exclude, six.string_types):
                        return exclude in expressions
                    elif isinstance(exclude, (list, tuple)):
                        # $#expressions = set(expressions)
                        for e in exclude:
                            if isinstance(e, six.string_types):
                                if e in expressions:
                                    return True
                            elif isinstance(e, (list, tuple)):
                                if set(e).issubset(expressions):
                                    return True
                            else:
                                raise ValueError("elements of exclude should contain a string or a sequence of strings")
                    else:
                        raise ValueError("exclude should contain a string, a sequence of strings, or should be a callable")
                    return False
                # test if any of the elements of exclude are a subset of the expression
                expressions_list = [expr for expr in expressions_list if not excluded(expr)]
            logger.debug("expression list generated: %r", expressions_list)
        return expressions_list

def wandb(self, line: str, cell: str | None = None) -> None:
        global _current_cell_wandb_magic

        args = parse_argstring(self.wandb, line)
        path: str | None = args.path
        height: int = args.height

        if path:
            _display_by_wandb_path(path, height=height)
            displayed = True
        elif run := wandb_setup.singleton().most_recent_active_run:
            _display_wandb_run(run, height=height)
            displayed = True
        else:
            displayed = False

        # If this is being used as a line magic ("%wandb"), we are done.
        # When used as a cell magic ("%%wandb"), we must run the cell.
        if cell is None:
            return

        if not displayed:
            _current_cell_wandb_magic = _WandbCellMagicState(height=height)

        try:
            IPython.get_ipython().run_cell(cell)
        finally:
            _current_cell_wandb_magic = None

def simple_inline_formatting(cells):
    errors = []
    for cell in cells:
        if not isinstance(cell, MarkdownCell):
            continue

        for elem, entering in cell.ast.walker():
            if not entering:
                # only look at things once
                continue

            if not is_inline(elem):
                # not an inline formatting, so not relevant
                continue

            if all(
                is_text(child) or is_image(child) for child in direct_children(elem)
            ):
                # if all of the children are plain text or images, this is perfect!
                continue

            # an inline element that contains non-text elements, error!
            summary = syntax_summary(elem)
            if summary is None:
                summary = ""
            else:
                summary = f" (`` {summary} ``)"

            suggestions = ["removing the some of the formatting"]
            if is_link(elem):
                suggestions.append(
                    f"placing the link separately (like `<text> ([link](<url>))` or `<text> ([docs](<url>))`)"
                )

            errors.append(
                message_with_line(
                    cell,
                    f"Found some nested formatting within a {elem.t} element{summary}, which isn't supported in reStructuredText, as used by Sphinx and Read the Docs. Consider: {'; '.join(suggestions)}",
                    sourcepos=closest_parent_sourcepos(elem),
                )
            )

    if errors:
        raise FormattingError(errors)

def get(self, key, default=None):
    if key in self._hparam_types:
      # Ensure that default is compatible with the parameter type.
      if default is not None:
        param_type, is_param_list = self._hparam_types[key]
        type_str = 'list<%s>' % param_type if is_param_list else str(param_type)
        fail_msg = ("Hparam '%s' of type '%s' is incompatible with "
                    'default=%s' % (key, type_str, default))

        is_default_list = isinstance(default, list)
        if is_param_list != is_default_list:
          raise ValueError(fail_msg)

        try:
          if is_default_list:
            for value in default:
              _cast_to_type_if_compatible(key, param_type, value)
          else:
            _cast_to_type_if_compatible(key, param_type, default)
        except ValueError as e:
          raise ValueError('%s. %s' % (fail_msg, e))

      return getattr(self, key)

    return default

