def post_process_semantic_segmentation(self, outputs, target_sizes: List[Tuple] = None):
        logits = outputs.logits

        # Resize logits and compute semantic segmentation maps
        if target_sizes is not None:
            if len(logits) != len(target_sizes):
                raise ValueError(
                    "Make sure that you pass in as many target sizes as the batch dimension of the logits"
                )

            if is_torch_tensor(target_sizes):
                target_sizes = target_sizes.numpy()

            semantic_segmentation = []

            for idx in range(len(logits)):
                resized_logits = torch.nn.functional.interpolate(
                    logits[idx].unsqueeze(dim=0), size=target_sizes[idx], mode="bilinear", align_corners=False
                )
                semantic_map = resized_logits[0].argmax(dim=0)
                semantic_segmentation.append(semantic_map)
        else:
            semantic_segmentation = logits.argmax(dim=1)
            semantic_segmentation = [semantic_segmentation[i] for i in range(semantic_segmentation.shape[0])]

        return semantic_segmentation

def normalize_dataset_config_value(
    value: Optional[str],
    configs_dir: Optional[str] = None,
) -> Optional[str]:

    if not value:
        return value

    extra_roots: List[Path] = []
    try:
        dataset_plan_root = DatasetPlanStore().path.parent
        extra_roots.append(dataset_plan_root)
    except Exception:
        pass
    try:
        extra_roots.append(Path(get_config_directory()).expanduser())
    except Exception:
        pass
    try:
        extra_roots.append(Path(get_simpletuner_root()).expanduser())
    except Exception:
        pass

    try:
        resolved = resolve_config_path(value, config_dir=configs_dir, check_cwd_first=True)
    except Exception:
        resolved = None

    if resolved:
        return _normalise_dataset_path(Path(resolved), configs_dir=configs_dir, extra_roots=extra_roots)

    if configs_dir:
        try:
            config_basename = Path(configs_dir).expanduser().name
            parts = Path(value).parts
            if parts and parts[0] == config_basename and len(parts) > 1:
                trimmed = Path(*parts[1:])
                try:
                    resolved_trimmed = resolve_config_path(trimmed, config_dir=configs_dir, check_cwd_first=True)
                except Exception:
                    resolved_trimmed = None
                if resolved_trimmed:
                    return _normalise_dataset_path(Path(resolved_trimmed), configs_dir=configs_dir, extra_roots=extra_roots)
                return trimmed.as_posix()
        except Exception:
            pass

    return value

def read_from_labelstudio_json(path, data_columns, label_columns):
    if not os.path.exists(path):
        raise OSError("annotation file path not exists.")

    with open(path, mode="r") as fp:
        label_studio_json = json.load(fp)
        if len(label_studio_json) == 0:
            raise ValueError("ERROR: empty export file")

        if "annotations" in label_studio_json[0]:
            # the file is export through JSON
            # JSON file parsing is available to specify nested data
            annotation = pd.json_normalize(
                data=label_studio_json, record_path=["annotations", "result"], meta=["data"]
            )
            data = pd.DataFrame(annotation["data"].values.tolist())

            # annotation: labeling content
            # data: data content/url/...
            df = pd.DataFrame()

            columns = data.columns
            for col in data_columns:
                if col in columns:
                    df[col] = data[col]
                else:
                    print("skip '{}' for not in the export data columns".format(col))

            columns = annotation.columns
            for col in label_columns:
                if col in columns:
                    df[col] = annotation[col]
                else:
                    print("skip '{}' for not in the export label columns".format(col))

            return df

        else:
            # the file is export through JSON-MIN

            df = pd.DataFrame()
            annotation_table = pd.json_normalize(data=label_studio_json)

            for col in data_columns:
                if col in annotation_table:
                    df[col] = annotation_table[col]
                else:
                    print("skip '{}' for not in the export data columns".format(col))

            for col in label_columns:
                if col in annotation_table:
                    df[col] = annotation_table[col]
                else:
                    print("skip '{}' for not in the export label columns".format(col))

            return df

def autoscale_view(self, tight=None,
                       scalex=True, scaley=True, scalez=True):
        # This method looks at the rectangular volume (see above)
        # of data and decides how to scale the view portal to fit it.
        if tight is None:
            _tight = self._tight
            if not _tight:
                # if image data only just use the datalim
                for artist in self._children:
                    if isinstance(artist, mimage.AxesImage):
                        _tight = True
                    elif isinstance(artist, (mlines.Line2D, mpatches.Patch)):
                        _tight = False
                        break
        else:
            _tight = self._tight = bool(tight)

        if scalex and self.get_autoscalex_on():
            self._autoscale_axis(
                self.xaxis, *self.xy_dataLim.intervalx,
                self.xy_dataLim.minposx, self._xmargin,
                self.set_xbound, _tight)

        if scaley and self.get_autoscaley_on():
            self._autoscale_axis(
                self.yaxis, *self.xy_dataLim.intervaly,
                self.xy_dataLim.minposy, self._ymargin,
                self.set_ybound, _tight)

        if scalez and self.get_autoscalez_on():
            self._autoscale_axis(
                self.zaxis, *self.zz_dataLim.intervalx,
                self.zz_dataLim.minposx, self._zmargin,
                self.set_zbound, _tight)

def compute_scheduled_huber_c(self, timesteps: torch.Tensor) -> torch.Tensor:
        if not hasattr(self.config, "loss_type"):
            return torch.tensor(0.1)  # Default value

        if self.config.loss_type not in ["huber", "smooth_l1"]:
            return torch.tensor(0.1)  # Not used for other loss types

        huber_schedule = getattr(self.config, "huber_schedule", "constant")
        base_huber_c = getattr(self.config, "huber_c", 0.1)

        if huber_schedule == "constant":
            return torch.tensor(base_huber_c)

        elif huber_schedule == "exponential":
            # Exponential decay based on timestep
            num_train_timesteps = self.noise_schedule.config.num_train_timesteps
            alpha = -math.log(base_huber_c) / num_train_timesteps

            # Handle batch of timesteps
            # Vectorized computation of huber_c_values using PyTorch
            huber_c_values = torch.exp(-alpha * timesteps)

            return huber_c_values.to(timesteps.device)

        elif huber_schedule == "snr":
            # SNR-based scheduling
            if self.PREDICTION_TYPE == PredictionTypes.FLOW_MATCHING:
                sigmas = timesteps / 1000
                sigmas = ((1.0 - sigmas) / (sigmas + 0.0001)) ** 0.5
            else:
                snr = compute_snr(timesteps, self.noise_schedule)
                sigmas = (
                    (1.0 - self.noise_schedule.alphas_cumprod[timesteps]) / self.noise_schedule.alphas_cumprod[timesteps]
                ) ** 0.5
            huber_c = (1 - base_huber_c) / (1 + sigmas) ** 2 + base_huber_c
            return huber_c

        else:
            raise NotImplementedError(f"Unknown Huber loss schedule {huber_schedule}")

