def export(self, path, directed=False, encoding="utf-8"):
        import xml.etree.ElementTree as etree
        ns = "{http://graphml.graphdrawing.org/xmlns}"
        etree.register_namespace("", ns.strip("{}"))
        # Define type for node labels (string).
        # Define type for node edges (float).
        root = etree.Element(ns + "graphml")
        root.insert(0, etree.Element(ns + "key", **{
            "id": "node_label", "for": "node", "attr.name": "label", "attr.type": "string"
        }))
        root.insert(0, etree.Element(ns + "key", **{
            "id": "edge_weight", "for": "edge", "attr.name": "weight", "attr.type": "double"
        }))
        # Map Node.id => GraphML node id.
        m = {}
        g = etree.SubElement(root, ns + "graph", id="g", edgedefault=directed and "directed" or "undirected")
        # Export nodes.
        for i, n in enumerate(self.graph.nodes):
            m[n.id] = "node%s" % i
            x = etree.SubElement(g, ns + "node", id=m[n.id])
            x = etree.SubElement(x, ns + "data", key="node_label")
            if n.text and n.text.string != n.id:
                x.text = n.text.string
        # Export edges.
        for i, e in enumerate(self.graph.edges):
            x = etree.SubElement(g, ns + "edge", id="edge%s" % i, source=m[e.node1.id], target=m[e.node2.id])
            x = etree.SubElement(x, ns + "data", key="edge_weight")
            x.text = "%.3f" % e.weight
        # Export graph with pretty indented XML.
        # http://effbot.org/zone/element-lib.htm#prettyprint

        def indent(e, level=0):
            w = "\n" + level * "  "
            if len(e):
                if not e.text or not e.text.strip():
                    e.text = w + "  "
                if not e.tail or not e.tail.strip():
                    e.tail = w
                for e in e:
                    indent(e, level + 1)
                if not e.tail or not e.tail.strip():
                    e.tail = w
            else:
                if level and (not e.tail or not e.tail.strip()):
                    e.tail = w
        indent(root)
        tree = etree.ElementTree(root)
        tree.write(path, encoding=encoding)

def sequence_loss(self, y_pred, y_true):
        if self.verbose > 2: print ("my_sequence_loss y_pred=%s, y_true=%s" % (y_pred, y_true))
        logits = tf.unstack(y_pred, axis=1)		# list of [-1, num_decoder_synbols] elements
        targets = tf.unstack(y_true, axis=1)		# y_true has shape [-1, self.out_seq_len]; unpack to list of self.out_seq_len [-1] elements
        if self.verbose > 2:
            print ("my_sequence_loss logits=%s" % (logits,))
            print ("my_sequence_loss targets=%s" % (targets,))
        weights = [tf.ones_like(yp, dtype=tf.float32) for yp in targets]
        if self.verbose > 4: print ("my_sequence_loss weights=%s" % (weights,))
        sl = seq2seq.sequence_loss(logits, targets, weights)
        if self.verbose > 2: print ("my_sequence_loss return = %s" % sl)
        return sl

def publish(fig, event, *, verbose=None):
    if fig in _disabled_event_channels:
        return

    # Compile a list of all event channels that the event should be published
    # on.
    channels = [_get_event_channel(fig)]
    links = _event_channel_links.get(fig, None)
    if links is not None:
        for linked_fig, (include_events, exclude_events) in links.items():
            if (include_events is None or event.name in include_events) and (
                exclude_events is None or event.name not in exclude_events
            ):
                channels.append(_get_event_channel(linked_fig))

    # Publish the event by calling the registered callback functions.
    event.source = fig
    logger.debug(f"Publishing {event} on channel {fig}")
    for channel in channels:
        if event.name not in channel:
            channel[event.name] = set()
        for callback in channel[event.name]:
            callback(event=event)

def query(
        self,
        query: str,
        data: Sequence[dict[str, Any]] | dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        if self._engine is None:
            raise AttributeError(
                "LinkState is not initialized. Call initialize() first."
            )

        if data is None:
            data = {}

        # Clean up whitespace to make the logs nicer
        query = re.sub(r"\s+", " ", query.strip())

        try:
            # Wrap query in text() to enable SQLAlchemy named parameter syntax (:param).
            sql = text(query)

            def execute_and_fetch(session: Session) -> list[dict[str, Any]]:
                """Execute query and fetch results from the given session."""
                # Execute query (results live in database cursor).
                # There is no need to check for batch vs single execution;
                # SQLAlchemy handles both cases automatically.
                result = session.execute(sql, data)

                # Fetch results into Python memory before commit.
                # mappings() returns dict-like rows (works for SELECT and RETURNING).
                if result.returns_rows:  # type: ignore
                    return [dict(row) for row in result.mappings()]

                # For statements without RETURNING (INSERT/UPDATE/DELETE),
                # returns_rows is False, so we return empty list.
                return []

            # Not in a session context, create a new session context for this query
            with self.session() as session:
                return execute_and_fetch(session)

        except SQLAlchemyError as exc:
            log(ERROR, {"query": query, "data": data, "exception": exc})
            raise

def tags(self) -> list[int]:
        tags: list[int] = []

        # Ensure the barcodes have been read
        self.detect()

        for x in self.barcodes:
            tag_texts: str = x.value

            for raw in tag_texts.split(","):
                try:
                    tag_str: str | None = None
                    for pattern in self.settings.barcode_tag_mapping:
                        if safe_regex_match(pattern, raw, flags=regex_mod.IGNORECASE):
                            sub = self.settings.barcode_tag_mapping[pattern]
                            tag_str = (
                                safe_regex_sub(
                                    pattern,
                                    sub,
                                    raw,
                                    flags=regex_mod.IGNORECASE,
                                )
                                if sub
                                else raw
                            )
                            break

                    if tag_str:
                        tag, _ = Tag.objects.get_or_create(
                            name__iexact=tag_str,
                            defaults={"name": tag_str},
                        )

                        logger.debug(
                            f"Found Tag Barcode '{raw}', substituted "
                            f"to '{tag}' and mapped to "
                            f"tag #{tag.pk}.",
                        )
                        tags.append(tag.pk)

                except Exception as e:
                    logger.error(
                        f"Failed to find or create TAG '{raw}' because: {e}",
                    )

        return tags

def print_directory_tree(path, indent="", display_metadata=True):
    if display_metadata:

        def get_directory_size(path="."):
            total_size = 0

            for dirpath, _, filenames in os.walk(path):
                for filename in filenames:
                    file_path = os.path.join(dirpath, filename)
                    total_size += os.path.getsize(file_path)

            return total_size

        def format_size(size):
            # Convert size to a human-readable format
            for unit in ["B", "KB", "MB", "GB", "TB"]:
                if size < 1024.0:
                    return f"{size:.2f} {unit}"
                size /= 1024.0

        total_size_bytes = get_directory_size(path)
        formatted_size = format_size(total_size_bytes)
        logger.info(f"Directory size: {formatted_size}")

    if os.path.isdir(path):
        logger.info(indent + os.path.basename(path) + "/")
        indent += "    "
        for item in os.listdir(path):
            print_directory_tree(
                os.path.join(path, item), indent=indent, display_metadata=False
            )
    else:
        logger.info(indent + os.path.basename(path))

def print_csv_files_in_folder(folder_path):
    csv_files = []
    output_str = ""
    for dirpath, _, filenames in os.walk(folder_path):
        for file in filenames:
            if file.endswith(".csv"):
                csv_files.append(os.path.join(dirpath, file))
    for csv_file in csv_files:
        output_str += f"File: {csv_file}\n"
        with open(csv_file) as f:
            for i, line in enumerate(f):
                if i == 10:
                    break
                output_str += line.strip() + "\n"
        output_str += "\n"
    print(output_str)

def qkv_out_features(in_features: int,
                     shard_rank: int,
                     num_shards: int,
                     head_size: int,
                     n_heads_q: Optional[int] = None,
                     n_heads_kv: Optional[int] = None) -> int:
    if n_heads_kv is not None and n_heads_q is None:
        raise ValueError("n_heads_kv should not be passed without n_heads_q")

    mha_sharding = n_heads_kv is None or n_heads_q == n_heads_kv

    if n_heads_q is not None and in_features != head_size * n_heads_q:
        raise ValueError("in_features is not consistent with n_heads_q and head_size")

    if mha_sharding:
        endpoints = get_shard_endpoints(in_features, shard_rank, num_shards, granularity=head_size)
        return (endpoints[1] - endpoints[0]) * 3
    else:
        if n_heads_kv >= num_shards:
            if n_heads_kv % num_shards != 0:
                raise ValueError("The KV heads must be evenly distributed across the shards.")

            n_local_groups = n_heads_kv // num_shards
            group_size = n_heads_q // n_heads_kv

            return n_local_groups * head_size * (2 + group_size)
        else:
            if num_shards % n_heads_kv != 0:
                raise ValueError("A shared KV head must always partition across the same number of shards.")

            q_split_degree = num_shards // n_heads_kv
            q_split_rank = shard_rank % q_split_degree
            split_granularity = (n_heads_q // n_heads_kv) * head_size

            q_endpoints = get_shard_endpoints(split_granularity, q_split_rank, q_split_degree, granularity=head_size)

            return (q_endpoints[1] - q_endpoints[0]) + 2 * head_size

def handle_content_block_delta(
    event: ContentBlockDeltaEvent, state: dict[str, Any]
) -> tuple[dict[str, Any], ModelStreamEvent]:
    delta_content = event["delta"]

    typed_event: ModelStreamEvent = ModelStreamEvent({})

    if "toolUse" in delta_content:
        if "input" not in state["current_tool_use"]:
            state["current_tool_use"]["input"] = ""

        state["current_tool_use"]["input"] += delta_content["toolUse"]["input"]
        typed_event = ToolUseStreamEvent(delta_content, state["current_tool_use"])

    elif "text" in delta_content:
        state["text"] += delta_content["text"]
        typed_event = TextStreamEvent(text=delta_content["text"], delta=delta_content)

    elif "citation" in delta_content:
        if "citationsContent" not in state:
            state["citationsContent"] = []

        state["citationsContent"].append(delta_content["citation"])
        typed_event = CitationStreamEvent(delta=delta_content, citation=delta_content["citation"])

    elif "reasoningContent" in delta_content:
        if "text" in delta_content["reasoningContent"]:
            if "reasoningText" not in state:
                state["reasoningText"] = ""

            state["reasoningText"] += delta_content["reasoningContent"]["text"]
            typed_event = ReasoningTextStreamEvent(
                reasoning_text=delta_content["reasoningContent"]["text"],
                delta=delta_content,
            )

        elif "signature" in delta_content["reasoningContent"]:
            if "signature" not in state:
                state["signature"] = ""

            state["signature"] += delta_content["reasoningContent"]["signature"]
            typed_event = ReasoningSignatureStreamEvent(
                reasoning_signature=delta_content["reasoningContent"]["signature"],
                delta=delta_content,
            )

        elif redacted_content := delta_content["reasoningContent"].get("redactedContent"):
            state["redactedContent"] = state.get("redactedContent", b"") + redacted_content
            typed_event = ReasoningRedactedContentStreamEvent(redacted_content=redacted_content, delta=delta_content)

    return state, typed_event

def shape_equal(shape1, shape2, axis=None, allow_none=True):
    if len(shape1) != len(shape2):
        return False

    shape1 = list(shape1)
    shape2 = list(shape2)

    if axis is not None:
        if isinstance(axis, int):
            axis = [axis]
        for ax in axis:
            shape1[ax] = -1
            shape2[ax] = -1

    if allow_none:
        for i in range(len(shape1)):
            if shape1[i] is None:
                shape1[i] = shape2[i]
            if shape2[i] is None:
                shape2[i] = shape1[i]

    return shape1 == shape2

def try_inline(
    sch: s_tir.Schedule,
    blocks: list[SBlockInfo],
) -> list[SBlockInfo]:

    def _trial(func: Callable):
        for i, block in enumerate(blocks):
            try:
                func(block.block_rv)
            except:  # pylint: disable=bare-except
                continue
            return i
        return None

    while True:
        i = _trial(sch.compute_inline)
        if i is None:
            i = _trial(sch.reverse_compute_inline)
        if i is None:
            break
        blocks.pop(i)
    return blocks

def secure_aggregate(self, ctx: Context, ranks: typing.Optional[int] = None):
        if ranks is None:
            ranks = self.ranks
        aggregated_weight = 0.0
        has_weight = False

        if self._is_mock:
            aggregated = []
            for rank in ranks:
                arrays, weight = ctx.parties[rank].get(self._get_name(self._send_name))
                for i in range(len(arrays)):
                    if len(aggregated) <= i:
                        aggregated.append(arrays[i])
                    else:
                        aggregated[i] += arrays[i]
                if weight is not None:
                    has_weight = True
                    aggregated_weight += weight
            if has_weight:
                aggregated = [x / aggregated_weight for x in aggregated]
        else:
            mix_aggregator = MixAggregate()
            for rank in ranks:
                mix_arrays, weight = ctx.parties[rank].get(self._get_name(self._send_name))
                mix_aggregator.aggregate(mix_arrays)
                if weight is not None:
                    has_weight = True
                    aggregated_weight += weight
            if not has_weight:
                aggregated_weight = None
            aggregated = mix_aggregator.finalize(aggregated_weight)

        for rank in ranks:
            ctx.parties[rank].put(self._get_name(self._recv_name), aggregated)

        return aggregated

def subjunctive(sentence, classical=True, **kwargs):
    S = sentence
    if not (hasattr(S, "words") and hasattr(S, "parse_token")):
        raise TypeError("%s object is not a parsed Sentence" % repr(S.__class__.__name__))
    if question(S):
        return False
    for i, w in enumerate(S):
        b = False
        if w.type.startswith("VB"):
            if s(w).startswith("wish"):
                # "I wish I knew."
                return True
            if s(w) == "hope" and i > 0 and s(S[i - 1]) in ("i", "we"):
                # "I hope ..."
                return True
            if s(w) == "were" and i > 0 and (s(S[i - 1]) in ("i", "it", "he", "she") or S[i - 1].type == "NN"):
                # "It is as though she were here." => counterfactual.
                return True
            if s(w) in subjunctive1:
                # "I propose that you be on time."
                b = True
            elif s(w) == "is" and 0 < i < len(S) - 1 and s(S[i - 1]) == "it" \
             and s(S[i + 1]) in subjunctive2:
                # "It is important that you be there." => but you aren't (yet).
                b = True
            elif s(w) == "is" and 0 < i < len(S) - 3 and s(S[i - 1]) == "it" \
             and s(S[i + 2]) in ("good", "bad") and s(S[i + 3]) == "idea":
                # "It is a good idea that you be there."
                b = True
        if b:
            # With classical=False, "It is important that you are there." passes.
            # This is actually an informal error: it states a fact, not a wish.
            v = find(lambda w: w.type.startswith("VB"), S[i + 1:])
            if v and classical is True and v and v.type == "VB":
                return True
            if v and classical is False:
                return True
    return False

def get_cluster_history_provision_log_path(cluster_name: str) -> Optional[str]:
    engine = _db_manager.get_engine()
    with orm.Session(engine) as session:
        # Try current cluster first (fast path)
        cluster_hash = _get_hash_for_existing_cluster(cluster_name)
        if cluster_hash is not None:
            row = session.query(cluster_history_table).filter_by(
                cluster_hash=cluster_hash).first()
            if row is not None:
                return getattr(row, 'provision_log_path', None)

        # Fallback: search history by name and pick the latest by
        # usage_intervals
        rows = session.query(cluster_history_table).filter_by(
            name=cluster_name).all()
        if not rows:
            return None

        def latest_timestamp(usages_bin) -> int:
            try:
                intervals = pickle.loads(usages_bin)
                # intervals: List[Tuple[int, Optional[int]]]
                if not intervals:
                    return -1
                _, end = intervals[-1]
                return end if end is not None else int(time.time())
            except Exception:  # pylint: disable=broad-except
                return -1

        latest_row = max(rows,
                         key=lambda r: latest_timestamp(r.usage_intervals))
        return getattr(latest_row, 'provision_log_path', None)

def get_lycoris_config(self, environment_id: str) -> Optional[Dict]:
        environment_id = self._validate_config_name(environment_id)
        store = self._get_store("model")
        try:
            config, _ = store.load_config(environment_id)
        except FileNotFoundError:
            return None

        # Check for lycoris_config path in environment config
        lycoris_path_str = config.get("lycoris_config") or config.get("--lycoris_config")
        if not lycoris_path_str:
            return None

        # Resolve the lycoris config path
        lycoris_path = resolve_config_path(lycoris_path_str, config_dir=store.config_dir, check_cwd_first=True)
        if not lycoris_path or not lycoris_path.exists():
            return None

        # Load and return the lycoris config
        try:
            with lycoris_path.open("r", encoding="utf-8") as handle:
                return json.load(handle)
        except (json.JSONDecodeError, OSError):
            return None

def get_df(
        cls,
        size: int = 3,
        seed: int = 100,
        keep_first_n_cols: Optional[int] = None,
        keep_title_col: bool = False,
        keep_genre_col: bool = False,
    ) -> pd.DataFrame:
        if keep_first_n_cols is not None:
            if keep_first_n_cols < 1 or keep_first_n_cols > len(DEFAULT_HEADER):
                raise ValueError(
                    f"Invalid value for 'keep_first_n_cols': {keep_first_n_cols}. Valid range: [1-{len(DEFAULT_HEADER)}]"
                )

        df = cls.generate(size=size, seed=seed)

        if keep_first_n_cols is not None:
            cols_to_keep = list(DEFAULT_HEADER[:keep_first_n_cols])
            if keep_title_col and DEFAULT_TITLE_COL not in cols_to_keep:
                cols_to_keep.append(DEFAULT_TITLE_COL)
            if keep_genre_col and DEFAULT_GENRE_COL not in cols_to_keep:
                cols_to_keep.append(DEFAULT_GENRE_COL)
            df = df[cols_to_keep]
        else:
            cols_to_drop = []
            if not keep_title_col:
                cols_to_drop.append(DEFAULT_TITLE_COL)
            if not keep_genre_col:
                cols_to_drop.append(DEFAULT_GENRE_COL)
            if cols_to_drop:
                df = df.drop(columns=cols_to_drop)

        return df

def init(root_dir=os.curdir, no_scm=False, force=False, subdir=False):  # noqa: C901
    if no_scm and subdir:
        raise InvalidArgumentError(
            "Cannot initialize repo with `--no-scm` and `--subdir`"
        )

    root_dir = os.path.abspath(root_dir)
    dvc_dir = os.path.join(root_dir, Repo.DVC_DIR)

    try:
        scm = SCM(root_dir, search_parent_directories=subdir, no_scm=no_scm)
    except SCMError:
        raise InitError(  # noqa: B904
            f"{root_dir} is not tracked by any supported SCM tool (e.g. Git). "
            "Use `--no-scm` if you don't want to use any SCM or "
            "`--subdir` if initializing inside a subdirectory of a parent SCM "
            "repository."
        )

    if scm.is_ignored(dvc_dir):
        raise InitError(
            f"{dvc_dir} is ignored by your SCM tool. \n"
            "Make sure that it's tracked, "
            "for example, by adding '!.dvc' to .gitignore."
        )

    if os.path.isdir(dvc_dir):
        if not force:
            raise InitError(f"'{relpath(dvc_dir)}' exists. Use `-f` to force.")

        remove(dvc_dir)

    os.makedirs(dvc_dir, exist_ok=True)

    config = Config.init(dvc_dir)

    if no_scm:
        with config.edit() as conf:
            conf["core"]["no_scm"] = True

    dvcignore = init_dvcignore(root_dir)

    proj = Repo(root_dir)

    if os.path.isdir(proj.site_cache_dir):
        proj.close()
        try:
            remove(proj.site_cache_dir)
        except OSError:
            logger.debug("failed to remove %s", dvc_dir, exc_info=True)
        proj = Repo(root_dir)

    with proj.scm_context(autostage=True) as context:
        files = [config.files["repo"], dvcignore]
        ignore_file = context.scm.ignore_file
        if ignore_file:
            files.extend([os.path.join(dvc_dir, ignore_file)])
        proj.scm_context.track_file(files)

    logger.info("Initialized DVC repository.\n")
    if not no_scm:
        logger.info("You can now commit the changes to git.\n")
    return proj

def filter(self, **kwargs):
        from django.db.models import Q

        Statement = self.get_model('statement')

        kwargs.pop('page_size', 1000)
        order_by = kwargs.pop('order_by', None)
        tags = kwargs.pop('tags', [])
        exclude_text = kwargs.pop('exclude_text', None)
        exclude_text_words = kwargs.pop('exclude_text_words', [])
        persona_not_startswith = kwargs.pop('persona_not_startswith', None)
        search_text_contains = kwargs.pop('search_text_contains', None)
        search_in_response_to_contains = kwargs.pop('search_in_response_to_contains', None)

        # Convert a single sting into a list if only one tag is provided
        if isinstance(tags, str):
            tags = [tags]

        if tags:
            kwargs['tags__name__in'] = tags

        statements = Statement.objects.using(self.database).filter(**kwargs)

        if exclude_text:
            statements = statements.exclude(
                text__in=exclude_text
            )

        if exclude_text_words:
            or_query = [
                ~Q(text__icontains=word) for word in exclude_text_words
            ]

            statements = statements.filter(
                *or_query
            )

        if persona_not_startswith:
            statements = statements.exclude(
                persona__startswith='bot:'
            )

        if search_text_contains:
            or_query = Q()

            for word in search_text_contains.split(' '):
                or_query |= Q(search_text__contains=word)

            statements = statements.filter(
                or_query
            )

        if search_in_response_to_contains:
            or_query = Q()

            for word in search_in_response_to_contains.split(' '):
                or_query |= Q(search_in_response_to__contains=word)

            statements = statements.filter(
                or_query
            )

        if order_by:
            statements = statements.order_by(*order_by)

        for statement in statements.iterator():
            yield statement

def as_dataset(
        self,
        split: Optional[Union[str, Split, list[str], list[Split]]] = None,
        in_memory=False,
    ) -> Union[Dataset, DatasetDict]:
        if self._file_format is not None and self._file_format != "arrow":
            raise FileFormatError('Loading a dataset not written in the "arrow" format is not supported.')
        if is_remote_filesystem(self._fs):
            raise NotImplementedError(f"Loading a dataset cached in a {type(self._fs).__name__} is not supported.")
        if not os.path.exists(self._output_dir):
            raise FileNotFoundError(
                f"Dataset {self.dataset_name}: could not find data in {self._output_dir}. Please make sure to call "
                "builder.download_and_prepare(), or use "
                "datasets.load_dataset() before trying to access the Dataset object."
            )

        logger.debug(f"Constructing Dataset for split {split or ', '.join(self.info.splits)}, from {self._output_dir}")

        # By default, return all splits
        if split is None:
            split = {s: s for s in self.info.splits}

        # Create a dataset for each of the given splits
        datasets = map_nested(
            partial(
                self._build_single_dataset,
                in_memory=in_memory,
            ),
            split,
            map_tuple=True,
            disable_tqdm=True,
        )
        if isinstance(datasets, dict):
            datasets = DatasetDict(datasets)
        return datasets

def to_json(self, indent=None, separators=None, sort_keys=False):
    def remove_callables(x):
      """Omit callable elements from input with arbitrary nesting."""
      if isinstance(x, dict):
        return {k: remove_callables(v) for k, v in six.iteritems(x)
                if not callable(v)}
      elif isinstance(x, list):
        return [remove_callables(i) for i in x if not callable(i)]
      return x
    return json.dumps(
        remove_callables(self.values()),
        indent=indent,
        separators=separators,
        sort_keys=sort_keys)

def resolve_virtualenv_python_path(virtual_env_manager: Any) -> Optional[str]:
    if virtual_env_manager is None:
        return None
    venv_python = virtual_env_manager.get_python_path()
    if venv_python and os.path.exists(venv_python):
        return venv_python
    env_path = getattr(virtual_env_manager, "env_path", None)
    if env_path is None:
        return venv_python
    candidates: List[str] = []
    if os.name == "nt":
        candidates.append(os.path.join(str(env_path), "Scripts", "python.exe"))
    candidates.append(os.path.join(str(env_path), "bin", "python"))
    for candidate in candidates:
        if os.path.exists(candidate):
            return candidate
    return venv_python

def convert_state_dict(self, state_dict):
        if not next(iter(state_dict)).startswith('module.'):
            return state_dict  # abort if dict is not a DataParallel model_state
        new_state_dict = OrderedDict()

        split_index = 0
        for cur_key, cur_value in state_dict.items():
            if cur_key.startswith('module.model'):
                split_index = 13
            elif cur_key.startswith('module'):
                split_index = 7

            break

        for k, v in state_dict.items():
            name = k[split_index:]  # remove `module.`
            new_state_dict[name] = v
        return new_state_dict

def get_torch_modules(obj: T.Any,  # noqa[C901]  # pylint:disable=too-many-branches,too-many-return-statements
                      mod: str | None = None,
                      seen: set[int] | None = None,
                      results: list[torch.nn.Module] | None = None) -> list[torch.nn.Module]:
    seen = set() if seen is None else seen
    retval: list[torch.nn.Module] = [] if results is None else results
    mod = obj.__class__.__module__ if mod is None else mod

    obj_id = id(obj)
    if obj_id in seen:
        return retval
    seen.add(obj_id)

    if isinstance(obj, torch.nn.Module):
        logger.debug("Torch module found in %s(%s)", obj.__class__.__name__, type(obj))
        retval.append(obj)
        return retval

    if isinstance(obj, (str, bytes, int, float, bool, type(None))):
        # Fast exit on primitive
        return retval

    if hasattr(obj, "__class__") and obj.__class__.__module__ not in (mod, "builtins"):
        # Never leave the plugin module
        return retval

    if isinstance(obj, Mapping):
        # Mapping before iterable as a mapping is also an iterable
        for v in obj.values():
            retval = get_torch_modules(v, mod, seen=seen, results=retval)

    if isinstance(obj, Iterable):
        for v in obj:
            retval = get_torch_modules(v, mod, seen=seen, results=retval)

    if hasattr(obj, "__dict__"):
        for v in obj.__dict__.values():
            retval = get_torch_modules(v, mod, seen=seen, results=retval)
    return retval

def concat(self, other, inplace=False):
        if not self.__eq__(other):
            raise ValueError(
                "Entitysets must have the same dataframes, relationships"
                ", and column names",
            )

        if inplace:
            combined_es = self
        else:
            combined_es = copy.deepcopy(self)

        has_last_time_index = []
        for df in self.dataframes:
            self_df = df
            other_df = other[df.ww.name]
            combined_df = pd.concat([self_df, other_df])
            # If both DataFrames have made indexes, there will likely
            # be overlap in the index column, so we use the other values
            if self_df.ww.metadata.get("created_index") or other_df.ww.metadata.get(
                "created_index",
            ):
                columns = [
                    col
                    for col in combined_df.columns
                    if col != df.ww.index or col != df.ww.time_index
                ]
            else:
                columns = [df.ww.index]
            combined_df.drop_duplicates(columns, inplace=True)

            self_lti_col = df.ww.metadata.get("last_time_index")
            other_lti_col = other[df.ww.name].ww.metadata.get("last_time_index")
            if self_lti_col is not None or other_lti_col is not None:
                has_last_time_index.append(df.ww.name)

            combined_es.replace_dataframe(
                dataframe_name=df.ww.name,
                df=combined_df,
                recalculate_last_time_indexes=False,
                already_sorted=False,
            )

        if has_last_time_index:
            combined_es.add_last_time_indexes(updated_dataframes=has_last_time_index)

        combined_es.reset_data_description()

        return combined_es

def apply_gradient_clipping(
    model: Union[ComposerModel, torch.nn.Module],
    clipping_type: str,
    clipping_threshold: float,
    fsdp_enabled: bool,
):
    if fsdp_enabled:
        for module in model.modules():
            if isinstance(module, FullyShardedDataParallel) and module.check_is_root():
                if clipping_type == 'norm':
                    module.clip_grad_norm_(max_norm=clipping_threshold)
                elif clipping_type == 'value':
                    module.clip_grad_norm_(max_norm=clipping_threshold, norm_type=float('inf'))
                else:
                    raise ValueError(f"clipping type must be 'norm' or 'value' with FSDP not {clipping_type}")
    else:
        parameters = model.parameters()
        if clipping_type == 'adaptive':
            _apply_agc(parameters, clipping_threshold=clipping_threshold)
        elif clipping_type == 'norm':
            torch.nn.utils.clip_grad_norm_(parameters, max_norm=clipping_threshold)
        elif clipping_type == 'value':
            torch.nn.utils.clip_grad_value_(parameters, clip_value=clipping_threshold)
        else:
            raise ValueError(f"clipping_type must be 'adaptive', 'norm', or 'value' not {clipping_type} ")

def preprocess(self, img: np.ndarray) -> np.ndarray:
        if img is None or not hasattr(img, "shape"):
            raise ValueError("Expected img to be a valid numpy array.")

        out = img
        if getattr(self, "grayscale", True):
            # assume BGR input
            out = cv2.cvtColor(out, cv2.COLOR_BGR2GRAY)

        sc = getattr(self, "scale", None)
        if sc is None:
            return out

        if isinstance(sc, (int, float)):
            if sc <= 0:
                raise ValueError(f"scale must be > 0, got {sc}")
            out = cv2.resize(out, (0, 0), fx=float(sc), fy=float(sc), interpolation=cv2.INTER_LINEAR)
        else:
            # treat as explicit size (W, H)
            w, h = int(sc[0]), int(sc[1])
            if w <= 0 or h <= 0:
                raise ValueError(f"Invalid target size for scale: {(w, h)}")
            out = cv2.resize(out, (w, h), interpolation=cv2.INTER_LINEAR)

        return out

def set_component_default_value(self, widget, comp_type, options):
        widget.blockSignals(True)

        if comp_type == "QLineEdit":
            widget.clear()
        elif comp_type == "QRadioButton":
            if options:
                target_option = options[0]
                for i in range(widget.layout().count()):
                    item = widget.layout().itemAt(i)
                    if item and item.widget():
                        item.widget().setChecked(
                            item.widget().text() == target_option
                        )
        elif comp_type == "QComboBox":
            widget.setCurrentIndex(0)
        elif comp_type == "QCheckBox":
            for i in range(widget.layout().count()):
                item = widget.layout().itemAt(i)
                if item and item.widget():
                    item.widget().setChecked(False)

        widget.blockSignals(False)

def pop_first(self):
        for i, s in enumerate(self.sets):
            if s:
                if i in [Categories.N_EQ, Categories.ALL]:
                    for ex in s:
                        try:
                            if not ex[0]._exhausted:
                                s.remove(ex)
                                return (ex, i)
                        except AttributeError:
                            s.remove(ex)
                            return (ex, i)
                else:
                    return (s.pop(), i)
        return ((None, None), None)

def get_dot_string(
        self,
        function_name="main",
        prefix_id=0,
        highlight_debug_op_types=None,
        highlight_debug_op_names=None,
    ):
        if highlight_debug_op_types is None:
            highlight_debug_op_types = []
        if highlight_debug_op_names is None:
            highlight_debug_op_names = []

        dotstring = "digraph g {\n" + "\tcompound=true;\n"

        input_var_names = list(self.inputs.keys())
        output_var_names = [v.name for v in self.outputs]

        debug_op_types = []
        if len(highlight_debug_op_types) > 0:
            for op in self.operations:
                if op.op_type in highlight_debug_op_types:
                    debug_op_types.append(op.name)

        vis = DotVisitor()
        vis.highlight_nodes(input_var_names, "yellow").highlight_nodes(
            output_var_names, "goldenrod2"
        ).highlight_nodes(highlight_debug_op_names, "cyan").highlight_nodes(
            debug_op_types, "green"
        )

        vis.visit_all(self, nodename_prefix=str(prefix_id))
        res = vis.get_result("subgraph", "cluster_" + function_name.replace("/", "_"))
        dotstring += "\n".join("\t" + r for r in res.split("\n")) + "\n"
        dotstring += "}"
        return dotstring

def parent(self) -> 'ObjectRef':
    if self.native_obj is None:
      return ObjectRef(None)

    def bone_parent(
        armature: bpy.types.Object, bone: bpy.types.Bone
    ) -> 'ObjectRef':
      if bone.parent:
        # Parent of a child bone is its parent bone in the same armature
        assert isinstance(bone.parent, bpy.types.Bone)
        return ObjectRef.new_bone(armature, bone.parent)
      else:
        # Parent of the root bone is the armature.
        return ObjectRef.new_object(armature)

    def object_parent(obj: bpy.types.Object) -> 'ObjectRef':
      if obj.parent_bone:
        # The object is parented to an armature, and the .parent field must
        # contain a reference the armature.
        assert obj.parent and obj.parent.type == _ARMATURE
        _check_that_parent_bone_exists(obj)
        armature = obj.parent
        parent_bone = armature.data.bones[obj.parent_bone]
        return ObjectRef.new_bone(armature, parent_bone)
      elif obj.parent:
        # The object is parented to another object.
        return ObjectRef.new_object(obj.parent)
      else:
        # This is a root object
        return ObjectRef(None)

    if self.native_bone:
      return bone_parent(self.native_obj, self.native_bone)
    else:
      return object_parent(self.native_obj)

def check_dynamic(
    nm: str, readelf: str, cxxfilt: str, binary_file: Path, build_root: Optional[Path]
) -> int:
    symbols = get_cached_symbols(nm, build_root) if build_root is not None else {}

    dynamic_symbols = []
    binary_dyn_sym = get_binary_dynamic_symbols(readelf, binary_file)
    for symbol in binary_dyn_sym:
        if symbols is not None and symbol in symbols:
            dynamic_symbols.append(symbols[symbol])
        else:
            dynamic_symbols.append(Symbol(symbol, "", False, False, []))
    demangle_symbols(cxxfilt, dynamic_symbols)
    check_disallowed_symbols(cxxfilt, dynamic_symbols)

    dynamic_by_file = {}
    global_dynamic = []
    for symbol in dynamic_symbols:
        if len(symbol.sources) == 0:
            global_dynamic.append(symbol)
            continue

        for file in symbol.sources:
            if file not in dynamic_by_file:
                dynamic_by_file[file] = []
            dynamic_by_file[file].append(symbol)

    print("Executable relies on the following dynamic symbols:")
    for file, symbols in dynamic_by_file.items():
        print(f"{file} contains dynamic symbols:")
        for symbol in symbols:
            print(" *", symbol.demangled)
        print()

    if len(dynamic_by_file) > 0:
        return STATUS_ERROR

    return STATUS_OK

def get_column(self, index, copy=False):
        if isinstance(index, Variable) and index not in self.domain:
            if index.compute_value is None:
                raise ValueError(f"variable {index.name} is not in domain")
            return _compute_column(index.compute_value, self)

        mapper = None
        if not isinstance(index, Integral):
            if isinstance(index, DiscreteVariable) \
                    and index.values != self.domain[index].values:
                mapper = index.get_mapper_from(self.domain[index])
            index = self.domain.index(index)

        col = self._get_column_view(index)
        if sp.issparse(col):
            col = col.toarray().reshape(-1)
        if col.dtype == object and self.domain[index].is_primitive():
            col = col.astype(np.float64)
        if mapper is not None:
            col = mapper(col)
        if copy and col.base is not None:
            col = col.copy()
        return col

def get_mailbox(server, port, security) -> MailBox:
    if not settings.EMAIL_ALLOW_INTERNAL_HOSTS:
        for ip_str in resolve_hostname_ips(server):
            if not is_public_ip(ip_str):
                raise MailError(
                    f"Connection blocked: {server} resolves to a non-public address",
                )

    ssl_context = ssl.create_default_context()
    if settings.EMAIL_CERTIFICATE_FILE is not None:  # pragma: no cover
        ssl_context.load_verify_locations(cafile=settings.EMAIL_CERTIFICATE_FILE)

    if security == MailAccount.ImapSecurity.NONE:
        mailbox = MailBoxUnencrypted(server, port)
    elif security == MailAccount.ImapSecurity.STARTTLS:
        mailbox = MailBoxStartTls(server, port, ssl_context=ssl_context)
    elif security == MailAccount.ImapSecurity.SSL:
        mailbox = MailBox(server, port, ssl_context=ssl_context)
    else:
        raise NotImplementedError("Unknown IMAP security")  # pragma: no cover
    return mailbox

def report(self, value: float, step: int) -> None:
        if len(self.study.directions) > 1:
            raise NotImplementedError(
                "Trial.report is not supported for multi-objective optimization."
            )

        try:
            # For convenience, we allow users to report a value that can be cast to `float`.
            value = float(value)
        except (TypeError, ValueError):
            message = (
                f"The `value` argument is of type '{type(value)}' but supposed to be a float."
            )
            raise TypeError(message) from None

        try:
            step = int(step)
        except (TypeError, ValueError):
            message = f"The `step` argument is of type '{type(step)}' but supposed to be an int."
            raise TypeError(message) from None

        if step < 0:
            raise ValueError(f"The `step` argument is {step} but cannot be negative.")

        if step in self._cached_frozen_trial.intermediate_values:
            # Do nothing if already reported.
            optuna_warn(
                f"The reported value is ignored because this `step` {step} is already reported."
            )
            return

        self.storage.set_trial_intermediate_value(self._trial_id, step, value)
        self._cached_frozen_trial.intermediate_values[step] = value

def read(self, length: int = -1):
        if self.response is None:
            self._open_connection()

        retried_once = False
        while True:
            try:
                if self.response is None or self._stream_iterator is None:
                    return b""  # Already read the entire file
                out = self._read_from_stream(self._stream_iterator, length)
                self.loc += len(out)
                return out
            except Exception:
                if self.response is not None:
                    self.response.close()
                if retried_once:  # Already retried once, give up
                    raise
                # First failure, retry with range header
                self._open_connection()
                retried_once = True

def pool_tensor(
        self, tensor: torch.Tensor | tuple[torch.Tensor] | list[torch.Tensor], mode: str = "mean", stride: int = 2
    ) -> torch.Tensor:
        if tensor is None:
            return None

        # Do the pool recursively if tensor is a list or tuple of tensors.
        if isinstance(tensor, (tuple, list)):
            return type(tensor)(self.pool_tensor(tensor, mode=mode, stride=stride) for x in tensor)

        if self.config.separate_cls:
            suffix = tensor[:, :-1] if self.config.truncate_seq else tensor
            tensor = torch.cat([tensor[:, :1], suffix], dim=1)

        ndim = tensor.ndim
        if ndim == 2:
            tensor = tensor[:, None, :, None]
        elif ndim == 3:
            tensor = tensor[:, None, :, :]
        # Stride is applied on the second-to-last dimension.
        stride = (stride, 1)

        if mode == "mean":
            tensor = nn.functional.avg_pool2d(tensor, stride, stride=stride, ceil_mode=True)
        elif mode == "max":
            tensor = nn.functional.max_pool2d(tensor, stride, stride=stride, ceil_mode=True)
        elif mode == "min":
            tensor = -nn.functional.max_pool2d(-tensor, stride, stride=stride, ceil_mode=True)
        else:
            raise NotImplementedError("The supported modes are 'mean', 'max' and 'min'.")

        if ndim == 2:
            return tensor[:, 0, :, 0]
        elif ndim == 3:
            return tensor[:, 0]
        return tensor

def batched_grid_agent_execution(
    agents: List["AgentType"],
    tasks: List[str],
    max_workers: int = None,
) -> List[Any]:
    logger.info(
        f"Batch Grid Execution with {len(agents)} agents and number of tasks: {len(tasks)}"
    )

    if len(agents) != len(tasks):
        raise ValueError(
            "The number of agents must match the number of tasks."
        )

    # 90% of the available CPU cores
    max_workers = max_workers or int(os.cpu_count() * 0.9)

    results = [None] * len(agents)
    with concurrent.futures.ThreadPoolExecutor(
        max_workers=max_workers
    ) as executor:
        future_to_index = {
            executor.submit(run_single_agent, agent, task): idx
            for idx, (agent, task) in enumerate(zip(agents, tasks))
        }
        for future in concurrent.futures.as_completed(
            future_to_index
        ):
            idx = future_to_index[future]
            try:
                results[idx] = future.result()
            except Exception as e:
                results[idx] = e

    return results

def pad_or_trim(array, length: int = N_SAMPLES, *, axis: int = -1):
    if torch.is_tensor(array):
        if array.shape[axis] > length:
            array = array.index_select(
                dim=axis, index=torch.arange(length, device=array.device)
            )

        if array.shape[axis] < length:
            pad_widths = [(0, 0)] * array.ndim
            pad_widths[axis] = (0, length - array.shape[axis])
            array = F.pad(array, [pad for sizes in pad_widths[::-1] for pad in sizes])
    else:
        if array.shape[axis] > length:
            array = array.take(indices=range(length), axis=axis)

        if array.shape[axis] < length:
            pad_widths = [(0, 0)] * array.ndim
            pad_widths[axis] = (0, length - array.shape[axis])
            array = np.pad(array, pad_widths)

    return array

def remove_empty_columns_from_stockholm_msa(stockholm_msa: str) -> str:
    processed_lines = {}
    unprocessed_lines = {}
    for i, line in enumerate(stockholm_msa.splitlines()):
        if line.startswith('#=GC RF'):
            reference_annotation_i = i
            reference_annotation_line = line
            # Reached the end of this chunk of the alignment. Process chunk.
            _, _, first_alignment = line.rpartition(' ')
            mask = []
            for j in range(len(first_alignment)):
                for _, unprocessed_line in unprocessed_lines.items():
                    prefix, _, alignment = unprocessed_line.rpartition(' ')
                    if alignment[j] != '-':
                        mask.append(True)
                        break
                else:  # Every row contained a hyphen - empty column.
                    mask.append(False)
            # Add reference annotation for processing with mask.
            unprocessed_lines[
                reference_annotation_i] = reference_annotation_line

            if not any(
                    mask
            ):  # All columns were empty. Output empty lines for chunk.
                for line_index in unprocessed_lines:
                    processed_lines[line_index] = ''
            else:
                for line_index, unprocessed_line in unprocessed_lines.items():
                    prefix, _, alignment = unprocessed_line.rpartition(' ')
                    masked_alignment = ''.join(
                        itertools.compress(alignment, mask))
                    processed_lines[
                        line_index] = f'{prefix} {masked_alignment}'

            # Clear raw_alignments.
            unprocessed_lines = {}
        elif line.strip() and not line.startswith(('#', '//')):
            unprocessed_lines[i] = line
        else:
            processed_lines[i] = line
    return '\n'.join((processed_lines[i] for i in range(len(processed_lines))))

def wait_for_completion(self) -> None:
        if not isinstance(self._process, subprocess.Popen):
            raise RuntimeError(
                "Cannot use sync wait_for_completion with an async Process. "
                "Use await_for_completion instead."
            )

        self.logger.debug(f"Waiting for PID {self.pid} to complete.")

        output_threads: list[threading.Thread] = []

        # Each thread needs its own copied Context. Reusing the same Context for
        # both `Context.run(...)` calls raises `RuntimeError` once one thread enters it.
        if self._process.stdout is not None:
            stdout_context = copy_context()
            output_threads.append(
                threading.Thread(
                    target=stdout_context.run,
                    args=(
                        self._capture_output_sync,
                        self._process.stdout,
                        "stream output",
                        True,
                    ),
                    daemon=True,
                )
            )

        if self._process.stderr is not None:
            stderr_context = copy_context()
            output_threads.append(
                threading.Thread(
                    target=stderr_context.run,
                    args=(
                        self._capture_output_sync,
                        self._process.stderr,
                        "stderr",
                        False,
                    ),
                    daemon=True,
                )
            )

        for output_thread in output_threads:
            output_thread.start()

        for output_thread in output_threads:
            output_thread.join()

        self._process.wait()

        if self.return_code != 0:
            raise RuntimeError(
                f"PID {self.pid} failed with return code {self.return_code}."
            )
        self.logger.info(
            f"PID {self.pid} completed with return code {self.return_code}."
        )

def match(self, e):
        if not isinstance(e, Element):
            return False
        if self.tag not in (e.tag, "*"):
            return False
        if self.id not in ((e.id or "").lower(), "", None):
            return False
        if self.classes.issubset(set(map(lambda s: s.lower(), e.attr.get("class", "")))) is False:
            return False
        if "first-child" in self.pseudo and self._first_child(e.parent) != e:
            return False
        if any(x.startswith("contains") and not self._contains(e, x) for x in self.pseudo):
            return False # jQuery :contains("...") selector.
        for k, v in self.attributes.items():
            if k not in e.attrs or not (v is True or re.search(v, " ".join(e.attrs[k])) is not None):
                return False
        return True

def expand_file_patterns(patterns: List[str]) -> List[Path]:
    xml_files = []

    for pattern in patterns:
        pattern_path = Path(pattern)

        if pattern_path.is_dir():
            # If it's a directory, find all XML files in it
            found_files = list(pattern_path.rglob('*.xml'))
        elif pattern_path.is_file():
            # If it's a file, use it directly
            found_files = [pattern_path]
        else:
            # Try to expand as a glob pattern
            found_files = list(Path('.').glob(pattern))

        xml_files.extend(found_files)

    if not xml_files:
        print(f"Error: No XML files found matching the patterns: {patterns}", file=sys.stderr)
        sys.exit(1)

    print(f"Found XML files: {[str(f) for f in xml_files]}")
    return xml_files

def derive_block(self, field_indexes) -> Tuple["Block", bool, list]:
        src_field_indexes, dst_field_indexes = [], []
        field_indexes = sorted(field_indexes, key=lambda v: v[1])
        for src_field_index, dst_field_index in field_indexes:
            src_field_indexes.append(src_field_index)
            dst_field_indexes.append(dst_field_index)

        new_block = copy.deepcopy(self)
        new_block.field_indexes = dst_field_indexes
        # new_block = type(self)(dst_field_indexes)
        new_block.should_compress = self._should_compress

        # TODO: can be optimize as sub_field_indexes is ordered, but this is not a bottle neck
        changed = True
        if len(src_field_indexes) == len(self._field_indexes):
            is_monotonous = True
            for i in range(1, len(src_field_indexes)):
                if src_field_indexes[i] < src_field_indexes[i - 1]:
                    is_monotonous = False

            if is_monotonous:
                retrieval_indexes = [i for i in range(len(self._field_indexes))]
                changed = False
            else:
                retrieval_indexes = [bisect.bisect_left(self._field_indexes, col) for col in src_field_indexes]
        else:
            retrieval_indexes = [bisect.bisect_left(self._field_indexes, col) for col in src_field_indexes]

        return new_block, changed, retrieval_indexes

def sparse_top_k_categorical_accuracy(
    y_true, y_pred, k=5, from_sorted_ids=False
):
    reshape_matches = False
    y_pred = ops.convert_to_tensor(y_pred)
    y_true_dtype = y_pred.dtype if from_sorted_ids else "int32"
    y_true = ops.convert_to_tensor(y_true, dtype=y_true_dtype)
    y_true_rank = len(y_true.shape)
    y_pred_rank = len(y_pred.shape)
    y_true_org_shape = ops.shape(y_true)

    # Flatten y_pred to (batch_size, num_samples) and y_true to (num_samples,)
    if (y_true_rank is not None) and (y_pred_rank is not None):
        if y_pred_rank > 2:
            y_pred = ops.reshape(y_pred, [-1, y_pred.shape[-1]])
        if y_true_rank > 1:
            reshape_matches = True
            y_true = ops.reshape(y_true, [-1])

    if from_sorted_ids:
        # By slicing the first k items, we assume they are sorted by score.
        # Reduce with `any` to count multiple matches only once.
        matches = ops.any(
            ops.equal(ops.expand_dims(y_true, axis=1), y_pred[:, :k]), axis=1
        )
    else:
        matches = ops.in_top_k(y_true, y_pred, k=k)

    matches = ops.cast(matches, dtype=backend.floatx())

    # returned matches is expected to have same shape as y_true input
    if reshape_matches:
        matches = ops.reshape(matches, y_true_org_shape)

    return matches

def get_parameters(
        self,
        trainable_only: bool = True,
        operations_only: bool = False,
        **kwargs,  # pylint:disable=unused-argument
    ) -> list[TensorLike]:
        if trainable_only:
            params = []
            for p_idx in self.trainable_params:
                par_info = self.par_info[p_idx]
                if operations_only and isinstance(self[par_info["op_idx"]], MeasurementProcess):
                    continue

                op = par_info["op"]
                op_idx = par_info["p_idx"]
                params.append(op.data[op_idx])
            return params

        # If trainable_only=False, return all parameters
        # This is faster than the above and should be used when indexing `par_info` is not needed
        params = [d for op in self.operations for d in op.data]
        if operations_only:
            return params
        for m in self.measurements:
            if m.obs is not None:
                params.extend(m.obs.data)
        return params

def flag_engine_match_query_doc(prompt: str, query: str, doc: str) -> bool:
        try:
            a_start = prompt.index("A: ") + len("A: ")
        except ValueError:
            return False

        # from A: after exact match query
        a_slice = prompt[a_start : a_start + len(query)]
        if a_slice != query:
            return False

        doc_prompt = prompt[a_start + len(query) :]
        try:
            b_start = doc_prompt.index("B: ") + len("B: ")
        except ValueError:
            return False

        # from B: after exact match doc
        b_slice = doc_prompt[b_start : b_start + len(doc)]
        if b_slice != doc:
            return False
        sep = "\n"
        default_prompt = "Given a query A and a passage B, determine whether the passage contains an answer to the query by providing a prediction of either 'Yes' or 'No'."

        remain_prompt = doc_prompt[b_start + len(doc) :]
        if remain_prompt != f" {sep} {default_prompt}":
            return False

        return True

def pair_sequences(examples: List[NumpyDict]) -> Dict[int, np.ndarray]:
    num_examples = len(examples)

    all_chain_species_dict = []
    common_species = set()
    for chain_features in examples:
        msa_df = _make_msa_df(chain_features)
        species_dict = _create_species_dict(msa_df)
        all_chain_species_dict.append(species_dict)
        common_species.update(set(species_dict))

    common_species = sorted(common_species)
    common_species.remove(b'')  # Remove target sequence species.

    all_paired_msa_rows = [np.zeros(len(examples), int)]
    all_paired_msa_rows_dict = {k: [] for k in range(num_examples)}
    all_paired_msa_rows_dict[num_examples] = [np.zeros(len(examples), int)]

    for species in common_species:
        if not species:
            continue
        this_species_msa_dfs = []
        species_dfs_present = 0
        for species_dict in all_chain_species_dict:
            if species in species_dict:
                this_species_msa_dfs.append(species_dict[species])
                species_dfs_present += 1
            else:
                this_species_msa_dfs.append(None)

        # Skip species that are present in only one chain.
        if species_dfs_present <= 1:
            continue

        if np.any(
                np.array([
                    len(species_df) for species_df in this_species_msa_dfs
                    if isinstance(species_df, pd.DataFrame)
                ]) > 600):
            continue

        paired_msa_rows = _match_rows_by_sequence_similarity(
            this_species_msa_dfs)
        all_paired_msa_rows.extend(paired_msa_rows)
        all_paired_msa_rows_dict[species_dfs_present].extend(paired_msa_rows)
    all_paired_msa_rows_dict = {
        num_examples: np.array(paired_msa_rows)
        for num_examples, paired_msa_rows in all_paired_msa_rows_dict.items()
    }
    return all_paired_msa_rows_dict

def step_4(w):
    for suffix, rules in suffixes4:
        if w.endswith(suffix):
            for A in rules:
                if w.endswith(A):
                    return R2(w).endswith(A) and w[:-len(A)] or w
    if R2(w).endswith("ion") and w[:-3].endswith(("s", "t")):
        # Delete -ion if preceded by s or t.
        return w[:-3]
    return w

def render_changelog(prs, assigned, label_to_subsection=None, module_order=None):
    from dateutil import parser

    SECTION_ORDER = ["Enhancements", "Documentation", "Maintenance", "Fixes", "Other"]
    for title in SECTION_ORDER:
        if title not in assigned:
            continue

        pr_group = [prs[i] for i in assigned[title]]
        if not pr_group:
            continue
        print()
        print(title)
        print("~" * len(title))

        # Group PRs by module labels
        def group_prs_by_module(pr_group: list[dict]) -> dict[str, list[dict]]:
            """Group PRs by module labels and return a dictionary."""
            subsection_map: dict[str, list[dict]] = defaultdict(list)

            for pr in pr_group:
                labels = [label["name"] for label in pr["labels"]]
                added = False

                for label in labels:
                    if label in LABEL_TO_SUBSECTION:
                        subsection_map[LABEL_TO_SUBSECTION[label]].append(pr)
                        added = True
                if not added:
                    subsection_map["Other"].append(pr)

            return subsection_map

        def render_subsection(subsection_map: dict[str, list[dict]]) -> None:
            """Render subsections and their PRs in order."""
            # Render subsections
            for subsection_title in MODULE_ORDER:
                pr_list = subsection_map.get(subsection_title, [])
                if pr_list is None or not pr_list:
                    continue
                print()
                print(subsection_title)
                print("^" * len(subsection_title))
                print()
                for pr in sorted(pr_list, key=lambda x: parser.parse(x["merged_at"])):
                    render_row(pr)

        if title in ["Enhancements", "Fixes"]:
            subsection_map = group_prs_by_module(pr_group)
            render_subsection(subsection_map)
        else:
            for pr in sorted(pr_group, key=lambda x: parser.parse(x["merged_at"])):
                render_row(pr)

def run_multimethod(self):
        if self.share_mutable_buffers:
            arena: int = 0

            # Every spec that shares an fqn is the same tensor! So we give it the same id and offset
            # anywhere it appears.
            for fqn, specs_set in self.state.mutable_buffers.items():
                specs = list(specs_set)
                # If the same buffer appears in mutable and maybe mutable then we know it is in fact mutable.
                if fqn in self.state.maybe_mutable_buffers.keys():
                    specs.extend(self.state.maybe_mutable_buffers[fqn])
                for spec in specs:
                    # Assume a default memory planning placed all activations on 1, place shared state on 2.
                    spec.mem_id = 2
                    spec.realign(self.alignment)
                    # State is persistent, so the memory never overlaps.
                    spec.mem_offset = arena
                # They should all be the same size since they are the same tensor, so just bump off the first.
                arena += specs[0].allocated_memory

            for graph_module in self.state.graph_modules:
                if len(graph_module.meta["non_const_buffer_sizes"]) != 2:
                    raise ValueError(
                        "Cannot share mutable state if not using default memory ids"
                    )
                graph_module.meta["non_const_buffer_sizes"].append(arena)

def clone_tensors_for_torch_save(item, device=torch.device('cpu')):
    if torch.is_tensor(item):
        if type(device) is str:
            device = torch.device(device)
        if device == item.device:
            return item.detach().clone()
        else:
            return item.detach().to(device)
    elif isinstance(item, list):
        return [clone_tensors_for_torch_save(v, device) for v in item]
    elif isinstance(item, tuple):
        return tuple([clone_tensors_for_torch_save(v, device) for v in item])
    elif isinstance(item, dict):
        return type(item)({k: clone_tensors_for_torch_save(v, device) for k, v in item.items()})
    else:
        return item

def from_dict(cls, obj: dict) -> DatasourceRawSamplesData:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return DatasourceRawSamplesData.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in DatasourceRawSamplesData) in the input: " + str(obj))

        _obj = DatasourceRawSamplesData.parse_obj({
            "has_more": obj.get("hasMore"),
            "cursor": obj.get("cursor"),
            "data": [DatasourceRawSamplesDataRow.from_dict(_item) for _item in obj.get("data")] if obj.get("data") is not None else None
        })
        return _obj

def debug_one(self, x: dict, decimals: int = 5) -> str:
        x = self._ohe_cat_features(x)

        def fmt_float(x: float) -> str:
            return "{: ,.{prec}f}".format(x, prec=decimals)

        names = (
            self._interaction_names(x)  # latents
            + list(map(str, x.keys()))  # weights
            + ["Intercept"]  # intercept
        )

        values = list(
            map(
                fmt_float,
                [
                    self._interaction_val(x, combination)
                    for combination in self._interaction_combination_keys(x)
                ]  # latents
                + list(x.values())  # weights
                + [1],  # intercept
            )
        )

        weights = list(
            map(
                fmt_float,
                [
                    self._interaction_coefficient(combination)
                    for combination in self._interaction_combination_keys(x)
                ]  # latents
                + [self.weights.get(i, 0) for i in x]  # weights
                + [self.intercept],  # intercept
            )
        )
        contributions = (
            [
                self._interaction_coefficient(combination) * self._interaction_val(x, combination)
                for combination in self._interaction_combination_keys(x)
            ]  # latents
            + [xi * self.weights.get(i, 0) for i, xi in x.items()]  # weights
            + [self.intercept]  # intercept
        )
        order = list(reversed(np.argsort(contributions)))
        contributions_str = list(map(fmt_float, contributions))

        table = utils.pretty.print_table(
            headers=["Name", "Value", "Weight", "Contribution"],
            columns=[names, values, weights, contributions_str],
            order=order,
        )

        return table

def parse_fontconfig_pattern(pattern):
    parser = _make_fontconfig_parser()
    try:
        parse = parser.parse_string(pattern)
    except ParseException as err:
        # explain becomes a plain method on pyparsing 3 (err.explain(0)).
        raise ValueError("\n" + ParseException.explain(err, 0)) from None
    parser.reset_cache()
    props = {}
    if "families" in parse:
        props["family"] = [*map(_family_unescape, parse["families"])]
    if "sizes" in parse:
        props["size"] = [*parse["sizes"]]
    for prop in parse.get("properties", []):
        if len(prop) == 1:
            prop = _CONSTANTS[prop[0]]
        k, *v = prop
        props.setdefault(k, []).extend(map(_value_unescape, v))
    return props

def replace_with_eetq_linear(model, modules_to_not_convert: list[str] | None = None, pre_quantized=False):
    from .hub_kernels import get_kernel

    global eetq_kernels_hub
    eetq_kernels_hub = get_kernel("kernels-community/quantization-eetq")

    has_been_replaced = False
    # we need this to correctly materialize the weights during quantization
    module_kwargs = {} if pre_quantized else {"dtype": None}
    for module_name, module in model.named_modules():
        if not should_convert_module(module_name, modules_to_not_convert):
            continue
        with torch.device("meta"):
            if isinstance(module, nn.Linear):
                new_module = EetqLinear(
                    module.in_features, module.out_features, bias=module.bias is not None, **module_kwargs
                )
                model.set_submodule(module_name, new_module)
                has_been_replaced = True

    if not has_been_replaced:
        logger.warning(
            "You are loading your model using eetq but no linear modules were found in your model."
            " Please double check your model architecture, or submit an issue on github if you think this is"
            " a bug."
        )

    return model

def status(self) -> CellStatusType | None:
        if self._impl is None:
            return CellStatusType.stale if self._cell.code else None
        # Transient runtime state takes priority.
        rs = self._impl.runtime_state
        if rs == "queued":
            return CellStatusType.queued
        if rs == "running":
            return CellStatusType.running
        if rs == "disabled-transitively":
            return CellStatusType.disabled
        # Stale overrides last run result.
        if self._is_stale():
            return CellStatusType.stale
        # Fall back to last execution result.
        rr = self._impl.run_result_status
        if rr is None:
            # Registered in the graph but never executed.
            return CellStatusType.stale if self._cell.code else None
        if rr == "success":
            return CellStatusType.idle
        return CellStatusType(rr)

def postprocess_token_labels(
    labels, input_mask, label_map=None, remove_trailing_word_pieces=False, trailing_token_mask=None
):
    if label_map:
        reversed_label_map = {v: k for k, v in label_map.items()}
        labels_org = [[reversed_label_map[l_i] for l_i in l] for l in labels]
    else:
        labels_org = labels

    labels_org_no_padding = [
        [label for label, mask in zip(label_list, mask_list) if mask == 1]
        for label_list, mask_list in zip(labels_org, input_mask)
    ]

    if remove_trailing_word_pieces and trailing_token_mask:
        # Remove the padded values in trailing_token_mask first
        token_mask_no_padding = [
            [token for token, padding in zip(t_mask, p_mask) if padding == 1]
            for t_mask, p_mask in zip(trailing_token_mask, input_mask)
        ]

        labels_no_trailing_pieces = [
            [label for label, mask in zip(label_list, mask_list) if mask]
            for label_list, mask_list in zip(labels_org_no_padding, token_mask_no_padding)
        ]
        return labels_no_trailing_pieces
    else:
        return labels_org_no_padding

def create_test_instances_and_names(cls, parameter_set="default"):
        if "parameter_set" in inspect.getfullargspec(cls.get_test_params).args:
            param_list = cls.get_test_params(parameter_set=parameter_set)
        else:
            param_list = cls.get_test_params()

        objs = []
        if not isinstance(param_list, dict | list):
            raise RuntimeError(
                f"Error in {cls.__name__}.get_test_params, "
                "return must be param dict for class, or list thereof"
            )
        if isinstance(param_list, dict):
            param_list = [param_list]
        for params in param_list:
            if not isinstance(params, dict):
                raise RuntimeError(
                    f"Error in {cls.__name__}.get_test_params, "
                    "return must be param dict for class, or list thereof"
                )
            objs += [cls.get_model_cls()(**params)]

        num_instances = len(param_list)
        if num_instances > 1:
            names = [cls.__name__ + "-" + str(i) for i in range(num_instances)]
        else:
            names = [cls.__name__]

        return objs, names

def parse_dotenv(filepath: str) -> dict[str, str | None]:
    env_dict: dict[str, str | None] = {}
    try:
        with open(filepath, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                # Skip empty lines and comments
                if not line or line.startswith("#"):
                    continue

                # Handle lines without equals sign
                if "=" not in line:
                    continue

                key, value = line.split("=", 1)
                key = key.strip()
                if not key:
                    continue

                value = _drop_quotes(value.strip())
                env_dict[key] = value
    except FileNotFoundError:
        # Handle case where .env file doesn't exist
        pass
    return env_dict

def log_outputs(
        self,
        run: wandb.Run,
        func_name: str,
        result: Any,
        bound_args: dict[str, Any],
    ) -> None:
        if result is not None and not run._is_finished:
            if _is_namedtuple(result):
                run.log({f"{func_name}.{k}": v for k, v in zip(result._fields, result)})
            else:
                run.log({func_name: result})

        for name in self._artifacts_out:
            if name in bound_args:
                try:
                    _log_artifact(run, name, bound_args[name], use=False)
                except Exception as e:
                    wandb.termwarn(f"Failed to log output artifact '{name}': {e}")

def parse_and_validate_blocks(self):
        blocks = self.pipeline.blocks_by_uuid.values()
        source_blocks = []
        sink_blocks = []
        transformer_blocks = []
        for b in blocks:
            if b.type == BlockType.DATA_LOADER:
                # Data loader block should be root block
                if len(b.upstream_blocks or []) > 0:
                    raise Exception(f'Data loader {b.uuid} can\'t have upstream blocks.')
                if len(b.downstream_blocks or []) < 1:
                    raise Exception(f'Data loader {b.uuid} must have at least one transformer or'
                                    ' data exporter as the downstream block.')
                source_blocks.append(b)
            if b.type == BlockType.DATA_EXPORTER:
                # Data exporter block should be leaf block
                if len(b.downstream_blocks or []) > 0:
                    raise Exception(f'Data expoter {b.uuid} can\'t have downstream blocks.')
                if len(b.upstream_blocks or []) != 1:
                    raise Exception(f'Data exporter {b.uuid} must have a transformer or data'
                                    ' loader as the upstream block.')
                sink_blocks.append(b)
            if b.type == BlockType.TRANSFORMER:
                # Each transformer block can only have one upstream block
                if len(b.upstream_blocks or []) != 1:
                    raise Exception(f'Transformer {b.uuid} should (only) have one upstream block.')
                transformer_blocks.append(b)

        if len(source_blocks) != 1:
            raise Exception('Please provide (only) one data loader block as the source.')

        self.source_block = source_blocks[0]
        self.sink_blocks = sink_blocks

def from_train(tokens):
        # Find the set of all attested labels.
        labels = {label for (tok, label) in tokens}

        # Determine the types of all features.
        features = {}
        for tok, label in tokens:
            for fname, fval in tok.items():
                if issubclass(type(fval), bool):
                    ftype = "{True, False}"
                elif issubclass(type(fval), (int, float, bool)):
                    ftype = "NUMERIC"
                elif issubclass(type(fval), str):
                    ftype = "STRING"
                elif fval is None:
                    continue  # can't tell the type.
                else:
                    raise ValueError("Unsupported value type %r" % ftype)

                if features.get(fname, ftype) != ftype:
                    raise ValueError("Inconsistent type for %s" % fname)
                features[fname] = ftype
        features = sorted(features.items())

        return ARFF_Formatter(labels, features)

def cyclic_schedule(
    skip_first: int = 0,
    wait: int = 0,
    warmup: int = 1,
    active: int = 4,
    repeat: int = 1,
) -> Callable[[State], ProfilerAction]:

    def schedule(state: State):
        # do wait, then warump, then active, up to repeat times per cycle
        cycle_len = wait + warmup + active
        batch_idx = int(state.timestamp.batch_in_epoch)
        if state.profiler is not None:
            skip_first_after_resumption = skip_first + state.profiler.resumption_batch_idx
        else:
            skip_first_after_resumption = skip_first
        if batch_idx < skip_first_after_resumption:
            return ProfilerAction.SKIP
        if repeat != 0 and batch_idx >= cycle_len * repeat + skip_first_after_resumption:
            # exhausted the repeat
            return ProfilerAction.SKIP
        position_in_cycle = (batch_idx - skip_first_after_resumption) % cycle_len
        if position_in_cycle < wait:
            return ProfilerAction.SKIP
        if position_in_cycle < wait + warmup:
            return ProfilerAction.WARMUP
        is_last_batch_in_epoch = state.dataloader_len is not None and state.timestamp.batch_in_epoch == state.dataloader_len - 1
        if position_in_cycle == cycle_len - 1 or is_last_batch_in_epoch:
            return ProfilerAction.ACTIVE_AND_SAVE
        return ProfilerAction.ACTIVE

    return schedule

def fetch_responses(self) -> None:
        prefetch_log_debug("Launching retrieval thread.")
        iterator_fn = _resolve_random_iterator()
        try:
            while True:
                if self.queue.qsize() < self.queue.maxsize:
                    prefetch_log_debug(f"Queue size: {self.queue.qsize()}. Fetching more data.")
                    try:
                        item = iterator_fn(self.step, self.datasets)
                    except ValueError:
                        prefetch_log_debug("No datasets available during prefetch; stopping fetch thread.")
                        self._keep_running = False
                        break
                    except StopIteration:
                        prefetch_log_debug("Dataloader iterator signaled completion.")
                        break
                    except Exception as exc:
                        logger.debug(f"BatchFetcher encountered exception: {exc}")
                        break
                    self.queue.put(item)
                    if self.queue.qsize() >= self.queue.maxsize:
                        prefetch_log_debug("Completed fetching data. Queue is full.")
                        if threading.current_thread() is threading.main_thread():
                            break
                        continue
                else:
                    if threading.current_thread() is threading.main_thread():
                        break
                    time.sleep(0.5)
                if not self.keep_running:
                    break
        finally:
            if DEFAULT_KEEP_RUNNING_PROPERTY is not None:
                type(self).keep_running = DEFAULT_KEEP_RUNNING_PROPERTY
            prefetch_log_debug("Exiting retrieval thread.")

def from_dict(cls, obj: dict) -> PredictionTaskSchemaSimple:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return PredictionTaskSchemaSimple.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in PredictionTaskSchemaSimple) in the input: " + str(obj))

        _obj = PredictionTaskSchemaSimple.parse_obj({
            "name": obj.get("name"),
            "type": obj.get("type"),
            "categories": [PredictionTaskSchemaCategory.from_dict(_item) for _item in obj.get("categories")] if obj.get("categories") is not None else None
        })
        return _obj

def get_params_override(self) -> Dict[str, Any]:
        params = self.model_dump()
        if params.get("verify_cert_path"):
            # to ensure that verify doesn't re-overwrite verify_cert_path
            params.pop("verify")

        params_override = {}
        for key, value in params.items():
            if value is None:
                continue
            elif key == "config":
                params_override[key] = Config(**value)
                # botocore UNSIGNED is an instance while actual signers can
                # be fetched as strings
                if params_override[key].signature_version == "unsigned":
                    params_override[key].signature_version = UNSIGNED
            elif key == "verify_cert_path":
                params_override["verify"] = value
            elif key == "verify":
                if value is not None:
                    params_override[key] = value
            else:
                params_override[key] = value
        return params_override

def serve(
        self,
        app_type: Literal["fastapi", "starlette"] = "starlette",
        *,
        host: str | None = None,
        port: int | None = None,
        **kwargs: Any,
    ) -> None:
        # Update host/port if overridden, and recalculate URLs if http_url wasn't explicitly set
        if host is not None:
            self.host = host
        if port is not None:
            self.port = port

        if host is not None or port is not None:
            # Only update the URL if it wasn't explicitly set via http_url parameter
            # (i.e., if the URL was auto-generated from host/port in __init__)
            if not self._http_url_explicit:
                self.public_base_url = f"http://{self.host}:{self.port}"
                self.http_url = f"{self.public_base_url}/"

        try:
            logger.info("Starting Strands A2A server...")
            if app_type == "fastapi":
                uvicorn.run(self.to_fastapi_app(), host=self.host, port=self.port, **kwargs)
            else:
                uvicorn.run(self.to_starlette_app(), host=self.host, port=self.port, **kwargs)
        except KeyboardInterrupt:
            logger.warning("Strands A2A server shutdown requested (KeyboardInterrupt).")
        except Exception:
            logger.exception("Strands A2A server encountered exception.")
        finally:
            logger.info("Strands A2A server has shutdown.")

def cli_endpoint(fn):
    @wraps(fn)
    def wrapper(catch_exception=True, **kwargs):
        if os.environ.get("PLOOMBER_DEBUG"):
            catch_exception = False

        if catch_exception:
            try:
                fn(**kwargs)
            # these already color output
            except (DAGBuildError, DAGRenderError) as e:
                error = str(e)
                color = False
            # for base exceptions (we raise this), we display the message
            # in red (no traceback since it's irrelevant for the user)
            except BaseException as e:
                click.secho(e.get_message(), file=sys.stderr, fg="red")
                sys.exit(1)
            # this means it's an unknown error (either a bug in ploomber or
            # an error in the user's code). we display the full traceback,
            # but still hide irrelevant tracebacks (i.e. if a nested exception
            # is raised where some of the exceptions are TaskBuildError)
            except Exception as e:
                error = _format.exception(e)
                color = True
            else:
                error = None

            if error:
                if color:
                    tw = TerminalWriter(file=sys.stderr)
                    tw._write_source(error.splitlines())
                else:
                    print(error, file=sys.stderr)

                sys.exit(1)
        else:
            if os.environ.get("PLOOMBER_POST_MORTEM"):
                try:
                    fn(**kwargs)
                except Exception:
                    _, _, tb = sys.exc_info()
                    pdb.post_mortem(tb)
            else:
                fn(**kwargs)

    return wrapper

def stem(self, word):
        word = word.lower()

        if word in self.stopwords:
            return word

        r1 = self._r1_scandinavian(word, self.__vowels)

        # STEP 1
        for suffix in self.__step1_suffixes:
            if r1.endswith(suffix):
                if suffix == "s":
                    if word[-2] in self.__s_ending:
                        word = word[:-1]
                        r1 = r1[:-1]
                else:
                    word = word[: -len(suffix)]
                    r1 = r1[: -len(suffix)]
                break

        # STEP 2
        for suffix in self.__step2_suffixes:
            if r1.endswith(suffix):
                word = word[:-1]
                r1 = r1[:-1]
                break

        # STEP 3
        for suffix in self.__step3_suffixes:
            if r1.endswith(suffix):
                if suffix in ("els", "lig", "ig"):
                    word = word[: -len(suffix)]
                elif suffix in ("fullt", "l\xf6st"):
                    word = word[:-1]
                break

        return word

def list_checkpoints(self, include_metadata: bool = True) -> List[Dict[str, any]]:
        checkpoints = []

        if not os.path.exists(self.output_dir):
            return checkpoints

        dirs = os.listdir(self.output_dir)
        checkpoint_dirs = [d for d in dirs if d.startswith("checkpoint-") and not d.endswith("-tmp")]

        for checkpoint_dir in checkpoint_dirs:
            checkpoint_path = os.path.join(self.output_dir, checkpoint_dir)
            info = {
                "name": checkpoint_dir,
                "path": checkpoint_path,
                "step": self._extract_step_from_name(checkpoint_dir),
            }

            if include_metadata:
                metadata = self._load_checkpoint_metadata(checkpoint_path)
                if metadata:
                    info.update(metadata)

            checkpoints.append(info)

        # Sort by step number (descending)
        checkpoints.sort(key=lambda x: x.get("step", 0), reverse=True)
        return checkpoints

def print_debug(id2token, u, s, topics, num_words=10, num_neg=None):
    if num_neg is None:
        # by default, print half as many salient negative words as positive
        num_neg = num_words / 2

    logger.info('computing word-topic salience for %i topics', len(topics))
    topics, result = set(topics), {}
    # TODO speed up by block computation
    for uvecno, uvec in enumerate(u):
        uvec = np.abs(np.asarray(uvec).flatten())
        udiff = uvec / np.sqrt(np.sum(np.dot(uvec, uvec)))
        for topic in topics:
            result.setdefault(topic, []).append((udiff[topic], uvecno))

    logger.debug("printing %i+%i salient words", num_words, num_neg)
    for topic in sorted(result.keys()):
        weights = sorted(result[topic], key=lambda x: -abs(x[0]))
        _, most = weights[0]
        if u[most, topic] < 0.0:  # the most significant word has a negative sign => flip sign of u[most]
            normalize = -1.0
        else:
            normalize = 1.0

        # order features according to salience; ignore near-zero entries in u
        pos, neg = [], []
        for weight, uvecno in weights:
            if normalize * u[uvecno, topic] > 0.0001:
                pos.append('%s(%.3f)' % (id2token[uvecno], u[uvecno, topic]))
                if len(pos) >= num_words:
                    break

        for weight, uvecno in weights:
            if normalize * u[uvecno, topic] < -0.0001:
                neg.append('%s(%.3f)' % (id2token[uvecno], u[uvecno, topic]))
                if len(neg) >= num_neg:
                    break

        logger.info('topic #%s(%.3f): %s, ..., %s', topic, s[topic], ', '.join(pos), ', '.join(neg))

def get_ner_prf(examples: Iterable[Example], **kwargs) -> Dict[str, Any]:
    score_per_type = defaultdict(PRFScore)
    for eg in examples:
        if not eg.y.has_annotation("ENT_IOB"):
            continue
        golds = {(e.label_, e.start, e.end) for e in eg.y.ents}
        align_x2y = eg.alignment.x2y
        for pred_ent in eg.x.ents:
            if pred_ent.label_ not in score_per_type:
                score_per_type[pred_ent.label_] = PRFScore()
            indices = align_x2y[pred_ent.start : pred_ent.end]
            if len(indices):
                g_span = eg.y[indices[0] : indices[-1] + 1]
                # Check we aren't missing annotation on this span. If so,
                # our prediction is neither right nor wrong, we just
                # ignore it.
                if all(token.ent_iob != 0 for token in g_span):
                    key = (pred_ent.label_, indices[0], indices[-1] + 1)
                    if key in golds:
                        score_per_type[pred_ent.label_].tp += 1
                        golds.remove(key)
                    else:
                        score_per_type[pred_ent.label_].fp += 1
        for label, start, end in golds:
            score_per_type[label].fn += 1
    totals = PRFScore()
    for prf in score_per_type.values():
        totals += prf
    if len(totals) > 0:
        return {
            "ents_p": totals.precision,
            "ents_r": totals.recall,
            "ents_f": totals.fscore,
            "ents_per_type": {k: v.to_dict() for k, v in score_per_type.items()},
        }
    else:
        return {
            "ents_p": None,
            "ents_r": None,
            "ents_f": None,
            "ents_per_type": None,
        }

def is_local_module(spec: Any) -> bool:
    if spec is None or spec.origin is None:
        return True  # Assume local if we can't determine

    if "site-packages" in spec.origin:
        return False

    module_path = pathlib.Path(spec.origin).resolve()
    site_packages_dirs = _getsitepackages()
    if not site_packages_dirs:
        # Ultimate fallback: use string matching
        return "site-packages" not in module_path.parts

    # Check if module is in any site-packages directory
    for site_dir in site_packages_dirs:
        try:
            if module_path.is_relative_to(site_dir):
                return False  # Module is in site-packages
        except (OSError, ValueError):
            # Handle path resolution issues
            continue

    return True  # Module is local

def drawdown_conf(
    changes: NDArray[np.float64],
    returns: NDArray[np.float64],
    n: int,
    n_boot: int,
) -> DrawdownMetrics:
    if n <= 0:
        raise ValueError("Bootstrap sample size must be greater than 0.")
    if n_boot <= 0:
        raise ValueError("Number of boostrap samples must be greater than 0.")
    n_changes = len(changes)
    if n_changes != len(returns):
        raise ValueError("Param changes length does not match returns length.")
    if n_changes <= n:
        n = n_changes
        n_boot = 1
    changes_sample = np.zeros(n)
    returns_sample = np.zeros(n)
    boot_dd = np.zeros(n_boot)
    boot_dd_pct = np.zeros(n_boot)
    for i in range(n_boot):
        for j in range(n):
            k = np.random.choice(n_changes)
            changes_sample[j] = changes[k]
            returns_sample[j] = returns[k]
        boot_dd[i] = max_drawdown(changes_sample)
        boot_dd_pct[i], _ = max_drawdown_percent(returns_sample)
    return DrawdownMetrics(_dd_confs(boot_dd), _dd_confs(boot_dd_pct))

def to_ms_dataset(cls,
                      ds_instance: Union[Dataset, DatasetDict, ExternalDataset,
                                         NativeIterableDataset,
                                         IterableDataset, IterableDatasetDict],
                      target: str = None) -> Union[dict, 'MsDataset']:
        if isinstance(ds_instance, Dataset):
            return cls(ds_instance, target)
        elif isinstance(ds_instance, DatasetDict):
            if len(ds_instance.keys()) == 1:
                return cls(next(iter(ds_instance.values())), target)
            return {k: cls(v, target) for k, v in ds_instance.items()}
        elif isinstance(ds_instance, ExternalDataset):
            return cls(ds_instance)
        elif isinstance(ds_instance, NativeIterableDataset):
            return cls(ds_instance)
        elif isinstance(ds_instance, IterableDataset):
            return cls(ds_instance)
        elif isinstance(ds_instance, IterableDatasetDict):
            if len(ds_instance.keys()) == 1:
                return cls(next(iter(ds_instance.values())), target)
            return {k: cls(v, target) for k, v in ds_instance.items()}
        else:
            raise TypeError(
                f'"ds_instance" must be a Dataset or DatasetDict, but got {type(ds_instance)}'
            )

def load_lookups(lang: str, tables: List[str], strict: bool = True) -> "Lookups":
    # TODO: import spacy_lookups_data instead of going via entry points here?
    lookups = Lookups()
    if lang not in registry.lookups:
        if strict and len(tables) > 0:
            raise ValueError(Errors.E955.format(table=", ".join(tables), lang=lang))
        return lookups
    data = registry.lookups.get(lang)
    for table in tables:
        if table not in data:
            if strict:
                raise ValueError(Errors.E955.format(table=table, lang=lang))
            language_data = {}  # type: ignore[var-annotated]
        else:
            language_data = load_language_data(data[table])  # type: ignore[assignment]
        lookups.add_table(table, language_data)
    return lookups

def format_kwargs_for_fingerprint(
    func: Callable,
    args: tuple,
    kwargs: dict[str, Any],
    use_kwargs: Optional[list[str]] = None,
    ignore_kwargs: Optional[list[str]] = None,
    randomized_function: bool = False,
) -> dict[str, Any]:
    kwargs_for_fingerprint = kwargs.copy()
    if args:
        params = [p.name for p in inspect.signature(func).parameters.values() if p != p.VAR_KEYWORD]
        args = args[1:]  # assume the first argument is the dataset
        params = params[1:]
        kwargs_for_fingerprint.update(zip(params, args))
    else:
        del kwargs_for_fingerprint[
            next(iter(inspect.signature(func).parameters))
        ]  # assume the first key is the dataset

    # keep the right kwargs to be hashed to generate the fingerprint

    if use_kwargs:
        kwargs_for_fingerprint = {k: v for k, v in kwargs_for_fingerprint.items() if k in use_kwargs}
    if ignore_kwargs:
        kwargs_for_fingerprint = {k: v for k, v in kwargs_for_fingerprint.items() if k not in ignore_kwargs}
    if randomized_function:  # randomized functions have `seed` and `generator` parameters
        if kwargs_for_fingerprint.get("seed") is None and kwargs_for_fingerprint.get("generator") is None:
            _, seed, pos, *_ = np.random.get_state()
            seed = seed[pos] if pos < 624 else seed[0]
            kwargs_for_fingerprint["generator"] = np.random.default_rng(seed)

    # remove kwargs that are the default values

    default_values = {
        p.name: p.default for p in inspect.signature(func).parameters.values() if p.default != inspect._empty
    }
    for default_varname, default_value in default_values.items():
        if default_varname in kwargs_for_fingerprint and kwargs_for_fingerprint[default_varname] == default_value:
            kwargs_for_fingerprint.pop(default_varname)
    return kwargs_for_fingerprint

def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        inputs_embeds: torch.LongTensor | None = None,
        cache_params: Cache | None = None,
        use_cache: bool | None = None,
        output_hidden_states: bool | None = None,
        return_dict: bool | None = None,
        attention_mask: torch.LongTensor | None = None,
        **kwargs,
    ) -> tuple | MambaOutput:
        output_hidden_states = (
            output_hidden_states if output_hidden_states is not None else self.config.output_hidden_states
        )
        use_cache = use_cache if use_cache is not None else (self.config.use_cache if not self.training else False)
        return_dict = return_dict if return_dict is not None else self.config.return_dict

        if (input_ids is None) ^ (inputs_embeds is not None):  # ^ is python for xor
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.embeddings(input_ids)

        if self.gradient_checkpointing and self.training and use_cache:
            use_cache = False

        if use_cache and cache_params is None:
            cache_params = DynamicCache(config=self.config)

        hidden_states = inputs_embeds
        all_hidden_states = () if output_hidden_states else None
        for mixer_block in self.layers:
            hidden_states = mixer_block(
                hidden_states,
                cache_params=cache_params,
                attention_mask=attention_mask,
            )

            if output_hidden_states:
                all_hidden_states = all_hidden_states + (hidden_states,)

        hidden_states = self.norm_f(hidden_states)

        if output_hidden_states:
            all_hidden_states = all_hidden_states + (hidden_states,)

        if not return_dict:
            return tuple(v for v in [hidden_states, cache_params, all_hidden_states] if v is not None)

        return MambaOutput(
            last_hidden_state=hidden_states,
            cache_params=cache_params if use_cache else None,
            hidden_states=all_hidden_states,
        )

def convert_nkjp(nkjp_path, output_dir):
    # Load XML NKJP
    print("Reading data from %s" % nkjp_path)
    if os.path.isfile(nkjp_path) and (nkjp_path.endswith(".tar.gz") or nkjp_path.endswith(".tgz")):
        with tempfile.TemporaryDirectory() as nkjp_dir:
            print("Temporarily extracting %s to %s" % (nkjp_path, nkjp_dir))
            with tarfile.open(nkjp_path, "r:gz") as tar_in:
                tar_in.extractall(nkjp_dir)

            subfolder_to_entities = load_xml_nkjp(nkjp_dir)
    elif os.path.isdir(nkjp_path):
        subfolder_to_entities = load_xml_nkjp(nkjp_path)
    else:
        raise FileNotFoundError("Cannot find either unpacked dataset or gzipped file")
    converted = []
    for subfolder_name, pars in subfolder_to_entities.items():
        for par_id, par in pars.items():
            paragraph_identifier = f"{subfolder_name}|{par_id}"
            par_tokens = []
            for _, sent in par.items():
                tokens = sent.values()
                srt = sorted(tokens, key=lambda tok:tok["i"])
                for token in srt:
                    _ = token.pop("i")
                    _ = token.pop("seg_id")
                    par_tokens.append(token)
            par_tokens[0]["paragraph_id"] = paragraph_identifier
            converted.append(par_tokens)

    split = split_dataset(converted)

    for split_name, split in split.items():
        if split:
            with open(os.path.join(output_dir, f"pl_nkjp.{split_name}.json"), "w", encoding="utf-8") as f:
                json.dump(split, f, ensure_ascii=False, indent=2)

def pad(
        self,
        images: list[np.ndarray],
        pad_size: SizeDict = None,
        fill_value: int | None = 0,
        padding_mode: str | None = "constant",
        return_mask: bool = False,
        **kwargs,
    ) -> tuple[list[np.ndarray], list[np.ndarray]] | list[np.ndarray]:
        if pad_size is not None:
            if not (pad_size.height and pad_size.width):
                raise ValueError(f"Pad size must contain 'height' and 'width' keys only. Got pad_size={pad_size}.")
            target_height, target_width = pad_size.height, pad_size.width
        else:
            target_height, target_width = get_max_height_width(images)

        processed_images = []
        processed_masks = []

        for image in images:
            height, width = get_image_size(image, channel_dim=ChannelDimension.FIRST)
            padding_height = target_height - height
            padding_width = target_width - width

            if padding_height < 0 or padding_width < 0:
                raise ValueError(
                    f"Padding dimensions are negative. Please make sure that the `pad_size` is larger than the "
                    f"image size. Got pad_size=({target_height}, {target_width}), image_size=({height}, {width})."
                )

            if height != target_height or width != target_width:
                # Pad format: ((before_1, after_1), (before_2, after_2), ...)
                # For CHW format: ((0, 0), (0, padding_height), (0, padding_width))
                pad_width = ((0, 0), (0, padding_height), (0, padding_width))
                if padding_mode == "constant":
                    image = np.pad(image, pad_width, mode="constant", constant_values=fill_value)
                else:
                    image = np.pad(image, pad_width, mode=padding_mode)

            processed_images.append(image)

            if return_mask:
                mask = np.zeros((target_height, target_width), dtype=np.int64)
                mask[:height, :width] = 1
                processed_masks.append(mask)

        if return_mask:
            return processed_images, processed_masks
        return processed_images

def extract_completion_tokens(response_payload: Mapping[str, Any]) -> list[int] | None:
    choices = response_payload.get("choices") or []
    if not choices:
        return None
    choice0 = choices[0]
    output_ids = choice0.get("output_token_ids")
    if isinstance(output_ids, list):
        return [int(tok) for tok in output_ids]
    logprobs = choice0.get("logprobs")
    if isinstance(logprobs, Mapping):
        token_ids = logprobs.get("token_ids")
        if isinstance(token_ids, list):
            return [int(tok) for tok in token_ids]
    return None

def store_embeddings(
    data_points: Union[list[DT], Dataset],
    storage_mode: EmbeddingStorageMode,
    dynamic_embeddings: Optional[list[str]] = None,
) -> None:
    if isinstance(data_points, Dataset):
        data_points = list(_iter_dataset(data_points))

    # if storage mode option 'none' delete everything
    if storage_mode == "none":
        dynamic_embeddings = None

    # if dynamic embedding keys not passed, identify them automatically
    elif dynamic_embeddings is None:
        dynamic_embeddings = identify_dynamic_embeddings(data_points)

    # always delete dynamic embeddings
    for data_point in data_points:
        data_point.clear_embeddings(dynamic_embeddings)

    # if storage mode is "cpu", send everything to CPU (pin to memory if we train on GPU)
    if storage_mode == "cpu":
        pin_memory = str(flair.device) != "cpu"
        for data_point in data_points:
            data_point.to("cpu", pin_memory=pin_memory)

def load(self, fname: Optional[str] = None, *args, **kwargs) -> None:
        if fname is not None:
            self.load_path = fname

        if self.load_path:
            log.debug(f"Load path {self.load_path} is given.")
            if isinstance(self.load_path, Path) and not self.load_path.parent.is_dir():
                raise ConfigError("Provided load path is incorrect!")

            weights_path = Path(self.load_path.resolve())
            weights_path = weights_path.with_suffix(f".pth.tar")
            if weights_path.exists():
                log.debug(f"Load path {weights_path} exists.")
                log.debug(f"Initializing `{self.__class__.__name__}` from saved.")

                # now load the weights, optimizer from saved
                log.debug(f"Loading weights from {weights_path}.")
                checkpoint = torch.load(weights_path, map_location=self.device)
                model_state = checkpoint["model_state_dict"]
                optimizer_state = checkpoint["optimizer_state_dict"]
                # load a multi-gpu model on a single device
                if all([key.startswith("module.") for key in list(model_state.keys())]):
                    model_state = {key.replace("module.", "", 1): val for key, val in model_state.items()}

                if self.is_data_parallel:
                    self.model.module.load_state_dict(model_state)
                else:
                    self.model.load_state_dict(model_state)
                try:  # TODO: remove this try-except after hf models deep update
                    self.optimizer.load_state_dict(optimizer_state)
                except ValueError as e:
                    log.error(f'Failed to load optimizer state due to {repr(e)}')
                self.epochs_done = checkpoint.get("epochs_done", 0)
            else:
                log.warning(f"Init from scratch. Load path {weights_path} does not exist.")
        else:
            log.warning(f"Init from scratch. Load path {self.load_path} is not provided.")
        self.model.to(self.device)

def div_(self, y):
        # TODO: Add test coverage for this code path (next 4 lines)
        if isinstance(y, float) and int(y) == y:
            y = int(y)
        if is_float_tensor(y) and y.frac().eq(0).all():
            y = y.long()

        if isinstance(y, int) or is_int_tensor(y):
            validate = cfg.safety.mpc.debug.validation_mode

            if validate:
                tolerance = 1.0
                tensor = self.get_plain_text()

            # Truncate protocol for dividing by public integers:
            if comm.get().get_world_size() > 2:
                protocol = globals()[cfg.safety.mpc.protocol]
                protocol.truncate(self, y)
            else:
                self.share = self.share.div_(y, rounding_mode="trunc")

            # Validate
            if validate:
                if not torch.lt(torch.abs(self.get_plain_text() * y - tensor), tolerance).all():
                    raise ValueError("Final result of division is incorrect.")

            return self

        # Otherwise multiply by reciprocal
        if isinstance(y, float):
            y = torch.tensor([y], dtype=torch.float, device=self.device)

        assert is_float_tensor(y), "Unsupported type for div_: %s" % type(y)
        return self.mul_(y.reciprocal())

def check_repository(self, repo_id: str) -> Dict[str, Any]:
        if not repo_id or "/" not in repo_id:
            raise PublishingServiceError(
                "Invalid repository ID. Must be in format 'username/repo-name'.",
                status.HTTP_400_BAD_REQUEST,
            )

        try:
            token = hf_get_token()
            if not token:
                token_path = Path.home() / ".cache" / "huggingface" / "token"
                if token_path.exists():
                    with open(token_path, "r") as f:
                        token = f.read().strip()

            # Try to get repo info
            try:
                repo_info = self.api.repo_info(repo_id=repo_id, token=token)
                return {
                    "exists": True,
                    "available": False,
                    "message": f"Repository '{repo_id}' already exists",
                    "repo_id": repo_info.id,
                    "private": getattr(repo_info, "private", None),
                }
            except Exception:
                # Repository doesn't exist, which means it's available
                return {
                    "exists": False,
                    "available": True,
                    "message": f"Repository name '{repo_id}' is available",
                }

        except Exception as e:
            raise PublishingServiceError(
                f"Failed to check repository: {str(e)}",
                status.HTTP_500_INTERNAL_SERVER_ERROR,
            ) from e

def export_yolo_images_and_txts_from_coco_object(
    output_dir: str, coco: Coco, ignore_negative_samples: bool = False, mp: bool = False, disable_symlink: bool = False
) -> None:
    logger.info("generating image symlinks and annotation files for yolo...")
    # symlink is not supported in colab
    if is_colab() and not disable_symlink:
        logger.warning("symlink is not supported in colab, disabling it...")
        disable_symlink = True
    image_dir = coco.image_dir or ""
    if mp:
        with Pool(processes=48) as pool:
            args = [
                (coco_image, image_dir, output_dir, ignore_negative_samples, disable_symlink)
                for coco_image in coco.images
            ]
            pool.starmap(
                export_single_yolo_image_and_corresponding_txt,
                tqdm(args, total=len(args)),
            )
    else:
        for coco_image in tqdm(coco.images):
            export_single_yolo_image_and_corresponding_txt(
                coco_image, image_dir, output_dir, ignore_negative_samples, disable_symlink
            )

def show_embeddings(emb_list: List[torch.Tensor], figsize: Tuple = (10, 10), emb_name_list: [List[str]] = None):
    if not is_matplotlib_available():
        models_log.warning('Matplotlib is not available.')
    from towhee.utils.matplotlib_utils import matplotlib
    import matplotlib.pylab as plt  # pylint: disable=import-outside-toplevel
    if isinstance(emb_name_list, list):
        assert len(emb_name_list) == len(
            emb_list), f'len(emb_name_list) is {len(emb_name_list)}, and len(emb_list) is {len(emb_list)}, they must be the same.'
    max_dim = 1
    new_emb_list = []
    for emb in emb_list:
        #  (B=1, C, H, W) or (C, H, W)
        assert (len(emb.shape) == 4 and emb.shape[0] == 1) or len(emb) == 3
        if len(emb.shape) == 4:
            new_emb = torch.squeeze(emb, dim=0).detach()
        else:
            new_emb = emb.detach()
        if new_emb.shape[0] > max_dim:
            max_dim = new_emb.shape[0]
        new_emb_list.append(new_emb)
    _, axs = plt.subplots(nrows=max_dim + 1, ncols=len(new_emb_list), squeeze=False, figsize=figsize)
    for row in range(max_dim + 1):
        dim_idx = row - 1
        for col in range(len(new_emb_list)):
            emb_layer_idx = col
            if row == 0:
                if emb_name_list is not None:
                    axs[0, col].text(0.5, 0.1, f'{emb_name_list[emb_layer_idx]}', horizontalalignment='center',
                                     verticalalignment='center', transform=axs[0, col].transAxes)
                axs[0, col].axis('off')
            else:
                if dim_idx >= new_emb_list[emb_layer_idx].shape[0]:
                    axs[row, col].axis('off')
                    continue
                one_channel_emb = torch.unsqueeze(new_emb_list[emb_layer_idx][dim_idx], dim=-1)
                emb_np = one_channel_emb.numpy()
                emb_np = (emb_np - emb_np.min()) / (emb_np.max() - emb_np.min()) * 255
                axs[row, col].imshow(emb_np)
            axs[row, col].set(xticklabels=[], yticklabels=[], xticks=[], yticks=[])
    plt.show()

def get(identifier):
    from keras.src.dtype_policies.dtype_policy import (
        _get_quantized_dtype_policy_by_str,
    )

    if identifier is None:
        return dtype_policy.dtype_policy()
    if isinstance(identifier, DTypePolicy):
        return identifier
    if isinstance(identifier, dict):
        return deserialize(identifier)
    if isinstance(identifier, str):
        if identifier.startswith(QUANTIZATION_MODES):
            return _get_quantized_dtype_policy_by_str(identifier)
        else:
            return DTypePolicy(identifier)
    try:
        return DTypePolicy(backend.standardize_dtype(identifier))
    except:
        raise ValueError(
            "Cannot interpret `dtype` argument. Expected a string "
            f"or an instance of DTypePolicy. Received: dtype={identifier}"
        )

def activation_to_tcnn_string(activation: Union[nn.Module, None]) -> str:
    if isinstance(activation, nn.ReLU):
        return "ReLU"
    if isinstance(activation, nn.LeakyReLU):
        return "Leaky ReLU"
    if isinstance(activation, nn.Sigmoid):
        return "Sigmoid"
    if isinstance(activation, nn.Softplus):
        return "Softplus"
    if isinstance(activation, nn.Tanh):
        return "Tanh"
    if isinstance(activation, type(None)):
        return "None"
    tcnn_documentation_url = "https://github.com/NVlabs/tiny-cuda-nn/blob/master/DOCUMENTATION.md#activation-functions"
    raise ValueError(
        f"TCNN activation {activation} not supported for now.\nSee {tcnn_documentation_url} for TCNN documentation."
    )

def simulate(
        self,
        circuit: QuantumScript,
        seed=None,
        debugger=None,
    ) -> Result:

        # Account for custom labelled wires
        circuit = circuit.map_to_standard_wires()

        # Build a stim circuit, tableau and simulator
        stim_circuit = stim.Circuit()
        tableau_simulator = stim.TableauSimulator()
        if self.wires is not None:
            tableau_simulator.set_num_qubits(len(self.wires))

        # Account for state preparation operation
        prep = None
        if len(circuit) > 0 and isinstance(circuit[0], StatePrepBase):
            prep = circuit[0]
        use_prep_ops = bool(prep)

        if use_prep_ops:
            stim_circuit = _handle_state_prep(prep, circuit, stim_circuit)

        # Iterate over the gates --> manage them manually or apply them to circuit
        global_phase_ops = []
        for op in circuit.operations[use_prep_ops:]:
            gate, wires = _pl_op_to_stim(op)
            if gate is not None:
                # Note: This is a lot faster than doing `stim_ct.append(gate, wires)`
                stim_circuit.append_from_stim_program_text(f"{gate} {wires}")
            else:
                if isinstance(op, ops.GlobalPhase):
                    global_phase_ops.append(op)
                if isinstance(op, ops.Snapshot):
                    self._apply_snapshot(circuit, stim_circuit, op, global_phase_ops, debugger)

        tableau_simulator.do_circuit(stim_circuit)
        global_phase = ops.GlobalPhase(sum(op.data[0] for op in global_phase_ops))

        # Perform measurements based on whether shots are provided
        if circuit.shots:
            meas_results = self.measure_statistical(circuit, stim_circuit, seed=seed)
        else:
            meas_results = self.measure_analytical(
                circuit, stim_circuit, tableau_simulator, global_phase
            )

        return meas_results[0] if len(meas_results) == 1 else tuple(meas_results)

def convert_inputs_to_api_kwargs(
        self,
        input: Optional[Any] = None,
        model_kwargs: Dict = {},
        model_type: ModelType = ModelType.UNDEFINED,
    ) -> Dict:
        # TODO: ollama will support batch embedding in the future: https://ollama.com/blog/embedding-models
        self.generate = False  # reset generate to False
        final_model_kwargs = model_kwargs.copy()
        if model_type == ModelType.EMBEDDER:
            if isinstance(input, str):
                final_model_kwargs["prompt"] = input
                return final_model_kwargs
            else:
                raise ValueError(
                    "Ollama does not support batch embedding yet. It only accepts a single string for input for now. Make sure you are not passing a list of strings"
                )
        elif model_type == ModelType.LLM:
            if input is not None and input != "":
                # check if "generate" is in model_kwargs, and if it is set to True, then we use generate api
                if model_kwargs.get("generate", False):
                    final_model_kwargs["prompt"] = input
                    self.generate = True
                else:
                    # for chat api, we need to convert the input to a message format
                    # if the input is a string, we create a message with role "user"
                    if isinstance(input, str):
                        input = [{"role": "user", "content": input}]
                        final_model_kwargs["messages"] = input
                    elif not isinstance(input, list):
                        raise ValueError("Input must be a string or a list of messages")
                # if the input is a list of messages, we use it as is
                return final_model_kwargs
            else:
                raise ValueError("Input must be text")
        else:
            raise ValueError(f"model_type {model_type} is not supported")

def transform_values(
        self,
        name: str,
        values: pd.Series | torch.Tensor | np.ndarray,
        data: pd.DataFrame = None,
        inverse=False,
        group_id: bool = False,
        **kwargs,
    ) -> np.ndarray:
        transformer = self.get_transformer(name, group_id=group_id)
        if transformer is None:
            return values
        if inverse:
            transform = transformer.inverse_transform
        else:
            transform = transformer.transform

        if group_id:
            name = self._group_ids_mapping[name]
        # remaining categories
        if name in self.flat_categoricals + self.group_ids + self._group_ids:
            return transform(values, **kwargs)

        # reals
        elif name in self.reals:
            if isinstance(transformer, GroupNormalizer):
                return transform(values, data, **kwargs)
            elif isinstance(transformer, EncoderNormalizer):
                return transform(values, **kwargs)
            else:
                if isinstance(values, pd.Series):
                    values = values.to_frame()
                    return np.asarray(transform(values, **kwargs)).reshape(-1)
                else:
                    values = values.reshape(-1, 1)
                    return transform(values, **kwargs).reshape(-1)
        else:
            return values

def select_device(device: str):
    if device == "cuda":
        device = "cuda:0"
    device = (
        str(device).strip().lower().replace("cuda:", "").replace("none", "")
    )  # to string, 'cuda:0' to '0'
    cpu = device == "cpu"
    mps = device == "mps"  # Apple Metal Performance Shaders (MPS)
    if cpu or mps:
        os.environ["CUDA_VISIBLE_DEVICES"] = (
            "-1"  # force torch.cuda.is_available() = False
        )
    elif device:  # non-cpu device requested
        os.environ["CUDA_VISIBLE_DEVICES"] = (
            device  # set environment variable - must be before assert is_available()
        )

    if (
        not cpu and not mps and is_torch_cuda_available()
    ):  # prefer GPU if available
        arg = "cuda:0"
    elif (
        mps
        and getattr(torch, "has_mps", False)
        and torch.backends.mps.is_available()
    ):  # prefer MPS if available
        arg = "mps"
    else:  # revert to CPU
        arg = "cpu"

    return torch.device(arg)

def raise_for_http_status(rsp):
    http_error_msg = ''
    if isinstance(rsp.reason, bytes):
        try:
            reason = rsp.reason.decode('utf-8')
        except UnicodeDecodeError:
            reason = rsp.reason.decode('iso-8859-1')
    else:
        reason = rsp.reason
    request_id = get_request_id(rsp)
    if 404 == rsp.status_code:
        http_error_msg = 'The request resource(model or dataset) does not exist!,'
        'url: %s, reason: %s' % (rsp.url, reason)
    elif 403 == rsp.status_code:
        http_error_msg = 'Authentication token does not exist or invalid.'
    elif 400 <= rsp.status_code < 500:
        http_error_msg = u'%s Client Error: %s, Request id: %s for url: %s' % (
            rsp.status_code, reason, request_id, rsp.url)

    elif 500 <= rsp.status_code < 600:
        http_error_msg = u'%s Server Error: %s, Request id: %s, for url: %s' % (
            rsp.status_code, reason, request_id, rsp.url)

    if http_error_msg:
        req = rsp.request
        if req.method == 'POST':
            http_error_msg = u'%s, body: %s' % (http_error_msg, req.body)
        raise HTTPError(http_error_msg, response=rsp)

def batch(generator, batch_size):
  if batch_size <= 0:
    raise ValueError(f'Batch size must be positive, but is {batch_size}.')
  buf = []
  i = 0
  for example in generator:
    buf.append(example)  # Examples are tuples of tensors.
    if len(buf) == batch_size:
      # buf is a list of tuples, e.g., [(in1, tgt1), (in2, tgt2), (in3, tgt3)]
      # batch is a tuple of arrays: ([in1, in2, in3], [tgt1, tgt2, tgt3])
      try:
        batched_example = tuple(
            pad_to_max_dims([np.asarray(tensor) for tensor in x])
            for x in zip(*buf))
      except ValueError as e:
        for j in range(len(buf)):
          logging.error('Batch[%d][%d] input shape: %r output shape: %r',
                        i, j, buf[j][0].shape, buf[j][1].shape)
        for j in range(len(buf)):
          logging.error('Batch[%d][%d] input: %r', i, j, buf[j][0])
          logging.error('Batch[%d][%d] output: %r', i, j, buf[j][1])
        raise e
      i += 1
      yield batched_example
      buf = []

def get_pad_tuple(padding, kernel):
    # compute the padding size
    if isinstance(padding, tuple | list):
        if len(padding) == 2:
            pad_h = padding[0] * 2
            pad_w = padding[1] * 2
        elif len(padding) == 4:
            return padding[0], padding[1], padding[2], padding[3]
        else:
            raise ValueError("Size of padding can only be 2 or 4")
    elif isinstance(padding, int):
        pad_h = pad_w = padding * 2
    elif padding == "VALID":
        pad_h = 0
        pad_w = 0
    elif padding == "SAME":
        pad_h = kernel[0] - 1
        pad_w = kernel[1] - 1
    else:
        raise ValueError(f"Unknown padding option {padding}")
    pad_top = (pad_h + 1) // 2
    pad_left = (pad_w + 1) // 2
    return pad_top, pad_left, pad_h - pad_top, pad_w - pad_left

def build_tool_call_messages(
    trace: list[ChatCompletionMessageParam] | None,
) -> list[Union[ToolCallMessage, ToolResponseMessage]]:
    if trace is None:
        return []

    tool_messages: list[Union[ToolCallMessage, ToolResponseMessage]] = []

    for message in trace:
        role = message.get("role")

        if role == "assistant" and "tool_calls" in message:
            tool_calls = message.get("tool_calls")
            if tool_calls:
                content = message.get("content")
                tool_messages.append(
                    ToolCallMessage(
                        role="assistant",
                        tool_calls=tool_calls,
                        content=extract_text_from_content(content),
                    )
                )
        elif role == "tool":
            content = message.get("content")
            tool_call_id = message.get("tool_call_id")

            if tool_call_id is None:
                raise ValueError("Tool call ID is required for tool response messages")
            if content is None:
                raise ValueError("Content is required for tool response messages")

            if not isinstance(content, str):
                content = str(content)

            tool_messages.append(
                ToolResponseMessage(
                    role="tool",
                    content=content,
                    tool_call_id=tool_call_id,
                )
            )

    return tool_messages

def predict(self, X, treatment=None, y=None, return_components=False, verbose=True):
        X, treatment, y = convert_pd_to_np(X, treatment, y)

        te = np.zeros((X.shape[0], self.t_groups.shape[0]))
        yhat_cs = {}
        yhat_ts = {}

        for i, group in enumerate(self.t_groups):
            models_tau = self.models_tau[group]
            _te = np.r_[[model.predict(X) for model in models_tau]].mean(axis=0)
            te[:, i] = np.ravel(_te)
            yhat_cs[group] = np.r_[
                [model.predict(X) for model in self.models_mu_c[group]]
            ].mean(axis=0)
            yhat_ts[group] = np.r_[
                [model.predict(X) for model in self.models_mu_t[group]]
            ].mean(axis=0)

            if (y is not None) and (treatment is not None) and verbose:
                mask = (treatment == group) | (treatment == self.control_name)
                treatment_filt = treatment[mask]
                y_filt = y[mask]
                w = (treatment_filt == group).astype(int)

                yhat = np.zeros_like(y_filt, dtype=float)
                yhat[w == 0] = yhat_cs[group][mask][w == 0]
                yhat[w == 1] = yhat_ts[group][mask][w == 1]

                logger.info("Error metrics for group {}".format(group))
                regression_metrics(y_filt, yhat, w)

        if not return_components:
            return te
        else:
            return te, yhat_cs, yhat_ts

def apply_prompt_template(
        self,
        chat_template: Callable,
        prompt: str,
        system_prompt: str = None,
    ) -> str:

        messages = []
        message = {"role": "user", "content": prompt}
        if self.decoder_model in VLM_SPECIAL_TOKENS:
            contents = self._split_prompt(prompt)
            message["content"] = []
            for content in contents:
                if content == IMG_TOKEN:
                    message["content"].append(
                        {"type": "image"},
                    )
                else:
                    message["content"].append(
                        {"type": "text", "text": content},
                    )
        elif self.decoder_model in ALM_SPECIAL_TOKENS:
            message["content"] = prompt

        messages.append(message)
        if system_prompt:
            messages.append({"role": "system", "content": system_prompt})

        template_prompt = chat_template(
            messages, tokenize=False, add_generation_prompt=True
        )

        # edge cases handling:
        # Gemma may produce unexpected output if the prompt contains an extra <bos> token.
        # This can happen after applying a prompt template, which might inject <bos> unintentionally.
        # To prevent decoding issues, we explicitly remove <bos> token
        if chat_template and self.decoder_model in {
            "gemma-2b",
            "gemma3-1b",
        }:
            template_prompt = template_prompt.replace("<bos>", "")

        return template_prompt

def set_params(self, hparam_dict=None, cache_dict=None):
        from ..initializers import SchedulerInitializer

        if hparam_dict is not None:
            for k, v in hparam_dict.items():
                if k in self.hyperparameters:
                    self.hyperparameters[k] = v
                    if k == "lr_scheduler":
                        self.lr_scheduler = SchedulerInitializer(v, lr=None)()

        if cache_dict is not None:
            for k, v in cache_dict.items():
                if k in self.cache:
                    self.cache[k] = v

def create_zero_bias_int32(
    graph_module: GraphModule,
    weight_node: fx.Node,
    bias_scale: float,
) -> fx.Node:
    try:
        attr_node = getattr(graph_module, weight_node.target)
    except AttributeError:
        if "val" in weight_node.meta:
            attr_node = weight_node.meta["val"]
        else:
            param_dict = dict(graph_module.named_parameters())
            if weight_node.target in param_dict:
                attr_node = param_dict[weight_node.target]
            else:
                buffer_dict = dict(graph_module.named_buffers())
                if weight_node.target in buffer_dict:
                    attr_node = buffer_dict[weight_node.target]
                else:
                    raise AttributeError(
                        f"Could not find weight tensor for node {weight_node.target}. "
                        f"Node metadata keys: {list(weight_node.meta.keys())}"
                    )

    weight_shape = list(attr_node.shape)
    bias_shape = weight_shape[0]
    new_node = graph_module.graph.call_function(
        torch.ops.aten.full.default,
        ([bias_shape], 0.0),
        {"dtype": torch.int32},
    )

    if "val" in weight_node.meta:
        fake_mode = weight_node.meta["val"].fake_mode
        if fake_mode is not None:
            with fake_mode:
                fake_bias = torch.zeros([bias_shape], dtype=torch.int32)
            new_node.meta["val"] = fake_bias
        else:
            new_node.meta["val"] = torch.zeros([bias_shape], dtype=torch.int32)
        copy_node_metadata(new_node, weight_node)

    return new_node

def should_retry(self, exception: Exception) -> bool:
        if self._total_retries >= self._max_retries:
            return False
        self._total_retries += 1

        now = NOW_FN()
        if now - self._start_time >= self._timeout:
            return False

        retry_check_result = self._retry_check(exception)
        if not retry_check_result:
            return False

        if isinstance(retry_check_result, datetime.timedelta):
            if not self._last_custom_timeout:
                self._last_custom_timeout = now

            if now - self._last_custom_timeout >= retry_check_result:
                return False

        return True

