def render(self, stats_list: list[pb.OperationStats]) -> list[str]:
        lines: list[str] = []

        for stats in sorted(stats_list, key=lambda s: s.label):
            # Don't display empty groups.
            if not stats.operations:
                continue

            if stats.label:
                remaining_non_header_lines = self._max_lines - len(lines) - 1
                indent = _INDENT
            else:
                remaining_non_header_lines = self._max_lines - len(lines)
                indent = ""

            # Ensure enough space left for at least one line of content
            # after the header.
            if remaining_non_header_lines < 1:
                break

            # Group header (if not empty).
            if stats.label:
                lines.append(stats.label)

            # Group content.
            stats_lines = _OperationStatsPrinter(
                printer=self._printer,
                max_lines=remaining_non_header_lines,
                loading_symbol=self._loading_symbol,
            ).render(stats)
            for line in stats_lines:
                lines.append(f"{indent}{line}")

        return lines

def save(
        self,
        project: str | None = None,
        settings: wandb.Settings | None = None,
    ) -> None:
        if self._state is not ArtifactState.PENDING:
            return self._update()

        if self._incremental:
            with telemetry.context() as tel:
                tel.feature.artifact_incremental = True

        if run := wandb_setup.singleton().most_recent_active_run:
            # TODO: Deprecate and encourage explicit log_artifact().
            run.log_artifact(self)
        else:
            if settings is None:
                settings = wandb.Settings(silent="true")
            with wandb.init(  # type: ignore
                entity=self._source_entity,
                project=project or self._source_project,
                job_type="auto",
                settings=settings,
            ) as run:
                # redoing this here because in this branch we know we didn't
                # have the run at the beginning of the method
                if self._incremental:
                    with telemetry.context(run=run) as tel:
                        tel.feature.artifact_incremental = True
                run.log_artifact(self)

def run_subprocess(
    arguments: list[str],
    env: dict[str, str] | None = None,
    logger: logging.Logger | None = None,
    *,
    check_exit_code: bool = True,
    log_stdout: bool = True,
    log_stderr: bool = True,
) -> CompletedProcess:

    proc_name = arguments[0]

    completed_proc = run(args=arguments, env=env, capture_output=True, check=False)

    if logger:
        logger.info(f"{proc_name} exited {completed_proc.returncode}")

    if log_stdout and logger and completed_proc.stdout:
        stdout_str = (
            completed_proc.stdout.decode("utf8", errors="ignore")
            .strip()
            .split(
                "\n",
            )
        )
        logger.info(f"{proc_name} stdout:")
        for line in stdout_str:
            logger.info(line)

    if log_stderr and logger and completed_proc.stderr:
        stderr_str = (
            completed_proc.stderr.decode("utf8", errors="ignore")
            .strip()
            .split(
                "\n",
            )
        )
        logger.info(f"{proc_name} stderr:")
        for line in stderr_str:
            logger.warning(line)

    # Last, if requested, after logging outputs
    if check_exit_code:
        completed_proc.check_returncode()

    return completed_proc

def stem(self, word):
        word = word.lower()

        if word in self.stopwords:
            return word

        r1 = self._r1_scandinavian(word, self.__vowels)

        # STEP 1
        for suffix in self.__step1_suffixes:
            if r1.endswith(suffix):
                if suffix in ("erte", "ert"):
                    word = suffix_replace(word, suffix, "er")
                    r1 = suffix_replace(r1, suffix, "er")

                elif suffix == "s":
                    if word[-2] in self.__s_ending or (
                        word[-2] == "k" and word[-3] not in self.__vowels
                    ):
                        word = word[:-1]
                        r1 = r1[:-1]
                else:
                    word = word[: -len(suffix)]
                    r1 = r1[: -len(suffix)]
                break

        # STEP 2
        for suffix in self.__step2_suffixes:
            if r1.endswith(suffix):
                word = word[:-1]
                r1 = r1[:-1]
                break

        # STEP 3
        for suffix in self.__step3_suffixes:
            if r1.endswith(suffix):
                word = word[: -len(suffix)]
                break

        return word

def on_train_end(self, last, best, epoch, results):
        if self.plots:
            plot_results(file=self.save_dir / "results.csv")  # save results.png
        files = ["results.png", "confusion_matrix.png", *(f"{x}_curve.png" for x in ("F1", "PR", "P", "R"))]
        files = [(self.save_dir / f) for f in files if (self.save_dir / f).exists()]  # filter
        self.logger.info(f"Results saved to {colorstr('bold', self.save_dir)}")

        if self.tb and not self.clearml:  # These images are already captured by ClearML by now, we don't want doubles
            for f in files:
                self.tb.add_image(f.stem, cv2.imread(str(f))[..., ::-1], epoch, dataformats="HWC")

        if self.wandb:
            self.wandb.log(dict(zip(self.keys[3:10], results)))
            self.wandb.log({"Results": [wandb.Image(str(f), caption=f.name) for f in files]})
            # Calling wandb.log. TODO: Refactor this into WandbLogger.log_model
            if not self.opt.evolve:
                wandb.log_artifact(
                    str(best if best.exists() else last),
                    type="model",
                    name=f"run_{self.wandb.wandb_run.id}_model",
                    aliases=["latest", "best", "stripped"],
                )
            self.wandb.finish_run()

        if self.clearml and not self.opt.evolve:
            self.clearml.task.update_output_model(
                model_path=str(best if best.exists() else last), name="Best Model", auto_delete_file=False
            )

        if self.comet_logger:
            final_results = dict(zip(self.keys[3:10], results))
            self.comet_logger.on_train_end(files, self.save_dir, last, best, epoch, final_results)

async def serve_public_file(request: Request) -> Response:
    app_state = AppState(request)
    filepath = str(request.path_params["filepath"])
    # Get notebook ID from header
    notebook_id = request.headers.get("X-Notebook-Id")
    if notebook_id:
        # Decode notebook ID
        notebook_id = uri_decode_component(notebook_id)
        app_manager = app_state.session_manager.app_manager(notebook_id)
        if app_manager.filename:
            notebook_dir = Path(app_manager.filename).parent
        else:
            notebook_dir = Path.cwd()
        public_dir = notebook_dir / "public"
        file_path = public_dir / filepath

        # Security check: ensure file is inside public directory.
        # validate_inside_directory preserves symlinks, so also verify the
        # resolved target stays within public_dir to avoid symlinks in
        # public/ pointing at files outside the notebook's public directory.
        try:
            PathValidator().validate_inside_directory(public_dir, file_path)
        except HTTPException:
            return Response(status_code=403, content="Access denied")

        try:
            resolved_file = file_path.resolve(strict=True)
            resolved_public = public_dir.resolve(strict=True)
            resolved_file.relative_to(resolved_public)
        except (OSError, ValueError):
            raise HTTPException(
                status_code=404, detail="File not found"
            ) from None

        if resolved_file.is_file():
            return FileResponse(resolved_file)

    raise HTTPException(status_code=404, detail="File not found")

def callback_check(fn, available, allow_default=True):
    # keep a copy of the original value because we'll modified it if this is
    # a DottedPath
    available_raw = available

    if isinstance(fn, DottedPath):
        available = {**fn._spec.get_kwargs(), **available}

        if fn.callable is None:
            raise CallbackCheckAborted(
                "Cannot check callback because function "
                "is a dotted path whose function has not been imported yet"
            )
        else:
            fn = fn.callable

    parameters = inspect.signature(fn).parameters
    optional = {
        name for name, param in parameters.items() if param.default != inspect._empty
    }
    # not all functions have __name__ (e.g. partials)
    fn_name = getattr(fn, "__name__", fn)

    if optional and not allow_default:
        raise CallbackSignatureError(
            "Callback functions cannot have "
            "parameters with default values, "
            'got: {} in "{}"'.format(optional, fn_name)
        )

    required = {
        name for name, param in parameters.items() if param.default == inspect._empty
    }

    available_set = set(available)
    extra = required - available_set

    if extra:
        raise CallbackSignatureError(
            'Callback function "{}" unknown '
            "parameter(s): {}, available ones are: "
            "{}".format(fn_name, extra, available_set)
        )

    return {k: v for k, v in available_raw.items() if k in required}

def config_uses_llm(config: dict[str, Any] | ModelConfig) -> bool:
    uses_llm = False

    # For a valid config, model_type LLM is automatically True
    # ECD models need to be checked for at least one LLM text encoder
    if isinstance(config, ModelConfig):
        if config.model_type == MODEL_LLM:
            uses_llm = True
        else:
            for feature in config.input_features:
                if feature.encoder and feature.encoder.type == MODEL_LLM:
                    uses_llm = True
                    break
    elif isinstance(config, dict) and config:
        if config.get(MODEL_TYPE, MODEL_ECD) == MODEL_LLM:
            uses_llm = True
        elif INPUT_FEATURES in config:
            for feature in config.get(INPUT_FEATURES, []):
                if feature.get(ENCODER, {}).get(TYPE) == MODEL_LLM:
                    uses_llm = True
                    break
        else:
            raise ValueError(
                "Invalid config cannot be checked for LLM usage because it has no input features." f"Config: {config}"
            )
    else:
        raise ValueError(f"Invalid config cannot be checked for LLM usage. Config: {config}")

    return uses_llm

def has_cycles(self) -> bool:
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {node_id: WHITE for node_id in self.nodes}

        def visit(node_id: uuid.UUID) -> bool:
            if color[node_id] == GRAY:
                return True  # Back edge found - cycle detected
            if color[node_id] == BLACK:
                return False  # Already fully explored

            color[node_id] = GRAY
            for dep_id in self._dependencies[node_id]:
                if visit(dep_id):
                    return True
            color[node_id] = BLACK
            return False

        for node_id in self.nodes:
            if color[node_id] == WHITE:
                if visit(node_id):
                    return True
        return False

def transform(self) -> DataFrame | Series:
        obj = self.obj
        func = self.func
        axis = self.axis
        args = self.args
        kwargs = self.kwargs

        is_series = obj.ndim == 1

        if obj._get_axis_number(axis) == 1:
            assert not is_series
            return obj.T.transform(func, 0, *args, **kwargs).T

        if is_list_like(func) and not is_dict_like(func):
            func = cast("list[AggFuncTypeBase]", func)
            # Convert func equivalent dict
            if is_series:
                func = {com.get_callable_name(v) or v: v for v in func}
            else:
                func = dict.fromkeys(obj, func)

        if is_dict_like(func):
            func = cast("AggFuncTypeDict", func)
            return self.transform_dict_like(func)

        # func is either str or callable
        func = cast("AggFuncTypeBase", func)
        try:
            result = self.transform_str_or_callable(func)
        except TypeError:
            raise
        except Exception as err:
            raise ValueError("Transform function failed") from err

        # Functions that transform may return empty Series/DataFrame
        # when the dtype is not appropriate
        if (
            isinstance(result, (ABCSeries, ABCDataFrame))
            and result.empty
            and not obj.empty
        ):
            raise ValueError("Transform function failed")
        if not isinstance(result, (ABCSeries, ABCDataFrame)) or not result.index.equals(
            obj.index
        ):
            raise ValueError("Function did not transform")

        return result

def plur2sing(self, token):
        # ^Haa, $Noon, Waaw
        if len(token) > 5:
            if token.startswith("\u0645") and token.endswith("\u0648\u0646"):
                return token[1:-2]
        if len(token) > 4:
            for ps2 in self.pl_si2:
                if token.endswith(ps2):
                    return token[:-2]
        if len(token) > 5:
            for ps3 in self.pl_si3:
                if token.endswith(ps3):
                    return token[:-3]
        if len(token) > 4:
            # $Alif, Taa
            if token.endswith("\u0627\u062a"):
                return token[:-2]
            # ^Alif Alif
            if token.startswith("\u0627") and token[2] == "\u0627":
                return token[:2] + token[3:]
            # ^Alif Alif
            if token.startswith("\u0627") and token[-2] == "\u0627":
                return token[1:-2] + token[-1]

def migrate_checkpoint(
    checkpoint: _CHECKPOINT, target_version: Optional[str] = None
) -> tuple[_CHECKPOINT, dict[str, list[str]]]:
    ckpt_version = _get_version(checkpoint)
    if Version(ckpt_version) > Version(pl.__version__):
        rank_zero_warn(
            f"The loaded checkpoint was produced with Lightning v{ckpt_version}, which is newer than your current"
            f" Lightning version: v{pl.__version__}",
            category=PossibleUserWarning,
        )
        return checkpoint, {}

    index = _migration_index()
    applied_migrations = {}
    for migration_version, migration_functions in index.items():
        if not _should_upgrade(checkpoint, migration_version, target_version):
            continue
        for migration_function in migration_functions:
            checkpoint = migration_function(checkpoint)

        applied_migrations[migration_version] = [fn.__name__ for fn in migration_functions]

    if ckpt_version != pl.__version__:
        _set_legacy_version(checkpoint, ckpt_version)
    _set_version(checkpoint, pl.__version__)
    return checkpoint, applied_migrations

def shoot_infs(inp_tensor):
    mask_inf = torch.isinf(inp_tensor)
    ind_inf = torch.nonzero(mask_inf, as_tuple=False)
    if len(ind_inf) > 0:
        for ind in ind_inf:
            if len(ind) == 2:
                inp_tensor[ind[0], ind[1]] = 0
            elif len(ind) == 1:
                inp_tensor[ind[0]] = 0
        m = torch.max(inp_tensor)
        for ind in ind_inf:
            if len(ind) == 2:
                inp_tensor[ind[0], ind[1]] = m
            elif len(ind) == 1:
                inp_tensor[ind[0]] = m
    return inp_tensor

def read_query_params_into_session_state(
    page_name: str, transforms: Optional[Dict[str, Callable[[str], Any]]] = None
):
    assert not st.session_state.get(f"{page_name}.initialized", False)
    for param, value in st.query_params.to_dict().items():
        prefix_page_name = True
        if param == ST_APP_NAME:
            prefix_page_name = False
        elif param.startswith("filter."):
            prefix_page_name = False
            if param.endswith(".multiselect"):
                value = value.split(",")
                if len(value) == 1 and value[0] == "":
                    value = []
        elif transforms and param in transforms:
            value = transforms[param](value)

        if prefix_page_name:
            st.session_state[f"{page_name}.{param}"] = value
        else:
            st.session_state[param] = value

def get_engine(engine: str) -> BaseEngine:
    if engine == "auto":
        engine = config["io"]["sql"]["engine"]

    if engine == "auto":
        # try engines in this order
        engine_classes = [SQLAlchemyEngine]

        error_msgs = ""
        for engine_class in engine_classes:
            try:
                return engine_class()
            except ImportError as err:
                error_msgs += "\n - " + str(err)

        raise ImportError(
            "Unable to find a usable engine; "
            "tried using: 'sqlalchemy'.\n"
            "A suitable version of "
            "sqlalchemy is required for sql I/O "
            "support.\n"
            "Trying to import the above resulted in these errors:"
            f"{error_msgs}"
        )

    if engine == "sqlalchemy":
        return SQLAlchemyEngine()

    raise ValueError("engine must be one of 'auto', 'sqlalchemy'")

def generate_example_config(self, model_family: str) -> Dict[str, Any]:
        config = {}

        # Add base required fields
        for rule in ConfigRegistry.get_rules("base"):
            if rule.rule_type == RuleType.REQUIRED:
                config[rule.field_name] = f"<REQUIRED: {rule.message}>"
            elif rule.rule_type == RuleType.DEFAULT:
                config[rule.field_name] = rule.value

        # Add model-specific fields
        for rule in ConfigRegistry.get_rules(model_family):
            if rule.rule_type == RuleType.REQUIRED:
                config[rule.field_name] = f"<REQUIRED: {rule.message}>"
            elif rule.rule_type == RuleType.DEFAULT:
                config[rule.field_name] = rule.value
            elif rule.rule_type == RuleType.OVERRIDE:
                config[rule.field_name] = rule.value

        # Add example dataloader config
        if model_family in ModelRegistry.model_families().keys():
            config["data_backend_config"] = "config/multidatabackend.json"

        return config

async def fix(self, file_status: FileStatus) -> bool:
        if file_status.notebook is None or file_status.contents is None:
            return False

        # Apply unsafe fixes if enabled
        modified_notebook = file_status.notebook
        if self.unsafe_fixes:
            # Collect diagnostics by rule code
            from collections import defaultdict

            from marimo._lint.rules.base import UnsafeFixRule

            diagnostics_by_rule = defaultdict(list)
            for diagnostic in file_status.diagnostics:
                if (
                    diagnostic.fixable == "unsafe"
                    and diagnostic.code in self.rule_lookup
                ):
                    diagnostics_by_rule[diagnostic.code].append(diagnostic)

            # Apply unsafe fixes once per rule
            for rule_code, diagnostics in diagnostics_by_rule.items():
                rule = self.rule_lookup[rule_code]
                if isinstance(rule, UnsafeFixRule):
                    # Apply fix once per rule with all its diagnostics
                    modified_notebook = rule.apply_unsafe_fix(
                        modified_notebook, diagnostics
                    )

        # Generate file contents from (possibly modified) notebook
        generated_contents = Linter._generate_file_contents_from_notebook(
            modified_notebook, file_status.file
        )

        # Only write if content changed (excluding __generated_with differences)
        if contents_differ_excluding_generated_with(
            file_status.contents, generated_contents
        ):
            await asyncio.to_thread(
                Path(file_status.file).write_text,
                generated_contents,
                encoding="utf-8",
            )
            return True

        return False

def delete_images_in_range(self, start_idx, end_idx):
        deleted_count = 0
        current_dir = os.path.dirname(self.image_file_list[0])
        save_path = os.path.join(current_dir, "..", "_delete_")
        os.makedirs(save_path, exist_ok=True)

        for i in range(start_idx - 1, end_idx):
            if i >= len(self.image_file_list):
                break

            image_file = self.image_file_list[i]

            if os.path.exists(image_file):
                try:
                    image_name = os.path.basename(image_file)
                    save_file = os.path.join(save_path, image_name)
                    shutil.move(image_file, save_file)

                    label_dir = os.path.dirname(image_file)
                    if self.parent.output_dir:
                        label_dir = self.parent.output_dir
                    label_file = os.path.join(
                        label_dir, os.path.splitext(image_name)[0] + ".json"
                    )

                    if os.path.exists(label_file):
                        os.remove(label_file)

                    deleted_count += 1
                except Exception as e:
                    logger.error(f"Error deleting {image_file}: {e}")

        if deleted_count > 0:
            self.parent.reset_state()
            self.parent.import_image_folder(current_dir)

            if len(self.parent.image_list) > 0:
                filename = self.parent.image_list[0]
                self.parent.filename = filename
                if filename:
                    self.parent.load_file(filename)

        logger.info(
            f"Deleted {deleted_count} image files in range {start_idx}-{end_idx}"
        )

        template = self.tr("Deleted %s image files")
        popup = Popup(
            template % deleted_count,
            self.parent,
            icon=new_icon_path("copy-green", "svg"),
        )
        popup.show_popup(self.parent, position="center")

def apply_gradients(self, apply_grads_closure, optimizer, *args, **kwargs):
        flattended_args0 = [item for tup in args[0] for item in tup]

        # If optimizer tracks iterations, we increment it on steps where we
        # are not going to call `apply_gradients()`.
        def increment_optimizer_iteration():
            # (kvignesh1420): Since all `tf.OptimizerV2` instances have the `iterations`
            # property for modifying the underlying `optimizer._iterations`, it is safe to use
            # the property instead of the private variable. For instance, the keras
            # `LossScaleOptimizer` inherits `tf.Optimizer` and exposes the cleaner `iterations`
            # property instead of the unsafe `_iterations`.

            if hasattr(optimizer, "iterations") and optimizer.iterations is not None:
                return optimizer.iterations.assign_add(1).op
            return tf.no_op()

        with tf.control_dependencies([tf.group(*get_not_none_from_list(flattended_args0))]):
            train_op = tf.cond(
                pred=tf.equal(self.counter, 0),
                true_fn=apply_grads_closure,
                false_fn=increment_optimizer_iteration,
            )

        # Since we skip applying updates when the counter is not at zero we
        # still want to increment the global step if it is being tracked
        # (e.g., Tensorflow Estimators).
        def increment_global_step_counter():
            global_step_counter = kwargs.get('global_step')
            if global_step_counter is None:
                return tf.no_op()
            return global_step_counter.assign_add(
                tf.constant(1, dtype=tf.int64),
                use_locking=True,
                read_value=False
            )

        with tf.control_dependencies([train_op]):
            # Increment global step on iterations where we don't call `apply_gradients()`.
            return tf.cond(
                pred=tf.equal(self.counter, 0),
                true_fn=tf.no_op,
                false_fn=increment_global_step_counter,
            )

def get_flops(model, imgsz=640):
    try:
        import thop
    except ImportError:
        thop = None  # conda support without 'ultralytics-thop' installed

    if not thop:
        return 0.0  # if not installed return 0.0 GFLOPs

    try:
        model = unwrap_model(model)
        p = next(model.parameters())
        if not isinstance(imgsz, list):
            imgsz = [imgsz, imgsz]  # expand if int/float
        try:
            # Method 1: Use stride-based input tensor
            stride = max(int(model.stride.max()), 32) if hasattr(model, "stride") else 32  # max stride
            im = torch.empty((1, p.shape[1], stride, stride), device=p.device)  # input image in BCHW format
            flops = thop.profile(deepcopy(model), inputs=[im], verbose=False)[0] / 1e9 * 2  # stride GFLOPs
            return flops * imgsz[0] / stride * imgsz[1] / stride  # imgsz GFLOPs
        except Exception:
            # Method 2: Use actual image size (required for RTDETR models)
            im = torch.empty((1, p.shape[1], *imgsz), device=p.device)  # input image in BCHW format
            return thop.profile(deepcopy(model), inputs=[im], verbose=False)[0] / 1e9 * 2  # imgsz GFLOPs
    except Exception:
        return 0.0

def high_availability_specified(cluster_name: Optional[str]) -> bool:
    controller = Controllers.from_name(cluster_name, expect_exact_match=False)
    if controller is None:
        return False

    if controller.value.controller_type == 'jobs':
        # pylint: disable-next=import-outside-toplevel
        from sky.jobs import utils as managed_job_utils
        if managed_job_utils.is_consolidation_mode():
            return True
    elif controller.value.controller_type == 'serve':
        # pylint: disable-next=import-outside-toplevel
        from sky.serve import serve_utils
        if serve_utils.is_consolidation_mode():
            return True

    if skypilot_config.loaded():
        return skypilot_config.get_nested((controller.value.controller_type,
                                           'controller', 'high_availability'),
                                          False)
    return False

def gen_following_tasks(self, task: dict, test_end: pd.Timestamp) -> List[dict]:
        prev_seg = task["dataset"]["kwargs"]["segments"]
        while True:
            segments = {}
            try:
                for k, seg in prev_seg.items():
                    # decide how to shift
                    # expanding only for train data, the segments size of test data and valid data won't change
                    if k == self.train_key and self.rtype == self.ROLL_EX:
                        rtype = self.ta.SHIFT_EX
                    else:
                        rtype = self.ta.SHIFT_SD
                    # shift the segments data
                    segments[k] = self.ta.shift(seg, step=self.step, rtype=rtype)
                if segments[self.test_key][0] > test_end:
                    break
            except KeyError:
                # We reach the end of tasks
                # No more rolling
                break

            prev_seg = segments
            t = self.task_copy_func(task)  # deepcopy is necessary to avoid replace task inplace
            self._update_task_segs(t, segments)
            yield t

def arrange_graph_outputs(
    gm: torch.fx.GraphModule,
    output_specs: List[OutputSpec],
    call_module_node: torch.fx.Node,
) -> torch.fx.GraphModule:
    # Find the output node
    output_node = None
    for node in gm.graph.nodes:
        if node.op == "output":
            output_node = node
            break

    if output_node is None or not output_node.args[0]:
        return gm

    old_outputs = list(output_node.args[0])

    if len(old_outputs) != len(output_specs):
        raise RuntimeError(
            f"Mismatch between graph outputs ({len(old_outputs)}) and "
            f"output_specs ({len(output_specs)}). This indicates a bug in "
            "_get_new_signature."
        )

    # Separate indices by kind: mutations first, then user outputs
    mutation_indices = []
    user_output_indices = []
    for i, spec in enumerate(output_specs):
        if spec.kind in (OutputKind.BUFFER_MUTATION, OutputKind.USER_INPUT_MUTATION):
            mutation_indices.append(i)
        else:
            user_output_indices.append(i)

    new_order = mutation_indices + user_output_indices

    # Check if already in correct order
    if new_order == list(range(len(old_outputs))):
        return gm

    # Build reverse mapping: old_index -> new_index
    old_to_new = {old_idx: new_idx for new_idx, old_idx in enumerate(new_order)}

    # Reorder the output tuple in the submodule graph
    new_outputs = [old_outputs[i] for i in new_order]
    output_node.args = (tuple(new_outputs),)

    # Reorder the output_specs to match (in-place)
    reordered_specs = [output_specs[i] for i in new_order]
    output_specs.clear()
    output_specs.extend(reordered_specs)

    # Remap getitem indices in the parent graph
    for user in list(call_module_node.users.keys()):
        if user.op == "call_function" and user.target == operator.getitem:
            old_idx = user.args[1]
            if isinstance(old_idx, int) and old_idx in old_to_new:
                user.args = (user.args[0], old_to_new[old_idx])

    gm.graph.lint()

    return gm

