def pool(self, df):
        def max_pool(x):
            values = np.array(
                [
                    np.reshape(np.array(x.values[i]), self.embedding_dim)
                    for i in range(x.values.shape[0])
                ]
            )
            m, _ = torch.max(torch.tensor(values, dtype=torch.float), 0)
            return m.numpy()

        def mean_pool(x):
            values = np.array(
                [
                    np.reshape(np.array(x.values[i]), self.embedding_dim)
                    for i in range(x.values.shape[0])
                ]
            )
            return torch.mean(torch.tensor(values, dtype=torch.float), 0).numpy()

        def cls_pool(x):
            values = np.array(
                [
                    np.reshape(np.array(x.values[i]), self.embedding_dim)
                    for i in range(x.values.shape[0])
                ]
            )
            return values[0]

        try:
            if self.pooling_strategy == "max":
                pool_func = max_pool
            elif self.pooling_strategy == "mean":
                pool_func = mean_pool
            elif self.pooling_strategy == "cls":
                pool_func = cls_pool
            else:
                raise ValueError("Please enter valid pooling strategy")
        except ValueError as ve:
            print(ve)

        return (
            df.groupby(["text_index", "layer_index"])["values"]
            .apply(lambda x: pool_func(x))
            .reset_index()
        )

async def acall(
        self,
        messages: List[Message],
        function_schemas: Optional[List[Dict[str, Any]]] = None,
    ) -> str:
        if self._async_client is None:
            raise ValueError("OpenAI async_client is not initialized.")
        try:
            tools: Union[List[Dict[str, Any]], NotGiven] = (
                function_schemas if function_schemas is not None else NOT_GIVEN
            )

            completion = await self._async_client.chat.completions.create(
                model=self.name,
                messages=[m.to_openai() for m in messages],
                temperature=self.temperature,
                max_tokens=self.max_tokens,
                tools=tools,  # type: ignore # We pass a list of dicts which get interpreted as Iterable[ChatCompletionToolParam].
            )

            if function_schemas:
                tool_calls = completion.choices[0].message.tool_calls
                if tool_calls is None:
                    raise ValueError("Invalid output, expected a tool call.")
                if len(tool_calls) < 1:
                    raise ValueError(
                        "Invalid output, expected at least one tool to be specified."
                    )

                # Collecting multiple tool calls information
                output = str(
                    await self.async_extract_tool_calls_info(tool_calls)  # type: ignore[arg-type]  # Ignore type errors between openai SDK <2.0.0 and >=2.0.0
                )  # str in keeping with base type.
            else:
                content = completion.choices[0].message.content
                if content is None:
                    raise ValueError("Invalid output, expected content.")
                output = content
            return output

        except Exception as e:
            logger.error(f"LLM error: {e}")
            raise Exception(f"LLM error: {e}") from e

def set_masks_source(self, masks_source: Optional[Union[Sequence[str], Dict[str, str]]] = None) -> None:
        if masks_source is None:
            self._masks_source = {}
            return
        uris: List[str] = []
        if isinstance(masks_source, dict):
            # use insertion order of values
            uris = [str(v) for v in masks_source.values()]
        else:
            uris = [str(u) for u in masks_source]
        self._masks_source = {f"{i:02d}": u for i, u in enumerate(uris)}

def collect(
    repo: "Repo",
    revs: Union[list[str], str, None] = None,
    all_branches: bool = False,
    all_tags: bool = False,
    all_commits: bool = False,
    num: int = 1,
    hide_queued: bool = False,
    hide_failed: bool = False,
    hide_workspace: bool = False,
    sha_only: bool = False,
    **kwargs,
) -> list["ExpState"]:
    assert isinstance(repo.scm, Git)
    if repo.scm.no_commits:
        return []
    if not any([revs, all_branches, all_tags, all_commits]):
        revs = ["HEAD"]
    if isinstance(revs, str):
        revs = [revs]
    cached_refs = list(repo.scm.iter_refs())
    baseline_revs = list(
        iter_revs(
            repo.scm,
            revs=revs,
            num=num,
            all_branches=all_branches,
            all_tags=all_tags,
            all_commits=all_commits,
        )
    )
    if sha_only:
        baseline_names: dict[str, Optional[str]] = {}
    else:
        baseline_names = describe(
            repo.scm, baseline_revs, refs=cached_refs, logger=logger
        )

    result: list[ExpState] = []
    if not hide_workspace:
        workspace_data = collect_rev(repo, "workspace", **kwargs)
        result.append(workspace_data)

    queued = collect_queued(repo, baseline_revs, **kwargs) if not hide_queued else {}
    active = collect_active(repo, baseline_revs, **kwargs)
    failed = collect_failed(repo, baseline_revs, **kwargs) if not hide_failed else {}
    successful = collect_successful(repo, baseline_revs, **kwargs)

    for baseline_rev in baseline_revs:
        baseline_data = collect_rev(repo, baseline_rev)
        experiments = list(
            itertools.chain.from_iterable(
                _sorted_ranges(collected.get(baseline_rev, []))
                for collected in (active, successful, queued, failed)
            )
        )
        result.append(
            ExpState(
                rev=baseline_rev,
                name=baseline_names.get(baseline_rev),
                data=baseline_data.data,
                error=baseline_data.error,
                experiments=experiments or None,
            )
        )
    return result

def make_coco_transforms(
    image_set: str,
    resolution: int,
    multi_scale: bool = False,
    expanded_scales: bool = False,
    skip_random_resize: bool = False,
    patch_size: int = 16,
    num_windows: int = 4,
    aug_config: Optional[Dict[str, Dict[str, Any]]] = None,
    gpu_postprocess: bool = False,
) -> Compose:
    to_image = ToImage()
    to_float = ToDtype(torch.float32, scale=True)
    normalize = Normalize()

    scales = [resolution]
    if multi_scale:
        # scales = [448, 512, 576, 640, 704, 768, 832, 896]
        scales = compute_multi_scale_scales(resolution, expanded_scales, patch_size, num_windows)
        if skip_random_resize:
            scales = [scales[-1]]
        logger.info(f"Using multi-scale training with scales: {scales}")

    if image_set == "train":
        resolved_aug_config = aug_config if aug_config is not None else AUG_CONFIG
        resize_wrappers = AlbumentationsWrapper.from_config(
            _build_train_resize_config(scales, square=False, max_size=1333)
        )
        pipeline = [*resize_wrappers]
        if not gpu_postprocess:
            aug_wrappers = AlbumentationsWrapper.from_config(resolved_aug_config)
            pipeline += [*aug_wrappers]
        pipeline += [to_image, to_float]
        if not gpu_postprocess:
            pipeline += [normalize]
        return Compose(pipeline)

    if image_set in ("val", "test"):
        resize_wrappers = AlbumentationsWrapper.from_config(
            [
                {"SmallestMaxSize": {"max_size": resolution}},
                {"LongestMaxSize": {"max_size": 1333}},
            ]
        )
        return Compose([*resize_wrappers, to_image, to_float, normalize])
    if image_set == "val_speed":
        resize_wrappers = AlbumentationsWrapper.from_config([{"Resize": {"height": resolution, "width": resolution}}])
        return Compose([*resize_wrappers, to_image, to_float, normalize])

    raise ValueError(f"unknown {image_set}")

def get_focal_lengths(cls, meta: Dict) -> Tuple[float, float]:
        fl_x, fl_y = 0, 0

        def fov_to_focal_length(rad, res):
            return 0.5 * res / np.tan(0.5 * rad)

        if "fl_x" in meta:
            fl_x = meta["fl_x"]
        elif "x_fov" in meta:
            fl_x = fov_to_focal_length(np.deg2rad(meta["x_fov"]), meta["w"])
        elif "camera_angle_x" in meta:
            fl_x = fov_to_focal_length(meta["camera_angle_x"], meta["w"])

        if "camera_angle_y" not in meta or "y_fov" not in meta:
            fl_y = fl_x
        else:
            if "fl_y" in meta:
                fl_y = meta["fl_y"]
            elif "y_fov" in meta:
                fl_y = fov_to_focal_length(np.deg2rad(meta["y_fov"]), meta["h"])
            elif "camera_angle_y" in meta:
                fl_y = fov_to_focal_length(meta["camera_angle_y"], meta["h"])

        if fl_x == 0 or fl_y == 0:
            raise AttributeError("Focal length cannot be calculated from transforms.json (missing fields).")

        return (fl_x, fl_y)

def line(self, x0, y0, x1, y1, char):  # noqa: C901, PLR0912
        if x0 > x1:
            x1, x0 = x0, x1
            y1, y0 = y0, y1

        dx = x1 - x0
        dy = y1 - y0

        if dx == 0 and dy == 0:
            self.point(x0, y0, char)
        elif abs(dx) >= abs(dy):
            for x in range(x0, x1 + 1):
                if dx == 0:
                    y = y0
                else:
                    y = y0 + round((x - x0) * dy / float(dx))
                self.point(x, y, char)
        elif y0 < y1:
            for y in range(y0, y1 + 1):
                if dy == 0:
                    x = x0
                else:
                    x = x0 + round((y - y0) * dx / float(dy))
                self.point(x, y, char)
        else:
            for y in range(y1, y0 + 1):
                if dy == 0:
                    x = x0
                else:
                    x = x1 + round((y - y1) * dx / float(dy))
                self.point(x, y, char)

def get_cached_symbols(nm: str, build_root: Path) -> Dict[str, Symbol]:
    global symbols_cache

    if symbols_cache is not None:
        return symbols_cache
    symbols = {}

    if not build_root.is_dir():
        error("Specified buck-out is not a directory")

    for root, _, files in os.walk(build_root):
        root_path = Path(root)
        for file_name in files:
            file_path = root_path / file_name
            if file_path.suffix == OBJECT_SUFFIX:
                object_file_path = file_path
                source_file_name = object_file_path.name[: -len(OBJECT_SUFFIX)]

                object_file_rel = Path(os.path.relpath(object_file_path, build_root))
                if "codegen" in str(object_file_path):
                    source_file_path = source_file_name + " (generated)"
                else:
                    source_file_path = (
                        PROJECT_ROOT / object_file_rel.parent.parent / source_file_name
                    )
                get_object_symbols(nm, symbols, object_file_path, source_file_path)

    symbols_cache = symbols
    return symbols_cache

def pretty_format_edge(self, edge, width=None):
        if width is None:
            width = 50 // (self.num_leaves() + 1)
        (start, end) = (edge.start(), edge.end())

        str = "|" + ("." + " " * (width - 1)) * start

        # Zero-width edges are "#" if complete, ">" if incomplete
        if start == end:
            if edge.is_complete():
                str += "#"
            else:
                str += ">"

        # Spanning complete edges are "[===]"; Other edges are
        # "[---]" if complete, "[--->" if incomplete
        elif edge.is_complete() and edge.span() == (0, self._num_leaves):
            str += "[" + ("=" * width) * (end - start - 1) + "=" * (width - 1) + "]"
        elif edge.is_complete():
            str += "[" + ("-" * width) * (end - start - 1) + "-" * (width - 1) + "]"
        else:
            str += "[" + ("-" * width) * (end - start - 1) + "-" * (width - 1) + ">"

        str += (" " * (width - 1) + ".") * (self._num_leaves - end)
        return str + "| %s" % edge

def to_optional(optional: onnx.OptionalProto) -> Any | None:
    elem_type = optional.elem_type
    if elem_type == onnx.OptionalProto.UNDEFINED:
        return None
    if elem_type == onnx.OptionalProto.TENSOR:
        return to_array(optional.tensor_value)
    if elem_type == onnx.OptionalProto.SPARSE_TENSOR:
        return to_array(optional.sparse_tensor_value)  # type: ignore[arg-type]
    if elem_type == onnx.OptionalProto.SEQUENCE:
        return to_list(optional.sequence_value)
    if elem_type == onnx.OptionalProto.MAP:
        return to_dict(optional.map_value)
    if elem_type == onnx.OptionalProto.OPTIONAL:
        return to_optional(optional.optional_value)
    raise TypeError("The element type in the input optional is not supported.")

def create_default_roles(
        cls,
        entity: Entity = None,
        entity_id: str = None,
        name_func: Callable[[str], str] = None,
    ) -> None:
        if entity is None:
            entity = Entity.GLOBAL
        permissions = Permission.create_default_permissions(entity=entity, entity_id=entity_id)
        mapping = {
            cls.DefaultRole.OWNER: Permission.Access.OWNER,
            cls.DefaultRole.ADMIN: Permission.Access.ADMIN,
            cls.DefaultRole.EDITOR: Permission.Access.EDITOR,
            cls.DefaultRole.VIEWER: Permission.Access.VIEWER,
        }
        for name, access in mapping.items():
            role_name = name
            if name_func is not None:
                role_name = name_func(name)
            role = cls.query.filter(Role.name == role_name).first()
            if not role:
                cls.create(
                    name=role_name,
                    permissions=[
                        Permission.query.filter(
                            Permission.entity == entity,
                            Permission.entity_id == entity_id,
                            Permission.access == access,
                        ).first()
                    ],
                    commit=False,
                )
            elif permissions:
                permission = find(lambda p, a=access: p.access == a.value, permissions)
                if permission:
                    role.update(
                        permissions=role.permissions + [permission],
                        commit=False,
                    )

        db_connection.session.commit()

def visit_quantum_gate(self, node: ast.QuantumGate, context: Context):  # pragma: no cover
        name = node.name.name.upper()
        if name in PARAMETERIZED_GATES:
            if not node.arguments:
                raise TypeError(
                    f"Missing required argument(s) for parameterized gate {node.name.name}"
                )
            gates_dict = PARAMETERIZED_GATES
        elif name in NON_PARAMETERIZED_GATES:
            gates_dict = NON_PARAMETERIZED_GATES
        elif name in [n.upper() for n in context.scopes["custom_gates"].keys()]:
            self.execute_custom_gate(node, context)
            return
        else:
            raise NotImplementedError(f"Unsupported gate encountered in QASM: {node.name.name}")

        gate, args, wires = self._gate_setup_helper(node, gates_dict, context)
        num_control = sum("ctrl" in mod.modifier.name for mod in node.modifiers)
        op_wires = wires[num_control:]
        control_wires = wires[:num_control]

        op = gate(*args, wires=op_wires)
        for mod in reversed(node.modifiers):
            op, control_wires = self.apply_modifier(mod, op, context, control_wires)

def find_pattern_matches(
        self, nodes: Iterator[Node], quantization_config: QuantizationConfig
    ) -> Iterator[PatternMatchResult]:

        node = next(nodes, None)
        node_queue = []
        while node is not None:
            potential_matches = []
            node_queue.append(node)
            next_node = next(nodes, None)
            node_users = list(node.users)

            # If there is a fork or gap in the nodes iterator, empty the queue
            if (len(node_users) != 1) or (node_users[0] != next_node):
                while node_queue:
                    new_matches = self._dequeue_and_get_matches(
                        node_queue, quantization_config
                    )
                    potential_matches.extend(new_matches)

            # When que reach the max length, search for match starting at the front of the queue
            elif len(node_queue) >= self.max_pattern_len:
                potential_matches = self._dequeue_and_get_matches(
                    node_queue, quantization_config
                )

            # Report all pattern matches, also rejected ones for debugging purposes
            for match in potential_matches:
                yield match

            node = next_node

def fill_missing_values(self, method: str = "auto", value: float = 0.0) -> TimeSeriesDataFrame:
        # Convert to pd.DataFrame for faster processing
        df = pd.DataFrame(self)

        # Skip filling if there are no NaNs
        if not df.isna().any(axis=None):
            return self

        if not self.index.is_monotonic_increasing:
            logger.warning(
                "Trying to fill missing values in an unsorted dataframe. "
                "It is highly recommended to call `ts_df.sort_index()` before calling `ts_df.fill_missing_values()`"
            )

        grouped_df = df.groupby(level=self.ITEMID, sort=False, group_keys=False)
        if method == "auto":
            filled_df = grouped_df.ffill()
            # If necessary, fill missing values at the start of each time series with bfill
            if filled_df.isna().any(axis=None):
                filled_df = filled_df.groupby(level=self.ITEMID, sort=False, group_keys=False).bfill()
        elif method in ["ffill", "pad"]:
            filled_df = grouped_df.ffill()
        elif method in ["bfill", "backfill"]:
            filled_df = grouped_df.bfill()
        elif method == "constant":
            filled_df = self.fillna(value=value)
        elif method == "interpolate":
            filled_df = grouped_df.apply(lambda ts: ts.interpolate())
        else:
            raise ValueError(
                "Invalid fill method. Expecting one of "
                "{'auto', 'ffill', 'pad', 'bfill', 'backfill', 'constant', 'interpolate'}. "
                f"Got {method}"
            )
        return TimeSeriesDataFrame(filled_df, static_features=self.static_features)

def process_queue(
    queue: AnnotatedQueue,
) -> tuple[list[ops_or_meas], list["pennylane.measurements.MeasurementProcess"]]:
    lists = {"_ops": [], "_measurements": []}
    list_order = {"_ops": 1, "_measurements": 2}
    current_list = "_ops"

    # cant use for obj in queue.queue, as OperatorRecorder overrides the definition of queue
    # cant use for obj in queue, as QuantumTape overrides the definition of __iter__
    for obj, _ in queue.items():
        if not hasattr(obj, "_queue_category"):
            raise QueuingError(
                f"{obj} encountered in AnnotatedQueue and is not an object that can "
                "be processed into a QuantumScript. Queues should contain Operator or MeasurementProcess objects only."
            )
        if obj._queue_category is None:
            warnings.warn(
                "Preventing an object to get queued with `_queue_category=None` is deprecated.",
                PennyLaneDeprecationWarning,
            )
            continue

        if list_order[obj._queue_category] > list_order[current_list]:
            current_list = obj._queue_category
        elif list_order[obj._queue_category] < list_order[current_list]:
            raise ValueError(
                f"{obj._queue_category[1:]} operation {obj} must occur prior "
                f"to {current_list[1:]}. Please place earlier in the queue."
            )
        lists[obj._queue_category].append(obj)

    return lists["_ops"], lists["_measurements"]

def get_optimizer_and_scheduler(self, model, num_training_steps):
        if isinstance(model, torch.nn.DataParallel):
            model = model.module

        if isinstance(model, transformers.PreTrainedModel):
            # Reference https://huggingface.co/transformers/training.html
            param_optimizer = list(model.named_parameters())
            no_decay = ["bias", "LayerNorm.bias", "LayerNorm.weight"]
            optimizer_grouped_parameters = [
                {
                    "params": [
                        p
                        for n, p in param_optimizer
                        if not any(nd in n for nd in no_decay)
                    ],
                    "weight_decay": self.training_args.weight_decay,
                },
                {
                    "params": [
                        p for n, p in param_optimizer if any(nd in n for nd in no_decay)
                    ],
                    "weight_decay": 0.0,
                },
            ]

            optimizer = torch.optim.AdamW(
                optimizer_grouped_parameters, lr=self.training_args.learning_rate
            )
            if isinstance(self.training_args.num_warmup_steps, float):
                num_warmup_steps = math.ceil(
                    self.training_args.num_warmup_steps * num_training_steps
                )
            else:
                num_warmup_steps = self.training_args.num_warmup_steps

            scheduler = transformers.optimization.get_linear_schedule_with_warmup(
                optimizer,
                num_warmup_steps=num_warmup_steps,
                num_training_steps=num_training_steps,
            )
        else:
            optimizer = torch.optim.Adam(
                filter(lambda x: x.requires_grad, model.parameters()),
                lr=self.training_args.learning_rate,
            )
            scheduler = None

        return optimizer, scheduler

def dot(tensor1, tensor2, like=None):
    x, y = np.coerce([tensor1, tensor2], like=like)

    if like == "torch":

        if x.ndim == 0 or y.ndim == 0:
            return x * y

        if x.ndim <= 2 and y.ndim <= 2:
            return x @ y

        return np.tensordot(x, y, axes=[[-1], [-2]], like=like)

    if like in {"tensorflow", "autograd"}:

        ndim_y = len(np.shape(y))
        ndim_x = len(np.shape(x))

        if ndim_x == 0 or ndim_y == 0:
            return x * y

        if ndim_y == 1:
            return np.tensordot(x, y, axes=[[-1], [0]], like=like)

        if ndim_x == 2 and ndim_y == 2:
            return x @ y

        return np.tensordot(x, y, axes=[[-1], [-2]], like=like)

    if like == "scipy":
        # See https://github.com/scipy/scipy/issues/18938 for the issue
        # with scipy sparse and np dot product

        # Avoid the case when one is a scalar - using a robust check for scalars
        if onp.isscalar(x) or onp.isscalar(y):
            return x * y
        return x.dot(y)
    return np.dot(x, y, like=like)

def forward(
        self,
        input_values: torch.Tensor,
        padding_mask: torch.Tensor | None = None,
        num_quantizers: int | None = None,
        audio_codes: torch.Tensor | None = None,
        encoder_past_key_values: Cache | None = None,
        decoder_past_key_values: Cache | None = None,
        return_dict: bool | None = None,
        **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor] | MimiOutput:
        return_dict = return_dict if return_dict is not None else self.config.return_dict

        if padding_mask is None:
            padding_mask = torch.ones_like(input_values).bool()

        if audio_codes is None:
            encoder_outputs = self.encode(
                input_values, padding_mask, num_quantizers, encoder_past_key_values, return_dict=return_dict
            )
            audio_codes = encoder_outputs[0]
            if return_dict:
                encoder_past_key_values = encoder_outputs.get("past_key_values")
            elif len(encoder_outputs) > 1:
                encoder_past_key_values = encoder_outputs[1]

        decoder_outputs = self.decode(audio_codes, padding_mask, decoder_past_key_values, return_dict=return_dict)
        audio_values = decoder_outputs[0]
        if return_dict:
            decoder_past_key_values = decoder_outputs.get("past_key_values")
        elif len(decoder_outputs) > 1:
            decoder_past_key_values = decoder_outputs[1]

        if not return_dict:
            return (audio_codes, audio_values, encoder_past_key_values, decoder_past_key_values)

        return MimiOutput(
            audio_codes=audio_codes,
            audio_values=audio_values,
            encoder_past_key_values=encoder_past_key_values,
            decoder_past_key_values=decoder_past_key_values,
        )

def kill(self):
        if self._proc is not None:
            # allow gracefully shutdown
            try:
                self._writer.close()
            except OSError:
                pass
            try:
                self._reader.close()
            except OSError:
                pass
            # kill all child processes recursively
            try:
                kill_child_processes(self._proc.pid)
            except TypeError:
                pass
            try:
                self._proc.kill()
            except OSError:
                pass

            # Join the child process to avoid zombie processes
            self.join(timeout=1.0)
            self._proc = None
            self._remaining_uses = None

def flatten(self, depth=1, traversable=lambda node, edge: True, _visited=None):
        _visited = _visited or {}
        _visited[self.id] = (self, depth)
        if depth >= 1:
            for n in self.links:
                if n.id not in _visited or _visited[n.id][1] < depth - 1:
                    if traversable(self, self.links.edges[n.id]):
                        n.flatten(depth - 1, traversable, _visited)
        return [n for n, d in _visited.values()] # Fast, but not order-preserving.

def model_hyperparameters(
        self,
        model: str,
        include_ag_args_ensemble: bool = True,
        output_format: Literal["user", "all"] = "user",
    ) -> dict:
        # TODO: Move logic into trainer?
        info_model = self.model_info(model=model)
        if output_format == "user":
            if "bagged_info" in info_model:
                hyperparameters = info_model["bagged_info"]["child_hyperparameters_user"].copy()
                if include_ag_args_ensemble and info_model["hyperparameters_user"]:
                    hyperparameters["ag_args_ensemble"] = info_model["hyperparameters_user"]
            else:
                hyperparameters = info_model["hyperparameters_user"]
        elif output_format == "all":
            if "bagged_info" in info_model:
                hyperparameters = info_model["bagged_info"]["child_hyperparameters"].copy()
                if info_model["bagged_info"]["child_ag_args_fit"]:
                    hyperparameters["ag_args_fit"] = info_model["bagged_info"]["child_ag_args_fit"]
                if include_ag_args_ensemble:
                    bag_hyperparameters = info_model["hyperparameters"].copy()
                    if info_model["ag_args_fit"]:
                        bag_hyperparameters["ag_args_fit"] = info_model["ag_args_fit"]
                    if bag_hyperparameters:
                        hyperparameters["ag_args_ensemble"] = bag_hyperparameters
            else:
                hyperparameters = info_model["hyperparameters"]
        else:
            raise ValueError(f"output_format={output_format} is unknown!")
        return hyperparameters

def resize_video_frames(video_frames: np.ndarray, dsize=None, fx=None, fy=None) -> np.ndarray:
    # Convert to list for batch processing
    frame_list = [frame for frame in video_frames if frame is not None and frame.size > 0]

    if not frame_list:
        raise ValueError("No valid frames found. Check your video data and resize parameters.")

    # Calculate target sizes for each frame
    if dsize is not None:
        # Fixed size for all frames
        target_sizes = [dsize] * len(frame_list)
    elif fx is not None and fy is not None:
        # Calculate sizes based on scaling factors
        target_sizes = []
        for frame in frame_list:
            h, w = frame.shape[:2]
            new_w = int(w * fx)
            new_h = int(h * fy)
            target_sizes.append((new_w, new_h))
    else:
        raise ValueError("Either dsize or both fx and fy must be provided")

    # Use high-performance batch resize (2.4x faster than individual calls)
    resized_frames = tsr.batch_resize_images_zero_copy(frame_list, target_sizes)

    return np.stack(resized_frames, axis=0)

def get_cudnn_version():
    def find_cudnn_in_headers(candiates):
        for c in candidates:
            file = glob.glob(c)
            if file:
                break
        if file:
            with open(file[0], "r") as f:
                version = ""
                for line in f:
                    if "#define CUDNN_MAJOR" in line:
                        version = line.split()[-1]
                    if "#define CUDNN_MINOR" in line:
                        version += "." + line.split()[-1]
                    if "#define CUDNN_PATCHLEVEL" in line:
                        version += "." + line.split()[-1]
            if version:
                return version
            else:
                return None
        else:
            return None

    try:
        import torch

        return str(torch.backends.cudnn.version())
    except (ImportError, ModuleNotFoundError):
        if sys.platform == "win32":
            candidates = [r"C:\NVIDIA\cuda\include\cudnn.h"]
        elif sys.platform == "linux":
            candidates = [
                "/usr/include/cudnn_version.h",
                "/usr/include/x86_64-linux-gnu/cudnn_v[0-99].h",
                "/usr/local/cuda/include/cudnn.h",
                "/usr/include/cudnn.h",
            ]
        elif sys.platform == "darwin":
            candidates = ["/usr/local/cuda/include/cudnn.h", "/usr/include/cudnn.h"]
        else:
            raise ValueError("Not in Windows, Linux or Mac")
        return find_cudnn_in_headers(candidates)

def KORNIA_CHECK_SHAPE(x: torch.Tensor, shape: list[str], msg: Optional[str] = None, raises: bool = True) -> bool:
    if not torch.jit.is_scripting():
        if not _KORNIA_CHECKS_ENABLED:
            return True

    if "*" == shape[0]:
        shape_to_check = shape[1:]
        x_shape_to_check = x.shape[-len(shape) + 1 :]
    elif "*" == shape[-1]:
        shape_to_check = shape[:-1]
        x_shape_to_check = x.shape[: len(shape) - 1]
    else:
        shape_to_check = shape
        x_shape_to_check = x.shape

    if len(x_shape_to_check) != len(shape_to_check):
        if raises:
            expected_dims = len(shape_to_check)
            actual_dims = len(x_shape_to_check)
            error_msg = f"Shape dimension mismatch: expected {expected_dims} dimensions, got {actual_dims}.\n"
            error_msg += f"  Expected shape: {shape}\n"
            x_shape_list = list(x.shape)
            error_msg += f"  Actual shape: {x_shape_list}"
            if msg is not None:
                error_msg += f"\n  {msg}"
            raise ShapeError(
                error_msg,
                actual_shape=x_shape_list,
                expected_shape=shape,
            )
        else:
            return False

    for i in range(len(x_shape_to_check)):
        # The voodoo below is because torchscript does not like
        # that dim can be both int and str
        dim_: str = shape_to_check[i]
        if not dim_.isnumeric():
            continue
        dim = int(dim_)
        if x_shape_to_check[i] != dim:
            if raises:
                error_msg = f"Shape mismatch at dimension {i}: expected {dim}, got {x_shape_to_check[i]}.\n"
                error_msg += f"  Expected shape: {shape}\n"
                x_shape_list = list(x.shape)
                error_msg += f"  Actual shape: {x_shape_list}"
                if msg is not None:
                    error_msg += f"\n  {msg}"
                raise ShapeError(
                    error_msg,
                    actual_shape=x_shape_list,
                    expected_shape=shape,
                )
            else:
                return False
    return True

def subselect_rows_by_indices(self, indices):
        kwargs = {"data": self.data}
        for augm_name in _AUGMENTABLE_NAMES:
            rows = getattr(self, augm_name)
            if rows is not None:
                if augm_name == "images" and ia.is_np_array(rows):
                    rows = rows[indices]  # pylint: disable=unsubscriptable-object
                else:
                    rows = [rows[index] for index in indices]

                if len(rows) == 0:
                    rows = None
            kwargs[augm_name] = rows

        return _BatchInAugmentation(**kwargs)

