def infer_schema(example, binary_features=[]):
  def _infer_sql_type(k, v):
    # special handling for binary features
    if k in binary_features:
      return BinaryType()

    if v.int64_list.value:
      result = v.int64_list.value
      sql_type = LongType()
    elif v.float_list.value:
      result = v.float_list.value
      sql_type = DoubleType()
    else:
      result = v.bytes_list.value
      sql_type = StringType()

    if len(result) > 1:             # represent multi-item tensors as Spark SQL ArrayType() of base types
      return ArrayType(sql_type)
    else:                           # represent everything else as base types (and empty tensors as StringType())
      return sql_type

  return StructType([StructField(k, _infer_sql_type(k, v), True) for k, v in sorted(example.features.feature.items())])

def resolve(self, value):
        if value is None:
            if self.allow_none:
                return None
            return None

        # Already a config instance
        if isinstance(value, LudwigBaseConfig):
            return value

        if self.allow_str_value and isinstance(value, str):
            value = self.str_value_to_object(value)

        if isinstance(value, dict):
            cls_type = value.get(self.key)
            cls_type = cls_type.lower() if cls_type else self.default_value
            if cls_type and cls_type in self.registry:
                cls = self.get_schema_from_registry(cls_type)
                try:
                    return cls.model_validate(value)
                except (TypeError, PydanticValidationError) as e:
                    raise ConfigValidationError(f"Invalid params: {value}, see `{cls}` definition") from e
            raise ConfigValidationError(f"Invalid type: '{cls_type}', expected one of: {list(self.registry.keys())}")

        maybe_str = ", `str`," if self.allow_str_value else ""
        raise ConfigValidationError(f"Invalid param {value}, expected `None`{maybe_str} or `dict`")

def validate_function_output(processed_inputs):
            allowed_processed_inputs_types = (Mapping, pa.Table, pd.DataFrame)
            if config.POLARS_AVAILABLE and "polars" in sys.modules:
                import polars as pl

                allowed_processed_inputs_types += (pl.DataFrame,)
            if processed_inputs is not None and not isinstance(processed_inputs, allowed_processed_inputs_types):
                raise TypeError(
                    f"Provided `function` which is applied to all elements of table returns a variable of type {type(processed_inputs)}. Make sure provided `function` returns a variable of type `dict` (or a pyarrow table) to update the dataset or `None` if you are only interested in side effects."
                )
            if batched and isinstance(processed_inputs, Mapping):
                allowed_batch_return_types = (list, np.ndarray, pd.Series)
                if config.POLARS_AVAILABLE and "polars" in sys.modules:
