                    )

def parse_backend_error_messages(response: Response) -> list[str]:
    from requests import JSONDecodeError

    try:
        data = response.json()
    except JSONDecodeError:
        return []

    if not isinstance(data, dict):
        return []

    # Backend error values are returned in one of two ways:
    # - A string containing the error message
    # - A JSON object with a "message" field that is a string
    def get_message(error: Any) -> str | None:
        if isinstance(error, str):
            return error
        elif (
            isinstance(error, dict)
            and (message := error.get("message"))
            and isinstance(message, str)
        ):
            return message
        else:
            return None

    # The response can contain an "error" field with a single error
    # or an "errors" field with a list of errors.
    if error := data.get("error"):
        message = get_message(error)
        return [message] if message else []

    elif (errors := data.get("errors")) and isinstance(errors, list):
        messages: list[str] = []
        for error in errors:
            message = get_message(error)
            if message:
                messages.append(message)
        return messages

    else:
        return []

def infer_devices(devices: DevicesSpecification) -> tuple[torch.device, ...]:
    exclude_devices = {
        d.strip()
        for d in os.getenv("TABPFN_EXCLUDE_DEVICES", "").split(",")
        if d.strip()
    }

    if devices == "auto":
        if "cuda" not in exclude_devices and torch.cuda.is_available():
            return tuple(
                torch.device(f"cuda:{i}") for i in range(torch.cuda.device_count())
            )

        if _is_mps_supported() and "mps" not in exclude_devices:
            return (torch.device("mps"),)

        return (torch.device("cpu"),)

    if isinstance(devices, (str, torch.device)):
        devices = (devices,)

    devices = tuple(_parse_device(device) for device in devices)

    if len(set(devices)) != len(devices):
        raise ValueError(
            "The list of devices for inference cannot contain the same device more "
            f"than once. It contained: {devices}"
        )

    if not _is_mps_supported() and any(d.type == "mps" for d in devices):
        raise ValueError(
            "The MPS device was selected, "
            "but this is not supported by TabPFN before PyTorch 2.5. "
            'Set `device="cpu"` instead.'
        )

    return devices

def analyze_pipes(
    nlp: "Language", *, keys: List[str] = DEFAULT_KEYS
) -> Dict[str, Dict[str, Union[List[str], Dict]]]:
    result: Dict[str, Dict[str, Union[List[str], Dict]]] = {
        "summary": {},
        "problems": {},
    }
    all_attrs: Set[str] = set()
    for i, name in enumerate(nlp.pipe_names):
        meta = nlp.get_pipe_meta(name)
        all_attrs.update(meta.assigns)
        all_attrs.update(meta.requires)
        result["summary"][name] = {key: getattr(meta, key, None) for key in keys}
        prev_pipes = nlp.pipeline[:i]
        requires = dict.fromkeys(meta.requires, False)
        if requires:
            for prev_name, prev_pipe in prev_pipes:
                prev_meta = nlp.get_pipe_meta(prev_name)
                for annot in prev_meta.assigns:
                    requires[annot] = True
        result["problems"][name] = [
            annot for annot, fulfilled in requires.items() if not fulfilled
        ]
    result["attrs"] = {attr: get_attr_info(nlp, attr) for attr in all_attrs}
    return result

def from_profiles_yml(
        cls: Type[Self],
        profile_name: Optional[str] = None,
        target_name: Optional[str] = None,
        profiles_dir: Optional[str] = None,
        allow_field_overrides: bool = False,
    ) -> "TargetConfigs":
        if profiles_dir:
            profiles = PrefectDbtSettings(
                profiles_dir=Path(profiles_dir)
            ).load_profiles_yml()
        else:
            profiles = PrefectDbtSettings().load_profiles_yml()

        # If no profile specified, use first non-config one
        if profile_name is None:
            for name in profiles:
                if name != "config":
                    profile_name = name
                    break
        elif profile_name not in profiles:
            raise ValueError(f"Profile {profile_name} not found in profiles.yml")

        profile = profiles[profile_name]
        if "outputs" not in profile:
            raise ValueError(f"No outputs found in profile {profile_name}")

        outputs = profile["outputs"]

        # If no target specified, use default target
        if target_name is None:
            target_name = profile["target"]
        elif target_name not in outputs:
            raise ValueError(
                f"Target {target_name} not found in profile {profile_name}"
            )

        target_config = outputs[target_name]

        type = target_config.pop("type")
        schema = None
        possible_keys = ["schema", "path", "dataset", "database"]
        for key in possible_keys:
            if key in target_config:
                schema = target_config.pop(key)
                break

        if schema is None:
            raise ValueError(f"No schema found. Expected one of: {possible_keys}")
        threads = target_config.pop("threads", 4)
        return cls(
            type=type,
            schema=schema,
            threads=threads,
            extras=target_config or None,
            allow_field_overrides=allow_field_overrides,
        )

def parse_input_args(input_str: str):
    output_dict = {}
    if not input_str:
        raise ValueError("Empty input string: {}".format(input_str))

    key_pairs: list = input_str.split(",")

    key_pairs = [x.strip() for x in key_pairs]

    if not key_pairs:
        raise ValueError("Incorrect format: {}".format(input_str))

    for each_key in key_pairs:
        try:
            key, value = each_key.split("=")
        except ValueError as value_error:
            raise ValueError("Expected input format "
                             "'key1=value1, key2=value2' "
                             "but received {}".format(input_str)) \
                from value_error
        if value.isdigit():
            value = int(value)
        output_dict[key] = value

    return output_dict

def reshape_outputs(model, nc):
        name, m = list((model.model if hasattr(model, "model") else model).named_children())[-1]  # last module
        if isinstance(m, Classify):  # YOLO Classify() head
            if m.linear.out_features != nc:
                m.linear = torch.nn.Linear(m.linear.in_features, nc)
        elif isinstance(m, torch.nn.Linear):  # ResNet, EfficientNet
            if m.out_features != nc:
                setattr(model, name, torch.nn.Linear(m.in_features, nc))
        elif isinstance(m, torch.nn.Sequential):
            types = [type(x) for x in m]
            if torch.nn.Linear in types:
                i = len(types) - 1 - types[::-1].index(torch.nn.Linear)  # last torch.nn.Linear index
                if m[i].out_features != nc:
                    m[i] = torch.nn.Linear(m[i].in_features, nc)
            elif torch.nn.Conv2d in types:
                i = len(types) - 1 - types[::-1].index(torch.nn.Conv2d)  # last torch.nn.Conv2d index
                if m[i].out_channels != nc:
                    m[i] = torch.nn.Conv2d(
                        m[i].in_channels, nc, m[i].kernel_size, m[i].stride, bias=m[i].bias is not None
                    )

def convert_processed_lines(processed_lines):
    paragraphs = []
    sentences = []
    for words in processed_lines:
        # turn the words into a sentence
        if len(words) > 1 and " " == words[0]:
            words = words[1:]
        elif len(words) == 1 and " " == words[0]:
            words = []

        sentence = []
        for word in words:
            word = word.strip()
            if not word:
                if len(sentence) == 0:
                    print(word)
                    raise ValueError("Unexpected space at start of sentence in document {}".format(filename))
                sentence[-1] = (sentence[-1][0], True)
            else:
                sentence.append((word, False))
        # blank lines are very rare in best, but why not treat them as a paragraph break
        if len(sentence) == 0:
            paragraphs.append([sentences])
            sentences = []
            continue
        sentence[-1] = (sentence[-1][0], True)
        sentences.append(sentence)
    paragraphs.append([sentences])
    return paragraphs

def infer_sparsity_amount_from_external_mask(self, external_mask: _torch.Tensor) -> float:
        if hasattr(self, "granularity"):
            # rank 2: torch.Linear, rank 3: torch.Conv1d, rank 4: torch.Conv2d, rank 5: torch.Conv3d
            rank = len(external_mask.shape)

            if self.granularity == "per_scalar" or rank == 2:
                return external_mask.eq(0).float().mean().item()
            elif rank in [3, 4, 5]:
                if self.granularity == "per_kernel":
                    start_dim = 2
                elif self.granularity == "per_channel":
                    start_dim = 1
                else:
                    raise ValueError(
                        f"Can not infer sparsity amount for granularity: {self.granularity}"
                    )
                return external_mask.flatten(start_dim).eq(0).all(-1).float().mean().item()
            else:
                raise ValueError(f"weights tensor rank must be in [2, 3, 4, 5], got {rank}")

def get_model(args):
    with torch.no_grad():
        model = (
            AutoModelForCausalLM.from_pretrained(
                args.model,
                use_cache=False,
                attn_implementation="sdpa",
                ignore_mismatched_sizes=True,
            )
            .eval()
            .cuda()
        )
        # register SDPA variant for the model
        register_sdpa.enable_sdpa_converter(args.model, model.config)

    hf_quant_config = load_quantization_config(args.model)
    if hf_quant_config:
        model = convert_linear_to_tensorrt_quantized(
            model, args.model_precision, hf_quant_config
        ).cuda()
        print(
            f"Model is {hf_quant_config['quant_algo']} pre-quantized hf model. Quantized linear layers are applied"
        )
        if args.quant_format:
            raise RuntimeError(
                f"Quantization cannot be applied for pre-quantized hf model"
            )

    if args.model_precision == "FP16":
        model = model.to(torch.float16)
    elif args.model_precision == "BF16":
        model = model.to(torch.bfloat16)
    else:
        model = model.to(torch.float32)

    return model

def is_quantized(node: torch.fx.Node) -> bool:
    try:
        node_dtype = get_first_fake_tensor(node).dtype
        # Integer-like dtype implies the node is already quantized as long
        # as inputs are not floating-point.
        if _is_integer_dtype(node_dtype):
            input_nodes = node.all_input_nodes
            input_nodes_dtypes = [
                get_first_fake_tensor(input_node).dtype for input_node in input_nodes
            ]
            if all(
                _is_integer_dtype(input_node_dtype)
                for input_node_dtype in input_nodes_dtypes
            ):
                return True

    except TypeError:
        # Could not determine dtype, fall back to other checks.
        pass

    # Nodes introduced during lowering that exclusively feed quantized users.
    if _is_quantized_constant(node):
        return True

    # Finally, fall back to the explicit annotation emitted by Arm passes.
    custom_meta = node.meta.get("custom", {})
    if ArmAnnotationInfo.CUSTOM_META_KEY in custom_meta:
        return custom_meta[ArmAnnotationInfo.CUSTOM_META_KEY]["quantized"]

    return False

def plot_regret(*args, **kwargs):
    # <3 legacy python
    ax = kwargs.get("ax", None)
    true_minimum = kwargs.get("true_minimum", None)
    yscale = kwargs.get("yscale", None)

    if ax is None:
        ax = plt.gca()

    ax.set_title("Cumulative regret plot")
    ax.set_xlabel("Number of calls $n$")
    ax.set_ylabel(r"$\sum_{i=0}^n(f(x_i) - optimum)$ after $n$ calls")
    ax.grid()

    if yscale is not None:
        ax.set_yscale(yscale)

    colors = cm.viridis(np.linspace(0.25, 1.0, len(args)))

    if true_minimum is None:
        results = []
        for res in args:
            if isinstance(res, tuple):
                res = res[1]

            if isinstance(res, OptimizeResult):
                results.append(res)
            elif isinstance(res, list):
                results.extend(res)
        true_minimum = np.min([np.min(r.func_vals) for r in results])

    for results, color in zip(args, colors):
        if isinstance(results, tuple):
            name, results = results
        else:
            name = None

        if isinstance(results, OptimizeResult):
            n_calls = len(results.x_iters)
            regrets = [np.sum(results.func_vals[:i] - true_minimum)
                       for i in range(1, n_calls + 1)]
            ax.plot(range(1, n_calls + 1), regrets, c=color,
                    marker=".", markersize=12, lw=2, label=name)

        elif isinstance(results, list):
            n_calls = len(results[0].x_iters)
            iterations = range(1, n_calls + 1)
            regrets = [[np.sum(r.func_vals[:i] - true_minimum) for i in
                        iterations] for r in results]

            for cr in regrets:
                ax.plot(iterations, cr, c=color, alpha=0.2)

            ax.plot(iterations, np.mean(regrets, axis=0), c=color,
                    marker=".", markersize=12, lw=2, label=name)

    if name:
        ax.legend(loc="best")

    return ax

def filter_services_by_price(
    services: List[Dict[str, Any]], max_price: int
) -> List[Dict[str, Any]]:
    filtered = []
    for item in services:
        accepts = item.get("accepts", [])
        for accept in accepts:
            max_amount_str = accept.get("maxAmountRequired", "")
            if max_amount_str:
                try:
                    max_amount = int(max_amount_str)
                    if max_amount <= max_price:
                        filtered.append(item)
                        break  # Only add item once if any payment option matches
                except (ValueError, TypeError):
                    continue
    return filtered

def get_spark_session(spark_config: SparkConfig):
    if not SPARK_ENABLED:
        raise ImportError('Spark is not supported in current environment.')

    if spark_config:
        active_session = SparkSession.getActiveSession()
        print('Check the given spark_config against the active Spark session.')
        if spark_config.use_custom_session or has_same_spark_config(
            spark_session=active_session,
            spark_config=spark_config,
        ):
            print('Reuse the active Spark session.')
            return active_session
        else:
            print('Create a new Spark session.')
            if active_session:
                active_session.stop()
            conf = SparkConf()
            if spark_config.app_name:
                conf.setAppName(spark_config.app_name)
            if spark_config.spark_master:
                conf.setMaster(spark_config.spark_master)
            if spark_config.spark_home:
                conf.setSparkHome(spark_config.spark_home)
            if spark_config.executor_env:
                env_kv_pairs = list(spark_config.executor_env.items())
                conf.setExecutorEnv(key=None, value=None, pairs=env_kv_pairs)
            if spark_config.spark_jars:
                conf.set('spark.jars', ','.join(spark_config.spark_jars))
            if spark_config.others:
                others_kv_pairs = list(spark_config.others.items())
                conf.setAll(others_kv_pairs)

            return SparkSession.builder.config(conf=conf).getOrCreate()
    else:
        return SparkSession.builder.master(
            os.getenv('SPARK_MASTER_HOST', 'local')).getOrCreate()

def cleanup(self):
        try:
            # Reset agent statuses
            for agent in self.agents:
                if hasattr(agent, "cleanup"):
                    try:
                        agent.cleanup()
                    except Exception as e:
                        logger.warning(
                            f"Failed to cleanup agent {agent.agent_name}: {str(e)}"
                        )

            # Clear conversation if needed
            if hasattr(self, "conversation"):
                # Keep the conversation for result formatting but reset for next run
                pass

        except Exception as e:
            logger.error(f"Cleanup failed: {str(e)}")

def get_components(self) -> Dict[str, np.ndarray]:
        if self.model_ is None:
            raise ValueError("Model has not been fitted. Call fit() first.")

        res = self.model_["results"]
        components = {}

        # Try to extract each component
        if hasattr(res, "level") and res.level is not None:
            components["level"] = res.level.smoothed

        if hasattr(res, "trend") and res.trend is not None:
            components["trend"] = res.trend.smoothed

        if hasattr(res, "seasonal") and res.seasonal is not None:
            components["seasonal"] = res.seasonal.smoothed

        if hasattr(res, "cycle") and res.cycle is not None:
            components["cycle"] = res.cycle.smoothed

        if hasattr(res, "autoregressive") and res.autoregressive is not None:
            components["autoregressive"] = res.autoregressive.smoothed

        return components

def git_check_submodules() -> None:
    # Provide an option to skip these checks for development.
    if bool(int(os.getenv("NVTE_SKIP_SUBMODULE_CHECKS_DURING_BUILD", "0"))):
        return

    # Require git executable.
    if shutil.which("git") is None:
        return

    # Require a .gitmodules file.
    if not (current_file_path / ".gitmodules").exists():
        return

    try:
        submodules = subprocess.check_output(
            ["git", "submodule", "status", "--recursive"],
            cwd=str(current_file_path),
            text=True,
        ).splitlines()

        for submodule in submodules:
            # '-' start is for an uninitialized submodule.
            # ' ' start is for a submodule on the correct commit.
            assert submodule[0] in (
                " ",
                "-",
            ), (
                "Submodules are initialized incorrectly. If this is intended, set the "
                "environment variable `NVTE_SKIP_SUBMODULE_CHECKS_DURING_BUILD` to a "
                "non-zero value to skip these checks during development. Otherwise, "
                "run `git submodule update --init --recursive` to checkout the correct"
                " submodule commits."
            )

        subprocess.check_call(
            ["git", "submodule", "update", "--init", "--recursive"],
            cwd=str(current_file_path),
        )
    except subprocess.CalledProcessError:
        return

def resolve_annotation(annotation: Any) -> Any:
  # handle forward reference string

  # if this is an Ai Platform resource noun
  if inspect.isclass(annotation):
    if issubclass(annotation, aiplatform.base.VertexAiResourceNoun):
      return annotation

  # if this is a union of all typed datasets annotation
  if annotation is dataset_annotation:
    # return the catch all Dataset class
    return aiplatform.datasets.dataset._Dataset

  # handle forward references
  resolved_annotation = get_forward_reference(annotation)
  if resolved_annotation:
    return resolved_annotation

  # handle optional types
  if getattr(annotation, '__origin__', None) is Union:
    # assume optional type
    # TODO check for optional type
    resolved_annotation = get_forward_reference(annotation.__args__[0])
    if resolved_annotation:
      return resolved_annotation
    else:
      return annotation.__args__[0]

  if annotation is inspect._empty:
    return None

  return annotation

def regularize_cost(regex, func, name='regularize_cost'):
    assert len(regex)
    ctx = get_current_tower_context()
    if not ctx.is_training:
        # Currently cannot build the wd_cost correctly at inference,
        # because ths vs_name used in inference can be '', therefore the
        # variable filter will fail
        return tf.constant(0, dtype=tf.float32, name='empty_' + name)

    # If vars are shared, regularize all of them
    # If vars are replicated, only regularize those in the current tower
    if ctx.has_own_variables:
        params = ctx.get_collection_in_tower(tfv1.GraphKeys.TRAINABLE_VARIABLES)
    else:
        params = tfv1.trainable_variables()

    names = []

    with tfv1.name_scope(name + '_internals'):
        costs = []
        for p in params:
            para_name = p.op.name
            if re.search(regex, para_name):
                regloss = func(p)
                assert regloss.dtype.is_floating, regloss
                # Some variables may not be fp32, but it should
                # be fine to assume regularization in fp32
                if regloss.dtype != tf.float32:
                    regloss = tf.cast(regloss, tf.float32)
                costs.append(regloss)
                names.append(p.name)
        if not costs:
            return tf.constant(0, dtype=tf.float32, name='empty_' + name)

    # remove tower prefix from names, and print
    if len(ctx.vs_name):
        prefix = ctx.vs_name + '/'
        prefixlen = len(prefix)

        def f(name):
            if name.startswith(prefix):
                return name[prefixlen:]
            return name
        names = list(map(f, names))
    logger.info("regularize_cost() found {} variables to regularize.".format(len(names)))
    _log_once("The following tensors will be regularized: {}".format(', '.join(names)))

    return tf.add_n(costs, name=name)

def format_table(headers: list[str], rows: list[list[str]], col_widths: list[int] | None = None) -> str:
    if col_widths is None:
        col_widths = [len(h) for h in headers]
        for row in rows:
            for i, cell in enumerate(row):
                if i < len(col_widths):
                    col_widths[i] = max(col_widths[i], len(cell))

    def fmt_row(cells: list[str]) -> str:
        parts = []
        for i, cell in enumerate(cells):
            w = col_widths[i] if i < len(col_widths) else len(cell)
            parts.append(cell.ljust(w))
        return "  ".join(parts)

    lines = [fmt_row(headers), "  ".join("-" * w for w in col_widths)]
    for row in rows:
        lines.append(fmt_row(row))
    return "\n".join(lines)

def get_schemas_openai(items: List[Callable]) -> List[Dict[str, Any]]:
    schemas = []
    for item in items:
        if not callable(item):
            raise ValueError("Provided item must be a callable function.")

        # Use the existing get_schema function to get the basic schema
        basic_schema = get_schema(item)

        # Initialize the function schema with basic details
        function_schema = {
            "name": basic_schema["name"],
            "description": basic_schema["description"],
            "parameters": {"type": "object", "properties": {}, "required": []},
        }

        # Extract parameter details from the signature
        signature = inspect.signature(item)
        docstring = inspect.getdoc(item)
        param_doc_regex = re.compile(r":param (\w+):(.*?)\n(?=:\w|$)", re.S)
        doc_params = param_doc_regex.findall(docstring) if docstring else []

        for param_name, param in signature.parameters.items():
            param_type = (
                param.annotation.__name__
                if param.annotation != inspect.Parameter.empty
                else "Any"
            )
            param_description = "No description available."
            param_required = param.default is inspect.Parameter.empty

            # Find the parameter description in the docstring
            for doc_param_name, doc_param_desc in doc_params:
                if doc_param_name == param_name:
                    param_description = doc_param_desc.strip()
                    break

            function_schema["parameters"]["properties"][param_name] = {
                "type": convert_python_type_to_json_type(param_type),
                "description": param_description,
            }

            if param_required:
                function_schema["parameters"]["required"].append(param_name)

        schemas.append({"type": "function", "function": function_schema})

    return schemas

def delete_files_created_by_app(blocks: Blocks, age: int | None) -> None:
    dont_delete = set()

    for component in blocks.blocks.values():
        dont_delete.update(getattr(component, "keep_in_cache", set()))
    for temp_set in blocks.temp_file_sets:
        # We use a copy of the set to avoid modifying the set while iterating over it
        # otherwise we would get an exception: Set changed size during iteration
        to_remove = set()
        for file in temp_set:
            if file in dont_delete:
                continue
            try:
                file_path = Path(file)
                modified_time = datetime.fromtimestamp(file_path.lstat().st_ctime)
                if (
                    age is None
                    or (datetime.now() - modified_time).total_seconds() > age
                ):
                    os.remove(file)
                    to_remove.add(file)
            except FileNotFoundError:
                continue
        temp_set -= to_remove

def print_cycles(objects, outstream=sys.stdout, show_progress=False):
    import gc

    def print_path(path):
        for i, step in enumerate(path):
            # next "wraps around"
            next = path[(i + 1) % len(path)]

            outstream.write("   %s -- " % type(step))
            if isinstance(step, dict):
                for key, val in step.items():
                    if val is next:
                        outstream.write(f"[{key!r}]")
                        break
                    if key is next:
                        outstream.write(f"[key] = {val!r}")
                        break
            elif isinstance(step, list):
                outstream.write("[%d]" % step.index(next))
            elif isinstance(step, tuple):
                outstream.write("( tuple )")
            else:
                outstream.write(repr(step))
            outstream.write(" ->\n")
        outstream.write("\n")

    def recurse(obj, start, all, current_path):
        if show_progress:
            outstream.write("%d\r" % len(all))

        all[id(obj)] = None

        referents = gc.get_referents(obj)
        for referent in referents:
            # If we've found our way back to the start, this is
            # a cycle, so print it out
            if referent is start:
                print_path(current_path)

            # Don't go back through the original list of objects, or
            # through temporary references to the object, since those
            # are just an artifact of the cycle detector itself.
            elif referent is objects or isinstance(referent, types.FrameType):
                continue

            # We haven't seen this object before, so recurse
            elif id(referent) not in all:
                recurse(referent, start, all, current_path + [obj])

    for obj in objects:
        outstream.write(f"Examining: {obj!r}\n")
        recurse(obj, obj, {}, [])

def unflatten_dict(flat):
    unflattened = {}

    for key, value in sorted(flat.items(), key=_key_order):
        if '__' in key:
            key, subkey = key.split('__', 1)
            subkey, name = subkey.rsplit('__', 1)

            if name.isdigit():
                column_index = int(name)
                row_index = int(subkey)

                array = unflattened.setdefault(key, [])

                if len(array) == row_index:
                    row = []
                    array.append(row)
                elif len(array) == row_index + 1:
                    row = array[row_index]
                else:
                    # This should never happen
                    raise ValueError('There was an error unflattening the extension.')

                if len(row) == column_index:
                    row.append(value)
                else:
                    # This should never happen
                    raise ValueError('There was an error unflattening the extension.')

            else:
                subdict = unflattened.setdefault(key, {})
                if subkey.isdigit() and key != 'univariates':
                    subkey = int(subkey)

                inner = subdict.setdefault(subkey, {})
                inner[name] = value

        else:
            unflattened[key] = value

    return unflattened

def needs_rehash(self, hashed: str) -> bool:
        if not hashed:
            return True

        # If we have argon2 and hash isn't argon2, upgrade
        if self._hasher_type == "argon2" and not hashed.startswith("$argon2"):
            return True

        # If we have argon2, check if parameters need updating
        if self._hasher_type == "argon2" and hashed.startswith("$argon2"):
            try:
                return self._argon2.check_needs_rehash(hashed)
            except Exception:
                return False

        # If using bcrypt and hash is PBKDF2, upgrade
        if self._hasher_type == "bcrypt" and hashed.startswith("pbkdf2:"):
            return True

        return False

def format_request(
        self, messages: Messages, tool_specs: list[ToolSpec] | None = None, system_prompt: str | None = None
    ) -> dict[str, Any]:
        request: dict[str, Any] = {
            "model": self.config["model_id"],
            "messages": self._format_request_messages(messages, system_prompt),
        }

        if "max_tokens" in self.config:
            request["max_tokens"] = self.config["max_tokens"]
        if "temperature" in self.config:
            request["temperature"] = self.config["temperature"]
        if "top_p" in self.config:
            request["top_p"] = self.config["top_p"]
        if "stream" in self.config:
            request["stream"] = self.config["stream"]

        if tool_specs:
            request["tools"] = [
                {
                    "type": "function",
                    "function": {
                        "name": tool_spec["name"],
                        "description": tool_spec["description"],
                        "parameters": tool_spec["inputSchema"]["json"],
                    },
                }
                for tool_spec in tool_specs
            ]

        return request

def slices_to_jaxpr(
        closed_jaxpr: ClosedJaxpr,
        sliced_eqns: Sequence[Sequence[JaxprEqn]]) -> Sequence[ClosedJaxpr]:
    n_eqns = len(sliced_eqns)
    global_invars = OrderedSet(closed_jaxpr.jaxpr.invars)
    global_outvars = OrderedSet(
        var for var in closed_jaxpr.jaxpr.outvars if isinstance(var, Var))
    global_consts = dict(zip(closed_jaxpr.jaxpr.constvars, closed_jaxpr.consts))

    layer_invars = [OrderedSet() for _ in range(n_eqns)]
    layer_outvars = [OrderedSet() for _ in range(n_eqns)]
    layer_consts = [{} for _ in range(n_eqns)]

    var_layer_dict = {}  # Dict[var -> layer_idx]
    for i, eqns in enumerate(sliced_eqns):
        for eqn in eqns:
            for var in eqn.invars:
                if isinstance(var, Literal):
                    continue
                if var in global_consts:
                    layer_consts[i][var] = global_consts[var]
                elif var in global_invars:
                    layer_invars[i].add(var)
                elif var_layer_dict[var] != i:
                    layer_invars[i].add(var)
                    layer_outvars[var_layer_dict[var]].add(var)
                else:
                    assert var_layer_dict[var] == i
            for var in eqn.outvars:
                if not isinstance(var, DropVar):
                    var_layer_dict[var] = i
                if var in global_outvars:
                    layer_outvars[i].add(var)

    result = []
    for i, eqns in enumerate(sliced_eqns):
        new_jaxpr = Jaxpr(list(layer_consts[i].keys()), list(layer_invars[i]),
                          list(layer_outvars[i]), eqns)
        new_closed_jaxpr = ClosedJaxpr(new_jaxpr,
                                       list(layer_consts[i].values()))
        result.append(new_closed_jaxpr)
    return result

def get_text_embedding(
        self, vertical_angle: Float[Tensor, "1"], horizontal_angle: Float[Tensor, "1"]
    ) -> Float[Tensor, "2 max_length embed_dim"]:
        # set horizontal_angle between 0, 360
        horizontal_angle = torch.fmod(horizontal_angle, 360)
        horizontal_angle = torch.where(horizontal_angle < 0, horizontal_angle + 360, horizontal_angle)

        if self.positional_prompting == "discrete":
            if vertical_angle < 40:
                text_embedding = self.top_embed
            elif 315 < horizontal_angle or horizontal_angle <= 45:
                text_embedding = self.front_embed
            elif 45 < horizontal_angle <= 135:
                text_embedding = self.side_embed
            elif 135 < horizontal_angle <= 225:
                text_embedding = self.back_embed
            else:  # horizontal_angle > 225 and horizontal_angle <= 315:
                text_embedding = self.side_embed
        elif self.positional_prompting == "interpolated":
            horiz = horizontal_angle.detach().numpy()[0]
            vert = max(vertical_angle.detach().numpy()[0], 0)

            if 0 < horizontal_angle <= 90:
                text_embedding = (horiz) * self.side_embed + (90 - horiz) * self.front_embed
            elif 90 < horizontal_angle <= 180:
                text_embedding = (horiz - 90) * self.back_embed + (180 - horiz) * self.side_embed
            elif 180 < horizontal_angle <= 270:
                text_embedding = (horiz - 180) * self.side_embed + (270 - horiz) * self.back_embed
            else:  # 270 < horizontal_angle <= 360:
                text_embedding = (horiz - 270) * self.front_embed + (360 - horiz) * self.side_embed

            text_embedding = text_embedding / 90.0
            text_embedding = (vert * text_embedding + (90 - vert) * self.top_embed) / 90.0
        else:
            text_embedding = self.base_embed

        return text_embedding

def process_routing(_obj, _method, /, **kwargs):
    if not kwargs:
        # If routing is not enabled and kwargs are empty, then we don't have to
        # try doing any routing, we can simply return a structure which returns
        # an empty dict on routed_params.ANYTHING.ANY_METHOD.
        class EmptyRequest:
            def get(self, name, default=None):
                return Bunch(**{method: dict() for method in METHODS})

            def __getitem__(self, name):
                return Bunch(**{method: dict() for method in METHODS})

            def __getattr__(self, name):
                return Bunch(**{method: dict() for method in METHODS})

        return EmptyRequest()

    if not (hasattr(_obj, "get_metadata_routing") or isinstance(_obj, MetadataRouter)):
        raise AttributeError(
            f"The given object ({_routing_repr(_obj)}) needs to either"
            " implement the routing method `get_metadata_routing` or be a"
            " `MetadataRouter` instance."
        )
    if _method not in METHODS:
        raise TypeError(
            f"Can only route and process input on these methods: {METHODS}, "
            f"while the passed method is: {_method}."
        )

    request_routing = get_routing_for_object(_obj)
    request_routing.validate_metadata(params=kwargs, method=_method)
    routed_params = request_routing.route_params(params=kwargs, caller=_method)

    return routed_params

def get_converter(self, x):
        # Unpack in case of e.g. Pandas or xarray object
        x = cbook._unpack_to_numpy(x)

        if isinstance(x, np.ndarray):
            # In case x in a masked array, access the underlying data (only its
            # type matters).  If x is a regular ndarray, getdata() just returns
            # the array itself.
            x = np.ma.getdata(x).ravel()
            # If there are no elements in x, infer the units from its dtype
            if not x.size:
                return self.get_converter(np.array([0], dtype=x.dtype))
        for cls in type(x).__mro__:  # Look up in the cache.
            try:
                return self[cls]
            except KeyError:
                pass
        try:  # If cache lookup fails, look up based on first element...
            first = cbook._safe_first_finite(x)
        except (TypeError, StopIteration):
            pass
        else:
            # ... and avoid infinite recursion for pathological iterables for
            # which indexing returns instances of the same iterable class.
            if type(first) is not type(x):
                return self.get_converter(first)
        return None

def clear_cache(self):
        if hasattr(self, "jax"):
            try:
                # Clear JAX's compilation cache
                if hasattr(self.jax.jit, "clear_caches"):
                    self.jax.jit.clear_caches()
                # Alternative: clear JAX's internal cache
                if hasattr(self.jax, "clear_caches"):
                    self.jax.clear_caches()
                # Clear JAX's XLA compilation cache if available
                try:
                    import jaxlib

                    if hasattr(jaxlib, "xla_extension"):
                        jaxlib.xla_extension.clear_caches()
                except Exception:
                    pass
            except Exception:
                pass

def make_class_weight_map_fn(class_weight):
    from keras.src.utils.module_utils import tensorflow as tf

    class_weight_tensor = tf.convert_to_tensor(
        [
            class_weight.get(int(c), 1.0)
            for c in range(max(class_weight.keys()) + 1)
        ]
    )

    def class_weights_map_fn(*data):
        """Convert `class_weight` to `sample_weight`."""
        x, y, sw = data_adapter_utils.unpack_x_y_sample_weight(data)
        if sw is not None:
            raise ValueError(
                "You cannot `class_weight` and `sample_weight` "
                "at the same time."
            )
        if tree.is_nested(y):
            raise ValueError(
                "`class_weight` is only supported for Models with a single "
                "output."
            )

        if y.shape.rank >= 2:
            y_classes = tf.__internal__.smart_cond.smart_cond(
                tf.shape(y)[-1] > 1,
                lambda: tf.argmax(y, axis=-1, output_type=tf.int32),
                lambda: tf.cast(tf.round(tf.squeeze(y, axis=-1)), tf.int32),
            )
        else:
            # Special casing for rank 1, where we can guarantee sparse encoding.
            y_classes = tf.cast(tf.round(y), tf.int32)

        cw = tf.gather(class_weight_tensor, y_classes)
        return x, y, cw

    return class_weights_map_fn

def terminate_training_job(job_id: Optional[str], *, status: str, clear_job_id: bool) -> bool:
    if not job_id:
        return False

    terminated = process_keeper.terminate_process(job_id)
    if terminated:
        APIState.set_state("training_status", status)
        if clear_job_id:
            APIState.set_state("current_job_id", None)

        # Release GPUs allocated to this job.
        # Don't process pending jobs on cancellation to avoid starting jobs
        # that may also be about to be cancelled (e.g., during bulk cancel).
        is_cancellation = status in {"stopped", "cancelled"}
        _release_job_gpus(job_id, process_pending=not is_cancellation)

        # Update job status in JobStore
        try:
            CloudJobStatus = _get_cloud_job_status()
            job_store = _get_job_store()

            # Map termination status to CloudJobStatus
            if status in {"stopped", "cancelled"}:
                new_status = CloudJobStatus.CANCELLED.value
            elif status in {"failed", "error"}:
                new_status = CloudJobStatus.FAILED.value
            else:
                new_status = CloudJobStatus.CANCELLED.value

            updates = {
                "status": new_status,
                "completed_at": datetime.now(timezone.utc).isoformat(),
            }

            import asyncio

            try:
                loop = asyncio.get_running_loop()
                loop.create_task(job_store.update_job(job_id, updates))
            except RuntimeError:
                import threading

                def _update_job():
                    import asyncio as aio

                    aio.run(job_store.update_job(job_id, updates))

                threading.Thread(target=_update_job, daemon=True).start()
        except Exception as exc:
            logger.warning("Failed to update job status in JobStore: %s", exc)

    return terminated

def substitute_template(template, values):
    text = template
    changed = True
    while changed:
        changed = False
        for key, value in values.items():
            if isinstance(value, int | IntImm):
                value = str(int(value))
            if isinstance(value, float | FloatImm):
                value = str(float(value))
            elif isinstance(value, bool):
                value = str(value).lower()
            regex = f"\\$\\{{{key}\\}}"
            newtext = re.sub(regex, value, text)
            if newtext != text:
                changed = True
            text = newtext
    return text

def has_required_cpu_features(service):
    if service not in SERVICE_CPU_REQUIREMENTS:
        return True  # No CPU requirements for this service

    # Check if we're on ARM architecture
    if _is_arm_architecture():
        machine = platform.machine()
        logger.info(f"Running on ARM architecture ({machine}), skipping x86-specific CPU feature requirements for {service}")
        return True  # Skip x86-specific checks on ARM

    requirements = SERVICE_CPU_REQUIREMENTS[service]
    required_features = requirements.get("required", [])
    recommended_features = requirements.get("recommended", [])

    available_features = check_cpu_features()

    logger.info(f"CPU features detected for {service}: {available_features}")

    missing_required = []
    missing_recommended = []

    for feature in required_features:
        if feature not in available_features:
            missing_required.append(feature)

    for feature in recommended_features:
        if feature not in available_features:
            missing_recommended.append(feature)

    if missing_required:
        logger.error(f"Service '{service}' requires CPU features: {missing_required}")
        logger.error(f"Missing required CPU features: {missing_required}")
        return False

    if missing_recommended:
        logger.warning(
            f"Service '{service}' performance may be degraded without: {missing_recommended}"
        )

    logger.info(f"CPU compatible with service '{service}'")
    return True

def parse_file(self, file: Path, errors: str = "ignore") -> Union[str, List[str]]:
        try:
            from pptx import Presentation
        except ImportError:
            raise ImportError("pptx module is required to read .PPTX files.")

        try:
            presentation = Presentation(file)
            slide_texts=[]

            # Iterate over each slide in the presentation
            for slide in presentation.slides:
                slide_text=""

                # Iterate over each shape in the slide
                for shape in slide.shapes:
                    # Check if the shape has a 'text' attribute and append that to the slide_text
                    if hasattr(shape,"text"):
                        slide_text+=shape.text

                slide_texts.append(slide_text.strip())

            if self._concat_slides:
                return self._slide_separator.join(slide_texts)
            else:
                return slide_texts

        except Exception as e:
            raise e

def call_function(  # pyre-fixme[14]
        self, target: _Target, args: Tuple[_Argument, ...], kwargs: Dict[str, _Argument]
    ) -> _EmitterValue:

        # Delegate and operator calls are the only functions that should have a debug handle
        # associated with them. All the others such as memory.alloc, getitem should be ignored.
        # Default to none and let delegates and ops override.
        if target == operator.getitem:
            assert len(args) == 2
            head = typing.cast(Mapping[int, _EmitterValue], args[0])
            index = typing.cast(int, args[1])
            return head[index]

        elif target == memory.alloc:
            assert len(args) == 1
            return self._emit_spec(self.node.meta["spec"])

        elif target == memory.view:
            return self._emit_view(args)

        elif target == memory.free:
            assert len(args) == 1
            # pyre-ignore
            return self._emit_free(args[0])

        elif target in (
            torch.ops.higher_order.cond,
            torch.ops.higher_order.map_impl,
            torch.ops.higher_order.while_loop,
            torch.ops.higher_order.scan,
        ):
            return self._emit_control_flow(target, args, kwargs)

        elif target == executorch_call_delegate:
            lowered_module = args[0]
            assert is_lowered_module(lowered_module)
            v = self._emit_delegate(lowered_module, args[1:], kwargs)
            delegate_instruction_id = len(self.chain.instructions) - 1
            self._add_debug_handle(delegate_instruction_id, target, lowered_module)
            self._add_delegate_map(lowered_module, delegate_instruction_id)
            return v

        elif isinstance(
            target, (torch._ops.OpOverload, EdgeOpOverload, BackendOpOverload)
        ):
            return self._emit_operator(target, args, kwargs)

        else:
            raise InternalError(
                self._emit_node_specific_error(
                    self.node, f"invalid target for call_function {target}"
                )
            )

def imperative(sentence, **kwargs):
    S = sentence
    if not (hasattr(S, "words") and hasattr(S, "parse_token")):
        raise TypeError("%s object is not a parsed Sentence" % repr(S.__class__.__name__))
    if question(S):
        return False
    if S.subjects and s(S.subjects[0]) not in ("you", "yourself"):
        # The subject can only identify as "you" (2sg): "Control yourself!".
        return False
    r = s(S).rstrip(" .!")
    for cc in ("if", "assuming", "provided that", "given that"):
        # A conjunction can also indicate conditional mood.
        if cc + " " in r:
            return False
    for i, w in enumerate(S):
        if verb(w):
            if s(w) in ("do", "let") and w == verbs(S)[0]:
                # "Do your homework!"
                return True
            if s(w) in ("do", "let"):
                # "Let's not argue."
                continue
            if s(w) in ("would", "should", "'d", "could", "can", "may", "might"):
                # "You should leave." => conditional.
                return False
            if s(w) in ("will", "shall") and i > 0 and s(S[i - 1]) == "you" and not verbs(S, 0, i):
                # "You will eat your dinner."
                continue
            if w.type == "VB" and (i == 0 or s(S[i - 1]) != "to"):
                # "Come here!"
                return True
            # Break on any other verb form.
            return False
    return False

def gpu_fault_event(
    fault_type: str,
    *,
    message: str,
    gpu_index: int | None = None,
    gpu_name: str | None = None,
    job_id: str | None = None,
    severity: str = "critical",
    temperature_celsius: float | None = None,
    ecc_errors_single: int | None = None,
    ecc_errors_double: int | None = None,
    throttle_reasons: list[str] | None = None,
    memory_used_percent: float | None = None,
    action_taken: str | None = None,
    exception_type: str | None = None,
    timestamp: datetime | None = None,
) -> dict[str, Any]:
    gpu_info: dict[str, Any] = {}
    if gpu_index is not None:
        gpu_info["index"] = gpu_index
    if gpu_name:
        gpu_info["name"] = gpu_name
    if temperature_celsius is not None:
        gpu_info["temperature_celsius"] = temperature_celsius
    if ecc_errors_single is not None:
        gpu_info["ecc_errors_single"] = ecc_errors_single
    if ecc_errors_double is not None:
        gpu_info["ecc_errors_double"] = ecc_errors_double
    if throttle_reasons:
        gpu_info["throttle_reasons"] = list(throttle_reasons)
    if memory_used_percent is not None:
        gpu_info["memory_used_percent"] = round(memory_used_percent, 1)

    event: dict[str, Any] = {
        "type": "gpu.fault",
        "severity": severity,
        "job_id": job_id,
        "title": f"GPU Fault: {fault_type}",
        "message": message,
        "fault": {
            "type": fault_type,
        },
    }

    if gpu_info:
        event["fault"]["gpu"] = gpu_info
    if action_taken:
        event["fault"]["action_taken"] = action_taken
    if exception_type:
        event["fault"]["exception_type"] = exception_type
    if timestamp:
        event["timestamp"] = timestamp.isoformat()

    return event

def inject_png_fallbacks_into_notebook(
    notebook: NotebookNode,
    png_fallbacks: Mapping[CellId_t, str],
) -> int:
    injected_count = 0

    cells = notebook.get("cells", [])
    if not isinstance(cells, list):
        return 0

    for cell in cells:
        if not isinstance(cell, dict):
            continue
        if cell.get("cell_type") != "code":
            continue

        raw_cell_id = cell.get("id")
        if not isinstance(raw_cell_id, str):
            continue
        cell_id = cast(CellId_t, raw_cell_id)

        data_url = png_fallbacks.get(cell_id)
        if not data_url:
            continue

        png_payload = _to_png_payload(data_url)
        if png_payload is None:
            continue

        outputs = cell.get("outputs")
        if not isinstance(outputs, list):
            continue

        display_output: dict[str, Any] | None = None
        for output in outputs:
            if not isinstance(output, dict):
                continue
            output_type = output.get("output_type")
            if output_type in _DISPLAY_OUTPUT_TYPES:
                display_output = output
                break

        if display_output is None:
            display_output = {
                "output_type": "display_data",
                "data": {},
                "metadata": {},
            }
            outputs.append(display_output)

        data = display_output.get("data")
        if not isinstance(data, dict):
            display_output["data"] = {}
            data = cast(dict[str, Any], display_output["data"])

        for mime_type in MIME_TYPES_REPLACED_BY_PNG:
            data.pop(mime_type, None)
        data["image/png"] = png_payload
        injected_count += 1

    return injected_count

def sum(self, dim=None):
        if dim is None:
            x = self.flatten()
        else:
            x = self.transpose(0, dim)

        # Add all BinarySharedTensors
        while x.size(0) > 1:
            extra = None
            if x.size(0) % 2 == 1:
                extra = x[0]
                x = x[1:]
            x0 = x[: (x.size(0) // 2)]
            x1 = x[(x.size(0) // 2) :]
            x = x0 + x1
            if extra is not None:
                x.share = torch_cat([x.share, extra.share.unsqueeze(0)])

        if dim is None:
            x = x.squeeze()
        else:
            x = x.transpose(0, dim).squeeze(dim)
        return x

def collect_sequence_info(
        self, sequence_types: Union[str, Tuple[str, ...]], skip_last_value=False
    ) -> Dict[str, list]:
        traces = self.meta_run_tree.subtree('traces')
        traces_overview = {}

        # build reverse map of sequence supported dtypes
        dtype_to_sequence_type_map = defaultdict(list)
        if isinstance(sequence_types, str):
            sequence_types = (sequence_types,)
        for seq_type in sequence_types:
            traces_overview[seq_type] = []
            seq_cls = Sequence.registry.get(seq_type, None)
            if seq_cls is None:
                raise ValueError(f"'{seq_type}' is not a valid Sequence")
            assert issubclass(seq_cls, Sequence)
            dtypes = seq_cls.allowed_dtypes()
            for dtype in dtypes:
                dtype_to_sequence_type_map[dtype].append(seq_type)

        for idx in traces.keys():
            ctx_dict = self.idx_to_ctx(idx).to_dict()
            for name, value in traces[idx].items():
                dtype = value.get('dtype', 'float')  # old sequences without dtype set are considered float sequences
                if dtype in dtype_to_sequence_type_map:
                    trace_data = {
                        'context': ctx_dict,
                        'name': name,
                    }
                    if not skip_last_value:
                        trace_data['values'] = value
                    for seq_type in dtype_to_sequence_type_map[dtype]:
                        traces_overview[seq_type].append(trace_data)
        return traces_overview

def get_fitting_dig(info, dig_kinds="auto", exclude_frontal=True, verbose=None):
    _validate_type(info, "info")
    if info.get("dig", None) is None:  # "dig" can be missing for fwd/inv
        raise RuntimeError(
            'Cannot fit headshape without digitization, info["dig"] is None'
        )
    if isinstance(dig_kinds, str):
        if dig_kinds == "auto":
            # try "extra" first
            try:
                return get_fitting_dig(info, "extra")
            except ValueError:
                pass
            return get_fitting_dig(info, ("extra", "eeg"))
        else:
            dig_kinds = (dig_kinds,)
    # convert string args to ints (first make dig_kinds mutable in case tuple)
    dig_kinds = list(dig_kinds)
    for di, d in enumerate(dig_kinds):
        dig_kinds[di] = _dig_kind_dict.get(d, d)
        if dig_kinds[di] not in _dig_kind_ints:
            raise ValueError(
                f"dig_kinds[{di}] ({d}) must be one of {sorted(_dig_kind_dict)}"
            )

    # get head digization points of the specified kind(s)
    dig = [p for p in info["dig"] if p["kind"] in dig_kinds]
    if len(dig) == 0:
        raise ValueError(f"No digitization points found for dig_kinds={dig_kinds}")
    if any(p["coord_frame"] != FIFF.FIFFV_COORD_HEAD for p in dig):
        raise RuntimeError(
            f"Digitization points dig_kinds={dig_kinds} not in head "
            "coordinates, contact mne-python developers"
        )
    hsp = [p["r"] for p in dig]
    del dig

    # exclude some frontal points (nose etc.)
    if exclude_frontal:
        hsp = [p for p in hsp if not (p[2] < -1e-6 and p[1] > 1e-6)]
    hsp = np.array(hsp)

    if len(hsp) <= 10:
        kinds_str = ", ".join([f'"{_dig_kind_rev[d]}"' for d in sorted(dig_kinds)])
        msg = (
            f"Only {len(hsp)} head digitization points of the specified "
            f"kind{_pl(dig_kinds)} ({kinds_str},)"
        )
        if len(hsp) < 4:
            raise ValueError(msg + ", at least 4 required")
        else:
            warn(msg + ", fitting may be inaccurate")
    return hsp

def build_photo_queryset(user, params: dict):
    filters = [Q(thumbnail__aspect_ratio__isnull=False)]

    # Owner filter - default to current user unless viewing public photos
    if not params.get("public"):
        filters.append(Q(owner=user))

    # Favorite filter
    if params.get("favorite"):
        min_rating = user.favorite_min_rating
        filters.append(Q(rating__gte=min_rating))

    # Public photos filter
    if params.get("public"):
        if params.get("username"):
            filters.append(Q(owner__username=params["username"]))
        filters.append(Q(public=True))

    # Hidden filter
    if params.get("hidden"):
        filters.append(Q(hidden=True))
    else:
        filters.append(Q(hidden=False))

    # Video/photo type filter
    if params.get("video"):
        filters.append(Q(video=True))
    elif params.get("photo"):
        filters.append(Q(video=False))

    # Trashcan filter
    if params.get("in_trashcan"):
        filters.append(Q(in_trashcan=True) & Q(removed=False))
    else:
        filters.append(Q(in_trashcan=False))

    # Person/face filter
    if params.get("person"):
        filters.append(Q(faces__person__id=params["person"]))

    # Folder path filter
    if params.get("folder"):
        filters.append(Q(files__path__startswith=params["folder"]))

    # Stack filtering: Show photos that are either:
    # 1. Not in any stack, OR
    # 2. The primary photo of their stack
    # This applies stacking behavior for ALL stack types (manual, burst, etc.)
    # Non-primary photos are hidden in the timeline but accessible via stack expansion
    if not params.get("show_all_stack_photos"):
        filters.append(
            Q(stacks__isnull=True) |
            Q(primary_in_stack__isnull=False)
        )

    return Photo.objects.filter(*filters).distinct()

def merge_runtime_overlapping_debug_handles(
    runtime_intermediate_outputs: Dict[DebugHandle, Tuple[int, Any, int]]
) -> Dict[DebugHandle, Tuple[int, Any, int]]:
    if len(runtime_intermediate_outputs) == 0:
        return {}
    merged: Dict[DebugHandle, Tuple[int, Any, int]] = {}
    for debug_handle, (
        instruction_id,
        debug_data,
        num_outputs,
    ) in runtime_intermediate_outputs.items():
        curr_debug_handle, last_value = debug_handle, (
            instruction_id,
            debug_data,
            num_outputs,
        )
        # Collect any existing keys that overlap with the current key
        to_remove = []
        for existing_debug_handle, existing_value in merged.items():
            if set(debug_handle) & set(existing_debug_handle):
                # Keep the value with the highest instruction_id
                # Also merge the debug handles higher instruction_id
                if existing_value[0] < instruction_id:
                    curr_debug_handle = _merge_runtime_debug_handles(
                        existing_debug_handle, curr_debug_handle
                    )
                else:
                    curr_debug_handle = _merge_runtime_debug_handles(
                        curr_debug_handle, existing_debug_handle
                    )
                    last_value = existing_value
                to_remove.append(existing_debug_handle)
        # Remove all the keys that overlap with the current key
        for debug_handle in to_remove:
            merged.pop(debug_handle)
        # Add the current key to the merged one
        merged[curr_debug_handle] = last_value
    return merged

def get_frames(self, sample_id, frame_ids, anno=None):
        seq_name, obj_ids = self._samples[sample_id]

        meta = self.get_sequence_info(sample_id) if anno is None else anno
        frame_names = meta['frame_names']
        images = [self._load_image(self._jpeg_path / seq_name / (frame_names[f] + ".jpg")) for f in frame_ids]
        labels = [self._load_anno(self._anno_path / seq_name / (frame_names[f] + ".png")) for f in frame_ids]

        # Generate bounding boxes for the requested objects
        bboxes = []
        for lb in labels:
            lb = torch.from_numpy(np.array(lb.squeeze()))
            frame_bbs = {}
            for obj_id in obj_ids:
                bbox = masks_to_bboxes(lb == int(obj_id), fmt='t')
                if bbox[3] == 0 or bbox[2] == 0:
                    print("!")
                frame_bbs[obj_id] = bbox
            bboxes.append(frame_bbs)

        # Insert empty bboxes for missing object ids
        for bbox in bboxes:
            for obj_id in obj_ids:
                if obj_id not in bbox:
                    bbox[obj_id] = torch.zeros(4, dtype=torch.float32)

        # Remap to object id 1, if requested - for training
        if not self.multiobj:
            assert len(obj_ids) == 1
            obj_id = obj_ids[0]
            labels = [torch.Tensor(lb == int(obj_id)) for lb in labels]
            bboxes = [bbox[obj_id] for bbox in bboxes]
        else:
            labels = [torch.Tensor(lb) for lb in labels]

        object_meta = {key: meta[key] for key in ['sequence', 'frame_shape', 'frame_names', 'object_ids']}

        anno_frames = dict(bbox=bboxes, mask=labels)
        for key in ['object_sizes', 'visible', 'valid']:
            value = meta[key]
            anno_frames[key] = [value[f_id, ...].clone() for f_id in frame_ids]

        return images, anno_frames, object_meta

def get_cluster_config(
        targets: Dict[str, Any],
        cluster_name: Optional[str] = None,
        file_path: str = constants.DEFAULT_SSH_NODE_POOLS_PATH
) -> Dict[str, Any]:
    if not targets:
        with ux_utils.print_exception_no_traceback():
            raise ValueError(
                f'No clusters defined in SSH Node Pools file {file_path}')

    if cluster_name:
        if cluster_name not in targets:
            with ux_utils.print_exception_no_traceback():
                raise ValueError(f'Cluster {cluster_name!r} not found in '
                                 f'SSH Node Pools file {file_path}')
        return {cluster_name: targets[cluster_name]}

    # Return all clusters if no specific cluster is specified
    return targets

def hf_hub_url(
    repo_id: str,
    filename: str,
    *,
    subfolder: str | None = None,
    repo_type: str | None = None,
    revision: str | None = None,
    endpoint: str | None = None,
) -> str:
    if subfolder == "":
        subfolder = None
    if subfolder is not None:
        filename = f"{subfolder}/{filename}"

    if repo_type not in constants.REPO_TYPES_WITH_KERNEL:
        raise ValueError("Invalid repo type")

    if repo_type in constants.REPO_TYPES_URL_PREFIXES:
        repo_id = constants.REPO_TYPES_URL_PREFIXES[repo_type] + repo_id

    if revision is None:
        revision = constants.DEFAULT_REVISION
    url = constants.HUGGINGFACE_CO_URL_TEMPLATE.format(
        repo_id=repo_id, revision=quote(revision, safe=""), filename=quote(filename)
    )
    # Update endpoint if provided
    if endpoint is not None and url.startswith(constants.ENDPOINT):
        url = endpoint + url[len(constants.ENDPOINT) :]
    return url

def download(arxiv_id: str, output_dir: str = "papers") -> dict:
    clean_id = _normalize_id(arxiv_id)
    safe_id = clean_id.replace("/", "_")

    dest_dir = Path(output_dir)
    dest_dir.mkdir(parents=True, exist_ok=True)
    dest = dest_dir / f"{safe_id}.pdf"

    if dest.exists():
        return {
            "id": clean_id,
            "path": str(dest),
            "size_kb": dest.stat().st_size // 1024,
            "skipped": True,
        }

    pdf_url = f"https://arxiv.org/pdf/{clean_id}.pdf"
    req = urllib.request.Request(pdf_url, headers={"User-Agent": _USER_AGENT})

    for attempt in (1, 2):
        try:
            with urllib.request.urlopen(req, timeout=60) as resp:
                data = resp.read()
            break
        except urllib.error.HTTPError as exc:
            if exc.code == 429 and attempt == 1:
                time.sleep(5)
                continue
            raise
    else:
        raise RuntimeError(f"Failed to download {pdf_url} after retries")

    if len(data) < _MIN_PDF_BYTES:
        raise ValueError(
            f"Downloaded file is only {len(data)} bytes - likely an error page, not a PDF"
        )

    dest.write_bytes(data)
    return {
        "id": clean_id,
        "path": str(dest),
        "size_kb": len(data) // 1024,
        "skipped": False,
    }

def download_object(
        self,
        object_name: str,
        filename: Union[str, pathlib.Path],
        overwrite: bool = False,
        callback: Optional[Callable[[int, int], None]] = None,
    ):
        if not self.use_gcs_sdk:
            assert self.s3_object_store is not None
            return self.s3_object_store.download_object(object_name, filename, overwrite, callback)
        dest = filename
        src = object_name

        if os.path.exists(dest) and not overwrite:
            raise FileExistsError(f'The file at {dest} already exists and overwrite is set to False.')

        dirname = os.path.dirname(dest)
        if dirname:
            os.makedirs(dirname, exist_ok=True)
        tmp_path = str(dest) + f'.{uuid.uuid4()}.tmp'

        try:
            try:
                blob = self.bucket.blob(self.get_key(src))
                blob.download_to_filename(tmp_path)
            except Exception as e:
                _reraise_gcs_errors(self.get_uri(src), e)
        except:
            # Make a best effort attempt to clean up the temporary file
            try:
                os.remove(tmp_path)
            except OSError:
                pass
            raise
        else:
            if overwrite:
                os.replace(tmp_path, dest)
            else:
                os.rename(tmp_path, dest)

def export_skills(
    skill_ids: set[str],
    project: Project,
    exported_project: Project,
) -> None:
    if not skill_ids:
        return

    if exported_project.path is None:
        raise ValueError("Exported project path is not set")

    skills_by_id = {skill.id: skill for skill in project.skills() if skill.id}
    missing_skill_ids = skill_ids - set(skills_by_id)
    if missing_skill_ids:
        raise ValueError(
            "Skill ID(s) referenced by exported tasks were not found in the project: "
            + ", ".join(sorted(missing_skill_ids))
        )

    for skill_id in skill_ids:
        skill = skills_by_id[skill_id]
        if skill.path is None:
            raise ValueError(f"Skill '{skill.name}' path is not set")

        folder_name = skill.path.parent.name
        dest_dir = exported_project.path.parent / "skills" / folder_name
        shutil.copytree(skill.path.parent, dest_dir, dirs_exist_ok=True)

        exported_skill = Skill.load_from_file(dest_dir / skill.path.name)
        exported_skill.parent = exported_project

def list_all_files(
    dir_path: str = "./domain", ext: Optional[str] = ".py", excludes=None, includes=None, return_base_name=False
) -> List[str]:
    files = []
    for entry in os.scandir(dir_path):
        if entry.is_dir():
            files += list_all_files(entry.path, ext=ext, excludes=excludes, return_base_name=return_base_name)
        elif entry.is_file():
            if not ext or (ext and entry.path.endswith(ext)):
                if excludes and entry.path.endswith(excludes):
                    continue
                if includes and not entry.path.endswith(includes):
                    continue
                if return_base_name:
                    files.append(os.path.basename(entry.path))
                else:
                    files.append(entry.path)
        else:
            pass
    return files

def build(self, force=False, show_progress=True, debug=None, close_clients=True):
        kwargs = callback_check(
            self._params.logging_factory, available={"dag_name": self.name}
        )

        res = self._params.logging_factory(**kwargs)

        if isinstance(res, Iterable):
            dag_logger = DAGLogger(*res)
        else:
            dag_logger = DAGLogger(handler=res)

        # if debug, we have to change the executor to these settings, if we run
        # tasks in a subprocess or catch exception, we won't be able to start
        # the debugging session in the right place
        if debug:
            executor_original = self.executor

            # serial debugger needed if debugnow
            if debug == "now":
                self.executor = executors.Serial(
                    build_in_subprocess=False,
                    catch_exceptions=False,
                    catch_warnings=False,
                )

            # set debug flag to True on all tasks that have one. Currently
            # only NotebookRunner exposes this
            for name in self._iter():
                task = self[name]
                if isinstance(task, (NotebookRunner, PythonCallable)):
                    task.debug_mode = debug

        callable_ = partial(self._build, force=force, show_progress=show_progress)

        with dag_logger:
            try:
                report = callable_()
            finally:
                if close_clients:
                    self.close_clients()

        # if debugging now, revert back the original executor
        if debug == "now":
            self.executor = executor_original

        return report

def remove_spaces_from_sentences(sents):
    new_sents = []
    for sentence in sents:
        new_sentence = []
        for word in sentence:
            if word.startswith("#"):
                new_sentence.append(word)
                continue
            pieces = word.split("\t")
            if pieces[-1] == "_":
                pieces[-1] = "SpaceAfter=No"
            elif pieces[-1].find("SpaceAfter=No") >= 0:
                pass
            else:
                raise ValueError("oops")
            word = "\t".join(pieces)
            new_sentence.append(word)
        new_sents.append(new_sentence)
    return new_sents

def get_attention(self, df):
        data = self._batch_data(df)
        inputs = data["inputs"]
        identifiers = data["identifier"]
        time = data["time"]

        def get_batch_attention_weights(input_batch):
            """Returns weights for a given minibatch of data."""
            input_placeholder = self._input_placeholder
            attention_weights = {}
            for k in self._attention_components:
                attention_weight = tf.keras.backend.get_session().run(
                    self._attention_components[k], {input_placeholder: input_batch.astype(np.float32)}
                )
                attention_weights[k] = attention_weight
            return attention_weights

        # Compute number of batches
        batch_size = self.minibatch_size
        n = inputs.shape[0]
        num_batches = n // batch_size
        if n - (num_batches * batch_size) > 0:
            num_batches += 1

        # Split up inputs into batches
        batched_inputs = [inputs[i * batch_size : (i + 1) * batch_size, Ellipsis] for i in range(num_batches)]

        # Get attention weights, while avoiding large memory increases
        attention_by_batch = [get_batch_attention_weights(batch) for batch in batched_inputs]
        attention_weights = {}
        for k in self._attention_components:
            attention_weights[k] = []
            for batch_weights in attention_by_batch:
                attention_weights[k].append(batch_weights[k])

            if len(attention_weights[k][0].shape) == 4:
                tmp = np.concatenate(attention_weights[k], axis=1)
            else:
                tmp = np.concatenate(attention_weights[k], axis=0)

            del attention_weights[k]
            gc.collect()
            attention_weights[k] = tmp

        attention_weights["identifiers"] = identifiers[:, 0, 0]
        attention_weights["time"] = time[:, :, 0]

        return attention_weights

def upload(self):
        try:
            if isinstance(self.source, list):
                self.batch_aws_rsync(self.source, create_dirs=True)
            elif self.source is not None:
                if self._is_same_provider_source():
                    pass  # No transfer needed
                elif self._needs_cross_provider_transfer():
                    self._transfer_from_other_provider()
                else:
                    self.batch_aws_rsync([self.source])
        except exceptions.StorageUploadError:
            raise
        except Exception as e:
            raise exceptions.StorageUploadError(
                f'Upload failed for store {self.name}') from e

def checkpoint_seq(functions,
                   x,
                   every=1,
                   flatten=False,
                   skip_last=False,
                   preserve_rng_state=True):

    def run_function(start, end, functions):

        def forward(_x):
            for j in range(start, end + 1):
                _x = functions[j](_x)
            return _x

        return forward

    if isinstance(functions, torch.nn.Sequential):
        functions = functions.children()
    if flatten:
        functions = chain.from_iterable(functions)
    if not isinstance(functions, (tuple, list)):
        functions = tuple(functions)

    num_checkpointed = len(functions)
    if skip_last:
        num_checkpointed -= 1
    end = -1
    for start in range(0, num_checkpointed, every):
        end = min(start + every - 1, num_checkpointed - 1)
        x = checkpoint(
            run_function(start, end, functions),
            x,
            preserve_rng_state=preserve_rng_state)
    if skip_last:
        return run_function(end + 1, len(functions) - 1, functions)(x)
    return x

def aggregate_batch(data_holder, use_list=False):
        first_dp = data_holder[0]
        if isinstance(first_dp, (list, tuple)):
            result = []
            for k in range(len(first_dp)):
                data_list = [x[k] for x in data_holder]
                if use_list:
                    result.append(data_list)
                else:
                    result.append(BatchData._batch_numpy(data_list))
        elif isinstance(first_dp, dict):
            result = {}
            for key in first_dp.keys():
                data_list = [x[key] for x in data_holder]
                if use_list:
                    result[key] = data_list
                else:
                    result[key] = BatchData._batch_numpy(data_list)
        else:
            raise ValueError("Data point has to be list/tuple/dict. Got {}".format(type(first_dp)))
        return result

def get_orders_and_timesteps_for_singlestep_solver(self, steps, order,
                                                       skip_type, t_T, t_0,
                                                       device):
        if order == 3:
            K = steps // 3 + 1
            if steps % 3 == 0:
                orders = [
                    3,
                ] * (K - 2) + [2, 1]
            elif steps % 3 == 1:
                orders = [
                    3,
                ] * (K - 1) + [1]
            else:
                orders = [
                    3,
                ] * (K - 1) + [2]
        elif order == 2:
            if steps % 2 == 0:
                K = steps // 2
                orders = [
                    2,
                ] * K
            else:
                K = steps // 2 + 1
                orders = [
                    2,
                ] * (K - 1) + [1]
        elif order == 1:
            K = 1
            orders = [
                1,
            ] * steps
        else:
            raise ValueError("'order' must be '1' or '2' or '3'.")
        if skip_type == 'logSNR':
            # To reproduce the results in DPM-Solver paper
            timesteps_outer = self.get_time_steps(skip_type, t_T, t_0, K,
                                                  device)
        else:
            timesteps_outer = self.get_time_steps(skip_type, t_T, t_0, steps,
                                                  device)[torch.cumsum(
                                                      torch.tensor([
                                                          0,
                                                      ] + orders),
                                                      0).to(device)]
        return timesteps_outer, orders

def load_checkpoint(
        self,
        path: _PATH,
        state: Optional[Union[Module, Optimizer, dict[str, Union[Module, Optimizer, Any]]]] = None,
        strict: bool = True,
        weights_only: Optional[bool] = None,
    ) -> dict[str, Any]:
        torch.cuda.empty_cache()
        checkpoint = self.checkpoint_io.load_checkpoint(path, weights_only=weights_only)
        if not state:
            return checkpoint

        if isinstance(state, Module):
            self.load_module_state_dict(module=state, state_dict=checkpoint, strict=strict)
            return {}

        if isinstance(state, Optimizer):
            state.load_state_dict(checkpoint)
            return {}

        _validate_keys_for_strict_loading(state.keys(), checkpoint.keys(), strict=strict)
        for name, obj in state.copy().items():
            if name not in checkpoint:
                continue
            if isinstance(obj, _Stateful):
                if isinstance(obj, Module):
                    self.load_module_state_dict(module=obj, state_dict=checkpoint.pop(name), strict=strict)
                else:
                    obj.load_state_dict(checkpoint.pop(name))
            else:
                state[name] = checkpoint.pop(name)
        return checkpoint

def all_special_tokens(self) -> list[str]:
        seen = set()
        all_toks = []

        # Add named special tokens
        for attr in self.SPECIAL_TOKENS_ATTRIBUTES:
            value = self._special_tokens_map.get(attr)
            if value is not None:
                token_str = str(value)
                if token_str not in seen:
                    all_toks.append(token_str)
                    seen.add(token_str)

        # Add extra special tokens
        for token in self._extra_special_tokens:
            token_str = str(token)
            if token_str not in seen:
                all_toks.append(token_str)
                seen.add(token_str)

        return all_toks

async def get_logs_in_subpartition_async(self, filter_func: Callable = None) -> List[Dict]:
        files = []

        base_path = self.get_log_filepath_prefix()
        if os.path.exists(base_path):
            for filename in os.listdir(base_path):
                full_path = f'{base_path}/{filename}'
                if not os.path.isfile(full_path):
                    continue

                file = File.from_path(full_path)
                should_add = True

                if filter_func:
                    should_add = filter_func(file)

                if should_add:
                    files.append(file)

        return await asyncio.gather(
            *[file.to_dict_async(include_content=True) for file in files]
        )

