def convert_to_rgb(
    video: np.ndarray,
    input_data_format: str | ChannelDimension | None = None,
) -> np.ndarray:
    if not isinstance(video, np.ndarray):
        raise TypeError(f"Video has to be a numpy array to convert to RGB format, but found {type(video)}")

    # np.array usually comes with ChannelDimension.LAST so let's convert it
    if input_data_format is None:
        input_data_format = infer_channel_dimension_format(video)
    video = to_channel_dimension_format(video, ChannelDimension.FIRST, input_channel_dim=input_data_format)

    # 3 channels for RGB already
    if video.shape[-3] == 3:
        return video

    # Grayscale video so we repeat it 3 times for each channel
    if video.shape[-3] == 1:
        return video.repeat(3, -3)

    if not (video[..., 3, :, :] < 255).any():
        return video

    # There is a transparency layer, blend it with a white background.
    # Calculate the alpha proportion for blending.
    alpha = video[..., 3, :, :] / 255.0
    video = (1 - alpha[..., None, :, :]) * 255 + alpha[..., None, :, :] * video[..., 3, :, :]
    return video

def get_excluded_files_from_skyignore(src_dir_path: str) -> List[str]:
    excluded_list: Set[str] = set()
    expand_src_dir_path = os.path.expanduser(src_dir_path)
    skyignore_path = os.path.join(expand_src_dir_path,
                                  constants.SKY_IGNORE_FILE)

    try:
        with open(skyignore_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    # Make parsing consistent with rsync.
                    # Rsync uses '/' as current directory.
                    if line.startswith('/'):
                        line = '.' + line
                    else:
                        line = '**/' + line
                    # Find all files matching the pattern.
                    matching_files = glob.glob(os.path.join(
                        expand_src_dir_path, line),
                                               recursive=True)
                    # Process filenames to comply with cloud rsync format.
                    for i in range(len(matching_files)):
                        matching_files[i] = os.path.relpath(
                            matching_files[i], expand_src_dir_path)
                    excluded_list.update(matching_files)
    except IOError as e:
        logger.warning(f'Error reading {skyignore_path}: '
                       f'{common_utils.format_exception(e, use_bracket=True)}')

    return list(excluded_list)

def matches_linear_qcnw_pattern(  # noqa: C901
    program: ExportedProgram, node: torch.fx.Node
) -> Optional[Tuple[torch.qscheme, int]]:
    if not utils.is_linear_node(node):
        return None

    input_node = node.args[0]
    weight_node = node.args[1]

    # Type checking
    if not isinstance(weight_node, torch.fx.Node):
        return None
    if not isinstance(input_node, torch.fx.Node):
        return None

    # The input arg should not be a dequant node; if it is, then it is indicative that
    # dynamically quantized linear should be used instead
    if utils.is_dequant_node(input_node):
        return None

    # The weight arg should be a dequant node dequantizing the quantized weight
    # Furthermore, the op expects per channel quantization of the weight
    if not utils.is_dequant_per_channel_node(weight_node):
        return None

    orig_weight = weight_node.args[0]
    zeros = weight_node.args[2]

    # Type checking
    if not isinstance(orig_weight, torch.fx.Node):
        return None
    if not is_param_node(program, orig_weight):
        return None
    if not isinstance(zeros, torch.fx.Node):
        return None
    if not is_param_node(program, zeros):
        return None

    zeros_tensor = get_param_tensor(program, zeros)
    if not isinstance(zeros_tensor, torch.Tensor):
        return None

    quant_method = torch.per_channel_affine
    # Check for symmetric quantization, where the zeros used for dequantization will
    # actually be all zeros.
    if torch.all(zeros_tensor == 0):
        quant_method = torch.per_channel_symmetric

    orig_weight_tensor = get_param_tensor(program, orig_weight)
    if not isinstance(orig_weight_tensor, torch.Tensor):
        return None
    # Sanity check the dtype of the quantized weight
    if orig_weight_tensor.dtype != torch.int8:
        return None

    quant_min = orig_weight_tensor.min().item()
    quant_max = orig_weight_tensor.max().item()
    # Determine the number of bits the weight has been quantized to
    if quant_min >= -8 and quant_max <= 7:
        return quant_method, 4
    elif quant_min >= -128 and quant_max <= 127:
        return quant_method, 8

    return None

def get_document_topics(self, bow, minimum_probability=None,
                            normalize=None):
        if minimum_probability is None:
            minimum_probability = self.minimum_probability
        minimum_probability = max(minimum_probability, 1e-8)

        # if the input vector is a corpus, return a transformed corpus
        is_corpus, corpus = utils.is_corpus(bow)

        if is_corpus:
            kwargs = dict(minimum_probability=minimum_probability)
            return self._apply(corpus, **kwargs)

        v = matutils.corpus2csc([bow], self.num_tokens)
        h = self._solveproj(v, self._W, v_max=np.inf)

        if normalize is None:
            normalize = self.normalize
        if normalize:
            the_sum = h.sum()
            if the_sum:
                h /= the_sum

        return [
            (idx, proba)
            for idx, proba in enumerate(h[:, 0])
            if not minimum_probability or proba > minimum_probability
        ]

def mean_tweedie_deviance(y_true, y_pred, *, sample_weight=None, power=0):
    xp, _, device = get_namespace_and_device(y_pred)
    y_true, sample_weight = move_to(y_true, sample_weight, xp=xp, device=device)
    y_type, y_true, y_pred, sample_weight, _ = _check_reg_targets_with_floating_dtype(
        y_true, y_pred, sample_weight, multioutput=None, xp=xp
    )
    if y_type == "continuous-multioutput":
        raise ValueError("Multioutput not supported in mean_tweedie_deviance")

    if sample_weight is not None:
        sample_weight = column_or_1d(sample_weight)
        sample_weight = sample_weight[:, np.newaxis]

    message = f"Mean Tweedie deviance error with power={power} can only be used on "
    if power < 0:
        # 'Extreme stable', y any real number, y_pred > 0
        if xp.any(y_pred <= 0):
            raise ValueError(message + "strictly positive y_pred.")
    elif power == 0:
        # Normal, y and y_pred can be any real number
        pass
    elif 1 <= power < 2:
        # Poisson and compound Poisson distribution, y >= 0, y_pred > 0
        if xp.any(y_true < 0) or xp.any(y_pred <= 0):
            raise ValueError(message + "non-negative y and strictly positive y_pred.")
    elif power >= 2:
        # Gamma and Extreme stable distribution, y and y_pred > 0
        if xp.any(y_true <= 0) or xp.any(y_pred <= 0):
            raise ValueError(message + "strictly positive y and y_pred.")
    else:  # pragma: nocover
        # Unreachable statement
        raise ValueError

    return _mean_tweedie_deviance(
        y_true, y_pred, sample_weight=sample_weight, power=power
    )

def redundancy_clean(model, deepspeed_config, mpu=None):
    compress_methods = get_compression_config(check_deepspeed_config(deepspeed_config))
    if hasattr(model, 'module'):
        c_model = model.module
    else:
        c_model = model

    layer_added_compress_methods_tmp = get_compress_methods(c_model, compress_methods, mpu=mpu)
    # sort methods
    order_list = [
        WEIGHT_QUANTIZATION, SPARSE_PRUNING, ROW_PRUNING, HEAD_PRUNING, CHANNEL_PRUNING, ACTIVATION_QUANTIZATION
    ]
    layer_added_compress_methods = sorted(layer_added_compress_methods_tmp,
                                          key=lambda x: order_list.index(list(x[2].keys())[0]))

    for module_name_lists, related_module_name_lists, compression_technique in layer_added_compress_methods:
        stored_mask = []
        need_mask = True if related_module_name_lists else False
        for i, mnl in enumerate(module_name_lists):
            for module_name in mnl:
                mask = fix_compression(c_model, module_name, compression_technique, dim_reduction=need_mask)
                if need_mask:
                    stored_mask.append(mask)
            if need_mask:
                for rmnl in related_module_name_lists[i]:
                    for j, module_name in enumerate(rmnl):
                        mask = fix_compression(c_model,
                                               module_name,
                                               compression_technique,
                                               mask=stored_mask[j],
                                               dim_reduction=True)
    return model

def find_tags(tokens, lexicon={}, model=None, morphology=None, context=None, entities=None, default=("NN", "NNP", "CD"), language="en", map=None, **kwargs):
    tagged = []
    # Tag known words.
    for i, token in enumerate(tokens):
        tagged.append([token, lexicon.get(token, i == 0 and lexicon.get(token.lower()) or None)])
    # Tag unknown words.
    for i, (token, tag) in enumerate(tagged):
        prev, next = (None, None), (None, None)
        if i > 0:
            prev = tagged[i - 1]
        if i < len(tagged) - 1:
            next = tagged[i + 1]
        if tag is None or token in (model is not None and model.unknown or ()):
            # Use language model (i.e., SLP).
            if model is not None:
                tagged[i] = model.apply([token, None], prev, next)
            # Use NNP for capitalized words (except in German).
            elif token.istitle() and language != "de":
                tagged[i] = [token, default[1]]
            # Use CD for digits and numbers.
            elif CD.match(token) is not None:
                tagged[i] = [token, default[2]]
            # Use suffix rules (e.g., -ly = RB).
            elif morphology is not None:
                tagged[i] = morphology.apply([token, default[0]], prev, next)
            # Use suffix rules (English default).
            elif language == "en":
                tagged[i] = _suffix_rules([token, default[0]])
            # Use most frequent tag (NN).
            else:
                tagged[i] = [token, default[0]]
    # Tag words by context.
    if context is not None and model is None:
        tagged = context.apply(tagged)
    # Tag named entities.
    if entities is not None:
        tagged = entities.apply(tagged)
    # Map tags with a custom function.
    if map is not None:
        tagged = [list(map(token, tag)) or [token, default[0]] for token, tag in tagged]
    return tagged

def inverse_transform(self, X, dict_type=dict):
        check_is_fitted(self, "feature_names_")

        # COO matrix is not subscriptable
        X = check_array(X, accept_sparse=["csr", "csc"])
        n_samples = X.shape[0]

        names = self.feature_names_
        dicts = [dict_type() for _ in range(n_samples)]

        if sp.issparse(X):
            for i, j in zip(*X.nonzero()):
                dicts[i][names[j]] = X[i, j]
        else:
            for i, d in enumerate(dicts):
                for j, v in enumerate(X[i, :]):
                    if v != 0:
                        d[names[j]] = X[i, j]

        return dicts

def generate_multiple_parameters(self, parameter_id_list, **kwargs):
        if self.first_one:
            params = []
            for one_id in parameter_id_list:
                init_challenger = self.smbo_solver.nni_smac_start()
                self.total_data[one_id] = init_challenger
                params.append(self.param_postprocess(init_challenger.get_dictionary()))
        else:
            challengers = self.smbo_solver.nni_smac_request_challengers()
            cnt = 0
            params = []
            for challenger in challengers:
                if cnt >= len(parameter_id_list):
                    break
                if self.dedup:
                    match = [v for k, v in self.total_data.items() \
                             if v.get_dictionary() == challenger.get_dictionary()]
                    if match:
                        continue
                self.total_data[parameter_id_list[cnt]] = challenger
                params.append(self.param_postprocess(challenger.get_dictionary()))
                cnt += 1
            if self.dedup and not params:
                self.logger.info('In generate_multiple_parameters: No more new parameters.')
        return params

def prepare_batch(batch: typing.Union[dict, list, torch.Tensor], device: str = "cpu"):
    if isinstance(batch, dict):
        batch = flatten(batch)
        for key, val in batch.items():
            try:
                batch[key] = val.to(device)
            except Exception:
                pass
        batch = unflatten(batch)
    elif torch.is_tensor(batch):
        batch = batch.to(device)
    elif isinstance(batch, list):
        for i in range(len(batch)):
            try:
                batch[i] = batch[i].to(device)
            except Exception:
                pass
    return batch

def rescale_output_resolution(
        self,
        scaling_factor: Union[Shaped[Tensor, "*num_cameras"], Shaped[Tensor, "*num_cameras 1"], float, int],
        scale_rounding_mode: str = "floor",
    ) -> None:
        if isinstance(scaling_factor, (float, int)):
            scaling_factor = torch.tensor([scaling_factor]).to(self.device).broadcast_to((self.cx.shape))
        elif isinstance(scaling_factor, torch.Tensor) and scaling_factor.shape == self.shape:
            scaling_factor = scaling_factor.unsqueeze(-1)
        elif isinstance(scaling_factor, torch.Tensor) and scaling_factor.shape == (*self.shape, 1):
            pass
        else:
            raise ValueError(
                f"Scaling factor must be a float, int, or a tensor of shape {self.shape} or {(*self.shape, 1)}."
            )

        self.fx = self.fx * scaling_factor
        self.fy = self.fy * scaling_factor
        self.cx = self.cx * scaling_factor
        self.cy = self.cy * scaling_factor
        if scale_rounding_mode == "floor":
            self.height = (self.height * scaling_factor).to(torch.int64)
            self.width = (self.width * scaling_factor).to(torch.int64)
        elif scale_rounding_mode == "round":
            self.height = torch.floor(0.5 + (self.height * scaling_factor)).to(torch.int64)
            self.width = torch.floor(0.5 + (self.width * scaling_factor)).to(torch.int64)
        elif scale_rounding_mode == "ceil":
            self.height = torch.ceil(self.height * scaling_factor).to(torch.int64)
            self.width = torch.ceil(self.width * scaling_factor).to(torch.int64)
        else:
            raise ValueError("Scale rounding mode must be 'floor', 'round' or 'ceil'.")

async def handle_request(
            request: Optional[Request],
            cancel_on_connect_interval,
            callback,
            *args,
            **kwargs,
        ):
            try:
                if cancel_on_connect_interval:
                    assert request is not None
                    res = await run_with_cancel_on_disconnect(
                        request, cancel_on_connect_interval, callback, *args, **kwargs
                    )
                else:
                    res = await callback(*args, **kwargs)
            except Exception as e:
                logger.info(f"Exception in handler:\n{traceback.format_exc()}")
                if isinstance(e, TimeoutError):
                    return JSONResponse(
                        {
                            "error": (
                                f"handler timeout after {self.handler_timeout} seconds"
                            )
                        },
                        status_code=504,
                    )
                elif isinstance(e, HTTPException):
                    return JSONResponse({"error": e.detail}, status_code=e.status_code)
                else:
                    return JSONResponse({"error": str(e)}, status_code=500)
            else:
                if res is None:
                    res = Response(status_code=204)
                elif not isinstance(res, response_class):
                    res = response_class(res)
                return res

def add_entrypoint_args_overrides(manifest: dict | list, overrides: dict) -> None:
    if isinstance(manifest, list):
        for item in manifest:
            add_entrypoint_args_overrides(item, overrides)
    elif isinstance(manifest, dict):
        if "spec" in manifest and "containers" in manifest["spec"]:
            containers = manifest["spec"]["containers"]
            for container in containers:
                if "command" in overrides:
                    container["command"] = overrides["command"]
                if "args" in overrides:
                    container["args"] = overrides["args"]
        for value in manifest.values():
            add_entrypoint_args_overrides(value, overrides)

def diagnose_ecs_task(
    event_detail: dict[str, Any],
) -> InfrastructureDiagnosis | None:
    if event_detail.get("lastStatus") != "STOPPED":
        return None

    stopped_reason: str = event_detail.get("stoppedReason") or ""
    stop_code: str = event_detail.get("stopCode") or ""

    # --- CannotPullContainerError (stoppedReason) --------------------------
    if "CannotPullContainerError" in stopped_reason:
        return InfrastructureDiagnosis(
            level=logging.ERROR,
            summary="Container image pull failed",
            detail=stopped_reason,
            resolution=(
                "Verify that the container image exists and the URI is correct."
                " If the image is in a private registry, ensure the task execution"
                " role has permissions to pull from it and that a repository"
                " authentication configuration is attached to the container definition."
            ),
        )

    # --- TaskFailedToStart (stopCode) --------------------------------------
    if stop_code == "TaskFailedToStart":
        return InfrastructureDiagnosis(
            level=logging.ERROR,
            summary="ECS task failed to start",
            detail=stopped_reason or "Task failed to start (no additional detail).",
            resolution=(
                "Check the stopped reason for specifics. Common causes include"
                " resource limits, missing IAM permissions, or networking"
                " misconfigurations. Review the ECS task and execution role policies."
            ),
        )

    # --- EssentialContainerExited (stopCode) --------------------------------
    if stop_code == "EssentialContainerExited":
        return _diagnose_container_exit_codes(event_detail, essential_exited=True)

    # --- Container exit code analysis (non-zero or null) -------------------
    containers: list[dict[str, Any]] = event_detail.get("containers", [])
    if containers:
        has_failure = any(
            c.get("exitCode") is None or c.get("exitCode") != 0 for c in containers
        )
        if has_failure:
            return _diagnose_container_exit_codes(event_detail)

    return None

def get_fp32_grad_partitions(self) -> Dict[int, Dict[int, Tensor]]:
        if not get_accelerator().resolves_data_dependency():
            self.reduce_and_partition_stream.synchronize()
        grad_dict = collections.defaultdict(dict)
        if self.offload_optimizer:
            for group in self.fp16_groups:
                for param_idx, param in enumerate(group):
                    group_idx, dest_offset, num_elements = self.grad_position[self.get_param_id(param)]
                    fp32_grad = self.fp32_partitioned_groups_flat[group_idx].grad.narrow(0, dest_offset, num_elements)
                    grad_dict[group_idx][param_idx] = fp32_grad
        else:
            for group_idx, group in self.averaged_gradients.items():
                for param_idx, gradient in enumerate(group):
                    grad_dict[group_idx][param_idx] = gradient.float()

        return grad_dict

def load_conll(f, ignore_gapping=True, keep_line_numbers=False):
        # f is open() or io.StringIO()
        doc, sent = [], []
        doc_comments, sent_comments = [], []
        for line_idx, line in enumerate(f):
            # leave whitespace such as NBSP, in case it is meaningful in the conll-u doc
            line = line.lstrip().rstrip(' \n\r\t')
            if len(line) == 0:
                if len(sent) > 0:
                    doc.append(sent)
                    sent = []
                    doc_comments.append(sent_comments)
                    sent_comments = []
            else:
                if line.startswith('#'): # read comment line
                    sent_comments.append(line)
                    continue
                array = line.split('\t')
                if ignore_gapping and '.' in array[0]:
                    continue
                if len(array) != FIELD_NUM:
                    raise CoNLLError(f"Cannot parse CoNLL line {line_idx+1}: expecting {FIELD_NUM} fields, {len(array)} found at line {line_idx}\n  {array}")
                if keep_line_numbers:
                    if array[-1] == "_" or array[-1] is None:
                        array[-1] = "%s=%d" % (LINE_NUMBER, line_idx)
                    else:
                        array[-1] = "%s|%s=%d" % (array[-1], LINE_NUMBER, line_idx)
                sent += [array]
        if len(sent) > 0:
            doc.append(sent)
            doc_comments.append(sent_comments)
        return doc, doc_comments

def normalize_example(self, example, hparams):
    length = self.max_length(hparams)
    def _to_constant_shape(tensor):
      tensor = tensor[:length]
      tensor = tf.pad(tensor, [(0, length - tf.shape(tensor)[0])])
      return tf.reshape(tensor, [length])

    if self.has_inputs:
      example['inputs'] = _to_constant_shape(example['inputs'])
      example['targets'] = _to_constant_shape(example['targets'])
    elif 'inputs' in example:
      if self.packed_length:
        raise ValueError('cannot concatenate packed examples on the fly.')
      inputs = example.pop('inputs')[:-1]  # Remove EOS token.
      targets = tf.concat([inputs, example['targets']], 0)
      example['targets'] = _to_constant_shape(targets)
    else:
      example['targets'] = _to_constant_shape(example['targets'])
    if self.packed_length:
      if self.has_inputs:
        if 'inputs_segmentation' in example:
          example['inputs_segmentation'] = _to_constant_shape(
              example['inputs_segmentation'])
          example['inputs_position'] = _to_constant_shape(
              example['inputs_position'])
        else:
          example['inputs_segmentation'] = tf.to_int64(
              tf.not_equal(example['inputs'], 0))
          example['inputs_position'] = (
              example['inputs_segmentation'] * tf.range(length, dtype=tf.int64))
      if 'targets_segmentation' in example:
        example['targets_segmentation'] = _to_constant_shape(
            example['targets_segmentation'])
        example['targets_position'] = _to_constant_shape(
            example['targets_position'])
      else:
        example['targets_segmentation'] = tf.to_int64(
            tf.not_equal(example['targets'], 0))
        example['targets_position'] = (
            example['targets_segmentation'] * tf.range(length, dtype=tf.int64))
    return example

def make_float(self, s, sign="+"):
        if decimal and self.float_type == NUMBER_DECIMAL:
            return self.make_decimal(s, sign)

        if s.startswith("-") or s.startswith("+"):
            sign = s[0]
            s = s[1:]
        elif isinstance(sign, int):
            if sign < 0:
                sign = "-"
            else:
                sign = "+"

        try:
            f = float(s)
        except ValueError:
            f = nan
        else:
            if sign == "-":
                f *= -1
        return f

def has_len_all_ranks(
    dataloader: object,
    strategy: "pl.strategies.Strategy",
    allow_zero_length_dataloader_with_multiple_devices: bool = False,
) -> TypeGuard[Sized]:
    local_length = sized_len(dataloader)
    if local_length is None:
        # __len__ is not defined, skip these checks
        return False

    total_length = strategy.reduce(torch.tensor(local_length, device=strategy.root_device), reduce_op="sum")
    if total_length == 0:
        rank_zero_warn(
            f"Total length of `{type(dataloader).__name__}` across ranks is zero."
            " Please make sure this was your intention."
        )
    if total_length > 0 and local_length == 0:
        dataloader_cls_name = type(dataloader).__name__
        if not allow_zero_length_dataloader_with_multiple_devices:
            raise RuntimeError(
                f"`{dataloader_cls_name}` within local rank has zero length."
                " Please make sure that it returns at least 1 batch."
            )
        rank_zero_warn(
            f"Total length of `{dataloader_cls_name}` across ranks is zero, but local rank has zero"
            " length. Please be cautious of uneven batch length."
        )

    if has_iterable_dataset(dataloader):
        rank_zero_warn(
            "Your `IterableDataset` has `__len__` defined."
            " In combination with multi-process data loading (when num_workers > 1),"
            " `__len__` could be inaccurate if each worker is not configured independently"
            " to avoid having duplicate data."
        )
    return True

async def remove_virtual_env(
        self,
        model_name: str,
        model_engine: Optional[str] = None,
        python_version: Optional[str] = None,
        worker_ip: Optional[str] = None,
    ) -> bool:
        if not model_name:
            raise ValueError("model_name is required")

        target_ip_worker_ref = (
            self._get_worker_ref_by_ip(worker_ip) if worker_ip is not None else None
        )
        if (
            worker_ip is not None
            and not self.is_local_deployment()
            and target_ip_worker_ref is None
        ):
            raise ValueError(f"Worker ip address {worker_ip} is not in the cluster.")

        # If specific worker is requested, remove only from that worker
        if target_ip_worker_ref:
            return await target_ip_worker_ref.remove_virtual_env(
                model_name, model_engine, python_version
            )

        # Otherwise, remove from all workers that have the virtual environment
        ret = True
        workers_with_env = []

        # First, identify which workers have the virtual environment
        for worker in self._worker_address_to_worker.values():
            try:
                envs = await worker.list_virtual_envs(model_name, model_engine)
                if envs:
                    workers_with_env.append(worker)
            except Exception as e:
                logger.debug(f"Failed to check worker for virtual environment: {e}")

        # Then remove from those workers
        for worker in workers_with_env:
            try:
                result = await worker.remove_virtual_env(
                    model_name, model_engine, python_version
                )
                ret = ret and result
            except Exception as e:
                logger.error(f"Failed to remove virtual environment from worker: {e}")
                ret = False

        return ret

def commutator(self, other):
        final_ps = PauliSentence()

        if isinstance(other, PauliWord):
            for pw1 in self:
                comm_pw, coeff = pw1._commutator(other)
                if len(comm_pw) != 0:
                    final_ps[comm_pw] += coeff * self[pw1]

            return final_ps

        if not isinstance(other, PauliSentence):
            if other.pauli_rep is None:
                raise NotImplementedError(
                    f"Cannot compute a native commutator of a Pauli word or sentence with the operator {other} of type {type(other)}."
                    f"You can try to use qml.commutator(op1, op2, pauli=False) instead."
                )
            other = qml.pauli.pauli_sentence(other)

        for pw1 in self:
            for pw2 in other:
                comm_pw, coeff = pw1._commutator(pw2)
                if len(comm_pw) != 0:
                    final_ps[comm_pw] += coeff * self[pw1] * other[pw2]

        return final_ps

def check_hyperopt_parameter_dicts(config: "ModelConfig") -> None:  # noqa: F821
    if config.hyperopt is None:
        return

    from ludwig.schema.hyperopt.utils import get_parameter_cls, parameter_config_registry  # noqa: F401

    for parameter, space in config.hyperopt.parameters.items():
        # skip nested hyperopt parameters
        if parameter != ".":
            parameter_attribute_path = parameter.split(".")
            passed = False

            for root in [config, config.input_features, config.output_features]:
                current = root
                for p in parameter_attribute_path:
                    try:
                        current = current.__getattribute__(p)
                        if p == parameter_attribute_path[-1]:
                            passed = True
                    except AttributeError:
                        break
                if passed:
                    break

            if not passed:
                raise ConfigValidationError(
                    f"The supplied hyperopt parameter {parameter} is not a valid config field. Check the Ludwig "
                    "docs for the list of valid parameters."
                )

            try:
                space_cls = get_parameter_cls(space["space"])
                space_cls.from_dict(space)
            except KeyError:
                space_types = ", ".join(parameter_config_registry.keys())
                raise ConfigValidationError(
                    f"Invalid hyperopt parameter space requested for `hyperopt.parameters.{parameter}`. Valid spaces "
                    f"are {space_types}."
                )

def apply_to_type(
    x: Any | collections.Sequence | collections.Mapping | str | bytes,
    input_type: type | tuple[type[Any], Any],
    func: Callable,
) -> Any | collections.Sequence | collections.Mapping | str | bytes:
    if isinstance(x, input_type):
        return func(x)
    if isinstance(x, (str, bytes)):
        return x
    if isinstance(x, collections.Mapping):
        return cast(Callable, type(x))({k: apply_to_type(sample, input_type, func) for k, sample in x.items()})
    if isinstance(x, tuple) and hasattr(x, "_fields"):  # namedtuple
        return cast(Callable, type(x))(*(apply_to_type(sample, input_type, func) for sample in x))
    if isinstance(x, collections.Sequence):
        return cast(Callable, type(x))([apply_to_type(sample, input_type, func) for sample in x])
    raise TypeError((f"x must contain {input_type}, dicts or lists; found {type(x)}"))

def push_weights_from_transformers(self, transformers_model):
        if not _has_transformers:
            raise ImportError("transformers not available")
        t0 = time.time()
        # Extract state dict from model, handling LoRA models properly
        if hasattr(transformers_model, "model") and hasattr(
            transformers_model.model, "state_dict"
        ):
            # TorchRL wrapper (e.g., TransformersWrapper)
            model = transformers_model.model
            # Check if it's a LoRA model
            if hasattr(model, "merge_and_unload"):
                state_dict = model.merge_and_unload().state_dict()
            else:
                state_dict = model.state_dict()
        elif hasattr(transformers_model, "state_dict"):
            # Direct transformers model
            # Check if it's a LoRA model
            if hasattr(transformers_model, "merge_and_unload"):
                state_dict = transformers_model.merge_and_unload().state_dict()
            else:
                state_dict = transformers_model.state_dict()
        else:
            raise TypeError(
                f"Cannot extract state_dict from {type(transformers_model)}"
            )

        t1 = time.time()
        torchrl_logger.debug(f"Time to extract state_dict: {t1 - t0}")
        # Convert to iterator for memory efficiency
        weights_iter = iter(state_dict.items())
        self.push_weights(weights_iter)
        torchrl_logger.debug(f"Time to push weights: {time.time() - t1}")

def build_combined_spanish_dataset(paths, model_type, dataset):
    udbase_dir = paths["UDBASE"]
    handparsed_dir = paths["HANDPARSED_DIR"]

    treebanks = ["UD_Spanish-AnCora", "UD_Spanish-GSD"]

    if dataset == 'train' and model_type == common.ModelType.POS:
        documents = {}
        for treebank in treebanks:
            conllu_file = common.find_treebank_dataset_file(treebank, udbase_dir, dataset, "conllu", fail=True)
            new_sents = read_sentences_from_conllu(conllu_file)
            if not treebank.endswith("AnCora"):
                new_sents = strip_xpos(new_sents)
            documents[treebank] = new_sents

        return documents

    if dataset == 'train':
        sents = []
        for treebank in treebanks:
            conllu_file = common.find_treebank_dataset_file(treebank, udbase_dir, dataset, "conllu", fail=True)
            new_sents = read_sentences_from_conllu(conllu_file)
            print("Read %d sentences from %s" % (len(new_sents), conllu_file))
            if treebank.endswith("GSD"):
                new_sents = replace_semicolons(new_sents)
