        if model_type in (common.ModelType.TOKENIZER, common.ModelType.MWT, common.ModelType.LEMMA):
            extra_spanish = os.path.join(handparsed_dir, "spanish-mwt", "adjectives.conllu")
            if not os.path.exists(extra_spanish):
                raise FileNotFoundError("Cannot find the extra dataset 'adjectives.conllu' which includes various multi-words retokenized, expected {}".format(extra_spanish))
            extra_sents = read_sentences_from_conllu(extra_spanish)
            print("Read %d sentences from %s" % (len(extra_sents), extra_spanish))
            sents.extend(extra_sents)
    else:
        conllu_file = common.find_treebank_dataset_file("UD_Spanish-AnCora", udbase_dir, dataset, "conllu", fail=True)
        sents = read_sentences_from_conllu(conllu_file)

    return sents

def snapshot_brain_montage(fig, montage, hide_sensors=True):
    from ..channels import DigMontage

    # Update the backend
    from .backends.renderer import _get_renderer

    if fig is None:
        raise ValueError("The figure must have a scene")
    if isinstance(montage, DigMontage):
        chs = montage._get_ch_pos()
        ch_names, xyz = zip(*[(ich, ixyz) for ich, ixyz in chs.items()])
    elif isinstance(montage, Info):
        xyz = [ich["loc"][:3] for ich in montage["chs"]]
        ch_names = [ich["ch_name"] for ich in montage["chs"]]
    elif isinstance(montage, dict):
        if not all(len(ii) == 3 for ii in montage.values()):
            raise ValueError("All electrode positions must be length 3")
        ch_names, xyz = zip(*[(ich, ixyz) for ich, ixyz in montage.items()])
    else:
        raise TypeError(
            "montage must be an instance of `DigMontage`, `Info`, or `dict`"
        )

    # initialize figure
    renderer = _get_renderer(fig, show=True)

    xyz = np.vstack(xyz)
    proj = renderer.project(xyz=xyz, ch_names=ch_names)
    if hide_sensors is True:
        proj.visible(False)

    im = renderer.screenshot()
    proj.visible(True)
    return proj.xy, im

def add_samples(self, data_points, labels):
        if len(data_points) == 0:
            raise TypeError("data_points is empty")

        if len(labels) == 0:
            raise TypeError("labels is empty")

        if len(data_points[0]) != self.number_of_dimensions:
            raise TypeError(
                "dimensionality of data_points != expected number of dimensions"
            )

        if len(data_points) != len(labels):
            raise TypeError("len(data_points) !=  len(labels)")

        # Validate the types of the labels before adding any points.
        self._validate_label_types(labels)

        for data_point in data_points:
            sample = (
                self.spec.kNearestNeighborsClassifier.nearestNeighborsIndex.floatSamples.add()
            )
            for feature in data_point:
                sample.vector.append(feature)

        if self.spec.kNearestNeighborsClassifier.HasField("int64ClassLabels"):
            for label in labels:
                self.spec.kNearestNeighborsClassifier.int64ClassLabels.vector.append(
                    label
                )
        else:
            # string labels
            for label in labels:
                self.spec.kNearestNeighborsClassifier.stringClassLabels.vector.append(
                    label
                )

def read_file_tool(agent: Any, file_path: str, **kwargs) -> str:
    try:
        # Resolve path - if relative, use agent workspace
        if not os.path.isabs(file_path):
            workspace_dir = agent._get_agent_workspace_dir()
            full_path = os.path.join(workspace_dir, file_path)
        else:
            full_path = file_path

        # Check if file exists
        if not os.path.exists(full_path):
            return f"Error: File does not exist at {full_path}"

        # Read file
        with open(full_path, "r", encoding="utf-8") as f:
            content = f.read()

        # Add to memory
        agent.short_memory.add(
            role="File Operations",
            content=f"Read file: {full_path} ({len(content)} characters)",
        )

        if agent.verbose:
            logger.info(f"Read file: {full_path}")

        return content
    except Exception as e:
        error_msg = f"Error reading file {file_path}: {str(e)}"
        logger.error(error_msg)
        agent.short_memory.add(
            role="File Operations",
            content=f"Error: {error_msg}",
        )
        return error_msg

def round_floats_for_json(obj, ndigits=2, key_ndigits=None):
    if key_ndigits is None:
        key_ndigits = {}

    if isinstance(obj, np.floating):
        obj = float(obj)
    elif isinstance(obj, np.ndarray):
        obj = obj.tolist()

    if isinstance(obj, float):
        obj = round(obj, ndigits)
    elif isinstance(obj, dict):
        new_obj = {}
        for k, v in obj.items():
            this_ndigits = key_ndigits.get(k, ndigits)
            new_obj[k] = round_floats_for_json(v, this_ndigits, key_ndigits)
        return new_obj
    elif isinstance(obj, str):
        return obj
    else:
        try:
            return [round_floats_for_json(x, ndigits, key_ndigits) for x in obj]
        except TypeError:
            pass

    return obj

def save(self, path: Optional[str] = None):
        if path is None:
            # If the user has not explicitly specified a path, we will be using the
            # cache directory to store the photon.
            create_cached_dir_if_needed()
            # assuming maximum 1000 versions for now
            for version in range(1000):
                if version == 0:
                    path = str(CACHE_DIR / f"{self._photon_name}.photon")
                else:
                    path = str(CACHE_DIR / f"{self._photon_name}.{version}.photon")
                if not os.path.exists(path):
                    break
            else:
                raise ValueError(
                    f"Can not find a valid path for creating photon {self._photon_name}"
                )
        with zipfile.ZipFile(path, "w") as f:
            metadata = self.metadata
            checked_extra_files = self._extra_files
            metadata["extra_files"] = list(checked_extra_files.keys())
            f.writestr(
                "metadata.json",
                json.dumps(metadata),
            )
            for name, path_or_content in checked_extra_files.items():
                if isinstance(path_or_content, bytes):
                    f.writestr(name, path_or_content)
                    continue
                elif isinstance(path_or_content, str):
                    if os.path.exists(path_or_content):
                        with open(path_or_content, "rb") as extra_file:
                            f.writestr(name, extra_file.read())
                    else:
                        f.writestr(name, path_or_content)
                else:
                    raise ValueError(
                        "extra_files value should be str or bytes, got"
                        f" {path_or_content}"
                    )

        # use path as local id for now
        add_photon(str(path), self._photon_name, self._photon_model, str(path))
        return path

def get_server(self) -> SMTP:
        smtp_server = self.smtp_server
        if isinstance(smtp_server, SMTPServer):
            smtp_server = smtp_server.value

        smtp_type = self.smtp_type
        smtp_port = self.smtp_port
        if smtp_port is None:
            smtp_port = smtp_type.value

        if smtp_type == SMTPType.INSECURE:
            server = SMTP(smtp_server, smtp_port)
        else:
            context = (
                ssl.create_default_context()
                if self.verify
                else ssl._create_unverified_context(protocol=ssl.PROTOCOL_TLS_CLIENT)
            )
            if smtp_type == SMTPType.SSL:
                server = SMTP_SSL(smtp_server, smtp_port, context=context)
            elif smtp_type == SMTPType.STARTTLS:
                server = SMTP(smtp_server, smtp_port)
                server.starttls(context=context)
        if self.username is not None:
            if not self.verify or smtp_type == SMTPType.INSECURE:
                try:
                    logger = get_run_logger()
                except Exception:
                    logger = internal_logger
                logger.warning(
                    """SMTP login is not secure without a verified SSL/TLS or SECURE connection. 
                    Without such a connection, the password may be sent in plain text, 
                    making it vulnerable to interception."""
                )
            server.login(self.username, self.password.get_secret_value())

        return server

def check_dumped_versions(configurations, *args):
    configurations = [configuration.strip() for configuration in configurations]
    versions = {version.split("=")[0]: version.split("=")[1] for version in configurations}
    if len(versions) != len(args):
        warnings.warn(
            "Loaded model contains an unexpected number of versions. You are probably loading a model coming from a different Hummingbird version."
        )

    for current_version in args:
        assert isinstance(current_version, ModuleType)
        if current_version.__name__ in versions:
            loaded_version = versions[current_version.__name__]
            if parse(loaded_version) != parse(current_version.__version__):
                warnings.warn(
                    "Version of {} used to save the model ({}) is different than the current version ({}).".format(
                        current_version.__name__, loaded_version, current_version.__version__
                    )
                )
        else:
            warnings.warn(
                "Module {} expected but not found. You are probably loading a model from a different version of Hummingbird.".format(
                    current_version.__name__
                )
            )

def tokenize(self, text):
        output_tokens = []
        for token in whitespace_tokenize(text):
            chars = list(token)
            if len(chars) > self.max_input_chars_per_word:
                output_tokens.append(self.unk_token)
                continue

            is_bad = False
            start = 0
            sub_tokens = []
            while start < len(chars):
                end = len(chars)
                cur_substr = None
                while start < end:
                    substr = "".join(chars[start:end])
                    if start > 0:
                        substr = "##" + substr
                    if substr in self.vocab:
                        cur_substr = substr
                        break
                    end -= 1
                if cur_substr is None:
                    is_bad = True
                    break
                sub_tokens.append(cur_substr)
                start = end

            if is_bad:
                output_tokens.append(self.unk_token)
            else:
                output_tokens.extend(sub_tokens)
        return output_tokens

def batch_agent_execution(
    agents: List[Union[Agent, Callable]],
    tasks: List[str] = None,
    imgs: List[str] = None,
    max_workers: int = max(1, int(os.cpu_count() * 0.9)),
):
    try:

        logger.info(
            f"Executing {len(agents)} agents on {len(tasks)} tasks"
        )

        if len(agents) != len(tasks):
            raise ValueError(
                "Number of agents must match number of tasks"
            )

        results = []

        formatter.print_panel(
            f"Executing {len(agents)} agents on {len(tasks)} tasks using {max_workers} workers"
        )

        with concurrent.futures.ThreadPoolExecutor(
            max_workers=max_workers
        ) as executor:
            # Submit all tasks to the executor
            future_to_task = {
                executor.submit(agent.run, task, imgs): (
                    agent,
                    task,
                    imgs,
                )
                for agent, task, imgs in zip(agents, tasks, imgs)
            }

            # Collect results as they complete
            for future in concurrent.futures.as_completed(
                future_to_task
            ):
                agent, task = future_to_task[future]
                try:
                    result = future.result()
                    results.append(result)
                except Exception as e:
                    print(
                        f"Task failed for agent {agent.agent_name}: {str(e)}"
                    )
                    results.append(None)

            # Wait for all futures to complete before returning
            concurrent.futures.wait(future_to_task.keys())

        return results
    except Exception as e:
        log = f"Batch agent execution failed Error: {str(e)} Traceback: {traceback.format_exc()}"

        logger.error(log)

        raise BatchAgentExecutionError(log)

def merge_configs(a, b, copy_trees=False):
        for key, value in b.items():
            # if key is in both a and b and both values are dictionary then merge it otherwise override it
            if key in a and isinstance(a[key], ConfigTree) and isinstance(b[key], ConfigTree):
                if copy_trees:
                    a[key] = a[key].copy()
                ConfigTree.merge_configs(a[key], b[key], copy_trees=copy_trees)
            else:
                if isinstance(value, ConfigValues):
                    value.parent = a
                    value.key = key
                    if key in a:
                        value.overriden_value = a[key]
                a[key] = value
                if a.root:
                    if b.root:
                        a.history[key] = a.history.get(key, []) + b.history.get(key, [value])
                    else:
                        a.history[key] = a.history.get(key, []) + [value]

        return a

def visit_function_call(self, node: ast.FunctionCall, context: Context):
        name = _resolve_name(node)  # str or Identifier

        if name in context.scopes["subroutines"]:
            return self._execute_function(name, node, context)

        if name in FUNCTIONS:
            # special handling since there is a loss of information when the parser encodes a bit string as an int
            if name in ("rotr", "rotl"):
                if isinstance(node.arguments[0], ast.Identifier):
                    var = context.retrieve_variable(_resolve_name(node.arguments[0]))
                    if var.ty == "BitType":
                        return FUNCTIONS[name](var, self.visit(node.arguments[1], context))
                    return FUNCTIONS[name](var.val, self.visit(node.arguments[1], context))
            return FUNCTIONS[name](*(self.visit(raw_arg, context) for raw_arg in node.arguments))

        raise NameError(
            f"Reference to subroutine {name} not available in calling namespace "
            f"on line {node.span.start_line}."
        )

def place_on_device(x, device):
    if isinstance(x, list):
        return [place_on_device(xi, device) for xi in x]
    elif isinstance(x, dict):
        return {k: place_on_device(v, device) for k, v in x.items()}
    elif isinstance(x, set):
        return {place_on_device(xi, device) for xi in x}
    elif isinstance(x, tuple):
        return tuple(place_on_device(xi, device) for xi in x)
    elif isinstance(x, torch.Tensor):
        return x.to(device)
    else:
        return x

def partition(self, exported_program: ExportedProgram) -> PartitionResult:
        partition_tags: Dict[str, DelegationSpec] = {}
        tag = "tag0"

        # Tag torch.cond and other control flow operations
        def is_control_flow(node: torch.fx.Node) -> bool:
            return node.op == "call_function" and node.target in [
                torch.ops.higher_order.cond,
                torch.ops.higher_order.map_impl,
                torch.ops.higher_order.while_loop,
            ]

        for node in exported_program.graph.nodes:
            if node.op == "call_function":
                node.meta["delegation_tag"] = tag
            # Tag get_attr nodes that are used by control flow operations
            elif node.op == "get_attr":
                # Check if any user is a control flow operation
                for user in node.users:
                    if is_control_flow(user):
                        node.meta["delegation_tag"] = tag
                        break

        partition_tags[tag] = self.delegation_spec

        tag_constant_data(exported_program)
        tag_mutated_buffer(exported_program)

        # Tag constant placeholders that have no users
        # tag_constant_data only tags constants that have users with delegation_tag
        # but we need to tag all constants for this partition
        for node in exported_program.graph.nodes:
            if node.op == "placeholder" and (
                is_param(exported_program, node)
                or is_buffer(exported_program, node)
                or is_lifted_tensor_constant(exported_program, node)
            ):
                if "delegation_tag" not in node.meta:
                    node.meta["delegation_tag"] = tag

        return PartitionResult(
            tagged_exported_program=exported_program, partition_tags=partition_tags
        )

def create_api_base_model(base_class, class_name):
    annotations = get_type_hints(base_class)
    if class_name in ("LLMSFTTrainingParamsAPI", "LLMRewardTrainingParamsAPI"):
        more_hidden_params = [
            "model_ref",
            "dpo_beta",
            "add_eos_token",
            "max_prompt_length",
            "max_completion_length",
        ]
    elif class_name == "LLMORPOTrainingParamsAPI":
        more_hidden_params = [
            "model_ref",
            "dpo_beta",
            "add_eos_token",
        ]
    elif class_name == "LLMDPOTrainingParamsAPI":
        more_hidden_params = [
            "add_eos_token",
        ]
    elif class_name == "LLMGenericTrainingParamsAPI":
        more_hidden_params = [
            "model_ref",
            "dpo_beta",
            "max_prompt_length",
            "max_completion_length",
        ]
    else:
        more_hidden_params = []
    _excluded = FIELDS_TO_EXCLUDE + more_hidden_params
    new_fields: Dict[str, Tuple[Any, Any]] = {}
    for name, field in base_class.__fields__.items():
        if name not in _excluded:
            field_type = annotations[name]
            if field.default is not None:
                field_default = field.default
            elif field.default_factory is not None:
                field_default = field.default_factory
            else:
                field_default = None
            new_fields[name] = (field_type, field_default)
    return create_model(
        class_name,
        **{key: (value[0], value[1]) for key, value in new_fields.items()},
        __config__=type("Config", (), {"protected_namespaces": ()}),
    )

def pc_back_to_front(self, name):
        if name is None:
            return None
        elif "summary:" in name:
            name = name.replace("summary:", "")
            return self.panel_metrics_helper.FRONTEND_NAME_MAPPING_REVERSED.get(
                name, name
            )
        elif name in self.FRONTEND_NAME_MAPPING_REVERSED:
            return self.FRONTEND_NAME_MAPPING_REVERSED[name]
        elif name in self.FRONTEND_NAME_MAPPING:
            return name
        elif name.startswith("config:") and ".value" in name:
            return name.replace("config:", "").replace(".value", "")
        elif name.startswith("summary_metrics."):
            return name.replace("summary_metrics.", "")
        return name

def stem(self, token):
        try:
            if token is None:
                raise ValueError(
                    "The word could not be stemmed, because \
                                 it is empty !"
                )
            # remove Arabic diacritics and replace some letters with others
            token = self.norm(token)
            # strip common prefixes of the nouns
            pre = self.pref(token)
            if pre is not None:
                token = pre
            # strip the suffixes which are common to nouns and verbs
            token = self.suff(token)
            # transform a plural noun to a singular noun
            ps = self.plur2sing(token)
            if ps is None:
                # transform from the feminine form to the masculine form
                fm = self.fem2masc(token)
                if fm is not None:
                    return fm
                else:
                    if pre is None:  # if the prefixes are not stripped
                        # strip the verb prefixes and suffixes
                        return self.verb(token)
            else:
                return ps
            return token
        except ValueError as e:
            print(e)

def model_surgery(src_path,
                  save_dir,
                  data_type='pascal_voc',
                  method='remove',
                  params_name=[
                      'model.roi_heads.box_predictor.cls_score',
                      'model.roi_heads.box_predictor.bbox_pred'
                  ]):

    assert method in ['remove',
                      'randinit'], '{} not implemented'.format(method)

    if data_type == 'coco':
        TAR_SIZE = 80
    elif data_type == 'pascal_voc':
        TAR_SIZE = 20
    else:
        NotImplementedError('{} dataset does not supported'.format(data_type))

    save_name = 'model_reset_' + ('remove' if method == 'remove' else
                                  'surgery') + '.pth'
    save_path = os.path.join(save_dir, save_name)
    os.makedirs(save_dir, exist_ok=True)

    ckpt = torch.load(src_path)
    if 'scheduler' in ckpt:
        del ckpt['scheduler']
    if 'optimizer' in ckpt:
        del ckpt['optimizer']
    if 'iteration' in ckpt:
        ckpt['iteration'] = 0

    if method == 'remove':
        for param_name in params_name:
            del ckpt['model'][param_name + '.weight']
            if param_name + '.bias' in ckpt['model']:
                del ckpt['model'][param_name + '.bias']
    elif method == 'randinit':
        tar_sizes = [TAR_SIZE + 1, TAR_SIZE * 4]
        for idx, (param_name,
                  tar_size) in enumerate(zip(params_name, tar_sizes)):
            surgery(data_type, param_name, True, tar_size, ckpt)
            surgery(data_type, param_name, False, tar_size, ckpt)
    else:
        raise NotImplementedError

    torch.save(ckpt, save_path)

async def payment_status_endpoint(app: BinduApplication, request: Request) -> Response:
    error_resp = validate_payment_manager(app)
    if error_resp:
        return error_resp

    assert app._payment_session_manager is not None  # Validated above

    session_id = request.path_params.get("session_id")
    if not session_id:
        return JSONResponse(content={"error": "Session ID required"}, status_code=400)

    wait = request.query_params.get("wait", "false").lower() == "true"

    if wait:
        # Wait for completion
        session = await app._payment_session_manager.wait_for_completion(
            session_id, timeout_seconds=PAYMENT_WAIT_TIMEOUT_SECONDS
        )
    else:
        # Get current status
        session = app._payment_session_manager.get_session(session_id)

    if session is None:
        return JSONResponse(
            content={"error": "Session not found or expired"}, status_code=404
        )

    # Prepare response
    response_data = {
        "session_id": session.session_id,
        "status": session.status,
    }

    if session.error:
        response_data["error"] = session.error

    # Include payment token if completed (but don't consume it!)
    if session.is_completed() and session.payment_payload:
        # Return the payment payload as base64-encoded JSON
        # This can be used directly as X-PAYMENT header
        payment_json = session.payment_payload.model_dump_json(by_alias=True)
        payment_token = base64.b64encode(payment_json.encode("utf-8")).decode("utf-8")
        response_data["payment_token"] = payment_token

    return JSONResponse(content=response_data)

def get_defined_names(base_dir: str) -> set[str]:
    defined_names = set()

    for root, _, files in os.walk(base_dir):
        for file in files:
            if not file.endswith(".py"):
                continue

            filepath = Path(root) / file

            try:
                with filepath.open(encoding="utf-8") as f:
                    file_content = f.read()

                tree = ast.parse(file_content, filepath)

                # Look for top-level definitions that don't start with underscore
                for node in ast.iter_child_nodes(tree):
                    defined_names.update(_extract_names_from_node(node))
            except (SyntaxError, UnicodeDecodeError, IsADirectoryError) as e:
                print(f"Error parsing {filepath}: {e}", file=sys.stderr)

    return defined_names

def proto_to_types(valuetype):
    if valuetype.WhichOneof("type") == "tensorType":
        tensortype = valuetype.tensorType
        dtype = types.PROTO_TO_BUILTIN_TYPE[tensortype.dataType]

        if tensortype.rank < 0:
            raise ValueError("Negative or Dynamic ranks not supported")
        if tensortype.rank != len(tensortype.dimensions):
            raise ValueError("Rank doesn't match the number of dimensions")
        if tensortype.attributes != {}:
            raise ValueError("Attributes on tensorType not supported")

        shape = []
        for i in range(tensortype.rank):
            shape.append(get_proto_dim(tensortype.dimensions[i]))

        # For the zero rank tensor, we always convert it back to scalar in PyMIL first
        if tensortype.rank == 0:
            return dtype

        return types.tensor(dtype, shape)

    elif valuetype.WhichOneof("type") == "listType":
        listtype = valuetype.listType
        elem_type = proto_to_types(listtype.type)

        if listtype.length.unknown:
            init_length = None
        else:
            init_length = listtype.length.constant.size

        # In the MIL proto, there is no such thing of "dynamic_length", hence we set it to True when
        # converting back to PyMIL
        return types.list(elem_type, init_length, dynamic_length=True)

    elif valuetype.WhichOneof("type") == "dictionaryType":
        dicttype = valuetype.dictionaryType
        keytype = proto_to_types(dicttype.keyType)
        valuetype = proto_to_types(dicttype.valueType)

        return types.dict(keytype, valuetype)

    elif valuetype.WhichOneof("type") == "stateType":
        wrapped_type = proto_to_types(valuetype.stateType.wrappedType)

        return types.state(wrapped_type)
    else:
        raise NotImplementedError("Types {} not yet implemented".format(valuetype.WhichOneof("type")))

def hocon_unquote_key(a_obj: Any) -> Any:
    if isinstance(a_obj, list):
        return [hocon_unquote_key(a) for a in a_obj]
    elif isinstance(a_obj, tuple):
        return tuple(hocon_unquote_key(a) for a in a_obj)
    elif not isinstance(a_obj, dict):
        return a_obj

    a_dict = a_obj

    # ConfigTree to dict
    if hasattr(a_dict, "as_plain_ordered_dict"):
        a_dict = a_dict.as_plain_ordered_dict()

    # preserve dict type
    new_dict = type(a_dict)()
    for k, v in a_dict.items():
        if isinstance(k, str) and k[0] == '"' and k[-1] == '"' and "." in k:
            new_dict[k[1:-1]] = hocon_unquote_key(v)
        else:
            new_dict[k] = hocon_unquote_key(v)
    return new_dict

def ngramize(items: List[str], ngram_range=(1, 1), doc: str = None) -> Generator[List[str], Any, None]:
    ngrams = []
    ranges = [(0, i) for i in range(ngram_range[0], ngram_range[1] + 1)]
    for r in ranges:
        ngrams += list(zip(*[items[j:] for j in range(*r)]))

    formatted_ngrams = [' '.join(item) for item in ngrams]
    if doc is not None:
        doc_lower = doc.lower()
        formatted_ngrams = [ngram for ngram in formatted_ngrams if (ngram in doc or ngram in doc_lower)]

    yield formatted_ngrams

def stem_and_skip_stop_words(self, words: list[str], *, shared_cache=True):
        def _stem_and_skip_stop_word(word: str):
            """
            Reduce a given word to its stem. If it's a stop word, return an empty string.
            E.g. "amazement", "amaze" and "amazed" all return "amaz".
            """
            cached = self._stem_cache.get(word)
            if cached is not None:
                return cached
            elif word in self._stop_words:
                return ""
            # Assumption: words that contain numbers are never stemmed
            elif RE_DIGIT.search(word):
                return word
            else:
                result = self._stemmer.stem(word)
                self._stem_cache.set(word, result)
                return result

        if shared_cache:
            self._stem_cache.load()

        # Stem the words and skip stop words
        result = " ".join(
            filter(None, (_stem_and_skip_stop_word(w) for w in words)),
        )
        if shared_cache:
            self._stem_cache.save()
        return result

async def get_idle_worker_for_job(
        self, gpu_requirements: Optional[Dict[str, Any]] = None, labels: Optional[Dict[str, str]] = None
    ) -> Optional[Worker]:
        loop = asyncio.get_running_loop()

        def _get():
            conn = self._get_connection()
            try:
                cursor = conn.cursor()
                cursor.execute("SELECT * FROM workers WHERE status = ?", (WorkerStatus.IDLE.value,))
                rows = cursor.fetchall()

                for row in rows:
                    worker = self._row_to_worker(row)

                    # Check GPU VRAM requirement
                    if gpu_requirements and "vram_gb" in gpu_requirements:
                        required_vram = gpu_requirements["vram_gb"]
                        worker_vram = worker.gpu_info.get("vram_gb", 0)
                        if worker_vram < required_vram:
                            continue

                    # Check labels - worker must have all required labels
                    if labels:
                        worker_labels = worker.labels or {}
                        if not all(worker_labels.get(k) == v for k, v in labels.items()):
                            continue

                    # Found a match
                    return worker

                return None
            finally:
                conn.close()

        return await loop.run_in_executor(None, _get)

def parse(self, *args: Any, **kwargs: Any) -> Any:
        p = self.parent
        call_kwargs = merge_args(args, kwargs)

        messages = call_kwargs.get("messages")
        if not messages:
            raise ValueError("messages required")

        model = call_kwargs.get("model")
        # Extract user-provided metadata (if any) - this is for OpenAI API, not our routing
        metadata = call_kwargs.pop("metadata", None) or {}

        # Get session metadata for proxy routing (this goes in the URL slug)
        routing_metadata = assemble_routing_metadata(metadata if isinstance(metadata, dict) else None)

        # Get client with metadata injection in URL
        if p.use_proxy:
            client = _get_scoped_client(p._client, p.base_url, routing_metadata, p._headers)
        else:
            client = _get_scoped_client(p._client, None, None, p._headers)

        # Call with_raw_response.parse() on the metadata-injected client
        start = time.perf_counter()
        raw_response = client.with_raw_response.chat.completions.parse(**call_kwargs)

        # Log trace if enabled
        if p.enable_local_tracing:
            latency_ms = (time.perf_counter() - start) * 1000
            # Handle both RawResponse (has .data) and LegacyAPIResponse (needs .parse())
            if hasattr(raw_response, "data"):
                resp_dict = raw_response.data.model_dump()
            elif hasattr(raw_response, "parse"):
                parsed = raw_response.parse()
                resp_dict = parsed.model_dump() if hasattr(parsed, "model_dump") else {}
            else:
                resp_dict = {}

            _log_trace(
                p._tracer or _SHARED_TRACER,
                model=model,
                messages=messages,
                response=resp_dict,
                token_ids=extract_completion_tokens(resp_dict),
                metadata=metadata,
                latency_ms=latency_ms,
            )

        return raw_response

def wait(self, timeout: int | None = None, refresh_every: int = 5) -> "InferenceEndpoint":
        if timeout is not None and timeout < 0:
            raise ValueError("`timeout` cannot be negative.")
        if refresh_every <= 0:
            raise ValueError("`refresh_every` must be positive.")

        start = time.time()
        while True:
            if self.status == InferenceEndpointStatus.FAILED:
                raise InferenceEndpointError(
                    f"Inference Endpoint {self.name} failed to deploy. Please check the logs for more information."
                )
            if self.status == InferenceEndpointStatus.UPDATE_FAILED:
                raise InferenceEndpointError(
                    f"Inference Endpoint {self.name} failed to update. Please check the logs for more information."
                )
            if self.status == InferenceEndpointStatus.RUNNING and self.url is not None:
                # Verify the endpoint is actually reachable
                _health_url = f"{self.url.rstrip('/')}/{self.health_route.lstrip('/')}"
                response = get_session().get(_health_url, headers=self._api._build_hf_headers(token=self._token))
                if response.status_code == 200:
                    logger.info("Inference Endpoint is ready to be used.")
                    return self

            if timeout is not None:
                if time.time() - start > timeout:
                    raise InferenceEndpointTimeoutError("Timeout while waiting for Inference Endpoint to be deployed.")
            logger.info(f"Inference Endpoint is not deployed yet ({self.status}). Waiting {refresh_every}s...")
            time.sleep(refresh_every)
            self.fetch()

def get_deal_price(self) -> pd.Series:
        if self.deal_price_type in ("bid_or_ask", "bid_or_ask_fill"):
            if self.order_dir is None:
                raise ValueError("Order direction cannot be none when deal_price_type is not close.")
            if self.order_dir == OrderDir.SELL:
                col = "$bid0"
            else:  # BUY
                col = "$ask0"
        elif self.deal_price_type == "close":
            col = "$close0"
        else:
            raise ValueError(f"Unsupported deal_price_type: {self.deal_price_type}")
        price = self.data[col]

        if self.deal_price_type == "bid_or_ask_fill":
            if self.order_dir == OrderDir.SELL:
                fill_col = "$ask0"
            else:
                fill_col = "$bid0"
            price = price.replace(0, np.nan).fillna(self.data[fill_col])

        return price

def get_unique_channels(
    image_sample: list[torch.Tensor],
    num_channels: int,
    num_classes: int = None,
) -> torch.Tensor:
    n_images = 0
    no_new_class = 0
    channel_class_map = None
    for img in image_sample:
        if img.ndim < 2:
            raise ValueError("Invalid image dimensions {img.ndim}")
        if img.ndim == 2:
            img = img.unsqueeze(0)
        if num_channels == 1 and num_channels_in_image(img) != 1:
            img = grayscale(img)
        if num_classes == 2 and num_channels_in_image(img) == 1:
            img = img.type(torch.float32) / 255
            img = img.round() * 255
            img = img.type(torch.uint8)

        img = img.flatten(1, 2)
        img = img.permute(1, 0)
        uniq_chans = img.unique(dim=0)

        if channel_class_map is None:
            channel_class_map = uniq_chans
        else:
            channel_class_map = torch.concat((channel_class_map, uniq_chans)).unique(dim=0)
        if channel_class_map.shape[0] > IMAGE_MAX_CLASSES:
            raise ValueError(
                f"Images inferred num classes {channel_class_map.shape[0]} exceeds " f"max classes {IMAGE_MAX_CLASSES}."
            )

        n_images += 1
        if n_images % 25 == 0:
            logger.info(f"Processed the first {n_images} images inferring {channel_class_map.shape[0]} classes...")

        if channel_class_map.shape[0] == uniq_chans.shape[0]:
            no_new_class += 1
            if no_new_class >= 4 and channel_class_map.shape[0] == num_classes:
                break  # early loop exit
        else:
            no_new_class = 0

    logger.info(f"Inferred {channel_class_map.shape[0]} classes from the first {n_images} images.")
    return channel_class_map.type(torch.uint8)

def adapt(self, data, steps=None):
        if self.num_bins is None:
            raise ValueError(
                "Cannot adapt a Discretization layer that has been initialized "
                "with `bin_boundaries`, use `num_bins` instead."
            )
        self.reset_state()
        if isinstance(data, tf.data.Dataset):
            if steps is not None:
                data = data.take(steps)
            for batch in data:
                self.update_state(batch)
        elif hasattr(data, "__iter__") and not (
            isinstance(data, np.ndarray)
            or backend.is_tensor(data)
            or tf.is_tensor(data)
        ):
            for i, batch in enumerate(data):
                if steps is not None and i >= steps:
                    break
                self.update_state(batch)
        else:
            self.update_state(data)
        self.finalize_state()

def update_drop_path_rate(
    model: VisionTransformer,
    drop_path_rate: float,
    mode: str = "linear",
) -> None:
    from timm.layers import DropPath

    total_depth = len(model.blocks)

    # Determine drop path rates based on the specified mode
    if mode == "linear":
        drop_probabilities = np.linspace(0, drop_path_rate, total_depth)
    elif mode == "uniform":
        drop_probabilities = [drop_path_rate for _ in range(total_depth)]
    else:
        raise ValueError(
            f"Unknown mode: '{mode}', supported modes are 'linear' and 'uniform'."
        )

    # Update the drop path rate for each block in the model
    for block, drop_prob in zip(model.blocks, drop_probabilities):
        if drop_prob > 0.0:
            block.drop_path1 = DropPath(drop_prob=drop_path_rate)
            block.drop_path2 = DropPath(drop_prob=drop_path_rate)
        else:
            block.drop_path1 = Identity()
            block.drop_path2 = Identity()

def generate_application_package_files(self):
        # Create the directories and files, and write content
        os.makedirs(self.base_dir, exist_ok=True)
        for subdir in self.subdirs:
            os.makedirs(os.path.join(self.base_dir, subdir), exist_ok=True)
            for file in self.application_package_files[subdir]:
                file_path = os.path.join(self.base_dir, subdir, file)
                with open(file_path, 'w') as f:
                    if file == "test_vespa_client.sd":
                        content_for_test_vespa_client_sd = self.get_test_vespa_client_schema_content()
                        f.write(content_for_test_vespa_client_sd)
        for file in self.application_package_files[""]:
            file_path = os.path.join(self.base_dir, file)
            with open(file_path, 'w') as f:
                if file == "services.xml":
                    content_for_services_xml = self.get_services_xml_content()
                    f.write(content_for_services_xml)
                if file == "hosts.xml":
                    # This will only happen for multinode
                    content_for_hosts_xml = self.get_hosts_xml_content()
                    f.write(content_for_hosts_xml)

def match_obj_type(
    type_or_obj: ValueType | type[ValueType],
) -> type[DatasetAttribute[HDF5Any, ValueType, ValueType]]:

    type_ = get_type(type_or_obj)
    if hasattr(type_, "type_id"):
        return DatasetAttribute.registry[type_.type_id]

    ret = DatasetAttribute.registry["array"]

    if type_ in DatasetAttribute.type_consumer_registry:
        ret = DatasetAttribute.type_consumer_registry[type_]
    elif issubclass(type_, Number):
        ret = DatasetAttribute.registry["scalar"]
    elif hasattr(type_, "__array__"):
        ret = DatasetAttribute.registry["array"]
    elif issubclass(type_, Sequence):
        ret = DatasetAttribute.registry["list"]
    elif issubclass(type_, Mapping):
        ret = DatasetAttribute.registry["dict"]
    elif is_pytree(type_):
        ret = DatasetAttribute.registry["pytree"]

    return ret

def maybe_init_target_entropy(self, fault_tolerant=True):
        if "_target_entropy" in self._buffers:
            return
        target_entropy = self._target_entropy
        device = next(self.parameters()).device
        if target_entropy == "auto":
            action_spec = self.get_action_spec()
            if action_spec is None:
                if fault_tolerant:
                    return
                raise RuntimeError(
                    "Cannot infer the dimensionality of the action. Consider providing "
                    "the target entropy explicitly or provide the spec of the "
                    "action tensor in the actor network."
                )
            if not isinstance(action_spec, Composite):
                action_spec = Composite({self.tensor_keys.action: action_spec})
            elif fault_tolerant and self.tensor_keys.action not in action_spec:
                return
            if (
                isinstance(self.tensor_keys.action, tuple)
                and len(self.tensor_keys.action) > 1
            ):
                action_container_shape = action_spec[self.tensor_keys.action[:-1]].shape
            else:
                action_container_shape = action_spec.shape
            target_entropy = -float(
                action_spec[self.tensor_keys.action]
                .shape[len(action_container_shape) :]
                .numel()
            )
        delattr(self, "_target_entropy")
        self.register_buffer(
            "_target_entropy", torch.tensor(target_entropy, device=device)
        )
        return self._target_entropy

def suff(self, token):
        if token.endswith("\u0643") and len(token) > 3:
            return token[:-1]
        if len(token) > 4:
            for s2 in self.su2:
                if token.endswith(s2):
                    return token[:-2]
        if len(token) > 5:
            for s3 in self.su3:
                if token.endswith(s3):
                    return token[:-3]
        if token.endswith("\u0647") and len(token) > 3:
            token = token[:-1]
            return token
        if len(token) > 4:
            for s2 in self.su22:
                if token.endswith(s2):
                    return token[:-2]
        if len(token) > 5:
            for s3 in self.su32:
                if token.endswith(s3):
                    return token[:-3]
        # $Noon and Alif
        if token.endswith("\u0646\u0627") and len(token) > 4:
            return token[:-2]
        return token

def from_numpy(
            cls: t.Type[TDataset],
            *args: np.ndarray,
            columns: t.Sequence[Hashable] = None,
            label_name: t.Hashable = None,
            **kwargs
    ) -> TDataset:
        if len(args) == 0 or len(args) > 2:
            raise DeepchecksValueError(
                "'from_numpy' constructor expecting to receive two numpy arrays (or at least one)."
                "First array must contains the columns and second the labels."
            )

        columns_array = args[0]
        columns_error_message = (
            "'from_numpy' constructor expecting columns (args[0]) "
            "to be not empty two dimensional array."
        )

        if len(columns_array.shape) != 2:
            raise DeepchecksValueError(columns_error_message)

        if columns_array.shape[0] == 0 or columns_array.shape[1] == 0:
            raise DeepchecksValueError(columns_error_message)

        if columns is not None and len(columns) != columns_array.shape[1]:
            raise DeepchecksValueError(
                f'{columns_array.shape[1]} columns were provided '
                f'but only {len(columns)} name(s) for them`s.'
            )

        elif columns is None:
            columns = [str(index) for index in range(1, columns_array.shape[1] + 1)]

        if len(args) == 1:
            labels_array = None
        else:
            labels_array = args[1]
            if len(labels_array.shape) != 1 or labels_array.shape[0] == 0:
                raise DeepchecksValueError(
                    "'from_numpy' constructor expecting labels (args[1]) "
                    "to be not empty one dimensional array."
                )

            labels_array = pd.Series(labels_array)
            if label_name:
                labels_array = labels_array.rename(label_name)

        return cls(
            df=pd.DataFrame(data=columns_array, columns=columns),
            label=labels_array,
            **kwargs
        )

def convert_to_float(value):
    if isinstance(value, float):
        return value
    if isinstance(value, int):
        return float(value)
    if not isinstance(value, str):
        raise ValueError("Argument value is not a string. Can't parse it as float")
    sanitized = value

    try:
        # Example: 1,000.7
        if "." in sanitized and "," in sanitized:
            return float(sanitized.replace(",", ""))
        # 1,000
        if "," in sanitized and _split_thousands(",", sanitized):
            return float(sanitized.replace(",", ""))
        # 5,5556
        if "," in sanitized and sanitized.count(",") == 1 and not _split_thousands(",", sanitized):
            return float(sanitized.replace(",", "."))
        # 0.0.0.1
        if sanitized.count(".") > 1:
            return float(sanitized.replace(".", ""))
        # 0,0,0,1
        if sanitized.count(",") > 1:
            return float(sanitized.replace(",", ""))
        return float(sanitized)
    except ValueError:
        # Avoid adding the sanitized value in the error message.
        raise ValueError("Unable to convert value to float")

def resolve_augmentation_backend(backend: str) -> str:
    if backend == "cpu":
        return "cpu"
    if backend == "auto":
        if not _has_cuda_device():
            return "cpu"
        try:
            import kornia.augmentation  # noqa: F401 # type: ignore[import-not-found]
        except ImportError:
            return "cpu"
        return "gpu"
    if backend == "gpu":
        if not _has_cuda_device():
            raise RuntimeError("augmentation_backend='gpu' requires a CUDA device")
        _require_kornia()
        return "gpu"
    raise ValueError(f"Unknown augmentation_backend {backend!r}; expected 'cpu', 'auto', or 'gpu'.")

def data_dict(self, records):
        self.version = records[0].replace("File-Date:", "").strip()
        dic = {}
        dic["deprecated"] = {}
        for label in [
            "language",
            "extlang",
            "script",
            "region",
            "variant",
            "redundant",
            "grandfathered",
        ]:
            dic["deprecated"][label] = {}
        for record in records[1:]:
            fields = [field.split(": ") for field in record.strip().split("\n")]
            typ = fields[0][1]
            tag = fields[1][1]
            if typ not in dic:
                dic[typ] = {}
            subfields = {}
            for field in fields[2:]:
                if len(field) == 2:
                    [key, val] = field
                    if key not in subfields:
                        subfields[key] = [val]
                    else:  # multiple value
                        subfields[key].append(val)
                else:  # multiline field
                    subfields[key][-1] += " " + field[0].strip()
                if (
                    "Deprecated" not in record
                    and typ == "language"
                    and key == "Description"
                ):
                    self.langcode[subfields[key][-1]] = tag
            for key in subfields:
                if len(subfields[key]) == 1:  # single value
                    subfields[key] = subfields[key][0]
            if "Deprecated" in record:
                dic["deprecated"][typ][tag] = subfields
            else:
                dic[typ][tag] = subfields
        return dic

def allocate(self, name: str, dim: Optional[int]) -> int:
        if name in self._stack:
            raise ValueError(f"duplicate plate '{name}'")
        if dim is None:
            # Automatically designate the rightmost available dim for allocation.
            dim = -1
            while -dim <= len(self._stack) and self._stack[-1 - dim] is not None:
                dim -= 1
        elif dim >= 0:
            raise ValueError(f"Expected dim < 0 to index from the right, actual {dim}")

        # Allocate the requested dimension.
        while dim < -len(self._stack):
            self._stack.append(None)
        if self._stack[-1 - dim] is not None:
            raise ValueError(
                "\n".join(
                    [
                        'at plates "{}" and "{}", collide at dim={}'.format(
                            name, self._stack[-1 - dim], dim
                        ),
                        "\nTry moving the dim of one plate to the left, e.g. dim={}".format(
                            dim - 1
                        ),
                    ]
                )
            )
        self._stack[-1 - dim] = name
        return dim

def extract_adapters_data(input_dir: str, output_dir: str):
    speech_lora = {}
    vision_lora = {}
    shards = [file for file in os.listdir(input_dir) if file.endswith(".safetensors")]
    for shard_file in shards:
        original_state_dict = load_file(os.path.join(input_dir, shard_file))
        for k, v in original_state_dict.items():
            if "lora" in k:
                if "speech" in k:
                    speech_lora[k.replace("speech.", "")] = v
                elif "vision" in k:
                    vision_lora[k.replace("vision.", "")] = v

    # Create and save the lora configs
    speech_lora_config = LoraConfig(
        r=320,
        lora_alpha=640,
        target_modules=r"model.layers.\d+.((self_attn.(qkv|o)_proj)|(mlp.(gate_up|down)_proj))",
        lora_dropout=0.01,
        task_type="CAUSAL_LM",
    )
    speech_lora_config.save_pretrained(os.path.join(output_dir, "speech-lora"))
    vision_lora_config = LoraConfig(
        r=256,
        lora_alpha=512,
        target_modules=r"model.layers.\d+.((self_attn.(qkv|o)_proj)|(mlp.(gate_up|down)_proj))",
        lora_dropout=0.0,
        task_type="CAUSAL_LM",
    )
    vision_lora_config.save_pretrained(os.path.join(output_dir, "vision-lora"))

    save_file(speech_lora, os.path.join(output_dir, "speech-lora", "adapter_model.safetensors"))
    save_file(vision_lora, os.path.join(output_dir, "vision-lora", "adapter_model.safetensors"))

def moe_permute_index_map_forward(
    inp: torch.Tensor,
    index: torch.Tensor,
    num_out_tokens: int,
    max_token_num: int,
) -> Tuple[torch.Tensor, torch.Tensor]:
    global _moe_permute_index_map_workspace, _moe_permute_index_map_max_expanded_token_num

    if not inp.numel():
        return inp.clone(), torch.tensor([], device=inp.device)

    if not inp.is_cuda:
        raise ValueError(f"inp must be a CUDA tensor, but got tensor on {inp.device}.")
    if not index.is_cuda:
        raise ValueError(f"index must be a CUDA tensor, but got tensor on {index.device}.")
    if inp.size(0) != index.size(0):
        raise ValueError(
            f"Permute not possible: inp.size(0) ({inp.size(0)}) must match "
            f"index.size(0) ({index.size(0)})."
        )
    assert (
        num_out_tokens >= 0
    ), f"moe_permute (index map) requires num_out_tokens >= 0, got {num_out_tokens}."
    if index.dtype != torch.int32:
        warnings.warn(
            f"The data type of the input `index` of Permute is {index.dtype}! "
            "The recommended type is torch.int32."
        )
        index = index.to(torch.int32)

    dtype = TE_DType[inp.dtype]

    topK = index.size(1)

    input_max_expanded_token_num = max(max_token_num, inp.size(0)) * topK
    if _moe_permute_index_map_max_expanded_token_num < input_max_expanded_token_num:
        _moe_permute_index_map_max_expanded_token_num = input_max_expanded_token_num
        _moe_permute_index_map_workspace = []

    permuted_act, row_id_map, _moe_permute_index_map_workspace = tex.moe_permute_fwd(
        inp,
        dtype,
        index,
        num_out_tokens,
        _moe_permute_index_map_workspace,
        _moe_permute_index_map_max_expanded_token_num,
    )

    return permuted_act, row_id_map

def sources(self) -> Dict[str, Any]:
        if self.__sources:
            return self.__sources
        # create path if not exists
        if not Path(self.__model_path).exists():
            Path(self.__model_path).mkdir(parents=True)
        # use empty sources if file not exist
        if not Path(self.__sources_full_path).exists():
            self.__sources = {
                'version': 2,
                'sources': []
            }
            return self.__sources
        try:
            with Path(self.__sources_full_path).open('r') as f:
                sources = yaml.safe_load(f.read())
        except Exception as e:
            raise SourcesError(
                f'Failed to load `{SOURCES_FILE_NAME}` in `{self.__model_path}`: {e}'
            )
        # In yaml `key:` is short for `key:None`
        # therefore an empty `sources:` is not a list
        # lazyly just bool testing, as it doesnt matter if empty or None
        if not sources.get('sources'):
            sources.update({'sources': []})
        self.__sources = sources
        return self.__sources

def pack_examples(examples,
                  has_inputs,
                  packed_length=256,
                  spacing=2,
                  queue_size=10,
                  chop_long_sequences=False):
  packer = SequencePairPacker if has_inputs else SequencePacker
  combined = []
  for example in examples:
    x = ((example["inputs"], example["targets"])
         if has_inputs else example["targets"])
    if chop_long_sequences and len(x) > packed_length:
      assert not has_inputs
      num_fragments = len(x) // packed_length
      for i in range(num_fragments):
        yield packer(
            x[packed_length * i:packed_length * (i + 1)], spacing).to_dict()
      x = x[packed_length * num_fragments:]
    added = False
    for c in combined:
      if c.can_fit(x, packed_length):
        c.add(x)
        added = True
        break
    if not added:
      if len(combined) == queue_size:
        yield combined[0].to_dict()
        combined = combined[1:]
      combined.append(packer(x, spacing))
  for c in combined:
    yield c.to_dict()

def jvp(tape, tangent, gradient_fn, gradient_kwargs=None):
    if len(tape.trainable_params) == 0:
        # The tape has no trainable parameters; the JVP
        # is simply none.
        def zero_jvp_for_single_shots(s):
            res = tuple(
                np.zeros(mp.shape(shots=s), dtype=mp.numeric_type) for mp in tape.measurements
            )
            return res[0] if len(tape.measurements) == 1 else res

        def zero_jvp(_):
            if tape.shots.has_partitioned_shots:
                return tuple(zero_jvp_for_single_shots(s) for s in tape.shots)
            return zero_jvp_for_single_shots(tape.shots.total_shots)

        return tuple(), zero_jvp

    multi_m = len(tape.measurements) > 1

    try:
        # if qml.math.allclose(qml.math.stack(tangent), 0):
        if math.allclose(tangent, 0):
            # If the tangent vector is zero, then the
            # corresponding element of the JVP will be zero,
            # and we can avoid a quantum computation.

            def func(_):
                # TODO: Update shape for CV variables and for qutrit simulations
                res = tuple(_single_measurement_zero(m, tangent) for m in tape.measurements)
                if not multi_m:
                    res = res[0]
                return res

            return [], func
    except (AttributeError, TypeError):
        pass

    gradient_kwargs = gradient_kwargs or {}
    gradient_tapes, fn = gradient_fn(tape, **gradient_kwargs)

    def processing_fn(results):
        # postprocess results to compute the Jacobian
        jac = fn(results)
        _jvp_fn = compute_jvp_multi if multi_m else compute_jvp_single

        # Jacobian without shot vectors
        if not tape.shots.has_partitioned_shots:
            return _jvp_fn(tangent, jac)

        # The jacobian is calculated for shot vectors
        return tuple(_jvp_fn(tangent, jac[i]) for i in range(tape.shots.num_copies))

    return gradient_tapes, processing_fn

def document(*fns, inherit=False, documentation_group=None):
    _documentation_group = documentation_group

    def inner_doc(cls):
        functions = list(fns)
        if hasattr(cls, "EVENTS"):
            functions += cls.EVENTS
        if inherit:
            classes_inherit_documentation[cls] = None

        documentation_group = _documentation_group  # avoid `nonlocal` reassignment
        if _documentation_group is None:
            try:
                modname = inspect.getmodule(cls).__name__  # type: ignore
                if modname.startswith("gradio.") or modname.startswith(
                    "gradio_client."
                ):
                    documentation_group = _get_module_documentation_group(modname)
                else:
                    # Then this is likely a custom Gradio component that we do not include in the documentation
                    pass
            except Exception as exc:
                warnings.warn(f"Could not get documentation group for {cls}: {exc}")
        classes_to_document[documentation_group].append((cls, functions))
        return cls

    return inner_doc

def transfer_artifacts(
        self, other_datastore: "TaskDataStore", names: Optional[List[str]] = None
    ):
        if (
            other_datastore.TYPE == self.TYPE
            and other_datastore._storage_impl.datastore_root
            == self._storage_impl.datastore_root
        ):
            # Nothing to transfer -- artifacts are already saved properly
            return

        # Determine which artifacts need to be transferred
        if names is None:
            # Transfer all artifacts from other datastore
            artifacts_to_transfer = list(other_datastore._objects.keys())
        else:
            # Transfer only specified artifacts
            artifacts_to_transfer = [
                name for name in names if name in other_datastore._objects
            ]

        if not artifacts_to_transfer:
            return

        # Get SHA keys for artifacts to transfer
        shas_to_transfer = [
            other_datastore._objects[name] for name in artifacts_to_transfer
        ]

        # Check which blobs are missing locally
        missing_shas = []
        for sha in shas_to_transfer:
            local_path = self._ca_store._storage_impl.path_join(
                self._ca_store._prefix, sha[:2], sha
            )
            if not self._ca_store._storage_impl.is_file([local_path])[0]:
                missing_shas.append(sha)

        if not missing_shas:
            return  # All blobs already exist locally

        # Load blobs from other datastore in transfer mode
        transfer_blobs = other_datastore._ca_store.load_blobs(
            missing_shas, is_transfer=True
        )

        # Save blobs to local datastore in transfer mode
        self._ca_store.save_blobs(transfer_blobs, is_transfer=True)

def verify_transitions(trees, sequences, transition_scheme, unary_limit, reverse, name, root_labels):
    model = SimpleModel(transition_scheme, unary_limit, reverse, root_labels)
    tlogger.info("Verifying the transition sequences for %d trees", len(trees))

    data = zip(trees, sequences)
    if tlogger.getEffectiveLevel() <= logging.INFO:
        data = tqdm(zip(trees, sequences), total=len(trees))

    for tree_idx, (tree, sequence) in enumerate(data):
        # TODO: make the SimpleModel have a parse operation?
        state = model.initial_state_from_gold_trees([tree])[0]
        for idx, trans in enumerate(sequence):
            if not trans.is_legal(state, model):
                raise RuntimeError("Tree {} of {} failed: transition {}:{} was not legal in a transition sequence:\nOriginal tree: {}\nTransitions: {}".format(tree_idx, name, idx, trans, tree, sequence))
            state = trans.apply(state, model)
        result = model.get_top_constituent(state.constituents)
        if reverse:
            result = result.reverse()
        if tree != result:
            raise RuntimeError("Tree {} of {} failed: transition sequence did not match for a tree!\nOriginal tree:{}\nTransitions: {}\nResult tree:{}".format(tree_idx, name, tree, sequence, result))

def download_or_cache(url, version):
    cache_dir = _get_xdg_cache_dir()

    if cache_dir is not None:  # Try to read from cache.
        try:
            data = (cache_dir / version).read_bytes()
        except OSError:
            pass
        else:
            return BytesIO(data)

    with urllib.request.urlopen(
        urllib.request.Request(url, headers={"User-Agent": ""})
    ) as req:
        data = req.read()

    if cache_dir is not None:  # Try to cache the downloaded file.
        try:
            cache_dir.mkdir(parents=True, exist_ok=True)
            with open(cache_dir / version, "xb") as fout:
                fout.write(data)
        except OSError:
            pass

    return BytesIO(data)

def cleanup(self) -> None:
        if self._cleanup_invoked:
            return
        self._cleanup_invoked = True

        try:
            if getattr(self, "gpu_circuit_breaker", None) is not None:
                self.gpu_circuit_breaker.stop_monitoring()
        except Exception as exc:
            logger.debug("Failed to stop GPU health monitor during cleanup: %s", exc, exc_info=True)

        try:
            if getattr(self, "bf", None) is not None:
                self.bf.stop_fetching()
        except Exception as exc:
            logger.debug("Failed to stop batch fetcher during cleanup: %s", exc, exc_info=True)

        try:
            if getattr(self, "model", None) is not None and hasattr(self.model, "unload"):
                self.model.unload()
        except Exception as exc:
            logger.warning("Failed to unload model components during cleanup: %s", exc, exc_info=True)

        try:
            reclaim_memory()
        except Exception as exc:
            logger.debug("Failed to reclaim accelerator memory during cleanup: %s", exc, exc_info=True)

def pyvi_tokenize(self, text):
        if len(text) == 0:
            return []
        elif text.isspace():
            return [text]
        segs = self.pyvi_sylabelize_with_ws(text)
        words = []
        preceding_ws = []
        for i, token in enumerate(segs):
            if not token.isspace():
                words.append(token)
                preceding_ws.append(
                    "" if (i == 0 or not segs[i - 1].isspace()) else segs[i - 1]
                )
        labels = self.ViTokenizer.ViTokenizer.model.predict(
            [self.ViTokenizer.ViTokenizer.sent2features(words, False)]
        )
        token = words[0]
        tokens = []
        for i in range(1, len(labels[0])):
            if (
                labels[0][i] == "I_W"
                and words[i] not in string.punctuation
                and words[i - 1] not in string.punctuation
                and not words[i][0].isdigit()
                and not words[i - 1][0].isdigit()
                and not (words[i][0].istitle() and not words[i - 1][0].istitle())
            ):
                token = token + preceding_ws[i] + words[i]
            else:
                tokens.append(token)
                token = words[i]
        tokens.append(token)
        return tokens

def serialize(self, serializer):
        self.t = serializer('t', self.t)
        if self.state is None:
            if isinstance(serializer, serializer_module.Deserializer):
                # try to initialize the state to retrieve state entries
                self._state = {}
                self_copy = copy.copy(self)
                arr = numpy.empty(1, dtype=numpy.float32)
                self_copy.init_state(variable.Variable(arr, grad=arr))

                for key in self._state:
                    try:
                        value = serializer(key, None)
                    except KeyError:
                        if self.enabled:
                            raise
                        value = None
                    # leave the update rule state as `None` if the keys are not
                    # contained in the snapshot, so that these states can be
                    # automatically initialized with the `_init_states` method
                    if value is None:
                        self._state = None
                        break
                    else:
                        self._state[key] = value
        else:
            for key in self._state:
                self._state[key] = serializer(key, self._state[key])

def table_from_frame(df, *, force_nominal=False, variables=None):
    XYM, domain = vars_from_df(df,
                               force_nominal=force_nominal,
                               variables=variables)

    if hasattr(df, 'orange_weights') and hasattr(df, 'orange_attributes'):
        W = [df.orange_weights[i] for i in df.index if i in df.orange_weights]
        if len(W) != len(df.index):
            W = None
        attributes = df.orange_attributes
        if isinstance(df.index, pd.MultiIndex) or not is_object_dtype(df.index):
            # we can skip checking for Orange indices when MultiIndex an when
            # not string dtype and so speedup the conversion
            ids = None
        else:
            ids = [
                int(i[2:])
                if str(i).startswith("_o") and i[2:].isdigit()
                else Table.new_id()
                for i in df.index
            ]
    else:
        W = None
        attributes = None
        ids = None

    return Table.from_numpy(
        domain,
        *XYM,
        W=W,
        attributes=attributes,
        ids=ids
    )

def wandb_track(
    name: str,
    data,
    datasets: bool = False,
    models: bool = False,
    others: bool = False,
    run: wandb.Run | None = None,
    testing: bool = False,
) -> str | None:
    # Check for pandas DataFrame
    if data_pandas and data_pandas.is_dataframe(data) and datasets:
        return data_pandas.track_dataframe(name, data, run, testing)

    # Check for PyTorch Module
    if data_pytorch and data_pytorch.is_nn_module(data) and models:
        return data_pytorch.track_nn_module(name, data, run, testing)

    # Check for scikit-learn BaseEstimator
    if data_sklearn and data_sklearn.is_estimator(data) and models:
        return data_sklearn.track_estimator(name, data, run, testing)

    # Check for Path objects
    if isinstance(data, Path) and datasets:
        return _track_path(name, data, run, testing)

    # Check for scalar types
    if isinstance(data, (dict, list, set, str, int, float, bool)):
        return _track_scalar(name, data, run, testing)

    # Generic fallback
    if others:
        return _track_generic(name, data, run, testing)

    # No action taken
    return None

async def deactivate_user(
    user_id: int,
    admin: User = Depends(require_permission("admin.users")),
) -> Dict[str, bool]:
    store = _get_store()

    # Prevent self-deactivation
    if user_id == admin.id:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Cannot deactivate your own account",
        )

    # Check if this would leave no active admins
    target_user = await store.get_user(user_id)
    if target_user and target_user.is_admin:
        all_users = await store.list_users(include_inactive=False)
        active_admins = [u for u in all_users if u.is_admin and u.id != user_id]
        if not active_admins:
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail="Cannot deactivate the last active admin user",
            )

    success = await store.deactivate_user(user_id)

    if not success:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"User {user_id} not found",
        )

    logger.info("User %d deactivated by admin %s", user_id, admin.username)

    return {"success": True}

def describe(
    scm: "Git",
    revs: Iterable[str],
    logger,
    refs: Optional[Iterable[str]] = None,
) -> dict[str, Optional[str]]:

    head_rev = scm.get_rev()
    head_ref = scm.get_ref("HEAD", follow=False)
    if head_ref and head_ref.startswith("refs/heads/"):
        head_branch = head_ref[len("refs/heads/") :]
    else:
        head_branch = None

    tags = {}
    branches = {}
    ref_it = iter(refs) if refs else scm.iter_refs()
    for ref in ref_it:
        is_tag = ref.startswith("refs/tags/")
        is_branch = ref.startswith("refs/heads/")
        if not (is_tag or is_branch):
            continue
        rev = scm.get_ref(ref)
        if not rev:
            logger.debug("unresolved ref %s", ref)
            continue
        if is_tag and rev not in tags:
            tags[rev] = ref[len("refs/tags/") :]
        if is_branch and rev not in branches:
            branches[rev] = ref[len("refs/heads/") :]

    names: dict[str, Optional[str]] = {}
    for rev in revs:
        if rev == head_rev and head_branch:
            names[rev] = head_branch
        else:
            names[rev] = tags.get(rev) or branches.get(rev)

    return names

def custom_getattr_mapper(node: torch.fx.Node, _: nn.Module) -> torch.fx.Node:
    # Have to use args here since getattr forces positional args.
    input_obj = node.args[0]
    attr_name = node.args[1]
    assert isinstance(input_obj, torch.fx.Node)
    input_obj_type = input_obj.meta["type"]

    # Handle named tuple access. NamedTupleMeta and the namedtuple factory function
    # create a subclass of tuple with an extra _fields attribute.
    if issubclass(input_obj_type, tuple) and hasattr(input_obj_type, "_fields"):
        idx = None
        for i, name in enumerate(input_obj_type._fields):
            if name == attr_name:
                idx = i
                break
        assert (
            idx is not None
        ), f"Named tuple type {input_obj_type} does not have field {name}"

        with node.graph.inserting_before(node):
            getitem_node = node.graph.call_function(
                getitem, kwargs={"input": input_obj, "idx": idx}
            )
            getitem_node.meta = node.meta.copy()
            return getitem_node

    assert input_obj_type in [
        torch.Tensor,
        torch.nn.parameter.Parameter,
    ], f"Expected torch.Tensor type for {input_obj_type}"
    assert (
        attr_name == "shape" or attr_name == "device" or attr_name == "dtype"
    ), f"Only supporting shape, device and dtype getattr for now, not {attr_name}"
    if attr_name == "shape":
        func = size
    elif attr_name == "device":
        func = device
    elif attr_name == "dtype":
        func = dtype
    with node.graph.inserting_before(node):
        size_node = node.graph.call_function(func, kwargs={"input": input_obj})
        size_node.meta = node.meta.copy()
        return size_node

def adjvec_to_op(adj_vecs, basis, is_orthogonal=True):
    assert math.shape(adj_vecs)[1] == len(basis)

    if all(isinstance(op, PauliSentence) for op in basis):
        if not is_orthogonal:
            gram = _gram_ps(basis)
            adj_vecs = math.tensordot(adj_vecs, math.linalg.pinv(sqrtm(gram)), axes=[[1], [0]])
        res = []
        for vec in adj_vecs:
            op_j = sum(c * op for c, op in zip(vec, basis))
            op_j.simplify()
            res.append(op_j)
        return res

    if all(isinstance(op, Operator) for op in basis):
        if not is_orthogonal:
            basis_ps = [op.pauli_rep for op in basis]
            gram = _gram_ps(basis_ps)
            adj_vecs = math.tensordot(adj_vecs, math.linalg.pinv(sqrtm(gram)), axes=[[1], [0]])
        res = []
        for vec in adj_vecs:
            op_j = sum(c * op for c, op in zip(vec, basis))
            op_j = simplify(op_j)
            res.append(op_j)
        return res

    if all(isinstance(op, TensorLike) for op in basis):
        if not is_orthogonal:
            gram = trace_inner_product(basis, basis).real
            adj_vecs = math.tensordot(adj_vecs, math.linalg.pinv(sqrtm(gram)), axes=[[1], [0]])
        return math.tensordot(adj_vecs, basis, axes=1)

    raise NotImplementedError(
        "At least one operator in the specified basis is of unsupported type, "
        "or not all operators are of the same type."
    )

def check_auto_termination(cluster_type: ClusterType):
    if cluster_type == ClusterType.K8S:
        workspaces = get_workspaces(cluster_type)
        for ws in workspaces:
            try:
                termination_policy = ws.lifecycle_config.termination_policy
                if termination_policy and termination_policy.enable_auto_termination:
                    workload_manager = ws.workload_manager
                    activity_details = workload_manager.get_workload_activity(ws.name)
                    max_idle_seconds = int(termination_policy.max_idle_seconds)
                    if activity_details and max_idle_seconds > 0:
                        active_pipeline_run_count = activity_details.get(
                            'active_pipeline_run_count'
                        )

                        last_user_request_ts = activity_details.get('last_user_request')
                        last_user_request = datetime.fromisoformat(last_user_request_ts)

                        latest_activity_time = last_user_request.timestamp()
                        last_scheduler_activity_ts = activity_details.get(
                            'last_scheduler_activity'
                        )
                        if last_scheduler_activity_ts:
                            last_scheduler_activity = datetime.fromisoformat(
                                last_scheduler_activity_ts
                            )
                            latest_activity_time = max(
                                latest_activity_time,
                                last_scheduler_activity.timestamp(),
                            )
                        now_time = datetime.utcnow().timestamp()
                        if (
                            not active_pipeline_run_count
                            and now_time - latest_activity_time > max_idle_seconds
                        ):
                            ws.stop()
            except Exception:
                pass

def as_dict(self, by_type = False) -> Dict[str, Dict[str, Union[int, None]]]:
        if by_type:
            ret = {'flops': {}, 'params': {}}
            for node in self.module.graph.nodes:
                node: Node
                if node.op == 'call_module':
                    module = self.fetch_attr(node.target)
                    if type(module).__name__ not in ret['flops']:
                        ret['flops'][type(module).__name__] = 0
                    if type(module) not in ret['params']:
                        ret['params'][type(module).__name__] = 0
                    ret['flops'][type(module).__name__] += NInfo(node).flops
                    ret['params'][type(module).__name__] += NInfo(node).param_size
            return ret
        else:
            return {
                'flops':
                {node.name: NInfo(node).flops for node in self.module.graph.nodes if node.op == 'call_module'},
                'params':
                {node.name: NInfo(node).param_size for node in self.module.graph.nodes if node.op == 'call_module'}
            }

def experiment(self) -> wandb.Run:
        if self._experiment is None:
            if self._offline:
                os.environ["WANDB_MODE"] = "dryrun"

            attach_id = getattr(self, "_attach_id", None)
            if wandb.run is not None:
                # wandb process already created in this instance
                rank_zero_warn(
                    "There is a wandb run already in progress and newly created instances of `WandbLogger` will reuse"
                    " this run. If this is not desired, call `wandb.finish()` before instantiating `WandbLogger`."
                )
                self._experiment = wandb.run
            elif attach_id is not None and hasattr(wandb, "_attach"):
                # attach to wandb process referenced
                self._experiment = wandb._attach(attach_id)
            else:
                # create new wandb process
                self._experiment = wandb.init(**self._wandb_init)

                # define default x-axis
                if isinstance(self._experiment, wandb.Run) and getattr(
                    self._experiment, "define_metric", None
                ):
                    self._experiment.define_metric("trainer/global_step")
                    self._experiment.define_metric(
                        "*", step_metric="trainer/global_step", step_sync=True
                    )

        self._experiment._label(repo="lightning_fabric_logger")  # pylint: disable=protected-access
        with telemetry.context(run=self._experiment) as tel:
            tel.feature.lightning_fabric_logger = True
        return self._experiment

def on_train_end(self, files, save_dir, last, best, epoch, results):
        if self.comet_log_predictions:
            curr_epoch = self.experiment.curr_epoch
            self.experiment.log_asset_data(self.metadata_dict, "image-metadata.json", epoch=curr_epoch)

        for f in files:
            self.log_asset(f, metadata={"epoch": epoch})
        self.log_asset(f"{save_dir}/results.csv", metadata={"epoch": epoch})

        if not self.opt.evolve:
            model_path = str(best if best.exists() else last)
            name = Path(model_path).name
            if self.save_model:
                self.experiment.log_model(
                    self.model_name,
                    file_or_folder=model_path,
                    file_name=name,
                    overwrite=True,
                )

        # Check if running Experiment with Comet Optimizer
        if hasattr(self.opt, "comet_optimizer_id"):
            metric = results.get(self.opt.comet_optimizer_metric)
            self.experiment.log_other("optimizer_metric_value", metric)

        self.finish_run()

def validate_object_content(content: bytes) -> None:
    try:
        # Check if there is a head-body divider
        index = content.find(HEAD_BODY_DIVIDER)
        if index == -1:
            raise ValueError(
                "Unexpected format for object content. Head and body "
                "could not be split."
            )

        head = _get_object_head(content)

        # check if the head has three parts:
        # <object_type> <children_ids> <object_body_len>
        head_decoded = head.decode(encoding="utf-8")
        head_parts = head_decoded.split(HEAD_VALUE_DIVIDER)

        if len(head_parts) != 3:
            raise ValueError("Unexpected format for object head.")

        obj_type, children_str, body_len = head_parts

        # Check that children IDs are valid IDs
        children = children_str.split(",")
        for children_id in children:
            if children_id and not is_valid_sha256_hash(children_id):
                raise ValueError(
                    f"Detected invalid object ID ({children_id}) in children."
                )

        # Check that object type is recognized
        if obj_type not in inflatable_class_registry:
            if obj_type != "CustomDataClass":  # to allow for the class in tests
                raise ValueError(f"Object of type {obj_type} is not supported.")

        # Check if the body length in the head matches that of the body
        actual_body_len = len(content) - len(head) - len(HEAD_BODY_DIVIDER)
        if actual_body_len != int(body_len):
            raise ValueError(
                f"Object content length expected {body_len} bytes but got "
                f"{actual_body_len} bytes."
            )

    except ValueError as err:
        raise UnexpectedObjectContentError(
            object_id=get_object_id(content), reason=str(err)
        ) from err

def verify(self, hashed: str, password: str) -> bool:
        if not hashed or not password:
            return False

        try:
            # Detect hash type from format
            if hashed.startswith("$argon2"):
                if self._hasher_type != "argon2":
                    logger.error("Argon2 hash found but argon2-cffi not installed")
                    return False
                from argon2.exceptions import VerifyMismatchError

                try:
                    self._argon2.verify(hashed, password)
                    return True
                except VerifyMismatchError:
                    return False

            elif hashed.startswith("$2"):
                # bcrypt hash
                if self._hasher_type == "bcrypt":
                    return self._bcrypt.checkpw(password.encode("utf-8"), hashed.encode("utf-8"))
                else:
                    import bcrypt

                    return bcrypt.checkpw(password.encode("utf-8"), hashed.encode("utf-8"))

            elif hashed.startswith("pbkdf2:"):
                return self._verify_pbkdf2(hashed, password)

            else:
                logger.warning("Unknown hash format")
                return False

        except Exception as exc:
            logger.error("Error verifying password: %s", exc)
            return False

def make_fixed_size(
    protein,
    shape_schema,
    msa_cluster_size,
    extra_msa_size,
    num_res=0,
    num_templates=0,
):

    def get_pad_size(cur_size, multiplier=4):
        return max(multiplier,
                   ((cur_size + multiplier - 1) // multiplier) * multiplier)

    if num_res is not None:
        input_num_res = (
            protein['aatype'].shape[0]
            if 'aatype' in protein else protein['msa_mask'].shape[1])
        if input_num_res != num_res:
            num_res = get_pad_size(input_num_res, 4)
    if 'extra_msa_mask' in protein:
        input_extra_msa_size = protein['extra_msa_mask'].shape[0]
        if input_extra_msa_size != extra_msa_size:
            extra_msa_size = get_pad_size(input_extra_msa_size, 8)
    pad_size_map = {
        N_RES: num_res,
        N_MSA: msa_cluster_size,
        N_EXTRA_MSA: extra_msa_size,
        N_TPL: num_templates,
    }

    for k, v in protein.items():
        # Don't transfer this to the accelerator.
        if k == 'extra_cluster_assignment':
            continue
        shape = list(v.shape)
        schema = shape_schema[k]
        msg = 'Rank mismatch between shape and shape schema for'
        assert len(shape) == len(schema), f'{msg} {k}: {shape} vs {schema}'
        pad_size = [
            pad_size_map.get(s2, None) or s1
            for (s1, s2) in zip(shape, schema)
        ]

        padding = [(0, p - v.shape[i]) for i, p in enumerate(pad_size)]
        padding.reverse()
        padding = list(itertools.chain(*padding))
        if padding:
            protein[k] = torch.nn.functional.pad(v, padding)
            protein[k] = torch.reshape(protein[k], pad_size)

    return protein

def make_value_estimator(self, value_type: ValueEstimators = None, **hyperparams):
        if value_type is None:
            value_type = self.default_value_estimator

        if isinstance(value_type, ValueEstimatorBase):
            self._value_estimator = value_type
            self.value_type = type(value_type)
            return self

        if isinstance(value_type, type) and issubclass(value_type, ValueEstimatorBase):
            if "device" not in hyperparams:
                device = self._default_device
                if device is not None:
                    hyperparams["device"] = device
            self._value_estimator = value_type(**hyperparams)
            self.value_type = value_type
            return self

        self.value_type = value_type
        if value_type == ValueEstimators.TD1:
            raise NotImplementedError(
                f"Value type {value_type} it not implemented for loss {type(self)}."
            )
        elif value_type == ValueEstimators.TD0:
            raise NotImplementedError(
                f"Value type {value_type} it not implemented for loss {type(self)}."
            )
        elif value_type == ValueEstimators.GAE:
            raise NotImplementedError(
                f"Value type {value_type} it not implemented for loss {type(self)}."
            )
        elif value_type == ValueEstimators.VTrace:
            raise NotImplementedError(
                f"Value type {value_type} it not implemented for loss {type(self)}."
            )
        elif value_type == ValueEstimators.TDLambda:
            raise NotImplementedError(
                f"Value type {value_type} it not implemented for loss {type(self)}."
            )
        else:
            raise NotImplementedError(f"Unknown value type {value_type}")

        return self

async def wait_for_exit(self, flow_run_id: UUID, grace_seconds: float = 30) -> bool:
        deadline = time.monotonic() + max(grace_seconds, 0)
        check_interval = max(grace_seconds / 10, 1) if grace_seconds > 0 else 0

        while True:
            handle = self.get(flow_run_id)
            if handle is None:
                return True

            if handle.returncode is not None:
                return True

            pid = handle.pid
            if pid is None:
                return True

            if not _pid_is_alive(pid):
                return True

            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False

            await anyio.sleep(min(check_interval, remaining))

def aggregate_failures(input_dir, output_file):
    failures = []
    input_path = Path(input_dir)

    if input_path.exists() and input_path.is_dir():
        for failure_file in input_path.glob("*.json"):
            try:
                with open(failure_file) as f:
                    failure_data = json.load(f)
                    failures.append(failure_data)
            except Exception as e:
                print(f"Error reading {failure_file}: {e}", file=sys.stderr)

    # Write aggregated failures
    with open(output_file, "w") as f:
        json.dump(failures, f, indent=2)

    print(f"Aggregated {len(failures)} failure(s) from {input_dir} to {output_file}")
    return len(failures)

def convert_added_tokens(
        cls, obj: Union[AddedToken, Any], save=False, add_type_field=True
    ):
        if isinstance(obj, dict) and "__type" in obj and obj["__type"] == "AddedToken":
            obj.pop("__type")
            return AddedToken(**obj)
        if isinstance(obj, AddedToken) and save:
            obj = obj.__getstate__()
            if add_type_field:
                obj["__type"] = "AddedToken"
            else:
                # Don't save "special" for previous tokenizers
                obj.pop("special")
            return obj
        if isinstance(obj, (list, tuple)):
            return [
                cls.convert_added_tokens(o, save=save, add_type_field=add_type_field)
                for o in obj
            ]
        if isinstance(obj, dict):
            return {
                k: cls.convert_added_tokens(v, save=save, add_type_field=add_type_field)
                for k, v in obj.items()
            }
        return obj

def construct_batch_groups(self, groups):
        self._groups = groups
        # calculate sizes of groups
        self._group_sizes = {}
        warns = []
        for name, group in self._groups.items():  # iterate over groups
            if self.drop_last:
                self._group_sizes[name] = len(group) // self.batch_size
            else:
                self._group_sizes[name] = (
                    len(group) + self.batch_size - 1
                ) // self.batch_size
            if self._group_sizes[name] == 0:
                self._group_sizes[name] = 1
                warns.append(name)
        if len(warns) > 0:
            warnings.warn(
                f"Less than {self.batch_size} samples available for "
                f"{len(warns)} prediction times. "
                f"Use batch size smaller than {self.batch_size}. "
                f"First 10 prediction times with small batch sizes: {warns[:10]}"
            )
        # create index from which can be sampled: index is equal to number of batches
        # associate index with prediction time
        self._group_index = np.repeat(
            list(self._group_sizes.keys()), list(self._group_sizes.values())
        )
        # associate index with batch within prediction time group
        self._sub_group_index = np.concatenate(
            [np.arange(size) for size in self._group_sizes.values()]
        )

def resolve_evaluator_from_catalog(benchmark: str) -> Evaluator | None:
    try:
        catalog = _load_dataset_catalog()
    except (FileNotFoundError, json.JSONDecodeError):
        return None

    entry = catalog.get("datasets", {}).get(benchmark)
    if entry is None:
        return None

    reward_fn_name = entry.get("reward_fn")
    if reward_fn_name is None:
        return None

    evaluator_cls = _EVALUATOR_REGISTRY.get(reward_fn_name)
    if evaluator_cls is not None:
        return evaluator_cls()

    # Fall through to full loader (user registry, import paths, entry points)
    try:
        return load_evaluator(reward_fn_name)
    except KeyError:
        return None

def promote_consts_to_inputs(f):
    indices = []
    consts = []

    if getattr(f, "__closure__", None) is not None:
        for ind, cell in enumerate(f.__closure__):
            val = cell.cell_contents
            if hasattr(val, "shape") and not all(isinstance(s, int) for s in val.shape):
                indices.append(ind)
                consts.append(val)

    def new_f(args, new_consts):
        """A version of f where the consts with dynamic shapes have been promoted to inputs."""

        # even deepcopy does not actually copy the closure for a function
        # we don't have a way to produce a new function with independent closure
        # so therefore we just need to make sure to clean up after ourselves after
        # in-place modifying the closure contents.

        try:
            for ind, c in zip(indices, new_consts, strict=True):
                f.__closure__[ind].cell_contents = c

            f_results = f(*args)
        finally:
            for ind, c in zip(indices, consts, strict=True):
                f.__closure__[ind].cell_contents = c

        return f_results, new_consts

    return new_f, consts

def handle_children_list(lst, augmenter_name, lst_name, default="sequential"):
    if lst is None:
        if default == "sequential":
            return Sequential([], name="%s-%s" % (augmenter_name, lst_name))
        return default
    if isinstance(lst, Augmenter):
        if ia.is_iterable(lst):
            # TODO why was this assert added here? seems to make no sense
            only_augmenters = all([isinstance(child, Augmenter)
                                   for child in lst])
            assert only_augmenters, (
                "Expected all children to be augmenters, got types %s." % (
                    ", ".join([str(type(v)) for v in lst])))
            return lst
        return Sequential(lst, name="%s-%s" % (augmenter_name, lst_name))
    if ia.is_iterable(lst):
        if len(lst) == 0 and default != "sequential":
            return default
        only_augmenters = all([isinstance(child, Augmenter)
                               for child in lst])
        assert only_augmenters, (
            "Expected all children to be augmenters, got types %s." % (
                ", ".join([str(type(v)) for v in lst])))
        return Sequential(lst, name="%s-%s" % (augmenter_name, lst_name))
    raise Exception(
        "Expected None, Augmenter or list/tuple as children list %s "
        "for augmenter with name %s, got %s." % (
            lst_name, augmenter_name, type(lst),))

def update_auth_settings(auth_config: Dict[str, Any]) -> None:
