def get_loss_func(
    problem_type: str,
    mixup_active: Optional[bool] = None,
    loss_func_name: Optional[str] = None,
    config: Optional[DictConfig] = None,
    **kwargs,
):
    if problem_type in [BINARY, MULTICLASS]:
        if mixup_active:
            loss_func = SoftTargetCrossEntropy()
        else:
            if loss_func_name is not None and loss_func_name.lower() == "focal_loss":
                loss_func = FocalLoss(
                    alpha=config.focal_loss.alpha,
                    gamma=config.focal_loss.gamma,
                    reduction=config.focal_loss.reduction,
                )
            else:
                loss_func = nn.CrossEntropyLoss(label_smoothing=config.label_smoothing)
                logger.debug(f"loss_func.label_smoothing: {loss_func.label_smoothing}")
    elif problem_type == REGRESSION:
        if loss_func_name is not None:
            if "bcewithlogitsloss" in loss_func_name.lower():
                loss_func = nn.BCEWithLogitsLoss()
            else:
                loss_func = nn.MSELoss()
        else:
            loss_func = nn.MSELoss()
    elif problem_type == NER:
        loss_func = nn.CrossEntropyLoss(ignore_index=0)
    elif problem_type in [None, OBJECT_DETECTION, FEW_SHOT_CLASSIFICATION]:
        return None
    elif problem_type == SEMANTIC_SEGMENTATION:
        if "structure_loss" in loss_func_name.lower():
            loss_func = StructureLoss()
        elif "balanced_bce" in loss_func_name.lower():
            loss_func = BBCEWithLogitLoss()
        elif "mask2former_loss" in loss_func_name.lower():
            weight_dict = {
                "loss_cross_entropy": config.mask2former_loss.loss_cross_entropy_weight,
                "loss_mask": config.mask2former_loss.loss_mask_weight,
                "loss_dice": config.mask2former_loss.loss_dice_weight,
            }
            loss_func = Mask2FormerLoss(
                config=Mask2FormerConfig(num_labels=kwargs["num_classes"]), weight_dict=weight_dict
            )
        else:
            loss_func = nn.BCEWithLogitsLoss()
    else:
        raise NotImplementedError

    return loss_func

def init_from_dict(self):
        D = self.param
        cc = D["cache"] if "cache" in D else None
        op = D["hyperparameters"] if "hyperparameters" in D else None

        if op is None:
            raise ValueError("`param` dictionary has no `hyperparemeters` key")

        if op and op["id"] == "SGD":
            optimizer = SGD()
        elif op and op["id"] == "RMSProp":
            optimizer = RMSProp()
        elif op and op["id"] == "AdaGrad":
            optimizer = AdaGrad()
        elif op and op["id"] == "Adam":
            optimizer = Adam()
        elif op:
            raise NotImplementedError("{}".format(op["id"]))
        optimizer.set_params(op, cc)
        return optimizer

def shard_param(param: Optional[torch.Tensor],
                shard_mode: ShardingType,
                shard_rank: int,
                num_shards: int,
                num_concatenated_matrices: int = 1,
                granularity: int = 32,
                bias_dims: int = 1) -> torch.Tensor:
    assert shard_rank < num_shards, "Shard rank must be less than num_shards"

    # Easier to hide this inside of the sharding logic than to add checks in every model
    # implementation.
    if param is None:
        return None

    if num_shards == 1:
        # Trivial case of no sharding.
        return param

    if shard_mode == ShardingType.OUTER_DIMENSION:

        def get_matrices(dim_idx: int) -> torch.Tensor:
            dim_size = param.size(dim_idx) // num_concatenated_matrices
            start_channel_id, end_channel_id = get_shard_endpoints(dim_size, shard_rank, num_shards, granularity)
            return torch.chunk(param, num_concatenated_matrices, dim=dim_idx), start_channel_id, end_channel_id

        if param.ndim == bias_dims:
            # Special case for bias parameters.
            matrices, start_channel_id, end_channel_id = get_matrices(dim_idx=-1)
            return torch.cat([mat[..., start_channel_id:end_channel_id] for mat in matrices], dim=-1)
        else:
            # General case for weight parameters. This assumes MoE parameters are stored in the format of
            # [num_experts, out_features, in_features]
            matrices, start_channel_id, end_channel_id = get_matrices(dim_idx=-2)
            return torch.cat([mat[..., start_channel_id:end_channel_id, :] for mat in matrices], dim=-2)

    elif shard_mode == ShardingType.INNER_DIMENSION:
        dim_size = param.size(-1) // num_concatenated_matrices
        start_channel_id, end_channel_id = get_shard_endpoints(dim_size, shard_rank, num_shards, granularity)
        matrices = torch.chunk(param, num_concatenated_matrices, dim=-1)
        return torch.cat([mat[..., start_channel_id:end_channel_id] for mat in matrices], dim=-1)

def get_boxes_from_bboxes(self, bboxes: np.ndarray) -> np.ndarray | None:
        if len(bboxes) == 0 or self.bbox_labels is None:
            return None

        # Get label encoder from BboxProcessor if needed
        bbox_processor = self.get_processor("bboxes")
        if bbox_processor is None:
            return None

        if not all(isinstance(label, (int, float)) for label in self.bbox_labels):
            label_fields = bbox_processor.params.label_fields
            if label_fields is None:
                raise ValueError("BboxParams.label_fields must be specified when using string labels")

            first_class_label = label_fields[0]
            # Access encoder through label_manager's metadata
            metadata = bbox_processor.label_manager.metadata["bboxes"][first_class_label]
            if metadata.encoder is None:
                raise ValueError(f"No encoder found for label field {first_class_label}")

            target_labels = metadata.encoder.transform(self.bbox_labels)
        else:
            target_labels = np.array(self.bbox_labels)

        # Filter boxes by labels (usually in column 4)
        mask = np.isin(bboxes[:, 4], target_labels)
        filtered_boxes = bboxes[mask, :4]

        return filtered_boxes if len(filtered_boxes) > 0 else None

def infer_modality(content: Union[str, List[str], bytes], media_download_headers: Optional[dict] = None) -> Modality:
    if isinstance(content, str):
        # Check if it's a base64-encoded image first
        if is_base64_image(content):
            return Modality.IMAGE

        if not validate_url(content):
            return Modality.TEXT

        # Encode the URL
        encoded_url = encode_url(content)
        extension = get_url_file_extension(encoded_url)

        # Check if the URL has a file extension
        if extension:
            modality: Optional[Modality] = _infer_modality_based_on_extension(extension)
            if modality:
                return modality

        # Use context manager to handle content sample
        try:
            with fetch_content_sample(encoded_url, media_download_headers) as sample:
                mime = magic.from_buffer(sample.read(), mime=True)
                modality: Modality = _infer_modality_based_on_mime_type(mime)
                return modality
        except requests.exceptions.RequestException as e:
            raise MediaDownloadError(f"Error downloading media file {content}: {e}") from e
        except magic.MagicException as e:
            raise MediaDownloadError(f"Error determining MIME type for {encoded_url}: {e}") from e
        except IOError as e:
            raise MediaDownloadError(f"IO error while processing {encoded_url}: {e}") from e

    elif isinstance(content, bytes):
        # Use python-magic for byte content
        mime = magic.from_buffer(content, mime=True)
        return _infer_modality_based_on_mime_type(mime)
    else:
        return Modality.TEXT

async def run_agents_with_tasks_async():
        results = []

        def run_agent_task_sync(agent: AgentType, task: str) -> Any:
            """Synchronous wrapper for agent execution with specific task."""
            return agent.run(task=task)

        loop = asyncio.get_event_loop()

        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            # Create tasks for agent-task pairs
            tasks_async = [
                loop.run_in_executor(
                    executor, run_agent_task_sync, agent, task
                )
                for agent, task in zip(agents, tasks)
            ]

            # Wait for all tasks to complete
            completed_tasks = await asyncio.gather(
                *tasks_async, return_exceptions=True
            )

            # Handle results and exceptions
            for i, result in enumerate(completed_tasks):
                if isinstance(result, Exception):
                    logger.error(
                        f"Agent {i+1} (task: {tasks[i][:50]}...) failed with error: {result}"
                    )
                    results.append(result)
                else:
                    results.append(result)

        return results

def copy(
        self, source: Union[str, Path], destination: Union[str, PurePosixPath]
    ) -> None:
        if not self.context:
            raise Exception("No context available")

        if not isinstance(destination, PurePosixPath):
            destination = PurePosixPath(destination)

        if not isinstance(source, Path):
            source = Path(source)

        if source.is_absolute():
            source = source.resolve().relative_to(self.base_directory)

        if self.temporary_directory:
            os.makedirs(self.context / source.parent, exist_ok=True)

            if source.is_dir():
                shutil.copytree(self.base_directory / source, self.context / source)
            else:
                shutil.copy2(self.base_directory / source, self.context / source)

        self.add_line(f"COPY {source} {destination}")

def binary_search_file(file, key, cache=None, cacheDepth=-1):
    key = key + " "
    keylen = len(key)
    start = 0
    currentDepth = 0

    if hasattr(file, "name"):
        end = os.stat(file.name).st_size - 1
    else:
        file.seek(0, 2)
        end = file.tell() - 1
        file.seek(0)

    if cache is None:
        cache = {}

    while start < end:
        lastState = start, end
        middle = (start + end) // 2

        if cache.get(middle):
            offset, line = cache[middle]

        else:
            line = ""
            while True:
                file.seek(max(0, middle - 1))
                if middle > 0:
                    file.discard_line()
                offset = file.tell()
                line = file.readline()
                if line != "":
                    break
                # at EOF; try to find start of the last line
                middle = (start + middle) // 2
                if middle == end - 1:
                    return None
            if currentDepth < cacheDepth:
                cache[middle] = (offset, line)

        if offset > end:
            assert end != middle - 1, "infinite loop"
            end = middle - 1
        elif line[:keylen] == key:
            return line
        elif line > key:
            assert end != middle - 1, "infinite loop"
            end = middle - 1
        elif line < key:
            start = offset + len(line) - 1

        currentDepth += 1
        thisState = start, end

        if lastState == thisState:
            # Detects the condition where we're searching past the end
            # of the file, which is otherwise difficult to detect
            return None

    return None

def first_commentable_line(lines):
    max_len = 100
    if lines[0].startswith(('"""', 'r"""')):
        if lines[0].count('"""') == 2:
            return 1
        for insert in range(1, min(max_len, len(lines))):
            if '"""' in lines[insert]:
                return insert + 1
        else:
            raise RuntimeError(
                f"Failed to find end of file docstring within {max_len} lines"
            )
    if lines[0].startswith("#!"):
        return 1
    else:
        return 0

def auto_label(name: str | label | None = None, scope: label_scope | None = None) -> str:
    if isinstance(name, label):
        # Already a label, no need to do anything.
        return cast(str, name)

    # Has scope is a special case, because it might not have been entered.
    if scope is not None:
        if not isinstance(scope, label_scope):
            raise TypeError('scope must be an instance of label_scope')
        if name is None:
            name = scope.next_label()
        scope.check_entered()
        return cast(str, label([*cast(List[str], scope.path), name]))

    # Fake a label scope and return its name directly.
    with label_scope(name) as scope:
        assert scope.path is not None
        return cast(str, label(scope.path))

def compute_loss(
        self,
        x=None,
        y=None,
        y_pred=None,
        sample_weight=None,
        training=True,
    ):
        # The default implementation does not use `x` or `training`.
        del x
        del training
        losses = []
        if self._compile_loss is not None:
            loss = self._compile_loss(y, y_pred, sample_weight)
            if loss is not None:
                losses.append(loss)
        for loss in self.losses:
            losses.append(self._aggregate_additional_loss(loss))
        if backend.backend() != "jax" and len(losses) == 0:
            raise ValueError(
                "No loss to compute. Provide a `loss` argument in `compile()`."
            )
        if len(losses) == 1:
            total_loss = losses[0]
        elif len(losses) == 0:
            total_loss = ops.zeros(())
        else:
            total_loss = ops.sum(losses)
        return total_loss

def deduce_default_output_parameters(
        dataset: TimeSeriesDataSet,
        kwargs: dict[str, Any],
        default_loss: MultiHorizonMetric = None,
    ) -> dict[str, Any]:

        # infer output size
        def get_output_size(normalizer, loss):
            if isinstance(loss, QuantileLoss):
                return len(loss.quantiles)
            elif isinstance(normalizer, NaNLabelEncoder):
                return len(normalizer.classes_)
            elif isinstance(loss, DistributionLoss):
                return len(loss.distribution_arguments)
            else:
                return 1  # default to 1

        # handle multiple targets
        new_kwargs = {}
        n_targets = len(dataset.target_names)
        if default_loss is None:
            default_loss = MAE()
        loss = kwargs.get("loss", default_loss)
        if n_targets > 1:  # try to infer number of output sizes
            if not isinstance(loss, MultiLoss):
                loss = MultiLoss([deepcopy(loss)] * n_targets)
                new_kwargs["loss"] = loss
            if isinstance(loss, MultiLoss) and "output_size" not in kwargs:
                new_kwargs["output_size"] = [
                    get_output_size(normalizer, l)
                    for normalizer, l in zip(
                        dataset.target_normalizer.normalizers, loss.metrics
                    )
                ]
        elif "output_size" not in kwargs:
            new_kwargs["output_size"] = get_output_size(dataset.target_normalizer, loss)
        return new_kwargs

def svm_train(arg1, arg2=None, arg3=None):
    prob, param = None, None
    if isinstance(arg1, (list, tuple)):
        assert isinstance(arg2, (list, tuple))
        y, x, options = arg1, arg2, arg3
        param = svm_parameter(options)
        prob = svm_problem(y, x, isKernel=(param.kernel_type == PRECOMPUTED))
    elif isinstance(arg1, svm_problem):
        prob = arg1
        if isinstance(arg2, svm_parameter):
            param = arg2
        else:
            param = svm_parameter(arg2)
    if prob is None or param is None:
        raise TypeError("Wrong types for the arguments")

    if param.kernel_type == PRECOMPUTED:
        for xi in prob.x_space:
            idx, val = xi[0].index, xi[0].value
            if xi[0].index != 0:
                raise ValueError('Wrong input format: first column must be 0:sample_serial_number')
            if val <= 0 or val > prob.n:
                raise ValueError('Wrong input format: sample_serial_number out of range')

    if param.gamma == 0 and prob.n > 0:
        param.gamma = 1.0 / prob.n
    libsvm.svm_set_print_string_function(param.print_func)
    err_msg = libsvm.svm_check_parameter(prob, param)
    if err_msg:
        raise ValueError('Error: %s' % err_msg)

    if param.cross_validation:
        l, nr_fold = prob.l, param.nr_fold
        target = (c_double * l)()
        libsvm.svm_cross_validation(prob, param, nr_fold, target)
        ACC, MSE, SCC = evaluations(prob.y[:l], target[:l])
        if param.svm_type in [EPSILON_SVR, NU_SVR]:
            print("Cross Validation Mean squared error = %g" % MSE)
            print("Cross Validation Squared correlation coefficient = %g" % SCC)
            return MSE
        else:
            print("Cross Validation Accuracy = %g%%" % ACC)
            return ACC
    else:
        m = libsvm.svm_train(prob, param)
        m = toPyModel(m)

        # If prob is destroyed, data including SVs pointed by m can remain.
        m.x_space = prob.x_space
        return m

def cwire_connections(layers, bit_map):
    if len(bit_map) == 0:
        return bit_map, {}, {}

    old_cwires = list(bit_map.values())
    connected_layers = {cwire: [] for cwire in old_cwires}
    connected_wires = {cwire: [] for cwire in old_cwires}

    for layer_idx, layer in enumerate(layers):
        for op in layer:
            _meas, con_wire = _get_meas(op, bit_map)

            for m in _meas:
                cwire = bit_map[m]
                connected_layers[cwire].append(layer_idx)
                if con_wire is not None:
                    connected_wires[cwire].append(con_wire)

    bit_map, connected_layers, connected_wires = _try_reusing_cwires(
        bit_map, connected_layers, connected_wires
    )

    return bit_map, connected_layers, connected_wires

def register_weights(
        self,
        params_map: dict[int, mp.Queue],
        init_queues: dict[int, mp.Queue],
        per_worker: bool = False,
    ) -> None:
        from torchrl.collectors.utils import _cast

        self._weight_queues = init_queues
        self._params_map = params_map
        self._per_worker = per_worker

        if per_worker:
            # Per-worker mode: each worker gets its own independent weight copy
            # No deduplication - every worker has unique weights
            self._unique_weights = []
            self._worker_to_weights_idx = (
                {}
            )  # Maps worker_idx to index in _unique_weights
            for worker_idx, weights in params_map.items():
                weights = weights.data.apply(_cast, weights)
                self._worker_to_weights_idx[worker_idx] = len(self._unique_weights)
                self._unique_weights.append(weights)
        else:
            # Default mode: device-based deduplication
            # Workers on the same device share the same weight buffer
            self._unique_weights = []
            for weights in params_map.values():
                if id(weights) in [id(w) for w in self._unique_weights]:
                    continue
                weights = weights.data.apply(_cast, weights)
                self._unique_weights.append(weights)

def get_optimizer(s):
    if "," in s:
        method = s[:s.find(',')]
        optim_params = {}
        for x in s[s.find(',') + 1:].split(','):
            split = x.split('=')
            assert len(split) == 2
            assert re.match("^[+-]?(\d+(\.\d*)?|\.\d+)$", split[1]) is not None
            optim_params[split[0]] = float(split[1])
    else:
        method = s
        optim_params = {}

    if method == 'adadelta':
        optim_fn = optim.Adadelta
    elif method == 'adagrad':
        optim_fn = optim.Adagrad
    elif method == 'adam':
        optim_fn = optim.Adam
    elif method == 'adamax':
        optim_fn = optim.Adamax
    elif method == 'asgd':
        optim_fn = optim.ASGD
    elif method == 'rmsprop':
        optim_fn = optim.RMSprop
    elif method == 'rprop':
        optim_fn = optim.Rprop
    elif method == 'sgd':
        optim_fn = optim.SGD
        assert 'lr' in optim_params
    else:
        raise Exception('Unknown optimization method: "%s"' % method)

    # check that we give good parameters to the optimizer
    expected_args = inspect.getfullargspec(optim_fn.__init__)[0]
    assert expected_args[:2] == ['self', 'params']
    if not all(k in expected_args[2:] for k in optim_params.keys()):
        raise Exception('Unexpected parameters: expected "%s", got "%s"' % (
            str(expected_args[2:]), str(optim_params.keys())))

    return optim_fn, optim_params

def effective_permissions(self) -> Set[str]:
        if self._effective_permissions is not None:
            return self._effective_permissions

        # Admin has all permissions
        if self.is_admin:
            return {"*"}

        # Combine permissions from all levels
        perms = set()
        for level in self.levels:
            perms.update(level.permissions)

        # Apply overrides
        for perm, granted in self.permission_overrides.items():
            if granted:
                perms.add(perm)
            else:
                perms.discard(perm)

        return perms

def TypedDict(typename, fields=_marker, /, *, total=True, closed=False, **kwargs):
        if fields is _marker or fields is None:
            if fields is _marker:
                deprecated_thing = "Failing to pass a value for the 'fields' parameter"
            else:
                deprecated_thing = "Passing `None` as the 'fields' parameter"

            example = f"`{typename} = TypedDict({typename!r}, {{}})`"
            deprecation_msg = (
                f"{deprecated_thing} is deprecated and will be disallowed in "
                "Python 3.15. To create a TypedDict class with 0 fields "
                "using the functional syntax, pass an empty dictionary, e.g. "
            ) + example + "."
            warnings.warn(deprecation_msg, DeprecationWarning, stacklevel=2)
            if closed is not False and closed is not True:
                kwargs["closed"] = closed
                closed = False
            fields = kwargs
        elif kwargs:
            raise TypeError("TypedDict takes either a dict or keyword arguments,"
                            " but not both")
        if kwargs:
            if sys.version_info >= (3, 13):
                raise TypeError("TypedDict takes no keyword arguments")
            warnings.warn(
                "The kwargs-based syntax for TypedDict definitions is deprecated "
                "in Python 3.11, will be removed in Python 3.13, and may not be "
                "understood by third-party type checkers.",
                DeprecationWarning,
                stacklevel=2,
            )

        ns = {'__annotations__': dict(fields)}
        module = _caller()
        if module is not None:
            # Setting correct module is necessary to make typed dict classes pickleable.
            ns['__module__'] = module

        td = _TypedDictMeta(typename, (), ns, total=total, closed=closed)
        td.__orig_bases__ = (TypedDict,)
        return td

def export_coco_as_yolo_via_yml(
    yml_path: str, output_dir: str, train_split_rate: float = 0.9, numpy_seed: int = 0, disable_symlink: bool = False
) -> str:
    try:
        import yaml
    except ImportError:
        raise ImportError('Please run "pip install -U pyyaml" to install yaml first for YOLO formatted exporting.')

    with open(yml_path) as stream:
        config_dict = yaml.safe_load(stream)

    if config_dict["train_json_path"]:
        if not config_dict["train_image_dir"]:
            raise ValueError(f"{yml_path} is missing `train_image_dir`")
        train_coco = Coco.from_coco_dict_or_path(
            config_dict["train_json_path"], image_dir=config_dict["train_image_dir"]
        )
    else:
        train_coco = None

    if config_dict["val_json_path"]:
        if not config_dict["val_image_dir"]:
            raise ValueError(f"{yml_path} is missing `val_image_dir`")
        val_coco = Coco.from_coco_dict_or_path(config_dict["val_json_path"], image_dir=config_dict["val_image_dir"])
    else:
        val_coco = None

    yaml_path = export_coco_as_yolo(
        output_dir=output_dir,
        train_coco=train_coco,
        val_coco=val_coco,
        train_split_rate=train_split_rate,
        numpy_seed=numpy_seed,
        disable_symlink=disable_symlink,
    )

    return yaml_path

def read_from_labelstudio_csv(path, data_columns, label_columns):
    if not os.path.exists(path):
