    labelstudio_csv = pd.read_csv(path)
    df = pd.DataFrame()
    columns = labelstudio_csv.columns
    # extracting columns for given data and label column names
    for col in data_columns:
        if col in columns:
            df[col] = labelstudio_csv[col]
        else:
