def segment_and_write_all_articles(file_path, output_file, min_article_character=200, workers=None,
                                   include_interlinks=False):
    if output_file is None:
        outfile = getattr(sys.stdout, 'buffer', sys.stdout)  # we want write bytes, so for py3 we used 'buffer'
    else:
        outfile = gensim.utils.open(output_file, 'wb')

    try:
        article_stream = segment_all_articles(file_path, min_article_character, workers=workers,
                                              include_interlinks=include_interlinks)
        for idx, article in enumerate(article_stream):
            article_title, article_sections = article[0], article[1]
            if include_interlinks:
                interlinks = article[2]

            output_data = {
                "title": article_title,
                "section_titles": [],
                "section_texts": [],
            }
            if include_interlinks:
                output_data["interlinks"] = interlinks

            for section_heading, section_content in article_sections:
                output_data["section_titles"].append(section_heading)
                output_data["section_texts"].append(section_content)

            if (idx + 1) % 100000 == 0:
                logger.info("processed #%d articles (at %r now)", idx + 1, article_title)
            outfile.write((json.dumps(output_data) + "\n").encode('utf-8'))

    finally:
        if output_file is not None:
            outfile.close()

def queue(
    fn=None,
    queue=None,
    max_tries=None,
    extend_fn=None,
    escape_fn=None,
    num_samples=None,
):

    if max_tries is None:
        max_tries = int(1e6)

    if extend_fn is None:
        extend_fn = util.enum_extend

    if escape_fn is None:
        escape_fn = util.discrete_escape

    if num_samples is None:
        num_samples = -1

    def wrapper(wrapped):
        def _fn(*args, **kwargs):
            for i in range(max_tries):
                assert (
                    not queue.empty()
                ), "trying to get() from an empty queue will deadlock"

                next_trace = queue.get()
                try:
                    ftr = trace(
                        escape(
                            replay(wrapped, trace=next_trace),  # noqa: F821
                            escape_fn=functools.partial(escape_fn, next_trace),
                        )
                    )
                    return ftr(*args, **kwargs)
                except NonlocalExit as site_container:
                    site_container.reset_stack()
                    for tr in extend_fn(
                        ftr.trace.copy(), site_container.site, num_samples=num_samples
                    ):
                        queue.put(tr)

            raise ValueError("max tries ({}) exceeded".format(str(max_tries)))

        return _fn

    return wrapper(fn) if fn is not None else wrapper

def common_filter(
    query: Query,
    data_schema,
    start_timestamp=None,
    end_timestamp=None,
    filters=None,
    order=None,
    limit=None,
    distinct=None,
    time_field="timestamp",
):
    assert data_schema is not None
    time_col = eval("data_schema.{}".format(time_field))

    if start_timestamp:
        query = query.filter(time_col >= to_pd_timestamp(start_timestamp))
    if end_timestamp:
        query = query.filter(time_col <= to_pd_timestamp(end_timestamp))

    if filters:
        for filter in filters:
            query = query.filter(filter)
    if order is not None:
        query = query.order_by(order)
    else:
        query = query.order_by(time_col.asc())
    if limit:
        query = query.limit(limit)
    if distinct:
        query = query.distinct(distinct)

    return query

def add_log_parameters_hook(
        self,
        module: Module,
        name: str = "",
        prefix: str = "",
        log_freq: int = 0,
    ) -> None:
        # if name is not None:
        prefix = prefix + name

        if not hasattr(module, "_wandb_hook_names"):
            module._wandb_hook_names = []

        def parameter_log_hook(module, input_, output, log_track):
            if not log_track_update(log_track):
                return
            for name, parameter in module.named_parameters():
                # for pytorch 0.3 Variables
                if isinstance(parameter, torch.autograd.Variable):
                    data = parameter.data
                else:
                    data = parameter
                self.log_tensor_stats(data.cpu(), "parameters/" + prefix + name)

        log_track_params = log_track_init(log_freq)
        try:
            hook = module.register_forward_hook(
                lambda mod, inp, outp: parameter_log_hook(
                    mod, inp, outp, log_track_params
                )
            )
            self._hook_handles["parameters/" + prefix] = hook
            module._wandb_hook_names.append("parameters/" + prefix)
        except RuntimeError as e:
            wandb.termwarn(
                f"Trying to register forward_hook failed ({e}) - skipping parameter tracking."
            )

def get_argnums(self, transform: BoundTransform) -> list[set[int]] | None:
        transform_index = self._get_idx_for_transform(transform)
        interface = _get_interface(self.qnode, self.args, self.kwargs)
        if interface not in ["jax", "jax-jit"]:
            return None

        if "argnum" in self._program[transform_index].kwargs:
            raise QuantumFunctionError(
                "argnum does not work with the Jax interface. You should use argnums instead."
            )

        transform = self._program[transform_index]
        argnums = self._program[-1].kwargs.get("argnums", None)

        if argnums is None and math.get_interface(self.args[0]) != "jax":
            raise QuantumFunctionError("No trainable parameters.")

        argnums = [0] if argnums is None else argnums
        argnums = [argnums] if isinstance(argnums, int) else argnums
        # pylint: disable=protected-access
        if (transform._use_argnum or transform.classical_cotransform) and argnums:
            subprogram = self._program[:transform_index]
            params = _jax_argnums_to_tape_trainable(
                self.qnode, argnums, subprogram, self.args, self.kwargs
            )
            return [math.get_trainable_indices(param) for param in params]
        return None

def inflate_runtime_output(
    value: Value, output_buffer: Optional[bytes]
) -> InferenceOutput:

    if value.val == ValueType.INT.value:
        if value.int_value is None:
            raise ValueError("Expected Int value, `None` provided")
        return value.int_value.int_val
    if value.val == ValueType.BOOL.value:
        if value.bool_value is None:
            raise ValueError("Expected Bool value, `None` provided")
        return value.bool_value.bool_val
    if value.val == ValueType.FLOAT.value:
        if value.float_value is None:
            raise ValueError("Expected Float value, `None` provided")
        return value.float_value.float_val
    if value.val == ValueType.DOUBLE.value:
        if value.double_value is None:
            raise ValueError("Expected Double value, `None` provided")
        return value.double_value.double_val
    if value.val == ValueType.TENSOR.value:
        return _parse_tensor_value(value.tensor, output_buffer)
    if value.val == ValueType.TENSOR_LIST.value:
        if value.tensor_list is None:
            raise ValueError("Expected TensorList value, `None` provided")
        return [
            _parse_tensor_value(t, output_buffer) for t in value.tensor_list.tensors
        ]

def result_to_parts(result: Any) -> list[Part]:
        # Fast path for strings
        if isinstance(result, str):
            return [TextPart(kind="text", text=result)]

        # Handle sequences
        if isinstance(result, (list, tuple)):
            # Check if all items are strings (common case)
            if result and all(isinstance(item, str) for item in result):
                return [TextPart(kind="text", text=item) for item in result]

            # Handle mixed types
            parts: list[Part] = []
            for item in result:
                if isinstance(item, str):
                    parts.append(TextPart(kind="text", text=item))
                elif isinstance(item, dict):
                    parts.append(PartConverter.dict_to_part(item))
                else:
                    parts.append(TextPart(kind="text", text=str(item)))
            return parts

        # Handle dictionaries
        if isinstance(result, dict):
            return [PartConverter.dict_to_part(result)]

        # Fallback: convert to text
        return [TextPart(kind="text", text=str(result))]

def docker_run(ctx, docker_run_args):
    import wandb.docker

    api = InternalApi()
    args = list(docker_run_args)
    if len(args) > 0 and args[0] == "run":
        args.pop(0)
    if len([a for a in args if a.startswith("--runtime")]) == 0 and _HAS_NVIDIA_DOCKER:
        args = ["--runtime", "nvidia"] + args
    #  TODO: image_from_docker_args uses heuristics to find the docker image arg, there are likely cases
    #  where this won't work
    image = util.image_from_docker_args(args)
    resolved_image = None
    if image:
        resolved_image = wandb.docker.image_id(image)
    if resolved_image:
        args = ["-e", f"WANDB_DOCKER={resolved_image}"] + args
    else:
        wandb.termlog(
            "Couldn't detect image argument, running command without the WANDB_DOCKER env variable"
        )
    if api.api_key:
        args = ["-e", f"WANDB_API_KEY={api.api_key}"] + args
    else:
        wandb.termlog(
            "Not logged in, run `wandb login` from the host machine to enable result logging"
        )
    subprocess.call(["docker", "run"] + args)

def write_corpus(fname, corpus, progress_cnt=1000, index=False, num_terms=None, metadata=False):
        mw = MmWriter(fname)

        # write empty headers to the file (with enough space to be overwritten later)
        mw.write_headers(-1, -1, -1)  # will print 50 spaces followed by newline on the stats line

        # calculate necessary header info (nnz elements, num terms, num docs) while writing out vectors
        _num_terms, num_nnz = 0, 0
        docno, poslast = -1, -1
        offsets = []
        if hasattr(corpus, 'metadata'):
            orig_metadata = corpus.metadata
            corpus.metadata = metadata
            if metadata:
                docno2metadata = {}
        else:
            metadata = False
        for docno, doc in enumerate(corpus):
            if metadata:
                bow, data = doc
                docno2metadata[docno] = data
            else:
                bow = doc
            if docno % progress_cnt == 0:
                logger.info("PROGRESS: saving document #%i", docno)
            if index:
                posnow = mw.fout.tell()
                if posnow == poslast:
                    offsets[-1] = -1
                offsets.append(posnow)
                poslast = posnow
            max_id, veclen = mw.write_vector(docno, bow)
            _num_terms = max(_num_terms, 1 + max_id)
            num_nnz += veclen
        if metadata:
            utils.pickle(docno2metadata, fname + '.metadata.cpickle')
            corpus.metadata = orig_metadata

        num_docs = docno + 1
        num_terms = num_terms or _num_terms

        if num_docs * num_terms != 0:
            logger.info(
                "saved %ix%i matrix, density=%.3f%% (%i/%i)",
                num_docs, num_terms, 100.0 * num_nnz / (num_docs * num_terms), num_nnz, num_docs * num_terms
            )

        # now write proper headers, by seeking and overwriting the spaces written earlier
        mw.fake_headers(num_docs, num_terms, num_nnz)

        mw.close()
        if index:
            return offsets

def assert_valid_class_labels(
    y: np.ndarray,
    allow_missing_classes: bool = True,
    allow_one_class: bool = False,
) -> None:
    if y.ndim != 1:
        raise ValueError("Labels must be 1D numpy array.")
    if any([isinstance(label, str) for label in y]):
        raise ValueError(
            "Labels cannot be strings, they must be zero-indexed integers corresponding to class indices."
        )
    if not np.equal(np.mod(y, 1), 0).all():  # check that labels are integers
        raise ValueError("Labels must be zero-indexed integers corresponding to class indices.")
    if min(y) < 0:
        raise ValueError("Labels must be positive integers corresponding to class indices.")

    unique_classes = np.unique(y)
    if (not allow_one_class) and (len(unique_classes) < 2):
        raise ValueError("Labels must contain at least 2 classes.")

    if not allow_missing_classes:
        if (unique_classes != np.arange(len(unique_classes))).any():
            msg = "cleanlab requires zero-indexed integer labels (0,1,2,..,K-1), but in "
            msg += "your case: np.unique(labels) = {}. ".format(str(unique_classes))
            msg += "Every class in (0,1,2,..,K-1) must be present in labels as well."
            raise TypeError(msg)

def recognize_entities(text, model, n=4, person="ignore"):
    doc = model(text)
    if person == "ignore":
        ents = Counter([ent.text.strip() for ent in list(doc.ents) if len(ent.text.strip()) >= 5])
    elif person:
        ents = Counter(
            [ent.text.strip() for ent in list(doc.ents) if ent.label_ == "PERSON" and len(ent.text.strip()) >= 5]
        )
    else:
        ents = Counter(
            [ent.text.strip() for ent in list(doc.ents) if ent.label_ != "PERSON" and len(ent.text.strip()) >= 5]
        )
    ents = ents.most_common(n)
    ents = ", ".join([a[0] for a in ents])

    return ents

def on_mouse_move(self, event):
        if not self.showverts:
            return
        if self._ind is None:
            return
        if event.inaxes is None:
            return
        if event.button != 1:
            return
        x, y = event.xdata, event.ydata

        self.poly.xy[self._ind] = x, y
        if self._ind == 0:
            self.poly.xy[-1] = x, y
        elif self._ind == len(self.poly.xy) - 1:
            self.poly.xy[0] = x, y
        self.line.set_data(zip(*self.poly.xy))

        self.canvas.restore_region(self.background)
        self.ax.draw_artist(self.poly)
        self.ax.draw_artist(self.line)
        self.canvas.blit(self.ax.bbox)

def query_controller(tag: str = None):
    prefix = "/retrievers/" + (tag.lstrip("/") if tag else "")

    if prefix.endswith("/"):
        prefix = prefix[:-1]

    def wrapper(cls) -> ClassBasedView:
        router = APIRouter(tags=[tag.strip("/") if tag else "retrievers"])

        http_method_names = ("GET", "POST", "PUT", "DELETE", "PATCH")

        for name, method in cls.__dict__.items():
            if callable(method) and hasattr(method, "method"):
                # Check if method is decorated with an HTTP method decorator
                if not hasattr(method, "__path__") or not method.__path__:
                    raise ValueError(f"Missing path for method {name}")

                http_method = method.method
                # Ensure that the method is a valid HTTP method
                if http_method not in http_method_names:
                    raise ValueError(f"Invalid method {http_method}")
                if prefix:
                    method.__path__ = prefix + method.__path__
                if not method.__path__.startswith("/"):
                    method.__path__ = "/" + method.__path__
                router.add_api_route(
                    method.__path__,
                    method,
                    methods=[http_method],
                    **method.__kwargs__,
                )

        def get_router() -> APIRouter:
            """
            Returns:
                APIRouter: The router associated with the controller.
            """
            return router

        cls.get_router = get_router

        return ClassBasedView(router=router, cls=cls)

    return wrapper

def alloc_tensor(
    shape: Expr,
    dtype: str | Expr,
    runtime_device_index: int | Expr,
    storage_scope: str | Expr = "global",
) -> Call:
    if not isinstance(shape, Expr):
        shape = convert_to_expr(shape)
    if isinstance(dtype, str):
        dtype = DataTypeImm(dtype)
    if isinstance(runtime_device_index, int):
        runtime_device_index = PrimValue(runtime_device_index)
    if isinstance(storage_scope, str):
        storage_scope = StringImm(storage_scope)
    if not isinstance(storage_scope, StringImm):
        raise ValueError(
            "relax.builtin.alloc_tensor expects string as the storage scope, "
            f"but {storage_scope} is got."
        )

    return _ffi_api.alloc_tensor(shape, dtype, runtime_device_index, storage_scope)  # type: ignore

def add_patterns(self, patterns: List[PatternType]) -> None:
        # disable the nlp components after this one in case they haven't been
        # initialized / deserialized yet
        try:
            current_index = -1
            for i, (name, pipe) in enumerate(self.nlp.pipeline):
                if self == pipe:
                    current_index = i
                    break
            subsequent_pipes = [pipe for pipe in self.nlp.pipe_names[current_index:]]
        except ValueError:
            subsequent_pipes = []
        with self.nlp.select_pipes(disable=subsequent_pipes):
            phrase_pattern_labels = []
            phrase_pattern_texts = []
            for entry in patterns:
                p_label = cast(str, entry["label"])
                p_id = cast(str, entry.get("id", ""))
                label = repr((p_label, p_id))
                self._match_label_id_map[self.nlp.vocab.strings.as_int(label)] = {
                    "label": p_label,
                    "id": p_id,
                }
                if isinstance(entry["pattern"], str):
                    phrase_pattern_labels.append(label)
                    phrase_pattern_texts.append(entry["pattern"])
                elif isinstance(entry["pattern"], list):
                    self.matcher.add(label, [entry["pattern"]])
                else:
                    raise ValueError(Errors.E097.format(pattern=entry["pattern"]))
                self._patterns.append(entry)
            for label, pattern in zip(
                phrase_pattern_labels,
                self.nlp.pipe(phrase_pattern_texts),
            ):
                self.phrase_matcher.add(label, [pattern])

def convert_div(self, el: Tag, text: str, **kwargs) -> str:
        classes = el.get("class", [])

        # Admonitions (tip, note, warning, etc.)
        if "admonition" in classes:
            return self._convert_admonition(el, classes)

        # marimo embed containers
        if "marimo-embed-container" in classes:
            iframe = el.find("iframe")
            if iframe and iframe.get("src"):
                return f"\n[Interactive marimo example]({iframe['src']})\n\n"
            return ""

        # Tabbed content sets
        if "tabbed-set" in classes:
            return self._convert_tabbed(el)

        # mkdocstrings doc signature blocks
        if "doc-signature" in classes or (
            "highlight" in classes and "doc-signature" in " ".join(classes)
        ):
            code_el = el.find("code")
            if code_el:
                raw = code_el.get_text()
                return f"\n```python\n{raw.strip()}\n```\n\n"

        # Doc contents - just pass through
        if "doc-contents" in classes:
            return f"\n{text}\n"

        # Default: return inner text
        return text

def get_dot_string(
        self, name_and_op_style=False, annotation=False, highlight_debug_nodes=None
    ):
        if highlight_debug_nodes is None:
            highlight_debug_nodes = []
        function_names = sorted(self.functions.keys())

        dotstring = "digraph g {\n" + "\tcompound=true;\n"
        # find all tensor nodes with unknown sizes
        ctr = 0
        for k in function_names:
            const_nodes = const_determined_nodes(self.functions[k].graph)
            unknown_sized_tensor_ops = []
            for v, n in self.functions[k].graph.items():
                if n.datatype is None or (
                    n.datatype is not None
                    and types.is_tensor(n.datatype)
                    and (
                        len(n.datatype.get_shape()) == 0 or -1 in n.datatype.get_shape()
                    )
                ):
                    unknown_sized_tensor_ops.append(v)
                if n.op in highlight_debug_nodes:
                    highlight_debug_nodes.append(v)

            v = self.functions[k]
            vis = DotVisitor(annotation)
            vis.highlight_nodes(v.inputs, "yellow").highlight_nodes(
                const_nodes, "azure2"
            ).highlight_nodes(v.outputs, "goldenrod2").highlight_nodes(
                unknown_sized_tensor_ops, "cyan2"
            )
            if len(highlight_debug_nodes) > 0:
                vis.highlight_nodes(highlight_debug_nodes, "green")
            if name_and_op_style:
                vis.labeller(lambda n: n.name + " (" + n.op + ")")

            res = vis.visit_all(v.graph, nodename_prefix=str(ctr)).get_result(
                "subgraph", "cluster_" + k.replace("/", "_")
            )
            dotstring += "\n".join("\t" + r for r in res.split("\n")) + "\n"
            ctr += 1
        dotstring += "}"
        return dotstring

def unpack_file(file: Path, unpack_to: Path, mode: Optional[str] = None, keep: bool = True):
    if mode == "zip" or (mode is None and str(file).endswith("zip")):
        from zipfile import ZipFile

        with ZipFile(file, "r") as zipObj:
            # Extract all the contents of zip file in current directory
            zipObj.extractall(unpack_to)

    elif mode == "targz" or ((mode is None and str(file).endswith("tar.gz")) or str(file).endswith("tgz")):
        import tarfile

        with tarfile.open(file, "r:gz") as tarObj:
            tarObj.extractall(unpack_to)

    elif mode == "tar" or (mode is None and str(file).endswith("tar")):
        import tarfile

        with tarfile.open(file, "r") as tarObj:
            tarObj.extractall(unpack_to)

    elif mode == "gz" or (mode is None and str(file).endswith("gz")):
        import gzip

        with gzip.open(str(file), "rb") as f_in, open(str(unpack_to), "wb") as f_out:
            shutil.copyfileobj(f_in, f_out)

    elif mode == "rar" or (mode is None and str(file).endswith("rar")):
        import patoolib

        patoolib.extract_archive(str(file), outdir=unpack_to, interactive=False)

    else:
        if mode is None:
            raise AssertionError(f"Can't infer archive type from {file}")
        else:
            raise AssertionError(f"Unsupported mode {mode}")

    if not keep:
        os.remove(str(file))

async def instantiate(self, request: CreateNotebookCommand) -> None:
        if self._lifespan is not None:
            await self._lifespan.__aenter__()

        self.load_dotenv()

        if self.graph.cells:
            del request
            LOGGER.info("App is already instantiated, skipping instantiation.")
            return

        broadcast_notification(
            NotebookDocumentTransactionNotification(
                transaction=Transaction(
                    changes=(ReorderCells(cell_ids=tuple(request.cell_ids)),),
                    source="kernel",
                )
            )
        )

        # Handle markdown cells specially during kernel-ready initialization
        execution_requests = {
            er.cell_id: er for er in request.execution_requests
        }
        self._handle_markdown_cells_on_instantiate(execution_requests)

        if request.auto_run:
            self.reset_ui_initializers()
            for (
                object_id,
                initial_value,
            ) in request.set_ui_element_value_request.ids_and_values:
                self.ui_initializers[object_id] = initial_value

            await self.run(list(execution_requests.values()))
            self.reset_ui_initializers()
        else:
            self._uninstantiated_execution_requests = execution_requests
            for (
                cell_id,
                cell_request,
            ) in self._uninstantiated_execution_requests.items():
                # Only mark non-empty cells as stale
                if cell_request.code.strip():
                    CellNotificationUtils.broadcast_stale(
                        cell_id=cell_id, stale=True
                    )

def score(
        self, examples: Iterable[Example], *, per_component: bool = False
    ) -> Dict[str, Any]:
        scores = {}
        if hasattr(self.nlp.tokenizer, "score"):
            if per_component:
                scores["tokenizer"] = self.nlp.tokenizer.score(examples, **self.cfg)
            else:
                scores.update(self.nlp.tokenizer.score(examples, **self.cfg))  # type: ignore
        for name, component in self.nlp.pipeline:
            if hasattr(component, "score"):
                if per_component:
                    scores[name] = component.score(examples, **self.cfg)
                else:
                    scores.update(component.score(examples, **self.cfg))
        return scores

def annotations(self, luNamePattern=None, exemplars=True, full_text=True):
        if exemplars:
            epart = PrettyLazyIteratorList(
                sent.frameAnnotation for sent in self.exemplars(luNamePattern)
            )
        else:
            epart = []

        if full_text:
            if luNamePattern is not None:
                matchedLUIDs = set(self.lu_ids_and_names(luNamePattern).keys())
            ftpart = PrettyLazyIteratorList(
                aset
                for sent in self.ft_sents()
                for aset in sent.annotationSet[1:]
                if luNamePattern is None or aset.get("luID", "CXN_ASET") in matchedLUIDs
            )
        else:
            ftpart = []

        if exemplars:
            if full_text:
                return epart + ftpart
            else:
                return epart
        elif full_text:
            return ftpart

def try_push_cleanup_commit(
    *, pr: PRInfo, images_to_delete: list[str], papers_yml_new: str | None
) -> str | None:

    if pr.is_fork:
        return None

    # Fetch and checkout the PR branch.
    subprocess.check_call(["git", "config", "user.name", "PySR Paper Bot"])
    subprocess.check_call(["git", "config", "user.email", "actions@github.com"])

    subprocess.check_call(["git", "fetch", "origin", f"{pr.head_ref}:{pr.head_ref}"])
    subprocess.check_call(["git", "checkout", pr.head_ref])

    changed = False

    for p in images_to_delete:
        if os.path.exists(p):
            os.remove(p)
            changed = True

    if papers_yml_new is not None:
        with open("docs/papers.yml", "w", encoding="utf-8") as f:
            f.write(papers_yml_new)
        changed = True

    if not changed:
        return None

    subprocess.check_call(["git", "add", "docs/papers.yml"], stdout=subprocess.DEVNULL)
    for p in images_to_delete:
        if os.path.exists(p):
            subprocess.check_call(["git", "add", "-u", p], stdout=subprocess.DEVNULL)
        else:
            # add -u will record deletion if it existed.
            subprocess.check_call(["git", "add", "-u"], stdout=subprocess.DEVNULL)

    subprocess.check_call(
        [
            "git",
            "commit",
            "-m",
            "chore(papers): move PR images to docs repo and remove from PySR",
        ]
    )
    subprocess.check_call(["git", "push", "origin", f"HEAD:{pr.head_ref}"])

    sha = subprocess.check_output(["git", "rev-parse", "HEAD"]).decode().strip()
    return sha

def convert(file_name, physics, timestep):
  frame_values = parse(file_name)
  joint2index = {}
  for name in physics.named.data.qpos.axes.row.names:
    joint2index[name] = physics.named.data.qpos.axes.row.convert_key_item(name)
  index2joint = {}
  for joint, index in joint2index.items():
    if isinstance(index, slice):
      indices = range(index.start, index.stop)
    else:
      indices = [index]
    for ii in indices:
      index2joint[ii] = joint

  # Convert frame_values to qpos
  amcvals2qpos_transformer = Amcvals2qpos(index2joint, _CMU_MOCAP_JOINT_ORDER)
  qpos_values = []
  for frame_value in frame_values:
    qpos_values.append(amcvals2qpos_transformer(frame_value))
  qpos_values = np.stack(qpos_values)  # Time by nq

  # Interpolate/resample.
  # Note: interpolate quaternions rather than euler angles (slerp).
  # see https://en.wikipedia.org/wiki/Slerp
  qpos_values_resampled = []
  time_vals = np.arange(0, len(frame_values)*MOCAP_DT - 1e-8, MOCAP_DT)
  time_vals_new = np.arange(0, len(frame_values)*MOCAP_DT, timestep)
  while time_vals_new[-1] > time_vals[-1]:
    time_vals_new = time_vals_new[:-1]

  for i in range(qpos_values.shape[1]):
    f = interpolate.splrep(time_vals, qpos_values[:, i])
    qpos_values_resampled.append(interpolate.splev(time_vals_new, f))

  qpos_values_resampled = np.stack(qpos_values_resampled)  # nq by ntime

  qvel_list = []
  for t in range(qpos_values_resampled.shape[1]-1):
    p_tp1 = qpos_values_resampled[:, t + 1]
    p_t = qpos_values_resampled[:, t]
    qvel = [(p_tp1[:3]-p_t[:3])/ timestep,
            mjmath.mj_quat2vel(
                mjmath.mj_quatdiff(p_t[3:7], p_tp1[3:7]), timestep),
            (p_tp1[7:]-p_t[7:])/ timestep]
    qvel_list.append(np.concatenate(qvel))

  qvel_values_resampled = np.vstack(qvel_list).T

  return Converted(qpos_values_resampled, qvel_values_resampled, time_vals_new)

def cast(self, col_name, dtype, optional=False):
        assert col_name in self.columns

        wbtype = _dtypes.TypeRegistry.type_from_dtype(dtype)

        if optional:
            wbtype = _dtypes.OptionalType(wbtype)

        # Cast each value in the row, raising an error if there are invalid entries.
        col_ndx = self.columns.index(col_name)
        for row in self.data:
            result_type = wbtype.assign(row[col_ndx])
            if isinstance(result_type, _dtypes.InvalidType):
                raise TypeError(
                    f"Existing data {row[col_ndx]}, of type {_dtypes.TypeRegistry.type_of(row[col_ndx])} cannot be cast to {wbtype}"
                )
            wbtype = result_type

        # Assert valid options
        is_pk = isinstance(wbtype, _PrimaryKeyType)
        is_fk = isinstance(wbtype, _ForeignKeyType)
        is_fi = isinstance(wbtype, _ForeignIndexType)
        if is_pk or is_fk or is_fi:
            assert not optional, (
                "Primary keys, foreign keys, and foreign indexes cannot be optional."
            )

        if (is_fk or is_fk) and id(wbtype.params["table"]) == id(self):
            raise AssertionError("Cannot set a foreign table reference to same table.")

        if is_pk:
            assert self._pk_col is None, (
                f"Cannot have multiple primary keys - {self._pk_col} is already set as the primary key."
            )

        # Update the column type
        self._column_types.params["type_map"][col_name] = wbtype

        # Wrap the data if needed
        self._update_keys()
        return wbtype

def create_api_token(
    name: str,
    description: str | None,
    scope: tuple[str, ...],
    expires: str | None,
    output: str,
) -> None:
    import json as json_mod

    import yaml
    from rich.panel import Panel
    from rich.syntax import Syntax

    expired_at = _parse_expiration(expires)
    scopes = list(scope) if scope else None

    try:
        token = bentoml.api_token.create(
            name=name,
            description=description,
            scopes=scopes,
            expired_at=expired_at,
        )
    except BentoMLException as e:
        _raise_api_token_error(e, "create")

    # Display the token value prominently since it's only shown once
    if token.token:
        rich.print(
            Panel(
                f"[bold green]{token.token}[/bold green]",
                title="[bold yellow]API Token (save this - it won't be shown again!)[/bold yellow]",
                border_style="yellow",
            )
        )

    if output == "table":
        rich.print(f"\nToken [green]{token.name}[/] created successfully")
        rich.print(f"  UID: {token.uid}")
        if token.description:
            rich.print(f"  Description: {token.description}")
        if token.expired_at:
            rich.print(f"  Expires: {token.expired_at.strftime('%Y-%m-%d %H:%M:%S')}")
        else:
            rich.print("  Expires: Never")
    elif output == "json":
        info = json_mod.dumps(token.to_dict(), indent=2, default=str)
        rich.print(info)
    elif output == "yaml":
        info = yaml.dump(token.to_dict(), indent=2, sort_keys=False)
        rich.print(Syntax(info, "yaml", background_color="default"))

def build_reference_docs(update_nav: bool = False) -> list[str]:
    _missing_type_warnings.clear()
    nav_items: list[str] = []
    created = 0

    desc = f"Docstrings {GITHUB_REPO or PACKAGE_DIR.name}"
    for py_filepath in TQDM(list(PACKAGE_DIR.rglob("*.py")), desc=desc, unit="file"):
        md_target = REFERENCE_DIR / py_filepath.relative_to(PACKAGE_DIR).with_suffix(".md")
        exists_before = md_target.exists()
        module = parse_module(py_filepath)
        if not module or (not module.classes and not module.functions):
            continue
        md_rel_filepath = create_markdown(module)
        if not exists_before:
            created += 1
        nav_items.append(str(md_rel_filepath))

    if update_nav:
        update_mkdocs_file(create_nav_menu_yaml(nav_items))
    if created:
        LOGGER.info(f"Created {created} new reference files")
    if _missing_type_warnings:
        LOGGER.warning(f"{len(_missing_type_warnings)} functions/methods have parameters missing type annotations:")
        for warning in _missing_type_warnings:
            LOGGER.warning(f"  - {warning}")
        raise ValueError(
            f"{len(_missing_type_warnings)} parameters missing types in both signature and docstring. "
            f"Add type annotations to the function signature or (type) in the docstring Args section."
        )
    return nav_items

def no_leading_block_quotes(cells):
    errors = []
    for cell in cells:
        if not isinstance(cell, MarkdownCell):
            continue

        # unfortunately, the cloud runner cells break this rule (and there doesn't seem to be a good
        # way to avoid it), so skip them, and we just have to be careful that they get formatted
        # correctly.
        if "CloudRunner" in cell.metadata.get("tags", []):
            continue

        first = cell.ast.first_child

        if is_block_quote(first):
            errors.append(
                message_with_line(
                    cell,
                    f"Found a block quote (like `> ...`) as the first element of a cell; this must be avoided because it may cause problems during the reStructuredText conversion (https://github.com/spatialaudio/nbsphinx/issues/450). Consider: moving the block quote",
                    sourcepos=first.sourcepos,
                )
            )

    if errors:
        raise FormattingError(errors)

def unique(
    x: Expr,
    sorted: bool | Expr = True,
    return_index: bool | Expr = False,
    return_inverse: bool | Expr = False,
    return_counts: bool | Expr = False,
    axis: int | Expr | None = None,
) -> Expr:

    if isinstance(sorted, bool):
        sorted = PrimValue(sorted)
    if isinstance(return_index, bool):
        return_index = PrimValue(return_index)
    if isinstance(return_inverse, bool):
        return_inverse = PrimValue(return_inverse)
    if isinstance(return_counts, bool):
        return_counts = PrimValue(return_counts)
    if axis is not None and isinstance(axis, int):
        axis = PrimValue(axis)
    return _ffi_api.unique(  # type: ignore
        x, sorted, return_index, return_inverse, return_counts, axis
    )

def load_full_skill(self, skill_name: str) -> Optional[str]:
        for skill in self.skills_metadata:
            if skill["name"] == skill_name:
                try:
                    with open(
                        skill["path"], "r", encoding="utf-8"
                    ) as f:
                        content = f.read()
                    # Return everything after frontmatter
                    if content.startswith("---"):
                        parts = content.split("---", 2)
                        if len(parts) >= 3:
                            return parts[2].strip()
                except Exception as e:
                    logger.error(
                        f"Failed to load full skill {skill_name}: {e}"
                    )
        return None

def set_optional_input(self, input_idx, value=None, format="float"):
        if input_idx >= len(self.spec.description.input):
            msg = (
                str(input_idx)
                + " out of "
                + str(len(self.spec.description.input))
                + " inputs!"
            )
            raise ValueError("Setting invalid input as optional! {}".format(msg))
        self.spec.description.input[input_idx].type.isOptional = True
        if value is None:
            return
        # Default value is supported from CoreML 4 onwards.
        self.spec.specificationVersion = max(
            self.spec.specificationVersion, _SPECIFICATION_VERSION_IOS_14
        )
        format = format.lower()
        if format == "float":
            self.spec.description.input[
                input_idx
            ].type.multiArrayType.floatDefaultValue = value
        elif format == "double":
            self.spec.description.input[
                input_idx
            ].type.multiArrayType.doubleDefaultValue = value
        elif format == "int":
            self.spec.description.input[
                input_idx
            ].type.multiArrayType.intDefaultValue = value
        else:
            raise ValueError(
                "Incorrect format for optional inputs! Expecting int/float/double, got {}!".format(
                    format
                )
            )

def is_tomek(y, nn_index, class_type):
        links = np.zeros(len(y), dtype=bool)

        # find which class to not consider
        class_excluded = [c for c in np.unique(y) if c not in class_type]

        # there is a Tomek link between two samples if they are both nearest
        # neighbors of each others.
        for index_sample, target_sample in enumerate(y):
            if target_sample in class_excluded:
                continue

            if y[nn_index[index_sample]] != target_sample:
                if nn_index[nn_index[index_sample]] == index_sample:
                    links[index_sample] = True

        return links

def normalize_result(result: Any) -> Any:
        # Strategy 1: Already a string - use directly
        if isinstance(result, str):
            return result

        # Strategy 2: Dict with "state" key - structured response (pass through)
        if isinstance(result, dict):
            if "state" in result:
                return result  # Structured state transition
            elif "content" in result:
                return result["content"]  # Extract content from dict
            else:
                return result  # Unknown dict format, pass through

        # Strategy 3: List (e.g., list of Message objects from Agno)
        if isinstance(result, list) and result:
            last_item = result[-1]

            # Try to extract content from last item
            if hasattr(last_item, "content"):
                return last_item.content
            elif hasattr(last_item, "to_dict"):
                item_dict = last_item.to_dict()
                if "content" in item_dict:
                    return item_dict["content"]
            elif isinstance(last_item, dict) and "content" in last_item:
                return last_item["content"]
            elif isinstance(last_item, str):
                return last_item

            # Can't extract, return last item as-is
            return last_item

        # Strategy 4: Object with .content attribute (e.g., Message object)
        if hasattr(result, "content"):
            return result.content

        # Strategy 5: Object with .to_dict() method
        if hasattr(result, "to_dict"):
            try:
                result_dict = result.to_dict()
                if "content" in result_dict:
                    return result_dict["content"]
                return result_dict
            except Exception as e:
                logger.debug(
                    "Failed to extract content from .to_dict() method", error=str(e)
                )

        # Strategy 6: Fallback to string conversion
        return str(result) if result is not None else ""

def step_fn(step):
        ret = 1.0
        for name in factors:
            if name == "constant":
                ret *= base_learning_rate
            elif name == "linear_warmup":
                ret *= jnp.minimum(1.0, step / warmup_steps)
            elif name == "rsqrt_decay":
                ret /= jnp.sqrt(jnp.maximum(step, warmup_steps))
            elif name == "rsqrt_normalized_decay":
                ret *= jnp.sqrt(warmup_steps)
                ret /= jnp.sqrt(jnp.maximum(step, warmup_steps))
            elif name == "decay_every":
                ret *= decay_factor ** (step // steps_per_decay)
            elif name == "cosine_decay":
                progress = jnp.maximum(0.0, (step - warmup_steps) / float(steps_per_cycle))
                ret *= jnp.maximum(0.0, 0.5 * (1.0 + jnp.cos(jnp.pi * (progress % 1.0))))
            else:
                raise ValueError("Unknown factor %s." % name)
        return jnp.asarray(ret, dtype=jnp.float32)

def delete_constant_placeholder(exp_program: ExportedProgram, node: torch.fx.Node):
    if not len(node.users) == 0:
        raise RuntimeError(
            f"Cannot delete input node {node.name} since it has users in the graph."
        )

    # Remove tensor from state_dict/ constants
    if node.name in exp_program.graph_signature.inputs_to_parameters:
        target = exp_program.graph_signature.inputs_to_parameters[node.name]
        del exp_program.state_dict[target]

    elif node.name in exp_program.graph_signature.inputs_to_buffers:
        target = exp_program.graph_signature.inputs_to_buffers[node.name]

        if target in exp_program.graph_signature.non_persistent_buffers:
            del exp_program.constants[target]
        else:
            del exp_program.state_dict[target]

    elif node.name in exp_program.graph_signature.inputs_to_lifted_tensor_constants:
        target = exp_program.graph_signature.inputs_to_lifted_tensor_constants[
            node.name
        ]
        del exp_program.constants[target]
    else:
        raise RuntimeError(
            f"Cannot delete input node {node.name} since it is not a parameter, a buffer, nor a lifted tensor constant."
        )

    # Remove input from graph signature
    input_specs = [
        spec
        for spec in exp_program.graph_signature.input_specs
        if spec.arg.name != node.name
    ]
    new_graph_signature = ExportGraphSignature(
        input_specs, exp_program.graph_signature.output_specs
    )
    exp_program._graph_signature = new_graph_signature

    # Remove node from graph
    node.graph.erase_node(node)

def recursive_print(name, val, spaces=0):
    # Format the message.
    if name is None:
        msg = None
    else:
        fmt = "." * max(0, spaces - 2) + "# {:" + str(50 - spaces) + "s}"
        msg = fmt.format(name)

    # Print and recurse (if needed).
    if isinstance(val, dict):
        if msg is not None:
            print(msg)
        for k in val:
            recursive_print(k, val[k], spaces + 2)
    elif isinstance(val, torch.Tensor):
        print(msg, ":", val.size())
    else:
        print(msg, ":", val)

def transform(self, inst):
        if isinstance(inst, BaseEpochs):
            X = inst.get_data(copy=False)
        elif isinstance(inst, Evoked):
            X = inst.data
        elif isinstance(inst, np.ndarray):
            X = inst
            if X.ndim not in (2, 3):
                raise ValueError(f"X must be 2D or 3D, got {X.ndim}")
        else:
            raise ValueError("Data input must be of Epoch type or numpy array")

        filters = [filt[: self.n_components] for filt in self.filters_.values()]
        filters = np.concatenate(filters, axis=0)
        X = np.dot(filters, X)
        if X.ndim == 3:
            X = X.transpose((1, 0, 2))
        return X

def add_arg(self, x_idx: int, x):
        arg_abstracted_axes = {}

        for shape_idx, s in enumerate(getattr(x, "shape", ())):
            if not isinstance(s, int):  #  pragma: no cover
                found = False
                if not self.allow_array_resizing:
                    for previous_idx, previous_shape in enumerate(self.abstract_shapes):
                        if s is previous_shape:
                            arg_abstracted_axes[shape_idx] = previous_idx
                            self.shape_locations[previous_idx].append(
                                AbstractShapeLocation(x_idx, shape_idx)
                            )
                            found = True
                            break
                # haven't encountered it, so add it to abstract_axes
                # and use new number designation
                if not found:  # pragma: no cover
                    arg_abstracted_axes[shape_idx] = len(self.abstract_shapes)
                    self.shape_locations.append([AbstractShapeLocation(x_idx, shape_idx)])
                    self.abstract_shapes.append(s)
        self.abstracted_axes.append(arg_abstracted_axes)

def transform_add_marimo_import(sources: list[CodeCell]) -> list[CodeCell]:
    def contains_mo(cell: str) -> bool:
        return cell.startswith("mo.md(") or "mo.sql(" in cell

    def has_marimo_import(cell: str) -> bool:
        # Quick check
        if "import marimo as mo" not in cell:
            return False

        def is_in_import_line(line: str) -> bool:
            if line.startswith("import marimo as mo"):
                return True
            if line.startswith(("import ", "from ")):
                return "import marimo as mo" in line
            return False

        # Slow check
        lines = cell.strip().split("\n")
        return any(is_in_import_line(line) for line in lines)

    already_has_marimo_import = any(
        has_marimo_import(cell.source) for cell in sources
    )
    if already_has_marimo_import:
        return sources

    if any(contains_mo(cell.source) for cell in sources):
        return [CodeCell("import marimo as mo")] + sources

    return sources

def history_output_formatter(
    conversation: callable, type: HistoryOutputType = "list"
) -> Any:
    if type == "list":
        return conversation.return_messages_as_list()
    elif type in ["dict", "dictionary"]:
        return conversation.to_dict()
    elif type in ["string", "str"]:
        return conversation.get_str()
    elif type in ["final", "last"]:
        return conversation.get_final_message_content()
    elif type == "json":
        return conversation.to_json()
    elif type == "all":
        return conversation.get_str()
    elif type == "yaml":
        return yaml.safe_dump(conversation.to_dict(), sort_keys=False)
    elif type == "dict-all-except-first":
        return conversation.return_all_except_first()
    elif type == "list-final":
        return conversation.return_list_final()
    elif type == "str-all-except-first":
        return conversation.return_all_except_first_string()
    elif type == "dict-final":
        return conversation.return_dict_final()
    elif type == "xml":
        data = conversation.to_dict()
        return to_xml_string(data, root_tag="conversation")
    else:
        raise ValueError(f"Invalid type: {type}")

async def invoke_returning_run_output(
        self,
        input: InputType,
        input_source: DataSource | None = None,
        prior_trace: list[ChatCompletionMessageParam] | None = None,
        parent_task_run: TaskRun | None = None,
    ) -> Tuple[TaskRun, RunOutput]:
        if prior_trace or parent_task_run is not None:
            raise NotImplementedError(
                "Session continuation is not supported for MCP adapter. "
                "MCP tools are single-turn and do not maintain conversation state."
            )

        is_root_agent = get_agent_run_id() is None

        if is_root_agent:
            run_id = generate_agent_run_id()
            set_agent_run_id(run_id)

        try:
            return await self._run_and_validate_output(
                input, input_source, parent_task_run
            )
        finally:
            if is_root_agent:
                try:
                    run_id = get_agent_run_id()
                    if run_id:
                        await MCPSessionManager.shared().cleanup_session(run_id)
                finally:
                    clear_agent_run_id()

def load_state(obj: Any, file_path: str) -> None:
        try:
            # Verify file exists
            if not os.path.exists(file_path):
                raise FileNotFoundError(
                    f"State file not found: {file_path}"
                )

            # Preserve existing instances
            preserved = SafeLoaderUtils.preserve_instances(obj)

            # Load state
            with open(file_path, "r") as f:
                state_dict = json.load(f)

            # Set safe values
            for key, value in state_dict.items():
                if (
                    not key.startswith("_")
                    and key not in preserved
                    and SafeLoaderUtils.is_safe_type(value)
                ):
                    setattr(obj, key, value)

            # Restore preserved instances
            for key, value in preserved.items():
                setattr(obj, key, value)

            logger.info(
                f"Successfully loaded state from: {file_path}"
            )

        except Exception as e:
            logger.error(f"Error loading state: {e}")
            raise

def detect_platform():
    # Check for Darwin (macOS)
    if platform.system() == "Darwin":
        return "apple"

    # Check for NVIDIA GPU
    if run_command("nvidia-smi > /dev/null 2>&1"):
        return "cuda"

    # Check for ROCm
    if run_command("rocm-smi > /dev/null 2>&1"):
        return "rocm"

    # Check for ROCm environment variables (additional detection)
    if any(env in os.environ for env in ["ROCM_PATH", "HIP_PATH", "ROCM_HOME"]):
        return "rocm"

    # Check if ROCm tools exist
    if shutil.which("rocminfo") or shutil.which("rocm-smi"):
        return "rocm"

    # Default to CPU to avoid pulling incorrect GPU packages
    return "cpu"

def to_tensor(
        self, mode: Optional[str] = None, as_padded_sequence: bool = False
    ) -> torch.Tensor | list[torch.Tensor]:
        batched_boxes = self._data if self._is_batched else self._data.unsqueeze(0)

        boxes: torch.Tensor | list[torch.Tensor]

        # Create boxes in xyxy_plus format.
        boxes = torch.stack([batched_boxes.amin(dim=-2), batched_boxes.amax(dim=-2)], dim=-2).view(
            batched_boxes.shape[0], batched_boxes.shape[1], 4
        )

        if mode is None:
            mode = self.mode

        mode = mode.lower()

        if mode in ("xyxy", "xyxy_plus"):
            pass
        elif mode in ("xywh", "vertices", "vertices_plus"):
            height, width = boxes[..., 3] - boxes[..., 1] + 1, boxes[..., 2] - boxes[..., 0] + 1
            boxes[..., 2] = width
            boxes[..., 3] = height
        else:
            raise ValueError(f"Unknown mode {mode}")

        if mode in ("xyxy", "vertices"):
            offset = torch.as_tensor([0, 0, 1, 1], device=boxes.device, dtype=boxes.dtype)
            boxes = boxes + offset

        if mode.startswith("vertices"):
            boxes = _boxes_to_polygons(boxes[..., 0], boxes[..., 1], boxes[..., 2], boxes[..., 3])

        if self._N is not None and not as_padded_sequence:
            boxes = [torch.nn.functional.pad(o, (len(o.shape) - 1) * [0, 0] + [0, -n]) for o, n in zip(boxes, self._N)]
        else:
            boxes = boxes if self._is_batched else boxes.squeeze(0)
        return boxes

def get_local_heads(shard_rank: int,
                    num_shards: int,
                    n_heads_q: int,
                    n_heads_kv: Optional[int] = None) -> Tuple[int, int]:
    if n_heads_q < num_shards:
        raise ValueError("There must be at least as many attention heads as there are shards.")

    if n_heads_kv is None or n_heads_kv == n_heads_q:
        # MHA attention
        base_heads = n_heads_q // num_shards
        extra_heads = n_heads_q % num_shards

        if shard_rank < extra_heads:
            return (base_heads + 1), (base_heads + 1)
        else:
            return base_heads, base_heads
    else:
        # GQA attention
        if n_heads_q % n_heads_kv != 0:
            raise ValueError("Must be an even ratio between query and key/value heads.")

        if n_heads_kv < num_shards and num_shards % n_heads_kv != 0:
            raise ValueError(
                "If splitting a group across multiple shards, we must be able to distribute the groups evenly.")

        if n_heads_kv >= num_shards and n_heads_kv % num_shards != 0:
            raise ValueError("If parallelizing groups, must be able to evenly distribute them.")

        q_ratio = n_heads_q // n_heads_kv

        if n_heads_kv >= num_shards:
            local_kv_heads = n_heads_kv // num_shards
            local_q_heads = local_kv_heads * q_ratio
            return local_q_heads, local_kv_heads
        else:
            group_sharding_size = num_shards // n_heads_kv
            group_rank_idx = shard_rank % group_sharding_size

            base_heads = q_ratio // group_sharding_size
            extra_heads = q_ratio % group_sharding_size

            if group_rank_idx < extra_heads:
                return (base_heads + 1), 1
            else:
                return base_heads, 1

def update_batch_progress(self):
        if self.cancel_processing:
            if hasattr(self, "progress_timer"):
                self.progress_timer.stop()
            self.finish_batch_processing()
            return

        if hasattr(self, "batch_lock"):
            with self.batch_lock:
                current_count = self.processed_count
                total = self.total_images
        else:
            current_count = 0
            total = self.total_images if hasattr(self, "total_images") else 0

        template = self.tr("Processing image %d/%d...")
        display_text = template % (current_count, total)
        self.progress_dialog.setLabelText(display_text)
        self.progress_dialog.setValue(current_count)

        if hasattr(self, "batch_complete") and self.batch_complete:
            if hasattr(self, "progress_timer"):
                self.progress_timer.stop()
            self.finish_batch_processing()

def add_elementwise(self, name, input_names, output_name, mode, alpha=None):
        input_names = input_names if isinstance(input_names, list) else [input_names]
        spec_layer = self._add_generic_layer(name, input_names, [output_name])

        # add one of the following layers
        mode = mode.upper() if isinstance(mode, str) else mode
        if mode == "CONCAT":
            spec_layer.concat.sequenceConcat = False
        elif mode == "SEQUENCE_CONCAT":
            spec_layer.concat.sequenceConcat = True
        elif mode == "ADD":
            spec_layer.add.MergeFromString(b"")
            if alpha:
                spec_layer.add.alpha = alpha
        elif mode == "MULTIPLY":
            spec_layer.multiply.MergeFromString(b"")
            if alpha:
                spec_layer.multiply.alpha = alpha
        elif mode == "COS":
            spec_layer.dot.cosineSimilarity = True
        elif mode == "DOT":
            spec_layer.dot.cosineSimilarity = False
        elif mode == "MAX":
            spec_layer.max.MergeFromString(b"")
        elif mode == "MIN":
            spec_layer.min.MergeFromString(b"")
        elif mode == "AVE":
            spec_layer.average.MergeFromString(b"")
        else:
            raise ValueError("Unsupported elementwise mode %s" % mode)
        return spec_layer

def move_models(self, target_device):
        target_device_obj = torch.device(target_device) if isinstance(target_device, str) else target_device
        accelerator_device = torch.device(self.accelerator.device) if hasattr(self.accelerator, "device") else None
        base_precision = str(getattr(self.config, "base_model_precision", "") or "").lower()
        torchao_quantized = "torchao" in base_precision
        should_configure_offload = (
            self.group_offload_requested()
            and accelerator_device is not None
            and isinstance(target_device_obj, torch.device)
            and target_device_obj == accelerator_device
        )
        skip_moving_trained_component = any(
            [
                (should_configure_offload and self.group_offload_configured),
                self.config.musubi_blocks_to_swap or 0 > 0,
                self.config.quantize_via == "pipeline",
                self.config.ramtorch,
                torchao_quantized,
            ]
        )

        if self.model is not None and not skip_moving_trained_component:
            model_ref = self.unwrap_model(model=self.model)
            if getattr(model_ref, "device", None) != "meta":
                model_ref.to(target_device)
        elif self.model is not None and torchao_quantized:
            logger.info(
                "Skipping model.to(%s) for TorchAO-quantized base model to avoid weight swap errors.",
                target_device,
            )
        if self.controlnet is not None and not skip_moving_trained_component:
            self.unwrap_model(model=self.controlnet).to(target_device)
        if self.vae is not None and self.vae.device != "meta":
            self.vae.to(target_device)
        if self.text_encoders is not None and not self._ramtorch_text_encoders_requested():
            for text_encoder in self.text_encoders:
                if text_encoder is None or getattr(text_encoder, "device", None) == "meta":
                    continue
                text_encoder.to(target_device)
        self.move_extra_models(target_device)

        if should_configure_offload:
            self.configure_group_offload()

def update_episode_metrics(
    episodes: list[Episode],
    metrics: RejectionSamplingMetrics,
) -> None:
    # Group episodes by task_id
    episodes_by_task: dict[str, list[Episode]] = {}
    for episode in episodes:
        if len(episode.trajectories) == 0:
            continue
        # Extract task_id from episode.id format "task_id:rollout_idx"
        task_id = episode.task_id
        if task_id not in episodes_by_task:
            episodes_by_task[task_id] = []
        episodes_by_task[task_id].append(episode)

    # Check correctness for each task
    for task_id, task_episodes in episodes_by_task.items():
        correct_mask = [ep.is_correct for ep in task_episodes]
        if all(correct_mask):
            metrics.solve_all += 1
        elif any(correct_mask):
            metrics.solve_partial += 1
        else:
            metrics.solve_none += 1

def set_edges(nodes: Dict[str, NodeRepr], top_sort: list):
        out_id = 0
        edges = {out_id: DAGRepr.get_edge_from_schema(nodes[InputConst.name].outputs, nodes[InputConst.name].inputs, nodes[InputConst.name].outputs,
                                                      nodes[InputConst.name].iter_info.type, None)}
        nodes[InputConst.name].in_edges = [out_id]

        for name in top_sort[:-1]:
            ahead_schema = set(nodes[name].outputs)
            for i in nodes[name].in_edges:
                ahead_schema = ahead_schema | edges[i]['schema'].keys()
            for next_name in nodes[name].next_nodes:
                out_id += 1
                out_schema = DAGRepr.dfs_used_schema(nodes, next_name, ahead_schema)
                edges[out_id] = DAGRepr.get_edge_from_schema(tuple(out_schema), nodes[name].inputs, nodes[name].outputs,
                                                             nodes[name].iter_info.type, [edges[e]['schema'] for e in nodes[name].in_edges])

                if nodes[next_name].in_edges is None:
                    nodes[next_name].in_edges = [out_id]
                else:
                    nodes[next_name].in_edges.append(out_id)

                if nodes[name].out_edges is None:
                    nodes[name].out_edges = [out_id]
                else:
                    nodes[name].out_edges.append(out_id)

        out_id += 1
        final_edge = nodes[OutputConst.name].in_edges[0]
        final_schema = edges[final_edge]['schema']
        edges[out_id] = {'schema': final_schema, 'data': [(s, final_schema[s].type) for s in nodes[OutputConst.name].inputs]}

        nodes[OutputConst.name].out_edges = [out_id]
        return nodes, edges

def validate_schema(assert_, data, schema, optional=None, on_unexpected_cols="raise"):
    if on_unexpected_cols not in {"warn", "raise", None}:
        raise ValueError(
            "'on_unexpected_cols' must be one of 'warn', 'raise' " "or None"
        )

    optional = optional or {}
    cols = set(data.columns)
    expected = set(schema)

    missing = expected - cols
    unexpected = cols - expected - set(optional)

    msg = "(validate_schema) Missing columns {missing}.".format(missing=missing)
    assert_(not missing, msg)

    if on_unexpected_cols is not None:
        msg = "(validate_schema) Unexpected columns {unexpected}".format(
            unexpected=unexpected
        )
        caller = assert_ if on_unexpected_cols == "raise" else assert_.warn
        caller(not unexpected, msg)

    # if passing a mapping, schema is validated (even for optional columns)
    for schema_to_validate in [schema, optional]:
        if isinstance(schema_to_validate, Mapping):
            # validate column types (as many as you can)
            dtypes = data.dtypes.astype(str).to_dict()

            for name, dtype in dtypes.items():
                expected = schema_to_validate.get(name)

                if expected is not None:
                    msg = (
                        '(validate_schema) Wrong dtype for column "{name}". '
                        'Expected: "{expected}". Got: "{dtype}"'.format(
                            name=name, expected=expected, dtype=dtype
                        )
                    )
                    assert_(dtype == expected, msg)

    return assert_

def from_dict(cls, obj: dict) -> SelectionConfigV3AllOf:
        if obj is None:
            return None

        if not isinstance(obj, dict):
            return SelectionConfigV3AllOf.parse_obj(obj)

        # raise errors for additional fields in the input
        for _key in obj.keys():
            if _key not in cls.__properties:
                raise ValueError("Error due to additional fields (not defined in SelectionConfigV3AllOf) in the input: " + str(obj))

        _obj = SelectionConfigV3AllOf.parse_obj({
            "strategies": [SelectionConfigV3Entry.from_dict(_item) for _item in obj.get("strategies")] if obj.get("strategies") is not None else None
        })
        return _obj

def unpack_text_embeddings_from_cache(self, embeddings):
        if not isinstance(embeddings, dict):
            return embeddings
        pad_to = getattr(self.config, "tokenizer_max_length", None)
        if not pad_to:
            return embeddings

        pad_slices = embeddings.get("_pad_slices", {})
        unpacked = {k: v for k, v in embeddings.items() if k != "_pad_slices"}
        for key, val in list(unpacked.items()):
            if not torch.is_tensor(val):
                continue

            if key in ("attention_masks", "attention_mask", "prompt_attention_mask"):
                if val.dim() >= 1 and val.shape[-1] < pad_to:
                    pad_len = pad_to - val.shape[-1]
                    pad_shape = val.shape[:-1] + (pad_len,)
                    unpacked[key] = torch.cat([val, val.new_zeros(pad_shape)], dim=-1)
                continue

            if key == "pooled_prompt_embeds":
                if val.dim() == 3:
                    logger.warning(
                        "Cached pooled_prompt_embeds has an unexpected sequence dimension; using first token. shape=%s",
                        val.shape,
                    )
                    unpacked[key] = val[:, 0, :]
                elif val.dim() != 2:
                    raise ValueError(f"Unexpected pooled_prompt_embeds shape {val.shape}")
                continue

            if val.dim() >= 2 and val.shape[-2] < pad_to:
                pad_len = pad_to - val.shape[-2]
                pad_token = pad_slices.get(key, val[..., -1:, :])
                pad_repeat = pad_token.expand(*pad_token.shape[:-2], pad_len, pad_token.shape[-1])
                unpacked[key] = torch.cat([val, pad_repeat], dim=-2)
            elif val.dim() >= 1 and val.shape[-1] < pad_to:
                pad_len = pad_to - val.shape[-1]
                pad_shape = val.shape[:-1] + (pad_len,)
                unpacked[key] = torch.cat([val, val.new_zeros(pad_shape)], dim=-1)
        return unpacked

def get_log_time_series(
        self,
        name_or_deployment: Union[str, LeptonDeployment] = None,
        name_or_job: Union[str, LeptonJob] = None,
        replica: Union[str, Replica] = None,
        start: int = None,
        end: int = None,
        interval_ms: int = None,
        limit: int = None,
        q: str = "",
        job_query_mode: str = LeptonJobQueryMode.AliveAndArchive.value,
        direction: str = "backward",
    ):

        query_kwargs = {}

        if start is not None:
            query_kwargs["start"] = start
        if end is not None:
            query_kwargs["end"] = end
        if interval_ms is not None:
            query_kwargs["interval_ms"] = interval_ms
        if limit is not None:
            query_kwargs["limit"] = limit
        if q is not None:
            query_kwargs["q"] = q
        if job_query_mode:
            query_kwargs["job_query_mode"] = job_query_mode
        if direction:
            query_kwargs["direction"] = direction

        if name_or_deployment:
            deployment_id = (
                name_or_deployment
                if isinstance(name_or_deployment, str)
                else name_or_deployment.metadata.id_
            )
            query_kwargs["deployment"] = deployment_id
        elif name_or_job:
            job_id = (
                name_or_job
                if isinstance(name_or_job, str)
                else name_or_job.metadata.id_
            )
            query_kwargs["job"] = job_id

        if replica:
            replica_id = replica if isinstance(replica, str) else replica.metadata.id_
            query_kwargs["replica"] = replica_id

        response = self._get(
            "/logs/timeseries",
            params=query_kwargs,
        )
        if not response.ok:
            raise RuntimeError(
                f"API call failed with status code {response.status_code}. Details:"
                f" {response.text}"
            )
        return response.json()

def visit_if(self: Parser, node: doc.If) -> None:
    with self.var_table.with_frame():
        predicate = self.eval_expr(node.test)
        if isinstance(predicate, PrimExpr | tvm.tirx.expr.ExprOp):
            with T.If(self.eval_expr(node.test)):
                with T.Then():
                    with self.var_table.with_frame():
                        self.visit_body(node.body)
                if node.orelse:
                    with T.Else():
                        with self.var_table.with_frame():
                            self.visit_body(node.orelse)
        elif isinstance(predicate, bool):
            if predicate:
                with self.var_table.with_frame():
                    self.visit_body(node.body)
            elif node.orelse:
                with self.var_table.with_frame():
                    self.visit_body(node.orelse)
        else:
            self.report_error(
                node.test,
                f"If condition must be a boolean expression, but got {predicate}",
            )

def get_unique_ssh_key_name(self, prefix: str,
                                pub_key: str) -> Tuple[str, bool]:
        candidate_keys = [
            k for k in self.list_ssh_keys()
            if k.get('name', '').startswith(prefix)
        ]

        # Prefix not found
        if not candidate_keys:
            return prefix, False

        suffix_digits = [0]
        for key_info in candidate_keys:
            name = key_info.get('name', '')
            if key_info.get('public_key', '').strip() == pub_key.strip():
                # Pub key already exists. Use strip to avoid whitespace diffs.
                return name, True
            if (len(name) > len(prefix) + 1 and name[len(prefix)] == '-' and
                    name[len(prefix) + 1:].isdigit()):
                suffix_digits.append(int(name[len(prefix) + 1:]))
        return f'{prefix}-{max(suffix_digits) + 1}', False

def iter_vaex(
    X: vaex.dataframe.DataFrame,
    y: str | vaex.expression.Expression | None = None,
    features: list[str] | vaex.expression.Expression | None = None,
) -> base.typing.Stream:

    features = _ensure_strings_from_expressions(features)
    feature_names = features or X.get_column_names()

    if y:
        y = _ensure_strings_from_expressions(y)
        y = _ensure_list(y)
        feature_names = [feat for feat in feature_names if feat not in y]

    multioutput = len(y) > 1  # type: ignore[arg-type]

    if multioutput:
        for i in range(len(X)):
            yield (
                {key: X.evaluate(key, i, i + 1)[0] for key in feature_names},
                {key: X.evaluate(key, i, i + 1)[0] for key in y},  # type: ignore[union-attr]
            )

    else:
        for i in range(len(X)):
            yield (
                {key: X.evaluate(key, i, i + 1)[0] for key in feature_names},
                X.evaluate(y[0], i, i + 1)[0],  # type: ignore[index]
            )

def classification_dataset_from_directory(
        root: str,
        batch_size: int = 32,
        num_workers: int = 0,
        shuffle: bool = True,
        pin_memory: bool = True,
        object_type: Literal[VisionData, DataLoader] = 'DataLoader',
        **kwargs
) -> t.Union[t.Tuple[t.Union[DataLoader, VisionData]], t.Union[DataLoader, VisionData]]:

    def batch_collate(batch):
        imgs, labels = zip(*batch)
        return list(imgs), list(labels)

    root_path = Path(root).absolute()
    if not (root_path.exists() and root_path.is_dir()):
        raise ValueError(f'{root_path} - path does not exist or is not a folder')

    roots_of_datasets = []
    if root_path.joinpath('train').exists():
        roots_of_datasets.append(root_path.joinpath('train'))
    if root_path.joinpath('test').exists():
        roots_of_datasets.append(root_path.joinpath('test'))
    if len(roots_of_datasets) == 0:
        roots_of_datasets.append(root_path)

    result = []
    for dataset_root in roots_of_datasets:
        dataset = SimpleClassificationDataset(root=str(dataset_root), **kwargs)
        if object_type == 'DataLoader':
            dataloader = DataLoader(dataset=dataset, batch_size=batch_size, shuffle=shuffle, num_workers=num_workers,
                                    collate_fn=batch_collate, pin_memory=pin_memory, generator=torch.Generator())
            result.append(dataloader)
        elif object_type == 'VisionData':
            dataloader = DataLoader(dataset=dataset, batch_size=batch_size, shuffle=shuffle, num_workers=num_workers,
                                    collate_fn=deepchecks_collate, pin_memory=pin_memory, generator=torch.Generator())
            result.append(VisionData(batch_loader=dataloader, label_map=dataset.reverse_classes_map,
                                     task_type='classification'))
        else:
            raise TypeError(f'Unknown value of object_type - {object_type}')
    return tuple(result) if len(result) > 1 else result[0]

def parse(uri: str) -> WandbReference | None:
        # TODO: Error if HTTP and host is not localhost?
        if (
            not uri.startswith("/")
            and not uri.startswith(PREFIX_HTTP)
            and not uri.startswith(PREFIX_HTTPS)
        ):
            return None

        ref = WandbReference()

        # This takes care of things like query and fragment
        parsed = urlparse(uri)
        if parsed.netloc:
            ref.host = parsed.netloc

        if not parsed.path.startswith("/"):
            return ref

        ref.path = parsed.path[1:]
        parts = ref.path.split("/")
        if len(parts) > 0 and parts[0] not in RESERVED_NON_ENTITIES:
            ref.path = None
            ref.entity = parts[0]
            if len(parts) > 1 and parts[1] not in RESERVED_NON_PROJECTS:
                ref.project = parts[1]
                if len(parts) > 3 and parts[2] == "runs":
                    ref.ref_type = ReferenceType.RUN
                    ref.run_id = parts[3]
                elif len(parts) > 4 and parts[2] == "artifacts" and parts[3] == "job":
                    ref.ref_type = ReferenceType.JOB
                    ref.job_name = parts[4]
                    if len(parts) > 5 and parts[5] not in RESERVED_JOB_PATHS:
                        ref.job_alias = parts[5]
                        # TODO: Right now we are not tracking selection as part of URL state in the Jobs tab.
                        #       If that changes we'll want to update this.

        return ref

def margins(self, *margins, x=None, y=None, z=None, tight=True):
        if margins and (x is not None or y is not None or z is not None):
            raise TypeError('Cannot pass both positional and keyword '
                            'arguments for x, y, and/or z.')
        elif len(margins) == 1:
            x = y = z = margins[0]
        elif len(margins) == 3:
            x, y, z = margins
        elif margins:
            raise TypeError('Must pass a single positional argument for all '
                            'margins, or one for each margin (x, y, z).')

        if x is None and y is None and z is None:
            if tight is not True:
                _api.warn_external(f'ignoring tight={tight!r} in get mode')
            return self._xmargin, self._ymargin, self._zmargin

        if x is not None:
            self.set_xmargin(x)
        if y is not None:
            self.set_ymargin(y)
        if z is not None:
            self.set_zmargin(z)

        self.autoscale_view(
            tight=tight, scalex=(x is not None), scaley=(y is not None),
            scalez=(z is not None)
        )

def prefect_json_object_decoder(result: dict[str, Any]) -> Any:
    if "__class__" in result:
        class_name = result["__class__"]
        if class_name not in _TYPE_ADAPTER_CACHE:
            try:
                cls = from_qualified_name(class_name)
            except (ImportError, AttributeError):
                return result
            _TYPE_ADAPTER_CACHE[class_name] = TypeAdapter(cls)
        return _TYPE_ADAPTER_CACHE[class_name].validate_python(result["data"])
    elif "__exc_type__" in result:
        try:
            exc_cls = from_qualified_name(result["__exc_type__"])
        except (ImportError, AttributeError):
            raise ValueError(f"Invalid exception type: {result['__exc_type__']!r}")
        if not (isinstance(exc_cls, type) and issubclass(exc_cls, BaseException)):
            raise ValueError(f"Invalid exception type: {result['__exc_type__']!r}")
        return exc_cls(result["message"])
    else:
        return result

async def async_expand_file_patterns(
    file_patterns: tuple[str, ...],
) -> AsyncGenerator[Path, None]:
    seen = set()

    for pattern in file_patterns:
        if await async_path.isfile(pattern):
            path = Path(pattern)
            if path not in seen:
                seen.add(path)
                yield path
        elif await async_path.isdir(pattern):
            async for file_path in async_get_files(pattern):
                if file_path not in seen:
                    seen.add(file_path)
                    yield file_path
        else:
            # Handle glob patterns by walking from root and filtering
            if "**" in pattern or "*" in pattern or "?" in pattern:
                # Extract root directory to walk from
                root = _get_root(pattern)

                # Get all files from root and filter by pattern
                if await async_path.isdir(root):
                    async for file_path in async_get_files(root):
                        if (
                            fnmatch.fnmatch(str(file_path), pattern)
                            and file_path not in seen
                        ):
                            seen.add(file_path)
                            yield file_path
            else:
                # Not a glob pattern but file doesn't exist - yield it anyway for error handling
                path = Path(pattern)
                if path not in seen:
                    seen.add(path)
                    yield path

def excitations_to_wires(singles, doubles, wires=None):
    if (not singles) and (not doubles):
        raise ValueError(
            f"'singles' and 'doubles' lists can not be both empty; "
            f"got singles = {singles}, doubles = {doubles}"
        )

    expected_shape = (2,)
    for single_ in singles:
        if np.array(single_).shape != expected_shape:
            raise ValueError(
                f"Expected entries of 'singles' to be of shape (2,); got {np.array(single_).shape}"
            )

    expected_shape = (4,)
    for double_ in doubles:
        if np.array(double_).shape != expected_shape:
            raise ValueError(
                f"Expected entries of 'doubles' to be of shape (4,); got {np.array(double_).shape}"
            )

    max_idx = 0
    if singles:
        max_idx = np.max(singles)
    if doubles:
        max_idx = max(np.max(doubles), max_idx)

    if wires is None:
        wires = range(max_idx + 1)
    elif len(wires) != max_idx + 1:
        raise ValueError(f"Expected number of wires is {max_idx + 1}; got {len(wires)}")

    singles_wires = []
    for r, p in singles:
        s_wires = [wires[i] for i in range(r, p + 1)]
        singles_wires.append(s_wires)

    doubles_wires = []
    for s, r, q, p in doubles:
        d1_wires = [wires[i] for i in range(s, r + 1)]
        d2_wires = [wires[i] for i in range(q, p + 1)]
        doubles_wires.append([d1_wires, d2_wires])

    return singles_wires, doubles_wires

def get_feedback_result(
    tru_record: record_schema.Record, feedback_name: str, timeout: int = 60
) -> pd.DataFrame:
    start_time = time.time()
    feedback_calls = None

    while time.time() - start_time < timeout:
        feedback_calls = next(
            (
                future_result.result()
                for feedback_definition, future_result in tru_record.feedback_and_future_results
                if feedback_definition.name == feedback_name
            ),
            None,
        )
        if feedback_calls is not None:
            break
        time.sleep(1)  # Wait for 1 second before checking again

    if feedback_calls is None:
        raise TimeoutError(
            f"Feedback for '{feedback_name}' not available within {timeout} seconds."
        )

    # Ensure feedback_calls is iterable
    if not hasattr(feedback_calls, "__iter__"):
        raise ValueError("feedback_calls is not iterable")

    feedback_result = [
        {
            **call.model_dump()["args"],
            "score": call.model_dump()["ret"],
            **call.model_dump()["meta"],
        }
        for call in feedback_calls.calls
    ]

    return pd.DataFrame(feedback_result)

def untoggle_optimizer(self, optimizer: Union[Optimizer, LightningOptimizer]) -> None:
        for opt in self.trainer.optimizers:
            if not (opt is optimizer or (isinstance(optimizer, LightningOptimizer) and opt is optimizer.optimizer)):
                for group in opt.param_groups:
                    for param in group["params"]:
                        if param in self._param_requires_grad_state:
                            param.requires_grad = self._param_requires_grad_state[param]
        # save memory
        self._param_requires_grad_state = {}

def inclusive_scan(
    data, axis=-1, output_dtype=None, binop=tvm.tirx.generic.add, identity_value=0, workspace=None
):

    if _can_use_scan_thrust(binop):
        if output_dtype is None or output_dtype == "":
            output_dtype = data.dtype
        ndim = len(data.shape)
        if axis < 0:
            axis += ndim

        if axis != ndim - 1:
            axes = swap(list(range(ndim)), axis)
            data = transpose(data, axes)
        output = scan_thrust(data, output_dtype, exclusive=False, binop=binop, workspace=workspace)
        if axis != ndim - 1:
            axes = swap(list(range(ndim)), axis)
            output = transpose(output, axes)
        return output

    ex_scan = exclusive_scan(
        data,
        axis,
        output_dtype=output_dtype,
        binop=binop,
        identity_value=identity_value,
        workspace=workspace,
    )

    if output_dtype is not None and data.dtype != output_dtype and output_dtype != "":
        data = cast(data, output_dtype)

    return binop(data, ex_scan)

def initialize_return_fields_defaults(config_path: Union[Path, str]) -> List:
    with open(config_path, "r") as f:
        config = json.load(f)

    return_fields_defaults = defaultdict(lambda: [])
    for op_type, sub_op_types in config.items():
        for sub_op_type in sub_op_types:
            if isinstance(sub_op_type, str):
                return_fields_defaults[(op_type,)].append(
                    camel_to_snake_case(sub_op_type)
                )
            elif isinstance(sub_op_type, dict):
                sub_op_type_key = list(sub_op_type.keys())[0]
                return_fields_defaults[(op_type, sub_op_type_key)] = [
                    camel_to_snake_case(field) for field in sub_op_type[sub_op_type_key]
                ]
    return return_fields_defaults

def count_nonzero(X, axis=None, sample_weight=None):
    if axis == -1:
        axis = 1
    elif axis == -2:
        axis = 0
    elif X.format != "csr":
        raise TypeError("Expected CSR sparse format, got {0}".format(X.format))

    # We rely here on the fact that np.diff(Y.indptr) for a CSR
    # will return the number of nonzero entries in each row.
    # A bincount over Y.indices will return the number of nonzeros
    # in each column. See ``csr_matrix.getnnz`` in scipy >= 0.14.
    if axis is None:
        if sample_weight is None:
            return X.nnz
        else:
            return np.dot(np.diff(X.indptr), sample_weight)
    elif axis == 1:
        out = np.diff(X.indptr)
        if sample_weight is None:
            # astype here is for consistency with axis=0 dtype
            return out.astype("intp")
        return out * sample_weight
    elif axis == 0:
        if sample_weight is None:
            return np.bincount(X.indices, minlength=X.shape[1])
        else:
            weights = np.repeat(sample_weight, np.diff(X.indptr))
            return np.bincount(X.indices, minlength=X.shape[1], weights=weights)
    else:
        raise ValueError("Unsupported axis: {0}".format(axis))

def restore_fp8_tensors(
    modules: Iterable[torch.nn.Module],
    fp8_tensors: Optional[List[Any]],
) -> None:

    if fp8_tensors is None:
        return

    for module in modules:
        for m in module.modules():
            module_tensors = fp8_tensors.pop(0)
            if isinstance(m, TransformerEngineBaseModule):
                m.reset_fp8_meta_tensors(module_tensors)
            elif isinstance(m, BasicOperation):
                m._load_fp8_metas(module_tensors)
    if len(fp8_tensors) != 0:
        raise RuntimeError(
            f"Got FP8 state for {len(fp8_tensors)} more modules than expected. "
            "There is probably a discrepancy with `save_fp8_tensors`."
        )

def multi_predict(stracks: list[STrack]):
        if len(stracks) <= 0:
            return
        multi_mean = np.asarray([st.mean.copy() for st in stracks])
        multi_covariance = np.asarray([st.covariance for st in stracks])
        for i, st in enumerate(stracks):
            if st.state != TrackState.Tracked:
                multi_mean[i][7] = 0
        multi_mean, multi_covariance = STrack.shared_kalman.multi_predict(multi_mean, multi_covariance)
        for i, (mean, cov) in enumerate(zip(multi_mean, multi_covariance)):
            stracks[i].mean = mean
            stracks[i].covariance = cov

def from_distance_maps(
    distance_maps: np.ndarray,
    inverted: bool,
    if_not_found_coords: Sequence[int] | dict[str, Any] | None = None,
    threshold: float | None = None,
) -> np.ndarray:
    if distance_maps.ndim != NUM_MULTI_CHANNEL_DIMENSIONS:
        msg = f"Expected three-dimensional input, got {distance_maps.ndim} dimensions and shape {distance_maps.shape}."
        raise ValueError(msg)
    height, width, nb_keypoints = distance_maps.shape

    drop_if_not_found, if_not_found_x, if_not_found_y = validate_if_not_found_coords(
        if_not_found_coords,
    )

    # Find the indices of max/min values for all keypoints at once
    if inverted:
        hitidx_flat = np.argmax(
            distance_maps.reshape(height * width, nb_keypoints),
            axis=0,
        )
    else:
        hitidx_flat = np.argmin(
            distance_maps.reshape(height * width, nb_keypoints),
            axis=0,
        )

    # Convert flat indices to 2D coordinates
    hitidx_y, hitidx_x = np.unravel_index(hitidx_flat, (height, width))

    # Create keypoints array
    keypoints = np.column_stack((hitidx_x, hitidx_y)).astype(float)

    if threshold is not None:
        # Check threshold condition
        if inverted:
            valid_mask = distance_maps[hitidx_y, hitidx_x, np.arange(nb_keypoints)] >= threshold
        else:
            valid_mask = distance_maps[hitidx_y, hitidx_x, np.arange(nb_keypoints)] <= threshold

        if not drop_if_not_found:
            # Replace invalid keypoints with if_not_found_coords
            keypoints[~valid_mask] = [if_not_found_x, if_not_found_y]
        else:
            # Keep only valid keypoints
            return keypoints[valid_mask]

    return keypoints

def to_rclone_flags(self) -> str:
        flags = []
        if self.transfers is not None:
            flags.append(f'--transfers {self.transfers}')
            # Automate checkers. It is recommend practice that checkers are
            # normally twice as many as transfers. However, research into
            # different examples reveal that at a very high transfer count
            # like 100, it is a bit pointless to have 200 checkers, so the
            # second part of the min provides a plateaued increase for
            # higher number of transfers.
            checkers = min(self.transfers * 2, 30 + self.transfers * 1.2)
            flags.append(f'--checkers {max(checkers, 4)}')
        if self.buffer_size is not None:
            flags.append(f'--buffer-size {self.buffer_size.upper()}')
        if self.vfs_cache_max_size is not None:
            flags.append(
                f'--vfs-cache-max-size {self.vfs_cache_max_size.upper()}')
        else:
            flags.append('--vfs-cache-max-size 10G')
        if self.vfs_cache_max_age is not None:
            flags.append(f'--vfs-cache-max-age {self.vfs_cache_max_age}')
        if self.vfs_read_ahead is not None:
            flags.append(f'--vfs-read-ahead {self.vfs_read_ahead.upper()}')
        if self.vfs_read_chunk_size is not None:
            flags.append(
                f'--vfs-read-chunk-size {self.vfs_read_chunk_size.upper()}')
        if self.vfs_read_chunk_streams is not None:
            flags.append(
                f'--vfs-read-chunk-streams {self.vfs_read_chunk_streams}')
        flags.append(f'--vfs-write-back {self.vfs_write_back or "1s"}')
        if self.read_only:
            flags.append('--read-only')
        return ' '.join(flags)

def result_type_many(*arrays_and_dtypes):
    try:
        return np.result_type(*arrays_and_dtypes)
    except ValueError:
        # we have > NPY_MAXARGS terms in our expression
        return reduce(np.result_type, arrays_and_dtypes)
    except TypeError:
        from pandas.core.dtypes.cast import find_common_type
        from pandas.core.dtypes.common import is_extension_array_dtype

        arr_and_dtypes = list(arrays_and_dtypes)
        ea_dtypes, non_ea_dtypes = [], []
        for arr_or_dtype in arr_and_dtypes:
            if is_extension_array_dtype(arr_or_dtype):
                ea_dtypes.append(arr_or_dtype)
            else:
                non_ea_dtypes.append(arr_or_dtype)

        if non_ea_dtypes:
            try:
                np_dtype = np.result_type(*non_ea_dtypes)
            except ValueError:
                np_dtype = reduce(np.result_type, arrays_and_dtypes)
            return find_common_type([*ea_dtypes, np_dtype])

        return find_common_type(ea_dtypes)

def extract_execution_flow(
        self, trace_data: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        logger.info(
            "DEBUG: LangGraphTraceProvider.extract_execution_flow called"
        )

        if "spans" not in trace_data:
            return []

        execution_flow = []
        for span in trace_data["spans"]:
            if isinstance(span, dict):
                span_name = span.get("span_name", "unknown")
                attrs = span.get("span_attributes", {})

                # Skip internal spans but be less aggressive
                if any(
                    skip in span_name.lower()
                    for skip in ["debug", "log", "trace", "monitor"]
                ):
                    continue

                # Extract detailed step information
                step = self._extract_detailed_step(span_name, attrs)
                if step:
                    execution_flow.append(step)

        logger.info(
            f"DEBUG: Extracted {len(execution_flow)} detailed execution steps"
        )
        return execution_flow

def fix_close_shift(gold_transition, pred_transition, gold_sequence, gold_index, root_labels, model, state, count_opens=False):
    if not isinstance(pred_transition, Shift):
        return None

    if not isinstance(gold_transition, CloseConstituent):
        return None

    num_closes = 0
    while isinstance(gold_sequence[gold_index + num_closes], CloseConstituent):
        num_closes += 1

    # We may allow unary transitions here
    # the opens will be lost in the repaired sequence
    num_opens = 0
    if count_opens:
        while isinstance(gold_sequence[gold_index + num_closes + num_opens], OpenConstituent):
            num_opens += 1

    if not isinstance(gold_sequence[gold_index + num_closes + num_opens], Shift):
        if count_opens:
            raise AssertionError("Should have found a Shift after a sequence of Opens or a Close with no Open.  Started counting at %d in sequence %s" % (gold_index, gold_sequence))
        return None

    if not isinstance(gold_sequence[gold_index + num_closes + num_opens + 1], CloseConstituent):
        return None
    for idx in range(num_opens):
        if not isinstance(gold_sequence[gold_index + num_closes + num_opens + idx + 1], CloseConstituent):
            return None

    # Now we know it is Close x num_closes, Shift, Close
    # Since we have erroneously predicted a Shift now, the best we can
    # do is to follow that, then add num_closes Closes
    updated_sequence = gold_sequence[:gold_index] + [pred_transition] + gold_sequence[gold_index:gold_index+num_closes] + gold_sequence[gold_index+num_closes+num_opens*2+1:]
    return updated_sequence

def cancel_block_runs_and_jobs(
    pipeline_run: PipelineRun,
    pipeline: Pipeline = None,
) -> None:
    block_runs_to_cancel = []
    running_blocks = []
    for b in pipeline_run.block_runs:
        if b.status in [
            BlockRun.BlockRunStatus.INITIAL,
            BlockRun.BlockRunStatus.QUEUED,
            BlockRun.BlockRunStatus.RUNNING,
        ]:
            block_runs_to_cancel.append(b)
        if b.status == BlockRun.BlockRunStatus.RUNNING:
            running_blocks.append(b)
    cancelled_block_run_ids = [b.id for b in block_runs_to_cancel]
    BlockRun.batch_update_status(
        cancelled_block_run_ids,
        BlockRun.BlockRunStatus.CANCELLED,
    )

    job_manager = get_job_manager()
    # Kill jobs for integration streams and pipeline run
    if pipeline and (
        pipeline.type in [PipelineType.INTEGRATION, PipelineType.STREAMING]
        or pipeline.run_pipeline_in_one_process
    ):
        job_manager.kill_pipeline_run_job(pipeline_run.id)
        if pipeline.type == PipelineType.INTEGRATION:
            for stream in pipeline.streams():
                job_manager.kill_integration_stream_job(
                    pipeline_run.id, stream.get('tap_stream_id')
                )
        if pipeline_run.executor_type == ExecutorType.K8S:
            """
            TODO: Support running and cancelling pipeline runs in ECS and GCP_CLOUD_RUN executors
            """
            ExecutorFactory.get_pipeline_executor(
                pipeline,
                executor_type=pipeline_run.executor_type,
            ).cancel(pipeline_run_id=pipeline_run.id)
    else:
        for b in running_blocks:
            job_manager.kill_block_run_job(b.id)

    GenericJob.enqueue_cancel_pipeline_run(pipeline_run.id, cancelled_block_run_ids)

def split_into_batches(data, batch_size):
    intervals = []
    interval_start = 0
    interval_size = 0
    for idx, line in enumerate(data):
        if len(line) > batch_size:
            # guess we'll just hope the model can handle a batch of this size after all
            if interval_size > 0:
                intervals.append((interval_start, idx))
            intervals.append((idx, idx+1))
            interval_start = idx+1
            interval_size = 0
        elif len(line) + interval_size > batch_size:
            # this line puts us over batch_size
            intervals.append((interval_start, idx))
            interval_start = idx
            interval_size = len(line)
        else:
            interval_size = interval_size + len(line)
    if interval_size > 0:
        # there's some leftover
        intervals.append((interval_start, len(data)))
    return intervals

def is_config_or_test(example, scan_width=5, coeff=0.05):
    keywords = ["unit tests", "test file", "configuration file"]
    lines = example["content"].splitlines()
    count_config = 0
    count_test = 0
    # first test
    for _, line in zip(range(scan_width), lines):
        for keyword in keywords:
            if keyword in line.lower():
                return {"config_or_test": True}
    # second test
    nlines = example["content"].count("\n")
    threshold = int(coeff * nlines)
    for line in lines:
        count_config += line.lower().count("config")
        count_test += line.lower().count("test")
        if count_config > threshold or count_test > threshold:
            return {"config_or_test": True}
    return {"config_or_test": False}

def add_proj(self, projs, remove_existing=False, verbose=None):
        if isinstance(projs, Projection):
            projs = [projs]

        if not isinstance(projs, list) and not all(
            isinstance(p, Projection) for p in projs
        ):
            raise ValueError("Only projs can be added. You supplied something else.")

        # mark proj as inactive, as they have not been applied
        projs = deactivate_proj(projs, copy=True)
        if remove_existing:
            # we cannot remove the proj if they are active
            if any(p["active"] for p in self.info["projs"]):
                raise ValueError(
                    "Cannot remove projectors that have already been applied"
                )
            with self.info._unlock():
                self.info["projs"] = projs
        else:
            self.info["projs"].extend(projs)
        # We don't want to add projectors that are activated again.
        with self.info._unlock():
            self.info["projs"] = _uniquify_projs(
                self.info["projs"], check_active=False, sort=False
            )
        return self

def start_agent_span(
        self,
        messages: Messages,
        agent_name: str,
        model_id: str | None = None,
        tools: list | None = None,
        custom_trace_attributes: Mapping[str, AttributeValue] | None = None,
        tools_config: dict | None = None,
        **kwargs: Any,
    ) -> Span:
        attributes: dict[str, AttributeValue] = self._get_common_attributes(operation_name="invoke_agent")
        attributes.update(
            {
                "gen_ai.agent.name": agent_name,
            }
        )

        if model_id:
            attributes["gen_ai.request.model"] = model_id

        if tools:
            attributes["gen_ai.agent.tools"] = serialize(tools)

        if self._include_tool_definitions and tools_config:
            try:
                tool_definitions = self._construct_tool_definitions(tools_config)
                attributes["gen_ai.tool.definitions"] = serialize(tool_definitions)
            except Exception:
                # A failure in telemetry should not crash the agent
                logger.warning("failed to attach tool metadata to agent span", exc_info=True)

        # Add custom trace attributes if provided
        if custom_trace_attributes:
            attributes.update(custom_trace_attributes)

        # Add additional kwargs as attributes
        attributes.update({k: v for k, v in kwargs.items() if isinstance(v, (str, int, float, bool))})

        span = self._start_span(
            f"invoke_agent {agent_name}", attributes=attributes, span_kind=trace_api.SpanKind.INTERNAL
        )
        self._add_event_messages(span, messages)

        return span

def propagate_in_video_iterator(
        self,
        inference_session: Sam2VideoInferenceSession,
        start_frame_idx: int | None = None,
        max_frame_num_to_track: int | None = None,
        reverse: bool = False,
        show_progress_bar: bool = False,
    ) -> Iterator[Sam2VideoSegmentationOutput]:
        num_frames = inference_session.num_frames

        # set start index, end index, and processing order
        if start_frame_idx is None:
            # default: start from the earliest frame with input points
            frames_with_inputs = [
                frame_idx
                for obj_output_dict in inference_session.output_dict_per_obj.values()
                for frame_idx in obj_output_dict["cond_frame_outputs"]
            ]
            if not frames_with_inputs:
                raise ValueError(
                    "Cannot determine the starting frame index; please specify it manually, or run inference on a frame with inputs first."
                )
            start_frame_idx = min(frames_with_inputs)
        if max_frame_num_to_track is None:
            # default: track all the frames in the video
            max_frame_num_to_track = num_frames
        if reverse:
            end_frame_idx = max(start_frame_idx - max_frame_num_to_track, 0)
            if start_frame_idx > 0:
                processing_order = range(start_frame_idx, end_frame_idx - 1, -1)
            else:
                processing_order = []  # skip reverse tracking if starting from frame 0
        else:
            end_frame_idx = min(start_frame_idx + max_frame_num_to_track, num_frames - 1)
            processing_order = range(start_frame_idx, end_frame_idx + 1)

        for frame_idx in tqdm(processing_order, desc="propagate in video", disable=not show_progress_bar):
            sam2_video_output = self(inference_session, frame_idx=frame_idx, reverse=reverse)
            yield sam2_video_output

def filter_jobs(
    jobs: List[Dict[str, Any]],
    workspace_match: Optional[str],
    name_match: Optional[str],
    pool_match: Optional[str],
    page: Optional[int],
    limit: Optional[int],
    user_match: Optional[str] = None,
    enable_user_match: bool = False,
    statuses: Optional[List[str]] = None,
) -> Tuple[List[Dict[str, Any]], int, Dict[str, int]]:

    # TODO(hailong): refactor the whole function including the
    # `dump_managed_job_queue()` to use DB filtering.

    def _pattern_matches(job: Dict[str, Any], key: str,
                         pattern: Optional[str]) -> bool:
        if pattern is None:
            return True
        if key not in job:
            return False
        value = job[key]
        if not value:
            return False
        return pattern in str(value)

    def _handle_page_and_limit(
        result: List[Dict[str, Any]],
        page: Optional[int],
        limit: Optional[int],
    ) -> List[Dict[str, Any]]:
        if page is None and limit is None:
            return result
        assert page is not None and limit is not None, (page, limit)
        # page starts from 1
        start = (page - 1) * limit
        end = min(start + limit, len(result))
        return result[start:end]

    status_counts: Dict[str, int] = collections.defaultdict(int)
    result = []
    checks = [
        ('workspace', workspace_match),
        ('job_name', name_match),
        ('pool', pool_match),
    ]
    if enable_user_match:
        checks.append(('user_name', user_match))

    for job in jobs:
        if not all(
                _pattern_matches(job, key, pattern) for key, pattern in checks):
            continue
        status_counts[job['status'].value] += 1
        if statuses:
            if job['status'].value not in statuses:
                continue
        result.append(job)

    total = len(result)

    return _handle_page_and_limit(result, page, limit), total, status_counts

def get_states(self, initial_state):
        if self.clusters is None:
            self.clusters = self.get_clusters_of_attributes()
        clusters = self.clusters

        # combinations within clusters
        states0 = chain.from_iterable(combinations(cluster.instances, 2)
                                      for cluster in clusters)
        if self.n_clusters == 1:
            return states0

        # combinations among clusters - closest clusters first
        centroids = [c.centroid for c in clusters]
        centroids_combs = np.array(list(combinations(centroids, 2)))
        distances = np.linalg.norm((centroids_combs[:, 0] -
                                    centroids_combs[:, 1]), axis=1)
        cluster_combs = list(combinations(range(len(clusters)), 2))
        states = ((min((c1, c2)), max((c1, c2))) for i in np.argsort(distances)
                  for c1 in clusters[cluster_combs[i][0]].instances
                  for c2 in clusters[cluster_combs[i][1]].instances)
        states = chain(states0, states)

        if initial_state is not None:
            while next(states) != initial_state:
                pass
            return chain([initial_state], states)
        return states

def example_splits(url_file, all_files):
  def generate_hash(inp):
    """Generate a sha1 hash to match the raw url to the filename extracted."""
    h = hashlib.sha1()
    h.update(inp)
    return h.hexdigest()

  all_files_map = {f.split("/")[-1]: f for f in all_files}

  urls = [line.strip().encode("utf-8") for line in tf.gfile.Open(url_file)]

  filelist = []
  for url in urls:
    url_hash = generate_hash(url)
    filename = url_hash + ".story"
    if filename not in all_files_map:
      tf.logging.info("Missing file: %s" % url)
      continue
    filelist.append(all_files_map[filename])

  tf.logging.info("Found %d examples" % len(filelist))

  return filelist

def set_adapter_stack(
    module,
    adapter_names: Union[str, Sequence[str]],
    weights: Optional[Union[float, List[float], List[dict]]] = None,
    freeze_names: Optional[Iterable[str]] = None,
) -> None:
    if module is None or adapter_names is None:
        return

    names: Union[str, List[str]]
    if isinstance(adapter_names, str):
        names = adapter_names
    else:
        names = list(adapter_names)

    if isinstance(names, list) and len(names) == 0:
        return

    has_stack = hasattr(module, "set_adapters") and callable(getattr(module, "set_adapters"))
    if has_stack:
        module.set_adapters(names, weights)
    elif hasattr(module, "set_adapter") and callable(getattr(module, "set_adapter")):
        # Fallback to single adapter activation.
        if isinstance(names, list) and len(names) > 0:
            module.set_adapter(names[0])
        elif isinstance(names, str):
            module.set_adapter(names)

    if freeze_names:
        for name in freeze_names:
            freeze_adapter_parameters(module, name)

def xml_format(a):
    if isinstance(a, str):
        return "\"%s\"" % encode_entities(a)
    if isinstance(a, bool):
        return "\"%s\"" % ("no", "yes")[int(a)]
    if isinstance(a, int):
        return "\"%s\"" % a
    if isinstance(a, float):
        return "\"%s\"" % round(a, 5)
    if isinstance(a, type(None)):
        return "\"\""
    if isinstance(a, Date):
        return "\"%s\"" % str(a)
    if isinstance(a, datetime):
        return "\"%s\"" % str(date(mktime(a.timetuple())))

def compute_padding(
    original_size: Union[int, Tuple[int, int]],
    window_size: Union[int, Tuple[int, int]],
    stride: Optional[Union[int, Tuple[int, int]]] = None,
) -> FullPadType:
    original_size = cast(Tuple[int, int], _pair(original_size))
    window_size = cast(Tuple[int, int], _pair(window_size))
    if stride is None:
        stride = window_size
    stride = cast(Tuple[int, int], _pair(stride))

    remainder_vertical = (original_size[0] - window_size[0]) % stride[0]
    remainder_horizontal = (original_size[1] - window_size[1]) % stride[1]
    # it might be best to apply padding only to the far edges (right, bottom), so
    # that fewer patches are affected by the padding.
    # For now, just use the default padding
    if remainder_vertical != 0:
        vertical_padding = stride[0] - remainder_vertical
    else:
        vertical_padding = 0

    if remainder_horizontal != 0:
        horizontal_padding = stride[1] - remainder_horizontal
    else:
        horizontal_padding = 0

    if vertical_padding % 2 == 0:
        top_padding = bottom_padding = vertical_padding // 2
    else:
        top_padding = vertical_padding // 2
        bottom_padding = ceil(vertical_padding / 2)

    if horizontal_padding % 2 == 0:
        left_padding = right_padding = horizontal_padding // 2
    else:
        left_padding = horizontal_padding // 2
        right_padding = ceil(horizontal_padding / 2)
    # the new implementation with unfolding requires symmetric padding
    padding = int(top_padding), int(bottom_padding), int(left_padding), int(right_padding)
    return padding

def load_pretrained_dict(model: torch.nn.Module,
                         state_dict: dict,
                         logger=None,
                         sub_level=None):
    revise_keys = [(r'^module\.', '')]

    if 'state_dict' in state_dict:
        state_dict = state_dict['state_dict']
    if 'model_state' in state_dict:
        state_dict = state_dict['model_state']

    for p, r in revise_keys:
        state_dict = {re.sub(p, r, k): v for k, v in state_dict.items()}

    if sub_level:
        sub_level = sub_level if sub_level.endswith('.') else (sub_level + '.')
        sub_level_len = len(sub_level)
        state_dict = {
            key[sub_level_len:]: value
            for key, value in state_dict.items() if key.startswith(sub_level)
        }

    state_dict = _auto_drop_invalid(model, state_dict, logger=logger)

    load_status = model.load_state_dict(state_dict, strict=False)
    unexpected_keys = load_status.unexpected_keys
    missing_keys = load_status.missing_keys
    err_msgs = []
    if unexpected_keys:
        err_msgs.append('unexpected key in source '
                        f'state_dict: {", ".join(unexpected_keys)}\n')
    if missing_keys:
        err_msgs.append('missing key in source '
                        f'state_dict: {", ".join(missing_keys)}\n')
    err_msgs = '\n'.join(err_msgs)

    if len(err_msgs) > 0:
        if logger:
            logger.warning(err_msgs)
        else:
            import warnings
            warnings.warn(err_msgs)

def create_compatible_mapping(self, model, compile=False):
        from kernels import Mode

        compatible_mapping = {}
        current_device = infer_device(model)
        for layer_name, kernel in self.kernel_mapping.items():
            # Infer Mode: use Mode.TRAINING if model is training, else use Mode.INFERENCE
            mode = Mode.TRAINING if model.training else Mode.INFERENCE
            if compile:
                mode = mode | Mode.TORCH_COMPILE

            if isinstance(kernel, str):
                repo_name = kernel
                if not self.use_local_kernel:
                    add_to_mapping(layer_name, current_device, repo_name, mode, compatible_mapping)
                else:
                    add_to_mapping_local(layer_name, current_device, repo_name, mode, compatible_mapping)
            elif isinstance(kernel, dict):
                for device, repo_name in kernel.items():
                    if device != current_device:
                        continue
                    if not self.use_local_kernel:
                        add_to_mapping(layer_name, device, repo_name, mode, compatible_mapping)
                    else:
                        add_to_mapping_local(layer_name, device, repo_name, mode, compatible_mapping)

        self.kernel_mapping = compatible_mapping

def predict(self, df, return_targets=False):
        data = self._batch_data(df)

        inputs = data["inputs"]
        time = data["time"]
        identifier = data["identifier"]
        outputs = data["outputs"]

        combined = self.model.predict(inputs, workers=16, use_multiprocessing=True, batch_size=self.minibatch_size)

        # Format output_csv
        if self.output_size != 1:
            raise NotImplementedError("Current version only supports 1D targets!")

        def format_outputs(prediction):
            """Returns formatted dataframes for prediction."""

            flat_prediction = pd.DataFrame(
                prediction[:, :, 0], columns=["t+{}".format(i) for i in range(self.time_steps - self.num_encoder_steps)]
            )
            cols = list(flat_prediction.columns)
            flat_prediction["forecast_time"] = time[:, self.num_encoder_steps - 1, 0]
            flat_prediction["identifier"] = identifier[:, 0, 0]

            # Arrange in order
            return flat_prediction[["forecast_time", "identifier"] + cols]

        # Extract predictions for each quantile into different entries
        process_map = {
            "p{}".format(int(q * 100)): combined[Ellipsis, i * self.output_size : (i + 1) * self.output_size]
            for i, q in enumerate(self.quantiles)
        }

        if return_targets:
            # Add targets if relevant
            process_map["targets"] = outputs

        return {k: format_outputs(process_map[k]) for k in process_map}

def aggregate_arrayrecords(
    records: list[RecordDict], weighting_metric_name: str
) -> ArrayRecord:
    # Retrieve weighting factor from MetricRecord
    weights: list[float] = []
    for record in records:
        # Get the first (and only) MetricRecord in the record
        metricrecord = next(iter(record.metric_records.values()))
        # Because replies have been checked for consistency,
        # we can safely cast the weighting factor to float
        w = cast(float, metricrecord[weighting_metric_name])
        weights.append(w)

    # Average
    total_weight = sum(weights)
    weight_factors = [w / total_weight for w in weights]

    # Perform weighted aggregation
    aggregated_np_arrays: dict[str, NDArray] = {}

    for record, weight in zip(records, weight_factors, strict=True):
        for record_item in record.array_records.values():
            # aggregate in-place
            for key, value in record_item.items():
                if key not in aggregated_np_arrays:
                    aggregated_np_arrays[key] = value.numpy() * weight
                else:
                    aggregated_np_arrays[key] += value.numpy() * weight

    return ArrayRecord(
        {k: Array(np.asarray(v)) for k, v in aggregated_np_arrays.items()}
    )

def extract_complete_objects(self, string: str) -> List[Any]:
        object_regex = r"(?<!\\)(\[[^][]*?(?<!\\)\]|\{[^{}]*\})"
        object_strings: List[str] = []
        opening: Dict[str, int] = {"{": 0, "[": 0}
        closing = {"}": "{", "]": "["}
        stack: List[str] = []
        start = 0

        for match in re.finditer(object_regex, string):
            if len(stack) == 0:
                start = match.start()
            stack.append(match.group(1))
            if match.group(1)[-1] in closing:
                opening_bracket = closing[match.group(1)[-1]]
                opening[opening_bracket] += 1
                nonzero = [v for v in opening.values() if v != 0]
                if opening[opening_bracket] == len(nonzero):
                    object_strings.append(string[start : match.end()])
                    stack = []
                    opening = {"{": 0, "[": 0}

        objects: List[Any] = []
        for obj_str in object_strings:
            try:
                objects.append(ast.literal_eval(obj_str))
            except (ValueError, SyntaxError):
                try:
                    objects.append(json.loads(obj_str))
                except (json.JSONDecodeError, ValueError):
                    pass
        return objects

def delete(self, route_name: str):
        # ensure index is not locked
        if self.index._is_locked():
            raise ValueError("Index is locked. Cannot delete route.")
        current_local_hash = self._get_hash()
        current_remote_hash = self.index._read_hash()
        if current_remote_hash.value == "":
            # if remote hash is empty, the index is to be initialized
            current_remote_hash = current_local_hash

        if route_name not in [route.name for route in self.routes]:
            err_msg = f"Route `{route_name}` not found in {self.__class__.__name__}"
            logger.warning(err_msg)
            try:
                self.index.delete(route_name=route_name)
            except Exception as e:
                logger.error(f"Failed to delete route from the index: {e}")
        else:
            self.routes = [route for route in self.routes if route.name != route_name]
            self.index.delete(route_name=route_name)

        if current_local_hash.value == current_remote_hash.value:
            self._write_hash()  # update current hash in index
        else:
            logger.warning(
                "Local and remote route layers were not aligned. Remote hash "
                f"not updated. Use `{self.__class__.__name__}.get_utterance_diff()` "
                "to see details."
            )

def get_default_accurate(resources, lang):
    default_processors = get_default_processors(resources, lang)

    tokenizer_model = default_processors['tokenize']
    if tokenizer_model.endswith('_nocharlm'):
        tokenizer_model = tokenizer_model.replace('_nocharlm', '_charlm')
    elif 'charlm' not in tokenizer_model:
        tokenizer_model = tokenizer_model + '_charlm'
    if tokenizer_model.endswith('_charlm') and tokenizer_model in resources[lang]['tokenize']:
        default_processors['tokenize'] = tokenizer_model
        print("TOKENIZE found a charlm version %s for %s default_accurate" % (tokenizer_model, lang))

    if 'lemma' in default_processors and default_processors['lemma'] != 'identity':
        lemma_model = default_processors['lemma']
        lemma_model = lemma_model.replace('_nocharlm', '_charlm')
        charlm_package = get_lemma_charlm_package(lang, lemma_model)
        if charlm_package is not None:
            if lemma_model in resources[lang]['lemma']:
                default_processors['lemma'] = lemma_model
            else:
                print("WARNING: wanted to use %s for %s default_accurate lemma, but that model does not exist" % (lemma_model, lang))

    transformer = TRANSFORMER_NICKNAMES.get(TRANSFORMERS.get(lang, None), None)
    if transformer is not None:
        for processor in ('pos', 'depparse', 'constituency', 'sentiment'):
            update_processor_add_transformer(resources, lang, default_processors, processor, transformer)
        if 'ner' in default_processors and (default_processors['ner'].endswith("_charlm") or default_processors['ner'].endswith("_nocharlm")):
            update_processor_add_transformer(resources, lang, default_processors, "ner", transformer)

    optional = get_optional_accurate(resources, lang)
    if optional:
        default_processors['optional'] = optional

    return default_processors
